INSERT INTO "claims" VALUES('THM-A001','theorems/theorems.jsonl',1,'source inspected; central proof not audited','Theorem1.1, p1','{"theorem_id": "THM-A001", "paper_id": "PAPER-A001", "locator": "Theorem1.1, p1", "kind": "published theorem", "statement": "For |b_n|<=1 and 1-separated t_r in [0,T] with |sum_{N<=n<=2N}b_n n^{it_r}|>=V, R<=T^{o(1)}(N^2/V^2+N^{18/5}/V^4+T N^{12/5}/V^4).", "verification_status": "source inspected; central proof not audited", "id": "THM-A001", "provenance_file": "theorems/analytic_track.jsonl"}','PAPER-A001','For |b_n|<=1 and 1-separated t_r in [0,T] with |sum_{N<=n<=2N}b_n n^{it_r}|>=V, R<=T^{o(1)}(N^2/V^2+N^{18/5}/V^4+T N^{12/5}/V^4).','published theorem','Theorem1.1, p1','theorems/analytic_track.jsonl');
INSERT INTO "claims" VALUES('THM-A002','theorems/theorems.jsonl',2,'statement and exponent reduction inspected; S3 input not audited','Theorem1.2 p2; section13.1 pp48–50','{"theorem_id": "THM-A002", "paper_id": "PAPER-A001", "locator": "Theorem1.2 p2; section13.1 pp48–50", "kind": "published theorem", "statement": "For fixed sigma in the critical strip, N(sigma,T)<=T^{15(1-sigma)/(3+5sigma)+o(1)}; combining Ingham yields envelope T^{30(1-sigma)/13+o(1)}.", "conventions": "Re rho>=sigma, |Im rho|<=T; asymptotic not explicit numeric bound", "verification_status": "statement and exponent reduction inspected; S3 input not audited", "id": "THM-A002", "provenance_file": "theorems/analytic_track.jsonl"}','PAPER-A001','For fixed sigma in the critical strip, N(sigma,T)<=T^{15(1-sigma)/(3+5sigma)+o(1)}; combining Ingham yields envelope T^{30(1-sigma)/13+o(1)}.','published theorem','Theorem1.2 p2; section13.1 pp48–50','theorems/analytic_track.jsonl');
INSERT INTO "claims" VALUES('THM-A003','theorems/theorems.jsonl',3,'source and certificate architecture read; original run not replicated','Theorem1 p2','{"theorem_id": "THM-A003", "paper_id": "PAPER-A002", "locator": "Theorem1 p2", "kind": "rigorous computational theorem", "statement": "RH holds for 0<Im rho<=3000175332800; lowest12363153437138 nontrivial zeros are on Re s=1/2.", "verification_status": "source and certificate architecture read; original run not replicated", "id": "THM-A003", "provenance_file": "theorems/analytic_track.jsonl"}','PAPER-A002','RH holds for 0<Im rho<=3000175332800; lowest12363153437138 nontrivial zeros are on Re s=1/2.','rigorous computational theorem','Theorem1 p2','theorems/analytic_track.jsonl');
INSERT INTO "claims" VALUES('THM-A004','theorems/theorems.jsonl',4,'original statement and local integration proof inspected; upstream whole theorem not audited','Lemma5 pp6–7 arXiv v1','{"theorem_id": "THM-A004", "paper_id": "PAPER-A006", "locator": "Lemma5 pp6–7 arXiv v1", "kind": "published theorem", "statement": "For fixed real even r in L1 supported[-1,1], Lipschitz at0, sum r_hat(i(rho-rho'')logT/(2pi))*4/(4-(rho-rho'')^2)=(TlogT/(2pi))*(r(0)+2int_0^1 alpha r(alpha)dalpha+O_r(1/sqrt(logT))).", "verification_status": "original statement and local integration proof inspected; upstream whole theorem not audited", "id": "THM-A004", "provenance_file": "theorems/analytic_track.jsonl"}','PAPER-A006','For fixed real even r in L1 supported[-1,1], Lipschitz at0, sum r_hat(i(rho-rho'')logT/(2pi))*4/(4-(rho-rho'')^2)=(TlogT/(2pi))*(r(0)+2int_0^1 alpha r(alpha)dalpha+O_r(1/sqrt(logT))).','published theorem','Lemma5 pp6–7 arXiv v1','theorems/analytic_track.jsonl');
INSERT INTO "claims" VALUES('THM-A005','theorems/theorems.jsonl',5,'proof reconstructed by one agent; independent review pending','Proposition2.1 pp6–12','{"theorem_id": "THM-A005", "paper_id": "PAPER-A003", "locator": "Proposition2.1 pp6–12", "kind": "preprint theorem", "statement": "For real even eta in L2 compactly supported(-lambda,lambda), int eta^2=1, K=Fourier(eta^2), and finite nonempty conjugation-invariant multiset Z, #simple_real(Z)>=2|Z|-sum_{z,s in Z} K(z-s)^2.", "verification_status": "proof reconstructed by one agent; independent review pending", "id": "THM-A005", "provenance_file": "theorems/analytic_track.jsonl"}','PAPER-A003','For real even eta in L2 compactly supported(-lambda,lambda), int eta^2=1, K=Fourier(eta^2), and finite nonempty conjugation-invariant multiset Z, #simple_real(Z)>=2|Z|-sum_{z,s in Z} K(z-s)^2.','preprint theorem','Proposition2.1 pp6–12','theorems/analytic_track.jsonl');
INSERT INTO "claims" VALUES('THM-A006','theorems/theorems.jsonl',6,'paper read; derivative weight removal checked; upstream analytic theorem not fully audited','Theorem1.1 p3; Lemma3.2 pp13–15','{"theorem_id": "THM-A006", "paper_id": "PAPER-A003", "locator": "Theorem1.1 p3; Lemma3.2 pp13–15", "kind": "preprint theorem", "statement": "For classical zeta, liminf N0s/N>=3/2-cot(1/sqrt2)/sqrt2=0.6725007...; further distinctness and union bounds in record.", "verification_status": "paper read; derivative weight removal checked; upstream analytic theorem not fully audited", "id": "THM-A006", "provenance_file": "theorems/analytic_track.jsonl"}','PAPER-A003','For classical zeta, liminf N0s/N>=3/2-cot(1/sqrt2)/sqrt2=0.6725007...; further distinctness and union bounds in record.','preprint theorem','Theorem1.1 p3; Lemma3.2 pp13–15','theorems/analytic_track.jsonl');
INSERT INTO "claims" VALUES('THM-A007','theorems/theorems.jsonl',7,'inspected independent algebra reconstruction; review pending','Lemma3.2 pp5–6','{"theorem_id": "THM-A007", "paper_id": "PAPER-A004", "locator": "Lemma3.2 pp5–6", "kind": "preprint linear-algebra theorem", "statement": "If P,Q Hermitian, P>=0, rank(P)<=r,n_+(Q)<=b, then r>=2trP+4trQ-4b-||P+Q||_HS^2.", "verification_status": "inspected independent algebra reconstruction; review pending", "id": "THM-A007", "provenance_file": "theorems/analytic_track.jsonl"}','PAPER-A004','If P,Q Hermitian, P>=0, rank(P)<=r,n_+(Q)<=b, then r>=2trP+4trQ-4b-||P+Q||_HS^2.','preprint linear-algebra theorem','Lemma3.2 pp5–6','theorems/analytic_track.jsonl');
INSERT INTO "claims" VALUES('THM-A008','theorems/theorems.jsonl',8,'selected source passages only; not independently established','Theorem1.1 p2; Table5 p33; section8 pp35–36','{"theorem_id": "THM-A008", "paper_id": "PAPER-A005", "locator": "Theorem1.1 p2; Table5 p33; section8 pp35–36", "kind": "preprint computational theorem claim", "statement": "liminf Nd/N>=1645064/1960733; finite search success enters Lean as extra computational axiom.", "verification_status": "selected source passages only; not independently established", "id": "THM-A008", "provenance_file": "theorems/analytic_track.jsonl"}','PAPER-A005','liminf Nd/N>=1645064/1960733; finite search success enters Lean as extra computational axiom.','preprint computational theorem claim','Theorem1.1 p2; Table5 p33; section8 pp35–36','theorems/analytic_track.jsonl');
INSERT INTO "claims" VALUES('THM-E-D201','theorems/theorems.jsonl',9,'established_primary_source_result','Lemme2,pp315–316','{"id": "THM-E-D201", "paper_id": "PAPER-E007", "locator": "Lemme2,pp315–316", "statement": "If1/2<=alpha<1andζnonvanishinginRe(s)>alpha, thenforfixedδ>0,η>0,N>=2,alpha+δ<=σ<=1, Σ_(n<=N)μ(n)n^(-s)=1/ζ(s)+O_(alpha,δ,η)(N^(-δ/3)(1+|t|)^η).", "status": "established_primary_source_result", "verification": "originalprimarytextstatementandPerronproofread; fixed-distance route reconstructed", "uniformity_warning": "No shrinkingδuniformityfromthisOstatementalone", "provenance_file": "theorems/baez_dependency_round2.jsonl"}','PAPER-E007','If1/2<=alpha<1andζnonvanishinginRe(s)>alpha, thenforfixedδ>0,η>0,N>=2,alpha+δ<=σ<=1, Σ_(n<=N)μ(n)n^(-s)=1/ζ(s)+O_(alpha,δ,η)(N^(-δ/3)(1+|t|)^η).',NULL,'Lemme2,pp315–316','theorems/baez_dependency_round2.jsonl');
INSERT INTO "claims" VALUES('THM-E-D202','theorems/theorems.jsonl',10,'derived_classical_RH_consequence','audits/baez_uniform_dependency_round2.md,LemmaF','{"id": "THM-E-D202", "paper_id": null, "locator": "audits/baez_uniform_dependency_round2.md,LemmaF", "statement": "UnderRH thereareK,V0>0suchthatforV>=V0,sup_|v|<=V,1/2+1/loglogV<=σ<=2 |1/ζ(σ+iv)|<=exp(K logV/loglogV).", "status": "derived_classical_RH_consequence", "source_provenance": ["Titchmarsh1986bookpp354–355,Eqs14.14.2–5", "Borel–Carathéodory low-heightpatch forpole-removedzeta", "fixedrightstripEuler/PhragmenLindelofbridge"], "verification": "scoped_Level3; independent proposer/skeptic/director ordinary reconstruction; exact scope in adjudication", "novelty": "not_claimed", "provenance_file": "theorems/baez_dependency_round2.jsonl", "verification_status": "adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'UnderRH thereareK,V0>0suchthatforV>=V0,sup_|v|<=V,1/2+1/loglogV<=σ<=2 |1/ζ(σ+iv)|<=exp(K logV/loglogV).',NULL,'audits/baez_uniform_dependency_round2.md,LemmaF','theorems/baez_dependency_round2.jsonl');
INSERT INTO "claims" VALUES('THM-E-D203','theorems/theorems.jsonl',11,'quantitative_reconstruction_of_required_Baez_Duarte_input','audits/baez_uniform_dependency_round2.md,(U)','{"id": "THM-E-D203", "paper_id": null, "locator": "audits/baez_uniform_dependency_round2.md,(U)", "statement": "UnderRH thereexistfixedb,c,C0,N0suchthatforallintegersN>=N0,realt,c/loglogN<=ε<=1/2, |Σ_(n<=N)μ(n)n^(-1/2−ε−it)−1/ζ(1/2+ε+it)|<=C0 N^(-ε/3) exp(b log(|t|+3)/loglog(|t|+3)). WithLemmaFconstantK, chooseA8K,b2K,c6(8K+1),enlargingN0.", "status": "quantitative_reconstruction_of_required_Baez_Duarte_input", "source_provenance": ["THM-E-D201 originalPerronroute", "THM-E-D202 uniforminversebound"], "verification": "scoped_Level3; independent proposer/skeptic/director ordinary reconstruction; exact scope in adjudication", "novelty": "not_claimed", "provenance_file": "theorems/baez_dependency_round2.jsonl", "verification_status": "adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'UnderRH thereexistfixedb,c,C0,N0suchthatforallintegersN>=N0,realt,c/loglogN<=ε<=1/2, |Σ_(n<=N)μ(n)n^(-1/2−ε−it)−1/ζ(1/2+ε+it)|<=C0 N^(-ε/3) exp(b log(|t|+3)/loglog(|t|+3)). WithLemmaFconstantK, chooseA8K,b2K,c6(8K+1),enlargingN0.',NULL,'audits/baez_uniform_dependency_round2.md,(U)','theorems/baez_dependency_round2.jsonl');
INSERT INTO "claims" VALUES('THM-E-D204','theorems/theorems.jsonl',12,'established_source_result_with_dependency_reconstruction','Expanded arXiv:math/0205003v1 Proposition3.1, pp6–8; same result as journal Theorem2, pp9–10; reconstructed uniform supplement in the director note','{"id": "THM-E-D204", "paper_id": "PAPER-E014", "locator": "Expanded arXiv:math/0205003v1 Proposition3.1, pp6–8; same result as journal Theorem2, pp9–10; reconstructed uniform supplement in the director note", "statement": "UnderRH, forsomefixedc>0, ε_N=c/loglogN gives ||χ+Σ_(n<=N)μ(n)n^(-ε_N)ρ_n||_H=O((loglogN)^(-1/3)). DerivedfromuniformpartialMöbiusinputI<=C N^(-2ε/3) andratioestimateJ<=C ε^(2/3), preservingoriginalshiftedcoefficients.", "status": "established_source_result_with_dependency_reconstruction", "verification": "Complete journal reconstruction with the previously adjudicated uniform shrinking-gap dependency. This is one quantitative result across manifestations.", "novelty": "not_claimed", "provenance_file": "theorems/baez_dependency_round2.jsonl", "source_manifestation": "VERSION-BAEZ-JOURNAL", "director_evidence": "audits/adversarial_reviews/director_baez_whole_round13.md", "status_update_evidence": "audits/adversarial_reviews/director_baez_whole_round13.md"}','PAPER-E014','UnderRH, forsomefixedc>0, ε_N=c/loglogN gives ||χ+Σ_(n<=N)μ(n)n^(-ε_N)ρ_n||_H=O((loglogN)^(-1/3)). DerivedfromuniformpartialMöbiusinputI<=C N^(-2ε/3) andratioestimateJ<=C ε^(2/3), preservingoriginalshiftedcoefficients.',NULL,'Expanded arXiv:math/0205003v1 Proposition3.1, pp6–8; same result as journal Theorem2, pp9–10; reconstructed uniform supplement in the director note','theorems/baez_dependency_round2.jsonl');
INSERT INTO "claims" VALUES('THM-SHRINKING-EXPONENT-SCALAR-GAUSSIAN','theorems/theorems.jsonl',13,'adjudicated_scoped','audits/adversarial_reviews/director_band_laws_round12.md','{"id": "THM-SHRINKING-EXPONENT-SCALAR-GAUSSIAN", "paper_id": null, "locator": "audits/adversarial_reviews/director_band_laws_round12.md", "statement": "Under RH, if b(Y)→0, a(Y)/b(Y)→r in (0,1), and a(Y)logY→infinity, the cosine prime band Y^a<p≤Y^b, centered by sum 1/p or its actual mean, converges in law and every fixed moment to N(0,(1/2)log(1/r)).", "hypotheses": "Symmetric strict derivative-square tail. Uses bounded aggregate polynomial powers at each fixed degree and the reconstructed sharp interface. Effective parameter estimates require effective cutoff moduli and the audited effective exceptional-prime estimate. This record alone is scalar.", "claim_kind": "conditional_shrinking_band_limit", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/band_laws_round12_claims.jsonl"}',NULL,'Under RH, if b(Y)→0, a(Y)/b(Y)→r in (0,1), and a(Y)logY→infinity, the cosine prime band Y^a<p≤Y^b, centered by sum 1/p or its actual mean, converges in law and every fixed moment to N(0,(1/2)log(1/r)).','conditional_shrinking_band_limit','audits/adversarial_reviews/director_band_laws_round12.md','theorems/band_laws_round12_claims.jsonl');
INSERT INTO "claims" VALUES('THM-ROOTED-CUE-FULL-BAND-LAW','theorems/theorems.jsonl',14,'adjudicated_scoped','audits/adversarial_reviews/director_band_laws_round12.md','{"id": "THM-ROOTED-CUE-FULL-BAND-LAW", "paper_id": null, "locator": "audits/adversarial_reviews/director_band_laws_round12.md", "statement": "For any fixed 0<a<b<infinity, globally derivative-square tilted rooted CUE Fourier bands converge jointly in law and every fixed moment to the one-root-reinserted rank-two-removed sine-projection linear statistics. The centered statistic is defined in L2 and has the regularized determinant in the director note.", "hypotheses": "Global Haar-matrix/root-label tilt, not per-matrix root normalization. Positive lower frequency, a fixed finite family, and centered L2 or symmetric summation. Absolute point sums diverge for the nontrivial individual cosine band. The quadratic trace correction in det2 is required. No RH or arithmetic law transfer.", "claim_kind": "intrinsic_random_matrix_limit", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/band_laws_round12_claims.jsonl"}',NULL,'For any fixed 0<a<b<infinity, globally derivative-square tilted rooted CUE Fourier bands converge jointly in law and every fixed moment to the one-root-reinserted rank-two-removed sine-projection linear statistics. The centered statistic is defined in L2 and has the regularized determinant in the director note.','intrinsic_random_matrix_limit','audits/adversarial_reviews/director_band_laws_round12.md','theorems/band_laws_round12_claims.jsonl');
INSERT INTO "claims" VALUES('THM-HLZ-FINITE-BAND-MOMENT-WINDOW','theorems/theorems.jsonl',15,'adjudicated_scoped','audits/adversarial_reviews/director_band_laws_round12.md','{"id": "THM-HLZ-FINITE-BAND-MOMENT-WINDOW", "paper_id": null, "locator": "audits/adversarial_reviews/director_band_laws_round12.md", "statement": "For every fixed integer r≥0 with rb<1/2, the raw rth moment of the RH derivative-weighted cosine band converges to r! times [z^r] exp(H z+H z²/4)[(1−d z)^4+q z(1−d z)], where H=log(b/a), d=b−a and q=2(b³−a³)/3.", "hypotheses": "One fixed 0<a<b and the exact symmetric strict tail. Each degree r uses aggregate arms through Y^(rb) and fixed declared exponent below 1/2. Only the source-admissible finite coefficient window is evaluated; growing r or all orders at fixed b are not justified.", "claim_kind": "conditional_finite_moment_formula", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/band_laws_round12_claims.jsonl"}',NULL,'For every fixed integer r≥0 with rb<1/2, the raw rth moment of the RH derivative-weighted cosine band converges to r! times [z^r] exp(H z+H z²/4)[(1−d z)^4+q z(1−d z)], where H=log(b/a), d=b−a and q=2(b³−a³)/3.','conditional_finite_moment_formula','audits/adversarial_reviews/director_band_laws_round12.md','theorems/band_laws_round12_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-HLZ-ALL-ORDER-EXTRAPOLATION-BARRIER','theorems/theorems.jsonl',16,'adjudicated_scoped','audits/adversarial_reviews/director_band_laws_round12.md','{"id": "OBS-HLZ-ALL-ORDER-EXTRAPOLATION-BARRIER", "paper_id": null, "locator": "audits/adversarial_reviews/director_band_laws_round12.md", "statement": "For every fixed 0<a<b, the formal all-order coefficient sequence of exp(H z+H z²/4)[(1−d z)^4+q z(1−d z)] cannot be the moments of a positive probability. Its entire formal MGF vanishes at 1/d; Gaussian-polynomial even-moment domination makes this a rigorous contradiction. A degree-70 negative Gram witness at [1/20,1/10] is independently interval-verified.", "hypotheses": "Pure unconditional statement about the formal sequence, not about source validity or actual higher arithmetic moments. The witness uses formal orders through 140, while that arithmetic band supplies only orders 0–4. All genuine source-window Hankel tests remain positive.", "claim_kind": "formal_extrapolation_positivity_obstruction", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/band_laws_round12_claims.jsonl"}',NULL,'For every fixed 0<a<b, the formal all-order coefficient sequence of exp(H z+H z²/4)[(1−d z)^4+q z(1−d z)] cannot be the moments of a positive probability. Its entire formal MGF vanishes at 1/d; Gaussian-polynomial even-moment domination makes this a rigorous contradiction. A degree-70 negative Gram witness at [1/20,1/10] is independently interval-verified.','formal_extrapolation_positivity_obstruction','audits/adversarial_reviews/director_band_laws_round12.md','theorems/band_laws_round12_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-SUBPOWER-SUBSET-TWO-SCALE-FOURTH','theorems/theorems.jsonl',17,'adjudicated_scoped','audits/adversarial_reviews/director_joint_process_round12.md','{"id": "LEM-SUBPOWER-SUBSET-TWO-SCALE-FOURTH", "paper_id": null, "locator": "audits/adversarial_reviews/director_joint_process_round12.md", "statement": "Under RH, for every prime subset I of (Y^(r0 b),Y^b], h=sum_I 1/p, one has E_Y|sum_I(cos(gamma logp)/sqrt p−1/p)|^4≤C_M min(h²+(logY)^−M,(logY)²h²), hence ≤C h^(3/2) for M≥6.", "hypotheses": "Fixed 0<r0<1, b→0 and b logY→infinity, same symmetric strict derivative-square tail, all subsets uniformly at sufficiently large Y. The exact local-mass bound uses analytic disks for zeta D_I² and the classical continuous fourth moment. A full-range Ch² bound is not asserted.", "claim_kind": "conditional_uniform_subset_lemma", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/band_laws_round12_claims.jsonl"}',NULL,'Under RH, for every prime subset I of (Y^(r0 b),Y^b], h=sum_I 1/p, one has E_Y|sum_I(cos(gamma logp)/sqrt p−1/p)|^4≤C_M min(h²+(logY)^−M,(logY)²h²), hence ≤C h^(3/2) for M≥6.','conditional_uniform_subset_lemma','audits/adversarial_reviews/director_joint_process_round12.md','theorems/band_laws_round12_claims.jsonl');
INSERT INTO "claims" VALUES('THM-SHRINKING-BAND-BROWNIAN-PROCESS','theorems/theorems.jsonl',18,'adjudicated_scoped','audits/adversarial_reviews/director_joint_process_round12.md','{"id": "THM-SHRINKING-BAND-BROWNIAN-PROCESS", "paper_id": null, "locator": "audits/adversarial_reviews/director_joint_process_round12.md", "statement": "Under RH, X_Y(r)=sum_(Y^(r0 b)<p≤Y^(r b))[cos(gamma logp)/sqrt p−1/p] converges in D([r0,1]), J1, to B_((1/2)log(r/r0)).", "hypotheses": "Fixed 0<r0<1, b(Y)→0, b(Y)logY→infinity and the symmetric strict derivative-square tail. Uses the two-scale fourth lemma, exact reciprocal-clock interpolation, vanishing jumps, and fixed-dimensional Gaussian projections. In-principle effective onset needs computable r0, effective cutoff moduli and the audited effective aggregate input; no numerical onset.", "claim_kind": "conditional_functional_limit", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/band_laws_round12_claims.jsonl"}',NULL,'Under RH, X_Y(r)=sum_(Y^(r0 b)<p≤Y^(r b))[cos(gamma logp)/sqrt p−1/p] converges in D([r0,1]), J1, to B_((1/2)log(r/r0)).','conditional_functional_limit','audits/adversarial_reviews/director_joint_process_round12.md','theorems/band_laws_round12_claims.jsonl');
INSERT INTO "claims" VALUES('THM-POLYNOMIAL-BAND-JOINT-THIRD-TENSOR','theorems/theorems.jsonl',19,'adjudicated_scoped','audits/adversarial_reviews/director_joint_process_round12.md','{"id": "THM-POLYNOMIAL-BAND-JOINT-THIRD-TENSOR", "paper_id": null, "locator": "audits/adversarial_reviews/director_joint_process_round12.md", "statement": "Under RH, for bounded real Riemann-integrable cosine/sine weights supported in [a,b] with 0<a<b<1/6, the centered third tensor matches globally derivative-square rooted CUE. The CSS entry is 12 integral f(x)(x²−2)dx integral g(y)y dy integral h(z)z dz. Odd-sine entries vanish. Same-band CSS is (Delta3−6Delta1)Delta2².", "hypotheses": "Signed primary HLZ extraction, aggregate length Y^(3b), repeated-prime cancellation, exact strict tail, and one deterministic root on the CUE side. Fourth moments are uniformly bounded. This adds the mixed tensor to the prior pure cosine cubic, not a full arithmetic law. At [1/20,1/10] CSS=−21537/1280000000.", "claim_kind": "conditional_cross_framework_joint_cumulant_match", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/band_laws_round12_claims.jsonl"}',NULL,'Under RH, for bounded real Riemann-integrable cosine/sine weights supported in [a,b] with 0<a<b<1/6, the centered third tensor matches globally derivative-square rooted CUE. The CSS entry is 12 integral f(x)(x²−2)dx integral g(y)y dy integral h(z)z dz. Odd-sine entries vanish. Same-band CSS is (Delta3−6Delta1)Delta2².','conditional_cross_framework_joint_cumulant_match','audits/adversarial_reviews/director_joint_process_round12.md','theorems/band_laws_round12_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-POLYNOMIAL-BAND-UNCORRELATED-DEPENDENCE','theorems/theorems.jsonl',20,'adjudicated_scoped','audits/adversarial_reviews/director_joint_process_round12.md','{"id": "OBS-POLYNOMIAL-BAND-UNCORRELATED-DEPENDENCE", "paper_id": null, "locator": "audits/adversarial_reviews/director_joint_process_round12.md", "statement": "For nonnegative bounded Riemann-integrable cosine and sine weights with positive integrals, supported in a common [a,b]⊂(0,1/6), any arithmetic weak subsequential vector limit has dependent cosine/sine coordinates despite exact zero covariance. The supports may be disjoint.", "hypotheses": "Assumes RH and the same strict tail. Uniform fourth moments transfer the nonzero centered CSS entry; independence would force it to vanish. Pointwise nonzero weights confined to null sets are excluded. Existence or uniqueness of a full vector limit and Gaussianity of the sine marginal are not asserted.", "claim_kind": "conditional_dependence_obstruction", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/band_laws_round12_claims.jsonl"}',NULL,'For nonnegative bounded Riemann-integrable cosine and sine weights with positive integrals, supported in a common [a,b]⊂(0,1/6), any arithmetic weak subsequential vector limit has dependent cosine/sine coordinates despite exact zero covariance. The supports may be disjoint.','conditional_dependence_obstruction','audits/adversarial_reviews/director_joint_process_round12.md','theorems/band_laws_round12_claims.jsonl');
INSERT INTO "claims" VALUES('THM-LB301','theorems/theorems.jsonl',21,'independent_SA_reconstruction; parent_reported_core_review_passed','["proposals/independent_campaigns/bessel_finite_offline_countermodel_round3.md section2", "PAPER-BK001 section3", "DLMF10.25.1–3,10.32.9"]','{"id": "THM-LB301", "kind": "classical_Bessel_spectral_reconstruction", "statement": "Forc>0, K_nu(c) has only nonzero purely imaginary order zeros. They correspond viaE=-nu² to simple Dirichlet eigenvalues of -d²/dx²+c²e^(2x) on(0,infinity), and are simple as entire-function zeros.", "hypotheses": "Fixedpositivec, complexorderparameter; compact-resolventDirichletSchrodinger realization.", "evidence": ["proposals/independent_campaigns/bessel_finite_offline_countermodel_round3.md section2", "PAPER-BK001 section3", "DLMF10.25.1–3,10.32.9"], "status": "independent_SA_reconstruction; parent_reported_core_review_passed", "novelty_claim": false, "paper_id": null, "locator": ["proposals/independent_campaigns/bessel_finite_offline_countermodel_round3.md section2", "PAPER-BK001 section3", "DLMF10.25.1–3,10.32.9"], "provenance_file": "theorems/bessel_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'Forc>0, K_nu(c) has only nonzero purely imaginary order zeros. They correspond viaE=-nu² to simple Dirichlet eigenvalues of -d²/dx²+c²e^(2x) on(0,infinity), and are simple as entire-function zeros.','classical_Bessel_spectral_reconstruction','["proposals/independent_campaigns/bessel_finite_offline_countermodel_round3.md section2", "PAPER-BK001 section3", "DLMF10.25.1–3,10.32.9"]','theorems/bessel_round3.jsonl');
