INSERT INTO "claims" VALUES('THM-LB305','theorems/theorems.jsonl',25,'independent_asymptotic_reconstruction; parent_requested_witness_verified','["proposals/independent_campaigns/bessel_finite_offline_countermodel_round3.md section6", "DLMF10.32.10and5.11", "experiments/results/bessel_round3_numeric.json(numericalillustrationonly)"]','{"id": "THM-LB305", "kind": "explicit_arithmetic_axiom_failure", "statement": "UncompletingF_TwiththestandardRiemannfactor(.5s(s-1)pi^(-s/2)Gamma(s/2))givesL_model(s)~C_Ts^(7/4),C_T>0,asrealstoinfinity. HenceL_modelcannotbeanordinaryDirichletseriesabsolutelyconvergentinarighthalfplane.", "hypotheses": "FixedT>=32; exactstandardcompletion; noassertionaboutallpossibleothergammafactors.", "evidence": ["proposals/independent_campaigns/bessel_finite_offline_countermodel_round3.md section6", "DLMF10.32.10and5.11", "experiments/results/bessel_round3_numeric.json(numericalillustrationonly)"], "status": "independent_asymptotic_reconstruction; parent_requested_witness_verified", "novelty_claim": false, "paper_id": null, "locator": ["proposals/independent_campaigns/bessel_finite_offline_countermodel_round3.md section6", "DLMF10.32.10and5.11", "experiments/results/bessel_round3_numeric.json(numericalillustrationonly)"], "provenance_file": "theorems/bessel_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'UncompletingF_TwiththestandardRiemannfactor(.5s(s-1)pi^(-s/2)Gamma(s/2))givesL_model(s)~C_Ts^(7/4),C_T>0,asrealstoinfinity. HenceL_modelcannotbeanordinaryDirichletseriesabsolutelyconvergentinarighthalfplane.','explicit_arithmetic_axiom_failure','["proposals/independent_campaigns/bessel_finite_offline_countermodel_round3.md section6", "DLMF10.32.10and5.11", "experiments/results/bessel_round3_numeric.json(numericalillustrationonly)"]','theorems/bessel_round3.jsonl');
INSERT INTO "claims" VALUES('THM-LB306','theorems/theorems.jsonl',26,'adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay','audits/positive_kernel_uniform_smoothing_round3.md','{"id": "THM-LB306", "title": "Two uniform smoothing factors preserve the RVM linear term and supply vertical decay", "kind": "generic_class_model_theorem_or_lemma", "hypotheses": "a=1/4,T>=32,delta=1/100,c=2pi exp(4delta),F proportional K_((s-1/2)/2)(c) Q_T(s-1/2) [sinh(delta(s-1/2))/(delta(s-1/2))]^2, normalized at0,1.", "statement": "Positive smooth even kernel; under the certified strict concavity of Q(D)exp[-c cosh2u], uniform convolutions preserve strict second log concavity. Positive-ordinate count is X/(2pi)log(X/(2pi))-X/(2pi)+O(1), exactly4 off-line zeros; equal uniform widths produce double line zeros. Z is O(|t|^-1/4) on fixed right strips and Z(sigma)~C sigma^-1/4, C>0, so no ordinary Dirichlet series on any nonempty half-plane.", "completion_normalization": "Z(s)=pi^(s/2) F(s)/[s(s-1)Gamma(s/2)] with F(0)=F(1)=1; NO factor1/2, so residue at1 is1 and Z(0)=-1/2.", "proof_reference": "audits/positive_kernel_uniform_smoothing_round3.md", "provenance": ["Pólya 1926 equation7,p306 and all-zero/count result, p. 315", "DLMF 10.25.2,10.27.4,5.11.1–2", "audits/adversarial_reviews/positive_kernel_bessel_skeptic_round3.md"], "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "independent_review": "audits/adversarial_reviews/beta_smoothing_third_round3.md", "base_concavity_review": "audits/adversarial_reviews/bessel_third_round3.md", "classical_zeta_RH_result": false, "novelty_status": "unassessed; classical component results explicitly credited", "date": "2026-11-17", "paper_id": null, "locator": "audits/positive_kernel_uniform_smoothing_round3.md", "provenance_file": "theorems/beta_smoothing_skeptic_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'Positive smooth even kernel; under the certified strict concavity of Q(D)exp[-c cosh2u], uniform convolutions preserve strict second log concavity. Positive-ordinate count is X/(2pi)log(X/(2pi))-X/(2pi)+O(1), exactly4 off-line zeros; equal uniform widths produce double line zeros. Z is O(|t|^-1/4) on fixed right strips and Z(sigma)~C sigma^-1/4, C>0, so no ordinary Dirichlet series on any nonempty half-plane.','generic_class_model_theorem_or_lemma','audits/positive_kernel_uniform_smoothing_round3.md','theorems/beta_smoothing_skeptic_round3.jsonl');
INSERT INTO "claims" VALUES('THM-LB307','theorems/theorems.jsonl',27,'adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay','audits/positive_kernel_beta_smoothing_round3.md#3-strict-log-concavity-after-beta-convolution-with-all-endpoint-terms-checked','{"id": "THM-LB307", "title": "Strict second log concavity survives compact beta convolution", "kind": "generic_class_model_theorem_or_lemma", "hypotheses": "k=e^-V positive C2 onR,Vpp>0; beta density b_delta proportional(delta²-v²)^(3/4) on(-delta,delta),delta>0.", "statement": "h=k*b_delta is positive, C2 and (logh)pp<=-E[Vpp Wpp/(Vpp+Wpp)]<0, W=-logb_delta. For the endpoint exponent3/4 the self-contained one-dimensional BL proof has p~d^(3/4),F~d^(7/4),u=F/p=O(d), so all boundary terms vanish. Ifk isC∞ so ish.", "completion_normalization": "Z(s)=pi^(s/2) F(s)/[s(s-1)Gamma(s/2)] with F(0)=F(1)=1; NO factor1/2, so residue at1 is1 and Z(0)=-1/2.", "proof_reference": "audits/positive_kernel_beta_smoothing_round3.md#3-strict-log-concavity-after-beta-convolution-with-all-endpoint-terms-checked", "provenance": ["Direct integration-by-parts and Cauchy proof in the audit; classical Brascamp–Lieb mechanism, no novelty claim"], "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "independent_review": "audits/adversarial_reviews/beta_smoothing_third_round3.md", "base_concavity_review": "audits/adversarial_reviews/bessel_third_round3.md", "classical_zeta_RH_result": false, "novelty_status": "unassessed; classical component results explicitly credited", "date": "2026-11-17", "paper_id": null, "locator": "audits/positive_kernel_beta_smoothing_round3.md#3-strict-log-concavity-after-beta-convolution-with-all-endpoint-terms-checked", "provenance_file": "theorems/beta_smoothing_skeptic_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'h=k*b_delta is positive, C2 and (logh)pp<=-E[Vpp Wpp/(Vpp+Wpp)]<0, W=-logb_delta. For the endpoint exponent3/4 the self-contained one-dimensional BL proof has p~d^(3/4),F~d^(7/4),u=F/p=O(d), so all boundary terms vanish. Ifk isC∞ so ish.','generic_class_model_theorem_or_lemma','audits/positive_kernel_beta_smoothing_round3.md#3-strict-log-concavity-after-beta-convolution-with-all-endpoint-terms-checked','theorems/beta_smoothing_skeptic_round3.jsonl');
INSERT INTO "claims" VALUES('THM-LB308','theorems/theorems.jsonl',28,'adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay','audits/positive_kernel_beta_smoothing_round3.md','{"id": "THM-LB308", "title": "Beta MGF supplies exactly the fractional smoothing power7/4", "kind": "generic_class_model_theorem_or_lemma", "hypotheses": "delta>0,nu=5/4,b_delta normalized even compact density proportional(1-v²/delta²)^(3/4).", "statement": "M_delta(w)=Gamma(9/4) sum_k(delta²w²/4)^k/[k!Gamma(k+9/4)] =Gamma(9/4)(2/(delta w))^(5/4)I_(5/4)(delta w), with the entire series fixing branches. Its zeros are simple±i j_(5/4,k)/delta, positive count delta X/pi+O(1), and M_delta(q+it)=O(|t|^-7/4) for q in a fixed bounded interval. As w→+infty, M=2^(3/4)Gamma(9/4)e^(delta w)w^-7/4/(sqrtpi delta^7/4) [1-21/(32delta w)+O(w^-2)].", "completion_normalization": "Z(s)=pi^(s/2) F(s)/[s(s-1)Gamma(s/2)] with F(0)=F(1)=1; NO factor1/2, so residue at1 is1 and Z(0)=-1/2.", "proof_reference": "audits/positive_kernel_beta_smoothing_round3.md", "provenance": ["DLMF 10.32.2,Reν>−1/2", "DLMF 10.21.15,ν>=0", "DLMF 10.21.19,fixedν>=0", "Independent inverse-square energy, Fourier-endpoint and Laplace-endpoint proofs in the audit"], "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "independent_review": "audits/adversarial_reviews/beta_smoothing_third_round3.md", "base_concavity_review": "audits/adversarial_reviews/bessel_third_round3.md", "classical_zeta_RH_result": false, "novelty_status": "unassessed; classical component results explicitly credited", "date": "2026-11-17", "paper_id": null, "locator": "audits/positive_kernel_beta_smoothing_round3.md", "provenance_file": "theorems/beta_smoothing_skeptic_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'M_delta(w)=Gamma(9/4) sum_k(delta²w²/4)^k/[k!Gamma(k+9/4)] =Gamma(9/4)(2/(delta w))^(5/4)I_(5/4)(delta w), with the entire series fixing branches. Its zeros are simple±i j_(5/4,k)/delta, positive count delta X/pi+O(1), and M_delta(q+it)=O(|t|^-7/4) for q in a fixed bounded interval. As w→+infty, M=2^(3/4)Gamma(9/4)e^(delta w)w^-7/4/(sqrtpi delta^7/4) [1-21/(32delta w)+O(w^-2)].','generic_class_model_theorem_or_lemma','audits/positive_kernel_beta_smoothing_round3.md','theorems/beta_smoothing_skeptic_round3.jsonl');
INSERT INTO "claims" VALUES('THM-LB309','theorems/theorems.jsonl',29,'adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay','audits/positive_kernel_beta_smoothing_round3.md','{"id": "THM-LB309", "title": "Explicit-height beta-tuned finite Li countermodels", "kind": "generic_class_model_theorem_or_lemma", "hypotheses": "For every integerN>=1, B=8N²+50,T=10NB,a=1/4,c=2pi exp(2delta).", "statement": "There existsdelta in(0,1/100) such that A=[K_(1/4)(c)Q_T(1/2)M_delta(1/2)]^-1 and C=A Gamma(9/4)/(pi^1/4 delta^7/4)=1. The normalized F=A K_((s-1/2)/2)(c)Q_T(s-1/2)M_delta(s-1/2) has positive smooth even strictly log-concave kernel, order1/infinite type, exactly4 off-line zeros and RVM smooth positive count+O(1). For1<=n<=N,lambda_n(F)>1/(12B²). Cross-factor line coincidences are allowed. The exact IVT endpoint estimateC(T,.01)<100000·3^9/T^4<1 forT>=256 ensures tuning at the same T >= 580.", "completion_normalization": "Z(s)=pi^(s/2) F(s)/[s(s-1)Gamma(s/2)] with F(0)=F(1)=1; NO factor1/2, so residue at1 is1 and Z(0)=-1/2.", "proof_reference": "audits/positive_kernel_beta_smoothing_round3.md", "provenance": ["THM-LB307", "THM-LB308", "Certified base Bessel/quartet positivity and concavity", "Half-line oscillator and sine-subspace minmax bounds, independently reconstructed", "Conjugate-quartet inverse-power/binomial bound"], "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "independent_review": "audits/adversarial_reviews/beta_smoothing_third_round3.md", "base_concavity_review": "audits/adversarial_reviews/bessel_third_round3.md", "classical_zeta_RH_result": false, "novelty_status": "unassessed; classical component results explicitly credited", "date": "2026-11-17", "paper_id": null, "locator": "audits/positive_kernel_beta_smoothing_round3.md", "provenance_file": "theorems/beta_smoothing_skeptic_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'There existsdelta in(0,1/100) such that A=[K_(1/4)(c)Q_T(1/2)M_delta(1/2)]^-1 and C=A Gamma(9/4)/(pi^1/4 delta^7/4)=1. The normalized F=A K_((s-1/2)/2)(c)Q_T(s-1/2)M_delta(s-1/2) has positive smooth even strictly log-concave kernel, order1/infinite type, exactly4 off-line zeros and RVM smooth positive count+O(1). For1<=n<=N,lambda_n(F)>1/(12B²). Cross-factor line coincidences are allowed. The exact IVT endpoint estimateC(T,.01)<100000·3^9/T^4<1 forT>=256 ensures tuning at the same T >= 580.','generic_class_model_theorem_or_lemma','audits/positive_kernel_beta_smoothing_round3.md','theorems/beta_smoothing_skeptic_round3.jsonl');
INSERT INTO "claims" VALUES('THM-LB310','theorems/theorems.jsonl',30,'adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay','audits/positive_kernel_beta_smoothing_round3.md','{"id": "THM-LB310", "title": "Classical completion and right limit one still do not give a Dirichlet series", "kind": "generic_class_model_theorem_or_lemma", "hypotheses": "F is a tuned beta countermodel in THM-LB309, or its generic-simple refinement; c,delta,T fixed as real sigma→infty.", "statement": "Z has only a simple pole at 1, residue 1; Z(0) = -1/2; exactly simple negative-even trivial zeros; pi^-s/2Gamma(s/2)Z(s)=F/[s(s-1)] is invariant s→1-s. Uniformly on fixed real strips, Z(sigma+it)=O(|t|^max(0,1/2-sigma)). Along real infinity Z(sigma)=1-b/sigma+O(sigma^-2), b=c²/2+21/(32delta)-3/16>0. Hence Z has no ordinary Dirichlet series on any nonempty half-plane, since absolute convergence would give a1=1 and Z(sigma)-1=O(2^-sigma).", "completion_normalization": "Z(s)=pi^(s/2) F(s)/[s(s-1)Gamma(s/2)] with F(0)=F(1)=1; NO factor1/2, so residue at1 is1 and Z(0)=-1/2.", "proof_reference": "audits/positive_kernel_beta_smoothing_round3.md", "provenance": ["THM-LB308", "THM-LB309", "Direct Gamma-expectation expansion with explicit first/second inverse moments", "DLMF 5.11 gamma ratio expansion", "Elementary absolute-convergence uniqueness of a Dirichlet leading term"], "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "independent_review": "audits/adversarial_reviews/beta_smoothing_third_round3.md", "base_concavity_review": "audits/adversarial_reviews/bessel_third_round3.md", "classical_zeta_RH_result": false, "novelty_status": "unassessed; classical component results explicitly credited", "date": "2026-11-17", "paper_id": null, "locator": "audits/positive_kernel_beta_smoothing_round3.md", "provenance_file": "theorems/beta_smoothing_skeptic_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'Z has only a simple pole at 1, residue 1; Z(0) = -1/2; exactly simple negative-even trivial zeros; pi^-s/2Gamma(s/2)Z(s)=F/[s(s-1)] is invariant s→1-s. Uniformly on fixed real strips, Z(sigma+it)=O(|t|^max(0,1/2-sigma)). Along real infinity Z(sigma)=1-b/sigma+O(sigma^-2), b=c²/2+21/(32delta)-3/16>0. Hence Z has no ordinary Dirichlet series on any nonempty half-plane, since absolute convergence would give a1=1 and Z(sigma)-1=O(2^-sigma).','generic_class_model_theorem_or_lemma','audits/positive_kernel_beta_smoothing_round3.md','theorems/beta_smoothing_skeptic_round3.jsonl');
INSERT INTO "claims" VALUES('THM-LB311','theorems/theorems.jsonl',31,'adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay','audits/positive_kernel_beta_smoothing_round3.md#optional-existence-refinement-every-zero-can-be-made-simple','{"id": "THM-LB311", "title": "A generic tuned beta model has every zero simple", "kind": "generic_class_model_theorem_or_lemma", "hypotheses": "H(delta)=Gamma(9/4)/[pi^1/4 delta^7/4 K_(1/4)(2pi exp2delta)M_delta(1/2)], T(delta)^2=sqrt(H(delta)+1/16)-5/16,delta>0 sufficiently small.", "statement": "ThisT tunes C = 1 exactly and tends to infinity asdelta→0. Each collision equation delta gamma_j(2pi exp2delta)=j_(5/4,m) is a nonidenticallyzero realanalytic equation extending through delta = 0, so all bad parameter values form a countable set. Arbitrarily smalldelta outside it gives all simple zeros while retaining every property in THM-LB310 and any prescribed finite positive Li prefix. This is existential, not a certificate for any named rational or algebraic delta; arbitrary fixed-T tuning may retain multiple line zeros.", "completion_normalization": "Z(s)=pi^(s/2) F(s)/[s(s-1)Gamma(s/2)] with F(0)=F(1)=1; NO factor1/2, so residue at1 is1 and Z(0)=-1/2.", "proof_reference": "audits/positive_kernel_beta_smoothing_round3.md#optional-existence-refinement-every-zero-can-be-made-simple", "provenance": ["THM-LB309", "THM-LB310", "Exact Q_T(1/2)=(T²+5/16)²-1/16", "Simple Bessel eigenvalue analytic dependence and implicit-function theorem", "Countable union of isolated zeros of nontrivial realanalytic functions"], "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "independent_review": "audits/adversarial_reviews/beta_smoothing_third_round3.md", "base_concavity_review": "audits/adversarial_reviews/bessel_third_round3.md", "classical_zeta_RH_result": false, "novelty_status": "unassessed; classical component results explicitly credited", "date": "2026-11-17", "paper_id": null, "locator": "audits/positive_kernel_beta_smoothing_round3.md#optional-existence-refinement-every-zero-can-be-made-simple", "provenance_file": "theorems/beta_smoothing_skeptic_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'ThisT tunes C = 1 exactly and tends to infinity asdelta→0. Each collision equation delta gamma_j(2pi exp2delta)=j_(5/4,m) is a nonidenticallyzero realanalytic equation extending through delta = 0, so all bad parameter values form a countable set. Arbitrarily smalldelta outside it gives all simple zeros while retaining every property in THM-LB310 and any prescribed finite positive Li prefix. This is existential, not a certificate for any named rational or algebraic delta; arbitrary fixed-T tuning may retain multiple line zeros.','generic_class_model_theorem_or_lemma','audits/positive_kernel_beta_smoothing_round3.md#optional-existence-refinement-every-zero-can-be-made-simple','theorems/beta_smoothing_skeptic_round3.jsonl');
INSERT INTO "claims" VALUES('THM-LB312','theorems/theorems.jsonl',32,'adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay','audits/adversarial_reviews/first_negative_li_asymptotic_skeptic_round3.md','{"id": "THM-LB312", "title": "First negative Li index for the tuned beta countermodel", "kind": "generic_class_model_asymptotic", "hypotheses": "For every real T sufficiently large, choose any delta_T in (0,1/100) satisfying the beta tuning C(T,delta_T)=1. Use the normalized F_T with the quartet a=1/4 and all other factors as in THM-LB309. Let n_-(T) be the least integer n>=1 with lambda_n(F_T)<0.", "statement": "The minimum exists, uniformly over all choices of tuned root, and n_-(T)=(T²/a)[2 log T+2 log log T-log a+o(1)] for a=1/4. Thus n_-=8T²logT+8T²loglogT+8(log2)T²+o(T²). The same asymptotic applies along the generic all simple subfamily. No explicit finite-T error or actual negative coefficient index is asserted.", "completion_normalization": "Z(s)=pi^(s/2)F(s)/[s(s-1)Gamma(s/2)], F(0)=F(1)=1; NO factor1/2. Li coefficients use F and are invariant under its constant normalization.", "proof_reference": "audits/adversarial_reviews/first_negative_li_asymptotic_skeptic_round3.md", "provenance": ["Exact quartet formula 4[1-cosh(n eta_T)cos(n theta_T)], eta_T~a/T², theta_T~1/T", "Uniform Bessel lambda_n=.5 n log n+O(n), derived from its classical uniform zero count by Stieltjes integration", "Exact beta bound 0<=lambda_n(M_delta)<=n²delta²/9", "THM-LB309 tuning rate delta_T~D T^-16/7", "Corpus envelope refinement independently rederived by skeptic"], "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "independent_review_status": "Corpus independent challenge accepted by skeptic; durable third-review addendum expected", "classical_zeta_RH_result": false, "novelty_status": "Unassessed. Classical exponential masking mechanism and existing heuristic T²-scale literature explicitly acknowledged; primary priority source reading incomplete.", "date": "2026-11-17", "inverse_scale_corollary": "For any fixed epsilon in(0,1/2), T=(1/2+epsilon)sqrt(N/logN) hides the first negative index beyondN for largeN, while T=(1/2-epsilon)sqrt(N/logN) yields a negative index belowN. Uniform over tuned roots. No effectiveN0 or finite-index replacement for the explicitT_N certificate is claimed.", "priority_context": "PAPER-L001 Lagarias2007 original introductionpp1693–1695 and full§6pp1721–1726 now inspected; finite-height masking and eventual exponential domination are prior literature. This precise constructed-family asymptotic is independently proved with priority unassessed.", "source_scope_note": "PAPER-L001 remains overallLevel0/partial; its full52-page automorphic proof was not read.", "paper_id": null, "locator": "audits/adversarial_reviews/first_negative_li_asymptotic_skeptic_round3.md", "provenance_file": "theorems/beta_smoothing_skeptic_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'The minimum exists, uniformly over all choices of tuned root, and n_-(T)=(T²/a)[2 log T+2 log log T-log a+o(1)] for a=1/4. Thus n_-=8T²logT+8T²loglogT+8(log2)T²+o(T²). The same asymptotic applies along the generic all simple subfamily. No explicit finite-T error or actual negative coefficient index is asserted.','generic_class_model_asymptotic','audits/adversarial_reviews/first_negative_li_asymptotic_skeptic_round3.md','theorems/beta_smoothing_skeptic_round3.jsonl');
INSERT INTO "claims" VALUES('THM-LATEST62-BFH501','theorems/theorems.jsonl',33,'established_primary_source_result','Theorem 1.2 (1.4) p. 3 and pp. 36, 39','{"id": "THM-LATEST62-BFH501", "paper_id": "PAPER-LATEST62-003", "locator": "Theorem 1.2 (1.4) p. 3 and pp. 36, 39", "statement": "Fix 0<ε,c<1 and assume RH. For C_1(ε)/(log log T)≤α log T≪(log log log T)^(-c), the normalized mean of |ζ(1/2+α+it)|^(-1) on [T,2T] is ≪exp((log T)^ε).", "hypotheses": "RH; α>0; T sufficiently large with the stated shift uniformity.", "status": "established_primary_source_result", "verification": "Complete paper Level 1 and scoped proof reconstruction using Lemma 7.2; external pointwise estimates treated as inputs.", "provenance_file": "theorems/bui_florea_heycock_latest62_round5.jsonl"}','PAPER-LATEST62-003','Fix 0<ε,c<1 and assume RH. For C_1(ε)/(log log T)≤α log T≪(log log log T)^(-c), the normalized mean of |ζ(1/2+α+it)|^(-1) on [T,2T] is ≪exp((log T)^ε).',NULL,'Theorem 1.2 (1.4) p. 3 and pp. 36, 39','theorems/bui_florea_heycock_latest62_round5.jsonl');
INSERT INTO "claims" VALUES('LEM-LATEST62-BFH502','theorems/theorems.jsonl',34,'established_primary_source_result_scoped_reconstruction','Lemma 7.2 p. 36; audits/bui_florea_heycock_latest62_fullsource_round5.md','{"id": "LEM-LATEST62-BFH502", "paper_id": "PAPER-LATEST62-003", "locator": "Lemma 7.2 p. 36; audits/bui_florea_heycock_latest62_fullsource_round5.md", "statement": "With the stated small-shift range and (log T)^ε≤V≤V_* as in (7.3), P(-log|ζ(1/2+α+it)|>V)≪exp(−V−2V/log V).", "hypotheses": "RH; 0<ε,c<1; sufficiently large C_1(ε); uniform t on [T,2T].", "status": "established_primary_source_result_scoped_reconstruction", "verification": "The omitted proof was filled in using an exact cutoff J=floor(log V), the prime-sum bound and factorial Markov bounds in §§2 and 7. Cited RH explicit and pointwise estimates treated as inputs.", "provenance_file": "theorems/bui_florea_heycock_latest62_round5.jsonl"}','PAPER-LATEST62-003','With the stated small-shift range and (log T)^ε≤V≤V_* as in (7.3), P(-log|ζ(1/2+α+it)|>V)≪exp(−V−2V/log V).',NULL,'Lemma 7.2 p. 36; audits/bui_florea_heycock_latest62_fullsource_round5.md','theorems/bui_florea_heycock_latest62_round5.jsonl');
INSERT INTO "claims" VALUES('THM-LATEST62-BFH503','theorems/theorems.jsonl',35,'primary_source_statement','Theorem 1.7 pp. 6–7; §§3–6','{"id": "THM-LATEST62-BFH503", "paper_id": "PAPER-LATEST62-003", "locator": "Theorem 1.7 pp. 6–7; §§3–6", "statement": "For V=κ log(1/α), P(-log|ζ(1/2+α+it)|>V)≪(log(1/α))^(-1/2)exp(−V²/log(1/α)).", "hypotheses": "RH; α=o(1); α log T≫1; κ in a fixed compact subinterval of (0,1/2), or any fixed compact positive interval when α log T≫(log(1/α))^(12+ε).", "status": "primary_source_statement", "verification": "Whole-paper Level 1; separate variance inference (6.4) flagged and its local adjustment recorded, whole Gaussian theorem not technically audited.", "provenance_file": "theorems/bui_florea_heycock_latest62_round5.jsonl"}','PAPER-LATEST62-003','For V=κ log(1/α), P(-log|ζ(1/2+α+it)|>V)≪(log(1/α))^(-1/2)exp(−V²/log(1/α)).',NULL,'Theorem 1.7 pp. 6–7; §§3–6','theorems/bui_florea_heycock_latest62_round5.jsonl');
INSERT INTO "claims" VALUES('OBS-LATEST62-BFH504','theorems/theorems.jsonl',36,'scoped_internal_variance_discrepancy_pending_independent_review','Lemma 2.3, (4.4) and (6.4), pp. 12, 16, 27; audits/bui_florea_heycock_latest62_fullsource_round5.md','{"id": "OBS-LATEST62-BFH504", "paper_id": "PAPER-LATEST62-003", "locator": "Lemma 2.3, (4.4) and (6.4), pp. 12, 16, 27; audits/bui_florea_heycock_latest62_fullsource_round5.md", "statement": "The uniform O(1) variance difference printed in (6.4) fails when α log T=log log T, ℓ=2 and j=K. Equation (4.4) implies the weaker O(1+z_ℓ²), absorbed locally by exp(−b c_ℓ) when retained. The terminal checkpoint has bounded z_ℓ.", "status": "scoped_internal_variance_discrepancy_pending_independent_review", "verification": "Displayed source checked visually; explicit admissible regime derived. Impact on the Gaussian theorem unadjudicated. No structural dependency of the reciprocal first moment/Mertens route on this branch.", "novelty_claim": false, "provenance_file": "theorems/bui_florea_heycock_latest62_round5.jsonl"}','PAPER-LATEST62-003','The uniform O(1) variance difference printed in (6.4) fails when α log T=log log T, ℓ=2 and j=K. Equation (4.4) implies the weaker O(1+z_ℓ²), absorbed locally by exp(−b c_ℓ) when retained. The terminal checkpoint has bounded z_ℓ.',NULL,'Lemma 2.3, (4.4) and (6.4), pp. 12, 16, 27; audits/bui_florea_heycock_latest62_fullsource_round5.md','theorems/bui_florea_heycock_latest62_round5.jsonl');
INSERT INTO "claims" VALUES('OBS-CSTAR-BOUNDED-COMMON-REAL-SEQUENCE-NORM-COUNTERMODEL','theorems/theorems.jsonl',37,'adjudicated_scoped','audits/adversarial_reviews/director_bounded_common_checkpoint14.md','{"id": "OBS-CSTAR-BOUNDED-COMMON-REAL-SEQUENCE-NORM-COUNTERMODEL", "paper_id": null, "locator": "audits/adversarial_reviews/director_bounded_common_checkpoint14.md · Bounded construction and progression budgets", "evidence": "audits/adversarial_reviews/director_bounded_common_checkpoint14.md", "claim_kind": "bounded_common_real_sequence_norm_countermodel", "statement": "One real sequence supported on J has exact mass P and takes values in [1/2,3/2] on J. The pooled squared discrepancy of the residue rows from P/k over k≤2K is O(PK), and the sum of the maximum absolute row discrepancies is O(K√P). On units the same orders hold about their induced means. The maximum-error budget is O_A(P/log^A T) for every fixed A. The unit-centered real projection against W(n)=Σ_(k∈S)(c_k/k)·1_((n,k)=1)·(cos(2πn/k)−μ(k)/φ(k)) is ≫|S|√T, exceeding T log⁴T by a divergent factor.", "hypotheses": "Fix 1/2<θ<2/3, K≍T^θ, integer P≍KT and J=[P,2P)∩ℤ. Take the primes in [X,(1+η)X] with X=K^(1/4) and fixed 0<η<2^(1/4)−1. Its full fourth-power support S⊂[K,2K) includes repeated factors, with |S|≍K/log⁴K and multinomial coefficients 1≤c_k≤24. The residue rows arise from one sequence and agree on marginals modulo common divisors. On units, the induced mean at each modulus is the total sequence mass on that modulus’s units divided by φ(k). This ordinary integer-interval setting leaves the prime-model P/φ(k) baseline, prime or sieve support, and the smooth C_* sum open.", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/checkpoint14_bounded_claims.jsonl"}',NULL,'One real sequence supported on J has exact mass P and takes values in [1/2,3/2] on J. The pooled squared discrepancy of the residue rows from P/k over k≤2K is O(PK), and the sum of the maximum absolute row discrepancies is O(K√P). On units the same orders hold about their induced means. The maximum-error budget is O_A(P/log^A T) for every fixed A. The unit-centered real projection against W(n)=Σ_(k∈S)(c_k/k)·1_((n,k)=1)·(cos(2πn/k)−μ(k)/φ(k)) is ≫|S|√T, exceeding T log⁴T by a divergent factor.','bounded_common_real_sequence_norm_countermodel','audits/adversarial_reviews/director_bounded_common_checkpoint14.md · Bounded construction and progression budgets','theorems/checkpoint14_bounded_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-CSTAR-BOUNDED-COMMON-INTEGER-SEQUENCE-NORM-COUNTERMODEL','theorems/theorems.jsonl',38,'adjudicated_scoped','audits/adversarial_reviews/director_bounded_common_checkpoint14.md','{"id": "OBS-CSTAR-BOUNDED-COMMON-INTEGER-SEQUENCE-NORM-COUNTERMODEL", "paper_id": null, "locator": "audits/adversarial_reviews/director_bounded_common_checkpoint14.md · Cap-preserving integerization", "evidence": "audits/adversarial_reviews/director_bounded_common_checkpoint14.md", "claim_kind": "bounded_common_integer_sequence_norm_countermodel", "statement": "One sequence supported on J takes values in {0,1,2} and has exact mass P. The pooled squared discrepancy of the residue rows from P/k over k≤2K is O(PK), and the sum of the maximum absolute row discrepancies is O(K√P). On units the same orders hold about their induced means. The maximum-error budget is O_A(P/log^A T) for every fixed A. The unit-centered real projection against W(n)=Σ_(k∈S)(c_k/k)·1_((n,k)=1)·(cos(2πn/k)−μ(k)/φ(k)) is ≫|S|√T, exceeding T log⁴T by a divergent factor.", "hypotheses": "Fix 1/2<θ<2/3, K≍T^θ, integer P≍KT and J=[P,2P)∩ℤ. Take the primes in [X,(1+η)X] with X=K^(1/4) and fixed 0<η<2^(1/4)−1. Its full fourth-power support S⊂[K,2K) includes repeated factors, with |S|≍K/log⁴K and multinomial coefficients 1≤c_k≤24. The residue rows arise from one sequence and agree on marginals modulo common divisors. On units, the induced mean at each modulus is the total sequence mass on that modulus’s units divided by φ(k). This ordinary integer-interval setting leaves the prime-model P/φ(k) baseline, prime or sieve support, and the smooth C_* sum open.", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/checkpoint14_bounded_claims.jsonl"}',NULL,'One sequence supported on J takes values in {0,1,2} and has exact mass P. The pooled squared discrepancy of the residue rows from P/k over k≤2K is O(PK), and the sum of the maximum absolute row discrepancies is O(K√P). On units the same orders hold about their induced means. The maximum-error budget is O_A(P/log^A T) for every fixed A. The unit-centered real projection against W(n)=Σ_(k∈S)(c_k/k)·1_((n,k)=1)·(cos(2πn/k)−μ(k)/φ(k)) is ≫|S|√T, exceeding T log⁴T by a divergent factor.','bounded_common_integer_sequence_norm_countermodel','audits/adversarial_reviews/director_bounded_common_checkpoint14.md · Cap-preserving integerization','theorems/checkpoint14_bounded_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-CONREYLI-NEGATIVE-SHIFTS','theorems/theorems.jsonl',39,'adjudicated_scoped_validated_finite_certificates_of_prior_results','audits/adversarial_reviews/director_conrey_li_certificates_round6.md; exactscriptsandresults','{"id": "CERT-CONREYLI-NEGATIVE-SHIFTS", "paper_id": "PAPER-OP62-CONREYLI", "claim_kind": "validated_reproduction_of_published_negative_examples", "statement": "AllfourConreyLi1998v1negativepositivityexamplesareindependentlyball-certified:entire-spacezerokernelformsforzetaandprimitivechi4, andreciprocal-spacekernelshiftformsforbothfunctions. Strictlyinteriorpointsw=-282+i1e-6 andw=-8714.2+i1e-6 giveactualsingle-kernelnegativeforms. NoRHorzeroenumerationassumption.", "hypotheses": "Exactlysourcekernelspaces,shift+i,domainandcompletionnormalizations. TwoexplicitactualzeroscertifiedbyIVTanduniformderivativeballs. TrustedFLINTballarithmetic; oneinteriorzetaquotientalsoindependentlyenclosedwithBernoulliremainders.", "locator": "audits/adversarial_reviews/director_conrey_li_certificates_round6.md; exactscriptsandresults", "status": "adjudicated_scoped_validated_finite_certificates_of_prior_results", "novelty_claim": false, "provenance_file": "theorems/conrey_li_director_round6.jsonl"}','PAPER-OP62-CONREYLI','AllfourConreyLi1998v1negativepositivityexamplesareindependentlyball-certified:entire-spacezerokernelformsforzetaandprimitivechi4, andreciprocal-spacekernelshiftformsforbothfunctions. Strictlyinteriorpointsw=-282+i1e-6 andw=-8714.2+i1e-6 giveactualsingle-kernelnegativeforms. NoRHorzeroenumerationassumption.','validated_reproduction_of_published_negative_examples','audits/adversarial_reviews/director_conrey_li_certificates_round6.md; exactscriptsandresults','theorems/conrey_li_director_round6.jsonl');
INSERT INTO "claims" VALUES('OBS-DR2006-HARDY-REPAIR','theorems/theorems.jsonl',40,'adjudicated_verified_versioned_identity_counterexample; correctedProp6.5andmainlowerconstantpreserved','audits/adversarial_reviews/director_deroton_hardy_round6.md; originalpp440–441','{"id": "OBS-DR2006-HARDY-REPAIR", "paper_id": "PAPER-DR2006", "claim_kind": "verified_local_displayed_identity_correction", "statement": "In the pinned2006Proposition6.4 the correct leading term is partial_w^k[(1-w)^(-j)U_F(w)t^-w], not(1-w)^(-j)partial_w^k[U_F(w)t^-w]. ForF=zeta,j=k1,w1/4,epsilon1/8 the omittedterm(16/9)U_zeta(1/4)t^-1/4 is notin theclaimedO(t^-1/8).", "hypotheses": "ActualphaseoperatorandHardyH; interiorparameterswithinprinteddomain; t approaches0. Exact Mellinresiduewitness, noRHornumericassumption.", "locator": "audits/adversarial_reviews/director_deroton_hardy_round6.md; originalpp440–441", "status": "adjudicated_verified_versioned_identity_counterexample; correctedProp6.5andmainlowerconstantpreserved", "novelty_claim": false, "provenance_file": "theorems/deroton_hardy_director_round6.jsonl"}','PAPER-DR2006','In the pinned2006Proposition6.4 the correct leading term is partial_w^k[(1-w)^(-j)U_F(w)t^-w], not(1-w)^(-j)partial_w^k[U_F(w)t^-w]. ForF=zeta,j=k1,w1/4,epsilon1/8 the omittedterm(16/9)U_zeta(1/4)t^-1/4 is notin theclaimedO(t^-1/8).','verified_local_displayed_identity_correction','audits/adversarial_reviews/director_deroton_hardy_round6.md; originalpp440–441','theorems/deroton_hardy_director_round6.jsonl');
INSERT INTO "claims" VALUES('THM-NAKAMURA-ZETA-ID','theorems/theorems.jsonl',41,'adjudicated_scoped','audits/adversarial_reviews/director_nakamura_whole_round10.md','{"id": "THM-NAKAMURA-ZETA-ID", "paper_id": "PAPER-SM63-POS-040", "statement": "RH iff the exact arithmetic g_zeta has exp(g_zeta) an infinitely divisible real-line characteristic function. Under RH its triplet is Gaussian0, uncompensated drift0, finite Levy measure sum_signed m_gamma/gamma² delta_(−gamma). Global nonpositivity alone also supplies the reverse implication.", "hypotheses": "Pinned arxiv2306.08317v1 whole-work audit; source arithmetic formula and signed-zero sum matched through half-line transform and Fourier uniqueness. Named classical xi inputs retained.", "claim_kind": "whole_source_theorems_reconstructed", "locator": "audits/adversarial_reviews/director_nakamura_whole_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}','PAPER-SM63-POS-040','RH iff the exact arithmetic g_zeta has exp(g_zeta) an infinitely divisible real-line characteristic function. Under RH its triplet is Gaussian0, uncompensated drift0, finite Levy measure sum_signed m_gamma/gamma² delta_(−gamma). Global nonpositivity alone also supplies the reverse implication.','whole_source_theorems_reconstructed','audits/adversarial_reviews/director_nakamura_whole_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('THM-FINITE-FROBENIUS-TRACE-CRITERION','theorems/theorems.jsonl',42,'adjudicated_scoped','audits/adversarial_reviews/director_finite_trace_round10.md','{"id": "THM-FINITE-FROBENIUS-TRACE-CRITERION", "paper_id": null, "statement": "For a fixed finite nonzero conjugate- and rho²/alpha-reciprocal multiset with positive multiplicities, purity is equivalent to all two-term power tests |sum(alpha/rho)^n|<=d, to trace positivity on all polynomials, and to one-sided subexponential upper bounds on one density-one set. A joint r-by-r Toeplitz PSD test suffices if r is the distinct root count.", "hypotheses": "Finite compatible spectrum for every power, rho>0; no semisimplicity or infinite-trace conclusion.", "claim_kind": "finite_spectral_equivalences", "locator": "audits/adversarial_reviews/director_finite_trace_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'For a fixed finite nonzero conjugate- and rho²/alpha-reciprocal multiset with positive multiplicities, purity is equivalent to all two-term power tests |sum(alpha/rho)^n|<=d, to trace positivity on all polynomials, and to one-sided subexponential upper bounds on one density-one set. A joint r-by-r Toeplitz PSD test suffices if r is the distinct root count.','finite_spectral_equivalences','audits/adversarial_reviews/director_finite_trace_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-FROBENIUS-PRIME-SAMPLING-FAILURE','theorems/theorems.jsonl',43,'adjudicated_scoped','audits/adversarial_reviews/director_finite_trace_round10.md','{"id": "OBS-FROBENIUS-PRIME-SAMPLING-FAILURE", "paper_id": null, "statement": "At q4, P=(X4+32)(X4+8) is integral reciprocal with off-circle roots, passes all prime-degree two-term tests but fails s4=−10,s8=17 at d8. It also admits an integral alternating similitude and positive formal closed-place counts.", "hypotheses": "Explicit finite algebraic model, not an actual curve zeta function; sparse sampling and point-count-like signs insufficient.", "claim_kind": "exact_sparse_test_counterexample", "locator": "audits/adversarial_reviews/director_finite_trace_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'At q4, P=(X4+32)(X4+8) is integral reciprocal with off-circle roots, passes all prime-degree two-term tests but fails s4=−10,s8=17 at d8. It also admits an integral alternating similitude and positive formal closed-place counts.','exact_sparse_test_counterexample','audits/adversarial_reviews/director_finite_trace_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('THM-INTEGRAL-TRACE-FINITE-CUTOFF','theorems/theorems.jsonl',44,'adjudicated_scoped','audits/adversarial_reviews/director_finite_trace_round10.md','{"id": "THM-INTEGRAL-TRACE-FINITE-CUTOFF", "paper_id": null, "statement": "For monic integral degree d>=1 with nonzero q-reciprocal roots, q>=1 integer, let D=max(d,binom(d,2)), n0=4d(q+1)(2q+1)^(D−1). Purity radius sqrtq iff sum alpha^(n0k)<=d q^(n0k/2) for k1..6^floor(d/2).", "hypotheses": "Algebraic norm gap and simultaneous scaled-phase approximation; repeated/reducible cases allowed, root reciprocity checked exactly. Astronomical finiteness, not an efficient high-degree algorithm.", "claim_kind": "effective_finite_integral_trace_criterion", "locator": "audits/adversarial_reviews/director_finite_trace_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'For monic integral degree d>=1 with nonzero q-reciprocal roots, q>=1 integer, let D=max(d,binom(d,2)), n0=4d(q+1)(2q+1)^(D−1). Purity radius sqrtq iff sum alpha^(n0k)<=d q^(n0k/2) for k1..6^floor(d/2).','effective_finite_integral_trace_criterion','audits/adversarial_reviews/director_finite_trace_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-RVM-BOUNDED-ALL-GRID-POSITIVITY','theorems/theorems.jsonl',45,'adjudicated_scoped','audits/adversarial_reviews/director_bounded_positivity_round10.md','{"id": "OBS-RVM-BOUNDED-ALL-GRID-POSITIVITY", "paper_id": null, "statement": "For every bounded diameter H and strip halfwidth0<a<.5 there is an even real order-one infinite-type entire model, positive on the imaginary axis, smooth RVM count+O1, and one remote off-real quartet. Its exp(c g) matrix is PSD on EVERY finite grid of diameter<=H for every c>0, but g is unbounded above at late times.", "hypotheses": "Exact paired canonical product and logarithmic-derivative transform; no zeta Euler product or global prime-side formula preserved.", "claim_kind": "all_grid_analytic_countermodel", "locator": "audits/adversarial_reviews/director_bounded_positivity_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'For every bounded diameter H and strip halfwidth0<a<.5 there is an even real order-one infinite-type entire model, positive on the imaginary axis, smooth RVM count+O1, and one remote off-real quartet. Its exp(c g) matrix is PSD on EVERY finite grid of diameter<=H for every c>0, but g is unbounded above at late times.','all_grid_analytic_countermodel','audits/adversarial_reviews/director_bounded_positivity_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-RVM-CUSP-POSITIVITY-OBSTRUCTION','theorems/theorems.jsonl',46,'adjudicated_scoped','audits/adversarial_reviews/director_bounded_positivity_round10.md','{"id": "OBS-RVM-CUSP-POSITIVITY-OBSTRUCTION", "paper_id": null, "statement": "The same model matches −.5|t|log(1/|t|)+.5(log2pi+gammaE−1)|t|+O(t²), also the actual arithmetic cusp. Thus those terms plus RVM count and every bounded-diameter positive-power test do not force global real-line positivity.", "hypotheses": "Stieltjes derivative cancellation controls O(t²); model counting main term, not the literal fluctuating zeta zero count.", "claim_kind": "local_information_countermodel", "locator": "audits/adversarial_reviews/director_bounded_positivity_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'The same model matches −.5|t|log(1/|t|)+.5(log2pi+gammaE−1)|t|+O(t²), also the actual arithmetic cusp. Thus those terms plus RVM count and every bounded-diameter positive-power test do not force global real-line positivity.','local_information_countermodel','audits/adversarial_reviews/director_bounded_positivity_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('THM-SHARP-CRITICAL-DERIVATIVE-BLOCK','theorems/theorems.jsonl',47,'adjudicated_scoped','audits/adversarial_reviews/director_sharper_moment_round10.md','{"id": "THM-SHARP-CRITICAL-DERIVATIVE-BLOCK", "paper_id": null, "statement": "Unconditionally for T>=100, r=min(.25,2/logT), the two-sign block sum |zeta prime(rho)|²|2^(1−rho)−1|² over T<|gamma|<=2T on the critical line is <=3600TlogT/r³. Exact radius-switched dyadic tail has leading upper coefficient900 log4Y/Y.", "hypotheses": "Distinct critical zeros, multiple zeros contribute0; local Hardy phase cancellation, Gaussian mean-square and cutoff Rolle. No RH or separation.", "claim_kind": "unconditional_effective_moment_bound", "locator": "audits/adversarial_reviews/director_sharper_moment_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'Unconditionally for T>=100, r=min(.25,2/logT), the two-sign block sum |zeta prime(rho)|²|2^(1−rho)−1|² over T<|gamma|<=2T on the critical line is <=3600TlogT/r³. Exact radius-switched dyadic tail has leading upper coefficient900 log4Y/Y.','unconditional_effective_moment_bound','audits/adversarial_reviews/director_sharper_moment_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-SHARP-CRITICAL-SERIES-SPLICE','theorems/theorems.jsonl',48,'adjudicated_scoped','audits/adversarial_reviews/director_sharper_moment_round10.md','{"id": "CERT-SHARP-CRITICAL-SERIES-SPLICE", "paper_id": null, "statement": "The complete height100 coefficient sum and two Arb-certified Hardy-derivative integral blocks yield full critical derivative series in[0.25253801685456458,8249.21].", "hypotheses": "Entire tail included analytically from400, holomorphic squared integrands on separate polynomial pieces, FLINT3.6.0. Series enclosure unconditional; RH identifies prime-array C2.", "claim_kind": "validated_continuous_integral_splice", "locator": "audits/adversarial_reviews/director_sharper_moment_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'The complete height100 coefficient sum and two Arb-certified Hardy-derivative integral blocks yield full critical derivative series in[0.25253801685456458,8249.21].','validated_continuous_integral_splice','audits/adversarial_reviews/director_sharper_moment_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('THM-NAKAMURA-PROBABILITY-TAIL','theorems/theorems.jsonl',49,'adjudicated_scoped','audits/adversarial_reviews/director_probability_tail_round10.md','{"id": "THM-NAKAMURA-PROBABILITY-TAIL", "paper_id": null, "statement": "Under RH, the source compound Poisson law has P(|X|>Y)=[log(Y/(2pi))+1]/(piY)+O(log³Y/Y²). Positive absolute pth moments exist exactly0<p<1, and exceedance ratios tend to Pareto1.", "hypotheses": "Both-sign multiplicity weights m/gamma²; strict endpoints; direct polynomial-in-n error averaged over Poisson counts, not inverse-derivative weights.", "claim_kind": "conditional_probability_tail_asymptotic", "locator": "audits/adversarial_reviews/director_probability_tail_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'Under RH, the source compound Poisson law has P(|X|>Y)=[log(Y/(2pi))+1]/(piY)+O(log³Y/Y²). Positive absolute pth moments exist exactly0<p<1, and exceedance ratios tend to Pareto1.','conditional_probability_tail_asymptotic','audits/adversarial_reviews/director_probability_tail_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-NAKAMURA-ZERO-ATOM','theorems/theorems.jsonl',50,'adjudicated_scoped','audits/adversarial_reviews/director_probability_tail_round10.md','{"id": "CERT-NAKAMURA-ZERO-ATOM", "paper_id": null, "statement": "Under RH intensity S=xi doubleprime(.5)/xi(.5)=0.046209986230837941577867620860678028...; 0.95487677454644730<P(X=0)<0.95490529007639706. The zero atom strictly exceeds exp(−S) through opposite-jump cancellation.", "hypotheses": "128bit director and independent160/192bit calculations, complete29-zero count and explicit remaining square-mass cap. Ordinary mean does not exist.", "claim_kind": "conditional_validated_probability_bounds", "locator": "audits/adversarial_reviews/director_probability_tail_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'Under RH intensity S=xi doubleprime(.5)/xi(.5)=0.046209986230837941577867620860678028...; 0.95487677454644730<P(X=0)<0.95490529007639706. The zero atom strictly exceeds exp(−S) through opposite-jump cancellation.','conditional_validated_probability_bounds','audits/adversarial_reviews/director_probability_tail_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('THM-NAKAMURA-DENSE-ATOMS','theorems/theorems.jsonl',51,'adjudicated_scoped','audits/adversarial_reviews/director_probability_tail_round10.md','{"id": "THM-NAKAMURA-DENSE-ATOMS", "paper_id": null, "statement": "Under RH the source law is pure point with atom set the countable dense group of finite integer combinations of zero ordinates, and topological support R.", "hypotheses": "BCY .4058 simple-critical proportion provides more than O(T) distinct ordinates, excluding a discrete cyclic subgroup. No rational linear-independence assumption.", "claim_kind": "conditional_support_theorem", "locator": "audits/adversarial_reviews/director_probability_tail_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'Under RH the source law is pure point with atom set the countable dense group of finite integer combinations of zero ordinates, and topological support R.','conditional_support_theorem','audits/adversarial_reviews/director_probability_tail_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('THM-NAKAMURA-CAUCHY-SCALING','theorems/theorems.jsonl',52,'adjudicated_scoped','audits/adversarial_reviews/director_probability_tail_round10.md','{"id": "THM-NAKAMURA-CAUCHY-SCALING", "paper_id": null, "statement": "Under RH iid sums from the source law divided by nlogn/2 tend to standard Cauchy. The exact unconditional cusp contains quadratic term−7t²/8. The off-axis RVM countermodel has the same formal pointwise Cauchy scaling despite failure of global characteristic positivity.", "hypotheses": "Probability limit uses source RH criterion; formal scaling of arbitrary functions is not Levy continuity without the characteristic-function premise.", "claim_kind": "conditional_limit_and_negative_control", "locator": "audits/adversarial_reviews/director_probability_tail_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'Under RH iid sums from the source law divided by nlogn/2 tend to standard Cauchy. The exact unconditional cusp contains quadratic term−7t²/8. The off-axis RVM countermodel has the same formal pointwise Cauchy scaling despite failure of global characteristic positivity.','conditional_limit_and_negative_control','audits/adversarial_reviews/director_probability_tail_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('THM-EULER-TILT-BOUNDARY','theorems/theorems.jsonl',53,'adjudicated_scoped','audits/adversarial_reviews/director_prime_phase_clt_round10.md','{"id": "THM-EULER-TILT-BOUNDARY", "paper_id": null, "statement": "For sigma>.5, prime Poisson product radii p^(−sigma) is Haar-equivalent with density |randomEulerProduct|²/zeta(2sigma). At sigma=.5 it is singularHaar: W_P/H_P tends to1 under the product and0 underHaar almost surely.", "hypotheses": "Product-torus statement, H_P=sum1/p, W_P=sum ReU_p/sqrtp; L2 martingale off line and explicit variance-summable separating event at boundary.", "claim_kind": "unconditional_product_measure_theorem", "locator": "audits/adversarial_reviews/director_prime_phase_clt_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'For sigma>.5, prime Poisson product radii p^(−sigma) is Haar-equivalent with density |randomEulerProduct|²/zeta(2sigma). At sigma=.5 it is singularHaar: W_P/H_P tends to1 under the product and0 underHaar almost surely.','unconditional_product_measure_theorem','audits/adversarial_reviews/director_prime_phase_clt_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('THM-ARITHMETIC-PRIME-PHASE-CLT','theorems/theorems.jsonl',54,'adjudicated_scoped','audits/adversarial_reviews/director_prime_phase_clt_round10.md','{"id": "THM-ARITHMETIC-PRIME-PHASE-CLT", "paper_id": null, "statement": "Under RH, draw |gamma|>Y with normalized |zeta prime(.5+i gamma)|²/(.25+gamma²) weights. For fixedD>0,P=log^D Y,H=sum1/p,V=.5sum(1/p−1/p²), W=sumcos(gamma logp)/sqrtp: P(|W/H−1|>epsilon)<<1/H and (W−H)/sqrtV tends toN01 with every fixed moment.", "hypotheses": "Full two-sign or equivalent positive-ordinate real statistic. Refined uniform rational-character bound at each fixed moment order, saving chosen afterD,k. Ineffective onset, no unweighted/spacing or TV assertion.", "claim_kind": "conditional_arithmetic_central_limit_theorem", "locator": "audits/adversarial_reviews/director_prime_phase_clt_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'Under RH, draw |gamma|>Y with normalized |zeta prime(.5+i gamma)|²/(.25+gamma²) weights. For fixedD>0,P=log^D Y,H=sum1/p,V=.5sum(1/p−1/p²), W=sumcos(gamma logp)/sqrtp: P(|W/H−1|>epsilon)<<1/H and (W−H)/sqrtV tends toN01 with every fixed moment.','conditional_arithmetic_central_limit_theorem','audits/adversarial_reviews/director_prime_phase_clt_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-CENTRAL-DRIFT-REGULARIZATION','theorems/theorems.jsonl',55,'adjudicated_scoped','audits/adversarial_reviews/director_central_drift_round10.md','{"id": "OBS-CENTRAL-DRIFT-REGULARIZATION", "paper_id": "PAPER-POS64-OPPROB-016", "statement": "In arxiv2307.02027v1 eq2.7 the full ordinary xiFprime/xiF(.5) is undefined for m0>0. Correct drift is i times its regular part after subtracting m0/(s−.5). Full transform retains the central pole and Gaussian variance m0.", "hypotheses": "Exact preprint only, two independently checked source manifestations and explicit weight18 central-zero witness; no journal text obtained.", "claim_kind": "verified_versioned_auxiliary_definition_error", "locator": "audits/adversarial_reviews/director_central_drift_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}','PAPER-POS64-OPPROB-016','In arxiv2307.02027v1 eq2.7 the full ordinary xiFprime/xiF(.5) is undefined for m0>0. Correct drift is i times its regular part after subtracting m0/(s−.5). Full transform retains the central pole and Gaussian variance m0.','verified_versioned_auxiliary_definition_error','audits/adversarial_reviews/director_central_drift_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('THM-REGULARIZED-SELBERG-ID','theorems/theorems.jsonl',56,'adjudicated_scoped','audits/adversarial_reviews/director_central_drift_round10.md','{"id": "THM-REGULARIZED-SELBERG-ID", "paper_id": "PAPER-POS64-OPPROB-016", "statement": "For fixed SelbergF, corrected exponent with Gaussian m0, finite regular drift and noncentral zero sum is infinitely divisible iff its GRH holds. Reverse follows directly from O(1+t²) Levy-Khintchine log growth and the full half-line transform.", "hypotheses": "Pinned source correction, order<=1 and strip inputs; ordinary drift can be nonzero, so decomposition includes deterministic translation. No whole-work promotion for this source.", "claim_kind": "corrected_source_criterion", "locator": "audits/adversarial_reviews/director_central_drift_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}','PAPER-POS64-OPPROB-016','For fixed SelbergF, corrected exponent with Gaussian m0, finite regular drift and noncentral zero sum is infinitely divisible iff its GRH holds. Reverse follows directly from O(1+t²) Levy-Khintchine log growth and the full half-line transform.','corrected_source_criterion','audits/adversarial_reviews/director_central_drift_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-DEGREE1-CENTRAL-SHIFT','theorems/theorems.jsonl',57,'adjudicated_scoped','audits/adversarial_reviews/director_central_drift_round10.md','{"id": "OBS-DEGREE1-CENTRAL-SHIFT", "paper_id": "PAPER-POS64-OPPROB-016", "statement": "Choose tau an actual certified beta critical ordinate in[6.02094890469,6.02094890471]. F_tau(s)=L(s+i tau,chi4) satisfies all printed Selberg axioms, has degree1 and a central zero. The source degree>=2 expectation omits the extra normalized-height restriction.", "hypotheses": "Pole-free primitive Dirichlet example; gamma shifts complex allowed, root number Q^(−2i tau). No GRH/simplicity needed for central existence. Nonzero zeta shifts fail the pole-location axiom.", "claim_kind": "exact_missing_normalization_counterexample", "locator": "audits/adversarial_reviews/director_central_drift_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}','PAPER-POS64-OPPROB-016','Choose tau an actual certified beta critical ordinate in[6.02094890469,6.02094890471]. F_tau(s)=L(s+i tau,chi4) satisfies all printed Selberg axioms, has degree1 and a central zero. The source degree>=2 expectation omits the extra normalized-height restriction.','exact_missing_normalization_counterexample','audits/adversarial_reviews/director_central_drift_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('THM-VERTICAL-GAUSSIAN-DIFFUSION','theorems/theorems.jsonl',58,'adjudicated_scoped','audits/adversarial_reviews/director_vertical_diffusion_round10.md','{"id": "THM-VERTICAL-GAUSSIAN-DIFFUSION", "paper_id": null, "statement": "For pole-free Selberg vertical family, compensated exponents extend locally uniformly through each zero crossing; underGRH associated laws are weakly continuous. A zero of multiplicitym reaching0 yields centered jump −delta[Poisson(m/delta²)−m/delta²] tending toN(0,m).", "hypotheses": "Drift sign b=−rawHadamardB; divergence cancels before taking limit. Full spectrum tail dominated by inverse squares on compact shifts, regularized central drift, fixed completion.", "claim_kind": "conditional_diffusive_bridge", "locator": "audits/adversarial_reviews/director_vertical_diffusion_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10_claims.jsonl"}',NULL,'For pole-free Selberg vertical family, compensated exponents extend locally uniformly through each zero crossing; underGRH associated laws are weakly continuous. A zero of multiplicitym reaching0 yields centered jump −delta[Poisson(m/delta²)−m/delta²] tending toN(0,m).','conditional_diffusive_bridge','audits/adversarial_reviews/director_vertical_diffusion_round10.md','theorems/director_round10_claims.jsonl');
INSERT INTO "claims" VALUES('THM-LAGARIAS-WHOLE-CRITERION','theorems/theorems.jsonl',59,'adjudicated_scoped','audits/adversarial_reviews/director_lagarias_whole_round10.md','{"id": "THM-LAGARIAS-WHOLE-CRITERION", "paper_id": "PAPER-R001", "statement": "RH iff sigma(n)<=H_n+exp(H_n)logH_n for every positive integer n, with equality only1. Both proof directions and all contextual mathematical statements reconstructed with recorded local corrections and accepted classical inputs.", "hypotheses": "Exact arxivmath0008177v2, version v2, 2001-05-06; Robin criterion and oscillation matched in original journal; complete finite cutoff through5041 and22CA table rows independently replayed. Journal wording inaccessible.", "claim_kind": "whole_source_theorem_reconstruction", "locator": "audits/adversarial_reviews/director_lagarias_whole_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10b_claims.jsonl"}','PAPER-R001','RH iff sigma(n)<=H_n+exp(H_n)logH_n for every positive integer n, with equality only1. Both proof directions and all contextual mathematical statements reconstructed with recorded local corrections and accepted classical inputs.','whole_source_theorem_reconstruction','audits/adversarial_reviews/director_lagarias_whole_round10.md','theorems/director_round10b_claims.jsonl');
INSERT INTO "claims" VALUES('THM-EFFECTIVE-SCALAR-PRIME-CLT','theorems/theorems.jsonl',60,'adjudicated_scoped','audits/adversarial_reviews/director_effective_scalar_clt_round10.md','{"id": "THM-EFFECTIVE-SCALAR-PRIME-CLT", "paper_id": null, "statement": "Under RH the standardized scalar W prime-phase statistic for P=log^D Y has effective convergence of every fixed moment and effective Kolmogorov convergence toN01. For computable fixedD>0 andepsilon>0 a conditional thresholdY0 is effectively computable.", "hypotheses": "Exact normalized two-sign |zeta prime|²/(.25+gamma²) strict-tail law; H=sum1/p,V=.5sum(1/p−1/p²),W=sumcos(gamma logp)/sqrtp. Delete a possible exceptional-conductor prime and restore full statistic at each prefix BEFORE integration. No numericalY0 allocated or effective all-coordinate covariance asserted.", "claim_kind": "conditional_effective_scalar_limit", "locator": "audits/adversarial_reviews/director_effective_scalar_clt_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10b_claims.jsonl"}',NULL,'Under RH the standardized scalar W prime-phase statistic for P=log^D Y has effective convergence of every fixed moment and effective Kolmogorov convergence toN01. For computable fixedD>0 andepsilon>0 a conditional thresholdY0 is effectively computable.','conditional_effective_scalar_limit','audits/adversarial_reviews/director_effective_scalar_clt_round10.md','theorems/director_round10b_claims.jsonl');
INSERT INTO "claims" VALUES('THM-Q2-FULL-MOMENT-QUARTIC','theorems/theorems.jsonl',61,'adjudicated_scoped','audits/adversarial_reviews/director_q2_quartic_round10.md','{"id": "THM-Q2-FULL-MOMENT-QUARTIC", "paper_id": null, "statement": "The exact Q2 density D2(L) and prefix polynomial Pminus=sum(−1)^j D2^(j) are as displayed in the director note. The reflected mixed prefix is T Pminus(log(T/2pi))/(2pi)+O_A(Tlog^(−A)T). Under RH its error isOepsilon(T^(7/8+epsilon)) and strict two-sign nonnegative tail is Pplus(log(Y/2pi))/(piY)+Oepsilon(Y^(−9/8+epsilon)).", "hypotheses": "Q2=2*2^(−s)−1 fixed, all nonprincipal conductor terms identically0; independent complex-shift residues, parity kernel and sharp fixed-ratio productAFE. Numerical remainder constants unallocated.", "claim_kind": "source_matched_quartic_and_conditional_power_saving", "locator": "audits/adversarial_reviews/director_q2_quartic_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10b_claims.jsonl"}',NULL,'The exact Q2 density D2(L) and prefix polynomial Pminus=sum(−1)^j D2^(j) are as displayed in the director note. The reflected mixed prefix is T Pminus(log(T/2pi))/(2pi)+O_A(Tlog^(−A)T). Under RH its error isOepsilon(T^(7/8+epsilon)) and strict two-sign nonnegative tail is Pplus(log(Y/2pi))/(piY)+Oepsilon(Y^(−9/8+epsilon)).','source_matched_quartic_and_conditional_power_saving','audits/adversarial_reviews/director_q2_quartic_round10.md','theorems/director_round10b_claims.jsonl');
INSERT INTO "claims" VALUES('THM-WEIGHTED-VECTOR-ROLLE-TAIL','theorems/theorems.jsonl',62,'adjudicated_scoped','audits/adversarial_reviews/director_weighted_rolle_round10.md','{"id": "THM-WEIGHTED-VECTOR-ROLLE-TAIL", "paper_id": null, "statement": "Unconditionally the distinct-critical-line Q2 derivative series has limsup Y*tail(Y)/log^4Y<=1/(4sqrt15). Explicit weighted vector-Rolle and centered Euler/Hilbert formulas bound the whole tail beyond10000 by1.741202.", "hypotheses": "Both signs, multiple-zero terms0; no RH or zero separation. Separate component Rolle points, actual sparse frequency gaps with first-tail-even exception, real-axis product-rule remainder. Thin-block limits take height first.", "claim_kind": "unconditional_effective_critical_series_bound", "locator": "audits/adversarial_reviews/director_weighted_rolle_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10b_claims.jsonl"}',NULL,'Unconditionally the distinct-critical-line Q2 derivative series has limsup Y*tail(Y)/log^4Y<=1/(4sqrt15). Explicit weighted vector-Rolle and centered Euler/Hilbert formulas bound the whole tail beyond10000 by1.741202.','unconditional_effective_critical_series_bound','audits/adversarial_reviews/director_weighted_rolle_round10.md','theorems/director_round10b_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-Q2-SERIES-10000','theorems/theorems.jsonl',63,'adjudicated_scoped','audits/adversarial_reviews/director_weighted_rolle_round10.md','{"id": "CERT-Q2-SERIES-10000", "paper_id": null, "statement": "The complete finite two-sign sum through10000 lies strictly between0.61649875288731141829 and0.61649875288731141830. Combined with the complete analytic tail, the unconditional critical-line series satisfies0.61649875288731141829<C2<2.35771.", "hypotheses": "10142positive simple critical zeros exhaust independent all-zero multiplicity count at10000+2^(−10);160bit full run independently replayed;192bit director shared-prefix replay. Quartic splice near.65339 is observation only.", "claim_kind": "validated_full_series_interval", "locator": "audits/adversarial_reviews/director_weighted_rolle_round10.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round10b_claims.jsonl"}',NULL,'The complete finite two-sign sum through10000 lies strictly between0.61649875288731141829 and0.61649875288731141830. Combined with the complete analytic tail, the unconditional critical-line series satisfies0.61649875288731141829<C2<2.35771.','validated_full_series_interval','audits/adversarial_reviews/director_weighted_rolle_round10.md','theorems/director_round10b_claims.jsonl');
INSERT INTO "claims" VALUES('THM-HLZ-JOURNAL5-REAL-COEFFICIENTS','theorems/theorems.jsonl',64,'adjudicated_scoped','audits/adversarial_reviews/director_polynomial_bands_round11.md','{"id": "THM-HLZ-JOURNAL5-REAL-COEFFICIENTS", "paper_id": "PAPER-DM63-HLZ2022", "statement": "For real Dirichlet Q(s)=sum_(n<=T^delta) a(n)n^(−s), delta<1/2, the shifted zero sum in HLZ Theorem 5 equals J(alpha,beta,T)+I(alpha,beta,T)+I(beta,alpha,T)+O_A(T(log T)^(−A)) for every fixed A>0. J and I are the exact expressions in journal equations (5) and (24).", "hypotheses": "Unconditional published input; |alpha|,|beta|<=c/log T, fixed small c; common fixed divisor-log coefficient envelope and |a(mn)| bounded by a constant times |a(m)a(n)|; the bounded unit coefficient is treated separately. The real-coefficient specialization avoids hidden conjugation conventions. Theorem 5 is distinct from the smoothing Lemma 6/Theorem 4. Sharp continuous input is independently reconstructed.", "claim_kind": "matched_published_primary_theorem", "locator": "audits/adversarial_reviews/director_polynomial_bands_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}','PAPER-DM63-HLZ2022','For real Dirichlet Q(s)=sum_(n<=T^delta) a(n)n^(−s), delta<1/2, the shifted zero sum in HLZ Theorem 5 equals J(alpha,beta,T)+I(alpha,beta,T)+I(beta,alpha,T)+O_A(T(log T)^(−A)) for every fixed A>0. J and I are the exact expressions in journal equations (5) and (24).','matched_published_primary_theorem','audits/adversarial_reviews/director_polynomial_bands_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('THM-JOINT-PRIME-GAUSSIAN-ARRAY','theorems/theorems.jsonl',65,'adjudicated_scoped','audits/adversarial_reviews/director_joint_brownian_round11.md','{"id": "THM-JOINT-PRIME-GAUSSIAN-ARRAY", "paper_id": null, "statement": "Under RH, fixed-dimensional cosine/sine normalized prime arrays on p ≤ (log Y)^D with covariance Σ_Y → Σ finite tend to N(0, Σ) if and only if max_p(‖a_p‖ + ‖b_p‖) → 0. Sufficiency is effective with computable fixed parameters and convergence moduli.", "hypotheses": "Exact symmetric strict tail probability weighted by |ζ′|²/(1/4 + γ²). The covariance uses v_p = (1 − 1/p)/2. The real coordinate is centered by p^(−1/2) and the imaginary coordinate by 0. Necessity uses unrestricted qualitative comparison and Cramér’s theorem. Singular covariance is allowed. Orthant effectivity requires positive limiting marginal variances.", "claim_kind": "conditional_joint_array_gaussian_criterion", "locator": "audits/adversarial_reviews/director_joint_brownian_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}',NULL,'Under RH, fixed-dimensional cosine/sine normalized prime arrays on p ≤ (log Y)^D with covariance Σ_Y → Σ finite tend to N(0, Σ) if and only if max_p(‖a_p‖ + ‖b_p‖) → 0. Sufficiency is effective with computable fixed parameters and convergence moduli.','conditional_joint_array_gaussian_criterion','audits/adversarial_reviews/director_joint_brownian_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('THM-FINITE-VARIANCE-PRIME-ANNULI','theorems/theorems.jsonl',66,'adjudicated_scoped','audits/adversarial_reviews/director_joint_brownian_round11.md','{"id": "THM-FINITE-VARIANCE-PRIME-ANNULI", "paper_id": null, "statement": "Under RH, disjoint centered unnormalized cosine bands (log Y)^(a_i) < p ≤ (log Y)^(b_i) have independent Gaussian limits of variance (1/2) log(b_i/a_i), for fixed positive separated exponent intervals.", "hypotheses": "Columns tend to zero as their primes tend to infinity. The variance need not diverge. Standardized cumulative cutoffs at (log Y)^D have limiting correlation 1.", "claim_kind": "conditional_moving_band_limit", "locator": "audits/adversarial_reviews/director_joint_brownian_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}',NULL,'Under RH, disjoint centered unnormalized cosine bands (log Y)^(a_i) < p ≤ (log Y)^(b_i) have independent Gaussian limits of variance (1/2) log(b_i/a_i), for fixed positive separated exponent intervals.','conditional_moving_band_limit','audits/adversarial_reviews/director_joint_brownian_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('THM-PRIME-BROWNIAN-PROCESS','theorems/theorems.jsonl',67,'adjudicated_scoped','audits/adversarial_reviews/director_joint_brownian_round11.md','{"id": "THM-PRIME-BROWNIAN-PROCESS", "paper_id": null, "statement": "Under RH, set L = log Y, b = log L, H = log b, and X_Y(u) = √(2/H) Σ_{p ≤ exp(b^u)} [cos(γ log p)/√p − 1/p]. For fixed 0 ≤ u₀ < 1, X_Y converges to standard Brownian motion restricted to [u₀, 1] in D with the J₁ topology. An effective conditional bounded-Lipschitz onset exists for computable parameters.", "hypotheses": "The same exact two-sign strict derivative-weighted law applies. The proof uses uniform subset fourth moments bounded by C(Σ 1/p)², exact reciprocal-clock interpolation, an all-time modulus, and finite-dimensional comparison. Numerical onset and the unweighted zero law are outside this result.", "claim_kind": "conditional_functional_limit", "locator": "audits/adversarial_reviews/director_joint_brownian_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}',NULL,'Under RH, set L = log Y, b = log L, H = log b, and X_Y(u) = √(2/H) Σ_{p ≤ exp(b^u)} [cos(γ log p)/√p − 1/p]. For fixed 0 ≤ u₀ < 1, X_Y converges to standard Brownian motion restricted to [u₀, 1] in D with the J₁ topology. An effective conditional bounded-Lipschitz onset exists for computable parameters.','conditional_functional_limit','audits/adversarial_reviews/director_joint_brownian_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('THM-INTEGER-TOEPLITZ-PURITY','theorems/theorems.jsonl',68,'adjudicated_scoped','audits/adversarial_reviews/director_integer_trace_round11.md','{"id": "THM-INTEGER-TOEPLITZ-PURITY", "paper_id": null, "statement": "A monic integral q-reciprocal polynomial of degree d with nonzero roots and integer q ≥ 1 is pure of radius √q if and only if K_{ij} = q^min(i,j) t_{|i−j|} is positive semidefinite for 0 ≤ i,j < d, where t_n = Σ α^n and t₀ = d. Its inertia is (c + b, b, d − c − 2b), with c distinct circle roots and b off-circle reciprocal-conjugate pairs.", "hypotheses": "Multiplicities are positive, and real coefficients give conjugate closure. Repeated roots and reducibility are allowed. Exact Newton traces through d − 1 and rational pivoting give a polynomial-bit algorithm. The classical power-sum Toeplitz criterion is credited to Heinig–Rost.", "claim_kind": "classical_criterion_arithmetic_specialization", "locator": "audits/adversarial_reviews/director_integer_trace_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}',NULL,'A monic integral q-reciprocal polynomial of degree d with nonzero roots and integer q ≥ 1 is pure of radius √q if and only if K_{ij} = q^min(i,j) t_{|i−j|} is positive semidefinite for 0 ≤ i,j < d, where t_n = Σ α^n and t₀ = d. Its inertia is (c + b, b, d − c − 2b), with c distinct circle roots and b off-circle reciprocal-conjugate pairs.','classical_criterion_arithmetic_specialization','audits/adversarial_reviews/director_integer_trace_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-GLOBAL-HARDY-C2','theorems/theorems.jsonl',69,'adjudicated_scoped','audits/adversarial_reviews/director_global_hardy_round11.md','{"id": "CERT-GLOBAL-HARDY-C2", "paper_id": null, "statement": "Unconditionally, the distinct-critical-line derivative series satisfies 0.61649875288731141829 < C₂ < 1.075561. The tail beyond 10,000 is less than 0.45906151 by global variation of Q₂Z/t with rational parameters and a complete infinite residual bound.", "hypotheses": "Uses the existing full 160-bit census of 10,142 positive zeros, independent replays, and the director’s 192-bit bound. RH is used only to identify the tapered-array limit. The quartic splice near 0.65339 remains observational.", "claim_kind": "validated_unconditional_full_series_interval", "locator": "audits/adversarial_reviews/director_global_hardy_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}',NULL,'Unconditionally, the distinct-critical-line derivative series satisfies 0.61649875288731141829 < C₂ < 1.075561. The tail beyond 10,000 is less than 0.45906151 by global variation of Q₂Z/t with rational parameters and a complete infinite residual bound.','validated_unconditional_full_series_interval','audits/adversarial_reviews/director_global_hardy_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('THM-DENINGER-REAL-DESCENT-OBSTRUCTION','theorems/theorems.jsonl',70,'adjudicated_scoped','audits/adversarial_reviews/director_deninger_whole_round11.md','{"id": "THM-DENINGER-REAL-DESCENT-OBSTRUCTION", "paper_id": "PAPER-GEO65-001", "statement": "A real equivariant central spectral space satisfying Artin multiplicity axiom 2.12 is impossible at a Galois field with a quaternionic irreducible representation of odd central Artin order. Such Q₈ fields exist, excluding a universal arithmetic-curve theory with these properties.", "hypotheses": "The audit pins the complete arXiv:2204.02714v2 and compares the published version. Real complexification gives even quaternionic multiplicity. The entire monomial Hecke witness has negative root number. An isolated realization over ℚ and conjectural complex or quaternionic coefficient theories are outside the obstruction.", "claim_kind": "whole_source_obstruction_reconstructed", "locator": "audits/adversarial_reviews/director_deninger_whole_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}','PAPER-GEO65-001','A real equivariant central spectral space satisfying Artin multiplicity axiom 2.12 is impossible at a Galois field with a quaternionic irreducible representation of odd central Artin order. Such Q₈ fields exist, excluding a universal arithmetic-curve theory with these properties.','whole_source_obstruction_reconstructed','audits/adversarial_reviews/director_deninger_whole_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-SUZUKI-COMPENSATED-DRIFT-SIGN','theorems/theorems.jsonl',71,'adjudicated_scoped','audits/adversarial_reviews/director_suzuki_drift_round11.md','{"id": "OBS-SUZUKI-COMPENSATED-DRIFT-SIGN", "paper_id": "PAPER-POS64-OPPROB-018", "statement": "On page 6 of arXiv:2209.12832v2, the term +iCt outside the integral requires C = −B − Σ m/[γ(1 + γ²)]. The displayed coefficient has the opposite sign. The exact S♯ example F = 1 + 2i·4^(−s) gives −8 log 2/17 for the printed C and +8 log 2/17 for the required C.", "hypotheses": "Source equations (1.1) and (2.5)–(2.6), signed atoms −γ, and truncation x/(1 + x²) are fixed. The change is a deterministic translation. The Gaussian and jump measures, screw kernel, and real-part criterion are unchanged. Journal wording is unverified.", "claim_kind": "verified_versioned_auxiliary_representation_error", "locator": "audits/adversarial_reviews/director_suzuki_drift_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}','PAPER-POS64-OPPROB-018','On page 6 of arXiv:2209.12832v2, the term +iCt outside the integral requires C = −B − Σ m/[γ(1 + γ²)]. The displayed coefficient has the opposite sign. The exact S♯ example F = 1 + 2i·4^(−s) gives −8 log 2/17 for the printed C and +8 log 2/17 for the required C.','verified_versioned_auxiliary_representation_error','audits/adversarial_reviews/director_suzuki_drift_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('THM-SCALAR-PRIME-SUBPOWER-POLYNOMIAL','theorems/theorems.jsonl',72,'adjudicated_scoped','audits/adversarial_reviews/director_polynomial_bands_round11.md','{"id": "THM-SCALAR-PRIME-SUBPOWER-POLYNOMIAL", "paper_id": null, "statement": "Under RH, every subpower cutoff P(Y) → ∞ with log P = o(log Y) gives all fixed Gaussian moments of standardized W_P. At P = Y^θ with 0 < θ < 1/2, weak Gaussian convergence holds, and moments through 2k converge when kθ < 1/2.", "hypotheses": "Uses natural cosine coefficients 1/√p, exact H_P and V_P centering and variance, and the symmetric strict tail. The bounded-coefficient aggregate polynomial theorem precedes main-term expansion. The proof uses near-power truncation and an upper-band L^p bound. The endpoint θ = 1/2 and all moments at fixed θ remain outside the result.", "claim_kind": "conditional_extended_scalar_cutoff_limit", "locator": "audits/adversarial_reviews/director_polynomial_bands_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}',NULL,'Under RH, every subpower cutoff P(Y) → ∞ with log P = o(log Y) gives all fixed Gaussian moments of standardized W_P. At P = Y^θ with 0 < θ < 1/2, weak Gaussian convergence holds, and moments through 2k converge when kθ < 1/2.','conditional_extended_scalar_cutoff_limit','audits/adversarial_reviews/director_polynomial_bands_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('THM-POLYNOMIAL-PRIME-BAND-COVARIANCE','theorems/theorems.jsonl',73,'adjudicated_scoped','audits/adversarial_reviews/director_polynomial_bands_round11.md','{"id": "THM-POLYNOMIAL-PRIME-BAND-COVARIANCE", "paper_id": null, "statement": "Under RH, for 0 < a < b < 1/4, let Δ_j = b^j − a^j. The cosine band mean tends to log(b/a) − 4Δ₁ + 2Δ₃/3 and its variance tends to (1/2) log(b/a) − 4Δ₁² + 4Δ₁Δ₃ − 4Δ₃²/9. The sine mean is zero and its variance tends to (1/2) log(b/a) − (3/2)Δ₂². The mixed covariance is zero.", "hypotheses": "Fixed band Y^a < p ≤ Y^b, coefficients 1/√p, and the symmetric strict tail. Ratio and product kernels differ by 12x²y². The proof uses the exact diagonal and aggregate D² support with 2b < 1/2. Covariance test functions retain the finite-rank correction and positive lower bound.", "claim_kind": "conditional_first_second_moment_theorem", "locator": "audits/adversarial_reviews/director_polynomial_bands_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}',NULL,'Under RH, for 0 < a < b < 1/4, let Δ_j = b^j − a^j. The cosine band mean tends to log(b/a) − 4Δ₁ + 2Δ₃/3 and its variance tends to (1/2) log(b/a) − 4Δ₁² + 4Δ₁Δ₃ − 4Δ₃²/9. The sine mean is zero and its variance tends to (1/2) log(b/a) − (3/2)Δ₂². The mixed covariance is zero.','conditional_first_second_moment_theorem','audits/adversarial_reviews/director_polynomial_bands_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('THM-POLYNOMIAL-PRIME-BAND-NONGAUSSIAN','theorems/theorems.jsonl',74,'adjudicated_scoped','audits/adversarial_reviews/director_polynomial_bands_round11.md','{"id": "THM-POLYNOMIAL-PRIME-BAND-NONGAUSSIAN", "paper_id": null, "statement": "Under RH, for 0 < a < b < 1/6, the centered cosine band third moment tends to −8Δ₁³ + 24Δ₁²Δ₃ − 8Δ₁Δ₃² + 16Δ₃³/27 < 0. For [a,b] = [1/20, 1/10], the value is −818904257/864000000000. No centered Gaussian weak subsequence is possible.", "hypotheses": "Aggregate D³ support requires 3b < 1/2. The repeated-prime term (3/2)H times the mean cancels the corresponding second-moment diagonal. Uniform fourth moments from |Re D|⁴ ≤ |D²|² give uniform integrability of the cubes. The full limiting band law remains unproved.", "claim_kind": "conditional_non_gaussian_obstruction", "locator": "audits/adversarial_reviews/director_polynomial_bands_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}',NULL,'Under RH, for 0 < a < b < 1/6, the centered cosine band third moment tends to −8Δ₁³ + 24Δ₁²Δ₃ − 8Δ₁Δ₃² + 16Δ₃³/27 < 0. For [a,b] = [1/20, 1/10], the value is −818904257/864000000000. No centered Gaussian weak subsequence is possible.','conditional_non_gaussian_obstruction','audits/adversarial_reviews/director_polynomial_bands_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('THM-ROOTED-CUE-PRIME-BAND-MOMENT-MATCH','theorems/theorems.jsonl',75,'adjudicated_scoped','audits/adversarial_reviews/director_polynomial_bands_round11.md','{"id": "THM-ROOTED-CUE-PRIME-BAND-MOMENT-MATCH", "paper_id": null, "statement": "Globally derivative-square tilted rooted CUE has the same limiting cosine and sine means and covariance as the arithmetic band under RH, and the same centered cosine third moment for b < 1/6. Its projection is onto polynomials of degrees 0 through N with the rank-two span of constant and linear coefficient vectors removed.", "hypotheses": "Uses the HKO joint Haar matrix and root-label tilt, includes the selected root, and takes the negative Fourier band observable with weights 1/k. The correspondence is k/N ↔ log p/log Y. The random matrix statements are unconditional and the arithmetic comparison assumes RH. The match covers the band means, covariance, and cosine cubic. A full joint third-moment tensor and law transfer remain outside its scope.", "claim_kind": "exact_cross_framework_moment_match", "locator": "audits/adversarial_reviews/director_polynomial_bands_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}',NULL,'Globally derivative-square tilted rooted CUE has the same limiting cosine and sine means and covariance as the arithmetic band under RH, and the same centered cosine third moment for b < 1/6. Its projection is onto polynomials of degrees 0 through N with the rank-two span of constant and linear coefficient vectors removed.','exact_cross_framework_moment_match','audits/adversarial_reviews/director_polynomial_bands_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('THM-SHARP-AGGREGATE-CONTINUOUS-J','theorems/theorems.jsonl',76,'adjudicated_scoped','audits/adversarial_reviews/director_polynomial_bands_round11.md','{"id": "THM-SHARP-AGGREGATE-CONTINUOUS-J", "paper_id": null, "statement": "The sharp shifted continuous moment with a fixed polynomial has uniform error O_ε(T^ε[y√T + √y T^(3/4)]) for bounded coefficient families with y ≤ T^δ and fixed δ < 1/2. It holds for |α|, |β| ≤ c/log T with fixed small c, includes the weights 1 and log(t/(2π)), and treats the χ′/χ correction separately. It is unconditional.", "hypotheses": "The direct product approximate functional equation uses aggregated integer frequency gaps, a Mellin diagonal shift of −1/4, sharp endpoints, low heights, and holomorphic extension across coinciding shifts. The proof avoids applying Pratt–Robles smoothing outside its stated range.", "claim_kind": "independent_sharp_interface_reconstruction", "locator": "audits/adversarial_reviews/director_polynomial_bands_round11.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round11_claims.jsonl"}',NULL,'The sharp shifted continuous moment with a fixed polynomial has uniform error O_ε(T^ε[y√T + √y T^(3/4)]) for bounded coefficient families with y ≤ T^δ and fixed δ < 1/2. It holds for |α|, |β| ≤ c/log T with fixed small c, includes the weights 1 and log(t/(2π)), and treats the χ′/χ correction separately. It is unconditional.','independent_sharp_interface_reconstruction','audits/adversarial_reviews/director_polynomial_bands_round11.md','theorems/director_round11_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-LI97-DEDEKIND-NORMALIZATION','theorems/theorems.jsonl',77,'adjudicated_exact_versioned_local_correction','audits/adversarial_reviews/director_li_whole_round12.md','{"id": "OBS-LI97-DEDEKIND-NORMALIZATION", "paper_id": "PAPER-E008", "locator": "audits/adversarial_reviews/director_li_whole_round12.md", "status": "adjudicated_exact_versioned_local_correction", "novelty_claim": false, "statement": "For the literal kernel, product differential and G2=(2π)^(1−s)Γ(s) of Li 1997, equation (3.4) needs multiplier (2π)^r2/c_k rather than 1/c_k; (3.7) inherits the same positive factor. Both main criteria survive.", "hypotheses": "Pinned 1997 journal-typeset mirror pp. 328–331. Ordinary product logarithmic measure as printed; exact Q(i) Jacobi-theta witness gives true multiplier 4 rather than 2/π.", "provenance_file": "theorems/director_round12_claims.jsonl"}','PAPER-E008','For the literal kernel, product differential and G2=(2π)^(1−s)Γ(s) of Li 1997, equation (3.4) needs multiplier (2π)^r2/c_k rather than 1/c_k; (3.7) inherits the same positive factor. Both main criteria survive.',NULL,'audits/adversarial_reviews/director_li_whole_round12.md','theorems/director_round12_claims.jsonl');
INSERT INTO "claims" VALUES('THM-FINITE-PHASE-LOWER','theorems/theorems.jsonl',78,'adjudicated_scoped_unconditional','audits/adversarial_reviews/director_finite_lower_round8.md §§1–2','{"id": "THM-FINITE-PHASE-LOWER", "paper_id": null, "claim_kind": "unconditional_fixed_finite_zero_certificate", "statement": "For any fixed finite set R of genuine critical-line zeta zeros, using all multiplicity jets, there is an explicitly computable C_R with (logN)Delta_N² >= sum_R m_rho²/|rho|²-C_R/logN for logN>=1. More generally every exact cutoff-phase trial vector yields Delta_N²>=2Re(a*b)-a*Ga without an invertibility assumption.", "hypotheses": "True certified zero labels, derivative indices below actual multiplicity, fixed set and certified separations/phase derivatives. No RH, no uniform growth of C_R. Ordinary complex coefficients, full Cauchy norm.", "locator": "audits/adversarial_reviews/director_finite_lower_round8.md §§1–2", "status": "adjudicated_scoped_unconditional", "novelty_claim": false, "provenance_file": "theorems/director_round8_claims.jsonl"}',NULL,'For any fixed finite set R of genuine critical-line zeta zeros, using all multiplicity jets, there is an explicitly computable C_R with (logN)Delta_N² >= sum_R m_rho²/|rho|²-C_R/logN for logN>=1. More generally every exact cutoff-phase trial vector yields Delta_N²>=2Re(a*b)-a*Ga without an invertibility assumption.','unconditional_fixed_finite_zero_certificate','audits/adversarial_reviews/director_finite_lower_round8.md §§1–2','theorems/director_round8_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-ZETA-FINITE-LOWER','theorems/theorems.jsonl',79,'adjudicated_scoped_unconditional_interval_certificate','audits/adversarial_reviews/director_finite_lower_round8.md §2; experiments/code/prefix_formula62_effective_lower_example.py','{"id": "CERT-ZETA-FINITE-LOWER", "paper_id": null, "claim_kind": "unconditional_validated_finite_zero_bound", "statement": "For every integer N with logN>=10, (logN)Delta_N² >= 1/112²-1/(4000logN), using one certified critical-line zero near ordinate111.029535543169674524656. Also valid for anchored d_N.", "hypotheses": "Exact norm as THM-FINITE-PHASE-LOWER; certified root and phase derivative ball, analytic local-series remainders. No RH.", "locator": "audits/adversarial_reviews/director_finite_lower_round8.md §2; experiments/code/prefix_formula62_effective_lower_example.py", "status": "adjudicated_scoped_unconditional_interval_certificate", "novelty_claim": false, "provenance_file": "theorems/director_round8_claims.jsonl"}',NULL,'For every integer N with logN>=10, (logN)Delta_N² >= 1/112²-1/(4000logN), using one certified critical-line zero near ordinate111.029535543169674524656. Also valid for anchored d_N.','unconditional_validated_finite_zero_bound','audits/adversarial_reviews/director_finite_lower_round8.md §2; experiments/code/prefix_formula62_effective_lower_example.py','theorems/director_round8_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-CHI4-FINITE-LOWER','theorems/theorems.jsonl',80,'adjudicated_scoped_unconditional_interval_certificate','audits/adversarial_reviews/director_finite_lower_round8.md §2; scripts/chi4_phase_certificate_skeptic62.py','{"id": "CERT-CHI4-FINITE-LOWER", "paper_id": null, "claim_kind": "unconditional_validated_finite_cutoff_bounds", "statement": "For chi4 ordinary optimized squared Cauchy-norm distances at N=10,100,1000,1000000, unconditional lower bounds are respectively 0.01463,0.00903,0.00665,0.00362.", "hypotheses": "Two conjugate actual critical zeros, zeroth jet at each; IVT interval[6.02094890469,6.02094890471]; 192-bit balls, analytic factorial tails, positive Gram determinant. No GRH or simplicity assumption.", "locator": "audits/adversarial_reviews/director_finite_lower_round8.md §2; scripts/chi4_phase_certificate_skeptic62.py", "status": "adjudicated_scoped_unconditional_interval_certificate", "novelty_claim": false, "provenance_file": "theorems/director_round8_claims.jsonl"}',NULL,'For chi4 ordinary optimized squared Cauchy-norm distances at N=10,100,1000,1000000, unconditional lower bounds are respectively 0.01463,0.00903,0.00665,0.00362.','unconditional_validated_finite_cutoff_bounds','audits/adversarial_reviews/director_finite_lower_round8.md §2; scripts/chi4_phase_certificate_skeptic62.py','theorems/director_round8_claims.jsonl');
INSERT INTO "claims" VALUES('THM-RST048-PREFIX','theorems/theorems.jsonl',81,'adjudicated_scoped_RH_conditional_source_theorem','audits/adversarial_reviews/director_rst048_prefix_round8.md; RST048v2 Theorem5,79–89; RST047v1 §§2–6','{"id": "THM-RST048-PREFIX", "paper_id": "PAPER-RST048", "claim_kind": "source_theorem_independently_reconstructed", "statement": "Under RH, for each fixed 0<b<1, constrain input coefficients a_n=mu(n)(1-logn/logN) for n<=N^b and leave the suffix arbitrary complex. Both unrestricted ||1-zeta A||_* and anchored ||1-zeta(A-A(1))||_* optimized squared costs times logN tend to C(b)=sum_distinctrho c_mrho(b)/|rho|², with c_m=m²b+v*M^-1v and M_ij=(1-b^(i+j+1))/(i+j+1),v_j=-delta_j0+m b^(j+1)/(j+1).", "hypotheses": "RH; fixed b before N limit; prefix imposed on input A, not on actual anchored polynomial after subtraction; source main adaptive proof and its recorded fixed-Laurent qualification. No moving-b uniformity or Theorem6 adoption.", "locator": "audits/adversarial_reviews/director_rst048_prefix_round8.md; RST048v2 Theorem5,79–89; RST047v1 §§2–6", "status": "adjudicated_scoped_RH_conditional_source_theorem", "novelty_claim": false, "provenance_file": "theorems/director_round8_claims.jsonl"}','PAPER-RST048','Under RH, for each fixed 0<b<1, constrain input coefficients a_n=mu(n)(1-logn/logN) for n<=N^b and leave the suffix arbitrary complex. Both unrestricted ||1-zeta A||_* and anchored ||1-zeta(A-A(1))||_* optimized squared costs times logN tend to C(b)=sum_distinctrho c_mrho(b)/|rho|², with c_m=m²b+v*M^-1v and M_ij=(1-b^(i+j+1))/(i+j+1),v_j=-delta_j0+m b^(j+1)/(j+1).','source_theorem_independently_reconstructed','audits/adversarial_reviews/director_rst048_prefix_round8.md; RST048v2 Theorem5,79–89; RST047v1 §§2–6','theorems/director_round8_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-RST047-COMPACT-JETS','theorems/theorems.jsonl',82,'adjudicated_scoped_source_lemma','audits/adversarial_reviews/director_rst048_prefix_round8.md §1; PAPER-RST047 §§2–6','{"id": "LEM-RST047-COMPACT-JETS", "paper_id": "PAPER-RST047", "claim_kind": "source_dependency_independently_reconstructed", "statement": "The gamma-tail compact Mellin tests with k=ceil(logN), A=N,R=ceil(4NlogN) transfer every fixed critical-line zero jet to arbitrary bounded-residual integer polynomials. Their normalized Gram tends to the confluent Hilbert blocks, with no separate suffix-coefficient bound.", "hypotheses": "Fixed zero set and derivative indices below multiplicity; finite Möbius coefficient bound and exact Fourier cancellation. Constants fixed by discs; no growing-set claim.", "locator": "audits/adversarial_reviews/director_rst048_prefix_round8.md §1; PAPER-RST047 §§2–6", "status": "adjudicated_scoped_source_lemma", "novelty_claim": false, "provenance_file": "theorems/director_round8_claims.jsonl"}','PAPER-RST047','The gamma-tail compact Mellin tests with k=ceil(logN), A=N,R=ceil(4NlogN) transfer every fixed critical-line zero jet to arbitrary bounded-residual integer polynomials. Their normalized Gram tends to the confluent Hilbert blocks, with no separate suffix-coefficient bound.','source_dependency_independently_reconstructed','audits/adversarial_reviews/director_rst048_prefix_round8.md §1; PAPER-RST047 §§2–6','theorems/director_round8_claims.jsonl');
INSERT INTO "claims" VALUES('THM-JUMP-TRANSPORT-EXACT','theorems/theorems.jsonl',83,'adjudicated_scoped_unconditional','audits/adversarial_reviews/director_manzur_noor_round8.md first four paragraphs; witness62_manzur_noor_step_bridge.md','{"id": "THM-JUMP-TRANSPORT-EXACT", "paper_id": "PAPER-MN2026-VERTICAL", "claim_kind": "source_operator_reconstruction_with_sharp_norm", "statement": "The exact unitary map (Ba)_n=sum_(j<n)a_j-n a_n sends disk Hardy space onto weighted unit-step S. Source T_tau becomes jump phase J_tau, M J_tau f(s)=(s-i tau)Mf(s-i tau)/s and ||J_tau||=sqrt(1+tau²)+|tau|.", "hypotheses": "S subset L²([1,infinity),dx/x²), all real tau; critical Mellin Hardy measure dt/(2pi). Sharp norm uses ambient norm and integer dilation/step approximation.", "locator": "audits/adversarial_reviews/director_manzur_noor_round8.md first four paragraphs; witness62_manzur_noor_step_bridge.md", "status": "adjudicated_scoped_unconditional", "novelty_claim": false, "provenance_file": "theorems/director_round8_claims.jsonl"}','PAPER-MN2026-VERTICAL','The exact unitary map (Ba)_n=sum_(j<n)a_j-n a_n sends disk Hardy space onto weighted unit-step S. Source T_tau becomes jump phase J_tau, M J_tau f(s)=(s-i tau)Mf(s-i tau)/s and ||J_tau||=sqrt(1+tau²)+|tau|.','source_operator_reconstruction_with_sharp_norm','audits/adversarial_reviews/director_manzur_noor_round8.md first four paragraphs; witness62_manzur_noor_step_bridge.md','theorems/director_round8_claims.jsonl');
INSERT INTO "claims" VALUES('THM-CHARACTER-RESONANT-MEMBERSHIP','theorems/theorems.jsonl',84,'adjudicated_scoped_equivalence_with_declared_classical_inputs','audits/adversarial_reviews/director_manzur_noor_round8.md; audits/manzur_noor_anchor_prefix_skeptic62.md; witness62_manzur_noor_step_bridge.md','{"id": "THM-CHARACTER-RESONANT-MEMBERSHIP", "paper_id": null, "claim_kind": "derived_fixed_character_operator_criterion", "statement": "For fixed nonprincipal chi, W_chi closed span of g_k=S_chi(x/k)-S_chi(x)/k in unit-step S, dist(J_tau g_k,W_chi)>=|L(1-i tau,chi)| |k^(i tau)-1|/k unconditionally. Under unanchored density W_chi=ker M(.,1) and equality holds. For every fixed k>=2,tau nonzero with k^(i tau)=1, membership J_tau g_k in W_chi is equivalent to fixed-chi GRH. No nonzero tau leaves all W_chi invariant.", "hypotheses": "Ordinary integer dilations, fixed modulus; classical nonvanishing Re1 and fixed-strip o(T) density input from Jutila1972 quoted Montgomery bound. Forward density from separately reconstructed fixed-character GRH theorem. Complex-chi functional symmetry and imprimitive Euler Re0 zeros retained.", "locator": "audits/adversarial_reviews/director_manzur_noor_round8.md; audits/manzur_noor_anchor_prefix_skeptic62.md; witness62_manzur_noor_step_bridge.md", "status": "adjudicated_scoped_equivalence_with_declared_classical_inputs", "novelty_claim": false, "provenance_file": "theorems/director_round8_claims.jsonl"}',NULL,'For fixed nonprincipal chi, W_chi closed span of g_k=S_chi(x/k)-S_chi(x)/k in unit-step S, dist(J_tau g_k,W_chi)>=|L(1-i tau,chi)| |k^(i tau)-1|/k unconditionally. Under unanchored density W_chi=ker M(.,1) and equality holds. For every fixed k>=2,tau nonzero with k^(i tau)=1, membership J_tau g_k in W_chi is equivalent to fixed-chi GRH. No nonzero tau leaves all W_chi invariant.','derived_fixed_character_operator_criterion','audits/adversarial_reviews/director_manzur_noor_round8.md; audits/manzur_noor_anchor_prefix_skeptic62.md; witness62_manzur_noor_step_bridge.md','theorems/director_round8_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-JUMP-FINITE-LENGTH-BARRIER','theorems/theorems.jsonl',85,'adjudicated_scoped_negative_control','audits/adversarial_reviews/director_manzur_noor_round8.md final paragraphs; audits/manzur_noor_anchor_prefix_skeptic62.md','{"id": "OBS-JUMP-FINITE-LENGTH-BARRIER", "paper_id": null, "claim_kind": "arithmetic_and_abstract_inference_obstruction", "statement": "For nonzero tau, the jump-transported zeta generator rho_k has infinitely many formal nonzero prime floor coefficients -(p^(i tau)-1)/k, so belongs to no finite ordinary length span. A separate l² model has perfect unconstrained approximation and norm1 transport but constrained prefix limit b/(1-b), precluding a generic subreciprocal-rate inference from density or membership.", "hypotheses": "k>=2 fixed, tau nonzero. The abstract prefix countermodel is not the arithmetic Mobius sequence.", "locator": "audits/adversarial_reviews/director_manzur_noor_round8.md final paragraphs; audits/manzur_noor_anchor_prefix_skeptic62.md", "status": "adjudicated_scoped_negative_control", "novelty_claim": false, "provenance_file": "theorems/director_round8_claims.jsonl"}',NULL,'For nonzero tau, the jump-transported zeta generator rho_k has infinitely many formal nonzero prime floor coefficients -(p^(i tau)-1)/k, so belongs to no finite ordinary length span. A separate l² model has perfect unconstrained approximation and norm1 transport but constrained prefix limit b/(1-b), precluding a generic subreciprocal-rate inference from density or membership.','arithmetic_and_abstract_inference_obstruction','audits/adversarial_reviews/director_manzur_noor_round8.md final paragraphs; audits/manzur_noor_anchor_prefix_skeptic62.md','theorems/director_round8_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-SUZUKI-SIGNED-CORRECTION','theorems/theorems.jsonl',86,'adjudicated_scoped_previously_author_corrected','audits/adversarial_reviews/director_suzuki_correction_round8.md; author erratum items1–4','{"id": "OBS-SUZUKI-SIGNED-CORRECTION", "paper_id": "PAPER-EC62-OP2-SUZMERGED", "claim_kind": "existing_author_erratum_independently_reconstructed", "statement": "The author-corrected conjugate negative-time extension and all-real zero series restore the bilateral screw-kernel/norm formulas under RH; the original positive-time norm criterion is unaffected. The merged prefactor and inequality constants require the separate erratum changes.", "hypotheses": "Pinned standalonev3 and merged/journal source conventions distinguished; actual author erratum SHA9c28b278874eb8242165ac3f8b3ab9ae44365cfba6958a4869e462eb057a1382. Model-space basis and density remain RH-dependent.", "locator": "audits/adversarial_reviews/director_suzuki_correction_round8.md; author erratum items1–4", "status": "adjudicated_scoped_previously_author_corrected", "novelty_claim": false, "provenance_file": "theorems/director_round8_claims.jsonl"}','PAPER-EC62-OP2-SUZMERGED','The author-corrected conjugate negative-time extension and all-real zero series restore the bilateral screw-kernel/norm formulas under RH; the original positive-time norm criterion is unaffected. The merged prefactor and inequality constants require the separate erratum changes.','existing_author_erratum_independently_reconstructed','audits/adversarial_reviews/director_suzuki_correction_round8.md; author erratum items1–4','theorems/director_round8_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-PINTZ-FIXED-SLAB','theorems/theorems.jsonl',87,'adjudicated_scoped_source_dependent','audits/adversarial_reviews/director_density_inverse_maps_round8.md §1; prefix_formula62_pintz_bgstb_slab.md','{"id": "OBS-PINTZ-FIXED-SLAB", "paper_id": "PAPER-ANALYTIC62-013", "claim_kind": "source_dependent_weighted_density_corollary", "statement": "For fixed 0<d<=1/16, I=[7/8+d,1-d], Delta_d=min_(eta in[d,1/8-d])(2eta-eta/(1-4eta))>0, the multiplicity weighted sum H_I=sum_(0<gamma<=T,beta in I)T^(2beta-1)/(1+log²T(beta-.5)²) is O_(d,epsilon)(T^(1-Delta_d+epsilon)/log²T). BGSTB far pairs charged to right maximizers in I cost O(logT H_I); the remaining region is not controlled by this assertion.", "hypotheses": "Pintz2310.04544v1 Cor4 only on proof-valid eta<1/4; fixed finite threshold mesh; fixed d. At d1/16 singleton, greater d empty.", "locator": "audits/adversarial_reviews/director_density_inverse_maps_round8.md §1; prefix_formula62_pintz_bgstb_slab.md", "status": "adjudicated_scoped_source_dependent", "novelty_claim": false, "provenance_file": "theorems/director_round8_claims.jsonl"}','PAPER-ANALYTIC62-013','For fixed 0<d<=1/16, I=[7/8+d,1-d], Delta_d=min_(eta in[d,1/8-d])(2eta-eta/(1-4eta))>0, the multiplicity weighted sum H_I=sum_(0<gamma<=T,beta in I)T^(2beta-1)/(1+log²T(beta-.5)²) is O_(d,epsilon)(T^(1-Delta_d+epsilon)/log²T). BGSTB far pairs charged to right maximizers in I cost O(logT H_I); the remaining region is not controlled by this assertion.','source_dependent_weighted_density_corollary','audits/adversarial_reviews/director_density_inverse_maps_round8.md §1; prefix_formula62_pintz_bgstb_slab.md','theorems/director_round8_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-DONG-INVERSE-PHASE-INTERFACE','theorems/theorems.jsonl',88,'adjudicated_scoped_source_dependent','audits/adversarial_reviews/director_density_inverse_maps_round8.md §2; witness62_dong_inverse_phase.md','{"id": "OBS-DONG-INVERSE-PHASE-INTERFACE", "paper_id": "PAPER-ANALYTIC62-019", "claim_kind": "source_dependent_hypothesis_map_and_obstruction", "statement": "A lower moment of the exact unweighted sum sum n^(it) can supply the source pointwise zero-forcing trigger. Its disk gives a zero-containing region, not a critical-line phase jet. A separate VK width excludes triggers when logx>=C(logT)^(250/291)(loglogT)^(50/291) up to logx<=logT/2. The source upper bound at x=sqrtT disproves a trigger converse at every permitted length.", "hypotheses": "Exact Theorem1.1 ranges and existential c,T0, nonempty L interval, common twist center; finite effective onset not supplied. Open radius<=.5 excludes critical line. No derivative-free line-zero certificate.", "locator": "audits/adversarial_reviews/director_density_inverse_maps_round8.md §2; witness62_dong_inverse_phase.md", "status": "adjudicated_scoped_source_dependent", "novelty_claim": false, "provenance_file": "theorems/director_round8_claims.jsonl"}','PAPER-ANALYTIC62-019','A lower moment of the exact unweighted sum sum n^(it) can supply the source pointwise zero-forcing trigger. Its disk gives a zero-containing region, not a critical-line phase jet. A separate VK width excludes triggers when logx>=C(logT)^(250/291)(loglogT)^(50/291) up to logx<=logT/2. The source upper bound at x=sqrtT disproves a trigger converse at every permitted length.','source_dependent_hypothesis_map_and_obstruction','audits/adversarial_reviews/director_density_inverse_maps_round8.md §2; witness62_dong_inverse_phase.md','theorems/director_round8_claims.jsonl');
INSERT INTO "claims" VALUES('THM-LATTICE-FINITE-CERTIFICATES','theorems/theorems.jsonl',89,'adjudicated_scoped','audits/adversarial_reviews/director_moment_certificates_round9.md','{"id": "THM-LATTICE-FINITE-CERTIFICATES", "paper_id": null, "claim_kind": "exact_positive_measure_certificates", "statement": "For mu_m=m(m−1), a_m=mu_m²W_m>=0 and nu=sum a_m delta_mu_m, R_M=int product_(j=2)^M(x−mu_j)dnu gives sum_(m>M)a_m<=R_M/D_M, D_M=(M−1)!(2M)!/(M+1)!. Zero residual forces support<=M. Signed Lagrange mass enclosures and nearest-lattice quadratic witnesses have exact rational constants.", "hypotheses": "Finite supplied moments of a feasible positive lattice measure; all derivative data are true limiting coefficients, not finite-N staircases. M=1 uses the empty product.", "locator": "audits/adversarial_reviews/director_moment_certificates_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'For mu_m=m(m−1), a_m=mu_m²W_m>=0 and nu=sum a_m delta_mu_m, R_M=int product_(j=2)^M(x−mu_j)dnu gives sum_(m>M)a_m<=R_M/D_M, D_M=(M−1)!(2M)!/(M+1)!. Zero residual forces support<=M. Signed Lagrange mass enclosures and nearest-lattice quadratic witnesses have exact rational constants.','exact_positive_measure_certificates','audits/adversarial_reviews/director_moment_certificates_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-LATTICE-AUGMENTED-FEASIBILITY','theorems/theorems.jsonl',90,'adjudicated_scoped','audits/adversarial_reviews/director_moment_certificates_round9.md','{"id": "THM-LATTICE-AUGMENTED-FEASIBILITY", "paper_id": null, "claim_kind": "exact_augmented_moment_classification", "statement": "For y0>0 and n>=1 the normalized data (moments through n, C0/y0) are feasible iff they lie in conv{(x,...,x^n,g(x)):x=m(m−1),m>=2} plus the nonnegative vertical ray; g(x)=4/(sqrt(1+4x)−1)^2. Feasible boundary data have a unique finite profile with <=n+1 support points; interior profiles can occupy every lattice point.", "hypotheses": "C0 constraint includes W1=C0−int g dnu>=0; finite exact moment data, true algebraic convex hull, not its closure.", "locator": "audits/adversarial_reviews/director_moment_certificates_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'For y0>0 and n>=1 the normalized data (moments through n, C0/y0) are feasible iff they lie in conv{(x,...,x^n,g(x)):x=m(m−1),m>=2} plus the nonnegative vertical ray; g(x)=4/(sqrt(1+4x)−1)^2. Feasible boundary data have a unique finite profile with <=n+1 support points; interior profiles can occupy every lattice point.','exact_augmented_moment_classification','audits/adversarial_reviews/director_moment_certificates_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-LATTICE-MOMENT-ESCAPE','theorems/theorems.jsonl',91,'adjudicated_scoped','audits/adversarial_reviews/director_moment_certificates_round9.md','{"id": "OBS-LATTICE-MOMENT-ESCAPE", "paper_id": null, "claim_kind": "exact_nonclosedness_countermodel", "statement": "The data (y0,y1,y2,C0)=(1,6,37,1/4) are infeasible but lie in the closure of feasible data. For x=m(m−1), m>=4, weights at2,6,x given by 1/[4(x−2)],1−w2−wx,1/[(x−6)(x−2)] preserve the three pure moments while g-cost decreases to1/4 and remote second moment tends to1.", "hypotheses": "Synthetic positive lattice measures; exact Jensen obstruction; no counterexample to an arithmetic RH prefix formula.", "locator": "audits/adversarial_reviews/director_moment_certificates_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'The data (y0,y1,y2,C0)=(1,6,37,1/4) are infeasible but lie in the closure of feasible data. For x=m(m−1), m>=4, weights at2,6,x given by 1/[4(x−2)],1−w2−wx,1/[(x−6)(x−2)] preserve the three pure moments while g-cost decreases to1/4 and remote second moment tends to1.','exact_nonclosedness_countermodel','audits/adversarial_reviews/director_moment_certificates_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-LATTICE-RATIONAL-CLI','theorems/theorems.jsonl',92,'adjudicated_scoped','audits/adversarial_reviews/director_moment_certificates_round9.md','{"id": "CERT-LATTICE-RATIONAL-CLI", "paper_id": null, "claim_kind": "reviewed_exact_computation", "statement": "The Fraction-based CLI produces rigorous rational/interval tail and atom enclosures conditional on a feasible positive profile, and explicitly returns feasibility_checked:false. Independent controls include 540 feasible profiles, malformed input, infeasibility-scope cases and exact repeated examples.", "hypotheses": "Experiments/code/prefix_moment63_certificates.py and its documented schema; no full moment-feasibility decision asserted.", "locator": "audits/adversarial_reviews/director_moment_certificates_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'The Fraction-based CLI produces rigorous rational/interval tail and atom enclosures conditional on a feasible positive profile, and explicitly returns feasibility_checked:false. Independent controls include 540 feasible profiles, malformed input, infeasibility-scope cases and exact repeated examples.','reviewed_exact_computation','audits/adversarial_reviews/director_moment_certificates_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-JUMP-GENERATOR-DOMAIN','theorems/theorems.jsonl',93,'adjudicated_scoped','audits/adversarial_reviews/director_jump_generator_round9.md','{"id": "THM-JUMP-GENERATOR-DOMAIN", "paper_id": "PAPER-MN2026-VERTICAL", "claim_kind": "closed_operator_reconstruction", "statement": "On S=ell²(1/[n(n+1)]), G=i(D−H), Db_n=log n b_n, Hb_n=sum_(r<n)log(1+1/r)b_r, with DomG={sum w_n log²n |b_n|²<infinity}; finite cells form a graph core and MGb=−i[(Mb)prime+(Mb)/s].", "hypotheses": "Exact jump-phase group, strong derivative in S; H bounded with norm<=2.", "locator": "audits/adversarial_reviews/director_jump_generator_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}','PAPER-MN2026-VERTICAL','On S=ell²(1/[n(n+1)]), G=i(D−H), Db_n=log n b_n, Hb_n=sum_(r<n)log(1+1/r)b_r, with DomG={sum w_n log²n |b_n|²<infinity}; finite cells form a graph core and MGb=−i[(Mb)prime+(Mb)/s].','closed_operator_reconstruction','audits/adversarial_reviews/director_jump_generator_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-JUMP-RESOLVENT-SPECTRUM','theorems/theorems.jsonl',94,'adjudicated_scoped','audits/adversarial_reviews/director_jump_generator_round9.md','{"id": "THM-JUMP-RESOLVENT-SPECTRUM", "paper_id": null, "claim_kind": "operator_spectral_reconstruction", "statement": "For q_n=(lambda−i log n)^−1, (lambda−G)^−1=diag q−iH diag(q_n q_(n+1)); it is compact, spectrum={i log n}, each algebraically simple. Projection P_n b=(b_n−b_(n−1))1_[n,infinity) has norm sqrt(2n); resolvent singular values are asymptotic1/log j and belong to no finite Schatten class.", "hypotheses": "The same weighted S and closed domain; lambda outside the displayed discrete set. This spectrum is indexed by integers, not zeta zeros.", "locator": "audits/adversarial_reviews/director_jump_generator_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'For q_n=(lambda−i log n)^−1, (lambda−G)^−1=diag q−iH diag(q_n q_(n+1)); it is compact, spectrum={i log n}, each algebraically simple. Projection P_n b=(b_n−b_(n−1))1_[n,infinity) has norm sqrt(2n); resolvent singular values are asymptotic1/log j and belong to no finite Schatten class.','operator_spectral_reconstruction','audits/adversarial_reviews/director_jump_generator_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-JUMP-INVARIANT-METRICS','theorems/theorems.jsonl',95,'adjudicated_scoped','audits/adversarial_reviews/director_jump_generator_round9.md','{"id": "THM-JUMP-INVARIANT-METRICS", "paper_id": null, "claim_kind": "positive_metric_classification", "statement": "Every bounded positive invariant form is sum d_n|b_n−b_(n−1)|² with d_n>=0 and sup n²d_n finite. It is injective iff every d_n>0 and is never coercive; no bounded invertible metric unitarizes the group.", "hypotheses": "Invariance under all real times on the original S; a weaker completion changes topology.", "locator": "audits/adversarial_reviews/director_jump_generator_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Every bounded positive invariant form is sum d_n|b_n−b_(n−1)|² with d_n>=0 and sup n²d_n finite. It is injective iff every d_n>0 and is never coercive; no bounded invertible metric unitarizes the group.','positive_metric_classification','audits/adversarial_reviews/director_jump_generator_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-JUMP-FLOW-SUBSPACES','theorems/theorems.jsonl',96,'adjudicated_scoped','audits/adversarial_reviews/director_jump_generator_round9.md','{"id": "THM-JUMP-FLOW-SUBSPACES", "paper_id": null, "claim_kind": "invariant_subspace_classification", "statement": "Every closed forward-flow invariant subspace is exactly a closed span of selected integer eigenvectors 1_[n,infinity). Every vector with all jumps nonzero is forward-orbit cyclic.", "hypotheses": "All times t>=0, Laplace resolvent analyticity and convergent subsequence of natural spectral sums; a single fixed-time criterion is separate.", "locator": "audits/adversarial_reviews/director_jump_generator_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Every closed forward-flow invariant subspace is exactly a closed span of selected integer eigenvectors 1_[n,infinity). Every vector with all jumps nonzero is forward-orbit cyclic.','invariant_subspace_classification','audits/adversarial_reviews/director_jump_generator_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-JUMP-EXACT-ANTECEDENT','theorems/theorems.jsonl',97,'adjudicated_scoped','audits/adversarial_reviews/director_jump_generator_round9.md','{"id": "OBS-JUMP-EXACT-ANTECEDENT", "paper_id": "PAPER-SM2017-LOGGROUP", "claim_kind": "exact_primary_source_intertwining", "statement": "The source jump group is exactly the time-reversed adjoint of the logarithmic multiplier group in Sklyar–Marchenko, under the unitary first-difference realization. Prior resolvent and nonbasis results apply to the same operator family.", "hypotheses": "Pinned arXiv1405.2731v4 and current source conventions; old version-only clauses are distinguished.", "locator": "audits/adversarial_reviews/director_jump_generator_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}','PAPER-SM2017-LOGGROUP','The source jump group is exactly the time-reversed adjoint of the logarithmic multiplier group in Sklyar–Marchenko, under the unitary first-difference realization. Prior resolvent and nonbasis results apply to the same operator family.','exact_primary_source_intertwining','audits/adversarial_reviews/director_jump_generator_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-SHIFT-RUNLENGTH-BASIS','theorems/theorems.jsonl',98,'adjudicated_scoped','audits/adversarial_reviews/director_shift_difference_subsequences_round9.md','{"id": "THM-SHIFT-RUNLENGTH-BASIS", "paper_id": null, "claim_kind": "replacement_basis_theorem", "statement": "For k>=1, phi_n=(I−T)^k e_n from a Riesz basis with associated shift, a selected sequence is Riesz iff its consecutive index runs are uniformly bounded. For run bound r, squared bounds are A[2−2cos(pi/(r+1))]^k and B4^k. Unbounded runs preclude a Schauder basis in every ordering.", "hypotheses": "Ordinary one-sided shift and fixed k; explicit normalized polynomial witnesses establish the negative direction.", "locator": "audits/adversarial_reviews/director_shift_difference_subsequences_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'For k>=1, phi_n=(I−T)^k e_n from a Riesz basis with associated shift, a selected sequence is Riesz iff its consecutive index runs are uniformly bounded. For run bound r, squared bounds are A[2−2cos(pi/(r+1))]^k and B4^k. Unbounded runs preclude a Schauder basis in every ordering.','replacement_basis_theorem','audits/adversarial_reviews/director_shift_difference_subsequences_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-SKLYAR-SUPERSEDED-CLAUSES','theorems/theorems.jsonl',99,'adjudicated_scoped','audits/adversarial_reviews/director_shift_difference_subsequences_round9.md','{"id": "OBS-SKLYAR-SUPERSEDED-CLAUSES", "paper_id": "PAPER-SM2017-LOGGROUP", "claim_kind": "historical_version_counterexample_and_correction", "statement": "The v1 domain restriction and v1–v3 blanket no-subsequence-basis clause are superseded. Sparse block-separated difference vectors give Riesz subsequences; v4 omits the latter clause. No inaccessible journal-text error is inferred.", "hypotheses": "Source versions explicitly compared; journal text unavailable in inspected routes.", "locator": "audits/adversarial_reviews/director_shift_difference_subsequences_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}','PAPER-SM2017-LOGGROUP','The v1 domain restriction and v1–v3 blanket no-subsequence-basis clause are superseded. Sparse block-separated difference vectors give Riesz subsequences; v4 omits the latter clause. No inaccessible journal-text error is inferred.','historical_version_counterexample_and_correction','audits/adversarial_reviews/director_shift_difference_subsequences_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-GENERATOR-ONE-MEMBER-RH','theorems/theorems.jsonl',100,'adjudicated_scoped','audits/adversarial_reviews/director_infinitesimal_membership_round9.md','{"id": "THM-GENERATOR-ONE-MEMBER-RH", "paper_id": null, "claim_kind": "fixed_target_equivalent_criterion", "statement": "For every fixed integer k>=2, RH iff G f_k belongs to W, where f_k=k floor(x/k)−floor x and W is the closed NB span. MGf_k=−i[ zeta(s)(k^(1−s)−1)]prime/s; a right-zero derivative jet gives an explicit positive off-RH distance.", "hypotheses": "Closed domain verified for f_k; full multiplicity jet, fixed k; forward uses classical density. Balazard holomorphy/jump-series antecedents are credited.", "locator": "audits/adversarial_reviews/director_infinitesimal_membership_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'For every fixed integer k>=2, RH iff G f_k belongs to W, where f_k=k floor(x/k)−floor x and W is the closed NB span. MGf_k=−i[ zeta(s)(k^(1−s)−1)]prime/s; a right-zero derivative jet gives an explicit positive off-RH distance.','fixed_target_equivalent_criterion','audits/adversarial_reviews/director_infinitesimal_membership_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-GENERATOR-CHARACTER-CRITERIA','theorems/theorems.jsonl',101,'adjudicated_scoped','audits/adversarial_reviews/director_infinitesimal_membership_round9.md','{"id": "THM-GENERATOR-CHARACTER-CRITERIA", "paper_id": null, "claim_kind": "fixed_character_criterion_and_anchor_obstruction", "statement": "For fixed nonprincipal chi, GRH_chi iff G S_chi is in the unrestricted dilation closure. For principal chi use anchored g_chi,k=S_chi(x/k)−S_chi(x)/k; membership Gg in its anchored span is equivalent to RH. For nonprincipal chi the same anchored Gg is never a member since its Mellin value at1 is iL(1,chi)log k/k.", "hypotheses": "Fixed character, ordinary integer dilations, classical nonvanishing at1; principal raw summatory function is outside S.", "locator": "audits/adversarial_reviews/director_infinitesimal_membership_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'For fixed nonprincipal chi, GRH_chi iff G S_chi is in the unrestricted dilation closure. For principal chi use anchored g_chi,k=S_chi(x/k)−S_chi(x)/k; membership Gg in its anchored span is equivalent to RH. For nonprincipal chi the same anchored Gg is never a member since its Mellin value at1 is iL(1,chi)log k/k.','fixed_character_criterion_and_anchor_obstruction','audits/adversarial_reviews/director_infinitesimal_membership_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-CHARACTER-EULER-SPAN-EQUALITY','theorems/theorems.jsonl',102,'adjudicated_scoped','audits/adversarial_reviews/director_infinitesimal_membership_round9.md','{"id": "THM-CHARACTER-EULER-SPAN-EQUALITY", "paper_id": null, "claim_kind": "unconditional_span_identity", "statement": "Deleting finitely many Euler factors preserves the unrestricted nonprincipal dilation span and preserves both principal/nonprincipal anchored spans unconditionally. Finite Euler dilation factors have bounded Neumann inverses; [G,U_d]=i log d U_d transfers exact generator membership.", "hypotheses": "Fixed modulus and finite factors, norm U_d=d^−1/2; no conductor-uniform assertion.", "locator": "audits/adversarial_reviews/director_infinitesimal_membership_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Deleting finitely many Euler factors preserves the unrestricted nonprincipal dilation span and preserves both principal/nonprincipal anchored spans unconditionally. Finite Euler dilation factors have bounded Neumann inverses; [G,U_d]=i log d U_d transfers exact generator membership.','unconditional_span_identity','audits/adversarial_reviews/director_infinitesimal_membership_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-RST048-FINITE-EXCEPTIONS','theorems/theorems.jsonl',103,'adjudicated_scoped','audits/adversarial_reviews/director_rst048_finite_exceptions_round9.md','{"id": "THM-RST048-FINITE-EXCEPTIONS", "paper_id": "PAPER-RST048", "claim_kind": "conditional_source_theorem_reconstruction", "statement": "Under finitely many right off-line nontrivial zeta zeros, V is exactly the joint Mellin-jet kernel in the unit-step space. With u=P_V(1/s), d_N² tends to D_infinity² and logN(d_N²−D_infinity²) tends to sum_critical_distinct m_rho²|u(rho)|². The unrestricted analogue uses u_star and the separately minimized pole scalar and has the same target-value rule.", "hypotheses": "Fixed finite exceptional configuration including multiplicities; discrete projection targets, not continuous Blaschke products; source integer quadrature and fixed Laurent repair retained. No extra factor1/|rho|².", "locator": "audits/adversarial_reviews/director_rst048_finite_exceptions_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}','PAPER-RST048','Under finitely many right off-line nontrivial zeta zeros, V is exactly the joint Mellin-jet kernel in the unit-step space. With u=P_V(1/s), d_N² tends to D_infinity² and logN(d_N²−D_infinity²) tends to sum_critical_distinct m_rho²|u(rho)|². The unrestricted analogue uses u_star and the separately minimized pole scalar and has the same target-value rule.','conditional_source_theorem_reconstruction','audits/adversarial_reviews/director_rst048_finite_exceptions_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-TAPERED-PRIME-ARRAY','theorems/theorems.jsonl',104,'adjudicated_scoped','audits/adversarial_reviews/director_tapered_prime_array_round9.md','{"id": "THM-TAPERED-PRIME-ARRAY", "paper_id": null, "claim_kind": "prescribed_array_asymptotic", "statement": "For each fixed k>=2, w_k(d)=k1_(k|d)Lambda(d/k)−Lambda(d)+k logk1_(d=k), A_N=sum_(d<=N)w_k(d)(1−logd/logN)d^−s and B_N=A_N−A_N(1). Under RH, logN||MR_k−zeta B_N/s||² tends to C_k=sum_simple_critical |zetaprime(rho)(k^(1−rho)−1)|²/|rho|². The best anchored and unrestricted ordinary polynomials have the same leading constant.", "hypotheses": "R_k,n=log[(floor(n/k)!)^k k^(k floor(n/k))/n!]; fixed k, full dt/(2pi) norm; multiple zeros contribute0; no simplicity or inverse derivative moment.", "locator": "audits/adversarial_reviews/director_tapered_prime_array_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'For each fixed k>=2, w_k(d)=k1_(k|d)Lambda(d/k)−Lambda(d)+k logk1_(d=k), A_N=sum_(d<=N)w_k(d)(1−logd/logN)d^−s and B_N=A_N−A_N(1). Under RH, logN||MR_k−zeta B_N/s||² tends to C_k=sum_simple_critical |zetaprime(rho)(k^(1−rho)−1)|²/|rho|². The best anchored and unrestricted ordinary polynomials have the same leading constant.','prescribed_array_asymptotic','audits/adversarial_reviews/director_tapered_prime_array_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-TAPERED-PRIME-ARRAY-RH-IFF','theorems/theorems.jsonl',105,'adjudicated_scoped','audits/adversarial_reviews/director_tapered_prime_array_round9.md','{"id": "THM-TAPERED-PRIME-ARRAY-RH-IFF", "paper_id": null, "claim_kind": "equivalent_criterion_with_prescribed_coefficients", "statement": "For every fixed k>=2, convergence to zero of the prescribed tapered anchored prime-array error is equivalent to RH. Fixed finite complex target combinations have the polarized quadratic limit under RH.", "hypotheses": "Forward requires RH; converse uses a fixed right-zero jet and no bound on polynomial coefficients; no target index growing with N in the leading constant statement.", "locator": "audits/adversarial_reviews/director_tapered_prime_array_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'For every fixed k>=2, convergence to zero of the prescribed tapered anchored prime-array error is equivalent to RH. Fixed finite complex target combinations have the polarized quadratic limit under RH.','equivalent_criterion_with_prescribed_coefficients','audits/adversarial_reviews/director_tapered_prime_array_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-PRIME-ARRAY-EFFECTIVE','theorems/theorems.jsonl',106,'adjudicated_scoped','audits/adversarial_reviews/director_prime_array_effective_round9.md','{"id": "THM-PRIME-ARRAY-EFFECTIVE", "paper_id": null, "claim_kind": "effective_global_conditional_bounds", "statement": "Under RH, every integer N>=3 has E_N(2)<=10^27/logN and E_N(k)<=10^44 k^6/logN for every integer k>=2.", "hypotheses": "E_N is the full squared anchored error of the explicit array. Coarse global constants, not optimized or practical thresholds; no simplicity assumption.", "locator": "audits/adversarial_reviews/director_prime_array_effective_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Under RH, every integer N>=3 has E_N(2)<=10^27/logN and E_N(k)<=10^44 k^6/logN for every integer k>=2.','effective_global_conditional_bounds','audits/adversarial_reviews/director_prime_array_effective_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('COR-PRIME-ARRAY-MOVING-INDEX','theorems/theorems.jsonl',107,'adjudicated_scoped','audits/adversarial_reviews/director_prime_array_effective_round9.md','{"id": "COR-PRIME-ARRAY-MOVING-INDEX", "paper_id": null, "claim_kind": "derived_moving_index_equivalence", "statement": "For any prescribed integer sequence k_N>=2 with k_N^6/logN tending to0, E_N(k_N) tends to0 iff RH.", "hypotheses": "Uniform effective upper and fixed off-line-zero jet lower; no joint leading-constant or inverse-recovery rate claimed.", "locator": "audits/adversarial_reviews/director_prime_array_effective_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'For any prescribed integer sequence k_N>=2 with k_N^6/logN tending to0, E_N(k_N) tends to0 iff RH.','derived_moving_index_equivalence','audits/adversarial_reviews/director_prime_array_effective_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-PRIME-ARRAY-FINITE-NORMS','theorems/theorems.jsonl',108,'adjudicated_scoped','audits/adversarial_reviews/director_prime_array_effective_round9.md','{"id": "CERT-PRIME-ARRAY-FINITE-NORMS", "paper_id": null, "claim_kind": "validated_finite_norm_certificates", "statement": "Unconditional full squared errors at k=2,N=10,30,100 lie respectively in [0.342801539918328691,0.343111054662620134], [0.247656566621497315,0.247904631616511935], [0.179598089981701525,0.179908683595524940].", "hypotheses": "Original160/224-bit Arb runs with infinite tail bounds, pinned v1 and independent replay; hardened v2 separately recorded. No numerical limit inference.", "locator": "audits/adversarial_reviews/director_prime_array_effective_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Unconditional full squared errors at k=2,N=10,30,100 lie respectively in [0.342801539918328691,0.343111054662620134], [0.247656566621497315,0.247904631616511935], [0.179598089981701525,0.179908683595524940].','validated_finite_norm_certificates','audits/adversarial_reviews/director_prime_array_effective_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-HARD-MANGOLDT-DIVERGENCE','theorems/theorems.jsonl',109,'adjudicated_scoped','audits/adversarial_reviews/director_prime_array_effective_round9.md','{"id": "OBS-HARD-MANGOLDT-DIVERGENCE", "paper_id": null, "claim_kind": "unconditional_negative_approximation_theorem", "statement": "A_kM=log k(f_k−f_M)+sum_(d<=M)Lambda(d) f_k(x/d) matches R_k for x<M but ||R_k−A_kM||²>=M(logk)²/68 and is Theta_k(M).", "hypotheses": "This exact renormalized anchored hard cutoff, fixed k>=2; elementary binomial/Legendre bounds, no PNT. Not every hard cutoff.", "locator": "audits/adversarial_reviews/director_prime_array_effective_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'A_kM=log k(f_k−f_M)+sum_(d<=M)Lambda(d) f_k(x/d) matches R_k for x<M but ||R_k−A_kM||²>=M(logk)²/68 and is Theta_k(M).','unconditional_negative_approximation_theorem','audits/adversarial_reviews/director_prime_array_effective_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-PRIME-FORM-FOURIER-INVERSE','theorems/theorems.jsonl',110,'adjudicated_scoped','audits/adversarial_reviews/director_prime_array_inverse_round9.md','{"id": "THM-PRIME-FORM-FOURIER-INVERSE", "paper_id": null, "claim_kind": "conditional_inverse_theorem", "statement": "Under RH, all fixed-target limiting real quadratic forms determine the finite symmetric simple-zero measure nu=sum |zetaprime(rho)|²/|rho|² delta_gamma. C_k=(k+1)B−2sqrt(k)F(logk), B=lim C_k/k, and difference forms recover F(log(k/l)).", "hypotheses": "Exact limiting data, finiteness and symmetry; arithmetic N limit first. Multiple zeros and derivative phases are invisible.", "locator": "audits/adversarial_reviews/director_prime_array_inverse_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Under RH, all fixed-target limiting real quadratic forms determine the finite symmetric simple-zero measure nu=sum |zetaprime(rho)|²/|rho|² delta_gamma. C_k=(k+1)B−2sqrt(k)F(logk), B=lim C_k/k, and difference forms recover F(log(k/l)).','conditional_inverse_theorem','audits/adversarial_reviews/director_prime_array_inverse_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-PRIME-SINGLETON-ATOM-INVERSE','theorems/theorems.jsonl',111,'adjudicated_scoped','audits/adversarial_reviews/director_prime_array_inverse_round9.md','{"id": "THM-PRIME-SINGLETON-ATOM-INVERSE", "paper_id": null, "claim_kind": "atomic_inverse_theorem", "statement": "Singleton C_k alone recover every atom by logarithmic Cesaro quadrature: nu{x}=lim_(K→infinity)sum_(k=2)^K log(1+1/k)F(logk)e^(ixlogk)/log(K+1). Replacing B with C_K/K in all samples adds O(B/logK).", "hypotheses": "Finite symmetric measure; whole-measure uniqueness from singleton data holds in the pure atomic class. No uniform finite-data modulus.", "locator": "audits/adversarial_reviews/director_prime_array_inverse_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Singleton C_k alone recover every atom by logarithmic Cesaro quadrature: nu{x}=lim_(K→infinity)sum_(k=2)^K log(1+1/k)F(logk)e^(ixlogk)/log(K+1). Replacing B with C_K/K in all samples adds O(B/logK).','atomic_inverse_theorem','audits/adversarial_reviews/director_prime_array_inverse_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-PRIME-INVERSE-FINITE-AMBIGUITY','theorems/theorems.jsonl',112,'adjudicated_scoped','audits/adversarial_reviews/director_prime_array_inverse_round9.md','{"id": "OBS-PRIME-INVERSE-FINITE-AMBIGUITY", "paper_id": null, "claim_kind": "inverse_problem_obstructions", "statement": "Every finite collection of form data admits different positive symmetric atomic measures, even with supplied equal mass; without mass, entire-kernel evaluation at i/2 gives different-mass competitors. All singleton data can miss diffuse measures. o(sqrt k) singleton errors preserve atomic recovery but O(sqrt k) can conceal distinct profiles.", "hypotheses": "Synthetic positive measures, not alternative zeta functions. Exact finite/noisy data are not full infinite limiting information.", "locator": "audits/adversarial_reviews/director_prime_array_inverse_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Every finite collection of form data admits different positive symmetric atomic measures, even with supplied equal mass; without mass, entire-kernel evaluation at i/2 gives different-mass competitors. All singleton data can miss diffuse measures. o(sqrt k) singleton errors preserve atomic recovery but O(sqrt k) can conceal distinct profiles.','inverse_problem_obstructions','audits/adversarial_reviews/director_prime_array_inverse_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-HLZ-FIXED-DERIVATIVE-MOMENT','theorems/theorems.jsonl',113,'adjudicated_scoped','audits/adversarial_reviews/director_hlz_prime_torus_round9.md','{"id": "THM-HLZ-FIXED-DERIVATIVE-MOMENT", "paper_id": "PAPER-DM63-HLZ2022", "claim_kind": "source_dependent_derived_asymptotic", "statement": "For fixed real Dirichlet polynomial Q, RH gives sum_(0<gamma<=T)|zetaprime(rho)Q(rho)|²=S(Q)Tlog^4T/(24pi)+O_Q(Tlog^3T), S=sum a_m a_n/lcm(m,n).", "hypotheses": "Heap–Li–Zhao journal Thm5 complex-shift uniformity and coefficient hypotheses; arbitrary fixed sparse support handled by divisor-closed positive padding and quadratic identity.", "locator": "audits/adversarial_reviews/director_hlz_prime_torus_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}','PAPER-DM63-HLZ2022','For fixed real Dirichlet polynomial Q, RH gives sum_(0<gamma<=T)|zetaprime(rho)Q(rho)|²=S(Q)Tlog^4T/(24pi)+O_Q(Tlog^3T), S=sum a_m a_n/lcm(m,n).','source_dependent_derived_asymptotic','audits/adversarial_reviews/director_hlz_prime_torus_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-HLZ-GCD-TAIL','theorems/theorems.jsonl',114,'adjudicated_scoped','audits/adversarial_reviews/director_hlz_prime_torus_round9.md','{"id": "THM-HLZ-GCD-TAIL", "paper_id": null, "claim_kind": "derived_arithmetic_tail_asymptotic", "statement": "For fixed k,l, the two-sided derivative-weighted Q_k,Q_l tail is (gcd(k,l)−1)log^4Y/(12piY)+O_(k,l)(log^3Y/Y). For Q=1 the coefficient is1.", "hypotheses": "RH; Q_k=k^(1−s)−1; strict-tail endpoint and both ordinate signs retained, multiple zeros vanish; no growing-index uniformity in this claim.", "locator": "audits/adversarial_reviews/director_hlz_prime_torus_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'For fixed k,l, the two-sided derivative-weighted Q_k,Q_l tail is (gcd(k,l)−1)log^4Y/(12piY)+O_(k,l)(log^3Y/Y). For Q=1 the coefficient is1.','derived_arithmetic_tail_asymptotic','audits/adversarial_reviews/director_hlz_prime_torus_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-PRIME-POISSON-TORUS','theorems/theorems.jsonl',115,'adjudicated_scoped','audits/adversarial_reviews/director_hlz_prime_torus_round9.md','{"id": "THM-PRIME-POISSON-TORUS", "paper_id": null, "claim_kind": "cross_paper_harmonic_connection", "statement": "Under RH, normalized high tails of nu pushed to (p^(−i gamma))_p converge weakly on the countable prime torus to independent Poisson circle laws with radii p^−1/2. Factorial variables have mean0 and covariance gcd(k,l)−1=sum_(d|k,d|l,d>=2)phi(d).", "hypotheses": "Fixed character tests before Y limit; source moment theorem plus partial summation. One weighted ordinate, not spacing or unweighted zero statistics.", "locator": "audits/adversarial_reviews/director_hlz_prime_torus_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Under RH, normalized high tails of nu pushed to (p^(−i gamma))_p converge weakly on the countable prime torus to independent Poisson circle laws with radii p^−1/2. Factorial variables have mean0 and covariance gcd(k,l)−1=sum_(d|k,d|l,d>=2)phi(d).','cross_paper_harmonic_connection','audits/adversarial_reviews/director_hlz_prime_torus_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-PRIME-PHASE-NONUNIFORMITY','theorems/theorems.jsonl',116,'adjudicated_scoped','audits/adversarial_reviews/director_hlz_prime_torus_round9.md','{"id": "OBS-PRIME-PHASE-NONUNIFORMITY", "paper_id": null, "claim_kind": "uniformity_and_topology_obstruction", "statement": "For each fixed positive tail mass B_Y, the supremum over distinct prime pairs of |F_Y(log(p/q))/B_Y−1/sqrt(pq)| is at least1. The fixed-rational limiting coefficient is discontinuous at0 in the ordinary real topology and is not a real-line probability Fourier transform.", "hypotheses": "Continuity of each finite actual tail Fourier transform and arbitrarily close large prime ratios; compatible with fixed-prime torus convergence.", "locator": "audits/adversarial_reviews/director_hlz_prime_torus_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'For each fixed positive tail mass B_Y, the supremum over distinct prime pairs of |F_Y(log(p/q))/B_Y−1/sqrt(pq)| is at least1. The fixed-rational limiting coefficient is discontinuous at0 in the ordinary real topology and is not a real-line probability Fourier transform.','uniformity_and_topology_obstruction','audits/adversarial_reviews/director_hlz_prime_torus_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-DENSITY-WEIGHTED-SLABS','theorems/theorems.jsonl',117,'adjudicated_scoped','audits/adversarial_reviews/director_density_synthesis_round9.md','{"id": "THM-DENSITY-WEIGHTED-SLABS", "paper_id": null, "claim_kind": "source_dependent_density_synthesis", "statement": "A fixed positive gap2(1−sigma)−E(sigma)>0 removes each compact slab from the BGSTB positive weighted majorant by a fixed mesh. Palomar right branch3(1−sigma)/(2sigma) removes every compact slab in(3/4,1), but value at3/4 remains9/16; Pintz wins above9/10.", "hypotheses": "Source density bounds with fixed sigma,epsilon, constants; near1 requires separate uniform external input. These are majorant consequences, not necessary signed-cancellation conditions.", "locator": "audits/adversarial_reviews/director_density_synthesis_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'A fixed positive gap2(1−sigma)−E(sigma)>0 removes each compact slab from the BGSTB positive weighted majorant by a fixed mesh. Palomar right branch3(1−sigma)/(2sigma) removes every compact slab in(3/4,1), but value at3/4 remains9/16; Pintz wins above9/10.','source_dependent_density_synthesis','audits/adversarial_reviews/director_density_synthesis_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-DENSITY-SINGLE-WINDOW','theorems/theorems.jsonl',118,'adjudicated_scoped','audits/adversarial_reviews/director_density_synthesis_round9.md','{"id": "THM-DENSITY-SINGLE-WINDOW", "paper_id": null, "claim_kind": "sharp_implication_of_density_inputs", "statement": "Combining Ye local bounds and an accepted uniform upper-tail input gives weighted o(T) in each comparable-height O(T^b) window for every fixed0<b<13/15. The7/10 layer, not3/4, is critical. No full-block saving follows by covering.", "hypotheses": "Fixed b, split point v just above3/4, correct source branch join; for b<2/3 use nesting.", "locator": "audits/adversarial_reviews/director_density_synthesis_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Combining Ye local bounds and an accepted uniform upper-tail input gives weighted o(T) in each comparable-height O(T^b) window for every fixed0<b<13/15. The7/10 layer, not3/4, is critical. No full-block saving follows by covering.','sharp_implication_of_density_inputs','audits/adversarial_reviews/director_density_synthesis_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-DENSITY-ALL-HEIGHT-ESCAPE','theorems/theorems.jsonl',119,'adjudicated_scoped','audits/adversarial_reviews/director_density_synthesis_round9.md','{"id": "OBS-DENSITY-ALL-HEIGHT-ESCAPE", "paper_id": null, "claim_kind": "all_height_negative_inference_model", "statement": "One fixed reflected positive multiset can satisfy all inspected global/local density bounds, RVM O(logT), unit counts, proportion lower bounds and off-line o(T), while D_T(1/2)=o(T), r_T→0 locally and M_T/T→2 along all real heights. Separate lacunary7/10 blocks show13/15 sharp for the stated inputs.", "hypotheses": "Explicit two-curve counting model with critical fillers. Does not impose actual zeta explicit formula, signed pair identity or Dirichlet-sum triggers.", "locator": "audits/adversarial_reviews/director_density_synthesis_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'One fixed reflected positive multiset can satisfy all inspected global/local density bounds, RVM O(logT), unit counts, proportion lower bounds and off-line o(T), while D_T(1/2)=o(T), r_T→0 locally and M_T/T→2 along all real heights. Separate lacunary7/10 blocks show13/15 sharp for the stated inputs.','all_height_negative_inference_model','audits/adversarial_reviews/director_density_synthesis_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-DENSITY-DYADIC-TIGHTNESS','theorems/theorems.jsonl',120,'adjudicated_scoped','audits/adversarial_reviews/director_density_synthesis_round9.md','{"id": "LEM-DENSITY-DYADIC-TIGHTNESS", "paper_id": null, "claim_kind": "conditional_sufficient_missing_lemma", "statement": "After upper-tail removal, D_T(a)=o(T) and a uniform bound Y^−1 integral_Y^(2Y) r_T(y)dy<=C Y^(1−kappa), kappa>0, imply M_T=o(T).", "hypotheses": "Exact layer identity, positive counting, uniform constants in Y,T; the displayed sufficient missing arithmetic hypothesis is unproved for actual zeta.", "locator": "audits/adversarial_reviews/director_density_synthesis_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'After upper-tail removal, D_T(a)=o(T) and a uniform bound Y^−1 integral_Y^(2Y) r_T(y)dy<=C Y^(1−kappa), kappa>0, imply M_T=o(T).','conditional_sufficient_missing_lemma','audits/adversarial_reviews/director_density_synthesis_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-PALOMAR-FULL-CURVE-QUERY','theorems/theorems.jsonl',121,'adjudicated_scoped','audits/adversarial_reviews/director_density_synthesis_round9.md','{"id": "CERT-PALOMAR-FULL-CURVE-QUERY", "paper_id": null, "claim_kind": "actual_formal_component_query", "statement": "The actual cached Lean full_curve and uniform_away_boundary declarations compiled/query exited0 with exactly propext, Classical.choice, Quot.sound and unchanged pinned module. Quantifiers differ: fixed sigma,epsilon then constants versus fixed delta,epsilon then all sigma,T.", "hypotheses": "Pinned Palomar source/Lean/mathlib receipts and raw declaration types; not a new build, axiom-free proof, or RH result.", "locator": "audits/adversarial_reviews/director_density_synthesis_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'The actual cached Lean full_curve and uniform_away_boundary declarations compiled/query exited0 with exactly propext, Classical.choice, Quot.sound and unchanged pinned module. Quantifiers differ: fixed sigma,epsilon then constants versus fixed delta,epsilon then all sigma,T.','actual_formal_component_query','audits/adversarial_reviews/director_density_synthesis_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-MANZUR-COVARIANCE-SIGN','theorems/theorems.jsonl',122,'adjudicated_scoped','audits/adversarial_reviews/director_manzur_noor_whole_round9.md','{"id": "OBS-MANZUR-COVARIANCE-SIGN", "paper_id": "PAPER-MN2026-VERTICAL", "claim_kind": "verified_versioned_auxiliary_display_error", "statement": "In arXiv2610.03568v1 §6 both displayed covariance phases require n^(−i tau), not n^(i tau). For n=2,tau=pi/(2log2),e0 the printed direct relation says e0+e1=−e0−e1. The main Theorem5.1 and printed operator matrix survive the correction.", "hypotheses": "Exact pinned seven-page v1, no RH needed for the witness; two independent complete reviews and director reconstruction.", "locator": "audits/adversarial_reviews/director_manzur_noor_whole_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}','PAPER-MN2026-VERTICAL','In arXiv2610.03568v1 §6 both displayed covariance phases require n^(−i tau), not n^(i tau). For n=2,tau=pi/(2log2),e0 the printed direct relation says e0+e1=−e0−e1. The main Theorem5.1 and printed operator matrix survive the correction.','verified_versioned_auxiliary_display_error','audits/adversarial_reviews/director_manzur_noor_whole_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-MANZUR-RIGHT-SHIFT-EXTENSION','theorems/theorems.jsonl',123,'adjudicated_scoped','audits/adversarial_reviews/director_manzur_noor_whole_round9.md','{"id": "LEM-MANZUR-RIGHT-SHIFT-EXTENSION", "paper_id": null, "claim_kind": "elementary_operator_extension", "statement": "For Re alpha>0, the same Copson-row construction with d_j=(j+1)^−alpha is bounded and satisfies T_alpha* k_s=(bar s+bar alpha)k_(s+alpha)/bar s with nonzero scalar.", "hypotheses": "Disk Hardy kernels with Re s>1/2; this separately answers the motivating right-shift question, whereas source T_tau is vertical. No novelty claim.", "locator": "audits/adversarial_reviews/director_manzur_noor_whole_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'For Re alpha>0, the same Copson-row construction with d_j=(j+1)^−alpha is bounded and satisfies T_alpha* k_s=(bar s+bar alpha)k_(s+alpha)/bar s with nonzero scalar.','elementary_operator_extension','audits/adversarial_reviews/director_manzur_noor_whole_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-LEE-PANKOWSKI-TARGET','theorems/theorems.jsonl',124,'adjudicated_scoped','audits/adversarial_reviews/director_lee_pankowski_scope_round9.md','{"id": "OBS-LEE-PANKOWSKI-TARGET", "paper_id": "PAPER-DM63-LEEPANKOWSKI2025", "claim_kind": "missing_hypothesis_with_exact_scope", "statement": "The literal new theorem statements omit nonvanishing although both proofs take log f. On D_(1/8)(3/4), f(s)=s−3/4 and epsilon1/16 force a right-strip zero by Rouche, so underRH the good set is empty. Global zero density does not by itself refute the unconditional short-window limsup.", "hypotheses": "Pinned arxivv1 and journal version; intended zero-free target repair, no public error flag or unconditional main theorem refutation.", "locator": "audits/adversarial_reviews/director_lee_pankowski_scope_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}','PAPER-DM63-LEEPANKOWSKI2025','The literal new theorem statements omit nonvanishing although both proofs take log f. On D_(1/8)(3/4), f(s)=s−3/4 and epsilon1/16 force a right-strip zero by Rouche, so underRH the good set is empty. Global zero density does not by itself refute the unconditional short-window limsup.','missing_hypothesis_with_exact_scope','audits/adversarial_reviews/director_lee_pankowski_scope_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-HLZ-UNIFORM-POLYLOG-PHASE','theorems/theorems.jsonl',125,'adjudicated_scoped','audits/adversarial_reviews/director_hlz_uniform_round9.md','{"id": "THM-HLZ-UNIFORM-POLYLOG-PHASE", "paper_id": null, "claim_kind": "uniform_source_dependent_asymptotic", "statement": "Under RH, for every fixed D,B>0 and all m,n<=log^D Y, mn T_Y(e_m,e_n)/B_Y=g+O_(D,B)(g log(mn/g²)/logY+log^(−B)Y), g=gcd(m,n). The diagonal is exactlym, and normalized Fourier absolute error is O_D(1/logY).", "hypotheses": "Two-sided symmetric derivative weights; source-uniform bounded padding before cancellation, exact untwisted normalization and arbitrary log saving. Siegel cutoff ineffective, no numerical onset.", "locator": "audits/adversarial_reviews/director_hlz_uniform_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Under RH, for every fixed D,B>0 and all m,n<=log^D Y, mn T_Y(e_m,e_n)/B_Y=g+O_(D,B)(g log(mn/g²)/logY+log^(−B)Y), g=gcd(m,n). The diagonal is exactlym, and normalized Fourier absolute error is O_D(1/logY).','uniform_source_dependent_asymptotic','audits/adversarial_reviews/director_hlz_uniform_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-HLZ-GROWING-PRIME-COVARIANCE','theorems/theorems.jsonl',126,'adjudicated_scoped','audits/adversarial_reviews/director_hlz_uniform_round9.md','{"id": "THM-HLZ-GROWING-PRIME-COVARIANCE", "paper_id": null, "claim_kind": "growing_block_covariance_theorem", "statement": "Under RH, for every fixed D>0, Z_p=(sqrt(p)e^(−i gamma logp)−1)/sqrt(p−1), primes p<=log^D Y, has centered covariance I+O_D((loglogY)²/logY) in operator norm under the normalized derivative-weighted high tail. Unscaled prime entries have O_D(loglogY/logY) absolute error.", "hypotheses": "Only covariance, not a growing-dimensional joint law; all-integer unscaled entries also converge uniformly for P=o(logY). No effective onset from Siegel-based source proof.", "locator": "audits/adversarial_reviews/director_hlz_uniform_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Under RH, for every fixed D>0, Z_p=(sqrt(p)e^(−i gamma logp)−1)/sqrt(p−1), primes p<=log^D Y, has centered covariance I+O_D((loglogY)²/logY) in operator norm under the normalized derivative-weighted high tail. Unscaled prime entries have O_D(loglogY/logY) absolute error.','growing_block_covariance_theorem','audits/adversarial_reviews/director_hlz_uniform_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-PRIME-ARRAY-COMPUTABLE-REMAINDER','theorems/theorems.jsonl',127,'adjudicated_scoped','audits/adversarial_reviews/director_prime_remainder_round9.md','{"id": "THM-PRIME-ARRAY-COMPUTABLE-REMAINDER", "paper_id": null, "claim_kind": "explicit_finite_height_convergence_modulus", "statement": "Under RH, a complete certified finite critical-zero list and local disk majorants give |sqrt(logN E_N)−sqrt(C_F)|<=alpha+q sqrt(c_plus)/(1+sqrt(1−q)) and |logN E_N−C2|<=2sqrt(c_plus+A(Y))eta+eta², with all quantities explicitly defined in the cited proof.", "hypotheses": "All-zero cutoff completeness and multiplicity, disjoint finite windows, actual anchor; B(Y) controls near-function tail while the improved A(Y) controls coefficient tail only. No practical small threshold claimed.", "locator": "audits/adversarial_reviews/director_prime_remainder_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Under RH, a complete certified finite critical-zero list and local disk majorants give |sqrt(logN E_N)−sqrt(C_F)|<=alpha+q sqrt(c_plus)/(1+sqrt(1−q)) and |logN E_N−C2|<=2sqrt(c_plus+A(Y))eta+eta², with all quantities explicitly defined in the cited proof.','explicit_finite_height_convergence_modulus','audits/adversarial_reviews/director_prime_remainder_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-EXPLICIT-CRITICAL-DERIVATIVE-TAIL','theorems/theorems.jsonl',128,'adjudicated_scoped','audits/adversarial_reviews/director_prime_remainder_round9.md','{"id": "THM-EXPLICIT-CRITICAL-DERIVATIVE-TAIL", "paper_id": null, "claim_kind": "unconditional_effective_tail_bound", "statement": "Unconditionally sum_(0<gamma<=T,critical)|zeta prime(1/2+i gamma)|²<=260000Tlog^4(4T) for T>=16. The two-sided factorialk2 derivative series tail for Y>=16 is <=6.24e6/Y[H4+4H3+12H2+24H+24]<=2.1e7H4/Y, H=log(4Y).", "hypotheses": "Only critical-line zeros counted, multiple zeros contribute0; no RH for these bounds. RH only identifies the series with the prescribed-array limit. Explicit HardyZ/Cauchy/Rolle and Gaussian strip mean square proof.", "locator": "audits/adversarial_reviews/director_prime_remainder_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'Unconditionally sum_(0<gamma<=T,critical)|zeta prime(1/2+i gamma)|²<=260000Tlog^4(4T) for T>=16. The two-sided factorialk2 derivative series tail for Y>=16 is <=6.24e6/Y[H4+4H3+12H2+24H+24]<=2.1e7H4/Y, H=log(4Y).','unconditional_effective_tail_bound','audits/adversarial_reviews/director_prime_remainder_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-PRIME-DERIVATIVE-HEIGHT100','theorems/theorems.jsonl',129,'adjudicated_scoped','audits/adversarial_reviews/director_prime_remainder_round9.md','{"id": "CERT-PRIME-DERIVATIVE-HEIGHT100", "paper_id": null, "claim_kind": "validated_finite_zeros_plus_effective_tail", "statement": "A complete count of29positive zeros through100 with simple disjoint line-zero balls yields finite derivative sum in[0.25253801685456458,0.25253801685456460]. The entire critical-line series is in[0.25253801685456458,1.716e8].", "hypotheses": "Unconditional count/jet/tail certificate;128bitdirector and192bitindependentArbreplays. RH only for interpreting the full series as C2. No large-height list computed.", "locator": "audits/adversarial_reviews/director_prime_remainder_round9.md", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/director_round9_claims.jsonl"}',NULL,'A complete count of29positive zeros through100 with simple disjoint line-zero balls yields finite derivative sum in[0.25253801685456458,0.25253801685456460]. The entire critical-line series is in[0.25253801685456458,1.716e8].','validated_finite_zeros_plus_effective_tail','audits/adversarial_reviews/director_prime_remainder_round9.md','theorems/director_round9_claims.jsonl');
INSERT INTO "claims" VALUES('THM-ADAPTIVE-DIRICHLET-OPT','theorems/theorems.jsonl',130,'adjudicated_scoped_GRH_conditional_transplant','audits/adversarial_reviews/director_dirichlet_transfer_round6.md; complete proofs and independent audits citedthere','{"id": "THM-ADAPTIVE-DIRICHLET-OPT", "paper_id": null, "claim_kind": "proved_source_based_fixed_character_transplant", "statement": "Fix a primitive Dirichlet characterchi and assume GRH for L(s,chi). LetDelta_(N,chi)^2 be the infimum over all ordinary Dirichlet polynomialsA=sum_{n<=N}a_n n^-s with arbitrary complex coefficients of(2pi)^(-1)integral_R|1-L(1/2+it,chi)A(1/2+it)|²/(1/4+t²)dt. Thenlim_N(logN)Delta_(N,chi)^2=sum_{distinct nontrivialrho ofLchi}m_rho²/|rho|². All signed ordinates are included without assuming plus/minus pairing; a centralzero is included once.", "hypotheses": "GRH for this fixedcharacter; no simplicity, spacing or reciprocal-derivative moment. Constants dependonchi. Unanchored arbitrarycoefficient infimum; no conductoruniformity, effective rate or prescribedarray claim. Primitiveprincipal conductor1 is the zeta sourcecase.", "verification_scope": "Independent proponent, skeptic, further audit and director reconstruction; published deRotonlower accepted in exact checked application. No whole-paper promotion or publication novelty claim.", "locator": "audits/adversarial_reviews/director_dirichlet_transfer_round6.md; complete proofs and independent audits citedthere", "status": "adjudicated_scoped_GRH_conditional_transplant", "novelty_claim": false, "provenance_file": "theorems/dirichlet_director_round6.jsonl"}',NULL,'Fix a primitive Dirichlet characterchi and assume GRH for L(s,chi). LetDelta_(N,chi)^2 be the infimum over all ordinary Dirichlet polynomialsA=sum_{n<=N}a_n n^-s with arbitrary complex coefficients of(2pi)^(-1)integral_R|1-L(1/2+it,chi)A(1/2+it)|²/(1/4+t²)dt. Thenlim_N(logN)Delta_(N,chi)^2=sum_{distinct nontrivialrho ofLchi}m_rho²/|rho|². All signed ordinates are included without assuming plus/minus pairing; a centralzero is included once.','proved_source_based_fixed_character_transplant','audits/adversarial_reviews/director_dirichlet_transfer_round6.md; complete proofs and independent audits citedthere','theorems/dirichlet_director_round6.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-LOCAL','theorems/theorems.jsonl',131,'adjudicated_scoped; effective_inputs_not_instantiated','audits/adversarial_reviews/effective_cluster62_proof.md §1','{"id": "EFFECTIVE-CLUSTER62-LOCAL", "status": "adjudicated_scoped; effective_inputs_not_instantiated", "statement": "Under RH and the source profile hypotheses, a fixed set of complete clusters with optimal top Laurent profiles has scaled squared norm S_Y plus an error bounded by K''_Y(1+log L)/L, where L=log N.", "dependencies": ["source profile Fourier identity", "fixed singleton Laurent repair", "certified finite analytic multipliers and isolating windows"], "locator": "audits/adversarial_reviews/effective_cluster62_proof.md §1", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_claims.jsonl", "verification": "Complete proof, independent witness and director reconstruction; fixed-Y constants, one-sided scope and supplied certificate assumptions retained.", "status_update_evidence": "audits/adversarial_reviews/director_effective_cluster_round6.md"}',NULL,'Under RH and the source profile hypotheses, a fixed set of complete clusters with optimal top Laurent profiles has scaled squared norm S_Y plus an error bounded by K''_Y(1+log L)/L, where L=log N.',NULL,'audits/adversarial_reviews/effective_cluster62_proof.md §1','theorems/effective_cluster62_claims.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-UPPER','theorems/theorems.jsonl',132,'adjudicated_scoped; effective_inputs_not_instantiated','audits/adversarial_reviews/effective_cluster62_proof.md (A), §§1–3','{"id": "EFFECTIVE-CLUSTER62-UPPER", "status": "adjudicated_scoped; effective_inputs_not_instantiated", "statement": "Under RH, for each fixed Y and all integers N >= Y^20 with log N >= 1, the optimized anchored and unrestricted scaled squared distances satisfy bound (A). Its squared delayed-tail cost is B Y^(-99/100)/log N and the mixed terms decay at fixed Y. Supplied input majorants and finite certificates make this an explicit upper tolerance algorithm.", "dependencies": ["EFFECTIVE-CLUSTER62-LOCAL", "source (41), (49), (59), (60), (62)", "differentiated Euler quadrature and fixed-right Perron anchor"], "locator": "audits/adversarial_reviews/effective_cluster62_proof.md (A), §§1–3", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_claims.jsonl", "verification": "Complete proof, independent witness and director reconstruction; fixed-Y constants, one-sided scope and supplied certificate assumptions retained.", "status_update_evidence": "audits/adversarial_reviews/director_effective_cluster_round6.md"}',NULL,'Under RH, for each fixed Y and all integers N >= Y^20 with log N >= 1, the optimized anchored and unrestricted scaled squared distances satisfy bound (A). Its squared delayed-tail cost is B Y^(-99/100)/log N and the mixed terms decay at fixed Y. Supplied input majorants and finite certificates make this an explicit upper tolerance algorithm.',NULL,'audits/adversarial_reviews/effective_cluster62_proof.md (A), §§1–3','theorems/effective_cluster62_claims.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-RATE-SCOPE','theorems/theorems.jsonl',133,'adjudicated_scoped; effective_inputs_not_instantiated','audits/adversarial_reviews/effective_cluster62_proof.md §3','{"id": "EFFECTIVE-CLUSTER62-RATE-SCOPE", "status": "adjudicated_scoped; effective_inputs_not_instantiated", "statement": "Qualitative convergence and monotonicity alone imply no universal rate, and the fixed-height certificate does not control its constants as Y grows. A two-sided numerical tolerance requires a quantitative lower-bound input. This is not an obstruction theorem for the actual optimized zeta distance.", "locator": "audits/adversarial_reviews/effective_cluster62_proof.md §3", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_claims.jsonl", "verification": "Complete proof, independent witness and director reconstruction; fixed-Y constants, one-sided scope and supplied certificate assumptions retained.", "status_update_evidence": "audits/adversarial_reviews/director_effective_cluster_round6.md"}',NULL,'Qualitative convergence and monotonicity alone imply no universal rate, and the fixed-height certificate does not control its constants as Y grows. A two-sided numerical tolerance requires a quantitative lower-bound input. This is not an obstruction theorem for the actual optimized zeta distance.',NULL,'audits/adversarial_reviews/effective_cluster62_proof.md §3','theorems/effective_cluster62_claims.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-DR2006-PHI','theorems/theorems.jsonl',134,'explicit_counterexample_to_printed_intermediate_lemma','audits/adversarial_reviews/effective_cluster62_deroton_phase_repair.md §1','{"id": "EFFECTIVE-CLUSTER62-DR2006-PHI", "status": "explicit_counterexample_to_printed_intermediate_lemma", "statement": "For the primitive odd character modulo 4, the source phase image is phi(x)=(1-cos(pi*x/2))/(pi*x/2), and x*phi''(x)=sin(pi*x/2)-phi(x) is not in L². This refutes the derivative estimate in de Roton 2006 Proposition 5.1 (12). More generally, the dilation derivative of the phase image of the indicator is never in L² for any unitary Mellin multiplier.", "locator": "audits/adversarial_reviews/effective_cluster62_deroton_phase_repair.md §1", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_deroton_phase_claims.jsonl"}',NULL,'For the primitive odd character modulo 4, the source phase image is phi(x)=(1-cos(pi*x/2))/(pi*x/2), and x*phi''(x)=sin(pi*x/2)-phi(x) is not in L². This refutes the derivative estimate in de Roton 2006 Proposition 5.1 (12). More generally, the dilation derivative of the phase image of the indicator is never in L² for any unitary Mellin multiplier.',NULL,'audits/adversarial_reviews/effective_cluster62_deroton_phase_repair.md §1','theorems/effective_cluster62_deroton_phase_claims.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-DR2006-WEIGHTED-REPAIR','theorems/theorems.jsonl',135,'reconstructed_under_published_square_integrability_premise','audits/adversarial_reviews/effective_cluster62_deroton_phase_repair.md §§2–5','{"id": "EFFECTIVE-CLUSTER62-DR2006-WEIGHTED-REPAIR", "status": "reconstructed_under_published_square_integrability_premise", "statement": "Under de Roton’s complementary-function L² premise, tested shifts justify the pole-canceled support and two fixed weighted inverse Mellin lines give analytic cutoff jets, Gram limits and target pairings, recovering the lower bound for critical zeros.", "locator": "audits/adversarial_reviews/effective_cluster62_deroton_phase_repair.md §§2–5", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_deroton_phase_claims.jsonl"}',NULL,'Under de Roton’s complementary-function L² premise, tested shifts justify the pole-canceled support and two fixed weighted inverse Mellin lines give analytic cutoff jets, Gram limits and target pairings, recovering the lower bound for critical zeros.',NULL,'audits/adversarial_reviews/effective_cluster62_deroton_phase_repair.md §§2–5','theorems/effective_cluster62_deroton_phase_claims.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-DIRICHLET-UPPER','theorems/theorems.jsonl',136,'adjudicated_scoped_fixed_character_GRH_transplant','audits/adversarial_reviews/effective_cluster62_dirichlet_transfer.md §§1–4','{"id": "EFFECTIVE-CLUSTER62-DIRICHLET-UPPER", "status": "adjudicated_scoped_fixed_character_GRH_transplant", "statement": "For each fixed primitive Dirichlet character under its GRH, the unanchored distance for all ordinary length-N Dirichlet polynomials satisfies limsup (log N) Delta_N,chi^2 <= sum m_rho^2/|rho|^2 over distinct nontrivial zeros.", "locator": "audits/adversarial_reviews/effective_cluster62_dirichlet_transfer.md §§1–4", "dependencies": ["fixed-character GRH growth and signed good heights", "RST048v2 retained-edge identity", "rational cluster profiles and ordinary integer quadrature", "finite singleton Laurent localization"], "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_dirichlet_claims.jsonl", "verification": "Independent proponent,skeptic,furtheradversarialreviewanddirector. Exactpublishedlowerapplicationchecked; no noveltyorconductoruniformityclaim.", "status_update_evidence": "audits/adversarial_reviews/director_dirichlet_transfer_round6.md"}',NULL,'For each fixed primitive Dirichlet character under its GRH, the unanchored distance for all ordinary length-N Dirichlet polynomials satisfies limsup (log N) Delta_N,chi^2 <= sum m_rho^2/|rho|^2 over distinct nontrivial zeros.',NULL,'audits/adversarial_reviews/effective_cluster62_dirichlet_transfer.md §§1–4','theorems/effective_cluster62_dirichlet_claims.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-DIRICHLET-LOWER','theorems/theorems.jsonl',137,'adjudicated_scoped_fixed_character_GRH_transplant','audits/adversarial_reviews/effective_cluster62_dirichlet_transfer.md §5','{"id": "EFFECTIVE-CLUSTER62-DIRICHLET-LOWER", "status": "adjudicated_scoped_fixed_character_GRH_transplant", "statement": "De Roton Thm 2 gives the matching liminf under GRH by continuous-to-integer scale inclusion at lambda=1/N and the complementary function Mellin transform -L(s,chi)/s for nonprincipal chi.", "locator": "audits/adversarial_reviews/effective_cluster62_dirichlet_transfer.md §5", "dependencies": ["de Roton BSMF 134 (2006) Theorem 2", "Mellin–Plancherel"], "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_dirichlet_claims.jsonl", "verification": "Independent proponent,skeptic,furtheradversarialreviewanddirector. Exactpublishedlowerapplicationchecked; no noveltyorconductoruniformityclaim.", "status_update_evidence": "audits/adversarial_reviews/director_dirichlet_transfer_round6.md"}',NULL,'De Roton Thm 2 gives the matching liminf under GRH by continuous-to-integer scale inclusion at lambda=1/N and the complementary function Mellin transform -L(s,chi)/s for nonprincipal chi.',NULL,'audits/adversarial_reviews/effective_cluster62_dirichlet_transfer.md §5','theorems/effective_cluster62_dirichlet_claims.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-PREFIX-MOMENT-INVERSION','theorems/theorems.jsonl',138,'adjudicated_scoped_abstract_or_conditional_arithmetic','audits/adversarial_reviews/effective_cluster62_prefix_inverse_moments.md §§1–3','{"id": "EFFECTIVE-CLUSTER62-PREFIX-MOMENT-INVERSION", "status": "adjudicated_scoped_abstract_or_conditional_arithmetic", "statement": "The analytic germ at 0 of the finite prefix-cost aggregate determines its weighted multiplicity distribution. Classical unconditional logarithmic zeta zero counts suffice for the local analytic germ and square-root exponential moment, and RH short-window counts yield holomorphy on the punctured b-plane excluding 1.", "locator": "audits/adversarial_reviews/effective_cluster62_prefix_inverse_moments.md §§1–3", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_prefix_inverse_moments.jsonl", "verification_status": "Two independent proofs and director; actual-zero germ unconditional, arithmetic prefix interpretation RH-dependent. Finite-data examples are synthetic.", "director_evidence": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "status_update_evidence": "audits/adversarial_reviews/director_prefix_inverse_round8.md"}',NULL,'The analytic germ at 0 of the finite prefix-cost aggregate determines its weighted multiplicity distribution. Classical unconditional logarithmic zeta zero counts suffice for the local analytic germ and square-root exponential moment, and RH short-window counts yield holomorphy on the punctured b-plane excluding 1.',NULL,'audits/adversarial_reviews/effective_cluster62_prefix_inverse_moments.md §§1–3','theorems/effective_cluster62_prefix_inverse_moments.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-PREFIX-MOMENT-SHARP','theorems/theorems.jsonl',139,'adjudicated_scoped_abstract_or_conditional_arithmetic','audits/adversarial_reviews/effective_cluster62_prefix_inverse_moments.md §§4–5','{"id": "EFFECTIVE-CLUSTER62-PREFIX-MOMENT-SHARP", "status": "adjudicated_scoped_abstract_or_conditional_arithmetic", "statement": "The exponential weight limsup gives the exact Taylor radius for nonconstant positive aggregates. Weak logarithmic count models allow radius below 1. Formal moments can be indeterminate on the exact m(m−1) lattice without a suitable tail hypothesis.", "locator": "audits/adversarial_reviews/effective_cluster62_prefix_inverse_moments.md §§4–5", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_prefix_inverse_moments.jsonl", "verification_status": "Two independent proofs and director; actual-zero germ unconditional, arithmetic prefix interpretation RH-dependent. Finite-data examples are synthetic.", "director_evidence": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "status_update_evidence": "audits/adversarial_reviews/director_prefix_inverse_round8.md"}',NULL,'The exponential weight limsup gives the exact Taylor radius for nonconstant positive aggregates. Weak logarithmic count models allow radius below 1. Formal moments can be indeterminate on the exact m(m−1) lattice without a suitable tail hypothesis.',NULL,'audits/adversarial_reviews/effective_cluster62_prefix_inverse_moments.md §§4–5','theorems/effective_cluster62_prefix_inverse_moments.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-PREFIX-FINITE-DATA','theorems/theorems.jsonl',140,'adjudicated_scoped_abstract_or_conditional_arithmetic','audits/adversarial_reviews/effective_cluster62_prefix_inverse_moments.md §§6–7','{"id": "EFFECTIVE-CLUSTER62-PREFIX-FINITE-DATA", "status": "adjudicated_scoped_abstract_or_conditional_arithmetic", "statement": "At every finite Taylor order there are distinct finite positive weighted multiplicity distributions with the same jet and different maximal multiplicity, although C''(0)=0 forces exclusively simple support. Arbitrarily high multiplicity can be hidden by small weight in approximate compact-range data. An exact limiting aggregate C(b)=o((1-b)^(-1)) as b approaches 1 forces simple support. Finite-N prefix staircases do not authorize differentiation of their limiting profile.", "locator": "audits/adversarial_reviews/effective_cluster62_prefix_inverse_moments.md §§6–7", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_prefix_inverse_moments.jsonl", "verification_status": "Two independent proofs and director; actual-zero germ unconditional, arithmetic prefix interpretation RH-dependent. Finite-data examples are synthetic.", "director_evidence": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "status_update_evidence": "audits/adversarial_reviews/director_prefix_inverse_round8.md"}',NULL,'At every finite Taylor order there are distinct finite positive weighted multiplicity distributions with the same jet and different maximal multiplicity, although C''(0)=0 forces exclusively simple support. Arbitrarily high multiplicity can be hidden by small weight in approximate compact-range data. An exact limiting aggregate C(b)=o((1-b)^(-1)) as b approaches 1 forces simple support. Finite-N prefix staircases do not authorize differentiation of their limiting profile.',NULL,'audits/adversarial_reviews/effective_cluster62_prefix_inverse_moments.md §§6–7','theorems/effective_cluster62_prefix_inverse_moments.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-SELBERG-INTERFACE','theorems/theorems.jsonl',141,'adjudicated_scoped_fixed_function_GRH_conditional','audits/adversarial_reviews/effective_cluster62_selberg_transfer.md §§1–3','{"id": "EFFECTIVE-CLUSTER62-SELBERG-INTERFACE", "status": "adjudicated_scoped_fixed_function_GRH_conditional", "statement": "The explicit reciprocal, contour, disk-growth and fixed-window multiplicity budgets in §1 suffice for the RST048 retained-edge upper construction over ordinary integer coefficients. Fixed Selberg-class GRH in the zero-free-half-plane sense provides these inputs with the mesh decreased by 1/(1+d).", "locator": "audits/adversarial_reviews/effective_cluster62_selberg_transfer.md §§1–3", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_selberg_claims.jsonl", "verification": "Director,proponent,twoindependentanalyticreviews;lowerphaseprooffurtherreplacedwithoutfalsePhiL2premise.", "status_update_evidence": "audits/adversarial_reviews/director_selberg_transfer_round6.md; director_deroton_phase_round6.md"}',NULL,'The explicit reciprocal, contour, disk-growth and fixed-window multiplicity budgets in §1 suffice for the RST048 retained-edge upper construction over ordinary integer coefficients. Fixed Selberg-class GRH in the zero-free-half-plane sense provides these inputs with the mesh decreased by 1/(1+d).',NULL,'audits/adversarial_reviews/effective_cluster62_selberg_transfer.md §§1–3','theorems/effective_cluster62_selberg_claims.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-SELBERG-LOWER','theorems/theorems.jsonl',142,'adjudicated_scoped_fixed_function_GRH_conditional','audits/adversarial_reviews/effective_cluster62_selberg_transfer.md §4','{"id": "EFFECTIVE-CLUSTER62-SELBERG-LOWER", "status": "adjudicated_scoped_fixed_function_GRH_conditional", "statement": "At every fixed Selberg degree under GRH, a tested Mellin shift identifies the pole-subtracted complementary function with the critical-line inverse transform of -F(s)/s in L². De Roton Theorem 2 yields the matching liminf by continuous-to-integer scale inclusion.", "locator": "audits/adversarial_reviews/effective_cluster62_selberg_transfer.md §4", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_selberg_claims.jsonl", "verification": "Director,proponent,twoindependentanalyticreviews;lowerphaseprooffurtherreplacedwithoutfalsePhiL2premise.", "status_update_evidence": "audits/adversarial_reviews/director_selberg_transfer_round6.md; director_deroton_phase_round6.md"}',NULL,'At every fixed Selberg degree under GRH, a tested Mellin shift identifies the pole-subtracted complementary function with the critical-line inverse transform of -F(s)/s in L². De Roton Theorem 2 yields the matching liminf by continuous-to-integer scale inclusion.',NULL,'audits/adversarial_reviews/effective_cluster62_selberg_transfer.md §4','theorems/effective_cluster62_selberg_claims.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-SELBERG-OPTIMAL','theorems/theorems.jsonl',143,'adjudicated_scoped_fixed_function_GRH_conditional','audits/adversarial_reviews/effective_cluster62_selberg_transfer.md','{"id": "EFFECTIVE-CLUSTER62-SELBERG-OPTIMAL", "status": "adjudicated_scoped_fixed_function_GRH_conditional", "statement": "For each fixed Selberg-class F under its GRH, the unanchored Cauchy-boundary distance has limit (log N) Delta_N,F² equal to the sum of m_rho²/|rho|² over distinct nontrivial zeros, allowing any fixed pole order at 1.", "locator": "audits/adversarial_reviews/effective_cluster62_selberg_transfer.md", "dependencies": ["EFFECTIVE-CLUSTER62-SELBERG-INTERFACE", "EFFECTIVE-CLUSTER62-SELBERG-LOWER"], "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_selberg_claims.jsonl", "verification": "Director,proponent,twoindependentanalyticreviews;lowerphaseprooffurtherreplacedwithoutfalsePhiL2premise.", "status_update_evidence": "audits/adversarial_reviews/director_selberg_transfer_round6.md; director_deroton_phase_round6.md"}',NULL,'For each fixed Selberg-class F under its GRH, the unanchored Cauchy-boundary distance has limit (log N) Delta_N,F² equal to the sum of m_rho²/|rho|² over distinct nontrivial zeros, allowing any fixed pole order at 1.',NULL,'audits/adversarial_reviews/effective_cluster62_selberg_transfer.md','theorems/effective_cluster62_selberg_claims.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-SUZUKI-FINITE-COMPUTATION','theorems/theorems.jsonl',144,'adjudicated_scoped_with_model_and_arithmetic_boundaries','audits/adversarial_reviews/effective_cluster62_suzuki_finite_certificates.md §§1–3','{"id": "EFFECTIVE-CLUSTER62-SUZUKI-FINITE-COMPUTATION", "status": "adjudicated_scoped_with_model_and_arithmetic_boundaries", "statement": "The author-corrected Suzuki S_t is unconditionally in L². Real-axis cancellation gives a uniform bounded-time pointwise envelope of order log(2+|x|)/(1+|x|), finite norm enclosures and a local time modulus, whereas the model-space Parseval identity still requires its arithmetic positivity premise.", "locator": "audits/adversarial_reviews/effective_cluster62_suzuki_finite_certificates.md §§1–3", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_suzuki_finite_certificates.jsonl", "verification_scope": "Root plus complete independent finite-model reconstruction; no all-tail actual-zeta RH premise derived.", "status_update_evidence": "audits/adversarial_reviews/director_suzuki_finite_models_round9.md"}',NULL,'The author-corrected Suzuki S_t is unconditionally in L². Real-axis cancellation gives a uniform bounded-time pointwise envelope of order log(2+|x|)/(1+|x|), finite norm enclosures and a local time modulus, whereas the model-space Parseval identity still requires its arithmetic positivity premise.',NULL,'audits/adversarial_reviews/effective_cluster62_suzuki_finite_certificates.md §§1–3','theorems/effective_cluster62_suzuki_finite_certificates.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-SUZUKI-STRIP-DEFECT','theorems/theorems.jsonl',145,'adjudicated_scoped_unconditional_equivalence_not_verified_tail_estimate','audits/adversarial_reviews/effective_cluster62_suzuki_finite_certificates.md §3','{"id": "EFFECTIVE-CLUSTER62-SUZUKI-STRIP-DEFECT", "status": "adjudicated_scoped_unconditional_equivalence_not_verified_tail_estimate", "statement": "For ω ≥ 0, eventual Ψ(t) ≥ −C exp(ωt) is equivalent to the zero-free half-plane Re s > 1/2+ω. The same eventual upper bound on norm defect ||S_t||²/(2π)−Ψ(t) suffices. This is a global tail condition.", "locator": "audits/adversarial_reviews/effective_cluster62_suzuki_finite_certificates.md §3", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_suzuki_finite_certificates.jsonl", "director_evidence": "audits/adversarial_reviews/director_suzuki_landau_round8.md", "verification_status": "Two independent proofs and director; eventual exponential lower bound is a criterion, not established for actual Psi at a nontrivial omega.", "status_update_evidence": "audits/adversarial_reviews/director_suzuki_landau_round8.md"}',NULL,'For ω ≥ 0, eventual Ψ(t) ≥ −C exp(ωt) is equivalent to the zero-free half-plane Re s > 1/2+ω. The same eventual upper bound on norm defect ||S_t||²/(2π)−Ψ(t) suffices. This is a global tail condition.',NULL,'audits/adversarial_reviews/effective_cluster62_suzuki_finite_certificates.md §3','theorems/effective_cluster62_suzuki_finite_certificates.jsonl');
INSERT INTO "claims" VALUES('EFFECTIVE-CLUSTER62-SUZUKI-FINITE-MODEL-OBSTRUCTION','theorems/theorems.jsonl',146,'adjudicated_scoped_with_model_and_arithmetic_boundaries','audits/adversarial_reviews/effective_cluster62_suzuki_finite_certificates.md §4','{"id": "EFFECTIVE-CLUSTER62-SUZUKI-FINITE-MODEL-OBSTRUCTION", "status": "adjudicated_scoped_with_model_and_arithmetic_boundaries", "statement": "In a symmetric entire-function model, a unit off-axis quartet at large height can change both norm and kernel data by arbitrarily little on a prior bounded time interval. This does not rule out certificates using additional arithmetic structure and is not a model of actual zeta zeros.", "locator": "audits/adversarial_reviews/effective_cluster62_suzuki_finite_certificates.md §4", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/effective_cluster62_suzuki_finite_certificates.jsonl", "verification_scope": "Root plus complete independent finite-model reconstruction; no all-tail actual-zeta RH premise derived.", "status_update_evidence": "audits/adversarial_reviews/director_suzuki_finite_models_round9.md"}',NULL,'In a symmetric entire-function model, a unit off-axis quartet at large height can change both norm and kernel data by arbitrarily little on a prior bounded time interval. This does not rule out certificates using additional arithmetic structure and is not a model of actual zeta zeros.',NULL,'audits/adversarial_reviews/effective_cluster62_suzuki_finite_certificates.md §4','theorems/effective_cluster62_suzuki_finite_certificates.jsonl');
INSERT INTO "claims" VALUES('THM-E-R201','theorems/theorems.jsonl',147,'independently_derived_elementary_specialization_of_known_basis_mechanism','proposals/independent_campaigns/multicluster_uniform.md,(A),(B)','{"id": "THM-E-R201", "paper_id": null, "locator": "proposals/independent_campaigns/multicluster_uniform.md,(A),(B)", "statement": "Fix m>=1,C>=0,L=N+m,N>=0; c_j real in[-C,C], repetitions allowed. Q=product(1-exp(-ic_j/L)z), E=inf_degA<=N ||1-QA||²_H². With normalized exponential Hermite divided differences h_j=j!i^(-j)[c_1,...,c_(j+1)]exp(iux), G=integral0¹ h h*, kappa=e0*G^-1e0, s=[1+2C sqrt(m traceHilbert_m^-1)]^-1, delta=s^(2m-1)/(4traceHilbert_m^-1), D=2m(C+m), one has G>=delta I and |L E-kappa|<=(4D²+2D)/(delta² L) uniformly including all collisions and genuine smallL aliases. If L>=2D/delta the constant improves to2D/delta²+2/delta.", "status": "independently_derived_elementary_specialization_of_known_basis_mechanism", "verification": "self_contained_proof; independently_reconstructed_and_checked_by_advocate_and_parent; no_formal_verification_or_novelty_claim", "novelty": "unassessed_not_claimed", "review": "audits/adversarial_reviews/multicluster_skeptic_round2.md", "provenance_file": "theorems/equivalence_round2.jsonl"}',NULL,'Fix m>=1,C>=0,L=N+m,N>=0; c_j real in[-C,C], repetitions allowed. Q=product(1-exp(-ic_j/L)z), E=inf_degA<=N ||1-QA||²_H². With normalized exponential Hermite divided differences h_j=j!i^(-j)[c_1,...,c_(j+1)]exp(iux), G=integral0¹ h h*, kappa=e0*G^-1e0, s=[1+2C sqrt(m traceHilbert_m^-1)]^-1, delta=s^(2m-1)/(4traceHilbert_m^-1), D=2m(C+m), one has G>=delta I and |L E-kappa|<=(4D²+2D)/(delta² L) uniformly including all collisions and genuine smallL aliases. If L>=2D/delta the constant improves to2D/delta²+2/delta.',NULL,'proposals/independent_campaigns/multicluster_uniform.md,(A),(B)','theorems/equivalence_round2.jsonl');
INSERT INTO "claims" VALUES('THM-E-R202','theorems/theorems.jsonl',148,'independently_derived_elementary_exercise','proposals/independent_campaigns/multicluster_uniform.md,(C)','{"id": "THM-E-R202", "paper_id": null, "locator": "proposals/independent_campaigns/multicluster_uniform.md,(C)", "statement": "Under the same fixedm,C definitions, let B_end=(h(0)h(0)*+h(1)h(1)*)/2,v=G^-1e0,beta=v*B_end v. For L>=2D/delta, |L E-kappa+beta/(L+1)|<=[(2m+M2/12)/delta²+2D²/delta³]/L², M2=4m(C+m)², uniformly in all node collisions. Full coalescence has kappa=m²,beta=(m^4+m²)/2.", "status": "independently_derived_elementary_exercise", "verification": "self_contained_proof; independently_reconstructed_and_checked_by_advocate_and_parent; no_formal_verification_or_novelty_claim", "novelty": "unassessed_not_claimed", "review": "audits/adversarial_reviews/multicluster_skeptic_round2.md", "provenance_file": "theorems/equivalence_round2.jsonl"}',NULL,'Under the same fixedm,C definitions, let B_end=(h(0)h(0)*+h(1)h(1)*)/2,v=G^-1e0,beta=v*B_end v. For L>=2D/delta, |L E-kappa+beta/(L+1)|<=[(2m+M2/12)/delta²+2D²/delta³]/L², M2=4m(C+m)², uniformly in all node collisions. Full coalescence has kappa=m²,beta=(m^4+m²)/2.',NULL,'proposals/independent_campaigns/multicluster_uniform.md,(C)','theorems/equivalence_round2.jsonl');
INSERT INTO "claims" VALUES('THM-E-R203','theorems/theorems.jsonl',149,'independently_derived_elementary_exercise','proposals/independent_campaigns/multicluster_blocks.md,E-BLOCK-001','{"id": "THM-E-R203", "paper_id": null, "locator": "proposals/independent_campaigns/multicluster_blocks.md,E-BLOCK-001", "statement": "For p finite groups of m_a<=q real frequencies within radiusR of centers separatedbyS, totalm=sum m_a, continuous divided-difference Gram G has crossblock perturbation<=epsilon=2m(q+R)/S. If epsilon<=delta_*/2, localGram lower bounddelta_* implies |kappa_total-sum kappa_a|<=4pm(q+R)/(delta_*² S). Internal collisions allowed. No infinitegroup or growingcenter finite-grid inference.", "status": "independently_derived_elementary_exercise", "verification": "integration_by_parts_and_resolvent_proof; independent_review_pending", "novelty": "unassessed_not_claimed", "provenance_file": "theorems/equivalence_round2.jsonl"}',NULL,'For p finite groups of m_a<=q real frequencies within radiusR of centers separatedbyS, totalm=sum m_a, continuous divided-difference Gram G has crossblock perturbation<=epsilon=2m(q+R)/S. If epsilon<=delta_*/2, localGram lower bounddelta_* implies |kappa_total-sum kappa_a|<=4pm(q+R)/(delta_*² S). Internal collisions allowed. No infinitegroup or growingcenter finite-grid inference.',NULL,'proposals/independent_campaigns/multicluster_blocks.md,E-BLOCK-001','theorems/equivalence_round2.jsonl');
INSERT INTO "claims" VALUES('THM-E-R204','theorems/theorems.jsonl',150,'independently_derived_elementary_exercise','proposals/independent_campaigns/multicluster_blocks.md,E-BLOCK-002','{"id": "THM-E-R204", "paper_id": null, "locator": "proposals/independent_campaigns/multicluster_blocks.md,E-BLOCK-002", "statement": "For finitegroups m_a<=q,totalm,offsetradiusR, common residualdegreeL>=m, letdelta_*=minlocalGram bound,D_*=max2m_a(R+m_a),sigma_L=min_ab(L+1)|1-exp(i(mu_a-mu_b)/L)|,epsilon_L=2m(q+R)/sigma_L. If L>=2D_*/delta_* andepsilon_L<=delta_*/4, actual finitepolynomial optima satisfy |L E_total-sum L E_a^(same residualdegreeL)|<=8p epsilon_L/delta_*². Hence continuumconstantdifference<=p(2D_*/delta_*²+2/delta_*)/L+16pm(q+R)/(delta_*²sigma_L). Ordinary centerseparationS mayreplacephasegaponlywhen allpaircenter differences<=piL, giving sigma_L>=2S/pi.", "status": "independently_derived_elementary_exercise", "verification": "self_contained_proof; independently_reconstructed_by_advocate_before_reading_proof; no_formal_verification_or_novelty_claim", "novelty": "unassessed_not_claimed", "review": "audits/adversarial_reviews/block_and_residue_skeptic_round2.md", "provenance_file": "theorems/equivalence_round2.jsonl"}',NULL,'For finitegroups m_a<=q,totalm,offsetradiusR, common residualdegreeL>=m, letdelta_*=minlocalGram bound,D_*=max2m_a(R+m_a),sigma_L=min_ab(L+1)|1-exp(i(mu_a-mu_b)/L)|,epsilon_L=2m(q+R)/sigma_L. If L>=2D_*/delta_* andepsilon_L<=delta_*/4, actual finitepolynomial optima satisfy |L E_total-sum L E_a^(same residualdegreeL)|<=8p epsilon_L/delta_*². Hence continuumconstantdifference<=p(2D_*/delta_*²+2/delta_*)/L+16pm(q+R)/(delta_*²sigma_L). Ordinary centerseparationS mayreplacephasegaponlywhen allpaircenter differences<=piL, giving sigma_L>=2S/pi.',NULL,'proposals/independent_campaigns/multicluster_blocks.md,E-BLOCK-002','theorems/equivalence_round2.jsonl');
INSERT INTO "claims" VALUES('THM-E-R205','theorems/theorems.jsonl',151,'established_interpolation_identity_specialized_to_source_kernel','proposals/independent_campaigns/grouped_residue_divided_differences.md,R1–R3','{"id": "THM-E-R205", "paper_id": null, "locator": "proposals/independent_campaigns/grouped_residue_divided_differences.md,R1–R3", "statement": "On an openconvex zeta-pole-free domainU with finite zero multisetC of sizem and no otherzeros, factorzeta=q_C g_C. ForN>1,s outsideU, the grouped BCF residuekernel sum equals HermiteDD_C F_C, F_C=N^(z-s)/[(z-s)²g_C]. Hence modulus<=sup_convexhull|F_C^(m-1)|/(m-1)!. If the radiusr hull-neighborhood liescompactlyinU ands liesoutsideit, a Cauchy bound gives <=N^b M/(d²r^(m-1)), with M=sup|1/g_C|,d=distance(s,neighborhood),b=maxRe(z-s). No arithmetic bound onM or infinite sum is established.", "status": "established_interpolation_identity_specialized_to_source_kernel", "source_provenance": ["PAPER-E003 Lemma2", "PAPER-E005 Eq51,Eq52"], "verification": "self_contained_proof; independently_reconstructed_by_advocate_before_reading_proof; no_formal_verification_or_novelty_claim", "novelty": "not_claimed", "review": "audits/adversarial_reviews/block_and_residue_skeptic_round2.md", "provenance_file": "theorems/equivalence_round2.jsonl"}',NULL,'On an openconvex zeta-pole-free domainU with finite zero multisetC of sizem and no otherzeros, factorzeta=q_C g_C. ForN>1,s outsideU, the grouped BCF residuekernel sum equals HermiteDD_C F_C, F_C=N^(z-s)/[(z-s)²g_C]. Hence modulus<=sup_convexhull|F_C^(m-1)|/(m-1)!. If the radiusr hull-neighborhood liescompactlyinU ands liesoutsideit, a Cauchy bound gives <=N^b M/(d²r^(m-1)), with M=sup|1/g_C|,d=distance(s,neighborhood),b=maxRe(z-s). No arithmetic bound onM or infinite sum is established.',NULL,'proposals/independent_campaigns/grouped_residue_divided_differences.md,R1–R3','theorems/equivalence_round2.jsonl');
INSERT INTO "claims" VALUES('THM-E-R206','theorems/theorems.jsonl',152,'elementary_negative_deduction_from_classical_source_input','proposals/independent_campaigns/global_density_obstruction.md,E-DENSITY-001','{"id": "THM-E-R206", "paper_id": null, "locator": "proposals/independent_campaigns/global_density_obstruction.md,E-DENSITY-001", "statement": "From Riemann-vonMangoldt N(T)~TlogT/(2pi), the multisetofpositivezeroordinates (or any fixedlinearscaling) is not a finiteunionofuniformlyseparated sequences, cannot have a covering by fixedradius clustersofuniformlyboundedsize withuniformlyseparatedcenters, and its unweightedpureexponentials onL²(0,1) admit no positiveuniformRieszlowerbound. Doesnot exclude weighted/growingcluster/heightdependent alternatives.", "status": "elementary_negative_deduction_from_classical_source_input", "source_provenance": ["PAPER-E003 Lemma3 proof pp6–7 zero-count asymptotic", "PAPER-E006 globalhypothesis comparison only"], "verification": "counting_and_two_exponential_proof; independent_review_pending", "novelty": "not_claimed", "provenance_file": "theorems/equivalence_round2.jsonl"}',NULL,'From Riemann-vonMangoldt N(T)~TlogT/(2pi), the multisetofpositivezeroordinates (or any fixedlinearscaling) is not a finiteunionofuniformlyseparated sequences, cannot have a covering by fixedradius clustersofuniformlyboundedsize withuniformlyseparatedcenters, and its unweightedpureexponentials onL²(0,1) admit no positiveuniformRieszlowerbound. Doesnot exclude weighted/growingcluster/heightdependent alternatives.',NULL,'proposals/independent_campaigns/global_density_obstruction.md,E-DENSITY-001','theorems/equivalence_round2.jsonl');
INSERT INTO "claims" VALUES('THM-E001','theorems/theorems.jsonl',153,'established_source_result','Expanded arXiv:math/0205003v1 Theorem1.1, pp1–2; journal Theorem1, p5, proof pp6–9','{"id": "THM-E001", "paper_id": "PAPER-E014", "locator": "Expanded arXiv:math/0205003v1 Theorem1.1, pp1–2; journal Theorem1, p5, proof pp6–9", "statement": "In H=L²((0,infinity),dx), let rho_a(x)={1/(a x)}, chi=1_(0,1], and B_nat=span{rho_a:a in positive integers}. RH iff chi belongs to the H closure of B_nat (Theorem1.1, pp.1–2).", "status": "established_source_result", "verification": "Complete journal and preprint comparison; main equivalence reconstructed in the version-pinned whole-work audit. Work alias does not alter historical theorem numbering.", "provenance_file": "theorems/equivalence_track.jsonl", "source_manifestation": "VERSION-BAEZ-MAY", "director_evidence": "audits/adversarial_reviews/director_baez_whole_round13.md", "status_update_evidence": "audits/adversarial_reviews/director_baez_whole_round13.md"}','PAPER-E014','In H=L²((0,infinity),dx), let rho_a(x)={1/(a x)}, chi=1_(0,1], and B_nat=span{rho_a:a in positive integers}. RH iff chi belongs to the H closure of B_nat (Theorem1.1, pp.1–2).',NULL,'Expanded arXiv:math/0205003v1 Theorem1.1, pp1–2; journal Theorem1, p5, proof pp6–9','theorems/equivalence_track.jsonl');
INSERT INTO "claims" VALUES('THM-E002','theorems/theorems.jsonl',154,'established_source_result','Theorem1.3 p.4 and Theorem5.5 pp.15–16','{"id": "THM-E002", "paper_id": "PAPER-E002", "locator": "Theorem1.3 p.4 and Theorem5.5 pp.15–16", "statement": "For B_lambda=span{{theta/t}:lambda<=theta<=1} in L²((0,infinity),dt), D(lambda)=dist(chi,B_lambda), liminf_{lambda↓0}D(lambda)*sqrt(log(1/lambda)) >= sqrt(sum_rho m_rho²/|rho|²) (Theorem1.3 p.4; Theorem5.5 pp.15–16). Proof assumes RH, since its failure makes the left side infinite; rho are distinct nontrivial zeros under that assumption.", "status": "established_source_result", "verification": "read_not_fully_reproved", "provenance_file": "theorems/equivalence_track.jsonl"}','PAPER-E002','For B_lambda=span{{theta/t}:lambda<=theta<=1} in L²((0,infinity),dt), D(lambda)=dist(chi,B_lambda), liminf_{lambda↓0}D(lambda)*sqrt(log(1/lambda)) >= sqrt(sum_rho m_rho²/|rho|²) (Theorem1.3 p.4; Theorem5.5 pp.15–16). Proof assumes RH, since its failure makes the left side infinite; rho are distinct nontrivial zeros under that assumption.',NULL,'Theorem1.3 p.4 and Theorem5.5 pp.15–16','theorems/equivalence_track.jsonl');
INSERT INTO "claims" VALUES('THM-E003','theorems/theorems.jsonl',155,'established_source_result','Theorem1.4 p.4 and §2 pp.4–6','{"id": "THM-E003", "paper_id": "PAPER-E002", "locator": "Theorem1.4 p.4 and §2 pp.4–6", "statement": "Theorem1.4: Q of positive degree with all roots alpha on the unit circle, multiplicities m_alpha, and fixed target polynomial P gives lim N inf_deg A<=N ||P-QA||²=sum_alpha m_alpha²|P(alpha)|².", "status": "established_source_result", "verification": "finite_projection_mechanism_reconstructed", "provenance_file": "theorems/equivalence_track.jsonl"}','PAPER-E002','Theorem1.4: Q of positive degree with all roots alpha on the unit circle, multiplicities m_alpha, and fixed target polynomial P gives lim N inf_deg A<=N ||P-QA||²=sum_alpha m_alpha²|P(alpha)|².',NULL,'Theorem1.4 p.4 and §2 pp.4–6','theorems/equivalence_track.jsonl');
INSERT INTO "claims" VALUES('THM-E004','theorems/theorems.jsonl',156,'established_conditional_source_result','Theorem1 p.2','{"id": "THM-E004", "paper_id": "PAPER-E003", "locator": "Theorem1 p.2", "statement": "Assume RH and sum_{|Im rho|<=T}|zeta''(rho)|^(-2)<<T^(3/2-delta) for some delta>0. For V_N(s)=sum_{n<=N}(1-log n/log N)mu(n)n^(-s), N>1, its squared weighted critical-line error (1/(2pi))integral_R |1-zeta(1/2+it)V_N(1/2+it)|² dt/(1/4+t²) is asymptotic to (2+gamma-log(4pi))/log N (Theorem1,p.2). Moment hypothesis forces simple zeros.", "status": "established_conditional_source_result", "verification": "read_not_fully_reproved", "provenance_file": "theorems/equivalence_track.jsonl"}','PAPER-E003','Assume RH and sum_{|Im rho|<=T}|zeta''(rho)|^(-2)<<T^(3/2-delta) for some delta>0. For V_N(s)=sum_{n<=N}(1-log n/log N)mu(n)n^(-s), N>1, its squared weighted critical-line error (1/(2pi))integral_R |1-zeta(1/2+it)V_N(1/2+it)|² dt/(1/4+t²) is asymptotic to (2+gamma-log(4pi))/log N (Theorem1,p.2). Moment hypothesis forces simple zeros.',NULL,'Theorem1 p.2','theorems/equivalence_track.jsonl');
INSERT INTO "claims" VALUES('THM-E005','theorems/theorems.jsonl',157,'independently_derived_exercise','proposals/independent_campaigns/multiplicity_adapted_smoothing.md, E-TOY-001','{"id": "THM-E005", "paper_id": null, "locator": "proposals/independent_campaigns/multiplicity_adapted_smoothing.md, E-TOY-001", "statement": "For Q=(1-z)^2, BCF linear reciprocal window has exact squared H² error 1+4/N, N>=1.", "status": "independently_derived_exercise", "verification": "scoped_Level3; audits/adversarial_reviews/director_adjudication.md", "provenance_file": "theorems/equivalence_track.jsonl"}',NULL,'For Q=(1-z)^2, BCF linear reciprocal window has exact squared H² error 1+4/N, N>=1.',NULL,'proposals/independent_campaigns/multiplicity_adapted_smoothing.md, E-TOY-001','theorems/equivalence_track.jsonl');
INSERT INTO "claims" VALUES('THM-E006','theorems/theorems.jsonl',158,'independently_derived_exercise','proposals/independent_campaigns/multiplicity_adapted_smoothing.md, E-TOY-002','{"id": "THM-E006", "paper_id": null, "locator": "proposals/independent_campaigns/multiplicity_adapted_smoothing.md, E-TOY-002", "statement": "For Q=(1-z)^2 and degree bound N>=0, optimal coefficients are (n+1)(L-n)(L-n-1)/((L+1)(L+2)), L=N+2; squared distance is 2(2L+1)/((L+1)(L+2)).", "status": "independently_derived_exercise", "verification": "scoped_Level3; audits/adversarial_reviews/director_adjudication.md", "provenance_file": "theorems/equivalence_track.jsonl"}',NULL,'For Q=(1-z)^2 and degree bound N>=0, optimal coefficients are (n+1)(L-n)(L-n-1)/((L+1)(L+2)), L=N+2; squared distance is 2(2L+1)/((L+1)(L+2)).',NULL,'proposals/independent_campaigns/multiplicity_adapted_smoothing.md, E-TOY-002','theorems/equivalence_track.jsonl');
INSERT INTO "claims" VALUES('THM-E007','theorems/theorems.jsonl',159,'independently_derived_exercise','proposals/independent_campaigns/clustered_root_transition.md,E-CLUSTER-001','{"id": "THM-E007", "paper_id": null, "locator": "proposals/independent_campaigns/clustered_root_transition.md,E-CLUSTER-001", "statement": "For Q_theta=(1-z)(1-exp(-i theta)z), degree bound N, L=N+2,d=L+1,S=sum exp(i k theta), k=0..L, theta not multiple2pi, squared optimal H² error=(2d-2ReS)/(d²-|S|²).", "status": "independently_derived_exercise", "verification": "independent_director_reconstruction; cluster_skeptic review where present", "provenance_file": "theorems/equivalence_track.jsonl"}',NULL,'For Q_theta=(1-z)(1-exp(-i theta)z), degree bound N, L=N+2,d=L+1,S=sum exp(i k theta), k=0..L, theta not multiple2pi, squared optimal H² error=(2d-2ReS)/(d²-|S|²).',NULL,'proposals/independent_campaigns/clustered_root_transition.md,E-CLUSTER-001','theorems/equivalence_track.jsonl');
INSERT INTO "claims" VALUES('THM-E008','theorems/theorems.jsonl',160,'independently_derived_exercise','proposals/independent_campaigns/clustered_root_transition.md,E-CLUSTER-002','{"id": "THM-E008", "paper_id": null, "locator": "proposals/independent_campaigns/clustered_root_transition.md,E-CLUSTER-002", "statement": "For fixed c!=0, L E_N(c/L) tends to (2-2sin(c)/c)/(1-(2sin(c/2)/c)^2), extending to4 at c=0 and tending to2 as |c|→infinity.", "status": "independently_derived_exercise", "verification": "independent_director_reconstruction; cluster_skeptic review where present", "provenance_file": "theorems/equivalence_track.jsonl"}',NULL,'For fixed c!=0, L E_N(c/L) tends to (2-2sin(c)/c)/(1-(2sin(c/2)/c)^2), extending to4 at c=0 and tending to2 as |c|→infinity.',NULL,'proposals/independent_campaigns/clustered_root_transition.md,E-CLUSTER-002','theorems/equivalence_track.jsonl');
INSERT INTO "claims" VALUES('THM-E009','theorems/theorems.jsonl',161,'independently_derived_exercise','proposals/independent_campaigns/clustered_root_transition.md,E-CLUSTER-003','{"id": "THM-E009", "paper_id": null, "locator": "proposals/independent_campaigns/clustered_root_transition.md,E-CLUSTER-003", "statement": "For the two-root polynomial Q_theta, triangular reciprocal window squared error equals [2N+2ReT+|T|²]/N², T=sum_{k=1}^N exp(-ik theta). If theta=c/N, it tends (2sin(c/2)/c)², whereas the optimum tends0.", "status": "independently_derived_exercise", "verification": "independent_director_reconstruction; cluster_skeptic review where present", "provenance_file": "theorems/equivalence_track.jsonl"}',NULL,'For the two-root polynomial Q_theta, triangular reciprocal window squared error equals [2N+2ReT+|T|²]/N², T=sum_{k=1}^N exp(-ik theta). If theta=c/N, it tends (2sin(c/2)/c)², whereas the optimum tends0.',NULL,'proposals/independent_campaigns/clustered_root_transition.md,E-CLUSTER-003','theorems/equivalence_track.jsonl');
INSERT INTO "claims" VALUES('THM-E010','theorems/theorems.jsonl',162,'independently_derived_elementary_exercise','proposals/independent_campaigns/uniform_cluster_remainder.md, E-UNIFORM-001','{"id": "THM-E010", "paper_id": null, "locator": "proposals/independent_campaigns/uniform_cluster_remainder.md, E-UNIFORM-001", "statement": "For every C>=0,N>=0,L=N+2, |c|<=C, the actual optimum E_N for Q_theta=(1-z)(1-exp(-i theta)z) satisfies |L E_N(c/L)-F(c)|<=38(12+C²)²/L, where F(c)=(2-2sin(c)/c)/(1-(2sin(c/2)/c)²), F(0)=4; aliases use the true double-root optimum. If L>=6(12+C²), the bound improves to [2(12+C²)²+5(12+C²)]/L.", "status": "independently_derived_elementary_exercise", "verification": "scoped_Level3; audits/adversarial_reviews/director_adjudication.md", "review": "audits/adversarial_reviews/uniform_cluster_skeptic.md", "computational_evidence": "experiments/results/uniform_cluster_remainder.json; exploratory_float_only", "provenance_file": "theorems/equivalence_track.jsonl"}',NULL,'For every C>=0,N>=0,L=N+2, |c|<=C, the actual optimum E_N for Q_theta=(1-z)(1-exp(-i theta)z) satisfies |L E_N(c/L)-F(c)|<=38(12+C²)²/L, where F(c)=(2-2sin(c)/c)/(1-(2sin(c/2)/c)²), F(0)=4; aliases use the true double-root optimum. If L>=6(12+C²), the bound improves to [2(12+C²)²+5(12+C²)]/L.',NULL,'proposals/independent_campaigns/uniform_cluster_remainder.md, E-UNIFORM-001','theorems/equivalence_track.jsonl');
INSERT INTO "claims" VALUES('THM-F001','theorems/theorems.jsonl',163,'All209010 inequalities independently checked in exact Fraction arithmetic with parent-reviewed analytic mean-value/Taylor derivation; not Lean checked.','experiments/results/independent_kernel_cells.json; audits/adversarial_reviews/kernel_cell_reconstruction_round2.md','{"theorem_id": "THM-F001", "paper_id": "PAPER-A005", "locator": "First-window frozen kernel table; independently reconstructed Kernel/Sound construction", "kind": "scoped exact computational verification of established certificate", "statement": "Let f(u)=(1+sum_{j=1}^6 a_j cos(2pi j u))1_{[-1/2,1/2]} with a=(193305,-23105,29166,13952,-21009,41052)/10^6 and K(t)=integral f(u)e^{-2pi iut}du. For every integer0<=k<=209009 and every real t in[k/16384,(k+1)/16384], the k-th supplied binary integer divided by2^28 is<=K(t)^2.", "verification_status": "All209010 inequalities independently checked in exact Fraction arithmetic with parent-reviewed analytic mean-value/Taylor derivation; not Lean checked.", "evidence": "experiments/results/independent_kernel_cells.json; audits/adversarial_reviews/kernel_cell_reconstruction_round2.md", "source_identity": "kristianmk/839@0e961ea199b425010843bc8044676d4ad29fe031", "novelty": "No novelty claimed; independent certificate reproduction.", "id": "THM-F001", "provenance_file": "theorems/formal_round2.jsonl"}','PAPER-A005','Let f(u)=(1+sum_{j=1}^6 a_j cos(2pi j u))1_{[-1/2,1/2]} with a=(193305,-23105,29166,13952,-21009,41052)/10^6 and K(t)=integral f(u)e^{-2pi iut}du. For every integer0<=k<=209009 and every real t in[k/16384,(k+1)/16384], the k-th supplied binary integer divided by2^28 is<=K(t)^2.','scoped exact computational verification of established certificate','First-window frozen kernel table; independently reconstructed Kernel/Sound construction','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F002','theorems/theorems.jsonl',164,'Hand-derived from h''''=2f and cosine orthogonality; exact arithmetic confirms source first-window C<266541/200000 and q=1645064/1960733.','experiments/results/cosine_window_energy_check.json; audits/adversarial_reviews/kernel_cell_reconstruction_round2.md','{"theorem_id": "THM-F002", "paper_id": "PAPER-A005", "locator": "Independent cosine-window energy reconstruction", "kind": "elementary independently reconstructed lemma", "statement": "For any finite real coefficients a_j and f(u)=(1+sum_j a_j cos(2pi j u))1_{[-1/2,1/2]}, integral f^2+doubleintegral |x-y|f(x)f(y)dxdy=4/3+sum_j a_j^2/2+pi^{-2}sum_j[(-1)^j a_j/j^2-a_j^2/(4j^2)].", "verification_status": "Hand-derived from h''''=2f and cosine orthogonality; exact arithmetic confirms source first-window C<266541/200000 and q=1645064/1960733.", "evidence": "experiments/results/cosine_window_energy_check.json; audits/adversarial_reviews/kernel_cell_reconstruction_round2.md", "novelty": "No novelty or publication priority claimed.", "id": "THM-F002", "provenance_file": "theorems/formal_round2.jsonl"}','PAPER-A005','For any finite real coefficients a_j and f(u)=(1+sum_j a_j cos(2pi j u))1_{[-1/2,1/2]}, integral f^2+doubleintegral |x-y|f(x)f(y)dxdy=4/3+sum_j a_j^2/2+pi^{-2}sum_j[(-1)^j a_j/j^2-a_j^2/(4j^2)].','elementary independently reconstructed lemma','Independent cosine-window energy reconstruction','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F003','theorems/theorems.jsonl',165,'Original full C++ search reproduced, all table cells independently validated, acceptance rules independently reconstructed by skeptic and inspected by proposer; director adjudication pending. Not Lean checked here.','experiments/results/839_reference_rerun.json; experiments/results/independent_kernel_cells.json; audits/adversarial_reviews/839_search_skeptic_round2.md','{"theorem_id": "THM-F003", "paper_id": "PAPER-A005", "locator": "Distinct839/Defs.lean162–172 at pinned arXiv-v1 source", "kind": "scoped computational local-inequality reconstruction", "statement": "For all real gaps g_0,...,g_5>=17/20 and every labeling ell:{0,...,6}->{0,1}, sum_i h[ell_i][i]/10^6 <= (6219/10^6)sum_r g_r + sum_{i<j}W[ell_i+ell_j][pair(i,j)]K(y_j-y_i)^2/10^6 + sum_r B_r^{ell_r+ell_{r+1}}(g_r), where y_i=sum_{r<i}g_r, W,h and knot ordinates are exactly experiments/inputs/839_first_window/inputs.json, pair order is increasing lexicographic(i,j), and B interpolates cob_knots/10^6 at3/4+k/8 and is zero outside[3/4,19/8]. K is THM-F001''s explicit kernel.", "verification_status": "Original full C++ search reproduced, all table cells independently validated, acceptance rules independently reconstructed by skeptic and inspected by proposer; director adjudication pending. Not Lean checked here.", "evidence": "experiments/results/839_reference_rerun.json; experiments/results/independent_kernel_cells.json; audits/adversarial_reviews/839_search_skeptic_round2.md", "novelty": "Independent checking of a source certificate, not a new number-theoretic result; zeta transfer is outside this statement.", "id": "THM-F003", "provenance_file": "theorems/formal_round2.jsonl"}','PAPER-A005','For all real gaps g_0,...,g_5>=17/20 and every labeling ell:{0,...,6}->{0,1}, sum_i h[ell_i][i]/10^6 <= (6219/10^6)sum_r g_r + sum_{i<j}W[ell_i+ell_j][pair(i,j)]K(y_j-y_i)^2/10^6 + sum_r B_r^{ell_r+ell_{r+1}}(g_r), where y_i=sum_{r<i}g_r, W,h and knot ordinates are exactly experiments/inputs/839_first_window/inputs.json, pair order is increasing lexicographic(i,j), and B interpolates cob_knots/10^6 at3/4+k/8 and is zero outside[3/4,19/8]. K is THM-F001''s explicit kernel.','scoped computational local-inequality reconstruction','Distinct839/Defs.lean162–172 at pinned arXiv-v1 source','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F004','theorems/theorems.jsonl',166,'All262144 cells and energy cap checked by exact Fraction arithmetic using previously reviewed analytic bounds; not Lean checked.','experiments/results/independent_kernel_cells_second_third.json; experiments/inputs/839_second_window/PROVENANCE.json','{"theorem_id": "THM-F004", "paper_id": "PAPER-A005", "locator": "Simple673/Defs.lean and frozen second-window table", "kind": "scoped exact certificate reproduction", "statement": "For f(u)=(1+sum_{j=1}^{10}a_j cos(2pi j u))1_{[-1/2,1/2]}, a=(122290,-45012,16241,1887,2711,3731,-5307,2982,-5153,5358)/10^6, K=Fourier(f), every second-window table entry at integer0<=k<=262143 divided by2^28 is<=K(t)^2 throughout t in[k/16384,(k+1)/16384]. Also C(f)<6639737/5000000.", "verification_status": "All262144 cells and energy cap checked by exact Fraction arithmetic using previously reviewed analytic bounds; not Lean checked.", "evidence": "experiments/results/independent_kernel_cells_second_third.json; experiments/inputs/839_second_window/PROVENANCE.json", "novelty": "None claimed; source certificate reproduction.", "id": "THM-F004", "provenance_file": "theorems/formal_round2.jsonl"}','PAPER-A005','For f(u)=(1+sum_{j=1}^{10}a_j cos(2pi j u))1_{[-1/2,1/2]}, a=(122290,-45012,16241,1887,2711,3731,-5307,2982,-5153,5358)/10^6, K=Fourier(f), every second-window table entry at integer0<=k<=262143 divided by2^28 is<=K(t)^2 throughout t in[k/16384,(k+1)/16384]. Also C(f)<6639737/5000000.','scoped exact certificate reproduction','Simple673/Defs.lean and frozen second-window table','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F005','theorems/theorems.jsonl',167,'All262144 cells and energy cap checked by exact Fraction arithmetic using previously reviewed analytic bounds; not Lean checked.','experiments/results/independent_kernel_cells_second_third.json; experiments/inputs/839_third_window/PROVENANCE.json','{"theorem_id": "THM-F005", "paper_id": "PAPER-A005", "locator": "Line889/Defs.lean and frozen third-window table", "kind": "scoped exact certificate reproduction", "statement": "For f(u)=(1+sum_{j=1}^{6}a_j cos(2pi j u))1_{[-1/2,1/2]}, a=(200566,19,-9358,9283,-6746,8170)/10^6, K=Fourier(f), every third-window table entry at integer0<=k<=262143 divided by2^28 is<=K(t)^2 throughout t in[k/16384,(k+1)/16384]. Also C(f)<6662319/5000000.", "verification_status": "All262144 cells and energy cap checked by exact Fraction arithmetic using previously reviewed analytic bounds; not Lean checked.", "evidence": "experiments/results/independent_kernel_cells_second_third.json; experiments/inputs/839_third_window/PROVENANCE.json", "novelty": "None claimed; source certificate reproduction.", "id": "THM-F005", "provenance_file": "theorems/formal_round2.jsonl"}','PAPER-A005','For f(u)=(1+sum_{j=1}^{6}a_j cos(2pi j u))1_{[-1/2,1/2]}, a=(200566,19,-9358,9283,-6746,8170)/10^6, K=Fourier(f), every third-window table entry at integer0<=k<=262143 divided by2^28 is<=K(t)^2 throughout t in[k/16384,(k+1)/16384]. Also C(f)<6662319/5000000.','scoped exact certificate reproduction','Line889/Defs.lean and frozen third-window table','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F006','theorems/theorems.jsonl',168,'adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay','proposals/independent_campaigns/finite_transfer_boundary_round2.md; audits/adversarial_reviews/839_transfer_skeptic_round2.md; experiments/results/839_transfer_boundary_core.json','{"theorem_id": "THM-F006", "paper_id": "PAPER-A005", "kind": "conditional finite transfer strengthening", "statement": "With the exact first-window data of experiments/inputs/839_first_window/inputs.json and the seven-point local inequality THM-F003 as hypothesis, every theta=17/20 separated finite chain of ell sites with multiplicity labels1or2 and symmetric nonnegative near-pair energies e_ij>=K(y_j-y_i)^2-epsilon has E_near>=sum_i reward(label_i)-6alpha*R-516027/2000000-48epsilon*ell, where alpha=6219/10^6, rewards x=54350/10^6,y=69433/10^6, R>=spread, E_near sums ordered pairs0<|i-j|<=6 weighted m_i*m_j. This replaces the source finite boundary6y+Omega=0.432480 by0.2580135. A directed/signed near-energy version uses exact symmetrized defects2sum_near_unordered m_i*m_j*delta_ij instead of48epsilon*ell. To extend to all pairs require nonnegative symmetrized far energy.", "verification_status": "adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay", "evidence": "proposals/independent_campaigns/finite_transfer_boundary_round2.md; audits/adversarial_reviews/839_transfer_skeptic_round2.md; experiments/results/839_transfer_boundary_core.json", "novelty": "No literature novelty established, no asymptotic zero proportion improvement. Generic extension requires y>=6alpha*theta, with explicit counterexample otherwise.", "director_adjudication": "Accepted at the explicit scoped conditional-reconstruction level; audits/adversarial_reviews/director_round3_adjudication.md", "id": "THM-F006", "locator": "proposals/independent_campaigns/finite_transfer_boundary_round2.md; audits/adversarial_reviews/839_transfer_skeptic_round2.md; experiments/results/839_transfer_boundary_core.json", "provenance_file": "theorems/formal_round2.jsonl", "verification": "scoped_Level3; independent proposer/skeptic/director ordinary reconstruction; exact scope in adjudication", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}','PAPER-A005','With the exact first-window data of experiments/inputs/839_first_window/inputs.json and the seven-point local inequality THM-F003 as hypothesis, every theta=17/20 separated finite chain of ell sites with multiplicity labels1or2 and symmetric nonnegative near-pair energies e_ij>=K(y_j-y_i)^2-epsilon has E_near>=sum_i reward(label_i)-6alpha*R-516027/2000000-48epsilon*ell, where alpha=6219/10^6, rewards x=54350/10^6,y=69433/10^6, R>=spread, E_near sums ordered pairs0<|i-j|<=6 weighted m_i*m_j. This replaces the source finite boundary6y+Omega=0.432480 by0.2580135. A directed/signed near-energy version uses exact symmetrized defects2sum_near_unordered m_i*m_j*delta_ij instead of48epsilon*ell. To extend to all pairs require nonnegative symmetrized far energy.','conditional finite transfer strengthening','proposals/independent_campaigns/finite_transfer_boundary_round2.md; audits/adversarial_reviews/839_transfer_skeptic_round2.md; experiments/results/839_transfer_boundary_core.json','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F007','theorems/theorems.jsonl',169,'adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay','audits/adversarial_reviews/analytic_trace_buffer_round2.md; audits/adversarial_reviews/AF_trace_localization_skeptic_round2.md','{"theorem_id": "THM-F007", "paper_id": "PAPER-A004", "related_paper_id": "PAPER-A007", "kind": "scoped replacement trace localization lemma", "statement": "For the original fixed real even AF C2 window of support[-L/2,L/2], bounded supremum, a>=a0>0, uniform Fourier decayO(exp(L|Imz|/2)|Rez|^-2), L=log(T/(2pi)), h=2pi/L,d=floor(T/h), and nontrivial zeta zeros counted with multiplicity, let G_U=(aL^2)^-1 sum_{T-U<=Re gamma<2T+U}m_gamma v_gamma v_gamma^T for0<=U<=T/2. Then trG_U=N([T,2T))+O(sqrt(T)) uniformlyU; hence trG_U=N([T-U,2T+U))+O(sqrt(T)+(U+1)L). Constants may depend on fixed window and classical local count.", "verification_status": "adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay", "evidence": "audits/adversarial_reviews/analytic_trace_buffer_round2.md; audits/adversarial_reviews/AF_trace_localization_skeptic_round2.md", "novelty": "No novelty claimed; repairs a printed geometric step without refuting its trace conclusion or main theorem.", "director_adjudication": "Accepted at the explicit scoped conditional-reconstruction level; audits/adversarial_reviews/director_round3_adjudication.md", "id": "THM-F007", "locator": "audits/adversarial_reviews/analytic_trace_buffer_round2.md; audits/adversarial_reviews/AF_trace_localization_skeptic_round2.md", "provenance_file": "theorems/formal_round2.jsonl", "verification": "scoped_Level3; independent proposer/skeptic/director ordinary reconstruction; exact scope in adjudication", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}','PAPER-A004','For the original fixed real even AF C2 window of support[-L/2,L/2], bounded supremum, a>=a0>0, uniform Fourier decayO(exp(L|Imz|/2)|Rez|^-2), L=log(T/(2pi)), h=2pi/L,d=floor(T/h), and nontrivial zeta zeros counted with multiplicity, let G_U=(aL^2)^-1 sum_{T-U<=Re gamma<2T+U}m_gamma v_gamma v_gamma^T for0<=U<=T/2. Then trG_U=N([T,2T))+O(sqrt(T)) uniformlyU; hence trG_U=N([T-U,2T+U))+O(sqrt(T)+(U+1)L). Constants may depend on fixed window and classical local count.','scoped replacement trace localization lemma','audits/adversarial_reviews/analytic_trace_buffer_round2.md; audits/adversarial_reviews/AF_trace_localization_skeptic_round2.md','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F008','theorems/theorems.jsonl',170,'adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay','proposals/independent_campaigns/zero_buffer_localization_round2.md; audits/adversarial_reviews/AF_zero_buffer_skeptic_round2.md; audits/adversarial_reviews/AF_zero_buffer_VK_skeptic_round2.md; PAPER-A006§2p6','{"theorem_id": "THM-F008", "paper_id": "PAPER-A004", "related_paper_ids": ["PAPER-A006", "PAPER-A007"], "kind": "conditional truncation hypothesis weakening", "statement": "For THM-F007 window/grid, form G_0 with zeros inI=[T,2T) only and E_0 with all other nontrivial zeta zeros. Then nuclear series converges absolutely and ||E_0||_1=O(sqrt(T)). Conditional on ||G_0+E_0||_HS^2=R(psi)N+O(NlogL/L), N~TL, one gets ||G_0||_HS^2=R(psi)N+O(N/sqrtL), so the original limiting simple-critical and distinct constants follow without a buffer. Importing the classical Vinogradov-Korobov strip beta in[delta(|gamma|),1-delta(|gamma|)], delta(t)=c(logt)^(-2/3)(loglogt)^(-1/3), improves the nuclear error toO(sqrt(T)exp(-c_prime L^(1/3)/(logL)^(1/3)))+O(T^(-3/2))=O_A(sqrt(T)L^(-A)) for everyfixedA; this preserves the given prime-sideO(NlogL/L)rate.", "verification_status": "adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay", "evidence": "proposals/independent_campaigns/zero_buffer_localization_round2.md; audits/adversarial_reviews/AF_zero_buffer_skeptic_round2.md; audits/adversarial_reviews/AF_zero_buffer_VK_skeptic_round2.md; PAPER-A006§2p6", "novelty": "No improved limiting proportion or literature novelty claimed; this changes a truncation proof requirement.", "director_adjudication": "Accepted at the explicit scoped conditional-reconstruction level; audits/adversarial_reviews/director_round3_adjudication.md", "id": "THM-F008", "locator": "proposals/independent_campaigns/zero_buffer_localization_round2.md; audits/adversarial_reviews/AF_zero_buffer_skeptic_round2.md; audits/adversarial_reviews/AF_zero_buffer_VK_skeptic_round2.md; PAPER-A006§2p6", "provenance_file": "theorems/formal_round2.jsonl", "verification": "scoped_Level3; independent proposer/skeptic/director ordinary reconstruction; exact scope in adjudication", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}','PAPER-A004','For THM-F007 window/grid, form G_0 with zeros inI=[T,2T) only and E_0 with all other nontrivial zeta zeros. Then nuclear series converges absolutely and ||E_0||_1=O(sqrt(T)). Conditional on ||G_0+E_0||_HS^2=R(psi)N+O(NlogL/L), N~TL, one gets ||G_0||_HS^2=R(psi)N+O(N/sqrtL), so the original limiting simple-critical and distinct constants follow without a buffer. Importing the classical Vinogradov-Korobov strip beta in[delta(|gamma|),1-delta(|gamma|)], delta(t)=c(logt)^(-2/3)(loglogt)^(-1/3), improves the nuclear error toO(sqrt(T)exp(-c_prime L^(1/3)/(logL)^(1/3)))+O(T^(-3/2))=O_A(sqrt(T)L^(-A)) for everyfixedA; this preserves the given prime-sideO(NlogL/L)rate.','conditional truncation hypothesis weakening','proposals/independent_campaigns/zero_buffer_localization_round2.md; audits/adversarial_reviews/AF_zero_buffer_skeptic_round2.md; audits/adversarial_reviews/AF_zero_buffer_VK_skeptic_round2.md; PAPER-A006§2p6','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F009','theorems/theorems.jsonl',171,'Actual local source build succeeded; actual type/axiom query exited0, dependencies only propext,Classical.choice,Quot.sound. Not external independent-kernel replay.','experiments/results/formal_ranktrace_summary.json','{"theorem_id": "THM-F009", "paper_id": "PAPER-A004", "locator": "Zeta23/LinAlg/RankTrace.lean at commit3635e74826a4c1fcece7d1cd2b6fa75e43a00510", "kind": "source algebra theorem locally checked by Lean", "statement": "For any RCLike field, finite Hermitian matricesP,Q withP positive semidefinite, rankP<=r, positive inertia index(Q)<=b and realc>0, c trP-(c^2/4)r+2c trQ-c^2 b<=||P+Q||_HS^2. The c=2 specialization is the paper rank-trace inequality.", "verification_status": "Actual local source build succeeded; actual type/axiom query exited0, dependencies only propext,Classical.choice,Quot.sound. Not external independent-kernel replay.", "evidence": "experiments/results/formal_ranktrace_summary.json", "novelty": "None claimed; source theorem independently compiled, not a newly discovered result.", "id": "THM-F009", "provenance_file": "theorems/formal_round2.jsonl"}','PAPER-A004','For any RCLike field, finite Hermitian matricesP,Q withP positive semidefinite, rankP<=r, positive inertia index(Q)<=b and realc>0, c trP-(c^2/4)r+2c trQ-c^2 b<=||P+Q||_HS^2. The c=2 specialization is the paper rank-trace inequality.','source algebra theorem locally checked by Lean','Zeta23/LinAlg/RankTrace.lean at commit3635e74826a4c1fcece7d1cd2b6fa75e43a00510','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F010','theorems/theorems.jsonl',172,'adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay','["proposals/independent_campaigns/no_buffer_operator_countermodel_round2.md", "audits/adversarial_reviews/AF_no_buffer_operator_countermodel.md", "audits/adversarial_reviews/director_round3_adjudication.md"]','{"theorem_id": "THM-F010", "kind": "explicit negative-control countermodel for an altered abstract inference", "paper_id": "PAPER-A004", "statement": "Fix any smooth nondecreasing cutoffchi withchi=0on(-infinity,0] andchi=1on[1,infinity). Letphi_L(u)=chi(L/2+u)chi(L/2-u), L=log(T/(2pi)), h=2pi/L, d=floor(T/h), alpha_k=T+kh. There is one fixed gamma multiset, invariant under conjugation and negation, inside|Im gamma|<=1/4, with global unit-interval multiplicityO(log(|t|+3)), Riemann-von-Mangoldt cumulative main count+O(logT), finite windows and eventual Vinogradov-Korobov strip compatibility, whose unbuffered omitted-zero matrixE_0 has||E_0(T_n)||_op tendingtoinfinity alongT_n=2pi exp(n^2), but||E_0(T)||_HS/sqrt(N([T,2T))) tends to0. Construction: real inverse values ofQ(t)=t/(2pi)(log(t/(2pi))-1) and their negatives, plus off-line quartets gamma=+/-[T_n-2pi/n^2]+/-i/4 for all sufficiently largen. AtT_n, E_00>=(2c_eta^2+o(1))exp(n^2/4)/n^4 withc_eta=J(-eta)/eta>0, eta=1/4,J(s)=integral_0^1 chi_prime(u)exp(su)du.", "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "evidence": ["proposals/independent_campaigns/no_buffer_operator_countermodel_round2.md", "audits/adversarial_reviews/AF_no_buffer_operator_countermodel.md", "audits/adversarial_reviews/director_round3_adjudication.md"], "limit": "Synthetic multiset only; no actual zeta zero claim, explicit formula, full prime-side moment or contradictory source theorem. The smooth fixed cutoff is essential; sharp cutoff is not substituted.", "novelty": "No publication novelty claimed. Clarifies the exact limitation of the accepted relative-Hilbert-Schmidt truncation.", "id": "THM-F010", "locator": ["proposals/independent_campaigns/no_buffer_operator_countermodel_round2.md", "audits/adversarial_reviews/AF_no_buffer_operator_countermodel.md", "audits/adversarial_reviews/director_round3_adjudication.md"], "provenance_file": "theorems/formal_round2.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}','PAPER-A004','Fix any smooth nondecreasing cutoffchi withchi=0on(-infinity,0] andchi=1on[1,infinity). Letphi_L(u)=chi(L/2+u)chi(L/2-u), L=log(T/(2pi)), h=2pi/L, d=floor(T/h), alpha_k=T+kh. There is one fixed gamma multiset, invariant under conjugation and negation, inside|Im gamma|<=1/4, with global unit-interval multiplicityO(log(|t|+3)), Riemann-von-Mangoldt cumulative main count+O(logT), finite windows and eventual Vinogradov-Korobov strip compatibility, whose unbuffered omitted-zero matrixE_0 has||E_0(T_n)||_op tendingtoinfinity alongT_n=2pi exp(n^2), but||E_0(T)||_HS/sqrt(N([T,2T))) tends to0. Construction: real inverse values ofQ(t)=t/(2pi)(log(t/(2pi))-1) and their negatives, plus off-line quartets gamma=+/-[T_n-2pi/n^2]+/-i/4 for all sufficiently largen. AtT_n, E_00>=(2c_eta^2+o(1))exp(n^2/4)/n^4 withc_eta=J(-eta)/eta>0, eta=1/4,J(s)=integral_0^1 chi_prime(u)exp(su)du.','explicit negative-control countermodel for an altered abstract inference','["proposals/independent_campaigns/no_buffer_operator_countermodel_round2.md", "audits/adversarial_reviews/AF_no_buffer_operator_countermodel.md", "audits/adversarial_reviews/director_round3_adjudication.md"]','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F011','theorems/theorems.jsonl',173,'adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay','["audits/adversarial_reviews/christoffel_scope_proposer_round3.md", "experiments/results/christoffel_one_sided_scope.json", "audits/adversarial_reviews/director_round3_adjudication.md", "audits/adversarial_reviews/christoffel_independent_third_round3.md"]','{"theorem_id": "THM-F011", "paper_id": "PAPER-A004", "locator": "arXiv2608.13637v2,§7.2(d),PDFp13,unrestricted ordinary-Christoffel reading only", "kind": "explicit counterexample to an informal moment-inference generalization", "statement": "For the66x66 diagonal Hermitian matrix with eigenvalues-1 repeated5times,1 repeated11times,and6/5 repeated50times, the normalized moments m0..m4 are(1,1,4/3,7/5,136/75), n_+(G)/66=61/66, and the ordinary degree2 Christoffel function Lambda2(0)=inf_{deg p<=2,p(0)=1}L(p^2)=5/309. Its Gram matrix is positive definite and unique minimizer is p*(x)=1+(12/103)x-(85/103)x^2. Thus1-Lambda2(0)=304/309>61/66 by135/2266. Ordinary Christoffel minimization does not automatically give a negative-halfline mass bound, even with m1=1,m2=4/3.", "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "evidence": ["audits/adversarial_reviews/christoffel_scope_proposer_round3.md", "experiments/results/christoffel_one_sided_scope.json", "audits/adversarial_reviews/director_round3_adjudication.md", "audits/adversarial_reviews/christoffel_independent_third_round3.md"], "limit": "Refutes the unrestricted ordinary-Christoffel reading of an informal remark. Does not model the complete zeta block/prime hypotheses or contradict TheoremsA/B or the specific four-moment consequence.", "novelty": "No novelty claimed; classical atom-versus-halfline distinction.", "id": "THM-F011", "provenance_file": "theorems/formal_round2.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}','PAPER-A004','For the66x66 diagonal Hermitian matrix with eigenvalues-1 repeated5times,1 repeated11times,and6/5 repeated50times, the normalized moments m0..m4 are(1,1,4/3,7/5,136/75), n_+(G)/66=61/66, and the ordinary degree2 Christoffel function Lambda2(0)=inf_{deg p<=2,p(0)=1}L(p^2)=5/309. Its Gram matrix is positive definite and unique minimizer is p*(x)=1+(12/103)x-(85/103)x^2. Thus1-Lambda2(0)=304/309>61/66 by135/2266. Ordinary Christoffel minimization does not automatically give a negative-halfline mass bound, even with m1=1,m2=4/3.','explicit counterexample to an informal moment-inference generalization','arXiv2608.13637v2,§7.2(d),PDFp13,unrestricted ordinary-Christoffel reading only','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F012','theorems/theorems.jsonl',174,'adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay','["audits/adversarial_reviews/christoffel_scope_proposer_round3.md", "experiments/results/christoffel_one_sided_scope.json", "audits/adversarial_reviews/director_round3_adjudication.md", "audits/adversarial_reviews/christoffel_independent_third_round3.md"]','{"theorem_id": "THM-F012", "paper_id": "PAPER-A004", "locator": "Corrected moment dual and explicit check of§7.2(f),PDFp13", "kind": "valid finite polynomial moment certificate and conditional source specialization", "statement": "LetG be a dxd Hermitian matrix,d>=1,and m_k=tr(G^k)/d. For any real polynomialq(x)=sum_{k=0}^{2m}q_k x^k withq(x)>=1 forx<=0 andq(x)>=0 forx>0, n_+(G)/d>=1-sum q_k m_k. A squared ordinary-Christoffel minimizer is valid for this purpose only when its halfline-majorant property is separately established. For m0..m4=(1,1,4/3,2,13/4), p(x)=1-7x/4+2x^2/3 hasp(x)>=1 onx<=0 and L(p^2)=5/36, hence n_+(G)/d>=31/36. Under the separately assumed source asymptotic moments, d/N->1 and source count bounds n_+(G)<=s1+s2+pairs,N>=s1+2s2+2pairs, this implies s1/N>=13/18-o(1).", "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "evidence": ["audits/adversarial_reviews/christoffel_scope_proposer_round3.md", "experiments/results/christoffel_one_sided_scope.json", "audits/adversarial_reviews/director_round3_adjudication.md", "audits/adversarial_reviews/christoffel_independent_third_round3.md"], "limit": "The one-sided inequality is a valid certificate, not a general sharpness theorem. HL*(4) remains an external conditional premise; no new unconditional zero proportion or RH result.", "novelty": "None claimed; explicit qualification preserves the source-specific conditional13/18 calculation.", "id": "THM-F012", "provenance_file": "theorems/formal_round2.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}','PAPER-A004','LetG be a dxd Hermitian matrix,d>=1,and m_k=tr(G^k)/d. For any real polynomialq(x)=sum_{k=0}^{2m}q_k x^k withq(x)>=1 forx<=0 andq(x)>=0 forx>0, n_+(G)/d>=1-sum q_k m_k. A squared ordinary-Christoffel minimizer is valid for this purpose only when its halfline-majorant property is separately established. For m0..m4=(1,1,4/3,2,13/4), p(x)=1-7x/4+2x^2/3 hasp(x)>=1 onx<=0 and L(p^2)=5/36, hence n_+(G)/d>=31/36. Under the separately assumed source asymptotic moments, d/N->1 and source count bounds n_+(G)<=s1+s2+pairs,N>=s1+2s2+2pairs, this implies s1/N>=13/18-o(1).','valid finite polynomial moment certificate and conditional source specialization','Corrected moment dual and explicit check of§7.2(f),PDFp13','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F013','theorems/theorems.jsonl',175,'42 closed interval exact rational checks and Fourier proof reconstructed; independent skeptic replayed final guarded script and checked enclosures/endpoints. Director adjudication pending. Not Lean checked or a full zeta proof.','["experiments/results/839_majorant_check.json", "experiments/results/839_majorant_skeptic_replay.json", "audits/adversarial_reviews/839_majorant_reconstruction.md", "audits/adversarial_reviews/839_majorant_skeptic.md"]','{"theorem_id": "THM-F013", "paper_id": "PAPER-A005", "locator": "First-window§3pp15–16;Distinct839/Majorant/{Checker,Pointwise,Fourier,Separated}.lean at pinned v1", "kind": "independently reconstructed majorant/Bessel/close-pair component", "statement": "For the first-window probability densityf ofTHM-F001,theta=17/20,gamma0=607/1000,andg(u)=gamma0[sinc(theta(u-1/2))+sinc(theta(u+1/2))]^2, one hasf(u)<=g(u) forallrealu. The continuous Fourier transformghat vanishes when|t|>=theta and Lambda=integral g=(2gamma0/theta)(1+sinc(theta))<=16711/10000<67/40. Thus everyfinite theta-separated real point set has Gram matrix[K(y_i-y_j)]<=Lambda I. The independently validated first13927 kernel cells also giveK(t)^2>=beta=8824337/134217728 for|t|<=theta. Forc=67/20,x=54350/10^6,y=69433/10^6, 2+2sqrt(beta)<c and2beta>2x,4beta>x+y,8beta>2y.", "verification_status": "42 closed interval exact rational checks and Fourier proof reconstructed; independent skeptic replayed final guarded script and checked enclosures/endpoints. Director adjudication pending. Not Lean checked or a full zeta proof.", "evidence": ["experiments/results/839_majorant_check.json", "experiments/results/839_majorant_skeptic_replay.json", "audits/adversarial_reviews/839_majorant_reconstruction.md", "audits/adversarial_reviews/839_majorant_skeptic.md"], "limit": "Close-pair inference explicitly depends on the pinned previously validated table; the source local-search, clipped matrix and analytic pair-correlation transfer remain separate premises.", "novelty": "No novelty claimed; independent validation of a source certificate component.", "id": "THM-F013", "provenance_file": "theorems/formal_round2.jsonl"}','PAPER-A005','For the first-window probability densityf ofTHM-F001,theta=17/20,gamma0=607/1000,andg(u)=gamma0[sinc(theta(u-1/2))+sinc(theta(u+1/2))]^2, one hasf(u)<=g(u) forallrealu. The continuous Fourier transformghat vanishes when|t|>=theta and Lambda=integral g=(2gamma0/theta)(1+sinc(theta))<=16711/10000<67/40. Thus everyfinite theta-separated real point set has Gram matrix[K(y_i-y_j)]<=Lambda I. The independently validated first13927 kernel cells also giveK(t)^2>=beta=8824337/134217728 for|t|<=theta. Forc=67/20,x=54350/10^6,y=69433/10^6, 2+2sqrt(beta)<c and2beta>2x,4beta>x+y,8beta>2y.','independently reconstructed majorant/Bessel/close-pair component','First-window§3pp15–16;Distinct839/Majorant/{Checker,Pointwise,Fourier,Separated}.lean at pinned v1','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-F014','theorems/theorems.jsonl',176,'Actual local Lean compilation exit0 in8.386s; both theorem axiom queries reported onlypropext,Classical.choice,Quot.sound. Uses already built source dependencies; no full zeta build or formal weak-convergence/clipping proof inferred.','["experiments/code/ObservatoryHoffmanWielandt.lean", "experiments/results/formal_hoffman_wielandt.json"]','{"theorem_id": "THM-F014", "paper_id": "PAPER-A004", "locator": "Archive proof experiments/code/ObservatoryHoffmanWielandt.lean using pinnedRHLinalg.vonNeumann_trace_ineq", "kind": "finite perturbation lemmas actually checked locally by Lean", "statement": "For finite Hermitian matricesA,B over anyRCLike field, sum_i(lambda_i(A)-lambda_i(B))^2<=frobSq(A-B), with both eigenvalue sequences in decreasing order. For anyf:R->R,C>=0 satisfying|f(x)-f(y)|<=C|x-y| forallx,y, (sum_i f(lambda_i(A))-sum_i f(lambda_i(B)))^2<=C^2*d*frobSq(A-B). For d>0 this gives empirical-test difference<=C||A-B||HS/sqrt(d).", "verification_status": "Actual local Lean compilation exit0 in8.386s; both theorem axiom queries reported onlypropext,Classical.choice,Quot.sound. Uses already built source dependencies; no full zeta build or formal weak-convergence/clipping proof inferred.", "evidence": ["experiments/code/ObservatoryHoffmanWielandt.lean", "experiments/results/formal_hoffman_wielandt.json"], "source_sha256": "1ba4288d5722abdfbda52f2958b0794294816b732864addc8cab8f4f01f9654e", "imported_source_commit": "3635e74826a4c1fcece7d1cd2b6fa75e43a00510", "limit": "The explicit clipped-polynomial Lipschitz condition and all arithmetic moment hypotheses require their separate ordinary proofs; this is only the finite matrix core.", "novelty": "Classical Hoffman-Wielandt/Cauchy-Schwarz consequence; new local formalization, no mathematical novelty claimed.", "id": "THM-F014", "provenance_file": "theorems/formal_round2.jsonl"}','PAPER-A004','For finite Hermitian matricesA,B over anyRCLike field, sum_i(lambda_i(A)-lambda_i(B))^2<=frobSq(A-B), with both eigenvalue sequences in decreasing order. For anyf:R->R,C>=0 satisfying|f(x)-f(y)|<=C|x-y| forallx,y, (sum_i f(lambda_i(A))-sum_i f(lambda_i(B)))^2<=C^2*d*frobSq(A-B). For d>0 this gives empirical-test difference<=C||A-B||HS/sqrt(d).','finite perturbation lemmas actually checked locally by Lean','Archive proof experiments/code/ObservatoryHoffmanWielandt.lean using pinnedRHLinalg.vonNeumann_trace_ineq','theorems/formal_round2.jsonl');
INSERT INTO "claims" VALUES('THM-C106-1','theorems/theorems.jsonl',177,'established_source_result','Theorem p312; proofpp312–314','{"id": "THM-C106-1", "paper_id": "PAPER-C106", "locator": "Theorem p312; proofpp312–314", "statement": "For everyfixed1<p<infinity, C={finiteΣcν{θν/x}:0<θν≤1,Σcνθν=0} isdenseL^p(0,1) iffζ hasnozeros inRe(s)>1/p.", "status": "established_source_result", "verification": "wholeoriginalread; explicitMellin,Hölder,dilation,annihilatorsupport andcharacter-use stepsreconstructed; canonicalfactorizationinputto1953dependencyidentifiedexternal", "hypotheses": ["strict1<p<infinity", "continuouslyvaryingθν", "exactcoefficientconstraint"], "novelty_claim": false, "provenance_file": "theorems/foundations_round2.jsonl"}','PAPER-C106','For everyfixed1<p<infinity, C={finiteΣcν{θν/x}:0<θν≤1,Σcνθν=0} isdenseL^p(0,1) iffζ hasnozeros inRe(s)>1/p.',NULL,'Theorem p312; proofpp312–314','theorems/foundations_round2.jsonl');
INSERT INTO "claims" VALUES('LEM-C106-1','theorems/theorems.jsonl',178,'independently_checked_source_lemma','p314 equation8 andprecedingconstruction','{"id": "LEM-C106-1", "paper_id": "PAPER-C106", "locator": "p314 equation8 andprecedingconstruction", "statement": "A nonzeroL^r annihilator ofC cannotvanish on(0,a) foranya>0. The testb{a/x}−a{b/x},a<b<min(1,2a), equalsa on(a,b), vanishespastb andbelongsC; orthogonality propagatesaninitialzerointervaldyadicallytoall(0,1).", "status": "independently_checked_source_lemma", "verification": "explicitfractionalpartcases andfiniteiterationchecked", "novelty_claim": false, "provenance_file": "theorems/foundations_round2.jsonl"}','PAPER-C106','A nonzeroL^r annihilator ofC cannotvanish on(0,a) foranya>0. The testb{a/x}−a{b/x},a<b<min(1,2a), equalsa on(a,b), vanishespastb andbelongsC; orthogonality propagatesaninitialzerointervaldyadicallytoall(0,1).',NULL,'p314 equation8 andprecedingconstruction','theorems/foundations_round2.jsonl');
INSERT INTO "claims" VALUES('THM-C107-1','theorems/theorems.jsonl',179,'established_source_result','TheoremI p128; proofpp128–130','{"id": "THM-C107-1", "paper_id": "PAPER-C107", "locator": "TheoremI p128; proofpp128–130", "statement": "For f∈L^P(0,1),1<P<infinity, notvanishinga.e.onanyinitialinterval, letC_f^r beL^rclosureofspan{f(ax):0<a≤1}. Then (intersection_(1≤r<P)C_f^r)∩L^P containsx^(−λ) forsomeReλ<1/P.", "status": "established_source_result", "verification": "wholepaperread; MellinG=KF,Fubini,boundarypole andentirecasearchitecturechecked; Nevanlinnacanonicaldecompositionretainedexternal", "novelty_claim": false, "provenance_file": "theorems/foundations_round2.jsonl"}','PAPER-C107','For f∈L^P(0,1),1<P<infinity, notvanishinga.e.onanyinitialinterval, letC_f^r beL^rclosureofspan{f(ax):0<a≤1}. Then (intersection_(1≤r<P)C_f^r)∩L^P containsx^(−λ) forsomeReλ<1/P.',NULL,'TheoremI p128; proofpp128–130','theorems/foundations_round2.jsonl');
INSERT INTO "claims" VALUES('OBS-C107-1','theorems/theorems.jsonl',180,'source_reported_known_obstruction','p127 introductorycounterexamplediscussion; p128definitionofΓ_f^P','{"id": "OBS-C107-1", "paper_id": "PAPER-C107", "locator": "p127 introductorycounterexamplediscussion; p128definitionofΓ_f^P", "statement": "The weaker-topologycharacter theorem mustnotbeupgradedtocharacterexistenceinC_f^P. The originalL²closureversion is explicitlyreportedfalse, with1949BeurlingandNyman1950asdependencies.", "status": "source_reported_known_obstruction", "verification": "actualprimarypassageread; individualcounterexamplesnotreconstructedfromcitedworks", "novelty_claim": false, "provenance_file": "theorems/foundations_round2.jsonl"}','PAPER-C107','The weaker-topologycharacter theorem mustnotbeupgradedtocharacterexistenceinC_f^P. The originalL²closureversion is explicitlyreportedfalse, with1949BeurlingandNyman1950asdependencies.',NULL,'p127 introductorycounterexamplediscussion; p128definitionofΓ_f^P','theorems/foundations_round2.jsonl');
INSERT INTO "claims" VALUES('LEM-C106-ANCHOR','theorems/theorems.jsonl',181,'elementary_reconstruction_no_novelty_claim','independentreconstructioninaudits/beurling1955_round2.md, relationtofullhalflinevariants','{"id": "LEM-C106-ANCHOR", "paper_id": "PAPER-C106", "related_paper_ids": ["PAPER-E001"], "locator": "independentreconstructioninaudits/beurling1955_round2.md, relationtofullhalflinevariants", "statement": "For finiteg(x)=Σcν{θν/x},0<θν≤1,A=Σcνθν,onehasg(x)=A/x forx>1and ||g−1_(0,1)||_L²(0,infinity)≥|A|. Thusfullnormapproximationcanbeanchoredtog−A{1/x},whichsatisfiesexactcoefficientconstraint,atcostO(|A|). Thisdoesnotjustifyrestrictingcontinuousθνtoreciprocalintegers.", "status": "elementary_reconstruction_no_novelty_claim", "verification": "tailintegral andtriangleinequalitychecked; independentparentreviewrequested", "novelty_claim": false, "provenance_file": "theorems/foundations_round2.jsonl"}','PAPER-C106','For finiteg(x)=Σcν{θν/x},0<θν≤1,A=Σcνθν,onehasg(x)=A/x forx>1and ||g−1_(0,1)||_L²(0,infinity)≥|A|. Thusfullnormapproximationcanbeanchoredtog−A{1/x},whichsatisfiesexactcoefficientconstraint,atcostO(|A|). Thisdoesnotjustifyrestrictingcontinuousθνtoreciprocalintegers.',NULL,'independentreconstructioninaudits/beurling1955_round2.md, relationtofullhalflinevariants','theorems/foundations_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G001','theorems/theorems.jsonl',182,'Source inspected and finite-sum proof independently reconstructed; no issue found.','Equation (4), pp.500–501','{"theorem_id": "THM-G001", "paper_id": "PAPER-G001", "locator": "Equation (4), pp.500–501", "kind": "published lemma independently reconstructed", "statement": "For finite Fq, nontrivial multiplicative χ:Fq*→C* and nontrivial additive ψ:Fq→C*, G=Σx≠0 χ(x)ψ(x) satisfies |G|²=q.", "verification_status": "Source inspected and finite-sum proof independently reconstructed; no issue found.", "hypotheses": ["Both characters nontrivial.", "Characters have finite image, hence unit magnitude."], "proof": "Substitute x=uy in |G|²; the inner additive sum over y≠0 is q−1 for u=1 and −1 otherwise. Multiplicative orthogonality gives q.", "id": "THM-G001", "provenance_file": "theorems/geometry_round2.jsonl"}','PAPER-G001','For finite Fq, nontrivial multiplicative χ:Fq*→C* and nontrivial additive ψ:Fq→C*, G=Σx≠0 χ(x)ψ(x) satisfies |G|²=q.','published lemma independently reconstructed','Equation (4), pp.500–501','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G002','theorems/theorems.jsonl',183,'Exact theorem and selected dependency architecture inspected; whole proof not independently audited.','Theorem(1.6), p.276; (1.15), p.279','{"theorem_id": "THM-G002", "paper_id": "PAPER-G002", "locator": "Theorem(1.6), p.276; (1.15), p.279", "kind": "published theorem", "statement": "For X0 smooth projective over Fq and ℓ≠char Fq, det(tI−F | H^i_et(X0×Fq Fqbar,Qℓ)) has coefficients in Z independent of ℓ; each complex conjugate α of every root satisfies |α|=q^(i/2). F is geometric Frobenius.", "verification_status": "Exact theorem and selected dependency architecture inspected; whole proof not independently audited.", "id": "THM-G002", "provenance_file": "theorems/geometry_round2.jsonl"}','PAPER-G002','For X0 smooth projective over Fq and ℓ≠char Fq, det(tI−F | H^i_et(X0×Fq Fqbar,Qℓ)) has coefficients in Z independent of ℓ; each complex conjugate α of every root satisfies |α|=q^(i/2). F is geometric Frobenius.','published theorem','Theorem(1.6), p.276; (1.15), p.279','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G003','theorems/theorems.jsonl',184,'Statement and positivity/pole argument inspected; underlying cohomology and invariant-theory results not independently proved.','Theorem(3.2), pp.283–285','{"theorem_id": "THM-G003", "paper_id": "PAPER-G002", "locator": "Theorem(3.2), pp.283–285", "kind": "published theorem", "statement": "Let U0⊂P1/Fq be the complement of finitely many closed points, F0 a lisse Qℓ-sheaf, β∈Z. Assume a perfect alternating pairing F0⊗F0→Qℓ(−β); the geometric monodromy image is open in the corresponding symplectic group; and det(1−tFx|F0,x)∈Q[t] for every closed x. Then F0 is pointwise pure of weight β.", "verification_status": "Statement and positivity/pole argument inspected; underlying cohomology and invariant-theory results not independently proved.", "hypotheses": ["ℓ≠char Fq.", "Geometric monodromy, not merely arithmetic self-duality.", "Rational local characteristic polynomials for every closed point."], "id": "THM-G003", "provenance_file": "theorems/geometry_round2.jsonl"}','PAPER-G002','Let U0⊂P1/Fq be the complement of finitely many closed points, F0 a lisse Qℓ-sheaf, β∈Z. Assume a perfect alternating pairing F0⊗F0→Qℓ(−β); the geometric monodromy image is open in the corresponding symplectic group; and det(1−tFx|F0,x)∈Q[t] for every closed x. Then F0 is pointwise pure of weight β.','published theorem','Theorem(3.2), pp.283–285','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G004','theorems/theorems.jsonl',185,'Elementary power/Künneth inference checked; geometric derivation of weak estimate not fully audited.','Lemma(7.1), pp.298–300; (7.3), p.301','{"theorem_id": "THM-G004", "paper_id": "PAPER-G002", "locator": "Lemma(7.1), pp.298–300; (7.3), p.301", "kind": "published amplification step", "statement": "For middle eigenvalue α on a smooth projective absolutely irreducible d-dimensional variety, a dimension-independent q^(d/2±1/2) estimate on even-dimensional cartesian powers gives q^(d/2−1/(2k))≤|α|≤q^(d/2+1/(2k)) and hence |α|=q^(d/2).", "verification_status": "Elementary power/Künneth inference checked; geometric derivation of weak estimate not fully audited.", "id": "THM-G004", "provenance_file": "theorems/geometry_round2.jsonl"}','PAPER-G002','For middle eigenvalue α on a smooth projective absolutely irreducible d-dimensional variety, a dimension-independent q^(d/2±1/2) estimate on even-dimensional cartesian powers gives q^(d/2−1/(2k))≤|α|≤q^(d/2+1/(2k)) and hence |α|=q^(d/2).','published amplification step','Lemma(7.1), pp.298–300; (7.3), p.301','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G005','theorems/theorems.jsonl',186,'Original statement and reduction architecture inspected; full proof not audited.','Theorem(3.3.1), p.204; conventions(0.1)–(0.2), p.144','{"theorem_id": "THM-G005", "paper_id": "PAPER-G003", "locator": "Theorem(3.3.1), p.204; conventions(0.1)–(0.2), p.144", "kind": "published theorem", "statement": "For f:X→Y between separated noetherian algebraic spaces of finite type over Z with fixed ℓ invertible, and constructible Qℓbar-sheaf F mixed of weights ≤n, R^i f! F is mixed of weights ≤n+i.", "verification_status": "Original statement and reduction architecture inspected; full proof not audited.", "id": "THM-G005", "provenance_file": "theorems/geometry_round2.jsonl"}','PAPER-G003','For f:X→Y between separated noetherian algebraic spaces of finite type over Z with fixed ℓ invertible, and constructible Qℓbar-sheaf F mixed of weights ≤n, R^i f! F is mixed of weights ≤n+i.','published theorem','Theorem(3.3.1), p.204; conventions(0.1)–(0.2), p.144','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G006','theorems/theorems.jsonl',187,'Hypotheses and use of opposite duality bounds inspected; no whole-proof audit.','Corollaries(3.3.4)–(3.3.6), p.206','{"theorem_id": "THM-G006", "paper_id": "PAPER-G003", "locator": "Corollaries(3.3.4)–(3.3.6), p.206", "kind": "published theorem", "statement": "Over Fq, Hc^i(X,F) has weights ≤n+i for F mixed of weights ≤n. On smooth X0 and lisse F0 of weights ≥n, H^i has weights ≥n+i. For F0 lisse pure weight n, im(Hc^i→H^i) is pure weight n+i.", "verification_status": "Hypotheses and use of opposite duality bounds inspected; no whole-proof audit.", "id": "THM-G006", "provenance_file": "theorems/geometry_round2.jsonl"}','PAPER-G003','Over Fq, Hc^i(X,F) has weights ≤n+i for F mixed of weights ≤n. On smooth X0 and lisse F0 of weights ≥n, H^i has weights ≥n+i. For F0 lisse pure weight n, im(Hc^i→H^i) is pure weight n+i.','published theorem','Corollaries(3.3.4)–(3.3.6), p.206','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G007','theorems/theorems.jsonl',188,'Source statement inspected; extension proper vs projective checked.','Corollary(3.3.9), p.207','{"theorem_id": "THM-G007", "paper_id": "PAPER-G003", "locator": "Corollary(3.3.9), p.207", "kind": "published theorem", "statement": "For X0 smooth proper over Fq and ℓ≠char Fq, the characteristic polynomial of geometric Frobenius on H^i_et(X,Qℓ) is integral and ℓ-independent; all complex eigenvalue conjugates have magnitude q^(i/2).", "verification_status": "Source statement inspected; extension proper vs projective checked.", "id": "THM-G007", "provenance_file": "theorems/geometry_round2.jsonl"}','PAPER-G003','For X0 smooth proper over Fq and ℓ≠char Fq, the characteristic polynomial of geometric Frobenius on H^i_et(X,Qℓ) is integral and ℓ-independent; all complex eigenvalue conjugates have magnitude q^(i/2).','published theorem','Corollary(3.3.9), p.207','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G008','theorems/theorems.jsonl',189,'Statement/image and Hadamard–de la Vallée-Poussin connection inspected; complete representation-theoretic proof not audited.','Corollary(2.2.10), p.196; context(2.1.9), p.191','{"theorem_id": "THM-G008", "paper_id": "PAPER-G003", "locator": "Corollary(2.2.10), p.196; context(2.1.9), p.191", "kind": "published theorem", "statement": "For X0/Fq smooth curve and F0 lisse iota-pure of weight β, every Frobenius eigenvalue α on Hc^1(X,F) satisfies wq(α)<β+2, wq(α)=2log_q|iota(α)|.", "verification_status": "Statement/image and Hadamard–de la Vallée-Poussin connection inspected; complete representation-theoretic proof not audited.", "id": "THM-G008", "provenance_file": "theorems/geometry_round2.jsonl"}','PAPER-G003','For X0/Fq smooth curve and F0 lisse iota-pure of weight β, every Frobenius eigenvalue α on Hc^1(X,F) satisfies wq(α)<β+2, wq(α)=2log_q|iota(α)|.','published theorem','Corollary(2.2.10), p.196; context(2.1.9), p.191','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G009','theorems/theorems.jsonl',190,'Exact statement and product-iteration architecture inspected; all local calculations not independently audited.','Lemma(3.2.4)(k), p.197 through proof(3.2.15), p.204','{"theorem_id": "THM-G009", "paper_id": "PAPER-G003", "locator": "Lemma(3.2.4)(k), p.197 through proof(3.2.15), p.204", "kind": "published theorem", "statement": "For every k≥0, smooth U0/Fq and F0 lisse iota-pure weight0, eigenvalues α on Hc^1(U,F) satisfy wq(α)≤1+2^(−k). Passing to the limit supplies the optimal upper weight bound; duality then yields curve purity in the proper intermediate-extension statement.", "verification_status": "Exact statement and product-iteration architecture inspected; all local calculations not independently audited.", "id": "THM-G009", "provenance_file": "theorems/geometry_round2.jsonl"}','PAPER-G003','For every k≥0, smooth U0/Fq and F0 lisse iota-pure weight0, eigenvalues α on Hc^1(U,F) satisfy wq(α)≤1+2^(−k). Passing to the limit supplies the optimal upper weight bound; duality then yields curve purity in the proper intermediate-extension statement.','published theorem','Lemma(3.2.4)(k), p.197 through proof(3.2.15), p.204','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G010','theorems/theorems.jsonl',191,'established auxiliary negative result; not a counterexample to any actual curve theorem or classical RH','frontiers/geometry_round2.md §3','{"theorem_id": "THM-G010", "paper_id": null, "locator": "frontiers/geometry_round2.md §3", "kind": "independently proved auxiliary obstruction", "statement": "Z*(t)=(1−5t+5t²)/((1−t)(1−5t)) has integral Taylor coefficients, nonnegative integer Euler exponents in every degree, genus-one reciprocal functional equation, and a finite alternating-duality trace model, but numerator eigenvalues (5±sqrt5)/2 have magnitudes unequal to sqrt5.", "verification_status": "Explicit all-degree labeled-graph proof reconstructed; parent independently checked injection, exact periods and recurrence. No literature novelty claim.", "proof_file": "frontiers/geometry_round2.md", "test_file": "experiments/code/geometry_round2_exact.py", "status": "established auxiliary negative result; not a counterexample to any actual curve theorem or classical RH", "id": "THM-G010", "provenance_file": "theorems/geometry_round2.jsonl"}',NULL,'Z*(t)=(1−5t+5t²)/((1−t)(1−5t)) has integral Taylor coefficients, nonnegative integer Euler exponents in every degree, genus-one reciprocal functional equation, and a finite alternating-duality trace model, but numerator eigenvalues (5±sqrt5)/2 have magnitudes unequal to sqrt5.','independently proved auxiliary obstruction','frontiers/geometry_round2.md §3','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G011','theorems/theorems.jsonl',192,'Parent independently checked continuity, geometric/arithmetic Frobenius convention and pole formula; no issue found.','frontiers/geometry_round2.md §3, genuine lisse-sheaf test','{"theorem_id": "THM-G011", "paper_id": null, "locator": "frontiers/geometry_round2.md §3, genuine lisse-sheaf test", "kind": "independently reconstructed hypothesis-deletion example", "statement": "For ℓ≠5, geometric Frobenius A=[[2,1],[1,3]] defines a continuous Gal(F5bar/F5) representation pulled back to A1/F5. It has a perfect alternating pairing to Qℓ(−1) and rational local characteristic polynomials but is not pure of weight1; geometric monodromy is trivial. L(A1,V^⊗2k,t)=det(1−5t A^⊗2k)^−1.", "verification_status": "Parent independently checked continuity, geometric/arithmetic Frobenius convention and pole formula; no issue found.", "source_theorems": ["THM-G003"], "role": "Tests deletion of the open-geometric-monodromy hypothesis; not a contradiction to Deligne.", "id": "THM-G011", "provenance_file": "theorems/geometry_round2.jsonl"}',NULL,'For ℓ≠5, geometric Frobenius A=[[2,1],[1,3]] defines a continuous Gal(F5bar/F5) representation pulled back to A1/F5. It has a perfect alternating pairing to Qℓ(−1) and rational local characteristic polynomials but is not pure of weight1; geometric monodromy is trivial. L(A1,V^⊗2k,t)=det(1−5t A^⊗2k)^−1.','independently reconstructed hypothesis-deletion example','frontiers/geometry_round2.md §3, genuine lisse-sheaf test','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G012','theorems/theorems.jsonl',193,'Independent logarithm/division proof; abstraction of DeligneI(7.3), no novelty claim.','frontiers/geometry_round2.md §4','{"theorem_id": "THM-G012", "paper_id": null, "locator": "frontiers/geometry_round2.md §4", "kind": "elementary amplification lemma", "statement": "If q>1, α≠0, and for arbitrarily large k, q^(kw/2−Ck)≤|α|^k≤q^(kw/2+Ck) with Ck=o(k), then |α|=q^(w/2).", "verification_status": "Independent logarithm/division proof; abstraction of DeligneI(7.3), no novelty claim.", "source_theorems": ["THM-G004"], "id": "THM-G012", "provenance_file": "theorems/geometry_round2.jsonl"}',NULL,'If q>1, α≠0, and for arbitrarily large k, q^(kw/2−Ck)≤|α|^k≤q^(kw/2+Ck) with Ck=o(k), then |α|=q^(w/2).','elementary amplification lemma','frontiers/geometry_round2.md §4','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('THM-G013','theorems/theorems.jsonl',194,'derived lemma under review','frontiers/geometry_round2.md §9','{"theorem_id": "THM-G013", "paper_id": null, "locator": "frontiers/geometry_round2.md §9", "kind": "derived sufficient-condition lemma pending independent review", "statement": "For affine U0⊂P1/Fq and lisse F0 with perfect alternating pairing to Qℓ(−β) and rational local characteristic polynomials, suppose for arbitrarily large k all Frobenius eigenvalues on (V^⊗2k)_geometric-monodromy are algebraic and every conjugate has magnitude ≤q^(kβ+Ck), Ck≥0, Ck=o(k). Then F0 is pointwise pure weightβ.", "verification_status": "Proof reconstruction supplied; separate review of coefficient-field descent and local/global radius comparison pending. Do not assign literature novelty.", "source_theorems": ["THM-G003", "THM-G012"], "proof_file": "frontiers/geometry_round2.md", "status": "derived lemma under review", "id": "THM-G013", "provenance_file": "theorems/geometry_round2.jsonl"}',NULL,'For affine U0⊂P1/Fq and lisse F0 with perfect alternating pairing to Qℓ(−β) and rational local characteristic polynomials, suppose for arbitrarily large k all Frobenius eigenvalues on (V^⊗2k)_geometric-monodromy are algebraic and every conjugate has magnitude ≤q^(kβ+Ck), Ck≥0, Ck=o(k). Then F0 is pointwise pure weightβ.','derived sufficient-condition lemma pending independent review','frontiers/geometry_round2.md §9','theorems/geometry_round2.jsonl');
INSERT INTO "claims" VALUES('OBS-POLY-GROWTH','theorems/theorems.jsonl',195,'established auxiliary consequence, no arithmetic or novelty claim','proposals/independent_campaigns/growing_multiplicity_transition_round3.md; audits/adversarial_reviews/growing_multiplicity_corpus_round3.md; audits/adversarial_reviews/growing_multiplicity_third_round3.md','{"id": "OBS-POLY-GROWTH", "paper_id": null, "kind": "derived exact finite-model transition", "statement": "For the exact coalesced polynomial optimum E=1−product_(j0..m−1)(N+m−j)/(N+m+1+j), E is asymptotic to m²/N iff m=o(sqrtN); ifm²/N→lambda finite, E→1−exp(−lambda); ifm²/N→infinity, E→1. Explicit artanh bounds and compact-uniform transition remainder are given in the proof/review. N,m integers>=1.", "locator": "proposals/independent_campaigns/growing_multiplicity_transition_round3.md; audits/adversarial_reviews/growing_multiplicity_corpus_round3.md; audits/adversarial_reviews/growing_multiplicity_third_round3.md", "verification": "adjudicated_scoped; root, corpus, semantic_skeptic independent reconstruction from separately verified exact formula", "status": "established auxiliary consequence, no arithmetic or novelty claim", "provenance_file": "theorems/growing_polynomial_director_round3.jsonl"}',NULL,'For the exact coalesced polynomial optimum E=1−product_(j0..m−1)(N+m−j)/(N+m+1+j), E is asymptotic to m²/N iff m=o(sqrtN); ifm²/N→lambda finite, E→1−exp(−lambda); ifm²/N→infinity, E→1. Explicit artanh bounds and compact-uniform transition remainder are given in the proof/review. N,m integers>=1.','derived exact finite-model transition','proposals/independent_campaigns/growing_multiplicity_transition_round3.md; audits/adversarial_reviews/growing_multiplicity_corpus_round3.md; audits/adversarial_reviews/growing_multiplicity_third_round3.md','theorems/growing_polynomial_director_round3.jsonl');
INSERT INTO "claims" VALUES('THM-HC301','theorems/theorems.jsonl',196,'primary_source_theorem_plus_direct_corollary; external_distribution_dictionary_not_independently_audited','["PAPER-HC002 Theorem1 and Corollary2, pp2–3; proof pp7–10", "audits/hamburger_converse_round3.md ordinary-series tail estimate"]','{"id": "THM-HC301", "kind": "established_converse", "statement": "An ordinary Dirichlet series convergent in some right half-plane, meromorphic on C with finitely many poles, obeying Burnol strip bound O(exp(exp(epsilon|s|))) for every epsilon>0 in every finite strip, and exact conductor-one zeta self-dual FE, is a_1 zeta(s).", "hypotheses": "Integer frequencies n^(-s), finite poles, exact gamma Γ(s/2)π^(-s/2), sign+1; growth as stated, all constants allowed to depend on strip and epsilon.", "evidence": ["PAPER-HC002 Theorem1 and Corollary2, pp2–3; proof pp7–10", "audits/hamburger_converse_round3.md ordinary-series tail estimate"], "status": "primary_source_theorem_plus_direct_corollary; external_distribution_dictionary_not_independently_audited", "novelty_claim": false, "paper_id": null, "locator": ["PAPER-HC002 Theorem1 and Corollary2, pp2–3; proof pp7–10", "audits/hamburger_converse_round3.md ordinary-series tail estimate"], "provenance_file": "theorems/hamburger_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'An ordinary Dirichlet series convergent in some right half-plane, meromorphic on C with finitely many poles, obeying Burnol strip bound O(exp(exp(epsilon|s|))) for every epsilon>0 in every finite strip, and exact conductor-one zeta self-dual FE, is a_1 zeta(s).','established_converse','["PAPER-HC002 Theorem1 and Corollary2, pp2–3; proof pp7–10", "audits/hamburger_converse_round3.md ordinary-series tail estimate"]','theorems/hamburger_round3.jsonl');
INSERT INTO "claims" VALUES('THM-HC302','theorems/theorems.jsonl',197,'independent_analytic_derivation; parent_review_requested','["audits/hamburger_converse_round3.md Exact matching", "THM-LB303", "THM-LB305"]','{"id": "THM-HC302", "kind": "model_scope_obstruction", "statement": "For normalized Bessel/quartet F_T, L_T=F_T π^(s/2)/[(s−1)Γ(1+s/2)] has only a simple pole at1 of residue2, has finite order after pole removal, satisfies exact zeta FE, but L_T(s)~[(2π)^(1/4)/D_T]s^(7/4) on the positive real axis. Hence it is not an ordinary Dirichlet series convergent in any right half-plane.", "hypotheses": "T>=32; D_T=K_(1/4)(2π)Q_T(1/2)>0; F_T as THM-LB303.", "evidence": ["audits/hamburger_converse_round3.md Exact matching", "THM-LB303", "THM-LB305"], "status": "independent_analytic_derivation; parent_review_requested", "novelty_claim": false, "paper_id": null, "locator": ["audits/hamburger_converse_round3.md Exact matching", "THM-LB303", "THM-LB305"], "provenance_file": "theorems/hamburger_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'For normalized Bessel/quartet F_T, L_T=F_T π^(s/2)/[(s−1)Γ(1+s/2)] has only a simple pole at1 of residue2, has finite order after pole removal, satisfies exact zeta FE, but L_T(s)~[(2π)^(1/4)/D_T]s^(7/4) on the positive real axis. Hence it is not an ordinary Dirichlet series convergent in any right half-plane.','model_scope_obstruction','["audits/hamburger_converse_round3.md Exact matching", "THM-LB303", "THM-LB305"]','theorems/hamburger_round3.jsonl');
INSERT INTO "claims" VALUES('THM-HC303','theorems/theorems.jsonl',198,'direct_identity_checked; background_attribution_disagreement_pending_parent_adjudication','["PAPER-HC003 pp201 and211–212, visually inspected", "audits/hamburger_converse_round3.md ExceptionsA"]','{"id": "THM-HC303", "kind": "normalization_identity", "statement": "Knopp R(z)=π^(−z)Γ(z)φ(z), R(z)=R(1/2−z), with ordinary φ(z)=sum a_n n^(−z), becomes conventional zeta completion for F(s)=φ(s/2), whose frequencies are sqrt(n). Requiring F itself to be ordinary is a stronger assumption.", "hypotheses": "Exact change of variables s=2z. No infinite-series reordering is needed.", "evidence": ["PAPER-HC003 pp201 and211–212, visually inspected", "audits/hamburger_converse_round3.md ExceptionsA"], "status": "direct_identity_checked; background_attribution_disagreement_pending_parent_adjudication", "novelty_claim": false, "paper_id": null, "locator": ["PAPER-HC003 pp201 and211–212, visually inspected", "audits/hamburger_converse_round3.md ExceptionsA"], "provenance_file": "theorems/hamburger_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'Knopp R(z)=π^(−z)Γ(z)φ(z), R(z)=R(1/2−z), with ordinary φ(z)=sum a_n n^(−z), becomes conventional zeta completion for F(s)=φ(s/2), whose frequencies are sqrt(n). Requiring F itself to be ordinary is a stronger assumption.','normalization_identity','["PAPER-HC003 pp201 and211–212, visually inspected", "audits/hamburger_converse_round3.md ExceptionsA"]','theorems/hamburger_round3.jsonl');
INSERT INTO "claims" VALUES('THM-HC304','theorems/theorems.jsonl',199,'elementary_direct_proof; finite_exact_checks_support_only','["audits/hamburger_converse_round3.md ExceptionsC", "experiments/code/hamburger_arithmetic_round3.py", "experiments/results/hamburger_arithmetic_round3.json"]','{"id": "THM-HC304", "kind": "finite_pole_hypothesis_witness", "statement": "For integer q>=2, f(s)=zeta(s)/[(1−q^(2−s))(1−q^(1+s))] satisfies exact zeta FE and has an ordinary DS absolutely convergent for Re(s)>2, but infinitely many simple poles at s=2+2πik/logq.", "hypotheses": "Classical nonvanishing of zeta for Re(s)>1 from its absolutely convergent Euler product. Infinite-pole example, not a finite-pole converse exception.", "evidence": ["audits/hamburger_converse_round3.md ExceptionsC", "experiments/code/hamburger_arithmetic_round3.py", "experiments/results/hamburger_arithmetic_round3.json"], "status": "elementary_direct_proof; finite_exact_checks_support_only", "novelty_claim": false, "paper_id": null, "locator": ["audits/hamburger_converse_round3.md ExceptionsC", "experiments/code/hamburger_arithmetic_round3.py", "experiments/results/hamburger_arithmetic_round3.json"], "provenance_file": "theorems/hamburger_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'For integer q>=2, f(s)=zeta(s)/[(1−q^(2−s))(1−q^(1+s))] satisfies exact zeta FE and has an ordinary DS absolutely convergent for Re(s)>2, but infinitely many simple poles at s=2+2πik/logq.','finite_pole_hypothesis_witness','["audits/hamburger_converse_round3.md ExceptionsC", "experiments/code/hamburger_arithmetic_round3.py", "experiments/results/hamburger_arithmetic_round3.json"]','theorems/hamburger_round3.jsonl');
INSERT INTO "claims" VALUES('THM-HC305','theorems/theorems.jsonl',200,'independent_local_distribution_proof; parent_review_requested; standard_dictionary_inputs_explicit','["audits/hamburger_dictionary_round3.md Integer-comb lemma", "PAPER-HC005 Theorem4.54,pp592–593"]','{"id": "THM-HC305", "kind": "classical_integer_support_rigidity_reconstruction", "statement": "If the tempered even integer-supported measure D=sum a_n(delta_n+delta_(-n)) has Fourier(D)−D quasi-homogeneous, then all a_n are equal. Combined with the moderate Mellin dictionary this proves the self-dual ordinary-series converse.", "hypotheses": "Tempered D, ordinary integer frequencies, quasi-homogeneous even difference. No positivity or Euler product needed.", "evidence": ["audits/hamburger_dictionary_round3.md Integer-comb lemma", "PAPER-HC005 Theorem4.54,pp592–593"], "status": "independent_local_distribution_proof; parent_review_requested; standard_dictionary_inputs_explicit", "novelty_claim": false, "paper_id": null, "locator": ["audits/hamburger_dictionary_round3.md Integer-comb lemma", "PAPER-HC005 Theorem4.54,pp592–593"], "provenance_file": "theorems/hamburger_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'If the tempered even integer-supported measure D=sum a_n(delta_n+delta_(-n)) has Fourier(D)−D quasi-homogeneous, then all a_n are equal. Combined with the moderate Mellin dictionary this proves the self-dual ordinary-series converse.','classical_integer_support_rigidity_reconstruction','["audits/hamburger_dictionary_round3.md Integer-comb lemma", "PAPER-HC005 Theorem4.54,pp592–593"]','theorems/hamburger_round3.jsonl');
INSERT INTO "claims" VALUES('THM-HC306','theorems/theorems.jsonl',201,'independent_asymptotic_and_first_coefficient_proof; parent_review_requested','["audits/hamburger_converse_round3.md Addendum", "DLMF10.32.10 gamma integral", "THM-LB305"]','{"id": "THM-HC306", "kind": "Bessel_polynomial_arithmetic_obstruction", "statement": "For every c>0 and nonzero polynomial P of integer degree d, standard uncompletion of P(s−1/2)K_((s−1/2)/2)(c) is not an ordinary Dirichlet series convergent in any right half-plane. Its positive-real asymptotic is p_d c^(1/4)(2π/c)^(σ/2)σ^(d−9/4); a first nonzero ordinary coefficient would require d=9/4.", "hypotheses": "Fixed c and P; standard Γ(s/2)π^(−s/2) completion with s(s−1)/2 factor; nonzero constant normalization allowed. No assertion about nonpolynomial modifications or sums of shifted Bessel orders.", "evidence": ["audits/hamburger_converse_round3.md Addendum", "DLMF10.32.10 gamma integral", "THM-LB305"], "status": "independent_asymptotic_and_first_coefficient_proof; parent_review_requested", "novelty_claim": false, "paper_id": null, "locator": ["audits/hamburger_converse_round3.md Addendum", "DLMF10.32.10 gamma integral", "THM-LB305"], "provenance_file": "theorems/hamburger_round3.jsonl", "verification": "adjudicated_scoped; exact model/source/conditional boundaries in director review", "verification_status": "adjudicated_scoped; not a whole-paper audit, RH result, novelty claim or complete formal replay", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'For every c>0 and nonzero polynomial P of integer degree d, standard uncompletion of P(s−1/2)K_((s−1/2)/2)(c) is not an ordinary Dirichlet series convergent in any right half-plane. Its positive-real asymptotic is p_d c^(1/4)(2π/c)^(σ/2)σ^(d−9/4); a first nonzero ordinary coefficient would require d=9/4.','Bessel_polynomial_arithmetic_obstruction','["audits/hamburger_converse_round3.md Addendum", "DLMF10.32.10 gamma integral", "THM-LB305"]','theorems/hamburger_round3.jsonl');
INSERT INTO "claims" VALUES('OBS-HW501','theorems/theorems.jsonl',202,'adjudicated_scoped_classical_reconstruction; real_q_extension_checked','audits/weighted_criterion_round2.md; complete real-q Hardy membership/evaluation proof inthreshold62_mertens_shifted_weighted_review.md','{"id": "OBS-HW501", "paper_id": null, "kind": "classical_Hardy_zero_witness_reconstructed", "statement": "For every fixed realq>=1, finite Dirichlet polynomialD and nontrivial zeta zero rho=beta+i gamma withbeta>1/2, d_q(D)>=sqrt(2beta-1)|rho-1|/|rho|^(q+1). Hence convergence tozero of any such finite-array error, evenalong an unbounded subsequence, impliesRH.", "hypotheses": "d_q²=(2pi)^-1integral|1-zeta(1/2+it)D(1/2+it)|²dt/|1/2+it|^(2q); no coefficientconstraints or zero-spacing/simplicity premise; classical functional equation forreflection.", "locator": "audits/weighted_criterion_round2.md; complete real-q Hardy membership/evaluation proof inthreshold62_mertens_shifted_weighted_review.md", "status": "adjudicated_scoped_classical_reconstruction; real_q_extension_checked", "novelty_claim": false, "provenance_file": "theorems/hardy_real_weight_director_round5.jsonl"}',NULL,'For every fixed realq>=1, finite Dirichlet polynomialD and nontrivial zeta zero rho=beta+i gamma withbeta>1/2, d_q(D)>=sqrt(2beta-1)|rho-1|/|rho|^(q+1). Hence convergence tozero of any such finite-array error, evenalong an unbounded subsequence, impliesRH.','classical_Hardy_zero_witness_reconstructed','audits/weighted_criterion_round2.md; complete real-q Hardy membership/evaluation proof inthreshold62_mertens_shifted_weighted_review.md','theorems/hardy_real_weight_director_round5.jsonl');
INSERT INTO "claims" VALUES('THM-HF301','theorems/theorems.jsonl',203,'Original statement and cosine-product dominated-limit proof inspected,criticalpageimagechecked; full30-page source not audited.','Theorem10,p204; Theorem13/proof,p205','{"theorem_id": "THM-HF301", "paper_id": "PAPER-D303", "locator": "Theorem10,p204; Theorem13/proof,p205", "kind": "published strip-contraction theorem", "statement": "For integrable Hermitian-symmetric f:R→C, f(u)=conjugate(f(−u)), decayO(exp(−|u|^β)),β>2,and all Fourier zeros in|Imz|≤Δ, the multiplierexp(λ²u²/2),λ>0, gives all zeros in sqrt(max(Δ²−λ²,0)); direct heatτ=λ²/2 gives coefficient2. Positivity/C∞ are not required.", "verification_status": "Original statement and cosine-product dominated-limit proof inspected,criticalpageimagechecked; full30-page source not audited.", "id": "THM-HF301", "provenance_file": "theorems/heatflow_round2.jsonl"}','PAPER-D303','For integrable Hermitian-symmetric f:R→C, f(u)=conjugate(f(−u)), decayO(exp(−|u|^β)),β>2,and all Fourier zeros in|Imz|≤Δ, the multiplierexp(λ²u²/2),λ>0, gives all zeros in sqrt(max(Δ²−λ²,0)); direct heatτ=λ²/2 gives coefficient2. Positivity/C∞ are not required.','published strip-contraction theorem','Theorem10,p204; Theorem13/proof,p205','theorems/heatflow_round2.jsonl');
INSERT INTO "claims" VALUES('THM-HF302','theorems/theorems.jsonl',204,'Original statement inspected; application to quartic polynomial checked. Entire main proof not independently audited.','Theorem1,p198','{"theorem_id": "THM-HF302", "paper_id": "PAPER-D303", "locator": "Theorem1,p198", "kind": "published real-zero kernel theorem", "statement": "A nonconstant even nonnegative real-axis entire potentialf whose derivative is a locally uniform limit of polynomials with imaginary-axis roots has Fouriertransformexp(−f(u)) with only real zeros. Quarticf=(u/ε)^4 satisfies the hypotheses exactly.", "verification_status": "Original statement inspected; application to quartic polynomial checked. Entire main proof not independently audited.", "id": "THM-HF302", "provenance_file": "theorems/heatflow_round2.jsonl"}','PAPER-D303','A nonconstant even nonnegative real-axis entire potentialf whose derivative is a locally uniform limit of polynomials with imaginary-axis roots has Fouriertransformexp(−f(u)) with only real zeros. Quarticf=(u/ε)^4 satisfies the hypotheses exactly.','published real-zero kernel theorem','Theorem1,p198','theorems/heatflow_round2.jsonl');
INSERT INTO "claims" VALUES('THM-HF303','theorems/theorems.jsonl',205,'Entire7-page article read; exact formula/conditions checked againstp247image; weak-limit proof architecture reconstructed,external antecedents not fully audited.','Theorem2,pp246–247; proofpp247–251','{"theorem_id": "THM-HF303", "paper_id": "PAPER-D304", "locator": "Theorem2,pp246–247; proofpp247–251", "kind": "published classification theorem", "statement": "Nonzero even nonnegative finiteρ has Z_b(w)=∫exp(wu−bu²)dρ with only imaginary zeros for everyb>0 iffρ=K(δ_t0+δ_-t0),K>0,t0≥0,orρ has densityK u^(2m)exp(−αu^4−βu²)∏j[(1+u²/aj²)exp(−u²/aj²)],K>0,m∈N0,aj>0,Σaj^-4<∞,and eitherα>0,βreal,orα=0,β+Σaj^-2>0 (automatic ifsum∞).", "verification_status": "Entire7-page article read; exact formula/conditions checked againstp247image; weak-limit proof architecture reconstructed,external antecedents not fully audited.", "id": "THM-HF303", "provenance_file": "theorems/heatflow_round2.jsonl"}','PAPER-D304','Nonzero even nonnegative finiteρ has Z_b(w)=∫exp(wu−bu²)dρ with only imaginary zeros for everyb>0 iffρ=K(δ_t0+δ_-t0),K>0,t0≥0,orρ has densityK u^(2m)exp(−αu^4−βu²)∏j[(1+u²/aj²)exp(−u²/aj²)],K>0,m∈N0,aj>0,Σaj^-4<∞,and eitherα>0,βreal,orα=0,β+Σaj^-2>0 (automatic ifsum∞).','published classification theorem','Theorem2,pp246–247; proofpp247–251','theorems/heatflow_round2.jsonl');
INSERT INTO "claims" VALUES('THM-HF304','theorems/theorems.jsonl',206,'Originalpageimageandproofread; quartic-tail lower-bound contradiction and endpoint closure independently reconstructed. No RH conclusion asserted.','Theorem3,p247; equations1.1–1.4,p245','{"theorem_id": "THM-HF304", "paper_id": "PAPER-D304", "locator": "Theorem3,p247; equations1.1–1.4,p245", "kind": "published finite Riemann heat threshold", "statement": "With Ξ_b(x)=∫exp(ixu−bu²)F(u)du,Ξ_0(x)=ξ(1/2+ix),there isfinite−1/8≤b0<∞ such thatΞ_b hasonlyrealzeros iff b≤b0,includingendpoint. RHmeansb0≥0; Newmanconjecturesb0≤0. F is the specified positive even super-exponentially decaying Riemann kernel.", "verification_status": "Originalpageimageandproofread; quartic-tail lower-bound contradiction and endpoint closure independently reconstructed. No RH conclusion asserted.", "id": "THM-HF304", "provenance_file": "theorems/heatflow_round2.jsonl"}','PAPER-D304','With Ξ_b(x)=∫exp(ixu−bu²)F(u)du,Ξ_0(x)=ξ(1/2+ix),there isfinite−1/8≤b0<∞ such thatΞ_b hasonlyrealzeros iff b≤b0,includingendpoint. RHmeansb0≥0; Newmanconjecturesb0≤0. F is the specified positive even super-exponentially decaying Riemann kernel.','published finite Riemann heat threshold','Theorem3,p247; equations1.1–1.4,p245','theorems/heatflow_round2.jsonl');
INSERT INTO "claims" VALUES('THM-HF305','theorems/theorems.jsonl',207,'Both actual primary kernel formulas inspected and substitution checked; not memory-based convention matching.','Newman1.2,p245; Rodgers–TaoPAPER-S004 equations1–4,p2; audits/heatflow_round2.md §3','{"theorem_id": "THM-HF305", "paper_id": null, "locator": "Newman1.2,p245; Rodgers–TaoPAPER-S004 equations1–4,p2; audits/heatflow_round2.md §3", "kind": "exact normalization conversion", "statement": "F_Newman(2u)=2Φ_RodgersTao(u),soΞ_b(x)=8H_(−4b)(2x),andΛ_standard=−4b0. Originalb0≥−1/8 becomesstandardΛ≤1/2. Sign and scale are both essential.", "verification_status": "Both actual primary kernel formulas inspected and substitution checked; not memory-based convention matching.", "source_theorems": ["THM-HF304", "THM-S004-NEWMAN"], "id": "THM-HF305", "provenance_file": "theorems/heatflow_round2.jsonl"}',NULL,'F_Newman(2u)=2Φ_RodgersTao(u),soΞ_b(x)=8H_(−4b)(2x),andΛ_standard=−4b0. Originalb0≥−1/8 becomesstandardΛ≤1/2. Sign and scale are both essential.','exact normalization conversion','Newman1.2,p245; Rodgers–TaoPAPER-S004 equations1–4,p2; audits/heatflow_round2.md §3','theorems/heatflow_round2.jsonl');
INSERT INTO "claims" VALUES('THM-HF306','theorems/theorems.jsonl',208,'Elementary complete zero classification supplied; independent review pending; noveltyunassessed.','audits/heatflow_round2.md §5','{"theorem_id": "THM-HF306", "paper_id": null, "locator": "audits/heatflow_round2.md §5", "kind": "exact positive atomic heat model", "statement": "ρ_a=coshaδ0+(δ1+δ_-1)/2 has Laplacetransformcoshw+cosha. Forward Laplaceheat givese^τcoshw+cosha,withonlyimaginaryzeros iffτ≥logcosha. Atthreshold zerosare double; belowthreshold zerosare±arcosh(e^-τcosha)+(2m+1)iπ. For a>0 thresholdpositive. AtomsfitNewmanmeasureambientclass,notdeBruijnintegrable-function hypotheses.", "verification_status": "Elementary complete zero classification supplied; independent review pending; noveltyunassessed.", "id": "THM-HF306", "provenance_file": "theorems/heatflow_round2.jsonl"}',NULL,'ρ_a=coshaδ0+(δ1+δ_-1)/2 has Laplacetransformcoshw+cosha. Forward Laplaceheat givese^τcoshw+cosha,withonlyimaginaryzeros iffτ≥logcosha. Atthreshold zerosare double; belowthreshold zerosare±arcosh(e^-τcosha)+(2m+1)iπ. For a>0 thresholdpositive. AtomsfitNewmanmeasureambientclass,notdeBruijnintegrable-function hypotheses.','exact positive atomic heat model','audits/heatflow_round2.md §5','theorems/heatflow_round2.jsonl');
INSERT INTO "claims" VALUES('THM-HF307','theorems/theorems.jsonl',209,'derived auxiliary proposition under review; no classicalRHgain/noveltyclaim','audits/heatflow_round2.md §6','{"theorem_id": "THM-HF307", "paper_id": null, "locator": "audits/heatflow_round2.md §6", "kind": "derived smooth source-class control", "statement": "Convolveρ_a with normalizedhε(u)=cεexp(−(u/ε)^4). The resultingdensity is strictlypositive,even,C∞,superGaussian; its initial Fourierzeros have exact striphalfwidtha. It has a finite upwardheatthreshold0<Λ_(a,ε)≤a²/2. Locallyuniformheattransform convergence to the atomic model gives liminfε→0Λ_(a,ε)≥logcosha; no claim of exact threshold convergence.", "verification_status": "Full source-hypothesis match,quartic-mollifierzero theorem,dominated convergence,Rouché witness and threshold proof supplied; independent adversarial review pending.", "source_theorems": ["THM-HF301", "THM-HF302", "THM-HF306"], "status": "derived auxiliary proposition under review; no classicalRHgain/noveltyclaim", "id": "THM-HF307", "provenance_file": "theorems/heatflow_round2.jsonl"}',NULL,'Convolveρ_a with normalizedhε(u)=cεexp(−(u/ε)^4). The resultingdensity is strictlypositive,even,C∞,superGaussian; its initial Fourierzeros have exact striphalfwidtha. It has a finite upwardheatthreshold0<Λ_(a,ε)≤a²/2. Locallyuniformheattransform convergence to the atomic model gives liminfε→0Λ_(a,ε)≥logcosha; no claim of exact threshold convergence.','derived smooth source-class control','audits/heatflow_round2.md §6','theorems/heatflow_round2.jsonl');
INSERT INTO "claims" VALUES('THM-HF308','theorems/theorems.jsonl',210,'Explicit analytic witness proof supplied; independent review pending; literature noveltyunassessed.','audits/heatflow_round2.md §6,sharpness paragraph','{"theorem_id": "THM-HF308", "paper_id": null, "locator": "audits/heatflow_round2.md §6,sharpness paragraph", "kind": "derived sharpness obstruction", "statement": "No universal replacement of2 byc>2 in sqrt(max(a²−2τ,0)) can hold even for strictlypositiveevenC∞superGaussian kernel functions. Chooseasmallwithlogcosha>a²/c and εsmall; the atomic off-axiszero atτ=a²/c persists in the admissible smooth approximation.", "verification_status": "Explicit analytic witness proof supplied; independent review pending; literature noveltyunassessed.", "source_theorems": ["THM-HF307"], "id": "THM-HF308", "provenance_file": "theorems/heatflow_round2.jsonl"}',NULL,'No universal replacement of2 byc>2 in sqrt(max(a²−2τ,0)) can hold even for strictlypositiveevenC∞superGaussian kernel functions. Chooseasmallwithlogcosha>a²/c and εsmall; the atomic off-axiszero atτ=a²/c persists in the admissible smooth approximation.','derived sharpness obstruction','audits/heatflow_round2.md §6,sharpness paragraph','theorems/heatflow_round2.jsonl');
INSERT INTO "claims" VALUES('THM-HF309','theorems/theorems.jsonl',211,'auxiliary criterion countermodel under review','audits/heatflow_round2.md §7','{"theorem_id": "THM-HF309", "paper_id": null, "locator": "audits/heatflow_round2.md §7", "kind": "finite-prefix positivity versus heat-threshold obstruction", "statement": "For everyfiniteN thereexists0<a<1/2 withλ1..λN>0 forX_a(s)=cosh(s−1/2)+cosha,whilezeroslieonRe(s)=1/2±a andheatthresholdlogcosha>0. Quartic smoothing preserves that positiveprefix byaddingnonnegative critical-line paired-zero Li-type contributions,yetretainspositivefiniteheatthreshold. λn is the explicit Li derivative functional,not a classicalξ coefficient.", "verification_status": "Pair-product positivity at a0,finite continuity and Hadamard-product smoothing proof supplied; independent review pending.", "source_theorems": ["THM-HF306", "THM-HF307"], "status": "auxiliary criterion countermodel under review", "id": "THM-HF309", "provenance_file": "theorems/heatflow_round2.jsonl"}',NULL,'For everyfiniteN thereexists0<a<1/2 withλ1..λN>0 forX_a(s)=cosh(s−1/2)+cosha,whilezeroslieonRe(s)=1/2±a andheatthresholdlogcosha>0. Quartic smoothing preserves that positiveprefix byaddingnonnegative critical-line paired-zero Li-type contributions,yetretainspositivefiniteheatthreshold. λn is the explicit Li derivative functional,not a classicalξ coefficient.','finite-prefix positivity versus heat-threshold obstruction','audits/heatflow_round2.md §7','theorems/heatflow_round2.jsonl');
INSERT INTO "claims" VALUES('THM-HF310','theorems/theorems.jsonl',212,'computational certificate under independent review','experiments/code/heatflow_round2.py; results/heatflow_round2.json','{"theorem_id": "THM-HF310", "paper_id": null, "locator": "experiments/code/heatflow_round2.py; results/heatflow_round2.json", "kind": "finite interval computation", "statement": "At exacta=1/100 the first100 Li-type coefficients ofcosh(s−1/2)+cosha are enclosed strictlypositive by180digit directed Decimal interval arithmetic with exact rational hyperbolic Taylor-tail bounds. Minimumlowerendpoint>0.2449129068. Atomicthresholdlogcosh(1/100)has a rigorouslypositive bracket near5e−5.", "verification_status": "Reproducible interval code passes; independent recurrence/rounding audit pending. This is a finite enclosure,not anall-n/RHclaim.", "status": "computational certificate under independent review", "id": "THM-HF310", "provenance_file": "theorems/heatflow_round2.jsonl"}',NULL,'At exacta=1/100 the first100 Li-type coefficients ofcosh(s−1/2)+cosha are enclosed strictlypositive by180digit directed Decimal interval arithmetic with exact rational hyperbolic Taylor-tail bounds. Minimumlowerendpoint>0.2449129068. Atomicthresholdlogcosh(1/100)has a rigorouslypositive bracket near5e−5.','finite interval computation','experiments/code/heatflow_round2.py; results/heatflow_round2.json','theorems/heatflow_round2.jsonl');
INSERT INTO "claims" VALUES('OBS-HG501','theorems/theorems.jsonl',213,'adjudicated_scoped_ordinary_analytic_theorem; priority_unassessed','audits/adversarial_reviews/director_round5_adjudication.md; two full proofs cited there','{"id": "OBS-HG501", "paper_id": null, "kind": "general_positive_real_boundary_energy_theorem", "statement": "Let G(w)=a w+i b+integral[1/(w-i gamma)-i gamma/(1+gamma²)]mu(dgamma), a>=0,b real,mu positive and integral(1+gamma²)^-1dmu finite. H_epsilon(w)=exp(-integral_0^epsilonG(w+r)dr). For every fixedx>0, lim_epsilon↓0 epsilon^-1 integral|1-H_epsilon(it)|² x dt/[pi(x²+t²)] =2ax+Sum_atoms 2x alpha_gamma[1-Gamma(alpha_gamma+1/2)/(sqrt(pi)Gamma(alpha_gamma+1))]/(x²+gamma²), alpha_gamma=mu{gamma}. The series converges; nonatomic mass contributes0.", "hypotheses": "Specified compensated positive Herglotz representation; no finite-total-mass, atom-isolation or compact-support assumption. Boundary values are almost-everywhere Fatou values.", "locator": "audits/adversarial_reviews/director_round5_adjudication.md; two full proofs cited there", "status": "adjudicated_scoped_ordinary_analytic_theorem; priority_unassessed", "novelty_claim": false, "provenance_file": "theorems/herglotz_semigroup_director_round5.jsonl"}',NULL,'Let G(w)=a w+i b+integral[1/(w-i gamma)-i gamma/(1+gamma²)]mu(dgamma), a>=0,b real,mu positive and integral(1+gamma²)^-1dmu finite. H_epsilon(w)=exp(-integral_0^epsilonG(w+r)dr). For every fixedx>0, lim_epsilon↓0 epsilon^-1 integral|1-H_epsilon(it)|² x dt/[pi(x²+t²)] =2ax+Sum_atoms 2x alpha_gamma[1-Gamma(alpha_gamma+1/2)/(sqrt(pi)Gamma(alpha_gamma+1))]/(x²+gamma²), alpha_gamma=mu{gamma}. The series converges; nonatomic mass contributes0.','general_positive_real_boundary_energy_theorem','audits/adversarial_reviews/director_round5_adjudication.md; two full proofs cited there','theorems/herglotz_semigroup_director_round5.jsonl');
INSERT INTO "claims" VALUES('OBS-XW501','theorems/theorems.jsonl',214,'adjudicated_scoped_RH_conditional_operator_theorem','audits/adversarial_reviews/director_round5_adjudication.md; ratio62_semigroup.md; xi_weighted_semigroup_rt62_xi_semigroup.md','{"id": "OBS-XW501", "paper_id": null, "kind": "conditional_spectral_candidate_obstruction", "statement": "Assuming RH, F(w)=xi(1/2+w) defines W_tau f(w)=F(w)f(w+tau)/F(w+tau) as a C0 contraction semigroup on H²(Rew>0). Each tau>0 is compact, injective, quasinilpotent. Its actual generator A has D(A)={f inH²:fprime-(Fprime/F)f inH²}, Af=fprime-(Fprime/F)f, and empty spectrum.", "hypotheses": "Ordinary Hardy H² norm dt/(2pi), classical completed xi, RH and classical Riemann-vonMangoldt/product inputs. This precise semigroup and maximal domain only.", "locator": "audits/adversarial_reviews/director_round5_adjudication.md; ratio62_semigroup.md; xi_weighted_semigroup_rt62_xi_semigroup.md", "status": "adjudicated_scoped_RH_conditional_operator_theorem", "novelty_claim": false, "limitation": "Not a proof of RH or obstruction to all spectral realizations.", "provenance_file": "theorems/herglotz_semigroup_director_round5.jsonl"}',NULL,'Assuming RH, F(w)=xi(1/2+w) defines W_tau f(w)=F(w)f(w+tau)/F(w+tau) as a C0 contraction semigroup on H²(Rew>0). Each tau>0 is compact, injective, quasinilpotent. Its actual generator A has D(A)={f inH²:fprime-(Fprime/F)f inH²}, Af=fprime-(Fprime/F)f, and empty spectrum.','conditional_spectral_candidate_obstruction','audits/adversarial_reviews/director_round5_adjudication.md; ratio62_semigroup.md; xi_weighted_semigroup_rt62_xi_semigroup.md','theorems/herglotz_semigroup_director_round5.jsonl');
INSERT INTO "claims" VALUES('OBS-XW502','theorems/theorems.jsonl',215,'adjudicated_scoped_conditional_corollary; separate boundary-pole verification','audits/adversarial_reviews/xi_weighted_semigroup_rt62_xi_semigroup.md; OBS-HG501 specialization','{"id": "OBS-XW502", "paper_id": null, "kind": "kernel_orbit_energy_and_domain_obstruction", "statement": "For the same RH-conditional semigroup and normalized kernel k_z(w)=sqrt(2x)/(w+conj(z)),z=x+i y,x>0, lim_tau↓0 ||W_tau k_z-k_z||²/tau =Sum_distinct_gamma 2x m_gamma[1-binomial(2m_gamma,m_gamma)/4^m_gamma]/[x²+(gamma-y)²]>0. Thus every normalized evaluation kernel lies outside D(A).", "hypotheses": "Same Hilbert norm and operator as OBS-XW501; multiplicities retained, both signs of ordinates counted separately.", "locator": "audits/adversarial_reviews/xi_weighted_semigroup_rt62_xi_semigroup.md; OBS-HG501 specialization", "status": "adjudicated_scoped_conditional_corollary; separate boundary-pole verification", "novelty_claim": false, "provenance_file": "theorems/herglotz_semigroup_director_round5.jsonl"}',NULL,'For the same RH-conditional semigroup and normalized kernel k_z(w)=sqrt(2x)/(w+conj(z)),z=x+i y,x>0, lim_tau↓0 ||W_tau k_z-k_z||²/tau =Sum_distinct_gamma 2x m_gamma[1-binomial(2m_gamma,m_gamma)/4^m_gamma]/[x²+(gamma-y)²]>0. Thus every normalized evaluation kernel lies outside D(A).','kernel_orbit_energy_and_domain_obstruction','audits/adversarial_reviews/xi_weighted_semigroup_rt62_xi_semigroup.md; OBS-HG501 specialization','theorems/herglotz_semigroup_director_round5.jsonl');
INSERT INTO "claims" VALUES('OBS-XW503','theorems/theorems.jsonl',216,'adjudicated_scoped_RH_conditional_norm_asymptotic','audits/adversarial_reviews/ratio62_semigroup.md; xi_semigroup_norm_rt62_xi_semigroup.md; director_round5_adjudication.md','{"id": "OBS-XW503", "paper_id": null, "kind": "sharp_large_time_semigroup_norm", "statement": "For the same RH-conditional xi semigroup, log||W_tau||=-(tau/2)logtau+(tau/2)(1+log(2pi))+O(logtau) as tau→infinity.", "hypotheses": "Ordinary Hardy norm and exact operator ofOBS-XW501; fixed normalized evaluation kernel for the lower bound, uniform right-half-plane digamma/Dirichlet-series bound for upper.", "locator": "audits/adversarial_reviews/ratio62_semigroup.md; xi_semigroup_norm_rt62_xi_semigroup.md; director_round5_adjudication.md", "status": "adjudicated_scoped_RH_conditional_norm_asymptotic", "novelty_claim": false, "provenance_file": "theorems/herglotz_semigroup_director_round5.jsonl"}',NULL,'For the same RH-conditional xi semigroup, log||W_tau||=-(tau/2)logtau+(tau/2)(1+log(2pi))+O(logtau) as tau→infinity.','sharp_large_time_semigroup_norm','audits/adversarial_reviews/ratio62_semigroup.md; xi_semigroup_norm_rt62_xi_semigroup.md; director_round5_adjudication.md','theorems/herglotz_semigroup_director_round5.jsonl');
INSERT INTO "claims" VALUES('THM-H001-ROBIN','theorems/theorems.jsonl',217,'whole_source_read;scoped_reconstruction_only','Theorem1,p188;proof§3Prop3,p204 and§4Prop1,pp204–205','{"theorem_id": "THM-H001-ROBIN", "paper_id": "PAPER-H001", "kind": "established_equivalence", "statement": "RH iff σ(n)<e^γ n log log n for every integer n≥5041.", "source_locator": "Theorem1,p188;proof§3Prop3,p204 and§4Prop1,pp204–205", "verification_status": "whole_source_read;scoped_reconstruction_only", "id": "THM-H001-ROBIN", "locator": "Theorem1,p188;proof§3Prop3,p204 and§4Prop1,pp204–205", "provenance_file": "theorems/history_round2.jsonl"}','PAPER-H001','RH iff σ(n)<e^γ n log log n for every integer n≥5041.','established_equivalence','Theorem1,p188;proof§3Prop3,p204 and§4Prop1,pp204–205','theorems/history_round2.jsonl');
