INSERT INTO "claims" VALUES('COR-H001-CA-LAG','theorems/theorems.jsonl',221,'independent_review_requested','PAPER-H001 reconciliationwithPAPER-R001Lemma3.2','{"theorem_id": "COR-H001-CA-LAG", "paper_id": null, "kind": "derived_known_input_corollary_no_novelty_claim", "statement": "For any fixed B, RH iff the Lagarias inequality holds for all CA integers n≥B. Under ¬RH, positive CA excess dominates Lagarias slack O(n/log n).", "source_locator": "PAPER-H001 reconciliationwithPAPER-R001Lemma3.2", "verification_status": "independent_review_requested", "id": "COR-H001-CA-LAG", "locator": "PAPER-H001 reconciliationwithPAPER-R001Lemma3.2", "provenance_file": "theorems/history_round2.jsonl"}',NULL,'For any fixed B, RH iff the Lagarias inequality holds for all CA integers n≥B. Under ¬RH, positive CA excess dominates Lagarias slack O(n/log n).','derived_known_input_corollary_no_novelty_claim','PAPER-H001 reconciliationwithPAPER-R001Lemma3.2','theorems/history_round2.jsonl');
