INSERT INTO "claims" VALUES('THM-HR406','theorems/theorems.jsonl',227,'Finitesquarefreedivisorcancellationchecked;noRHorPNTinput.','Original58–59,Eq12;Riemannoriginal679','{"theorem_id": "THM-HR406", "paper_id": "PAPER-H402", "kind": "published_finite_Mobius_inversion", "locator": "Original58–59,Eq12;Riemannoriginal679", "statement": "pi0(x)=sum_m>=1 mu(m)J0(x^(1/m))/m;sumisfiniteforfixedx>1andmidpointprimepowerweightspreserved.", "verification_status": "Finitesquarefreedivisorcancellationchecked;noRHorPNTinput.", "id": "THM-HR406", "provenance_file": "theorems/history_round4_corpus.jsonl"}','PAPER-H402','pi0(x)=sum_m>=1 mu(m)J0(x^(1/m))/m;sumisfiniteforfixedx>1andmidpointprimepowerweightspreserved.','published_finite_Mobius_inversion','Original58–59,Eq12;Riemannoriginal679','theorems/history_round4_corpus.jsonl');
