INSERT INTO "claims" VALUES('THM-HR409','theorems/theorems.jsonl',230,'Modern3+4cos+cos2 reconstruction, independently checked by root; historicalsourceproofdifferent and separately preserved.','§5,202; audit§1','{"theorem_id": "THM-HR409", "paper_id": "PAPER-H401", "kind": "precise_modern_sufficient_form_of_source_lemma", "locator": "§5,202; audit§1", "statement": "If log f=Σa_n exp(−λ_ns), a_n≥0, λ_n>0 real, absolutely convergent Re s>1, and f continues meromorphically across Re s=1 with sole boundary pole simple at1, then f(1+it)≠0 for t≠0.", "verification_status": "Modern3+4cos+cos2 reconstruction, independently checked by root; historicalsourceproofdifferent and separately preserved.", "id": "THM-HR409", "provenance_file": "theorems/history_round4_corpus.jsonl"}','PAPER-H401','If log f=Σa_n exp(−λ_ns), a_n≥0, λ_n>0 real, absolutely convergent Re s>1, and f continues meromorphically across Re s=1 with sole boundary pole simple at1, then f(1+it)≠0 for t≠0.','precise_modern_sufficient_form_of_source_lemma','§5,202; audit§1','theorems/history_round4_corpus.jsonl');
INSERT INTO "claims" VALUES('THM-HR410','theorems/theorems.jsonl',231,'Exactcentralformulaimageschecked; tailmechanismreconstructed conditionalonhistoricalgenus/contourestimates,notcompletepaperLevel2.','§§12–17,211–217; Eqs17–19','{"theorem_id": "THM-HR410", "paper_id": "PAPER-H401", "kind": "published_smoothed_prime_power_asymptotic", "locator": "§§12–17,211–217; Eqs17–19", "statement": "For a>1, μ>1, ψμ(x)=−(2πi)^−1∫_(a−i∞)^(a+i∞)(ζ′/ζ)(s)x^s/s^μ ds =Γ(μ)^−1Σ_(p^k<x)logp[log(x/p^k)]^(μ−1)~x.", "verification_status": "Exactcentralformulaimageschecked; tailmechanismreconstructed conditionalonhistoricalgenus/contourestimates,notcompletepaperLevel2.", "id": "THM-HR410", "provenance_file": "theorems/history_round4_corpus.jsonl"}','PAPER-H401','For a>1, μ>1, ψμ(x)=−(2πi)^−1∫_(a−i∞)^(a+i∞)(ζ′/ζ)(s)x^s/s^μ ds =Γ(μ)^−1Σ_(p^k<x)logp[log(x/p^k)]^(μ−1)~x.','published_smoothed_prime_power_asymptotic','§§12–17,211–217; Eqs17–19','theorems/history_round4_corpus.jsonl');
INSERT INTO "claims" VALUES('THM-HR411','theorems/theorems.jsonl',232,'Full elementary two-sided proof reconstructed and independently checked by root; no quantitative rate inferred from bare asymptotic.','§18,217–218; audit§3','{"theorem_id": "THM-HR411", "paper_id": "PAPER-H401", "kind": "published_monotone_unsmoothing", "locator": "§18,217–218; audit§3", "statement": "For nondecreasing θ and A(v)−A(u)=∫_u^v θ(t)dt/t, A(x)~x implies θ(x)~x. Fixed multiplicative h first, x→∞ then h→0.", "verification_status": "Full elementary two-sided proof reconstructed and independently checked by root; no quantitative rate inferred from bare asymptotic.", "id": "THM-HR411", "provenance_file": "theorems/history_round4_corpus.jsonl"}','PAPER-H401','For nondecreasing θ and A(v)−A(u)=∫_u^v θ(t)dt/t, A(x)~x implies θ(x)~x. Fixed multiplicative h first, x→∞ then h→0.','published_monotone_unsmoothing','§18,217–218; audit§3','theorems/history_round4_corpus.jsonl');
