INSERT INTO "claims" VALUES('OBS-HR501','theorems/theorems.jsonl',247,'adjudicated_scoped_RH_conditional; priority_unassessed','audits/adversarial_reviews/horizontal_ratio_slope_director_adjudication_round5.md; complete three proofs cited there','{"id": "OBS-HR501", "paper_id": null, "kind": "independently_reconstructed_conditional_theorem", "statement": "Under RH, lim_(epsilon↓0)J_epsilon/epsilon=Sum_(distinct ordinatesgamma)m_gamma[1−binomial(2m_gamma,m_gamma)/4^m_gamma]/(1/4+gamma²), with both signs included separately and absolute convergence.", "definitions": "J_epsilon=(2pi)^−1 integral_R |zeta(1/2+it)/zeta(1/2+epsilon+it)−1|²dt/(1/4+t²); m_gamma is analytic zero multiplicity.", "hypotheses": ["RH", "epsilon→0 through positive real values", "standard order-one completed xi and its paired Hadamard product", "no simplicity or spacing assumption"], "locator": "audits/adversarial_reviews/horizontal_ratio_slope_director_adjudication_round5.md; complete three proofs cited there", "status": "adjudicated_scoped_RH_conditional; priority_unassessed", "novelty_claim": false, "source_question": "PAPER-C103 Proposition2 and subsequent precise-asymptotic remark", "provenance_file": "theorems/horizontal_ratio_slope_director_round5.jsonl"}',NULL,'Under RH, lim_(epsilon↓0)J_epsilon/epsilon=Sum_(distinct ordinatesgamma)m_gamma[1−binomial(2m_gamma,m_gamma)/4^m_gamma]/(1/4+gamma²), with both signs included separately and absolute convergence.','independently_reconstructed_conditional_theorem','audits/adversarial_reviews/horizontal_ratio_slope_director_adjudication_round5.md; complete three proofs cited there','theorems/horizontal_ratio_slope_director_round5.jsonl');
INSERT INTO "claims" VALUES('OBS-HR502','theorems/theorems.jsonl',248,'adjudicated_scoped_corollary; no simplicity certificate or priority claim','audits/adversarial_reviews/horizontal_ratio_slope_director_adjudication_round5.md; central-binomial monotonicity c_(m+1)/c_m=(2m+1)/(2m+2)','{"id": "OBS-HR502", "paper_id": null, "kind": "conditional_multiplicity_characterization", "statement": "Assuming RH, the horizontal-ratio slope in OBS-HR501 is at least C0=xi′(1)/xi(1)=1+EulerGamma/2−log(4pi)/2, with equality iff every nontrivial zeta zero is simple; the slope is strictly less than2C0.", "hypotheses": ["RH", "same full-height J_epsilon and limiting quantifier as OBS-HR501"], "locator": "audits/adversarial_reviews/horizontal_ratio_slope_director_adjudication_round5.md; central-binomial monotonicity c_(m+1)/c_m=(2m+1)/(2m+2)", "status": "adjudicated_scoped_corollary; no simplicity certificate or priority claim", "novelty_claim": false, "provenance_file": "theorems/horizontal_ratio_slope_director_round5.jsonl"}',NULL,'Assuming RH, the horizontal-ratio slope in OBS-HR501 is at least C0=xi′(1)/xi(1)=1+EulerGamma/2−log(4pi)/2, with equality iff every nontrivial zeta zero is simple; the slope is strictly less than2C0.','conditional_multiplicity_characterization','audits/adversarial_reviews/horizontal_ratio_slope_director_adjudication_round5.md; central-binomial monotonicity c_(m+1)/c_m=(2m+1)/(2m+2)','theorems/horizontal_ratio_slope_director_round5.jsonl');
INSERT INTO "claims" VALUES('OBS-HR503','theorems/theorems.jsonl',249,'adjudicated_scoped_exact_counterexample','audits/adversarial_reviews/horizontal_ratio_slope_skeptic_round4.md §6; exact expression1+exp(−2epsilon²)−2exp(−epsilon²−epsilon)','{"id": "OBS-HR503", "paper_id": null, "kind": "negative_control_counterexample", "statement": "For even zero-free F(w)=exp(w²), H_epsilon=F(w)/F(w+epsilon) is Schur on Rew>0 yet its Poisson-centered squared-defect slope at x=1/2 is2. Thus contractivity and evenness alone do not justify exhaustion of all first-order boundary energy by zeros.", "hypotheses": ["Order-two F, deliberately outside the xi order-one product hypothesis", "dnu=dt/[2pi(1/4+t²)]"], "locator": "audits/adversarial_reviews/horizontal_ratio_slope_skeptic_round4.md §6; exact expression1+exp(−2epsilon²)−2exp(−epsilon²−epsilon)", "status": "adjudicated_scoped_exact_counterexample", "novelty_claim": false, "provenance_file": "theorems/horizontal_ratio_slope_director_round5.jsonl"}',NULL,'For even zero-free F(w)=exp(w²), H_epsilon=F(w)/F(w+epsilon) is Schur on Rew>0 yet its Poisson-centered squared-defect slope at x=1/2 is2. Thus contractivity and evenness alone do not justify exhaustion of all first-order boundary energy by zeros.','negative_control_counterexample','audits/adversarial_reviews/horizontal_ratio_slope_skeptic_round4.md §6; exact expression1+exp(−2epsilon²)−2exp(−epsilon²−epsilon)','theorems/horizontal_ratio_slope_director_round5.jsonl');
INSERT INTO "claims" VALUES('THM-RI301','theorems/theorems.jsonl',250,'Original statement/proof and cancellation example inspected; full Potapov foundations and whole paper not audited.','Theorem3.1/proof and following remarks,pp10–11,arXivv2','{"theorem_id": "THM-RI301", "paper_id": "PAPER-D301", "locator": "Theorem3.1/proof and following remarks,pp10–11,arXivv2", "kind": "source factorization theorem/context", "statement": "Rational para-unitary matrix functions have Blaschke–Potapov factorizations by rank-one projection factors and constant (co)isometries. Source permits poles on either side of the unit circle; arbitrary factor products may have degree cancellation.", "verification_status": "Original statement/proof and cancellation example inspected; full Potapov foundations and whole paper not audited.", "id": "THM-RI301", "provenance_file": "theorems/inner_round2.jsonl"}','PAPER-D301','Rational para-unitary matrix functions have Blaschke–Potapov factorizations by rank-one projection factors and constant (co)isometries. Source permits poles on either side of the unit circle; arbitrary factor products may have degree cancellation.','source factorization theorem/context','Theorem3.1/proof and following remarks,pp10–11,arXivv2','theorems/inner_round2.jsonl');
INSERT INTO "claims" VALUES('THM-RI302','theorems/theorems.jsonl',251,'Primary formulas and coordinate matching checked; not a proof of the separate closed-boundary operator construction or full-paper audit.','§9, equations39–43,p18,arXivv2','{"theorem_id": "THM-RI302", "paper_id": "PAPER-D302", "locator": "§9, equations39–43,p18,arXivv2", "kind": "source passive realization construction", "statement": "Passive finite-state transfer realizations have A=−C_out* C_out/2−iΩ, B=−C_out*D, unitaryD. Rank-one factors admit the displayed oscillator realization and cascades represent factor products. Under s=−ik, D=I,C_out=G, transfer is I−iG(k−Ω+iG*G/2)^−1G*.", "verification_status": "Primary formulas and coordinate matching checked; not a proof of the separate closed-boundary operator construction or full-paper audit.", "id": "THM-RI302", "provenance_file": "theorems/inner_round2.jsonl"}','PAPER-D302','Passive finite-state transfer realizations have A=−C_out* C_out/2−iΩ, B=−C_out*D, unitaryD. Rank-one factors admit the displayed oscillator realization and cascades represent factor products. Under s=−ik, D=I,C_out=G, transfer is I−iG(k−Ω+iG*G/2)^−1G*.','source passive realization construction','§9, equations39–43,p18,arXivv2','theorems/inner_round2.jsonl');
INSERT INTO "claims" VALUES('THM-RI303','theorems/theorems.jsonl',252,'established auxiliary proposition; novelty unassessed','proposals/independent_campaigns/factored_inner_round2.md §§1–4','{"theorem_id": "THM-RI303", "paper_id": null, "locator": "proposals/independent_campaigns/factored_inner_round2.md §§1–4", "kind": "independently reconstructed finite-inner root count", "statement": "For W(k)=C∏j[I−Pj+((k−dj−iaj)/(k−dj+iaj))Pj] diag(exp(ikℓa)), ℓa,aj>0, orthogonalPj, M=ΣrankPj, all crossings through1 are positive. N((0,K])=LK/(2π)+G(K)+F(0)−F(K), 0≤F<E, G nondecreasing in[0,M]. Thus −3E−2M<ΔN<3E+M and |ΔN|<3E+2M.", "verification_status": "adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay", "hypotheses": ["Finite all-upper-half-plane inner factors, not arbitrary real-axis unitary functions.", "Positive finite edge lengths and one fixed model over all three compared heights.", "Endpoint eigenvalue1 uses argument0, so0excluded andKincluded."], "status": "established auxiliary proposition; novelty unassessed", "id": "THM-RI303", "provenance_file": "theorems/inner_round2.jsonl", "verification": "scoped_Level3; independent proposer/skeptic/director ordinary reconstruction; exact scope in adjudication", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'For W(k)=C∏j[I−Pj+((k−dj−iaj)/(k−dj+iaj))Pj] diag(exp(ikℓa)), ℓa,aj>0, orthogonalPj, M=ΣrankPj, all crossings through1 are positive. N((0,K])=LK/(2π)+G(K)+F(0)−F(K), 0≤F<E, G nondecreasing in[0,M]. Thus −3E−2M<ΔN<3E+M and |ΔN|<3E+2M.','independently reconstructed finite-inner root count','proposals/independent_campaigns/factored_inner_round2.md §§1–4','theorems/inner_round2.jsonl');
INSERT INTO "claims" VALUES('THM-RI304','theorems/theorems.jsonl',253,'independent reconstruction in established passive-realization framework; no literature novelty claim','proposals/independent_campaigns/factored_inner_round2.md §5','{"theorem_id": "THM-RI304", "paper_id": null, "locator": "proposals/independent_campaigns/factored_inner_round2.md §5", "kind": "constructive self-adjoint realization of factor class", "statement": "Choose Gj=sqrt(2aj)Vj with Pj=VjVj*. On edgeL2⊕C^M, use boundaryη−C*ξ=Gq and Haux=Ωq+iG*(η+C*ξ)/2, where Ωjj=djI and Ωjt=±iGj*Gt/2 with plus below diagonal. The operator is self-adjoint with compact resolvent. Its real spectral equation is exactly W(k)ξ=ξ with equal multiplicities; triangular elimination has no real poles or dark modes.", "verification_status": "adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay", "status": "independent reconstruction in established passive-realization framework; no literature novelty claim", "id": "THM-RI304", "provenance_file": "theorems/inner_round2.jsonl", "verification": "scoped_Level3; independent proposer/skeptic/director ordinary reconstruction; exact scope in adjudication", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'Choose Gj=sqrt(2aj)Vj with Pj=VjVj*. On edgeL2⊕C^M, use boundaryη−C*ξ=Gq and Haux=Ωq+iG*(η+C*ξ)/2, where Ωjj=djI and Ωjt=±iGj*Gt/2 with plus below diagonal. The operator is self-adjoint with compact resolvent. Its real spectral equation is exactly W(k)ξ=ξ with equal multiplicities; triangular elimination has no real poles or dark modes.','constructive self-adjoint realization of factor class','proposals/independent_campaigns/factored_inner_round2.md §5','theorems/inner_round2.jsonl');
INSERT INTO "claims" VALUES('THM-RI305','theorems/theorems.jsonl',254,'established auxiliary theorem under stated finite-model assumptions; novelty unassessed','proposals/independent_campaigns/factored_inner_round2.md §8','{"theorem_id": "THM-RI305", "paper_id": null, "locator": "proposals/independent_campaigns/factored_inner_round2.md §8", "kind": "general finite Hermitian auxiliary boundary model theorem", "statement": "For arbitrary finite HermitianΩ on C^M and G:C^M→C^E, constant unitaryC and positive edge lengths, define H=(-if′,Ωq+iG*μ) on domainη−C*ξ=Gq, μ=(η+C*ξ)/2. H is self-adjoint with compact resolvent. Split darkD=⊕λ(ker(Ω−λ)∩kerG). On its orthogonal complement A=Ωv−iGv*Gv/2 has strictly lower-half-plane spectrum. Visible transfer S0=I−iGv(k−A)^−1Gv* is rational inner, −iS0*S0′=GvR*RGv*≥0, determinant phase budget2πMv. Add finite dark counts Nd to the visible phase increment. Full N=LK/(2π)+Acount(K)+F0−F(K), with Acount nondecreasing in[0,M], giving −3E−2M<ΔN<3E+M, including coincident dark/visible multiplicities.", "verification_status": "adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay", "status": "established auxiliary theorem under stated finite-model assumptions; novelty unassessed", "id": "THM-RI305", "provenance_file": "theorems/inner_round2.jsonl", "verification": "scoped_Level3; independent proposer/skeptic/director ordinary reconstruction; exact scope in adjudication", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'For arbitrary finite HermitianΩ on C^M and G:C^M→C^E, constant unitaryC and positive edge lengths, define H=(-if′,Ωq+iG*μ) on domainη−C*ξ=Gq, μ=(η+C*ξ)/2. H is self-adjoint with compact resolvent. Split darkD=⊕λ(ker(Ω−λ)∩kerG). On its orthogonal complement A=Ωv−iGv*Gv/2 has strictly lower-half-plane spectrum. Visible transfer S0=I−iGv(k−A)^−1Gv* is rational inner, −iS0*S0′=GvR*RGv*≥0, determinant phase budget2πMv. Add finite dark counts Nd to the visible phase increment. Full N=LK/(2π)+Acount(K)+F0−F(K), with Acount nondecreasing in[0,M], giving −3E−2M<ΔN<3E+M, including coincident dark/visible multiplicities.','general finite Hermitian auxiliary boundary model theorem','proposals/independent_campaigns/factored_inner_round2.md §8','theorems/inner_round2.jsonl');
INSERT INTO "claims" VALUES('THM-RI306','theorems/theorems.jsonl',255,'conditional model obstruction, not RH','proposals/independent_campaigns/factored_inner_round2.md §§4,8','{"theorem_id": "THM-RI306", "paper_id": null, "locator": "proposals/independent_campaigns/factored_inner_round2.md §§4,8", "kind": "conditional zeta-count approximation cost", "statement": "If one of these models matches Nζ atK,2K,4K with errors≤ε_K K, then3E+M≥Klog2/π−6ε_K K−O(logK). Therefore ε_K→0 forces liminf(3E_K+M_K)/K≥log2/π. Uses positive Riemann–vonMangoldt curvature and the one-sided upper bound3E+M; no assertion about zero locations.", "verification_status": "adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay", "source_theorems": ["THM-RI305"], "status": "conditional model obstruction, not RH", "id": "THM-RI306", "provenance_file": "theorems/inner_round2.jsonl", "verification": "scoped_Level3; independent proposer/skeptic/director ordinary reconstruction; exact scope in adjudication", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'If one of these models matches Nζ atK,2K,4K with errors≤ε_K K, then3E+M≥Klog2/π−6ε_K K−O(logK). Therefore ε_K→0 forces liminf(3E_K+M_K)/K≥log2/π. Uses positive Riemann–vonMangoldt curvature and the one-sided upper bound3E+M; no assertion about zero locations.','conditional zeta-count approximation cost','proposals/independent_campaigns/factored_inner_round2.md §§4,8','theorems/inner_round2.jsonl');
INSERT INTO "claims" VALUES('THM-RI307','theorems/theorems.jsonl',256,'independently checked negative control','proposals/independent_campaigns/factored_inner_round2.md §6 and end§8','{"theorem_id": "THM-RI307", "paper_id": null, "locator": "proposals/independent_campaigns/factored_inner_round2.md §6 and end§8", "kind": "nondense common-restriction failure control", "statement": "The coupled scalar domain f(ℓ)−f(0)=γz and periodic-derivative⊕[d] reference domain f(ℓ)−f(0)=0 intersect only with z=0 whenγ≠0. Their intersection is not dense in L2⊕C. More generally coupled/reference intersections impose Gq=0. The earlier dense-common-S finite-defect theorem cannot remove the auxiliary-state cost.", "verification_status": "adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay", "source_theorems": ["THM-D205", "THM-RI305"], "status": "independently checked negative control", "id": "THM-RI307", "provenance_file": "theorems/inner_round2.jsonl", "verification": "scoped_Level3; independent proposer/skeptic/director ordinary reconstruction; exact scope in adjudication", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'The coupled scalar domain f(ℓ)−f(0)=γz and periodic-derivative⊕[d] reference domain f(ℓ)−f(0)=0 intersect only with z=0 whenγ≠0. Their intersection is not dense in L2⊕C. More generally coupled/reference intersections impose Gq=0. The earlier dense-common-S finite-defect theorem cannot remove the auxiliary-state cost.','nondense common-restriction failure control','proposals/independent_campaigns/factored_inner_round2.md §6 and end§8','theorems/inner_round2.jsonl');
INSERT INTO "claims" VALUES('THM-RI308','theorems/theorems.jsonl',257,'established auxiliary counterexample','experiments/code/factored_inner_round2.py; campaign §§1–2','{"theorem_id": "THM-RI308", "paper_id": null, "locator": "experiments/code/factored_inner_round2.py; campaign §§1–2", "kind": "counterexample to real-axis-unitary-only phase inference", "statement": "The inverse scalar Blaschke factor is unitary on R but has negative phase derivative. With width1/2 and edge length1, −iW*W′ at its center is−3. Thus unitarity alone does not imply the positive crossing hypothesis. With constant phase chosen so W(center)=1 it produces a negative crossing.", "verification_status": "adjudicated_scoped; external inputs and conditional hypotheses retained; not a whole-paper audit or full formal replay", "status": "established auxiliary counterexample", "id": "THM-RI308", "provenance_file": "theorems/inner_round2.jsonl", "verification": "scoped_Level3; independent proposer/skeptic/director ordinary reconstruction; exact scope in adjudication", "status_update_evidence": "audits/adversarial_reviews/director_round3_adjudication.md"}',NULL,'The inverse scalar Blaschke factor is unitary on R but has negative phase derivative. With width1/2 and edge length1, −iW*W′ at its center is−3. Thus unitarity alone does not imply the positive crossing hypothesis. With constant phase chosen so W(center)=1 it produces a negative crossing.','counterexample to real-axis-unitary-only phase inference','experiments/code/factored_inner_round2.py; campaign §§1–2','theorems/inner_round2.jsonl');
INSERT INTO "claims" VALUES('OBS-PREFIX-BESSEL','theorems/theorems.jsonl',258,'adjudicated_scoped_unconditional_finite_theorem','audits/adversarial_reviews/director_joint_prefix_round6.md; three independent derivations; proponent explicit bounds1–2','{"id": "OBS-PREFIX-BESSEL", "paper_id": null, "claim_kind": "proved_uniform_finite_cost_transition", "statement": "For integerm approachinginfinity andr=m²b/(1-b) inanyfixed[0,R], c_m(b)/m²=Phi(r)+O_R(1/m), Phi(r)=I0(2sqrt r)^2-I1(2sqrt r)^2. Withr*=m(m-1)b/(1-b), (c_m-m²)/[m(m-1)]=Phi(r*)-1+O_R(m^-2). Valuesatb0 usecontinuous limits.", "hypotheses": "Finite Gram matrix cost OBS-PREFIX-CLOSED; no RH or arithmetic-prefix theorem. Uniform on bounded scaled parameter only.", "locator": "audits/adversarial_reviews/director_joint_prefix_round6.md; three independent derivations; proponent explicit bounds1–2", "status": "adjudicated_scoped_unconditional_finite_theorem", "novelty_claim": false, "provenance_file": "theorems/joint_prefix_director_round6.jsonl"}',NULL,'For integerm approachinginfinity andr=m²b/(1-b) inanyfixed[0,R], c_m(b)/m²=Phi(r)+O_R(1/m), Phi(r)=I0(2sqrt r)^2-I1(2sqrt r)^2. Withr*=m(m-1)b/(1-b), (c_m-m²)/[m(m-1)]=Phi(r*)-1+O_R(m^-2). Valuesatb0 usecontinuous limits.','proved_uniform_finite_cost_transition','audits/adversarial_reviews/director_joint_prefix_round6.md; three independent derivations; proponent explicit bounds1–2','theorems/joint_prefix_director_round6.jsonl');
INSERT INTO "claims" VALUES('OBS-PREFIX-JOINT-LARGE','theorems/theorems.jsonl',259,'adjudicated_scoped_unconditional_finite_theorem','audits/adversarial_reviews/director_joint_prefix_round6.md uniformGaussian derivativeandendpointproof','{"id": "OBS-PREFIX-JOINT-LARGE", "paper_id": null, "claim_kind": "proved_uniform_joint_finite_cost_asymptotic", "statement": "Along every joint limitm approachinginfinity,0<b<1,andm sqrt b approachinginfinity, c_m(b)~(1-b)^2[(1+sqrt b)/(1-sqrt b)]^(2m-1)/(8pi b), with relative errorO(1/[m min(2atanh sqrt b,1)]) above an absolute threshold. This includesbapproaching0 or1.", "locator": "audits/adversarial_reviews/director_joint_prefix_round6.md uniformGaussian derivativeandendpointproof", "status": "adjudicated_scoped_unconditional_finite_theorem", "novelty_claim": false, "provenance_file": "theorems/joint_prefix_director_round6.jsonl"}',NULL,'Along every joint limitm approachinginfinity,0<b<1,andm sqrt b approachinginfinity, c_m(b)~(1-b)^2[(1+sqrt b)/(1-sqrt b)]^(2m-1)/(8pi b), with relative errorO(1/[m min(2atanh sqrt b,1)]) above an absolute threshold. This includesbapproaching0 or1.','proved_uniform_joint_finite_cost_asymptotic','audits/adversarial_reviews/director_joint_prefix_round6.md uniformGaussian derivativeandendpointproof','theorems/joint_prefix_director_round6.jsonl');
INSERT INTO "claims" VALUES('OBS-PREFIX-MATCHING-BOUNDARY','theorems/theorems.jsonl',260,'adjudicated_scoped_unconditional_finite_theorem','audits/adversarial_reviews/director_joint_prefix_round6.md equationB; independent skeptic and witness comparison','{"id": "OBS-PREFIX-MATCHING-BOUNDARY", "paper_id": null, "claim_kind": "proved_relative_transition_and_nonuniformity_witness", "statement": "Letm approachinfinity,r=m²b/(1-b),Phi(r)=I0(2sqrt r)^2-I1(2sqrt r)^2. The ratio[c_m(b)/m²]/Phi(r) approaches1 wheneverr=o(m^(4/3)); approachesexp(-2alpha^(3/2)/3) whenr/m^(4/3) approachesalpha in(0,infinity); andapproaches0 whenr/m^(4/3) approachesinfinity.", "hypotheses": "Finite matrix cost only. No moving-prefix arithmetic conclusion, no RH counterexample, no publication priority claim.", "locator": "audits/adversarial_reviews/director_joint_prefix_round6.md equationB; independent skeptic and witness comparison", "status": "adjudicated_scoped_unconditional_finite_theorem", "novelty_claim": false, "provenance_file": "theorems/joint_prefix_director_round6.jsonl"}',NULL,'Letm approachinfinity,r=m²b/(1-b),Phi(r)=I0(2sqrt r)^2-I1(2sqrt r)^2. The ratio[c_m(b)/m²]/Phi(r) approaches1 wheneverr=o(m^(4/3)); approachesexp(-2alpha^(3/2)/3) whenr/m^(4/3) approachesalpha in(0,infinity); andapproaches0 whenr/m^(4/3) approachesinfinity.','proved_relative_transition_and_nonuniformity_witness','audits/adversarial_reviews/director_joint_prefix_round6.md equationB; independent skeptic and witness comparison','theorems/joint_prefix_director_round6.jsonl');
INSERT INTO "claims" VALUES('THM-LATEST62-CA501','theorems/theorems.jsonl',261,'adjudicated_scoped; retain conditional/model/finite scope in statement','proposals/independent_campaigns/lagarias_shared_ca_latest62_round5.md, local thresholds and interpolation','{"id": "THM-LATEST62-CA501", "paper_id": null, "locator": "proposals/independent_campaigns/lagarias_shared_ca_latest62_round5.md, local thresholds and interpolation", "statement": "The only global maximizers of σ(n)/n^(1+ε*) at ε*=log(14/13)/log 13 are 55440 and 720720, which are consecutive colossally abundant integers. The prior global concavity of the Lagarias envelope and two strict endpoint certificates imply σ(n)<H_n+exp(H_n)log H_n for every integer 55440≤n≤720720.", "hypotheses": "Global concavity result in lagarias_global_concavity_round2.md and exact integer replay of lagarias_latest62_ca.py; no RH assumption.", "status": "adjudicated_scoped; retain conditional/model/finite scope in statement", "verification": "Independent proposer, skeptic and director reconstructions; explicit source inputs and limitations retained", "novelty_claim": false, "provenance_file": "theorems/lagarias_latest62_ca_round5.jsonl", "verification_status": "No issue found in the inspected complete scoped argument; no whole-paper audit or publication novelty", "status_update_evidence": "audits/adversarial_reviews/director_round5_adjudication.md"}',NULL,'The only global maximizers of σ(n)/n^(1+ε*) at ε*=log(14/13)/log 13 are 55440 and 720720, which are consecutive colossally abundant integers. The prior global concavity of the Lagarias envelope and two strict endpoint certificates imply σ(n)<H_n+exp(H_n)log H_n for every integer 55440≤n≤720720.',NULL,'proposals/independent_campaigns/lagarias_shared_ca_latest62_round5.md, local thresholds and interpolation','theorems/lagarias_latest62_ca_round5.jsonl');
INSERT INTO "claims" VALUES('THM-DF62-001','theorems/theorems.jsonl',262,'established_primary_source_result','Theorem 51, arXiv v1 p. 29 and proof pp. 29–31','{"id": "THM-DF62-001", "paper_id": "PAPER-DF62-001", "locator": "Theorem 51, arXiv v1 p. 29 and proof pp. 29–31", "statement": "For fixed 17/22≤σ≤4/5, the zeta zero-density coefficient A(σ) obeys A(σ)≤max(2/(9σ−6),9/[8(2σ−1)]), switching at 38/49.", "hypotheses": "Unconditional; source epsilon-loss convention.", "status": "established_primary_source_result", "verification": "Targeted statement and proof-architecture reading; dated Table 2 compares literature envelopes at the time.", "provenance_file": "theorems/latest62_density_frontier.jsonl"}','PAPER-DF62-001','For fixed 17/22≤σ≤4/5, the zeta zero-density coefficient A(σ) obeys A(σ)≤max(2/(9σ−6),9/[8(2σ−1)]), switching at 38/49.',NULL,'Theorem 51, arXiv v1 p. 29 and proof pp. 29–31','theorems/latest62_density_frontier.jsonl');
INSERT INTO "claims" VALUES('THM-DF62-002','theorems/theorems.jsonl',263,'primary_source_statement','Theorem 1.1 p. 2; proof §2 pp. 8–12','{"id": "THM-DF62-002", "paper_id": "PAPER-DF62-002", "locator": "Theorem 1.1 p. 2; proof §2 pp. 8–12", "statement": "For globally tempered fixed cuspidal unitary π, or zeta, a uniform short-interval 2ℓ moment exponent θ on intervals of length X^a implies the short-strip density exponent (1−σ)max(15a/(3+5σ),4θ/[ℓ(2σ−1)+4(1−σ)])+ε for 3/5≤σ<1.", "hypotheses": "0<a≤1, ℓ≥1, θ≥a; fixed L-function data and uniform moment hypothesis in X.", "status": "primary_source_statement", "verification": "Targeted substantive full density proof reading. Type I uses Guth–Maynard, Type II Maynard–Pratt.", "provenance_file": "theorems/latest62_density_frontier.jsonl"}','PAPER-DF62-002','For globally tempered fixed cuspidal unitary π, or zeta, a uniform short-interval 2ℓ moment exponent θ on intervals of length X^a implies the short-strip density exponent (1−σ)max(15a/(3+5σ),4θ/[ℓ(2σ−1)+4(1−σ)])+ε for 3/5≤σ<1.',NULL,'Theorem 1.1 p. 2; proof §2 pp. 8–12','theorems/latest62_density_frontier.jsonl');
INSERT INTO "claims" VALUES('THM-DF62-003','theorems/theorems.jsonl',264,'primary_source_statement','Theorem 1.2 p. 2; proof §2 pp. 11–12','{"id": "THM-DF62-003", "paper_id": "PAPER-DF62-002", "locator": "Theorem 1.2 p. 2; proof §2 pp. 11–12", "statement": "For 2/3≤a≤1, 7/10≤σ≤4/5, the number with multiplicity of zeta zeros with Re ρ>σ and T≤Im ρ≤T+T^a is O(T^(15a(1−σ)/(3+5σ)+ε)). At σ=3/4 the exponent is 5a/9.", "hypotheses": "Unconditional; T≥3; implied constants may depend on a,ε.", "status": "primary_source_statement", "verification": "Fixed source v2; full §2 read. Heath-Brown–Iwaniec fourth moment and Type I/II detector transfer checked in source.", "provenance_file": "theorems/latest62_density_frontier.jsonl"}','PAPER-DF62-002','For 2/3≤a≤1, 7/10≤σ≤4/5, the number with multiplicity of zeta zeros with Re ρ>σ and T≤Im ρ≤T+T^a is O(T^(15a(1−σ)/(3+5σ)+ε)). At σ=3/4 the exponent is 5a/9.',NULL,'Theorem 1.2 p. 2; proof §2 pp. 11–12','theorems/latest62_density_frontier.jsonl');
INSERT INTO "claims" VALUES('THM-DF62-004','theorems/theorems.jsonl',265,'external_kernel_check_reported_primary_formal_declaration_inspected','Palomar pinned Solution.lean, GuthMaynardStatement.global_uniform','{"id": "THM-DF62-004", "paper_id": "PAPER-DF62-003", "locator": "Palomar pinned Solution.lean, GuthMaynardStatement.global_uniform", "statement": "Uniformly all 1/2≤σ≤1 and T≥2, the multiplicity-weighted number of actual zeta zeros with 0<Reρ<1, Reρ≥σ and |Imρ|≤T is ≤Cε T^((39/17)(1−σ)+ε).", "hypotheses": "For each ε>0 the constant is chosen before σ,T. No RH input.", "status": "external_kernel_check_reported_primary_formal_declaration_inspected", "verification": "Palomar v1 reports Lean, nanoda and con-ron replay. Pinned statement/proof wrappers and selected dependencies inspected; no local replay.", "provenance_file": "theorems/latest62_density_frontier.jsonl"}','PAPER-DF62-003','Uniformly all 1/2≤σ≤1 and T≥2, the multiplicity-weighted number of actual zeta zeros with 0<Reρ<1, Reρ≥σ and |Imρ|≤T is ≤Cε T^((39/17)(1−σ)+ε).',NULL,'Palomar pinned Solution.lean, GuthMaynardStatement.global_uniform','theorems/latest62_density_frontier.jsonl');
INSERT INTO "claims" VALUES('THM-DF62-005','theorems/theorems.jsonl',266,'external_kernel_check_reported_primary_formal_declaration_inspected','Palomar pinned Solution.lean, GuthMaynardStatement.middle_large_values','{"id": "THM-DF62-005", "paper_id": "PAPER-DF62-003", "locator": "Palomar pinned Solution.lean, GuthMaynardStatement.middle_large_values", "statement": "For N≥2, N^(6/5)≤T≤N^(5/3), and V>0, the number of 1-separated observations in any translate of [0,T] at which a dyadic Dirichlet polynomial with coefficients |a_n|≤1 reaches magnitude ≥V is Oε(N^ε(N²/V²+N^(18/7)T^(6/7)/V⁴)).", "hypotheses": "All parameters and coefficients under one constant for each ε>0.", "status": "external_kernel_check_reported_primary_formal_declaration_inspected", "verification": "Pinned statement/proof wrapper and imported middle-range estimate inspected; no local replay.", "provenance_file": "theorems/latest62_density_frontier.jsonl"}','PAPER-DF62-003','For N≥2, N^(6/5)≤T≤N^(5/3), and V>0, the number of 1-separated observations in any translate of [0,T] at which a dyadic Dirichlet polynomial with coefficients |a_n|≤1 reaches magnitude ≥V is Oε(N^ε(N²/V²+N^(18/7)T^(6/7)/V⁴)).',NULL,'Palomar pinned Solution.lean, GuthMaynardStatement.middle_large_values','theorems/latest62_density_frontier.jsonl');
INSERT INTO "claims" VALUES('THM-DF62-006','theorems/theorems.jsonl',267,'primary_source_statement_scoped_reading','Theorem 1.1 pp. 2–3; eqs. (33),(35) pp. 22,24; Theorem 8.14 pp. 46–47; Theorem 9.3 pp. 51–52; Hexagon 2611.00421v1','{"id": "THM-DF62-006", "paper_id": "PAPER-DF62-004", "locator": "Theorem 1.1 pp. 2–3; eqs. (33),(35) pp. 22,24; Theorem 8.14 pp. 46–47; Theorem 9.3 pp. 51–52; Hexagon 2611.00421v1", "statement": "Source states a strict zero-free half-plane Re s>B*=0.8733458561067185768… for every continuous unitary Hecke character over every number field, with the simple norm-character pole at 1+it permitted. Zeta is the principal character over Q.", "hypotheses": "Unconditional as stated in source. Proof depends on earlier finite-order and unitary theta/character-moment analytic results and a positive-comparison induction.", "status": "primary_source_statement_scoped_reading", "verification": "The statement, exact algebraic root, finite-order proof and unitary transfer were read. Full analytic chain not independently audited.", "provenance_file": "theorems/latest62_density_frontier.jsonl"}','PAPER-DF62-004','Source states a strict zero-free half-plane Re s>B*=0.8733458561067185768… for every continuous unitary Hecke character over every number field, with the simple norm-character pole at 1+it permitted. Zeta is the principal character over Q.',NULL,'Theorem 1.1 pp. 2–3; eqs. (33),(35) pp. 22,24; Theorem 8.14 pp. 46–47; Theorem 9.3 pp. 51–52; Hexagon 2611.00421v1','theorems/latest62_density_frontier.jsonl');
INSERT INTO "claims" VALUES('LATEST62-OUIMET-V1-GUMBEL','theorems/theorems.jsonl',268,'primary_source_claim_targeted_dependency_audit','arXiv:2611.01905v1 (2.1), (2.2), (2.6), and Theorem 2.1','{"id": "LATEST62-OUIMET-V1-GUMBEL", "status": "primary_source_claim_targeted_dependency_audit", "source": "PAPER-STAT62-016", "locator": "arXiv:2611.01905v1 (2.1), (2.2), (2.6), and Theorem 2.1", "statement": "Fix θ>0, φ>7/2, Φ>φ+1, Cσ>0; let t=log log T and let X and η=σ−1/2 be deterministic and satisfy T^{1/t^Φ}≤X≤T^{1/t^φ}, 0<η≤Cσ t^Φ/log T, η log X/t→∞. For one τ uniform on [T,2T] let M_T=max_{|h|≤(log T)^θ}log|ζ(σ+i(τ+h))|. The author claims P(M_T−u_T≤x)→exp(−κ_θ exp(−2√(1+θ)x)) for every real x, where u_T is the specified one-point Haar-prime-phase quantile and 0<κ_θ<∞ is a microscopic Gaussian-profile lattice limit. The same maximum law is claimed separately in the Euler and Haar fields. No RH assumed, no global range maximum, no critical-line inference, no claim about zero statistics or whole-field limits.", "audit": "audits/latest62_ouimet_gumbel_dependency.md", "paper_id": null, "provenance_file": "theorems/latest62_ouimet_scoped_claims.jsonl"}',NULL,'Fix θ>0, φ>7/2, Φ>φ+1, Cσ>0; let t=log log T and let X and η=σ−1/2 be deterministic and satisfy T^{1/t^Φ}≤X≤T^{1/t^φ}, 0<η≤Cσ t^Φ/log T, η log X/t→∞. For one τ uniform on [T,2T] let M_T=max_{|h|≤(log T)^θ}log|ζ(σ+i(τ+h))|. The author claims P(M_T−u_T≤x)→exp(−κ_θ exp(−2√(1+θ)x)) for every real x, where u_T is the specified one-point Haar-prime-phase quantile and 0<κ_θ<∞ is a microscopic Gaussian-profile lattice limit. The same maximum law is claimed separately in the Euler and Haar fields. No RH assumed, no global range maximum, no critical-line inference, no claim about zero statistics or whole-field limits.',NULL,'arXiv:2611.01905v1 (2.1), (2.2), (2.6), and Theorem 2.1','theorems/latest62_ouimet_scoped_claims.jsonl');
INSERT INTO "claims" VALUES('LATEST62-OUIMET-ZETA-EULER-BRIDGE','theorems/theorems.jsonl',269,'scoped_dependency_reconstructed','arXiv:2610.22821v1 Proposition 3.3 (3.8), Lemmas 3.5–3.7; arXiv:2611.01905v1 (6.26)','{"id": "LATEST62-OUIMET-ZETA-EULER-BRIDGE", "status": "scoped_dependency_reconstructed", "locator": "arXiv:2610.22821v1 Proposition 3.3 (3.8), Lemmas 3.5–3.7; arXiv:2611.01905v1 (6.26)", "statement": "Under the preceding displacement and cutoff assumptions, sup_{|h|≤(log T)^θ}|log|ζ(σ+i(τ+h))|−Re Σ_{p^j≤X}p^{-j(σ+i(τ+h))}/j| is o_P(1). The maximum transfer is a consequence of this uniform approximation and a separate limit theorem for the arithmetic Euler field. The claim uses ordinary zero-density control on a random rectangle, no RH and no fixed global zero-free half-plane.", "audit": "audits/latest62_ouimet_gumbel_dependency.md", "paper_id": null, "provenance_file": "theorems/latest62_ouimet_scoped_claims.jsonl"}',NULL,'Under the preceding displacement and cutoff assumptions, sup_{|h|≤(log T)^θ}|log|ζ(σ+i(τ+h))|−Re Σ_{p^j≤X}p^{-j(σ+i(τ+h))}/j| is o_P(1). The maximum transfer is a consequence of this uniform approximation and a separate limit theorem for the arithmetic Euler field. The claim uses ordinary zero-density control on a random rectangle, no RH and no fixed global zero-free half-plane.',NULL,'arXiv:2610.22821v1 Proposition 3.3 (3.8), Lemmas 3.5–3.7; arXiv:2611.01905v1 (6.26)','theorems/latest62_ouimet_scoped_claims.jsonl');
INSERT INTO "claims" VALUES('THM-LATEST62-001','theorems/theorems.jsonl',270,'established_primary_source_result','Theorem 1.1 p. 1; proof p. 19','{"id": "THM-LATEST62-001", "paper_id": "PAPER-LATEST62-001", "locator": "Theorem 1.1 p. 1; proof p. 19", "statement": "For T≥1 and ε>0, the critical-line sixth moment on [0,T] is ≪ε T^(37/30+ε).", "hypotheses": "Unconditional.", "status": "established_primary_source_result", "verification": "Whole-work Level 1, with endpoint arithmetic checked independently.", "provenance_file": "theorems/latest62_round5.jsonl"}','PAPER-LATEST62-001','For T≥1 and ε>0, the critical-line sixth moment on [0,T] is ≪ε T^(37/30+ε).',NULL,'Theorem 1.1 p. 1; proof p. 19','theorems/latest62_round5.jsonl');
INSERT INTO "claims" VALUES('THM-LATEST62-002','theorems/theorems.jsonl',271,'established_primary_source_result','Theorem 1.3 p. 2; Theorem 9.1 pp. 15–18','{"id": "THM-LATEST62-002", "paper_id": "PAPER-LATEST62-001", "locator": "Theorem 1.3 p. 2; Theorem 9.1 pp. 15–18", "statement": "For T^(7/60)≤V≤T^(5/38), the maximal cardinality of a 1-spaced zeta level set at threshold V on [T,2T] is ≪ε T^(24/17+ε)V^(-128/17).", "hypotheses": "T≥1 and ε>0; unconditional.", "status": "established_primary_source_result", "verification": "Whole-work Level 1.", "provenance_file": "theorems/latest62_round5.jsonl"}','PAPER-LATEST62-001','For T^(7/60)≤V≤T^(5/38), the maximal cardinality of a 1-spaced zeta level set at threshold V on [T,2T] is ≪ε T^(24/17+ε)V^(-128/17).',NULL,'Theorem 1.3 p. 2; Theorem 9.1 pp. 15–18','theorems/latest62_round5.jsonl');
INSERT INTO "claims" VALUES('THM-LATEST62-003','theorems/theorems.jsonl',272,'established_primary_source_result','Theorem 10.1 p. 18','{"id": "THM-LATEST62-003", "paper_id": "PAPER-LATEST62-001", "locator": "Theorem 10.1 p. 18", "statement": "For T≥1 and ε>0, the critical-line twelfth moment on [0,T] is ≪ε T^(2−520/445121+ε).", "hypotheses": "Unconditional. Proof uses Theorem 9.1 with auxiliary k=6, Trudgian–Yang 2025 exponent pair (64/135,122/243), and Bourgain subconvexity.", "status": "established_primary_source_result", "verification": "Whole-work Level 1.", "provenance_file": "theorems/latest62_round5.jsonl"}','PAPER-LATEST62-001','For T≥1 and ε>0, the critical-line twelfth moment on [0,T] is ≪ε T^(2−520/445121+ε).',NULL,'Theorem 10.1 p. 18','theorems/latest62_round5.jsonl');
INSERT INTO "claims" VALUES('THM-LATEST62-004','theorems/theorems.jsonl',273,'established_primary_source_result','Theorem 1.1 p. 2','{"id": "THM-LATEST62-004", "paper_id": "PAPER-LATEST62-002", "locator": "Theorem 1.1 p. 2", "statement": "For fixed k>0 and V(T)~k log log T, the normalized measure of t in [T,2T] with log|ζ(1/2+it)|>V is at most exp(exp(ck)) exp(−V²/log log T)/sqrt(log log T) for sufficiently large T and an absolute c>0.", "hypotheses": "Riemann hypothesis.", "status": "established_primary_source_result", "verification": "Whole-work Level 1.", "provenance_file": "theorems/latest62_round5.jsonl"}','PAPER-LATEST62-002','For fixed k>0 and V(T)~k log log T, the normalized measure of t in [T,2T] with log|ζ(1/2+it)|>V is at most exp(exp(ck)) exp(−V²/log log T)/sqrt(log log T) for sufficiently large T and an absolute c>0.',NULL,'Theorem 1.1 p. 2','theorems/latest62_round5.jsonl');
INSERT INTO "claims" VALUES('THM-LATEST62-005','theorems/theorems.jsonl',274,'established_primary_source_result','Corollary 1.2 p. 2','{"id": "THM-LATEST62-005", "paper_id": "PAPER-LATEST62-002", "locator": "Corollary 1.2 p. 2", "statement": "For k≥2 the normalized critical-line 2k-th moment on [T,2T] is ≪ exp(exp(ck))(log T)^(k²) for sufficiently large T with c as in Theorem 1.1.", "hypotheses": "Riemann hypothesis.", "status": "established_primary_source_result", "verification": "Whole-work Level 1.", "provenance_file": "theorems/latest62_round5.jsonl"}','PAPER-LATEST62-002','For k≥2 the normalized critical-line 2k-th moment on [T,2T] is ≪ exp(exp(ck))(log T)^(k²) for sufficiently large T with c as in Theorem 1.1.',NULL,'Corollary 1.2 p. 2','theorems/latest62_round5.jsonl');
INSERT INTO "claims" VALUES('THM-LATEST62-006','theorems/theorems.jsonl',275,'established_primary_source_result','Theorem 1.4 p. 4; §8 pp. 40–43','{"id": "THM-LATEST62-006", "paper_id": "PAPER-LATEST62-003", "locator": "Theorem 1.4 p. 4; §8 pp. 40–43", "statement": "For every positive integer k, the partial sums of the Dirichlet coefficients μ_k of ζ(s)^(-k) satisfy |Σ_{n≤x} μ_k(n)| ≪ sqrt(x) exp(C_k (log x/log log x)^(k/(k+1))).", "hypotheses": "Riemann hypothesis; C_k>0. At k=1 this bounds the ordinary Mertens function.", "status": "established_primary_source_result", "verification": "Complete primary Level 1. Scoped reconstruction of the k=1 vertical-contour estimate and central scale in audits/bui_florea_heycock_latest62_fullsource_round5.md. Cited pointwise estimates and the complete theorem proof not fully audited.", "provenance_file": "theorems/latest62_round5.jsonl"}','PAPER-LATEST62-003','For every positive integer k, the partial sums of the Dirichlet coefficients μ_k of ζ(s)^(-k) satisfy |Σ_{n≤x} μ_k(n)| ≪ sqrt(x) exp(C_k (log x/log log x)^(k/(k+1))).',NULL,'Theorem 1.4 p. 4; §8 pp. 40–43','theorems/latest62_round5.jsonl');
INSERT INTO "claims" VALUES('CAND-LATEST62-YE-SHORT-FOURTH','theorems/theorems.jsonl',276,'adjudicated_scoped_source_dependent_corollary','audits/latest62_ye_fullread.md, A direct shorter-height envelope','{"id": "CAND-LATEST62-YE-SHORT-FOURTH", "status": "adjudicated_scoped_source_dependent_corollary", "statement": "For every fixed \\(0<a\\le1\\) and every \\(\\varepsilon>0\\), uniformly for real \\(T\\ge3\\) and \\(3/5\\le\\sigma<1\\), the multiplicity count of nontrivial zeta zeros satisfying \\(\\Re\\rho>\\sigma\\) and \\(T\\le\\Im\\rho\\le T+T^a\\) is \\(O_{a,\\varepsilon}(T^{(1-\\sigma)\\max\\{15a/(3+5\\sigma),\\,2\\max(a,2/3)\\}+\\varepsilon})\\). At \\(a=3/5,\\sigma=3/4\\) this is \\(O_\\varepsilon(T^{1/3+\\varepsilon})\\); enlarging directly to the \\(a=2/3\\) estimate of Ye Theorem 1.2 gives \\(O_\\varepsilon(T^{10/27+\\varepsilon})\\).", "dependencies": ["Ye arXiv:2610.15989v2 Theorem 1.1 and (2.17)", "Uniformity in the real start of the Heath-Brown–Iwaniec short-interval fourth moment as quoted by Ye"], "derivation": "For \\(0<a<2/3\\) and each real \\(U\\ge3\\), positivity gives \\(\\int_U^{U+U^a}|\\zeta(1/2+it)|^4dt\\le \\int_U^{U+U^{2/3}}|\\zeta(1/2+it)|^4dt\\ll_\\eta U^{2/3+\\eta}\\) for every \\(\\eta>0\\). This extension holds for every start \\(U\\), including the \\(O(1)\\) starts used to cover the enlarged Type II integral. For \\(a\\ge2/3\\), use (2.17) with the same \\(a\\). Apply Theorem 1.1 with \\(\\ell=2\\) and \\(\\theta=\\max(a,2/3)\\), so the denominator is exactly \\(2\\). No zero-free half-plane input.", "locator": "audits/latest62_ye_fullread.md, A direct shorter-height envelope", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/latest62_ye_candidates.jsonl", "verification_status": "Independent derivation, skeptic and director; exact source hypotheses retained; not whole-source proof validation.", "director_evidence": "audits/adversarial_reviews/director_ye_corollaries_round8.md", "status_update_evidence": "audits/adversarial_reviews/director_ye_corollaries_round8.md"}',NULL,'For every fixed \(0<a\le1\) and every \(\varepsilon>0\), uniformly for real \(T\ge3\) and \(3/5\le\sigma<1\), the multiplicity count of nontrivial zeta zeros satisfying \(\Re\rho>\sigma\) and \(T\le\Im\rho\le T+T^a\) is \(O_{a,\varepsilon}(T^{(1-\sigma)\max\{15a/(3+5\sigma),\,2\max(a,2/3)\}+\varepsilon})\). At \(a=3/5,\sigma=3/4\) this is \(O_\varepsilon(T^{1/3+\varepsilon})\); enlarging directly to the \(a=2/3\) estimate of Ye Theorem 1.2 gives \(O_\varepsilon(T^{10/27+\varepsilon})\).',NULL,'audits/latest62_ye_fullread.md, A direct shorter-height envelope','theorems/latest62_ye_candidates.jsonl');
INSERT INTO "claims" VALUES('CAND-LATEST62-YE-OSCILLATORY-27040','theorems/theorems.jsonl',277,'adjudicated_scoped_source_dependent_corollary_with_external_unverified_7_8_cutoff','audits/latest62_ye_fullread.md, A direct shorter-height envelope','{"id": "CAND-LATEST62-YE-OSCILLATORY-27040", "status": "adjudicated_scoped_source_dependent_corollary_with_external_unverified_7_8_cutoff", "statement": "Assume as a separate external input that every nontrivial zero of \\(\\zeta(s)\\) has real part at most \\(7/8\\). Fix a real \\(\\alpha\\ne0\\) and a smooth function \\(\\phi\\in C_c^\\infty((-1,1))\\). For every \\(\\varepsilon>0\\), uniformly for all sufficiently large real \\(K\\), the smoothed oscillatory prime-power sum \\(\\sum_{n\\ge1}\\Lambda(n)e^{2\\pi i\\alpha n^{3/5}}\\phi((n-K)/K^{7/10})\\) is \\(O_{\\alpha,\\phi,\\varepsilon}(K^{27/40+\\varepsilon})\\). This is \\(m=1\\), \\(\\beta=3/5\\), \\(\\delta=7/10\\) in Ye (1.7)–(1.9). The estimate is pointwise in the window center \\(K\\), with no averaging over \\(K,\\alpha\\), or \\(\\phi\\), and with the nonzero phase fixed. Its exponent improves \\(44/65+\\varepsilon\\) from direct substitution in Ye Theorem 1.3 at those same parameters and cutoff. It makes no claim for the unphased prime count or the global prime number theorem.", "dependencies": ["CAND-LATEST62-YE-SHORT-FOURTH", "Ye arXiv:2610.15989v2 Proposition 3.3, (3.14), and (4.2)", "External fixed zero-free cutoff \\(\\Re\rho\\le7/8\\) as in Ye §4"], "derivation": "\\(b=3/5\\), \\(v=w_0=q=a_0=3/10\\). Proposition 3.3 gives a zero window \\(J\\) at absolute height \\(\\asymp K^{3/5}\\) of length \\(O(K^{3/10+\\eta})\\) and the factor \\(K^{-3/10}\\), with arbitrary power error. The sign of the window can be reflected for zeta. For fixed sufficiently small \\(0<\\eta<1/100\\), cover \\(J\\) by \\(O(1)\\) windows at starts \\(T\\asymp K^{3/5}\\) with \\(a=(3/10+2\\eta)/(3/5)\\in(1/2,2/3)\\). Here \\(15a/(3+5\\sigma)\\le (5/2)a<4/3\\) after choosing \\(\\eta\\) sufficiently small. The new local count is \\(O(K^{(4/5)(1-\\sigma)+\\varepsilon})\\) uniformly for \\(3/5\\le\\sigma<1\\). Zeros with \\(1/2\\le\\Re\\rho\\le3/5\\) contribute \\(O(K^{9/10+\\eta+\\varepsilon})\\) to the weighted sum \\(\\sum_{\\rho:\\gamma\\in J,\\Re\\rho\\ge1/2}K^{\\Re\\rho}\\), by subdividing into unit height intervals. For \\(\\Re\\rho>3/5\\), partial summation uses the local density count, with its lower-boundary term and inclusive \\(7/8\\) endpoint. The affine exponent \\(\\sigma+(4/5)(1-\\sigma)\\) has maximum \\(39/40\\) at \\(7/8\\). Multiplying by \\(K^{-3/10}\\) yields \\(27/40\\). The formula in Ye''s preprint uses \\(\\nu=\\max(q,2b/3)=2/5\\), so \\(Q(2/5)-3/10=7/10+18/65-3/10=44/65\\); the difference is \\(1/520\\).", "locator": "audits/latest62_ye_fullread.md, A direct shorter-height envelope", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/latest62_ye_candidates.jsonl", "verification_status": "Independent derivation, skeptic and director; exact source hypotheses retained; not whole-source proof validation.", "director_evidence": "audits/adversarial_reviews/director_ye_corollaries_round8.md", "status_update_evidence": "audits/adversarial_reviews/director_ye_corollaries_round8.md"}',NULL,'Assume as a separate external input that every nontrivial zero of \(\zeta(s)\) has real part at most \(7/8\). Fix a real \(\alpha\ne0\) and a smooth function \(\phi\in C_c^\infty((-1,1))\). For every \(\varepsilon>0\), uniformly for all sufficiently large real \(K\), the smoothed oscillatory prime-power sum \(\sum_{n\ge1}\Lambda(n)e^{2\pi i\alpha n^{3/5}}\phi((n-K)/K^{7/10})\) is \(O_{\alpha,\phi,\varepsilon}(K^{27/40+\varepsilon})\). This is \(m=1\), \(\beta=3/5\), \(\delta=7/10\) in Ye (1.7)–(1.9). The estimate is pointwise in the window center \(K\), with no averaging over \(K,\alpha\), or \(\phi\), and with the nonzero phase fixed. Its exponent improves \(44/65+\varepsilon\) from direct substitution in Ye Theorem 1.3 at those same parameters and cutoff. It makes no claim for the unphased prime count or the global prime number theorem.',NULL,'audits/latest62_ye_fullread.md, A direct shorter-height envelope','theorems/latest62_ye_candidates.jsonl');
INSERT INTO "claims" VALUES('CAND-LATEST62-YE-LOCAL-BGSTB','theorems/theorems.jsonl',278,'adjudicated_scoped_source_dependent_corollary','audits/latest62_ye_fullread.md, Weighted BGSTB height slice','{"id": "CAND-LATEST62-YE-LOCAL-BGSTB", "status": "adjudicated_scoped_source_dependent_corollary", "statement": "Fix \\(0<d<2/5\\) and fixed constants \\(c,C>0\\). For \\(T\\to\\infty\\), uniformly over real \\(U\\in[cT,CT]\\), the sum of \\(e^{2y}/(1+y^2)\\) over zeta zero copies with \\(U\\le\\Im\\rho\\le U+U^{3/5}\\), \\(1/2\\le\\Re\\rho\\le1-d\\), and \\(y=(\\Re\\rho-1/2)\\log T\\), is \\(O_{d,\\varepsilon,c,C}(T^{1-d/2+\\varepsilon})\\) for each \\(\\varepsilon>0\\), hence \\(o(T)\\). This is a single-height-window estimate and does not imply global weighted BGSTB tightness.", "dependencies": ["CAND-LATEST62-YE-SHORT-FOURTH", "Classical unit-interval zero count"], "derivation": "Below \\(3/5\\), the local total count and the trivial exponential weight bound give \\(O(T^{4/5+\\varepsilon})\\). Above \\(3/5\\), the local count has slope at most \\(3/2\\); counting bins of width \\(1/\\log T\\) and multiplying by the exponential weight gives exponent \\(1-(1-\\sigma)/2+\\varepsilon\\le1-d/2+\\varepsilon\\). Adjust a strict counting threshold by \\(1/\\log T\\) at grid boundaries, using the trivial bound on the resulting overlap around \\(3/5\\). Covering \\([T,2T]\\) would cost \\(O(T^{2/5})\\) windows. This removes the saving. No fixed zero-free cutoff is needed for the stated real-part slice.", "locator": "audits/latest62_ye_fullread.md, Weighted BGSTB height slice", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/latest62_ye_candidates.jsonl", "verification_status": "Independent derivation, skeptic and director; exact source hypotheses retained; not whole-source proof validation.", "director_evidence": "audits/adversarial_reviews/director_ye_corollaries_round8.md", "status_update_evidence": "audits/adversarial_reviews/director_ye_corollaries_round8.md"}',NULL,'Fix \(0<d<2/5\) and fixed constants \(c,C>0\). For \(T\to\infty\), uniformly over real \(U\in[cT,CT]\), the sum of \(e^{2y}/(1+y^2)\) over zeta zero copies with \(U\le\Im\rho\le U+U^{3/5}\), \(1/2\le\Re\rho\le1-d\), and \(y=(\Re\rho-1/2)\log T\), is \(O_{d,\varepsilon,c,C}(T^{1-d/2+\varepsilon})\) for each \(\varepsilon>0\), hence \(o(T)\). This is a single-height-window estimate and does not imply global weighted BGSTB tightness.',NULL,'audits/latest62_ye_fullread.md, Weighted BGSTB height slice','theorems/latest62_ye_candidates.jsonl');
INSERT INTO "claims" VALUES('THM-L001','theorems/theorems.jsonl',279,'independently_reconstructed_parent_adjudicated','proposals/independent_campaigns/li_advocate.md, Statement L1 and proof','{"id": "THM-L001", "kind": "derived_elementary_theorem", "statement": "For every N>=1 there exists a real entire symmetric order-one F, F(0)=F(1)=1, positive on the real axis and with all zeros in 0<Re(s)<1, with lambda_n(F)>0 for 1<=n<=N but with off-line zeros. Explicit F=normalized cosh times beta=1/4 quartet at T>=10N(N+pi).", "hypotheses": "Generic entire-function class only; no arithmetic Dirichlet/Euler/gamma constraints.", "evidence": "proposals/independent_campaigns/li_advocate.md, Statement L1 and proof", "status": "independently_reconstructed_parent_adjudicated", "novelty_claim": false, "paper_id": null, "locator": "proposals/independent_campaigns/li_advocate.md, Statement L1 and proof", "provenance_file": "theorems/li_campaign.jsonl", "verification": "scoped_Level3; audits/adversarial_reviews/director_adjudication.md"}',NULL,'For every N>=1 there exists a real entire symmetric order-one F, F(0)=F(1)=1, positive on the real axis and with all zeros in 0<Re(s)<1, with lambda_n(F)>0 for 1<=n<=N but with off-line zeros. Explicit F=normalized cosh times beta=1/4 quartet at T>=10N(N+pi).','derived_elementary_theorem','proposals/independent_campaigns/li_advocate.md, Statement L1 and proof','theorems/li_campaign.jsonl');
INSERT INTO "claims" VALUES('THM-L002','theorems/theorems.jsonl',280,'parent_reviewed_with_recorded_correction','proposals/independent_campaigns/li_advocate.md, Statement L2; revision log corrects growth lower-bound inequality','{"id": "THM-L002", "kind": "derived_elementary_theorem", "statement": "THM-L001 remains true with order one infinite type and positive-ordinate zero count T/(2pi)log(T/(2pi))-T/(2pi)+O(1).", "hypotheses": "Construct t_k>2pi e by smooth Riemann counting term=k, pair critical-line zeros in a normalized canonical product, then insert far quartet. No arithmetic constraints.", "evidence": "proposals/independent_campaigns/li_advocate.md, Statement L2; revision log corrects growth lower-bound inequality", "status": "parent_reviewed_with_recorded_correction", "novelty_claim": false, "paper_id": null, "locator": "proposals/independent_campaigns/li_advocate.md, Statement L2; revision log corrects growth lower-bound inequality", "provenance_file": "theorems/li_campaign.jsonl", "verification": "scoped_Level3; audits/adversarial_reviews/director_adjudication.md"}',NULL,'THM-L001 remains true with order one infinite type and positive-ordinate zero count T/(2pi)log(T/(2pi))-T/(2pi)+O(1).','derived_elementary_theorem','proposals/independent_campaigns/li_advocate.md, Statement L2; revision log corrects growth lower-bound inequality','theorems/li_campaign.jsonl');
INSERT INTO "claims" VALUES('THM-L003','theorems/theorems.jsonl',281,'exact_rational_code_and_analytic_bound_author_checked','["proposals/independent_campaigns/li_advocate.md, L3", "experiments/code/li_advocate.py", "experiments/results/li_advocate_exact.json"]','{"id": "THM-L003", "kind": "exact_computational_witness_with_analytic_bound", "statement": "F=cosh(s-1/2)/cosh(1/2) times normalized quartet beta=1/4,T=2 has lambda_n(F)>0 for n=1..11 and lambda_91(F)<0.", "hypotheses": "Li derivatives at s=1; real symmetric product.", "evidence": ["proposals/independent_campaigns/li_advocate.md, L3", "experiments/code/li_advocate.py", "experiments/results/li_advocate_exact.json"], "status": "exact_rational_code_and_analytic_bound_author_checked", "novelty_claim": false, "paper_id": null, "locator": ["proposals/independent_campaigns/li_advocate.md, L3", "experiments/code/li_advocate.py", "experiments/results/li_advocate_exact.json"], "provenance_file": "theorems/li_campaign.jsonl"}',NULL,'F=cosh(s-1/2)/cosh(1/2) times normalized quartet beta=1/4,T=2 has lambda_n(F)>0 for n=1..11 and lambda_91(F)<0.','exact_computational_witness_with_analytic_bound','["proposals/independent_campaigns/li_advocate.md, L3", "experiments/code/li_advocate.py", "experiments/results/li_advocate_exact.json"]','theorems/li_campaign.jsonl');
INSERT INTO "claims" VALUES('THM-L004','theorems/theorems.jsonl',282,'all_m_proof_and_80_exact_rational_samples; independent_extension_review_not_yet_recorded','["proposals/independent_campaigns/multiplicity_general.md", "experiments/code/multiplicity_general_exact.py", "experiments/results/multiplicity_general_exact.json"]','{"id": "THM-L004", "kind": "derived_elementary_theorem", "statement": "For P=(1-z)^m,m>=1,N>=0,L=N+m, the degree<=N optimal coefficient a_n=binom(n+m-1,m-1)*(L-n)_falling_m/(L+1)_rising_m. Minimum squared H2 residual=1-(L)_falling_m/(L+1)_rising_m~m^2/N for fixedm.", "hypotheses": "Unweighted circle H2 norm, complex polynomial approximants, integer multiplicitym>=1.", "evidence": ["proposals/independent_campaigns/multiplicity_general.md", "experiments/code/multiplicity_general_exact.py", "experiments/results/multiplicity_general_exact.json"], "status": "all_m_proof_and_80_exact_rational_samples; independent_extension_review_not_yet_recorded", "novelty_claim": false, "paper_id": null, "locator": ["proposals/independent_campaigns/multiplicity_general.md", "experiments/code/multiplicity_general_exact.py", "experiments/results/multiplicity_general_exact.json"], "provenance_file": "theorems/li_campaign.jsonl", "verification": "scoped_Level3; audits/adversarial_reviews/director_adjudication.md"}',NULL,'For P=(1-z)^m,m>=1,N>=0,L=N+m, the degree<=N optimal coefficient a_n=binom(n+m-1,m-1)*(L-n)_falling_m/(L+1)_rising_m. Minimum squared H2 residual=1-(L)_falling_m/(L+1)_rising_m~m^2/N for fixedm.','derived_elementary_theorem','["proposals/independent_campaigns/multiplicity_general.md", "experiments/code/multiplicity_general_exact.py", "experiments/results/multiplicity_general_exact.json"]','theorems/li_campaign.jsonl');
INSERT INTO "claims" VALUES('THM-L005','theorems/theorems.jsonl',283,'author_algebra_checked; originalLi_proof_independently_reconstructed','audits/adversarial_reviews/li_original_necessity_round2.md, explicit polynomial inw and exponential expansion','{"id": "THM-L005", "kind": "derived_elementary_strengthening", "statement": "The generic finite-Li-prefix countermodels cosh(s-1/2)/cosh(1/2) times a normalized beta1/4 quartet at T>=1/4 also have strictly positive Taylor coefficients of F(1/(1-z)) at every positive degree. Thus positivity of all these coefficients plus any finite positive Li prefix still does not force all zeros onto the line in this generic class.", "hypotheses": "Generic real symmetric entire order-one model; no Euler product, arithmetic coefficients or prescribed gamma factor.", "evidence": "audits/adversarial_reviews/li_original_necessity_round2.md, explicit polynomial inw and exponential expansion", "status": "author_algebra_checked; originalLi_proof_independently_reconstructed", "novelty_claim": false, "paper_id": null, "locator": "audits/adversarial_reviews/li_original_necessity_round2.md, explicit polynomial inw and exponential expansion", "provenance_file": "theorems/li_campaign.jsonl"}',NULL,'The generic finite-Li-prefix countermodels cosh(s-1/2)/cosh(1/2) times a normalized beta1/4 quartet at T>=1/4 also have strictly positive Taylor coefficients of F(1/(1-z)) at every positive degree. Thus positivity of all these coefficients plus any finite positive Li prefix still does not force all zeros onto the line in this generic class.','derived_elementary_strengthening','audits/adversarial_reviews/li_original_necessity_round2.md, explicit polynomial inw and exponential expansion','theorems/li_campaign.jsonl');
INSERT INTO "claims" VALUES('THM-LK301','theorems/theorems.jsonl',284,'self_contained_reconstruction_parent_review_pending','proposals/independent_campaigns/positive_kernel_countermodel_round3.md sections1–4','{"id": "THM-LK301", "kind": "constructed_generic_entire_family", "statement": "For delta*=H13/2-gamma-1>0, B*(w)=sinh(delta*w)/(delta*w) times product_{j>=14}sinh(w/(2j))/(w/(2j)), and C_a(w)=(cosh w+cosh a)/(1+cosh a), F_a(s)=B*(s-1/2)C_a(s-1/2)/[B*(1/2)C_a(1/2)] is real symmetric entire of exact order1/infinite type, normalizedF(0)=F(1)=1 and positive onR. For0<a<1/2 it has off-line zeros1/2±a+i pi(2k+1) and no zeros outside0<Re(s)<1.", "hypotheses": "Generic entire/Laplace model only; positive delta calibrated using57/100<gamma<59/100; zero counts with multiplicity.", "evidence": "proposals/independent_campaigns/positive_kernel_countermodel_round3.md sections1–4", "status": "self_contained_reconstruction_parent_review_pending", "novelty_claim": false, "paper_id": null, "locator": "proposals/independent_campaigns/positive_kernel_countermodel_round3.md sections1–4", "provenance_file": "theorems/li_kernel_round3.jsonl"}',NULL,'For delta*=H13/2-gamma-1>0, B*(w)=sinh(delta*w)/(delta*w) times product_{j>=14}sinh(w/(2j))/(w/(2j)), and C_a(w)=(cosh w+cosh a)/(1+cosh a), F_a(s)=B*(s-1/2)C_a(s-1/2)/[B*(1/2)C_a(1/2)] is real symmetric entire of exact order1/infinite type, normalizedF(0)=F(1)=1 and positive onR. For0<a<1/2 it has off-line zeros1/2±a+i pi(2k+1) and no zeros outside0<Re(s)<1.','constructed_generic_entire_family','proposals/independent_campaigns/positive_kernel_countermodel_round3.md sections1–4','theorems/li_kernel_round3.jsonl');
INSERT INTO "claims" VALUES('THM-LK302','theorems/theorems.jsonl',285,'analytic_reconstruction_parent_review_pending','proposals/independent_campaigns/positive_kernel_countermodel_round3.md sections1–3','{"id": "THM-LK302", "kind": "positive_kernel_regularization", "statement": "The constructed family is the normalized bilateral Laplace transform of a strictly positive even C-infinity probability density onR, with double-exponential tails. Its characteristic function is bounded byexp(-|t|/224) for|t|>=28.", "hypotheses": "Independent uniforms with widthsdelta*,1/(2j),j>=14, plus the specified three-point symmetric variableY_a; fixed0<=a<=1/2.", "evidence": "proposals/independent_campaigns/positive_kernel_countermodel_round3.md sections1–3", "status": "analytic_reconstruction_parent_review_pending", "novelty_claim": false, "paper_id": null, "locator": "proposals/independent_campaigns/positive_kernel_countermodel_round3.md sections1–3", "provenance_file": "theorems/li_kernel_round3.jsonl"}',NULL,'The constructed family is the normalized bilateral Laplace transform of a strictly positive even C-infinity probability density onR, with double-exponential tails. Its characteristic function is bounded byexp(-|t|/224) for|t|>=28.','positive_kernel_regularization','proposals/independent_campaigns/positive_kernel_countermodel_round3.md sections1–3','theorems/li_kernel_round3.jsonl');
INSERT INTO "claims" VALUES('THM-LK303','theorems/theorems.jsonl',286,'exact_formula_and_integer_brackets_checked; parent_review_pending','["proposals/independent_campaigns/positive_kernel_countermodel_round3.md section4", "experiments/code/positive_kernel_round3.py", "experiments/results/positive_kernel_round3.json"]','{"id": "THM-LK303", "kind": "exact_zero_count_calibration", "statement": "WithX=T/(2pi), N_a(T)=D(X)-sum_{j1..13}floor(X/j)+floor(2delta*X)+2floor(X+1/2)=XlogX-X+O(sqrtX), independently ofa in[0,1/2). More precisely remainder equals classical divisor errorDelta_D(X) plus a bounded floor term between-2and14.", "hypotheses": "All zeros counted with multiplicity, including split or double odd-pi zeros. No Riemann-vonMangoldt O(logT) remainder asserted.", "evidence": ["proposals/independent_campaigns/positive_kernel_countermodel_round3.md section4", "experiments/code/positive_kernel_round3.py", "experiments/results/positive_kernel_round3.json"], "status": "exact_formula_and_integer_brackets_checked; parent_review_pending", "novelty_claim": false, "paper_id": null, "locator": ["proposals/independent_campaigns/positive_kernel_countermodel_round3.md section4", "experiments/code/positive_kernel_round3.py", "experiments/results/positive_kernel_round3.json"], "provenance_file": "theorems/li_kernel_round3.jsonl"}',NULL,'WithX=T/(2pi), N_a(T)=D(X)-sum_{j1..13}floor(X/j)+floor(2delta*X)+2floor(X+1/2)=XlogX-X+O(sqrtX), independently ofa in[0,1/2). More precisely remainder equals classical divisor errorDelta_D(X) plus a bounded floor term between-2and14.','exact_zero_count_calibration','["proposals/independent_campaigns/positive_kernel_countermodel_round3.md section4", "experiments/code/positive_kernel_round3.py", "experiments/results/positive_kernel_round3.json"]','theorems/li_kernel_round3.jsonl');
INSERT INTO "claims" VALUES('THM-LK304','theorems/theorems.jsonl',287,'all_N_analytic_proof_and_exact_sample_bounds_checked; parent_review_pending','["proposals/independent_campaigns/positive_kernel_countermodel_round3.md section5", "experiments/code/positive_kernel_round3.py", "experiments/results/positive_kernel_round3.json"]','{"id": "THM-LK304", "kind": "explicit_finite_Li_positive_countermodel", "statement": "For every integerN>=1 choosea_N=1/[10(N+88)5^N]. Thenlambda_n(F_aN)>0 for1<=n<=N, whileoff-line zerosremain. Every positive-degree Taylor coefficient ofF_aN(1/(1-z)) is also strictly positive.", "hypotheses": "Li derivative convention at1. Generic familyTHM-LK301; no arithmetic Euler/Dirichlet/gamma/modularity conditions.", "evidence": ["proposals/independent_campaigns/positive_kernel_countermodel_round3.md section5", "experiments/code/positive_kernel_round3.py", "experiments/results/positive_kernel_round3.json"], "bounds": "baseline lambda_n>=1/[6(N+88)^2]; variation<=8n(cosha-1)5^(n-1); explicita_N makes variation<halfbaseline.", "status": "all_N_analytic_proof_and_exact_sample_bounds_checked; parent_review_pending", "novelty_claim": false, "paper_id": null, "locator": ["proposals/independent_campaigns/positive_kernel_countermodel_round3.md section5", "experiments/code/positive_kernel_round3.py", "experiments/results/positive_kernel_round3.json"], "provenance_file": "theorems/li_kernel_round3.jsonl"}',NULL,'For every integerN>=1 choosea_N=1/[10(N+88)5^N]. Thenlambda_n(F_aN)>0 for1<=n<=N, whileoff-line zerosremain. Every positive-degree Taylor coefficient ofF_aN(1/(1-z)) is also strictly positive.','explicit_finite_Li_positive_countermodel','["proposals/independent_campaigns/positive_kernel_countermodel_round3.md section5", "experiments/code/positive_kernel_round3.py", "experiments/results/positive_kernel_round3.json"]','theorems/li_kernel_round3.jsonl');
INSERT INTO "claims" VALUES('THM-LI97-01','theorems/theorems.jsonl',288,'established_primary_source_result','Theorem1,p325;proofpp325–328;Eq1.1','{"id": "THM-LI97-01", "paper_id": "PAPER-E008", "locator": "Theorem1,p325;proofpp325–328;Eq1.1", "statement": "ForXi(s)=s(s−1)π^(−s/2)Γ(s/2)ζ(s) andλ_n=D^n[s^(n−1)logXi(s)]_(s1)/(n−1)!, allnontrivialzeroscriticaliffλ_n>=0foreveryintegern>=1.", "status": "established_primary_source_result", "verification": "Complete journal-typeset source reconstructed by two independent agents and director; exact local Dedekind normalization repair and source-access boundaries documented.", "review": "audits/adversarial_reviews/li_original_necessity_round2.md", "provenance_file": "theorems/li_original_round2.jsonl", "director_evidence": "audits/adversarial_reviews/director_li_whole_round12.md", "verification_scope": "Whole-work Level 3 for the pinned manifestation; upstream inputs explicitly bounded.", "status_update_evidence": "audits/adversarial_reviews/director_li_whole_round12.md"}','PAPER-E008','ForXi(s)=s(s−1)π^(−s/2)Γ(s/2)ζ(s) andλ_n=D^n[s^(n−1)logXi(s)]_(s1)/(n−1)!, allnontrivialzeroscriticaliffλ_n>=0foreveryintegern>=1.',NULL,'Theorem1,p325;proofpp325–328;Eq1.1','theorems/li_original_round2.jsonl');
