INSERT INTO "claims" VALUES('THM-PHASE-REGULARIZATION-PARETO','theorems/theorems.jsonl',314,'adjudicated_scoped_unconditional_classical_spectral_calculation','audits/adversarial_reviews/director_phase_regularization_round6.md; two independentproofs andexactintegrals','{"id": "THM-PHASE-REGULARIZATION-PARETO", "paper_id": null, "claim_kind": "proved_exact_operator_domain_regularization_frontier", "statement": "LetUbeanyunitaryMellinmultiplieroncomplexL²(dx),g=U1_(0,1],D=xpartial_xwithmaximalweakdomain. Foreach0<epsilon<1, letzin(0,1)solvez+z³=2epsilon². Theninf_{f inDomD,||f-g||<=epsilon}||Df||²=(1-z²)²/(8z),withuniqueMellinfilterf_tauhat=U(s)/[s(1+tau|s|²)],z=sqrt(tau/(4+tau)). Thus epsilon timesminimumderivativenormapproaches1/4.", "hypotheses": "CriticalRe1/2,Mellinmeasure dt/(2pi);arbitrarycomplexfunctions;maximalweakDdomain=logH1. D+.5orfullgraphnormhave differentfinitefrontiers. NoRH,source-priorityornoveltyclaim.", "locator": "audits/adversarial_reviews/director_phase_regularization_round6.md; two independentproofs andexactintegrals", "status": "adjudicated_scoped_unconditional_classical_spectral_calculation", "novelty_claim": false, "provenance_file": "theorems/phase_regularization_director_round6.jsonl"}',NULL,'LetUbeanyunitaryMellinmultiplieroncomplexL²(dx),g=U1_(0,1],D=xpartial_xwithmaximalweakdomain. Foreach0<epsilon<1, letzin(0,1)solvez+z³=2epsilon². Theninf_{f inDomD,||f-g||<=epsilon}||Df||²=(1-z²)²/(8z),withuniqueMellinfilterf_tauhat=U(s)/[s(1+tau|s|²)],z=sqrt(tau/(4+tau)). Thus epsilon timesminimumderivativenormapproaches1/4.','proved_exact_operator_domain_regularization_frontier','audits/adversarial_reviews/director_phase_regularization_round6.md; two independentproofs andexactintegrals','theorems/phase_regularization_director_round6.jsonl');
INSERT INTO "claims" VALUES('OBS-PREFIX-CLOSED','theorems/theorems.jsonl',315,'adjudicated_scoped_unconditional_finite_theorem','audits/adversarial_reviews/director_prefix_cost_round6.md; two independent proofs and72 exact rational comparisons each','{"id": "OBS-PREFIX-CLOSED", "paper_id": null, "claim_kind": "independently_proved_finite_matrix_identity", "statement": "For integerm>=1 and0<=b<1, Mij=(1-b^(i+j+1))/(i+j+1),vj=-delta_j0+m b^(j+1)/(j+1), letc_m(b)=m²b+v^T M^-1v. With LegendreP_n(1)=1 and a=(1+b)/(1-b), c_m(b)=m²+2integral_1^a[P''_(m-1)(x)]²dx. For m>=2 it is strictly increasing inb and >m² forb>0; c1=1,c2=4/(1-b).", "hypotheses": "Finite real positive definite polynomial Gram problem; no RH or arithmetic-prefix theorem premise.", "locator": "audits/adversarial_reviews/director_prefix_cost_round6.md; two independent proofs and72 exact rational comparisons each", "status": "adjudicated_scoped_unconditional_finite_theorem", "novelty_claim": false, "provenance_file": "theorems/prefix_cost_director_round6.jsonl"}',NULL,'For integerm>=1 and0<=b<1, Mij=(1-b^(i+j+1))/(i+j+1),vj=-delta_j0+m b^(j+1)/(j+1), letc_m(b)=m²b+v^T M^-1v. With LegendreP_n(1)=1 and a=(1+b)/(1-b), c_m(b)=m²+2integral_1^a[P''_(m-1)(x)]²dx. For m>=2 it is strictly increasing inb and >m² forb>0; c1=1,c2=4/(1-b).','independently_proved_finite_matrix_identity','audits/adversarial_reviews/director_prefix_cost_round6.md; two independent proofs and72 exact rational comparisons each','theorems/prefix_cost_director_round6.jsonl');
INSERT INTO "claims" VALUES('OBS-PREFIX-ENDPOINT','theorems/theorems.jsonl',316,'adjudicated_scoped_unconditional','audits/adversarial_reviews/director_prefix_cost_round6.md endpointregime; OBS-PREFIX-CLOSED','{"id": "OBS-PREFIX-ENDPOINT", "paper_id": null, "claim_kind": "proved_finite_constant_endpoint_asymptotic", "statement": "For each fixed integerm>=2, c_m(b)~4(2m-3)binom(2m-4,m-2)^2(1-b)^(-(2m-3)) asb approaches1 frombelow. In particular the naive polepower2m-1 is wrong; c3(1/2)=165.", "locator": "audits/adversarial_reviews/director_prefix_cost_round6.md endpointregime; OBS-PREFIX-CLOSED", "status": "adjudicated_scoped_unconditional", "novelty_claim": false, "provenance_file": "theorems/prefix_cost_director_round6.jsonl"}',NULL,'For each fixed integerm>=2, c_m(b)~4(2m-3)binom(2m-4,m-2)^2(1-b)^(-(2m-3)) asb approaches1 frombelow. In particular the naive polepower2m-1 is wrong; c3(1/2)=165.','proved_finite_constant_endpoint_asymptotic','audits/adversarial_reviews/director_prefix_cost_round6.md endpointregime; OBS-PREFIX-CLOSED','theorems/prefix_cost_director_round6.jsonl');
INSERT INTO "claims" VALUES('OBS-PREFIX-LARGE-M','theorems/theorems.jsonl',317,'adjudicated_scoped_unconditional','audits/adversarial_reviews/director_prefix_cost_round6.md endpointLaplaceproof; independent terminal-mode proof','{"id": "OBS-PREFIX-LARGE-M", "paper_id": null, "claim_kind": "proved_finite_constant_large_degree_asymptotic", "statement": "For every fixedb in(0,1), withR=(1+sqrt b)/(1-sqrt b), c_m(b)~(1-b)^2 R^(2m-1)/(8pi b) asm tendsinfinity. This is not asserted uniformly for movingb.", "locator": "audits/adversarial_reviews/director_prefix_cost_round6.md endpointLaplaceproof; independent terminal-mode proof", "status": "adjudicated_scoped_unconditional", "novelty_claim": false, "provenance_file": "theorems/prefix_cost_director_round6.jsonl"}',NULL,'For every fixedb in(0,1), withR=(1+sqrt b)/(1-sqrt b), c_m(b)~(1-b)^2 R^(2m-1)/(8pi b) asm tendsinfinity. This is not asserted uniformly for movingb.','proved_finite_constant_large_degree_asymptotic','audits/adversarial_reviews/director_prefix_cost_round6.md endpointLaplaceproof; independent terminal-mode proof','theorems/prefix_cost_director_round6.jsonl');
INSERT INTO "claims" VALUES('OBS-PREFIX-DIAGONAL-CONTROL','theorems/theorems.jsonl',318,'adjudicated_scoped_model_counterexample_not_actual_arithmetic_sequence','audits/adversarial_reviews/director_prefix_cost_round6.md; prefix_skeptic62.md','{"id": "OBS-PREFIX-DIAGONAL-CONTROL", "paper_id": null, "claim_kind": "explicit_negative_control_to_uniformity_inference", "statement": "The positive increasing functionsF_N(b)=c_m(b)(1+b^N) have the correct fixedb<1 limitc_m(b), whileF_N(1-1/N)/c_m(1-1/N) approaches1+e^-1. Thus even monotone fixed-prefix limits do not imply a moving-prefix relative asymptotic.", "locator": "audits/adversarial_reviews/director_prefix_cost_round6.md; prefix_skeptic62.md", "status": "adjudicated_scoped_model_counterexample_not_actual_arithmetic_sequence", "novelty_claim": false, "provenance_file": "theorems/prefix_cost_director_round6.jsonl"}',NULL,'The positive increasing functionsF_N(b)=c_m(b)(1+b^N) have the correct fixedb<1 limitc_m(b), whileF_N(1-1/N)/c_m(1-1/N) approaches1+e^-1. Thus even monotone fixed-prefix limits do not imply a moving-prefix relative asymptotic.','explicit_negative_control_to_uniformity_inference','audits/adversarial_reviews/director_prefix_cost_round6.md; prefix_skeptic62.md','theorems/prefix_cost_director_round6.jsonl');
INSERT INTO "claims" VALUES('PREFIX-FORMULA62-IMPRIMITIVE-SANDWICH','theorems/theorems.jsonl',319,'adjudicated_scoped_unconditional','audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, Two inequalities','{"id": "PREFIX-FORMULA62-IMPRIMITIVE-SANDWICH", "status": "adjudicated_scoped_unconditional", "claim_kind": "unconditional_finite_factor_transfer", "statement": "For fixed imprimitive chi induced by chi*, M the product of newly omitted primes, and delta_J the product envelope in the proof, Delta_(MN,chi*) <= Delta_(N,chi) <= (1+delta_J)Delta_(floor(N/M^J),chi*)+delta_J. Ordinary unrestricted coefficients, N>=M^J.", "locator": "audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, Two inequalities", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/prefix_formula62_imprimitive_transfer_claims.jsonl", "verification_status": "Two independent derivations and director; fixed-character unrestricted ordinary space; anchor distinguished.", "director_evidence": "audits/adversarial_reviews/director_imprimitive_anchor_round8.md", "status_update_evidence": "audits/adversarial_reviews/director_imprimitive_anchor_round8.md"}',NULL,'For fixed imprimitive chi induced by chi*, M the product of newly omitted primes, and delta_J the product envelope in the proof, Delta_(MN,chi*) <= Delta_(N,chi) <= (1+delta_J)Delta_(floor(N/M^J),chi*)+delta_J. Ordinary unrestricted coefficients, N>=M^J.','unconditional_finite_factor_transfer','audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, Two inequalities','theorems/prefix_formula62_imprimitive_transfer_claims.jsonl');
INSERT INTO "claims" VALUES('PREFIX-FORMULA62-IMPRIMITIVE-OPTIMUM','theorems/theorems.jsonl',320,'adjudicated_scoped_conditional_on_primitive_optimum','audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, Right constant','{"id": "PREFIX-FORMULA62-IMPRIMITIVE-OPTIMUM", "status": "adjudicated_scoped_conditional_on_primitive_optimum", "claim_kind": "conditional_arithmetic_corollary", "statement": "For fixed induced chi and the primitive GRH-conditional optimum, log(N)Delta_(N,chi)^2 has the same squared multiplicity constant of distinct critical-line zeros as the inducing primitive function, including the imprimitive principal case under RH.", "locator": "audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, Right constant", "dependencies": ["PREFIX-FORMULA62-IMPRIMITIVE-SANDWICH", "audits/adversarial_reviews/director_dirichlet_transfer_round6.md"], "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/prefix_formula62_imprimitive_transfer_claims.jsonl", "verification_status": "Two independent derivations and director; fixed-character unrestricted ordinary space; anchor distinguished.", "director_evidence": "audits/adversarial_reviews/director_imprimitive_anchor_round8.md", "status_update_evidence": "audits/adversarial_reviews/director_imprimitive_anchor_round8.md"}',NULL,'For fixed induced chi and the primitive GRH-conditional optimum, log(N)Delta_(N,chi)^2 has the same squared multiplicity constant of distinct critical-line zeros as the inducing primitive function, including the imprimitive principal case under RH.','conditional_arithmetic_corollary','audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, Right constant','theorems/prefix_formula62_imprimitive_transfer_claims.jsonl');
INSERT INTO "claims" VALUES('PREFIX-FORMULA62-NONPRINCIPAL-ANCHOR','theorems/theorems.jsonl',321,'adjudicated_scoped_unconditional','audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, What an anchor at one changes','{"id": "PREFIX-FORMULA62-NONPRINCIPAL-ANCHOR", "status": "adjudicated_scoped_unconditional", "claim_kind": "unconditional_anchor_obstruction", "statement": "For every fixed nonprincipal Dirichlet character, imposing A(1)=0, including via A−A(1), makes the ordinary critical-line rational-weight distance exactly one at every cutoff.", "locator": "audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, What an anchor at one changes", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/prefix_formula62_imprimitive_transfer_claims.jsonl", "verification_status": "Two independent derivations and director; fixed-character unrestricted ordinary space; anchor distinguished.", "director_evidence": "audits/adversarial_reviews/director_imprimitive_anchor_round8.md", "status_update_evidence": "audits/adversarial_reviews/director_imprimitive_anchor_round8.md"}',NULL,'For every fixed nonprincipal Dirichlet character, imposing A(1)=0, including via A−A(1), makes the ordinary critical-line rational-weight distance exactly one at every cutoff.','unconditional_anchor_obstruction','audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, What an anchor at one changes','theorems/prefix_formula62_imprimitive_transfer_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-ROOTED-CUE-TAGGED-COMPRESSION','theorems/theorems.jsonl',322,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md','{"id": "LEM-ROOTED-CUE-TAGGED-COMPRESSION", "paper_id": null, "locator": "audits/adversarial_reviews/director_cue_windows_round13.md · Measure and exact complementary determinant; separate signed totals", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md", "statement": "The rank-two rooted CUE MGF equals e^(−H_N z_c) det A det(U* A^−1 U). For each tagged word with positive and negative totals P,Q≤n=N+1, the compressed inverse coefficient uses the oriented sum from Q to n−P; its constant/linear matrix is the polynomial in ell=n−P−Q and D=P−Q in the director note.", "hypotheses": "Global joint Haar-matrix/root-label derivative-square tilt with the deterministic root reinserted; formal coefficients at zero. The reversed interval contributes an oriented sum, including P=n or Q=n. No fixed-symbol asymptotic is invoked.", "claim_kind": "intrinsic_exact_finite_identity", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'The rank-two rooted CUE MGF equals e^(−H_N z_c) det A det(U* A^−1 U). For each tagged word with positive and negative totals P,Q≤n=N+1, the compressed inverse coefficient uses the oriented sum from Q to n−P; its constant/linear matrix is the polynomial in ell=n−P−Q and D=P−Q in the director note.','intrinsic_exact_finite_identity','audits/adversarial_reviews/director_cue_windows_round13.md · Measure and exact complementary determinant; separate signed totals','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('THM-ROOTED-CUE-JOINT-CLOSED-MOMENT-WINDOW','theorems/theorems.jsonl',323,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md','{"id": "THM-ROOTED-CUE-JOINT-CLOSED-MOMENT-WINDOW", "paper_id": null, "locator": "audits/adversarial_reviews/director_cue_windows_round13.md · Joint quartic and exact finite-size surrogate", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md", "statement": "At each fixed total degree r with rb≤1, the limiting mixed moments are the factorial-weighted coefficients of exp[H z_c+H(z_c²+z_s²)/4] [(1−d z_c)^4+2J3 z_c(1−d z_c)−3J2² z_s²], where H=log(b/a), d=b−a and J_j=(b^j−a^j)/j. The exact finite surrogate uses H_N, d_N, J_j,N and the n^−2 correction in the note.", "hypotheses": "Fixed 0<a<b<1; negative cosine/sine bands, one deterministic root, global rank-two tilt. Finite agreement through degree r holds for r K_N≤n=N+1. The arithmetic window remains rb<1/2 under RH; this result is intrinsic.", "claim_kind": "intrinsic_finite_mixed_moment_window", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'At each fixed total degree r with rb≤1, the limiting mixed moments are the factorial-weighted coefficients of exp[H z_c+H(z_c²+z_s²)/4] [(1−d z_c)^4+2J3 z_c(1−d z_c)−3J2² z_s²], where H=log(b/a), d=b−a and J_j=(b^j−a^j)/j. The exact finite surrogate uses H_N, d_N, J_j,N and the n^−2 correction in the note.','intrinsic_finite_mixed_moment_window','audits/adversarial_reviews/director_cue_windows_round13.md · Joint quartic and exact finite-size surrogate','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('THM-ROOTED-CUE-FIRST-FREQUENCY-CORRECTION','theorems/theorems.jsonl',324,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md','{"id": "THM-ROOTED-CUE-FIRST-FREQUENCY-CORRECTION", "paper_id": null, "locator": "audits/adversarial_reviews/director_cue_windows_round13.md · First new frequency chamber", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md", "statement": "For (r−1)b≤1<rb, the first cosine raw-moment discrepancy from its formal continuation is −2^(1−r) I_r, where I_r=∫_{[a,b]^r, sum x_i>1}(2−4 sum x_i+2(sum x_i)^3) prod dx_i/x_i>0. The joint degree-r MGF difference is −[(z_c−i z_s)^r+(z_c+i z_s)^r] I_r/(2^r r!).", "hypotheses": "Same fixed rank-two model; only the first crossing is evaluated. The pure cosine sign is strict; mixed rays can vanish or change sign.", "claim_kind": "intrinsic_first_chamber_correction", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'For (r−1)b≤1<rb, the first cosine raw-moment discrepancy from its formal continuation is −2^(1−r) I_r, where I_r=∫_{[a,b]^r, sum x_i>1}(2−4 sum x_i+2(sum x_i)^3) prod dx_i/x_i>0. The joint degree-r MGF difference is −[(z_c−i z_s)^r+(z_c+i z_s)^r] I_r/(2^r r!).','intrinsic_first_chamber_correction','audits/adversarial_reviews/director_cue_windows_round13.md · First new frequency chamber','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-ROOTED-CUE-FIRST-CHAMBER-FOURTH','theorems/theorems.jsonl',325,'adjudicated_scoped','audits/adversarial_reviews/uniform92_first_chamber_certificate_review.md','{"id": "CERT-ROOTED-CUE-FIRST-CHAMBER-FOURTH", "paper_id": null, "locator": "audits/adversarial_reviews/director_cue_windows_round13.md · Independent exact finite and continuum checks", "evidence": "audits/adversarial_reviews/uniform92_first_chamber_certificate_review.md", "statement": "For N=40, n=41 and modes 9,10,11 the exact fourth moment minus the formal surrogate is −3384187/302541624000. For band (0.22,0.28) an exact rational enclosure of the limiting fourth correction near −1.116093794622113479066e−5 has width <2.63e−27.", "hypotheses": "Exact rational projection/cumulant and simplex checks. The director''s finite calculation is experiments/results/director_round13_cue_fourth.json. These certificates do not give an arithmetic chamber or convergence rate.", "claim_kind": "exact_finite_and_interval_certificate", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'For N=40, n=41 and modes 9,10,11 the exact fourth moment minus the formal surrogate is −3384187/302541624000. For band (0.22,0.28) an exact rational enclosure of the limiting fourth correction near −1.116093794622113479066e−5 has width <2.63e−27.','exact_finite_and_interval_certificate','audits/adversarial_reviews/director_cue_windows_round13.md · Independent exact finite and continuum checks','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('THM-ROOTED-CUE-INTEGER-RANK-WINDOW','theorems/theorems.jsonl',326,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md','{"id": "THM-ROOTED-CUE-INTEGER-RANK-WINDOW", "paper_id": null, "locator": "audits/adversarial_reviews/director_cue_windows_round13.md · Every fixed integer tilt rank has an extrapolation barrier", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md", "statement": "At fixed integer rank J≥1 the cosine-window coefficients for rb≤1 are those of exp[(J−1)H z+H z²/4] det B_J(z), with B_J the formal oriented Legendre matrix in the note, B_J(0)=I, and deg det B_J≤J².", "hypotheses": "Global root tilt |Z′|^(2(J−1)), ambient dimension N+J−1, one deterministic root, fixed positive band and fixed degree. Formal compound-Poisson notation computes polynomial coefficients.", "claim_kind": "intrinsic_fixed_rank_moment_window", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'At fixed integer rank J≥1 the cosine-window coefficients for rb≤1 are those of exp[(J−1)H z+H z²/4] det B_J(z), with B_J the formal oriented Legendre matrix in the note, B_J(0)=I, and deg det B_J≤J².','intrinsic_fixed_rank_moment_window','audits/adversarial_reviews/director_cue_windows_round13.md · Every fixed integer tilt rank has an extrapolation barrier','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-ROOTED-CUE-ALL-RANK-FINITE-SQUARE-BARRIER','theorems/theorems.jsonl',327,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md','{"id": "OBS-ROOTED-CUE-ALL-RANK-FINITE-SQUARE-BARRIER", "paper_id": null, "locator": "audits/adversarial_reviews/director_cue_windows_round13.md · Every fixed integer tilt rank has an extrapolation barrier", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md", "statement": "For each integer J≥1 and fixed 0<a<b<1 the formal all-order cosine continuation has a positive real MGF zero and a finite negative square witness. For J≥3 the {0,2} principal minor at z=1/d has determinant −20(m3/d)², forcing a zero before 1/d. Centered finite Taylor approximants to exp(z* X/2) eventually have negative formal square expectation.", "hypotheses": "The polynomial-exponential signed inverse has Gaussian moment domination. The witness is at finite but potentially large degree in the formal sequence; no contradiction to the true finite window or novelty is claimed.", "claim_kind": "formal_extrapolation_positivity_obstruction", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'For each integer J≥1 and fixed 0<a<b<1 the formal all-order cosine continuation has a positive real MGF zero and a finite negative square witness. For J≥3 the {0,2} principal minor at z=1/d has determinant −20(m3/d)², forcing a zero before 1/d. Centered finite Taylor approximants to exp(z* X/2) eventually have negative formal square expectation.','formal_extrapolation_positivity_obstruction','audits/adversarial_reviews/director_cue_windows_round13.md · Every fixed integer tilt rank has an extrapolation barrier','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('THM-ROOTED-CUE-RANK-CORRECTION-PARITY','theorems/theorems.jsonl',328,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md','{"id": "THM-ROOTED-CUE-RANK-CORRECTION-PARITY", "paper_id": null, "locator": "audits/adversarial_reviews/director_cue_windows_round13.md · Every fixed integer tilt rank has an extrapolation barrier", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md", "statement": "For (r−1)b≤1<rb the first cosine raw-moment discrepancy at fixed rank J has sign (−1)^(J+1). The pure-sign continuation A_J(t) has sign (−1)^J for t>1; rank three gives A_3(t)=−6t^5+12t³−9t+3 and a finite example with correction +9/160.", "hypotheses": "Intrinsic globally weighted rooted model. Christoffel–Darboux and Legendre parity apply to the reversed integration interval. This is a first crossing sign only.", "claim_kind": "intrinsic_first_chamber_rank_sign", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'For (r−1)b≤1<rb the first cosine raw-moment discrepancy at fixed rank J has sign (−1)^(J+1). The pure-sign continuation A_J(t) has sign (−1)^J for t>1; rank three gives A_3(t)=−6t^5+12t³−9t+3 and a finite example with correction +9/160.','intrinsic_first_chamber_rank_sign','audits/adversarial_reviews/director_cue_windows_round13.md · Every fixed integer tilt rank has an extrapolation barrier','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('THM-GRID-TWO-SCALE-UNIVERSAL-TIGHTNESS','theorems/theorems.jsonl',329,'adjudicated_scoped','audits/adversarial_reviews/director_two_scale_round13.md','{"id": "THM-GRID-TWO-SCALE-UNIVERSAL-TIGHTNESS", "paper_id": null, "locator": "audits/adversarial_reviews/director_two_scale_round13.md · Statement with the quantifiers fixed", "evidence": "audits/adversarial_reviews/director_two_scale_round13.md", "statement": "For node increments bounded in pth moment by C min(h^a+epsilon_n,A_n h^b), the polygonal modulus satisfies ||omega(delta)||_p≤C1 [delta^((a′−1)/p)+lambda_n^(1/p) min(1,(delta/w_n)^((b′−1)/p))], where a′=min(a,p), b′=min(b,p), w_n=(epsilon_n/A_n)^(1/b), lambda_n=epsilon_n/w_n. The universal tightness criterion A_n epsilon_n^(b−1)→0 is sharp, with a single random spike giving failure otherwise.", "hypotheses": "Fixed p,a,b>1 and C>0, A_n≥1, 0<epsilon_n≤1 tending to zero, arbitrary deterministic finite grids, tight initial values for each family. A guarantee uniform across families needs uniformly tight initial values. Step transfer uses mesh→0, jumps→0, or exact composition and continuous clock comparison as specified. Necessity quantifies over grids and laws rather than one process.", "claim_kind": "unconditional_sharp_universal_tightness", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'For node increments bounded in pth moment by C min(h^a+epsilon_n,A_n h^b), the polygonal modulus satisfies ||omega(delta)||_p≤C1 [delta^((a′−1)/p)+lambda_n^(1/p) min(1,(delta/w_n)^((b′−1)/p))], where a′=min(a,p), b′=min(b,p), w_n=(epsilon_n/A_n)^(1/b), lambda_n=epsilon_n/w_n. The universal tightness criterion A_n epsilon_n^(b−1)→0 is sharp, with a single random spike giving failure otherwise.','unconditional_sharp_universal_tightness','audits/adversarial_reviews/director_two_scale_round13.md · Statement with the quantifiers fixed','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-GRID-TWO-SCALE-DIRECT-EXPONENT','theorems/theorems.jsonl',330,'adjudicated_scoped','audits/adversarial_reviews/director_two_scale_round13.md','{"id": "LEM-GRID-TWO-SCALE-DIRECT-EXPONENT", "paper_id": null, "locator": "audits/adversarial_reviews/director_two_scale_round13.md · Direct exponents, arithmetic use and Lean boundary", "evidence": "audits/adversarial_reviews/director_two_scale_round13.md", "statement": "For 1<q≤min(a,b), the optimal scalar envelope constant is comparable to 1+A_n^(q/b) epsilon_n^(1−q/b). For a=b=2, A=L² and epsilon=L^−M, the sharp universal saving threshold is M>2 and the maximal common direct exponent is 2M/(M+2) as L→infinity.", "hypotheses": "All scalar distances 0<h≤1; realized distances in a particular grid can give stronger estimates. For M≤2 no uniform q>1 follows from the envelope. Polygonal interpolation caps the power at p.", "claim_kind": "unconditional_scalar_envelope_bound", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'For 1<q≤min(a,b), the optimal scalar envelope constant is comparable to 1+A_n^(q/b) epsilon_n^(1−q/b). For a=b=2, A=L² and epsilon=L^−M, the sharp universal saving threshold is M>2 and the maximal common direct exponent is 2M/(M+2) as L→infinity.','unconditional_scalar_envelope_bound','audits/adversarial_reviews/director_two_scale_round13.md · Direct exponents, arithmetic use and Lean boundary','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-LEAN-TWO-SCALE-SCALAR','theorems/theorems.jsonl',331,'adjudicated_scoped','experiments/results/two_scale_scalar_lean_check.txt','{"id": "CERT-LEAN-TWO-SCALE-SCALAR", "paper_id": null, "locator": "audits/adversarial_reviews/director_two_scale_round13.md · Direct exponents, arithmetic use and Lean boundary", "evidence": "experiments/results/two_scale_scalar_lean_check.txt", "statement": "Lean declaration Observatory.twoScaleScalarBound proves X≤2 C u³ from X≤C(u⁴+v⁶), X v²≤C u⁴, 0≤u≤1, 0<v≤1 and C≥0. With h=u² and L=1/v this is the M=6 scalar step.", "hypotheses": "Lean 4.33.0-rc2, standard axiom closure propext, Classical.choice and Quot.sound, no sorryAx. Both scalar inequalities are premises; the probability and number-theoretic inputs and Brownian limit are outside this declaration.", "claim_kind": "locally_compiled_formal_scalar_check", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'Lean declaration Observatory.twoScaleScalarBound proves X≤2 C u³ from X≤C(u⁴+v⁶), X v²≤C u⁴, 0≤u≤1, 0<v≤1 and C≥0. With h=u² and L=1/v this is the M=6 scalar step.','locally_compiled_formal_scalar_check','audits/adversarial_reviews/director_two_scale_round13.md · Direct exponents, arithmetic use and Lean boundary','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('THM-HR-REPAIRED-FINITE-GAUSSIAN-MOMENTS','theorems/theorems.jsonl',332,'adjudicated_scoped','audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md','{"id": "THM-HR-REPAIRED-FINITE-GAUSSIAN-MOMENTS", "paper_id": "PAPER-AN79-HR-ZETA", "locator": "audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md · Statistic, literal hypotheses and repaired theorem", "evidence": "audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md", "statement": "The first m raw zero-statistic moments converge to the Gaussian moments of mean I=∫f and variance ∫min(|v|,1) fhat(v)² dv, provided I=0 or ∫w(u) log^m(2+|u|)du<infinity. For I≠0 that logarithmic moment is necessary for finiteness of the mth absolute moment at any fixed T>1,H>0.", "hypotheses": "No RH. Real even f with smooth compact Fourier transform in [−sigma,sigma], m sigma/2<a, H=T^a, 0<a≤1; evaluate the entire extension at complex ordinates. Nonnegative mass-one w with compact Fourier support. Finite moment window; the repair controls mixed gamma and polar terms additively.", "claim_kind": "versioned_repaired_source_theorem", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}','PAPER-AN79-HR-ZETA','The first m raw zero-statistic moments converge to the Gaussian moments of mean I=∫f and variance ∫min(|v|,1) fhat(v)² dv, provided I=0 or ∫w(u) log^m(2+|u|)du<infinity. For I≠0 that logarithmic moment is necessary for finiteness of the mth absolute moment at any fixed T>1,H>0.','versioned_repaired_source_theorem','audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md · Statistic, literal hypotheses and repaired theorem','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('THM-HR-OSCILLATORY-PRINTED-WEIGHT-WINDOW','theorems/theorems.jsonl',333,'adjudicated_scoped','audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md','{"id": "THM-HR-OSCILLATORY-PRINTED-WEIGHT-WINDOW", "paper_id": "PAPER-AN79-HR-ZETA", "locator": "audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md · Reconstruction of the valid argument", "evidence": "audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md", "statement": "The oscillatory prime statistic alone has the stated finite Gaussian moment window with the original nonnegative unit-mass bandlimited weights. Compact Fourier support eliminates unequal product frequencies and the leading equal-product terms give Wick pairings.", "hypotheses": "No RH and no logarithmic moment required for this oscillatory theorem. Same strict m sigma/2<a; the variance identification is needed only when m≥2. This theorem excludes the centering and polar contributions to the full statistic.", "claim_kind": "versioned_source_theorem_reconstruction", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}','PAPER-AN79-HR-ZETA','The oscillatory prime statistic alone has the stated finite Gaussian moment window with the original nonnegative unit-mass bandlimited weights. Compact Fourier support eliminates unequal product frequencies and the leading equal-product terms give Wick pairings.','versioned_source_theorem_reconstruction','audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md · Reconstruction of the valid argument','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-HLZ-FOURTH-PURE-ARM-REDUCTION','theorems/theorems.jsonl',334,'adjudicated_scoped','audits/adversarial_reviews/director_pure_fourth_round13.md','{"id": "OBS-HLZ-FOURTH-PURE-ARM-REDUCTION", "paper_id": null, "locator": "audits/adversarial_reviews/director_pure_fourth_round13.md · Exact target and what is already covered", "evidence": "audits/adversarial_reviews/director_pure_fourth_round13.md", "statement": "For the cosine band W=Re D and 1/8<b<1/6, the difference between E_Y W⁴ and its formal fourth coefficient is (Re E_Y D⁴−m4_pure)/8+o(1), with m4_pure=4![z⁴] exp(H0 z)[(1−d z)^4+2m3 z(1−d z)+3m2² z²]. The mixed arms and a uniform sixth absolute moment are already covered.", "hypotheses": "RH, fixed 0<a<b, and the symmetric strict derivative-square tail. The 3+1 and 2+2 arms have longest length ≤Y^(3b)<sqrt(Y); the long pure arm is unresolved. Intrinsic CUE gives no arithmetic main term.", "claim_kind": "conditional_exact_single_arm_reduction", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'For the cosine band W=Re D and 1/8<b<1/6, the difference between E_Y W⁴ and its formal fourth coefficient is (Re E_Y D⁴−m4_pure)/8+o(1), with m4_pure=4![z⁴] exp(H0 z)[(1−d z)^4+2m3 z(1−d z)+3m2² z²]. The mixed arms and a uniform sixth absolute moment are already covered.','conditional_exact_single_arm_reduction','audits/adversarial_reviews/director_pure_fourth_round13.md · Exact target and what is already covered','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-HLZ-ONE-SIDED-LONG-CONTINUOUS','theorems/theorems.jsonl',335,'adjudicated_scoped','audits/adversarial_reviews/director_pure_fourth_round13.md','{"id": "LEM-HLZ-ONE-SIDED-LONG-CONTINUOUS", "paper_id": null, "locator": "audits/adversarial_reviews/director_pure_fourth_round13.md · One-sided continuous moments do not impose the half-power barrier", "evidence": "audits/adversarial_reviews/director_pure_fourth_round13.md", "statement": "The continuous shifted zeta product against one bounded-coefficient Dirichlet polynomial of length y≤T^theta, theta<1, has the explicit two-diagonal formula in the note with error O_epsilon(T^epsilon[(yT)^(1/2)+y^(1/4)T^(3/4)]), also with the logarithmic weight. The diagonal poles cancel.", "hypotheses": "Unconditional continuous-height integral, constant second arm and fixed microscopic shift radius. The direct asymmetric AFE proof does not estimate the discrete nonprincipal edge.", "claim_kind": "unconditional_asymmetric_continuous_estimate", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'The continuous shifted zeta product against one bounded-coefficient Dirichlet polynomial of length y≤T^theta, theta<1, has the explicit two-diagonal formula in the note with error O_epsilon(T^epsilon[(yT)^(1/2)+y^(1/4)T^(3/4)]), also with the logarithmic weight. The diagonal poles cancel.','unconditional_asymmetric_continuous_estimate','audits/adversarial_reviews/director_pure_fourth_round13.md · One-sided continuous moments do not impose the half-power barrier','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-HLZ-SMOOTH-REFLECTED-SADDLE','theorems/theorems.jsonl',336,'adjudicated_scoped','audits/adversarial_reviews/director_pure_fourth_round13.md','{"id": "LEM-HLZ-SMOOTH-REFLECTED-SADDLE", "paper_id": null, "locator": "audits/adversarial_reviews/director_pure_fourth_round13.md · A smooth contour formulation closes the saddle error", "evidence": "audits/adversarial_reviews/director_pure_fourth_round13.md", "statement": "A two-transition compact comparable-height cutoff of width H=T^kappa with kappa>(1+theta)/2, theta=4b, gives a reflected saddle error O(T/H²) per comparable term. The aggregated error is bounded by T^epsilon[T²y/H²+y+Ty/H]. Sharp zero-sum endpoints are recovered after differentiation with transition mass O(T^epsilon(H+Y^(2b))).", "hypotheses": "RH for the zero-sampling endpoint comparison, fixed microscopic shifts, theta<1 and kappa<1. The cutoff is shift-independent before differentiation. The result applies to the smooth saddle and does not recover the original hard arithmetic cutoff.", "claim_kind": "conditional_smooth_saddle_and_endpoint_replacement", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'A two-transition compact comparable-height cutoff of width H=T^kappa with kappa>(1+theta)/2, theta=4b, gives a reflected saddle error O(T/H²) per comparable term. The aggregated error is bounded by T^epsilon[T²y/H²+y+Ty/H]. Sharp zero-sum endpoints are recovered after differentiation with transition mass O(T^epsilon(H+Y^(2b))).','conditional_smooth_saddle_and_endpoint_replacement','audits/adversarial_reviews/director_pure_fourth_round13.md · A smooth contour formulation closes the saddle error','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-HLZ-REFLECTED-EDGE-FIXED-SEQUENCE','theorems/theorems.jsonl',337,'adjudicated_scoped','audits/adversarial_reviews/uniform99_fixed_sequence_adjudication.md','{"id": "LEM-HLZ-REFLECTED-EDGE-FIXED-SEQUENCE", "paper_id": null, "locator": "audits/adversarial_reviews/uniform99_fixed_sequence_adjudication.md · Differentiation and the original-modulus average; Reduction to the single Mangoldt convolution", "evidence": "audits/adversarial_reviews/uniform99_fixed_sequence_adjudication.md", "statement": "The three differentiated reflected shifts give A(m)+log(k/m)(log*log)(m), with A=d_2*Lambda*Lambda*Lambda. The original-modulus unit average of e(−m/k) is mu(q)/phi(q), q=k/(k,m). The divisor products decay faster than any fixed power for the smooth cutoff; the remaining edge is (1/2) E_Cstar+O_N(T^−N), where Cstar=d_2*(Lambda log²).", "hypotheses": "Compact-local smooth contour formulation, k≤y≤T^theta, H=T^kappa with kappa>(1+theta)/2, bounded outer coefficients. Divisor removal is unconditional via Poisson or Hurwitz–Mellin cancellation. Arbitrary decay applies to discarded divisor pieces; inherited contour errors keep their separate bounds.", "claim_kind": "proved_fixed_arithmetic_sequence_reduction", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'The three differentiated reflected shifts give A(m)+log(k/m)(log*log)(m), with A=d_2*Lambda*Lambda*Lambda. The original-modulus unit average of e(−m/k) is mu(q)/phi(q), q=k/(k,m). The divisor products decay faster than any fixed power for the smooth cutoff; the remaining edge is (1/2) E_Cstar+O_N(T^−N), where Cstar=d_2*(Lambda log²).','proved_fixed_arithmetic_sequence_reduction','audits/adversarial_reviews/uniform99_fixed_sequence_adjudication.md · Differentiation and the original-modulus average; Reduction to the single Mangoldt convolution','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('OPEN-HLZ-PURE-FOURTH-CSTAR-CANCELLATION','theorems/theorems.jsonl',338,'open_sufficient_target','audits/adversarial_reviews/uniform99_fixed_sequence_adjudication.md','{"id": "OPEN-HLZ-PURE-FOURTH-CSTAR-CANCELLATION", "paper_id": null, "locator": "audits/adversarial_reviews/uniform99_fixed_sequence_adjudication.md · Reduction to the single Mangoldt convolution", "evidence": "audits/adversarial_reviews/uniform99_fixed_sequence_adjudication.md", "statement": "The remaining sufficient target is Re E_Cstar=o(T log⁴T), with E_Cstar=∑_{k≤Y^(4b)} (c_k/k)∑_m Cstar(m) w_T(2πm/k)[e(−m/k)−mu(q)/phi(q)], q=k/(k,m), and c_k the coefficients of D⁴.", "hypotheses": "Compact comparable heights T approximately Y, fixed 1/8<b<1/6 and the same two-transition taper and principal subtraction. The target is unproved. RH and the established compact-to-strict-tail comparison would transfer a proof to the pure and real fourth moments.", "claim_kind": "open_arithmetic_sufficient_condition", "status": "open_sufficient_target", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'The remaining sufficient target is Re E_Cstar=o(T log⁴T), with E_Cstar=∑_{k≤Y^(4b)} (c_k/k)∑_m Cstar(m) w_T(2πm/k)[e(−m/k)−mu(q)/phi(q)], q=k/(k,m), and c_k the coefficients of D⁴.','open_arithmetic_sufficient_condition','audits/adversarial_reviews/uniform99_fixed_sequence_adjudication.md · Reduction to the single Mangoldt convolution','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('THM-GR1974-GRR-MODULUS','theorems/theorems.jsonl',339,'adjudicated_scoped','audits/adversarial_reviews/release92_tightness_source_selection.md','{"id": "THM-GR1974-GRR-MODULUS", "paper_id": "PAPER-U89-GARSIA-RODEMICH-REARRANGEMENT", "locator": "audits/adversarial_reviews/release92_tightness_source_selection.md · Garsia and Rodemich; 1974 journal pp. 69–70, Theorem 1.2 and (1.2), (1.3), (1.7), (1.8)", "evidence": "audits/adversarial_reviews/release92_tightness_source_selection.md", "statement": "The reproduced GRR inequality bounds continuous-path increments in its power case by a constant times B^(1/p) ∫_0^h u^(−2/p)dg(u), with B the double energy in the director note.", "hypotheses": "Continuous interpolation, increasing continuous gauge, finite energy, convergent scale integral. The source almost-everywhere estimate extends to a continuous path. Targeted primary passage; the 1974 article credits the three-author original.", "claim_kind": "targeted_primary_source_dependency", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}','PAPER-U89-GARSIA-RODEMICH-REARRANGEMENT','The reproduced GRR inequality bounds continuous-path increments in its power case by a constant times B^(1/p) ∫_0^h u^(−2/p)dg(u), with B the double energy in the director note.','targeted_primary_source_dependency','audits/adversarial_reviews/release92_tightness_source_selection.md · Garsia and Rodemich; 1974 journal pp. 69–70, Theorem 1.2 and (1.2), (1.3), (1.7), (1.8)','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('THM-BILLINGSLEY1968-C-TIGHTNESS-AND-TRIANGLE','theorems/theorems.jsonl',340,'adjudicated_scoped','audits/adversarial_reviews/release92_tightness_source_selection.md','{"id": "THM-BILLINGSLEY1968-C-TIGHTNESS-AND-TRIANGLE", "paper_id": "PAPER-U89-BILLINGSLEY-CONVERGENCE-1968", "locator": "audits/adversarial_reviews/release92_tightness_source_selection.md · Billingsley; first edition Theorem 8.2 p. 55, Theorem 12.3 pp. 95–96 and §12 Problem 9 p. 103", "evidence": "audits/adversarial_reviews/release92_tightness_source_selection.md", "statement": "Tight initial values and asymptotically small modulus probabilities characterize tightness in C. The common-clock sufficient criterion requires a time exponent greater than one; a randomly located shrinking triangle demonstrates failure at the critical exponent.", "hypotheses": "First-edition scanned passages only. Both the arbitrary-grid minimum envelope and its sharpness at a variable crossover are local adaptations.", "claim_kind": "targeted_primary_source_dependency", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}','PAPER-U89-BILLINGSLEY-CONVERGENCE-1968','Tight initial values and asymptotically small modulus probabilities characterize tightness in C. The common-clock sufficient criterion requires a time exponent greater than one; a randomly located shrinking triangle demonstrates failure at the critical exponent.','targeted_primary_source_dependency','audits/adversarial_reviews/release92_tightness_source_selection.md · Billingsley; first edition Theorem 8.2 p. 55, Theorem 12.3 pp. 95–96 and §12 Problem 9 p. 103','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-PETROV-ROOTED-CUE-EXACT-FACTOR-BRIDGE','theorems/theorems.jsonl',341,'adjudicated_scoped','audits/adversarial_reviews/director_petrov_round13.md','{"id": "LEM-PETROV-ROOTED-CUE-EXACT-FACTOR-BRIDGE", "paper_id": null, "locator": "audits/adversarial_reviews/director_petrov_round13.md · Applicable source theorem and exact matching", "evidence": "audits/adversarial_reviews/director_petrov_round13.md", "statement": "Petrov v1 Theorem 4.4, ordinary BOGC and finite Jacobi give det(U* A_n^−1 U)=(det Gamma/det Gamma(0)) L_obl/L_n for the rooted CUE cosine symbol. On the real Laplace axis both exact Gram and oblique tail determinants are strictly positive at every fixed N,z.", "hypotheses": "Fixed integers N≥2 and J≥1, analytic polynomial tilts X=T((1−w)^J) on N−1 free modes and exponential finite Laurent symbol. The source theorem requires its Gram to be invertible; real z gives the adjoint structure. The optional fixed-tail chart requires separate invertibility.", "claim_kind": "intrinsic_exact_source_theorem_transfer", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'Petrov v1 Theorem 4.4, ordinary BOGC and finite Jacobi give det(U* A_n^−1 U)=(det Gamma/det Gamma(0)) L_obl/L_n for the rooted CUE cosine symbol. On the real Laplace axis both exact Gram and oblique tail determinants are strictly positive at every fixed N,z.','intrinsic_exact_source_theorem_transfer','audits/adversarial_reviews/director_petrov_round13.md · Applicable source theorem and exact matching','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-PETROV-ROOTED-CUE-GRAM-QUADRATIC-MISMATCH','theorems/theorems.jsonl',342,'adjudicated_scoped','experiments/results/director_petrov_quadratic_round13.json','{"id": "OBS-PETROV-ROOTED-CUE-GRAM-QUADRATIC-MISMATCH", "paper_id": null, "locator": "audits/adversarial_reviews/director_petrov_round13.md · The tail contributes already at order two; Exact finite witness and optional chart", "evidence": "experiments/results/director_petrov_quadratic_round13.json", "statement": "The tilted tail contributes −kappa_(J,N) z² with kappa_(J,N)=Σ_(j<J)||H(F_+)*U_j||²>0. If 2 max(band)≤n and the band is nonempty, the normalized Gram already differs from the complementary determinant at order two. For N=4,J=2,k=2 the gap is 9/160; the optional chart determinant changes sign between z=0 and 8 while the exact factors remain positive.", "hypotheses": "Same fixed-rank cosine model. The ordinary ambient tail is stable in the stated coefficient window. For fixed 0<a<b≤1/2 the quadratic gap has the positive Riemann-sum limit in the note. The chart obstruction is separate from the zero of the extrapolated formal moment polynomial.", "claim_kind": "intrinsic_quadratic_nonidentification_and_chart_witness", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round13_claims.jsonl"}',NULL,'The tilted tail contributes −kappa_(J,N) z² with kappa_(J,N)=Σ_(j<J)||H(F_+)*U_j||²>0. If 2 max(band)≤n and the band is nonempty, the normalized Gram already differs from the complementary determinant at order two. For N=4,J=2,k=2 the gap is 9/160; the optional chart determinant changes sign between z=0 and 8 while the exact factors remain positive.','intrinsic_quadratic_nonidentification_and_chart_witness','audits/adversarial_reviews/director_petrov_round13.md · The tail contributes already at order two; Exact finite witness and optional chart','theorems/research_round13_claims.jsonl');
INSERT INTO "claims" VALUES('THM-ROOTED-CUE-HANKEL-WITNESS-DEGREE-BOUND','theorems/theorems.jsonl',343,'adjudicated_scoped','audits/adversarial_reviews/director_quantitative_rmt_round14.md','{"id": "THM-ROOTED-CUE-HANKEL-WITNESS-DEGREE-BOUND", "paper_id": null, "locator": "audits/adversarial_reviews/director_quantitative_rmt_round14.md · A quantitative finite witness for every fixed rank", "evidence": "audits/adversarial_reviews/director_quantitative_rmt_round14.md", "statement": "For the formal fixed-rank cosine series M and a real zero 0<t_*≤1/d, let R=2/d and B≥1 majorize |M| on |z|=R. With L=ceil(log_2(8B(B+1))), the two degree-L Taylor polynomials of exp(±t_*x/2) give a strictly negative two-by-two moment determinant. The order-L Hankel form is therefore not positive semidefinite, using moments through degree 2L. A sufficient explicit majorant is B=J! D^J exp((J−1)HR+HR²/4), D=(2J−1)16^(2J−2)(2J−1)! exp(1+R d exp(b)).", "hypotheses": "Fixed positive integer rank J and 0<a<b<1, H=log(b/a), d=b−a. The form is for the extrapolated cosine series. The bound is sufficient, not generally the least witness order.", "claim_kind": "intrinsic_quantitative_formal_positivity_obstruction", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round14_claims.jsonl"}',NULL,'For the formal fixed-rank cosine series M and a real zero 0<t_*≤1/d, let R=2/d and B≥1 majorize |M| on |z|=R. With L=ceil(log_2(8B(B+1))), the two degree-L Taylor polynomials of exp(±t_*x/2) give a strictly negative two-by-two moment determinant. The order-L Hankel form is therefore not positive semidefinite, using moments through degree 2L. A sufficient explicit majorant is B=J! D^J exp((J−1)HR+HR²/4), D=(2J−1)16^(2J−2)(2J−1)! exp(1+R d exp(b)).','intrinsic_quantitative_formal_positivity_obstruction','audits/adversarial_reviews/director_quantitative_rmt_round14.md · A quantitative finite witness for every fixed rank','theorems/research_round14_claims.jsonl');
INSERT INTO "claims" VALUES('THM-ROOTED-CUE-RANK-ONE-HERMITE-WITNESS','theorems/theorems.jsonl',344,'adjudicated_scoped','audits/adversarial_reviews/director_quantitative_rmt_round14.md','{"id": "THM-ROOTED-CUE-RANK-ONE-HERMITE-WITNESS", "paper_id": null, "locator": "audits/adversarial_reviews/director_quantitative_rmt_round14.md · At rank one the least order is known exactly", "evidence": "audits/adversarial_reviews/director_quantitative_rmt_round14.md", "statement": "At rank one set σ²=H/2. The order-L formal Hankel form is congruent to I−(d/σ²)T_L, with Hermite Jacobi edges σ sqrt(k), 1≤k≤L. A negative witness exists exactly when the largest zero of He_(L+1) strictly exceeds σ/d. Equality gives singular positive semidefiniteness. The least order lies above σ²/(4d²) and at most floor(σ²/d²)+1; it is σ²/(4d²)+O(σ/d) as σ/d→infinity.", "hypotheses": "Fixed positive band at rank one, with the formal Gaussian density modifier 1−d x/σ². He denotes the probabilists'' Hermite polynomial. The asymptotic concerns small d/σ, and the criterion does not test the true law outside the supported moment window.", "claim_kind": "intrinsic_exact_rank_one_formal_witness_degree", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round14_claims.jsonl"}',NULL,'At rank one set σ²=H/2. The order-L formal Hankel form is congruent to I−(d/σ²)T_L, with Hermite Jacobi edges σ sqrt(k), 1≤k≤L. A negative witness exists exactly when the largest zero of He_(L+1) strictly exceeds σ/d. Equality gives singular positive semidefiniteness. The least order lies above σ²/(4d²) and at most floor(σ²/d²)+1; it is σ²/(4d²)+O(σ/d) as σ/d→infinity.','intrinsic_exact_rank_one_formal_witness_degree','audits/adversarial_reviews/director_quantitative_rmt_round14.md · At rank one the least order is known exactly','theorems/research_round14_claims.jsonl');
INSERT INTO "claims" VALUES('CERT-ROOTED-CUE-RANK-ONE-HANKEL-FIXTURES','theorems/theorems.jsonl',345,'adjudicated_scoped','experiments/results/geometry111_rankone_hankel_certificate.json','{"id": "CERT-ROOTED-CUE-RANK-ONE-HANKEL-FIXTURES", "paper_id": null, "locator": "audits/adversarial_reviews/director_quantitative_rmt_round14.md · At rank one the least order is known exactly", "evidence": "experiments/results/geometry111_rankone_hankel_certificate.json", "statement": "For the standardized series exp(z²/2)(1−z/2), all principal minors through Hankel order two are nonnegative and q(x)=2x³+9x²+6x−3 has formal square expectation −30. At standardized tilt 1/sqrt(3), after rescaling y=sqrt(3)x, the order-two form is singular positive semidefinite, y²+3y is null, and y³+4y²+12y has square expectation −27.", "hypotheses": "Exact rational formal-moment fixtures with director replay. They check the strict Hermite threshold and are separate from the general degree proof.", "claim_kind": "exact_rank_one_hankel_certificate", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round14_claims.jsonl"}',NULL,'For the standardized series exp(z²/2)(1−z/2), all principal minors through Hankel order two are nonnegative and q(x)=2x³+9x²+6x−3 has formal square expectation −30. At standardized tilt 1/sqrt(3), after rescaling y=sqrt(3)x, the order-two form is singular positive semidefinite, y²+3y is null, and y³+4y²+12y has square expectation −27.','exact_rank_one_hankel_certificate','audits/adversarial_reviews/director_quantitative_rmt_round14.md · At rank one the least order is known exactly','theorems/research_round14_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-PETROV-ROOTED-CUE-FINITE-SCHUR-TAIL','theorems/theorems.jsonl',346,'adjudicated_scoped','audits/adversarial_reviews/director_quantitative_rmt_round14.md','{"id": "LEM-PETROV-ROOTED-CUE-FINITE-SCHUR-TAIL", "paper_id": null, "locator": "audits/adversarial_reviews/director_quantitative_rmt_round14.md · The exact Petrov tail quotient has a positive finite representation", "evidence": "audits/adversarial_reviews/director_quantitative_rmt_round14.md", "statement": "With L=P_nT(φ_+)|P_n, M=U*L^(−*)L^(−1)U and A_n=P_nT(φ)|P_n, the tilted-to-ambient Fredholm ratio is det S, S=M^(−1/2)(U*A_n^(−1)U)M^(−1/2), and det Γ(z)/det Γ(0)=det M. For real z the ratio is in [exp(−H_N z²/4),1]; det M and det(U*A_n^(−1)U) lie in [exp(−J|z|H_N),exp(J|z|H_N)]. The mass-removed complementary determinant has liminf at least exp(−2JH z_*) at any positive formal zero z_*.", "hypotheses": "Fixed N≥2 and deleted rank J≥1, n=N+J−1, global rooted cosine CUE model, real z, fixed positive band for uniformity in N. No invertibility of Petrov''s optional fixed-tail chart is needed.", "claim_kind": "intrinsic_exact_real_tail_quotient_and_nonvanishing", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-GEOMETRY102-PETROV2026"], "provenance_file": "theorems/research_round14_claims.jsonl"}',NULL,'With L=P_nT(φ_+)|P_n, M=U*L^(−*)L^(−1)U and A_n=P_nT(φ)|P_n, the tilted-to-ambient Fredholm ratio is det S, S=M^(−1/2)(U*A_n^(−1)U)M^(−1/2), and det Γ(z)/det Γ(0)=det M. For real z the ratio is in [exp(−H_N z²/4),1]; det M and det(U*A_n^(−1)U) lie in [exp(−J|z|H_N),exp(J|z|H_N)]. The mass-removed complementary determinant has liminf at least exp(−2JH z_*) at any positive formal zero z_*.','intrinsic_exact_real_tail_quotient_and_nonvanishing','audits/adversarial_reviews/director_quantitative_rmt_round14.md · The exact Petrov tail quotient has a positive finite representation','theorems/research_round14_claims.jsonl');
INSERT INTO "claims" VALUES('THM-PETROV-ROOTED-CUE-TRUE-CUTOFF-CONTINUUM-GRAM','theorems/theorems.jsonl',347,'adjudicated_scoped','audits/adversarial_reviews/director_quantitative_rmt_round14.md','{"id": "THM-PETROV-ROOTED-CUE-TRUE-CUTOFF-CONTINUUM-GRAM", "paper_id": null, "locator": "audits/adversarial_reviews/director_quantitative_rmt_round14.md · A true-cutoff continuum Gram and a factorial approximation", "evidence": "audits/adversarial_reviews/director_quantitative_rmt_round14.md", "statement": "For real z≥0, e^(−H_N z)M_ij converges to E[1_(max(p,q)≤1) ∫_(max(p,q))^1 u_i(t−p)u_j(t−q)dt], with independent compound-Poisson shift totals p,q of intensity z dx/(2x) on [a,b] and shifted orthonormal Legendre profiles u_j. For p,q≤1 its kernel differs from the transposed oriented formal kernel by an ordinary lower interval of length min(p,q).", "hypotheses": "Fixed rank and 0<a<b<1. Exact Gram limit with the finite convolution cutoff. Pure-sign agreement is within the coefficient window; the formal extrapolation can use unsupported shifts.", "claim_kind": "intrinsic_true_cutoff_continuum_limit", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-GEOMETRY102-PETROV2026"], "provenance_file": "theorems/research_round14_claims.jsonl"}',NULL,'For real z≥0, e^(−H_N z)M_ij converges to E[1_(max(p,q)≤1) ∫_(max(p,q))^1 u_i(t−p)u_j(t−q)dt], with independent compound-Poisson shift totals p,q of intensity z dx/(2x) on [a,b] and shifted orthonormal Legendre profiles u_j. For p,q≤1 its kernel differs from the transposed oriented formal kernel by an ordinary lower interval of length min(p,q).','intrinsic_true_cutoff_continuum_limit','audits/adversarial_reviews/director_quantitative_rmt_round14.md · A true-cutoff continuum Gram and a factorial approximation','theorems/research_round14_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-PETROV-ROOTED-CUE-FACTORIAL-HANKEL-TRUNCATION','theorems/theorems.jsonl',348,'adjudicated_scoped','audits/adversarial_reviews/director_quantitative_rmt_round14.md','{"id": "LEM-PETROV-ROOTED-CUE-FACTORIAL-HANKEL-TRUNCATION", "paper_id": null, "locator": "audits/adversarial_reviews/director_quantitative_rmt_round14.md · A true-cutoff continuum Gram and a factorial approximation", "evidence": "audits/adversarial_reviews/director_quantitative_rmt_round14.md", "statement": "For h=H(φ_−/φ_+), the Hilbert–Schmidt error after cutting both indices at M_cut≥n is at most |z|sqrt(H_N/2) times ∑_(s≥floor(M_cut/k_*)) (|z|H_N)^s/s!, where k_* is the maximum band index. Schatten Hölder bounds the induced trace-norm K error, and the log-determinant quotient error is at most twice that error divided by exp(−2|z|H_N).", "hypotheses": "Fixed positive band, fixed deleted rank, real z in a compact interval. A nonempty finite band is required for k_*; an empty band has K=0 and both tails equal one.", "claim_kind": "intrinsic_uniform_finite_tail_approximation", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-GEOMETRY102-PETROV2026"], "provenance_file": "theorems/research_round14_claims.jsonl"}',NULL,'For h=H(φ_−/φ_+), the Hilbert–Schmidt error after cutting both indices at M_cut≥n is at most |z|sqrt(H_N/2) times ∑_(s≥floor(M_cut/k_*)) (|z|H_N)^s/s!, where k_* is the maximum band index. Schatten Hölder bounds the induced trace-norm K error, and the log-determinant quotient error is at most twice that error divided by exp(−2|z|H_N).','intrinsic_uniform_finite_tail_approximation','audits/adversarial_reviews/director_quantitative_rmt_round14.md · A true-cutoff continuum Gram and a factorial approximation','theorems/research_round14_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-CSTAR-EFFECTIVE-MODULUS-AND-SHORT-FACTOR','theorems/theorems.jsonl',349,'adjudicated_scoped','audits/adversarial_reviews/director_arithmetic_strata_round14.md','{"id": "LEM-CSTAR-EFFECTIVE-MODULUS-AND-SHORT-FACTOR", "paper_id": null, "locator": "audits/adversarial_reviews/director_arithmetic_strata_round14.md · Exact effective modulus and removal of several strata", "evidence": "audits/adversarial_reviews/director_arithmetic_strata_round14.md", "statement": "For fixed Mangoldt factor ν, put g=(k,ν), q=k/g, M=kT/ν and δ=H/T. The centered divisor twist reduces exactly to a unit numerator at q and vanishes when q=1. It is bounded by O_B(M log(2+M)(1+Hg/√(kTν))^(−B)) and O_B(q δ^(−2)(q²/(Mδ²))^B). Thus ν/g²≤(H²/(kT))T^(−δ_0) can be discarded with arbitrary fixed-power savings for a fixed positive margin δ_0.", "hypotheses": "Compact comparable-height cutoff with derivative bounds, T≈Y, k≤Y^θ, H=T^κ and fixed κ>(1+θ)/2 for the short-factor claim. The weak pointwise loss O_ε(qT^ε) requires choosing κ close to one and then a small positive B. The divisor argument n need not be coprime to q.", "claim_kind": "unconditional_centered_divisor_transform_and_short_factor", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round14_claims.jsonl"}',NULL,'For fixed Mangoldt factor ν, put g=(k,ν), q=k/g, M=kT/ν and δ=H/T. The centered divisor twist reduces exactly to a unit numerator at q and vanishes when q=1. It is bounded by O_B(M log(2+M)(1+Hg/√(kTν))^(−B)) and O_B(q δ^(−2)(q²/(Mδ²))^B). Thus ν/g²≤(H²/(kT))T^(−δ_0) can be discarded with arbitrary fixed-power savings for a fixed positive margin δ_0.','unconditional_centered_divisor_transform_and_short_factor','audits/adversarial_reviews/director_arithmetic_strata_round14.md · Exact effective modulus and removal of several strata','theorems/research_round14_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-CSTAR-SHARED-FACTORS-AND-HIGHER-POWERS','theorems/theorems.jsonl',350,'adjudicated_scoped','audits/adversarial_reviews/director_arithmetic_strata_round14.md','{"id": "LEM-CSTAR-SHARED-FACTORS-AND-HIGHER-POWERS", "paper_id": null, "locator": "audits/adversarial_reviews/director_arithmetic_strata_round14.md · Exact effective modulus and removal of several strata", "evidence": "audits/adversarial_reviews/director_arithmetic_strata_round14.md", "statement": "All supported prime powers sharing a prime with the modulus contribute o(T). All powers p^j with j≥3 contribute O(Y^θ T^(1/3+ε) log^C T), hence o(T) for θ<2/3 with fixed power margin and sufficiently small ε.", "hypotheses": "The fixed d₂*(Λ log²) smooth signed sum, four-prime-supported bounded outer coefficients c_k, T≈Y, fixed 0<a<b, θ=4b∈(1/2,2/3). The taper exponent is chosen sufficiently near one. This is an unconditional estimate for these arithmetic strata.", "claim_kind": "unconditional_partial_prime_power_elimination", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round14_claims.jsonl"}',NULL,'All supported prime powers sharing a prime with the modulus contribute o(T). All powers p^j with j≥3 contribute O(Y^θ T^(1/3+ε) log^C T), hence o(T) for θ<2/3 with fixed power margin and sufficiently small ε.','unconditional_partial_prime_power_elimination','audits/adversarial_reviews/director_arithmetic_strata_round14.md · Exact effective modulus and removal of several strata','theorems/research_round14_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-CSTAR-ALL-PRIME-SQUARES-BELOW-9-17','theorems/theorems.jsonl',351,'adjudicated_scoped','audits/adversarial_reviews/director_arithmetic_strata_round14.md','{"id": "LEM-CSTAR-ALL-PRIME-SQUARES-BELOW-9-17", "paper_id": null, "locator": "audits/adversarial_reviews/director_arithmetic_strata_round14.md · Ghosh''s primary quadratic estimate removes every square in a strict range", "evidence": "audits/adversarial_reviews/director_arithmetic_strata_round14.md", "statement": "At k≈K and square base p≈X the reduced quadratic numerator estimate, weighted over gcd classes, costs O(T^ε(KT/X)[K^(−1/4)+X^(−1/8)+K^(1/4)X^(−1/2)]). Combined with small-X pointwise control it gives a power saving for all square factors when 1/2<θ<9/17, equivalently 1/8<b<9/68.", "hypotheses": "Same compact signed sum and bounded four-prime coefficients. Ghosh''s thesis Theorem 2 on exact reduced rational phases, two monotone taper transitions and fixed strict power margins. The endpoint and the genuine-prime stratum are outside this estimate.", "claim_kind": "unconditional_all_square_stratum_power_saving", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-WEIGHTED107-GHOSH-THESIS1981", "PAPER-WEIGHTED107-REN2005"], "provenance_file": "theorems/research_round14_claims.jsonl"}',NULL,'At k≈K and square base p≈X the reduced quadratic numerator estimate, weighted over gcd classes, costs O(T^ε(KT/X)[K^(−1/4)+X^(−1/8)+K^(1/4)X^(−1/2)]). Combined with small-X pointwise control it gives a power saving for all square factors when 1/2<θ<9/17, equivalently 1/8<b<9/68.','unconditional_all_square_stratum_power_saving','audits/adversarial_reviews/director_arithmetic_strata_round14.md · Ghosh''s primary quadratic estimate removes every square in a strict range','theorems/research_round14_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-CSTAR-GCD-RESOLVED-INVERSE-PRIME-WINDOWS','theorems/theorems.jsonl',352,'adjudicated_scoped','audits/adversarial_reviews/director_arithmetic_strata_round14.md','{"id": "LEM-CSTAR-GCD-RESOLVED-INVERSE-PRIME-WINDOWS", "paper_id": null, "locator": "audits/adversarial_reviews/director_arithmetic_strata_round14.md · Divisor Voronoi and averaged inverse-prime bounds", "evidence": "audits/adversarial_reviews/director_arithmetic_strata_round14.md", "statement": "For K≈T^θ and P≈T^ξ, the coprime genuine-prime block saves a power in either open region: Baker θ/2<ξ<θ, (11/10)θ+(4/5)ξ<1 and θ+(11/12)ξ<1; Fouvry–Shparlinski 0<ξ<(3/2)θ, (13/10)θ+(3/5)ξ<1 and (13/12)θ+(5/6)ξ<1. Centered divisor Voronoi and a uniform O(T^ε δ^(−5/2)) cumulative kernel-and-first-derivative envelope permit full dual gcd resolution.", "hypotheses": "1/2<θ<2/3 on the stated dyadic scales. Use averages at common prime endpoints and reduce each nonunit dual index to modulus k/gcd(k,l). No least-prime-factor restriction on these gcd estimates. Choose the taper exponent sufficiently near one on compact subsets of the strict regions. The longer-prime scales remain outside them.", "claim_kind": "unconditional_gcd_resolved_inverse_prime_savings", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-R112-BAKER2012", "PAPER-R114-FOUVRY-SHPARLINSKI2011", "PAPER-R112-BHM2007"], "provenance_file": "theorems/research_round14_claims.jsonl"}',NULL,'For K≈T^θ and P≈T^ξ, the coprime genuine-prime block saves a power in either open region: Baker θ/2<ξ<θ, (11/10)θ+(4/5)ξ<1 and θ+(11/12)ξ<1; Fouvry–Shparlinski 0<ξ<(3/2)θ, (13/10)θ+(3/5)ξ<1 and (13/12)θ+(5/6)ξ<1. Centered divisor Voronoi and a uniform O(T^ε δ^(−5/2)) cumulative kernel-and-first-derivative envelope permit full dual gcd resolution.','unconditional_gcd_resolved_inverse_prime_savings','audits/adversarial_reviews/director_arithmetic_strata_round14.md · Divisor Voronoi and averaged inverse-prime bounds','theorems/research_round14_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-CSTAR-KOROLEV-POINTWISE-INVERSE-PRIME-BAND','theorems/theorems.jsonl',353,'adjudicated_scoped','audits/adversarial_reviews/director_arithmetic_strata_round14.md','{"id": "LEM-CSTAR-KOROLEV-POINTWISE-INVERSE-PRIME-BAND", "paper_id": null, "locator": "audits/adversarial_reviews/director_arithmetic_strata_round14.md · An alternate inverse-prime input and an excluded shortcut", "evidence": "audits/adversarial_reviews/director_arithmetic_strata_round14.md", "statement": "The 2018 homogeneous Korolev unit-numerator prefix estimate and common short dual truncation give a power saving near P=T^(1−θ) on K≈T^θ for 1/2<θ<10/17; the principal inverse-prime exponent at the center is (64+17θ)/74 before the small taper and interval losses.", "hypotheses": "Original homogeneous theorem range q^(7/10+ε)≤X≤q, fixed strict margins, supported modulus primes above Y^a and common dual truncation below Y^a. Prime partial summation adds one vertical factor and changes the cutoff cost to δ^(−3−2B). The later inhomogeneous theorem with two unit coefficients is a different result.", "claim_kind": "unconditional_alternate_local_inverse_prime_saving", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-WEIGHTED107-KOROLEV2018"], "provenance_file": "theorems/research_round14_claims.jsonl"}',NULL,'The 2018 homogeneous Korolev unit-numerator prefix estimate and common short dual truncation give a power saving near P=T^(1−θ) on K≈T^θ for 1/2<θ<10/17; the principal inverse-prime exponent at the center is (64+17θ)/74 before the small taper and interval losses.','unconditional_alternate_local_inverse_prime_saving','audits/adversarial_reviews/director_arithmetic_strata_round14.md · An alternate inverse-prime input and an excluded shortcut','theorems/research_round14_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-CSTAR-CHARACTER-TWIST-ZERO-RESIDUES','theorems/theorems.jsonl',354,'adjudicated_scoped','audits/adversarial_reviews/director_arithmetic_strata_round14.md','{"id": "OBS-CSTAR-CHARACTER-TWIST-ZERO-RESIDUES", "paper_id": null, "locator": "audits/adversarial_reviews/director_arithmetic_strata_round14.md · An alternate inverse-prime input and an excluded shortcut", "evidence": "audits/adversarial_reviews/director_arithmetic_strata_round14.md", "statement": "The character twist of d₂*(Λ log²) is L(s,χ)²(−L''/L)'''' in absolute convergence. At a simple zero ρ it has residue −2L''(ρ,χ)²; at a zero of order at least two there is no pole. Hence a contour move treating the full twist as an ordinary divisor/Eisenstein twist would omit these zero residues.", "hypotheses": "Ordinary Dirichlet characters with their Euler factors. The statement concerns the indicated meromorphic continuation and poles at zeros, not a bound on their residue sum. Freezing the prime factor gives a different, valid divisor transform. No Dirichlet GRH is assumed.", "claim_kind": "meromorphic_obstruction_to_full_sequence_divisor_transform", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round14_claims.jsonl"}',NULL,'The character twist of d₂*(Λ log²) is L(s,χ)²(−L''/L)'''' in absolute convergence. At a simple zero ρ it has residue −2L''(ρ,χ)²; at a zero of order at least two there is no pole. Hence a contour move treating the full twist as an ordinary divisor/Eisenstein twist would omit these zero residues.','meromorphic_obstruction_to_full_sequence_divisor_transform','audits/adversarial_reviews/director_arithmetic_strata_round14.md · An alternate inverse-prime input and an excluded shortcut','theorems/research_round14_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-BL-RAW-HEIGHT-SMOOTH-COUNTEREXAMPLE','theorems/theorems.jsonl',355,'adjudicated_scoped','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md','{"id": "OBS-BL-RAW-HEIGHT-SMOOTH-COUNTEREXAMPLE", "paper_id": null, "locator": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A fixed smooth witness for which the stated height limit fails", "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md", "statement": "There exists a fixed smooth real f satisfying the pinned manuscript''s literal endpoint and local hypotheses whose zero sum fails under symmetric raw-height cutoffs. Disjoint log-coordinate bumps with amplitudes a_j=exp(−(1/2+δ)j), b_j=exp(−(1+δ)j), and separated high-frequency carriers produce symmetric height increments exceeding 2j/5. The arithmetic side has ordinary absolute convergence.", "hypotheses": "Nontrivial zeta zeros with multiplicity, actual unaveraged cutoffs |Im ρ|≤T, and the auxiliary formula on pinned manuscript pp. 5–6. Uses the unconditional zero count in populated high cells. The compact jump tests in the main theorem have a separate justification.", "claim_kind": "intrinsic_smooth_raw_height_counterexample", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-L002"], "provenance_file": "theorems/research_round15_claims.jsonl"}',NULL,'There exists a fixed smooth real f satisfying the pinned manuscript''s literal endpoint and local hypotheses whose zero sum fails under symmetric raw-height cutoffs. Disjoint log-coordinate bumps with amplitudes a_j=exp(−(1/2+δ)j), b_j=exp(−(1+δ)j), and separated high-frequency carriers produce symmetric height increments exceeding 2j/5. The arithmetic side has ordinary absolute convergence.','intrinsic_smooth_raw_height_counterexample','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A fixed smooth witness for which the stated height limit fails','theorems/research_round15_claims.jsonl');
INSERT INTO "claims" VALUES('THM-MELLIN-STRIP-SOBOLEV-ZERO-TRACE','theorems/theorems.jsonl',356,'adjudicated_scoped','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md','{"id": "THM-MELLIN-STRIP-SOBOLEV-ZERO-TRACE", "paper_id": null, "locator": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A sufficient strip-Sobolev condition", "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md", "statement": "For h(s)=∫₀∞ f(x)x^(s−1)dx and N_s² the strip area integral of |h(β+it)|²(1+t²)^s, the zero trace is absolutely summable. With r=min(ε/2,1/4), its ℓ¹ bound is C_N/(√π r) times [2·5^s Σ_n log²(2+|n|)/(1+n²)^s]^(1/2) N_s. Restricting the series to |n|>T−1 gives tail O(N_s T^(1/2−s) log(2+T)). The compensated explicit formula follows by compact smooth approximation, with automatic central trace control.", "hypotheses": "Continuous f with the original endpoint value bounds at margin δ>0, 0<ε<δ, finite norm on β∈[−ε,1+ε], s>1/2. C_N bounds the number of zeta zeros with n≤Im ρ<n+1 by C_N log(2+|n|), including multiplicities.", "claim_kind": "sufficient_absolute_zero_trace_and_explicit_formula", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-L002"], "provenance_file": "theorems/research_round15_claims.jsonl"}',NULL,'For h(s)=∫₀∞ f(x)x^(s−1)dx and N_s² the strip area integral of |h(β+it)|²(1+t²)^s, the zero trace is absolutely summable. With r=min(ε/2,1/4), its ℓ¹ bound is C_N/(√π r) times [2·5^s Σ_n log²(2+|n|)/(1+n²)^s]^(1/2) N_s. Restricting the series to |n|>T−1 gives tail O(N_s T^(1/2−s) log(2+T)). The compensated explicit formula follows by compact smooth approximation, with automatic central trace control.','sufficient_absolute_zero_trace_and_explicit_formula','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A sufficient strip-Sobolev condition','theorems/research_round15_claims.jsonl');
INSERT INTO "claims" VALUES('THM-MELLIN-CRITICAL-LOG-ZERO-TRACE','theorems/theorems.jsonl',357,'adjudicated_scoped','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md','{"id": "THM-MELLIN-CRITICAL-LOG-ZERO-TRACE", "paper_id": null, "locator": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A weaker critical logarithmic class", "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md", "statement": "Replacing the strip weight by w_p(t)=√(1+t²) log^p(e+|t|) gives an absolute zero trace, with tail O(N_log,p [log(2+T)]^((3−p)/2)). Fourier inversion on the central line gives the Dini modulus O(N_log,p [log(e/|u|)]^((1−p)/2)) near u=0. Approximation establishes the same compensated explicit formula.", "hypotheses": "Continuous f with the original endpoint value bounds, strip margin 0<ε<δ, and finite area norm with p>3. The endpoint claim separately addresses failure of universal absolute sampling at p=3.", "claim_kind": "sufficient_critical_logarithmic_zero_trace_and_explicit_formula", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-L002"], "provenance_file": "theorems/research_round15_claims.jsonl"}',NULL,'Replacing the strip weight by w_p(t)=√(1+t²) log^p(e+|t|) gives an absolute zero trace, with tail O(N_log,p [log(2+T)]^((3−p)/2)). Fourier inversion on the central line gives the Dini modulus O(N_log,p [log(e/|u|)]^((1−p)/2)) near u=0. Approximation establishes the same compensated explicit formula.','sufficient_critical_logarithmic_zero_trace_and_explicit_formula','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A weaker critical logarithmic class','theorems/research_round15_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-MELLIN-CRITICAL-LOG-SMOOTH-STRICT-INCLUSION','theorems/theorems.jsonl',358,'adjudicated_scoped','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md','{"id": "OBS-MELLIN-CRITICAL-LOG-SMOOTH-STRICT-INCLUSION", "paper_id": null, "locator": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A weaker critical logarithmic class", "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md", "statement": "For each p>3 a smooth real example lies in the critical-log strip class and in none of the polynomial strip classes with s>1/2. Use disjoint log bumps at j, carrier Γ_j=2^(j²), and amplitudes Γ_j^(−1/2) log^(−p/2)(e+Γ_j) j^(−2)e^(−2j) in x^(−1/2) times the log-coordinate series. Uniform carrier lower bounds give divergence of every heavier polynomial norm.", "hypotheses": "Fixed ε=1/4 and fixed nonnegative smooth compact bump. The value is O(x^(−2)) as x→∞ and vanishes for x near zero. This example concerns strict class inclusion and has absolute zero trace.", "claim_kind": "smooth_strict_inclusion_of_mellin_trace_classes", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round15_claims.jsonl"}',NULL,'For each p>3 a smooth real example lies in the critical-log strip class and in none of the polynomial strip classes with s>1/2. Use disjoint log bumps at j, carrier Γ_j=2^(j²), and amplitudes Γ_j^(−1/2) log^(−p/2)(e+Γ_j) j^(−2)e^(−2j) in x^(−1/2) times the log-coordinate series. Uniform carrier lower bounds give divergence of every heavier polynomial norm.','smooth_strict_inclusion_of_mellin_trace_classes','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A weaker critical logarithmic class','theorems/research_round15_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-BL-FINITE-CUTOFF-COMPENSATOR','theorems/theorems.jsonl',359,'adjudicated_scoped','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md','{"id": "LEM-BL-FINITE-CUTOFF-COMPENSATOR", "paper_id": null, "locator": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A separate finite-cutoff identity and why the main theorem survives", "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md", "statement": "In pinned manuscript p. 8 equation (3.5), the finite-cutoff equality requires the additive gamma-compensator term n∫_(1/ε)^∞ dx/[x(x²−1)] = −(n/2)log(1−ε²). For n=1 and ε=2/3 the missing positive term is (1/2)log(9/5). The term tends to zero at O_n(ε²), and the compact jump formula with midpoint values gives the main limiting identity.", "hypotheses": "Exact finite equality in the pinned author manuscript, with the manuscript''s jump convention. The witness cutoff 3/2 avoids prime powers. This calculation concerns the finite formula and its true limit.", "claim_kind": "exact_finite_cutoff_correction", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-L002"], "provenance_file": "theorems/research_round15_claims.jsonl"}',NULL,'In pinned manuscript p. 8 equation (3.5), the finite-cutoff equality requires the additive gamma-compensator term n∫_(1/ε)^∞ dx/[x(x²−1)] = −(n/2)log(1−ε²). For n=1 and ε=2/3 the missing positive term is (1/2)log(9/5). The term tends to zero at O_n(ε²), and the compact jump formula with midpoint values gives the main limiting identity.','exact_finite_cutoff_correction','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A separate finite-cutoff identity and why the main theorem survives','theorems/research_round15_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-CSTAR-LONG-PRIME-PROGRESSION-NORM-COUNTERMODEL','theorems/theorems.jsonl',360,'adjudicated_scoped','audits/adversarial_reviews/director_long_prime_round15.md','{"id": "OBS-CSTAR-LONG-PRIME-PROGRESSION-NORM-COUNTERMODEL", "paper_id": null, "locator": "audits/adversarial_reviews/director_long_prime_round15.md · An exact limitation of two progression norms", "evidence": "audits/adversarial_reviews/director_long_prime_round15.md", "statement": "On true supported squarefree four-prime moduli k≈K at P=KT, a nonnegative centered row model satisfies Σ_k max_u|E_(k,u)|≪√(PS) and Σ_(k,u)* |E_(k,u)|²≈PK, where S≈K/log⁴T. Its h=1 real projection with coefficients a_k/k is (12+o(1))√(PS), exceeding T log⁴T by a divergent factor. The common-divisor CRT marginals differ at 1 for two moduli gv₁ and gv₂, excluding a single common unit-supported sequence.", "hypotheses": "Fixed 1/8<b<1/6, K≈Y^(4b), T≈Y, and all four distinct factors in one fixed near-top multiplicative prime band. This is an abstract implication countermodel; it gives no lower bound for genuine primes.", "claim_kind": "abstract_phase_blind_norm_countermodel", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round15_claims.jsonl"}',NULL,'On true supported squarefree four-prime moduli k≈K at P=KT, a nonnegative centered row model satisfies Σ_k max_u|E_(k,u)|≪√(PS) and Σ_(k,u)* |E_(k,u)|²≈PK, where S≈K/log⁴T. Its h=1 real projection with coefficients a_k/k is (12+o(1))√(PS), exceeding T log⁴T by a divergent factor. The common-divisor CRT marginals differ at 1 for two moduli gv₁ and gv₂, excluding a single common unit-supported sequence.','abstract_phase_blind_norm_countermodel','audits/adversarial_reviews/director_long_prime_round15.md · An exact limitation of two progression norms','theorems/research_round15_claims.jsonl');
INSERT INTO "claims" VALUES('OPEN-CSTAR-LONG-PRIME-MOVING-PHASE-SQUARE','theorems/theorems.jsonl',361,'open_sufficient_target','audits/adversarial_reviews/director_long_prime_round15.md','{"id": "OPEN-CSTAR-LONG-PRIME-MOVING-PHASE-SQUARE", "paper_id": null, "locator": "audits/adversarial_reviews/director_long_prime_round15.md · The exact prime form", "evidence": "audits/adversarial_reviews/director_long_prime_round15.md", "statement": "A sufficient open target on each residual block is Σ_(k≈K,h≈D)|Σ_(p≈P,(p,k)=1)(log p)³p^(−it)[e(−hp/k)−μ(q)/φ(q)]|²≪T^(2−η)K/D with q=k/(h,k), uniformly for |t|≤T^ε and some fixed η>0. Cauchy–Schwarz costs O(T^ε√(D/K)) and the Mellin integral costs O(T^(1−κ)).", "hypotheses": "T≈Y, DP≈KT, a_k≤24, cutoff H=T^κ with κ sufficiently near one, and 1−κ+ε<η/2 with strict margin. The k-sum may be restricted to actual modulus support. All divisor gcds are retained. No square estimate on genuine primes is claimed.", "claim_kind": "open_sufficient_moving_phase_target", "status": "open_sufficient_target", "novelty_claim": false, "provenance_file": "theorems/research_round15_claims.jsonl"}',NULL,'A sufficient open target on each residual block is Σ_(k≈K,h≈D)|Σ_(p≈P,(p,k)=1)(log p)³p^(−it)[e(−hp/k)−μ(q)/φ(q)]|²≪T^(2−η)K/D with q=k/(h,k), uniformly for |t|≤T^ε and some fixed η>0. Cauchy–Schwarz costs O(T^ε√(D/K)) and the Mellin integral costs O(T^(1−κ)).','open_sufficient_moving_phase_target','audits/adversarial_reviews/director_long_prime_round15.md · The exact prime form','theorems/research_round15_claims.jsonl');
INSERT INTO "claims" VALUES('THM-PRIME-PRODUCT-EXACT-PADDED-FACTORABILITY','theorems/theorems.jsonl',362,'adjudicated_scoped','audits/adversarial_reviews/director_long_prime_round15.md','{"id": "THM-PRIME-PRODUCT-EXACT-PADDED-FACTORABILITY", "paper_id": null, "locator": "audits/adversarial_reviews/director_long_prime_round15.md · Exact padded factorability", "evidence": "audits/adversarial_reviews/director_long_prime_round15.md", "statement": "For the full ordered m-prime coefficient c_m/m! from a finite nonempty set with largest prime p_*, the exact r-way 1-bounded well-factorable level is p_*^(m+r−1). Completely multiplicative |g|≤1 preserves sufficiency and preserves necessity if g(p_*)≠0. For m=4,r=3 the padded Y^(6b) level fits Pascadi''s longest-block fixed-residue exponent 5/8 with a strict margin when b<5/28.", "hypotheses": "Integers m,r≥1, and every prescribed real split Q=∏Q_i with Q_i≥1. The sequence is untruncated. The comparison to Pascadi uses x≈Y^(1+4b) and fixed nonzero residue; no sharp-shell factorability or varying-residue conclusion follows.", "claim_kind": "intrinsic_exact_padded_factorability", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round15_claims.jsonl"}',NULL,'For the full ordered m-prime coefficient c_m/m! from a finite nonempty set with largest prime p_*, the exact r-way 1-bounded well-factorable level is p_*^(m+r−1). Completely multiplicative |g|≤1 preserves sufficiency and preserves necessity if g(p_*)≠0. For m=4,r=3 the padded Y^(6b) level fits Pascadi''s longest-block fixed-residue exponent 5/8 with a strict margin when b<5/28.','intrinsic_exact_padded_factorability','audits/adversarial_reviews/director_long_prime_round15.md · Exact padded factorability','theorems/research_round15_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-GONEK-EXPLICIT-ABEL-PRIME-SUBSTITUTION','theorems/theorems.jsonl',363,'adjudicated_scoped','audits/adversarial_reviews/director_explicit_abel_round15.md','{"id": "LEM-GONEK-EXPLICIT-ABEL-PRIME-SUBSTITUTION", "paper_id": null, "locator": "audits/adversarial_reviews/director_explicit_abel_round15.md · Uniform Abel estimate", "evidence": "audits/adversarial_reviews/director_explicit_abel_round15.md", "statement": "Let A_m be the difference between Σ_(n≤x) Λ(n)n^(iδ−1)log^m(x/n) and ∫₁ˣu^(iδ−1)log^m(x/u)du. With L=log x and K=|Im δ|L it is bounded by L^m+4e^K 1_(m=0)+20e^K|iδ−1|L^m+20m e^K L^(m−1). For real |δ|≤1/2 a common bound is 31L^m+20mL^(m−1).", "hypotheses": "Real x>1, integer m≥0, complex δ; omit the final term for m=0 and take the zeroth log power to be one. The right endpoint includes prime-power jumps. Uses Fiori–Jaskari v2 unconditionally for the absolute PNT error bounds r≤4 and ∫r(u)du/u<20. This is one substitution in Gonek Lemma 8.", "claim_kind": "unconditional_explicit_abel_substitution", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-P122-FIORI-JASKARI-PNT", "PAPER-LF63-GONEK1984"], "provenance_file": "theorems/research_round15_claims.jsonl"}',NULL,'Let A_m be the difference between Σ_(n≤x) Λ(n)n^(iδ−1)log^m(x/n) and ∫₁ˣu^(iδ−1)log^m(x/u)du. With L=log x and K=|Im δ|L it is bounded by L^m+4e^K 1_(m=0)+20e^K|iδ−1|L^m+20m e^K L^(m−1). For real |δ|≤1/2 a common bound is 31L^m+20mL^(m−1).','unconditional_explicit_abel_substitution','audits/adversarial_reviews/director_explicit_abel_round15.md · Uniform Abel estimate','theorems/research_round15_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-MELLIN-CRITICAL-LOG-ENDPOINT-ABSOLUTE-DIVERGENCE','theorems/theorems.jsonl',364,'adjudicated_scoped','audits/adversarial_reviews/director_critical_endpoint_round15.md','{"id": "OBS-MELLIN-CRITICAL-LOG-ENDPOINT-ABSOLUTE-DIVERGENCE", "paper_id": null, "locator": "audits/adversarial_reviews/director_critical_endpoint_round15.md · Exact assertion", "evidence": "audits/adversarial_reviews/director_critical_endpoint_round15.md", "statement": "A real smooth f vanishing near zero and one and satisfying f(x)=O(x^(−4)) has finite Mellin area norm on β∈[−1/4,5/4] with weight √(1+t²) log³(e+|t|), yet Σ_ρ|h(ρ)| diverges. Every realization of the disjoint finite-carrier packet signs has finite norm, and divergence holds for almost every independent symmetric sign realization.", "hypotheses": "Actual nontrivial zeta zeros counted with multiplicity, using unconditional Riemann–von Mangoldt counting. The same example excludes universal absolute sampling for p≤3. Signed symmetric height convergence at p=3 remains open.", "claim_kind": "critical_log_endpoint_counterexample_to_absolute_zero_sampling", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round15_claims.jsonl"}',NULL,'A real smooth f vanishing near zero and one and satisfying f(x)=O(x^(−4)) has finite Mellin area norm on β∈[−1/4,5/4] with weight √(1+t²) log³(e+|t|), yet Σ_ρ|h(ρ)| diverges. Every realization of the disjoint finite-carrier packet signs has finite norm, and divergence holds for almost every independent symmetric sign realization.','critical_log_endpoint_counterexample_to_absolute_zero_sampling','audits/adversarial_reviews/director_critical_endpoint_round15.md · Exact assertion','theorems/research_round15_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-MORSE-PRINTED-SHIFTED-FAMILY-SELF-REFLECTION','theorems/theorems.jsonl',365,'adjudicated_scoped','audits/adversarial_reviews/director_morse_scoped_round15.md','{"id": "OBS-MORSE-PRINTED-SHIFTED-FAMILY-SELF-REFLECTION", "paper_id": null, "locator": "audits/adversarial_reviews/director_morse_scoped_round15.md · The nonzero-shift function is self-reflected", "evidence": "audits/adversarial_reviews/director_morse_scoped_round15.md", "statement": "The printed E_h=(P+Q)/2−i(P−Q)/(2h), where P(z)=ξ(1/2−iz+h) and Q(z)=ξ(1/2−iz−h), equals its Schwarz reflection for every real h≠0 because P#=Q and Q#=P. Thus h=1/2,z=i already gives equality in the absolute values required to be strictly ordered by (5.1). The local limit of the printed family is ξ−iξ′.", "hypotheses": "The display immediately preceding (5.5) in the pinned arXiv v6 and journal versions. The separately defined h=0 function and the fixed-boundary spectral results are outside this claim.", "claim_kind": "exact_source_local_hermite_biehler_counterexample", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-LAG2009-MORSE"], "provenance_file": "theorems/research_round15_claims.jsonl"}',NULL,'The printed E_h=(P+Q)/2−i(P−Q)/(2h), where P(z)=ξ(1/2−iz+h) and Q(z)=ξ(1/2−iz−h), equals its Schwarz reflection for every real h≠0 because P#=Q and Q#=P. Thus h=1/2,z=i already gives equality in the absolute values required to be strictly ordered by (5.1). The local limit of the printed family is ξ−iξ′.','exact_source_local_hermite_biehler_counterexample','audits/adversarial_reviews/director_morse_scoped_round15.md · The nonzero-shift function is self-reflected','theorems/research_round15_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-MORSE-PRINTED-HERGLOTZ-QUOTIENT-SIGN','theorems/theorems.jsonl',366,'adjudicated_scoped','audits/adversarial_reviews/director_morse_scoped_round15.md','{"id": "OBS-MORSE-PRINTED-HERGLOTZ-QUOTIENT-SIGN", "paper_id": null, "locator": "audits/adversarial_reviews/director_morse_scoped_round15.md · The explicit quotient has the opposite Herglotz sign", "evidence": "audits/adversarial_reviews/director_morse_scoped_round15.md", "statement": "At z=i and x=e^u, the printed quotient (6.2) is −i exp(−x)/(1+x), so u=0 gives −i/(2e). Its imaginary part is strictly negative. With the printed decomposition E=A−iB, the compatible Herglotz quotient is +B/A.", "hypotheses": "Equation (6.2) and the positive-imaginary convention in the pinned arXiv v6 and journal versions. This is an auxiliary quotient in the z variable. The Appendix B Weyl–Titchmarsh quotient uses energy E=z² and has its own sign.", "claim_kind": "exact_source_local_herglotz_sign_counterexample", "status": "adjudicated_scoped", "novelty_claim": false, "related_paper_ids": ["PAPER-LAG2009-MORSE"], "provenance_file": "theorems/research_round15_claims.jsonl"}',NULL,'At z=i and x=e^u, the printed quotient (6.2) is −i exp(−x)/(1+x), so u=0 gives −i/(2e). Its imaginary part is strictly negative. With the printed decomposition E=A−iB, the compatible Herglotz quotient is +B/A.','exact_source_local_herglotz_sign_counterexample','audits/adversarial_reviews/director_morse_scoped_round15.md · The explicit quotient has the opposite Herglotz sign','theorems/research_round15_claims.jsonl');
INSERT INTO "claims" VALUES('THM-MELLIN-CRITICAL-STRIP-SYMMETRIC-EXPLICIT-FORMULA','theorems/theorems.jsonl',367,'adjudicated_scoped','audits/adversarial_reviews/director_signed_mellin_round16.md','{"id": "THM-MELLIN-CRITICAL-STRIP-SYMMETRIC-EXPLICIT-FORMULA", "paper_id": null, "related_paper_ids": ["PAPER-L002", "PAPER-M001"], "locator": "audits/adversarial_reviews/director_signed_mellin_round16.md · Statement and distinction from absolute sampling", "evidence": "audits/adversarial_reviews/director_signed_mellin_round16.md", "claim_kind": "sufficient_critical_strip_symmetric_explicit_formula", "status": "adjudicated_scoped", "novelty_claim": false, "statement": "The ordinary inclusive symmetric height sum over nontrivial zeta zeros counted with multiplicity converges to the ordinary compensated Guinand–Weil formula with critical Mellin strip area weight √(1+t²). Consequently the logarithmic weights √(1+t²) log^p(e+|t|) suffice for every p≥0 under the same local hypotheses.", "hypotheses": "Continuous f with f(x)=O(x^δ) at zero and O(x^(−1−δ)) at infinity, F(u)=e^(u/2)f(e^u) in H¹ on a neighborhood of 0, and a finite stated strip norm on β∈[−ε,1+ε], 0<ε<δ. Unconditional. The contour proof establishes symmetric convergence, with separate half-axis convergence established by the Selberg route for p>1.", "qa_evidence": ["audits/adversarial_reviews/geometry155_director_round16_qa.md"], "provenance_file": "theorems/research_round16_claims.jsonl"}',NULL,'The ordinary inclusive symmetric height sum over nontrivial zeta zeros counted with multiplicity converges to the ordinary compensated Guinand–Weil formula with critical Mellin strip area weight √(1+t²). Consequently the logarithmic weights √(1+t²) log^p(e+|t|) suffice for every p≥0 under the same local hypotheses.','sufficient_critical_strip_symmetric_explicit_formula','audits/adversarial_reviews/director_signed_mellin_round16.md · Statement and distinction from absolute sampling','theorems/research_round16_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-MELLIN-SELBERG-PROJECTION-AND-COUNT-REMAINDER','theorems/theorems.jsonl',368,'adjudicated_scoped','audits/adversarial_reviews/director_signed_mellin_round16.md','{"id": "LEM-MELLIN-SELBERG-PROJECTION-AND-COUNT-REMAINDER", "paper_id": null, "related_paper_ids": ["PAPER-M001"], "locator": "audits/adversarial_reviews/director_signed_mellin_round16.md · Literal local hypotheses and the independent Selberg route", "evidence": "audits/adversarial_reviews/director_signed_mellin_round16.md", "claim_kind": "absolute_projection_and_count_remainder_bounds", "status": "adjudicated_scoped", "novelty_claim": false, "statement": "For p>1, writing H(t)=h(1/2+it), Σ_ρ|h(ρ)−H(Im ρ)|<∞. If S₀(t)=N(t)−M(t) is the right-continuous positive-height counting remainder, then ∫₂∞|H′(t)S₀(t)|dt<∞ and H(T)S₀(T)→0 at every height. The same control holds with H(−t) on the negative half-axis.", "hypotheses": "Original endpoint value bounds and finite logarithmic Mellin strip area norm with p>1 and positive strip margin. Neither local H¹ nor a smooth-density convergence assumption is needed. The lemma does not address the projected term ∫ H M′.", "qa_evidence": ["audits/adversarial_reviews/geometry155_director_round16_qa.md"], "provenance_file": "theorems/research_round16_claims.jsonl"}',NULL,'For p>1, writing H(t)=h(1/2+it), Σ_ρ|h(ρ)−H(Im ρ)|<∞. If S₀(t)=N(t)−M(t) is the right-continuous positive-height counting remainder, then ∫₂∞|H′(t)S₀(t)|dt<∞ and H(T)S₀(T)→0 at every height. The same control holds with H(−t) on the negative half-axis.','absolute_projection_and_count_remainder_bounds','audits/adversarial_reviews/director_signed_mellin_round16.md · Literal local hypotheses and the independent Selberg route','theorems/research_round16_claims.jsonl');
INSERT INTO "claims" VALUES('THM-MELLIN-LOG-SIGNED-HALF-AXIS-CONVERGENCE','theorems/theorems.jsonl',369,'adjudicated_scoped','audits/adversarial_reviews/director_signed_mellin_round16.md','{"id": "THM-MELLIN-LOG-SIGNED-HALF-AXIS-CONVERGENCE", "paper_id": null, "related_paper_ids": ["PAPER-M001"], "locator": "audits/adversarial_reviews/director_signed_mellin_round16.md · Literal local hypotheses and the independent Selberg route", "evidence": "audits/adversarial_reviews/director_signed_mellin_round16.md", "claim_kind": "sufficient_separate_signed_height_convergence", "status": "adjudicated_scoped", "novelty_claim": false, "statement": "For p>1 the same signed zero sum converges separately on each half-height axis. The uniform density bound makes the projection onto Re s=1/2 an absolutely summable correction. The second moment of the counting remainder handles the signed Stieltjes integral, including the exact ordinate endpoint.", "hypotheses": "Same value, local H¹ and strip hypotheses as the symmetric theorem but with weight √(1+t²) log^p(e+|t|), p>1. No separate half-axis conclusion at p≤1 is asserted.", "qa_evidence": ["audits/adversarial_reviews/geometry155_director_round16_qa.md"], "provenance_file": "theorems/research_round16_claims.jsonl"}',NULL,'For p>1 the same signed zero sum converges separately on each half-height axis. The uniform density bound makes the projection onto Re s=1/2 an absolutely summable correction. The second moment of the counting remainder handles the signed Stieltjes integral, including the exact ordinate endpoint.','sufficient_separate_signed_height_convergence','audits/adversarial_reviews/director_signed_mellin_round16.md · Literal local hypotheses and the independent Selberg route','theorems/research_round16_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-BL-LITERAL-TEST-CLASS-LOCAL-MELLIN-H1','theorems/theorems.jsonl',370,'adjudicated_scoped','audits/adversarial_reviews/director_signed_mellin_round16.md','{"id": "LEM-BL-LITERAL-TEST-CLASS-LOCAL-MELLIN-H1", "paper_id": null, "related_paper_ids": ["PAPER-L002"], "locator": "audits/adversarial_reviews/director_signed_mellin_round16.md · Literal local hypotheses and the independent Selberg route", "evidence": "audits/adversarial_reviews/director_signed_mellin_round16.md", "claim_kind": "source_scope_local_regularization_implication", "status": "adjudicated_scoped", "novelty_claim": false, "statement": "Under the pinned manuscript''s literal conditions (A) and (B), finite critical strip norm gives central F∈H¹⁄². Its Gagliardo seminorm excludes any genuine jump. The source midpoint values then select the continuous representative, and finite one-sided limits of f′ give local H¹ near x=1, so the critical symmetric formula applies.", "hypotheses": "Pinned 12-page Michigan author manuscript only. Condition (A) places the first-kind restriction on both f and f′ at its exceptional points. The general continuous class with the same value bounds needs a separate local assumption.", "qa_evidence": ["audits/adversarial_reviews/geometry155_director_round16_qa.md"], "provenance_file": "theorems/research_round16_claims.jsonl"}',NULL,'Under the pinned manuscript''s literal conditions (A) and (B), finite critical strip norm gives central F∈H¹⁄². Its Gagliardo seminorm excludes any genuine jump. The source midpoint values then select the continuous representative, and finite one-sided limits of f′ give local H¹ near x=1, so the critical symmetric formula applies.','source_scope_local_regularization_implication','audits/adversarial_reviews/director_signed_mellin_round16.md · Literal local hypotheses and the independent Selberg route','theorems/research_round16_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-MELLIN-LOG-SIGNED-BOUNDARY-CUSP','theorems/theorems.jsonl',371,'adjudicated_scoped','audits/adversarial_reviews/director_signed_mellin_round16.md','{"id": "OBS-MELLIN-LOG-SIGNED-BOUNDARY-CUSP", "paper_id": null, "related_paper_ids": ["PAPER-M001"], "locator": "audits/adversarial_reviews/director_signed_mellin_round16.md · A counterexample when the local-origin condition is omitted", "evidence": "audits/adversarial_reviews/director_signed_mellin_round16.md", "claim_kind": "counterexample_to_universal_signed_sampling_without_local_regularity", "status": "adjudicated_scoped", "novelty_claim": false, "statement": "A real continuous compactly supported f, smooth off x=1, has finite p=3 logarithmic strip norm and symmetric raw-height sum tending to positive infinity. Its local archimedean compensation diverges. In log coordinates take a compact positive-definite multiplier times the inverse Fourier transform of a positive even spectrum comparable to 1/(|t| log²|t| loglog|t|). The smooth counting density diverges positively while the signed projection and count-remainder corrections converge.", "hypotheses": "Any fixed finite strip of the indicated form. The cusp lies outside literal (A) and the neighborhood H¹ theorem. It is separate from the smooth p=3 example of absolute divergence and supplies no additional author finding.", "qa_evidence": ["audits/adversarial_reviews/geometry155_director_round16_qa.md"], "provenance_file": "theorems/research_round16_claims.jsonl"}',NULL,'A real continuous compactly supported f, smooth off x=1, has finite p=3 logarithmic strip norm and symmetric raw-height sum tending to positive infinity. Its local archimedean compensation diverges. In log coordinates take a compact positive-definite multiplier times the inverse Fourier transform of a positive even spectrum comparable to 1/(|t| log²|t| loglog|t|). The smooth counting density diverges positively while the signed projection and count-remainder corrections converge.','counterexample_to_universal_signed_sampling_without_local_regularity','audits/adversarial_reviews/director_signed_mellin_round16.md · A counterexample when the local-origin condition is omitted','theorems/research_round16_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-GONEK-EXPLICIT-POSITIVE-DERIVATIVE-CONVOLUTION','theorems/theorems.jsonl',372,'adjudicated_scoped','audits/adversarial_reviews/director_gonek_constants_round16.md','{"id": "LEM-GONEK-EXPLICIT-POSITIVE-DERIVATIVE-CONVOLUTION", "paper_id": null, "related_paper_ids": ["PAPER-LF63-GONEK1984"], "locator": "audits/adversarial_reviews/director_gonek_constants_round16.md · All positive integer orders", "evidence": "audits/adversarial_reviews/director_gonek_constants_round16.md", "claim_kind": "unconditional_explicit_positive_derivative_convolution", "status": "adjudicated_scoped", "novelty_claim": false, "statement": "For integer μ,ν≥1, z>1, M=μ+ν and L=log z, the unsigned log-power divisor sum differs from μ!ν!/(M+1)! times zL^(M+1) by at most [min(μ,ν)+1/e+μ^μν^ν/M^M] zL^M.", "hypotheses": "Gonek Lemma 7 (40), both derivative orders positive. The sign (−1)^(μ+ν) multiplies both parts in the Dirichlet series convention. The counting sum includes the integer endpoint. No claim of optimality or full numerical derivative-tail bound.", "qa_evidence": ["audits/adversarial_reviews/geometry155_director_round16_qa.md"], "provenance_file": "theorems/research_round16_claims.jsonl"}',NULL,'For integer μ,ν≥1, z>1, M=μ+ν and L=log z, the unsigned log-power divisor sum differs from μ!ν!/(M+1)! times zL^(M+1) by at most [min(μ,ν)+1/e+μ^μν^ν/M^M] zL^M.','unconditional_explicit_positive_derivative_convolution','audits/adversarial_reviews/director_gonek_constants_round16.md · All positive integer orders','theorems/research_round16_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-GONEK-EXPLICIT-LEMMA8-ORDER-ONE-PAIR','theorems/theorems.jsonl',373,'adjudicated_scoped','audits/adversarial_reviews/director_gonek_constants_round16.md','{"id": "LEM-GONEK-EXPLICIT-LEMMA8-ORDER-ONE-PAIR", "paper_id": null, "related_paper_ids": ["PAPER-LF63-GONEK1984"], "locator": "audits/adversarial_reviews/director_gonek_constants_round16.md · A convenient rational (1,1) allocation and its finite use", "evidence": "audits/adversarial_reviews/director_gonek_constants_round16.md", "claim_kind": "unconditional_explicit_finite_prime_divisor_step", "status": "adjudicated_scoped", "novelty_claim": false, "statement": "For the (1,1) coefficient B_n in Gonek Lemma 8, letting L=log x and I₃=∫₁ˣ u^(iδ−1) log³(x/u)du, the finite error |Σ_(n≤x) B_n(1,1,δ)+(x/6)I₃| is at most x[(19/4)L³+(229/4)L²+90L].", "hypotheses": "Real x>1 and real |δ|≤1/2. Uses the convenient rational (1,1) convolution bound 9/4 and the positive-power Abel specialization with vanishing upper boundary. This concerns only the divisor and prime-to-integral steps.", "qa_evidence": ["audits/adversarial_reviews/geometry155_director_round16_qa.md"], "provenance_file": "theorems/research_round16_claims.jsonl"}',NULL,'For the (1,1) coefficient B_n in Gonek Lemma 8, letting L=log x and I₃=∫₁ˣ u^(iδ−1) log³(x/u)du, the finite error |Σ_(n≤x) B_n(1,1,δ)+(x/6)I₃| is at most x[(19/4)L³+(229/4)L²+90L].','unconditional_explicit_finite_prime_divisor_step','audits/adversarial_reviews/director_gonek_constants_round16.md · A convenient rational (1,1) allocation and its finite use','theorems/research_round16_claims.jsonl');
INSERT INTO "claims" VALUES('THM-RIEMANN1859-MODERN-GENUS-ZERO-PAIRED-PRODUCT','theorems/theorems.jsonl',374,'adjudicated_scoped','audits/adversarial_reviews/director_riemann1859_whole_round16.md','{"id": "THM-RIEMANN1859-MODERN-GENUS-ZERO-PAIRED-PRODUCT", "paper_id": null, "related_paper_ids": ["PAPER-S001"], "locator": "audits/adversarial_reviews/director_riemann1859_whole_round16.md · Continuation and the product: the exact missing steps", "evidence": "audits/adversarial_reviews/director_riemann1859_whole_round16.md", "claim_kind": "known_modern_reconstruction_of_historical_product", "status": "adjudicated_scoped", "novelty_claim": false, "statement": "Let Xi(t)=ξ_*(1/2+it), with ξ_*(s)=s(s−1)π^(−s/2)Γ(s/2)ζ(s)/2. Its even Taylor series defines G(w)=Xi(√w), entire of order at most 1/2 by log M_Xi(R)=O(R log(R+2)), with order exactly 1/2 by Stirling along positive real s. Hadamard gives the genus-zero product Xi(t)=Xi(0) ∏_(Re α>0)(1−t²/α²), including multiplicities. In s coordinates the paired normalization is Xi(0)∏_α(1+1/(4α²))=ξ_*(0)=1/2.", "hypotheses": "Riemann''s theta and cosine representations, evenness, positivity on the imaginary t axis, and external modern finite-order Hadamard factorization. No RH, square-root branch choice, or zero-count asymptotic is used for the product. This is a known modern reconstruction of the 1859 product.", "qa_evidence": ["audits/adversarial_reviews/geometry157_director_riemann_whole_qa.md"], "provenance_file": "theorems/research_round16_claims.jsonl"}',NULL,'Let Xi(t)=ξ_*(1/2+it), with ξ_*(s)=s(s−1)π^(−s/2)Γ(s/2)ζ(s)/2. Its even Taylor series defines G(w)=Xi(√w), entire of order at most 1/2 by log M_Xi(R)=O(R log(R+2)), with order exactly 1/2 by Stirling along positive real s. Hadamard gives the genus-zero product Xi(t)=Xi(0) ∏_(Re α>0)(1−t²/α²), including multiplicities. In s coordinates the paired normalization is Xi(0)∏_α(1+1/(4α²))=ξ_*(0)=1/2.','known_modern_reconstruction_of_historical_product','audits/adversarial_reviews/director_riemann1859_whole_round16.md · Continuation and the product: the exact missing steps','theorems/research_round16_claims.jsonl');
INSERT INTO "claims" VALUES('THM-RIEMANN1859-MODERN-ORDERED-J0-FORMULA','theorems/theorems.jsonl',375,'adjudicated_scoped','audits/adversarial_reviews/director_riemann1859_whole_round16.md','{"id": "THM-RIEMANN1859-MODERN-ORDERED-J0-FORMULA", "paper_id": null, "related_paper_ids": ["PAPER-S001", "PAPER-H402", "PAPER-H406"], "locator": "audits/adversarial_reviews/director_riemann1859_whole_round16.md · Exact arithmetic identity, branches and the known constant", "evidence": "audits/adversarial_reviews/director_riemann1859_whole_round16.md", "claim_kind": "known_modern_reconstruction_of_historical_ordered_explicit_formula", "status": "adjudicated_scoped", "novelty_claim": false, "statement": "For x>1, midpoint J₀(x) equals li(x)−lim_(T→∞)Σ_(|Im ρ|≤T) E_ρ(x)+∫ₓ∞du/[u(u²−1)log u]−log 2. Use E_ρ(x)=Ei(ρ log x)−iπ sgn(Im ρ) with the continued log x^ρ=ρ log x. The offsets cancel under conjugate ordering. The summable O_I((1+|Im ρ|)^(−2)) kernel remainder reduces raw pointwise convergence to the later von Mangoldt midpoint ψ₀ formula. Unit-height counts and O_x(1/T) terms give equivalence with the source''s |α| order.", "hypotheses": "Midpoint values at prime powers, zeros with multiplicity, the stated height order, paired normalization, and external later ordered von Mangoldt formula. The real constant −log 2 is Genocchi''s known correction. No proof of the ordered limit is attributed to the 1859 text and no novelty is claimed.", "qa_evidence": ["audits/adversarial_reviews/geometry157_director_riemann_whole_qa.md"], "provenance_file": "theorems/research_round16_claims.jsonl"}',NULL,'For x>1, midpoint J₀(x) equals li(x)−lim_(T→∞)Σ_(|Im ρ|≤T) E_ρ(x)+∫ₓ∞du/[u(u²−1)log u]−log 2. Use E_ρ(x)=Ei(ρ log x)−iπ sgn(Im ρ) with the continued log x^ρ=ρ log x. The offsets cancel under conjugate ordering. The summable O_I((1+|Im ρ|)^(−2)) kernel remainder reduces raw pointwise convergence to the later von Mangoldt midpoint ψ₀ formula. Unit-height counts and O_x(1/T) terms give equivalence with the source''s |α| order.','known_modern_reconstruction_of_historical_ordered_explicit_formula','audits/adversarial_reviews/director_riemann1859_whole_round16.md · Exact arithmetic identity, branches and the known constant','theorems/research_round16_claims.jsonl');
INSERT INTO "claims" VALUES('LEM-MELLIN-NEGATIVE-LOG-SHARP-INVERSION-PACKET','theorems/theorems.jsonl',376,'adjudicated_scoped','audits/adversarial_reviews/director_negative_mellin_round17.md','{"id": "LEM-MELLIN-NEGATIVE-LOG-SHARP-INVERSION-PACKET", "paper_id": null, "locator": "audits/adversarial_reviews/director_negative_mellin_round17.md · One packet: a large sharp inverse with small weakened norm", "evidence": "audits/adversarial_reviews/director_negative_mellin_round17.md", "claim_kind": "negative_logarithmic_sharp_inversion_packet_estimate", "statement": "Fix a prime p, u_*=log p, b=1/p and 0<A<q. The one-sided packet F_T(u_*+v)=b χ(v/W)η(Tv)sin(Tv), W=log^A(T)/T, has squared N_(−q) norm O(b²[W√T+TW/log^q T]) and tends to zero in this norm. On a=1+ε/2 its sharp inverse at u_* equals b exp((a−1/2)u_*) log(TW)/(2π)+O(b), with O(bW) change for U∈[T,T+1]. The target prime contributes −b log p log(TW)/(2π√p) in the folded contour, while all other prime terms tend to zero and the gamma piece is O(N_(−q)).", "hypotheses": "Fixed prime, strip margin 0<ε<1/4 and fixed 0<A<q. Constants may depend on the stage, including p,q,A,ε. The packet shrinks strictly between the target prime center and the next prime-power center. The contour statement uses a good height in [T,T+1].", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round17_claims.jsonl"}',NULL,'Fix a prime p, u_*=log p, b=1/p and 0<A<q. The one-sided packet F_T(u_*+v)=b χ(v/W)η(Tv)sin(Tv), W=log^A(T)/T, has squared N_(−q) norm O(b²[W√T+TW/log^q T]) and tends to zero in this norm. On a=1+ε/2 its sharp inverse at u_* equals b exp((a−1/2)u_*) log(TW)/(2π)+O(b), with O(bW) change for U∈[T,T+1]. The target prime contributes −b log p log(TW)/(2π√p) in the folded contour, while all other prime terms tend to zero and the gamma piece is O(N_(−q)).','negative_logarithmic_sharp_inversion_packet_estimate','audits/adversarial_reviews/director_negative_mellin_round17.md · One packet: a large sharp inverse with small weakened norm','theorems/research_round17_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-MELLIN-ALL-NEGATIVE-LOG-SIGNED-DIVERGENCE','theorems/theorems.jsonl',377,'adjudicated_scoped','audits/adversarial_reviews/director_negative_mellin_round17.md','{"id": "OBS-MELLIN-ALL-NEGATIVE-LOG-SIGNED-DIVERGENCE", "paper_id": null, "locator": "audits/adversarial_reviews/director_negative_mellin_round17.md · A single globally smooth test", "evidence": "audits/adversarial_reviews/director_negative_mellin_round17.md", "claim_kind": "simultaneous_negative_logarithmic_strip_signed_counterexample", "statement": "For each fixed strip with 0<ε<1/4 one real smooth f, zero near zero and one and O(x^(−3/2)) at infinity, has finite N_(−q) for every fixed q>0. Its samples f(n) at prime powers and f(1/n) for n≥1 vanish. The ordinary symmetric raw zero sum with multiplicity has a subsequence tending to −∞ and a bounded subsequence. The pole and archimedean terms are absolutely finite.", "hypotheses": "Use one locally finite escaped-prime packet sequence with q_j=1/j and A_j=q_j/2 before choosing each carrier. Stagewise protection controls both finite-height subsequences. The witness satisfies literal (A) and (B). Its critical norm is infinite, and the weakened norms need not be bounded uniformly as q decreases to zero.", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round17_claims.jsonl"}',NULL,'For each fixed strip with 0<ε<1/4 one real smooth f, zero near zero and one and O(x^(−3/2)) at infinity, has finite N_(−q) for every fixed q>0. Its samples f(n) at prime powers and f(1/n) for n≥1 vanish. The ordinary symmetric raw zero sum with multiplicity has a subsequence tending to −∞ and a bounded subsequence. The pole and archimedean terms are absolutely finite.','simultaneous_negative_logarithmic_strip_signed_counterexample','audits/adversarial_reviews/director_negative_mellin_round17.md · A single globally smooth test','theorems/research_round17_claims.jsonl');
INSERT INTO "claims" VALUES('THM-MELLIN-EXACT-SIGNED-LOG-BOUNDARY','theorems/theorems.jsonl',378,'adjudicated_scoped','audits/adversarial_reviews/director_negative_mellin_round17.md','{"id": "THM-MELLIN-EXACT-SIGNED-LOG-BOUNDARY", "paper_id": null, "locator": "audits/adversarial_reviews/director_negative_mellin_round17.md · What this obstruction says", "evidence": "audits/adversarial_reviews/director_negative_mellin_round17.md", "claim_kind": "sharp_signed_symmetric_logarithmic_strip_boundary", "statement": "The exponent p=0 is the exact boundary for a universal ordinary symmetric height formula in this logarithmic strip scale. Every p≥0 suffices under the original value bounds and local H¹ around x=1 or the literal (A) class with midpoint values. One smooth witness in that class defeats all weights √(1+t²)/log^q(e+|t|), q>0.", "hypotheses": "Fix 0<ε<1/4 so both sufficiency and the counterexample apply on the stated strip. This is a universal symmetric result for the stated test class. No individual necessity claim, uniform q-bound, or separate half-axis threshold is asserted.", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round17_claims.jsonl"}',NULL,'The exponent p=0 is the exact boundary for a universal ordinary symmetric height formula in this logarithmic strip scale. Every p≥0 suffices under the original value bounds and local H¹ around x=1 or the literal (A) class with midpoint values. One smooth witness in that class defeats all weights √(1+t²)/log^q(e+|t|), q>0.','sharp_signed_symmetric_logarithmic_strip_boundary','audits/adversarial_reviews/director_negative_mellin_round17.md · What this obstruction says','theorems/research_round17_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-CSTAR-COMMON-NONNEGATIVE-SEQUENCE-NORM-COUNTERMODEL','theorems/theorems.jsonl',379,'adjudicated_scoped','audits/adversarial_reviews/director_common_sequence_round17.md','{"id": "OBS-CSTAR-COMMON-NONNEGATIVE-SEQUENCE-NORM-COUNTERMODEL", "paper_id": null, "locator": "audits/adversarial_reviews/director_common_sequence_round17.md · Exact statement", "evidence": "audits/adversarial_reviews/director_common_sequence_round17.md", "claim_kind": "common_sequence_all_residue_and_induced_unit_norm_countermodel", "statement": "For K≈T^θ, 1/2<θ<2/3 and integer P≈KT, one nonnegative real sequence b(n) on J=[P,2P)∩ℤ has exact mass P. Writing B_(k,u)=Σ_(n≡u mod k)b(n), the all-residue squared error about P/k totals O(PK) over k≤2K and the sum of row maxima is O(K√P). Both bounds hold on the unit rows centered by their induced means. For the full support S of the narrow-band fourth prime polynomial, including repeated factors, |S|=binom(M+3,4)≍K/log⁴K where M is the number of band primes. The coefficients c_k=4!/∏_(p|k)m_p! satisfy 1≤c_k≤24. The h=1 unit-centered real phase projection with weights c_k/k is ≫√(P|S|), exceeding T log⁴T by a divergent factor.", "hypotheses": "Fix a narrow relative prime band [X,(1+η)X] with K=X⁴ and (1+η)⁴<2 so S lies in [K,2K). All congruence rows arise from the same sequence and whole-row common-divisor marginals agree. The all-residue centering and induced unit means concern an integer interval, with no prime support, simultaneous unit support, P/φ(k) baseline, or Mangoldt pointwise cap.", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round17_claims.jsonl"}',NULL,'For K≈T^θ, 1/2<θ<2/3 and integer P≈KT, one nonnegative real sequence b(n) on J=[P,2P)∩ℤ has exact mass P. Writing B_(k,u)=Σ_(n≡u mod k)b(n), the all-residue squared error about P/k totals O(PK) over k≤2K and the sum of row maxima is O(K√P). Both bounds hold on the unit rows centered by their induced means. For the full support S of the narrow-band fourth prime polynomial, including repeated factors, |S|=binom(M+3,4)≍K/log⁴K where M is the number of band primes. The coefficients c_k=4!/∏_(p|k)m_p! satisfy 1≤c_k≤24. The h=1 unit-centered real phase projection with weights c_k/k is ≫√(P|S|), exceeding T log⁴T by a divergent factor.','common_sequence_all_residue_and_induced_unit_norm_countermodel','audits/adversarial_reviews/director_common_sequence_round17.md · Exact statement','theorems/research_round17_claims.jsonl');
INSERT INTO "claims" VALUES('OBS-CSTAR-COMMON-INTEGER-SEQUENCE-NORM-COUNTERMODEL','theorems/theorems.jsonl',380,'adjudicated_scoped','audits/adversarial_reviews/director_common_sequence_round17.md','{"id": "OBS-CSTAR-COMMON-INTEGER-SEQUENCE-NORM-COUNTERMODEL", "paper_id": null, "locator": "audits/adversarial_reviews/director_common_sequence_round17.md · Integer-valued realization with exact mass", "evidence": "audits/adversarial_reviews/director_common_sequence_round17.md", "claim_kind": "integer_valued_common_sequence_countermodel", "statement": "In the common-sequence countermodel the weights can be nonnegative integers while preserving mass P, the same order of discrepancy bounds and the phase lower bound. Draw P integers from probabilities b(n)/P. The multinomial summed expected variance is O(PK), and the projection variance O(P(|S|/K)²) is negligible against P|S|. Markov and Chebyshev give a realization satisfying both bounds.", "hypotheses": "Same single interval, full fourth-power support and centering as the real-weight model. Integer values can include repeated draws. This remains an abstract obstruction and does not estimate the genuine prime term or the full smooth C_* sum.", "status": "adjudicated_scoped", "novelty_claim": false, "provenance_file": "theorems/research_round17_claims.jsonl"}',NULL,'In the common-sequence countermodel the weights can be nonnegative integers while preserving mass P, the same order of discrepancy bounds and the phase lower bound. Draw P integers from probabilities b(n)/P. The multinomial summed expected variance is O(PK), and the projection variance O(P(|S|/K)²) is negligible against P|S|. Markov and Chebyshev give a realization satisfying both bounds.','integer_valued_common_sequence_countermodel','audits/adversarial_reviews/director_common_sequence_round17.md · Integer-valued realization with exact mass','theorems/research_round17_claims.jsonl');
INSERT INTO "claims" VALUES('THM-S004-ADV401','theorems/theorems.jsonl',381,'independentalgebraandtailreconstruction;967finiteexactchecks','arXiv1801.05914v5 Lemma12(v),p30','{"theorem_id": "THM-S004-ADV401", "paper_id": "PAPER-S004", "kind": "published_local_identity_independently_reconstructed", "source_locator": "arXiv1801.05914v5 Lemma12(v),p30", "statement": "For finiteK, ordered-pair local H derivative equals −4 local inverse-square energy plus2 times external sum_ioutsideK sum_k!=l_inK 1/((xi−xk)(xi−xl)); absolute convergence follows from macroscopic root growth.", "verification_status": "independentalgebraandtailreconstruction;967finiteexactchecks", "proof_file": "audits/rodgerstao_full_source_advocate_round4.md", "id": "THM-S004-ADV401", "locator": "arXiv1801.05914v5 Lemma12(v),p30", "provenance_file": "theorems/rodgerstao_advocate_round4.jsonl"}','PAPER-S004','For finiteK, ordered-pair local H derivative equals −4 local inverse-square energy plus2 times external sum_ioutsideK sum_k!=l_inK 1/((xi−xk)(xi−xl)); absolute convergence follows from macroscopic root growth.','published_local_identity_independently_reconstructed','arXiv1801.05914v5 Lemma12(v),p30','theorems/rodgerstao_advocate_round4.jsonl');
INSERT INTO "claims" VALUES('THM-S004-ADV402','theorems/theorems.jsonl',382,'advocateandsemanticindependentwitnessandreplacement;directorscopeclassificationpending','v5 Lemma16 proof,p40','{"theorem_id": "THM-S004-ADV402", "paper_id": "PAPER-S004", "kind": "scoped_independent_repair_of_intermediate_bound", "source_locator": "v5 Lemma16 proof,p40", "statement": "The odd reciprocal-cube endpoint sum is bounded using (1+minimum_endpoint_distance)^−2, not the printed maximum; its aggregate sum is bounded, preserving Lemma16 up to polylog factors.", "verification_status": "advocateandsemanticindependentwitnessandreplacement;directorscopeclassificationpending", "proof_file": "audits/rodgerstao_full_source_advocate_round4.md", "review": "audits/adversarial_reviews/rodgerstao_local_semantic_round4.md", "id": "THM-S004-ADV402", "locator": "v5 Lemma16 proof,p40", "provenance_file": "theorems/rodgerstao_advocate_round4.jsonl"}','PAPER-S004','The odd reciprocal-cube endpoint sum is bounded using (1+minimum_endpoint_distance)^−2, not the printed maximum; its aggregate sum is bounded, preserving Lemma16 up to polylog factors.','scoped_independent_repair_of_intermediate_bound','v5 Lemma16 proof,p40','theorems/rodgerstao_advocate_round4.jsonl');
INSERT INTO "claims" VALUES('THM-S004-ADV403','theorems/theorems.jsonl',383,'completeadvocatederivation;independentchallengepending','audits/adversarial_reviews/rodgerstao_far_field_advocate_round4.md','{"theorem_id": "THM-S004-ADV403", "paper_id": "PAPER-S004", "kind": "proposed_signed_far_field_repair", "statement": "Under xj−ξj=Ologj and weighted inverse-square sum≤M≥Tlog³T, signed far field is −π/8signk pluspower-small error in bulk; pair antisymmetry and weightedCauchy imply sourceX4=o(M).", "verification_status": "completeadvocatederivation;independentchallengepending", "proof_file": "audits/adversarial_reviews/rodgerstao_far_field_advocate_round4.md", "novelty": "unassessed", "limitations": ["DoesnotcorrectliteralLemma21(ii)", "DoesnotcertifyallProposition22orMainTheoremdependencies"], "id": "THM-S004-ADV403", "locator": "audits/adversarial_reviews/rodgerstao_far_field_advocate_round4.md", "provenance_file": "theorems/rodgerstao_advocate_round4.jsonl"}','PAPER-S004','Under xj−ξj=Ologj and weighted inverse-square sum≤M≥Tlog³T, signed far field is −π/8signk pluspower-small error in bulk; pair antisymmetry and weightedCauchy imply sourceX4=o(M).','proposed_signed_far_field_repair','audits/adversarial_reviews/rodgerstao_far_field_advocate_round4.md','theorems/rodgerstao_advocate_round4.jsonl');
INSERT INTO "claims" VALUES('THM-R201-AUX','theorems/theorems.jsonl',384,'elementary independently reconstructed model proposition; no novelty claim','proposals/independent_campaigns/auxiliary_spectral_complexity.md','{"id": "THM-R201-AUX", "paper_id": null, "statement": "If A selfadjoint compact-resolvent, D Hermitian on C^M, B:C^M->H bounded, T=[[A,B],[B*,D]] on D(A)+C^M, then |Delta_T(K)-Delta_A(K)|<=3M for everyK>0, including two-sided unbounded spectra; constant3 sharp.", "hypotheses": ["compact resolvent", "bounded block coupling on stated common domain", "multiplicity counts in half-open bounded intervals"], "locator": "proposals/independent_campaigns/auxiliary_spectral_complexity.md", "status": "elementary independently reconstructed model proposition; no novelty claim", "verification": "scoped independent advocate/skeptic plus director adjudication; see director_round2_adjudication.md", "provenance_file": "theorems/root_round2.jsonl"}',NULL,'If A selfadjoint compact-resolvent, D Hermitian on C^M, B:C^M->H bounded, T=[[A,B],[B*,D]] on D(A)+C^M, then |Delta_T(K)-Delta_A(K)|<=3M for everyK>0, including two-sided unbounded spectra; constant3 sharp.',NULL,'proposals/independent_campaigns/auxiliary_spectral_complexity.md','theorems/root_round2.jsonl');
INSERT INTO "claims" VALUES('COR-R202-AUX-GRAPH','theorems/theorems.jsonl',385,'conditional model-complexity corollary; not RH progress','proposals/independent_campaigns/auxiliary_spectral_complexity.md','{"id": "COR-R202-AUX-GRAPH", "paper_id": null, "statement": "An E-channel fixed-boundary first-order graph with M boundedly coupled finite auxiliary levels has |Delta(K)|<3(E+M); matching classical zeta counts to o(K) atK,2K,4K requires liminf(E_K+M_K)/K>=log2/(3pi).", "hypotheses": ["one fixed graph/auxiliary realization per three-height comparison", "positive finite edge lengths", "bounded finite-rank block coupling"], "locator": "proposals/independent_campaigns/auxiliary_spectral_complexity.md", "status": "conditional model-complexity corollary; not RH progress", "verification": "scoped independent advocate/skeptic plus director adjudication; see director_round2_adjudication.md", "provenance_file": "theorems/root_round2.jsonl"}',NULL,'An E-channel fixed-boundary first-order graph with M boundedly coupled finite auxiliary levels has |Delta(K)|<3(E+M); matching classical zeta counts to o(K) atK,2K,4K requires liminf(E_K+M_K)/K>=log2/(3pi).',NULL,'proposals/independent_campaigns/auxiliary_spectral_complexity.md','theorems/root_round2.jsonl');
INSERT INTO "claims" VALUES('THM-R203-CA-CONCAVE','theorems/theorems.jsonl',386,'elementary independently reconstructed calculus lemma; novelty unassessed','proposals/independent_campaigns/lagarias_CA_interpolation_round2.md','{"id": "THM-R203-CA-CONCAVE", "paper_id": null, "statement": "For realx>=32768,H(x)=psi(x+1)+gamma,B=H+exp(H)logH, g(t)=log(B(exp t)/exp t) satisfiesg_second(t)<0.", "hypotheses": ["realx>=32768", "natural logs", "smooth digamma interpolation"], "locator": "proposals/independent_campaigns/lagarias_CA_interpolation_round2.md", "status": "elementary independently reconstructed calculus lemma; novelty unassessed", "verification": "parent plus two independent reconstructions; audits/adversarial_reviews/lagarias_concavity_round2.md and lagarias_concavity_third_round2.md", "provenance_file": "theorems/root_round2.jsonl"}',NULL,'For realx>=32768,H(x)=psi(x+1)+gamma,B=H+exp(H)logH, g(t)=log(B(exp t)/exp t) satisfiesg_second(t)<0.',NULL,'proposals/independent_campaigns/lagarias_CA_interpolation_round2.md','theorems/root_round2.jsonl');
INSERT INTO "claims" VALUES('COR-R204-CA-ENDPOINTS','theorems/theorems.jsonl',387,'conditional finite-interval certificate; no infinite-tail proof','proposals/independent_campaigns/lagarias_CA_interpolation_round2.md','{"id": "COR-R204-CA-ENDPOINTS", "paper_id": null, "statement": "If32768<=u<v are integer global maximizers ofsigma(n)/n^(1+epsilon) for the SAMEepsilon>0, and both endpoint Lagarias inequalities hold, every integer betweenu,v satisfies the inequality; strict endpoints imply strict throughout.", "hypotheses": ["certified shared supporting parameter; arbitrary abundant endpoints insufficient", "no assumption that consecutive CA ratios are prime"], "locator": "proposals/independent_campaigns/lagarias_CA_interpolation_round2.md", "status": "conditional finite-interval certificate; no infinite-tail proof", "verification": "two independent reviews and director proof", "provenance_file": "theorems/root_round2.jsonl"}',NULL,'If32768<=u<v are integer global maximizers ofsigma(n)/n^(1+epsilon) for the SAMEepsilon>0, and both endpoint Lagarias inequalities hold, every integer betweenu,v satisfies the inequality; strict endpoints imply strict throughout.',NULL,'proposals/independent_campaigns/lagarias_CA_interpolation_round2.md','theorems/root_round2.jsonl');
INSERT INTO "claims" VALUES('OBS-R205-FINITE55440','theorems/theorems.jsonl',388,'known finite inequalities independently reproduced over extended base interval','experiments/code/lagarias_55440.py','{"id": "OBS-R205-FINITE55440", "paper_id": "PAPER-R001", "statement": "All integers2<=n<=55440 satisfy strict Lagarias inequality; equality at1. Exact lower-bound integer arithmetic certificate.", "locator": "experiments/code/lagarias_55440.py", "status": "known finite inequalities independently reproduced over extended base interval", "verification": "exact integer run; inherited directed-rounding proof independently reviewed", "provenance_file": "theorems/root_round2.jsonl"}','PAPER-R001','All integers2<=n<=55440 satisfy strict Lagarias inequality; equality at1. Exact lower-bound integer arithmetic certificate.',NULL,'experiments/code/lagarias_55440.py','theorems/root_round2.jsonl');
INSERT INTO "claims" VALUES('THM-R207-CA-GLOBAL','theorems/theorems.jsonl',389,'ordinary analytic-plus-exact-computational proof; novelty unassessed','proposals/independent_campaigns/lagarias_global_concavity_round2.md','{"id": "THM-R207-CA-GLOBAL", "paper_id": null, "statement": "For every realx>=1,H(x)=psi(x+1)+gamma,B=H+exp(H)logH,g(t)=log(B(exp t)/exp t), g_second(t)<0. Analytic proof forx>=2048 plus170exact interval cells on[1,2048].", "locator": "proposals/independent_campaigns/lagarias_global_concavity_round2.md", "hypotheses": ["smooth digamma continuation", "compact cells verified by standard-library integer interval arithmetic with proved exp/log remainders"], "status": "ordinary analytic-plus-exact-computational proof; novelty unassessed", "verification": "independent Arb and integer replays, mathematical third review; not Lean-formalized", "provenance_file": "theorems/root_round2.jsonl"}',NULL,'For every realx>=1,H(x)=psi(x+1)+gamma,B=H+exp(H)logH,g(t)=log(B(exp t)/exp t), g_second(t)<0. Analytic proof forx>=2048 plus170exact interval cells on[1,2048].',NULL,'proposals/independent_campaigns/lagarias_global_concavity_round2.md','theorems/root_round2.jsonl');
INSERT INTO "claims" VALUES('THM-R001-1','theorems/theorems.jsonl',390,'source-stated; section3 reconstructed conditional on Robin dependencies','Theorem1.1; Problem E (1.1), p1; proof pp6–8','{"id": "THM-R001-1", "paper_id": "PAPER-R001", "locator": "Theorem1.1; Problem E (1.1), p1; proof pp6–8", "statement": "RH iff for every integer n>=1, sigma(n)<=H_n+exp(H_n)*log(H_n), with equality only n=1.", "hypotheses": ["n positive integer", "H_n=sum(1/j,j=1..n)", "natural log"], "status": "source-stated; section3 reconstructed conditional on Robin dependencies", "provenance_file": "theorems/root_track.jsonl"}','PAPER-R001','RH iff for every integer n>=1, sigma(n)<=H_n+exp(H_n)*log(H_n), with equality only n=1.',NULL,'Theorem1.1; Problem E (1.1), p1; proof pp6–8','theorems/root_track.jsonl');
INSERT INTO "claims" VALUES('THM-R001-2','theorems/theorems.jsonl',391,'source-stated; proof inspected','Lemma3.2,p7','{"id": "THM-R001-2", "paper_id": "PAPER-R001", "locator": "Lemma3.2,p7", "statement": "For every integer n>=20, H_n+exp(H_n)*log(H_n)<=exp(gamma)*n*log(log(n))+7*n/log(n).", "hypotheses": ["n>=20 integer"], "status": "source-stated; proof inspected", "provenance_file": "theorems/root_track.jsonl"}','PAPER-R001','For every integer n>=20, H_n+exp(H_n)*log(H_n)<=exp(gamma)*n*log(log(n))+7*n/log(n).',NULL,'Lemma3.2,p7','theorems/root_track.jsonl');
INSERT INTO "claims" VALUES('OBS-R001-3','theorems/theorems.jsonl',392,'elementary derived corollary; no novelty claim','proposals/independent_campaigns/lagarias_slack.md','{"id": "OBS-R001-3", "paper_id": "PAPER-R001", "locator": "proposals/independent_campaigns/lagarias_slack.md", "statement": "Delta(n)~exp(gamma)*gamma*n/log(n).", "hypotheses": ["n tends to infinity through integers"], "status": "elementary derived corollary; no novelty claim", "provenance_file": "theorems/root_track.jsonl"}','PAPER-R001','Delta(n)~exp(gamma)*gamma*n/log(n).',NULL,'proposals/independent_campaigns/lagarias_slack.md','theorems/root_track.jsonl');
INSERT INTO "claims" VALUES('THM-R002-FRAME','theorems/theorems.jsonl',393,'alternate_elementary_proof_for_scoped_source_estimate; no novelty claim','audits/adversarial_reviews/af_boundary_repair.md; original arXiv2608.13637v2 Proposition5.2 pp8–9','{"id": "THM-R002-FRAME", "paper_id": null, "statement": "For the fixed tapered Fourier window and sampling grid in AF Proposition5.2, with locally bounded logarithmic-tail weight |nu|<=B+log+(|tau|/(4T)), the exterior integral satisfies |E2|=O(B² L² logL), hence normalized remainder O(TlogL/L²).", "hypotheses": ["T sufficiently large,L=log(T/(2pi)),d=floor(TL/(2pi))", "phi real even C², support[-L/2,L/2],0<=phi<=1,uniform L1 first/second derivative bounds", "a=||phi||²/L bounded below", "source nu envelope(5.7), B=L+4sqrt(T/(2pi))"], "locator": "audits/adversarial_reviews/af_boundary_repair.md; original arXiv2608.13637v2 Proposition5.2 pp8–9", "status": "alternate_elementary_proof_for_scoped_source_estimate; no novelty claim", "verification": "scoped_Level3; frame_third_review.md and director_adjudication.md", "provenance_file": "theorems/root_track.jsonl"}',NULL,'For the fixed tapered Fourier window and sampling grid in AF Proposition5.2, with locally bounded logarithmic-tail weight |nu|<=B+log+(|tau|/(4T)), the exterior integral satisfies |E2|=O(B² L² logL), hence normalized remainder O(TlogL/L²).',NULL,'audits/adversarial_reviews/af_boundary_repair.md; original arXiv2608.13637v2 Proposition5.2 pp8–9','theorems/root_track.jsonl');
INSERT INTO "claims" VALUES('LEM-RST048-CLUSTER','theorems/theorems.jsonl',394,'adjudicated_scoped_conditional_reconstruction','RST048v2 equations22–41; audits/adversarial_reviews/director_rstation48_main_theorem_round6.md §§1–3','{"id": "LEM-RST048-CLUSTER", "paper_id": "PAPER-RST048", "claim_kind": "source_lemma_independently_reconstructed", "statement": "Under RH and source fixed D=e=10^-4,delta=10^-6, delayed-profile grouped errors satisfy ||sum_{C in B} zeta(R_C-T_{L,w_kC}R_C)||_*² <= (C/L)sum_{C in B}(2+|tau_C|)^(-2+1/100) for every subset B, L=logN. Centers are fixed-mesh separated; individual roots need not be. The tail beyondY is O(Y^(-99/100)/L).", "hypotheses": "Exact source norm dt/[2pi(1/4+t²)], RH fixed-right reciprocal/subpower bounds and fixed-interval zero counts; source profiles22–23. Hilbert-space subset summability, not sum of individual norms.", "locator": "RST048v2 equations22–41; audits/adversarial_reviews/director_rstation48_main_theorem_round6.md §§1–3", "status": "adjudicated_scoped_conditional_reconstruction", "novelty_claim": false, "provenance_file": "theorems/rstation48_director_round6.jsonl"}','PAPER-RST048','Under RH and source fixed D=e=10^-4,delta=10^-6, delayed-profile grouped errors satisfy ||sum_{C in B} zeta(R_C-T_{L,w_kC}R_C)||_*² <= (C/L)sum_{C in B}(2+|tau_C|)^(-2+1/100) for every subset B, L=logN. Centers are fixed-mesh separated; individual roots need not be. The tail beyondY is O(Y^(-99/100)/L).','source_lemma_independently_reconstructed','RST048v2 equations22–41; audits/adversarial_reviews/director_rstation48_main_theorem_round6.md §§1–3','theorems/rstation48_director_round6.jsonl');
INSERT INTO "claims" VALUES('LEM-RST048-INTEGER','theorems/theorems.jsonl',395,'adjudicated_scoped_conditional_reconstruction','RST048v2 equations51–62; director_rstation48_main_theorem_round6.md §6; independent quadrature reviews','{"id": "LEM-RST048-INTEGER", "paper_id": "PAPER-RST048", "claim_kind": "source_arithmetic_realization_independently_reconstructed", "statement": "Under the same RH inputs, withH=N^(1/20), K=N^(3/20), the source growing delayed correction is realized by an actual length-at-mostN Dirichlet polynomial. Its low/high squared zeta-weighted quadrature errors are O(N^(-0.1499595)) and O(N^(-0.049958)); the anchor is O(N^(-0.07499475)). Constants may depend on the fixed contour parameters.", "locator": "RST048v2 equations51–62; director_rstation48_main_theorem_round6.md §6; independent quadrature reviews", "status": "adjudicated_scoped_conditional_reconstruction", "novelty_claim": false, "provenance_file": "theorems/rstation48_director_round6.jsonl"}','PAPER-RST048','Under the same RH inputs, withH=N^(1/20), K=N^(3/20), the source growing delayed correction is realized by an actual length-at-mostN Dirichlet polynomial. Its low/high squared zeta-weighted quadrature errors are O(N^(-0.1499595)) and O(N^(-0.049958)); the anchor is O(N^(-0.07499475)). Constants may depend on the fixed contour parameters.','source_arithmetic_realization_independently_reconstructed','RST048v2 equations51–62; director_rstation48_main_theorem_round6.md §6; independent quadrature reviews','theorems/rstation48_director_round6.jsonl');
INSERT INTO "claims" VALUES('LEM-RST048-LOCAL-REPAIR','theorems/theorems.jsonl',396,'adjudicated_scoped_repairable_compressed_source_step','audits/adversarial_reviews/director_rstation48_main_theorem_round6.md §7; threshold62_rstation48_main_theorem_skeptic.md; latest62_rst048_independent.md','{"id": "LEM-RST048-LOCAL-REPAIR", "paper_id": "PAPER-RST048", "claim_kind": "explicit_fixed_Laurent_localization_qualification", "statement": "For each fixed finite union of source clusters, expand its principal parts into individual Laurent terms a_(rho,j)/(s-rho)^j. Outside a fixed neighborhood of that term''s own ordinate, the singleton repeated-node profile estimate bounds its zeta-multiplied error by C_F|zeta(1/2+it)|/[L|t-gamma|^(j+1)], giving weighted norm O_F(1/L). This also covers gaps inside the original full cluster hull and fills the use of26 in source§7.2.", "hypotheses": "Assume RH, so rho=1/2+i gamma; classical RH subpower zeta bound for integrability. Fixed finite set first; constants not uniform in growing sets. Source taper admissible for j<=kC; optimal replacement has analogous BV estimate. No new uniform zero-separation assumption.", "locator": "audits/adversarial_reviews/director_rstation48_main_theorem_round6.md §7; threshold62_rstation48_main_theorem_skeptic.md; latest62_rst048_independent.md", "status": "adjudicated_scoped_repairable_compressed_source_step", "novelty_claim": false, "provenance_file": "theorems/rstation48_director_round6.jsonl"}','PAPER-RST048','For each fixed finite union of source clusters, expand its principal parts into individual Laurent terms a_(rho,j)/(s-rho)^j. Outside a fixed neighborhood of that term''s own ordinate, the singleton repeated-node profile estimate bounds its zeta-multiplied error by C_F|zeta(1/2+it)|/[L|t-gamma|^(j+1)], giving weighted norm O_F(1/L). This also covers gaps inside the original full cluster hull and fills the use of26 in source§7.2.','explicit_fixed_Laurent_localization_qualification','audits/adversarial_reviews/director_rstation48_main_theorem_round6.md §7; threshold62_rstation48_main_theorem_skeptic.md; latest62_rst048_independent.md','theorems/rstation48_director_round6.jsonl');
INSERT INTO "claims" VALUES('THM-RST048-OPTIMAL','theorems/theorems.jsonl',397,'adjudicated_scoped_RH_conditional_source_theorem_with_explicit_local_qualification','RST048v2 Theorem1,equations1–78; director_rstation48_main_theorem_round6.md; Burnol math/0103058v2 Theorem1.3 printedp4','{"id": "THM-RST048-OPTIMAL", "paper_id": "PAPER-RST048", "claim_kind": "source_main_theorem_independently_reconstructed_with_local_qualification", "statement": "Assume RH. In the classical norm ||f||_*²=(2pi)^(-1)integral_R|f(1/2+it)|²/(1/4+t²)dt, letDelta_N²=inf_{A=sum_{n<=N}a_n n^-s}||1-zeta A||_*² with arbitrary complex coefficients; letd_N restrict the polynomial multiplying zeta toA(1)=0. Thenlim_N(logN)Delta_N²=lim_N(logN)d_N²=sum_{distinct nontrivialrho}m_rho²/|rho|², counting both ordinate signs.", "hypotheses": "RH only, together with its declared classical consequences; source main theorem reconstructed through78 with explicit fixed-Laurent qualification at§7.2. Burnol published lower bound accepted/rechecked in exact norm. Coefficients depend on zeros; no rate for a prescribed Mobius array, no unconditional RH conclusion, and no uniform conductor or effective finite-N rate.", "verification_scope": "Scoped Theorem1 reconstruction with fixed-Laurent qualification; Theorem5 fixed-prefix and Theorem6 finite-off-line source extensions now separately adjudicated. Whole-paperLevel1, notLevel2/3.", "locator": "RST048v2 Theorem1,equations1–78; director_rstation48_main_theorem_round6.md; Burnol math/0103058v2 Theorem1.3 printedp4", "status": "adjudicated_scoped_RH_conditional_source_theorem_with_explicit_local_qualification", "novelty_claim": false, "provenance_file": "theorems/rstation48_director_round6.jsonl", "status_update_evidence": "audits/adversarial_reviews/director_rst048_finite_exceptions_round9.md"}','PAPER-RST048','Assume RH. In the classical norm ||f||_*²=(2pi)^(-1)integral_R|f(1/2+it)|²/(1/4+t²)dt, letDelta_N²=inf_{A=sum_{n<=N}a_n n^-s}||1-zeta A||_*² with arbitrary complex coefficients; letd_N restrict the polynomial multiplying zeta toA(1)=0. Thenlim_N(logN)Delta_N²=lim_N(logN)d_N²=sum_{distinct nontrivialrho}m_rho²/|rho|², counting both ordinate signs.','source_main_theorem_independently_reconstructed_with_local_qualification','RST048v2 Theorem1,equations1–78; director_rstation48_main_theorem_round6.md; Burnol math/0103058v2 Theorem1.3 printedp4','theorems/rstation48_director_round6.jsonl');
INSERT INTO "claims" VALUES('THM-SCALAR62-M2','theorems/theorems.jsonl',398,'adjudicated_scoped; retain conditional/model/finite scope in statement','proposals/independent_campaigns/scalar62_two_term_extremum.md','{"id": "THM-SCALAR62-M2", "statement": "For the scalar reciprocal taper with M=2 and every positive integer degree m, the squared H2 residual is uniquely maximized up to common rotation at complete coalescence. Its maximum is B-1+4^(-m)m^2 B-2^(1-m)m binom(2m,m-1), with B=binom(2m,m).", "hypotheses": "All q_j unit, repetitions allowed; Q=prod(1-q_j z), A=1+2^(-m)(sum q_j)z; standard H2 coefficient-square norm.", "locator": "proposals/independent_campaigns/scalar62_two_term_extremum.md", "status": "adjudicated_scoped; retain conditional/model/finite scope in statement", "verification": "Independent proposer, skeptic and director reconstructions; explicit source inputs and limitations retained", "novelty": "unassessed_not_claimed", "arithmetic_transfer": "none", "paper_id": null, "provenance_file": "theorems/scalar62_two_term_extremum.jsonl", "verification_status": "No issue found in the inspected complete scoped argument; no whole-paper audit or publication novelty", "status_update_evidence": "audits/adversarial_reviews/director_round5_adjudication.md"}',NULL,'For the scalar reciprocal taper with M=2 and every positive integer degree m, the squared H2 residual is uniquely maximized up to common rotation at complete coalescence. Its maximum is B-1+4^(-m)m^2 B-2^(1-m)m binom(2m,m-1), with B=binom(2m,m).',NULL,'proposals/independent_campaigns/scalar62_two_term_extremum.md','theorems/scalar62_two_term_extremum.jsonl');
INSERT INTO "claims" VALUES('THM-SCALAR62-FIXED-M','theorems/theorems.jsonl',399,'adjudicated_scoped; retain conditional/model/finite scope in statement','proposals/independent_campaigns/scalar62_two_term_extremum.md, Fixed window lengths at sufficiently high degree','{"id": "THM-SCALAR62-FIXED-M", "statement": "For arbitrary integers m,M>=2, set L=m+M-1 and H=sum_(j=0)^(M-1) binom(m+j-1,j)(1-j/M)^m. If 4L^2(H^2-1)<1 then complete coalescence uniquely maximizes scalar reciprocal taper energy up to common rotation. In particular each fixed M is covered for all sufficiently large m.", "hypotheses": "All q_j unit, repetitions allowed; Q=prod(1-q_j z), A=sum_(j=0)^(M-1) ([z^j]Q^-1)(1-j/M)^m z^j; standard H2 coefficient-square norm.", "locator": "proposals/independent_campaigns/scalar62_two_term_extremum.md, Fixed window lengths at sufficiently high degree", "status": "adjudicated_scoped; retain conditional/model/finite scope in statement", "verification": "Independent proposer, skeptic and director reconstructions; explicit source inputs and limitations retained", "novelty": "unassessed_not_claimed", "arithmetic_transfer": "none", "paper_id": null, "provenance_file": "theorems/scalar62_two_term_extremum.jsonl", "verification_status": "No issue found in the inspected complete scoped argument; no whole-paper audit or publication novelty", "status_update_evidence": "audits/adversarial_reviews/director_round5_adjudication.md"}',NULL,'For arbitrary integers m,M>=2, set L=m+M-1 and H=sum_(j=0)^(M-1) binom(m+j-1,j)(1-j/M)^m. If 4L^2(H^2-1)<1 then complete coalescence uniquely maximizes scalar reciprocal taper energy up to common rotation. In particular each fixed M is covered for all sufficiently large m.',NULL,'proposals/independent_campaigns/scalar62_two_term_extremum.md, Fixed window lengths at sufficiently high degree','theorems/scalar62_two_term_extremum.jsonl');
INSERT INTO "claims" VALUES('LEM-E-W301','theorems/theorems.jsonl',400,'independently_checked_elementary_identity','proposals/independent_campaigns/unit_circle_scalar_window_round3.md§1','{"id": "LEM-E-W301", "paper_id": null, "statement": "With b^S_n=[z^n]product_(j inS)(1-q_jz)^-1 and negative indices0, Q applied to b^all_n w_n has coefficient w_n delta_(n0)+sum_(empty!=S subset{1..m})q_S h_(n-|S|)(q_j:j inS) Delta_backward^|S| w_n. Identity is exact for any scalar sequence w and each n>=0; repeated root labels are distinct indexed factors.", "hypotheses": "Finite indexed factor set; w any sequence defined at needed indices; negative reciprocal coefficient0.", "locator": "proposals/independent_campaigns/unit_circle_scalar_window_round3.md§1", "status": "independently_checked_elementary_identity", "review": "audits/adversarial_reviews/polynomial_window_third_round3.md", "novelty": "not_claimed", "provenance_file": "theorems/scalar_window_lemmas_round3.jsonl"}',NULL,'With b^S_n=[z^n]product_(j inS)(1-q_jz)^-1 and negative indices0, Q applied to b^all_n w_n has coefficient w_n delta_(n0)+sum_(empty!=S subset{1..m})q_S h_(n-|S|)(q_j:j inS) Delta_backward^|S| w_n. Identity is exact for any scalar sequence w and each n>=0; repeated root labels are distinct indexed factors.',NULL,'proposals/independent_campaigns/unit_circle_scalar_window_round3.md§1','theorems/scalar_window_lemmas_round3.jsonl');
INSERT INTO "claims" VALUES('LEM-E-W302','theorems/theorems.jsonl',401,'derived_exact_identity_independent_review_pending','proposals/independent_campaigns/scalar_window_coalescence_maximum_round3.md','{"id": "LEM-E-W302", "paper_id": null, "statement": "For three unit roots, S=sumq,P=productq,v=|S|²,u=Re(S³/P), Delta=product_(i<j)|q_i-q_j|², one has Delta=27−18v−v²+8u.", "hypotheses": "Exactly three unit roots, coincidences allowed.", "locator": "proposals/independent_campaigns/scalar_window_coalescence_maximum_round3.md", "status": "derived_exact_identity_independent_review_pending", "verification": "Cubic discriminant expansion; exact symbolic supplementary code.", "novelty": "classical_identity", "provenance_file": "theorems/scalar_window_lemmas_round3.jsonl"}',NULL,'For three unit roots, S=sumq,P=productq,v=|S|²,u=Re(S³/P), Delta=product_(i<j)|q_i-q_j|², one has Delta=27−18v−v²+8u.',NULL,'proposals/independent_campaigns/scalar_window_coalescence_maximum_round3.md','theorems/scalar_window_lemmas_round3.jsonl');
INSERT INTO "claims" VALUES('LEM-E-W303','theorems/theorems.jsonl',402,'previously_independently_checked_scoped_lemma','audits/adversarial_reviews/weighted_selberg_round2.md Hilbert-space identity and shrinking interval','{"id": "LEM-E-W303", "paper_id": null, "statement": "For any finite coefficient vector a_n supported1..N and fixed integerq>=1, C=sum a_n, d_q²=(2pi)^-1integral|1-zeta(s)sum a_n n^-s|²/|s|^(2q), one has d_q>=|C+2|/sqrtN−4pi²/(3^q sqrt5)N^-5/2.", "hypotheses": "N>=1, q>=1 integer, critical-line boundary measure dt/(2pi).", "locator": "audits/adversarial_reviews/weighted_selberg_round2.md Hilbert-space identity and shrinking interval", "status": "previously_independently_checked_scoped_lemma", "verification": "Unitary reflected Mellin identity; local linear term preserved by I^(q−1).", "novelty": "unassessed_not_claimed", "provenance_file": "theorems/scalar_window_lemmas_round3.jsonl"}',NULL,'For any finite coefficient vector a_n supported1..N and fixed integerq>=1, C=sum a_n, d_q²=(2pi)^-1integral|1-zeta(s)sum a_n n^-s|²/|s|^(2q), one has d_q>=|C+2|/sqrtN−4pi²/(3^q sqrt5)N^-5/2.',NULL,'audits/adversarial_reviews/weighted_selberg_round2.md Hilbert-space identity and shrinking interval','theorems/scalar_window_lemmas_round3.jsonl');
INSERT INTO "claims" VALUES('LEM-E-W304','theorems/theorems.jsonl',403,'derived_cutoff_lemma_independent_review_pending','proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md§2','{"id": "LEM-E-W304", "paper_id": null, "statement": "For fixedalpha>=0, Psi_alpha(x)=sum_(n<=x)mu(n)log(x/n)^alpha, one has |Psi_alpha(x)−Psi_alpha(floorx)|<=2 for0<alpha<1, <=1.5Gamma(alpha+1) foralpha>=1, and0 foralpha0 inclusive hard cutoff, when x>=2.", "hypotheses": "alpha fixedreal; alpha0 means inclusive ordinary summatory Möbius function; foralpha>0,0^alpha0.", "locator": "proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md§2", "status": "derived_cutoff_lemma_independent_review_pending", "verification": "Concavity with isolated n=N term foralpha<1; integral comparison foralpha>=1.", "novelty": "not_claimed", "provenance_file": "theorems/scalar_window_lemmas_round3.jsonl"}',NULL,'For fixedalpha>=0, Psi_alpha(x)=sum_(n<=x)mu(n)log(x/n)^alpha, one has |Psi_alpha(x)−Psi_alpha(floorx)|<=2 for0<alpha<1, <=1.5Gamma(alpha+1) foralpha>=1, and0 foralpha0 inclusive hard cutoff, when x>=2.',NULL,'proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md§2','theorems/scalar_window_lemmas_round3.jsonl');
INSERT INTO "claims" VALUES('LEM-E-W305','theorems/theorems.jsonl',404,'classical_transform_independently_reconstructed; extension_application_review_pending','proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md§3','{"id": "LEM-E-W305", "paper_id": null, "statement": "Foralpha>=0 real andRe(s)>1, integral_1^infty Psi_alpha(x)x^(-s-1)dx=Gamma(alpha+1)/(s^(alpha+1)zeta(s)), with principal Logs onRe(s)>0. A growth bound Psi=O(sqrtx(logx)^B), Bfixed, makes the left side analyticRe(s)>.5.", "hypotheses": "alpha0 hard cutoff as above; initial sum-integral interchange absolutely convergent.", "locator": "proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md§3", "status": "classical_transform_independently_reconstructed; extension_application_review_pending", "verification": "Substitute x=ny; integral logarithmic power isGamma(alpha+1)s^(-alpha-1).", "novelty": "classical_transform_not_new", "provenance_file": "theorems/scalar_window_lemmas_round3.jsonl"}',NULL,'Foralpha>=0 real andRe(s)>1, integral_1^infty Psi_alpha(x)x^(-s-1)dx=Gamma(alpha+1)/(s^(alpha+1)zeta(s)), with principal Logs onRe(s)>0. A growth bound Psi=O(sqrtx(logx)^B), Bfixed, makes the left side analyticRe(s)>.5.',NULL,'proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md§3','theorems/scalar_window_lemmas_round3.jsonl');
INSERT INTO "claims" VALUES('LEM-E-W306','theorems/theorems.jsonl',405,'classical_product_consequence_reconstructed_pending_review','proposals/independent_campaigns/growing_logarithmic_riesz_round3.md§2','{"id": "LEM-E-W306", "paper_id": null, "statement": "UnderRH, for0<epsilon<=1/8, |xi(.5+it)/xi(.5+epsilon+it)|<=1, and |zeta(.5+it)/zeta(.5+epsilon+it)|<=C(|t|+3)^(epsilon/2).", "hypotheses": "RH; multiplicities allowed; numerator zeros interpreted continuously.", "locator": "proposals/independent_campaigns/growing_logarithmic_riesz_round3.md§2", "status": "classical_product_consequence_reconstructed_pending_review", "verification": "Each paired factor squared modulus difference2epsilon²(gamma²+t²)+epsilon4>=0; uniformGamma completion ratio.", "novelty": "classical_consequence_no_claim", "provenance_file": "theorems/scalar_window_lemmas_round3.jsonl"}',NULL,'UnderRH, for0<epsilon<=1/8, |xi(.5+it)/xi(.5+epsilon+it)|<=1, and |zeta(.5+it)/zeta(.5+epsilon+it)|<=C(|t|+3)^(epsilon/2).',NULL,'proposals/independent_campaigns/growing_logarithmic_riesz_round3.md§2','theorems/scalar_window_lemmas_round3.jsonl');
INSERT INTO "claims" VALUES('LEM-E-W307','theorems/theorems.jsonl',406,'derived_kernel_lemma_pending_independent_review','proposals/independent_campaigns/growing_logarithmic_riesz_round3.md(G1)–(G3)','{"id": "LEM-E-W307", "paper_id": null, "statement": "Foralpha=epsilon L>=4,0<epsilon<=1,K(v)=Gamma(alpha+1)exp(alpha+iLv)/[2piL^alpha(epsilon+iv)^(alpha+1)] has complexmass1,L1<=3,and forfixedeta in(0,1],delta in(0,1/8], integral_|v|>etaepsilon |K(v)|(3+|v|)^delta dv<=C_delta sqrtalpha exp(-alpha log(1+eta²)/4).", "hypotheses": "Positivealpha,epsilon,L withalpha=epsilonL; principalLog onRew>0.", "locator": "proposals/independent_campaigns/growing_logarithmic_riesz_round3.md(G1)–(G3)", "status": "derived_kernel_lemma_pending_independent_review", "verification": "InverseLaplace scalar mass,Stirling and scaled Student-type density; globaltailnot merelylocalGaussian.", "novelty": "unassessed_not_claimed", "provenance_file": "theorems/scalar_window_lemmas_round3.jsonl"}',NULL,'Foralpha=epsilon L>=4,0<epsilon<=1,K(v)=Gamma(alpha+1)exp(alpha+iLv)/[2piL^alpha(epsilon+iv)^(alpha+1)] has complexmass1,L1<=3,and forfixedeta in(0,1],delta in(0,1/8], integral_|v|>etaepsilon |K(v)|(3+|v|)^delta dv<=C_delta sqrtalpha exp(-alpha log(1+eta²)/4).',NULL,'proposals/independent_campaigns/growing_logarithmic_riesz_round3.md(G1)–(G3)','theorems/scalar_window_lemmas_round3.jsonl');
INSERT INTO "claims" VALUES('EXT-TITCH-1986-9.6A','theorems/theorems.jsonl',407,'established_source_passage_targeted_read','Titchmarsh1986printedp217,Eq9.6.1;PDF113','{"id": "EXT-TITCH-1986-9.6A", "paper_id": "PAPER-M001", "statement": "At large positiveheight, zeta_prime/zeta(s)=sum_(|t-gamma|<=1)1/(s-rho)+O(logt), uniformly−1<=sigma<=2, excluding its actual poles.", "hypotheses": "Zeros countedwithmultiplicity;sourceTheorem9.6(A);negativeheights byconjugation;smallheight extension separately reconstructed inapplication.", "locator": "Titchmarsh1986printedp217,Eq9.6.1;PDF113", "status": "established_source_passage_targeted_read", "verification": "Actualscannedstatement anddisplayedproofvisuallyread2026-11-17;localcountTheorem9.2 acceptedclassicalinput.", "source_file": "sources/equivalence_round2/titchmarsh1986.pdf", "source_image": "sources/logarithmic_riesz_round3/titchmarsh_216217.png", "novelty": "published_classical_source", "provenance_file": "theorems/scalar_window_lemmas_round3.jsonl"}','PAPER-M001','At large positiveheight, zeta_prime/zeta(s)=sum_(|t-gamma|<=1)1/(s-rho)+O(logt), uniformly−1<=sigma<=2, excluding its actual poles.',NULL,'Titchmarsh1986printedp217,Eq9.6.1;PDF113','theorems/scalar_window_lemmas_round3.jsonl');
INSERT INTO "claims" VALUES('THM-E-W301','theorems/theorems.jsonl',408,'proved_elementary_finite_bound','proposals/independent_campaigns/unit_circle_scalar_window_round3.md §§1–3','{"paper_id": null, "novelty": "unassessed_not_claimed", "date": "2026-11-17", "arithmetic_transfer": "none unless explicitly stated", "id": "THM-E-W301", "statement": "For p=m, E<=C_m²/M+sum_(r=1..m-1)T_mr²/M²<=K_m/M, C_m=m binom(2m-1,m-1), T_mr=sum_(j=r+1..m)binom(m,j)(j-r)^m, K_m=C_m²+sum T_mr². Exact twisted finite-difference identity supplies cancellation and all bounds are uniform in roots/collisions.", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics.", "locator": "proposals/independent_campaigns/unit_circle_scalar_window_round3.md §§1–3", "status": "proved_elementary_finite_bound", "verification": "self_contained_proof; independent third reconstruction and root review; exact rational supplementary checks", "review": "audits/adversarial_reviews/polynomial_window_third_round3.md", "experiments": ["experiments/code/unit_circle_scalar_window_round3.py", "experiments/results/unit_circle_scalar_window_round3.json"], "provenance_file": "theorems/scalar_window_round3.jsonl"}',NULL,'For p=m, E<=C_m²/M+sum_(r=1..m-1)T_mr²/M²<=K_m/M, C_m=m binom(2m-1,m-1), T_mr=sum_(j=r+1..m)binom(m,j)(j-r)^m, K_m=C_m²+sum T_mr². Exact twisted finite-difference identity supplies cancellation and all bounds are uniform in roots/collisions.',NULL,'proposals/independent_campaigns/unit_circle_scalar_window_round3.md §§1–3','theorems/scalar_window_round3.jsonl');
INSERT INTO "claims" VALUES('THM-E-W302','theorems/theorems.jsonl',409,'proved_exact_finite_identity','proposals/independent_campaigns/unit_circle_scalar_window_round3.md §6','{"paper_id": null, "novelty": "unassessed_not_claimed", "date": "2026-11-17", "arithmetic_transfer": "none unless explicitly stated", "id": "THM-E-W302", "statement": "For m=p=2, after common rotation Q=(1-z)(1-qz), E(1)-E(q)=2/M^4 sum_(k=1..M)(M-k+1)(2(M-k)+1)(1-Re(q^k))>=0. E(1)=4/M+3/M²-2/M³<=5/M; constant5 is sharp over all M, at M1 or2 and q1; complete coalescence is the unique maximum modulo common rotation.", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics. Here m=p=2.", "locator": "proposals/independent_campaigns/unit_circle_scalar_window_round3.md §6", "status": "proved_exact_finite_identity", "verification": "exact autocorrelation reconstruction independently checked by semantic_skeptic and root", "review": "audits/adversarial_reviews/polynomial_window_third_round3.md", "provenance_file": "theorems/scalar_window_round3.jsonl"}',NULL,'For m=p=2, after common rotation Q=(1-z)(1-qz), E(1)-E(q)=2/M^4 sum_(k=1..M)(M-k+1)(2(M-k)+1)(1-Re(q^k))>=0. E(1)=4/M+3/M²-2/M³<=5/M; constant5 is sharp over all M, at M1 or2 and q1; complete coalescence is the unique maximum modulo common rotation.',NULL,'proposals/independent_campaigns/unit_circle_scalar_window_round3.md §6','theorems/scalar_window_round3.jsonl');
INSERT INTO "claims" VALUES('THM-E-W303','theorems/theorems.jsonl',410,'proved_fixed_m_asymptotic','proposals/independent_campaigns/unit_circle_scalar_window_round3.md §4','{"paper_id": null, "novelty": "unassessed_not_claimed", "date": "2026-11-17", "arithmetic_transfer": "none unless explicitly stated", "id": "THM-E-W303", "statement": "At complete coalescence Q=(1-qz)^m and p=m, E=m²/M+O_m(M^-2). Thus this prescribed scalar window has the same leading m² as the known optimal approximation; exact finite optimality is not asserted.", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics. Complete coalescence; p=m.", "locator": "proposals/independent_campaigns/unit_circle_scalar_window_round3.md §4", "status": "proved_fixed_m_asymptotic", "verification": "finite differences, polynomial expansion and endpoint reproducing identity checked independently", "review": "audits/adversarial_reviews/polynomial_window_third_round3.md", "source_context": ["THM-E003", "PAPER-E002"], "provenance_file": "theorems/scalar_window_round3.jsonl"}',NULL,'At complete coalescence Q=(1-qz)^m and p=m, E=m²/M+O_m(M^-2). Thus this prescribed scalar window has the same leading m² as the known optimal approximation; exact finite optimality is not asserted.',NULL,'proposals/independent_campaigns/unit_circle_scalar_window_round3.md §4','theorems/scalar_window_round3.jsonl');
INSERT INTO "claims" VALUES('THM-E-W304','theorems/theorems.jsonl',411,'proved_real_taper_threshold','proposals/independent_campaigns/fractional_scalar_threshold_round3.md §§1–4','{"paper_id": null, "novelty": "unassessed_not_claimed", "date": "2026-11-17", "arithmetic_transfer": "none unless explicitly stated", "id": "THM-E-W304", "statement": "A collision-uniform E<=C_(m,p)/M for every M and all roots exists iff p>m-1/2. At equality E=O_m((1+logM)/M) uniformly and complete coalescence gives Ω_m(logM/M). For p<m-1/2 the exact terminal coefficient at coalescence rules out O(1/M).", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics. p>=0 real.", "locator": "proposals/independent_campaigns/fractional_scalar_threshold_round3.md §§1–4", "status": "proved_real_taper_threshold", "verification": "semantic_skeptic proof independently challenged by equivalences; endpoint j0 handled by finite sum, not singular derivative", "review": "audits/adversarial_reviews/fractional_scalar_threshold_equivalences_round3.md", "proposer": "semantic_skeptic", "provenance_file": "theorems/scalar_window_round3.jsonl"}',NULL,'A collision-uniform E<=C_(m,p)/M for every M and all roots exists iff p>m-1/2. At equality E=O_m((1+logM)/M) uniformly and complete coalescence gives Ω_m(logM/M). For p<m-1/2 the exact terminal coefficient at coalescence rules out O(1/M).',NULL,'proposals/independent_campaigns/fractional_scalar_threshold_round3.md §§1–4','theorems/scalar_window_round3.jsonl');
INSERT INTO "claims" VALUES('THM-E-W305','theorems/theorems.jsonl',412,'proved_fixed_m_critical_asymptotic','proposals/independent_campaigns/fractional_scalar_critical_constant_round3.md','{"paper_id": null, "novelty": "unassessed_not_claimed", "date": "2026-11-17", "arithmetic_transfer": "none unless explicitly stated", "id": "THM-E-W305", "statement": "At complete coalescence and critical real power p=m-1/2, E=kappa_m² logM/M+O_m(1/M), kappa_m=m binom(2m,m)/4^m.", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics. Complete coalescence; p=m-1/2.", "locator": "proposals/independent_campaigns/fractional_scalar_critical_constant_round3.md", "status": "proved_fixed_m_critical_asymptotic", "verification": "independent semantic_skeptic reconstruction including uniform M/4 interior bound and summable errors", "review": "audits/adversarial_reviews/fractional_critical_leading_skeptic_round3.md", "provenance_file": "theorems/scalar_window_round3.jsonl"}',NULL,'At complete coalescence and critical real power p=m-1/2, E=kappa_m² logM/M+O_m(1/M), kappa_m=m binom(2m,m)/4^m.',NULL,'proposals/independent_campaigns/fractional_scalar_critical_constant_round3.md','theorems/scalar_window_round3.jsonl');
INSERT INTO "claims" VALUES('THM-E-W306','theorems/theorems.jsonl',413,'derived_exact_finite_case_independent_review_pending','proposals/independent_campaigns/scalar_window_coalescence_maximum_round3.md §Exact three-root example','{"paper_id": null, "novelty": "unassessed_not_claimed", "date": "2026-11-17", "arithmetic_transfer": "none unless explicitly stated", "id": "THM-E-W306", "statement": "For m=p=3,M=2, write Delta=product_(i<j)|q_i-q_j|². Then E(coalesced)-E(qs)=[31 sum_(i<j)|q_i-q_j|²+Delta]/32>=0. Equality iff all roots equal.", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics. m=p=3,M=2 only.", "locator": "proposals/independent_campaigns/scalar_window_coalescence_maximum_round3.md §Exact three-root example", "status": "derived_exact_finite_case_independent_review_pending", "verification": "exact residual expansion and cubic discriminant identity; general m/M maximum remains unproved", "experiments": ["experiments/code/scalar_window_m3_invariants_round3.py"], "provenance_file": "theorems/scalar_window_round3.jsonl"}',NULL,'For m=p=3,M=2, write Delta=product_(i<j)|q_i-q_j|². Then E(coalesced)-E(qs)=[31 sum_(i<j)|q_i-q_j|²+Delta]/32>=0. Equality iff all roots equal.',NULL,'proposals/independent_campaigns/scalar_window_coalescence_maximum_round3.md §Exact three-root example','theorems/scalar_window_round3.jsonl');
INSERT INTO "claims" VALUES('THM-E-W307','theorems/theorems.jsonl',414,'derived_necessary_condition_independent_review_pending','proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §§1–3','{"paper_id": null, "novelty": "unassessed_not_claimed", "date": "2026-11-17", "arithmetic_transfer": "none unless explicitly stated", "id": "THM-E-W307", "statement": "If d_q(V_(N,alpha))->0, RH holds and every nontrivial zero multiplicity satisfies m<alpha+1. Thus alpha0 convergence is impossible; for alpha>0, m<=ceil(alpha). Real-cutoff interpolation |Psi_alpha(x)-Psi_alpha(floor x)|=O_alpha(1) is valid even for0<alpha<1.", "hypotheses": "Fixed alpha>=0 real, fixed integer q>=1, integer N>=2; V=sum_(n<=N)mu(n)(1-logn/logN)^alpha n^-s; alpha0 uses inclusive hard cutoff; d_q²=(2pi)^-1 integral_R |1-zeta(.5+it)V(.5+it)|²/|.5+it|^(2q)dt. Full-sequence convergence, not merely a subsequence.", "locator": "proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §§1–3", "status": "derived_necessary_condition_independent_review_pending", "verification": "exact local coefficient witness plus Mellin identity and Abelian pole-order argument; cutoff endpoint checked; parent review requested", "dependencies": ["audits/adversarial_reviews/weighted_selberg_round2.md", "PAPER-C105", "PAPER-M002", "PAPER-E011"], "provenance_file": "theorems/scalar_window_round3.jsonl"}',NULL,'If d_q(V_(N,alpha))->0, RH holds and every nontrivial zero multiplicity satisfies m<alpha+1. Thus alpha0 convergence is impossible; for alpha>0, m<=ceil(alpha). Real-cutoff interpolation |Psi_alpha(x)-Psi_alpha(floor x)|=O_alpha(1) is valid even for0<alpha<1.',NULL,'proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §§1–3','theorems/scalar_window_round3.jsonl');
INSERT INTO "claims" VALUES('THM-E-W308','theorems/theorems.jsonl',415,'derived_quantitative_necessary_condition_independent_review_pending','proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §4','{"paper_id": null, "novelty": "unassessed_not_claimed", "date": "2026-11-17", "arithmetic_transfer": "none unless explicitly stated", "id": "THM-E-W308", "statement": "For every critical zero rho of multiplicitym, limsup_N d_q(V_(N,alpha))/(logN)^(m-alpha-1)>=m Gamma(alpha+1)/[|rho|^(alpha+1)|zeta^(m)(rho)|]. Infinite limsup is allowed; finite limsup itself supplies the zero-free open half-plane needed for the Mellin argument.", "hypotheses": "Fixed alpha>=0 real, fixed integer q>=1, integer N>=2; V=sum_(n<=N)mu(n)(1-logn/logN)^alpha n^-s; alpha0 uses inclusive hard cutoff; d_q²=(2pi)^-1 integral_R |1-zeta(.5+it)V(.5+it)|²/|.5+it|^(2q)dt. Full-sequence convergence, not merely a subsequence. rho=1/2+i gamma a zero of multiplicitym>=1.", "locator": "proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §4", "status": "derived_quantitative_necessary_condition_independent_review_pending", "verification": "pole coefficient m! compared with Abelian Gamma(m), using norm not norm-square; no independent RH premise", "dependencies": ["THM-E-W307"], "provenance_file": "theorems/scalar_window_round3.jsonl"}',NULL,'For every critical zero rho of multiplicitym, limsup_N d_q(V_(N,alpha))/(logN)^(m-alpha-1)>=m Gamma(alpha+1)/[|rho|^(alpha+1)|zeta^(m)(rho)|]. Infinite limsup is allowed; finite limsup itself supplies the zero-free open half-plane needed for the Mellin argument.',NULL,'proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §4','theorems/scalar_window_round3.jsonl');
INSERT INTO "claims" VALUES('THM-E-W309','theorems/theorems.jsonl',416,'classical_source_specialization','PAPER-M002 Theorem39/Lemma10 p50 and shifted Eq(2)p51; campaign Eq(7)','{"paper_id": "PAPER-M002", "novelty": "unassessed_not_claimed", "date": "2026-11-17", "arithmetic_transfer": "none unless explicitly stated", "id": "THM-E-W309", "statement": "For alpha>0,L=logN, and c>max(0,1-Re(s)), V_(N,alpha)(s)=Gamma(alpha+1)/(2pi i L^alpha) integral_(Re w=c) exp(Lw)/[w^(alpha+1)zeta(s+w)]dw; principal Logw on Rew>0, absolutely convergent initial line, endpoint n=N contributes0.", "hypotheses": "Fixed alpha>=0 real, fixed integer q>=1, integer N>=2; V=sum_(n<=N)mu(n)(1-logn/logN)^alpha n^-s; alpha0 uses inclusive hard cutoff; d_q²=(2pi)^-1 integral_R |1-zeta(.5+it)V(.5+it)|²/|.5+it|^(2q)dt. Full-sequence convergence, not merely a subsequence. alpha>0 and initial contour c>max(0,1-Re(s)).", "locator": "PAPER-M002 Theorem39/Lemma10 p50 and shifted Eq(2)p51; campaign Eq(7)", "status": "classical_source_specialization", "verification": "source visually inspected; absolute initial-line interchange independently reconstructed; no critical-line contour shift claimed", "source_locator": "Printedpp50–51,Theorem39,Lemma10,Eq(2)", "provenance_file": "theorems/scalar_window_round3.jsonl"}','PAPER-M002','For alpha>0,L=logN, and c>max(0,1-Re(s)), V_(N,alpha)(s)=Gamma(alpha+1)/(2pi i L^alpha) integral_(Re w=c) exp(Lw)/[w^(alpha+1)zeta(s+w)]dw; principal Logw on Rew>0, absolutely convergent initial line, endpoint n=N contributes0.',NULL,'PAPER-M002 Theorem39/Lemma10 p50 and shifted Eq(2)p51; campaign Eq(7)','theorems/scalar_window_round3.jsonl');
INSERT INTO "claims" VALUES('THM-E-W310','theorems/theorems.jsonl',417,'derived_finite_convergence_threshold_independent_review_pending','proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §5; fractional_scalar_threshold_round3.md §§1–3','{"paper_id": null, "novelty": "unassessed_not_claimed", "date": "2026-11-17", "arithmetic_transfer": "none unless explicitly stated", "id": "THM-E-W310", "statement": "The supremum over all unit-root configurations of E_(M,p) tends to0 iff p>m-1. For m-1<p<m-1/2, E=O_(m,p)(M^(-2(p-m+1))); at p=m-1/2, O_m(logM/M); above it, O_(m,p)(1/M). At p<=m-1 complete coalescence terminal coefficient prevents convergence.", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics. p>=0 real; uniformity only for fixedm,p.", "locator": "proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §5; fractional_scalar_threshold_round3.md §§1–3", "status": "derived_finite_convergence_threshold_independent_review_pending", "verification": "same explicit positive falling-factor difference estimate applies for p>m-1; terminal coefficient proves necessity", "provenance_file": "theorems/scalar_window_round3.jsonl"}',NULL,'The supremum over all unit-root configurations of E_(M,p) tends to0 iff p>m-1. For m-1<p<m-1/2, E=O_(m,p)(M^(-2(p-m+1))); at p=m-1/2, O_m(logM/M); above it, O_(m,p)(1/M). At p<=m-1 complete coalescence terminal coefficient prevents convergence.',NULL,'proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §5; fractional_scalar_threshold_round3.md §§1–3','theorems/scalar_window_round3.jsonl');
INSERT INTO "claims" VALUES('THM-E-W312','theorems/theorems.jsonl',418,'adjudicated_scoped_conditional_or_model_theorem','proposals/independent_campaigns/growing_logarithmic_riesz_round3.md (G1)–(G6)','{"id": "THM-E-W312", "paper_id": null, "statement": "For EVERY fixedc>0 and integerq>=1, RH implies d_q(V_(N,c))->0 for the prescribed Mobius array with epsilon_N=c/loglogN and logarithmic Riesz orderalpha_N=epsilon_N logN; the arbitrary-finite-array Hardy witness proves the converse. Thus convergence is equivalent to RH for each fixedc. No spacing, simplicity or derivative-moment hypothesis. Constants/N0 may dependonc,q; no movingc_N orq_N claim.", "hypotheses": "RH for forward direction; sufficiently large integersN; alpha_N>0, endpointn=N weight0; fixedc>0,q>=1integer; sourced classical RH inverse/log-derivative inputs; freeauxiliary finite-height exponentr chosenafterfixedc.", "locator": "proposals/independent_campaigns/growing_logarithmic_riesz_round3.md (G1)–(G6)", "status": "adjudicated_scoped_conditional_or_model_theorem", "verification": "adjudicated_scoped; independent proposer/skeptic/director reconstructions; exact external-source and model/conditional boundaries retained", "novelty": "unassessed_not_claimed", "source_provenance": ["PAPER-M002Theorem39/Lemma10pp50–51", "PAPER-M001Theorem9.6(A),Eq9.6.1p217,visuallyinspectedPDF113", "THM-E-D202 and uniformPerron audit source-region bridge", "RH pairedHadamardproduct comparison reconstructed inproof"], "review": "audits/adversarial_reviews/growing_logarithmic_riesz_skeptic_round4.md", "date": "2026-11-17", "proposed_strengthening": "For EACH fixedc>0, the same RH-conditional convergence follows by using finite-heightbound distancea/loglogV witha=c/2 and freeauxiliaryV=|t+v|+N^r+3,r<kappa_eta c/(8K_a). Constants,N0 dependonc; no uniformasc->0 or movingc assertion.", "strengthening_locator": "proposals/independent_campaigns/growing_logarithmic_riesz_round3.md§4,(G7)–(G8)", "strengthening_verification": "root independently proposed free-r refinement; equivalences checked parameter geometry; independent skeptical review pending", "review_status": "Independentli_skepticreconstructioncheckedallfixedc>0addendumwithactualTitchsources; rootadjudicationseparate.", "provenance_file": "theorems/scalar_window_round3.jsonl", "verification_status": "adjudicated_scoped; ordinary proof, not a whole-paper audit or unconditional zeta moment theorem", "accepted_strengthening": "Every fixedc>0, replacing the first sufficient-largec proof; exact free-r argument independently verified.", "status_update_evidence": "audits/adversarial_reviews/director_sine_riesz_round4.md"}',NULL,'For EVERY fixedc>0 and integerq>=1, RH implies d_q(V_(N,c))->0 for the prescribed Mobius array with epsilon_N=c/loglogN and logarithmic Riesz orderalpha_N=epsilon_N logN; the arbitrary-finite-array Hardy witness proves the converse. Thus convergence is equivalent to RH for each fixedc. No spacing, simplicity or derivative-moment hypothesis. Constants/N0 may dependonc,q; no movingc_N orq_N claim.',NULL,'proposals/independent_campaigns/growing_logarithmic_riesz_round3.md (G1)–(G6)','theorems/scalar_window_round3.jsonl');
