INSERT INTO "claims" VALUES('LEM-SELBERG-COMPLEMENT-L2','theorems/theorems.jsonl',422,'adjudicated_scoped_GRH_conditional_lemma','audits/adversarial_reviews/director_selberg_transfer_round6.md §2; independentlyderivedtestedMellinproofs','{"id": "LEM-SELBERG-COMPLEMENT-L2", "paper_id": null, "claim_kind": "proved_conditional_distributional_Mellin_identification", "statement": "ForfixedSelbergFunderthestatedGRH, definepsi_F(t)=Res_(s=1)[F(s)t^-s/s]-sum_{n<=1/t}a_n forallt>0. Thenpsi_FisinL²(dt)anditscritical-lineL²Mellintransformis-F(s)/s. Acompactlog-testcontourshiftandGRHsubpowerboundproveitatarbitraryfixeddegree/poleorder. Theresiduetailfort>1mustberetained.", "locator": "audits/adversarial_reviews/director_selberg_transfer_round6.md §2; independentlyderivedtestedMellinproofs", "status": "adjudicated_scoped_GRH_conditional_lemma", "novelty_claim": false, "provenance_file": "theorems/selberg_director_round6.jsonl"}',NULL,'ForfixedSelbergFunderthestatedGRH, definepsi_F(t)=Res_(s=1)[F(s)t^-s/s]-sum_{n<=1/t}a_n forallt>0. Thenpsi_FisinL²(dt)anditscritical-lineL²Mellintransformis-F(s)/s. Acompactlog-testcontourshiftandGRHsubpowerboundproveitatarbitraryfixeddegree/poleorder. Theresiduetailfort>1mustberetained.','proved_conditional_distributional_Mellin_identification','audits/adversarial_reviews/director_selberg_transfer_round6.md §2; independentlyderivedtestedMellinproofs','theorems/selberg_director_round6.jsonl');
INSERT INTO "claims" VALUES('THM-C101-Q4','theorems/theorems.jsonl',423,'source_open_question_1998','§5 Question4, printedp7','{"id": "THM-C101-Q4", "paper_id": "PAPER-C101", "locator": "§5 Question4, printedp7", "statement": "Assuming RH, does η_N²=(1/2π)∫|1−ζ(1/2+it)Σ_{n≤N}μ(n)(1−logn/logN)n^(−1/2−it)|²dt/(1/4+t²) tend to0?", "status": "source_open_question_1998", "verification": "actual primary passage read; later2022 paper restates as open", "provenance_file": "theorems/selberg_round2.jsonl"}','PAPER-C101','Assuming RH, does η_N²=(1/2π)∫|1−ζ(1/2+it)Σ_{n≤N}μ(n)(1−logn/logN)n^(−1/2−it)|²dt/(1/4+t²) tend to0?',NULL,'§5 Question4, printedp7','theorems/selberg_round2.jsonl');
INSERT INTO "claims" VALUES('THM-C103-P1P3','theorems/theorems.jsonl',424,'established_source_result','Propositions1–3, printedpp4–5','{"id": "THM-C103-P1P3", "paper_id": "PAPER-C103", "locator": "Propositions1–3, printedpp4–5", "statement": "UnderRH the shifted-array squared error ν_(N,ε) is at most2I_(N,ε)+2J_ε, with J_ε≪ε and I_(N,ε)≪N^(−ε/2) for ε≥25(loglogN)^(5/2+δ)(logN)^(−1/2), N≥N0(δ).", "hypotheses": ["δ>0 fixed", "ε>0", "RH for bounds on I and J"], "status": "established_source_result", "verification": "Proposition1 proof reconstructed; technical proof of propositions2–3 not fully audited", "provenance_file": "theorems/selberg_round2.jsonl"}','PAPER-C103','UnderRH the shifted-array squared error ν_(N,ε) is at most2I_(N,ε)+2J_ε, with J_ε≪ε and I_(N,ε)≪N^(−ε/2) for ε≥25(loglogN)^(5/2+δ)(logN)^(−1/2), N≥N0(δ).',NULL,'Propositions1–3, printedpp4–5','theorems/selberg_round2.jsonl');
INSERT INTO "claims" VALUES('THM-C105-1','theorems/theorems.jsonl',425,'established_source_result','Proposition1.9 p7; proofpp27–28; Remark5.8p29','{"id": "THM-C105-1", "paper_id": "PAPER-C105", "locator": "Proposition1.9 p7; proofpp27–28; Remark5.8p29", "statement": "For the prescribed Selberg V_N(s)=Σ_{n≤N}μ(n)(1−logn/logN)n^(−s), if η_N²=(1/2π)∫_R|1−ζ(1/2+it)V_N(1/2+it)|²dt/(1/4+t²) tends to0, then RH holds and every nontrivial zero of ζ is simple.", "hypotheses": ["N→∞ through positive integers", "full critical-line integral, not truncated", "exact fixed coefficient array"], "status": "established_source_result", "verification": "independently reconstructed by reviewer before prior source located; parent reconstructed unitary, small-interval and pole steps independently; no novelty claim", "provenance_file": "theorems/selberg_round2.jsonl"}','PAPER-C105','For the prescribed Selberg V_N(s)=Σ_{n≤N}μ(n)(1−logn/logN)n^(−s), if η_N²=(1/2π)∫_R|1−ζ(1/2+it)V_N(1/2+it)|²dt/(1/4+t²) tends to0, then RH holds and every nontrivial zero of ζ is simple.',NULL,'Proposition1.9 p7; proofpp27–28; Remark5.8p29','theorems/selberg_round2.jsonl');
INSERT INTO "claims" VALUES('THM-C105-2','theorems/theorems.jsonl',426,'established_source_result','Theorem1.10 p7','{"id": "THM-C105-2", "paper_id": "PAPER-C105", "locator": "Theorem1.10 p7", "statement": "RH iff the same prescribed Selberg error integral on every fixed vertical line Re(s)=τ′ with1/2<τ′<1 tends to0. Boundedness of the full boundary-line prescribed error sequence impliesRH.", "status": "established_source_result", "verification": "statement read; proof not fully independently audited; shifted-line quantifier preserved", "provenance_file": "theorems/selberg_round2.jsonl"}','PAPER-C105','RH iff the same prescribed Selberg error integral on every fixed vertical line Re(s)=τ′ with1/2<τ′<1 tends to0. Boundedness of the full boundary-line prescribed error sequence impliesRH.',NULL,'Theorem1.10 p7','theorems/selberg_round2.jsonl');
INSERT INTO "claims" VALUES('LEM-C105-U','theorems/theorems.jsonl',427,'independently_reconstructed_prior_method','independent reconstruction in audits/selberg_provenance_round2.md, consistent with Wei–Wu unitaryproofpp27–28 and Conrey–MyersonProp1','{"id": "LEM-C105-U", "paper_id": "PAPER-C105", "related_paper_ids": ["PAPER-C102"], "locator": "independent reconstruction in audits/selberg_provenance_round2.md, consistent with Wei–Wu unitaryproofpp27–28 and Conrey–MyersonProp1", "statement": "For real finite coefficients b_n and A(s)=Σb_n n^(−s), define W(u)=Σb_n{nu}/n and g(u)=−sin(2πu)/π. Then ||(1−ζA)/s||²_(critical line,d t/2π)=||W−g||²_(L²(du/u²)).", "status": "independently_reconstructed_prior_method", "verification": "functional equation and Mellin sine transform checked; parent independently reconstructed", "provenance_file": "theorems/selberg_round2.jsonl"}','PAPER-C105','For real finite coefficients b_n and A(s)=Σb_n n^(−s), define W(u)=Σb_n{nu}/n and g(u)=−sin(2πu)/π. Then ||(1−ζA)/s||²_(critical line,d t/2π)=||W−g||²_(L²(du/u²)).',NULL,'independent reconstruction in audits/selberg_provenance_round2.md, consistent with Wei–Wu unitaryproofpp27–28 and Conrey–MyersonProp1','theorems/selberg_round2.jsonl');
INSERT INTO "claims" VALUES('LEM-C105-Q1','theorems/theorems.jsonl',428,'derived_elementary_corollary_no_novelty_claim','derived quantitative corollaries in audits/selberg_provenance_round2.md','{"id": "LEM-C105-Q1", "paper_id": "PAPER-C105", "locator": "derived quantitative corollaries in audits/selberg_provenance_round2.md", "statement": "For fixed Selberg error η_N and C_N=Σμ(n)(1−logn/logN), η_N≥|C_N+2|/sqrtN−4π²/(3sqrt5)N^(−5/2). If a critical-line zeroρ has multiplicitym≥2, limsup η_N/(logN)^(m−2)≥m/(|ρ|²|ζ^(m)(ρ)|).", "status": "derived_elementary_corollary_no_novelty_claim", "verification": "reviewer derivation complete; parent independently checked double-zero constant and small-interval form; general-m coefficient submitted for review", "limitations": ["not optimized distance d_N", "no multiple zero is asserted to exist", "priority search incomplete"], "provenance_file": "theorems/selberg_round2.jsonl"}','PAPER-C105','For fixed Selberg error η_N and C_N=Σμ(n)(1−logn/logN), η_N≥|C_N+2|/sqrtN−4π²/(3sqrt5)N^(−5/2). If a critical-line zeroρ has multiplicitym≥2, limsup η_N/(logN)^(m−2)≥m/(|ρ|²|ζ^(m)(ρ)|).',NULL,'derived quantitative corollaries in audits/selberg_provenance_round2.md','theorems/selberg_round2.jsonl');
INSERT INTO "claims" VALUES('THM-E-W311','theorems/theorems.jsonl',429,'independent_review_passed_director_adjudication_pending','proposals/independent_campaigns/coalescence_maximum_semantic_round3.md §1','{"id": "THM-E-W311", "paper_id": null, "date": "2026-11-17", "kind": "exact_finite_scalar_window_extremum", "hypotheses": "Four complex unit factors q1,...,q4, with arbitrary collisions; Q=product(1-qj z); b_n=[z^n]1/Q; M=2 and integer taper powerp=4, A=1+(q1+...+q4)z/16; E=||1-QA||_H2^2 with normalized coefficient-square norm.", "statement": "E<=363/8, attained iff all four factors coincide. In fact363/8-E=(16-|e1|^2)(131-7|e1|^2)/128+(36-|e2|^2)(3/4+|e1|^2/256)+(16-|sum_j qj^2|^2)/16, and all terms are nonnegative.", "locator": "proposals/independent_campaigns/coalescence_maximum_semantic_round3.md §1", "verification": "Independent residual/Newton/gap reconstruction by equivalences; exact identity tested on100 rational-complex phase configurations. Director adjudication pending. General-m/M maximum not claimed.", "review": "audits/adversarial_reviews/coalescence_m4_equivalences_round3.md", "status": "independent_review_passed_director_adjudication_pending", "experiments": ["experiments/code/coalescence_maximum_semantic_round3.py", "experiments/results/coalescence_maximum_semantic_round3.json"], "novelty": "unassessed_not_claimed", "arithmetic_transfer": "none", "provenance_file": "theorems/semantic_finite_cases_round3.jsonl"}',NULL,'E<=363/8, attained iff all four factors coincide. In fact363/8-E=(16-|e1|^2)(131-7|e1|^2)/128+(36-|e2|^2)(3/4+|e1|^2/256)+(16-|sum_j qj^2|^2)/16, and all terms are nonnegative.','exact_finite_scalar_window_extremum','proposals/independent_campaigns/coalescence_maximum_semantic_round3.md §1','theorems/semantic_finite_cases_round3.jsonl');
INSERT INTO "claims" VALUES('THM-SG309','theorems/theorems.jsonl',430,'adjudicated_scoped_conditional_or_model_theorem','["proposals/independent_campaigns/sine_gram_moment_existence_round4.md", "audits/adversarial_reviews/sine_gram_moment_existence_third_round3.md", "audits/adversarial_reviews/sine_gram_skeptic_round4.md"]','{"id": "THM-SG309", "kind": "sine_Gram_all_expected_moment_limits_and_full_law", "statement": "For the unit-intensity sine determinantal point process with kernel k(x)=sin(pi*x)/(pi*x), S_R its sinc-Gram matrix on [0,R], and mu_R=R^(-1) E sum_j delta_(lambda_j(S_R)), every fixed nonnegative integer moment has a finite limit as R tends to infinity. These limits have the absolutely convergent anchored partition-integral formula in the cited proof. The deterministic expected per-length laws mu_R consequently converge weakly to a unique probability law, which has no atom at zero, is moment determinate, and has a positive exponential moment.", "hypotheses": "Stationary sine DPP on the full real line; intensity one; expected per-length law, not random point-count normalization. Moment order is fixed before R tends to infinity. No arithmetic moment-matching hypothesis is established.", "proof_dependencies": ["THM-SG302 factorial bound and Carleman", "THM-SG303 zero-atom exclusion", "Closed trace-cycle quotient is a connected Eulerian multigraph; after removal of loops it has no bridges", "For a connected bridgeless multigraph, uniform spanning-tree edge inclusion probabilities theta_e lie strictly between zero and one; generalized Holder and rooted-tree integration imply anchored absolute integrability of the product of sinc edge kernels", "Stationarity and exact interval-overlap factor permit dominated convergence for each finite set partition"], "evidence": ["proposals/independent_campaigns/sine_gram_moment_existence_round4.md", "audits/adversarial_reviews/sine_gram_moment_existence_third_round3.md", "audits/adversarial_reviews/sine_gram_skeptic_round4.md"], "status": "adjudicated_scoped_conditional_or_model_theorem", "novelty_claim": false, "limitations": ["No almost-sure empirical-law convergence or integrated-density-of-states assertion", "No convergence rate or growing-moment-order uniformity", "No zeta/prime-side moment matching, RH assertion, or validation of the full AF preprint", "Priority of this assembly has not been established"], "paper_id": null, "locator": ["proposals/independent_campaigns/sine_gram_moment_existence_round4.md", "audits/adversarial_reviews/sine_gram_moment_existence_third_round3.md", "audits/adversarial_reviews/sine_gram_skeptic_round4.md"], "provenance_file": "theorems/sine_gram_moment_existence_skeptic_round4.jsonl", "verification": "adjudicated_scoped; independent proposer/skeptic/director reconstructions; exact external-source and model/conditional boundaries retained", "verification_status": "adjudicated_scoped; ordinary proof, not a whole-paper audit or unconditional zeta moment theorem", "status_update_evidence": "audits/adversarial_reviews/director_sine_riesz_round4.md"}',NULL,'For the unit-intensity sine determinantal point process with kernel k(x)=sin(pi*x)/(pi*x), S_R its sinc-Gram matrix on [0,R], and mu_R=R^(-1) E sum_j delta_(lambda_j(S_R)), every fixed nonnegative integer moment has a finite limit as R tends to infinity. These limits have the absolutely convergent anchored partition-integral formula in the cited proof. The deterministic expected per-length laws mu_R consequently converge weakly to a unique probability law, which has no atom at zero, is moment determinate, and has a positive exponential moment.','sine_Gram_all_expected_moment_limits_and_full_law','["proposals/independent_campaigns/sine_gram_moment_existence_round4.md", "audits/adversarial_reviews/sine_gram_moment_existence_third_round3.md", "audits/adversarial_reviews/sine_gram_skeptic_round4.md"]','theorems/sine_gram_moment_existence_skeptic_round4.jsonl');
INSERT INTO "claims" VALUES('THM-SG301','theorems/theorems.jsonl',431,'adjudicated_scoped_conditional_or_model_theorem','["proposals/independent_campaigns/sine_gram_all_moments_round3.md §2"]','{"id": "THM-SG301", "kind": "deterministic_sampling_trace_bound", "statement": "For finiteY and PW_[−1/2,1/2] Gram matrix G_Y, a reproducing convolution phi gives TrG_Y^j<=||phi||1^j int(sum_Y|phi(x−t)|)^jdt, integerj>=1.", "hypotheses": "phihat=1 on band, phi inL1∩Linfty, jinteger; minmax+scalarJensen+Bessel, no matrixpower-monotonicity claim.", "evidence": ["proposals/independent_campaigns/sine_gram_all_moments_round3.md §2"], "status": "adjudicated_scoped_conditional_or_model_theorem", "novelty_claim": false, "paper_id": null, "locator": ["proposals/independent_campaigns/sine_gram_all_moments_round3.md §2"], "provenance_file": "theorems/sine_gram_round3.jsonl", "verification": "adjudicated_scoped; independent proposer/skeptic/director reconstructions; exact external-source and model/conditional boundaries retained", "verification_status": "adjudicated_scoped; ordinary proof, not a whole-paper audit or unconditional zeta moment theorem", "status_update_evidence": "audits/adversarial_reviews/director_sine_riesz_round4.md"}',NULL,'For finiteY and PW_[−1/2,1/2] Gram matrix G_Y, a reproducing convolution phi gives TrG_Y^j<=||phi||1^j int(sum_Y|phi(x−t)|)^jdt, integerj>=1.','deterministic_sampling_trace_bound','["proposals/independent_campaigns/sine_gram_all_moments_round3.md §2"]','theorems/sine_gram_round3.jsonl');
INSERT INTO "claims" VALUES('THM-SG302','theorems/theorems.jsonl',432,'adjudicated_scoped_conditional_or_model_theorem','["THM-SG301", "PAPER-SG001 Eq1.5,1.20,2.35", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §§3–4"]','{"id": "THM-SG302", "kind": "sine_Gram_factorial_moment_bound", "statement": "For unit-intensity sine DPP GramG_R over[0,R], ETrG_R^j/R<=4^j j! for everyintegerj>=1,R>0. Every weak expected-law subsequential limit has an exponential moment and is moment determinate.", "hypotheses": "SineDPP rho_l=det(sincpi differences), PW bandlength1; expected law normalizedbylengthR. Full moment-limit or IDS existence not assumed.", "evidence": ["THM-SG301", "PAPER-SG001 Eq1.5,1.20,2.35", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §§3–4"], "status": "adjudicated_scoped_conditional_or_model_theorem", "novelty_claim": false, "paper_id": null, "locator": ["THM-SG301", "PAPER-SG001 Eq1.5,1.20,2.35", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §§3–4"], "provenance_file": "theorems/sine_gram_round3.jsonl", "verification": "adjudicated_scoped; independent proposer/skeptic/director reconstructions; exact external-source and model/conditional boundaries retained", "verification_status": "adjudicated_scoped; ordinary proof, not a whole-paper audit or unconditional zeta moment theorem", "status_update_evidence": "audits/adversarial_reviews/director_sine_riesz_round4.md"}',NULL,'For unit-intensity sine DPP GramG_R over[0,R], ETrG_R^j/R<=4^j j! for everyintegerj>=1,R>0. Every weak expected-law subsequential limit has an exponential moment and is moment determinate.','sine_Gram_factorial_moment_bound','["THM-SG301", "PAPER-SG001 Eq1.5,1.20,2.35", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §§3–4"]','theorems/sine_gram_round3.jsonl');
INSERT INTO "claims" VALUES('THM-SG303','theorems/theorems.jsonl',433,'adjudicated_scoped_conditional_or_model_theorem','["PAPER-SG002 Theorem3,p7; PW definitionspp5–6", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §5"]','{"id": "THM-SG303", "kind": "sine_Gram_subsequential_zero_atom_exclusion", "statement": "Every weak subsequential limit of mu_R=(1/R)E sum_eigen(G_R)delta_lambda has no atom at0.", "hypotheses": "Sine point process onone infinite configuration; globally removeclosepoints andcap fixedblocks; classical separatedD+<1 PW²interpolation theorem. Perconfiguration Riesz lower bound may vary; deterministic quantile handles averaging.", "evidence": ["PAPER-SG002 Theorem3,p7; PW definitionspp5–6", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §5"], "status": "adjudicated_scoped_conditional_or_model_theorem", "novelty_claim": false, "paper_id": null, "locator": ["PAPER-SG002 Theorem3,p7; PW definitionspp5–6", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §5"], "provenance_file": "theorems/sine_gram_round3.jsonl", "verification": "adjudicated_scoped; independent proposer/skeptic/director reconstructions; exact external-source and model/conditional boundaries retained", "verification_status": "adjudicated_scoped; ordinary proof, not a whole-paper audit or unconditional zeta moment theorem", "status_update_evidence": "audits/adversarial_reviews/director_sine_riesz_round4.md"}',NULL,'Every weak subsequential limit of mu_R=(1/R)E sum_eigen(G_R)delta_lambda has no atom at0.','sine_Gram_subsequential_zero_atom_exclusion','["PAPER-SG002 Theorem3,p7; PW definitionspp5–6", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §5"]','theorems/sine_gram_round3.jsonl');
INSERT INTO "claims" VALUES('THM-SG304','theorems/theorems.jsonl',434,'adjudicated_scoped_conditional_or_model_theorem','["THM-SG302", "THM-SG303", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §6", "audits/adversarial_reviews/christoffel_independent_third_round3.md regular quadrature proof"]','{"id": "THM-SG304", "kind": "Christoffel_limit_for_sine_Gram_laws", "statement": "For any weak expected-law subsequential limitmu above, lambda_m(0;mu) decreases to0. In the infinite-support case, each minimum-square polynomial hasm distinct positive roots and supplies a valid1−p_m² one-sided positive-mass certificate.", "hypotheses": "mu Stieltjes, exponential-moment determinate, mu({0})0 asSG302–303. Finite positive-support case handled separately by annihilating polynomial.", "evidence": ["THM-SG302", "THM-SG303", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §6", "audits/adversarial_reviews/christoffel_independent_third_round3.md regular quadrature proof"], "status": "adjudicated_scoped_conditional_or_model_theorem", "novelty_claim": false, "paper_id": null, "locator": ["THM-SG302", "THM-SG303", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §6", "audits/adversarial_reviews/christoffel_independent_third_round3.md regular quadrature proof"], "provenance_file": "theorems/sine_gram_round3.jsonl", "verification": "adjudicated_scoped; independent proposer/skeptic/director reconstructions; exact external-source and model/conditional boundaries retained", "verification_status": "adjudicated_scoped; ordinary proof, not a whole-paper audit or unconditional zeta moment theorem", "status_update_evidence": "audits/adversarial_reviews/director_sine_riesz_round4.md"}',NULL,'For any weak expected-law subsequential limitmu above, lambda_m(0;mu) decreases to0. In the infinite-support case, each minimum-square polynomial hasm distinct positive roots and supplies a valid1−p_m² one-sided positive-mass certificate.','Christoffel_limit_for_sine_Gram_laws','["THM-SG302", "THM-SG303", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §6", "audits/adversarial_reviews/christoffel_independent_third_round3.md regular quadrature proof"]','theorems/sine_gram_round3.jsonl');
INSERT INTO "claims" VALUES('THM-SG305','theorems/theorems.jsonl',435,'adjudicated_scoped_conditional_or_model_theorem','["THM-SG304", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §7", "audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md"]','{"id": "THM-SG305", "kind": "conditional_all_fixed_moment_prefix_index_route", "statement": "If a Hermitian family has every fixed momentprefix converge to one such sineGram law, then its positive-index fraction tends1. The conclusion transfers to a same-dimension exact-block family at Hilbert–Schmidt erroro(sqrt(d)); with s1>=2n+(block)−N+oN,d~N, the simple-on-line fraction tends1.", "hypotheses": "All fixed momentprefixes forone sequence, matching exactbandwidth/densitynormalization; no uniformm(T) estimate needed. ArithmeticHL* hypotheses not supplied.", "evidence": ["THM-SG304", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §7", "audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md"], "status": "adjudicated_scoped_conditional_or_model_theorem", "novelty_claim": false, "paper_id": null, "locator": ["THM-SG304", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §7", "audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md"], "provenance_file": "theorems/sine_gram_round3.jsonl", "verification": "adjudicated_scoped; independent proposer/skeptic/director reconstructions; exact external-source and model/conditional boundaries retained", "verification_status": "adjudicated_scoped; ordinary proof, not a whole-paper audit or unconditional zeta moment theorem", "status_update_evidence": "audits/adversarial_reviews/director_sine_riesz_round4.md"}',NULL,'If a Hermitian family has every fixed momentprefix converge to one such sineGram law, then its positive-index fraction tends1. The conclusion transfers to a same-dimension exact-block family at Hilbert–Schmidt erroro(sqrt(d)); with s1>=2n+(block)−N+oN,d~N, the simple-on-line fraction tends1.','conditional_all_fixed_moment_prefix_index_route','["THM-SG304", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §7", "audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md"]','theorems/sine_gram_round3.jsonl');
INSERT INTO "claims" VALUES('THM-SG306','theorems/theorems.jsonl',436,'adjudicated_scoped_conditional_or_model_theorem','["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §§1–2", "audits/adversarial_reviews/zero_buffer_weaklaw_third_round3.md"]','{"id": "THM-SG306", "kind": "classical_Hoffman_Wielandt_weak_spectral_transfer", "statement": "For same-dimension HermitianF,G, boundedLipschitz normalizedtrace difference<=Lip(h)||F−G||HS/sqrt(d). Hence HSerroro(sqrt(d)) transfers weakempirical spectral limits, even if highermoments do not transfer.", "hypotheses": "Hermitian, same dimension; sorted real eigenvalues. Fixed boundedLipschitztest. Higher polynomial moments may change arbitrarily.", "evidence": ["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §§1–2", "audits/adversarial_reviews/zero_buffer_weaklaw_third_round3.md"], "status": "adjudicated_scoped_conditional_or_model_theorem", "novelty_claim": false, "paper_id": null, "locator": ["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §§1–2", "audits/adversarial_reviews/zero_buffer_weaklaw_third_round3.md"], "provenance_file": "theorems/sine_gram_round3.jsonl", "verification": "adjudicated_scoped; independent proposer/skeptic/director reconstructions; exact external-source and model/conditional boundaries retained", "verification_status": "adjudicated_scoped; ordinary proof, not a whole-paper audit or unconditional zeta moment theorem", "status_update_evidence": "audits/adversarial_reviews/director_sine_riesz_round4.md"}',NULL,'For same-dimension HermitianF,G, boundedLipschitz normalizedtrace difference<=Lip(h)||F−G||HS/sqrt(d). Hence HSerroro(sqrt(d)) transfers weakempirical spectral limits, even if highermoments do not transfer.','classical_Hoffman_Wielandt_weak_spectral_transfer','["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §§1–2", "audits/adversarial_reviews/zero_buffer_weaklaw_third_round3.md"]','theorems/sine_gram_round3.jsonl');
INSERT INTO "claims" VALUES('THM-SG307','theorems/theorems.jsonl',437,'adjudicated_scoped_conditional_or_model_theorem','["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §3", "audits/adversarial_reviews/hs_clipped_certificate_skeptic_round4.md", "audits/adversarial_reviews/zero_buffer_clipped_moment_third_round3.md"]','{"id": "THM-SG307", "kind": "clipped_polynomial_HS_certificate_transfer", "statement": "For a fixed real polynomialq<=indicator_(0,infty), h=max(q,−1) is a bounded globally Lipschitz minorant withh>=q. Thus n+(G)/d>=Trq(F)/d−Lip(h)||F−G||HS/sqrt(d) for arbitrary same-dimension HermitianF,G.", "hypotheses": "Global one-sided polynomialminorant, fixedq. No highermoment transfer oroperatornormsmall condition. Growingdegree/Lipschitz requires extra control.", "evidence": ["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §3", "audits/adversarial_reviews/hs_clipped_certificate_skeptic_round4.md", "audits/adversarial_reviews/zero_buffer_clipped_moment_third_round3.md"], "status": "adjudicated_scoped_conditional_or_model_theorem", "novelty_claim": false, "paper_id": null, "locator": ["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §3", "audits/adversarial_reviews/hs_clipped_certificate_skeptic_round4.md", "audits/adversarial_reviews/zero_buffer_clipped_moment_third_round3.md"], "provenance_file": "theorems/sine_gram_round3.jsonl", "verification": "adjudicated_scoped; independent proposer/skeptic/director reconstructions; exact external-source and model/conditional boundaries retained", "verification_status": "adjudicated_scoped; ordinary proof, not a whole-paper audit or unconditional zeta moment theorem", "status_update_evidence": "audits/adversarial_reviews/director_sine_riesz_round4.md"}',NULL,'For a fixed real polynomialq<=indicator_(0,infty), h=max(q,−1) is a bounded globally Lipschitz minorant withh>=q. Thus n+(G)/d>=Trq(F)/d−Lip(h)||F−G||HS/sqrt(d) for arbitrary same-dimension HermitianF,G.','clipped_polynomial_HS_certificate_transfer','["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §3", "audits/adversarial_reviews/hs_clipped_certificate_skeptic_round4.md", "audits/adversarial_reviews/zero_buffer_clipped_moment_third_round3.md"]','theorems/sine_gram_round3.jsonl');
INSERT INTO "claims" VALUES('THM-SG308','theorems/theorems.jsonl',438,'adjudicated_scoped_conditional_or_model_theorem','["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §4", "experiments/code/hs_clipped_certificate_round3.py", "experiments/results/hs_clipped_certificate_round3.json", "audits/adversarial_reviews/hs_clipped_certificate_skeptic_round4.md", "audits/adversarial_reviews/zero_buffer_clipped_moment_third_round3.md"]','{"id": "THM-SG308", "kind": "finite_four_moment_singleD_HS_certificate", "statement": "Forq=(7/2)x−(211/48)x²+(7/3)x³−(4/9)x4, h=max(q,−1) hasLip<=6, so n+(G)/d>=L_F(q)−6||F−G||HS/sqrt(d). Ifm1(F)->1,m2(F)->4/3,epsilonHS->0,d~N,andblockcharge s1>=2n+(G)−N+oN, then liminfD>115, D=84m3−16m4, suffices to beat2/3; D116 gives13/18.", "hypotheses": "ArithmeticD bound andexactblockcount are conditional inputs, not proved. BoundedD needed toreplace d/N by1; intendedimprovementcondition plusD<=121+o1 supplies it.", "evidence": ["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §4", "experiments/code/hs_clipped_certificate_round3.py", "experiments/results/hs_clipped_certificate_round3.json", "audits/adversarial_reviews/hs_clipped_certificate_skeptic_round4.md", "audits/adversarial_reviews/zero_buffer_clipped_moment_third_round3.md"], "status": "adjudicated_scoped_conditional_or_model_theorem", "novelty_claim": false, "paper_id": null, "locator": ["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §4", "experiments/code/hs_clipped_certificate_round3.py", "experiments/results/hs_clipped_certificate_round3.json", "audits/adversarial_reviews/hs_clipped_certificate_skeptic_round4.md", "audits/adversarial_reviews/zero_buffer_clipped_moment_third_round3.md"], "provenance_file": "theorems/sine_gram_round3.jsonl", "verification": "adjudicated_scoped; independent proposer/skeptic/director reconstructions; exact external-source and model/conditional boundaries retained", "verification_status": "adjudicated_scoped; ordinary proof, not a whole-paper audit or unconditional zeta moment theorem", "status_update_evidence": "audits/adversarial_reviews/director_sine_riesz_round4.md"}',NULL,'Forq=(7/2)x−(211/48)x²+(7/3)x³−(4/9)x4, h=max(q,−1) hasLip<=6, so n+(G)/d>=L_F(q)−6||F−G||HS/sqrt(d). Ifm1(F)->1,m2(F)->4/3,epsilonHS->0,d~N,andblockcharge s1>=2n+(G)−N+oN, then liminfD>115, D=84m3−16m4, suffices to beat2/3; D116 gives13/18.','finite_four_moment_singleD_HS_certificate','["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §4", "experiments/code/hs_clipped_certificate_round3.py", "experiments/results/hs_clipped_certificate_round3.json", "audits/adversarial_reviews/hs_clipped_certificate_skeptic_round4.md", "audits/adversarial_reviews/zero_buffer_clipped_moment_third_round3.md"]','theorems/sine_gram_round3.jsonl');
INSERT INTO "claims" VALUES('THM-SG310','theorems/theorems.jsonl',439,'adjudicated_scoped_conditional_or_model_theorem','["audits/adversarial_reviews/sine_gram_fourth_moment_advocate_archived_round3.md", "experiments/code/sine_gram_fourth_exact_advocate_round3.py", "experiments/results/sine_gram_fourth_exact_advocate_round3.json", "THM-SG309"]','{"id": "THM-SG310", "kind": "exact_first_four_sine_Gram_model_moments", "statement": "The unit-density sinc(pi) sine-DPP expected Gram spectral law has moments m1=1,m2=4/3,m3=2,m4=13/4. The all-distinct fourcycle determinant integral is0; D=84m3−16m4=116.", "hypotheses": "Actual random sine-Gram model, not zeta prime-side matrix. Absolute graph integrability asSG309;24 determinant permutations and15 trace partitions, with exact projection/Fourier integrals.", "evidence": ["audits/adversarial_reviews/sine_gram_fourth_moment_advocate_archived_round3.md", "experiments/code/sine_gram_fourth_exact_advocate_round3.py", "experiments/results/sine_gram_fourth_exact_advocate_round3.json", "THM-SG309"], "status": "adjudicated_scoped_conditional_or_model_theorem", "novelty_claim": false, "paper_id": null, "locator": ["audits/adversarial_reviews/sine_gram_fourth_moment_advocate_archived_round3.md", "experiments/code/sine_gram_fourth_exact_advocate_round3.py", "experiments/results/sine_gram_fourth_exact_advocate_round3.json", "THM-SG309"], "provenance_file": "theorems/sine_gram_round3.jsonl", "verification": "adjudicated_scoped; independent proposer/skeptic/director reconstructions; exact external-source and model/conditional boundaries retained", "verification_status": "adjudicated_scoped; ordinary proof, not a whole-paper audit or unconditional zeta moment theorem", "status_update_evidence": "audits/adversarial_reviews/director_sine_riesz_round4.md"}',NULL,'The unit-density sinc(pi) sine-DPP expected Gram spectral law has moments m1=1,m2=4/3,m3=2,m4=13/4. The all-distinct fourcycle determinant integral is0; D=84m3−16m4=116.','exact_first_four_sine_Gram_model_moments','["audits/adversarial_reviews/sine_gram_fourth_moment_advocate_archived_round3.md", "experiments/code/sine_gram_fourth_exact_advocate_round3.py", "experiments/results/sine_gram_fourth_exact_advocate_round3.json", "THM-SG309"]','theorems/sine_gram_round3.jsonl');
INSERT INTO "claims" VALUES('THM-E-SND401','theorems/theorems.jsonl',440,'established_primary_source_result','Theorem1p1','{"id": "THM-E-SND401", "paper_id": "PAPER-E013", "locator": "Theorem1p1", "statement": "AssumeRH. For sufficiently largex, |sum_(n<=x)mu(n)|≪sqrt(x)exp((logx)^(1/2)(loglogx)^14).", "hypotheses": "RH; xreal sufficientlylarge; impliedconstantabsolute; this is original exponent14.", "status": "established_primary_source_result", "verification": "Whole11pagepreprintread; main proof architecture reconstructed, external dependencies not fully audited.", "provenance_file": "theorems/soundararajan_round4.jsonl"}','PAPER-E013','AssumeRH. For sufficiently largex, |sum_(n<=x)mu(n)|≪sqrt(x)exp((logx)^(1/2)(loglogx)^14).',NULL,'Theorem1p1','theorems/soundararajan_round4.jsonl');
INSERT INTO "claims" VALUES('THM-E-SND402','theorems/theorems.jsonl',441,'established_primary_source_result','Theorem2p2; proofpp5–6','{"id": "THM-E-SND402", "paper_id": "PAPER-E013", "locator": "Theorem2p2; proofpp5–6", "statement": "UnderRH, largeT,0<=h<=sqrtT,(loglogT)^2<=V<=logT/loglogT: numberR of1-separated t_j in[T,2T] with N(t_j+h)−N(t_j−h)−(h/pi)log(t_j/2pi)>V is≪T exp(−Vlog(V/loglogT)+3VloglogV).", "hypotheses": "Zeros counted withmultiplicity; the sameT,h,V and separation across all testpoints.", "status": "established_primary_source_result", "verification": "Actual statement and Selberg/explicit-formula/large-sieve proof read; moment restriction length^k<=T traced.", "provenance_file": "theorems/soundararajan_round4.jsonl"}','PAPER-E013','UnderRH, largeT,0<=h<=sqrtT,(loglogT)^2<=V<=logT/loglogT: numberR of1-separated t_j in[T,2T] with N(t_j+h)−N(t_j−h)−(h/pi)log(t_j/2pi)>V is≪T exp(−Vlog(V/loglogT)+3VloglogV).',NULL,'Theorem2p2; proofpp5–6','theorems/soundararajan_round4.jsonl');
INSERT INTO "claims" VALUES('THM-E-SND403','theorems/theorems.jsonl',442,'established_primary_source_result','Definition3pp2–3; Proposition4p3,proofpp6–7','{"id": "THM-E-SND403", "paper_id": "PAPER-E013", "locator": "Definition3pp2–3; Proposition4p3,proofpp6–7", "statement": "UnderRH, all t in[T,2T] are V-typical forV>=(1/2+o1)logT/loglogT; for(loglogT)^2<=V<=logT/loglogT, number of1-separatedV-atypical heights is≪T exp(−Vlog(V/loglogT)+4VloglogV).", "hypotheses": "Typicality has ALL3conditions: smoothed primepolylengthT^(1/V) modulus<=2V forallsigma>=.5; each localinterval length2piV/logT has<=3Vzeroordinates; each localinterval length2piV/((logV)logT) has<=V.", "status": "established_primary_source_result", "verification": "Source definition and proof read; no Gaussian exceptional estimate asserted.", "provenance_file": "theorems/soundararajan_round4.jsonl"}','PAPER-E013','UnderRH, all t in[T,2T] are V-typical forV>=(1/2+o1)logT/loglogT; for(loglogT)^2<=V<=logT/loglogT, number of1-separatedV-atypical heights is≪T exp(−Vlog(V/loglogT)+4VloglogV).',NULL,'Definition3pp2–3; Proposition4p3,proofpp6–7','theorems/soundararajan_round4.jsonl');
INSERT INTO "claims" VALUES('THM-E-SND404','theorems/theorems.jsonl',443,'established_primary_source_result_with_scoped_reconstruction','Proposition5p3; Lemmas9–11pp7–9','{"id": "THM-E-SND404", "paper_id": "PAPER-E013", "locator": "Proposition5p3; Lemmas9–11pp7–9", "statement": "UnderRH atV-typical t, sigma0=.5+V/logT: log|zeta(sigma+it)|>=−VloglogV for sigma0<=sigma<=2; for .5<sigma<=sigma0 it is>=−Vlog[(sigma0−.5)/(sigma−.5)]−8VloglogV.", "hypotheses": "Same typicality sizeT and Vrange; pointwise only at typicalt; no zero-spacing or simplicity assumption.", "status": "established_primary_source_result_with_scoped_reconstruction", "verification": "Smoothed logderivative identity and F bound reconstructed; central halfwidth specified literally in audit. External ancestry not fully audited.", "provenance_file": "theorems/soundararajan_round4.jsonl"}','PAPER-E013','UnderRH atV-typical t, sigma0=.5+V/logT: log|zeta(sigma+it)|>=−VloglogV for sigma0<=sigma<=2; for .5<sigma<=sigma0 it is>=−Vlog[(sigma0−.5)/(sigma−.5)]−8VloglogV.',NULL,'Proposition5p3; Lemmas9–11pp7–9','theorems/soundararajan_round4.jsonl');
INSERT INTO "claims" VALUES('THM-D201','theorems/theorems.jsonl',444,'Exact source hypotheses/statements and two proof routes inspected selectively; no whole-paper technical audit.','Theorem1.1,pp2–3; equations1.11–1.14','{"theorem_id": "THM-D201", "paper_id": "PAPER-D201", "locator": "Theorem1.1,pp2–3; equations1.11–1.14", "kind": "published theorem, inspected preprint version", "statement": "S closed densely defined symmetric bounded below, deficiency(n,n)<∞, boundary triplet. For selfadjoint extensions H1,H2 the below-essential-spectrum counting shift σ=N_H1((−∞,λ])−N_H2((−∞,λ]) lies in[−σ−,σ+], where σ−+σ+=n−dim(L1∩L2).", "verification_status": "Exact source hypotheses/statements and two proof routes inspected selectively; no whole-paper technical audit.", "limitations": "Semiboundedness explicit; cannot directly cite as theorem for arbitrary two-sided spectra.", "id": "THM-D201", "provenance_file": "theorems/spectral_extension_round2.jsonl"}','PAPER-D201','S closed densely defined symmetric bounded below, deficiency(n,n)<∞, boundary triplet. For selfadjoint extensions H1,H2 the below-essential-spectrum counting shift σ=N_H1((−∞,λ])−N_H2((−∞,λ]) lies in[−σ−,σ+], where σ−+σ+=n−dim(L1∩L2).','published theorem, inspected preprint version','Theorem1.1,pp2–3; equations1.11–1.14','theorems/spectral_extension_round2.jsonl');
INSERT INTO "claims" VALUES('THM-D202','theorems/theorems.jsonl',445,'Statement and relative-count cancellation proof inspected; full index foundations not audited.','Theorem1.2,p4; Proposition5.3 and proof,p19','{"theorem_id": "THM-D202", "paper_id": "PAPER-D201", "locator": "Theorem1.2,p4; Proposition5.3 and proof,p19", "kind": "published theorem, inspected preprint version", "statement": "Under Theorem1.1 hypotheses, for[a,b] outside the essential spectrum, N_H1((a,b])−N_H2((a,b]) is the difference of endpoint Duistermaat indices. Relative counts require no unique-continuation assumption because common S-eigenvalues cancel.", "verification_status": "Statement and relative-count cancellation proof inspected; full index foundations not audited.", "id": "THM-D202", "provenance_file": "theorems/spectral_extension_round2.jsonl"}','PAPER-D201','Under Theorem1.1 hypotheses, for[a,b] outside the essential spectrum, N_H1((a,b])−N_H2((a,b]) is the difference of endpoint Duistermaat indices. Relative counts require no unique-continuation assumption because common S-eigenvalues cancel.','published theorem, inspected preprint version','Theorem1.2,p4; Proposition5.3 and proof,p19','theorems/spectral_extension_round2.jsonl');
INSERT INTO "claims" VALUES('THM-D203','theorems/theorems.jsonl',446,'Elementary range/resolvent identity proof supplied; parent independently confirmed the rank strategy. No literature novelty asserted.','audits/extension_interlacing_round2.md §1','{"theorem_id": "THM-D203", "paper_id": null, "locator": "audits/extension_interlacing_round2.md §1", "kind": "independently reconstructed finite-defect resolvent lemma", "statement": "For selfadjoint extensions H0,H1 of one closed densely defined symmetric S with deficiency(d,d), D(i)=R1(i)−R0(i) maps into ker(S*−i), so rank≤d. For common z,w, D(z)=[I+(z−w)R1(z)]D(w)[I+(z−w)R0(z)]; the outer factors are invertible, hence the finite rank is anchor-independent. One compact resolvent implies both are compact.", "verification_status": "Elementary range/resolvent identity proof supplied; parent independently confirmed the rank strategy. No literature novelty asserted.", "source_context": "PAPER-D201 Theorem6.2,pp22–24 contains the source finite-defect mechanism under its semibounded setting; this proof does not assume semiboundedness.", "id": "THM-D203", "provenance_file": "theorems/spectral_extension_round2.jsonl"}',NULL,'For selfadjoint extensions H0,H1 of one closed densely defined symmetric S with deficiency(d,d), D(i)=R1(i)−R0(i) maps into ker(S*−i), so rank≤d. For common z,w, D(z)=[I+(z−w)R1(z)]D(w)[I+(z−w)R0(z)]; the outer factors are invertible, hence the finite rank is anchor-independent. One compact resolvent implies both are compact.','independently reconstructed finite-defect resolvent lemma','audits/extension_interlacing_round2.md §1','theorems/spectral_extension_round2.jsonl');
INSERT INTO "claims" VALUES('THM-D204','theorems/theorems.jsonl',447,'established auxiliary theorem under stated hypotheses','audits/extension_interlacing_round2.md §§2–4','{"theorem_id": "THM-D204", "paper_id": null, "locator": "audits/extension_interlacing_round2.md §§2–4", "kind": "independently reconstructed compact-resolvent relative-count theorem", "statement": "For compact-resolvent selfadjoint H0,H1 on the same Hilbert space, choose common real anchor c and suppose F=(H1−c)^−1−(H0−c)^−1 has inertia(p,m), rankr=p+m<∞. Define ξ(x) by N_H1((c,x])−N_H0((c,x]) above c and the negative difference on(x,c] below c. Then ξ(x)∈[−m,p] for all realx, with exact half-open conventions; ξ(v)−ξ(u) is the finite interval count difference. Hence |Δ_H1(K)−Δ_H0(K)|≤3r, Δ_H=N_H((2K,4K])−2N_H((K,2K]).", "verification_status": "Complete proof using both reciprocal branches and compact-tail inertia supplied; parent independently checked signs, endpoints, common anchor and3r cancellation. No separate third reconstruction or literature novelty claimed.", "hypotheses": ["Same Hilbert space and same two fixed operators during all height comparisons.", "Compact resolvent; essential/continuous spectrum excluded.", "One fixed real common resolvent anchor; no lower spectral bound required."], "source_theorems": ["THM-D203"], "status": "established auxiliary theorem under stated hypotheses", "id": "THM-D204", "provenance_file": "theorems/spectral_extension_round2.jsonl"}',NULL,'For compact-resolvent selfadjoint H0,H1 on the same Hilbert space, choose common real anchor c and suppose F=(H1−c)^−1−(H0−c)^−1 has inertia(p,m), rankr=p+m<∞. Define ξ(x) by N_H1((c,x])−N_H0((c,x]) above c and the negative difference on(x,c] below c. Then ξ(x)∈[−m,p] for all realx, with exact half-open conventions; ξ(v)−ξ(u) is the finite interval count difference. Hence |Δ_H1(K)−Δ_H0(K)|≤3r, Δ_H=N_H((2K,4K])−2N_H((K,2K]).','independently reconstructed compact-resolvent relative-count theorem','audits/extension_interlacing_round2.md §§2–4','theorems/spectral_extension_round2.jsonl');
INSERT INTO "claims" VALUES('THM-D205','theorems/theorems.jsonl',448,'established auxiliary corollary; no novelty claim','audits/extension_interlacing_round2.md, proposition and §§1–4','{"theorem_id": "THM-D205", "paper_id": null, "locator": "audits/extension_interlacing_round2.md, proposition and §§1–4", "kind": "finite boundary-defect curvature corollary", "statement": "If H0,H1 are selfadjoint extensions of one closed densely defined symmetric S with finite equal deficiency(d,d), and one has compact resolvent, then their anchored relative count has range length≤d and |Δ_H1(K)−Δ_H0(K)|≤3d, even when spectra are unbounded in both directions.", "verification_status": "Derived from THM-D203 and THM-D204; full proof provided, parent reviewed. Not attributed to the semibounded source theorem.", "source_theorems": ["THM-D203", "THM-D204"], "status": "established auxiliary corollary; no novelty claim", "id": "THM-D205", "provenance_file": "theorems/spectral_extension_round2.jsonl"}',NULL,'If H0,H1 are selfadjoint extensions of one closed densely defined symmetric S with finite equal deficiency(d,d), and one has compact resolvent, then their anchored relative count has range length≤d and |Δ_H1(K)−Δ_H0(K)|≤3d, even when spectra are unbounded in both directions.','finite boundary-defect curvature corollary','audits/extension_interlacing_round2.md, proposition and §§1–4','theorems/spectral_extension_round2.jsonl');
INSERT INTO "claims" VALUES('THM-D206','theorems/theorems.jsonl',449,'exact auxiliary example, not a zeta-zero construction','audits/extension_interlacing_round2.md §4; experiments/code/extension_interlacing_round2.py','{"theorem_id": "THM-D206", "paper_id": null, "locator": "audits/extension_interlacing_round2.md §4; experiments/code/extension_interlacing_round2.py", "kind": "sharpness example in actual differential extension class", "statement": "For S=−i d/dx on H0^1(0,2π), deficiency(1,1), let Hθ have domain f(2π)=exp(2πiθ)f(0), spectrum n+θ. With θ1=3/20, θ0=2/5 and K=3/10, positive counts atK,2K,4K are(1,1,2) and(0,1,1), respectively, yielding curvature difference3. Direct sums yield3d.", "verification_status": "Boundary Green identity, deficiency ODE and exact rational counts checked; example unbounded in both directions with compact resolvent. Parent was informed separately of the sharp example.", "status": "exact auxiliary example, not a zeta-zero construction", "id": "THM-D206", "provenance_file": "theorems/spectral_extension_round2.jsonl"}',NULL,'For S=−i d/dx on H0^1(0,2π), deficiency(1,1), let Hθ have domain f(2π)=exp(2πiθ)f(0), spectrum n+θ. With θ1=3/20, θ0=2/5 and K=3/10, positive counts atK,2K,4K are(1,1,2) and(0,1,1), respectively, yielding curvature difference3. Direct sums yield3d.','sharpness example in actual differential extension class','audits/extension_interlacing_round2.md §4; experiments/code/extension_interlacing_round2.py','theorems/spectral_extension_round2.jsonl');
INSERT INTO "claims" VALUES('THM-D207','theorems/theorems.jsonl',450,'conditional model obstruction; no classical RH assertion','audits/extension_interlacing_round2.md §5','{"theorem_id": "THM-D207", "paper_id": null, "locator": "audits/extension_interlacing_round2.md §5", "kind": "conditional model-cost consequence", "statement": "If a reference E-channel first-order graph satisfies|Δ_H0|<3E and H1 is another compact-resolvent selfadjoint extension of their common finite-defectd symmetric restriction, then|Δ_H1|<3(E+d). If instead the full reference is A⊕D with M finite auxiliary levels, then|Δ_H1−Δ_A|≤3d+2M. These require an actual full-space common-extension realization; arbitrary unitary S(k) is insufficient.", "verification_status": "Triangle inequality and finite-level contribution0,−2,1 checked. Applicability to any proposed model must be separately verified.", "source_theorems": ["THM-D205"], "status": "conditional model obstruction; no classical RH assertion", "id": "THM-D207", "provenance_file": "theorems/spectral_extension_round2.jsonl"}',NULL,'If a reference E-channel first-order graph satisfies|Δ_H0|<3E and H1 is another compact-resolvent selfadjoint extension of their common finite-defectd symmetric restriction, then|Δ_H1|<3(E+d). If instead the full reference is A⊕D with M finite auxiliary levels, then|Δ_H1−Δ_A|≤3d+2M. These require an actual full-space common-extension realization; arbitrary unitary S(k) is insufficient.','conditional model-cost consequence','audits/extension_interlacing_round2.md §5','theorems/spectral_extension_round2.jsonl');
INSERT INTO "claims" VALUES('THM-S001-AC','theorems/theorems.jsonl',451,'source_read_not_full_modern_proof_audited','Wilkins translation pp2–3','{"theorem_id": "THM-S001-AC", "paper_id": "PAPER-S001", "kind": "established_theorem", "statement": "ζ has meromorphic continuation to C, with only a simple pole at1; completed xi is entire and invariant under s→1−s.", "source_locator": "Wilkins translation pp2–3", "verification_status": "source_read_not_full_modern_proof_audited", "id": "THM-S001-AC", "locator": "Wilkins translation pp2–3", "provenance_file": "theorems/spectral_track.jsonl"}','PAPER-S001','ζ has meromorphic continuation to C, with only a simple pole at1; completed xi is entire and invariant under s→1−s.','established_theorem','Wilkins translation pp2–3','theorems/spectral_track.jsonl');
INSERT INTO "claims" VALUES('CONJ-S001-RH','theorems/theorems.jsonl',452,'faithfully_identified_as_conjecture','Wilkins translation p4','{"theorem_id": "CONJ-S001-RH", "paper_id": "PAPER-S001", "kind": "conjecture", "statement": "All zeros of ξ_mod(1/2+it) are real in variable t.", "source_locator": "Wilkins translation p4", "verification_status": "faithfully_identified_as_conjecture", "id": "CONJ-S001-RH", "locator": "Wilkins translation p4", "provenance_file": "theorems/spectral_track.jsonl"}','PAPER-S001','All zeros of ξ_mod(1/2+it) are real in variable t.','conjecture','Wilkins translation p4','theorems/spectral_track.jsonl');
INSERT INTO "claims" VALUES('THM-S003-SECU','theorems/theorems.jsonl',453,'inspected_and_single_edge_case_independently_checked','Proposition9.1,p17,eq83','{"theorem_id": "THM-S003-SECU", "paper_id": "PAPER-S003", "kind": "established_theorem", "statement": "For finite positive edge lengths and a fixed self-adjoint endpoint coupling, k is an eigenvalue iff det(I−S diag(exp(ik l_j)))=0, with corresponding multiplicity.", "source_locator": "Proposition9.1,p17,eq83", "verification_status": "inspected_and_single_edge_case_independently_checked", "id": "THM-S003-SECU", "locator": "Proposition9.1,p17,eq83", "provenance_file": "theorems/spectral_track.jsonl"}','PAPER-S003','For finite positive edge lengths and a fixed self-adjoint endpoint coupling, k is an eigenvalue iff det(I−S diag(exp(ik l_j)))=0, with corresponding multiplicity.','established_theorem','Proposition9.1,p17,eq83','theorems/spectral_track.jsonl');
INSERT INTO "claims" VALUES('THM-S003-NOGO','theorems/theorems.jsonl',454,'growth_order_independently_checked; coefficient_issue_is_separate','Theorem15.6,p28','{"theorem_id": "THM-S003-NOGO", "paper_id": "PAPER-S003", "kind": "established_theorem", "statement": "Fixed compact-graph self-adjoint realizations of HBK and the specified squared expression cannot have the complete nontrivial Riemann-zero spectrum.", "source_locator": "Theorem15.6,p28", "verification_status": "growth_order_independently_checked; coefficient_issue_is_separate", "id": "THM-S003-NOGO", "locator": "Theorem15.6,p28", "provenance_file": "theorems/spectral_track.jsonl"}','PAPER-S003','Fixed compact-graph self-adjoint realizations of HBK and the specified squared expression cannot have the complete nontrivial Riemann-zero spectrum.','established_theorem','Theorem15.6,p28','theorems/spectral_track.jsonl');
INSERT INTO "claims" VALUES('THM-S004-NEWMAN','theorems/theorems.jsonl',455,'source_read; full_proof_not_audited','Theorem1,p3,arxivv5','{"theorem_id": "THM-S004-NEWMAN", "paper_id": "PAPER-S004", "kind": "established_theorem", "statement": "The de Bruijn–Newman constant in the paper normalization satisfies Λ≥0.", "source_locator": "Theorem1,p3,arxivv5", "verification_status": "source_read; full_proof_not_audited", "id": "THM-S004-NEWMAN", "locator": "Theorem1,p3,arxivv5", "provenance_file": "theorems/spectral_track.jsonl"}','PAPER-S004','The de Bruijn–Newman constant in the paper normalization satisfies Λ≥0.','established_theorem','Theorem1,p3,arxivv5','theorems/spectral_track.jsonl');
INSERT INTO "claims" VALUES('THM-S004-ROOTODE','theorems/theorems.jsonl',456,'source_statement_read; predecessor_source_not_audited','Theorem11,p27,eq56','{"theorem_id": "THM-S004-ROOTODE", "paper_id": "PAPER-S004", "kind": "established_conditional_result", "statement": "Assuming Λ<0, on Λ<t≤0 the simple zero trajectories satisfy x_k′=2PV∑_{j≠k}1/(x_k−x_j).", "source_locator": "Theorem11,p27,eq56", "verification_status": "source_statement_read; predecessor_source_not_audited", "id": "THM-S004-ROOTODE", "locator": "Theorem11,p27,eq56", "provenance_file": "theorems/spectral_track.jsonl"}','PAPER-S004','Assuming Λ<0, on Λ<t≤0 the simple zero trajectories satisfy x_k′=2PV∑_{j≠k}1/(x_k−x_j).','established_conditional_result','Theorem11,p27,eq56','theorems/spectral_track.jsonl');
INSERT INTO "claims" VALUES('OBS-S-C1','theorems/theorems.jsonl',457,'independent_review_requested; no_novelty_claim','proposals/independent_campaigns/spectral_counting_barrier.md','{"theorem_id": "OBS-S-C1", "paper_id": null, "kind": "independently_derived_elementary_proposition", "statement": "For E finite first-order graph channels with fixed unitary endpoint matrix, N_+(K)=LK/(2π)+C−F(K),0≤F(K)<E; hence absolute dyadic count curvature<3E.", "source_locator": "proposals/independent_campaigns/spectral_counting_barrier.md", "verification_status": "independent_review_requested; no_novelty_claim", "id": "OBS-S-C1", "locator": "proposals/independent_campaigns/spectral_counting_barrier.md", "provenance_file": "theorems/spectral_track.jsonl", "verification": "scoped_Level3; audits/adversarial_reviews/director_adjudication.md"}',NULL,'For E finite first-order graph channels with fixed unitary endpoint matrix, N_+(K)=LK/(2π)+C−F(K),0≤F(K)<E; hence absolute dyadic count curvature<3E.','independently_derived_elementary_proposition','proposals/independent_campaigns/spectral_counting_barrier.md','theorems/spectral_track.jsonl');
INSERT INTO "claims" VALUES('OBS-S-C2','theorems/theorems.jsonl',458,'independent_review_requested; no_novelty_claim','proposals/independent_campaigns/spectral_counting_barrier.md','{"theorem_id": "OBS-S-C2", "paper_id": null, "kind": "derived_conditional_complexity_bound", "statement": "If such a graph matches Nζ at K,2K,4K with errors≤ε_K K, then3E≥Klog2/π−6ε_KK−O(logK); o(K) error requires liminf E/K≥log2/(3π).", "source_locator": "proposals/independent_campaigns/spectral_counting_barrier.md", "verification_status": "independent_review_requested; no_novelty_claim", "id": "OBS-S-C2", "locator": "proposals/independent_campaigns/spectral_counting_barrier.md", "provenance_file": "theorems/spectral_track.jsonl", "verification": "scoped_Level3; audits/adversarial_reviews/director_adjudication.md"}',NULL,'If such a graph matches Nζ at K,2K,4K with errors≤ε_K K, then3E≥Klog2/π−6ε_KK−O(logK); o(K) error requires liminf E/K≥log2/(3π).','derived_conditional_complexity_bound','proposals/independent_campaigns/spectral_counting_barrier.md','theorems/spectral_track.jsonl');
INSERT INTO "claims" VALUES('THM-S005-PHASE','theorems/theorems.jsonl',459,'local source inspected; mechanism independently reconstructed','arxivv2 Section5.1,eq5.5–5.11,pp36–38','{"theorem_id": "THM-S005-PHASE", "paper_id": "PAPER-S005", "kind": "established_result", "statement": "For the stated energy-independent quantum evolution map, eigenphase velocities are positive and sum to twice total undirected bond length; the count has linear Weyl term plus bounded oscillatory part.", "source_locator": "arxivv2 Section5.1,eq5.5–5.11,pp36–38", "verification_status": "local source inspected; mechanism independently reconstructed", "id": "THM-S005-PHASE", "locator": "arxivv2 Section5.1,eq5.5–5.11,pp36–38", "provenance_file": "theorems/spectral_track.jsonl"}','PAPER-S005','For the stated energy-independent quantum evolution map, eigenphase velocities are positive and sum to twice total undirected bond length; the count has linear Weyl term plus bounded oscillatory part.','established_result','arxivv2 Section5.1,eq5.5–5.11,pp36–38','theorems/spectral_track.jsonl');
INSERT INTO "claims" VALUES('CONS-S006-BUTTERFLY','theorems/theorems.jsonl',460,'source main text read; first correction independently checked; infinite limit not fully audited','arxivv2 eq11–14,pp3–5','{"theorem_id": "CONS-S006-BUTTERFLY", "paper_id": "PAPER-S006", "kind": "established_construction_with_limits", "statement": "A recursive infinite collection of unitary butterflies can match smoothed prime-power oscillatory trace coefficients while its mean density diverges and its full spectrum differs from zeta zeros.", "source_locator": "arxivv2 eq11–14,pp3–5", "verification_status": "source main text read; first correction independently checked; infinite limit not fully audited", "id": "CONS-S006-BUTTERFLY", "locator": "arxivv2 eq11–14,pp3–5", "provenance_file": "theorems/spectral_track.jsonl"}','PAPER-S006','A recursive infinite collection of unitary butterflies can match smoothed prime-power oscillatory trace coefficients while its mean density diverges and its full spectrum differs from zeta zeros.','established_construction_with_limits','arxivv2 eq11–14,pp3–5','theorems/spectral_track.jsonl');
INSERT INTO "claims" VALUES('THM-S007-HARDY','theorems/theorems.jsonl',461,'whole_original_read; local proof reconstructed; no full independent adversarial audit','original pp1012–1014,especially§3 eq4–6','{"theorem_id": "THM-S007-HARDY", "paper_id": "PAPER-S007", "kind": "established_theorem", "statement": "Infinitely many distinct nontrivial zeros of ζ(s) have real part1/2; no RH or positive-proportion assertion follows.", "source_locator": "original pp1012–1014,especially§3 eq4–6", "verification_status": "whole_original_read; local proof reconstructed; no full independent adversarial audit", "id": "THM-S007-HARDY", "locator": "original pp1012–1014,especially§3 eq4–6", "provenance_file": "theorems/spectral_track.jsonl"}','PAPER-S007','Infinitely many distinct nontrivial zeros of ζ(s) have real part1/2; no RH or positive-proportion assertion follows.','established_theorem','original pp1012–1014,especially§3 eq4–6','theorems/spectral_track.jsonl');
INSERT INTO "claims" VALUES('LEM-THRESHOLD62-DENSITY-MOMENT','theorems/theorems.jsonl',462,'adjudicated_scoped_conditional_refinement','proposals/independent_campaigns/threshold62_weighteddensity_bgstb.md','{"id": "LEM-THRESHOLD62-DENSITY-MOMENT", "statement": "With the BGSTB §6 kernel, unit-window zero count and reflection, let L=log T and D_T(y)=N(1/2+y/L,T) for 1/2≤y≤L/2. The sufficient horizontal moment condition for S(T)=o(TL) is exactly equivalent to r_T(1/2)+∫ r_T(y)/(1+y²)dy→0, where r_T(y)=e^(2y)D_T(y)/T. The condition refers to the absolute majorant, not necessity for the signed far-pair sum.", "locator": "proposals/independent_campaigns/threshold62_weighteddensity_bgstb.md", "status": "adjudicated_scoped_conditional_refinement", "priority": "unassessed", "paper_id": null, "provenance_file": "theorems/threshold62_weighteddensity_bgstb.jsonl", "verification": "Independent proponent, ratio reviewer and director reconstruction; endpoint conventions and source-specific inputs retained.", "status_update_evidence": "audits/adversarial_reviews/director_weighted_density_round6.md"}',NULL,'With the BGSTB §6 kernel, unit-window zero count and reflection, let L=log T and D_T(y)=N(1/2+y/L,T) for 1/2≤y≤L/2. The sufficient horizontal moment condition for S(T)=o(TL) is exactly equivalent to r_T(1/2)+∫ r_T(y)/(1+y²)dy→0, where r_T(y)=e^(2y)D_T(y)/T. The condition refers to the absolute majorant, not necessity for the signed far-pair sum.',NULL,'proposals/independent_campaigns/threshold62_weighteddensity_bgstb.md','theorems/threshold62_weighteddensity_bgstb.jsonl');
INSERT INTO "claims" VALUES('COR-THRESHOLD62-DENSITY-HEIGHT','theorems/theorems.jsonl',463,'adjudicated_scoped_conditional_refinement','proposals/independent_campaigns/threshold62_weighteddensity_bgstb.md','{"id": "COR-THRESHOLD62-DENSITY-HEIGHT", "statement": "Under the source''s uniform N(σ,X)≪X^(2(1−σ)) bound on σ*≤σ≤1, fix 0<θ<2(1−σ*). The contribution of positive heights at most T^θ to the horizontal moment is o(T), with scale log T. Hence the weighted condition can be imposed just on heights T^θ<γ≤T, and under it the BGSTB §7 multiplicity bound follows from Lemma 7 and near-pair positivity.", "locator": "proposals/independent_campaigns/threshold62_weighteddensity_bgstb.md", "status": "adjudicated_scoped_conditional_refinement", "priority": "unassessed", "paper_id": null, "provenance_file": "theorems/threshold62_weighteddensity_bgstb.jsonl", "verification": "Independent proponent, ratio reviewer and director reconstruction; endpoint conventions and source-specific inputs retained.", "status_update_evidence": "audits/adversarial_reviews/director_weighted_density_round6.md"}',NULL,'Under the source''s uniform N(σ,X)≪X^(2(1−σ)) bound on σ*≤σ≤1, fix 0<θ<2(1−σ*). The contribution of positive heights at most T^θ to the horizontal moment is o(T), with scale log T. Hence the weighted condition can be imposed just on heights T^θ<γ≤T, and under it the BGSTB §7 multiplicity bound follows from Lemma 7 and near-pair positivity.',NULL,'proposals/independent_campaigns/threshold62_weighteddensity_bgstb.md','theorems/threshold62_weighteddensity_bgstb.jsonl');
INSERT INTO "claims" VALUES('OBS-WC501','theorems/theorems.jsonl',464,'adjudicated_scoped_unconditional_implication','audits/adversarial_reviews/weighted_criterion_director_round5.md','{"id": "OBS-WC501", "paper_id": null, "kind": "weighted_Mellin_zero_witness", "statement": "For alpha∈[-3,-2],1≤a<(1-alpha)/2, t=-(alpha+1)/2,c=a-1,b=t-c, u=(1-z)^(-c), the specified D_(alpha+2) target closure implies zeta zero-free Re(s)>b. A continuous radial Lambda_s forRe(s)>b hasLambda_s(u)=-1/s andLambda_s(u h_k)=(1-k^(1-s))zeta(s)/s, with the removable value at s=1 understood.", "locator": "audits/adversarial_reviews/weighted_criterion_director_round5.md", "status": "adjudicated_scoped_unconditional_implication", "novelty_claim": false, "provenance_file": "theorems/weighted_criterion_director_round5.jsonl"}',NULL,'For alpha∈[-3,-2],1≤a<(1-alpha)/2, t=-(alpha+1)/2,c=a-1,b=t-c, u=(1-z)^(-c), the specified D_(alpha+2) target closure implies zeta zero-free Re(s)>b. A continuous radial Lambda_s forRe(s)>b hasLambda_s(u)=-1/s andLambda_s(u h_k)=(1-k^(1-s))zeta(s)/s, with the removable value at s=1 understood.','weighted_Mellin_zero_witness','audits/adversarial_reviews/weighted_criterion_director_round5.md','theorems/weighted_criterion_director_round5.jsonl');
INSERT INTO "claims" VALUES('OBS-WC502','theorems/theorems.jsonl',465,'adjudicated_scoped_verified_versioned_statement_counterexample','Publisherp26; audits/adversarial_reviews/weighted_criterion_director_round5.md','{"id": "OBS-WC502", "paper_id": "PAPER-E012", "kind": "explicit_counterexample_to_versioned_reverse_implication", "statement": "At alpha=-3,a=7/4, published Theorem5.5''s zero-free premise Re(s)>1 is true but its weighted target closure inD_-1 is false. For any nontrivial zero rho withsigma=Re(rho)>=1/2, the target distance is at least |Gamma(rho)|(sigma-1/4)/(sqrt6+7/4)>0.", "hypotheses": "Classical Euler product, existence of a nontrivial zero and reflection; exact source norm and branches. No RH or numerical zero location needed.", "locator": "Publisherp26; audits/adversarial_reviews/weighted_criterion_director_round5.md", "status": "adjudicated_scoped_verified_versioned_statement_counterexample", "novelty_claim": false, "provenance_file": "theorems/weighted_criterion_director_round5.jsonl"}','PAPER-E012','At alpha=-3,a=7/4, published Theorem5.5''s zero-free premise Re(s)>1 is true but its weighted target closure inD_-1 is false. For any nontrivial zero rho withsigma=Re(rho)>=1/2, the target distance is at least |Gamma(rho)|(sigma-1/4)/(sqrt6+7/4)>0.','explicit_counterexample_to_versioned_reverse_implication','Publisherp26; audits/adversarial_reviews/weighted_criterion_director_round5.md','theorems/weighted_criterion_director_round5.jsonl');
INSERT INTO "claims" VALUES('OBS-WC503','theorems/theorems.jsonl',466,'adjudicated_scoped_source_dependent_reconstruction; priority_unassessed','audits/adversarial_reviews/weighted_criterion_director_round5.md; complete independent sufficiency and necessity reviews cited there','{"id": "OBS-WC503", "paper_id": null, "kind": "corrected_weighted_closure_equivalence", "statement": "In exactly the original source parameter range and topology, (1-z)^(1-a) belongs to closedspan{(1-z)^(1-a)h_k:k>=2} inD_(alpha+2) iff zeta has no zeros inRe(s)>b=(1-alpha)/2-a. b∈(0,1].", "hypotheses": "Classical Hadamard/convexity facts; Balazard–Saias general-b uniform Mobius estimate as reproduced inBaez-Duarte math/0202141v2 Lemma2.1 accepted external; b1 uses separately reconstructed unconditional Bergman density.", "locator": "audits/adversarial_reviews/weighted_criterion_director_round5.md; complete independent sufficiency and necessity reviews cited there", "status": "adjudicated_scoped_source_dependent_reconstruction; priority_unassessed", "novelty_claim": false, "provenance_file": "theorems/weighted_criterion_director_round5.jsonl"}',NULL,'In exactly the original source parameter range and topology, (1-z)^(1-a) belongs to closedspan{(1-z)^(1-a)h_k:k>=2} inD_(alpha+2) iff zeta has no zeros inRe(s)>b=(1-alpha)/2-a. b∈(0,1].','corrected_weighted_closure_equivalence','audits/adversarial_reviews/weighted_criterion_director_round5.md; complete independent sufficiency and necessity reviews cited there','theorems/weighted_criterion_director_round5.jsonl');
INSERT INTO "claims" VALUES('OBS-WC504','theorems/theorems.jsonl',467,'adjudicated_scoped_boundary_check; no boundary zero exclusion','audits/adversarial_reviews/gallardo_seco_necessity_threshold62_round5.md; director review','{"id": "OBS-WC504", "paper_id": null, "kind": "sharp_boundary_of_specific_functional", "statement": "ForRe(s)>0, n^(s+c)Lambda_s(z^n) tends (s-1)Gamma(s+c)/(sGamma(s)); on Re(s)=b ands!=1 the functional has no bounded extension toD_(alpha+2). At the sole boundary b=s1, Lambda1 is-f(0) onpolynomials.", "locator": "audits/adversarial_reviews/gallardo_seco_necessity_threshold62_round5.md; director review", "status": "adjudicated_scoped_boundary_check; no boundary zero exclusion", "novelty_claim": false, "provenance_file": "theorems/weighted_criterion_director_round5.jsonl"}',NULL,'ForRe(s)>0, n^(s+c)Lambda_s(z^n) tends (s-1)Gamma(s+c)/(sGamma(s)); on Re(s)=b ands!=1 the functional has no bounded extension toD_(alpha+2). At the sole boundary b=s1, Lambda1 is-f(0) onpolynomials.','sharp_boundary_of_specific_functional','audits/adversarial_reviews/gallardo_seco_necessity_threshold62_round5.md; director review','theorems/weighted_criterion_director_round5.jsonl');
INSERT INTO "claims" VALUES('OBS-WC505','theorems/theorems.jsonl',468,'adjudicated_scoped_unconditional_counterexample','audits/adversarial_reviews/weighted_criterion_director_round5.md; independent Bergman and witness reviews','{"id": "OBS-WC505", "paper_id": null, "kind": "arithmetic_span_closure_topology_counterexample", "statement": "For alpha=-3,c3/4, f0=1/(1-z) lies in ordinaryD_-3 closure ofspanR_k, but not in its closure for norm||g/(1-z)^(3/4)||D_-3. Thus ordinary-to-weighted core transport fails for this exact arithmetic family.", "locator": "audits/adversarial_reviews/weighted_criterion_director_round5.md; independent Bergman and witness reviews", "status": "adjudicated_scoped_unconditional_counterexample", "novelty_claim": false, "provenance_file": "theorems/weighted_criterion_director_round5.jsonl"}',NULL,'For alpha=-3,c3/4, f0=1/(1-z) lies in ordinaryD_-3 closure ofspanR_k, but not in its closure for norm||g/(1-z)^(3/4)||D_-3. Thus ordinary-to-weighted core transport fails for this exact arithmetic family.','arithmetic_span_closure_topology_counterexample','audits/adversarial_reviews/weighted_criterion_director_round5.md; independent Bergman and witness reviews','theorems/weighted_criterion_director_round5.jsonl');
INSERT INTO "claims" VALUES('EXT-E-GS5.5','theorems/theorems.jsonl',469,'printed_reverse_implication_refuted_at_explicit_permitted_parameters; do_not_import_as_verified','Publisher2025p26; arXiv2206.02654v6p21','{"id": "EXT-E-GS5.5", "paper_id": "PAPER-E012", "kind": "printed_source_assertion", "statement": "Inspected Theorem5.5 asserts weighted target closure iff zeta zero-freeRe(s)>t=-(alpha+1)/2, independentlyofa in its printed range.", "locator": "Publisher2025p26; arXiv2206.02654v6p21", "status": "printed_reverse_implication_refuted_at_explicit_permitted_parameters; do_not_import_as_verified", "counterexample": "OBS-WC502", "corrected_reconstruction": "OBS-WC503", "provenance_file": "theorems/weighted_criterion_director_round5.jsonl"}','PAPER-E012','Inspected Theorem5.5 asserts weighted target closure iff zeta zero-freeRe(s)>t=-(alpha+1)/2, independentlyofa in its printed range.','printed_source_assertion','Publisher2025p26; arXiv2206.02654v6p21','theorems/weighted_criterion_director_round5.jsonl');
INSERT INTO "claims" VALUES('LEM-WC-R2-1','theorems/theorems.jsonl',470,'independently_reconstructed_standard_lemma','audits/weighted_criterion_round2.md equationsW1–W3; Wei–Wu Proposition2.14 p12','{"id": "LEM-WC-R2-1", "paper_ids": ["PAPER-E001", "PAPER-C105"], "locator": "audits/weighted_criterion_round2.md equationsW1–W3; Wei–Wu Proposition2.14 p12", "statement": "For finiteD(s)=Σa_n n^(-s), A=D(1), h_D(x)=1+Σa_n{1/(nx)} on(0,1), H_D=Mh_D, one has H_D=(1−ζD)/s+A/(s−1). Therefore F_q=((s−1)/s)(1−ζD)/s^q=((s−1)/s)H_D/s^(q−1)−A/s^q belongsH²(Re(s)>1/2), and its H² norm equals d_q(D) because(s−1)/s is inner for this half-plane.", "hypotheses": ["finite Dirichlet polynomial, exponents n≥1", "integerq≥1", "H² boundary measure dt/(2π)"], "status": "independently_reconstructed_standard_lemma", "verification": "complete explicit Mellin proof; parent review requested", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/weighted_criterion_round2.jsonl"}',NULL,'For finiteD(s)=Σa_n n^(-s), A=D(1), h_D(x)=1+Σa_n{1/(nx)} on(0,1), H_D=Mh_D, one has H_D=(1−ζD)/s+A/(s−1). Therefore F_q=((s−1)/s)(1−ζD)/s^q=((s−1)/s)H_D/s^(q−1)−A/s^q belongsH²(Re(s)>1/2), and its H² norm equals d_q(D) because(s−1)/s is inner for this half-plane.',NULL,'audits/weighted_criterion_round2.md equationsW1–W3; Wei–Wu Proposition2.14 p12','theorems/weighted_criterion_round2.jsonl');
INSERT INTO "claims" VALUES('THM-WC-R2-1','theorems/theorems.jsonl',471,'derived_reconstruction_from_established_q1_criterion','audits/weighted_criterion_round2.md W4–W6','{"id": "THM-WC-R2-1", "paper_ids": ["PAPER-E001", "PAPER-C105"], "locator": "audits/weighted_criterion_round2.md W4–W6", "statement": "For each fixedintegerq≥1, RH iff δ_q(N)=inf_lengthD≤N d_q(D) tends0. Ifρ=β+iγ is a nontrivial zero withβ>1/2, everyfiniteD obeys d_q(D)≥sqrt(2β−1)|ρ−1|/|ρ|^(q+1). Optimizedδ_q is nonincreasing, so liminf0 is equivalent tolimit0.", "status": "derived_reconstruction_from_established_q1_criterion", "verification": "forward by d_q≤2^(q−1)d1; converse by explicitH²representation and Mellin evaluation; parent review requested", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/weighted_criterion_round2.jsonl"}',NULL,'For each fixedintegerq≥1, RH iff δ_q(N)=inf_lengthD≤N d_q(D) tends0. Ifρ=β+iγ is a nontrivial zero withβ>1/2, everyfiniteD obeys d_q(D)≥sqrt(2β−1)|ρ−1|/|ρ|^(q+1). Optimizedδ_q is nonincreasing, so liminf0 is equivalent tolimit0.',NULL,'audits/weighted_criterion_round2.md W4–W6','theorems/weighted_criterion_round2.jsonl');
INSERT INTO "claims" VALUES('OBS-WC-R2-1','theorems/theorems.jsonl',472,'quantifier_scope_observation','audits/weighted_criterion_round2.md §5','{"id": "OBS-WC-R2-1", "paper_ids": ["PAPER-C105"], "locator": "audits/weighted_criterion_round2.md §5", "statement": "For any prescribed familyD_N, liminf d_q(D_N)=0 impliesRH by the same uniformoff-line-zero bound. For fixedSelbergweights, the cited simplicityproof assumesfullsequenceconvergence; a sparse subsequence supplies onlysubsequence Ψ-estimates and does not complete itsglobalAbelianpole argument.", "status": "quantifier_scope_observation", "verification": "logicaldependency checked; no assertion that a strongerliminf⇒simplicity theorem is false", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/weighted_criterion_round2.jsonl"}',NULL,'For any prescribed familyD_N, liminf d_q(D_N)=0 impliesRH by the same uniformoff-line-zero bound. For fixedSelbergweights, the cited simplicityproof assumesfullsequenceconvergence; a sparse subsequence supplies onlysubsequence Ψ-estimates and does not complete itsglobalAbelianpole argument.',NULL,'audits/weighted_criterion_round2.md §5','theorems/weighted_criterion_round2.jsonl');
INSERT INTO "claims" VALUES('LEM-WC-R2-2','theorems/theorems.jsonl',473,'elementary_conditional_interpolation_observation','audits/weighted_criterion_round2.md §5 finalparagraph','{"id": "LEM-WC-R2-2", "paper_ids": ["PAPER-C105"], "locator": "audits/weighted_criterion_round2.md §5 finalparagraph", "statement": "If fixedSelberg error tends0 alongN_k andN_(k+1)−N_k=o(sqrt(N_k)logN_k), thenΨ(N_k)=o(sqrt(N_k)logN_k) extends toallx using|Ψ′|=|M(x)/x|≤1. This recoversRHandsimplicity byWei–Wu pole argument.", "status": "elementary_conditional_interpolation_observation", "verification": "reviewer complete proof; independentreviewpending", "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/weighted_criterion_round2.jsonl"}',NULL,'If fixedSelberg error tends0 alongN_k andN_(k+1)−N_k=o(sqrt(N_k)logN_k), thenΨ(N_k)=o(sqrt(N_k)logN_k) extends toallx using|Ψ′|=|M(x)/x|≤1. This recoversRHandsimplicity byWei–Wu pole argument.',NULL,'audits/weighted_criterion_round2.md §5 finalparagraph','theorems/weighted_criterion_round2.jsonl');
INSERT INTO "claims" VALUES('LEM-WC-R2-3','theorems/theorems.jsonl',474,'elementary_consequence_no_novelty_claim','audits/weighted_criterion_round2.md §6; Ehm§7.1forreciprocalmoments','{"id": "LEM-WC-R2-3", "paper_ids": ["PAPER-C105"], "locator": "audits/weighted_criterion_round2.md §6; Ehm§7.1forreciprocalmoments", "statement": "For every finiteDirichletpolynomialD andintegerq≥1, d_q(D)≥|D(1)|, sinceF_(q,D)(1)=−D(1) andtheH²evaluationnormat1is1. ThereforefixedSelbergfamilyerror≥(1+o1)/logN foranyfixedq≥1.", "status": "elementary_consequence_no_novelty_claim", "verification": "reviewerderivation complete; parent notified", "limitations": ["not anoptimizeddistance lowerbound", "uses fullcritical-line norm"], "novelty_claim": false, "paper_id": null, "provenance_file": "theorems/weighted_criterion_round2.jsonl"}',NULL,'For every finiteDirichletpolynomialD andintegerq≥1, d_q(D)≥|D(1)|, sinceF_(q,D)(1)=−D(1) andtheH²evaluationnormat1is1. ThereforefixedSelbergfamilyerror≥(1+o1)/logN foranyfixedq≥1.',NULL,'audits/weighted_criterion_round2.md §6; Ehm§7.1forreciprocalmoments','theorems/weighted_criterion_round2.jsonl');
