INSERT INTO "claims" VALUES('THM-E-GS302','theorems/theorems.jsonl',477,'localized_formula_reconstruction_independent_review_pending','PAPER-E012preprintp5/journalp6Lemma2.3; audits/gallardo_seco_endpoint_round3.md§B','{"id": "THM-E-GS302", "paper_id": null, "statement": "For f(x)=sum_(k1..N)c_k{1/(kx)},sumc_k/k=0,Res>0, Mellin integral0¹ f(x)x^(s−1)dx=−zeta(s)/s sum_(k1..N)c_k k^-s, removableat1. PrintedLemma2.3sumstartsk2missesc1. WitnessN2,c1−1,c2=2,s2hasactualintegralzeta2/4>0,printedvalue−zeta2/4. Repairpreserveszero-exclusionargument.", "hypotheses": "FiniteN,fullconstrainedfractional-partcoefficientvector; samec_kthroughformula; nochangeofbasiswithoutrescaling.", "locator": "PAPER-E012preprintp5/journalp6Lemma2.3; audits/gallardo_seco_endpoint_round3.md§B", "status": "localized_formula_reconstruction_independent_review_pending", "verification": "Actualbothversionsvisuallyinspected; independentdirectMellincalculation/paritywitness; parentreviewrequested.", "novelty": "classicalMellinidentity; no noveltyclaim", "provenance_file": "theorems/weighted_dirichlet_round3.jsonl"}',NULL,'For f(x)=sum_(k1..N)c_k{1/(kx)},sumc_k/k=0,Res>0, Mellin integral0¹ f(x)x^(s−1)dx=−zeta(s)/s sum_(k1..N)c_k k^-s, removableat1. PrintedLemma2.3sumstartsk2missesc1. WitnessN2,c1−1,c2=2,s2hasactualintegralzeta2/4>0,printedvalue−zeta2/4. Repairpreserveszero-exclusionargument.',NULL,'PAPER-E012preprintp5/journalp6Lemma2.3; audits/gallardo_seco_endpoint_round3.md§B','theorems/weighted_dirichlet_round3.jsonl');
