INSERT INTO "claims" VALUES('OP62-CONNES-WEIGHTED','theorems/theorems.jsonl',479,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"id": "OP62-CONNES-WEIGHTED", "paper_id": "PAPER-OP62-CONNES", "source_locator": "§III, Thm. 1, p. 13", "locator": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped", "statement": "For δ>1 the discrete spectrum on Hχ is the critical-line zero ordinates in iR only, with multiplicity min(actual zero order, largest integer strictly below (1+δ)/2).", "source_proof_reconstructed": false, "novelty_claim": false, "provenance_file": "theorems/witness62_operator_frontier_exact.jsonl"}','PAPER-OP62-CONNES','For δ>1 the discrete spectrum on Hχ is the critical-line zero ordinates in iR only, with multiplicity min(actual zero order, largest integer strictly below (1+δ)/2).',NULL,'audits/adversarial_reviews/witness62_operator_frontier.md','theorems/witness62_operator_frontier_exact.jsonl');
INSERT INTO "claims" VALUES('OP62-CONNES-CUTOFF','theorems/theorems.jsonl',480,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"id": "OP62-CONNES-CUTOFF", "paper_id": "PAPER-OP62-CONNES", "source_locator": "§VIII, Thm. 5 and Eq. (16); §IX, pp. 45–47", "locator": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped", "statement": "For a positive-characteristic global field, the cutoff trace identity on compactly supported test functions is equivalent to RH for every Grössencharakter L-function. The archimedean discussion instead changes the cutoff.", "source_proof_reconstructed": false, "novelty_claim": false, "provenance_file": "theorems/witness62_operator_frontier_exact.jsonl"}','PAPER-OP62-CONNES','For a positive-characteristic global field, the cutoff trace identity on compactly supported test functions is equivalent to RH for every Grössencharakter L-function. The archimedean discussion instead changes the cutoff.',NULL,'audits/adversarial_reviews/witness62_operator_frontier.md','theorems/witness62_operator_frontier_exact.jsonl');
INSERT INTO "claims" VALUES('OP62-CONREYLI-ENTIRE','theorems/theorems.jsonl',481,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"id": "OP62-CONREYLI-ENTIRE", "paper_id": "PAPER-OP62-CONREYLI", "source_locator": "§2, Thm. 1; §3.1, Eq. (3.2)", "locator": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped", "statement": "For E satisfying the theorem’s entire-function, no-real-zero, strict Hermite–Biehler, unit-modulus shift and vertical monotonicity hypotheses, nonnegative real shift form on the simultaneous translate domain forces Im(w)=-1/2 and the stated derivative sign. The paper reports a negative sign for the natural xi model.", "source_proof_reconstructed": false, "novelty_claim": false, "provenance_file": "theorems/witness62_operator_frontier_exact.jsonl"}','PAPER-OP62-CONREYLI','For E satisfying the theorem’s entire-function, no-real-zero, strict Hermite–Biehler, unit-modulus shift and vertical monotonicity hypotheses, nonnegative real shift form on the simultaneous translate domain forces Im(w)=-1/2 and the stated derivative sign. The paper reports a negative sign for the natural xi model.',NULL,'audits/adversarial_reviews/witness62_operator_frontier.md','theorems/witness62_operator_frontier_exact.jsonl');
INSERT INTO "claims" VALUES('OP62-CONREYLI-HALFPLANE','theorems/theorems.jsonl',482,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"id": "OP62-CONREYLI-HALFPLANE", "paper_id": "PAPER-OP62-CONREYLI", "source_locator": "§2, Thm. 2; §3.1, Eq. (3.4)", "locator": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped", "statement": "For W analytic and zero-free in the upper half-plane, a kernel-translation linear operator on F(W) with nonnegative real numerical range forces continuation to Im(z)>-1/2 and a nonnegative quotient real part there. The paper reports a negative quotient real part in the natural reciprocal-xi model.", "source_proof_reconstructed": false, "novelty_claim": false, "provenance_file": "theorems/witness62_operator_frontier_exact.jsonl"}','PAPER-OP62-CONREYLI','For W analytic and zero-free in the upper half-plane, a kernel-translation linear operator on F(W) with nonnegative real numerical range forces continuation to Im(z)>-1/2 and a nonnegative quotient real part there. The paper reports a negative quotient real part in the natural reciprocal-xi model.',NULL,'audits/adversarial_reviews/witness62_operator_frontier.md','theorems/witness62_operator_frontier_exact.jsonl');
INSERT INTO "claims" VALUES('OP62-SUZUKI-INNER','theorems/theorems.jsonl',483,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"id": "OP62-SUZUKI-INNER", "paper_id": "PAPER-OP62-SUZUKI", "source_locator": "§1.4, Prop. 1.2; §2, Thm. 2.2", "locator": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped", "statement": "For fixed ω0≥0, zero-freeness in Re(s)>1/2+ω0 is equivalent to meromorphic innerness for all ω>ω0. For each fixed positive ω innerness is equivalent to the stated full-domain arithmetic Mellin convolution conditions.", "source_proof_reconstructed": false, "novelty_claim": false, "provenance_file": "theorems/witness62_operator_frontier_exact.jsonl"}','PAPER-OP62-SUZUKI','For fixed ω0≥0, zero-freeness in Re(s)>1/2+ω0 is equivalent to meromorphic innerness for all ω>ω0. For each fixed positive ω innerness is equivalent to the stated full-domain arithmetic Mellin convolution conditions.',NULL,'audits/adversarial_reviews/witness62_operator_frontier.md','theorems/witness62_operator_frontier_exact.jsonl');
INSERT INTO "claims" VALUES('OP62-SUZUKI-KERNEL','theorems/theorems.jsonl',484,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"id": "OP62-SUZUKI-KERNEL", "paper_id": "PAPER-OP62-SUZUKI", "source_locator": "§2, Thm. 2.3 and following discussion", "locator": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped", "statement": "Explicit determinant-ratio canonical Hamiltonian construction assumes ω>1. The stated weaker compressed-kernel conclusions include Hilbert–Schmidt and invertibility for ω>1/2 and compact self-adjointness for ω>0.", "source_proof_reconstructed": false, "novelty_claim": false, "provenance_file": "theorems/witness62_operator_frontier_exact.jsonl"}','PAPER-OP62-SUZUKI','Explicit determinant-ratio canonical Hamiltonian construction assumes ω>1. The stated weaker compressed-kernel conclusions include Hilbert–Schmidt and invertibility for ω>1/2 and compact self-adjointness for ω>0.',NULL,'audits/adversarial_reviews/witness62_operator_frontier.md','theorems/witness62_operator_frontier_exact.jsonl');
INSERT INTO "claims" VALUES('OP62-MEYER-SPECTRUM','theorems/theorems.jsonl',485,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"id": "OP62-MEYER-SPECTRUM", "paper_id": "PAPER-OP62-MEYER", "source_locator": "§4.2, Cor. 4.2", "locator": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped", "statement": "Eigenvalues of the transpose on the continuous dual of the nuclear Fréchet quotient equal the zeros of the meromorphic completed zeta, with algebraic multiplicities equal to zero orders.", "source_proof_reconstructed": false, "novelty_claim": false, "provenance_file": "theorems/witness62_operator_frontier_exact.jsonl"}','PAPER-OP62-MEYER','Eigenvalues of the transpose on the continuous dual of the nuclear Fréchet quotient equal the zeros of the meromorphic completed zeta, with algebraic multiplicities equal to zero orders.',NULL,'audits/adversarial_reviews/witness62_operator_frontier.md','theorems/witness62_operator_frontier_exact.jsonl');
INSERT INTO "claims" VALUES('OP62-MEYER-TRACE','theorems/theorems.jsonl',486,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"id": "OP62-MEYER-TRACE", "paper_id": "PAPER-OP62-MEYER", "source_locator": "§5, Thm. 5.8", "locator": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped", "statement": "For all f in the specified test algebra the signed Mellin spectral sum equals the virtual character and sum of local distributions, with pole orders positive and zero orders negative. Density in the proof is density of convolutions of compactly supported smooth functions in the test algebra.", "source_proof_reconstructed": false, "novelty_claim": false, "provenance_file": "theorems/witness62_operator_frontier_exact.jsonl"}','PAPER-OP62-MEYER','For all f in the specified test algebra the signed Mellin spectral sum equals the virtual character and sum of local distributions, with pole orders positive and zero orders negative. Density in the proof is density of convolutions of compactly supported smooth functions in the test algebra.',NULL,'audits/adversarial_reviews/witness62_operator_frontier.md','theorems/witness62_operator_frontier_exact.jsonl');
INSERT INTO "claims" VALUES('OP62-WEIL72-POSITIVE','theorems/theorems.jsonl',487,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"id": "OP62-WEIL72-POSITIVE", "paper_id": "PAPER-OP62-WEIL72", "source_locator": "French original, §16, p. 18", "locator": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped", "statement": "Positivity of the explicit-formula distribution on W is stated to be equivalent to the conjunction of RH and Artin’s conjecture for all L_k(χ,s).", "source_proof_reconstructed": false, "novelty_claim": false, "provenance_file": "theorems/witness62_operator_frontier_exact.jsonl"}','PAPER-OP62-WEIL72','Positivity of the explicit-formula distribution on W is stated to be equivalent to the conjunction of RH and Artin’s conjecture for all L_k(χ,s).',NULL,'audits/adversarial_reviews/witness62_operator_frontier.md','theorems/witness62_operator_frontier_exact.jsonl');
INSERT INTO "claims" VALUES('OBS-LI-001','theorems/theorems.jsonl',488,'independently_reconstructed_generic_class_obstruction; no novelty claim','proposals/independent_campaigns/li_advocate.md','{"id": "OBS-LI-001", "paper_id": null, "statement": "For every N there is a real symmetric order-one entire function with all zeros in the critical strip, first N Li derivatives positive, and an off-line quartet. This remains true with Riemann–von Mangoldt smooth zero count to O(1).", "locator": "proposals/independent_campaigns/li_advocate.md", "status": "independently_reconstructed_generic_class_obstruction; no novelty claim", "verification": "scoped_Level3; director_adjudication.md"}',NULL,'For every N there is a real symmetric order-one entire function with all zeros in the critical strip, first N Li derivatives positive, and an off-line quartet. This remains true with Riemann–von Mangoldt smooth zero count to O(1).',NULL,'proposals/independent_campaigns/li_advocate.md',NULL);
INSERT INTO "claims" VALUES('OBS-R001-FINITE','theorems/theorems.jsonl',489,'known_finite_step_independently_reproduced','experiments/code/lagarias_finite.py','{"id": "OBS-R001-FINITE", "paper_id": "PAPER-R001", "statement": "For all integers2<=n<=5040, sigma(n)<H_n+exp(H_n)logH_n; equality at1.", "locator": "experiments/code/lagarias_finite.py", "status": "known_finite_step_independently_reproduced", "verification": "exact_integer_certificate_and_independent_review"}','PAPER-R001','For all integers2<=n<=5040, sigma(n)<H_n+exp(H_n)logH_n; equality at1.',NULL,'experiments/code/lagarias_finite.py',NULL);
INSERT INTO "connections" VALUES('CONN-A001','connections/connections.jsonl',1,'single-agent checked; independent review pending','connections/analytic_track.jsonl','{"connection_id": "CONN-A001", "source_theorems": ["THM-A002", "PAPER-A006:Theorem3"], "kind": "quantified obstruction", "statement": "Guth–Maynard''s density upper bound alone does not verify BGSTB''s strong-density premise. At sigma=3/4 it gives exponent5/9; premise asks o(T^{1/2}).", "compatible_assumptions": "Fixed sigma3/4 lies in required BGSTB range; two-sided vs positive heights changes only constant, irrelevant to exponent.", "already_proved": "Original bounds as stated, exact exponent arithmetic.", "conjectural": "Actual strong density may hold; no refutation implied.", "next_step": "Prove o(T^{2(1-sigma)}) with required uniformity in moving endpoint range, or bypass that premise as Lamzouri''s finite inequality does.", "counterexample_to_inference": "Numerical growth model M(T)=T^{19/36} satisfies an O(T^{5/9}) bound but is not o(T^{1/2}); this is a logical growth witness, not a zero distribution.", "tests": "Fraction arithmetic in experiments/code/analytic_checks.py", "significance": "Prevents erroneous theorem chaining; identifies a real exponent/quantifier gap.", "difficulty": "high for stronger analytic theorem; arithmetic check elementary", "status": "single-agent checked; independent review pending", "id": "CONN-A001", "provenance_file": "connections/analytic_track.jsonl"}','Guth–Maynard''s density upper bound alone does not verify BGSTB''s strong-density premise. At sigma=3/4 it gives exponent5/9; premise asks o(T^{1/2}).','connections/analytic_track.jsonl');
INSERT INTO "connections" VALUES('CONN-A002','connections/connections.jsonl',2,'single-agent reconstructed; independent review pending','connections/analytic_track.jsonl','{"connection_id": "CONN-A002", "source_theorems": ["THM-A004", "THM-A005", "PAPER-A003:Lemma3.2"], "kind": "established source connection, not new discovery", "statement": "Fixed-test unconditional weighted pair correlation combines with conjugation-symmetric tensor positivity after differential deweighting Q-Q''''/(4log^2T).", "compatible_assumptions": "eta smooth real even supported strictly inside(-1/2,1/2), integral eta^2=1; Q=eta^2*eta^2 and Q'''' fixed, smooth, supported[-1,1]; zero multiset conjugation invariant.", "already_proved": "Lamzouri states and proves this in section3; local Fourier algebra checked here.", "conjectural": "Effective finite-T bound with completely explicit constants not derived here.", "next_step": "Extract effective dependence on Q and Q'''' from BGSTB proof, keep smoothing fixed before T-limit.", "potential_counterexamples": "Dropping conjugation symmetry fails already at Z={i}; varying tests without uniform error control invalidates inference.", "tests": "Random finite multiset stress tests are nonrigorous supplements only.", "significance": "Reusable way to replace termwise positivity by a global Hilbert-space norm.", "difficulty": "moderate effective reconstruction, substantial analytic bookkeeping", "status": "single-agent reconstructed; independent review pending", "id": "CONN-A002", "provenance_file": "connections/analytic_track.jsonl"}','Fixed-test unconditional weighted pair correlation combines with conjugation-symmetric tensor positivity after differential deweighting Q-Q''''/(4log^2T).','connections/analytic_track.jsonl');
INSERT INTO "connections" VALUES('CONN-A003','connections/connections.jsonl',3,'source-backed research target; no new bound proved','connections/analytic_track.jsonl','{"connection_id": "CONN-A003", "source_theorems": ["PAPER-A001:section13.1 final remark", "PAPER-A001:Proposition3.1", "PAPER-A001:equation7.2"], "kind": "precise method-transfer target", "statement": "At the density-envelope bottleneck sigma7/10, improved S3 control must confront near-extremal sets with |W|~T1^{2/3}, energy~|W|^{5/2}, and R(v)=sum_W |v|^{it} concentrated near rationals of scale T1^{1/3}.", "already_proved": "Authors identify this obstruction; S1/S2 tight within their framework.", "conjectural": "An incidence-theoretic or rational-concentration inverse theorem can yield a power saving for all relevant W.", "next_step": "Reconstruct Proposition9.1 sharpness configuration, quantify exclusion needed for S3 saving, then test against clustered arithmetic/rational models.", "potential_counterexamples": "Generic-random-set gains do not cover worst-case large-value sets.", "significance": "Targets exact loss instead of vague transplant rhetoric.", "difficulty": "very high", "status": "source-backed research target; no new bound proved", "id": "CONN-A003", "provenance_file": "connections/analytic_track.jsonl"}','At the density-envelope bottleneck sigma7/10, improved S3 control must confront near-extremal sets with |W|~T1^{2/3}, energy~|W|^{5/2}, and R(v)=sum_W |v|^{it} concentrated near rationals of scale T1^{1/3}.','connections/analytic_track.jsonl');
