INSERT INTO "connections" VALUES('CONN-AGGREGATE-CUTOFF-EXTENSION','connections/connections.jsonl',17,'adjudicated_scoped','audits/adversarial_reviews/director_polynomial_bands_round11.md','{"id": "CONN-AGGREGATE-CUTOFF-EXTENSION", "sources": ["THM-SCALAR-PRIME-SUBPOWER-POLYNOMIAL", "THM-SHARP-AGGREGATE-CONTINUOUS-J"], "statement": "Use the full shifted quadratic form before expansion to avoid exponential loss from summing individual character errors.", "hypotheses": "The zero law assumes RH. Uses bounded Dirichlet coefficients, padded divisor-closed families, and declared length below √T.", "already_proved": "All fixed moments for subpower cutoffs and the weak scalar CLT at polynomial cutoffs.", "conjectural": "All moments at fixed θ and general unbounded joint arrays remain unestablished.", "next_step": "Find a uniform higher-order main-term and error estimate or a fixed-band characteristic-function estimate.", "counterexamples": "An arbitrary fixed logarithmic saving cannot absorb exp(L^a) words. The polynomial local factor F differs from 1.", "tests": "Independent reconstructions of aggregate padding, the sharp approximate functional equation, and strict Stieltjes integration.", "significance": "Extends the earlier logarithmic cutoffs.", "difficulty": "See the proof and next step. Priority remains unresolved or the classical antecedent is credited.", "status": "adjudicated_scoped", "evidence": "audits/adversarial_reviews/director_polynomial_bands_round11.md", "provenance_file": "connections/director_round11_connections.jsonl"}','Use the full shifted quadratic form before expansion to avoid exponential loss from summing individual character errors.','connections/director_round11_connections.jsonl');
INSERT INTO "connections" VALUES('CONN-ROOTED-CUE-NONGAUSSIAN-BANDS','connections/connections.jsonl',18,'adjudicated_scoped','audits/adversarial_reviews/director_polynomial_bands_round11.md','{"id": "CONN-ROOTED-CUE-NONGAUSSIAN-BANDS", "sources": ["THM-POLYNOMIAL-PRIME-BAND-COVARIANCE", "THM-POLYNOMIAL-PRIME-BAND-NONGAUSSIAN", "THM-ROOTED-CUE-PRIME-BAND-MOMENT-MATCH"], "statement": "The derivative-rooted CUE rank-two projection and exact HLZ local kernels give the same band means, covariance, and centered cosine third moment.", "hypotheses": "The covariance range is 0 < a < b < 1/4 and the cubic requires b < 1/6. Uses the symmetric derivative-weighted tail under RH and the global joint Haar matrix and root-label tilt.", "already_proved": "Explicit means, rank-two and rank-one covariance corrections, a negative cubic, and exclusion of Gaussian weak subsequences.", "conjectural": "The full band law and matching higher moments remain open.", "next_step": "Characterize the candidate DPP band law and the exact arithmetic estimate needed to transfer it.", "counterexamples": "Normalizing root-label sampling within each matrix gives a different measure. Matching these moments does not identify the law.", "tests": "Three independent HLZ extractions, exact CUE projection traces, and uniform fourth moments.", "significance": "Connects the arithmetic and random matrix calculations through explicit moments.", "difficulty": "See the proof and next step. Priority remains unresolved or the classical antecedent is credited.", "status": "adjudicated_scoped", "evidence": "audits/adversarial_reviews/director_polynomial_bands_round11.md", "provenance_file": "connections/director_round11_connections.jsonl"}','The derivative-rooted CUE rank-two projection and exact HLZ local kernels give the same band means, covariance, and centered cosine third moment.','connections/director_round11_connections.jsonl');
INSERT INTO "connections" VALUES('CONN-LOCAL-MASS-PROCESS-TIGHTNESS','connections/connections.jsonl',19,'adjudicated_scoped','audits/adversarial_reviews/director_joint_brownian_round11.md','{"id": "CONN-LOCAL-MASS-PROCESS-TIGHTNESS", "sources": ["THM-JOINT-PRIME-GAUSSIAN-ARRAY", "THM-PRIME-BROWNIAN-PROCESS"], "statement": "Local reciprocal-mass fourth moments turn finite-dimensional arithmetic phase comparison into Brownian path convergence.", "hypotheses": "Assumes RH and uses the fixed Brownian logarithmic clock and symmetric strict tail.", "already_proved": "An all-time interpolated increment bound, an effective modulus, and the J₁ limit.", "conjectural": "Larger-cutoff processes and numerical rates at finite Y require separate research.", "next_step": "Extend the local mass bound to larger cutoffs without introducing an interval-independent error.", "counterexamples": "Finite-dimensional convergence alone does not give tightness. The wrong log-power clock gives perfectly correlated limits.", "tests": "Independent three-piece interpolation and dyadic chaining.", "significance": "The tightness argument specifies the clock and sampling measure.", "difficulty": "See the proof and next step. Priority remains unresolved or the classical antecedent is credited.", "status": "adjudicated_scoped", "evidence": "audits/adversarial_reviews/director_joint_brownian_round11.md", "provenance_file": "connections/director_round11_connections.jsonl"}','Local reciprocal-mass fourth moments turn finite-dimensional arithmetic phase comparison into Brownian path convergence.','connections/director_round11_connections.jsonl');
INSERT INTO "connections" VALUES('CONN-INTEGER-TRACE-CLASSICAL-TOEPLITZ','connections/connections.jsonl',20,'adjudicated_scoped','audits/adversarial_reviews/director_integer_trace_round11.md','{"id": "CONN-INTEGER-TRACE-CLASSICAL-TOEPLITZ", "sources": ["THM-INTEGER-TOEPLITZ-PURITY", "THM-INTEGRAL-TRACE-FINITE-CUTOFF"], "statement": "Classical power-sum Toeplitz inertia becomes an exact low-index integer purity certificate by arithmetic congruence.", "hypotheses": "One fixed monic integral q-reciprocal spectrum with positive multiplicities.", "already_proved": "A positive semidefiniteness criterion and inertia from traces through d − 1, with a polynomial-bit algorithm.", "conjectural": "An infinite trace realization of the classical zeta function remains open.", "next_step": "Test candidate finite Frobenius models with K, then prove compatible trace and positivity limits.", "counterexamples": "Individual two-term tests and leading minors alone fail. The ordinary Schur–Cohn form vanishes.", "tests": "Independent Vandermonde congruences and exact singular, repeated-root, and nonsquare cases.", "significance": "Makes the existing criterion computationally usable and credits its antecedent.", "difficulty": "See the proof and next step. Priority remains unresolved or the classical antecedent is credited.", "status": "adjudicated_scoped", "evidence": "audits/adversarial_reviews/director_integer_trace_round11.md", "provenance_file": "connections/director_round11_connections.jsonl"}','Classical power-sum Toeplitz inertia becomes an exact low-index integer purity certificate by arithmetic congruence.','connections/director_round11_connections.jsonl');
INSERT INTO "connections" VALUES('CONN-DENINGER-REAL-QUATERNIONIC-BOUNDARY','connections/connections.jsonl',21,'adjudicated_scoped','audits/adversarial_reviews/director_deninger_whole_round11.md','{"id": "CONN-DENINGER-REAL-QUATERNIONIC-BOUNDARY", "sources": ["THM-DENINGER-REAL-DESCENT-OBSTRUCTION"], "statement": "An Artin root-number parity supplies an exact obstruction to ordinary real functorial spectral descent.", "hypotheses": "Central Artin multiplicity compatibility and a field with a negative-sign quaternionic sector.", "already_proved": "The multiplicity contradiction excludes a universal ordinary real theory.", "conjectural": "Constructing positive complex or quaternionic cohomology or an isolated operator over ℚ remains open.", "next_step": "Specify the Galois-equivariant star and prove positivity on every spectral sector.", "counterexamples": "Even parity of the whole space or height positivity on a subsector is insufficient.", "tests": "Independent original root-number witnesses and the antilinear map on the Hom space with square −1.", "significance": "Identifies the hypotheses of a known structural obstruction.", "difficulty": "See the proof and next step. Priority remains unresolved or the classical antecedent is credited.", "status": "adjudicated_scoped", "evidence": "audits/adversarial_reviews/director_deninger_whole_round11.md", "provenance_file": "connections/director_round11_connections.jsonl"}','An Artin root-number parity supplies an exact obstruction to ordinary real functorial spectral descent.','connections/director_round11_connections.jsonl');
INSERT INTO "connections" VALUES('CONN-FINITE-PHASE-EFFECTIVITY','connections/connections.jsonl',22,'adjudicated_scoped_unconditional_lower_conditional_two_sided','audits/adversarial_reviews/director_finite_lower_round8.md','{"id": "CONN-FINITE-PHASE-EFFECTIVITY", "source_theorems": ["THM-FINITE-PHASE-LOWER", "CERT-ZETA-FINITE-LOWER", "CERT-CHI4-FINITE-LOWER", "EFFECTIVE-CLUSTER62-UPPER"], "statement": "A fixed finite phase Gram projection supplies the effective lower half of a two-sided optimized-distance tolerance certificate, matching the adaptive effective-input upper.", "compatible_assumptions": "Unconditional lower for actual critical-line zeros; RH and supplied global analytic/finite-cluster certificates only for upper and full constant comparison; same dt/[2pi(1/4+t²)] norm and ordinary lengthN space.", "new_claim_suggested": "Instantiate one complete certified height list and global majorants to produce a genuine numerical two-sided threshold.", "already_proved": "Finite-set lower S_R-C_R/logN, exact small-interval Gram cancellation, four beta cutoffs and a positive one-zeta-zero bound; abstract upper/lower tolerance procedure.", "conjectural_or_unresolved": "No complete numerical upper-majorant package, no practical global N0, no uniform C_R growth.", "next_precise_step": "Compute certified finite-set C_R and tail Theta_Y for one fixed Y, then supply each named upper majorant rather than inferring them from a qualitative liminf.", "potential_counterexamples": "Approximate nonzero evaluation points do not annihilate arbitrary coefficients; summing all zeros of an imprimitive Euler factor gives a wrong constant; qualitative convergence supplies no modulus.", "tests": "Root reran both FLINT programs with analytic series tails; Gram determinant and root IVT signs are interval certified.", "significance": "Turns a qualitative limiting comparison into an explicit relative certificate interface.", "difficulty": "Finite formulas established; global analytic constants and large finite jets remain demanding.", "evidence": "audits/adversarial_reviews/director_finite_lower_round8.md", "status": "adjudicated_scoped_unconditional_lower_conditional_two_sided", "provenance_file": "connections/director_round8_connections.jsonl"}','A fixed finite phase Gram projection supplies the effective lower half of a two-sided optimized-distance tolerance certificate, matching the adaptive effective-input upper.','connections/director_round8_connections.jsonl');
INSERT INTO "connections" VALUES('CONN-PREFIX-MULTIPLICITY-INVERSE','connections/connections.jsonl',23,'adjudicated_scoped_RH_conditional_arithmetic_connection','audits/adversarial_reviews/director_prefix_inverse_round8.md; audits/adversarial_reviews/director_rst048_prefix_round8.md','{"id": "CONN-PREFIX-MULTIPLICITY-INVERSE", "source_theorems": ["THM-RST048-PREFIX", "OBS-PREFIX-CLOSED", "EFFECTIVE-CLUSTER62-PREFIX-MOMENT-INVERSION", "EFFECTIVE-CLUSTER62-PREFIX-MOMENT-SHARP", "EFFECTIVE-CLUSTER62-PREFIX-FINITE-DATA"], "statement": "The fixed-prefix arithmetic optimum under RH encodes a determinate positive moment measure of weighted zero multiplicities; endpoint growth detects maximum multiplicity.", "compatible_assumptions": "RH only for arithmetic limit interpretation and punctured-plane extension; actual-zero unit-height count suffices for local germ/determinacy; b fixed before N limit.", "new_claim_suggested": "An arithmetic estimate C(b)=o((1-b)^(-1)) as b approaches1 would force simple zeros under RH.", "already_proved": "Triangular Legendre coefficients recover all positive moments; square-root exponential moment gives determinacy, hence every W_m; exact radius from weight limsup and finite-data obstructions.", "conjectural_or_unresolved": "No endpoint arithmetic upper estimate, no stable finite-data algorithm, no zero ordinates recovered, no priority claim.", "next_precise_step": "Bound the limiting arithmetic prefix cost near b1 with a proved order of limits or new uniform construction, rather than differentiating finite-N staircases.", "potential_counterexamples": "Synthetic positive profiles can match arbitrarily many finite coefficients and have different maximum multiplicity; tiny high-mass indices evade any positive compact-range tolerance; C prime(0)=0 is a special exact positive certificate.", "tests": "Independent exact coefficient expansions through order9,110 Legendre coefficient checks and finite barycentric controls.", "significance": "A precise