INSERT INTO "connections" VALUES('CONN-YE-SHORT-WEIGHTED-DENSITY','connections/connections.jsonl',24,'adjudicated_scoped_source_dependent','audits/adversarial_reviews/director_ye_corollaries_round8.md','{"id": "CONN-YE-SHORT-WEIGHTED-DENSITY", "source_theorems": ["CAND-LATEST62-YE-SHORT-FOURTH", "CAND-LATEST62-YE-LOCAL-BGSTB"], "statement": "The fourth-moment short-window density theorem controls an exponentially weighted zero sum on one height slice, but covering a full block destroys its saving.", "compatible_assumptions": "Ye2610.15989v2 Thm1.1 accepted as external input, same-real-start moment inclusion, fixed positive horizontal gap d, real-start windows U^(3/5). No external fixed global cutoff needed here.", "new_claim_suggested": "Find an averaged or correlated full-height estimate avoiding the T^(2/5) union cost.", "already_proved": "Local weighted sum O(T^(1-d/2+epsilon)) with multiplicities and horizontal boundary handling.", "conjectural_or_unresolved": "Global weighted BGSTB moment remains unproved from this input.", "next_precise_step": "Establish a full-height weighted estimate with an extra saving exceeding the covering cost, or exploit a rigorous signed cancellation unavailable to a positive majorant.", "potential_counterexamples": "A local o(T) estimate does not sum to a full-block o(T); replacing sigma-uniform bounds by pointwise bounds can invalidate the layer integral.", "tests": "Two independent parameter balances and root verification of source quantifiers.", "significance": "Exact hypothesis mismatch prevents an invalid arithmetic transfer while identifying the needed strengthening.", "difficulty": "Source-dependent local consequence straightforward; global improvement substantial.", "evidence": "audits/adversarial_reviews/director_ye_corollaries_round8.md", "status": "adjudicated_scoped_source_dependent", "provenance_file": "connections/director_round8_connections.jsonl"}','The fourth-moment short-window density theorem controls an exponentially weighted zero sum on one height slice, but covering a full block destroys its saving.','connections/director_round8_connections.jsonl');
INSERT INTO "connections" VALUES('CONN-CHARACTER-ANCHOR-BOUNDARY','connections/connections.jsonl',25,'adjudicated_scoped_unconditional_transfer_conditional_limit','audits/adversarial_reviews/director_imprimitive_anchor_round8.md','{"id": "CONN-CHARACTER-ANCHOR-BOUNDARY", "source_theorems": ["PREFIX-FORMULA62-IMPRIMITIVE-SANDWICH", "PREFIX-FORMULA62-IMPRIMITIVE-OPTIMUM", "PREFIX-FORMULA62-NONPRINCIPAL-ANCHOR", "THM-ADAPTIVE-DIRICHLET-OPT"], "statement": "Finite Euler-factor division preserves unrestricted optimized distance, while Hardy evaluation separates entire nonprincipal L-functions from pole-bearing principal characters under the zero-at-one anchor.", "compatible_assumptions": "Each character/modulus fixed; full Cauchy norm; arbitrary complex ordinary coefficients. Anchor A(1)=0 imposed only in the separate assertion.", "new_claim_suggested": "Choose any additional linear approximation constraint using the actual Hardy target evaluation and pole order, rather than transferring the zeta anchor mechanically.", "already_proved": "Exact finite cutoff sandwich and polylogarithmic length loss; same critical-line multiplicity constant under inducing GRH; unconditional nonprincipal anchored distance1 and principal length-two strict improvement.", "conjectural_or_unresolved": "Optimal constants for other constraints, uniform growing conductor and ramified-support restrictions require new arguments.", "next_precise_step": "Compute the Hardy projection for one deliberately chosen nonprincipal linear constraint and identify its limiting feasible target.", "potential_counterexamples": "Counting Re0 Euler-factor zeros changes the wrong constant; reciprocal coefficients on critical line are not absolutely summable; imposing A(1)=0 for an entire L-function blocks convergence.", "tests": "Two independent transfer cutoffs and two independent H² evaluation proofs, with explicit principal length-two control.", "significance": "Precise reusable transfer theorem and obstruction for