INSERT INTO "connections" VALUES('CONN-E-W305','connections/connections.jsonl',85,'exact_negative_witness; m3SOS_independent_review_pending','proposals/independent_campaigns/scalar_window_coalescence_maximum_round3.md','{"id": "CONN-E-W305", "source_papers": [], "source_theorems": ["THM-E-W302", "THM-E-W306"], "claim": "Nonnegative Laurent autocorrelation proves the exact two-root maximum but cannot extend verbatim to all degree: m3,M2 has coefficient−4 for multi-index(−1,−1,2) in M^(2m)E. A discriminant-based gap decomposition proves this case despite the negative coefficient.", "verified_compatible_assumptions": "Exact integer Laurent arithmetic and unit-root cubic discriminant, only the displayed finite cases.", "established_part": "Negative raw Laurent coefficient is a verified failed proof strategy witness; it does not refute coalescence maximum.", "conjectural_part": "General degree/root-configuration maximum.", "next_step": "Seek valid symmetric gap decomposition or exact rational counterexample.", "counterexample_risks": ["Negative Fourier coefficient is not itself a maximizing-configuration counterexample."], "tests": "experiments/code/scalar_window_laurent_round3.py;scalar_window_m3_invariants_round3.py", "evidence": "proposals/independent_campaigns/scalar_window_coalescence_maximum_round3.md", "verification": "exact_negative_witness; m3SOS_independent_review_pending", "novelty": "unassessed_not_claimed", "provenance_file": "connections/scalar_window_round3.jsonl"}','Nonnegative Laurent autocorrelation proves the exact two-root maximum but cannot extend verbatim to all degree: m3,M2 has coefficient−4 for multi-index(−1,−1,2) in M^(2m)E. A discriminant-based gap decomposition proves this case despite the negative coefficient.','connections/scalar_window_round3.jsonl');
