INSERT INTO "findings" VALUES('FIND-DR2006-HARDY-DERIVATIVE','audits/findings.jsonl',1,'director_adjudicated_exact_printed_identity_counterexample_and_repair; main_theorem_preserved','audits/adversarial_reviews/director_deroton_hardy_round6.md; originalPDFSHA2566b379ceeead2c10e614bd4be268c9672f0b364fa95799a5474a9479a82f9e445','{"id": "FIND-DR2006-HARDY-DERIVATIVE", "classification": "Verified mathematical error", "title": "Printed Proposition6.4 leaves the Hardy multiplier outside a parameter derivative", "sources": ["PAPER-DR2006:Proposition6.4_printedp440", "PAPER-DR2006:Proposition6.5_printedp441"], "scope": "Exact displayed small-t identity in the pinned2006print, notTheorem2. Correct whole-derivative formula recovers Proposition6.5 and the multiplicity-squared Gram limit. A local printed error with explicit repair, no whole-paper invalidity or author-competence characterization.", "evidence": "audits/adversarial_reviews/director_deroton_hardy_round6.md; originalPDFSHA2566b379ceeead2c10e614bd4be268c9672f0b364fa95799a5474a9479a82f9e445", "verified_author_error": true, "director_adjudication": "audits/adversarial_reviews/director_deroton_hardy_round6.md", "independent_reviews": ["audits/deroton2006_hardy_skeptic62.md", "audits/adversarial_reviews/witness62_deroton2006_prop64.md", "audits/prefix_formula62_deroton2006_full_reading.md"], "explicit_witness": "ActualF=zeta,j=k=1,w=1/4,epsilon=1/8:actualminusprintedleadingterm=(16/9)U_zeta(1/4)t^-1/4, U_zeta(1/4)=pi^(1/4)Gamma(1/8)/(3Gamma(3/8))>0. It is notO(t^-1/8). Independent exact Mellin contour proof supplied.", "status": "director_adjudicated_exact_printed_identity_counterexample_and_repair; main_theorem_preserved", "date": "2026-11-17", "track_file": "audits/deroton_hardy_director_round6_findings.jsonl"}','Printed Proposition6.4 leaves the Hardy multiplier outside a parameter derivative','Verified mathematical error','audits/deroton_hardy_director_round6_findings.jsonl',NULL,1);
INSERT INTO "findings" VALUES('FIND-DR2006-PHASE-DERIVATIVE','audits/findings.jsonl',2,'director_adjudicated_versioned_assertion_counterexample; complete_lower_proof_repair_preserves_main_result','audits/adversarial_reviews/director_deroton_phase_round6.md; originalPDFSHA2566b379ceeead2c10e614bd4be268c9672f0b364fa95799a5474a9479a82f9e445','{"id": "FIND-DR2006-PHASE-DERIVATIVE", "classification": "Verified mathematical error", "title": "Printed phase-derivative decay and L2 invocation fail for actual classical gamma phases", "sources": ["PAPER-DR2006:Proposition5.1_equation12_printedp432", "PAPER-DR2006:p433_application_of_Proposition4.1"], "scope": "The derivative assertion and its use, nottheconditionalProposition4.1orfinalTheorem2. Bothzetaandprimitivechi4explicitlyrefutethedecay; aweightedMellin/Bochnerrouteseparatelyrecoverstherequiredzerojetsandlowerconstant.", "evidence": "audits/adversarial_reviews/director_deroton_phase_round6.md; originalPDFSHA2566b379ceeead2c10e614bd4be268c9672f0b364fa95799a5474a9479a82f9e445", "verified_author_error": true, "director_adjudication": "audits/adversarial_reviews/director_deroton_phase_round6.md", "independent_reviews": ["audits/adversarial_reviews/witness62_deroton2006_prop51.md", "audits/adversarial_reviews/effective_cluster62_deroton_phase_repair.md", "audits/mellin_phase_derivative_domain_skeptic62.md"], "explicit_witness": "ForactualF=zeta,phi(x)=sin(2pi x)/(pi x),Phi=xphi''=2cos(2pi x)-phi, equal2atallpositiveintegersandnotL2. Foractualprimitivechi4,Phi=sin(pi x/2)-(1-cos(pi x/2))/(pi x/2). UniversalunitaryphaseindicatorweakderivativehasMellinmodulus1andcannotbeL2.", "status": "director_adjudicated_versioned_assertion_counterexample; complete_lower_proof_repair_preserves_main_result", "date": "2026-11-17", "track_file": "audits/deroton_phase_director_round6_findings.jsonl"}','Printed phase-derivative decay and L2 invocation fail for actual classical gamma phases','Verified mathematical error','audits/deroton_phase_director_round6_findings.jsonl',NULL,1);
INSERT INTO "findings" VALUES('FIND-DIRECTOR-GS-ENDPOINT','audits/findings.jsonl',3,NULL,'audits/adversarial_reviews/gallardo_seco_director_endpoint_round4.md','{"id": "FIND-DIRECTOR-GS-ENDPOINT", "classification": "Verified mathematical error", "title": "Inclusive endpoint of versioned auxiliary Proposition5.1 admits an explicit non-surjectivity counterexample", "paper_id": "PAPER-E012", "scope": "Only printed bounded-bijection endpoint alpha=-3,a=1 (and its equality family); no falsity of earlier main zero-free results or Theorem5.5 established.", "evidence": "audits/adversarial_reviews/gallardo_seco_director_endpoint_round4.md", "verified_author_error": true, "verified_statement_error_scope": "Version-specific printed auxiliary assertion, not author competence, whole paper or main RH result", "director_adjudication": "audits/adversarial_reviews/gallardo_seco_director_endpoint_round4.md", "independent_reviews": ["audits/adversarial_reviews/gallardo_seco_endpoint_skeptic_round4.md", "audits/adversarial_reviews/gallardo_seco_hardy_repair_equivalences_round3.md", "audits/adversarial_reviews/gallardo_seco_operator_impact_advocate_round4.md"], "explicit_witness": {"parameters": "alpha=-3,a=1", "polynomials": "f_K=sum_0^K z^n, domain squared norm H_(K+1), output squared norm<=3/2", "not_in_range": "g_n=(n+1)/log(n+2) in D_-3, every preimage coefficient grows like loglogn and is not D_-1"}, "correction_history_scope": "No correction listed/located in checked arXiv/Crossref/current publisherCrossmark through2026-11-17; prior-notice/novelty not assessed", "novelty_claim": false, "sources": "PAPER-E012", "track_file": "audits/director_endpoint_round4_findings.jsonl", "contributor_records": [{"id": "FIND-E-GS301", "classification": "Unresolved ambiguity requiring expert review", "title": "PrintedweightedDirichletoperatorinclusiveendpointunderexplicitcounterexamplereview", "paper_id": "PAPER-E012", "claim_id": "THM-E-GS301", "scope": "Prop5.1atalpha−3,a1only; generalendpointreviewalsoprovided; notblanketmainresultrefutation.", "status": "mathematicalwitnessandprimaryhypothesesindependentlychecked; directorclassificationpending", "evidence": "audits/gallardo_seco_endpoint_round3.md; audits/adversarial_reviews/gallardo_seco_endpoint_skeptic_round4.md", "verified_author_error": false, "date": "2026-11-17", "sources": "PAPER-E012", "track_file": "audits/weighted_dirichlet_findings_round3.jsonl"}], "alias_ids": ["FIND-E-GS301"], "alias_evidence": ["audits/adversarial_reviews/gallardo_seco_director_endpoint_round4.md"]}','Inclusive endpoint of versioned auxiliary Proposition5.1 admits an explicit non-surjectivity counterexample','Verified mathematical error','audits/director_endpoint_round4_findings.jsonl',NULL,1);
INSERT INTO "findings" VALUES('FIND-SELBERG-CENTRAL-DRIFT','audits/findings.jsonl',4,'adjudicated_exact_versioned_auxiliary_definition_error','audits/adversarial_reviews/director_central_drift_round10.md','{"id": "FIND-SELBERG-CENTRAL-DRIFT", "classification": "Verified mathematical error", "title": "Unregularized drift at an explicitly allowed central zero", "sources": ["PAPER-POS64-OPPROB-016", "OBS-CENTRAL-DRIFT-REGULARIZATION"], "scope": "Only arxiv2307.02027v1 eq2.7 and repeated ordinary substitution after retained z^m0 factor. Regular-part replacement restores the intended criterion and Gaussian variance; no journal version verified.", "evidence": "audits/adversarial_reviews/director_central_drift_round10.md", "verified_author_error": true, "status": "adjudicated_exact_versioned_auxiliary_definition_error", "director_adjudication": "audits/adversarial_reviews/director_central_drift_round10.md", "independent_reviews": ["audits/adversarial_reviews/geometry64_central_zero_scope.md", "audits/adversarial_reviews/release64_central_extension_versions.md", "papers/positivity64_operator_probability_notes.md"], "explicit_witness": "F(s)=L(s+17/2,DeltaE6), Selbergdegree2 with central order1 by the split positive Mellin integral; xiFprime/xiF has residue1 at .5, so the printed ordinary value does not exist.", "date": "2026-11-18", "track_file": "audits/director_round10_findings.jsonl"}','Unregularized drift at an explicitly allowed central zero','Verified mathematical error','audits/director_round10_findings.jsonl',NULL,1);
