INSERT INTO "findings" VALUES('FIND-LAGARIAS-PREPRINT-AUXILIARY','audits/findings.jsonl',6,'adjudicated_exact_versioned_auxiliary_assertions','audits/adversarial_reviews/director_lagarias_whole_round10.md','{"id": "FIND-LAGARIAS-PREPRINT-AUXILIARY", "classification": "Verified mathematical error", "title": "Two false auxiliary maximal-order displays in accessible Lagarias manuscripts", "sources": ["PAPER-R001"], "scope": "Mayarxivv2 andJuly29author manuscript p3 ordinary Mertens exponent and literal0.6482 strict Robin coefficient; neither enters main criterion. No publisher mathematical text verified.", "evidence": "audits/adversarial_reviews/director_lagarias_whole_round10.md", "director_adjudication": "audits/adversarial_reviews/director_lagarias_whole_round10.md", "verified_author_error": true, "status": "adjudicated_exact_versioned_auxiliary_assertions", "independent_reviews": ["audits/adversarial_reviews/geometry64_lagarias_whole_advocate.md", "audits/adversarial_reviews/release64_lagarias_whole_skeptic.md"], "explicit_witness": "Atn12 exact equality-forced coefficient is in(.64821364942179,.64821364942181), above.6482; ordinary Mertens coefficient isexp(−gamma), notexp(+gamma).", "date": "2026-11-18", "track_file": "audits/director_round10b_findings.jsonl"}','Two false auxiliary maximal-order displays in accessible Lagarias manuscripts','Verified mathematical error','audits/director_round10b_findings.jsonl',NULL,1);
