INSERT INTO "findings" VALUES('FIND-SUZUKI-COMPENSATED-DRIFT-SIGN','audits/findings.jsonl',8,'adjudicated_exact_versioned_auxiliary_representation_error','audits/adversarial_reviews/director_suzuki_drift_round11.md','{"id": "FIND-SUZUKI-COMPENSATED-DRIFT-SIGN", "classification": "Verified mathematical error", "title": "Opposite compensated drift in pinned extended Selberg screw representation", "sources": ["PAPER-POS64-OPPROB-018", "OBS-SUZUKI-COMPENSATED-DRIFT-SIGN"], "scope": "Limited to the printed coefficient of +iCt outside the integral in arXiv:2209.12832v2, page 6, §5.1. The kernel, real-part criterion, and infinite divisibility survive translation. Journal wording is unverified.", "evidence": "audits/adversarial_reviews/director_suzuki_drift_round11.md", "director_adjudication": "audits/adversarial_reviews/director_suzuki_drift_round11.md", "verified_author_error": true, "status": "adjudicated_exact_versioned_auxiliary_representation_error", "independent_reviews": ["audits/adversarial_reviews/uniform66_suzuki_compensated_drift.md", "audits/adversarial_reviews/geometry66_suzuki_compensated_drift.md"], "explicit_witness": "F = 1 + 2i·4^(−s) satisfies S♯, with GRH following by absolute values. Here B = −log 2 and A = 9 log 2/17. The printed C is −8 log 2/17 and the required C is +8 log 2/17.", "date": "2026-11-18", "track_file": "audits/director_round11_findings.jsonl"}','Opposite compensated drift in pinned extended Selberg screw representation','Verified mathematical error','audits/director_round11_findings.jsonl',NULL,1);
INSERT INTO "findings" VALUES('FIND-DENINGER-ISOLATED-FIELD-SCOPE','audits/findings.jsonl',9,'adjudicated_scope_qualification','audits/adversarial_reviews/director_deninger_whole_round11.md','{"id": "FIND-DENINGER-ISOLATED-FIELD-SCOPE", "classification": "Correct argument, but commonly misinterpreted", "title": "Real-descent obstruction needs an obstructed Artin sector or a universal family", "sources": ["PAPER-GEO65-001", "THM-DENINGER-REAL-DESCENT-OBSTRUCTION"], "scope": "Theorem 2.13 is read in its global functorial context. Its obstruction does not extend to a blanket claim about an isolated operator over ℚ. The positive pairing remains conjectural.", "evidence": "audits/adversarial_reviews/director_deninger_whole_round11.md", "director_adjudication": "audits/adversarial_reviews/director_deninger_whole_round11.md", "verified_author_error": false, "status": "adjudicated_scope_qualification", "independent_reviews": ["audits/adversarial_reviews/geometry68_deninger_whole_advocate.md", "audits/adversarial_reviews/analytic68_deninger_whole_skeptic.md"], "date": "2026-11-18", "track_file": "audits/director_round11_findings.jsonl"}','Real-descent obstruction needs an obstructed Artin sector or a universal family','Correct argument, but commonly misinterpreted','audits/director_round11_findings.jsonl',NULL,0);
INSERT INTO "findings" VALUES('FIND-LI97-LOCAL-DEDEKIND-NORMALIZATION','audits/findings.jsonl',10,'adjudicated_versioned_local_assertions_with_repairs','audits/adversarial_reviews/director_li_whole_round12.md','{"id": "FIND-LI97-LOCAL-DEDEKIND-NORMALIZATION", "classification": "Verified mathematical error", "title": "Local nonvanishing-symbol and complex-place normalization slips in the pinned Li manifestation", "sources": ["PAPER-E008", "OBS-LI97-DEDEKIND-NORMALIZATION"], "scope": "Only the p. 329 assertion that zeta_k is nonvanishing at zero and the positive multiplier in (3.4), inherited in (3.7). The normalized Xi_k is nonvanishing at zero and the corrected positive multiplier preserves Lemma 3.2 and both main criteria. Publisher-byte identity is unverified.", "evidence": "audits/adversarial_reviews/director_li_whole_round12.md", "director_adjudication": "audits/adversarial_reviews/director_li_whole_round12.md", "independent_reviews": ["audits/adversarial_reviews/uniform74_li_whole_advocate.md", "audits/adversarial_reviews/prime74_li_whole_skeptic.md"], "explicit_witness": "For Q(sqrt5), zeta_k has a simple zero at zero. For Q(i), Jacobi inversion gives Xi_k(s)=1+4s(s−1)K(s), K(2)>0, whereas the printed (3.4) coefficient is 2/π. Both are exact symbolic witnesses.", "verified_author_error": true, "status": "adjudicated_versioned_local_assertions_with_repairs", "date": "2026-11-18", "track_file": "audits/director_round12_findings.jsonl"}','Local nonvanishing-symbol and complex-place normalization slips in the pinned Li manifestation','Verified mathematical error','audits/director_round12_findings.jsonl',NULL,1);
