INSERT INTO "findings" VALUES('FIND-F011','audits/findings.jsonl',35,'Locally Lean-checked module and printed types/axiom dependencies; not external independent-kernel replay.','experiments/results/formal_ranktrace_summary.json','{"finding_id": "FIND-F011", "paper_id": "PAPER-A004", "category": "Independently checked with no issue found in the inspected portion", "scope": "Actual local pinned Lean source build of rank-trace algebra module only", "result": "2770-job source build succeeded; actual theorem/type and axiom query exited0. rank_trace_ineq and rank_trace_ineq_two depend only on propext,Classical.choice,Quot.sound.", "verification_status": "Locally Lean-checked module and printed types/axiom dependencies; not external independent-kernel replay.", "limit": "No main zeta proportion theorem build success inferred.", "provenance": "experiments/results/formal_ranktrace_summary.json", "id": "FIND-F011", "classification": "Independently checked with no issue found in the inspected portion", "title": "Actual local pinned Lean source build of rank-trace algebra module only", "sources": "PAPER-A004", "evidence": "experiments/results/formal_ranktrace_summary.json", "verified_author_error": false, "track_file": "audits/formal_round2_findings.jsonl"}','Actual local pinned Lean source build of rank-trace algebra module only','Independently checked with no issue found in the inspected portion','audits/formal_round2_findings.jsonl',NULL,0);
INSERT INTO "findings" VALUES('FIND-F012','audits/findings.jsonl',36,'Independent proposer, skeptic and director checks accepted.','THM-F010;audits/adversarial_reviews/AF_no_buffer_operator_countermodel.md','{"finding_id": "FIND-F012", "paper_id": "PAPER-A004", "category": "Independently checked with no issue found in the inspected portion", "scope": "New explicit negative control for an altered abstract inference, not a source-theorem error", "result": "Strip/symmetry/local-count/RvM assumptions, even with eventual VK strip, do not imply unbuffered operator erroro(1). A single fixed sparse-quartet multiset yields divergent operator norm with vanishing relativeHS error.", "verification_status": "Independent proposer, skeptic and director checks accepted.", "limit": "Does not satisfy or claim the full zeta explicit formula/prime-side moment; no actual zeta zero assertion.", "provenance": "THM-F010;audits/adversarial_reviews/AF_no_buffer_operator_countermodel.md", "id": "FIND-F012", "classification": "Independently checked with no issue found in the inspected portion", "title": "New explicit negative control for an altered abstract inference, not a source-theorem error", "sources": "PAPER-A004", "evidence": "THM-F010;audits/adversarial_reviews/AF_no_buffer_operator_countermodel.md", "verified_author_error": false, "track_file": "audits/formal_round2_findings.jsonl"}','New explicit negative control for an altered abstract inference, not a source-theorem error','Independently checked with no issue found in the inspected portion','audits/formal_round2_findings.jsonl',NULL,0);
INSERT INTO "findings" VALUES('FIND-F013','audits/findings.jsonl',37,'Director accepted scoped qualification after independent mathematical checks; exact witnesses and preserved special case recorded.','THM-F011;THM-F012;audits/adversarial_reviews/christoffel_scope_proposer_round3.md','{"finding_id": "FIND-F013", "paper_id": "PAPER-A004", "category": "Missing or insufficiently stated hypothesis", "scope": "Ordinary-Christoffel interpretation of an explicitly informal general observation§7.2(d),not mainA/B", "result": "A one-sided majorant qualification is required before ordinary Christoffel minimization bounds negative-halfline spectral mass. Exact66-point and independent8-point witnesses refute the unrestricted reading. The particular sine-moment polynomial is a valid majorant and retains the conditional13/18 consequence.", "verification_status": "Director accepted scoped qualification after independent mathematical checks; exact witnesses and preserved special case recorded.", "limit": "No complete zeta sampling/block/prime countermodel and no main theorem falsehood alleged.", "provenance": "THM-F011;THM-F012;audits/adversarial_reviews/christoffel_scope_proposer_round3.md", "id": "FIND-F013", "classification": "Missing or insufficiently stated hypothesis", "title": "Ordinary-Christoffel interpretation of an explicitly informal general observation§7.2(d),not mainA/B", "sources": "PAPER-A004", "evidence": "THM-F011;THM-F012;audits/adversarial_reviews/christoffel_scope_proposer_round3.md", "verified_author_error": false, "track_file": "audits/formal_round2_findings.jsonl"}','Ordinary-Christoffel interpretation of an explicitly informal general observation§7.2(d),not mainA/B','Missing or insufficiently stated hypothesis','audits/formal_round2_findings.jsonl',NULL,0);
