INSERT INTO "findings" VALUES('FINDING-G001','audits/findings.jsonl',40,'Explicit all-degree proof and independent parent check; no error in the cited source theorems alleged.','THM-G010,THM-G011; frontiers/geometry_round2.md §§3,6','{"finding_id": "FINDING-G001", "classification": "Correct argument, but commonly misinterpreted", "paper_ids": ["PAPER-G002", "PAPER-G003"], "locators": ["I(3.2),pp283–285", "II(3.3.6),p206", "II(3.3.9),p207"], "statement": "Alternating duality/positive Euler coefficients do not suffice for purity, and purity of im(Hc→H) on an open smooth variety does not imply purity of either whole group. Explicit negative controls are provided.", "evidence": "THM-G010,THM-G011; frontiers/geometry_round2.md §§3,6", "verification": "Explicit all-degree proof and independent parent check; no error in the cited source theorems alleged.", "id": "FINDING-G001", "title": "Alternating duality/positive Euler coefficients do not suffice for purity, and purity of im(Hc→H) on an open smooth variety does not imply purity of either whole group. Explicit negative controls are provided.", "sources": ["PAPER-G002", "PAPER-G003"], "scope": "Alternating duality/positive Euler coefficients do not suffice for purity, and purity of im(Hc→H) on an open smooth variety does not imply purity of either whole group. Explicit negative controls are provided.", "verified_author_error": false, "track_file": "audits/geometry_round2_findings.jsonl"}','Alternating duality/positive Euler coefficients do not suffice for purity, and purity of im(Hc→H) on an open smooth variety does not imply purity of either whole group. Explicit negative controls are provided.','Correct argument, but commonly misinterpreted','audits/geometry_round2_findings.jsonl',NULL,0);
INSERT INTO "findings" VALUES('FINDING-G002','audits/findings.jsonl',41,'Independent finite-sum reconstruction. Not a whole-paper L2 audit.','THM-G001; frontiers/geometry_round2.md §7','{"finding_id": "FINDING-G002", "classification": "Independently checked with no issue found in the inspected portion", "paper_ids": ["PAPER-G001"], "locators": ["Equation4,pp500–501"], "statement": "The Gauss-sum norm argument works with both character nontriviality assumptions retained; all sums are finite.", "evidence": "THM-G001; frontiers/geometry_round2.md §7", "verification": "Independent finite-sum reconstruction. Not a whole-paper L2 audit.", "id": "FINDING-G002", "title": "The Gauss-sum norm argument works with both character nontriviality assumptions retained; all sums are finite.", "sources": ["PAPER-G001"], "scope": "The Gauss-sum norm argument works with both character nontriviality assumptions retained; all sums are finite.", "verified_author_error": false, "track_file": "audits/geometry_round2_findings.jsonl"}','The Gauss-sum norm argument works with both character nontriviality assumptions retained; all sums are finite.','Independently checked with no issue found in the inspected portion','audits/geometry_round2_findings.jsonl',NULL,0);
INSERT INTO "findings" VALUES('FIND-R13-HR-AVERAGING-WEIGHT-LOG-MOMENT','audits/findings.jsonl',42,'adjudicated_exact_journal_counterexample_and_repair','audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md','{"id": "FIND-R13-HR-AVERAGING-WEIGHT-LOG-MOMENT", "title": "The printed Hughes–Rudnick averaging class allows an infinite first moment", "classification": "Missing or insufficiently stated hypothesis", "status": "adjudicated_exact_journal_counterexample_and_repair", "sources": ["PAPER-AN79-HR-ZETA"], "claim_id": "THM-HR-REPAIRED-FINITE-GAUSSIAN-MOMENTS", "evidence": "audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md", "director_adjudication": "audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md", "independent_reviews": ["audits/adversarial_reviews/analytic89_hr_whole_advocate.md", "audits/adversarial_reviews/weighted88_hr_whole_skeptic.md"], "verified_author_error": true, "version": "2002 journal typeset version, C. R. Math. 335(8), 667–670", "source_sha256": "b4572e5bdbf3cf7e891a4128aeb3bb56d151f2b16d23f9e63a94b1a2d2c09139", "source_locator": "Journal Theorem 1.1 and printed weight definition; explicit formula (2)–(4), pp. 668–669.", "explicit_witness": "Let b=q²/∫q² for a nonzero real even Schwartz q with smooth compact Fourier support, and choose w(u)=∑_{j≥1}2^−j b(u−exp(4^j)). It is smooth, nonnegative, of mass one and bandlimited, but ∫w log(2+|u|)=∞. For a real even bandlimited Schwartz-square test with I=∫f>0 and sufficiently small support, N_f(tau)=(I/log T)log(1+|tau|)+O_{f,T}(1). Consequently its printed weighted first moment is +∞ for every fixed T>1,H>0.", "scope": "Literal full-statistic moment statement in the pinned journal only. The repaired finite window holds when I=0 or w has finite mth logarithmic moment. The oscillatory prime theorem remains valid on the full printed class. No variance error or broader claim is recorded.", "track_file": "audits/research_round13_findings.jsonl"}','The printed Hughes–Rudnick averaging class allows an infinite first moment','Missing or insufficiently stated hypothesis','audits/research_round13_findings.jsonl','THM-HR-REPAIRED-FINITE-GAUSSIAN-MOMENTS',1);
INSERT INTO "findings" VALUES('FIND-R15-BL-RAW-HEIGHT-TEST-CLASS','audits/findings.jsonl',43,'adjudicated_exact_manuscript_counterexample_and_repair','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md','{"id": "FIND-R15-BL-RAW-HEIGHT-TEST-CLASS", "title": "The manuscript''s literal auxiliary test class allows a divergent raw-height sum", "classification": "Verified mathematical error", "status": "adjudicated_exact_manuscript_counterexample_and_repair", "sources": ["PAPER-L002"], "related_claim_ids": ["OBS-BL-RAW-HEIGHT-SMOOTH-COUNTEREXAMPLE"], "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md", "director_adjudication": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md", "independent_reviews": ["audits/adversarial_reviews/geometry130_explicit_formula_countermodel.md", "audits/adversarial_reviews/weighted130_explicit_formula_countermodel_review.md", "audits/adversarial_reviews/analytic131_explicit_formula_countermodel_adjudication.md", "audits/adversarial_reviews/analytic138_director_mellin_final_qa.md"], "verified_author_error": true, "version": "Michigan author-hosted 12-page manuscript, version date unverified", "source_path": "sources/uniform121_bombieri_lagarias/bombieri_lagarias_author.pdf", "source_sha256": "cd13c8560f961c68e21256e5ba107bdd08fa7f34ce1e2cffbd4b63a16e8d48e0", "source_locator": "Pinned 12-page author manuscript, pp. 5–6, auxiliary explicit formula and test-function conditions.", "explicit_witness": "A fixed smooth disjoint log-bump function obeys the literal value and local hypotheses. Populated symmetric high zero cells and separated carriers force increments greater than 2j/5 under raw-height summation while the arithmetic side converges absolutely.", "scope": "Pinned author-hosted manuscript only. The auxiliary formula needs stronger hypotheses for the stated summation mode. The generalized multiset criterion and the compact main application retain separate proofs. No journal-version finding.", "track_file": "audits/research_round15_bombieri_lagarias_findings.jsonl"}','The manuscript''s literal auxiliary test class allows a divergent raw-height sum','Verified mathematical error','audits/research_round15_bombieri_lagarias_findings.jsonl',NULL,1);
INSERT INTO "findings" VALUES('FIND-R15-BL-FINITE-CUTOFF-COMPENSATOR','audits/findings.jsonl',44,'adjudicated_exact_manuscript_counterexample_and_repair','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md','{"id": "FIND-R15-BL-FINITE-CUTOFF-COMPENSATOR", "title": "The printed finite-cutoff equality loses its upper-tail compensator", "classification": "Verified mathematical error", "status": "adjudicated_exact_manuscript_counterexample_and_repair", "sources": ["PAPER-L002"], "related_claim_ids": ["LEM-BL-FINITE-CUTOFF-COMPENSATOR"], "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md", "director_adjudication": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md", "independent_reviews": ["audits/adversarial_reviews/uniform121_bombieri_lagarias_whole_advocate.md", "audits/adversarial_reviews/weighted121_bombieri_lagarias_whole_skeptic.md", "audits/adversarial_reviews/geometry127_bombieri_lagarias_adjudication_input.md", "audits/adversarial_reviews/analytic138_director_mellin_final_qa.md"], "verified_author_error": true, "version": "Michigan author-hosted 12-page manuscript, version date unverified", "source_path": "sources/uniform121_bombieri_lagarias/bombieri_lagarias_author.pdf", "source_sha256": "cd13c8560f961c68e21256e5ba107bdd08fa7f34ce1e2cffbd4b63a16e8d48e0", "source_locator": "Pinned 12-page author manuscript, p. 8, equation (3.5).", "explicit_witness": "At n=1 and ε=2/3 the gamma compensator contributes an omitted positive (1/2)log(9/5). The cutoff 3/2 is distinct from every prime power.", "scope": "Pinned author-hosted manuscript only. The omitted term is O_n(ε²) and vanishes in the limiting theorem. No journal-version finding.", "track_file": "audits/research_round15_bombieri_lagarias_findings.jsonl"}','The printed finite-cutoff equality loses its upper-tail compensator','Verified mathematical error','audits/research_round15_bombieri_lagarias_findings.jsonl',NULL,1);
INSERT INTO "findings" VALUES('FIND-R15-GONEK-P123-CONTINUOUS-DERIVATIVE-SIGN','audits/findings.jsonl',45,'adjudicated_exact_journal_counterexample_and_repair','audits/adversarial_reviews/director_gonek_whole_round15.md','{"id": "FIND-R15-GONEK-P123-CONTINUOUS-DERIVATIVE-SIGN", "title": "Continuous derivative-product comparison has the wrong sign at odd total order", "classification": "Verified mathematical error", "status": "adjudicated_exact_journal_counterexample_and_repair", "sources": ["PAPER-LF63-GONEK1984"], "evidence": "audits/adversarial_reviews/director_gonek_whole_round15.md", "director_adjudication": "audits/adversarial_reviews/director_gonek_whole_round15.md", "independent_reviews": ["audits/adversarial_reviews/geometry88_gonek_whole_advocate.md", "audits/adversarial_reviews/prime88_gonek_whole_skeptic.md", "audits/adversarial_reviews/weighted89_gonek_local_adjudication_input.md"], "verified_author_error": true, "version": "1984 journal typeset scan, Inventiones Mathematicae 75(1), 123–141", "source_sha256": "dfdd2444a2f62f1947c897e87101080225714dbf1f21db8ca19096d2a6e80fc3", "source_locator": "Pinned journal p. 123, introductory equation (2) and the derivative convention immediately below.", "explicit_witness": "With mu=1, nu=0, differentiating the functional equation on the line gives 2 Re[zeta′(s)zeta(1−s)]=(chi′/chi)(s)|zeta(s)|². The logarithmic derivative is −log(t/(2pi))+O(1/t); the ordinary second moment and partial summation give a negative leading term −T log²T/2, while (2) prints a positive term.", "scope": "Contextual display in this journal edition. Insert (−1)^(mu+nu). The discrete source theorem (4) already has the sign. No finding is attributed to Ingham’s primary work.", "track_file": "audits/research_round15_gonek_findings.jsonl"}','Continuous derivative-product comparison has the wrong sign at odd total order','Verified mathematical error','audits/research_round15_gonek_findings.jsonl',NULL,1);
INSERT INTO "findings" VALUES('FIND-R15-GONEK-P129-INNER-PHASE','audits/findings.jsonl',46,'adjudicated_exact_journal_counterexample_and_repair','audits/adversarial_reviews/director_gonek_whole_round15.md','{"id": "FIND-R15-GONEK-P129-INNER-PHASE", "title": "Printed auxiliary saddle phase fails its stated double-zero identity", "classification": "Verified mathematical error", "status": "adjudicated_exact_journal_counterexample_and_repair", "sources": ["PAPER-LF63-GONEK1984"], "evidence": "audits/adversarial_reviews/director_gonek_whole_round15.md", "director_adjudication": "audits/adversarial_reviews/director_gonek_whole_round15.md", "independent_reviews": ["audits/adversarial_reviews/geometry88_gonek_whole_advocate.md", "audits/adversarial_reviews/prime88_gonek_whole_skeptic.md", "audits/adversarial_reviews/weighted89_gonek_local_adjudication_input.md"], "verified_author_error": true, "version": "1984 journal typeset scan, Inventiones Mathematicae 75(1), 123–141", "source_sha256": "dfdd2444a2f62f1947c897e87101080225714dbf1f21db8ca19096d2a6e80fc3", "source_locator": "Pinned journal p. 129, proof of Lemma 1, immediately after extracting exp(−ir).", "explicit_witness": "Direct substitution into f(x)=(1+x)log(1+x)−(1+x) gives f(0)=−1. The expansion with the extracted constant requires F=f+1, for which F(0)=F′(0)=0 and F′′(0)=1.", "scope": "Auxiliary phase definition in the proof. The corrected signed square root gives the stated stationary-phase lemma and leaves (4) and its corollaries intact.", "track_file": "audits/research_round15_gonek_findings.jsonl"}','Printed auxiliary saddle phase fails its stated double-zero identity','Verified mathematical error','audits/research_round15_gonek_findings.jsonl',NULL,1);
INSERT INTO "findings" VALUES('FIND-R15-GONEK-P140-RECIPROCAL-GAP-SCALE','audits/findings.jsonl',47,'adjudicated_exact_journal_counterexample_and_repair','audits/adversarial_reviews/director_gonek_whole_round15.md','{"id": "FIND-R15-GONEK-P140-RECIPROCAL-GAP-SCALE", "title": "Gap proof displays the reciprocal of the defined normalization", "classification": "Verified mathematical error", "status": "adjudicated_exact_journal_counterexample_and_repair", "sources": ["PAPER-LF63-GONEK1984"], "evidence": "audits/adversarial_reviews/director_gonek_whole_round15.md", "director_adjudication": "audits/adversarial_reviews/director_gonek_whole_round15.md", "independent_reviews": ["audits/adversarial_reviews/geometry88_gonek_whole_advocate.md", "audits/adversarial_reviews/prime88_gonek_whole_skeptic.md", "audits/adversarial_reviews/weighted89_gonek_local_adjudication_input.md"], "verified_author_error": true, "version": "1984 journal typeset scan, Inventiones Mathematicae 75(1), 123–141", "source_sha256": "dfdd2444a2f62f1947c897e87101080225714dbf1f21db8ca19096d2a6e80fc3", "source_locator": "Pinned journal p. 125, definition of lambda; p. 140 §6 opening display.", "explicit_witness": "The proof prints a factor 2pi/log gamma_n, whose gap limsup is zero by bounded gaps from the zero count. The defined factor log gamma_n/(2pi) has limsup at least one by mean density. The displayed quantities cannot agree.", "scope": "Restore the p. 125 factor for the gap proof. The separate bulk-interval covering repair justifies Corollary 3 and carries no verified-author-error flag. The p. 125 statement and the derivative prefix survive.", "track_file": "audits/research_round15_gonek_findings.jsonl"}','Gap proof displays the reciprocal of the defined normalization','Verified mathematical error','audits/research_round15_gonek_findings.jsonl',NULL,1);
INSERT INTO "findings" VALUES('FIND-R15-MORSE-SHIFTED-FAMILY-SELF-REFLECTION','audits/findings.jsonl',48,'adjudicated_exact_versioned_local_counterexample_and_repair','audits/adversarial_reviews/director_morse_scoped_round15.md','{"id": "FIND-R15-MORSE-SHIFTED-FAMILY-SELF-REFLECTION", "title": "The displayed shifted family is self-reflected", "classification": "Verified mathematical error", "status": "adjudicated_exact_versioned_local_counterexample_and_repair", "sources": ["PAPER-LAG2009-MORSE"], "related_claim_ids": ["OBS-MORSE-PRINTED-SHIFTED-FAMILY-SELF-REFLECTION"], "evidence": "audits/adversarial_reviews/director_morse_scoped_round15.md", "director_adjudication": "audits/adversarial_reviews/director_morse_scoped_round15.md", "independent_reviews": ["audits/adversarial_reviews/geometry120_lagarias_morse_whole_advocate.md", "audits/adversarial_reviews/analytic120_lagarias_morse_whole_skeptic.md", "audits/adversarial_reviews/weighted128_morse_conventions_adjudication.md", "audits/adversarial_reviews/geometry138_morse_local_findings.md"], "verified_author_error": true, "version": "arXiv:0712.3238v6, 2009-08-18", "source_sha256": "307d253d70abc7d8ef3d24355e9ab7708010bda18c7b9060a4913033c6e224be", "source_manifestations": [{"version": "arXiv:0712.3238v6, 2009-08-18", "source_path": "sources/prefix_skeptic62_spectral/lagarias_morse.pdf", "source_sha256": "307d253d70abc7d8ef3d24355e9ab7708010bda18c7b9060a4913033c6e224be", "source_locator": "ArXiv v6 p. 20, display before (5.5) and its attached assertion, with (5.1) on p. 19."}, {"version": "2009 journal, CNTP 3(2), 323–361, DOI 10.4310/CNTP.2009.v3.n2.a3", "source_path": "sources/geometry120_morse_references/lagarias_morse_journal.pdf", "source_sha256": "268dff410dae549b457c45375007922e91cc8b9b7e23530814044d42bb54b280", "source_locator": "Journal printed pp. 344 and 346, PDF pp. 22 and 24."}], "source_locator": "ArXiv v6 p. 20, display before (5.5) and its attached assertion, with (5.1) on p. 19. Journal printed pp. 344 and 346, PDF pp. 22 and 24.", "explicit_witness": "Reflection exchanges P and Q and conjugates −i, so the displayed E_h#=E_h and the strict Hermite–Biehler inequality fails at h=1/2,z=i.", "scope": "The nonzero-shift display and its attached claim. The separately defined zero-shift criterion and cited single-shift result retain their own arguments.", "track_file": "audits/research_round15_morse_findings.jsonl"}','The displayed shifted family is self-reflected','Verified mathematical error','audits/research_round15_morse_findings.jsonl',NULL,1);
INSERT INTO "findings" VALUES('FIND-R15-MORSE-EXPLICIT-HERGLOTZ-QUOTIENT-SIGN','audits/findings.jsonl',49,'adjudicated_exact_versioned_local_counterexample_and_repair','audits/adversarial_reviews/director_morse_scoped_round15.md','{"id": "FIND-R15-MORSE-EXPLICIT-HERGLOTZ-QUOTIENT-SIGN", "title": "The explicit Herglotz quotient has negative imaginary part", "classification": "Verified mathematical error", "status": "adjudicated_exact_versioned_local_counterexample_and_repair", "sources": ["PAPER-LAG2009-MORSE"], "related_claim_ids": ["OBS-MORSE-PRINTED-HERGLOTZ-QUOTIENT-SIGN"], "evidence": "audits/adversarial_reviews/director_morse_scoped_round15.md", "director_adjudication": "audits/adversarial_reviews/director_morse_scoped_round15.md", "independent_reviews": ["audits/adversarial_reviews/geometry120_lagarias_morse_whole_advocate.md", "audits/adversarial_reviews/analytic120_lagarias_morse_whole_skeptic.md", "audits/adversarial_reviews/weighted128_morse_conventions_adjudication.md", "audits/adversarial_reviews/geometry138_morse_local_findings.md"], "verified_author_error": true, "version": "arXiv:0712.3238v6, 2009-08-18", "source_sha256": "307d253d70abc7d8ef3d24355e9ab7708010bda18c7b9060a4913033c6e224be", "source_manifestations": [{"version": "arXiv:0712.3238v6, 2009-08-18", "source_path": "sources/prefix_skeptic62_spectral/lagarias_morse.pdf", "source_sha256": "307d253d70abc7d8ef3d24355e9ab7708010bda18c7b9060a4913033c6e224be", "source_locator": "ArXiv v6 p. 23, (6.1)–(6.2), with decomposition on p. 19."}, {"version": "2009 journal, CNTP 3(2), 323–361, DOI 10.4310/CNTP.2009.v3.n2.a3", "source_path": "sources/geometry120_morse_references/lagarias_morse_journal.pdf", "source_sha256": "268dff410dae549b457c45375007922e91cc8b9b7e23530814044d42bb54b280", "source_locator": "Journal printed pp. 344 and 349, PDF pp. 22 and 27."}], "source_locator": "ArXiv v6 p. 23, (6.1)–(6.2), with decomposition on p. 19. Journal printed pp. 344 and 349, PDF pp. 22 and 27.", "explicit_witness": "Whittaker evenness and the integral for U give U(1,3,x)=x⁻¹+x⁻² and U(2,3,x)=x⁻². At u=0,z=i the printed equation evaluates to −i/(2e).", "scope": "The auxiliary z-plane quotient and its stated Herglotz convention. The fixed-boundary spectral theorems and Appendix B energy-plane Weyl quotient retain their separate arguments.", "track_file": "audits/research_round15_morse_findings.jsonl"}','The explicit Herglotz quotient has negative imaginary part','Verified mathematical error','audits/research_round15_morse_findings.jsonl',NULL,1);
