INSERT INTO "findings" VALUES('FIND-R207','audits/findings.jsonl',56,'adjudicated_journal_and_preprint_scope','audits/baez_duarte_deep_round2.md','{"id": "FIND-R207", "classification": "Correct argument, but commonly misinterpreted", "title": "Báez-Duarte displayed epsilon majorant admits a stronger valid repair", "sources": ["PAPER-E014"], "evidence": "audits/baez_duarte_deep_round2.md", "scope": "The February, May and journal manifestations are one work with version-specific gamma and normalization text. The free-exponent majorant repair, ordered norm limits, RH-dependent function identification and separately reconstructed shrinking-gap input preserve the criterion and rate. Whole journal audit and exact edition map now complete.", "verified_author_error": false, "track_file": "audits/research_round2_findings.jsonl", "status_update_history": [{"fields": {"status": "adjudicated_journal_and_preprint_scope", "sources": ["PAPER-E014"], "director_adjudication": "audits/adversarial_reviews/director_baez_whole_round13.md", "independent_reviews": ["audits/adversarial_reviews/analytic74_baez_whole_advocate.md", "audits/adversarial_reviews/weighted74_baez_whole_skeptic.md"], "verified_author_error": false, "scope": "The February, May and journal manifestations are one work with version-specific gamma and normalization text. The free-exponent majorant repair, ordered norm limits, RH-dependent function identification and separately reconstructed shrinking-gap input preserve the criterion and rate. Whole journal audit and exact edition map now complete."}, "evidence": "audits/adversarial_reviews/director_baez_whole_round13.md"}], "status": "adjudicated_journal_and_preprint_scope", "director_adjudication": "audits/adversarial_reviews/director_baez_whole_round13.md", "independent_reviews": ["audits/adversarial_reviews/analytic74_baez_whole_advocate.md", "audits/adversarial_reviews/weighted74_baez_whole_skeptic.md"], "status_update_evidence": "audits/adversarial_reviews/director_baez_whole_round13.md"}','Báez-Duarte displayed epsilon majorant admits a stronger valid repair','Correct argument, but commonly misinterpreted','audits/research_round2_findings.jsonl',NULL,0);
INSERT INTO "findings" VALUES('FIND-RST048-LOCALIZATION','audits/findings.jsonl',57,'adjudicated_local_qualification_and_repair; no main theorem counterexample','audits/adversarial_reviews/director_rstation48_main_theorem_round6.md §7; threshold62_rstation48_main_theorem_skeptic.md; latest62_rst048_independent.md','{"id": "FIND-RST048-LOCALIZATION", "classification": "Missing or insufficiently stated hypothesis", "title": "Full-cluster hull estimate requires a fixed-singleton qualification in §7.2", "sources": ["PAPER-RST048:v2§7.2", "LEM-RST048-LOCAL-REPAIR"], "scope": "The appeal to equation26 outside individual zero neighborhoods does not directly meet the full-hull distance hypothesis. Expanding a fixed finite set into individual Laurent terms repairs the step with constants independent ofN. This does not invalidate the independently reconstructed main theorem.", "evidence": "audits/adversarial_reviews/director_rstation48_main_theorem_round6.md §7; threshold62_rstation48_main_theorem_skeptic.md; latest62_rst048_independent.md", "status": "adjudicated_local_qualification_and_repair; no main theorem counterexample", "verified_author_error": false, "director_adjudication": "audits/adversarial_reviews/director_rstation48_main_theorem_round6.md", "independent_reviews": ["audits/adversarial_reviews/threshold62_rstation48_main_theorem_skeptic.md", "audits/adversarial_reviews/latest62_rst048_independent.md", "audits/adversarial_reviews/rstation48_quadrature_norm_rt62_rstation48.md"], "date": "2026-11-17", "track_file": "audits/rstation48_director_round6_findings.jsonl"}','Full-cluster hull estimate requires a fixed-singleton qualification in §7.2','Missing or insufficiently stated hypothesis','audits/rstation48_director_round6_findings.jsonl',NULL,0);
INSERT INTO "findings" VALUES('FIND-SUZUKI-KNOWN-SIGNED-CORRECTION','audits/findings.jsonl',58,'known_author_erratum_reconstructed; no_new_error_priority','audits/adversarial_reviews/director_suzuki_correction_round8.md','{"id": "FIND-SUZUKI-KNOWN-SIGNED-CORRECTION", "classification": "Correct argument, but commonly misinterpreted", "title": "Corrected bilateral formulas require the existing author signed-time erratum", "sources": ["PAPER-EC62-OP2-SUZMERGED", "arXiv2209.04658v3:pp2,4,7", "author_erratum:items1–4"], "scope": "The literal obsolete even extension has an exact contradictory Gram pair; the existing author correction restores signed bilateral formulas. This record concerns reading the corrected theorem, not a novel author error.", "evidence": "audits/adversarial_reviews/director_suzuki_correction_round8.md", "verified_author_error": false, "status": "known_author_erratum_reconstructed; no_new_error_priority", "director_adjudication": "audits/adversarial_reviews/director_suzuki_correction_round8.md", "independent_reviews": ["audits/adversarial_reviews/witness62_suzuki_signed_time.md", "audits/adversarial_reviews/prefix_formula62_suzuki_signed_extension.md"], "explicit_witness": "Old even path gives S_a=S_-a but bilateral increment norm -2g(2a)>0 for an appropriate a under RH. Existing conjugate extension repairs it.", "date": "2026-11-17", "track_file": "audits/suzuki_director_round8_findings.jsonl"}','Corrected bilateral formulas require the existing author signed-time erratum','Correct argument, but commonly misinterpreted','audits/suzuki_director_round8_findings.jsonl',NULL,0);
