INSERT INTO "graph_nodes" VALUES('THM-A001','graphs/knowledge_graph.jsonl',1012,'source inspected; central proof not audited','Theorem1.1, p1','{"record_type": "node", "id": "THM-A001", "type": "mathematical_claim", "label": "For |b_n|<=1 and 1-separated t_r in [0,T] with |sum_{N<=n<=2N}b_n n^{it_r}|>=V, R<=T^{o(1)}(N^2/V^2+N^{18/5}/V^4+T N^{12/5}/V^4).", "evidence": "Theorem1.1, p1", "status": "source inspected; central proof not audited"}','mathematical_claim','For |b_n|<=1 and 1-separated t_r in [0,T] with |sum_{N<=n<=2N}b_n n^{it_r}|>=V, R<=T^{o(1)}(N^2/V^2+N^{18/5}/V^4+T N^{12/5}/V^4).');
INSERT INTO "graph_nodes" VALUES('THM-A002','graphs/knowledge_graph.jsonl',1013,'statement and exponent reduction inspected; S3 input not audited','Theorem1.2 p2; section13.1 pp48–50','{"record_type": "node", "id": "THM-A002", "type": "mathematical_claim", "label": "For fixed sigma in the critical strip, N(sigma,T)<=T^{15(1-sigma)/(3+5sigma)+o(1)}; combining Ingham yields envelope T^{30(1-sigma)/13+o(1)}.", "evidence": "Theorem1.2 p2; section13.1 pp48–50", "status": "statement and exponent reduction inspected; S3 input not audited"}','mathematical_claim','For fixed sigma in the critical strip, N(sigma,T)<=T^{15(1-sigma)/(3+5sigma)+o(1)}; combining Ingham yields envelope T^{30(1-sigma)/13+o(1)}.');
INSERT INTO "graph_nodes" VALUES('THM-A003','graphs/knowledge_graph.jsonl',1014,'source and certificate architecture read; original run not replicated','Theorem1 p2','{"record_type": "node", "id": "THM-A003", "type": "mathematical_claim", "label": "RH holds for 0<Im rho<=3000175332800; lowest12363153437138 nontrivial zeros are on Re s=1/2.", "evidence": "Theorem1 p2", "status": "source and certificate architecture read; original run not replicated"}','mathematical_claim','RH holds for 0<Im rho<=3000175332800; lowest12363153437138 nontrivial zeros are on Re s=1/2.');
INSERT INTO "graph_nodes" VALUES('THM-A004','graphs/knowledge_graph.jsonl',1015,'original statement and local integration proof inspected; upstream whole theorem not audited','Lemma5 pp6–7 arXiv v1','{"record_type": "node", "id": "THM-A004", "type": "mathematical_claim", "label": "For fixed real even r in L1 supported[-1,1], Lipschitz at0, sum r_hat(i(rho-rho'')logT/(2pi))*4/(4-(rho-rho'')^2)=(TlogT/(2pi))*(r(0)+2int_0^1 alpha r(alpha)dalpha+O_r(1/sqrt(logT))).", "evidence": "Lemma5 pp6–7 arXiv v1", "status": "original statement and local integration proof inspected; upstream whole theorem not audited"}','mathematical_claim','For fixed real even r in L1 supported[-1,1], Lipschitz at0, sum r_hat(i(rho-rho'')logT/(2pi))*4/(4-(rho-rho'')^2)=(TlogT/(2pi))*(r(0)+2int_0^1 alpha r(alpha)dalpha+O_r(1/sqrt(logT))).');
INSERT INTO "graph_nodes" VALUES('THM-A005','graphs/knowledge_graph.jsonl',1016,'proof reconstructed by one agent; independent review pending','Proposition2.1 pp6–12','{"record_type": "node", "id": "THM-A005", "type": "mathematical_claim", "label": "For real even eta in L2 compactly supported(-lambda,lambda), int eta^2=1, K=Fourier(eta^2), and finite nonempty conjugation-invariant multiset Z, #simple_real(Z)>=2|Z|-sum_{z,s in Z} K(z-s)^2.", "evidence": "Proposition2.1 pp6–12", "status": "proof reconstructed by one agent; independent review pending"}','mathematical_claim','For real even eta in L2 compactly supported(-lambda,lambda), int eta^2=1, K=Fourier(eta^2), and finite nonempty conjugation-invariant multiset Z, #simple_real(Z)>=2|Z|-sum_{z,s in Z} K(z-s)^2.');
INSERT INTO "graph_nodes" VALUES('THM-A006','graphs/knowledge_graph.jsonl',1017,'paper read; derivative weight removal checked; upstream analytic theorem not fully audited','Theorem1.1 p3; Lemma3.2 pp13–15','{"record_type": "node", "id": "THM-A006", "type": "mathematical_claim", "label": "For classical zeta, liminf N0s/N>=3/2-cot(1/sqrt2)/sqrt2=0.6725007...; further distinctness and union bounds in record.", "evidence": "Theorem1.1 p3; Lemma3.2 pp13–15", "status": "paper read; derivative weight removal checked; upstream analytic theorem not fully audited"}','mathematical_claim','For classical zeta, liminf N0s/N>=3/2-cot(1/sqrt2)/sqrt2=0.6725007...; further distinctness and union bounds in record.');
INSERT INTO "graph_nodes" VALUES('THM-A007','graphs/knowledge_graph.jsonl',1018,'inspected independent algebra reconstruction; review pending','Lemma3.2 pp5–6','{"record_type": "node", "id": "THM-A007", "type": "mathematical_claim", "label": "If P,Q Hermitian, P>=0, rank(P)<=r,n_+(Q)<=b, then r>=2trP+4trQ-4b-||P+Q||_HS^2.", "evidence": "Lemma3.2 pp5–6", "status": "inspected independent algebra reconstruction; review pending"}','mathematical_claim','If P,Q Hermitian, P>=0, rank(P)<=r,n_+(Q)<=b, then r>=2trP+4trQ-4b-||P+Q||_HS^2.');
INSERT INTO "graph_nodes" VALUES('THM-A008','graphs/knowledge_graph.jsonl',1019,'selected source passages only; not independently established','Theorem1.1 p2; Table5 p33; section8 pp35–36','{"record_type": "node", "id": "THM-A008", "type": "mathematical_claim", "label": "liminf Nd/N>=1645064/1960733; finite search success enters Lean as extra computational axiom.", "evidence": "Theorem1.1 p2; Table5 p33; section8 pp35–36", "status": "selected source passages only; not independently established"}','mathematical_claim','liminf Nd/N>=1645064/1960733; finite search success enters Lean as extra computational axiom.');
INSERT INTO "graph_nodes" VALUES('THM-E-D201','graphs/knowledge_graph.jsonl',1020,'established_primary_source_result','Lemme2,pp315–316','{"record_type": "node", "id": "THM-E-D201", "type": "mathematical_claim", "label": "If1/2<=alpha<1andζnonvanishinginRe(s)>alpha, thenforfixedδ>0,η>0,N>=2,alpha+δ<=σ<=1, Σ_(n<=N)μ(n)n^(-s)=1/ζ(s)+O_(alpha,δ,η)(N^(-δ/3)(1+|t|)^η).", "evidence": "Lemme2,pp315–316", "status": "established_primary_source_result"}','mathematical_claim','If1/2<=alpha<1andζnonvanishinginRe(s)>alpha, thenforfixedδ>0,η>0,N>=2,alpha+δ<=σ<=1, Σ_(n<=N)μ(n)n^(-s)=1/ζ(s)+O_(alpha,δ,η)(N^(-δ/3)(1+|t|)^η).');
INSERT INTO "graph_nodes" VALUES('THM-E-D202','graphs/knowledge_graph.jsonl',1021,'derived_classical_RH_consequence','audits/baez_uniform_dependency_round2.md,LemmaF','{"record_type": "node", "id": "THM-E-D202", "type": "mathematical_claim", "label": "UnderRH thereareK,V0>0suchthatforV>=V0,sup_|v|<=V,1/2+1/loglogV<=σ<=2 |1/ζ(σ+iv)|<=exp(K logV/loglogV).", "evidence": "audits/baez_uniform_dependency_round2.md,LemmaF", "status": "derived_classical_RH_consequence"}','mathematical_claim','UnderRH thereareK,V0>0suchthatforV>=V0,sup_|v|<=V,1/2+1/loglogV<=σ<=2 |1/ζ(σ+iv)|<=exp(K logV/loglogV).');
INSERT INTO "graph_nodes" VALUES('THM-E-D203','graphs/knowledge_graph.jsonl',1022,'quantitative_reconstruction_of_required_Baez_Duarte_input','audits/baez_uniform_dependency_round2.md,(U)','{"record_type": "node", "id": "THM-E-D203", "type": "mathematical_claim", "label": "UnderRH thereexistfixedb,c,C0,N0suchthatforallintegersN>=N0,realt,c/loglogN<=ε<=1/2, |Σ_(n<=N)μ(n)n^(-1/2−ε−it)−1/ζ(1/2+ε+it)|<=C0 N^(-ε/3) exp(b log(|t|+3)/loglog(|t|+3)). WithLemmaFconstantK, chooseA8K,b2K,c6(8K+1),enlargingN0.", "evidence": "audits/baez_uniform_dependency_round2.md,(U)", "status": "quantitative_reconstruction_of_required_Baez_Duarte_input"}','mathematical_claim','UnderRH thereexistfixedb,c,C0,N0suchthatforallintegersN>=N0,realt,c/loglogN<=ε<=1/2, |Σ_(n<=N)μ(n)n^(-1/2−ε−it)−1/ζ(1/2+ε+it)|<=C0 N^(-ε/3) exp(b log(|t|+3)/loglog(|t|+3)). WithLemmaFconstantK, chooseA8K,b2K,c6(8K+1),enlargingN0.');
INSERT INTO "graph_nodes" VALUES('THM-E-D204','graphs/knowledge_graph.jsonl',1023,'established_source_result_with_dependency_reconstruction','Expanded arXiv:math/0205003v1 Proposition3.1, pp6–8; same result as journal Theorem2, pp9–10; reconstructed uniform supplement in the director note','{"record_type": "node", "id": "THM-E-D204", "type": "mathematical_claim", "label": "UnderRH, forsomefixedc>0, ε_N=c/loglogN gives ||χ+Σ_(n<=N)μ(n)n^(-ε_N)ρ_n||_H=O((loglogN)^(-1/3)). DerivedfromuniformpartialMöbiusinputI<=C N^(-2ε/3) andratioestimateJ<=C ε^(2/3), preservingoriginalshiftedcoefficients.", "evidence": "Expanded arXiv:math/0205003v1 Proposition3.1, pp6–8; same result as journal Theorem2, pp9–10; reconstructed uniform supplement in the director note", "status": "established_source_result_with_dependency_reconstruction"}','mathematical_claim','UnderRH, forsomefixedc>0, ε_N=c/loglogN gives ||χ+Σ_(n<=N)μ(n)n^(-ε_N)ρ_n||_H=O((loglogN)^(-1/3)). DerivedfromuniformpartialMöbiusinputI<=C N^(-2ε/3) andratioestimateJ<=C ε^(2/3), preservingoriginalshiftedcoefficients.');
INSERT INTO "graph_nodes" VALUES('THM-SHRINKING-EXPONENT-SCALAR-GAUSSIAN','graphs/knowledge_graph.jsonl',1024,'adjudicated_scoped','audits/adversarial_reviews/director_band_laws_round12.md','{"record_type": "node", "id": "THM-SHRINKING-EXPONENT-SCALAR-GAUSSIAN", "type": "mathematical_claim", "label": "Under RH, if b(Y)→0, a(Y)/b(Y)→r in (0,1), and a(Y)logY→infinity, the cosine prime band Y^a<p≤Y^b, centered by sum 1/p or its actual mean, converges in law and every fixed moment to N(0,(1/2)log(1/r)).", "evidence": "audits/adversarial_reviews/director_band_laws_round12.md", "status": "adjudicated_scoped", "claim_kind": "conditional_shrinking_band_limit", "hypotheses": "Symmetric strict derivative-square tail. Uses bounded aggregate polynomial powers at each fixed degree and the reconstructed sharp interface. Effective parameter estimates require effective cutoff moduli and the audited effective exceptional-prime estimate. This record alone is scalar."}','mathematical_claim','Under RH, if b(Y)→0, a(Y)/b(Y)→r in (0,1), and a(Y)logY→infinity, the cosine prime band Y^a<p≤Y^b, centered by sum 1/p or its actual mean, converges in law and every fixed moment to N(0,(1/2)log(1/r)).');
INSERT INTO "graph_nodes" VALUES('THM-ROOTED-CUE-FULL-BAND-LAW','graphs/knowledge_graph.jsonl',1025,'adjudicated_scoped','audits/adversarial_reviews/director_band_laws_round12.md','{"record_type": "node", "id": "THM-ROOTED-CUE-FULL-BAND-LAW", "type": "mathematical_claim", "label": "For any fixed 0<a<b<infinity, globally derivative-square tilted rooted CUE Fourier bands converge jointly in law and every fixed moment to the one-root-reinserted rank-two-removed sine-projection linear statistics. The centered statistic is defined in L2 and has the regularized determinant in the director note.", "evidence": "audits/adversarial_reviews/director_band_laws_round12.md", "status": "adjudicated_scoped", "claim_kind": "intrinsic_random_matrix_limit", "hypotheses": "Global Haar-matrix/root-label tilt, not per-matrix root normalization. Positive lower frequency, a fixed finite family, and centered L2 or symmetric summation. Absolute point sums diverge for the nontrivial individual cosine band. The quadratic trace correction in det2 is required. No RH or arithmetic law transfer."}','mathematical_claim','For any fixed 0<a<b<infinity, globally derivative-square tilted rooted CUE Fourier bands converge jointly in law and every fixed moment to the one-root-reinserted rank-two-removed sine-projection linear statistics. The centered statistic is defined in L2 and has the regularized determinant in the director note.');
INSERT INTO "graph_nodes" VALUES('THM-HLZ-FINITE-BAND-MOMENT-WINDOW','graphs/knowledge_graph.jsonl',1026,'adjudicated_scoped','audits/adversarial_reviews/director_band_laws_round12.md','{"record_type": "node", "id": "THM-HLZ-FINITE-BAND-MOMENT-WINDOW", "type": "mathematical_claim", "label": "For every fixed integer r≥0 with rb<1/2, the raw rth moment of the RH derivative-weighted cosine band converges to r! times [z^r] exp(H z+H z²/4)[(1−d z)^4+q z(1−d z)], where H=log(b/a), d=b−a and q=2(b³−a³)/3.", "evidence": "audits/adversarial_reviews/director_band_laws_round12.md", "status": "adjudicated_scoped", "claim_kind": "conditional_finite_moment_formula", "hypotheses": "One fixed 0<a<b and the exact symmetric strict tail. Each degree r uses aggregate arms through Y^(rb) and fixed declared exponent below 1/2. Only the source-admissible finite coefficient window is evaluated; growing r or all orders at fixed b are not justified."}','mathematical_claim','For every fixed integer r≥0 with rb<1/2, the raw rth moment of the RH derivative-weighted cosine band converges to r! times [z^r] exp(H z+H z²/4)[(1−d z)^4+q z(1−d z)], where H=log(b/a), d=b−a and q=2(b³−a³)/3.');
INSERT INTO "graph_nodes" VALUES('OBS-HLZ-ALL-ORDER-EXTRAPOLATION-BARRIER','graphs/knowledge_graph.jsonl',1027,'adjudicated_scoped','audits/adversarial_reviews/director_band_laws_round12.md','{"record_type": "node", "id": "OBS-HLZ-ALL-ORDER-EXTRAPOLATION-BARRIER", "type": "mathematical_claim", "label": "For every fixed 0<a<b, the formal all-order coefficient sequence of exp(H z+H z²/4)[(1−d z)^4+q z(1−d z)] cannot be the moments of a positive probability. Its entire formal MGF vanishes at 1/d; Gaussian-polynomial even-moment domination makes this a rigorous contradiction. A degree-70 negative Gram witness at [1/20,1/10] is independently interval-verified.", "evidence": "audits/adversarial_reviews/director_band_laws_round12.md", "status": "adjudicated_scoped", "claim_kind": "formal_extrapolation_positivity_obstruction", "hypotheses": "Pure unconditional statement about the formal sequence, not about source validity or actual higher arithmetic moments. The witness uses formal orders through 140, while that arithmetic band supplies only orders 0–4. All genuine source-window Hankel tests remain positive."}','mathematical_claim','For every fixed 0<a<b, the formal all-order coefficient sequence of exp(H z+H z²/4)[(1−d z)^4+q z(1−d z)] cannot be the moments of a positive probability. Its entire formal MGF vanishes at 1/d; Gaussian-polynomial even-moment domination makes this a rigorous contradiction. A degree-70 negative Gram witness at [1/20,1/10] is independently interval-verified.');
INSERT INTO "graph_nodes" VALUES('LEM-SUBPOWER-SUBSET-TWO-SCALE-FOURTH','graphs/knowledge_graph.jsonl',1028,'adjudicated_scoped','audits/adversarial_reviews/director_joint_process_round12.md','{"record_type": "node", "id": "LEM-SUBPOWER-SUBSET-TWO-SCALE-FOURTH", "type": "mathematical_claim", "label": "Under RH, for every prime subset I of (Y^(r0 b),Y^b], h=sum_I 1/p, one has E_Y|sum_I(cos(gamma logp)/sqrt p−1/p)|^4≤C_M min(h²+(logY)^−M,(logY)²h²), hence ≤C h^(3/2) for M≥6.", "evidence": "audits/adversarial_reviews/director_joint_process_round12.md", "status": "adjudicated_scoped", "claim_kind": "conditional_uniform_subset_lemma", "hypotheses": "Fixed 0<r0<1, b→0 and b logY→infinity, same symmetric strict derivative-square tail, all subsets uniformly at sufficiently large Y. The exact local-mass bound uses analytic disks for zeta D_I² and the classical continuous fourth moment. A full-range Ch² bound is not asserted."}','mathematical_claim','Under RH, for every prime subset I of (Y^(r0 b),Y^b], h=sum_I 1/p, one has E_Y|sum_I(cos(gamma logp)/sqrt p−1/p)|^4≤C_M min(h²+(logY)^−M,(logY)²h²), hence ≤C h^(3/2) for M≥6.');
INSERT INTO "graph_nodes" VALUES('THM-SHRINKING-BAND-BROWNIAN-PROCESS','graphs/knowledge_graph.jsonl',1029,'adjudicated_scoped','audits/adversarial_reviews/director_joint_process_round12.md','{"record_type": "node", "id": "THM-SHRINKING-BAND-BROWNIAN-PROCESS", "type": "mathematical_claim", "label": "Under RH, X_Y(r)=sum_(Y^(r0 b)<p≤Y^(r b))[cos(gamma logp)/sqrt p−1/p] converges in D([r0,1]), J1, to B_((1/2)log(r/r0)).", "evidence": "audits/adversarial_reviews/director_joint_process_round12.md", "status": "adjudicated_scoped", "claim_kind": "conditional_functional_limit", "hypotheses": "Fixed 0<r0<1, b(Y)→0, b(Y)logY→infinity and the symmetric strict derivative-square tail. Uses the two-scale fourth lemma, exact reciprocal-clock interpolation, vanishing jumps, and fixed-dimensional Gaussian projections. In-principle effective onset needs computable r0, effective cutoff moduli and the audited effective aggregate input; no numerical onset."}','mathematical_claim','Under RH, X_Y(r)=sum_(Y^(r0 b)<p≤Y^(r b))[cos(gamma logp)/sqrt p−1/p] converges in D([r0,1]), J1, to B_((1/2)log(r/r0)).');
INSERT INTO "graph_nodes" VALUES('THM-POLYNOMIAL-BAND-JOINT-THIRD-TENSOR','graphs/knowledge_graph.jsonl',1030,'adjudicated_scoped','audits/adversarial_reviews/director_joint_process_round12.md','{"record_type": "node", "id": "THM-POLYNOMIAL-BAND-JOINT-THIRD-TENSOR", "type": "mathematical_claim", "label": "Under RH, for bounded real Riemann-integrable cosine/sine weights supported in [a,b] with 0<a<b<1/6, the centered third tensor matches globally derivative-square rooted CUE. The CSS entry is 12 integral f(x)(x²−2)dx integral g(y)y dy integral h(z)z dz. Odd-sine entries vanish. Same-band CSS is (Delta3−6Delta1)Delta2².", "evidence": "audits/adversarial_reviews/director_joint_process_round12.md", "status": "adjudicated_scoped", "claim_kind": "conditional_cross_framework_joint_cumulant_match", "hypotheses": "Signed primary HLZ extraction, aggregate length Y^(3b), repeated-prime cancellation, exact strict tail, and one deterministic root on the CUE side. Fourth moments are uniformly bounded. This adds the mixed tensor to the prior pure cosine cubic, not a full arithmetic law. At [1/20,1/10] CSS=−21537/1280000000."}','mathematical_claim','Under RH, for bounded real Riemann-integrable cosine/sine weights supported in [a,b] with 0<a<b<1/6, the centered third tensor matches globally derivative-square rooted CUE. The CSS entry is 12 integral f(x)(x²−2)dx integral g(y)y dy integral h(z)z dz. Odd-sine entries vanish. Same-band CSS is (Delta3−6Delta1)Delta2².');
INSERT INTO "graph_nodes" VALUES('OBS-POLYNOMIAL-BAND-UNCORRELATED-DEPENDENCE','graphs/knowledge_graph.jsonl',1031,'adjudicated_scoped','audits/adversarial_reviews/director_joint_process_round12.md','{"record_type": "node", "id": "OBS-POLYNOMIAL-BAND-UNCORRELATED-DEPENDENCE", "type": "mathematical_claim", "label": "For nonnegative bounded Riemann-integrable cosine and sine weights with positive integrals, supported in a common [a,b]⊂(0,1/6), any arithmetic weak subsequential vector limit has dependent cosine/sine coordinates despite exact zero covariance. The supports may be disjoint.", "evidence": "audits/adversarial_reviews/director_joint_process_round12.md", "status": "adjudicated_scoped", "claim_kind": "conditional_dependence_obstruction", "hypotheses": "Assumes RH and the same strict tail. Uniform fourth moments transfer the nonzero centered CSS entry; independence would force it to vanish. Pointwise nonzero weights confined to null sets are excluded. Existence or uniqueness of a full vector limit and Gaussianity of the sine marginal are not asserted."}','mathematical_claim','For nonnegative bounded Riemann-integrable cosine and sine weights with positive integrals, supported in a common [a,b]⊂(0,1/6), any arithmetic weak subsequential vector limit has dependent cosine/sine coordinates despite exact zero covariance. The supports may be disjoint.');
INSERT INTO "graph_nodes" VALUES('THM-LB301','graphs/knowledge_graph.jsonl',1032,'independent_SA_reconstruction; parent_reported_core_review_passed','["proposals/independent_campaigns/bessel_finite_offline_countermodel_round3.md section2", "PAPER-BK001 section3", "DLMF10.25.1–3,10.32.9"]','{"record_type": "node", "id": "THM-LB301", "type": "mathematical_claim", "label": "Forc>0, K_nu(c) has only nonzero purely imaginary order zeros. They correspond viaE=-nu² to simple Dirichlet eigenvalues of -d²/dx²+c²e^(2x) on(0,infinity), and are simple as entire-function zeros.", "evidence": ["proposals/independent_campaigns/bessel_finite_offline_countermodel_round3.md section2", "PAPER-BK001 section3", "DLMF10.25.1–3,10.32.9"], "status": "independent_SA_reconstruction; parent_reported_core_review_passed", "hypotheses": "Fixedpositivec, complexorderparameter; compact-resolventDirichletSchrodinger realization."}','mathematical_claim','Forc>0, K_nu(c) has only nonzero purely imaginary order zeros. They correspond viaE=-nu² to simple Dirichlet eigenvalues of -d²/dx²+c²e^(2x) on(0,infinity), and are simple as entire-function zeros.');
INSERT INTO "graph_nodes" VALUES('THM-LB302','graphs/knowledge_graph.jsonl',1033,'independent_phase_reconstruction; parent_reported_core_review_passed','["proposals/independent_campaigns/bessel_finite_offline_countermodel_round3.md section3", "DLMF10.25.2,10.27.4,5.11.1–2", "PAPER-BK002 pp2–4"]','{"record_type": "node", "id": "THM-LB302", "type": "mathematical_claim", "label": "Positive w-ordinate zeros ofK_(w/2)(c) satisfyN(U)=U/(2pi)log[U/(ec)]+O(1). Atc2pi thetwoRiemann-vonMangoldtsmoothmaintermsmatch.", "evidence": ["proposals/independent_campaigns/bessel_finite_offline_countermodel_round3.md section3", "DLMF10.25.2,10.27.4,5.11.1–2", "PAPER-BK002 pp2–4"], "status": "independent_phase_reconstruction; parent_reported_core_review_passed", "hypotheses": "c>0fixed; exactIseriesboundsplusGamma/digammaStirling; noWKBerrorpremise."}','mathematical_claim','Positive w-ordinate zeros ofK_(w/2)(c) satisfyN(U)=U/(2pi)log[U/(ec)]+O(1). Atc2pi thetwoRiemann-vonMangoldtsmoothmaintermsmatch.');
