INSERT INTO "graph_nodes" VALUES('OBS-HR501','graphs/knowledge_graph.jsonl',1258,'adjudicated_scoped_RH_conditional; priority_unassessed','audits/adversarial_reviews/horizontal_ratio_slope_director_adjudication_round5.md; complete three proofs cited there','{"record_type": "node", "id": "OBS-HR501", "type": "mathematical_claim", "label": "Under RH, lim_(epsilon↓0)J_epsilon/epsilon=Sum_(distinct ordinatesgamma)m_gamma[1−binomial(2m_gamma,m_gamma)/4^m_gamma]/(1/4+gamma²), with both signs included separately and absolute convergence.", "evidence": "audits/adversarial_reviews/horizontal_ratio_slope_director_adjudication_round5.md; complete three proofs cited there", "status": "adjudicated_scoped_RH_conditional; priority_unassessed", "hypotheses": ["RH", "epsilon→0 through positive real values", "standard order-one completed xi and its paired Hadamard product", "no simplicity or spacing assumption"]}','mathematical_claim','Under RH, lim_(epsilon↓0)J_epsilon/epsilon=Sum_(distinct ordinatesgamma)m_gamma[1−binomial(2m_gamma,m_gamma)/4^m_gamma]/(1/4+gamma²), with both signs included separately and absolute convergence.');
INSERT INTO "graph_nodes" VALUES('OBS-HR502','graphs/knowledge_graph.jsonl',1259,'adjudicated_scoped_corollary; no simplicity certificate or priority claim','audits/adversarial_reviews/horizontal_ratio_slope_director_adjudication_round5.md; central-binomial monotonicity c_(m+1)/c_m=(2m+1)/(2m+2)','{"record_type": "node", "id": "OBS-HR502", "type": "mathematical_claim", "label": "Assuming RH, the horizontal-ratio slope in OBS-HR501 is at least C0=xi′(1)/xi(1)=1+EulerGamma/2−log(4pi)/2, with equality iff every nontrivial zeta zero is simple; the slope is strictly less than2C0.", "evidence": "audits/adversarial_reviews/horizontal_ratio_slope_director_adjudication_round5.md; central-binomial monotonicity c_(m+1)/c_m=(2m+1)/(2m+2)", "status": "adjudicated_scoped_corollary; no simplicity certificate or priority claim", "hypotheses": ["RH", "same full-height J_epsilon and limiting quantifier as OBS-HR501"]}','mathematical_claim','Assuming RH, the horizontal-ratio slope in OBS-HR501 is at least C0=xi′(1)/xi(1)=1+EulerGamma/2−log(4pi)/2, with equality iff every nontrivial zeta zero is simple; the slope is strictly less than2C0.');
INSERT INTO "graph_nodes" VALUES('OBS-HR503','graphs/knowledge_graph.jsonl',1260,'adjudicated_scoped_exact_counterexample','audits/adversarial_reviews/horizontal_ratio_slope_skeptic_round4.md §6; exact expression1+exp(−2epsilon²)−2exp(−epsilon²−epsilon)','{"record_type": "node", "id": "OBS-HR503", "type": "mathematical_claim", "label": "For even zero-free F(w)=exp(w²), H_epsilon=F(w)/F(w+epsilon) is Schur on Rew>0 yet its Poisson-centered squared-defect slope at x=1/2 is2. Thus contractivity and evenness alone do not justify exhaustion of all first-order boundary energy by zeros.", "evidence": "audits/adversarial_reviews/horizontal_ratio_slope_skeptic_round4.md §6; exact expression1+exp(−2epsilon²)−2exp(−epsilon²−epsilon)", "status": "adjudicated_scoped_exact_counterexample", "hypotheses": ["Order-two F, deliberately outside the xi order-one product hypothesis", "dnu=dt/[2pi(1/4+t²)]"]}','mathematical_claim','For even zero-free F(w)=exp(w²), H_epsilon=F(w)/F(w+epsilon) is Schur on Rew>0 yet its Poisson-centered squared-defect slope at x=1/2 is2. Thus contractivity and evenness alone do not justify exhaustion of all first-order boundary energy by zeros.');
INSERT INTO "graph_nodes" VALUES('THM-RI301','graphs/knowledge_graph.jsonl',1261,'Original statement/proof and cancellation example inspected; full Potapov foundations and whole paper not audited.','Theorem3.1/proof and following remarks,pp10–11,arXivv2','{"record_type": "node", "id": "THM-RI301", "type": "mathematical_claim", "label": "Rational para-unitary matrix functions have Blaschke–Potapov factorizations by rank-one projection factors and constant (co)isometries. Source permits poles on either side of the unit circle; arbitrary factor products may have degree cancellation.", "evidence": "Theorem3.1/proof and following remarks,pp10–11,arXivv2", "status": "Original statement/proof and cancellation example inspected; full Potapov foundations and whole paper not audited."}','mathematical_claim','Rational para-unitary matrix functions have Blaschke–Potapov factorizations by rank-one projection factors and constant (co)isometries. Source permits poles on either side of the unit circle; arbitrary factor products may have degree cancellation.');
INSERT INTO "graph_nodes" VALUES('THM-RI302','graphs/knowledge_graph.jsonl',1262,'Primary formulas and coordinate matching checked; not a proof of the separate closed-boundary operator construction or full-paper audit.','§9, equations39–43,p18,arXivv2','{"record_type": "node", "id": "THM-RI302", "type": "mathematical_claim", "label": "Passive finite-state transfer realizations have A=−C_out* C_out/2−iΩ, B=−C_out*D, unitaryD. Rank-one factors admit the displayed oscillator realization and cascades represent factor products. Under s=−ik, D=I,C_out=G, transfer is I−iG(k−Ω+iG*G/2)^−1G*.", "evidence": "§9, equations39–43,p18,arXivv2", "status": "Primary formulas and coordinate matching checked; not a proof of the separate closed-boundary operator construction or full-paper audit."}','mathematical_claim','Passive finite-state transfer realizations have A=−C_out* C_out/2−iΩ, B=−C_out*D, unitaryD. Rank-one factors admit the displayed oscillator realization and cascades represent factor products. Under s=−ik, D=I,C_out=G, transfer is I−iG(k−Ω+iG*G/2)^−1G*.');
INSERT INTO "graph_nodes" VALUES('THM-RI303','graphs/knowledge_graph.jsonl',1263,'established auxiliary proposition; novelty unassessed','proposals/independent_campaigns/factored_inner_round2.md §§1–4','{"record_type": "node", "id": "THM-RI303", "type": "mathematical_claim", "label": "For W(k)=C∏j[I−Pj+((k−dj−iaj)/(k−dj+iaj))Pj] diag(exp(ikℓa)), ℓa,aj>0, orthogonalPj, M=ΣrankPj, all crossings through1 are positive. N((0,K])=LK/(2π)+G(K)+F(0)−F(K), 0≤F<E, G nondecreasing in[0,M]. Thus −3E−2M<ΔN<3E+M and |ΔN|<3E+2M.", "evidence": "proposals/independent_campaigns/factored_inner_round2.md §§1–4", "status": "established auxiliary proposition; novelty unassessed", "hypotheses": ["Finite all-upper-half-plane inner factors, not arbitrary real-axis unitary functions.", "Positive finite edge lengths and one fixed model over all three compared heights.", "Endpoint eigenvalue1 uses argument0, so0excluded andKincluded."]}','mathematical_claim','For W(k)=C∏j[I−Pj+((k−dj−iaj)/(k−dj+iaj))Pj] diag(exp(ikℓa)), ℓa,aj>0, orthogonalPj, M=ΣrankPj, all crossings through1 are positive. N((0,K])=LK/(2π)+G(K)+F(0)−F(K), 0≤F<E, G nondecreasing in[0,M]. Thus −3E−2M<ΔN<3E+M and |ΔN|<3E+2M.');
INSERT INTO "graph_nodes" VALUES('THM-RI304','graphs/knowledge_graph.jsonl',1264,'independent reconstruction in established passive-realization framework; no literature novelty claim','proposals/independent_campaigns/factored_inner_round2.md §5','{"record_type": "node", "id": "THM-RI304", "type": "mathematical_claim", "label": "Choose Gj=sqrt(2aj)Vj with Pj=VjVj*. On edgeL2⊕C^M, use boundaryη−C*ξ=Gq and Haux=Ωq+iG*(η+C*ξ)/2, where Ωjj=djI and Ωjt=±iGj*Gt/2 with plus below diagonal. The operator is self-adjoint with compact resolvent. Its real spectral equation is exactly W(k)ξ=ξ with equal multiplicities; triangular elimination has no real poles or dark modes.", "evidence": "proposals/independent_campaigns/factored_inner_round2.md §5", "status": "independent reconstruction in established passive-realization framework; no literature novelty claim"}','mathematical_claim','Choose Gj=sqrt(2aj)Vj with Pj=VjVj*. On edgeL2⊕C^M, use boundaryη−C*ξ=Gq and Haux=Ωq+iG*(η+C*ξ)/2, where Ωjj=djI and Ωjt=±iGj*Gt/2 with plus below diagonal. The operator is self-adjoint with compact resolvent. Its real spectral equation is exactly W(k)ξ=ξ with equal multiplicities; triangular elimination has no real poles or dark modes.');
INSERT INTO "graph_nodes" VALUES('THM-RI305','graphs/knowledge_graph.jsonl',1265,'established auxiliary theorem under stated finite-model assumptions; novelty unassessed','proposals/independent_campaigns/factored_inner_round2.md §8','{"record_type": "node", "id": "THM-RI305", "type": "mathematical_claim", "label": "For arbitrary finite HermitianΩ on C^M and G:C^M→C^E, constant unitaryC and positive edge lengths, define H=(-if′,Ωq+iG*μ) on domainη−C*ξ=Gq, μ=(η+C*ξ)/2. H is self-adjoint with compact resolvent. Split darkD=⊕λ(ker(Ω−λ)∩kerG). On its orthogonal complement A=Ωv−iGv*Gv/2 has strictly lower-half-plane spectrum. Visible transfer S0=I−iGv(k−A)^−1Gv* is rational inner, −iS0*S0′=GvR*RGv*≥0, determinant phase budget2πMv. Add finite dark counts Nd to the visible phase increment. Full N=LK/(2π)+Acount(K)+F0−F(K), with Acount nondecreasing in[0,M], giving −3E−2M<ΔN<3E+M, including coincident dark/visible multiplicities.", "evidence": "proposals/independent_campaigns/factored_inner_round2.md §8", "status": "established auxiliary theorem under stated finite-model assumptions; novelty unassessed"}','mathematical_claim','For arbitrary finite HermitianΩ on C^M and G:C^M→C^E, constant unitaryC and positive edge lengths, define H=(-if′,Ωq+iG*μ) on domainη−C*ξ=Gq, μ=(η+C*ξ)/2. H is self-adjoint with compact resolvent. Split darkD=⊕λ(ker(Ω−λ)∩kerG). On its orthogonal complement A=Ωv−iGv*Gv/2 has strictly lower-half-plane spectrum. Visible transfer S0=I−iGv(k−A)^−1Gv* is rational inner, −iS0*S0′=GvR*RGv*≥0, determinant phase budget2πMv. Add finite dark counts Nd to the visible phase increment. Full N=LK/(2π)+Acount(K)+F0−F(K), with Acount nondecreasing in[0,M], giving −3E−2M<ΔN<3E+M, including coincident dark/visible multiplicities.');
INSERT INTO "graph_nodes" VALUES('THM-RI306','graphs/knowledge_graph.jsonl',1266,'conditional model obstruction, not RH','proposals/independent_campaigns/factored_inner_round2.md §§4,8','{"record_type": "node", "id": "THM-RI306", "type": "mathematical_claim", "label": "If one of these models matches Nζ atK,2K,4K with errors≤ε_K K, then3E+M≥Klog2/π−6ε_K K−O(logK). Therefore ε_K→0 forces liminf(3E_K+M_K)/K≥log2/π. Uses positive Riemann–vonMangoldt curvature and the one-sided upper bound3E+M; no assertion about zero locations.", "evidence": "proposals/independent_campaigns/factored_inner_round2.md §§4,8", "status": "conditional model obstruction, not RH"}','mathematical_claim','If one of these models matches Nζ atK,2K,4K with errors≤ε_K K, then3E+M≥Klog2/π−6ε_K K−O(logK). Therefore ε_K→0 forces liminf(3E_K+M_K)/K≥log2/π. Uses positive Riemann–vonMangoldt curvature and the one-sided upper bound3E+M; no assertion about zero locations.');
INSERT INTO "graph_nodes" VALUES('THM-RI307','graphs/knowledge_graph.jsonl',1267,'independently checked negative control','proposals/independent_campaigns/factored_inner_round2.md §6 and end§8','{"record_type": "node", "id": "THM-RI307", "type": "mathematical_claim", "label": "The coupled scalar domain f(ℓ)−f(0)=γz and periodic-derivative⊕[d] reference domain f(ℓ)−f(0)=0 intersect only with z=0 whenγ≠0. Their intersection is not dense in L2⊕C. More generally coupled/reference intersections impose Gq=0. The earlier dense-common-S finite-defect theorem cannot remove the auxiliary-state cost.", "evidence": "proposals/independent_campaigns/factored_inner_round2.md §6 and end§8", "status": "independently checked negative control"}','mathematical_claim','The coupled scalar domain f(ℓ)−f(0)=γz and periodic-derivative⊕[d] reference domain f(ℓ)−f(0)=0 intersect only with z=0 whenγ≠0. Their intersection is not dense in L2⊕C. More generally coupled/reference intersections impose Gq=0. The earlier dense-common-S finite-defect theorem cannot remove the auxiliary-state cost.');
INSERT INTO "graph_nodes" VALUES('THM-RI308','graphs/knowledge_graph.jsonl',1268,'established auxiliary counterexample','experiments/code/factored_inner_round2.py; campaign §§1–2','{"record_type": "node", "id": "THM-RI308", "type": "mathematical_claim", "label": "The inverse scalar Blaschke factor is unitary on R but has negative phase derivative. With width1/2 and edge length1, −iW*W′ at its center is−3. Thus unitarity alone does not imply the positive crossing hypothesis. With constant phase chosen so W(center)=1 it produces a negative crossing.", "evidence": "experiments/code/factored_inner_round2.py; campaign §§1–2", "status": "established auxiliary counterexample"}','mathematical_claim','The inverse scalar Blaschke factor is unitary on R but has negative phase derivative. With width1/2 and edge length1, −iW*W′ at its center is−3. Thus unitarity alone does not imply the positive crossing hypothesis. With constant phase chosen so W(center)=1 it produces a negative crossing.');
INSERT INTO "graph_nodes" VALUES('OBS-PREFIX-BESSEL','graphs/knowledge_graph.jsonl',1269,'adjudicated_scoped_unconditional_finite_theorem','audits/adversarial_reviews/director_joint_prefix_round6.md; three independent derivations; proponent explicit bounds1–2','{"record_type": "node", "id": "OBS-PREFIX-BESSEL", "type": "mathematical_claim", "label": "For integerm approachinginfinity andr=m²b/(1-b) inanyfixed[0,R], c_m(b)/m²=Phi(r)+O_R(1/m), Phi(r)=I0(2sqrt r)^2-I1(2sqrt r)^2. Withr*=m(m-1)b/(1-b), (c_m-m²)/[m(m-1)]=Phi(r*)-1+O_R(m^-2). Valuesatb0 usecontinuous limits.", "evidence": "audits/adversarial_reviews/director_joint_prefix_round6.md; three independent derivations; proponent explicit bounds1–2", "status": "adjudicated_scoped_unconditional_finite_theorem", "claim_kind": "proved_uniform_finite_cost_transition", "hypotheses": "Finite Gram matrix cost OBS-PREFIX-CLOSED; no RH or arithmetic-prefix theorem. Uniform on bounded scaled parameter only."}','mathematical_claim','For integerm approachinginfinity andr=m²b/(1-b) inanyfixed[0,R], c_m(b)/m²=Phi(r)+O_R(1/m), Phi(r)=I0(2sqrt r)^2-I1(2sqrt r)^2. Withr*=m(m-1)b/(1-b), (c_m-m²)/[m(m-1)]=Phi(r*)-1+O_R(m^-2). Valuesatb0 usecontinuous limits.');
INSERT INTO "graph_nodes" VALUES('OBS-PREFIX-JOINT-LARGE','graphs/knowledge_graph.jsonl',1270,'adjudicated_scoped_unconditional_finite_theorem','audits/adversarial_reviews/director_joint_prefix_round6.md uniformGaussian derivativeandendpointproof','{"record_type": "node", "id": "OBS-PREFIX-JOINT-LARGE", "type": "mathematical_claim", "label": "Along every joint limitm approachinginfinity,0<b<1,andm sqrt b approachinginfinity, c_m(b)~(1-b)^2[(1+sqrt b)/(1-sqrt b)]^(2m-1)/(8pi b), with relative errorO(1/[m min(2atanh sqrt b,1)]) above an absolute threshold. This includesbapproaching0 or1.", "evidence": "audits/adversarial_reviews/director_joint_prefix_round6.md uniformGaussian derivativeandendpointproof", "status": "adjudicated_scoped_unconditional_finite_theorem", "claim_kind": "proved_uniform_joint_finite_cost_asymptotic"}','mathematical_claim','Along every joint limitm approachinginfinity,0<b<1,andm sqrt b approachinginfinity, c_m(b)~(1-b)^2[(1+sqrt b)/(1-sqrt b)]^(2m-1)/(8pi b), with relative errorO(1/[m min(2atanh sqrt b,1)]) above an absolute threshold. This includesbapproaching0 or1.');
INSERT INTO "graph_nodes" VALUES('OBS-PREFIX-MATCHING-BOUNDARY','graphs/knowledge_graph.jsonl',1271,'adjudicated_scoped_unconditional_finite_theorem','audits/adversarial_reviews/director_joint_prefix_round6.md equationB; independent skeptic and witness comparison','{"record_type": "node", "id": "OBS-PREFIX-MATCHING-BOUNDARY", "type": "mathematical_claim", "label": "Letm approachinfinity,r=m²b/(1-b),Phi(r)=I0(2sqrt r)^2-I1(2sqrt r)^2. The ratio[c_m(b)/m²]/Phi(r) approaches1 wheneverr=o(m^(4/3)); approachesexp(-2alpha^(3/2)/3) whenr/m^(4/3) approachesalpha in(0,infinity); andapproaches0 whenr/m^(4/3) approachesinfinity.", "evidence": "audits/adversarial_reviews/director_joint_prefix_round6.md equationB; independent skeptic and witness comparison", "status": "adjudicated_scoped_unconditional_finite_theorem", "claim_kind": "proved_relative_transition_and_nonuniformity_witness", "hypotheses": "Finite matrix cost only. No moving-prefix arithmetic conclusion, no RH counterexample, no publication priority claim."}','mathematical_claim','Letm approachinfinity,r=m²b/(1-b),Phi(r)=I0(2sqrt r)^2-I1(2sqrt r)^2. The ratio[c_m(b)/m²]/Phi(r) approaches1 wheneverr=o(m^(4/3)); approachesexp(-2alpha^(3/2)/3) whenr/m^(4/3) approachesalpha in(0,infinity); andapproaches0 whenr/m^(4/3) approachesinfinity.');
INSERT INTO "graph_nodes" VALUES('THM-LATEST62-CA501','graphs/knowledge_graph.jsonl',1272,'adjudicated_scoped; retain conditional/model/finite scope in statement','proposals/independent_campaigns/lagarias_shared_ca_latest62_round5.md, local thresholds and interpolation','{"record_type": "node", "id": "THM-LATEST62-CA501", "type": "mathematical_claim", "label": "The only global maximizers of σ(n)/n^(1+ε*) at ε*=log(14/13)/log 13 are 55440 and 720720, which are consecutive colossally abundant integers. The prior global concavity of the Lagarias envelope and two strict endpoint certificates imply σ(n)<H_n+exp(H_n)log H_n for every integer 55440≤n≤720720.", "evidence": "proposals/independent_campaigns/lagarias_shared_ca_latest62_round5.md, local thresholds and interpolation", "status": "adjudicated_scoped; retain conditional/model/finite scope in statement", "hypotheses": "Global concavity result in lagarias_global_concavity_round2.md and exact integer replay of lagarias_latest62_ca.py; no RH assumption."}','mathematical_claim','The only global maximizers of σ(n)/n^(1+ε*) at ε*=log(14/13)/log 13 are 55440 and 720720, which are consecutive colossally abundant integers. The prior global concavity of the Lagarias envelope and two strict endpoint certificates imply σ(n)<H_n+exp(H_n)log H_n for every integer 55440≤n≤720720.');
INSERT INTO "graph_nodes" VALUES('THM-DF62-001','graphs/knowledge_graph.jsonl',1273,'established_primary_source_result','Theorem 51, arXiv v1 p. 29 and proof pp. 29–31','{"record_type": "node", "id": "THM-DF62-001", "type": "mathematical_claim", "label": "For fixed 17/22≤σ≤4/5, the zeta zero-density coefficient A(σ) obeys A(σ)≤max(2/(9σ−6),9/[8(2σ−1)]), switching at 38/49.", "evidence": "Theorem 51, arXiv v1 p. 29 and proof pp. 29–31", "status": "established_primary_source_result", "hypotheses": "Unconditional; source epsilon-loss convention."}','mathematical_claim','For fixed 17/22≤σ≤4/5, the zeta zero-density coefficient A(σ) obeys A(σ)≤max(2/(9σ−6),9/[8(2σ−1)]), switching at 38/49.');
INSERT INTO "graph_nodes" VALUES('THM-DF62-002','graphs/knowledge_graph.jsonl',1274,'primary_source_statement','Theorem 1.1 p. 2; proof §2 pp. 8–12','{"record_type": "node", "id": "THM-DF62-002", "type": "mathematical_claim", "label": "For globally tempered fixed cuspidal unitary π, or zeta, a uniform short-interval 2ℓ moment exponent θ on intervals of length X^a implies the short-strip density exponent (1−σ)max(15a/(3+5σ),4θ/[ℓ(2σ−1)+4(1−σ)])+ε for 3/5≤σ<1.", "evidence": "Theorem 1.1 p. 2; proof §2 pp. 8–12", "status": "primary_source_statement", "hypotheses": "0<a≤1, ℓ≥1, θ≥a; fixed L-function data and uniform moment hypothesis in X."}','mathematical_claim','For globally tempered fixed cuspidal unitary π, or zeta, a uniform short-interval 2ℓ moment exponent θ on intervals of length X^a implies the short-strip density exponent (1−σ)max(15a/(3+5σ),4θ/[ℓ(2σ−1)+4(1−σ)])+ε for 3/5≤σ<1.');
INSERT INTO "graph_nodes" VALUES('THM-DF62-003','graphs/knowledge_graph.jsonl',1275,'primary_source_statement','Theorem 1.2 p. 2; proof §2 pp. 11–12','{"record_type": "node", "id": "THM-DF62-003", "type": "mathematical_claim", "label": "For 2/3≤a≤1, 7/10≤σ≤4/5, the number with multiplicity of zeta zeros with Re ρ>σ and T≤Im ρ≤T+T^a is O(T^(15a(1−σ)/(3+5σ)+ε)). At σ=3/4 the exponent is 5a/9.", "evidence": "Theorem 1.2 p. 2; proof §2 pp. 11–12", "status": "primary_source_statement", "hypotheses": "Unconditional; T≥3; implied constants may depend on a,ε."}','mathematical_claim','For 2/3≤a≤1, 7/10≤σ≤4/5, the number with multiplicity of zeta zeros with Re ρ>σ and T≤Im ρ≤T+T^a is O(T^(15a(1−σ)/(3+5σ)+ε)). At σ=3/4 the exponent is 5a/9.');
INSERT INTO "graph_nodes" VALUES('THM-DF62-004','graphs/knowledge_graph.jsonl',1276,'external_kernel_check_reported_primary_formal_declaration_inspected','Palomar pinned Solution.lean, GuthMaynardStatement.global_uniform','{"record_type": "node", "id": "THM-DF62-004", "type": "mathematical_claim", "label": "Uniformly all 1/2≤σ≤1 and T≥2, the multiplicity-weighted number of actual zeta zeros with 0<Reρ<1, Reρ≥σ and |Imρ|≤T is ≤Cε T^((39/17)(1−σ)+ε).", "evidence": "Palomar pinned Solution.lean, GuthMaynardStatement.global_uniform", "status": "external_kernel_check_reported_primary_formal_declaration_inspected", "hypotheses": "For each ε>0 the constant is chosen before σ,T. No RH input."}','mathematical_claim','Uniformly all 1/2≤σ≤1 and T≥2, the multiplicity-weighted number of actual zeta zeros with 0<Reρ<1, Reρ≥σ and |Imρ|≤T is ≤Cε T^((39/17)(1−σ)+ε).');
INSERT INTO "graph_nodes" VALUES('THM-DF62-005','graphs/knowledge_graph.jsonl',1277,'external_kernel_check_reported_primary_formal_declaration_inspected','Palomar pinned Solution.lean, GuthMaynardStatement.middle_large_values','{"record_type": "node", "id": "THM-DF62-005", "type": "mathematical_claim", "label": "For N≥2, N^(6/5)≤T≤N^(5/3), and V>0, the number of 1-separated observations in any translate of [0,T] at which a dyadic Dirichlet polynomial with coefficients |a_n|≤1 reaches magnitude ≥V is Oε(N^ε(N²/V²+N^(18/7)T^(6/7)/V⁴)).", "evidence": "Palomar pinned Solution.lean, GuthMaynardStatement.middle_large_values", "status": "external_kernel_check_reported_primary_formal_declaration_inspected", "hypotheses": "All parameters and coefficients under one constant for each ε>0."}','mathematical_claim','For N≥2, N^(6/5)≤T≤N^(5/3), and V>0, the number of 1-separated observations in any translate of [0,T] at which a dyadic Dirichlet polynomial with coefficients |a_n|≤1 reaches magnitude ≥V is Oε(N^ε(N²/V²+N^(18/7)T^(6/7)/V⁴)).');
INSERT INTO "graph_nodes" VALUES('THM-DF62-006','graphs/knowledge_graph.jsonl',1278,'primary_source_statement_scoped_reading','Theorem 1.1 pp. 2–3; eqs. (33),(35) pp. 22,24; Theorem 8.14 pp. 46–47; Theorem 9.3 pp. 51–52; Hexagon 2611.00421v1','{"record_type": "node", "id": "THM-DF62-006", "type": "mathematical_claim", "label": "Source states a strict zero-free half-plane Re s>B*=0.8733458561067185768… for every continuous unitary Hecke character over every number field, with the simple norm-character pole at 1+it permitted. Zeta is the principal character over Q.", "evidence": "Theorem 1.1 pp. 2–3; eqs. (33),(35) pp. 22,24; Theorem 8.14 pp. 46–47; Theorem 9.3 pp. 51–52; Hexagon 2611.00421v1", "status": "primary_source_statement_scoped_reading", "hypotheses": "Unconditional as stated in source. Proof depends on earlier finite-order and unitary theta/character-moment analytic results and a positive-comparison induction."}','mathematical_claim','Source states a strict zero-free half-plane Re s>B*=0.8733458561067185768… for every continuous unitary Hecke character over every number field, with the simple norm-character pole at 1+it permitted. Zeta is the principal character over Q.');
INSERT INTO "graph_nodes" VALUES('LATEST62-OUIMET-V1-GUMBEL','graphs/knowledge_graph.jsonl',1279,'primary_source_claim_targeted_dependency_audit','arXiv:2611.01905v1 (2.1), (2.2), (2.6), and Theorem 2.1','{"record_type": "node", "id": "LATEST62-OUIMET-V1-GUMBEL", "type": "mathematical_claim", "label": "Fix θ>0, φ>7/2, Φ>φ+1, Cσ>0; let t=log log T and let X and η=σ−1/2 be deterministic and satisfy T^{1/t^Φ}≤X≤T^{1/t^φ}, 0<η≤Cσ t^Φ/log T, η log X/t→∞. For one τ uniform on [T,2T] let M_T=max_{|h|≤(log T)^θ}log|ζ(σ+i(τ+h))|. The author claims P(M_T−u_T≤x)→exp(−κ_θ exp(−2√(1+θ)x)) for every real x, where u_T is the specified one-point Haar-prime-phase quantile and 0<κ_θ<∞ is a microscopic Gaussian-profile lattice limit. The same maximum law is claimed separately in the Euler and Haar fields. No RH assumed, no global range maximum, no critical-line inference, no claim about zero statistics or whole-field limits.", "evidence": "arXiv:2611.01905v1 (2.1), (2.2), (2.6), and Theorem 2.1", "status": "primary_source_claim_targeted_dependency_audit"}','mathematical_claim','Fix θ>0, φ>7/2, Φ>φ+1, Cσ>0; let t=log log T and let X and η=σ−1/2 be deterministic and satisfy T^{1/t^Φ}≤X≤T^{1/t^φ}, 0<η≤Cσ t^Φ/log T, η log X/t→∞. For one τ uniform on [T,2T] let M_T=max_{|h|≤(log T)^θ}log|ζ(σ+i(τ+h))|. The author claims P(M_T−u_T≤x)→exp(−κ_θ exp(−2√(1+θ)x)) for every real x, where u_T is the specified one-point Haar-prime-phase quantile and 0<κ_θ<∞ is a microscopic Gaussian-profile lattice limit. The same maximum law is claimed separately in the Euler and Haar fields. No RH assumed, no global range maximum, no critical-line inference, no claim about zero statistics or whole-field limits.');
INSERT INTO "graph_nodes" VALUES('LATEST62-OUIMET-ZETA-EULER-BRIDGE','graphs/knowledge_graph.jsonl',1280,'scoped_dependency_reconstructed','arXiv:2610.22821v1 Proposition 3.3 (3.8), Lemmas 3.5–3.7; arXiv:2611.01905v1 (6.26)','{"record_type": "node", "id": "LATEST62-OUIMET-ZETA-EULER-BRIDGE", "type": "mathematical_claim", "label": "Under the preceding displacement and cutoff assumptions, sup_{|h|≤(log T)^θ}|log|ζ(σ+i(τ+h))|−Re Σ_{p^j≤X}p^{-j(σ+i(τ+h))}/j| is o_P(1). The maximum transfer is a consequence of this uniform approximation and a separate limit theorem for the arithmetic Euler field. The claim uses ordinary zero-density control on a random rectangle, no RH and no fixed global zero-free half-plane.", "evidence": "arXiv:2610.22821v1 Proposition 3.3 (3.8), Lemmas 3.5–3.7; arXiv:2611.01905v1 (6.26)", "status": "scoped_dependency_reconstructed"}','mathematical_claim','Under the preceding displacement and cutoff assumptions, sup_{|h|≤(log T)^θ}|log|ζ(σ+i(τ+h))|−Re Σ_{p^j≤X}p^{-j(σ+i(τ+h))}/j| is o_P(1). The maximum transfer is a consequence of this uniform approximation and a separate limit theorem for the arithmetic Euler field. The claim uses ordinary zero-density control on a random rectangle, no RH and no fixed global zero-free half-plane.');
INSERT INTO "graph_nodes" VALUES('THM-LATEST62-001','graphs/knowledge_graph.jsonl',1281,'established_primary_source_result','Theorem 1.1 p. 1; proof p. 19','{"record_type": "node", "id": "THM-LATEST62-001", "type": "mathematical_claim", "label": "For T≥1 and ε>0, the critical-line sixth moment on [0,T] is ≪ε T^(37/30+ε).", "evidence": "Theorem 1.1 p. 1; proof p. 19", "status": "established_primary_source_result", "hypotheses": "Unconditional."}','mathematical_claim','For T≥1 and ε>0, the critical-line sixth moment on [0,T] is ≪ε T^(37/30+ε).');
INSERT INTO "graph_nodes" VALUES('THM-LATEST62-002','graphs/knowledge_graph.jsonl',1282,'established_primary_source_result','Theorem 1.3 p. 2; Theorem 9.1 pp. 15–18','{"record_type": "node", "id": "THM-LATEST62-002", "type": "mathematical_claim", "label": "For T^(7/60)≤V≤T^(5/38), the maximal cardinality of a 1-spaced zeta level set at threshold V on [T,2T] is ≪ε T^(24/17+ε)V^(-128/17).", "evidence": "Theorem 1.3 p. 2; Theorem 9.1 pp. 15–18", "status": "established_primary_source_result", "hypotheses": "T≥1 and ε>0; unconditional."}','mathematical_claim','For T^(7/60)≤V≤T^(5/38), the maximal cardinality of a 1-spaced zeta level set at threshold V on [T,2T] is ≪ε T^(24/17+ε)V^(-128/17).');
INSERT INTO "graph_nodes" VALUES('THM-LATEST62-003','graphs/knowledge_graph.jsonl',1283,'established_primary_source_result','Theorem 10.1 p. 18','{"record_type": "node", "id": "THM-LATEST62-003", "type": "mathematical_claim", "label": "For T≥1 and ε>0, the critical-line twelfth moment on [0,T] is ≪ε T^(2−520/445121+ε).", "evidence": "Theorem 10.1 p. 18", "status": "established_primary_source_result", "hypotheses": "Unconditional. Proof uses Theorem 9.1 with auxiliary k=6, Trudgian–Yang 2025 exponent pair (64/135,122/243), and Bourgain subconvexity."}','mathematical_claim','For T≥1 and ε>0, the critical-line twelfth moment on [0,T] is ≪ε T^(2−520/445121+ε).');
INSERT INTO "graph_nodes" VALUES('THM-LATEST62-004','graphs/knowledge_graph.jsonl',1284,'established_primary_source_result','Theorem 1.1 p. 2','{"record_type": "node", "id": "THM-LATEST62-004", "type": "mathematical_claim", "label": "For fixed k>0 and V(T)~k log log T, the normalized measure of t in [T,2T] with log|ζ(1/2+it)|>V is at most exp(exp(ck)) exp(−V²/log log T)/sqrt(log log T) for sufficiently large T and an absolute c>0.", "evidence": "Theorem 1.1 p. 2", "status": "established_primary_source_result", "hypotheses": "Riemann hypothesis."}','mathematical_claim','For fixed k>0 and V(T)~k log log T, the normalized measure of t in [T,2T] with log|ζ(1/2+it)|>V is at most exp(exp(ck)) exp(−V²/log log T)/sqrt(log log T) for sufficiently large T and an absolute c>0.');
INSERT INTO "graph_nodes" VALUES('THM-LATEST62-005','graphs/knowledge_graph.jsonl',1285,'established_primary_source_result','Corollary 1.2 p. 2','{"record_type": "node", "id": "THM-LATEST62-005", "type": "mathematical_claim", "label": "For k≥2 the normalized critical-line 2k-th moment on [T,2T] is ≪ exp(exp(ck))(log T)^(k²) for sufficiently large T with c as in Theorem 1.1.", "evidence": "Corollary 1.2 p. 2", "status": "established_primary_source_result", "hypotheses": "Riemann hypothesis."}','mathematical_claim','For k≥2 the normalized critical-line 2k-th moment on [T,2T] is ≪ exp(exp(ck))(log T)^(k²) for sufficiently large T with c as in Theorem 1.1.');
INSERT INTO "graph_nodes" VALUES('THM-LATEST62-006','graphs/knowledge_graph.jsonl',1286,'established_primary_source_result','Theorem 1.4 p. 4; §8 pp. 40–43','{"record_type": "node", "id": "THM-LATEST62-006", "type": "mathematical_claim", "label": "For every positive integer k, the partial sums of the Dirichlet coefficients μ_k of ζ(s)^(-k) satisfy |Σ_{n≤x} μ_k(n)| ≪ sqrt(x) exp(C_k (log x/log log x)^(k/(k+1))).", "evidence": "Theorem 1.4 p. 4; §8 pp. 40–43", "status": "established_primary_source_result", "hypotheses": "Riemann hypothesis; C_k>0. At k=1 this bounds the ordinary Mertens function."}','mathematical_claim','For every positive integer k, the partial sums of the Dirichlet coefficients μ_k of ζ(s)^(-k) satisfy |Σ_{n≤x} μ_k(n)| ≪ sqrt(x) exp(C_k (log x/log log x)^(k/(k+1))).');
INSERT INTO "graph_nodes" VALUES('CAND-LATEST62-YE-SHORT-FOURTH','graphs/knowledge_graph.jsonl',1287,'adjudicated_scoped_source_dependent_corollary','audits/latest62_ye_fullread.md, A direct shorter-height envelope','{"record_type": "node", "id": "CAND-LATEST62-YE-SHORT-FOURTH", "type": "mathematical_claim", "label": "For every fixed \\(0<a\\le1\\) and every \\(\\varepsilon>0\\), uniformly for real \\(T\\ge3\\) and \\(3/5\\le\\sigma<1\\), the multiplicity count of nontrivial zeta zeros satisfying \\(\\Re\\rho>\\sigma\\) and \\(T\\le\\Im\\rho\\le T+T^a\\) is \\(O_{a,\\varepsilon}(T^{(1-\\sigma)\\max\\{15a/(3+5\\sigma),\\,2\\max(a,2/3)\\}+\\varepsilon})\\). At \\(a=3/5,\\sigma=3/4\\) this is \\(O_\\varepsilon(T^{1/3+\\varepsilon})\\); enlarging directly to the \\(a=2/3\\) estimate of Ye Theorem 1.2 gives \\(O_\\varepsilon(T^{10/27+\\varepsilon})\\).", "evidence": "audits/latest62_ye_fullread.md, A direct shorter-height envelope", "status": "adjudicated_scoped_source_dependent_corollary"}','mathematical_claim','For every fixed \(0<a\le1\) and every \(\varepsilon>0\), uniformly for real \(T\ge3\) and \(3/5\le\sigma<1\), the multiplicity count of nontrivial zeta zeros satisfying \(\Re\rho>\sigma\) and \(T\le\Im\rho\le T+T^a\) is \(O_{a,\varepsilon}(T^{(1-\sigma)\max\{15a/(3+5\sigma),\,2\max(a,2/3)\}+\varepsilon})\). At \(a=3/5,\sigma=3/4\) this is \(O_\varepsilon(T^{1/3+\varepsilon})\); enlarging directly to the \(a=2/3\) estimate of Ye Theorem 1.2 gives \(O_\varepsilon(T^{10/27+\varepsilon})\).');
INSERT INTO "graph_nodes" VALUES('CAND-LATEST62-YE-OSCILLATORY-27040','graphs/knowledge_graph.jsonl',1288,'adjudicated_scoped_source_dependent_corollary_with_external_unverified_7_8_cutoff','audits/latest62_ye_fullread.md, A direct shorter-height envelope','{"record_type": "node", "id": "CAND-LATEST62-YE-OSCILLATORY-27040", "type": "mathematical_claim", "label": "Assume as a separate external input that every nontrivial zero of \\(\\zeta(s)\\) has real part at most \\(7/8\\). Fix a real \\(\\alpha\\ne0\\) and a smooth function \\(\\phi\\in C_c^\\infty((-1,1))\\). For every \\(\\varepsilon>0\\), uniformly for all sufficiently large real \\(K\\), the smoothed oscillatory prime-power sum \\(\\sum_{n\\ge1}\\Lambda(n)e^{2\\pi i\\alpha n^{3/5}}\\phi((n-K)/K^{7/10})\\) is \\(O_{\\alpha,\\phi,\\varepsilon}(K^{27/40+\\varepsilon})\\). This is \\(m=1\\), \\(\\beta=3/5\\), \\(\\delta=7/10\\) in Ye (1.7)–(1.9). The estimate is pointwise in the window center \\(K\\), with no averaging over \\(K,\\alpha\\), or \\(\\phi\\), and with the nonzero phase fixed. Its exponent improves \\(44/65+\\varepsilon\\) from direct substitution in Ye Theorem 1.3 at those same parameters and cutoff. It makes no claim for the unphased prime count or the global prime number theorem.", "evidence": "audits/latest62_ye_fullread.md, A direct shorter-height envelope", "status": "adjudicated_scoped_source_dependent_corollary_with_external_unverified_7_8_cutoff"}','mathematical_claim','Assume as a separate external input that every nontrivial zero of \(\zeta(s)\) has real part at most \(7/8\). Fix a real \(\alpha\ne0\) and a smooth function \(\phi\in C_c^\infty((-1,1))\). For every \(\varepsilon>0\), uniformly for all sufficiently large real \(K\), the smoothed oscillatory prime-power sum \(\sum_{n\ge1}\Lambda(n)e^{2\pi i\alpha n^{3/5}}\phi((n-K)/K^{7/10})\) is \(O_{\alpha,\phi,\varepsilon}(K^{27/40+\varepsilon})\). This is \(m=1\), \(\beta=3/5\), \(\delta=7/10\) in Ye (1.7)–(1.9). The estimate is pointwise in the window center \(K\), with no averaging over \(K,\alpha\), or \(\phi\), and with the nonzero phase fixed. Its exponent improves \(44/65+\varepsilon\) from direct substitution in Ye Theorem 1.3 at those same parameters and cutoff. It makes no claim for the unphased prime count or the global prime number theorem.');
INSERT INTO "graph_nodes" VALUES('CAND-LATEST62-YE-LOCAL-BGSTB','graphs/knowledge_graph.jsonl',1289,'adjudicated_scoped_source_dependent_corollary','audits/latest62_ye_fullread.md, Weighted BGSTB height slice','{"record_type": "node", "id": "CAND-LATEST62-YE-LOCAL-BGSTB", "type": "mathematical_claim", "label": "Fix \\(0<d<2/5\\) and fixed constants \\(c,C>0\\). For \\(T\\to\\infty\\), uniformly over real \\(U\\in[cT,CT]\\), the sum of \\(e^{2y}/(1+y^2)\\) over zeta zero copies with \\(U\\le\\Im\\rho\\le U+U^{3/5}\\), \\(1/2\\le\\Re\\rho\\le1-d\\), and \\(y=(\\Re\\rho-1/2)\\log T\\), is \\(O_{d,\\varepsilon,c,C}(T^{1-d/2+\\varepsilon})\\) for each \\(\\varepsilon>0\\), hence \\(o(T)\\). This is a single-height-window estimate and does not imply global weighted BGSTB tightness.", "evidence": "audits/latest62_ye_fullread.md, Weighted BGSTB height slice", "status": "adjudicated_scoped_source_dependent_corollary"}','mathematical_claim','Fix \(0<d<2/5\) and fixed constants \(c,C>0\). For \(T\to\infty\), uniformly over real \(U\in[cT,CT]\), the sum of \(e^{2y}/(1+y^2)\) over zeta zero copies with \(U\le\Im\rho\le U+U^{3/5}\), \(1/2\le\Re\rho\le1-d\), and \(y=(\Re\rho-1/2)\log T\), is \(O_{d,\varepsilon,c,C}(T^{1-d/2+\varepsilon})\) for each \(\varepsilon>0\), hence \(o(T)\). This is a single-height-window estimate and does not imply global weighted BGSTB tightness.');
INSERT INTO "graph_nodes" VALUES('THM-L001','graphs/knowledge_graph.jsonl',1290,'independently_reconstructed_parent_adjudicated','proposals/independent_campaigns/li_advocate.md, Statement L1 and proof','{"record_type": "node", "id": "THM-L001", "type": "mathematical_claim", "label": "For every N>=1 there exists a real entire symmetric order-one F, F(0)=F(1)=1, positive on the real axis and with all zeros in 0<Re(s)<1, with lambda_n(F)>0 for 1<=n<=N but with off-line zeros. Explicit F=normalized cosh times beta=1/4 quartet at T>=10N(N+pi).", "evidence": "proposals/independent_campaigns/li_advocate.md, Statement L1 and proof", "status": "independently_reconstructed_parent_adjudicated", "hypotheses": "Generic entire-function class only; no arithmetic Dirichlet/Euler/gamma constraints."}','mathematical_claim','For every N>=1 there exists a real entire symmetric order-one F, F(0)=F(1)=1, positive on the real axis and with all zeros in 0<Re(s)<1, with lambda_n(F)>0 for 1<=n<=N but with off-line zeros. Explicit F=normalized cosh times beta=1/4 quartet at T>=10N(N+pi).');
INSERT INTO "graph_nodes" VALUES('THM-L002','graphs/knowledge_graph.jsonl',1291,'parent_reviewed_with_recorded_correction','proposals/independent_campaigns/li_advocate.md, Statement L2; revision log corrects growth lower-bound inequality','{"record_type": "node", "id": "THM-L002", "type": "mathematical_claim", "label": "THM-L001 remains true with order one infinite type and positive-ordinate zero count T/(2pi)log(T/(2pi))-T/(2pi)+O(1).", "evidence": "proposals/independent_campaigns/li_advocate.md, Statement L2; revision log corrects growth lower-bound inequality", "status": "parent_reviewed_with_recorded_correction", "hypotheses": "Construct t_k>2pi e by smooth Riemann counting term=k, pair critical-line zeros in a normalized canonical product, then insert far quartet. No arithmetic constraints."}','mathematical_claim','THM-L001 remains true with order one infinite type and positive-ordinate zero count T/(2pi)log(T/(2pi))-T/(2pi)+O(1).');
INSERT INTO "graph_nodes" VALUES('THM-L003','graphs/knowledge_graph.jsonl',1292,'exact_rational_code_and_analytic_bound_author_checked','["proposals/independent_campaigns/li_advocate.md, L3", "experiments/code/li_advocate.py", "experiments/results/li_advocate_exact.json"]','{"record_type": "node", "id": "THM-L003", "type": "mathematical_claim", "label": "F=cosh(s-1/2)/cosh(1/2) times normalized quartet beta=1/4,T=2 has lambda_n(F)>0 for n=1..11 and lambda_91(F)<0.", "evidence": ["proposals/independent_campaigns/li_advocate.md, L3", "experiments/code/li_advocate.py", "experiments/results/li_advocate_exact.json"], "status": "exact_rational_code_and_analytic_bound_author_checked", "hypotheses": "Li derivatives at s=1; real symmetric product."}','mathematical_claim','F=cosh(s-1/2)/cosh(1/2) times normalized quartet beta=1/4,T=2 has lambda_n(F)>0 for n=1..11 and lambda_91(F)<0.');
INSERT INTO "graph_nodes" VALUES('THM-L004','graphs/knowledge_graph.jsonl',1293,'all_m_proof_and_80_exact_rational_samples; independent_extension_review_not_yet_recorded','["proposals/independent_campaigns/multiplicity_general.md", "experiments/code/multiplicity_general_exact.py", "experiments/results/multiplicity_general_exact.json"]','{"record_type": "node", "id": "THM-L004", "type": "mathematical_claim", "label": "For P=(1-z)^m,m>=1,N>=0,L=N+m, the degree<=N optimal coefficient a_n=binom(n+m-1,m-1)*(L-n)_falling_m/(L+1)_rising_m. Minimum squared H2 residual=1-(L)_falling_m/(L+1)_rising_m~m^2/N for fixedm.", "evidence": ["proposals/independent_campaigns/multiplicity_general.md", "experiments/code/multiplicity_general_exact.py", "experiments/results/multiplicity_general_exact.json"], "status": "all_m_proof_and_80_exact_rational_samples; independent_extension_review_not_yet_recorded", "hypotheses": "Unweighted circle H2 norm, complex polynomial approximants, integer multiplicitym>=1."}','mathematical_claim','For P=(1-z)^m,m>=1,N>=0,L=N+m, the degree<=N optimal coefficient a_n=binom(n+m-1,m-1)*(L-n)_falling_m/(L+1)_rising_m. Minimum squared H2 residual=1-(L)_falling_m/(L+1)_rising_m~m^2/N for fixedm.');
INSERT INTO "graph_nodes" VALUES('THM-L005','graphs/knowledge_graph.jsonl',1294,'author_algebra_checked; originalLi_proof_independently_reconstructed','audits/adversarial_reviews/li_original_necessity_round2.md, explicit polynomial inw and exponential expansion','{"record_type": "node", "id": "THM-L005", "type": "mathematical_claim", "label": "The generic finite-Li-prefix countermodels cosh(s-1/2)/cosh(1/2) times a normalized beta1/4 quartet at T>=1/4 also have strictly positive Taylor coefficients of F(1/(1-z)) at every positive degree. Thus positivity of all these coefficients plus any finite positive Li prefix still does not force all zeros onto the line in this generic class.", "evidence": "audits/adversarial_reviews/li_original_necessity_round2.md, explicit polynomial inw and exponential expansion", "status": "author_algebra_checked; originalLi_proof_independently_reconstructed", "hypotheses": "Generic real symmetric entire order-one model; no Euler product, arithmetic coefficients or prescribed gamma factor."}','mathematical_claim','The generic finite-Li-prefix countermodels cosh(s-1/2)/cosh(1/2) times a normalized beta1/4 quartet at T>=1/4 also have strictly positive Taylor coefficients of F(1/(1-z)) at every positive degree. Thus positivity of all these coefficients plus any finite positive Li prefix still does not force all zeros onto the line in this generic class.');
INSERT INTO "graph_nodes" VALUES('THM-LK301','graphs/knowledge_graph.jsonl',1295,'self_contained_reconstruction_parent_review_pending','proposals/independent_campaigns/positive_kernel_countermodel_round3.md sections1–4','{"record_type": "node", "id": "THM-LK301", "type": "mathematical_claim", "label": "For delta*=H13/2-gamma-1>0, B*(w)=sinh(delta*w)/(delta*w) times product_{j>=14}sinh(w/(2j))/(w/(2j)), and C_a(w)=(cosh w+cosh a)/(1+cosh a), F_a(s)=B*(s-1/2)C_a(s-1/2)/[B*(1/2)C_a(1/2)] is real symmetric entire of exact order1/infinite type, normalizedF(0)=F(1)=1 and positive onR. For0<a<1/2 it has off-line zeros1/2±a+i pi(2k+1) and no zeros outside0<Re(s)<1.", "evidence": "proposals/independent_campaigns/positive_kernel_countermodel_round3.md sections1–4", "status": "self_contained_reconstruction_parent_review_pending", "hypotheses": "Generic entire/Laplace model only; positive delta calibrated using57/100<gamma<59/100; zero counts with multiplicity."}','mathematical_claim','For delta*=H13/2-gamma-1>0, B*(w)=sinh(delta*w)/(delta*w) times product_{j>=14}sinh(w/(2j))/(w/(2j)), and C_a(w)=(cosh w+cosh a)/(1+cosh a), F_a(s)=B*(s-1/2)C_a(s-1/2)/[B*(1/2)C_a(1/2)] is real symmetric entire of exact order1/infinite type, normalizedF(0)=F(1)=1 and positive onR. For0<a<1/2 it has off-line zeros1/2±a+i pi(2k+1) and no zeros outside0<Re(s)<1.');
INSERT INTO "graph_nodes" VALUES('THM-LK302','graphs/knowledge_graph.jsonl',1296,'analytic_reconstruction_parent_review_pending','proposals/independent_campaigns/positive_kernel_countermodel_round3.md sections1–3','{"record_type": "node", "id": "THM-LK302", "type": "mathematical_claim", "label": "The constructed family is the normalized bilateral Laplace transform of a strictly positive even C-infinity probability density onR, with double-exponential tails. Its characteristic function is bounded byexp(-|t|/224) for|t|>=28.", "evidence": "proposals/independent_campaigns/positive_kernel_countermodel_round3.md sections1–3", "status": "analytic_reconstruction_parent_review_pending", "hypotheses": "Independent uniforms with widthsdelta*,1/(2j),j>=14, plus the specified three-point symmetric variableY_a; fixed0<=a<=1/2."}','mathematical_claim','The constructed family is the normalized bilateral Laplace transform of a strictly positive even C-infinity probability density onR, with double-exponential tails. Its characteristic function is bounded byexp(-|t|/224) for|t|>=28.');
INSERT INTO "graph_nodes" VALUES('THM-LK303','graphs/knowledge_graph.jsonl',1297,'exact_formula_and_integer_brackets_checked; parent_review_pending','["proposals/independent_campaigns/positive_kernel_countermodel_round3.md section4", "experiments/code/positive_kernel_round3.py", "experiments/results/positive_kernel_round3.json"]','{"record_type": "node", "id": "THM-LK303", "type": "mathematical_claim", "label": "WithX=T/(2pi), N_a(T)=D(X)-sum_{j1..13}floor(X/j)+floor(2delta*X)+2floor(X+1/2)=XlogX-X+O(sqrtX), independently ofa in[0,1/2). More precisely remainder equals classical divisor errorDelta_D(X) plus a bounded floor term between-2and14.", "evidence": ["proposals/independent_campaigns/positive_kernel_countermodel_round3.md section4", "experiments/code/positive_kernel_round3.py", "experiments/results/positive_kernel_round3.json"], "status": "exact_formula_and_integer_brackets_checked; parent_review_pending", "hypotheses": "All zeros counted with multiplicity, including split or double odd-pi zeros. No Riemann-vonMangoldt O(logT) remainder asserted."}','mathematical_claim','WithX=T/(2pi), N_a(T)=D(X)-sum_{j1..13}floor(X/j)+floor(2delta*X)+2floor(X+1/2)=XlogX-X+O(sqrtX), independently ofa in[0,1/2). More precisely remainder equals classical divisor errorDelta_D(X) plus a bounded floor term between-2and14.');
INSERT INTO "graph_nodes" VALUES('THM-LK304','graphs/knowledge_graph.jsonl',1298,'all_N_analytic_proof_and_exact_sample_bounds_checked; parent_review_pending','["proposals/independent_campaigns/positive_kernel_countermodel_round3.md section5", "experiments/code/positive_kernel_round3.py", "experiments/results/positive_kernel_round3.json"]','{"record_type": "node", "id": "THM-LK304", "type": "mathematical_claim", "label": "For every integerN>=1 choosea_N=1/[10(N+88)5^N]. Thenlambda_n(F_aN)>0 for1<=n<=N, whileoff-line zerosremain. Every positive-degree Taylor coefficient ofF_aN(1/(1-z)) is also strictly positive.", "evidence": ["proposals/independent_campaigns/positive_kernel_countermodel_round3.md section5", "experiments/code/positive_kernel_round3.py", "experiments/results/positive_kernel_round3.json"], "status": "all_N_analytic_proof_and_exact_sample_bounds_checked; parent_review_pending", "hypotheses": "Li derivative convention at1. Generic familyTHM-LK301; no arithmetic Euler/Dirichlet/gamma/modularity conditions."}','mathematical_claim','For every integerN>=1 choosea_N=1/[10(N+88)5^N]. Thenlambda_n(F_aN)>0 for1<=n<=N, whileoff-line zerosremain. Every positive-degree Taylor coefficient ofF_aN(1/(1-z)) is also strictly positive.');
