INSERT INTO "graph_nodes" VALUES('THM-LC401','graphs/knowledge_graph.jsonl',1303,'Actualscanvisuallyread; bookalreadycounted, noadditionalwork. Original1924/27proofancestryonlypartiallyaccessed.','1986§14.14,354–355,Eqs14.14.1–5','{"record_type": "node", "id": "THM-LC401", "type": "mathematical_claim", "label": "UnderRH, criticaluppergrowth exp(C logt/loglogt), near-lineupper/lowerlog|ζ|andcontinuedargumentbounds; equalityline14.14.4notalonehalfplanebound. Exactregions/proofpassagereadincompanionaudit.", "evidence": "1986§14.14,354–355,Eqs14.14.1–5", "status": "Actualscanvisuallyread; bookalreadycounted, noadditionalwork. Original1924/27proofancestryonlypartiallyaccessed."}','mathematical_claim','UnderRH, criticaluppergrowth exp(C logt/loglogt), near-lineupper/lowerlog|ζ|andcontinuedargumentbounds; equalityline14.14.4notalonehalfplanebound. Exactregions/proofpassagereadincompanionaudit.');
INSERT INTO "graph_nodes" VALUES('THM-LC402','graphs/knowledge_graph.jsonl',1304,'adjudicated_scoped_conditional_or_function_space_theorem','audits/littlewood_dependency_corpus_round4.md§5','{"record_type": "node", "id": "THM-LC402", "type": "mathematical_claim", "label": "AssumingRH, anEulercontinuedanalyticlogbranch forlargepositiveheights, onefixedA0 equalitycurve|logζ|≤C0L(t), anduniformRe logζ≤CL(t), forallfixeda>0 existKa,t_a suchthat |logζ(σ+it)|≤KaL(t) fort≥t_a,.5+a/loglogt≤σ≤2; BCfactorO(1+A0/a).", "evidence": "audits/littlewood_dependency_corpus_round4.md§5", "status": "adjudicated_scoped_conditional_or_function_space_theorem"}','mathematical_claim','AssumingRH, anEulercontinuedanalyticlogbranch forlargepositiveheights, onefixedA0 equalitycurve|logζ|≤C0L(t), anduniformRe logζ≤CL(t), forallfixeda>0 existKa,t_a suchthat |logζ(σ+it)|≤KaL(t) fort≥t_a,.5+a/loglogt≤σ≤2; BCfactorO(1+A0/a).');
INSERT INTO "graph_nodes" VALUES('EXT-LRP001','graphs/knowledge_graph.jsonl',1305,'actual primary theorem substantively read and visually checked; whole-workL1, no complete technical audit','Unnumbered main Theorem,printedp59; constrained correction Eq2,p60','{"record_type": "node", "id": "EXT-LRP001", "type": "mathematical_claim", "label": "For fixed1<p<=2, absence of zeta zeros in Re(s)>1/p is equivalent to convergence of sum_(n<=N)mu(n){1/(nx)} to−1 in every fixed L^r(0,1),1<r<p; equivalent constrained real/rational Beurling-space density statements are included.", "evidence": "Unnumbered main Theorem,printedp59; constrained correction Eq2,p60", "status": "actual primary theorem substantively read and visually checked; whole-workL1, no complete technical audit"}','mathematical_claim','For fixed1<p<=2, absence of zeta zeros in Re(s)>1/p is equivalent to convergence of sum_(n<=N)mu(n){1/(nx)} to−1 in every fixed L^r(0,1),1<r<p; equivalent constrained real/rational Beurling-space density statements are included.');
INSERT INTO "graph_nodes" VALUES('EXT-LRP002','graphs/knowledge_graph.jsonl',1306,'actual source definitions and theorem passages read; not full proof audit','Eq22,p9; Theorem5.1,p17; classical finite-pole Theorem1.2,p8','{"record_type": "node", "id": "EXT-LRP002", "type": "mathematical_claim", "label": "For fixed k>ell>=0 and a general-frequency Riesz germ f with sup_(Re(s)>0)|f(s)/(1+s)^ell| finite, the fixed-order Riesz means converge almost everywhere to the horizontal boundary limit. The source separately recalls a classical theorem allowing finitely many boundary poles under a uniform growth condition.", "evidence": "Eq22,p9; Theorem5.1,p17; classical finite-pole Theorem1.2,p8", "status": "actual source definitions and theorem passages read; not full proof audit"}','mathematical_claim','For fixed k>ell>=0 and a general-frequency Riesz germ f with sup_(Re(s)>0)|f(s)/(1+s)^ell| finite, the fixed-order Riesz means converge almost everywhere to the horizontal boundary limit. The source separately recalls a classical theorem allowing finitely many boundary poles under a uniform growth condition.');
INSERT INTO "graph_nodes" VALUES('THM-A008-MERTENS','graphs/knowledge_graph.jsonl',1307,'Actual PDF statement visually checked against extracted text and version metadata; full proof and numerical constants not independently audited.','Theorem1.1,eq(9),PDFp2,arXiv2208.06141v5','{"record_type": "node", "id": "THM-A008-MERTENS", "type": "mathematical_claim", "label": "For every realx>=exp(4589.20), |M(x)|<33.56*x*log(x)*exp(-sqrt(log(x)/5.56)), whereM(x)=sum_{n<=x}mu(n). Stated unconditionally.", "evidence": "Theorem1.1,eq(9),PDFp2,arXiv2208.06141v5", "status": "Actual PDF statement visually checked against extracted text and version metadata; full proof and numerical constants not independently audited."}','mathematical_claim','For every realx>=exp(4589.20), |M(x)|<33.56*x*log(x)*exp(-sqrt(log(x)/5.56)), whereM(x)=sum_{n<=x}mu(n). Stated unconditionally.');
INSERT INTO "graph_nodes" VALUES('OBS-MERTENS-Q1-ASYM','graphs/knowledge_graph.jsonl',1308,'adjudicated_scoped_source_dependent_conditional_corollary','audits/adversarial_reviews/director_round5_adjudication.md; THM-LATEST62-Q1502; OBS-HR501; two independent q1 audits','{"record_type": "node", "id": "OBS-MERTENS-Q1-ASYM", "type": "mathematical_claim", "label": "Under RH, the stated BFH Mertens bound with exponentC, BFH reciprocal-first-moment Theorem1.2(1.4), and the stated uniform Bui-Florea pointwise bound, fixA>C. For epsilon_N=A/sqrt(logN loglogN), the shifted Mobius array P_N(s)=sum_{n<=N} mu(n)n^(-s-epsilon_N) has d1(P_N)^2~epsilon_N Sum_distinct_gamma m_gamma[1-binomial(2m_gamma,m_gamma)/4^m_gamma]/(1/4+gamma²).", "evidence": "audits/adversarial_reviews/director_round5_adjudication.md; THM-LATEST62-Q1502; OBS-HR501; two independent q1 audits", "status": "adjudicated_scoped_source_dependent_conditional_corollary", "hypotheses": "The extra reciprocal inputs are essential to the inspected q1 truncation proof; this is not deduced from the Mertens envelope alone. Full-height normdt/[2pi|1/2+it|²], fixedA>C and both ordinate signs."}','mathematical_claim','Under RH, the stated BFH Mertens bound with exponentC, BFH reciprocal-first-moment Theorem1.2(1.4), and the stated uniform Bui-Florea pointwise bound, fixA>C. For epsilon_N=A/sqrt(logN loglogN), the shifted Mobius array P_N(s)=sum_{n<=N} mu(n)n^(-s-epsilon_N) has d1(P_N)^2~epsilon_N Sum_distinct_gamma m_gamma[1-binomial(2m_gamma,m_gamma)/4^m_gamma]/(1/4+gamma²).');
INSERT INTO "graph_nodes" VALUES('LEM-LATEST62-Q1501','graphs/knowledge_graph.jsonl',1309,'adjudicated_scoped; retain conditional/model/finite scope in statement','proposals/independent_campaigns/mertens_shifted_q1_latest62_round5.md §2','{"record_type": "node", "id": "LEM-LATEST62-Q1501", "type": "mathematical_claim", "label": "Assume RH and the cited Bui–Florea–Heycock and Bui–Florea reciprocal estimates. With U=log x, φ(U)=sqrt(U/log U), and M_x(it)=Σ_{n≤x}μ(n)n^(−it), uniformly for |t|≤x^(3/4), |ζ(1/2+it) M_x(it)| ≪ sqrt(x){|ζ(1/2+it)|exp(C*φ(U))+(1+|t|)^(1/2)exp(D*sqrt(U)/log U)}.", "evidence": "proposals/independent_campaigns/mertens_shifted_q1_latest62_round5.md §2", "status": "adjudicated_scoped; retain conditional/model/finite scope in statement"}','mathematical_claim','Assume RH and the cited Bui–Florea–Heycock and Bui–Florea reciprocal estimates. With U=log x, φ(U)=sqrt(U/log U), and M_x(it)=Σ_{n≤x}μ(n)n^(−it), uniformly for |t|≤x^(3/4), |ζ(1/2+it) M_x(it)| ≪ sqrt(x){|ζ(1/2+it)|exp(C*φ(U))+(1+|t|)^(1/2)exp(D*sqrt(U)/log U)}.');
INSERT INTO "graph_nodes" VALUES('THM-LATEST62-Q1502','graphs/knowledge_graph.jsonl',1310,'adjudicated_scoped; retain conditional/model/finite scope in statement','proposals/independent_campaigns/mertens_shifted_q1_latest62_round5.md §3','{"record_type": "node", "id": "THM-LATEST62-Q1502", "type": "mathematical_claim", "label": "Assume RH, the BFH Mertens estimate with exponent C, and the cited reciprocal moment and pointwise estimates. For any fixed A>C, ε_N=A/sqrt(log N log log N) and P_N=Σ_{n≤N}μ(n)n^(−s−ε_N), the classical normalized error satisfies d_1(P_N)=O((log N log log N)^(-1/4)).", "evidence": "proposals/independent_campaigns/mertens_shifted_q1_latest62_round5.md §3", "status": "adjudicated_scoped; retain conditional/model/finite scope in statement"}','mathematical_claim','Assume RH, the BFH Mertens estimate with exponent C, and the cited reciprocal moment and pointwise estimates. For any fixed A>C, ε_N=A/sqrt(log N log log N) and P_N=Σ_{n≤N}μ(n)n^(−s−ε_N), the classical normalized error satisfies d_1(P_N)=O((log N log log N)^(-1/4)).');
INSERT INTO "graph_nodes" VALUES('LEM-LATEST62-W501','graphs/knowledge_graph.jsonl',1311,'adjudicated_scoped; retain conditional/model/finite scope in statement','proposals/independent_campaigns/mertens_shifted_weighted_latest62_round5.md equations (3)–(5)','{"record_type": "node", "id": "LEM-LATEST62-W501", "type": "mathematical_claim", "label": "Assume RH and |M(x)|≤K√x exp(F(log x)) eventually, with F eventually C¹ concave and F(u)=o(u). For L=log N, 0<ε≤1/4 and λ=ε−F′(L)>0, the shifted Möbius array satisfies d_q(P)≪_q √ε+K exp(F(L)−εL)(1+λ^−1) for each integer q≥2. Under RH/Lindelöf, Plancherel gives the bound with λ^−1/2 in place of λ^−1 for fixed real q>1.", "evidence": "proposals/independent_campaigns/mertens_shifted_weighted_latest62_round5.md equations (3)–(5)", "status": "adjudicated_scoped; retain conditional/model/finite scope in statement"}','mathematical_claim','Assume RH and |M(x)|≤K√x exp(F(log x)) eventually, with F eventually C¹ concave and F(u)=o(u). For L=log N, 0<ε≤1/4 and λ=ε−F′(L)>0, the shifted Möbius array satisfies d_q(P)≪_q √ε+K exp(F(L)−εL)(1+λ^−1) for each integer q≥2. Under RH/Lindelöf, Plancherel gives the bound with λ^−1/2 in place of λ^−1 for fixed real q>1.');
INSERT INTO "graph_nodes" VALUES('THM-LATEST62-W502','graphs/knowledge_graph.jsonl',1312,'adjudicated_scoped; retain conditional/model/finite scope in statement','proposals/independent_campaigns/mertens_shifted_weighted_latest62_round5.md equation (2) and converse','{"record_type": "node", "id": "THM-LATEST62-W502", "type": "mathematical_claim", "label": "Under RH and the Mertens input in arXiv:2610.27591v1 Theorem 1.4 at k=1, fix A>C and let ε_N=A/√(log N log log N). Then d_q(Σ_{n≤N} μ(n)n^(−s−ε_N))=O_{q,A,C,K}((log N log log N)^−1/4) for each fixed q>1. Independently, any fixed A>0 giving subsequence convergence to zero forces RH by the Hardy witness.", "evidence": "proposals/independent_campaigns/mertens_shifted_weighted_latest62_round5.md equation (2) and converse", "status": "adjudicated_scoped; retain conditional/model/finite scope in statement"}','mathematical_claim','Under RH and the Mertens input in arXiv:2610.27591v1 Theorem 1.4 at k=1, fix A>C and let ε_N=A/√(log N log log N). Then d_q(Σ_{n≤N} μ(n)n^(−s−ε_N))=O_{q,A,C,K}((log N log log N)^−1/4) for each fixed q>1. Independently, any fixed A>0 giving subsequence convergence to zero forces RH by the Hardy witness.');
INSERT INTO "graph_nodes" VALUES('OBS-LATEST62-W503','graphs/knowledge_graph.jsonl',1313,'adjudicated_scoped; retain conditional/model/finite scope in statement','proposals/independent_campaigns/mertens_shifted_weighted_latest62_round5.md optional leading coefficient','{"record_type": "node", "id": "OBS-LATEST62-W503", "type": "mathematical_claim", "label": "With the same hypotheses as THM-LATEST62-W502 and the separately adjudicated horizontal-ratio slope, d_q(P_N)^2~ε_N S_q for fixed q>1, where S_q=Σ_γ m_γ[1−binom(2m_γ,m_γ)/4^m_γ]/(1/4+γ²)^q over distinct ordinates of both signs.", "evidence": "proposals/independent_campaigns/mertens_shifted_weighted_latest62_round5.md optional leading coefficient", "status": "adjudicated_scoped; retain conditional/model/finite scope in statement"}','mathematical_claim','With the same hypotheses as THM-LATEST62-W502 and the separately adjudicated horizontal-ratio slope, d_q(P_N)^2~ε_N S_q for fixed q>1, where S_q=Σ_γ m_γ[1−binom(2m_γ,m_γ)/4^m_γ]/(1/4+γ²)^q over distinct ordinates of both signs.');
INSERT INTO "graph_nodes" VALUES('THM-MONT73-01','graphs/knowledge_graph.jsonl',1314,'established_primary_source_result','UnnumberedTheorem,p181;proofpp185–190,Eqs18–31','{"record_type": "node", "id": "THM-MONT73-01", "type": "mathematical_claim", "label": "AssumeRH; withFM,H,wdefinedinrecord,FMreal/even; forallε>0 eventuallyFM>=−εforallrealα; FM=(1+o1)T^(−2α)logT+α+o1uniform0≤α≤1−εforeachfixedε>0.", "evidence": "UnnumberedTheorem,p181;proofpp185–190,Eqs18–31", "status": "established_primary_source_result"}','mathematical_claim','AssumeRH; withFM,H,wdefinedinrecord,FMreal/even; forallε>0 eventuallyFM>=−εforallrealα; FM=(1+o1)T^(−2α)logT+α+o1uniform0≤α≤1−εforeachfixedε>0.');
INSERT INTO "graph_nodes" VALUES('THM-MONT73-02','graphs/knowledge_graph.jsonl',1315,'established_primary_source_result','LemmaEq18,pp185–186','{"record_type": "node", "id": "THM-MONT73-02", "type": "mathematical_claim", "label": "AssumeRH,fixed1<σ<2,allx≥1,realt,τ=|t|+2: (2σ−1)Σγ x^(iγ)/[(σ−1/2)^2+(t−γ)^2]=−x^(−1/2)[Σn≤xΛ(n)(x/n)^(1−σ+it)+Σn>xΛ(n)(x/n)^(σ+it)]+x^(1/2−σ+it)(logτ+Oσ1)+Oσ(x^(1/2)τ^−1). AllOconstantsdependonlyonσ.", "evidence": "LemmaEq18,pp185–186", "status": "established_primary_source_result"}','mathematical_claim','AssumeRH,fixed1<σ<2,allx≥1,realt,τ=|t|+2: (2σ−1)Σγ x^(iγ)/[(σ−1/2)^2+(t−γ)^2]=−x^(−1/2)[Σn≤xΛ(n)(x/n)^(1−σ+it)+Σn>xΛ(n)(x/n)^(σ+it)]+x^(1/2−σ+it)(logτ+Oσ1)+Oσ(x^(1/2)τ^−1). AllOconstantsdependonlyonσ.');
INSERT INTO "graph_nodes" VALUES('THM-MONT73-03','graphs/knowledge_graph.jsonl',1316,'established_primary_source_result','Corollary1Eq6,p182;proofp191','{"record_type": "node", "id": "THM-MONT73-03", "type": "mathematical_claim", "label": "AssumeRH,fixed0<a<1. Sumovermultiplicitycounted0<γ,γprime≤T of sinc²((a/2)(γ−γprime)logT)w(γ−γprime)~(1/a+a/3)TlogT/(2pi). Weightmaybeomitted.", "evidence": "Corollary1Eq6,p182;proofp191", "status": "established_primary_source_result"}','mathematical_claim','AssumeRH,fixed0<a<1. Sumovermultiplicitycounted0<γ,γprime≤T of sinc²((a/2)(γ−γprime)logT)w(γ−γprime)~(1/a+a/3)TlogT/(2pi). Weightmaybeomitted.');
