INSERT INTO "graph_nodes" VALUES('LEM-MONT73-D02','graphs/knowledge_graph.jsonl',1320,'elementary_derived_consequence_no_novelty_claim','Supplementarymultiplicityalgebra,independentreview','{"record_type": "node", "id": "LEM-MONT73-D02", "type": "mathematical_claim", "label": "Forpositiveintegermultiplicities,N=Σm,M2=Σm²,S=#m1,D=#distinct: S≥2N−M2 andD≥(3N−M2)/2. ThusunderoriginalRHcorrelationboundliminfD/N≥5/6.", "evidence": "Supplementarymultiplicityalgebra,independentreview", "status": "elementary_derived_consequence_no_novelty_claim"}','mathematical_claim','Forpositiveintegermultiplicities,N=Σm,M2=Σm²,S=#m1,D=#distinct: S≥2N−M2 andD≥(3N−M2)/2. ThusunderoriginalRHcorrelationboundliminfD/N≥5/6.');
INSERT INTO "graph_nodes" VALUES('THM-NOOR-A401','graphs/knowledge_graph.jsonl',1321,'adjudicated_scoped_conditional_or_function_space_theorem','Noor1809.09577v4 pp2–3 equations1.1–1.4; independent basis/preimage proof in audit','{"record_type": "node", "id": "THM-NOOR-A401", "type": "mathematical_claim", "label": "Tg=gprime−g/(1-z) is an isometric isomorphism from H² onto A with norm² sum |g_n|²/[(n+1)(n+2)].", "evidence": "Noor1809.09577v4 pp2–3 equations1.1–1.4; independent basis/preimage proof in audit", "status": "adjudicated_scoped_conditional_or_function_space_theorem", "hypotheses": ["Holomorphic unit disk", "H² coefficient norm", "A exact weights specified"]}','mathematical_claim','Tg=gprime−g/(1-z) is an isometric isomorphism from H² onto A with norm² sum |g_n|²/[(n+1)(n+2)].');
INSERT INTO "graph_nodes" VALUES('THM-NOOR-A402','graphs/knowledge_graph.jsonl',1322,'adjudicated_scoped_conditional_or_function_space_theorem','proposals/independent_campaigns/noor_critical_bergman_advocate_round4.md','{"record_type": "node", "id": "THM-NOOR-A402", "type": "mathematical_claim", "label": "For h_k=(1-z)^−1 log[(1+...+z^(k−1))/k], span{k≥2}h_k is norm dense in D−1 (unweighted area Bergman), unconditionally, using external quantitative Mertens input.", "evidence": "proposals/independent_campaigns/noor_critical_bergman_advocate_round4.md", "status": "adjudicated_scoped_conditional_or_function_space_theorem", "hypotheses": ["D−1 norm²=sum |f_n|²/(n+1)", "normalized analytic logarithm", "external M(x)=O_K(x/log^Kx) for every fixedK"]}','mathematical_claim','For h_k=(1-z)^−1 log[(1+...+z^(k−1))/k], span{k≥2}h_k is norm dense in D−1 (unweighted area Bergman), unconditionally, using external quantitative Mertens input.');
INSERT INTO "graph_nodes" VALUES('OBS-MELLIN-PHASE-DERIVATIVE-BARRIER','graphs/knowledge_graph.jsonl',1323,'adjudicated_scoped_unconditional_operator_domain_theorem','audits/adversarial_reviews/director_deroton_phase_round6.md; independentlogcoordinateanddomainproofs','{"record_type": "node", "id": "OBS-MELLIN-PHASE-DERIVATIVE-BARRIER", "type": "mathematical_claim", "label": "ForanyunitaryMellinmultiplierUonL²((0,infinity),dx), phi=U1_(0,1] hasweakdilationderivativeDphi=xphi''outsideL²(dx). Itsdistributionalcritical-lineMellintransformis-U(s),ofmodulus1a.e. No unitaryphasecanregularizetheindicatorintothisderivativedomain.", "evidence": "audits/adversarial_reviews/director_deroton_phase_round6.md; independentlogcoordinateanddomainproofs", "status": "adjudicated_scoped_unconditional_operator_domain_theorem", "claim_kind": "proved_unconditional_closed_domain_obstruction", "hypotheses": "Mellinmeasure dt/(2pi),criticalRe1/2;weakderivativeonpositiveaxis; noRHorclassicalL-functionhypothesis."}','mathematical_claim','ForanyunitaryMellinmultiplierUonL²((0,infinity),dx), phi=U1_(0,1] hasweakdilationderivativeDphi=xphi''outsideL²(dx). Itsdistributionalcritical-lineMellintransformis-U(s),ofmodulus1a.e. No unitaryphasecanregularizetheindicatorintothisderivativedomain.');
INSERT INTO "graph_nodes" VALUES('OBS-DR2006-PHASE-REPAIR','graphs/knowledge_graph.jsonl',1324,'adjudicated_verified_printed_assertion_counterexample_and_complete_scoped_repair; mainlowerconstantpreserved','audits/adversarial_reviews/director_deroton_phase_round6.md; completeeffective_cluster62_deroton_phase_repair.md','{"record_type": "node", "id": "OBS-DR2006-PHASE-REPAIR", "type": "mathematical_claim", "label": "Thejointdecay/L2assertionforphiandPhi=xphi'' inProp5.1(12)isfalse:actualzetaphasehasphi=sin(2pi x)/(pi x),Phi=2cos(2pi x)-phi. Theunimodulargamma-phasezerojetconstructioncaninsteadbeprovedbytwo weightedMellinlinescandkappaandholomorphiccutofffamilies, recoveringTheorem2underitsoriginalcomplementary-functionL²premise.", "evidence": "audits/adversarial_reviews/director_deroton_phase_round6.md; completeeffective_cluster62_deroton_phase_repair.md", "status": "adjudicated_verified_printed_assertion_counterexample_and_complete_scoped_repair; mainlowerconstantpreserved", "claim_kind": "verified_local_source_counterexample_and_replacement_proof"}','mathematical_claim','Thejointdecay/L2assertionforphiandPhi=xphi'' inProp5.1(12)isfalse:actualzetaphasehasphi=sin(2pi x)/(pi x),Phi=2cos(2pi x)-phi. Theunimodulargamma-phasezerojetconstructioncaninsteadbeprovedbytwo weightedMellinlinescandkappaandholomorphiccutofffamilies, recoveringTheorem2underitsoriginalcomplementary-functionL²premise.');
INSERT INTO "graph_nodes" VALUES('THM-PHASE-REGULARIZATION-PARETO','graphs/knowledge_graph.jsonl',1325,'adjudicated_scoped_unconditional_classical_spectral_calculation','audits/adversarial_reviews/director_phase_regularization_round6.md; two independentproofs andexactintegrals','{"record_type": "node", "id": "THM-PHASE-REGULARIZATION-PARETO", "type": "mathematical_claim", "label": "LetUbeanyunitaryMellinmultiplieroncomplexL²(dx),g=U1_(0,1],D=xpartial_xwithmaximalweakdomain. Foreach0<epsilon<1, letzin(0,1)solvez+z³=2epsilon². Theninf_{f inDomD,||f-g||<=epsilon}||Df||²=(1-z²)²/(8z),withuniqueMellinfilterf_tauhat=U(s)/[s(1+tau|s|²)],z=sqrt(tau/(4+tau)). Thus epsilon timesminimumderivativenormapproaches1/4.", "evidence": "audits/adversarial_reviews/director_phase_regularization_round6.md; two independentproofs andexactintegrals", "status": "adjudicated_scoped_unconditional_classical_spectral_calculation", "claim_kind": "proved_exact_operator_domain_regularization_frontier", "hypotheses": "CriticalRe1/2,Mellinmeasure dt/(2pi);arbitrarycomplexfunctions;maximalweakDdomain=logH1. D+.5orfullgraphnormhave differentfinitefrontiers. NoRH,source-priorityornoveltyclaim."}','mathematical_claim','LetUbeanyunitaryMellinmultiplieroncomplexL²(dx),g=U1_(0,1],D=xpartial_xwithmaximalweakdomain. Foreach0<epsilon<1, letzin(0,1)solvez+z³=2epsilon². Theninf_{f inDomD,||f-g||<=epsilon}||Df||²=(1-z²)²/(8z),withuniqueMellinfilterf_tauhat=U(s)/[s(1+tau|s|²)],z=sqrt(tau/(4+tau)). Thus epsilon timesminimumderivativenormapproaches1/4.');
INSERT INTO "graph_nodes" VALUES('OBS-PREFIX-CLOSED','graphs/knowledge_graph.jsonl',1326,'adjudicated_scoped_unconditional_finite_theorem','audits/adversarial_reviews/director_prefix_cost_round6.md; two independent proofs and72 exact rational comparisons each','{"record_type": "node", "id": "OBS-PREFIX-CLOSED", "type": "mathematical_claim", "label": "For integerm>=1 and0<=b<1, Mij=(1-b^(i+j+1))/(i+j+1),vj=-delta_j0+m b^(j+1)/(j+1), letc_m(b)=m²b+v^T M^-1v. With LegendreP_n(1)=1 and a=(1+b)/(1-b), c_m(b)=m²+2integral_1^a[P''_(m-1)(x)]²dx. For m>=2 it is strictly increasing inb and >m² forb>0; c1=1,c2=4/(1-b).", "evidence": "audits/adversarial_reviews/director_prefix_cost_round6.md; two independent proofs and72 exact rational comparisons each", "status": "adjudicated_scoped_unconditional_finite_theorem", "claim_kind": "independently_proved_finite_matrix_identity", "hypotheses": "Finite real positive definite polynomial Gram problem; no RH or arithmetic-prefix theorem premise."}','mathematical_claim','For integerm>=1 and0<=b<1, Mij=(1-b^(i+j+1))/(i+j+1),vj=-delta_j0+m b^(j+1)/(j+1), letc_m(b)=m²b+v^T M^-1v. With LegendreP_n(1)=1 and a=(1+b)/(1-b), c_m(b)=m²+2integral_1^a[P''_(m-1)(x)]²dx. For m>=2 it is strictly increasing inb and >m² forb>0; c1=1,c2=4/(1-b).');
INSERT INTO "graph_nodes" VALUES('OBS-PREFIX-ENDPOINT','graphs/knowledge_graph.jsonl',1327,'adjudicated_scoped_unconditional','audits/adversarial_reviews/director_prefix_cost_round6.md endpointregime; OBS-PREFIX-CLOSED','{"record_type": "node", "id": "OBS-PREFIX-ENDPOINT", "type": "mathematical_claim", "label": "For each fixed integerm>=2, c_m(b)~4(2m-3)binom(2m-4,m-2)^2(1-b)^(-(2m-3)) asb approaches1 frombelow. In particular the naive polepower2m-1 is wrong; c3(1/2)=165.", "evidence": "audits/adversarial_reviews/director_prefix_cost_round6.md endpointregime; OBS-PREFIX-CLOSED", "status": "adjudicated_scoped_unconditional", "claim_kind": "proved_finite_constant_endpoint_asymptotic"}','mathematical_claim','For each fixed integerm>=2, c_m(b)~4(2m-3)binom(2m-4,m-2)^2(1-b)^(-(2m-3)) asb approaches1 frombelow. In particular the naive polepower2m-1 is wrong; c3(1/2)=165.');
INSERT INTO "graph_nodes" VALUES('OBS-PREFIX-LARGE-M','graphs/knowledge_graph.jsonl',1328,'adjudicated_scoped_unconditional','audits/adversarial_reviews/director_prefix_cost_round6.md endpointLaplaceproof; independent terminal-mode proof','{"record_type": "node", "id": "OBS-PREFIX-LARGE-M", "type": "mathematical_claim", "label": "For every fixedb in(0,1), withR=(1+sqrt b)/(1-sqrt b), c_m(b)~(1-b)^2 R^(2m-1)/(8pi b) asm tendsinfinity. This is not asserted uniformly for movingb.", "evidence": "audits/adversarial_reviews/director_prefix_cost_round6.md endpointLaplaceproof; independent terminal-mode proof", "status": "adjudicated_scoped_unconditional", "claim_kind": "proved_finite_constant_large_degree_asymptotic"}','mathematical_claim','For every fixedb in(0,1), withR=(1+sqrt b)/(1-sqrt b), c_m(b)~(1-b)^2 R^(2m-1)/(8pi b) asm tendsinfinity. This is not asserted uniformly for movingb.');
INSERT INTO "graph_nodes" VALUES('OBS-PREFIX-DIAGONAL-CONTROL','graphs/knowledge_graph.jsonl',1329,'adjudicated_scoped_model_counterexample_not_actual_arithmetic_sequence','audits/adversarial_reviews/director_prefix_cost_round6.md; prefix_skeptic62.md','{"record_type": "node", "id": "OBS-PREFIX-DIAGONAL-CONTROL", "type": "mathematical_claim", "label": "The positive increasing functionsF_N(b)=c_m(b)(1+b^N) have the correct fixedb<1 limitc_m(b), whileF_N(1-1/N)/c_m(1-1/N) approaches1+e^-1. Thus even monotone fixed-prefix limits do not imply a moving-prefix relative asymptotic.", "evidence": "audits/adversarial_reviews/director_prefix_cost_round6.md; prefix_skeptic62.md", "status": "adjudicated_scoped_model_counterexample_not_actual_arithmetic_sequence", "claim_kind": "explicit_negative_control_to_uniformity_inference"}','mathematical_claim','The positive increasing functionsF_N(b)=c_m(b)(1+b^N) have the correct fixedb<1 limitc_m(b), whileF_N(1-1/N)/c_m(1-1/N) approaches1+e^-1. Thus even monotone fixed-prefix limits do not imply a moving-prefix relative asymptotic.');
INSERT INTO "graph_nodes" VALUES('PREFIX-FORMULA62-IMPRIMITIVE-SANDWICH','graphs/knowledge_graph.jsonl',1330,'adjudicated_scoped_unconditional','audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, Two inequalities','{"record_type": "node", "id": "PREFIX-FORMULA62-IMPRIMITIVE-SANDWICH", "type": "mathematical_claim", "label": "For fixed imprimitive chi induced by chi*, M the product of newly omitted primes, and delta_J the product envelope in the proof, Delta_(MN,chi*) <= Delta_(N,chi) <= (1+delta_J)Delta_(floor(N/M^J),chi*)+delta_J. Ordinary unrestricted coefficients, N>=M^J.", "evidence": "audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, Two inequalities", "status": "adjudicated_scoped_unconditional", "claim_kind": "unconditional_finite_factor_transfer"}','mathematical_claim','For fixed imprimitive chi induced by chi*, M the product of newly omitted primes, and delta_J the product envelope in the proof, Delta_(MN,chi*) <= Delta_(N,chi) <= (1+delta_J)Delta_(floor(N/M^J),chi*)+delta_J. Ordinary unrestricted coefficients, N>=M^J.');
INSERT INTO "graph_nodes" VALUES('PREFIX-FORMULA62-IMPRIMITIVE-OPTIMUM','graphs/knowledge_graph.jsonl',1331,'adjudicated_scoped_conditional_on_primitive_optimum','audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, Right constant','{"record_type": "node", "id": "PREFIX-FORMULA62-IMPRIMITIVE-OPTIMUM", "type": "mathematical_claim", "label": "For fixed induced chi and the primitive GRH-conditional optimum, log(N)Delta_(N,chi)^2 has the same squared multiplicity constant of distinct critical-line zeros as the inducing primitive function, including the imprimitive principal case under RH.", "evidence": "audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, Right constant", "status": "adjudicated_scoped_conditional_on_primitive_optimum", "claim_kind": "conditional_arithmetic_corollary"}','mathematical_claim','For fixed induced chi and the primitive GRH-conditional optimum, log(N)Delta_(N,chi)^2 has the same squared multiplicity constant of distinct critical-line zeros as the inducing primitive function, including the imprimitive principal case under RH.');
INSERT INTO "graph_nodes" VALUES('PREFIX-FORMULA62-NONPRINCIPAL-ANCHOR','graphs/knowledge_graph.jsonl',1332,'adjudicated_scoped_unconditional','audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, What an anchor at one changes','{"record_type": "node", "id": "PREFIX-FORMULA62-NONPRINCIPAL-ANCHOR", "type": "mathematical_claim", "label": "For every fixed nonprincipal Dirichlet character, imposing A(1)=0, including via A−A(1), makes the ordinary critical-line rational-weight distance exactly one at every cutoff.", "evidence": "audits/adversarial_reviews/prefix_formula62_imprimitive_transfer.md, What an anchor at one changes", "status": "adjudicated_scoped_unconditional", "claim_kind": "unconditional_anchor_obstruction"}','mathematical_claim','For every fixed nonprincipal Dirichlet character, imposing A(1)=0, including via A−A(1), makes the ordinary critical-line rational-weight distance exactly one at every cutoff.');
INSERT INTO "graph_nodes" VALUES('LEM-ROOTED-CUE-TAGGED-COMPRESSION','graphs/knowledge_graph.jsonl',1333,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md · Measure and exact complementary determinant; separate signed totals','{"record_type": "node", "id": "LEM-ROOTED-CUE-TAGGED-COMPRESSION", "type": "mathematical_claim", "label": "The rank-two rooted CUE MGF equals e^(−H_N z_c) det A det(U* A^−1 U). For each tagged word with positive and negative totals P,Q≤n=N+1, the compressed inverse coefficient uses the oriented sum from Q to n−P; its constant/linear matrix is the polynomial in ell=n−P−Q and D=P−Q in the director note.", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md · Measure and exact complementary determinant; separate signed totals", "status": "adjudicated_scoped", "claim_kind": "intrinsic_exact_finite_identity", "hypotheses": "Global joint Haar-matrix/root-label derivative-square tilt with the deterministic root reinserted; formal coefficients at zero. The reversed interval contributes an oriented sum, including P=n or Q=n. No fixed-symbol asymptotic is invoked."}','mathematical_claim','The rank-two rooted CUE MGF equals e^(−H_N z_c) det A det(U* A^−1 U). For each tagged word with positive and negative totals P,Q≤n=N+1, the compressed inverse coefficient uses the oriented sum from Q to n−P; its constant/linear matrix is the polynomial in ell=n−P−Q and D=P−Q in the director note.');
INSERT INTO "graph_nodes" VALUES('THM-ROOTED-CUE-JOINT-CLOSED-MOMENT-WINDOW','graphs/knowledge_graph.jsonl',1334,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md · Joint quartic and exact finite-size surrogate','{"record_type": "node", "id": "THM-ROOTED-CUE-JOINT-CLOSED-MOMENT-WINDOW", "type": "mathematical_claim", "label": "At each fixed total degree r with rb≤1, the limiting mixed moments are the factorial-weighted coefficients of exp[H z_c+H(z_c²+z_s²)/4] [(1−d z_c)^4+2J3 z_c(1−d z_c)−3J2² z_s²], where H=log(b/a), d=b−a and J_j=(b^j−a^j)/j. The exact finite surrogate uses H_N, d_N, J_j,N and the n^−2 correction in the note.", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md · Joint quartic and exact finite-size surrogate", "status": "adjudicated_scoped", "claim_kind": "intrinsic_finite_mixed_moment_window", "hypotheses": "Fixed 0<a<b<1; negative cosine/sine bands, one deterministic root, global rank-two tilt. Finite agreement through degree r holds for r K_N≤n=N+1. The arithmetic window remains rb<1/2 under RH; this result is intrinsic."}','mathematical_claim','At each fixed total degree r with rb≤1, the limiting mixed moments are the factorial-weighted coefficients of exp[H z_c+H(z_c²+z_s²)/4] [(1−d z_c)^4+2J3 z_c(1−d z_c)−3J2² z_s²], where H=log(b/a), d=b−a and J_j=(b^j−a^j)/j. The exact finite surrogate uses H_N, d_N, J_j,N and the n^−2 correction in the note.');
INSERT INTO "graph_nodes" VALUES('THM-ROOTED-CUE-FIRST-FREQUENCY-CORRECTION','graphs/knowledge_graph.jsonl',1335,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md · First new frequency chamber','{"record_type": "node", "id": "THM-ROOTED-CUE-FIRST-FREQUENCY-CORRECTION", "type": "mathematical_claim", "label": "For (r−1)b≤1<rb, the first cosine raw-moment discrepancy from its formal continuation is −2^(1−r) I_r, where I_r=∫_{[a,b]^r, sum x_i>1}(2−4 sum x_i+2(sum x_i)^3) prod dx_i/x_i>0. The joint degree-r MGF difference is −[(z_c−i z_s)^r+(z_c+i z_s)^r] I_r/(2^r r!).", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md · First new frequency chamber", "status": "adjudicated_scoped", "claim_kind": "intrinsic_first_chamber_correction", "hypotheses": "Same fixed rank-two model; only the first crossing is evaluated. The pure cosine sign is strict; mixed rays can vanish or change sign."}','mathematical_claim','For (r−1)b≤1<rb, the first cosine raw-moment discrepancy from its formal continuation is −2^(1−r) I_r, where I_r=∫_{[a,b]^r, sum x_i>1}(2−4 sum x_i+2(sum x_i)^3) prod dx_i/x_i>0. The joint degree-r MGF difference is −[(z_c−i z_s)^r+(z_c+i z_s)^r] I_r/(2^r r!).');
INSERT INTO "graph_nodes" VALUES('CERT-ROOTED-CUE-FIRST-CHAMBER-FOURTH','graphs/knowledge_graph.jsonl',1336,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md · Independent exact finite and continuum checks','{"record_type": "node", "id": "CERT-ROOTED-CUE-FIRST-CHAMBER-FOURTH", "type": "mathematical_claim", "label": "For N=40, n=41 and modes 9,10,11 the exact fourth moment minus the formal surrogate is −3384187/302541624000. For band (0.22,0.28) an exact rational enclosure of the limiting fourth correction near −1.116093794622113479066e−5 has width <2.63e−27.", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md · Independent exact finite and continuum checks", "status": "adjudicated_scoped", "claim_kind": "exact_finite_and_interval_certificate", "hypotheses": "Exact rational projection/cumulant and simplex checks. The director''s finite calculation is experiments/results/director_round13_cue_fourth.json. These certificates do not give an arithmetic chamber or convergence rate."}','mathematical_claim','For N=40, n=41 and modes 9,10,11 the exact fourth moment minus the formal surrogate is −3384187/302541624000. For band (0.22,0.28) an exact rational enclosure of the limiting fourth correction near −1.116093794622113479066e−5 has width <2.63e−27.');
INSERT INTO "graph_nodes" VALUES('THM-ROOTED-CUE-INTEGER-RANK-WINDOW','graphs/knowledge_graph.jsonl',1337,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md · Every fixed integer tilt rank has an extrapolation barrier','{"record_type": "node", "id": "THM-ROOTED-CUE-INTEGER-RANK-WINDOW", "type": "mathematical_claim", "label": "At fixed integer rank J≥1 the cosine-window coefficients for rb≤1 are those of exp[(J−1)H z+H z²/4] det B_J(z), with B_J the formal oriented Legendre matrix in the note, B_J(0)=I, and deg det B_J≤J².", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md · Every fixed integer tilt rank has an extrapolation barrier", "status": "adjudicated_scoped", "claim_kind": "intrinsic_fixed_rank_moment_window", "hypotheses": "Global root tilt |Z′|^(2(J−1)), ambient dimension N+J−1, one deterministic root, fixed positive band and fixed degree. Formal compound-Poisson notation computes polynomial coefficients."}','mathematical_claim','At fixed integer rank J≥1 the cosine-window coefficients for rb≤1 are those of exp[(J−1)H z+H z²/4] det B_J(z), with B_J the formal oriented Legendre matrix in the note, B_J(0)=I, and deg det B_J≤J².');
INSERT INTO "graph_nodes" VALUES('OBS-ROOTED-CUE-ALL-RANK-FINITE-SQUARE-BARRIER','graphs/knowledge_graph.jsonl',1338,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md · Every fixed integer tilt rank has an extrapolation barrier','{"record_type": "node", "id": "OBS-ROOTED-CUE-ALL-RANK-FINITE-SQUARE-BARRIER", "type": "mathematical_claim", "label": "For each integer J≥1 and fixed 0<a<b<1 the formal all-order cosine continuation has a positive real MGF zero and a finite negative square witness. For J≥3 the {0,2} principal minor at z=1/d has determinant −20(m3/d)², forcing a zero before 1/d. Centered finite Taylor approximants to exp(z* X/2) eventually have negative formal square expectation.", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md · Every fixed integer tilt rank has an extrapolation barrier", "status": "adjudicated_scoped", "claim_kind": "formal_extrapolation_positivity_obstruction", "hypotheses": "The polynomial-exponential signed inverse has Gaussian moment domination. The witness is at finite but potentially large degree in the formal sequence; no contradiction to the true finite window or novelty is claimed."}','mathematical_claim','For each integer J≥1 and fixed 0<a<b<1 the formal all-order cosine continuation has a positive real MGF zero and a finite negative square witness. For J≥3 the {0,2} principal minor at z=1/d has determinant −20(m3/d)², forcing a zero before 1/d. Centered finite Taylor approximants to exp(z* X/2) eventually have negative formal square expectation.');
INSERT INTO "graph_nodes" VALUES('THM-ROOTED-CUE-RANK-CORRECTION-PARITY','graphs/knowledge_graph.jsonl',1339,'adjudicated_scoped','audits/adversarial_reviews/director_cue_windows_round13.md · Every fixed integer tilt rank has an extrapolation barrier','{"record_type": "node", "id": "THM-ROOTED-CUE-RANK-CORRECTION-PARITY", "type": "mathematical_claim", "label": "For (r−1)b≤1<rb the first cosine raw-moment discrepancy at fixed rank J has sign (−1)^(J+1). The pure-sign continuation A_J(t) has sign (−1)^J for t>1; rank three gives A_3(t)=−6t^5+12t³−9t+3 and a finite example with correction +9/160.", "evidence": "audits/adversarial_reviews/director_cue_windows_round13.md · Every fixed integer tilt rank has an extrapolation barrier", "status": "adjudicated_scoped", "claim_kind": "intrinsic_first_chamber_rank_sign", "hypotheses": "Intrinsic globally weighted rooted model. Christoffel–Darboux and Legendre parity apply to the reversed integration interval. This is a first crossing sign only."}','mathematical_claim','For (r−1)b≤1<rb the first cosine raw-moment discrepancy at fixed rank J has sign (−1)^(J+1). The pure-sign continuation A_J(t) has sign (−1)^J for t>1; rank three gives A_3(t)=−6t^5+12t³−9t+3 and a finite example with correction +9/160.');
INSERT INTO "graph_nodes" VALUES('THM-GRID-TWO-SCALE-UNIVERSAL-TIGHTNESS','graphs/knowledge_graph.jsonl',1340,'adjudicated_scoped','audits/adversarial_reviews/director_two_scale_round13.md · Statement with the quantifiers fixed','{"record_type": "node", "id": "THM-GRID-TWO-SCALE-UNIVERSAL-TIGHTNESS", "type": "mathematical_claim", "label": "For node increments bounded in pth moment by C min(h^a+epsilon_n,A_n h^b), the polygonal modulus satisfies ||omega(delta)||_p≤C1 [delta^((a′−1)/p)+lambda_n^(1/p) min(1,(delta/w_n)^((b′−1)/p))], where a′=min(a,p), b′=min(b,p), w_n=(epsilon_n/A_n)^(1/b), lambda_n=epsilon_n/w_n. The universal tightness criterion A_n epsilon_n^(b−1)→0 is sharp, with a single random spike giving failure otherwise.", "evidence": "audits/adversarial_reviews/director_two_scale_round13.md · Statement with the quantifiers fixed", "status": "adjudicated_scoped", "claim_kind": "unconditional_sharp_universal_tightness", "hypotheses": "Fixed p,a,b>1 and C>0, A_n≥1, 0<epsilon_n≤1 tending to zero, arbitrary deterministic finite grids, tight initial values for each family. A guarantee uniform across families needs uniformly tight initial values. Step transfer uses mesh→0, jumps→0, or exact composition and continuous clock comparison as specified. Necessity quantifies over grids and laws rather than one process."}','mathematical_claim','For node increments bounded in pth moment by C min(h^a+epsilon_n,A_n h^b), the polygonal modulus satisfies ||omega(delta)||_p≤C1 [delta^((a′−1)/p)+lambda_n^(1/p) min(1,(delta/w_n)^((b′−1)/p))], where a′=min(a,p), b′=min(b,p), w_n=(epsilon_n/A_n)^(1/b), lambda_n=epsilon_n/w_n. The universal tightness criterion A_n epsilon_n^(b−1)→0 is sharp, with a single random spike giving failure otherwise.');
INSERT INTO "graph_nodes" VALUES('LEM-GRID-TWO-SCALE-DIRECT-EXPONENT','graphs/knowledge_graph.jsonl',1341,'adjudicated_scoped','audits/adversarial_reviews/director_two_scale_round13.md · Direct exponents, arithmetic use and Lean boundary','{"record_type": "node", "id": "LEM-GRID-TWO-SCALE-DIRECT-EXPONENT", "type": "mathematical_claim", "label": "For 1<q≤min(a,b), the optimal scalar envelope constant is comparable to 1+A_n^(q/b) epsilon_n^(1−q/b). For a=b=2, A=L² and epsilon=L^−M, the sharp universal saving threshold is M>2 and the maximal common direct exponent is 2M/(M+2) as L→infinity.", "evidence": "audits/adversarial_reviews/director_two_scale_round13.md · Direct exponents, arithmetic use and Lean boundary", "status": "adjudicated_scoped", "claim_kind": "unconditional_scalar_envelope_bound", "hypotheses": "All scalar distances 0<h≤1; realized distances in a particular grid can give stronger estimates. For M≤2 no uniform q>1 follows from the envelope. Polygonal interpolation caps the power at p."}','mathematical_claim','For 1<q≤min(a,b), the optimal scalar envelope constant is comparable to 1+A_n^(q/b) epsilon_n^(1−q/b). For a=b=2, A=L² and epsilon=L^−M, the sharp universal saving threshold is M>2 and the maximal common direct exponent is 2M/(M+2) as L→infinity.');
INSERT INTO "graph_nodes" VALUES('CERT-LEAN-TWO-SCALE-SCALAR','graphs/knowledge_graph.jsonl',1342,'adjudicated_scoped','audits/adversarial_reviews/director_two_scale_round13.md · Direct exponents, arithmetic use and Lean boundary','{"record_type": "node", "id": "CERT-LEAN-TWO-SCALE-SCALAR", "type": "mathematical_claim", "label": "Lean declaration Observatory.twoScaleScalarBound proves X≤2 C u³ from X≤C(u⁴+v⁶), X v²≤C u⁴, 0≤u≤1, 0<v≤1 and C≥0. With h=u² and L=1/v this is the M=6 scalar step.", "evidence": "audits/adversarial_reviews/director_two_scale_round13.md · Direct exponents, arithmetic use and Lean boundary", "status": "adjudicated_scoped", "claim_kind": "locally_compiled_formal_scalar_check", "hypotheses": "Lean 4.33.0-rc2, standard axiom closure propext, Classical.choice and Quot.sound, no sorryAx. Both scalar inequalities are premises; the probability and number-theoretic inputs and Brownian limit are outside this declaration."}','mathematical_claim','Lean declaration Observatory.twoScaleScalarBound proves X≤2 C u³ from X≤C(u⁴+v⁶), X v²≤C u⁴, 0≤u≤1, 0<v≤1 and C≥0. With h=u² and L=1/v this is the M=6 scalar step.');
INSERT INTO "graph_nodes" VALUES('THM-HR-REPAIRED-FINITE-GAUSSIAN-MOMENTS','graphs/knowledge_graph.jsonl',1343,'adjudicated_scoped','audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md · Statistic, literal hypotheses and repaired theorem','{"record_type": "node", "id": "THM-HR-REPAIRED-FINITE-GAUSSIAN-MOMENTS", "type": "mathematical_claim", "label": "The first m raw zero-statistic moments converge to the Gaussian moments of mean I=∫f and variance ∫min(|v|,1) fhat(v)² dv, provided I=0 or ∫w(u) log^m(2+|u|)du<infinity. For I≠0 that logarithmic moment is necessary for finiteness of the mth absolute moment at any fixed T>1,H>0.", "evidence": "audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md · Statistic, literal hypotheses and repaired theorem", "status": "adjudicated_scoped", "claim_kind": "versioned_repaired_source_theorem", "hypotheses": "No RH. Real even f with smooth compact Fourier transform in [−sigma,sigma], m sigma/2<a, H=T^a, 0<a≤1; evaluate the entire extension at complex ordinates. Nonnegative mass-one w with compact Fourier support. Finite moment window; the repair controls mixed gamma and polar terms additively."}','mathematical_claim','The first m raw zero-statistic moments converge to the Gaussian moments of mean I=∫f and variance ∫min(|v|,1) fhat(v)² dv, provided I=0 or ∫w(u) log^m(2+|u|)du<infinity. For I≠0 that logarithmic moment is necessary for finiteness of the mth absolute moment at any fixed T>1,H>0.');
INSERT INTO "graph_nodes" VALUES('THM-HR-OSCILLATORY-PRINTED-WEIGHT-WINDOW','graphs/knowledge_graph.jsonl',1344,'adjudicated_scoped','audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md · Reconstruction of the valid argument','{"record_type": "node", "id": "THM-HR-OSCILLATORY-PRINTED-WEIGHT-WINDOW", "type": "mathematical_claim", "label": "The oscillatory prime statistic alone has the stated finite Gaussian moment window with the original nonnegative unit-mass bandlimited weights. Compact Fourier support eliminates unequal product frequencies and the leading equal-product terms give Wick pairings.", "evidence": "audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md · Reconstruction of the valid argument", "status": "adjudicated_scoped", "claim_kind": "versioned_source_theorem_reconstruction", "hypotheses": "No RH and no logarithmic moment required for this oscillatory theorem. Same strict m sigma/2<a; the variance identification is needed only when m≥2. This theorem excludes the centering and polar contributions to the full statistic."}','mathematical_claim','The oscillatory prime statistic alone has the stated finite Gaussian moment window with the original nonnegative unit-mass bandlimited weights. Compact Fourier support eliminates unequal product frequencies and the leading equal-product terms give Wick pairings.');
INSERT INTO "graph_nodes" VALUES('OBS-HLZ-FOURTH-PURE-ARM-REDUCTION','graphs/knowledge_graph.jsonl',1345,'adjudicated_scoped','audits/adversarial_reviews/director_pure_fourth_round13.md · Exact target and what is already covered','{"record_type": "node", "id": "OBS-HLZ-FOURTH-PURE-ARM-REDUCTION", "type": "mathematical_claim", "label": "For the cosine band W=Re D and 1/8<b<1/6, the difference between E_Y W⁴ and its formal fourth coefficient is (Re E_Y D⁴−m4_pure)/8+o(1), with m4_pure=4![z⁴] exp(H0 z)[(1−d z)^4+2m3 z(1−d z)+3m2² z²]. The mixed arms and a uniform sixth absolute moment are already covered.", "evidence": "audits/adversarial_reviews/director_pure_fourth_round13.md · Exact target and what is already covered", "status": "adjudicated_scoped", "claim_kind": "conditional_exact_single_arm_reduction", "hypotheses": "RH, fixed 0<a<b, and the symmetric strict derivative-square tail. The 3+1 and 2+2 arms have longest length ≤Y^(3b)<sqrt(Y); the long pure arm is unresolved. Intrinsic CUE gives no arithmetic main term."}','mathematical_claim','For the cosine band W=Re D and 1/8<b<1/6, the difference between E_Y W⁴ and its formal fourth coefficient is (Re E_Y D⁴−m4_pure)/8+o(1), with m4_pure=4![z⁴] exp(H0 z)[(1−d z)^4+2m3 z(1−d z)+3m2² z²]. The mixed arms and a uniform sixth absolute moment are already covered.');
INSERT INTO "graph_nodes" VALUES('LEM-HLZ-ONE-SIDED-LONG-CONTINUOUS','graphs/knowledge_graph.jsonl',1346,'adjudicated_scoped','audits/adversarial_reviews/director_pure_fourth_round13.md · One-sided continuous moments do not impose the half-power barrier','{"record_type": "node", "id": "LEM-HLZ-ONE-SIDED-LONG-CONTINUOUS", "type": "mathematical_claim", "label": "The continuous shifted zeta product against one bounded-coefficient Dirichlet polynomial of length y≤T^theta, theta<1, has the explicit two-diagonal formula in the note with error O_epsilon(T^epsilon[(yT)^(1/2)+y^(1/4)T^(3/4)]), also with the logarithmic weight. The diagonal poles cancel.", "evidence": "audits/adversarial_reviews/director_pure_fourth_round13.md · One-sided continuous moments do not impose the half-power barrier", "status": "adjudicated_scoped", "claim_kind": "unconditional_asymmetric_continuous_estimate", "hypotheses": "Unconditional continuous-height integral, constant second arm and fixed microscopic shift radius. The direct asymmetric AFE proof does not estimate the discrete nonprincipal edge."}','mathematical_claim','The continuous shifted zeta product against one bounded-coefficient Dirichlet polynomial of length y≤T^theta, theta<1, has the explicit two-diagonal formula in the note with error O_epsilon(T^epsilon[(yT)^(1/2)+y^(1/4)T^(3/4)]), also with the logarithmic weight. The diagonal poles cancel.');
INSERT INTO "graph_nodes" VALUES('LEM-HLZ-SMOOTH-REFLECTED-SADDLE','graphs/knowledge_graph.jsonl',1347,'adjudicated_scoped','audits/adversarial_reviews/director_pure_fourth_round13.md · A smooth contour formulation closes the saddle error','{"record_type": "node", "id": "LEM-HLZ-SMOOTH-REFLECTED-SADDLE", "type": "mathematical_claim", "label": "A two-transition compact comparable-height cutoff of width H=T^kappa with kappa>(1+theta)/2, theta=4b, gives a reflected saddle error O(T/H²) per comparable term. The aggregated error is bounded by T^epsilon[T²y/H²+y+Ty/H]. Sharp zero-sum endpoints are recovered after differentiation with transition mass O(T^epsilon(H+Y^(2b))).", "evidence": "audits/adversarial_reviews/director_pure_fourth_round13.md · A smooth contour formulation closes the saddle error", "status": "adjudicated_scoped", "claim_kind": "conditional_smooth_saddle_and_endpoint_replacement", "hypotheses": "RH for the zero-sampling endpoint comparison, fixed microscopic shifts, theta<1 and kappa<1. The cutoff is shift-independent before differentiation. The result applies to the smooth saddle and does not recover the original hard arithmetic cutoff."}','mathematical_claim','A two-transition compact comparable-height cutoff of width H=T^kappa with kappa>(1+theta)/2, theta=4b, gives a reflected saddle error O(T/H²) per comparable term. The aggregated error is bounded by T^epsilon[T²y/H²+y+Ty/H]. Sharp zero-sum endpoints are recovered after differentiation with transition mass O(T^epsilon(H+Y^(2b))).');
INSERT INTO "graph_nodes" VALUES('LEM-HLZ-REFLECTED-EDGE-FIXED-SEQUENCE','graphs/knowledge_graph.jsonl',1348,'adjudicated_scoped','audits/adversarial_reviews/uniform99_fixed_sequence_adjudication.md · Differentiation and the original-modulus average; Reduction to the single Mangoldt convolution','{"record_type": "node", "id": "LEM-HLZ-REFLECTED-EDGE-FIXED-SEQUENCE", "type": "mathematical_claim", "label": "The three differentiated reflected shifts give A(m)+log(k/m)(log*log)(m), with A=d_2*Lambda*Lambda*Lambda. The original-modulus unit average of e(−m/k) is mu(q)/phi(q), q=k/(k,m). The divisor products decay faster than any fixed power for the smooth cutoff; the remaining edge is (1/2) E_Cstar+O_N(T^−N), where Cstar=d_2*(Lambda log²).", "evidence": "audits/adversarial_reviews/uniform99_fixed_sequence_adjudication.md · Differentiation and the original-modulus average; Reduction to the single Mangoldt convolution", "status": "adjudicated_scoped", "claim_kind": "proved_fixed_arithmetic_sequence_reduction", "hypotheses": "Compact-local smooth contour formulation, k≤y≤T^theta, H=T^kappa with kappa>(1+theta)/2, bounded outer coefficients. Divisor removal is unconditional via Poisson or Hurwitz–Mellin cancellation. Arbitrary decay applies to discarded divisor pieces; inherited contour errors keep their separate bounds."}','mathematical_claim','The three differentiated reflected shifts give A(m)+log(k/m)(log*log)(m), with A=d_2*Lambda*Lambda*Lambda. The original-modulus unit average of e(−m/k) is mu(q)/phi(q), q=k/(k,m). The divisor products decay faster than any fixed power for the smooth cutoff; the remaining edge is (1/2) E_Cstar+O_N(T^−N), where Cstar=d_2*(Lambda log²).');
INSERT INTO "graph_nodes" VALUES('OPEN-HLZ-PURE-FOURTH-CSTAR-CANCELLATION','graphs/knowledge_graph.jsonl',1349,'open_sufficient_target','audits/adversarial_reviews/uniform99_fixed_sequence_adjudication.md · Reduction to the single Mangoldt convolution','{"record_type": "node", "id": "OPEN-HLZ-PURE-FOURTH-CSTAR-CANCELLATION", "type": "mathematical_claim", "label": "The remaining sufficient target is Re E_Cstar=o(T log⁴T), with E_Cstar=∑_{k≤Y^(4b)} (c_k/k)∑_m Cstar(m) w_T(2πm/k)[e(−m/k)−mu(q)/phi(q)], q=k/(k,m), and c_k the coefficients of D⁴.", "evidence": "audits/adversarial_reviews/uniform99_fixed_sequence_adjudication.md · Reduction to the single Mangoldt convolution", "status": "open_sufficient_target", "claim_kind": "open_arithmetic_sufficient_condition", "hypotheses": "Compact comparable heights T approximately Y, fixed 1/8<b<1/6 and the same two-transition taper and principal subtraction. The target is unproved. RH and the established compact-to-strict-tail comparison would transfer a proof to the pure and real fourth moments."}','mathematical_claim','The remaining sufficient target is Re E_Cstar=o(T log⁴T), with E_Cstar=∑_{k≤Y^(4b)} (c_k/k)∑_m Cstar(m) w_T(2πm/k)[e(−m/k)−mu(q)/phi(q)], q=k/(k,m), and c_k the coefficients of D⁴.');
INSERT INTO "graph_nodes" VALUES('THM-GR1974-GRR-MODULUS','graphs/knowledge_graph.jsonl',1350,'adjudicated_scoped','audits/adversarial_reviews/release92_tightness_source_selection.md · Garsia and Rodemich; 1974 journal pp. 69–70, Theorem 1.2 and (1.2), (1.3), (1.7), (1.8)','{"record_type": "node", "id": "THM-GR1974-GRR-MODULUS", "type": "mathematical_claim", "label": "The reproduced GRR inequality bounds continuous-path increments in its power case by a constant times B^(1/p) ∫_0^h u^(−2/p)dg(u), with B the double energy in the director note.", "evidence": "audits/adversarial_reviews/release92_tightness_source_selection.md · Garsia and Rodemich; 1974 journal pp. 69–70, Theorem 1.2 and (1.2), (1.3), (1.7), (1.8)", "status": "adjudicated_scoped", "claim_kind": "targeted_primary_source_dependency", "hypotheses": "Continuous interpolation, increasing continuous gauge, finite energy, convergent scale integral. The source almost-everywhere estimate extends to a continuous path. Targeted primary passage; the 1974 article credits the three-author original."}','mathematical_claim','The reproduced GRR inequality bounds continuous-path increments in its power case by a constant times B^(1/p) ∫_0^h u^(−2/p)dg(u), with B the double energy in the director note.');
INSERT INTO "graph_nodes" VALUES('THM-BILLINGSLEY1968-C-TIGHTNESS-AND-TRIANGLE','graphs/knowledge_graph.jsonl',1351,'adjudicated_scoped','audits/adversarial_reviews/release92_tightness_source_selection.md · Billingsley; first edition Theorem 8.2 p. 55, Theorem 12.3 pp. 95–96 and §12 Problem 9 p. 103','{"record_type": "node", "id": "THM-BILLINGSLEY1968-C-TIGHTNESS-AND-TRIANGLE", "type": "mathematical_claim", "label": "Tight initial values and asymptotically small modulus probabilities characterize tightness in C. The common-clock sufficient criterion requires a time exponent greater than one; a randomly located shrinking triangle demonstrates failure at the critical exponent.", "evidence": "audits/adversarial_reviews/release92_tightness_source_selection.md · Billingsley; first edition Theorem 8.2 p. 55, Theorem 12.3 pp. 95–96 and §12 Problem 9 p. 103", "status": "adjudicated_scoped", "claim_kind": "targeted_primary_source_dependency", "hypotheses": "First-edition scanned passages only. Both the arbitrary-grid minimum envelope and its sharpness at a variable crossover are local adaptations."}','mathematical_claim','Tight initial values and asymptotically small modulus probabilities characterize tightness in C. The common-clock sufficient criterion requires a time exponent greater than one; a randomly located shrinking triangle demonstrates failure at the critical exponent.');
INSERT INTO "graph_nodes" VALUES('LEM-PETROV-ROOTED-CUE-EXACT-FACTOR-BRIDGE','graphs/knowledge_graph.jsonl',1352,'adjudicated_scoped','audits/adversarial_reviews/director_petrov_round13.md · Applicable source theorem and exact matching','{"record_type": "node", "id": "LEM-PETROV-ROOTED-CUE-EXACT-FACTOR-BRIDGE", "type": "mathematical_claim", "label": "Petrov v1 Theorem 4.4, ordinary BOGC and finite Jacobi give det(U* A_n^−1 U)=(det Gamma/det Gamma(0)) L_obl/L_n for the rooted CUE cosine symbol. On the real Laplace axis both exact Gram and oblique tail determinants are strictly positive at every fixed N,z.", "evidence": "audits/adversarial_reviews/director_petrov_round13.md · Applicable source theorem and exact matching", "status": "adjudicated_scoped", "claim_kind": "intrinsic_exact_source_theorem_transfer", "hypotheses": "Fixed integers N≥2 and J≥1, analytic polynomial tilts X=T((1−w)^J) on N−1 free modes and exponential finite Laurent symbol. The source theorem requires its Gram to be invertible; real z gives the adjoint structure. The optional fixed-tail chart requires separate invertibility."}','mathematical_claim','Petrov v1 Theorem 4.4, ordinary BOGC and finite Jacobi give det(U* A_n^−1 U)=(det Gamma/det Gamma(0)) L_obl/L_n for the rooted CUE cosine symbol. On the real Laplace axis both exact Gram and oblique tail determinants are strictly positive at every fixed N,z.');
INSERT INTO "graph_nodes" VALUES('OBS-PETROV-ROOTED-CUE-GRAM-QUADRATIC-MISMATCH','graphs/knowledge_graph.jsonl',1353,'adjudicated_scoped','audits/adversarial_reviews/director_petrov_round13.md · The tail contributes already at order two; Exact finite witness and optional chart','{"record_type": "node", "id": "OBS-PETROV-ROOTED-CUE-GRAM-QUADRATIC-MISMATCH", "type": "mathematical_claim", "label": "The tilted tail contributes −kappa_(J,N) z² with kappa_(J,N)=Σ_(j<J)||H(F_+)*U_j||²>0. If 2 max(band)≤n and the band is nonempty, the normalized Gram already differs from the complementary determinant at order two. For N=4,J=2,k=2 the gap is 9/160; the optional chart determinant changes sign between z=0 and 8 while the exact factors remain positive.", "evidence": "audits/adversarial_reviews/director_petrov_round13.md · The tail contributes already at order two; Exact finite witness and optional chart", "status": "adjudicated_scoped", "claim_kind": "intrinsic_quadratic_nonidentification_and_chart_witness", "hypotheses": "Same fixed-rank cosine model. The ordinary ambient tail is stable in the stated coefficient window. For fixed 0<a<b≤1/2 the quadratic gap has the positive Riemann-sum limit in the note. The chart obstruction is separate from the zero of the extrapolated formal moment polynomial."}','mathematical_claim','The tilted tail contributes −kappa_(J,N) z² with kappa_(J,N)=Σ_(j<J)||H(F_+)*U_j||²>0. If 2 max(band)≤n and the band is nonempty, the normalized Gram already differs from the complementary determinant at order two. For N=4,J=2,k=2 the gap is 9/160; the optional chart determinant changes sign between z=0 and 8 while the exact factors remain positive.');
INSERT INTO "graph_nodes" VALUES('THM-ROOTED-CUE-HANKEL-WITNESS-DEGREE-BOUND','graphs/knowledge_graph.jsonl',1354,'adjudicated_scoped','audits/adversarial_reviews/director_quantitative_rmt_round14.md · A quantitative finite witness for every fixed rank','{"record_type": "node", "id": "THM-ROOTED-CUE-HANKEL-WITNESS-DEGREE-BOUND", "type": "mathematical_claim", "label": "For the formal fixed-rank cosine series M and a real zero 0<t_*≤1/d, let R=2/d and B≥1 majorize |M| on |z|=R. With L=ceil(log_2(8B(B+1))), the two degree-L Taylor polynomials of exp(±t_*x/2) give a strictly negative two-by-two moment determinant. The order-L Hankel form is therefore not positive semidefinite, using moments through degree 2L. A sufficient explicit majorant is B=J! D^J exp((J−1)HR+HR²/4), D=(2J−1)16^(2J−2)(2J−1)! exp(1+R d exp(b)).", "evidence": "audits/adversarial_reviews/director_quantitative_rmt_round14.md · A quantitative finite witness for every fixed rank", "status": "adjudicated_scoped", "claim_kind": "intrinsic_quantitative_formal_positivity_obstruction", "hypotheses": "Fixed positive integer rank J and 0<a<b<1, H=log(b/a), d=b−a. The form is for the extrapolated cosine series. The bound is sufficient, not generally the least witness order."}','mathematical_claim','For the formal fixed-rank cosine series M and a real zero 0<t_*≤1/d, let R=2/d and B≥1 majorize |M| on |z|=R. With L=ceil(log_2(8B(B+1))), the two degree-L Taylor polynomials of exp(±t_*x/2) give a strictly negative two-by-two moment determinant. The order-L Hankel form is therefore not positive semidefinite, using moments through degree 2L. A sufficient explicit majorant is B=J! D^J exp((J−1)HR+HR²/4), D=(2J−1)16^(2J−2)(2J−1)! exp(1+R d exp(b)).');
INSERT INTO "graph_nodes" VALUES('THM-ROOTED-CUE-RANK-ONE-HERMITE-WITNESS','graphs/knowledge_graph.jsonl',1355,'adjudicated_scoped','audits/adversarial_reviews/director_quantitative_rmt_round14.md · At rank one the least order is known exactly','{"record_type": "node", "id": "THM-ROOTED-CUE-RANK-ONE-HERMITE-WITNESS", "type": "mathematical_claim", "label": "At rank one set σ²=H/2. The order-L formal Hankel form is congruent to I−(d/σ²)T_L, with Hermite Jacobi edges σ sqrt(k), 1≤k≤L. A negative witness exists exactly when the largest zero of He_(L+1) strictly exceeds σ/d. Equality gives singular positive semidefiniteness. The least order lies above σ²/(4d²) and at most floor(σ²/d²)+1; it is σ²/(4d²)+O(σ/d) as σ/d→infinity.", "evidence": "audits/adversarial_reviews/director_quantitative_rmt_round14.md · At rank one the least order is known exactly", "status": "adjudicated_scoped", "claim_kind": "intrinsic_exact_rank_one_formal_witness_degree", "hypotheses": "Fixed positive band at rank one, with the formal Gaussian density modifier 1−d x/σ². He denotes the probabilists'' Hermite polynomial. The asymptotic concerns small d/σ, and the criterion does not test the true law outside the supported moment window."}','mathematical_claim','At rank one set σ²=H/2. The order-L formal Hankel form is congruent to I−(d/σ²)T_L, with Hermite Jacobi edges σ sqrt(k), 1≤k≤L. A negative witness exists exactly when the largest zero of He_(L+1) strictly exceeds σ/d. Equality gives singular positive semidefiniteness. The least order lies above σ²/(4d²) and at most floor(σ²/d²)+1; it is σ²/(4d²)+O(σ/d) as σ/d→infinity.');
INSERT INTO "graph_nodes" VALUES('CERT-ROOTED-CUE-RANK-ONE-HANKEL-FIXTURES','graphs/knowledge_graph.jsonl',1356,'adjudicated_scoped','audits/adversarial_reviews/director_quantitative_rmt_round14.md · At rank one the least order is known exactly','{"record_type": "node", "id": "CERT-ROOTED-CUE-RANK-ONE-HANKEL-FIXTURES", "type": "mathematical_claim", "label": "For the standardized series exp(z²/2)(1−z/2), all principal minors through Hankel order two are nonnegative and q(x)=2x³+9x²+6x−3 has formal square expectation −30. At standardized tilt 1/sqrt(3), after rescaling y=sqrt(3)x, the order-two form is singular positive semidefinite, y²+3y is null, and y³+4y²+12y has square expectation −27.", "evidence": "audits/adversarial_reviews/director_quantitative_rmt_round14.md · At rank one the least order is known exactly", "status": "adjudicated_scoped", "claim_kind": "exact_rank_one_hankel_certificate", "hypotheses": "Exact rational formal-moment fixtures with director replay. They check the strict Hermite threshold and are separate from the general degree proof."}','mathematical_claim','For the standardized series exp(z²/2)(1−z/2), all principal minors through Hankel order two are nonnegative and q(x)=2x³+9x²+6x−3 has formal square expectation −30. At standardized tilt 1/sqrt(3), after rescaling y=sqrt(3)x, the order-two form is singular positive semidefinite, y²+3y is null, and y³+4y²+12y has square expectation −27.');
INSERT INTO "graph_nodes" VALUES('LEM-PETROV-ROOTED-CUE-FINITE-SCHUR-TAIL','graphs/knowledge_graph.jsonl',1357,'adjudicated_scoped','audits/adversarial_reviews/director_quantitative_rmt_round14.md · The exact Petrov tail quotient has a positive finite representation','{"record_type": "node", "id": "LEM-PETROV-ROOTED-CUE-FINITE-SCHUR-TAIL", "type": "mathematical_claim", "label": "With L=P_nT(φ_+)|P_n, M=U*L^(−*)L^(−1)U and A_n=P_nT(φ)|P_n, the tilted-to-ambient Fredholm ratio is det S, S=M^(−1/2)(U*A_n^(−1)U)M^(−1/2), and det Γ(z)/det Γ(0)=det M. For real z the ratio is in [exp(−H_N z²/4),1]; det M and det(U*A_n^(−1)U) lie in [exp(−J|z|H_N),exp(J|z|H_N)]. The mass-removed complementary determinant has liminf at least exp(−2JH z_*) at any positive formal zero z_*.", "evidence": "audits/adversarial_reviews/director_quantitative_rmt_round14.md · The exact Petrov tail quotient has a positive finite representation", "status": "adjudicated_scoped", "claim_kind": "intrinsic_exact_real_tail_quotient_and_nonvanishing", "hypotheses": "Fixed N≥2 and deleted rank J≥1, n=N+J−1, global rooted cosine CUE model, real z, fixed positive band for uniformity in N. No invertibility of Petrov''s optional fixed-tail chart is needed."}','mathematical_claim','With L=P_nT(φ_+)|P_n, M=U*L^(−*)L^(−1)U and A_n=P_nT(φ)|P_n, the tilted-to-ambient Fredholm ratio is det S, S=M^(−1/2)(U*A_n^(−1)U)M^(−1/2), and det Γ(z)/det Γ(0)=det M. For real z the ratio is in [exp(−H_N z²/4),1]; det M and det(U*A_n^(−1)U) lie in [exp(−J|z|H_N),exp(J|z|H_N)]. The mass-removed complementary determinant has liminf at least exp(−2JH z_*) at any positive formal zero z_*.');
INSERT INTO "graph_nodes" VALUES('THM-PETROV-ROOTED-CUE-TRUE-CUTOFF-CONTINUUM-GRAM','graphs/knowledge_graph.jsonl',1358,'adjudicated_scoped','audits/adversarial_reviews/director_quantitative_rmt_round14.md · A true-cutoff continuum Gram and a factorial approximation','{"record_type": "node", "id": "THM-PETROV-ROOTED-CUE-TRUE-CUTOFF-CONTINUUM-GRAM", "type": "mathematical_claim", "label": "For real z≥0, e^(−H_N z)M_ij converges to E[1_(max(p,q)≤1) ∫_(max(p,q))^1 u_i(t−p)u_j(t−q)dt], with independent compound-Poisson shift totals p,q of intensity z dx/(2x) on [a,b] and shifted orthonormal Legendre profiles u_j. For p,q≤1 its kernel differs from the transposed oriented formal kernel by an ordinary lower interval of length min(p,q).", "evidence": "audits/adversarial_reviews/director_quantitative_rmt_round14.md · A true-cutoff continuum Gram and a factorial approximation", "status": "adjudicated_scoped", "claim_kind": "intrinsic_true_cutoff_continuum_limit", "hypotheses": "Fixed rank and 0<a<b<1. Exact Gram limit with the finite convolution cutoff. Pure-sign agreement is within the coefficient window; the formal extrapolation can use unsupported shifts."}','mathematical_claim','For real z≥0, e^(−H_N z)M_ij converges to E[1_(max(p,q)≤1) ∫_(max(p,q))^1 u_i(t−p)u_j(t−q)dt], with independent compound-Poisson shift totals p,q of intensity z dx/(2x) on [a,b] and shifted orthonormal Legendre profiles u_j. For p,q≤1 its kernel differs from the transposed oriented formal kernel by an ordinary lower interval of length min(p,q).');
INSERT INTO "graph_nodes" VALUES('LEM-PETROV-ROOTED-CUE-FACTORIAL-HANKEL-TRUNCATION','graphs/knowledge_graph.jsonl',1359,'adjudicated_scoped','audits/adversarial_reviews/director_quantitative_rmt_round14.md · A true-cutoff continuum Gram and a factorial approximation','{"record_type": "node", "id": "LEM-PETROV-ROOTED-CUE-FACTORIAL-HANKEL-TRUNCATION", "type": "mathematical_claim", "label": "For h=H(φ_−/φ_+), the Hilbert–Schmidt error after cutting both indices at M_cut≥n is at most |z|sqrt(H_N/2) times ∑_(s≥floor(M_cut/k_*)) (|z|H_N)^s/s!, where k_* is the maximum band index. Schatten Hölder bounds the induced trace-norm K error, and the log-determinant quotient error is at most twice that error divided by exp(−2|z|H_N).", "evidence": "audits/adversarial_reviews/director_quantitative_rmt_round14.md · A true-cutoff continuum Gram and a factorial approximation", "status": "adjudicated_scoped", "claim_kind": "intrinsic_uniform_finite_tail_approximation", "hypotheses": "Fixed positive band, fixed deleted rank, real z in a compact interval. A nonempty finite band is required for k_*; an empty band has K=0 and both tails equal one."}','mathematical_claim','For h=H(φ_−/φ_+), the Hilbert–Schmidt error after cutting both indices at M_cut≥n is at most |z|sqrt(H_N/2) times ∑_(s≥floor(M_cut/k_*)) (|z|H_N)^s/s!, where k_* is the maximum band index. Schatten Hölder bounds the induced trace-norm K error, and the log-determinant quotient error is at most twice that error divided by exp(−2|z|H_N).');
INSERT INTO "graph_nodes" VALUES('LEM-CSTAR-EFFECTIVE-MODULUS-AND-SHORT-FACTOR','graphs/knowledge_graph.jsonl',1360,'adjudicated_scoped','audits/adversarial_reviews/director_arithmetic_strata_round14.md · Exact effective modulus and removal of several strata','{"record_type": "node", "id": "LEM-CSTAR-EFFECTIVE-MODULUS-AND-SHORT-FACTOR", "type": "mathematical_claim", "label": "For fixed Mangoldt factor ν, put g=(k,ν), q=k/g, M=kT/ν and δ=H/T. The centered divisor twist reduces exactly to a unit numerator at q and vanishes when q=1. It is bounded by O_B(M log(2+M)(1+Hg/√(kTν))^(−B)) and O_B(q δ^(−2)(q²/(Mδ²))^B). Thus ν/g²≤(H²/(kT))T^(−δ_0) can be discarded with arbitrary fixed-power savings for a fixed positive margin δ_0.", "evidence": "audits/adversarial_reviews/director_arithmetic_strata_round14.md · Exact effective modulus and removal of several strata", "status": "adjudicated_scoped", "claim_kind": "unconditional_centered_divisor_transform_and_short_factor", "hypotheses": "Compact comparable-height cutoff with derivative bounds, T≈Y, k≤Y^θ, H=T^κ and fixed κ>(1+θ)/2 for the short-factor claim. The weak pointwise loss O_ε(qT^ε) requires choosing κ close to one and then a small positive B. The divisor argument n need not be coprime to q."}','mathematical_claim','For fixed Mangoldt factor ν, put g=(k,ν), q=k/g, M=kT/ν and δ=H/T. The centered divisor twist reduces exactly to a unit numerator at q and vanishes when q=1. It is bounded by O_B(M log(2+M)(1+Hg/√(kTν))^(−B)) and O_B(q δ^(−2)(q²/(Mδ²))^B). Thus ν/g²≤(H²/(kT))T^(−δ_0) can be discarded with arbitrary fixed-power savings for a fixed positive margin δ_0.');
INSERT INTO "graph_nodes" VALUES('LEM-CSTAR-SHARED-FACTORS-AND-HIGHER-POWERS','graphs/knowledge_graph.jsonl',1361,'adjudicated_scoped','audits/adversarial_reviews/director_arithmetic_strata_round14.md · Exact effective modulus and removal of several strata','{"record_type": "node", "id": "LEM-CSTAR-SHARED-FACTORS-AND-HIGHER-POWERS", "type": "mathematical_claim", "label": "All supported prime powers sharing a prime with the modulus contribute o(T). All powers p^j with j≥3 contribute O(Y^θ T^(1/3+ε) log^C T), hence o(T) for θ<2/3 with fixed power margin and sufficiently small ε.", "evidence": "audits/adversarial_reviews/director_arithmetic_strata_round14.md · Exact effective modulus and removal of several strata", "status": "adjudicated_scoped", "claim_kind": "unconditional_partial_prime_power_elimination", "hypotheses": "The fixed d₂*(Λ log²) smooth signed sum, four-prime-supported bounded outer coefficients c_k, T≈Y, fixed 0<a<b, θ=4b∈(1/2,2/3). The taper exponent is chosen sufficiently near one. This is an unconditional estimate for these arithmetic strata."}','mathematical_claim','All supported prime powers sharing a prime with the modulus contribute o(T). All powers p^j with j≥3 contribute O(Y^θ T^(1/3+ε) log^C T), hence o(T) for θ<2/3 with fixed power margin and sufficiently small ε.');
INSERT INTO "graph_nodes" VALUES('LEM-CSTAR-ALL-PRIME-SQUARES-BELOW-9-17','graphs/knowledge_graph.jsonl',1362,'adjudicated_scoped','audits/adversarial_reviews/director_arithmetic_strata_round14.md · Ghosh''s primary quadratic estimate removes every square in a strict range','{"record_type": "node", "id": "LEM-CSTAR-ALL-PRIME-SQUARES-BELOW-9-17", "type": "mathematical_claim", "label": "At k≈K and square base p≈X the reduced quadratic numerator estimate, weighted over gcd classes, costs O(T^ε(KT/X)[K^(−1/4)+X^(−1/8)+K^(1/4)X^(−1/2)]). Combined with small-X pointwise control it gives a power saving for all square factors when 1/2<θ<9/17, equivalently 1/8<b<9/68.", "evidence": "audits/adversarial_reviews/director_arithmetic_strata_round14.md · Ghosh''s primary quadratic estimate removes every square in a strict range", "status": "adjudicated_scoped", "claim_kind": "unconditional_all_square_stratum_power_saving", "hypotheses": "Same compact signed sum and bounded four-prime coefficients. Ghosh''s thesis Theorem 2 on exact reduced rational phases, two monotone taper transitions and fixed strict power margins. The endpoint and the genuine-prime stratum are outside this estimate."}','mathematical_claim','At k≈K and square base p≈X the reduced quadratic numerator estimate, weighted over gcd classes, costs O(T^ε(KT/X)[K^(−1/4)+X^(−1/8)+K^(1/4)X^(−1/2)]). Combined with small-X pointwise control it gives a power saving for all square factors when 1/2<θ<9/17, equivalently 1/8<b<9/68.');
INSERT INTO "graph_nodes" VALUES('LEM-CSTAR-GCD-RESOLVED-INVERSE-PRIME-WINDOWS','graphs/knowledge_graph.jsonl',1363,'adjudicated_scoped','audits/adversarial_reviews/director_arithmetic_strata_round14.md · Divisor Voronoi and averaged inverse-prime bounds','{"record_type": "node", "id": "LEM-CSTAR-GCD-RESOLVED-INVERSE-PRIME-WINDOWS", "type": "mathematical_claim", "label": "For K≈T^θ and P≈T^ξ, the coprime genuine-prime block saves a power in either open region: Baker θ/2<ξ<θ, (11/10)θ+(4/5)ξ<1 and θ+(11/12)ξ<1; Fouvry–Shparlinski 0<ξ<(3/2)θ, (13/10)θ+(3/5)ξ<1 and (13/12)θ+(5/6)ξ<1. Centered divisor Voronoi and a uniform O(T^ε δ^(−5/2)) cumulative kernel-and-first-derivative envelope permit full dual gcd resolution.", "evidence": "audits/adversarial_reviews/director_arithmetic_strata_round14.md · Divisor Voronoi and averaged inverse-prime bounds", "status": "adjudicated_scoped", "claim_kind": "unconditional_gcd_resolved_inverse_prime_savings", "hypotheses": "1/2<θ<2/3 on the stated dyadic scales. Use averages at common prime endpoints and reduce each nonunit dual index to modulus k/gcd(k,l). No least-prime-factor restriction on these gcd estimates. Choose the taper exponent sufficiently near one on compact subsets of the strict regions. The longer-prime scales remain outside them."}','mathematical_claim','For K≈T^θ and P≈T^ξ, the coprime genuine-prime block saves a power in either open region: Baker θ/2<ξ<θ, (11/10)θ+(4/5)ξ<1 and θ+(11/12)ξ<1; Fouvry–Shparlinski 0<ξ<(3/2)θ, (13/10)θ+(3/5)ξ<1 and (13/12)θ+(5/6)ξ<1. Centered divisor Voronoi and a uniform O(T^ε δ^(−5/2)) cumulative kernel-and-first-derivative envelope permit full dual gcd resolution.');
INSERT INTO "graph_nodes" VALUES('LEM-CSTAR-KOROLEV-POINTWISE-INVERSE-PRIME-BAND','graphs/knowledge_graph.jsonl',1364,'adjudicated_scoped','audits/adversarial_reviews/director_arithmetic_strata_round14.md · An alternate inverse-prime input and an excluded shortcut','{"record_type": "node", "id": "LEM-CSTAR-KOROLEV-POINTWISE-INVERSE-PRIME-BAND", "type": "mathematical_claim", "label": "The 2018 homogeneous Korolev unit-numerator prefix estimate and common short dual truncation give a power saving near P=T^(1−θ) on K≈T^θ for 1/2<θ<10/17; the principal inverse-prime exponent at the center is (64+17θ)/74 before the small taper and interval losses.", "evidence": "audits/adversarial_reviews/director_arithmetic_strata_round14.md · An alternate inverse-prime input and an excluded shortcut", "status": "adjudicated_scoped", "claim_kind": "unconditional_alternate_local_inverse_prime_saving", "hypotheses": "Original homogeneous theorem range q^(7/10+ε)≤X≤q, fixed strict margins, supported modulus primes above Y^a and common dual truncation below Y^a. Prime partial summation adds one vertical factor and changes the cutoff cost to δ^(−3−2B). The later inhomogeneous theorem with two unit coefficients is a different result."}','mathematical_claim','The 2018 homogeneous Korolev unit-numerator prefix estimate and common short dual truncation give a power saving near P=T^(1−θ) on K≈T^θ for 1/2<θ<10/17; the principal inverse-prime exponent at the center is (64+17θ)/74 before the small taper and interval losses.');
INSERT INTO "graph_nodes" VALUES('OBS-CSTAR-CHARACTER-TWIST-ZERO-RESIDUES','graphs/knowledge_graph.jsonl',1365,'adjudicated_scoped','audits/adversarial_reviews/director_arithmetic_strata_round14.md · An alternate inverse-prime input and an excluded shortcut','{"record_type": "node", "id": "OBS-CSTAR-CHARACTER-TWIST-ZERO-RESIDUES", "type": "mathematical_claim", "label": "The character twist of d₂*(Λ log²) is L(s,χ)²(−L''/L)'''' in absolute convergence. At a simple zero ρ it has residue −2L''(ρ,χ)²; at a zero of order at least two there is no pole. Hence a contour move treating the full twist as an ordinary divisor/Eisenstein twist would omit these zero residues.", "evidence": "audits/adversarial_reviews/director_arithmetic_strata_round14.md · An alternate inverse-prime input and an excluded shortcut", "status": "adjudicated_scoped", "claim_kind": "meromorphic_obstruction_to_full_sequence_divisor_transform", "hypotheses": "Ordinary Dirichlet characters with their Euler factors. The statement concerns the indicated meromorphic continuation and poles at zeros, not a bound on their residue sum. Freezing the prime factor gives a different, valid divisor transform. No Dirichlet GRH is assumed."}','mathematical_claim','The character twist of d₂*(Λ log²) is L(s,χ)²(−L''/L)'''' in absolute convergence. At a simple zero ρ it has residue −2L''(ρ,χ)²; at a zero of order at least two there is no pole. Hence a contour move treating the full twist as an ordinary divisor/Eisenstein twist would omit these zero residues.');
INSERT INTO "graph_nodes" VALUES('OBS-BL-RAW-HEIGHT-SMOOTH-COUNTEREXAMPLE','graphs/knowledge_graph.jsonl',1366,'adjudicated_scoped','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A fixed smooth witness for which the stated height limit fails','{"record_type": "node", "id": "OBS-BL-RAW-HEIGHT-SMOOTH-COUNTEREXAMPLE", "type": "mathematical_claim", "label": "There exists a fixed smooth real f satisfying the pinned manuscript''s literal endpoint and local hypotheses whose zero sum fails under symmetric raw-height cutoffs. Disjoint log-coordinate bumps with amplitudes a_j=exp(−(1/2+δ)j), b_j=exp(−(1+δ)j), and separated high-frequency carriers produce symmetric height increments exceeding 2j/5. The arithmetic side has ordinary absolute convergence.", "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A fixed smooth witness for which the stated height limit fails", "status": "adjudicated_scoped", "claim_kind": "intrinsic_smooth_raw_height_counterexample", "hypotheses": "Nontrivial zeta zeros with multiplicity, actual unaveraged cutoffs |Im ρ|≤T, and the auxiliary formula on pinned manuscript pp. 5–6. Uses the unconditional zero count in populated high cells. The compact jump tests in the main theorem have a separate justification."}','mathematical_claim','There exists a fixed smooth real f satisfying the pinned manuscript''s literal endpoint and local hypotheses whose zero sum fails under symmetric raw-height cutoffs. Disjoint log-coordinate bumps with amplitudes a_j=exp(−(1/2+δ)j), b_j=exp(−(1+δ)j), and separated high-frequency carriers produce symmetric height increments exceeding 2j/5. The arithmetic side has ordinary absolute convergence.');
INSERT INTO "graph_nodes" VALUES('THM-MELLIN-STRIP-SOBOLEV-ZERO-TRACE','graphs/knowledge_graph.jsonl',1367,'adjudicated_scoped','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A sufficient strip-Sobolev condition','{"record_type": "node", "id": "THM-MELLIN-STRIP-SOBOLEV-ZERO-TRACE", "type": "mathematical_claim", "label": "For h(s)=∫₀∞ f(x)x^(s−1)dx and N_s² the strip area integral of |h(β+it)|²(1+t²)^s, the zero trace is absolutely summable. With r=min(ε/2,1/4), its ℓ¹ bound is C_N/(√π r) times [2·5^s Σ_n log²(2+|n|)/(1+n²)^s]^(1/2) N_s. Restricting the series to |n|>T−1 gives tail O(N_s T^(1/2−s) log(2+T)). The compensated explicit formula follows by compact smooth approximation, with automatic central trace control.", "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A sufficient strip-Sobolev condition", "status": "adjudicated_scoped", "claim_kind": "sufficient_absolute_zero_trace_and_explicit_formula", "hypotheses": "Continuous f with the original endpoint value bounds at margin δ>0, 0<ε<δ, finite norm on β∈[−ε,1+ε], s>1/2. C_N bounds the number of zeta zeros with n≤Im ρ<n+1 by C_N log(2+|n|), including multiplicities."}','mathematical_claim','For h(s)=∫₀∞ f(x)x^(s−1)dx and N_s² the strip area integral of |h(β+it)|²(1+t²)^s, the zero trace is absolutely summable. With r=min(ε/2,1/4), its ℓ¹ bound is C_N/(√π r) times [2·5^s Σ_n log²(2+|n|)/(1+n²)^s]^(1/2) N_s. Restricting the series to |n|>T−1 gives tail O(N_s T^(1/2−s) log(2+T)). The compensated explicit formula follows by compact smooth approximation, with automatic central trace control.');
INSERT INTO "graph_nodes" VALUES('THM-MELLIN-CRITICAL-LOG-ZERO-TRACE','graphs/knowledge_graph.jsonl',1368,'adjudicated_scoped','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A weaker critical logarithmic class','{"record_type": "node", "id": "THM-MELLIN-CRITICAL-LOG-ZERO-TRACE", "type": "mathematical_claim", "label": "Replacing the strip weight by w_p(t)=√(1+t²) log^p(e+|t|) gives an absolute zero trace, with tail O(N_log,p [log(2+T)]^((3−p)/2)). Fourier inversion on the central line gives the Dini modulus O(N_log,p [log(e/|u|)]^((1−p)/2)) near u=0. Approximation establishes the same compensated explicit formula.", "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A weaker critical logarithmic class", "status": "adjudicated_scoped", "claim_kind": "sufficient_critical_logarithmic_zero_trace_and_explicit_formula", "hypotheses": "Continuous f with the original endpoint value bounds, strip margin 0<ε<δ, and finite area norm with p>3. The endpoint claim separately addresses failure of universal absolute sampling at p=3."}','mathematical_claim','Replacing the strip weight by w_p(t)=√(1+t²) log^p(e+|t|) gives an absolute zero trace, with tail O(N_log,p [log(2+T)]^((3−p)/2)). Fourier inversion on the central line gives the Dini modulus O(N_log,p [log(e/|u|)]^((1−p)/2)) near u=0. Approximation establishes the same compensated explicit formula.');
INSERT INTO "graph_nodes" VALUES('OBS-MELLIN-CRITICAL-LOG-SMOOTH-STRICT-INCLUSION','graphs/knowledge_graph.jsonl',1369,'adjudicated_scoped','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A weaker critical logarithmic class','{"record_type": "node", "id": "OBS-MELLIN-CRITICAL-LOG-SMOOTH-STRICT-INCLUSION", "type": "mathematical_claim", "label": "For each p>3 a smooth real example lies in the critical-log strip class and in none of the polynomial strip classes with s>1/2. Use disjoint log bumps at j, carrier Γ_j=2^(j²), and amplitudes Γ_j^(−1/2) log^(−p/2)(e+Γ_j) j^(−2)e^(−2j) in x^(−1/2) times the log-coordinate series. Uniform carrier lower bounds give divergence of every heavier polynomial norm.", "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A weaker critical logarithmic class", "status": "adjudicated_scoped", "claim_kind": "smooth_strict_inclusion_of_mellin_trace_classes", "hypotheses": "Fixed ε=1/4 and fixed nonnegative smooth compact bump. The value is O(x^(−2)) as x→∞ and vanishes for x near zero. This example concerns strict class inclusion and has absolute zero trace."}','mathematical_claim','For each p>3 a smooth real example lies in the critical-log strip class and in none of the polynomial strip classes with s>1/2. Use disjoint log bumps at j, carrier Γ_j=2^(j²), and amplitudes Γ_j^(−1/2) log^(−p/2)(e+Γ_j) j^(−2)e^(−2j) in x^(−1/2) times the log-coordinate series. Uniform carrier lower bounds give divergence of every heavier polynomial norm.');
INSERT INTO "graph_nodes" VALUES('LEM-BL-FINITE-CUTOFF-COMPENSATOR','graphs/knowledge_graph.jsonl',1370,'adjudicated_scoped','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A separate finite-cutoff identity and why the main theorem survives','{"record_type": "node", "id": "LEM-BL-FINITE-CUTOFF-COMPENSATOR", "type": "mathematical_claim", "label": "In pinned manuscript p. 8 equation (3.5), the finite-cutoff equality requires the additive gamma-compensator term n∫_(1/ε)^∞ dx/[x(x²−1)] = −(n/2)log(1−ε²). For n=1 and ε=2/3 the missing positive term is (1/2)log(9/5). The term tends to zero at O_n(ε²), and the compact jump formula with midpoint values gives the main limiting identity.", "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md · A separate finite-cutoff identity and why the main theorem survives", "status": "adjudicated_scoped", "claim_kind": "exact_finite_cutoff_correction", "hypotheses": "Exact finite equality in the pinned author manuscript, with the manuscript''s jump convention. The witness cutoff 3/2 avoids prime powers. This calculation concerns the finite formula and its true limit."}','mathematical_claim','In pinned manuscript p. 8 equation (3.5), the finite-cutoff equality requires the additive gamma-compensator term n∫_(1/ε)^∞ dx/[x(x²−1)] = −(n/2)log(1−ε²). For n=1 and ε=2/3 the missing positive term is (1/2)log(9/5). The term tends to zero at O_n(ε²), and the compact jump formula with midpoint values gives the main limiting identity.');
INSERT INTO "graph_nodes" VALUES('OBS-CSTAR-LONG-PRIME-PROGRESSION-NORM-COUNTERMODEL','graphs/knowledge_graph.jsonl',1371,'adjudicated_scoped','audits/adversarial_reviews/director_long_prime_round15.md · An exact limitation of two progression norms','{"record_type": "node", "id": "OBS-CSTAR-LONG-PRIME-PROGRESSION-NORM-COUNTERMODEL", "type": "mathematical_claim", "label": "On true supported squarefree four-prime moduli k≈K at P=KT, a nonnegative centered row model satisfies Σ_k max_u|E_(k,u)|≪√(PS) and Σ_(k,u)* |E_(k,u)|²≈PK, where S≈K/log⁴T. Its h=1 real projection with coefficients a_k/k is (12+o(1))√(PS), exceeding T log⁴T by a divergent factor. The common-divisor CRT marginals differ at 1 for two moduli gv₁ and gv₂, excluding a single common unit-supported sequence.", "evidence": "audits/adversarial_reviews/director_long_prime_round15.md · An exact limitation of two progression norms", "status": "adjudicated_scoped", "claim_kind": "abstract_phase_blind_norm_countermodel", "hypotheses": "Fixed 1/8<b<1/6, K≈Y^(4b), T≈Y, and all four distinct factors in one fixed near-top multiplicative prime band. This is an abstract implication countermodel; it gives no lower bound for genuine primes."}','mathematical_claim','On true supported squarefree four-prime moduli k≈K at P=KT, a nonnegative centered row model satisfies Σ_k max_u|E_(k,u)|≪√(PS) and Σ_(k,u)* |E_(k,u)|²≈PK, where S≈K/log⁴T. Its h=1 real projection with coefficients a_k/k is (12+o(1))√(PS), exceeding T log⁴T by a divergent factor. The common-divisor CRT marginals differ at 1 for two moduli gv₁ and gv₂, excluding a single common unit-supported sequence.');
INSERT INTO "graph_nodes" VALUES('OPEN-CSTAR-LONG-PRIME-MOVING-PHASE-SQUARE','graphs/knowledge_graph.jsonl',1372,'open_sufficient_target','audits/adversarial_reviews/director_long_prime_round15.md · The exact prime form','{"record_type": "node", "id": "OPEN-CSTAR-LONG-PRIME-MOVING-PHASE-SQUARE", "type": "mathematical_claim", "label": "A sufficient open target on each residual block is Σ_(k≈K,h≈D)|Σ_(p≈P,(p,k)=1)(log p)³p^(−it)[e(−hp/k)−μ(q)/φ(q)]|²≪T^(2−η)K/D with q=k/(h,k), uniformly for |t|≤T^ε and some fixed η>0. Cauchy–Schwarz costs O(T^ε√(D/K)) and the Mellin integral costs O(T^(1−κ)).", "evidence": "audits/adversarial_reviews/director_long_prime_round15.md · The exact prime form", "status": "open_sufficient_target", "claim_kind": "open_sufficient_moving_phase_target", "hypotheses": "T≈Y, DP≈KT, a_k≤24, cutoff H=T^κ with κ sufficiently near one, and 1−κ+ε<η/2 with strict margin. The k-sum may be restricted to actual modulus support. All divisor gcds are retained. No square estimate on genuine primes is claimed."}','mathematical_claim','A sufficient open target on each residual block is Σ_(k≈K,h≈D)|Σ_(p≈P,(p,k)=1)(log p)³p^(−it)[e(−hp/k)−μ(q)/φ(q)]|²≪T^(2−η)K/D with q=k/(h,k), uniformly for |t|≤T^ε and some fixed η>0. Cauchy–Schwarz costs O(T^ε√(D/K)) and the Mellin integral costs O(T^(1−κ)).');
INSERT INTO "graph_nodes" VALUES('THM-PRIME-PRODUCT-EXACT-PADDED-FACTORABILITY','graphs/knowledge_graph.jsonl',1373,'adjudicated_scoped','audits/adversarial_reviews/director_long_prime_round15.md · Exact padded factorability','{"record_type": "node", "id": "THM-PRIME-PRODUCT-EXACT-PADDED-FACTORABILITY", "type": "mathematical_claim", "label": "For the full ordered m-prime coefficient c_m/m! from a finite nonempty set with largest prime p_*, the exact r-way 1-bounded well-factorable level is p_*^(m+r−1). Completely multiplicative |g|≤1 preserves sufficiency and preserves necessity if g(p_*)≠0. For m=4,r=3 the padded Y^(6b) level fits Pascadi''s longest-block fixed-residue exponent 5/8 with a strict margin when b<5/28.", "evidence": "audits/adversarial_reviews/director_long_prime_round15.md · Exact padded factorability", "status": "adjudicated_scoped", "claim_kind": "intrinsic_exact_padded_factorability", "hypotheses": "Integers m,r≥1, and every prescribed real split Q=∏Q_i with Q_i≥1. The sequence is untruncated. The comparison to Pascadi uses x≈Y^(1+4b) and fixed nonzero residue; no sharp-shell factorability or varying-residue conclusion follows."}','mathematical_claim','For the full ordered m-prime coefficient c_m/m! from a finite nonempty set with largest prime p_*, the exact r-way 1-bounded well-factorable level is p_*^(m+r−1). Completely multiplicative |g|≤1 preserves sufficiency and preserves necessity if g(p_*)≠0. For m=4,r=3 the padded Y^(6b) level fits Pascadi''s longest-block fixed-residue exponent 5/8 with a strict margin when b<5/28.');
INSERT INTO "graph_nodes" VALUES('LEM-GONEK-EXPLICIT-ABEL-PRIME-SUBSTITUTION','graphs/knowledge_graph.jsonl',1374,'adjudicated_scoped','audits/adversarial_reviews/director_explicit_abel_round15.md · Uniform Abel estimate','{"record_type": "node", "id": "LEM-GONEK-EXPLICIT-ABEL-PRIME-SUBSTITUTION", "type": "mathematical_claim", "label": "Let A_m be the difference between Σ_(n≤x) Λ(n)n^(iδ−1)log^m(x/n) and ∫₁ˣu^(iδ−1)log^m(x/u)du. With L=log x and K=|Im δ|L it is bounded by L^m+4e^K 1_(m=0)+20e^K|iδ−1|L^m+20m e^K L^(m−1). For real |δ|≤1/2 a common bound is 31L^m+20mL^(m−1).", "evidence": "audits/adversarial_reviews/director_explicit_abel_round15.md · Uniform Abel estimate", "status": "adjudicated_scoped", "claim_kind": "unconditional_explicit_abel_substitution", "hypotheses": "Real x>1, integer m≥0, complex δ; omit the final term for m=0 and take the zeroth log power to be one. The right endpoint includes prime-power jumps. Uses Fiori–Jaskari v2 unconditionally for the absolute PNT error bounds r≤4 and ∫r(u)du/u<20. This is one substitution in Gonek Lemma 8."}','mathematical_claim','Let A_m be the difference between Σ_(n≤x) Λ(n)n^(iδ−1)log^m(x/n) and ∫₁ˣu^(iδ−1)log^m(x/u)du. With L=log x and K=|Im δ|L it is bounded by L^m+4e^K 1_(m=0)+20e^K|iδ−1|L^m+20m e^K L^(m−1). For real |δ|≤1/2 a common bound is 31L^m+20mL^(m−1).');
INSERT INTO "graph_nodes" VALUES('OBS-MELLIN-CRITICAL-LOG-ENDPOINT-ABSOLUTE-DIVERGENCE','graphs/knowledge_graph.jsonl',1375,'adjudicated_scoped','audits/adversarial_reviews/director_critical_endpoint_round15.md · Exact assertion','{"record_type": "node", "id": "OBS-MELLIN-CRITICAL-LOG-ENDPOINT-ABSOLUTE-DIVERGENCE", "type": "mathematical_claim", "label": "A real smooth f vanishing near zero and one and satisfying f(x)=O(x^(−4)) has finite Mellin area norm on β∈[−1/4,5/4] with weight √(1+t²) log³(e+|t|), yet Σ_ρ|h(ρ)| diverges. Every realization of the disjoint finite-carrier packet signs has finite norm, and divergence holds for almost every independent symmetric sign realization.", "evidence": "audits/adversarial_reviews/director_critical_endpoint_round15.md · Exact assertion", "status": "adjudicated_scoped", "claim_kind": "critical_log_endpoint_counterexample_to_absolute_zero_sampling", "hypotheses": "Actual nontrivial zeta zeros counted with multiplicity, using unconditional Riemann–von Mangoldt counting. The same example excludes universal absolute sampling for p≤3. Signed symmetric height convergence at p=3 remains open."}','mathematical_claim','A real smooth f vanishing near zero and one and satisfying f(x)=O(x^(−4)) has finite Mellin area norm on β∈[−1/4,5/4] with weight √(1+t²) log³(e+|t|), yet Σ_ρ|h(ρ)| diverges. Every realization of the disjoint finite-carrier packet signs has finite norm, and divergence holds for almost every independent symmetric sign realization.');
INSERT INTO "graph_nodes" VALUES('OBS-MORSE-PRINTED-SHIFTED-FAMILY-SELF-REFLECTION','graphs/knowledge_graph.jsonl',1376,'adjudicated_scoped','audits/adversarial_reviews/director_morse_scoped_round15.md · The nonzero-shift function is self-reflected','{"record_type": "node", "id": "OBS-MORSE-PRINTED-SHIFTED-FAMILY-SELF-REFLECTION", "type": "mathematical_claim", "label": "The printed E_h=(P+Q)/2−i(P−Q)/(2h), where P(z)=ξ(1/2−iz+h) and Q(z)=ξ(1/2−iz−h), equals its Schwarz reflection for every real h≠0 because P#=Q and Q#=P. Thus h=1/2,z=i already gives equality in the absolute values required to be strictly ordered by (5.1). The local limit of the printed family is ξ−iξ′.", "evidence": "audits/adversarial_reviews/director_morse_scoped_round15.md · The nonzero-shift function is self-reflected", "status": "adjudicated_scoped", "claim_kind": "exact_source_local_hermite_biehler_counterexample", "hypotheses": "The display immediately preceding (5.5) in the pinned arXiv v6 and journal versions. The separately defined h=0 function and the fixed-boundary spectral results are outside this claim."}','mathematical_claim','The printed E_h=(P+Q)/2−i(P−Q)/(2h), where P(z)=ξ(1/2−iz+h) and Q(z)=ξ(1/2−iz−h), equals its Schwarz reflection for every real h≠0 because P#=Q and Q#=P. Thus h=1/2,z=i already gives equality in the absolute values required to be strictly ordered by (5.1). The local limit of the printed family is ξ−iξ′.');
INSERT INTO "graph_nodes" VALUES('OBS-MORSE-PRINTED-HERGLOTZ-QUOTIENT-SIGN','graphs/knowledge_graph.jsonl',1377,'adjudicated_scoped','audits/adversarial_reviews/director_morse_scoped_round15.md · The explicit quotient has the opposite Herglotz sign','{"record_type": "node", "id": "OBS-MORSE-PRINTED-HERGLOTZ-QUOTIENT-SIGN", "type": "mathematical_claim", "label": "At z=i and x=e^u, the printed quotient (6.2) is −i exp(−x)/(1+x), so u=0 gives −i/(2e). Its imaginary part is strictly negative. With the printed decomposition E=A−iB, the compatible Herglotz quotient is +B/A.", "evidence": "audits/adversarial_reviews/director_morse_scoped_round15.md · The explicit quotient has the opposite Herglotz sign", "status": "adjudicated_scoped", "claim_kind": "exact_source_local_herglotz_sign_counterexample", "hypotheses": "Equation (6.2) and the positive-imaginary convention in the pinned arXiv v6 and journal versions. This is an auxiliary quotient in the z variable. The Appendix B Weyl–Titchmarsh quotient uses energy E=z² and has its own sign."}','mathematical_claim','At z=i and x=e^u, the printed quotient (6.2) is −i exp(−x)/(1+x), so u=0 gives −i/(2e). Its imaginary part is strictly negative. With the printed decomposition E=A−iB, the compatible Herglotz quotient is +B/A.');
INSERT INTO "graph_nodes" VALUES('THM-MELLIN-CRITICAL-STRIP-SYMMETRIC-EXPLICIT-FORMULA','graphs/knowledge_graph.jsonl',1378,'adjudicated_scoped','audits/adversarial_reviews/director_signed_mellin_round16.md · Statement and distinction from absolute sampling','{"record_type": "node", "id": "THM-MELLIN-CRITICAL-STRIP-SYMMETRIC-EXPLICIT-FORMULA", "type": "mathematical_claim", "label": "The ordinary inclusive symmetric height sum over nontrivial zeta zeros counted with multiplicity converges to the ordinary compensated Guinand–Weil formula with critical Mellin strip area weight √(1+t²). Consequently the logarithmic weights √(1+t²) log^p(e+|t|) suffice for every p≥0 under the same local hypotheses.", "evidence": "audits/adversarial_reviews/director_signed_mellin_round16.md · Statement and distinction from absolute sampling", "status": "adjudicated_scoped", "claim_kind": "sufficient_critical_strip_symmetric_explicit_formula", "hypotheses": "Continuous f with f(x)=O(x^δ) at zero and O(x^(−1−δ)) at infinity, F(u)=e^(u/2)f(e^u) in H¹ on a neighborhood of 0, and a finite stated strip norm on β∈[−ε,1+ε], 0<ε<δ. Unconditional. The contour proof establishes symmetric convergence, with separate half-axis convergence established by the Selberg route for p>1."}','mathematical_claim','The ordinary inclusive symmetric height sum over nontrivial zeta zeros counted with multiplicity converges to the ordinary compensated Guinand–Weil formula with critical Mellin strip area weight √(1+t²). Consequently the logarithmic weights √(1+t²) log^p(e+|t|) suffice for every p≥0 under the same local hypotheses.');
INSERT INTO "graph_nodes" VALUES('LEM-MELLIN-SELBERG-PROJECTION-AND-COUNT-REMAINDER','graphs/knowledge_graph.jsonl',1379,'adjudicated_scoped','audits/adversarial_reviews/director_signed_mellin_round16.md · Literal local hypotheses and the independent Selberg route','{"record_type": "node", "id": "LEM-MELLIN-SELBERG-PROJECTION-AND-COUNT-REMAINDER", "type": "mathematical_claim", "label": "For p>1, writing H(t)=h(1/2+it), Σ_ρ|h(ρ)−H(Im ρ)|<∞. If S₀(t)=N(t)−M(t) is the right-continuous positive-height counting remainder, then ∫₂∞|H′(t)S₀(t)|dt<∞ and H(T)S₀(T)→0 at every height. The same control holds with H(−t) on the negative half-axis.", "evidence": "audits/adversarial_reviews/director_signed_mellin_round16.md · Literal local hypotheses and the independent Selberg route", "status": "adjudicated_scoped", "claim_kind": "absolute_projection_and_count_remainder_bounds", "hypotheses": "Original endpoint value bounds and finite logarithmic Mellin strip area norm with p>1 and positive strip margin. Neither local H¹ nor a smooth-density convergence assumption is needed. The lemma does not address the projected term ∫ H M′."}','mathematical_claim','For p>1, writing H(t)=h(1/2+it), Σ_ρ|h(ρ)−H(Im ρ)|<∞. If S₀(t)=N(t)−M(t) is the right-continuous positive-height counting remainder, then ∫₂∞|H′(t)S₀(t)|dt<∞ and H(T)S₀(T)→0 at every height. The same control holds with H(−t) on the negative half-axis.');
INSERT INTO "graph_nodes" VALUES('THM-MELLIN-LOG-SIGNED-HALF-AXIS-CONVERGENCE','graphs/knowledge_graph.jsonl',1380,'adjudicated_scoped','audits/adversarial_reviews/director_signed_mellin_round16.md · Literal local hypotheses and the independent Selberg route','{"record_type": "node", "id": "THM-MELLIN-LOG-SIGNED-HALF-AXIS-CONVERGENCE", "type": "mathematical_claim", "label": "For p>1 the same signed zero sum converges separately on each half-height axis. The uniform density bound makes the projection onto Re s=1/2 an absolutely summable correction. The second moment of the counting remainder handles the signed Stieltjes integral, including the exact ordinate endpoint.", "evidence": "audits/adversarial_reviews/director_signed_mellin_round16.md · Literal local hypotheses and the independent Selberg route", "status": "adjudicated_scoped", "claim_kind": "sufficient_separate_signed_height_convergence", "hypotheses": "Same value, local H¹ and strip hypotheses as the symmetric theorem but with weight √(1+t²) log^p(e+|t|), p>1. No separate half-axis conclusion at p≤1 is asserted."}','mathematical_claim','For p>1 the same signed zero sum converges separately on each half-height axis. The uniform density bound makes the projection onto Re s=1/2 an absolutely summable correction. The second moment of the counting remainder handles the signed Stieltjes integral, including the exact ordinate endpoint.');
INSERT INTO "graph_nodes" VALUES('LEM-BL-LITERAL-TEST-CLASS-LOCAL-MELLIN-H1','graphs/knowledge_graph.jsonl',1381,'adjudicated_scoped','audits/adversarial_reviews/director_signed_mellin_round16.md · Literal local hypotheses and the independent Selberg route','{"record_type": "node", "id": "LEM-BL-LITERAL-TEST-CLASS-LOCAL-MELLIN-H1", "type": "mathematical_claim", "label": "Under the pinned manuscript''s literal conditions (A) and (B), finite critical strip norm gives central F∈H¹⁄². Its Gagliardo seminorm excludes any genuine jump. The source midpoint values then select the continuous representative, and finite one-sided limits of f′ give local H¹ near x=1, so the critical symmetric formula applies.", "evidence": "audits/adversarial_reviews/director_signed_mellin_round16.md · Literal local hypotheses and the independent Selberg route", "status": "adjudicated_scoped", "claim_kind": "source_scope_local_regularization_implication", "hypotheses": "Pinned 12-page Michigan author manuscript only. Condition (A) places the first-kind restriction on both f and f′ at its exceptional points. The general continuous class with the same value bounds needs a separate local assumption."}','mathematical_claim','Under the pinned manuscript''s literal conditions (A) and (B), finite critical strip norm gives central F∈H¹⁄². Its Gagliardo seminorm excludes any genuine jump. The source midpoint values then select the continuous representative, and finite one-sided limits of f′ give local H¹ near x=1, so the critical symmetric formula applies.');
INSERT INTO "graph_nodes" VALUES('OBS-MELLIN-LOG-SIGNED-BOUNDARY-CUSP','graphs/knowledge_graph.jsonl',1382,'adjudicated_scoped','audits/adversarial_reviews/director_signed_mellin_round16.md · A counterexample when the local-origin condition is omitted','{"record_type": "node", "id": "OBS-MELLIN-LOG-SIGNED-BOUNDARY-CUSP", "type": "mathematical_claim", "label": "A real continuous compactly supported f, smooth off x=1, has finite p=3 logarithmic strip norm and symmetric raw-height sum tending to positive infinity. Its local archimedean compensation diverges. In log coordinates take a compact positive-definite multiplier times the inverse Fourier transform of a positive even spectrum comparable to 1/(|t| log²|t| loglog|t|). The smooth counting density diverges positively while the signed projection and count-remainder corrections converge.", "evidence": "audits/adversarial_reviews/director_signed_mellin_round16.md · A counterexample when the local-origin condition is omitted", "status": "adjudicated_scoped", "claim_kind": "counterexample_to_universal_signed_sampling_without_local_regularity", "hypotheses": "Any fixed finite strip of the indicated form. The cusp lies outside literal (A) and the neighborhood H¹ theorem. It is separate from the smooth p=3 example of absolute divergence and supplies no additional author finding."}','mathematical_claim','A real continuous compactly supported f, smooth off x=1, has finite p=3 logarithmic strip norm and symmetric raw-height sum tending to positive infinity. Its local archimedean compensation diverges. In log coordinates take a compact positive-definite multiplier times the inverse Fourier transform of a positive even spectrum comparable to 1/(|t| log²|t| loglog|t|). The smooth counting density diverges positively while the signed projection and count-remainder corrections converge.');
INSERT INTO "graph_nodes" VALUES('LEM-GONEK-EXPLICIT-POSITIVE-DERIVATIVE-CONVOLUTION','graphs/knowledge_graph.jsonl',1383,'adjudicated_scoped','audits/adversarial_reviews/director_gonek_constants_round16.md · All positive integer orders','{"record_type": "node", "id": "LEM-GONEK-EXPLICIT-POSITIVE-DERIVATIVE-CONVOLUTION", "type": "mathematical_claim", "label": "For integer μ,ν≥1, z>1, M=μ+ν and L=log z, the unsigned log-power divisor sum differs from μ!ν!/(M+1)! times zL^(M+1) by at most [min(μ,ν)+1/e+μ^μν^ν/M^M] zL^M.", "evidence": "audits/adversarial_reviews/director_gonek_constants_round16.md · All positive integer orders", "status": "adjudicated_scoped", "claim_kind": "unconditional_explicit_positive_derivative_convolution", "hypotheses": "Gonek Lemma 7 (40), both derivative orders positive. The sign (−1)^(μ+ν) multiplies both parts in the Dirichlet series convention. The counting sum includes the integer endpoint. No claim of optimality or full numerical derivative-tail bound."}','mathematical_claim','For integer μ,ν≥1, z>1, M=μ+ν and L=log z, the unsigned log-power divisor sum differs from μ!ν!/(M+1)! times zL^(M+1) by at most [min(μ,ν)+1/e+μ^μν^ν/M^M] zL^M.');
INSERT INTO "graph_nodes" VALUES('LEM-GONEK-EXPLICIT-LEMMA8-ORDER-ONE-PAIR','graphs/knowledge_graph.jsonl',1384,'adjudicated_scoped','audits/adversarial_reviews/director_gonek_constants_round16.md · A convenient rational (1,1) allocation and its finite use','{"record_type": "node", "id": "LEM-GONEK-EXPLICIT-LEMMA8-ORDER-ONE-PAIR", "type": "mathematical_claim", "label": "For the (1,1) coefficient B_n in Gonek Lemma 8, letting L=log x and I₃=∫₁ˣ u^(iδ−1) log³(x/u)du, the finite error |Σ_(n≤x) B_n(1,1,δ)+(x/6)I₃| is at most x[(19/4)L³+(229/4)L²+90L].", "evidence": "audits/adversarial_reviews/director_gonek_constants_round16.md · A convenient rational (1,1) allocation and its finite use", "status": "adjudicated_scoped", "claim_kind": "unconditional_explicit_finite_prime_divisor_step", "hypotheses": "Real x>1 and real |δ|≤1/2. Uses the convenient rational (1,1) convolution bound 9/4 and the positive-power Abel specialization with vanishing upper boundary. This concerns only the divisor and prime-to-integral steps."}','mathematical_claim','For the (1,1) coefficient B_n in Gonek Lemma 8, letting L=log x and I₃=∫₁ˣ u^(iδ−1) log³(x/u)du, the finite error |Σ_(n≤x) B_n(1,1,δ)+(x/6)I₃| is at most x[(19/4)L³+(229/4)L²+90L].');
INSERT INTO "graph_nodes" VALUES('THM-RIEMANN1859-MODERN-GENUS-ZERO-PAIRED-PRODUCT','graphs/knowledge_graph.jsonl',1385,'adjudicated_scoped','audits/adversarial_reviews/director_riemann1859_whole_round16.md · Continuation and the product: the exact missing steps','{"record_type": "node", "id": "THM-RIEMANN1859-MODERN-GENUS-ZERO-PAIRED-PRODUCT", "type": "mathematical_claim", "label": "Let Xi(t)=ξ_*(1/2+it), with ξ_*(s)=s(s−1)π^(−s/2)Γ(s/2)ζ(s)/2. Its even Taylor series defines G(w)=Xi(√w), entire of order at most 1/2 by log M_Xi(R)=O(R log(R+2)), with order exactly 1/2 by Stirling along positive real s. Hadamard gives the genus-zero product Xi(t)=Xi(0) ∏_(Re α>0)(1−t²/α²), including multiplicities. In s coordinates the paired normalization is Xi(0)∏_α(1+1/(4α²))=ξ_*(0)=1/2.", "evidence": "audits/adversarial_reviews/director_riemann1859_whole_round16.md · Continuation and the product: the exact missing steps", "status": "adjudicated_scoped", "claim_kind": "known_modern_reconstruction_of_historical_product", "hypotheses": "Riemann''s theta and cosine representations, evenness, positivity on the imaginary t axis, and external modern finite-order Hadamard factorization. No RH, square-root branch choice, or zero-count asymptotic is used for the product. This is a known modern reconstruction of the 1859 product."}','mathematical_claim','Let Xi(t)=ξ_*(1/2+it), with ξ_*(s)=s(s−1)π^(−s/2)Γ(s/2)ζ(s)/2. Its even Taylor series defines G(w)=Xi(√w), entire of order at most 1/2 by log M_Xi(R)=O(R log(R+2)), with order exactly 1/2 by Stirling along positive real s. Hadamard gives the genus-zero product Xi(t)=Xi(0) ∏_(Re α>0)(1−t²/α²), including multiplicities. In s coordinates the paired normalization is Xi(0)∏_α(1+1/(4α²))=ξ_*(0)=1/2.');
INSERT INTO "graph_nodes" VALUES('THM-RIEMANN1859-MODERN-ORDERED-J0-FORMULA','graphs/knowledge_graph.jsonl',1386,'adjudicated_scoped','audits/adversarial_reviews/director_riemann1859_whole_round16.md · Exact arithmetic identity, branches and the known constant','{"record_type": "node", "id": "THM-RIEMANN1859-MODERN-ORDERED-J0-FORMULA", "type": "mathematical_claim", "label": "For x>1, midpoint J₀(x) equals li(x)−lim_(T→∞)Σ_(|Im ρ|≤T) E_ρ(x)+∫ₓ∞du/[u(u²−1)log u]−log 2. Use E_ρ(x)=Ei(ρ log x)−iπ sgn(Im ρ) with the continued log x^ρ=ρ log x. The offsets cancel under conjugate ordering. The summable O_I((1+|Im ρ|)^(−2)) kernel remainder reduces raw pointwise convergence to the later von Mangoldt midpoint ψ₀ formula. Unit-height counts and O_x(1/T) terms give equivalence with the source''s |α| order.", "evidence": "audits/adversarial_reviews/director_riemann1859_whole_round16.md · Exact arithmetic identity, branches and the known constant", "status": "adjudicated_scoped", "claim_kind": "known_modern_reconstruction_of_historical_ordered_explicit_formula", "hypotheses": "Midpoint values at prime powers, zeros with multiplicity, the stated height order, paired normalization, and external later ordered von Mangoldt formula. The real constant −log 2 is Genocchi''s known correction. No proof of the ordered limit is attributed to the 1859 text and no novelty is claimed."}','mathematical_claim','For x>1, midpoint J₀(x) equals li(x)−lim_(T→∞)Σ_(|Im ρ|≤T) E_ρ(x)+∫ₓ∞du/[u(u²−1)log u]−log 2. Use E_ρ(x)=Ei(ρ log x)−iπ sgn(Im ρ) with the continued log x^ρ=ρ log x. The offsets cancel under conjugate ordering. The summable O_I((1+|Im ρ|)^(−2)) kernel remainder reduces raw pointwise convergence to the later von Mangoldt midpoint ψ₀ formula. Unit-height counts and O_x(1/T) terms give equivalence with the source''s |α| order.');
INSERT INTO "graph_nodes" VALUES('LEM-MELLIN-NEGATIVE-LOG-SHARP-INVERSION-PACKET','graphs/knowledge_graph.jsonl',1387,'adjudicated_scoped','audits/adversarial_reviews/director_negative_mellin_round17.md · One packet: a large sharp inverse with small weakened norm','{"record_type": "node", "id": "LEM-MELLIN-NEGATIVE-LOG-SHARP-INVERSION-PACKET", "type": "mathematical_claim", "label": "Fix a prime p, u_*=log p, b=1/p and 0<A<q. The one-sided packet F_T(u_*+v)=b χ(v/W)η(Tv)sin(Tv), W=log^A(T)/T, has squared N_(−q) norm O(b²[W√T+TW/log^q T]) and tends to zero in this norm. On a=1+ε/2 its sharp inverse at u_* equals b exp((a−1/2)u_*) log(TW)/(2π)+O(b), with O(bW) change for U∈[T,T+1]. The target prime contributes −b log p log(TW)/(2π√p) in the folded contour, while all other prime terms tend to zero and the gamma piece is O(N_(−q)).", "evidence": "audits/adversarial_reviews/director_negative_mellin_round17.md · One packet: a large sharp inverse with small weakened norm", "status": "adjudicated_scoped", "claim_kind": "negative_logarithmic_sharp_inversion_packet_estimate", "hypotheses": "Fixed prime, strip margin 0<ε<1/4 and fixed 0<A<q. Constants may depend on the stage, including p,q,A,ε. The packet shrinks strictly between the target prime center and the next prime-power center. The contour statement uses a good height in [T,T+1]."}','mathematical_claim','Fix a prime p, u_*=log p, b=1/p and 0<A<q. The one-sided packet F_T(u_*+v)=b χ(v/W)η(Tv)sin(Tv), W=log^A(T)/T, has squared N_(−q) norm O(b²[W√T+TW/log^q T]) and tends to zero in this norm. On a=1+ε/2 its sharp inverse at u_* equals b exp((a−1/2)u_*) log(TW)/(2π)+O(b), with O(bW) change for U∈[T,T+1]. The target prime contributes −b log p log(TW)/(2π√p) in the folded contour, while all other prime terms tend to zero and the gamma piece is O(N_(−q)).');
INSERT INTO "graph_nodes" VALUES('OBS-MELLIN-ALL-NEGATIVE-LOG-SIGNED-DIVERGENCE','graphs/knowledge_graph.jsonl',1388,'adjudicated_scoped','audits/adversarial_reviews/director_negative_mellin_round17.md · A single globally smooth test','{"record_type": "node", "id": "OBS-MELLIN-ALL-NEGATIVE-LOG-SIGNED-DIVERGENCE", "type": "mathematical_claim", "label": "For each fixed strip with 0<ε<1/4 one real smooth f, zero near zero and one and O(x^(−3/2)) at infinity, has finite N_(−q) for every fixed q>0. Its samples f(n) at prime powers and f(1/n) for n≥1 vanish. The ordinary symmetric raw zero sum with multiplicity has a subsequence tending to −∞ and a bounded subsequence. The pole and archimedean terms are absolutely finite.", "evidence": "audits/adversarial_reviews/director_negative_mellin_round17.md · A single globally smooth test", "status": "adjudicated_scoped", "claim_kind": "simultaneous_negative_logarithmic_strip_signed_counterexample", "hypotheses": "Use one locally finite escaped-prime packet sequence with q_j=1/j and A_j=q_j/2 before choosing each carrier. Stagewise protection controls both finite-height subsequences. The witness satisfies literal (A) and (B). Its critical norm is infinite, and the weakened norms need not be bounded uniformly as q decreases to zero."}','mathematical_claim','For each fixed strip with 0<ε<1/4 one real smooth f, zero near zero and one and O(x^(−3/2)) at infinity, has finite N_(−q) for every fixed q>0. Its samples f(n) at prime powers and f(1/n) for n≥1 vanish. The ordinary symmetric raw zero sum with multiplicity has a subsequence tending to −∞ and a bounded subsequence. The pole and archimedean terms are absolutely finite.');
INSERT INTO "graph_nodes" VALUES('THM-MELLIN-EXACT-SIGNED-LOG-BOUNDARY','graphs/knowledge_graph.jsonl',1389,'adjudicated_scoped','audits/adversarial_reviews/director_negative_mellin_round17.md · What this obstruction says','{"record_type": "node", "id": "THM-MELLIN-EXACT-SIGNED-LOG-BOUNDARY", "type": "mathematical_claim", "label": "The exponent p=0 is the exact boundary for a universal ordinary symmetric height formula in this logarithmic strip scale. Every p≥0 suffices under the original value bounds and local H¹ around x=1 or the literal (A) class with midpoint values. One smooth witness in that class defeats all weights √(1+t²)/log^q(e+|t|), q>0.", "evidence": "audits/adversarial_reviews/director_negative_mellin_round17.md · What this obstruction says", "status": "adjudicated_scoped", "claim_kind": "sharp_signed_symmetric_logarithmic_strip_boundary", "hypotheses": "Fix 0<ε<1/4 so both sufficiency and the counterexample apply on the stated strip. This is a universal symmetric result for the stated test class. No individual necessity claim, uniform q-bound, or separate half-axis threshold is asserted."}','mathematical_claim','The exponent p=0 is the exact boundary for a universal ordinary symmetric height formula in this logarithmic strip scale. Every p≥0 suffices under the original value bounds and local H¹ around x=1 or the literal (A) class with midpoint values. One smooth witness in that class defeats all weights √(1+t²)/log^q(e+|t|), q>0.');
INSERT INTO "graph_nodes" VALUES('OBS-CSTAR-COMMON-NONNEGATIVE-SEQUENCE-NORM-COUNTERMODEL','graphs/knowledge_graph.jsonl',1390,'adjudicated_scoped','audits/adversarial_reviews/director_common_sequence_round17.md · Exact statement','{"record_type": "node", "id": "OBS-CSTAR-COMMON-NONNEGATIVE-SEQUENCE-NORM-COUNTERMODEL", "type": "mathematical_claim", "label": "For K≈T^θ, 1/2<θ<2/3 and integer P≈KT, one nonnegative real sequence b(n) on J=[P,2P)∩ℤ has exact mass P. Writing B_(k,u)=Σ_(n≡u mod k)b(n), the all-residue squared error about P/k totals O(PK) over k≤2K and the sum of row maxima is O(K√P). Both bounds hold on the unit rows centered by their induced means. For the full support S of the narrow-band fourth prime polynomial, including repeated factors, |S|=binom(M+3,4)≍K/log⁴K where M is the number of band primes. The coefficients c_k=4!/∏_(p|k)m_p! satisfy 1≤c_k≤24. The h=1 unit-centered real phase projection with weights c_k/k is ≫√(P|S|), exceeding T log⁴T by a divergent factor.", "evidence": "audits/adversarial_reviews/director_common_sequence_round17.md · Exact statement", "status": "adjudicated_scoped", "claim_kind": "common_sequence_all_residue_and_induced_unit_norm_countermodel", "hypotheses": "Fix a narrow relative prime band [X,(1+η)X] with K=X⁴ and (1+η)⁴<2 so S lies in [K,2K). All congruence rows arise from the same sequence and whole-row common-divisor marginals agree. The all-residue centering and induced unit means concern an integer interval, with no prime support, simultaneous unit support, P/φ(k) baseline, or Mangoldt pointwise cap."}','mathematical_claim','For K≈T^θ, 1/2<θ<2/3 and integer P≈KT, one nonnegative real sequence b(n) on J=[P,2P)∩ℤ has exact mass P. Writing B_(k,u)=Σ_(n≡u mod k)b(n), the all-residue squared error about P/k totals O(PK) over k≤2K and the sum of row maxima is O(K√P). Both bounds hold on the unit rows centered by their induced means. For the full support S of the narrow-band fourth prime polynomial, including repeated factors, |S|=binom(M+3,4)≍K/log⁴K where M is the number of band primes. The coefficients c_k=4!/∏_(p|k)m_p! satisfy 1≤c_k≤24. The h=1 unit-centered real phase projection with weights c_k/k is ≫√(P|S|), exceeding T log⁴T by a divergent factor.');
INSERT INTO "graph_nodes" VALUES('OBS-CSTAR-COMMON-INTEGER-SEQUENCE-NORM-COUNTERMODEL','graphs/knowledge_graph.jsonl',1391,'adjudicated_scoped','audits/adversarial_reviews/director_common_sequence_round17.md · Integer-valued realization with exact mass','{"record_type": "node", "id": "OBS-CSTAR-COMMON-INTEGER-SEQUENCE-NORM-COUNTERMODEL", "type": "mathematical_claim", "label": "In the common-sequence countermodel the weights can be nonnegative integers while preserving mass P, the same order of discrepancy bounds and the phase lower bound. Draw P integers from probabilities b(n)/P. The multinomial summed expected variance is O(PK), and the projection variance O(P(|S|/K)²) is negligible against P|S|. Markov and Chebyshev give a realization satisfying both bounds.", "evidence": "audits/adversarial_reviews/director_common_sequence_round17.md · Integer-valued realization with exact mass", "status": "adjudicated_scoped", "claim_kind": "integer_valued_common_sequence_countermodel", "hypotheses": "Same single interval, full fourth-power support and centering as the real-weight model. Integer values can include repeated draws. This remains an abstract obstruction and does not estimate the genuine prime term or the full smooth C_* sum."}','mathematical_claim','In the common-sequence countermodel the weights can be nonnegative integers while preserving mass P, the same order of discrepancy bounds and the phase lower bound. Draw P integers from probabilities b(n)/P. The multinomial summed expected variance is O(PK), and the projection variance O(P(|S|/K)²) is negligible against P|S|. Markov and Chebyshev give a realization satisfying both bounds.');
INSERT INTO "graph_nodes" VALUES('THM-S004-ADV401','graphs/knowledge_graph.jsonl',1392,'independentalgebraandtailreconstruction;967finiteexactchecks','arXiv1801.05914v5 Lemma12(v),p30','{"record_type": "node", "id": "THM-S004-ADV401", "type": "mathematical_claim", "label": "For finiteK, ordered-pair local H derivative equals −4 local inverse-square energy plus2 times external sum_ioutsideK sum_k!=l_inK 1/((xi−xk)(xi−xl)); absolute convergence follows from macroscopic root growth.", "evidence": "arXiv1801.05914v5 Lemma12(v),p30", "status": "independentalgebraandtailreconstruction;967finiteexactchecks"}','mathematical_claim','For finiteK, ordered-pair local H derivative equals −4 local inverse-square energy plus2 times external sum_ioutsideK sum_k!=l_inK 1/((xi−xk)(xi−xl)); absolute convergence follows from macroscopic root growth.');
INSERT INTO "graph_nodes" VALUES('THM-S004-ADV402','graphs/knowledge_graph.jsonl',1393,'advocateandsemanticindependentwitnessandreplacement;directorscopeclassificationpending','v5 Lemma16 proof,p40','{"record_type": "node", "id": "THM-S004-ADV402", "type": "mathematical_claim", "label": "The odd reciprocal-cube endpoint sum is bounded using (1+minimum_endpoint_distance)^−2, not the printed maximum; its aggregate sum is bounded, preserving Lemma16 up to polylog factors.", "evidence": "v5 Lemma16 proof,p40", "status": "advocateandsemanticindependentwitnessandreplacement;directorscopeclassificationpending"}','mathematical_claim','The odd reciprocal-cube endpoint sum is bounded using (1+minimum_endpoint_distance)^−2, not the printed maximum; its aggregate sum is bounded, preserving Lemma16 up to polylog factors.');
INSERT INTO "graph_nodes" VALUES('THM-S004-ADV403','graphs/knowledge_graph.jsonl',1394,'completeadvocatederivation;independentchallengepending','audits/adversarial_reviews/rodgerstao_far_field_advocate_round4.md','{"record_type": "node", "id": "THM-S004-ADV403", "type": "mathematical_claim", "label": "Under xj−ξj=Ologj and weighted inverse-square sum≤M≥Tlog³T, signed far field is −π/8signk pluspower-small error in bulk; pair antisymmetry and weightedCauchy imply sourceX4=o(M).", "evidence": "audits/adversarial_reviews/rodgerstao_far_field_advocate_round4.md", "status": "completeadvocatederivation;independentchallengepending"}','mathematical_claim','Under xj−ξj=Ologj and weighted inverse-square sum≤M≥Tlog³T, signed far field is −π/8signk pluspower-small error in bulk; pair antisymmetry and weightedCauchy imply sourceX4=o(M).');
INSERT INTO "graph_nodes" VALUES('THM-R201-AUX','graphs/knowledge_graph.jsonl',1395,'elementary independently reconstructed model proposition; no novelty claim','proposals/independent_campaigns/auxiliary_spectral_complexity.md','{"record_type": "node", "id": "THM-R201-AUX", "type": "mathematical_claim", "label": "If A selfadjoint compact-resolvent, D Hermitian on C^M, B:C^M->H bounded, T=[[A,B],[B*,D]] on D(A)+C^M, then |Delta_T(K)-Delta_A(K)|<=3M for everyK>0, including two-sided unbounded spectra; constant3 sharp.", "evidence": "proposals/independent_campaigns/auxiliary_spectral_complexity.md", "status": "elementary independently reconstructed model proposition; no novelty claim", "hypotheses": ["compact resolvent", "bounded block coupling on stated common domain", "multiplicity counts in half-open bounded intervals"]}','mathematical_claim','If A selfadjoint compact-resolvent, D Hermitian on C^M, B:C^M->H bounded, T=[[A,B],[B*,D]] on D(A)+C^M, then |Delta_T(K)-Delta_A(K)|<=3M for everyK>0, including two-sided unbounded spectra; constant3 sharp.');
INSERT INTO "graph_nodes" VALUES('COR-R202-AUX-GRAPH','graphs/knowledge_graph.jsonl',1396,'conditional model-complexity corollary; not RH progress','proposals/independent_campaigns/auxiliary_spectral_complexity.md','{"record_type": "node", "id": "COR-R202-AUX-GRAPH", "type": "mathematical_claim", "label": "An E-channel fixed-boundary first-order graph with M boundedly coupled finite auxiliary levels has |Delta(K)|<3(E+M); matching classical zeta counts to o(K) atK,2K,4K requires liminf(E_K+M_K)/K>=log2/(3pi).", "evidence": "proposals/independent_campaigns/auxiliary_spectral_complexity.md", "status": "conditional model-complexity corollary; not RH progress", "hypotheses": ["one fixed graph/auxiliary realization per three-height comparison", "positive finite edge lengths", "bounded finite-rank block coupling"]}','mathematical_claim','An E-channel fixed-boundary first-order graph with M boundedly coupled finite auxiliary levels has |Delta(K)|<3(E+M); matching classical zeta counts to o(K) atK,2K,4K requires liminf(E_K+M_K)/K>=log2/(3pi).');
INSERT INTO "graph_nodes" VALUES('THM-R203-CA-CONCAVE','graphs/knowledge_graph.jsonl',1397,'elementary independently reconstructed calculus lemma; novelty unassessed','proposals/independent_campaigns/lagarias_CA_interpolation_round2.md','{"record_type": "node", "id": "THM-R203-CA-CONCAVE", "type": "mathematical_claim", "label": "For realx>=32768,H(x)=psi(x+1)+gamma,B=H+exp(H)logH, g(t)=log(B(exp t)/exp t) satisfiesg_second(t)<0.", "evidence": "proposals/independent_campaigns/lagarias_CA_interpolation_round2.md", "status": "elementary independently reconstructed calculus lemma; novelty unassessed", "hypotheses": ["realx>=32768", "natural logs", "smooth digamma interpolation"]}','mathematical_claim','For realx>=32768,H(x)=psi(x+1)+gamma,B=H+exp(H)logH, g(t)=log(B(exp t)/exp t) satisfiesg_second(t)<0.');
INSERT INTO "graph_nodes" VALUES('COR-R204-CA-ENDPOINTS','graphs/knowledge_graph.jsonl',1398,'conditional finite-interval certificate; no infinite-tail proof','proposals/independent_campaigns/lagarias_CA_interpolation_round2.md','{"record_type": "node", "id": "COR-R204-CA-ENDPOINTS", "type": "mathematical_claim", "label": "If32768<=u<v are integer global maximizers ofsigma(n)/n^(1+epsilon) for the SAMEepsilon>0, and both endpoint Lagarias inequalities hold, every integer betweenu,v satisfies the inequality; strict endpoints imply strict throughout.", "evidence": "proposals/independent_campaigns/lagarias_CA_interpolation_round2.md", "status": "conditional finite-interval certificate; no infinite-tail proof", "hypotheses": ["certified shared supporting parameter; arbitrary abundant endpoints insufficient", "no assumption that consecutive CA ratios are prime"]}','mathematical_claim','If32768<=u<v are integer global maximizers ofsigma(n)/n^(1+epsilon) for the SAMEepsilon>0, and both endpoint Lagarias inequalities hold, every integer betweenu,v satisfies the inequality; strict endpoints imply strict throughout.');
INSERT INTO "graph_nodes" VALUES('OBS-R205-FINITE55440','graphs/knowledge_graph.jsonl',1399,'known finite inequalities independently reproduced over extended base interval','experiments/code/lagarias_55440.py','{"record_type": "node", "id": "OBS-R205-FINITE55440", "type": "mathematical_claim", "label": "All integers2<=n<=55440 satisfy strict Lagarias inequality; equality at1. Exact lower-bound integer arithmetic certificate.", "evidence": "experiments/code/lagarias_55440.py", "status": "known finite inequalities independently reproduced over extended base interval"}','mathematical_claim','All integers2<=n<=55440 satisfy strict Lagarias inequality; equality at1. Exact lower-bound integer arithmetic certificate.');
INSERT INTO "graph_nodes" VALUES('THM-R207-CA-GLOBAL','graphs/knowledge_graph.jsonl',1400,'ordinary analytic-plus-exact-computational proof; novelty unassessed','proposals/independent_campaigns/lagarias_global_concavity_round2.md','{"record_type": "node", "id": "THM-R207-CA-GLOBAL", "type": "mathematical_claim", "label": "For every realx>=1,H(x)=psi(x+1)+gamma,B=H+exp(H)logH,g(t)=log(B(exp t)/exp t), g_second(t)<0. Analytic proof forx>=2048 plus170exact interval cells on[1,2048].", "evidence": "proposals/independent_campaigns/lagarias_global_concavity_round2.md", "status": "ordinary analytic-plus-exact-computational proof; novelty unassessed", "hypotheses": ["smooth digamma continuation", "compact cells verified by standard-library integer interval arithmetic with proved exp/log remainders"]}','mathematical_claim','For every realx>=1,H(x)=psi(x+1)+gamma,B=H+exp(H)logH,g(t)=log(B(exp t)/exp t), g_second(t)<0. Analytic proof forx>=2048 plus170exact interval cells on[1,2048].');
INSERT INTO "graph_nodes" VALUES('THM-R001-1','graphs/knowledge_graph.jsonl',1401,'source-stated; section3 reconstructed conditional on Robin dependencies','Theorem1.1; Problem E (1.1), p1; proof pp6–8','{"record_type": "node", "id": "THM-R001-1", "type": "mathematical_claim", "label": "RH iff for every integer n>=1, sigma(n)<=H_n+exp(H_n)*log(H_n), with equality only n=1.", "evidence": "Theorem1.1; Problem E (1.1), p1; proof pp6–8", "status": "source-stated; section3 reconstructed conditional on Robin dependencies", "hypotheses": ["n positive integer", "H_n=sum(1/j,j=1..n)", "natural log"]}','mathematical_claim','RH iff for every integer n>=1, sigma(n)<=H_n+exp(H_n)*log(H_n), with equality only n=1.');
INSERT INTO "graph_nodes" VALUES('THM-R001-2','graphs/knowledge_graph.jsonl',1402,'source-stated; proof inspected','Lemma3.2,p7','{"record_type": "node", "id": "THM-R001-2", "type": "mathematical_claim", "label": "For every integer n>=20, H_n+exp(H_n)*log(H_n)<=exp(gamma)*n*log(log(n))+7*n/log(n).", "evidence": "Lemma3.2,p7", "status": "source-stated; proof inspected", "hypotheses": ["n>=20 integer"]}','mathematical_claim','For every integer n>=20, H_n+exp(H_n)*log(H_n)<=exp(gamma)*n*log(log(n))+7*n/log(n).');
INSERT INTO "graph_nodes" VALUES('OBS-R001-3','graphs/knowledge_graph.jsonl',1403,'elementary derived corollary; no novelty claim','proposals/independent_campaigns/lagarias_slack.md','{"record_type": "node", "id": "OBS-R001-3", "type": "mathematical_claim", "label": "Delta(n)~exp(gamma)*gamma*n/log(n).", "evidence": "proposals/independent_campaigns/lagarias_slack.md", "status": "elementary derived corollary; no novelty claim", "hypotheses": ["n tends to infinity through integers"]}','mathematical_claim','Delta(n)~exp(gamma)*gamma*n/log(n).');
INSERT INTO "graph_nodes" VALUES('THM-R002-FRAME','graphs/knowledge_graph.jsonl',1404,'alternate_elementary_proof_for_scoped_source_estimate; no novelty claim','audits/adversarial_reviews/af_boundary_repair.md; original arXiv2608.13637v2 Proposition5.2 pp8–9','{"record_type": "node", "id": "THM-R002-FRAME", "type": "mathematical_claim", "label": "For the fixed tapered Fourier window and sampling grid in AF Proposition5.2, with locally bounded logarithmic-tail weight |nu|<=B+log+(|tau|/(4T)), the exterior integral satisfies |E2|=O(B² L² logL), hence normalized remainder O(TlogL/L²).", "evidence": "audits/adversarial_reviews/af_boundary_repair.md; original arXiv2608.13637v2 Proposition5.2 pp8–9", "status": "alternate_elementary_proof_for_scoped_source_estimate; no novelty claim", "hypotheses": ["T sufficiently large,L=log(T/(2pi)),d=floor(TL/(2pi))", "phi real even C², support[-L/2,L/2],0<=phi<=1,uniform L1 first/second derivative bounds", "a=||phi||²/L bounded below", "source nu envelope(5.7), B=L+4sqrt(T/(2pi))"]}','mathematical_claim','For the fixed tapered Fourier window and sampling grid in AF Proposition5.2, with locally bounded logarithmic-tail weight |nu|<=B+log+(|tau|/(4T)), the exterior integral satisfies |E2|=O(B² L² logL), hence normalized remainder O(TlogL/L²).');
INSERT INTO "graph_nodes" VALUES('LEM-RST048-CLUSTER','graphs/knowledge_graph.jsonl',1405,'adjudicated_scoped_conditional_reconstruction','RST048v2 equations22–41; audits/adversarial_reviews/director_rstation48_main_theorem_round6.md §§1–3','{"record_type": "node", "id": "LEM-RST048-CLUSTER", "type": "mathematical_claim", "label": "Under RH and source fixed D=e=10^-4,delta=10^-6, delayed-profile grouped errors satisfy ||sum_{C in B} zeta(R_C-T_{L,w_kC}R_C)||_*² <= (C/L)sum_{C in B}(2+|tau_C|)^(-2+1/100) for every subset B, L=logN. Centers are fixed-mesh separated; individual roots need not be. The tail beyondY is O(Y^(-99/100)/L).", "evidence": "RST048v2 equations22–41; audits/adversarial_reviews/director_rstation48_main_theorem_round6.md §§1–3", "status": "adjudicated_scoped_conditional_reconstruction", "claim_kind": "source_lemma_independently_reconstructed", "hypotheses": "Exact source norm dt/[2pi(1/4+t²)], RH fixed-right reciprocal/subpower bounds and fixed-interval zero counts; source profiles22–23. Hilbert-space subset summability, not sum of individual norms."}','mathematical_claim','Under RH and source fixed D=e=10^-4,delta=10^-6, delayed-profile grouped errors satisfy ||sum_{C in B} zeta(R_C-T_{L,w_kC}R_C)||_*² <= (C/L)sum_{C in B}(2+|tau_C|)^(-2+1/100) for every subset B, L=logN. Centers are fixed-mesh separated; individual roots need not be. The tail beyondY is O(Y^(-99/100)/L).');
INSERT INTO "graph_nodes" VALUES('LEM-RST048-INTEGER','graphs/knowledge_graph.jsonl',1406,'adjudicated_scoped_conditional_reconstruction','RST048v2 equations51–62; director_rstation48_main_theorem_round6.md §6; independent quadrature reviews','{"record_type": "node", "id": "LEM-RST048-INTEGER", "type": "mathematical_claim", "label": "Under the same RH inputs, withH=N^(1/20), K=N^(3/20), the source growing delayed correction is realized by an actual length-at-mostN Dirichlet polynomial. Its low/high squared zeta-weighted quadrature errors are O(N^(-0.1499595)) and O(N^(-0.049958)); the anchor is O(N^(-0.07499475)). Constants may depend on the fixed contour parameters.", "evidence": "RST048v2 equations51–62; director_rstation48_main_theorem_round6.md §6; independent quadrature reviews", "status": "adjudicated_scoped_conditional_reconstruction", "claim_kind": "source_arithmetic_realization_independently_reconstructed"}','mathematical_claim','Under the same RH inputs, withH=N^(1/20), K=N^(3/20), the source growing delayed correction is realized by an actual length-at-mostN Dirichlet polynomial. Its low/high squared zeta-weighted quadrature errors are O(N^(-0.1499595)) and O(N^(-0.049958)); the anchor is O(N^(-0.07499475)). Constants may depend on the fixed contour parameters.');
INSERT INTO "graph_nodes" VALUES('LEM-RST048-LOCAL-REPAIR','graphs/knowledge_graph.jsonl',1407,'adjudicated_scoped_repairable_compressed_source_step','audits/adversarial_reviews/director_rstation48_main_theorem_round6.md §7; threshold62_rstation48_main_theorem_skeptic.md; latest62_rst048_independent.md','{"record_type": "node", "id": "LEM-RST048-LOCAL-REPAIR", "type": "mathematical_claim", "label": "For each fixed finite union of source clusters, expand its principal parts into individual Laurent terms a_(rho,j)/(s-rho)^j. Outside a fixed neighborhood of that term''s own ordinate, the singleton repeated-node profile estimate bounds its zeta-multiplied error by C_F|zeta(1/2+it)|/[L|t-gamma|^(j+1)], giving weighted norm O_F(1/L). This also covers gaps inside the original full cluster hull and fills the use of26 in source§7.2.", "evidence": "audits/adversarial_reviews/director_rstation48_main_theorem_round6.md §7; threshold62_rstation48_main_theorem_skeptic.md; latest62_rst048_independent.md", "status": "adjudicated_scoped_repairable_compressed_source_step", "claim_kind": "explicit_fixed_Laurent_localization_qualification", "hypotheses": "Assume RH, so rho=1/2+i gamma; classical RH subpower zeta bound for integrability. Fixed finite set first; constants not uniform in growing sets. Source taper admissible for j<=kC; optimal replacement has analogous BV estimate. No new uniform zero-separation assumption."}','mathematical_claim','For each fixed finite union of source clusters, expand its principal parts into individual Laurent terms a_(rho,j)/(s-rho)^j. Outside a fixed neighborhood of that term''s own ordinate, the singleton repeated-node profile estimate bounds its zeta-multiplied error by C_F|zeta(1/2+it)|/[L|t-gamma|^(j+1)], giving weighted norm O_F(1/L). This also covers gaps inside the original full cluster hull and fills the use of26 in source§7.2.');
INSERT INTO "graph_nodes" VALUES('THM-RST048-OPTIMAL','graphs/knowledge_graph.jsonl',1408,'adjudicated_scoped_RH_conditional_source_theorem_with_explicit_local_qualification','RST048v2 Theorem1,equations1–78; director_rstation48_main_theorem_round6.md; Burnol math/0103058v2 Theorem1.3 printedp4','{"record_type": "node", "id": "THM-RST048-OPTIMAL", "type": "mathematical_claim", "label": "Assume RH. In the classical norm ||f||_*²=(2pi)^(-1)integral_R|f(1/2+it)|²/(1/4+t²)dt, letDelta_N²=inf_{A=sum_{n<=N}a_n n^-s}||1-zeta A||_*² with arbitrary complex coefficients; letd_N restrict the polynomial multiplying zeta toA(1)=0. Thenlim_N(logN)Delta_N²=lim_N(logN)d_N²=sum_{distinct nontrivialrho}m_rho²/|rho|², counting both ordinate signs.", "evidence": "RST048v2 Theorem1,equations1–78; director_rstation48_main_theorem_round6.md; Burnol math/0103058v2 Theorem1.3 printedp4", "status": "adjudicated_scoped_RH_conditional_source_theorem_with_explicit_local_qualification", "claim_kind": "source_main_theorem_independently_reconstructed_with_local_qualification", "hypotheses": "RH only, together with its declared classical consequences; source main theorem reconstructed through78 with explicit fixed-Laurent qualification at§7.2. Burnol published lower bound accepted/rechecked in exact norm. Coefficients depend on zeros; no rate for a prescribed Mobius array, no unconditional RH conclusion, and no uniform conductor or effective finite-N rate.", "verification_scope": "Scoped Theorem1 reconstruction with fixed-Laurent qualification; Theorem5 fixed-prefix and Theorem6 finite-off-line source extensions now separately adjudicated. Whole-paperLevel1, notLevel2/3."}','mathematical_claim','Assume RH. In the classical norm ||f||_*²=(2pi)^(-1)integral_R|f(1/2+it)|²/(1/4+t²)dt, letDelta_N²=inf_{A=sum_{n<=N}a_n n^-s}||1-zeta A||_*² with arbitrary complex coefficients; letd_N restrict the polynomial multiplying zeta toA(1)=0. Thenlim_N(logN)Delta_N²=lim_N(logN)d_N²=sum_{distinct nontrivialrho}m_rho²/|rho|², counting both ordinate signs.');
INSERT INTO "graph_nodes" VALUES('THM-SCALAR62-M2','graphs/knowledge_graph.jsonl',1409,'adjudicated_scoped; retain conditional/model/finite scope in statement','proposals/independent_campaigns/scalar62_two_term_extremum.md','{"record_type": "node", "id": "THM-SCALAR62-M2", "type": "mathematical_claim", "label": "For the scalar reciprocal taper with M=2 and every positive integer degree m, the squared H2 residual is uniquely maximized up to common rotation at complete coalescence. Its maximum is B-1+4^(-m)m^2 B-2^(1-m)m binom(2m,m-1), with B=binom(2m,m).", "evidence": "proposals/independent_campaigns/scalar62_two_term_extremum.md", "status": "adjudicated_scoped; retain conditional/model/finite scope in statement", "hypotheses": "All q_j unit, repetitions allowed; Q=prod(1-q_j z), A=1+2^(-m)(sum q_j)z; standard H2 coefficient-square norm."}','mathematical_claim','For the scalar reciprocal taper with M=2 and every positive integer degree m, the squared H2 residual is uniquely maximized up to common rotation at complete coalescence. Its maximum is B-1+4^(-m)m^2 B-2^(1-m)m binom(2m,m-1), with B=binom(2m,m).');
INSERT INTO "graph_nodes" VALUES('THM-SCALAR62-FIXED-M','graphs/knowledge_graph.jsonl',1410,'adjudicated_scoped; retain conditional/model/finite scope in statement','proposals/independent_campaigns/scalar62_two_term_extremum.md, Fixed window lengths at sufficiently high degree','{"record_type": "node", "id": "THM-SCALAR62-FIXED-M", "type": "mathematical_claim", "label": "For arbitrary integers m,M>=2, set L=m+M-1 and H=sum_(j=0)^(M-1) binom(m+j-1,j)(1-j/M)^m. If 4L^2(H^2-1)<1 then complete coalescence uniquely maximizes scalar reciprocal taper energy up to common rotation. In particular each fixed M is covered for all sufficiently large m.", "evidence": "proposals/independent_campaigns/scalar62_two_term_extremum.md, Fixed window lengths at sufficiently high degree", "status": "adjudicated_scoped; retain conditional/model/finite scope in statement", "hypotheses": "All q_j unit, repetitions allowed; Q=prod(1-q_j z), A=sum_(j=0)^(M-1) ([z^j]Q^-1)(1-j/M)^m z^j; standard H2 coefficient-square norm."}','mathematical_claim','For arbitrary integers m,M>=2, set L=m+M-1 and H=sum_(j=0)^(M-1) binom(m+j-1,j)(1-j/M)^m. If 4L^2(H^2-1)<1 then complete coalescence uniquely maximizes scalar reciprocal taper energy up to common rotation. In particular each fixed M is covered for all sufficiently large m.');
INSERT INTO "graph_nodes" VALUES('LEM-E-W301','graphs/knowledge_graph.jsonl',1411,'independently_checked_elementary_identity','proposals/independent_campaigns/unit_circle_scalar_window_round3.md§1','{"record_type": "node", "id": "LEM-E-W301", "type": "mathematical_claim", "label": "With b^S_n=[z^n]product_(j inS)(1-q_jz)^-1 and negative indices0, Q applied to b^all_n w_n has coefficient w_n delta_(n0)+sum_(empty!=S subset{1..m})q_S h_(n-|S|)(q_j:j inS) Delta_backward^|S| w_n. Identity is exact for any scalar sequence w and each n>=0; repeated root labels are distinct indexed factors.", "evidence": "proposals/independent_campaigns/unit_circle_scalar_window_round3.md§1", "status": "independently_checked_elementary_identity", "hypotheses": "Finite indexed factor set; w any sequence defined at needed indices; negative reciprocal coefficient0."}','mathematical_claim','With b^S_n=[z^n]product_(j inS)(1-q_jz)^-1 and negative indices0, Q applied to b^all_n w_n has coefficient w_n delta_(n0)+sum_(empty!=S subset{1..m})q_S h_(n-|S|)(q_j:j inS) Delta_backward^|S| w_n. Identity is exact for any scalar sequence w and each n>=0; repeated root labels are distinct indexed factors.');
INSERT INTO "graph_nodes" VALUES('LEM-E-W302','graphs/knowledge_graph.jsonl',1412,'derived_exact_identity_independent_review_pending','proposals/independent_campaigns/scalar_window_coalescence_maximum_round3.md','{"record_type": "node", "id": "LEM-E-W302", "type": "mathematical_claim", "label": "For three unit roots, S=sumq,P=productq,v=|S|²,u=Re(S³/P), Delta=product_(i<j)|q_i-q_j|², one has Delta=27−18v−v²+8u.", "evidence": "proposals/independent_campaigns/scalar_window_coalescence_maximum_round3.md", "status": "derived_exact_identity_independent_review_pending", "hypotheses": "Exactly three unit roots, coincidences allowed."}','mathematical_claim','For three unit roots, S=sumq,P=productq,v=|S|²,u=Re(S³/P), Delta=product_(i<j)|q_i-q_j|², one has Delta=27−18v−v²+8u.');
INSERT INTO "graph_nodes" VALUES('LEM-E-W303','graphs/knowledge_graph.jsonl',1413,'previously_independently_checked_scoped_lemma','audits/adversarial_reviews/weighted_selberg_round2.md Hilbert-space identity and shrinking interval','{"record_type": "node", "id": "LEM-E-W303", "type": "mathematical_claim", "label": "For any finite coefficient vector a_n supported1..N and fixed integerq>=1, C=sum a_n, d_q²=(2pi)^-1integral|1-zeta(s)sum a_n n^-s|²/|s|^(2q), one has d_q>=|C+2|/sqrtN−4pi²/(3^q sqrt5)N^-5/2.", "evidence": "audits/adversarial_reviews/weighted_selberg_round2.md Hilbert-space identity and shrinking interval", "status": "previously_independently_checked_scoped_lemma", "hypotheses": "N>=1, q>=1 integer, critical-line boundary measure dt/(2pi)."}','mathematical_claim','For any finite coefficient vector a_n supported1..N and fixed integerq>=1, C=sum a_n, d_q²=(2pi)^-1integral|1-zeta(s)sum a_n n^-s|²/|s|^(2q), one has d_q>=|C+2|/sqrtN−4pi²/(3^q sqrt5)N^-5/2.');
INSERT INTO "graph_nodes" VALUES('LEM-E-W304','graphs/knowledge_graph.jsonl',1414,'derived_cutoff_lemma_independent_review_pending','proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md§2','{"record_type": "node", "id": "LEM-E-W304", "type": "mathematical_claim", "label": "For fixedalpha>=0, Psi_alpha(x)=sum_(n<=x)mu(n)log(x/n)^alpha, one has |Psi_alpha(x)−Psi_alpha(floorx)|<=2 for0<alpha<1, <=1.5Gamma(alpha+1) foralpha>=1, and0 foralpha0 inclusive hard cutoff, when x>=2.", "evidence": "proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md§2", "status": "derived_cutoff_lemma_independent_review_pending", "hypotheses": "alpha fixedreal; alpha0 means inclusive ordinary summatory Möbius function; foralpha>0,0^alpha0."}','mathematical_claim','For fixedalpha>=0, Psi_alpha(x)=sum_(n<=x)mu(n)log(x/n)^alpha, one has |Psi_alpha(x)−Psi_alpha(floorx)|<=2 for0<alpha<1, <=1.5Gamma(alpha+1) foralpha>=1, and0 foralpha0 inclusive hard cutoff, when x>=2.');
INSERT INTO "graph_nodes" VALUES('LEM-E-W305','graphs/knowledge_graph.jsonl',1415,'classical_transform_independently_reconstructed; extension_application_review_pending','proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md§3','{"record_type": "node", "id": "LEM-E-W305", "type": "mathematical_claim", "label": "Foralpha>=0 real andRe(s)>1, integral_1^infty Psi_alpha(x)x^(-s-1)dx=Gamma(alpha+1)/(s^(alpha+1)zeta(s)), with principal Logs onRe(s)>0. A growth bound Psi=O(sqrtx(logx)^B), Bfixed, makes the left side analyticRe(s)>.5.", "evidence": "proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md§3", "status": "classical_transform_independently_reconstructed; extension_application_review_pending", "hypotheses": "alpha0 hard cutoff as above; initial sum-integral interchange absolutely convergent."}','mathematical_claim','Foralpha>=0 real andRe(s)>1, integral_1^infty Psi_alpha(x)x^(-s-1)dx=Gamma(alpha+1)/(s^(alpha+1)zeta(s)), with principal Logs onRe(s)>0. A growth bound Psi=O(sqrtx(logx)^B), Bfixed, makes the left side analyticRe(s)>.5.');
INSERT INTO "graph_nodes" VALUES('LEM-E-W306','graphs/knowledge_graph.jsonl',1416,'classical_product_consequence_reconstructed_pending_review','proposals/independent_campaigns/growing_logarithmic_riesz_round3.md§2','{"record_type": "node", "id": "LEM-E-W306", "type": "mathematical_claim", "label": "UnderRH, for0<epsilon<=1/8, |xi(.5+it)/xi(.5+epsilon+it)|<=1, and |zeta(.5+it)/zeta(.5+epsilon+it)|<=C(|t|+3)^(epsilon/2).", "evidence": "proposals/independent_campaigns/growing_logarithmic_riesz_round3.md§2", "status": "classical_product_consequence_reconstructed_pending_review", "hypotheses": "RH; multiplicities allowed; numerator zeros interpreted continuously."}','mathematical_claim','UnderRH, for0<epsilon<=1/8, |xi(.5+it)/xi(.5+epsilon+it)|<=1, and |zeta(.5+it)/zeta(.5+epsilon+it)|<=C(|t|+3)^(epsilon/2).');
INSERT INTO "graph_nodes" VALUES('LEM-E-W307','graphs/knowledge_graph.jsonl',1417,'derived_kernel_lemma_pending_independent_review','proposals/independent_campaigns/growing_logarithmic_riesz_round3.md(G1)–(G3)','{"record_type": "node", "id": "LEM-E-W307", "type": "mathematical_claim", "label": "Foralpha=epsilon L>=4,0<epsilon<=1,K(v)=Gamma(alpha+1)exp(alpha+iLv)/[2piL^alpha(epsilon+iv)^(alpha+1)] has complexmass1,L1<=3,and forfixedeta in(0,1],delta in(0,1/8], integral_|v|>etaepsilon |K(v)|(3+|v|)^delta dv<=C_delta sqrtalpha exp(-alpha log(1+eta²)/4).", "evidence": "proposals/independent_campaigns/growing_logarithmic_riesz_round3.md(G1)–(G3)", "status": "derived_kernel_lemma_pending_independent_review", "hypotheses": "Positivealpha,epsilon,L withalpha=epsilonL; principalLog onRew>0."}','mathematical_claim','Foralpha=epsilon L>=4,0<epsilon<=1,K(v)=Gamma(alpha+1)exp(alpha+iLv)/[2piL^alpha(epsilon+iv)^(alpha+1)] has complexmass1,L1<=3,and forfixedeta in(0,1],delta in(0,1/8], integral_|v|>etaepsilon |K(v)|(3+|v|)^delta dv<=C_delta sqrtalpha exp(-alpha log(1+eta²)/4).');
INSERT INTO "graph_nodes" VALUES('EXT-TITCH-1986-9.6A','graphs/knowledge_graph.jsonl',1418,'established_source_passage_targeted_read','Titchmarsh1986printedp217,Eq9.6.1;PDF113','{"record_type": "node", "id": "EXT-TITCH-1986-9.6A", "type": "mathematical_claim", "label": "At large positiveheight, zeta_prime/zeta(s)=sum_(|t-gamma|<=1)1/(s-rho)+O(logt), uniformly−1<=sigma<=2, excluding its actual poles.", "evidence": "Titchmarsh1986printedp217,Eq9.6.1;PDF113", "status": "established_source_passage_targeted_read", "hypotheses": "Zeros countedwithmultiplicity;sourceTheorem9.6(A);negativeheights byconjugation;smallheight extension separately reconstructed inapplication."}','mathematical_claim','At large positiveheight, zeta_prime/zeta(s)=sum_(|t-gamma|<=1)1/(s-rho)+O(logt), uniformly−1<=sigma<=2, excluding its actual poles.');
INSERT INTO "graph_nodes" VALUES('THM-E-W301','graphs/knowledge_graph.jsonl',1419,'proved_elementary_finite_bound','proposals/independent_campaigns/unit_circle_scalar_window_round3.md §§1–3','{"record_type": "node", "id": "THM-E-W301", "type": "mathematical_claim", "label": "For p=m, E<=C_m²/M+sum_(r=1..m-1)T_mr²/M²<=K_m/M, C_m=m binom(2m-1,m-1), T_mr=sum_(j=r+1..m)binom(m,j)(j-r)^m, K_m=C_m²+sum T_mr². Exact twisted finite-difference identity supplies cancellation and all bounds are uniform in roots/collisions.", "evidence": "proposals/independent_campaigns/unit_circle_scalar_window_round3.md §§1–3", "status": "proved_elementary_finite_bound", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics."}','mathematical_claim','For p=m, E<=C_m²/M+sum_(r=1..m-1)T_mr²/M²<=K_m/M, C_m=m binom(2m-1,m-1), T_mr=sum_(j=r+1..m)binom(m,j)(j-r)^m, K_m=C_m²+sum T_mr². Exact twisted finite-difference identity supplies cancellation and all bounds are uniform in roots/collisions.');
INSERT INTO "graph_nodes" VALUES('THM-E-W302','graphs/knowledge_graph.jsonl',1420,'proved_exact_finite_identity','proposals/independent_campaigns/unit_circle_scalar_window_round3.md §6','{"record_type": "node", "id": "THM-E-W302", "type": "mathematical_claim", "label": "For m=p=2, after common rotation Q=(1-z)(1-qz), E(1)-E(q)=2/M^4 sum_(k=1..M)(M-k+1)(2(M-k)+1)(1-Re(q^k))>=0. E(1)=4/M+3/M²-2/M³<=5/M; constant5 is sharp over all M, at M1 or2 and q1; complete coalescence is the unique maximum modulo common rotation.", "evidence": "proposals/independent_campaigns/unit_circle_scalar_window_round3.md §6", "status": "proved_exact_finite_identity", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics. Here m=p=2."}','mathematical_claim','For m=p=2, after common rotation Q=(1-z)(1-qz), E(1)-E(q)=2/M^4 sum_(k=1..M)(M-k+1)(2(M-k)+1)(1-Re(q^k))>=0. E(1)=4/M+3/M²-2/M³<=5/M; constant5 is sharp over all M, at M1 or2 and q1; complete coalescence is the unique maximum modulo common rotation.');
INSERT INTO "graph_nodes" VALUES('THM-E-W303','graphs/knowledge_graph.jsonl',1421,'proved_fixed_m_asymptotic','proposals/independent_campaigns/unit_circle_scalar_window_round3.md §4','{"record_type": "node", "id": "THM-E-W303", "type": "mathematical_claim", "label": "At complete coalescence Q=(1-qz)^m and p=m, E=m²/M+O_m(M^-2). Thus this prescribed scalar window has the same leading m² as the known optimal approximation; exact finite optimality is not asserted.", "evidence": "proposals/independent_campaigns/unit_circle_scalar_window_round3.md §4", "status": "proved_fixed_m_asymptotic", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics. Complete coalescence; p=m."}','mathematical_claim','At complete coalescence Q=(1-qz)^m and p=m, E=m²/M+O_m(M^-2). Thus this prescribed scalar window has the same leading m² as the known optimal approximation; exact finite optimality is not asserted.');
INSERT INTO "graph_nodes" VALUES('THM-E-W304','graphs/knowledge_graph.jsonl',1422,'proved_real_taper_threshold','proposals/independent_campaigns/fractional_scalar_threshold_round3.md §§1–4','{"record_type": "node", "id": "THM-E-W304", "type": "mathematical_claim", "label": "A collision-uniform E<=C_(m,p)/M for every M and all roots exists iff p>m-1/2. At equality E=O_m((1+logM)/M) uniformly and complete coalescence gives Ω_m(logM/M). For p<m-1/2 the exact terminal coefficient at coalescence rules out O(1/M).", "evidence": "proposals/independent_campaigns/fractional_scalar_threshold_round3.md §§1–4", "status": "proved_real_taper_threshold", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics. p>=0 real."}','mathematical_claim','A collision-uniform E<=C_(m,p)/M for every M and all roots exists iff p>m-1/2. At equality E=O_m((1+logM)/M) uniformly and complete coalescence gives Ω_m(logM/M). For p<m-1/2 the exact terminal coefficient at coalescence rules out O(1/M).');
INSERT INTO "graph_nodes" VALUES('THM-E-W305','graphs/knowledge_graph.jsonl',1423,'proved_fixed_m_critical_asymptotic','proposals/independent_campaigns/fractional_scalar_critical_constant_round3.md','{"record_type": "node", "id": "THM-E-W305", "type": "mathematical_claim", "label": "At complete coalescence and critical real power p=m-1/2, E=kappa_m² logM/M+O_m(1/M), kappa_m=m binom(2m,m)/4^m.", "evidence": "proposals/independent_campaigns/fractional_scalar_critical_constant_round3.md", "status": "proved_fixed_m_critical_asymptotic", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics. Complete coalescence; p=m-1/2."}','mathematical_claim','At complete coalescence and critical real power p=m-1/2, E=kappa_m² logM/M+O_m(1/M), kappa_m=m binom(2m,m)/4^m.');
INSERT INTO "graph_nodes" VALUES('THM-E-W306','graphs/knowledge_graph.jsonl',1424,'derived_exact_finite_case_independent_review_pending','proposals/independent_campaigns/scalar_window_coalescence_maximum_round3.md §Exact three-root example','{"record_type": "node", "id": "THM-E-W306", "type": "mathematical_claim", "label": "For m=p=3,M=2, write Delta=product_(i<j)|q_i-q_j|². Then E(coalesced)-E(qs)=[31 sum_(i<j)|q_i-q_j|²+Delta]/32>=0. Equality iff all roots equal.", "evidence": "proposals/independent_campaigns/scalar_window_coalescence_maximum_round3.md §Exact three-root example", "status": "derived_exact_finite_case_independent_review_pending", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics. m=p=3,M=2 only."}','mathematical_claim','For m=p=3,M=2, write Delta=product_(i<j)|q_i-q_j|². Then E(coalesced)-E(qs)=[31 sum_(i<j)|q_i-q_j|²+Delta]/32>=0. Equality iff all roots equal.');
INSERT INTO "graph_nodes" VALUES('THM-E-W307','graphs/knowledge_graph.jsonl',1425,'derived_necessary_condition_independent_review_pending','proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §§1–3','{"record_type": "node", "id": "THM-E-W307", "type": "mathematical_claim", "label": "If d_q(V_(N,alpha))->0, RH holds and every nontrivial zero multiplicity satisfies m<alpha+1. Thus alpha0 convergence is impossible; for alpha>0, m<=ceil(alpha). Real-cutoff interpolation |Psi_alpha(x)-Psi_alpha(floor x)|=O_alpha(1) is valid even for0<alpha<1.", "evidence": "proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §§1–3", "status": "derived_necessary_condition_independent_review_pending", "hypotheses": "Fixed alpha>=0 real, fixed integer q>=1, integer N>=2; V=sum_(n<=N)mu(n)(1-logn/logN)^alpha n^-s; alpha0 uses inclusive hard cutoff; d_q²=(2pi)^-1 integral_R |1-zeta(.5+it)V(.5+it)|²/|.5+it|^(2q)dt. Full-sequence convergence, not merely a subsequence."}','mathematical_claim','If d_q(V_(N,alpha))->0, RH holds and every nontrivial zero multiplicity satisfies m<alpha+1. Thus alpha0 convergence is impossible; for alpha>0, m<=ceil(alpha). Real-cutoff interpolation |Psi_alpha(x)-Psi_alpha(floor x)|=O_alpha(1) is valid even for0<alpha<1.');
INSERT INTO "graph_nodes" VALUES('THM-E-W308','graphs/knowledge_graph.jsonl',1426,'derived_quantitative_necessary_condition_independent_review_pending','proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §4','{"record_type": "node", "id": "THM-E-W308", "type": "mathematical_claim", "label": "For every critical zero rho of multiplicitym, limsup_N d_q(V_(N,alpha))/(logN)^(m-alpha-1)>=m Gamma(alpha+1)/[|rho|^(alpha+1)|zeta^(m)(rho)|]. Infinite limsup is allowed; finite limsup itself supplies the zero-free open half-plane needed for the Mellin argument.", "evidence": "proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §4", "status": "derived_quantitative_necessary_condition_independent_review_pending", "hypotheses": "Fixed alpha>=0 real, fixed integer q>=1, integer N>=2; V=sum_(n<=N)mu(n)(1-logn/logN)^alpha n^-s; alpha0 uses inclusive hard cutoff; d_q²=(2pi)^-1 integral_R |1-zeta(.5+it)V(.5+it)|²/|.5+it|^(2q)dt. Full-sequence convergence, not merely a subsequence. rho=1/2+i gamma a zero of multiplicitym>=1."}','mathematical_claim','For every critical zero rho of multiplicitym, limsup_N d_q(V_(N,alpha))/(logN)^(m-alpha-1)>=m Gamma(alpha+1)/[|rho|^(alpha+1)|zeta^(m)(rho)|]. Infinite limsup is allowed; finite limsup itself supplies the zero-free open half-plane needed for the Mellin argument.');
INSERT INTO "graph_nodes" VALUES('THM-E-W309','graphs/knowledge_graph.jsonl',1427,'classical_source_specialization','PAPER-M002 Theorem39/Lemma10 p50 and shifted Eq(2)p51; campaign Eq(7)','{"record_type": "node", "id": "THM-E-W309", "type": "mathematical_claim", "label": "For alpha>0,L=logN, and c>max(0,1-Re(s)), V_(N,alpha)(s)=Gamma(alpha+1)/(2pi i L^alpha) integral_(Re w=c) exp(Lw)/[w^(alpha+1)zeta(s+w)]dw; principal Logw on Rew>0, absolutely convergent initial line, endpoint n=N contributes0.", "evidence": "PAPER-M002 Theorem39/Lemma10 p50 and shifted Eq(2)p51; campaign Eq(7)", "status": "classical_source_specialization", "hypotheses": "Fixed alpha>=0 real, fixed integer q>=1, integer N>=2; V=sum_(n<=N)mu(n)(1-logn/logN)^alpha n^-s; alpha0 uses inclusive hard cutoff; d_q²=(2pi)^-1 integral_R |1-zeta(.5+it)V(.5+it)|²/|.5+it|^(2q)dt. Full-sequence convergence, not merely a subsequence. alpha>0 and initial contour c>max(0,1-Re(s))."}','mathematical_claim','For alpha>0,L=logN, and c>max(0,1-Re(s)), V_(N,alpha)(s)=Gamma(alpha+1)/(2pi i L^alpha) integral_(Re w=c) exp(Lw)/[w^(alpha+1)zeta(s+w)]dw; principal Logw on Rew>0, absolutely convergent initial line, endpoint n=N contributes0.');
INSERT INTO "graph_nodes" VALUES('THM-E-W310','graphs/knowledge_graph.jsonl',1428,'derived_finite_convergence_threshold_independent_review_pending','proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §5; fractional_scalar_threshold_round3.md §§1–3','{"record_type": "node", "id": "THM-E-W310", "type": "mathematical_claim", "label": "The supremum over all unit-root configurations of E_(M,p) tends to0 iff p>m-1. For m-1<p<m-1/2, E=O_(m,p)(M^(-2(p-m+1))); at p=m-1/2, O_m(logM/M); above it, O_(m,p)(1/M). At p<=m-1 complete coalescence terminal coefficient prevents convergence.", "evidence": "proposals/independent_campaigns/logarithmic_riesz_multiplicity_round3.md §5; fractional_scalar_threshold_round3.md §§1–3", "status": "derived_finite_convergence_threshold_independent_review_pending", "hypotheses": "m>=1 integer, M>=1 integer; Q(z)=product_j(1-q_j z), |q_j|=1 with repetitions/arbitrary M-dependence allowed; b_n=[z^n]Q^-1; A_(M,p)=sum_(n=0..M-1)b_n(1-n/M)^p z^n; E=||1-QA||² in standard normalized H²; m,p fixed in asymptotics. p>=0 real; uniformity only for fixedm,p."}','mathematical_claim','The supremum over all unit-root configurations of E_(M,p) tends to0 iff p>m-1. For m-1<p<m-1/2, E=O_(m,p)(M^(-2(p-m+1))); at p=m-1/2, O_m(logM/M); above it, O_(m,p)(1/M). At p<=m-1 complete coalescence terminal coefficient prevents convergence.');
INSERT INTO "graph_nodes" VALUES('THM-E-W312','graphs/knowledge_graph.jsonl',1429,'adjudicated_scoped_conditional_or_model_theorem','proposals/independent_campaigns/growing_logarithmic_riesz_round3.md (G1)–(G6)','{"record_type": "node", "id": "THM-E-W312", "type": "mathematical_claim", "label": "For EVERY fixedc>0 and integerq>=1, RH implies d_q(V_(N,c))->0 for the prescribed Mobius array with epsilon_N=c/loglogN and logarithmic Riesz orderalpha_N=epsilon_N logN; the arbitrary-finite-array Hardy witness proves the converse. Thus convergence is equivalent to RH for each fixedc. No spacing, simplicity or derivative-moment hypothesis. Constants/N0 may dependonc,q; no movingc_N orq_N claim.", "evidence": "proposals/independent_campaigns/growing_logarithmic_riesz_round3.md (G1)–(G6)", "status": "adjudicated_scoped_conditional_or_model_theorem", "hypotheses": "RH for forward direction; sufficiently large integersN; alpha_N>0, endpointn=N weight0; fixedc>0,q>=1integer; sourced classical RH inverse/log-derivative inputs; freeauxiliary finite-height exponentr chosenafterfixedc."}','mathematical_claim','For EVERY fixedc>0 and integerq>=1, RH implies d_q(V_(N,c))->0 for the prescribed Mobius array with epsilon_N=c/loglogN and logarithmic Riesz orderalpha_N=epsilon_N logN; the arbitrary-finite-array Hardy witness proves the converse. Thus convergence is equivalent to RH for each fixedc. No spacing, simplicity or derivative-moment hypothesis. Constants/N0 may dependonc,q; no movingc_N orq_N claim.');
INSERT INTO "graph_nodes" VALUES('THM-E-W313','graphs/knowledge_graph.jsonl',1430,'adjudicated_scoped_conditional_or_model_theorem','proposals/independent_campaigns/growing_logarithmic_riesz_rate_round3.md(QR1)–(QR6)','{"record_type": "node", "id": "THM-E-W313", "type": "mathematical_claim", "label": "UnderRH, forEACHfixedc>0,epsilon_N=c/loglogN,alpha_N=epsilon_N logN,andtheprescribedgrowinglogarithmicV_N, weightednorm||zeta(s)V_N(s)−zeta(s)/zeta(s+epsilon_N)||_q<=C_(q,c)[alpha_N^-1/2+sqrtalpha_N exp(−kappa alpha_N/2)], hence d_q(V_N)=O_(q,c)((loglogN)^−1/3) andsquarednormO((loglogN)^−2/3).", "evidence": "proposals/independent_campaigns/growing_logarithmic_riesz_rate_round3.md(QR1)–(QR6)", "status": "adjudicated_scoped_conditional_or_model_theorem", "hypotheses": "RH; fixedintegerq>=1,fixedc>0; Nlargeparameterdependent; freeauxiliaryrfromW312chosenwithstrictpositivekerneldecaymargin; noextra simplicity/spacing/derivativemomentassumption. Constantsnotuniformasc->0,qgrowing."}','mathematical_claim','UnderRH, forEACHfixedc>0,epsilon_N=c/loglogN,alpha_N=epsilon_N logN,andtheprescribedgrowinglogarithmicV_N, weightednorm||zeta(s)V_N(s)−zeta(s)/zeta(s+epsilon_N)||_q<=C_(q,c)[alpha_N^-1/2+sqrtalpha_N exp(−kappa alpha_N/2)], hence d_q(V_N)=O_(q,c)((loglogN)^−1/3) andsquarednormO((loglogN)^−2/3).');
INSERT INTO "graph_nodes" VALUES('THM-E-W314','graphs/knowledge_graph.jsonl',1431,'adjudicated_scoped_conditional_or_function_space_theorem','audits/balazard_roton_ratio_round3.md(BR1)–(BR3); PAPER-C103Prop2,Props4–5proofpp5–8','{"record_type": "node", "id": "THM-E-W314", "type": "mathematical_claim", "label": "UnderRH, forEACHfixedc>0 andfixedintegerq>=1, theprescribedgrowinglogarithmicarrayV_N withalpha_N=c logN/loglogN satisfiesd_q(V_N)=O_(q,c)((loglogN)^−1/2), squarednormO_(q,c)(1/loglogN).", "evidence": "audits/balazard_roton_ratio_round3.md(BR1)–(BR3); PAPER-C103Prop2,Props4–5proofpp5–8", "status": "adjudicated_scoped_conditional_or_function_space_theorem", "hypotheses": "Samearray,full-heightnorm,branchandfixedparameterconditionsasW312–313. UsesEXACTclassicalBalazard–deRotonhorizontalratioJ_epsilon≪epsilon,0<epsilon<=1/2; no spacing,simplicity,orzero-derivativemomenthypothesis. Constantsnotuniformforc_N->0orq_Ngrowing."}','mathematical_claim','UnderRH, forEACHfixedc>0 andfixedintegerq>=1, theprescribedgrowinglogarithmicarrayV_N withalpha_N=c logN/loglogN satisfiesd_q(V_N)=O_(q,c)((loglogN)^−1/2), squarednormO_(q,c)(1/loglogN).');
INSERT INTO "graph_nodes" VALUES('THM-ADAPTIVE-SELBERG-OPT','graphs/knowledge_graph.jsonl',1432,'adjudicated_scoped_fixed_function_GRH_conditional_theorem','audits/adversarial_reviews/director_selberg_transfer_round6.md andnamedcompleteproofs','{"record_type": "node", "id": "THM-ADAPTIVE-SELBERG-OPT", "type": "mathematical_claim", "label": "LetF be one fixed Selberg-class function and assumeF(s) hasnozerosforRe(s)>1/2,withitsactualfinitepoleat1permitted. ForDelta_(N,F)^2=inf_{A=sum_{n<=N}a_n n^-s,allcomplexcoefficients}(2pi)^(-1)integral_R|1-F(1/2+it)A(1/2+it)|²/(1/4+t²)dt, lim_N(logN)Delta_(N,F)^2=sum_{distinctnontrivialrhoofF}m_rho²/|rho|². Include allsignedordinatesandpossiblecentralzero.", "evidence": "audits/adversarial_reviews/director_selberg_transfer_round6.md andnamedcompleteproofs", "status": "adjudicated_scoped_fixed_function_GRH_conditional_theorem", "claim_kind": "proved_source_based_fixed_Selberg_function_transplant", "hypotheses": "SelbergaxiomsincludingordinaryintegerDirichletseries,finitegamma/poledata,RamanujanandEulerlogprimepowerexponent<1/2; statedzero-free-half-planeGRHincludingboundaryconvention. Everyfunctionparameterfixed. Noanchoringconstraintorprescribedcoefficientarray.", "verification_scope": "Complete explicitupperinterface,degreebudgetanddistributionalMellinlowerreconstruction,independentproponent/skeptic/witness/director. PublisheddeRotonlowerandversionedRST048upperancestryretained. No whole-paperpromotion,uniformdegree/conductor/effectivityorpublicationnoveltyclaim."}','mathematical_claim','LetF be one fixed Selberg-class function and assumeF(s) hasnozerosforRe(s)>1/2,withitsactualfinitepoleat1permitted. ForDelta_(N,F)^2=inf_{A=sum_{n<=N}a_n n^-s,allcomplexcoefficients}(2pi)^(-1)integral_R|1-F(1/2+it)A(1/2+it)|²/(1/4+t²)dt, lim_N(logN)Delta_(N,F)^2=sum_{distinctnontrivialrhoofF}m_rho²/|rho|². Include allsignedordinatesandpossiblecentralzero.');
INSERT INTO "graph_nodes" VALUES('LEM-SELBERG-COMPLEMENT-L2','graphs/knowledge_graph.jsonl',1433,'adjudicated_scoped_GRH_conditional_lemma','audits/adversarial_reviews/director_selberg_transfer_round6.md §2; independentlyderivedtestedMellinproofs','{"record_type": "node", "id": "LEM-SELBERG-COMPLEMENT-L2", "type": "mathematical_claim", "label": "ForfixedSelbergFunderthestatedGRH, definepsi_F(t)=Res_(s=1)[F(s)t^-s/s]-sum_{n<=1/t}a_n forallt>0. Thenpsi_FisinL²(dt)anditscritical-lineL²Mellintransformis-F(s)/s. Acompactlog-testcontourshiftandGRHsubpowerboundproveitatarbitraryfixeddegree/poleorder. Theresiduetailfort>1mustberetained.", "evidence": "audits/adversarial_reviews/director_selberg_transfer_round6.md §2; independentlyderivedtestedMellinproofs", "status": "adjudicated_scoped_GRH_conditional_lemma", "claim_kind": "proved_conditional_distributional_Mellin_identification"}','mathematical_claim','ForfixedSelbergFunderthestatedGRH, definepsi_F(t)=Res_(s=1)[F(s)t^-s/s]-sum_{n<=1/t}a_n forallt>0. Thenpsi_FisinL²(dt)anditscritical-lineL²Mellintransformis-F(s)/s. Acompactlog-testcontourshiftandGRHsubpowerboundproveitatarbitraryfixeddegree/poleorder. Theresiduetailfort>1mustberetained.');
INSERT INTO "graph_nodes" VALUES('THM-C101-Q4','graphs/knowledge_graph.jsonl',1434,'source_open_question_1998','§5 Question4, printedp7','{"record_type": "node", "id": "THM-C101-Q4", "type": "mathematical_claim", "label": "Assuming RH, does η_N²=(1/2π)∫|1−ζ(1/2+it)Σ_{n≤N}μ(n)(1−logn/logN)n^(−1/2−it)|²dt/(1/4+t²) tend to0?", "evidence": "§5 Question4, printedp7", "status": "source_open_question_1998"}','mathematical_claim','Assuming RH, does η_N²=(1/2π)∫|1−ζ(1/2+it)Σ_{n≤N}μ(n)(1−logn/logN)n^(−1/2−it)|²dt/(1/4+t²) tend to0?');
INSERT INTO "graph_nodes" VALUES('THM-C103-P1P3','graphs/knowledge_graph.jsonl',1435,'established_source_result','Propositions1–3, printedpp4–5','{"record_type": "node", "id": "THM-C103-P1P3", "type": "mathematical_claim", "label": "UnderRH the shifted-array squared error ν_(N,ε) is at most2I_(N,ε)+2J_ε, with J_ε≪ε and I_(N,ε)≪N^(−ε/2) for ε≥25(loglogN)^(5/2+δ)(logN)^(−1/2), N≥N0(δ).", "evidence": "Propositions1–3, printedpp4–5", "status": "established_source_result", "hypotheses": ["δ>0 fixed", "ε>0", "RH for bounds on I and J"]}','mathematical_claim','UnderRH the shifted-array squared error ν_(N,ε) is at most2I_(N,ε)+2J_ε, with J_ε≪ε and I_(N,ε)≪N^(−ε/2) for ε≥25(loglogN)^(5/2+δ)(logN)^(−1/2), N≥N0(δ).');
INSERT INTO "graph_nodes" VALUES('THM-C105-1','graphs/knowledge_graph.jsonl',1436,'established_source_result','Proposition1.9 p7; proofpp27–28; Remark5.8p29','{"record_type": "node", "id": "THM-C105-1", "type": "mathematical_claim", "label": "For the prescribed Selberg V_N(s)=Σ_{n≤N}μ(n)(1−logn/logN)n^(−s), if η_N²=(1/2π)∫_R|1−ζ(1/2+it)V_N(1/2+it)|²dt/(1/4+t²) tends to0, then RH holds and every nontrivial zero of ζ is simple.", "evidence": "Proposition1.9 p7; proofpp27–28; Remark5.8p29", "status": "established_source_result", "hypotheses": ["N→∞ through positive integers", "full critical-line integral, not truncated", "exact fixed coefficient array"]}','mathematical_claim','For the prescribed Selberg V_N(s)=Σ_{n≤N}μ(n)(1−logn/logN)n^(−s), if η_N²=(1/2π)∫_R|1−ζ(1/2+it)V_N(1/2+it)|²dt/(1/4+t²) tends to0, then RH holds and every nontrivial zero of ζ is simple.');
INSERT INTO "graph_nodes" VALUES('THM-C105-2','graphs/knowledge_graph.jsonl',1437,'established_source_result','Theorem1.10 p7','{"record_type": "node", "id": "THM-C105-2", "type": "mathematical_claim", "label": "RH iff the same prescribed Selberg error integral on every fixed vertical line Re(s)=τ′ with1/2<τ′<1 tends to0. Boundedness of the full boundary-line prescribed error sequence impliesRH.", "evidence": "Theorem1.10 p7", "status": "established_source_result"}','mathematical_claim','RH iff the same prescribed Selberg error integral on every fixed vertical line Re(s)=τ′ with1/2<τ′<1 tends to0. Boundedness of the full boundary-line prescribed error sequence impliesRH.');
INSERT INTO "graph_nodes" VALUES('LEM-C105-U','graphs/knowledge_graph.jsonl',1438,'independently_reconstructed_prior_method','independent reconstruction in audits/selberg_provenance_round2.md, consistent with Wei–Wu unitaryproofpp27–28 and Conrey–MyersonProp1','{"record_type": "node", "id": "LEM-C105-U", "type": "mathematical_claim", "label": "For real finite coefficients b_n and A(s)=Σb_n n^(−s), define W(u)=Σb_n{nu}/n and g(u)=−sin(2πu)/π. Then ||(1−ζA)/s||²_(critical line,d t/2π)=||W−g||²_(L²(du/u²)).", "evidence": "independent reconstruction in audits/selberg_provenance_round2.md, consistent with Wei–Wu unitaryproofpp27–28 and Conrey–MyersonProp1", "status": "independently_reconstructed_prior_method"}','mathematical_claim','For real finite coefficients b_n and A(s)=Σb_n n^(−s), define W(u)=Σb_n{nu}/n and g(u)=−sin(2πu)/π. Then ||(1−ζA)/s||²_(critical line,d t/2π)=||W−g||²_(L²(du/u²)).');
INSERT INTO "graph_nodes" VALUES('LEM-C105-Q1','graphs/knowledge_graph.jsonl',1439,'derived_elementary_corollary_no_novelty_claim','derived quantitative corollaries in audits/selberg_provenance_round2.md','{"record_type": "node", "id": "LEM-C105-Q1", "type": "mathematical_claim", "label": "For fixed Selberg error η_N and C_N=Σμ(n)(1−logn/logN), η_N≥|C_N+2|/sqrtN−4π²/(3sqrt5)N^(−5/2). If a critical-line zeroρ has multiplicitym≥2, limsup η_N/(logN)^(m−2)≥m/(|ρ|²|ζ^(m)(ρ)|).", "evidence": "derived quantitative corollaries in audits/selberg_provenance_round2.md", "status": "derived_elementary_corollary_no_novelty_claim"}','mathematical_claim','For fixed Selberg error η_N and C_N=Σμ(n)(1−logn/logN), η_N≥|C_N+2|/sqrtN−4π²/(3sqrt5)N^(−5/2). If a critical-line zeroρ has multiplicitym≥2, limsup η_N/(logN)^(m−2)≥m/(|ρ|²|ζ^(m)(ρ)|).');
INSERT INTO "graph_nodes" VALUES('THM-E-W311','graphs/knowledge_graph.jsonl',1440,'independent_review_passed_director_adjudication_pending','proposals/independent_campaigns/coalescence_maximum_semantic_round3.md §1','{"record_type": "node", "id": "THM-E-W311", "type": "mathematical_claim", "label": "E<=363/8, attained iff all four factors coincide. In fact363/8-E=(16-|e1|^2)(131-7|e1|^2)/128+(36-|e2|^2)(3/4+|e1|^2/256)+(16-|sum_j qj^2|^2)/16, and all terms are nonnegative.", "evidence": "proposals/independent_campaigns/coalescence_maximum_semantic_round3.md §1", "status": "independent_review_passed_director_adjudication_pending", "hypotheses": "Four complex unit factors q1,...,q4, with arbitrary collisions; Q=product(1-qj z); b_n=[z^n]1/Q; M=2 and integer taper powerp=4, A=1+(q1+...+q4)z/16; E=||1-QA||_H2^2 with normalized coefficient-square norm."}','mathematical_claim','E<=363/8, attained iff all four factors coincide. In fact363/8-E=(16-|e1|^2)(131-7|e1|^2)/128+(36-|e2|^2)(3/4+|e1|^2/256)+(16-|sum_j qj^2|^2)/16, and all terms are nonnegative.');
INSERT INTO "graph_nodes" VALUES('THM-SG309','graphs/knowledge_graph.jsonl',1441,'adjudicated_scoped_conditional_or_model_theorem','["proposals/independent_campaigns/sine_gram_moment_existence_round4.md", "audits/adversarial_reviews/sine_gram_moment_existence_third_round3.md", "audits/adversarial_reviews/sine_gram_skeptic_round4.md"]','{"record_type": "node", "id": "THM-SG309", "type": "mathematical_claim", "label": "For the unit-intensity sine determinantal point process with kernel k(x)=sin(pi*x)/(pi*x), S_R its sinc-Gram matrix on [0,R], and mu_R=R^(-1) E sum_j delta_(lambda_j(S_R)), every fixed nonnegative integer moment has a finite limit as R tends to infinity. These limits have the absolutely convergent anchored partition-integral formula in the cited proof. The deterministic expected per-length laws mu_R consequently converge weakly to a unique probability law, which has no atom at zero, is moment determinate, and has a positive exponential moment.", "evidence": ["proposals/independent_campaigns/sine_gram_moment_existence_round4.md", "audits/adversarial_reviews/sine_gram_moment_existence_third_round3.md", "audits/adversarial_reviews/sine_gram_skeptic_round4.md"], "status": "adjudicated_scoped_conditional_or_model_theorem", "hypotheses": "Stationary sine DPP on the full real line; intensity one; expected per-length law, not random point-count normalization. Moment order is fixed before R tends to infinity. No arithmetic moment-matching hypothesis is established."}','mathematical_claim','For the unit-intensity sine determinantal point process with kernel k(x)=sin(pi*x)/(pi*x), S_R its sinc-Gram matrix on [0,R], and mu_R=R^(-1) E sum_j delta_(lambda_j(S_R)), every fixed nonnegative integer moment has a finite limit as R tends to infinity. These limits have the absolutely convergent anchored partition-integral formula in the cited proof. The deterministic expected per-length laws mu_R consequently converge weakly to a unique probability law, which has no atom at zero, is moment determinate, and has a positive exponential moment.');
INSERT INTO "graph_nodes" VALUES('THM-SG301','graphs/knowledge_graph.jsonl',1442,'adjudicated_scoped_conditional_or_model_theorem','["proposals/independent_campaigns/sine_gram_all_moments_round3.md §2"]','{"record_type": "node", "id": "THM-SG301", "type": "mathematical_claim", "label": "For finiteY and PW_[−1/2,1/2] Gram matrix G_Y, a reproducing convolution phi gives TrG_Y^j<=||phi||1^j int(sum_Y|phi(x−t)|)^jdt, integerj>=1.", "evidence": ["proposals/independent_campaigns/sine_gram_all_moments_round3.md §2"], "status": "adjudicated_scoped_conditional_or_model_theorem", "hypotheses": "phihat=1 on band, phi inL1∩Linfty, jinteger; minmax+scalarJensen+Bessel, no matrixpower-monotonicity claim."}','mathematical_claim','For finiteY and PW_[−1/2,1/2] Gram matrix G_Y, a reproducing convolution phi gives TrG_Y^j<=||phi||1^j int(sum_Y|phi(x−t)|)^jdt, integerj>=1.');
INSERT INTO "graph_nodes" VALUES('THM-SG302','graphs/knowledge_graph.jsonl',1443,'adjudicated_scoped_conditional_or_model_theorem','["THM-SG301", "PAPER-SG001 Eq1.5,1.20,2.35", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §§3–4"]','{"record_type": "node", "id": "THM-SG302", "type": "mathematical_claim", "label": "For unit-intensity sine DPP GramG_R over[0,R], ETrG_R^j/R<=4^j j! for everyintegerj>=1,R>0. Every weak expected-law subsequential limit has an exponential moment and is moment determinate.", "evidence": ["THM-SG301", "PAPER-SG001 Eq1.5,1.20,2.35", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §§3–4"], "status": "adjudicated_scoped_conditional_or_model_theorem", "hypotheses": "SineDPP rho_l=det(sincpi differences), PW bandlength1; expected law normalizedbylengthR. Full moment-limit or IDS existence not assumed."}','mathematical_claim','For unit-intensity sine DPP GramG_R over[0,R], ETrG_R^j/R<=4^j j! for everyintegerj>=1,R>0. Every weak expected-law subsequential limit has an exponential moment and is moment determinate.');
INSERT INTO "graph_nodes" VALUES('THM-SG303','graphs/knowledge_graph.jsonl',1444,'adjudicated_scoped_conditional_or_model_theorem','["PAPER-SG002 Theorem3,p7; PW definitionspp5–6", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §5"]','{"record_type": "node", "id": "THM-SG303", "type": "mathematical_claim", "label": "Every weak subsequential limit of mu_R=(1/R)E sum_eigen(G_R)delta_lambda has no atom at0.", "evidence": ["PAPER-SG002 Theorem3,p7; PW definitionspp5–6", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §5"], "status": "adjudicated_scoped_conditional_or_model_theorem", "hypotheses": "Sine point process onone infinite configuration; globally removeclosepoints andcap fixedblocks; classical separatedD+<1 PW²interpolation theorem. Perconfiguration Riesz lower bound may vary; deterministic quantile handles averaging."}','mathematical_claim','Every weak subsequential limit of mu_R=(1/R)E sum_eigen(G_R)delta_lambda has no atom at0.');
INSERT INTO "graph_nodes" VALUES('THM-SG304','graphs/knowledge_graph.jsonl',1445,'adjudicated_scoped_conditional_or_model_theorem','["THM-SG302", "THM-SG303", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §6", "audits/adversarial_reviews/christoffel_independent_third_round3.md regular quadrature proof"]','{"record_type": "node", "id": "THM-SG304", "type": "mathematical_claim", "label": "For any weak expected-law subsequential limitmu above, lambda_m(0;mu) decreases to0. In the infinite-support case, each minimum-square polynomial hasm distinct positive roots and supplies a valid1−p_m² one-sided positive-mass certificate.", "evidence": ["THM-SG302", "THM-SG303", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §6", "audits/adversarial_reviews/christoffel_independent_third_round3.md regular quadrature proof"], "status": "adjudicated_scoped_conditional_or_model_theorem", "hypotheses": "mu Stieltjes, exponential-moment determinate, mu({0})0 asSG302–303. Finite positive-support case handled separately by annihilating polynomial."}','mathematical_claim','For any weak expected-law subsequential limitmu above, lambda_m(0;mu) decreases to0. In the infinite-support case, each minimum-square polynomial hasm distinct positive roots and supplies a valid1−p_m² one-sided positive-mass certificate.');
INSERT INTO "graph_nodes" VALUES('THM-SG305','graphs/knowledge_graph.jsonl',1446,'adjudicated_scoped_conditional_or_model_theorem','["THM-SG304", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §7", "audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md"]','{"record_type": "node", "id": "THM-SG305", "type": "mathematical_claim", "label": "If a Hermitian family has every fixed momentprefix converge to one such sineGram law, then its positive-index fraction tends1. The conclusion transfers to a same-dimension exact-block family at Hilbert–Schmidt erroro(sqrt(d)); with s1>=2n+(block)−N+oN,d~N, the simple-on-line fraction tends1.", "evidence": ["THM-SG304", "proposals/independent_campaigns/sine_gram_all_moments_round3.md §7", "audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md"], "status": "adjudicated_scoped_conditional_or_model_theorem", "hypotheses": "All fixed momentprefixes forone sequence, matching exactbandwidth/densitynormalization; no uniformm(T) estimate needed. ArithmeticHL* hypotheses not supplied."}','mathematical_claim','If a Hermitian family has every fixed momentprefix converge to one such sineGram law, then its positive-index fraction tends1. The conclusion transfers to a same-dimension exact-block family at Hilbert–Schmidt erroro(sqrt(d)); with s1>=2n+(block)−N+oN,d~N, the simple-on-line fraction tends1.');
INSERT INTO "graph_nodes" VALUES('THM-SG306','graphs/knowledge_graph.jsonl',1447,'adjudicated_scoped_conditional_or_model_theorem','["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §§1–2", "audits/adversarial_reviews/zero_buffer_weaklaw_third_round3.md"]','{"record_type": "node", "id": "THM-SG306", "type": "mathematical_claim", "label": "For same-dimension HermitianF,G, boundedLipschitz normalizedtrace difference<=Lip(h)||F−G||HS/sqrt(d). Hence HSerroro(sqrt(d)) transfers weakempirical spectral limits, even if highermoments do not transfer.", "evidence": ["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §§1–2", "audits/adversarial_reviews/zero_buffer_weaklaw_third_round3.md"], "status": "adjudicated_scoped_conditional_or_model_theorem", "hypotheses": "Hermitian, same dimension; sorted real eigenvalues. Fixed boundedLipschitztest. Higher polynomial moments may change arbitrarily."}','mathematical_claim','For same-dimension HermitianF,G, boundedLipschitz normalizedtrace difference<=Lip(h)||F−G||HS/sqrt(d). Hence HSerroro(sqrt(d)) transfers weakempirical spectral limits, even if highermoments do not transfer.');
INSERT INTO "graph_nodes" VALUES('THM-SG307','graphs/knowledge_graph.jsonl',1448,'adjudicated_scoped_conditional_or_model_theorem','["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §3", "audits/adversarial_reviews/hs_clipped_certificate_skeptic_round4.md", "audits/adversarial_reviews/zero_buffer_clipped_moment_third_round3.md"]','{"record_type": "node", "id": "THM-SG307", "type": "mathematical_claim", "label": "For a fixed real polynomialq<=indicator_(0,infty), h=max(q,−1) is a bounded globally Lipschitz minorant withh>=q. Thus n+(G)/d>=Trq(F)/d−Lip(h)||F−G||HS/sqrt(d) for arbitrary same-dimension HermitianF,G.", "evidence": ["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §3", "audits/adversarial_reviews/hs_clipped_certificate_skeptic_round4.md", "audits/adversarial_reviews/zero_buffer_clipped_moment_third_round3.md"], "status": "adjudicated_scoped_conditional_or_model_theorem", "hypotheses": "Global one-sided polynomialminorant, fixedq. No highermoment transfer oroperatornormsmall condition. Growingdegree/Lipschitz requires extra control."}','mathematical_claim','For a fixed real polynomialq<=indicator_(0,infty), h=max(q,−1) is a bounded globally Lipschitz minorant withh>=q. Thus n+(G)/d>=Trq(F)/d−Lip(h)||F−G||HS/sqrt(d) for arbitrary same-dimension HermitianF,G.');
INSERT INTO "graph_nodes" VALUES('THM-SG308','graphs/knowledge_graph.jsonl',1449,'adjudicated_scoped_conditional_or_model_theorem','["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §4", "experiments/code/hs_clipped_certificate_round3.py", "experiments/results/hs_clipped_certificate_round3.json", "audits/adversarial_reviews/hs_clipped_certificate_skeptic_round4.md", "audits/adversarial_reviews/zero_buffer_clipped_moment_third_round3.md"]','{"record_type": "node", "id": "THM-SG308", "type": "mathematical_claim", "label": "Forq=(7/2)x−(211/48)x²+(7/3)x³−(4/9)x4, h=max(q,−1) hasLip<=6, so n+(G)/d>=L_F(q)−6||F−G||HS/sqrt(d). Ifm1(F)->1,m2(F)->4/3,epsilonHS->0,d~N,andblockcharge s1>=2n+(G)−N+oN, then liminfD>115, D=84m3−16m4, suffices to beat2/3; D116 gives13/18.", "evidence": ["audits/adversarial_reviews/hilbert_schmidt_moment_transfer_round3.md §4", "experiments/code/hs_clipped_certificate_round3.py", "experiments/results/hs_clipped_certificate_round3.json", "audits/adversarial_reviews/hs_clipped_certificate_skeptic_round4.md", "audits/adversarial_reviews/zero_buffer_clipped_moment_third_round3.md"], "status": "adjudicated_scoped_conditional_or_model_theorem", "hypotheses": "ArithmeticD bound andexactblockcount are conditional inputs, not proved. BoundedD needed toreplace d/N by1; intendedimprovementcondition plusD<=121+o1 supplies it."}','mathematical_claim','Forq=(7/2)x−(211/48)x²+(7/3)x³−(4/9)x4, h=max(q,−1) hasLip<=6, so n+(G)/d>=L_F(q)−6||F−G||HS/sqrt(d). Ifm1(F)->1,m2(F)->4/3,epsilonHS->0,d~N,andblockcharge s1>=2n+(G)−N+oN, then liminfD>115, D=84m3−16m4, suffices to beat2/3; D116 gives13/18.');
INSERT INTO "graph_nodes" VALUES('THM-SG310','graphs/knowledge_graph.jsonl',1450,'adjudicated_scoped_conditional_or_model_theorem','["audits/adversarial_reviews/sine_gram_fourth_moment_advocate_archived_round3.md", "experiments/code/sine_gram_fourth_exact_advocate_round3.py", "experiments/results/sine_gram_fourth_exact_advocate_round3.json", "THM-SG309"]','{"record_type": "node", "id": "THM-SG310", "type": "mathematical_claim", "label": "The unit-density sinc(pi) sine-DPP expected Gram spectral law has moments m1=1,m2=4/3,m3=2,m4=13/4. The all-distinct fourcycle determinant integral is0; D=84m3−16m4=116.", "evidence": ["audits/adversarial_reviews/sine_gram_fourth_moment_advocate_archived_round3.md", "experiments/code/sine_gram_fourth_exact_advocate_round3.py", "experiments/results/sine_gram_fourth_exact_advocate_round3.json", "THM-SG309"], "status": "adjudicated_scoped_conditional_or_model_theorem", "hypotheses": "Actual random sine-Gram model, not zeta prime-side matrix. Absolute graph integrability asSG309;24 determinant permutations and15 trace partitions, with exact projection/Fourier integrals."}','mathematical_claim','The unit-density sinc(pi) sine-DPP expected Gram spectral law has moments m1=1,m2=4/3,m3=2,m4=13/4. The all-distinct fourcycle determinant integral is0; D=84m3−16m4=116.');
INSERT INTO "graph_nodes" VALUES('THM-E-SND401','graphs/knowledge_graph.jsonl',1451,'established_primary_source_result','Theorem1p1','{"record_type": "node", "id": "THM-E-SND401", "type": "mathematical_claim", "label": "AssumeRH. For sufficiently largex, |sum_(n<=x)mu(n)|≪sqrt(x)exp((logx)^(1/2)(loglogx)^14).", "evidence": "Theorem1p1", "status": "established_primary_source_result", "hypotheses": "RH; xreal sufficientlylarge; impliedconstantabsolute; this is original exponent14."}','mathematical_claim','AssumeRH. For sufficiently largex, |sum_(n<=x)mu(n)|≪sqrt(x)exp((logx)^(1/2)(loglogx)^14).');
INSERT INTO "graph_nodes" VALUES('THM-E-SND402','graphs/knowledge_graph.jsonl',1452,'established_primary_source_result','Theorem2p2; proofpp5–6','{"record_type": "node", "id": "THM-E-SND402", "type": "mathematical_claim", "label": "UnderRH, largeT,0<=h<=sqrtT,(loglogT)^2<=V<=logT/loglogT: numberR of1-separated t_j in[T,2T] with N(t_j+h)−N(t_j−h)−(h/pi)log(t_j/2pi)>V is≪T exp(−Vlog(V/loglogT)+3VloglogV).", "evidence": "Theorem2p2; proofpp5–6", "status": "established_primary_source_result", "hypotheses": "Zeros counted withmultiplicity; the sameT,h,V and separation across all testpoints."}','mathematical_claim','UnderRH, largeT,0<=h<=sqrtT,(loglogT)^2<=V<=logT/loglogT: numberR of1-separated t_j in[T,2T] with N(t_j+h)−N(t_j−h)−(h/pi)log(t_j/2pi)>V is≪T exp(−Vlog(V/loglogT)+3VloglogV).');
INSERT INTO "graph_nodes" VALUES('THM-E-SND403','graphs/knowledge_graph.jsonl',1453,'established_primary_source_result','Definition3pp2–3; Proposition4p3,proofpp6–7','{"record_type": "node", "id": "THM-E-SND403", "type": "mathematical_claim", "label": "UnderRH, all t in[T,2T] are V-typical forV>=(1/2+o1)logT/loglogT; for(loglogT)^2<=V<=logT/loglogT, number of1-separatedV-atypical heights is≪T exp(−Vlog(V/loglogT)+4VloglogV).", "evidence": "Definition3pp2–3; Proposition4p3,proofpp6–7", "status": "established_primary_source_result", "hypotheses": "Typicality has ALL3conditions: smoothed primepolylengthT^(1/V) modulus<=2V forallsigma>=.5; each localinterval length2piV/logT has<=3Vzeroordinates; each localinterval length2piV/((logV)logT) has<=V."}','mathematical_claim','UnderRH, all t in[T,2T] are V-typical forV>=(1/2+o1)logT/loglogT; for(loglogT)^2<=V<=logT/loglogT, number of1-separatedV-atypical heights is≪T exp(−Vlog(V/loglogT)+4VloglogV).');
INSERT INTO "graph_nodes" VALUES('THM-E-SND404','graphs/knowledge_graph.jsonl',1454,'established_primary_source_result_with_scoped_reconstruction','Proposition5p3; Lemmas9–11pp7–9','{"record_type": "node", "id": "THM-E-SND404", "type": "mathematical_claim", "label": "UnderRH atV-typical t, sigma0=.5+V/logT: log|zeta(sigma+it)|>=−VloglogV for sigma0<=sigma<=2; for .5<sigma<=sigma0 it is>=−Vlog[(sigma0−.5)/(sigma−.5)]−8VloglogV.", "evidence": "Proposition5p3; Lemmas9–11pp7–9", "status": "established_primary_source_result_with_scoped_reconstruction", "hypotheses": "Same typicality sizeT and Vrange; pointwise only at typicalt; no zero-spacing or simplicity assumption."}','mathematical_claim','UnderRH atV-typical t, sigma0=.5+V/logT: log|zeta(sigma+it)|>=−VloglogV for sigma0<=sigma<=2; for .5<sigma<=sigma0 it is>=−Vlog[(sigma0−.5)/(sigma−.5)]−8VloglogV.');
INSERT INTO "graph_nodes" VALUES('THM-D201','graphs/knowledge_graph.jsonl',1455,'Exact source hypotheses/statements and two proof routes inspected selectively; no whole-paper technical audit.','Theorem1.1,pp2–3; equations1.11–1.14','{"record_type": "node", "id": "THM-D201", "type": "mathematical_claim", "label": "S closed densely defined symmetric bounded below, deficiency(n,n)<∞, boundary triplet. For selfadjoint extensions H1,H2 the below-essential-spectrum counting shift σ=N_H1((−∞,λ])−N_H2((−∞,λ]) lies in[−σ−,σ+], where σ−+σ+=n−dim(L1∩L2).", "evidence": "Theorem1.1,pp2–3; equations1.11–1.14", "status": "Exact source hypotheses/statements and two proof routes inspected selectively; no whole-paper technical audit."}','mathematical_claim','S closed densely defined symmetric bounded below, deficiency(n,n)<∞, boundary triplet. For selfadjoint extensions H1,H2 the below-essential-spectrum counting shift σ=N_H1((−∞,λ])−N_H2((−∞,λ]) lies in[−σ−,σ+], where σ−+σ+=n−dim(L1∩L2).');
INSERT INTO "graph_nodes" VALUES('THM-D202','graphs/knowledge_graph.jsonl',1456,'Statement and relative-count cancellation proof inspected; full index foundations not audited.','Theorem1.2,p4; Proposition5.3 and proof,p19','{"record_type": "node", "id": "THM-D202", "type": "mathematical_claim", "label": "Under Theorem1.1 hypotheses, for[a,b] outside the essential spectrum, N_H1((a,b])−N_H2((a,b]) is the difference of endpoint Duistermaat indices. Relative counts require no unique-continuation assumption because common S-eigenvalues cancel.", "evidence": "Theorem1.2,p4; Proposition5.3 and proof,p19", "status": "Statement and relative-count cancellation proof inspected; full index foundations not audited."}','mathematical_claim','Under Theorem1.1 hypotheses, for[a,b] outside the essential spectrum, N_H1((a,b])−N_H2((a,b]) is the difference of endpoint Duistermaat indices. Relative counts require no unique-continuation assumption because common S-eigenvalues cancel.');
INSERT INTO "graph_nodes" VALUES('THM-D203','graphs/knowledge_graph.jsonl',1457,'Elementary range/resolvent identity proof supplied; parent independently confirmed the rank strategy. No literature novelty asserted.','audits/extension_interlacing_round2.md §1','{"record_type": "node", "id": "THM-D203", "type": "mathematical_claim", "label": "For selfadjoint extensions H0,H1 of one closed densely defined symmetric S with deficiency(d,d), D(i)=R1(i)−R0(i) maps into ker(S*−i), so rank≤d. For common z,w, D(z)=[I+(z−w)R1(z)]D(w)[I+(z−w)R0(z)]; the outer factors are invertible, hence the finite rank is anchor-independent. One compact resolvent implies both are compact.", "evidence": "audits/extension_interlacing_round2.md §1", "status": "Elementary range/resolvent identity proof supplied; parent independently confirmed the rank strategy. No literature novelty asserted."}','mathematical_claim','For selfadjoint extensions H0,H1 of one closed densely defined symmetric S with deficiency(d,d), D(i)=R1(i)−R0(i) maps into ker(S*−i), so rank≤d. For common z,w, D(z)=[I+(z−w)R1(z)]D(w)[I+(z−w)R0(z)]; the outer factors are invertible, hence the finite rank is anchor-independent. One compact resolvent implies both are compact.');
INSERT INTO "graph_nodes" VALUES('THM-D204','graphs/knowledge_graph.jsonl',1458,'established auxiliary theorem under stated hypotheses','audits/extension_interlacing_round2.md §§2–4','{"record_type": "node", "id": "THM-D204", "type": "mathematical_claim", "label": "For compact-resolvent selfadjoint H0,H1 on the same Hilbert space, choose common real anchor c and suppose F=(H1−c)^−1−(H0−c)^−1 has inertia(p,m), rankr=p+m<∞. Define ξ(x) by N_H1((c,x])−N_H0((c,x]) above c and the negative difference on(x,c] below c. Then ξ(x)∈[−m,p] for all realx, with exact half-open conventions; ξ(v)−ξ(u) is the finite interval count difference. Hence |Δ_H1(K)−Δ_H0(K)|≤3r, Δ_H=N_H((2K,4K])−2N_H((K,2K]).", "evidence": "audits/extension_interlacing_round2.md §§2–4", "status": "established auxiliary theorem under stated hypotheses", "hypotheses": ["Same Hilbert space and same two fixed operators during all height comparisons.", "Compact resolvent; essential/continuous spectrum excluded.", "One fixed real common resolvent anchor; no lower spectral bound required."]}','mathematical_claim','For compact-resolvent selfadjoint H0,H1 on the same Hilbert space, choose common real anchor c and suppose F=(H1−c)^−1−(H0−c)^−1 has inertia(p,m), rankr=p+m<∞. Define ξ(x) by N_H1((c,x])−N_H0((c,x]) above c and the negative difference on(x,c] below c. Then ξ(x)∈[−m,p] for all realx, with exact half-open conventions; ξ(v)−ξ(u) is the finite interval count difference. Hence |Δ_H1(K)−Δ_H0(K)|≤3r, Δ_H=N_H((2K,4K])−2N_H((K,2K]).');
INSERT INTO "graph_nodes" VALUES('THM-D205','graphs/knowledge_graph.jsonl',1459,'established auxiliary corollary; no novelty claim','audits/extension_interlacing_round2.md, proposition and §§1–4','{"record_type": "node", "id": "THM-D205", "type": "mathematical_claim", "label": "If H0,H1 are selfadjoint extensions of one closed densely defined symmetric S with finite equal deficiency(d,d), and one has compact resolvent, then their anchored relative count has range length≤d and |Δ_H1(K)−Δ_H0(K)|≤3d, even when spectra are unbounded in both directions.", "evidence": "audits/extension_interlacing_round2.md, proposition and §§1–4", "status": "established auxiliary corollary; no novelty claim"}','mathematical_claim','If H0,H1 are selfadjoint extensions of one closed densely defined symmetric S with finite equal deficiency(d,d), and one has compact resolvent, then their anchored relative count has range length≤d and |Δ_H1(K)−Δ_H0(K)|≤3d, even when spectra are unbounded in both directions.');
INSERT INTO "graph_nodes" VALUES('THM-D206','graphs/knowledge_graph.jsonl',1460,'exact auxiliary example, not a zeta-zero construction','audits/extension_interlacing_round2.md §4; experiments/code/extension_interlacing_round2.py','{"record_type": "node", "id": "THM-D206", "type": "mathematical_claim", "label": "For S=−i d/dx on H0^1(0,2π), deficiency(1,1), let Hθ have domain f(2π)=exp(2πiθ)f(0), spectrum n+θ. With θ1=3/20, θ0=2/5 and K=3/10, positive counts atK,2K,4K are(1,1,2) and(0,1,1), respectively, yielding curvature difference3. Direct sums yield3d.", "evidence": "audits/extension_interlacing_round2.md §4; experiments/code/extension_interlacing_round2.py", "status": "exact auxiliary example, not a zeta-zero construction"}','mathematical_claim','For S=−i d/dx on H0^1(0,2π), deficiency(1,1), let Hθ have domain f(2π)=exp(2πiθ)f(0), spectrum n+θ. With θ1=3/20, θ0=2/5 and K=3/10, positive counts atK,2K,4K are(1,1,2) and(0,1,1), respectively, yielding curvature difference3. Direct sums yield3d.');
INSERT INTO "graph_nodes" VALUES('THM-D207','graphs/knowledge_graph.jsonl',1461,'conditional model obstruction; no classical RH assertion','audits/extension_interlacing_round2.md §5','{"record_type": "node", "id": "THM-D207", "type": "mathematical_claim", "label": "If a reference E-channel first-order graph satisfies|Δ_H0|<3E and H1 is another compact-resolvent selfadjoint extension of their common finite-defectd symmetric restriction, then|Δ_H1|<3(E+d). If instead the full reference is A⊕D with M finite auxiliary levels, then|Δ_H1−Δ_A|≤3d+2M. These require an actual full-space common-extension realization; arbitrary unitary S(k) is insufficient.", "evidence": "audits/extension_interlacing_round2.md §5", "status": "conditional model obstruction; no classical RH assertion"}','mathematical_claim','If a reference E-channel first-order graph satisfies|Δ_H0|<3E and H1 is another compact-resolvent selfadjoint extension of their common finite-defectd symmetric restriction, then|Δ_H1|<3(E+d). If instead the full reference is A⊕D with M finite auxiliary levels, then|Δ_H1−Δ_A|≤3d+2M. These require an actual full-space common-extension realization; arbitrary unitary S(k) is insufficient.');
INSERT INTO "graph_nodes" VALUES('THM-S001-AC','graphs/knowledge_graph.jsonl',1462,'source_read_not_full_modern_proof_audited','Wilkins translation pp2–3','{"record_type": "node", "id": "THM-S001-AC", "type": "mathematical_claim", "label": "ζ has meromorphic continuation to C, with only a simple pole at1; completed xi is entire and invariant under s→1−s.", "evidence": "Wilkins translation pp2–3", "status": "source_read_not_full_modern_proof_audited"}','mathematical_claim','ζ has meromorphic continuation to C, with only a simple pole at1; completed xi is entire and invariant under s→1−s.');
INSERT INTO "graph_nodes" VALUES('CONJ-S001-RH','graphs/knowledge_graph.jsonl',1463,'faithfully_identified_as_conjecture','Wilkins translation p4','{"record_type": "node", "id": "CONJ-S001-RH", "type": "conjecture", "label": "All zeros of ξ_mod(1/2+it) are real in variable t.", "evidence": "Wilkins translation p4", "status": "faithfully_identified_as_conjecture"}','conjecture','All zeros of ξ_mod(1/2+it) are real in variable t.');
INSERT INTO "graph_nodes" VALUES('THM-S003-SECU','graphs/knowledge_graph.jsonl',1464,'inspected_and_single_edge_case_independently_checked','Proposition9.1,p17,eq83','{"record_type": "node", "id": "THM-S003-SECU", "type": "mathematical_claim", "label": "For finite positive edge lengths and a fixed self-adjoint endpoint coupling, k is an eigenvalue iff det(I−S diag(exp(ik l_j)))=0, with corresponding multiplicity.", "evidence": "Proposition9.1,p17,eq83", "status": "inspected_and_single_edge_case_independently_checked"}','mathematical_claim','For finite positive edge lengths and a fixed self-adjoint endpoint coupling, k is an eigenvalue iff det(I−S diag(exp(ik l_j)))=0, with corresponding multiplicity.');
INSERT INTO "graph_nodes" VALUES('THM-S003-NOGO','graphs/knowledge_graph.jsonl',1465,'growth_order_independently_checked; coefficient_issue_is_separate','Theorem15.6,p28','{"record_type": "node", "id": "THM-S003-NOGO", "type": "mathematical_claim", "label": "Fixed compact-graph self-adjoint realizations of HBK and the specified squared expression cannot have the complete nontrivial Riemann-zero spectrum.", "evidence": "Theorem15.6,p28", "status": "growth_order_independently_checked; coefficient_issue_is_separate"}','mathematical_claim','Fixed compact-graph self-adjoint realizations of HBK and the specified squared expression cannot have the complete nontrivial Riemann-zero spectrum.');
INSERT INTO "graph_nodes" VALUES('THM-S004-NEWMAN','graphs/knowledge_graph.jsonl',1466,'source_read; full_proof_not_audited','Theorem1,p3,arxivv5','{"record_type": "node", "id": "THM-S004-NEWMAN", "type": "mathematical_claim", "label": "The de Bruijn–Newman constant in the paper normalization satisfies Λ≥0.", "evidence": "Theorem1,p3,arxivv5", "status": "source_read; full_proof_not_audited"}','mathematical_claim','The de Bruijn–Newman constant in the paper normalization satisfies Λ≥0.');
INSERT INTO "graph_nodes" VALUES('THM-S004-ROOTODE','graphs/knowledge_graph.jsonl',1467,'source_statement_read; predecessor_source_not_audited','Theorem11,p27,eq56','{"record_type": "node", "id": "THM-S004-ROOTODE", "type": "mathematical_claim", "label": "Assuming Λ<0, on Λ<t≤0 the simple zero trajectories satisfy x_k′=2PV∑_{j≠k}1/(x_k−x_j).", "evidence": "Theorem11,p27,eq56", "status": "source_statement_read; predecessor_source_not_audited"}','mathematical_claim','Assuming Λ<0, on Λ<t≤0 the simple zero trajectories satisfy x_k′=2PV∑_{j≠k}1/(x_k−x_j).');
INSERT INTO "graph_nodes" VALUES('OBS-S-C1','graphs/knowledge_graph.jsonl',1468,'independent_review_requested; no_novelty_claim','proposals/independent_campaigns/spectral_counting_barrier.md','{"record_type": "node", "id": "OBS-S-C1", "type": "mathematical_claim", "label": "For E finite first-order graph channels with fixed unitary endpoint matrix, N_+(K)=LK/(2π)+C−F(K),0≤F(K)<E; hence absolute dyadic count curvature<3E.", "evidence": "proposals/independent_campaigns/spectral_counting_barrier.md", "status": "independent_review_requested; no_novelty_claim"}','mathematical_claim','For E finite first-order graph channels with fixed unitary endpoint matrix, N_+(K)=LK/(2π)+C−F(K),0≤F(K)<E; hence absolute dyadic count curvature<3E.');
INSERT INTO "graph_nodes" VALUES('OBS-S-C2','graphs/knowledge_graph.jsonl',1469,'independent_review_requested; no_novelty_claim','proposals/independent_campaigns/spectral_counting_barrier.md','{"record_type": "node", "id": "OBS-S-C2", "type": "mathematical_claim", "label": "If such a graph matches Nζ at K,2K,4K with errors≤ε_K K, then3E≥Klog2/π−6ε_KK−O(logK); o(K) error requires liminf E/K≥log2/(3π).", "evidence": "proposals/independent_campaigns/spectral_counting_barrier.md", "status": "independent_review_requested; no_novelty_claim"}','mathematical_claim','If such a graph matches Nζ at K,2K,4K with errors≤ε_K K, then3E≥Klog2/π−6ε_KK−O(logK); o(K) error requires liminf E/K≥log2/(3π).');
INSERT INTO "graph_nodes" VALUES('THM-S005-PHASE','graphs/knowledge_graph.jsonl',1470,'local source inspected; mechanism independently reconstructed','arxivv2 Section5.1,eq5.5–5.11,pp36–38','{"record_type": "node", "id": "THM-S005-PHASE", "type": "mathematical_claim", "label": "For the stated energy-independent quantum evolution map, eigenphase velocities are positive and sum to twice total undirected bond length; the count has linear Weyl term plus bounded oscillatory part.", "evidence": "arxivv2 Section5.1,eq5.5–5.11,pp36–38", "status": "local source inspected; mechanism independently reconstructed"}','mathematical_claim','For the stated energy-independent quantum evolution map, eigenphase velocities are positive and sum to twice total undirected bond length; the count has linear Weyl term plus bounded oscillatory part.');
INSERT INTO "graph_nodes" VALUES('CONS-S006-BUTTERFLY','graphs/knowledge_graph.jsonl',1471,'source main text read; first correction independently checked; infinite limit not fully audited','arxivv2 eq11–14,pp3–5','{"record_type": "node", "id": "CONS-S006-BUTTERFLY", "type": "mathematical_claim", "label": "A recursive infinite collection of unitary butterflies can match smoothed prime-power oscillatory trace coefficients while its mean density diverges and its full spectrum differs from zeta zeros.", "evidence": "arxivv2 eq11–14,pp3–5", "status": "source main text read; first correction independently checked; infinite limit not fully audited"}','mathematical_claim','A recursive infinite collection of unitary butterflies can match smoothed prime-power oscillatory trace coefficients while its mean density diverges and its full spectrum differs from zeta zeros.');
INSERT INTO "graph_nodes" VALUES('THM-S007-HARDY','graphs/knowledge_graph.jsonl',1472,'whole_original_read; local proof reconstructed; no full independent adversarial audit','original pp1012–1014,especially§3 eq4–6','{"record_type": "node", "id": "THM-S007-HARDY", "type": "mathematical_claim", "label": "Infinitely many distinct nontrivial zeros of ζ(s) have real part1/2; no RH or positive-proportion assertion follows.", "evidence": "original pp1012–1014,especially§3 eq4–6", "status": "whole_original_read; local proof reconstructed; no full independent adversarial audit"}','mathematical_claim','Infinitely many distinct nontrivial zeros of ζ(s) have real part1/2; no RH or positive-proportion assertion follows.');
INSERT INTO "graph_nodes" VALUES('LEM-THRESHOLD62-DENSITY-MOMENT','graphs/knowledge_graph.jsonl',1473,'adjudicated_scoped_conditional_refinement','proposals/independent_campaigns/threshold62_weighteddensity_bgstb.md','{"record_type": "node", "id": "LEM-THRESHOLD62-DENSITY-MOMENT", "type": "mathematical_claim", "label": "With the BGSTB §6 kernel, unit-window zero count and reflection, let L=log T and D_T(y)=N(1/2+y/L,T) for 1/2≤y≤L/2. The sufficient horizontal moment condition for S(T)=o(TL) is exactly equivalent to r_T(1/2)+∫ r_T(y)/(1+y²)dy→0, where r_T(y)=e^(2y)D_T(y)/T. The condition refers to the absolute majorant, not necessity for the signed far-pair sum.", "evidence": "proposals/independent_campaigns/threshold62_weighteddensity_bgstb.md", "status": "adjudicated_scoped_conditional_refinement"}','mathematical_claim','With the BGSTB §6 kernel, unit-window zero count and reflection, let L=log T and D_T(y)=N(1/2+y/L,T) for 1/2≤y≤L/2. The sufficient horizontal moment condition for S(T)=o(TL) is exactly equivalent to r_T(1/2)+∫ r_T(y)/(1+y²)dy→0, where r_T(y)=e^(2y)D_T(y)/T. The condition refers to the absolute majorant, not necessity for the signed far-pair sum.');
INSERT INTO "graph_nodes" VALUES('COR-THRESHOLD62-DENSITY-HEIGHT','graphs/knowledge_graph.jsonl',1474,'adjudicated_scoped_conditional_refinement','proposals/independent_campaigns/threshold62_weighteddensity_bgstb.md','{"record_type": "node", "id": "COR-THRESHOLD62-DENSITY-HEIGHT", "type": "mathematical_claim", "label": "Under the source''s uniform N(σ,X)≪X^(2(1−σ)) bound on σ*≤σ≤1, fix 0<θ<2(1−σ*). The contribution of positive heights at most T^θ to the horizontal moment is o(T), with scale log T. Hence the weighted condition can be imposed just on heights T^θ<γ≤T, and under it the BGSTB §7 multiplicity bound follows from Lemma 7 and near-pair positivity.", "evidence": "proposals/independent_campaigns/threshold62_weighteddensity_bgstb.md", "status": "adjudicated_scoped_conditional_refinement"}','mathematical_claim','Under the source''s uniform N(σ,X)≪X^(2(1−σ)) bound on σ*≤σ≤1, fix 0<θ<2(1−σ*). The contribution of positive heights at most T^θ to the horizontal moment is o(T), with scale log T. Hence the weighted condition can be imposed just on heights T^θ<γ≤T, and under it the BGSTB §7 multiplicity bound follows from Lemma 7 and near-pair positivity.');
INSERT INTO "graph_nodes" VALUES('OBS-WC501','graphs/knowledge_graph.jsonl',1475,'adjudicated_scoped_unconditional_implication','audits/adversarial_reviews/weighted_criterion_director_round5.md','{"record_type": "node", "id": "OBS-WC501", "type": "mathematical_claim", "label": "For alpha∈[-3,-2],1≤a<(1-alpha)/2, t=-(alpha+1)/2,c=a-1,b=t-c, u=(1-z)^(-c), the specified D_(alpha+2) target closure implies zeta zero-free Re(s)>b. A continuous radial Lambda_s forRe(s)>b hasLambda_s(u)=-1/s andLambda_s(u h_k)=(1-k^(1-s))zeta(s)/s, with the removable value at s=1 understood.", "evidence": "audits/adversarial_reviews/weighted_criterion_director_round5.md", "status": "adjudicated_scoped_unconditional_implication"}','mathematical_claim','For alpha∈[-3,-2],1≤a<(1-alpha)/2, t=-(alpha+1)/2,c=a-1,b=t-c, u=(1-z)^(-c), the specified D_(alpha+2) target closure implies zeta zero-free Re(s)>b. A continuous radial Lambda_s forRe(s)>b hasLambda_s(u)=-1/s andLambda_s(u h_k)=(1-k^(1-s))zeta(s)/s, with the removable value at s=1 understood.');
INSERT INTO "graph_nodes" VALUES('OBS-WC502','graphs/knowledge_graph.jsonl',1476,'adjudicated_scoped_verified_versioned_statement_counterexample','Publisherp26; audits/adversarial_reviews/weighted_criterion_director_round5.md','{"record_type": "node", "id": "OBS-WC502", "type": "mathematical_claim", "label": "At alpha=-3,a=7/4, published Theorem5.5''s zero-free premise Re(s)>1 is true but its weighted target closure inD_-1 is false. For any nontrivial zero rho withsigma=Re(rho)>=1/2, the target distance is at least |Gamma(rho)|(sigma-1/4)/(sqrt6+7/4)>0.", "evidence": "Publisherp26; audits/adversarial_reviews/weighted_criterion_director_round5.md", "status": "adjudicated_scoped_verified_versioned_statement_counterexample", "hypotheses": "Classical Euler product, existence of a nontrivial zero and reflection; exact source norm and branches. No RH or numerical zero location needed."}','mathematical_claim','At alpha=-3,a=7/4, published Theorem5.5''s zero-free premise Re(s)>1 is true but its weighted target closure inD_-1 is false. For any nontrivial zero rho withsigma=Re(rho)>=1/2, the target distance is at least |Gamma(rho)|(sigma-1/4)/(sqrt6+7/4)>0.');
INSERT INTO "graph_nodes" VALUES('OBS-WC503','graphs/knowledge_graph.jsonl',1477,'adjudicated_scoped_source_dependent_reconstruction; priority_unassessed','audits/adversarial_reviews/weighted_criterion_director_round5.md; complete independent sufficiency and necessity reviews cited there','{"record_type": "node", "id": "OBS-WC503", "type": "mathematical_claim", "label": "In exactly the original source parameter range and topology, (1-z)^(1-a) belongs to closedspan{(1-z)^(1-a)h_k:k>=2} inD_(alpha+2) iff zeta has no zeros inRe(s)>b=(1-alpha)/2-a. b∈(0,1].", "evidence": "audits/adversarial_reviews/weighted_criterion_director_round5.md; complete independent sufficiency and necessity reviews cited there", "status": "adjudicated_scoped_source_dependent_reconstruction; priority_unassessed", "hypotheses": "Classical Hadamard/convexity facts; Balazard–Saias general-b uniform Mobius estimate as reproduced inBaez-Duarte math/0202141v2 Lemma2.1 accepted external; b1 uses separately reconstructed unconditional Bergman density."}','mathematical_claim','In exactly the original source parameter range and topology, (1-z)^(1-a) belongs to closedspan{(1-z)^(1-a)h_k:k>=2} inD_(alpha+2) iff zeta has no zeros inRe(s)>b=(1-alpha)/2-a. b∈(0,1].');
INSERT INTO "graph_nodes" VALUES('OBS-WC504','graphs/knowledge_graph.jsonl',1478,'adjudicated_scoped_boundary_check; no boundary zero exclusion','audits/adversarial_reviews/gallardo_seco_necessity_threshold62_round5.md; director review','{"record_type": "node", "id": "OBS-WC504", "type": "mathematical_claim", "label": "ForRe(s)>0, n^(s+c)Lambda_s(z^n) tends (s-1)Gamma(s+c)/(sGamma(s)); on Re(s)=b ands!=1 the functional has no bounded extension toD_(alpha+2). At the sole boundary b=s1, Lambda1 is-f(0) onpolynomials.", "evidence": "audits/adversarial_reviews/gallardo_seco_necessity_threshold62_round5.md; director review", "status": "adjudicated_scoped_boundary_check; no boundary zero exclusion"}','mathematical_claim','ForRe(s)>0, n^(s+c)Lambda_s(z^n) tends (s-1)Gamma(s+c)/(sGamma(s)); on Re(s)=b ands!=1 the functional has no bounded extension toD_(alpha+2). At the sole boundary b=s1, Lambda1 is-f(0) onpolynomials.');
INSERT INTO "graph_nodes" VALUES('OBS-WC505','graphs/knowledge_graph.jsonl',1479,'adjudicated_scoped_unconditional_counterexample','audits/adversarial_reviews/weighted_criterion_director_round5.md; independent Bergman and witness reviews','{"record_type": "node", "id": "OBS-WC505", "type": "mathematical_claim", "label": "For alpha=-3,c3/4, f0=1/(1-z) lies in ordinaryD_-3 closure ofspanR_k, but not in its closure for norm||g/(1-z)^(3/4)||D_-3. Thus ordinary-to-weighted core transport fails for this exact arithmetic family.", "evidence": "audits/adversarial_reviews/weighted_criterion_director_round5.md; independent Bergman and witness reviews", "status": "adjudicated_scoped_unconditional_counterexample"}','mathematical_claim','For alpha=-3,c3/4, f0=1/(1-z) lies in ordinaryD_-3 closure ofspanR_k, but not in its closure for norm||g/(1-z)^(3/4)||D_-3. Thus ordinary-to-weighted core transport fails for this exact arithmetic family.');
INSERT INTO "graph_nodes" VALUES('EXT-E-GS5.5','graphs/knowledge_graph.jsonl',1480,'printed_reverse_implication_refuted_at_explicit_permitted_parameters; do_not_import_as_verified','Publisher2025p26; arXiv2206.02654v6p21','{"record_type": "node", "id": "EXT-E-GS5.5", "type": "mathematical_claim", "label": "Inspected Theorem5.5 asserts weighted target closure iff zeta zero-freeRe(s)>t=-(alpha+1)/2, independentlyofa in its printed range.", "evidence": "Publisher2025p26; arXiv2206.02654v6p21", "status": "printed_reverse_implication_refuted_at_explicit_permitted_parameters; do_not_import_as_verified"}','mathematical_claim','Inspected Theorem5.5 asserts weighted target closure iff zeta zero-freeRe(s)>t=-(alpha+1)/2, independentlyofa in its printed range.');
INSERT INTO "graph_nodes" VALUES('LEM-WC-R2-1','graphs/knowledge_graph.jsonl',1481,'independently_reconstructed_standard_lemma','audits/weighted_criterion_round2.md equationsW1–W3; Wei–Wu Proposition2.14 p12','{"record_type": "node", "id": "LEM-WC-R2-1", "type": "mathematical_claim", "label": "For finiteD(s)=Σa_n n^(-s), A=D(1), h_D(x)=1+Σa_n{1/(nx)} on(0,1), H_D=Mh_D, one has H_D=(1−ζD)/s+A/(s−1). Therefore F_q=((s−1)/s)(1−ζD)/s^q=((s−1)/s)H_D/s^(q−1)−A/s^q belongsH²(Re(s)>1/2), and its H² norm equals d_q(D) because(s−1)/s is inner for this half-plane.", "evidence": "audits/weighted_criterion_round2.md equationsW1–W3; Wei–Wu Proposition2.14 p12", "status": "independently_reconstructed_standard_lemma", "hypotheses": ["finite Dirichlet polynomial, exponents n≥1", "integerq≥1", "H² boundary measure dt/(2π)"]}','mathematical_claim','For finiteD(s)=Σa_n n^(-s), A=D(1), h_D(x)=1+Σa_n{1/(nx)} on(0,1), H_D=Mh_D, one has H_D=(1−ζD)/s+A/(s−1). Therefore F_q=((s−1)/s)(1−ζD)/s^q=((s−1)/s)H_D/s^(q−1)−A/s^q belongsH²(Re(s)>1/2), and its H² norm equals d_q(D) because(s−1)/s is inner for this half-plane.');
INSERT INTO "graph_nodes" VALUES('THM-WC-R2-1','graphs/knowledge_graph.jsonl',1482,'derived_reconstruction_from_established_q1_criterion','audits/weighted_criterion_round2.md W4–W6','{"record_type": "node", "id": "THM-WC-R2-1", "type": "mathematical_claim", "label": "For each fixedintegerq≥1, RH iff δ_q(N)=inf_lengthD≤N d_q(D) tends0. Ifρ=β+iγ is a nontrivial zero withβ>1/2, everyfiniteD obeys d_q(D)≥sqrt(2β−1)|ρ−1|/|ρ|^(q+1). Optimizedδ_q is nonincreasing, so liminf0 is equivalent tolimit0.", "evidence": "audits/weighted_criterion_round2.md W4–W6", "status": "derived_reconstruction_from_established_q1_criterion"}','mathematical_claim','For each fixedintegerq≥1, RH iff δ_q(N)=inf_lengthD≤N d_q(D) tends0. Ifρ=β+iγ is a nontrivial zero withβ>1/2, everyfiniteD obeys d_q(D)≥sqrt(2β−1)|ρ−1|/|ρ|^(q+1). Optimizedδ_q is nonincreasing, so liminf0 is equivalent tolimit0.');
INSERT INTO "graph_nodes" VALUES('OBS-WC-R2-1','graphs/knowledge_graph.jsonl',1483,'quantifier_scope_observation','audits/weighted_criterion_round2.md §5','{"record_type": "node", "id": "OBS-WC-R2-1", "type": "mathematical_claim", "label": "For any prescribed familyD_N, liminf d_q(D_N)=0 impliesRH by the same uniformoff-line-zero bound. For fixedSelbergweights, the cited simplicityproof assumesfullsequenceconvergence; a sparse subsequence supplies onlysubsequence Ψ-estimates and does not complete itsglobalAbelianpole argument.", "evidence": "audits/weighted_criterion_round2.md §5", "status": "quantifier_scope_observation"}','mathematical_claim','For any prescribed familyD_N, liminf d_q(D_N)=0 impliesRH by the same uniformoff-line-zero bound. For fixedSelbergweights, the cited simplicityproof assumesfullsequenceconvergence; a sparse subsequence supplies onlysubsequence Ψ-estimates and does not complete itsglobalAbelianpole argument.');
INSERT INTO "graph_nodes" VALUES('LEM-WC-R2-2','graphs/knowledge_graph.jsonl',1484,'elementary_conditional_interpolation_observation','audits/weighted_criterion_round2.md §5 finalparagraph','{"record_type": "node", "id": "LEM-WC-R2-2", "type": "mathematical_claim", "label": "If fixedSelberg error tends0 alongN_k andN_(k+1)−N_k=o(sqrt(N_k)logN_k), thenΨ(N_k)=o(sqrt(N_k)logN_k) extends toallx using|Ψ′|=|M(x)/x|≤1. This recoversRHandsimplicity byWei–Wu pole argument.", "evidence": "audits/weighted_criterion_round2.md §5 finalparagraph", "status": "elementary_conditional_interpolation_observation"}','mathematical_claim','If fixedSelberg error tends0 alongN_k andN_(k+1)−N_k=o(sqrt(N_k)logN_k), thenΨ(N_k)=o(sqrt(N_k)logN_k) extends toallx using|Ψ′|=|M(x)/x|≤1. This recoversRHandsimplicity byWei–Wu pole argument.');
INSERT INTO "graph_nodes" VALUES('LEM-WC-R2-3','graphs/knowledge_graph.jsonl',1485,'elementary_consequence_no_novelty_claim','audits/weighted_criterion_round2.md §6; Ehm§7.1forreciprocalmoments','{"record_type": "node", "id": "LEM-WC-R2-3", "type": "mathematical_claim", "label": "For every finiteDirichletpolynomialD andintegerq≥1, d_q(D)≥|D(1)|, sinceF_(q,D)(1)=−D(1) andtheH²evaluationnormat1is1. ThereforefixedSelbergfamilyerror≥(1+o1)/logN foranyfixedq≥1.", "evidence": "audits/weighted_criterion_round2.md §6; Ehm§7.1forreciprocalmoments", "status": "elementary_consequence_no_novelty_claim"}','mathematical_claim','For every finiteDirichletpolynomialD andintegerq≥1, d_q(D)≥|D(1)|, sinceF_(q,D)(1)=−D(1) andtheH²evaluationnormat1is1. ThereforefixedSelbergfamilyerror≥(1+o1)/logN foranyfixedq≥1.');
INSERT INTO "graph_nodes" VALUES('EXT-E-GS5.1','graphs/knowledge_graph.jsonl',1486,'source_printed_assertion_refuted_only_at_inclusive_endpoint','ActualjournalPDFp21; arXivv6p17','{"record_type": "node", "id": "EXT-E-GS5.1", "type": "mathematical_claim", "label": "PrintedProposition5.1: foralpha in[−3,−2),a>0,T_a=f_prime−af/(1−z):D_(alpha+2)->D_alpha isboundedbijectiveiffa>=−(1+alpha)/2; boundedawayzeroH-infinitymultipliershpreservethisforT_a,h.", "evidence": "ActualjournalPDFp21; arXivv6p17", "status": "source_printed_assertion_refuted_only_at_inclusive_endpoint", "hypotheses": "FullcoefficientnormD_beta=sum|a_n|²(n+1)^beta; statedinclusiveequality; noboundaryconstraintorquotient."}','mathematical_claim','PrintedProposition5.1: foralpha in[−3,−2),a>0,T_a=f_prime−af/(1−z):D_(alpha+2)->D_alpha isboundedbijectiveiffa>=−(1+alpha)/2; boundedawayzeroH-infinitymultipliershpreservethisforT_a,h.');
INSERT INTO "graph_nodes" VALUES('THM-E-GS301','graphs/knowledge_graph.jsonl',1487,'adjudicated_scoped_endpoint_counterexample_or_strict_operator_repair','audits/gallardo_seco_endpoint_round3.md(GS1), explicitrangeobstructionaddendum','{"record_type": "node", "id": "THM-E-GS301", "type": "mathematical_claim", "label": "For T1:D−1->D−3, fK=sum_(n0..K)z^n obeys ||fK||²=H_(K+1) and ||T1fK||²=(K+1)² sum_(j>=K+1)j^-3<=1/2+1/(K+1). ThusT1isnotboundedbelow. Explicit g_j=(j+1)/log(j+2)belongsD−3 buthasnoD−1preimage: anycoefficient solutionhas t_n=t0+sum_(k2..n+1)1/(klogk),a_n=t_n+n/((n+1)log(n+1)),so ||f||D−1=infinity.", "evidence": "audits/gallardo_seco_endpoint_round3.md(GS1), explicitrangeobstructionaddendum", "status": "adjudicated_scoped_endpoint_counterexample_or_strict_operator_repair", "hypotheses": "ExactcoefficientnormsfromPAPER-E012; operatorT1f=f_prime−f/(1−z),fullspaces."}','mathematical_claim','For T1:D−1->D−3, fK=sum_(n0..K)z^n obeys ||fK||²=H_(K+1) and ||T1fK||²=(K+1)² sum_(j>=K+1)j^-3<=1/2+1/(K+1). ThusT1isnotboundedbelow. Explicit g_j=(j+1)/log(j+2)belongsD−3 buthasnoD−1preimage: anycoefficient solutionhas t_n=t0+sum_(k2..n+1)1/(klogk),a_n=t_n+n/((n+1)log(n+1)),so ||f||D−1=infinity.');
INSERT INTO "graph_nodes" VALUES('THM-E-GS302','graphs/knowledge_graph.jsonl',1488,'localized_formula_reconstruction_independent_review_pending','PAPER-E012preprintp5/journalp6Lemma2.3; audits/gallardo_seco_endpoint_round3.md§B','{"record_type": "node", "id": "THM-E-GS302", "type": "mathematical_claim", "label": "For f(x)=sum_(k1..N)c_k{1/(kx)},sumc_k/k=0,Res>0, Mellin integral0¹ f(x)x^(s−1)dx=−zeta(s)/s sum_(k1..N)c_k k^-s, removableat1. PrintedLemma2.3sumstartsk2missesc1. WitnessN2,c1−1,c2=2,s2hasactualintegralzeta2/4>0,printedvalue−zeta2/4. Repairpreserveszero-exclusionargument.", "evidence": "PAPER-E012preprintp5/journalp6Lemma2.3; audits/gallardo_seco_endpoint_round3.md§B", "status": "localized_formula_reconstruction_independent_review_pending", "hypotheses": "FiniteN,fullconstrainedfractional-partcoefficientvector; samec_kthroughformula; nochangeofbasiswithoutrescaling."}','mathematical_claim','For f(x)=sum_(k1..N)c_k{1/(kx)},sumc_k/k=0,Res>0, Mellin integral0¹ f(x)x^(s−1)dx=−zeta(s)/s sum_(k1..N)c_k k^-s, removableat1. PrintedLemma2.3sumstartsk2missesc1. WitnessN2,c1−1,c2=2,s2hasactualintegralzeta2/4>0,printedvalue−zeta2/4. Repairpreserveszero-exclusionargument.');
INSERT INTO "graph_nodes" VALUES('THM-E-GS303','graphs/knowledge_graph.jsonl',1489,'adjudicated_scoped_endpoint_counterexample_or_strict_operator_repair','audits/adversarial_reviews/gallardo_seco_hardy_repair_skeptic_round4.md(H1)–(H7); independent equivalencesreconstruction companion','{"record_type": "node", "id": "THM-E-GS303", "type": "mathematical_claim", "label": "For fixedalpha<−1,a>0,T_a=f_prime−af/(1−z):D_(alpha+2)->D_alpha isbounded. Withdelta=a+(alpha+1)/2,delta>0givesboundedbijection;delta<0givessurjectionwithonedimensionalkernelspan{(1−z)^−a}andboundedrightinverse;delta0givesinjectivedensepropernonclosedrange. ThussourceProp5.1boundedbijectionconditionmustbestrictinitsstatedalpha[-3,-2)range.", "evidence": "audits/adversarial_reviews/gallardo_seco_hardy_repair_skeptic_round4.md(H1)–(H7); independent equivalencesreconstruction companion", "status": "adjudicated_scoped_endpoint_counterexample_or_strict_operator_repair", "hypotheses": "ExactweightedcoefficientHilbertspaces; fullanalyticdomain,noboundaryquotient; alpha,a fixed, no uniformityneardelta0. Invertibletargetmultiplierspreserveclassification."}','mathematical_claim','For fixedalpha<−1,a>0,T_a=f_prime−af/(1−z):D_(alpha+2)->D_alpha isbounded. Withdelta=a+(alpha+1)/2,delta>0givesboundedbijection;delta<0givessurjectionwithonedimensionalkernelspan{(1−z)^−a}andboundedrightinverse;delta0givesinjectivedensepropernonclosedrange. ThussourceProp5.1boundedbijectionconditionmustbestrictinitsstatedalpha[-3,-2)range.');
INSERT INTO "graph_nodes" VALUES('OP62-CONNES-WEIGHTED','graphs/knowledge_graph.jsonl',1490,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"record_type": "node", "id": "OP62-CONNES-WEIGHTED", "type": "mathematical_claim", "label": "For δ>1 the discrete spectrum on Hχ is the critical-line zero ordinates in iR only, with multiplicity min(actual zero order, largest integer strictly below (1+δ)/2).", "evidence": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped"}','mathematical_claim','For δ>1 the discrete spectrum on Hχ is the critical-line zero ordinates in iR only, with multiplicity min(actual zero order, largest integer strictly below (1+δ)/2).');
INSERT INTO "graph_nodes" VALUES('OP62-CONNES-CUTOFF','graphs/knowledge_graph.jsonl',1491,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"record_type": "node", "id": "OP62-CONNES-CUTOFF", "type": "mathematical_claim", "label": "For a positive-characteristic global field, the cutoff trace identity on compactly supported test functions is equivalent to RH for every Grössencharakter L-function. The archimedean discussion instead changes the cutoff.", "evidence": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped"}','mathematical_claim','For a positive-characteristic global field, the cutoff trace identity on compactly supported test functions is equivalent to RH for every Grössencharakter L-function. The archimedean discussion instead changes the cutoff.');
INSERT INTO "graph_nodes" VALUES('OP62-CONREYLI-ENTIRE','graphs/knowledge_graph.jsonl',1492,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"record_type": "node", "id": "OP62-CONREYLI-ENTIRE", "type": "mathematical_claim", "label": "For E satisfying the theorem’s entire-function, no-real-zero, strict Hermite–Biehler, unit-modulus shift and vertical monotonicity hypotheses, nonnegative real shift form on the simultaneous translate domain forces Im(w)=-1/2 and the stated derivative sign. The paper reports a negative sign for the natural xi model.", "evidence": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped"}','mathematical_claim','For E satisfying the theorem’s entire-function, no-real-zero, strict Hermite–Biehler, unit-modulus shift and vertical monotonicity hypotheses, nonnegative real shift form on the simultaneous translate domain forces Im(w)=-1/2 and the stated derivative sign. The paper reports a negative sign for the natural xi model.');
INSERT INTO "graph_nodes" VALUES('OP62-CONREYLI-HALFPLANE','graphs/knowledge_graph.jsonl',1493,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"record_type": "node", "id": "OP62-CONREYLI-HALFPLANE", "type": "mathematical_claim", "label": "For W analytic and zero-free in the upper half-plane, a kernel-translation linear operator on F(W) with nonnegative real numerical range forces continuation to Im(z)>-1/2 and a nonnegative quotient real part there. The paper reports a negative quotient real part in the natural reciprocal-xi model.", "evidence": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped"}','mathematical_claim','For W analytic and zero-free in the upper half-plane, a kernel-translation linear operator on F(W) with nonnegative real numerical range forces continuation to Im(z)>-1/2 and a nonnegative quotient real part there. The paper reports a negative quotient real part in the natural reciprocal-xi model.');
INSERT INTO "graph_nodes" VALUES('OP62-SUZUKI-INNER','graphs/knowledge_graph.jsonl',1494,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"record_type": "node", "id": "OP62-SUZUKI-INNER", "type": "mathematical_claim", "label": "For fixed ω0≥0, zero-freeness in Re(s)>1/2+ω0 is equivalent to meromorphic innerness for all ω>ω0. For each fixed positive ω innerness is equivalent to the stated full-domain arithmetic Mellin convolution conditions.", "evidence": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped"}','mathematical_claim','For fixed ω0≥0, zero-freeness in Re(s)>1/2+ω0 is equivalent to meromorphic innerness for all ω>ω0. For each fixed positive ω innerness is equivalent to the stated full-domain arithmetic Mellin convolution conditions.');
INSERT INTO "graph_nodes" VALUES('OP62-SUZUKI-KERNEL','graphs/knowledge_graph.jsonl',1495,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"record_type": "node", "id": "OP62-SUZUKI-KERNEL", "type": "mathematical_claim", "label": "Explicit determinant-ratio canonical Hamiltonian construction assumes ω>1. The stated weaker compressed-kernel conclusions include Hilbert–Schmidt and invertibility for ω>1/2 and compact self-adjointness for ω>0.", "evidence": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped"}','mathematical_claim','Explicit determinant-ratio canonical Hamiltonian construction assumes ω>1. The stated weaker compressed-kernel conclusions include Hilbert–Schmidt and invertibility for ω>1/2 and compact self-adjointness for ω>0.');
INSERT INTO "graph_nodes" VALUES('OP62-MEYER-SPECTRUM','graphs/knowledge_graph.jsonl',1496,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"record_type": "node", "id": "OP62-MEYER-SPECTRUM", "type": "mathematical_claim", "label": "Eigenvalues of the transpose on the continuous dual of the nuclear Fréchet quotient equal the zeros of the meromorphic completed zeta, with algebraic multiplicities equal to zero orders.", "evidence": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped"}','mathematical_claim','Eigenvalues of the transpose on the continuous dual of the nuclear Fréchet quotient equal the zeros of the meromorphic completed zeta, with algebraic multiplicities equal to zero orders.');
INSERT INTO "graph_nodes" VALUES('OP62-MEYER-TRACE','graphs/knowledge_graph.jsonl',1497,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"record_type": "node", "id": "OP62-MEYER-TRACE", "type": "mathematical_claim", "label": "For all f in the specified test algebra the signed Mellin spectral sum equals the virtual character and sum of local distributions, with pole orders positive and zero orders negative. Density in the proof is density of convolutions of compactly supported smooth functions in the test algebra.", "evidence": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped"}','mathematical_claim','For all f in the specified test algebra the signed Mellin spectral sum equals the virtual character and sum of local distributions, with pole orders positive and zero orders negative. Density in the proof is density of convolutions of compactly supported smooth functions in the test algebra.');
INSERT INTO "graph_nodes" VALUES('OP62-WEIL72-POSITIVE','graphs/knowledge_graph.jsonl',1498,'source_statement_scoped','audits/adversarial_reviews/witness62_operator_frontier.md','{"record_type": "node", "id": "OP62-WEIL72-POSITIVE", "type": "mathematical_claim", "label": "Positivity of the explicit-formula distribution on W is stated to be equivalent to the conjunction of RH and Artin’s conjecture for all L_k(χ,s).", "evidence": "audits/adversarial_reviews/witness62_operator_frontier.md", "status": "source_statement_scoped"}','mathematical_claim','Positivity of the explicit-formula distribution on W is stated to be equivalent to the conjunction of RH and Artin’s conjecture for all L_k(χ,s).');
INSERT INTO "graph_nodes" VALUES('OBS-LI-001','graphs/knowledge_graph.jsonl',1499,'independently_reconstructed_generic_class_obstruction; no novelty claim','proposals/independent_campaigns/li_advocate.md','{"record_type": "node", "id": "OBS-LI-001", "type": "mathematical_claim", "label": "For every N there is a real symmetric order-one entire function with all zeros in the critical strip, first N Li derivatives positive, and an off-line quartet. This remains true with Riemann–von Mangoldt smooth zero count to O(1).", "evidence": "proposals/independent_campaigns/li_advocate.md", "status": "independently_reconstructed_generic_class_obstruction; no novelty claim"}','mathematical_claim','For every N there is a real symmetric order-one entire function with all zeros in the critical strip, first N Li derivatives positive, and an off-line quartet. This remains true with Riemann–von Mangoldt smooth zero count to O(1).');
