INSERT INTO "graph_nodes" VALUES('CONN-DIR-HR501','graphs/knowledge_graph.jsonl',1598,'adjudicated_scoped; no publication novelty claim','audits/adversarial_reviews/horizontal_ratio_slope_director_adjudication_round5.md','{"record_type": "node", "id": "CONN-DIR-HR501", "type": "research_connection", "label": "The exact first-order horizontal zeta-ratio norm is a weighted multiplicity statistic under RH; an order-one Schur/Poisson mass identity connects the published approximation norm to local beta-integral profiles at zeros.", "evidence": "audits/adversarial_reviews/horizontal_ratio_slope_director_adjudication_round5.md", "status": "adjudicated_scoped; no publication novelty claim"}','research_connection','The exact first-order horizontal zeta-ratio norm is a weighted multiplicity statistic under RH; an order-one Schur/Poisson mass identity connects the published approximation norm to local beta-integral profiles at zeros.');
INSERT INTO "graph_nodes" VALUES('CONN-RI301','graphs/knowledge_graph.jsonl',1599,'Complete auxiliary proof plus independent parent review; separate third review pending. Prior realization theory acknowledged; novelty unassessed.','connections/inner_round2.jsonl','{"record_type": "node", "id": "CONN-RI301", "type": "research_connection", "label": "The finite passive transfer pattern from Tabak–MabuchiEq41 becomes S0(k)=I−iG(k−Ω+iG*G/2)^−1G* under s=−ik. A specified closed edge-plus-state boundary operator realizes it self-adjointly; dark-state decomposition and determinant phase budget then give the one-sided curvature boundΔN<3E+M.", "evidence": "connections/inner_round2.jsonl", "status": "Complete auxiliary proof plus independent parent review; separate third review pending. Prior realization theory acknowledged; novelty unassessed."}','research_connection','The finite passive transfer pattern from Tabak–MabuchiEq41 becomes S0(k)=I−iG(k−Ω+iG*G/2)^−1G* under s=−ik. A specified closed edge-plus-state boundary operator realizes it self-adjointly; dark-state decomposition and determinant phase budget then give the one-sided curvature boundΔN<3E+M.');
INSERT INTO "graph_nodes" VALUES('CONN-RI302','graphs/knowledge_graph.jsonl',1600,'Independently checked by child and parent; no error in a cited theorem alleged.','connections/inner_round2.jsonl','{"record_type": "node", "id": "CONN-RI302", "type": "research_connection", "label": "The finite-defect3d relative-count theorem requires a densely defined common symmetric restriction. For the scalar boundary-coupled auxiliary model versus periodic derivative⊕[d], common domains imposez=0, so no such dense common restriction exists. The auxiliary degree cannot be erased by treating this as an edge-only domain perturbation.", "evidence": "connections/inner_round2.jsonl", "status": "Independently checked by child and parent; no error in a cited theorem alleged."}','research_connection','The finite-defect3d relative-count theorem requires a densely defined common symmetric restriction. For the scalar boundary-coupled auxiliary model versus periodic derivative⊕[d], common domains imposez=0, so no such dense common restriction exists. The auxiliary degree cannot be erased by treating this as an edge-only domain perturbation.');
