INSERT INTO "papers" VALUES('PAPER-ACA65-PRIME-WEYL-NEW','corpus/bibliography.jsonl',136,'full_text_accessed','papers/analytic65_classical_analytic_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "exponential", "arxiv_id": "2608.14777", "audit_level": 0, "authors": ["James Maynard", "Mayank Pandey", "Maksym Radziwiłł"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2608.14777", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "For α=a/q+ε with (a,q)=1, q≤N^(1/2) and |ε|≤1/(qN^(1/2)), the von Mangoldt-weighted linear sum over n<N is bounded by N^{o(1)}(N/√B+N^(19/24)), where B=max(q,qN|ε|).", "novelty_claim": false, "paper_id": "PAPER-ACA65-PRIME-WEYL-NEW", "pdf_pages": 17, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1", "record_path": "papers/analytic65_classical_analytic_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "A logarithmic prime phase first needs accurate local linearization and rational approximation at the resulting slope.", "source_locator": "Theorem 1.1", "source_path": "sources/analytic65_classical_analytic/prime_weyl_new.pdf", "source_sha256": "4de22ea64e5b5899f3951d5a222ff7f952951f5880b620b28daafa24e9312188", "source_url": "https://arxiv.org/pdf/2608.14777v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Exponential sums over primes", "track_file": "papers/analytic65_records.jsonl", "transfer_hypothesis": "A logarithmic phase needs local linearization with a controlled error and rational approximation at the resulting slope.", "venue": "arXiv", "version": "arXiv:2608.14777v1", "version_date": "2026-08-14", "version_receipt": "sources/analytic65_classical_analytic/prime_weyl_new.html", "whole_work_read": false, "year": 2026, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/analytic65_records.jsonl", "id": "PAPER-ACA65-PRIME-WEYL-NEW", "arxiv": "2608.14777", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ACA65-PRIME-WEYL-NEW"]}','Exponential sums over primes','["James Maynard", "Mayank Pandey", "Maksym Radziwiłł"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2608.14777v1','https://arxiv.org/pdf/2608.14777v1','4de22ea64e5b5899f3951d5a222ff7f952951f5880b620b28daafa24e9312188','papers/analytic65_classical_analytic_notes.md','papers/analytic65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ACA65-MULTIPLICATIVE-LOG','corpus/bibliography.jsonl',137,'full_text_accessed','papers/analytic65_classical_analytic_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "exponential", "arxiv_id": "2610.22081", "audit_level": 0, "authors": ["Haozhe Gou"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2610.22081", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "For 1-bounded multiplicative f, (a,q)=1, 1≤q≤x and |α−a/q|≤1/(qx), the logarithmically weighted twist is bounded by (4/√6+o(1))log(x)/√q+O(log q). Complete multiplicativity improves 4/√6 to 1.", "novelty_claim": false, "paper_id": "PAPER-ACA65-MULTIPLICATIVE-LOG", "pdf_pages": 13, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1, (1.5) and Corollary 1.2", "record_path": "papers/analytic65_classical_analytic_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Keep the logarithmic averaging and additive phase when applying to a detector coefficient block. Removing either changes the estimate.", "source_locator": "Theorem 1.1, (1.5) and Corollary 1.2", "source_path": "sources/analytic65_classical_analytic/multiplicative_log.pdf", "source_sha256": "7e280cc03edecbe14957a36e438f84b17d42d59a9861088374ec40b55eb36997", "source_url": "https://arxiv.org/pdf/2610.22081v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Logarithmic exponential sums with multiplicative coefficients", "track_file": "papers/analytic65_records.jsonl", "transfer_hypothesis": "Preserve logarithmic weighting and the secondary term. Corollary 1.2 removes that term under the additional narrow q range.", "venue": "arXiv", "version": "arXiv:2610.22081v1", "version_date": "2026-10-15", "version_receipt": "sources/analytic65_classical_analytic/multiplicative_log.html", "whole_work_read": false, "year": 2026, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/analytic65_records.jsonl", "id": "PAPER-ACA65-MULTIPLICATIVE-LOG", "arxiv": "2610.22081", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ACA65-MULTIPLICATIVE-LOG"]}','Logarithmic exponential sums with multiplicative coefficients','["Haozhe Gou"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2610.22081v1','https://arxiv.org/pdf/2610.22081v1','7e280cc03edecbe14957a36e438f84b17d42d59a9861088374ec40b55eb36997','papers/analytic65_classical_analytic_notes.md','papers/analytic65_records.jsonl');
