INSERT INTO "papers" VALUES('PAPER-ACA65-GAPS-SHORT','corpus/bibliography.jsonl',153,'full_text_accessed','papers/analytic65_classical_analytic_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "prime-gaps", "arxiv_id": "1707.05437", "audit_level": 0, "authors": ["Ryan Alweiss", "Sammy Luo"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1707.05437", "doi": "10.1007/s40993-018-0109-y", "full_text_accessed": true, "language": "English", "main_result": "Theorem 1.1 gives an admissible-linear-forms lower count. Corollary 1.2 gives bounded consecutive prime gaps in [x−h,x] for δ in [0.525,1], x^δ≤h≤x and x sufficiently large.", "novelty_claim": false, "paper_id": "PAPER-ACA65-GAPS-SHORT", "pdf_pages": 29, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1 and Corollary 1.2", "record_path": "papers/analytic65_classical_analytic_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "The sieve uses short-interval distribution in arithmetic progressions, an input stronger than finding a single prime in the interval.", "source_locator": "Theorem 1.1 and Corollary 1.2", "source_path": "sources/analytic65_classical_analytic/gaps_short.pdf", "source_sha256": "8c776cd1264e5d65b36a9ffe94f25ccc156290b07ac67688c247699d4dea28b2", "source_url": "https://arxiv.org/pdf/1707.05437v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Bounded gaps between primes in short intervals", "track_file": "papers/analytic65_records.jsonl", "transfer_hypothesis": "Maintain the relevant distribution in arithmetic progressions when adapting the sieve.", "venue": "arXiv", "version": "arXiv:1707.05437v1", "version_date": "2017-07-18", "version_receipt": "sources/analytic65_classical_analytic/gaps_short.html", "whole_work_read": false, "year": 2017, "admi