INSERT INTO "papers" VALUES('PAPER-ACA65-PRIME-PHASE-SHORT','corpus/bibliography.jsonl',162,'full_text_accessed','papers/analytic65_classical_analytic_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "prime-gaps", "arxiv_id": "1902.04708", "audit_level": 0, "authors": ["Kaisa Matomäki", "Xuancheng Shao"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1902.04708", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "For H=N^θ with fixed θ>2/3 and e(αn^k) with k a positive integer, a Λ-weighted twist of magnitude at least H/(log N)^A, A≥2, forces an integer 1≤q≤(log N)^{O_k(A)} with ||qα||≤(log N)^{O_k(A)}/(N^{k−1}H).", "novelty_claim": false, "paper_id": "PAPER-ACA65-PRIME-PHASE-SHORT", "pdf_pages": 20, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1 and the major-arc discussion immediately following", "record_path": "papers/analytic65_classical_analytic_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "A log-phase reduction must quantify the Taylor remainder at that interval length and keep the exceptional rational slopes.", "source_locator": "Theorem 1.1 and the major-arc discussion immediately following", "source_path": "sources/analytic65_classical_analytic/prime_phase_short.pdf", "source_sha256": "0f6de1d6d62a7b75cce45e5eb4a24ab9dcb5a323906aac0e7fae4e8fb7f6dbb9", "source_url": "https://arxiv.org/pdf/1902.04708v3", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Discorrelation between primes in short intervals and polynomial phases", "track_file": "papers/analytic65_records.jsonl", "transfer_hypothesis": "A log-phase reduction must establish a matching monomial approximation and a sufficiently small remainder. A general polynomial or nilsequence requires its separate theorem.", 