INSERT INTO "papers" VALUES('PAPER-ACA65-GAP-MEAN-SQUARE','corpus/bibliography.jsonl',164,'full_text_accessed','papers/analytic65_classical_analytic_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "prime-gaps", "arxiv_id": "2212.10867", "audit_level": 0, "authors": ["Julia Stadlmann"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2212.10867", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "For every ε>0 the source bounds the unnormalized sum of (p_(n+1)−p_n)^2 over p_n≤x by Oε(x^(1.23+ε)).", "novelty_claim": false, "paper_id": "PAPER-ACA65-GAP-MEAN-SQUARE", "pdf_pages": 71, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1 and §1.1", "record_path": "papers/analytic65_classical_analytic_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "A second-moment estimate controls aggregate gaps. To bound a particular gap extract it with the squared scale and keep the full height dependence.", "source_locator": "Theorem 1 and §1.1", "source_path": "sources/analytic65_classical_analytic/gap_mean_square.pdf", "source_sha256": "5f36c9f967da2be720b42f25e48d398ffef71fc385561d9c7d47b2e1adede549", "source_url": "https://arxiv.org/pdf/2212.10867v2", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "On the mean square gap between primes", "track_file": "papers/analytic65_records.jsonl", "transfer_hypothesis": "A particular gap is bounded by a single summand of the unnormalized sum; a per-prime average divides by π(x).", "venue": "arXiv", "version": "arXiv:2212.10867v2", "version_date": "2026-10-25", "version_receipt": "sources/analytic65_classical_analytic/gap_mean_square.html", "whole_work_read": false, "year": 2022, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pend