INSERT INTO "papers" VALUES('PAPER-AH70-DEDEKIND-COUNT','corpus/bibliography.jsonl',179,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zero-counting", "arxiv_id": "2102.04663", "audit_level": 0, "authors": ["Elchin Hasanalizade", "Quanli Shen", "Peng-Jie Wong"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2102.04663", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For any number field K and T≥1, the baseline for N_K(T) is (T/π)log(d_K(T/(2πe))^n_K)−r₁/4. The bound is 0.22737 log(d_K(T+2)^n_K/(2π)^n_K)+23.02528n_K+4.51954.", "novelty_claim": false, "paper_id": "PAPER-AH70-DEDEKIND-COUNT", "pdf_pages": 15, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1 equation (1.2) and Table 2", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Retain the r₁/4 main-term adjustment and verify endpoint zero-count convention before differencing the count.", "source_locator": "Theorem 1.1 equation (1.2) and Table 2", "source_path": "sources/analytic70_history/dedekind_count.pdf", "source_sha256": "f86bc699394c6c64c06bfab787c3daec8995293f4e1ca1e930c45dbc884f4022", "source_url": "https://arxiv.org/pdf/2102.04663v3", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Counting zeros of Dedekind zeta functions", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Use the two-sided height count in the source and preserve the r₁ parity term and absolute discriminant.", "venue": "arXiv", "version": "arXiv:2102.04663v3", "version_date": "2021-05-03", "version_receipt": "sources/analytic70_history/dedekind_count.html", "whole_work_read": false, "year": 2021, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-DEDEKIND-COUNT", "arxiv": "2102.04663", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-DEDEKIND-COUNT"]}','Counting zeros of Dedekind zeta functions','["Elchin Hasanalizade", "Quanli Shen", "Peng-Jie Wong"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2102.04663v3','https://arxiv.org/pdf/2102.04663v3','f86bc699394c6c64c06bfab787c3daec8995293f4e1ca1e930c45dbc884f4022','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-DIRICHLET-COUNT','corpus/bibliography.jsonl',180,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zero-counting", "arxiv_id": "2005.02989", "audit_level": 0, "authors": ["Michael A. Bennett", "Greg Martin", "Kevin O''Bryant", "Andrew Rechnitzer"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2005.02989", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For χ of conductor q>1 and T≥5/7, write ℓ=log(q(T+2)/(2π)). If ℓ≤1.567 the count is zero. Otherwise the absolute error from (T/π)log(qT/(2πe))−χ(−1)/4 is ≤0.22737ℓ+2log(1+ℓ)−0.5.", "novelty_claim": false, "paper_id": "PAPER-AH70-DIRICHLET-COUNT", "pdf_pages": 22, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1 and count definition", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Use primitive inducing conductor rather than ambient modulus and preserve the parity term.", "source_locator": "Theorem 1.1 and count definition", "source_path": "sources/analytic70_history/dirichlet_count.pdf", "source_sha256": "bc7d063bcde319274f878acb05816c3ddeddce8820ae614485e9ff9ecd64ab43", "source_url": "https://arxiv.org/pdf/2005.02989v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Counting Zeros of Dirichlet $L$-Functions", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Retain the parity correction and conductor rather than modulus in the count normalization.", "venue": "arXiv", "version": "arXiv:2005.02989v1", "version_date": "2020-05-06", "version_receipt": "sources/analytic70_history/dirichlet_count.html", "whole_work_read": false, "year": 2020, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-DIRICHLET-COUNT", "arxiv": "2005.02989", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-DIRICHLET-COUNT"]}','Counting Zeros of Dirichlet $L$-Functions','["Michael A. Bennett", "Greg Martin", "Kevin O''Bryant", "Andrew Rechnitzer"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2005.02989v1','https://arxiv.org/pdf/2005.02989v1','bc7d063bcde319274f878acb05816c3ddeddce8820ae614485e9ff9ecd64ab43','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
