INSERT INTO "papers" VALUES('PAPER-AH70-TURING-INTEGRAL','corpus/bibliography.jsonl',184,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zero-counting", "arxiv_id": "2512.23064", "audit_level": 0, "authors": ["Victor Amberger"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2512.23064", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For t₂>t₁≥653, |S₁(t₂)−S₁(t₁)|≤1.680+0.186 loglog t₂+0.0314 log t₂. The conditional-in-data Turing criterion uses K consecutive Rosser-rule Gram blocks with union [g_n,g_p), g_n≥t₀ and the strict cutoff in Theorem 2.3, and concludes N(g_n)≤n+1 and N(g_p)≥p+1.", "novelty_claim": false, "paper_id": "PAPER-AH70-TURING-INTEGRAL", "pdf_pages": 17, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 2.1 and 2.3", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "A certificate must establish the block hypotheses and the exact strict inequality involving the final Gram point g_p before using the count.", "source_locator": "Theorems 2.1 and 2.3", "source_path": "sources/analytic70_history/turing_integral.pdf", "source_sha256": "60264209c40721891f1fc87e7d259a85907dfbfa44542dfe4328e8f2305cdea8", "source_url": "https://arxiv.org/pdf/2512.23064v3", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Bounding the integral of the argument of the Riemann Zeta function", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Check the Gram-block and endpoint conditions before claiming completeness for a supplied zero list.", "venue": "arXiv", "version": "arXiv:2512.23064v3", "version_date": "2026-01-04", "version_receipt": "sources/analytic70_history/turing_integral.html", "whole_work_read": false, "year": 2025, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-TURING-INTEGRAL", "arxiv": "2512.23064", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-TURING-INTEGRAL"]}','Bounding the integral of the argument of the Riemann Zeta function','["Victor Amberger"]',NULL,'2025',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2512.23064v3','https://arxiv.org/pdf/2512.23064v3','60264209c40721891f1fc87e7d259a85907dfbfa44542dfe4328e8f2305cdea8','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-DERIVATIVE-COUNT','corpus/bibliography.jsonl',185,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zero-counting", "arxiv_id": "1512.06419", "audit_level": 1, "authors": ["Fan Ge"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1512.06419", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Whole text read, scoped transfer tracked", "language": "English", "main_result": "Under RH, the number of ζ′ zeros with β′>0 and 0<γ′≤T is T/(2π)log(T/(4πe))+O(log T/loglog T); Thm. 2 uses increasing loglog T≪Φ(T)≪log T for the ordinary zero count.", "novelty_claim": false, "paper_id": "PAPER-AH70-DERIVATIVE-COUNT", "pdf_pages": 9, "publication_status": "Verified arXiv manifestation", "read_scope": "Whole pinned edition. Whole source, Theorems 1–2, Lemmas 3–8, (8) and (13)", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "The transfer uses a geometric angle bound and Zhang''s integrated ζ′-zero control, so stronger ζ counts alone do not erase its extra √(log T) loglog T term.", "source_locator": "Whole source, Theorems 1–2, Lemmas 3–8, (8) and (13)", "source_path": "sources/analytic70_history/derivative_count.pdf", "source_sha256": "c3fd105752b18b674d712126f352e66e03ffbdc26f38fa7010ad1e16ef8c036c", "source_url": "https://arxiv.org/pdf/1512.06419v2", "substantive_reading": true, "title": "The Number of Zeros of $\\zeta''(s)$", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "The transfer uses a geometric angle bound and Zhang''s integrated ζ′-zero control, so stronger ζ counts alone do not erase its extra √(log T) loglog T term.", "venue": "arXiv", "version": "arXiv:1512.06419v2", "version_date": "2016-04-14", "version_receipt": "sources/analytic70_history/derivative_count.html", "whole_work_read": true, "year": 2015, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-DERIVATIVE-COUNT", "arxiv": "1512.06419", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-DERIVATIVE-COUNT"]}','The Number of Zeros of $\zeta''(s)$','["Fan Ge"]',NULL,'2015',1,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1512.06419v2','https://arxiv.org/pdf/1512.06419v2','c3fd105752b18b674d712126f352e66e03ffbdc26f38fa7010ad1e16ef8c036c','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-ARGUMENT-II','corpus/bibliography.jsonl',186,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zero-counting", "arxiv_id": "1208.5846", "audit_level": 0, "authors": ["T. S. Trudgian"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1208.5846", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For T≥e, the paper proves |S(T)|≤0.111 log T+0.275 loglog T+2.450.", "novelty_claim": false, "paper_id": "PAPER-AH70-ARGUMENT-II", "pdf_pages": 10, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1 and Corollary 1", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "For a tail estimate, use the same S(T) branch and zero-ordinate convention when converting to inclusive N(T).", "source_locator": "Theorem 1 and Corollary 1", "source_path": "sources/analytic70_history/argument_ii.pdf", "source_sha256": "274b3a0a14d79400f23505ede664a2f77b0a6ad7278245d25ec6e06169e2a303", "source_url": "https://arxiv.org/pdf/1208.5846v2", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "An improved upper bound for the argument of the Riemann zeta-function on the critical line II", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "For a tail estimate, use the same S(T) branch and zero-ordinate convention when converting to inclusive N(T).", "venue": "arXiv", "version": "arXiv:1208.5846v2", "version_date": "2012-09-05", "version_receipt": "sources/analytic70_history/argument_ii.html", "whole_work_read": false, "year": 2012, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-ARGUMENT-II", "arxiv": "1208.5846", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-ARGUMENT-II"]}','An improved upper bound for the argument of the Riemann zeta-function on the critical line II','["T. S. Trudgian"]',NULL,'2012',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1208.5846v2','https://arxiv.org/pdf/1208.5846v2','274b3a0a14d79400f23505ede664a2f77b0a6ad7278245d25ec6e06169e2a303','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-COUNT-AUXILIARY','corpus/bibliography.jsonl',187,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zero-counting", "arxiv_id": "2406.08890", "audit_level": 1, "authors": ["Juan Arias de Reyna"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2406.08890", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Whole text read, scoped transfer tracked", "language": "English", "main_result": "The Riemann auxiliary function''s count at positive ordinates through T is T/(4π)log(T/(2π))−T/(4π)−(1/2)√(T/(2π))+O(T^(2/5)log²T).", "novelty_claim": false, "paper_id": "PAPER-AH70-COUNT-AUXILIARY", "pdf_pages": 7, "publication_status": "Verified arXiv manifestation", "read_scope": "Whole pinned edition. Whole source, Lemma 1, Remark 2, Theorem 3 and (2)–(8)", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "These are auxiliary-function zeros. A critical-line ζ count would also need their side-of-line locations. Backlund''s lemma requires a zero-free segment and holomorphy on the enclosing disk.", "source_locator": "Whole source, Lemma 1, Remark 2, Theorem 3 and (2)–(8)", "source_path": "sources/analytic70_history/count_auxiliary.pdf", "source_sha256": "2a98c2e69e0e2c9eaa29ce3f26a5d9092333761b244fe6f9d0466117d21a0b2b", "source_url": "https://arxiv.org/pdf/2406.08890v1", "substantive_reading": true, "title": "On the number of zeros of $\\mathop{\\mathcal R}(s)$", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "These are auxiliary-function zeros. A critical-line ζ count would also need their side-of-line locations. Backlund''s lemma requires a zero-free segment and holomorphy on the enclosing disk.", "venue": "arXiv", "version": "arXiv:2406.08890v1", "version_date": "2024-06-13", "version_receipt": "sources/analytic70_history/count_auxiliary.html", "whole_work_read": true, "year": 2024, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-COUNT-AUXILIARY", "arxiv": "2406.08890", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-COUNT-AUXILIARY"]}','On the number of zeros of $\mathop{\mathcal R}(s)$','["Juan Arias de Reyna"]',NULL,'2024',1,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2406.08890v1','https://arxiv.org/pdf/2406.08890v1','2a98c2e69e0e2c9eaa29ce3f26a5d9092333761b244fe6f9d0466117d21a0b2b','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-HIGHER-ZERO-COUNT','corpus/bibliography.jsonl',188,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zero-counting", "arxiv_id": "2007.14617", "audit_level": 0, "authors": ["Fan Ge", "Ade Irma Suriajaya"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2007.14617", "doi": "10.1007/s11139-019-00219-z", "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "Assuming RH, for each fixed positive integer k the source counts ζ^(k) zeros with β_k>0 and 0<γ_k≤T. The count is (T/2π)log(T/(4πe))+O_k(log T/loglog T).", "novelty_claim": false, "paper_id": "PAPER-AH70-HIGHER-ZERO-COUNT", "pdf_pages": 10, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Definition of N_k and Theorem 1", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Check the region and k dependence before extending a first-derivative energy argument.", "source_locator": "Definition of N_k and Theorem 1", "source_path": "sources/analytic70_history/higher_zero_count.pdf", "source_sha256": "20f351c3cbc4be4e2a3f45db3e0a872d6e19c9a920779ee77241d97227045f07", "source_url": "https://arxiv.org/pdf/2007.14617v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Note on the number of zeros of $\\zeta^{(k)}(s)$", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Retain the strict real-part cutoff, ordinate range, and fixed derivative order.", "venue": "arXiv", "version": "arXiv:2007.14617v1", "version_date": "2020-07-29", "version_receipt": "sources/analytic70_history/higher_zero_count.html", "whole_work_read": false, "year": 2020, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-HIGHER-ZERO-COUNT", "arxiv": "2007.14617", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-HIGHER-ZERO-COUNT"]}','Note on the number of zeros of $\zeta^{(k)}(s)$','["Fan Ge", "Ade Irma Suriajaya"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2007.14617v1','https://arxiv.org/pdf/2007.14617v1','20f351c3cbc4be4e2a3f45db3e0a872d6e19c9a920779ee77241d97227045f07','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-COMPLETED-COMBO','corpus/bibliography.jsonl',189,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zero-counting", "arxiv_id": "2401.02813", "audit_level": 0, "authors": ["Pedro Ribeiro"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2401.02813", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "Theorem A states that Σ_j c_j η(s+iλ_j) has infinitely many zeros on Re(s)=1/2 when the nonzero real c_j are absolutely summable and the distinct real λ_j form a bounded sequence attaining its bounds. η is the displayed gamma-completed ζ.", "novelty_claim": false, "paper_id": "PAPER-AH70-COMPLETED-COMBO", "pdf_pages": 38, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Quoted Theorem A; Theorems B and 1.1 are separate extensions", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "A combined function can have distinct cancellation phenomena. Establish the actual coefficients, shifts and endpoint-attainment requirement before using the quoted ζ example.", "source_locator": "Quoted Theorem A; Theorems B and 1.1 are separate extensions", "source_path": "sources/analytic70_history/completed_combo.pdf", "source_sha256": "499c12f021775aae6cca1bf2626c0cb4bee11cbe063528576058fa8d87d3bb3d", "source_url": "https://arxiv.org/pdf/2401.02813v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Estimates for the number of zeros of shifted combinations of completed Dirichlet series", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "This is infinitude on the line; exhaustive localization or conclusions on the factors require additional input.", "venue": "arXiv", "version": "arXiv:2401.02813v1", "version_date": "2024-01-05", "version_receipt": "sources/analytic70_history/completed_combo.html", "whole_work_read": false, "year": 2024, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-COMPLETED-COMBO", "arxiv": "2401.02813", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-COMPLETED-COMBO"]}','Estimates for the number of zeros of shifted combinations of completed Dirichlet series','["Pedro Ribeiro"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2401.02813v1','https://arxiv.org/pdf/2401.02813v1','499c12f021775aae6cca1bf2626c0cb4bee11cbe063528576058fa8d87d3bb3d','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-IMPROVED-COUNT','corpus/bibliography.jsonl',190,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zero-counting", "arxiv_id": "2412.15470", "audit_level": 0, "authors": ["Chiara Bellotti", "Peng-Jie Wong"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2412.15470", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For every T≥e, |N(T)−T/(2π)log(T/(2πe))|≤0.10076 log T+0.24460 loglog T+8.08344.", "novelty_claim": false, "paper_id": "PAPER-AH70-IMPROVED-COUNT", "pdf_pages": 32, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Calculate the normalized count error for the actual height, including the nonlogarithmic term when taking short-window differences.", "source_locator": "Theorem 1.1", "source_path": "sources/analytic70_history/improved_count.pdf", "source_sha256": "9299073e0fbb836ca744790e5ac2c03a496df3194409aaa87832ba6161ead3b5", "source_url": "https://arxiv.org/pdf/2412.15470v2", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Improved estimates for the argument and zero-counting function of the Riemann zeta-function", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Calculate the normalized count error for the actual height, including the nonlogarithmic term when taking short-window differences.", "venue": "arXiv", "version": "arXiv:2412.15470v2", "version_date": "2025-07-07", "version_receipt": "sources/analytic70_history/improved_count.html", "whole_work_read": false, "year": 2024, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-IMPROVED-COUNT", "arxiv": "2412.15470", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-IMPROVED-COUNT"]}','Improved estimates for the argument and zero-counting function of the Riemann zeta-function','["Chiara Bellotti", "Peng-Jie Wong"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2412.15470v2','https://arxiv.org/pdf/2412.15470v2','9299073e0fbb836ca744790e5ac2c03a496df3194409aaa87832ba6161ead3b5','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-DIRICHLET-DEDEKIND-ERROR','corpus/bibliography.jsonl',191,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zero-counting", "arxiv_id": "1206.1844", "audit_level": 0, "authors": ["T. S. Trudgian"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1206.1844", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "Theorem 1 bounds the two-sided Dirichlet zero count for T≥1 and primitive nonprincipal χ mod k by absolute error ≤0.317 log(kT)+6.401 from (T/π)log(kT/(2πe)). Theorem 2 is a separately stated Dedekind estimate.", "novelty_claim": false, "paper_id": "PAPER-AH70-DIRICHLET-DEDEKIND-ERROR", "pdf_pages": 12, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 1–2 and Table 1", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "The switches in Table 1 depend on the chosen coefficient pair. The ζ-only count uses a different symmetry convention.", "source_locator": "Theorems 1–2 and Table 1", "source_path": "sources/analytic70_history/dirichlet_dedekind_error.pdf", "source_sha256": "c6e94ad46b6ce7b8e180566970093ce49cedcdc285e5d91c9db76dc410f42b20", "source_url": "https://arxiv.org/pdf/1206.1844v4", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "An improved upper bound for the error in the zero-counting formulae for Dirichlet $L$-functions and Dedekind zeta-functions", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Use the exact count definition and retain primitive nonprincipal scope for this bound.", "venue": "arXiv", "version": "arXiv:1206.1844v4", "version_date": "2013-12-05", "version_receipt": "sources/analytic70_history/dirichlet_dedekind_error.html", "whole_work_read": false, "year": 2012, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-DIRICHLET-DEDEKIND-ERROR", "arxiv": "1206.1844", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-DIRICHLET-DEDEKIND-ERROR"]}','An improved upper bound for the error in the zero-counting formulae for Dirichlet $L$-functions and Dedekind zeta-functions','["T. S. Trudgian"]',NULL,'2012',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1206.1844v4','https://arxiv.org/pdf/1206.1844v4','c6e94ad46b6ce7b8e180566970093ce49cedcdc285e5d91c9db76dc410f42b20','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
