INSERT INTO "papers" VALUES('PAPER-AH70-STRIP-TWISTED','corpus/bibliography.jsonl',193,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "2312.10614", "audit_level": 0, "authors": ["Jinbo Yu"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2312.10614", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For fixed 0<C₁<C₂, C₁T<Y<C₂T, T≥max(e,1/C₁) and 1/4<σ<1/2, the dyadic twisted mean square has main, oscillatory and remainder terms depending on the chosen polynomial A.", "novelty_claim": false, "paper_id": "PAPER-AH70-STRIP-TWISTED", "pdf_pages": 30, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1 and formulas preceding it", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Do not transfer the leading term alone without bounding the two oscillatory differences and verifying A''s coefficient hypotheses.", "source_locator": "Theorem 1.1 and formulas preceding it", "source_path": "sources/analytic70_history/strip_twisted.pdf", "source_sha256": "11c56435767489098f022a960eb6d23817ea5b57b0bfef3dbcf832ecd4a38835", "source_url": "https://arxiv.org/pdf/2312.10614v2", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "The mean square of the product of the Riemann zeta-function and a Dirichlet polynomial in the critical strip", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Do not transfer the leading term alone without bounding the two oscillatory differences and verifying A''s coefficient hypotheses.", "venue": "arXiv"