INSERT INTO "papers" VALUES('PAPER-AH70-ARITH-DISCRETE','corpus/bibliography.jsonl',195,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "2401.01892", "audit_level": 0, "authors": ["Hirotaka Kobayashi"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2401.01892", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For fixed spacing a in the increasing progression with e^(2πk/a) irrational for every positive integer k, the critical-line ζ mean square on arithmetic progression an+b is (T/a)log T+o_a(T log T) in the printed setup.", "novelty_claim": false, "paper_id": "PAPER-AH70-ARITH-DISCRETE", "pdf_pages": 14, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1, (3)", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "The irrationality of this spacing excludes exact multiplicative resonances; actual zero sampling has a different distribution.", "source_locator": "Theorem 1.1, (3)", "source_path": "sources/analytic70_history/arith_discrete.pdf", "source_sha256": "f147a9d4b1daff7506b39de3eeb6b16ff8bbc616e31d2bc1ca84f84ff179f16a", "source_url": "https://arxiv.org/pdf/2401.01892v1", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Mean-square values of the Riemann zeta function on arithmetic progressions", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "The irrationality of this spacing excludes exact multiplicative resonances; actual zero sampling has a different distribution.", "venue": "arXiv", "version": "arXiv:240