INSERT INTO "papers" VALUES('PAPER-AH70-DIR-MEAN','corpus/bibliography.jsonl',197,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "0907.4767", "audit_level": 1, "authors": ["Michel Weber"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/0907.4767", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Whole text read, scoped transfer tracked", "language": "English", "main_result": "For every integer q≥1, any real frequencies, nonnegative coefficients and T>0, the 2q-th mean over |t|≤T is ≥c_q(Σa_n²)^q.", "novelty_claim": false, "paper_id": "PAPER-AH70-DIR-MEAN", "pdf_pages": 6, "publication_status": "Verified arXiv manifestation", "read_scope": "Whole pinned edition. Whole source, Theorem 1, Lemma 2 and Corollary 3", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "For signed arrays only the stated one-way majorization by a nonnegative array is available. The lower bound itself requires positivity.", "source_locator": "Whole source, Theorem 1, Lemma 2 and Corollary 3", "source_path": "sources/analytic70_history/dir_mean.pdf", "source_sha256": "b05a40fcec1d993e5d201e87011e14d5518104b6c1bcb16ce395951843e92fc4", "source_url": "https://arxiv.org/pdf/0907.4767v1", "substantive_reading": true, "title": "On Mean Values of Dirichlet Polynomials", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "For signed arrays only the stated one-way majorization by a nonnegative array is available. The lower bound itself requires positivity.", "venue": "arXiv", "version": "arXiv:0907.4767v1", "version_date": "2009-07-28", "version_receipt": "sources/analytic70_history/dir_mean.html", "whole_work_read": true, "year": 2009, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-DIR-MEAN", "arxiv": "0907.4767", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-DIR-MEAN"]}','On Mean Values of Dirichlet Polynomials','["Michel Weber"]',NULL,'2009',1,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv:0907.4767v1','https://arxiv.org/pdf/0907.4767v1','b05a40fcec1d993e5d201e87011e14d5518104b6c1bcb16ce395951843e92fc4','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-HURWITZ-FOURTH','corpus/bibliography.jsonl',198,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "2405.10888", "audit_level": 0, "authors": ["Winston Heap", "Anurag Sahay"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2405.10888", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For irrational 0<α<1 with irrationality exponent μ(α)<3, the fourth mean of Hurwitz ζ(1/2+it,α) over [T,2T] is O(T(log T)²) for large T.", "novelty_claim": false, "paper_id": "PAPER-AH70-HURWITZ-FOURTH", "pdf_pages": 34, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "The shift’s Diophantine condition is part of the estimate. It cannot be replaced by generic irrationality.", "source_locator": "Theorem 1", "source_path": "sources/analytic70_history/hurwitz_fourth.pdf", "source_sha256": "13eae3ed892c9189369a6fb9ad14bd4f01a9eb27db4df2aabf544c2fc2454763", "source_url": "https://arxiv.org/pdf/2405.10888v1", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "The fourth moment of the Hurwitz zeta function", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "The shift’s Diophantine condition is part of the estimate. It cannot be replaced by generic irrationality.", "venue": "arXiv", "version": "arXiv:2405.10888v1", "version_date": "2024-05-17", "version_receipt": "sources/analytic70_history/hurwitz_fourth.html", "whole_work_read": false, "year": 2024, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-HURWITZ-FOURTH", "arxiv": "2405.10888", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-HURWITZ-FOURTH"]}','The fourth moment of the Hurwitz zeta function','["Winston Heap", "Anurag Sahay"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2405.10888v1','https://arxiv.org/pdf/2405.10888v1','13eae3ed892c9189369a6fb9ad14bd4f01a9eb27db4df2aabf544c2fc2454763','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-HARDY-MEAN','corpus/bibliography.jsonl',199,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "2003.11349", "audit_level": 0, "authors": ["Xiaodong Cao", "Yoshio Tanigawa", "Wenguang Zhai"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2003.11349", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For large T the signed complex integral of Z(t)ζ(1/2+it) from 0 to T has an explicit leading term of size T^(3/4)log T with fixed phase exp(iπ/8), and error O(√T log²T).", "novelty_claim": false, "paper_id": "PAPER-AH70-HARDY-MEAN", "pdf_pages": 18, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "The integrand is neither |ζ|² nor |Z′|². The phase must match before the estimate can control a Hardy integral.", "source_locator": "Theorem 1", "source_path": "sources/analytic70_history/hardy_mean.pdf", "source_sha256": "daae72a392ffb0dbe06eff1cd3d6dd86c725ec79ba175c74269ff2612a696638", "source_url": "https://arxiv.org/pdf/2003.11349v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Some mean value results related to Hardy''s function", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "The integral is not an absolute moment. Keep the fixed phase and the distinction from the preceding conjectured other moment.", "venue": "arXiv", "version": "arXiv:2003.11349v1", "version_date": "2020-03-25", "version_receipt": "sources/analytic70_history/hardy_mean.html", "whole_work_read": false, "year": 2020, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-HARDY-MEAN", "arxiv": "2003.11349", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-HARDY-MEAN"]}','Some mean value results related to Hardy''s function','["Xiaodong Cao", "Yoshio Tanigawa", "Wenguang Zhai"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2003.11349v1','https://arxiv.org/pdf/2003.11349v1','daae72a392ffb0dbe06eff1cd3d6dd86c725ec79ba175c74269ff2612a696638','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-LONG-CONDITIONAL','corpus/bibliography.jsonl',200,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "2201.02108", "audit_level": 0, "authors": ["Winston Heap"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2201.02108", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "Assuming RH, for k∈N, fixed 0<θ<1/100 and X≤T^(2m), the [T,2T] 2k-th mean of the stated prime-power polynomial has a main term given by k!T times the kth power of a weighted prime sum restricted to p≤T^(θ/k). The same m≥2 enters transform decay in (ii).", "novelty_claim": false, "paper_id": "PAPER-AH70-LONG-CONDITIONAL", "pdf_pages": 27, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Conditions (i)–(iii) and Theorem 1", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "The smooth kernel V_X and length exponent m are integral to the theorem. Application needs the exact weight conditions, beyond the range extracted here.", "source_locator": "Conditions (i)–(iii) and Theorem 1", "source_path": "sources/analytic70_history/long_conditional.pdf", "source_sha256": "b975a5a9c5607798fd07d334785d34ab3b3ed1be53e3d28b863a8c7b8d8fc9ca", "source_url": "https://arxiv.org/pdf/2201.02108v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Conditional mean values of long Dirichlet polynomials", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Keep bounded even support in [−log X,log X], the transform decay and localization in (ii)–(iii), and the separation between prime-power input and prime main term.", "venue": "arXiv", "version": "arXiv:2201.02108v1", "version_date": "2022-01-06", "version_receipt": "sources/analytic70_history/long_conditional.html", "whole_work_read": false, "year": 2022, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-LONG-CONDITIONAL", "arxiv": "2201.02108", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-LONG-CONDITIONAL"]}','Conditional mean values of long Dirichlet polynomials','["Winston Heap"]',NULL,'2022',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2201.02108v1','https://arxiv.org/pdf/2201.02108v1','b975a5a9c5607798fd07d334785d34ab3b3ed1be53e3d28b863a8c7b8d8fc9ca','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-DISCRETE-ZETA','corpus/bibliography.jsonl',201,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "1608.08493", "audit_level": 0, "authors": ["Ramūnas Garunkštis", "Antanas Laurinčikas"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1608.08493", "doi": "10.1007/s10998-017-0228-6", "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "Assuming RH, for fixed σ>1/2, any A>0, s=σ+it and |t|≤T^A, the sum of |ζ(s+iγ)|² over 0<γ≤T equals ζ(2σ)(T/2π)log(T/(2πe))+ζ(2σ)(T/π)Re(ζ′/ζ(s+1/2))+O_(σ,A)(T^(1−η)), for some η=η(A)>0.", "novelty_claim": false, "paper_id": "PAPER-AH70-DISCRETE-ZETA", "pdf_pages": 18, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1 and definitions of s, γ", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "The sampling uses ordinary counts through T; taking σ to 1/2 or changing to derivative masses is outside this fixed-σ theorem.", "source_locator": "Theorem 1 and definitions of s, γ", "source_path": "sources/analytic70_history/discrete_zeta.pdf", "source_sha256": "b02af249f79d709482cd3bb9ae98f0324db91681482bf3d756ec1cb027f92793", "source_url": "https://arxiv.org/pdf/1608.08493v2", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Discrete mean square of the Riemann zeta-function over imaginary parts of its zeros", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Retain the discrete sampling by ζ zeros, RH, and the secondary logarithmic derivative term.", "venue": "arXiv", "version": "arXiv:1608.08493v2", "version_date": "2017-12-07", "version_receipt": "sources/analytic70_history/discrete_zeta.html", "whole_work_read": false, "year": 2016, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-DISCRETE-ZETA", "arxiv": "1608.08493", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-DISCRETE-ZETA"]}','Discrete mean square of the Riemann zeta-function over imaginary parts of its zeros','["Ramūnas Garunkštis", "Antanas Laurinčikas"]',NULL,'2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1608.08493v2','https://arxiv.org/pdf/1608.08493v2','b02af249f79d709482cd3bb9ae98f0324db91681482bf3d756ec1cb027f92793','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-ARITH-SECOND','corpus/bibliography.jsonl',202,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "2212.06520", "audit_level": 0, "authors": ["Hirotaka Kobayashi"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2212.06520", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "The sum of |ζ(1/2+in)|² over positive integers n≤T has main term T log(T/(2π)) and error O(T log T exp(−C log₂(T)/log₃(T))) for some C>0.", "novelty_claim": false, "paper_id": "PAPER-AH70-ARITH-SECOND", "pdf_pages": 11, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1, display (1)", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Integer-ordinate sampling interacts with the ratio exp(2πk); zero sampling requires a separate character theorem.", "source_locator": "Theorem 1.1, display (1)", "source_path": "sources/analytic70_history/arith_second.pdf", "source_sha256": "10105af1d4f54769ac93454e025e72e4385e753bd7a4559a929af625913a4ea2", "source_url": "https://arxiv.org/pdf/2212.06520v2", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "A mean-square value of the Riemann zeta function over an arithmetic progression", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "This grid is the integer ordinate grid; shifts and different spacings require their own results.", "venue": "arXiv", "version": "arXiv:2212.06520v2", "version_date": "2023-01-24", "version_receipt": "sources/analytic70_history/arith_second.html", "whole_work_read": false, "year": 2022, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-ARITH-SECOND", "arxiv": "2212.06520", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-ARITH-SECOND"]}','A mean-square value of the Riemann zeta function over an arithmetic progression','["Hirotaka Kobayashi"]',NULL,'2022',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2212.06520v2','https://arxiv.org/pdf/2212.06520v2','10105af1d4f54769ac93454e025e72e4385e753bd7a4559a929af625913a4ea2','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-LOGDERIV-GUE','corpus/bibliography.jsonl',203,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "math/9412220", "audit_level": 0, "authors": ["David W. Farmer"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/9412220", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "Assuming RH and the paper’s GUE3 condition, if a≈1/log T, the [−T,T] integral of |ζ′/ζ(1/2+a+it)|² times ζ′/ζ(1/2+a+it) is asymptotic to T log(T) T^(−2a)/(2a²).", "novelty_claim": false, "paper_id": "PAPER-AH70-LOGDERIV-GUE", "pdf_pages": 10, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1 and GUE3 hypothesis", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "The higher correlation hypothesis is genuine. Pair correlation or variance alone does not substitute for it.", "source_locator": "Theorem 1 and GUE3 hypothesis", "source_path": "sources/analytic70_history/logderiv_gue.pdf", "source_sha256": "4fa77f3c8cdb15ef8208857619f853774c063e4b235a042ee5ac4e884460d1a6", "source_url": "https://arxiv.org/pdf/math/9412220v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Mean Values of the Logarithmic Derivative of the zeta Function and the GUE Hypothesis", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Keep the exact complex product with an absolute square, the factor T^(−2a) and the order-three correlation input.", "venue": "arXiv", "version": "arXiv:math/9412220v1", "version_date": "1994-12-05", "version_receipt": "sources/analytic70_history/logderiv_gue.html", "whole_work_read": false, "year": 1994, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-LOGDERIV-GUE", "arxiv": "math/9412220", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-LOGDERIV-GUE"]}','Mean Values of the Logarithmic Derivative of the zeta Function and the GUE Hypothesis','["David W. Farmer"]',NULL,'1994',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/9412220v1','https://arxiv.org/pdf/math/9412220v1','4fa77f3c8cdb15ef8208857619f853774c063e4b235a042ee5ac4e884460d1a6','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-DERIVATIVE-LOGMEAN','corpus/bibliography.jsonl',204,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "2107.13636", "audit_level": 0, "authors": ["Andrés Chirre"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2107.13636", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "Under RH and for each fixed integer k≥0, the universal integrated F(α,T) limit on all fixed intervals [b,b+ℓ] with b≥1 and ℓ>0 is equivalent to the source’s I_k(a,T) asymptotic for every fixed a>0.", "novelty_claim": false, "paper_id": "PAPER-AH70-DERIVATIVE-LOGMEAN", "pdf_pages": 10, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1, statements (I) and (II)", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "When pushing the estimate to a shrinking height shift, retain the asymptotic quantifiers on the right of Theorem 1.", "source_locator": "Theorem 1, statements (I) and (II)", "source_path": "sources/analytic70_history/derivative_logmean.pdf", "source_sha256": "6f238238c012c0509cc1d2b748229b27ce2d22d13cf241ef5226ffddd34f3258", "source_url": "https://arxiv.org/pdf/2107.13636v2", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "A note on the mean values of the derivatives of $\\zeta''/\\zeta$", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "The interval quantifier is universal with each pair fixed, and the mean equivalence uses all fixed positive a.", "venue": "arXiv", "version": "arXiv:2107.13636v2", "version_date": "2022-01-03", "version_receipt": "sources/analytic70_history/derivative_logmean.html", "whole_work_read": false, "year": 2021, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-DERIVATIVE-LOGMEAN", "arxiv": "2107.13636", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-DERIVATIVE-LOGMEAN"]}','A note on the mean values of the derivatives of $\zeta''/\zeta$','["Andrés Chirre"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2107.13636v2','https://arxiv.org/pdf/2107.13636v2','6f238238c012c0509cc1d2b748229b27ce2d22d13cf241ef5226ffddd34f3258','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-ATKINSON-EXPLICIT','corpus/bibliography.jsonl',205,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "2105.06821", "audit_level": 0, "authors": ["Aleksander Simonič", "Valeriia V. Starichkova"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2105.06821", "doi": "10.1016/j.jnt.2022.09.010", "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "Theorem 1 decomposes the critical-line second-moment error into two oscillatory sums and a remainder when fixed positive A′≤A″ and the integer N satisfy A′T≤N≤A″T. Theorem 2 supplies an explicit remainder bound for T≥T₀, with coefficient triples tabulated for stated inputs.", "novelty_claim": false, "paper_id": "PAPER-AH70-ATKINSON-EXPLICIT", "pdf_pages": 42, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 1–2, (4)–(8) and Table 1", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Use the tables for the actual cutoff and height range, including the dependence on both A′,A″.", "source_locator": "Theorems 1–2, (4)–(8) and Table 1", "source_path": "sources/analytic70_history/atkinson_explicit.pdf", "source_sha256": "f2f19c87cef5ab706147604f058985e5aa6dee2d27b05513e6ad411e57375d05", "source_url": "https://arxiv.org/pdf/2105.06821v3", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Atkinson''s formula for the mean square of $\\zeta(s)$ with an explicit error term", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Use Theorem 2 and the selected parameter triple for numerical effectivity; retain its lower height restriction.", "venue": "arXiv", "version": "arXiv:2105.06821v3", "version_date": "2022-12-13", "version_receipt": "sources/analytic70_history/atkinson_explicit.html", "whole_work_read": false, "year": 2021, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-ATKINSON-EXPLICIT", "arxiv": "2105.06821", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-ATKINSON-EXPLICIT"]}','Atkinson''s formula for the mean square of $\zeta(s)$ with an explicit error term','["Aleksander Simonič", "Valeriia V. Starichkova"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2105.06821v3','https://arxiv.org/pdf/2105.06821v3','f2f19c87cef5ab706147604f058985e5aa6dee2d27b05513e6ad411e57375d05','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-LONG-DIVISOR','corpus/bibliography.jsonl',206,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "2309.08057", "audit_level": 0, "authors": ["Fatma Cicek", "Alia Hamieh", "Nathan Ng"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2309.08057", "doi": "10.2140/ant.2025.19.1427", "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "Smoothed second moment with divisor coefficients at length K=T^(1+η), 0<η<1/3, assumes the specified ω and ϕ, including ν>[5+3(η+1)]/9.", "novelty_claim": false, "paper_id": "PAPER-AH70-LONG-DIVISOR", "pdf_pages": 38, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.2; conditions (4)–(6), (11)", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "When truncating a spectral mean beyond T, verify the weight smoothness and expansion of the off-diagonal, not only the length inequality.", "source_locator": "Theorem 1.2; conditions (4)–(6), (11)", "source_path": "sources/analytic70_history/long_divisor.pdf", "source_sha256": "892bd1da177a0973e39eb17fdd65b2846902300d772a5c913d4809143c2e39c4", "source_url": "https://arxiv.org/pdf/2309.08057v1", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Mean values of long Dirichlet polynomials with divisor coefficients", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "When truncating a spectral mean beyond T, verify the weight smoothness and expansion of the off-diagonal, not only the length inequality.", "venue": "arXiv", "version": "arXiv:2309.08057v1", "version_date": "2023-09-14", "version_receipt": "sources/analytic70_history/long_divisor.html", "whole_work_read": false, "year": 2023, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-LONG-DIVISOR", "arxiv": "2309.08057", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-LONG-DIVISOR"]}','Mean values of long Dirichlet polynomials with divisor coefficients','["Fatma Cicek", "Alia Hamieh", "Nathan Ng"]',NULL,'2023',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2309.08057v1','https://arxiv.org/pdf/2309.08057v1','892bd1da177a0973e39eb17fdd65b2846902300d772a5c913d4809143c2e39c4','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-LONG-HIGHER-DIVISOR','corpus/bibliography.jsonl',207,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "2105.03525", "audit_level": 0, "authors": ["Alia Hamieh", "Nathan Ng"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2105.03525", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For k,ℓ≥2 and K=T^(1+η), the shifted long-divisor mean relies on the displayed AD_{k,ℓ}(ϑ,C,β) additive-divisor hypothesis and the shift and smoothing conditions.", "novelty_claim": false, "paper_id": "PAPER-AH70-LONG-HIGHER-DIVISOR", "pdf_pages": 50, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1 and hypothesis AD", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Prove a compatible shifted convolution bound before using the conditional mean for a longer detector.", "source_locator": "Theorem 1.1 and hypothesis AD", "source_path": "sources/analytic70_history/long_higher_divisor.pdf", "source_sha256": "8a1293b67fa01d042d16f2ff76fb739cbbe8d3ff35e0d09d3ffd1cf81a009441", "source_url": "https://arxiv.org/pdf/2105.03525v2", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Mean values of long Dirichlet polynomials with higher divisor coefficients", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Prove a compatible shifted convolution bound before using the conditional mean for a longer detector.", "venue": "arXiv", "version": "arXiv:2105.03525v2", "version_date": "2022-10-17", "version_receipt": "sources/analytic70_history/long_higher_divisor.html", "whole_work_read": false, "year": 2021, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-LONG-HIGHER-DIVISOR", "arxiv": "2105.03525", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-LONG-HIGHER-DIVISOR"]}','Mean values of long Dirichlet polynomials with higher divisor coefficients','["Alia Hamieh", "Nathan Ng"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2105.03525v2','https://arxiv.org/pdf/2105.03525v2','8a1293b67fa01d042d16f2ff76fb739cbbe8d3ff35e0d09d3ffd1cf81a009441','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-DIR-MOLLIFIED','corpus/bibliography.jsonl',208,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "1808.02879", "audit_level": 0, "authors": ["Brian Conrey", "Henryk Iwaniec", "Kannan Soundararajan"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1808.02879", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For large Q, shifts ≪1/log Q and a fixed smooth W supported in [1,2], the completed Dirichlet mean averages over even primitive characters and contains two main terms summed over (q,hk)=1. The stated error estimate is for its displayed average.", "novelty_claim": false, "paper_id": "PAPER-AH70-DIR-MOLLIFIED", "pdf_pages": 28, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Definitions (4)–(5), Theorem 1 and the remainder average", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Do not transfer a conductor average to a fixed character. Track the h,k range and remainder before polarization.", "source_locator": "Definitions (4)–(5), Theorem 1 and the remainder average", "source_path": "sources/analytic70_history/dir_mollified.pdf", "source_sha256": "1e11dc4e21de5325d2e7ce62de7799b85aa861f39af66ecda09c1823a0750e5a", "source_url": "https://arxiv.org/pdf/1808.02879v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "The mean square of the product of a Dirichlet $L$-function and a Dirichlet polynomial", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Preserve the moduli and mollifier averaging that controls the remainder; evenness fixes the gamma factors in this version.", "venue": "arXiv", "version": "arXiv:1808.02879v1", "version_date": "2018-08-08", "version_receipt": "sources/analytic70_history/dir_mollified.html", "whole_work_read": false, "year": 2018, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-DIR-MOLLIFIED", "arxiv": "1808.02879", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-DIR-MOLLIFIED"]}','The mean square of the product of a Dirichlet $L$-function and a Dirichlet polynomial','["Brian Conrey", "Henryk Iwaniec", "Kannan Soundararajan"]',NULL,'2018',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1808.02879v1','https://arxiv.org/pdf/1808.02879v1','1e11dc4e21de5325d2e7ce62de7799b85aa861f39af66ecda09c1823a0750e5a','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-ZETA-SUMS-MOM','corpus/bibliography.jsonl',209,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "exponential-sums", "arxiv_id": "2405.12506", "audit_level": 0, "authors": ["Peng Gao"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2405.12506", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "Under RH, for real m>2, a fixed positive margin ε and large T,Y with Y≤(1−ε)T, the [T,2T] moment of |Σ_{n≤Y}n^(−it)|^(2m) is ≪TY^m(log T)^((m−1)^2).", "novelty_claim": false, "paper_id": "PAPER-AH70-ZETA-SUMS-MOM", "pdf_pages": 10, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Definition S_m(T,Y) and Theorem 1.1, (1.2)", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Preserve the continuous height law and keep Y separated from T; discrete zero sampling would need a different estimate.", "source_locator": "Definition S_m(T,Y) and Theorem 1.1, (1.2)", "source_path": "sources/analytic70_history/zeta_sums_mom.pdf", "source_sha256": "d2ed6429a01d2e5a21ad6e6631b6ff89c43f99230ad25f71a74de892a171673f", "source_url": "https://arxiv.org/pdf/2405.12506v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Upper bounds for moments of zeta sums", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Maintain RH, the fixed endpoint margin and the unweighted Dirichlet polynomial when comparing a weighted moment.", "venue": "arXiv", "version": "arXiv:2405.12506v1", "version_date": "2024-05-21", "version_receipt": "sources/analytic70_history/zeta_sums_mom.html", "whole_work_read": false, "year": 2024, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-ZETA-SUMS-MOM", "arxiv": "2405.12506", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-ZETA-SUMS-MOM"]}','Upper bounds for moments of zeta sums','["Peng Gao"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2405.12506v1','https://arxiv.org/pdf/2405.12506v1','d2ed6429a01d2e5a21ad6e6631b6ff89c43f99230ad25f71a74de892a171673f','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-RATIONAL-MEAN','corpus/bibliography.jsonl',210,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "exponential-sums", "arxiv_id": "2503.10933", "audit_level": 0, "authors": ["Doowon Koh", "Igor E. Shparlinski"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2503.10933", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For integers d≥k≥1 and s≥d(d+1)/2, under sN^k<p≤sN^(k+1) the full finite-field average satisfies M_(d,2s)(N)≤N^(2s−k(k+1)/2+o(1))p^(−d+k).", "novelty_claim": false, "paper_id": "PAPER-AH70-RATIONAL-MEAN", "pdf_pages": 15, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. (1.3), (1.8) and Theorem 1.1", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "A transfer from modular inverses to real-height log phases requires an explicit arithmetic reduction; the lengths are part of the result.", "source_locator": "(1.3), (1.8) and Theorem 1.1", "source_path": "sources/analytic70_history/rational_mean.pdf", "source_sha256": "169c27c67b68fdca19049b64e8fd5a6bd58bfb5d304bd2d17f396e671ccb8a23", "source_url": "https://arxiv.org/pdf/2503.10933v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Mean value theorems for rational exponential sums", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Keep k fixed, the finite-field full average and the strict lower/open and upper/closed endpoints. A restricted-sampling or continuous moment is separate.", "venue": "arXiv", "version": "arXiv:2503.10933v1", "version_date": "2025-03-13", "version_receipt": "sources/analytic70_history/rational_mean.html", "whole_work_read": false, "year": 2025, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-RATIONAL-MEAN", "arxiv": "2503.10933", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-RATIONAL-MEAN"]}','Mean value theorems for rational exponential sums','["Doowon Koh", "Igor E. Shparlinski"]',NULL,'2025',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2503.10933v1','https://arxiv.org/pdf/2503.10933v1','169c27c67b68fdca19049b64e8fd5a6bd58bfb5d304bd2d17f396e671ccb8a23','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-SHORT-LP','corpus/bibliography.jsonl',211,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": "1703.08842", "audit_level": 0, "authors": ["Winston Heap"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1703.08842", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For 0<q≤1 gives the stated upper order for a special truncated Dirichlet polynomial''s torus norm, with exponent α_q=1/[4(2−q)].", "novelty_claim": false, "paper_id": "PAPER-AH70-SHORT-LP", "pdf_pages": 18, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1 and definition (4)", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "The underlying statistic uses the Bohr/Haar norm. A finite-height or derivative-weighted mean requires uniform character comparison.", "source_locator": "Theorem 1 and definition (4)", "source_path": "sources/analytic70_history/short_lp.pdf", "source_sha256": "74291dd5c30ed405eddbb3d6a729a7eb27b1296c5467fa16ea83289ea8de14ee", "source_url": "https://arxiv.org/pdf/1703.08842v1", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Upper bounds for $L^q$ norms of Dirichlet polynomials with small $q$", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "The underlying statistic uses the Bohr/Haar norm. A finite-height or derivative-weighted mean requires uniform character comparison.", "venue": "arXiv", "version": "arXiv:1703.08842v1", "version_date": "2017-03-26", "version_receipt": "sources/analytic70_history/short_lp.html", "whole_work_read": false, "year": 2017, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-SHORT-LP", "arxiv": "1703.08842", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-SHORT-LP"]}','Upper bounds for $L^q$ norms of Dirichlet polynomials with small $q$','["Winston Heap"]',NULL,'2017',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1703.08842v1','https://arxiv.org/pdf/1703.08842v1','74291dd5c30ed405eddbb3d6a729a7eb27b1296c5467fa16ea83289ea8de14ee','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-LOCAL-SUP','corpus/bibliography.jsonl',212,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "exponential-sums", "arxiv_id": "1005.3932", "audit_level": 0, "authors": ["Michel Weber"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1005.3932", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For every fixed 0<α*<1 the theorem provides σ₀∈(1/2,1), B≥4 and ν₀, and the stated minimum number of blocks at every ν≥ν₀ on which ζ(σ+it) is nonzero for all σ≥σ₀ and all t in the block.", "novelty_claim": false, "paper_id": "PAPER-AH70-LOCAL-SUP", "pdf_pages": 12, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1 and the displayed block family", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Locate the actual dyadic block dimensions before using this as a uniform-in-height zero-free estimate. It gives many blocks, not an entire region at every height.", "source_locator": "Theorem 1.1 and the displayed block family", "source_path": "sources/analytic70_history/local_sup.pdf", "source_sha256": "246383aba0bdb1b1968525955dec80e224f2c48c1617262709381b360e8817d0", "source_url": "https://arxiv.org/pdf/1005.3932v2", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Local Suprema of Dirichlet Polynomials and Zerofree Regions of the Riemann Zeta-Function", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "This many-block result within a selected block family gives neither every block nor an unrestricted zero-free region.", "venue": "arXiv", "version": "arXiv:1005.3932v2", "version_date": "2012-03-13", "version_receipt": "sources/analytic70_history/local_sup.html", "whole_work_read": false, "year": 2010, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-LOCAL-SUP", "arxiv": "1005.3932", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-LOCAL-SUP"]}','Local Suprema of Dirichlet Polynomials and Zerofree Regions of the Riemann Zeta-Function','["Michel Weber"]',NULL,'2010',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1005.3932v2','https://arxiv.org/pdf/1005.3932v2','246383aba0bdb1b1968525955dec80e224f2c48c1617262709381b360e8817d0','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AH70-IV-ADD-DIV','corpus/bibliography.jsonl',213,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "exponential-sums", "arxiv_id": "1110.3950", "audit_level": 0, "authors": ["Eeva Suvitie"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1110.3950", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For N≥1, 1≤L≤N and 1≤F≪N^(1−ε), the sum of binary additive divisor correlations over f∼F,n∼N,l∼L minus its displayed integral main term is ≪N^(2+ε)+N^(1+ε)LF.", "novelty_claim": false, "paper_id": "PAPER-AH70-IV-ADD-DIV", "pdf_pages": 14, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1, display (6), and Corollary 1.2", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "Uniform aggregate cancellation is distinct from pointwise additive-divisor control for a fixed difference.", "source_locator": "Theorem 1.1, display (6), and Corollary 1.2", "source_path": "sources/analytic70_history/iv_add_div.pdf", "source_sha256": "7df7fac2e3ce3ed905a885b9c40693b54dc5e0a8f29a3b6ea81040d4101fe7f3", "source_url": "https://arxiv.org/pdf/1110.3950v2", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "On the binary additive divisor problem in mean", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "The theorem bounds the joint average over the printed ranges, rather than each individual shift.", "venue": "arXiv", "version": "arXiv:1110.3950v2", "version_date": "2012-02-03", "version_receipt": "sources/analytic70_history/iv_add_div.html", "whole_work_read": false, "year": 2011, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-IV-ADD-DIV", "arxiv": "1110.3950", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-IV-ADD-DIV"]}','On the binary additive divisor problem in mean','["Eeva Suvitie"]',NULL,'2011',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1110.3950v2','https://arxiv.org/pdf/1110.3950v2','7df7fac2e3ce3ed905a885b9c40693b54dc5e0a8f29a3b6ea81040d4101fe7f3','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
