INSERT INTO "papers" VALUES('PAPER-AH70-IVIC-OTHER03','corpus/bibliography.jsonl',219,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": null, "audit_level": 0, "authors": ["Aleksandar Ivić"], "bibliographic_verified": true, "canonical_url": "https://www.numdam.org/item/JTNB_2003__15_1_163_0/", "doi": null, "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "Studies ζ''s 2k-th moment for fixed integer k≥3 and fixed 1/2<σ<1, and related cusp-form and Rankin–Selberg means. The precise improved abscissa ranges were not extracted.", "novelty_claim": false, "paper_id": "PAPER-AH70-IVIC-OTHER03", "pdf_pages": 17, "publication_status": "Verified published edition facsimile", "read_scope": "Targeted passage only. Introduction, (1.1)", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "The estimate concerns fixed σ and uses a divisor-square main coefficient. Check the actual uniformity near the critical line separately.", "source_locator": "Introduction, (1.1)", "source_path": "sources/analytic70_history/ivic_other03.pdf", "source_sha256": "fc05dc17366546c6e290abaaba5eee6577ae275ec67874abf994228e20a0752c", "source_url": "https://www.numdam.org/item/JTNB_2003__15_1_163_0.pdf", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "On mean values of some zeta-functions in the critical strip", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "The estimate concerns fixed σ and uses a divisor-square main coefficient. Check the actual uniformity near the critical line separately.", "venue": "Journal de Théorie des Nombres de Bo