INSERT INTO "papers" VALUES('PAPER-AH70-STRIP-ERROR06','corpus/bibliography.jsonl',220,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": null, "audit_level": 0, "authors": ["Yuk-Kam Lau"], "bibliographic_verified": true, "canonical_url": "https://www.numdam.org/item/JTNB_2006__18_2_445_0/", "doi": "10.5802/jtnb.553", "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For 3/4≤σ<1, T≥1 and N≍T, the integral of E_σ(t) from 1 to T equals −2πζ(2σ−1)T plus two displayed oscillatory sums and O(log²T). For T≥3 Corollary 1 yields O(√T) above 3/4 and O(√T log T) at 3/4 after the main term.", "novelty_claim": false, "paper_id": "PAPER-AH70-STRIP-ERROR06", "pdf_pages": 27, "publication_status": "Verified published edition facsimile", "read_scope": "Targeted passage only. Theorem 1 and Corollary 1, pp. 447–448", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "A strip extension to σ→1/2 cannot use this formula without new estimates.", "source_locator": "Theorem 1 and Corollary 1, pp. 447–448", "source_path": "sources/analytic70_history/strip_error06.pdf", "source_sha256": "75753dca80423be608355750a3f18136531890fdee26004a565fc45797bbb81c", "source_url": "https://www.numdam.org/item/JTNB_2006__18_2_445_0.pdf", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "A study of the mean value of the error term in the mean square formula of the Riemann zeta-function in the critical strip $3/4\\le \\sigma < 1$", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "Keep the integrated error and the endpoint distinction.", "venue": "Journal de Théorie des Nombres de Bordeaux 18(2), 445–472", "version": "Published edition facsimile", "version_date": null, "version_receipt": "sources/analytic70_history/strip_error06.html", "whole_work_read": false, "year": 2006, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/analytic70_records.jsonl", "id": "PAPER-AH70-STRIP-ERROR06", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AH70-STRIP-ERROR06"]}','A study of the mean value of the error term in the mean square formula of the Riemann zeta-function in the critical strip $3/4\le \sigma < 1$','["Yuk-Kam Lau"]',NULL,'2006',0,0,'selected_checkpoint_priority_work','full_text_accessed','Published edition facsimile','https://www.numdam.org/item/JTNB_2006__18_2_445_0.pdf','75753dca80423be608355750a3f18136531890fdee26004a565fc45797bbb81c','quality/pending_round12/analytic70_notes.md','papers/analytic70_records.jsonl');
