INSERT INTO "papers" VALUES('PAPER-AH70-EXPLICIT-L2','corpus/bibliography.jsonl',224,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "mean-values", "arxiv_id": null, "audit_level": 0, "authors": ["Daniele Dona", "Harald A. Helfgott", "Sebastian Zuniga Alterman"], "bibliographic_verified": true, "canonical_url": "https://www.numdam.org/item/JTNB_2022__34_1_91_0/", "doi": "10.5802/jtnb.1194", "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "English", "main_result": "For 0<σ≤1 the paper gives piecewise explicit bounds for the tail integral of |ζ(σ+it)/(σ+it)|²; the σ=1 bound for T≥200 is π²/(6T)+28.3log T/T².", "novelty_claim": false, "paper_id": "PAPER-AH70-EXPLICIT-L2", "pdf_pages": 44, "publication_status": "Verified published edition facsimile", "read_scope": "Targeted passage only. Theorems 1.1–1.2, pp. 93–94", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "The denominator and actual σ branch matter when replacing a contour tail estimate.", "source_locator": "Theorems 1.1–1.2, pp. 93–94", "source_path": "sources/analytic70_history/explicit_l2.pdf", "source_sha256": "1234c42429f2bd0fe42b749918cdb9cb8939ddfd7574c93f4a2321c3cc76fec6", "source_url": "https://www.numdam.org/item/JTNB_2022__34_1_91_0.pdf", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Explicit $L^2$ bounds for the Riemann $\\zeta $ function", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "The denominator and actual σ branch matter when replacing a contour tail estimate.", "venue": "Journal de Théorie des Nombres de Bordeaux 34(1), 91–133", "version": "Published edition facsimile",