INSERT INTO "papers" VALUES('PAPER-AH70-FRIABLE-DENSITY','corpus/bibliography.jsonl',225,'full_text_accessed','quality/pending_round12/analytic70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "exponential-sums", "arxiv_id": null, "audit_level": 0, "authors": ["Régis de La Bretèche", "Andrew Granville"], "bibliographic_verified": true, "canonical_url": "https://www.numdam.org/articles/10.24033/bsmf.2667/", "doi": "10.24033/bsmf.2667", "full_text_accessed": true, "hypothesis_extraction": "Targeted statement or introduction only. Read scope is recorded and theorem context can be incomplete.", "language": "French", "main_result": "In x≥2, exp((log x)^(2/3+ε))≤y≤x, the paper gives the asymptotic N(x,y)=Ψ(x,y)^3/(2x)·(1+O(log(u+1)/log y)) with u=log x/log y.", "novelty_claim": false, "paper_id": "PAPER-AH70-FRIABLE-DENSITY", "pdf_pages": 48, "publication_status": "Verified published edition facsimile", "read_scope": "Targeted passage only. Théorème 1.1 and Remarque 1, p. 306", "record_path": "quality/pending_round12/analytic70_notes.md", "result_status": "Source-stated result. No independent proof certification or RH transfer.", "selection_reason": "An application to a factored coefficient sum must preserve its friability cutoff. The finer exceptional-zero term is discussed separately in §5.", "source_locator": "Théorème 1.1 and Remarque 1, p. 306", "source_path": "sources/analytic70_history/friable_density.pdf", "source_sha256": "831bf1677b3fa43d9389f40fc4cc6c34e4f7707c2b62258249af474d04dd203d", "source_url": "https://www.numdam.org/item/10.24033/bsmf.2667.pdf", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Densité des friables", "track_file": "papers/analytic70_records.jsonl", "transfer_hypothesis": "An application to a factored coefficient sum must preserve its friability cutoff. The finer exceptional-zero term is discussed separately in §5.", "venue": "Bulletin de la Soci