INSERT INTO "papers" VALUES('PAPER-BK001','corpus/bibliography.jsonl',240,'full_text_accessed','papers/PAPER-BK001.md','{"id": "PAPER-BK001", "title": "Asymptotic Estimation for Eigenvalues in the Exponential Potential and for Zeros of Kiν(z) with Respect to Order", "authors": ["Yuri Krynytskyi", "Andrij Rovenchak"], "year": 2021, "date": "2021-06-10", "venue": "SIGMA17(2021),057,7pages", "doi": "10.3842/SIGMA.2021.057", "arxiv": "2103.01732v2", "version": "v2,2021-06-10,publishedSIGMAversion", "source_url": "https://arxiv.org/pdf/2103.01732v2", "publication_status": "published", "family": ["D", "F", "H"], "audit_level": 1, "bibliographic_verified": true, "access_status": "full_text_accessed", "substantive_whole_work_read": true, "read_scope": "Complete7-pageprimarytextread,includingSchrodingerreduction§3andquasiclassicalLambert-Wformula;figurecurves/numericaltablesnotindependentlyaudited.", "source_file": "sources/bessel_round3/krynytskyi2021.pdf", "source_sha256": "9890d645a706658522bb7bf7884c98f8fefec4be2ad58a8d4652c1bcfa4588ab", "accessed_at": "2026-11-17", "main_result_inspected": "Fixedz>0large-indexν-zerosestimatedbyπ(n-1/4)/W(2π(n-1/4)/(ez)) times[1+O(logn/n²)],p4Eq7,derivedthroughquasiclassicalquantization.", "technical_review": "Schrodinger-to-Besselscalingindependentlyreconstructed;WKBerrornotindependentlyvalidatedandnotusedasrigorousO(1)countinput.", "correction_search_status": "incomplete", "research_connection": "ClassicalBesselbaseforpositivefinite-offlinecountermodel;thecampaignaddsownexactI-seriesphaseproofratherthanassumingWKBprecision.", "original_access_status": "full_text_accessed", "whole_work_read": true, "record_path": "papers/PAPER-BK001.md", "track_file": "papers/bessel_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-BK001", "PAPER-BESSEL-S02"], "manifestation_records": [{"id": "PAPER-BK001", "title": "Asymptotic Estimation for Eigenvalues in the Exponential Potential and for Zeros of K_{iν}(z) with Respect to Order", "authors": ["Yuri Krynytskyi", "Andrij Rovenchak"], "date": "2021-06-10", "year": 2021, "venue": "SIGMA 17 (2021), 057, 7 pages", "publication_status": "published publisher PDF", "doi": "10.3842/SIGMA.2021.057", "arxiv": "2103.01732", "source_url": "https://www.imath.kiev.ua/~sigma/2021/057/", "version": "Publisher final, received 15 May 2021, final form 1 June 2021, published 10 June 2021", "family": ["B", "D", "F", "H"], "audit_level": 1, "whole_work_read": true, "inspected_portions_level": 2, "read_scope": "Complete 7-page publisher PDF, all sections, figures, and references. Independently reconstructed the exact spectral/Bessel substitution. Semiclassical full expansion and 10,000-zero numerical dataset were not independently replayed.", "access_status": "full_text_accessed", "source_file": "sources/positive_kernel_bessel_skeptic_round3/krynytskyi_rovenchak2021.pdf", "main_result": "Section 3, pages 3–4, identifies Dirichlet eigenvalues of an exponential half-line Schrödinger potential with imaginary-order K zeros. Equation (7), page 4, gives a Lambert-W asymptotic approximation for the nth positive order zero at fixed z>0. Section 2 derives its classical action and WKB quantization approximation.", "limitations": ["The Bohr–Sommerfeld relation in Section 2 is a semiclassical input, not an exact eigenvalue equation.", "Numerical claims and the full claimed remainder in equation (7) have not been independently verified.", "This does not identify individual Riemann zeta zeros."], "research_questions": ["Compare exact gamma-phase counting with the WKB action while preserving all normalization factors.", "Use the solvable positive kernel to test which spectral/Laplace assumptions fail to enforce an all-zero conclusion."], "correction_search_status": "Publisher final source inspected; exhaustive correction and forward-citation search incomplete", "accessed_at": "2026-11-17", "source_sha256": "44b9fad51e3552396cf5999faee58f6105f5dde1889f993e1ace3bf5b4973bde", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-BESSEL-S02.md", "track_file": "papers/positive_kernel_bessel_skeptic_round3_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-BESSEL-S02"]}]}','Asymptotic Estimation for Eigenvalues in the Exponential Potential and for Zeros of Kiν(z) with Respect to Order','["Yuri Krynytskyi", "Andrij Rovenchak"]','["D", "F", "H"]','2021',1,1,'selected_checkpoint_priority_work','full_text_accessed','v2,2021-06-10,publishedSIGMAversion','https://arxiv.org/pdf/2103.01732v2','9890d645a706658522bb7bf7884c98f8fefec4be2ad58a8d4652c1bcfa4588ab','papers/PAPER-BK001.md','papers/bessel_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-BK002','corpus/bibliography.jsonl',241,'full_text_accessed','papers/PAPER-BK002.md','{"id": "PAPER-BK002", "title": "On the ν-zeros of the Bessel functions of purely imaginary order", "authors": ["R.B.Paris"], "year": 2022, "date": "2022-04-20", "venue": "arXiv2204.09306v1", "doi": null, "arxiv": "2204.09306v1", "version": "v1,2022-04-20;latesthistorynotaudited", "source_url": "https://arxiv.org/pdf/2204.09306v1", "publication_status": "preprint_version_inspected;laterjournalstatusnotchecked", "family": ["D", "F", "H"], "audit_level": 0, "bibliographic_verified": true, "access_status": "full_text_accessed", "substantive_whole_work_read": false, "read_scope": "Pages1–4inspectedforexactIseries,connectionformulaandlarge-imaginary-orderphase;wholepaperandnumericsnotread/audited.", "source_file": "sources/bessel_round3/paris2022.pdf", "source_sha256": "51f9683afe2b7e15f3064946e7d434af11d2a2cc2217ab7aab913740d7138198", "accessed_at": "2026-11-17", "mathematical_content_inspected": "Eq2.1exactIseries;Eqs2.3–2.7largeorderexpansionsandphase;authorcitesestablishedsimpleorderzeros.", "technical_review": "CampaignindependentlyboundsseriesAandAderivativetoobtainrigorousmonotonephase;doesnotrelyonformalasymsalone.", "correction_search_status": "not_completed", "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-BK002.md", "track_file": "papers/bessel_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-BK002"]}','On the ν-zeros of the Bessel functions of purely imaginary order','["R.B.Paris"]','["D", "F", "H"]','2022',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1,2022-04-20;latesthistorynotaudited','https://arxiv.org/pdf/2204.09306v1','51f9683afe2b7e15f3064946e7d434af11d2a2cc2217ab7aab913740d7138198','papers/PAPER-BK002.md','papers/bessel_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-BF62','corpus/bibliography.jsonl',242,'full_text_accessed','papers/PAPER-BF62.md','{"paper_id": "PAPER-BF62", "title": "Negative moments of the Riemann zeta-function", "authors": ["Hung M. Bui", "Alexandra Florea"], "year": 2024, "date": "2024-01-06", "publication_date": "2024-01-06", "publication_year": 2024, "first_submission_date": "2023-02-14", "preprint_year": 2023, "arxiv_id": "2302.07226", "arxiv_version": "v1", "version": "accepted author manuscript; related arXiv v1", "venue": "Journal für die reine und angewandte Mathematik (Crelles Journal)", "volume": "2024", "issue": "806", "journal_pages": "247–288", "doi": "10.1515/crelle-2023-0091", "canonical_url": "https://doi.org/10.1515/crelle-2023-0091", "source_url": "https://pure.manchester.ac.uk/ws/portalfiles/portal/280630528/BuiFlorea_negative_moments.pdf", "arxiv_url": "https://arxiv.org/abs/2302.07226v1", "publication_status": "published journal article; inspected full-text manifestation is the accepted author manuscript", "full_text_access": "Complete repository accepted manuscript PDF and arXiv v1 PDF accessible; version-of-record mathematics not compared", "bibliographic_verified": true, "full_text_accessed": true, "source_path": "sources/latest62_q1_round5/bui_florea_publisher.pdf", "source_sha256": "0fa36e9efeeb3e96448191f814ec1ae42cbd4c355dad2863b7ba552b32127921", "arxiv_v1_source_path": "sources/latest62_q1_round5/bui_florea_arxiv_v1.pdf", "arxiv_v1_source_sha256": "14740c801f9739340258b66fe09a757abdcd891eb129858f45b54cea8ae1c5d1", "pages": 40, "internal_article_pages": 39, "access_date": "2026-11-17", "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Targeted primary reading: cover, title, acknowledgments, internal pp. 6–9 Lemmas 2.1–2.2 and proofs, internal pp. 30–31 and 34 selected Perron arguments; arXiv v1 (2.8) compared. The complete work and other proof branches were not read.", "record_path": "papers/PAPER-BF62.md", "selection_reason": "Primary pointwise reciprocal-zeta input for the q=1 shifted Möbius proof candidate and direct ancestry of Bui–Florea–Heycock negative-moment and Mertens estimates.", "selected": true, "id": "PAPER-BF62", "arxiv": "2302.07226", "read_scope": "Targeted primary reading: cover, title, acknowledgments, internal pp. 6–9 Lemmas 2.1–2.2 and proofs, internal pp. 30–31 and 34 selected Perron arguments; arXiv v1 (2.8) compared. The complete work and other proof branches were not read.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/bui_florea_latest62_metadata_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-BF62"]}','Negative moments of the Riemann zeta-function','["Hung M. Bui", "Alexandra Florea"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','accepted author manuscript; related arXiv v1','https://pure.manchester.ac.uk/ws/portalfiles/portal/280630528/BuiFlorea_negative_moments.pdf','0fa36e9efeeb3e96448191f814ec1ae42cbd4c355dad2863b7ba552b32127921','papers/PAPER-BF62.md','papers/bui_florea_latest62_metadata_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-CMS001','corpus/bibliography.jsonl',243,'full_text_accessed','papers/PAPER-CMS001.md','{"id": "PAPER-CMS001", "title": "A differential version of the Chebyshev–Markov–Stieltjes inequalities", "authors": ["Shoni Gilboa", "Ron Peled"], "year": 2015, "date": "2015-02-09", "venue": "Journal of Approximation Theory196,13–54", "doi": "10.1016/j.jat.2015.02.010", "arxiv": "1407.2467v2", "version": "Accessed PDF bears arXivv2 sidebar9Feb2015, body date20Oct2018, PDF creation23Oct2018; no assertion that these dates are identical. Full revision history not audited.", "source_url": "https://arxiv.org/pdf/1407.2467v2", "source_file": "sources/christoffel_round3/gilboa_peled.pdf", "source_sha256": "f649e94cf990e99cb88d5f9d23772fb4abe6aeb492d85f466c068c4dc4938e72", "audit_level": 0, "bibliographic_verified": true, "access_status": "full_text_accessed", "substantive_whole_work_read": false, "read_scope": "Actual primary pp1–2, Eq1–3 introduction, visually inspected to distinguish upper/lower CDF extrema from maximum atom mass. Rest of the43-page preprint not read or audited.", "technical_review": "Classical introductory identity upperπ−lowerπ=λ inspected. This compact-supportλ is not silently identified with unrestricted ordinary Hankel Christoffel function. Differential theorems not audited.", "main_result_inspected": "Finite-moment classes on[−1,1] have separate sharp upper/lower distribution functions and maximum point mass; the atom extremum is their gap.", "family": ["F", "H"], "accessed_at": "2026-11-17", "publication_status": "published; inspected preprint", "correction_search_status": "Published erratum discovered: JAT199(2015),95,DOI10.1016/j.jat.2015.08.003. Erratum content not accessed; differential theorems not relied on.", "audit_file": "audits/adversarial_reviews/christoffel_independent_third_round3.md", "novelty_claim": false, "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-CMS001.md", "track_file": "papers/christoffel_source_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-CMS001"]}','A differential version of the Chebyshev–Markov–Stieltjes inequalities','["Shoni Gilboa", "Ron Peled"]','["F", "H"]','2015',0,0,'selected_checkpoint_priority_work','full_text_accessed','Accessed PDF bears arXivv2 sidebar9Feb2015, body date20Oct2018, PDF creation23Oct2018; no assertion that these dates are identical. Full revision history not audited.','https://arxiv.org/pdf/1407.2467v2','f649e94cf990e99cb88d5f9d23772fb4abe6aeb492d85f466c068c4dc4938e72','papers/PAPER-CMS001.md','papers/christoffel_source_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-WEIL1941','corpus/bibliography.jsonl',244,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-WEIL1941", "title": "On the Riemann Hypothesis in Function-Fields", "authors": ["André Weil"], "year": 1941, "venue": "PNAS 27, 345–347", "language": "English", "doi": "10.1073/pnas.27.7.345", "arxiv_id": null, "canonical_url": "https://doi.org/10.1073/pnas.27.7.345", "publication_status": "published", "version": "original journal pages 345–347, assembled from PMC page scans", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "read_scope": "Read all three article pages, following the intersection numbers, positive form, Frobenius power sums, and real interpolation contradiction. The note defers full foundational details of the correspondence theory.", "source_path": "sources/classical63_automorphic_geometry/weil1941.pdf", "source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC1078336/", "source_sha256": "246a2bd8d5412e4c26191890390b7b6d9ab9a3e96e7d4359967a1ff41c8ca234", "pdf_pages": 3, "source_locator": "pp. 345–347, especially the polynomial argument on p. 347", "main_result": "For a separable one-variable function field over F_q in Weil''s setup, positivity of the correspondence trace pairing and reciprocal pairing of eigenvalues imply that all reciprocal roots have absolute value √q.", "classical_zeta_transfer_obstacle": "The proof uses the Frobenius correspondence and its transpose, with product q times the identity, on a smooth projective curve. No correspondence with these properties is available here for the completed classical zeta function.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-WEIL1941"]}','On the Riemann Hypothesis in Function-Fields','["André Weil"]',NULL,'1941',1,1,'selected_checkpoint_priority_work','full_text_accessed','original journal pages 345–347, assembled from PMC page scans','https://pmc.ncbi.nlm.nih.gov/articles/PMC1078336/','246a2bd8d5412e4c26191890390b7b6d9ab9a3e96e7d4359967a1ff41c8ca234','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-WEIL1948','corpus/bibliography.jsonl',245,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-WEIL1948", "title": "Sur les courbes algébriques et les variétés qui s’en déduisent", "authors": ["André Weil"], "year": 1948, "venue": "Actualités Scientifiques et Industrielles 1041, Hermann", "language": "French", "doi": null, "arxiv_id": null, "canonical_url": "https://denisevellachemla.eu/Weil-courbes-varietes.pdf", "publication_status": "published", "version": "digitized transcription of the 1948 monograph", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at § IV, no. 22.", "source_path": "sources/classical63_automorphic_geometry/weil1948.pdf", "source_url": "https://denisevellachemla.eu/Weil-courbes-varietes.pdf", "source_sha256": "f68899a91a569a41a4f15e64511c8c52e42b94864b033936f4f15f99e837ae04", "pdf_pages": 74, "source_locator": "§ IV, no. 22", "main_result": "The zeta-function numerator of the curve has roots on the circle abs(u)=q^(-1/2), by the preceding theory of correspondences.", "classical_zeta_transfer_obstacle": "The argument uses the polarization of a curve''s Jacobian and the evaluation of point counts through Frobenius iterates over finite fields.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-WEIL1948"]}','Sur les courbes algébriques et les variétés qui s’en déduisent','["André Weil"]',NULL,'1948',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized transcription of the 1948 monograph','https://denisevellachemla.eu/Weil-courbes-varietes.pdf','f68899a91a569a41a4f15e64511c8c52e42b94864b033936f4f15f99e837ae04','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-GROTHENDIECK1968','corpus/bibliography.jsonl',246,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-GROTHENDIECK1968", "title": "Standard conjectures on algebraic cycles", "authors": ["Alexander Grothendieck"], "year": 1968, "venue": "Algebraic Geometry, Bombay Colloquium, 193–199", "language": "English", "doi": null, "arxiv_id": null, "canonical_url": "https://download.uni-mainz.de/mathematik/Algebraische%20Geometrie/Lehre/WS23.Padische.1968.Grothendieck.StandardConjs.pdf", "publication_status": "published", "version": "scan of original proceedings chapter", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "read_scope": "Read §§1–4 and the conclusion, following Dwork–Faton''s trace criterion, diagonal projectors, the equivalence argument via X×X, and the conditional positivity implication.", "source_path": "sources/classical63_automorphic_geometry/grothendieck1968.pdf", "source_url": "https://download.uni-mainz.de/mathematik/Algebraische%20Geometrie/Lehre/WS23.Padische.1968.Grothendieck.StandardConjs.pdf", "source_sha256": "989595b34439bc0565f2ee158e1eeaf6c8673470b90d8d5eafd52481702e7678", "pdf_pages": 7, "source_locator": "§§2–4, pp. 194–198", "main_result": "Formulates C(X), A(X)/B(X) and Hdg(X). B(X) and Hdg(X×X) imply the Weil weight assertion for endomorphisms scaling the polarization by q, and hence its Frobenius case.", "classical_zeta_transfer_obstacle": "Even the conditional argument requires an algebraic Lefschetz operator and a positive primitive intersection form for an appropriate geometric realization. The paper supplies these as conjectures about varieties.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-GROTHENDIECK1968"]}','Standard conjectures on algebraic cycles','["Alexander Grothendieck"]',NULL,'1968',1,1,'selected_checkpoint_priority_work','full_text_accessed','scan of original proceedings chapter','https://download.uni-mainz.de/mathematik/Algebraische%20Geometrie/Lehre/WS23.Padische.1968.Grothendieck.StandardConjs.pdf','989595b34439bc0565f2ee158e1eeaf6c8673470b90d8d5eafd52481702e7678','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-KATZMESSING1974','corpus/bibliography.jsonl',247,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-KATZMESSING1974", "title": "Some consequences of the Riemann hypothesis for varieties over finite fields", "authors": ["Nicholas M. Katz", "William Messing"], "year": 1974, "venue": "Inventiones Mathematicae 23, 73–77", "language": "English", "doi": "10.1007/BF01405203", "arxiv_id": null, "canonical_url": "https://doi.org/10.1007/BF01405203", "publication_status": "published", "version": "original journal PDF with archive cover sheet", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "read_scope": "Read all five printed pages from the scan and OCR, including the Lefschetz pencil divisibility proof, hard Lefschetz corollary, and polynomial construction of cycle projectors.", "source_path": "sources/classical63_automorphic_geometry/katzmessing1974.pdf", "source_url": "https://web.math.princeton.edu/~nmk/old/katzmessing.pdf", "source_sha256": "9283138c8620fe8570f217c41d9a077f0b5fbc7d793ea97f4aed12396c2afa53", "pdf_pages": 7, "source_locator": "§ II Theorem 1 and Corollary 1, § III Theorem 2", "main_result": "For smooth projective geometrically irreducible varieties over F_q, any cohomology satisfying the stated duality, weak Lefschetz and zeta formula has the étale Frobenius polynomials. With the extra cycle-class hypothesis, Künneth projectors are rational combinations of Frobenius graphs.", "classical_zeta_transfer_obstacle": "The comparison starts with Deligne''s established weight-stratified Frobenius polynomials and an alternating cohomological factorization. Neither input is furnished for classical ζ.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-KATZMESSING1974"]}','Some consequences of the Riemann hypothesis for varieties over finite fields','["Nicholas M. Katz", "William Messing"]',NULL,'1974',1,1,'selected_checkpoint_priority_work','full_text_accessed','original journal PDF with archive cover sheet','https://web.math.princeton.edu/~nmk/old/katzmessing.pdf','9283138c8620fe8570f217c41d9a077f0b5fbc7d793ea97f4aed12396c2afa53','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-ARTHUR1974','corpus/bibliography.jsonl',248,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-ARTHUR1974", "title": "The Selberg trace formula for groups of F-rank one", "authors": ["James Arthur"], "year": 1974, "venue": "Annals of Mathematics 100, 326–385", "language": "English", "doi": "10.2307/1971076", "arxiv_id": null, "canonical_url": "https://doi.org/10.2307/1971076", "publication_status": "published", "version": "original journal PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §3 Assumption 3.5 and Theorem 3.6, §9.", "source_path": "sources/classical63_automorphic_geometry/arthur1974.pdf", "source_url": "https://www.claymath.org/library/cw/arthur/pdf/1.pdf", "source_sha256": "5690ad90ee56acb475c8c3fa9bc45ad05416f9f07e2183dde69a03d34ee6a3e6", "pdf_pages": 60, "source_locator": "§3 Assumption 3.5 and Theorem 3.6, §9", "main_result": "For the adelic F-rank-one setup the discrete automorphic convolution operator is trace class under Assumption 3.5 (K-finite convolution factors and the prescribed vanishing on almost all ramified classes), and §9 gives the trace expansion after continuous and geometric divergences cancel.", "classical_zeta_transfer_obstacle": "The trace class statement concerns the discrete automorphic convolution operator; its spectrum and the parabolic correction terms give no operator whose eigenvalues are all classical zeta zeros.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-ARTHUR1974"]}','The Selberg trace formula for groups of F-rank one','["James Arthur"]',NULL,'1974',0,0,'selected_checkpoint_priority_work','full_text_accessed','original journal PDF','https://www.claymath.org/library/cw/arthur/pdf/1.pdf','5690ad90ee56acb475c8c3fa9bc45ad05416f9f07e2183dde69a03d34ee6a3e6','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-ARTHUR1978','corpus/bibliography.jsonl',249,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-ARTHUR1978", "title": "A trace formula for reductive groups I. Terms associated to classes in G(Q)", "authors": ["James Arthur"], "year": 1978, "venue": "Duke Mathematical Journal 45, 911–952", "language": "English", "doi": "10.1215/S0012-7094-78-04542-8", "arxiv_id": null, "canonical_url": "https://doi.org/10.1215/S0012-7094-78-04542-8", "publication_status": "published", "version": "original journal PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §7 Theorem 7.1 and §8.", "source_path": "sources/classical63_automorphic_geometry/arthur1978.pdf", "source_url": "https://www.claymath.org/library/cw/arthur/pdf/7.pdf", "source_sha256": "7e60f480e35d9ccec29b7aa53d6a5a6f0ca617dc6f69332fec49a08f51c8e2f3", "pdf_pages": 42, "source_locator": "§7 Theorem 7.1 and §8", "main_result": "For sufficiently regular truncation parameter T the sum of integrals of the absolute values of the class kernels is finite. The resulting geometric distributions are indexed by rational conjugacy of semisimple parts.", "classical_zeta_transfer_obstacle": "This is geometric control of a truncated reductive-group automorphic kernel. It does not identify an untruncated self-adjoint operator with classical ζ''s explicit formula.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-ARTHUR1978"]}','A trace formula for reductive groups I. Terms associated to classes in G(Q)','["James Arthur"]',NULL,'1978',0,0,'selected_checkpoint_priority_work','full_text_accessed','original journal PDF','https://www.claymath.org/library/cw/arthur/pdf/7.pdf','7e60f480e35d9ccec29b7aa53d6a5a6f0ca617dc6f69332fec49a08f51c8e2f3','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-LABESSELANGLANDS1979','corpus/bibliography.jsonl',250,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-LABESSELANGLANDS1979", "title": "L-indistinguishability for SL(2)", "authors": ["Jean-Pierre Labesse", "Robert P. Langlands"], "year": 1979, "venue": "Canadian Journal of Mathematics 31, 726–785", "language": "English", "doi": "10.4153/CJM-1979-070-3", "arxiv_id": null, "canonical_url": "https://doi.org/10.4153/CJM-1979-070-3", "publication_status": "published", "version": "IAS typeset copy of published article", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §§6–7, Propositions 7.2–7.4.", "source_path": "sources/classical63_automorphic_geometry/labesselanglands1979.pdf", "source_url": "https://publications.ias.edu/sites/default/files/ll-ps.pdf", "source_sha256": "f3edf55752b03e496f895d85b6bbe744214217db82ddbebc57c078775fadae64", "pdf_pages": 71, "source_locator": "§§6–7, Propositions 7.2–7.4", "main_result": "Computes global automorphic multiplicities for SL(2) and its inner forms by distinguishing packet types and tracking contributions related to tori.", "classical_zeta_transfer_obstacle": "Packet multiplicities are for automorphic representations on a prescribed group. Stabilizing this trace formula yields no zero-location theorem for the degree-one trivial Hecke L-function.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-LABESSELANGLANDS1979"]}','L-indistinguishability for SL(2)','["Jean-Pierre Labesse", "Robert P. Langlands"]',NULL,'1979',0,0,'selected_checkpoint_priority_work','full_text_accessed','IAS typeset copy of published article','https://publications.ias.edu/sites/default/files/ll-ps.pdf','f3edf55752b03e496f895d85b6bbe744214217db82ddbebc57c078775fadae64','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-KATZ1988','corpus/bibliography.jsonl',251,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-KATZ1988", "title": "Gauss Sums, Kloosterman Sums, and Monodromy Groups", "authors": ["Nicholas M. Katz"], "year": 1988, "venue": "Annals of Mathematics Studies 116, Princeton University Press", "language": "English", "doi": null, "arxiv_id": null, "canonical_url": "https://web.math.princeton.edu/~nmk/Katz-GKM.pdf", "publication_status": "published", "version": "digitized original monograph", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Chapter 11, §§11.1, 11.4.", "source_path": "sources/classical63_automorphic_geometry/katz1988.pdf", "source_url": "https://web.math.princeton.edu/~nmk/Katz-GKM.pdf", "source_sha256": "8711424f8edb14f38c0e61606ef49d6efc67d5a93ac9f5bd9fa3e13b7c7d9ffe", "pdf_pages": 127, "source_locator": "Chapter 11, §§11.1, 11.4", "main_result": "Determines geometric monodromy of rank n≥2 Kloosterman sheaves: Sp(n) for even n, SL(n) for odd n and odd p, SO(n) for odd n≠7 and p=2, and G₂ for n=7 and p=2. §11.4 applies equidistribution to the normalized Frobenius classes.", "classical_zeta_transfer_obstacle": "These compact laws use the computed monodromy of a pure finite-field sheaf. They do not construct a sheaf giving classical zeta zeros.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-KATZ1988"]}','Gauss Sums, Kloosterman Sums, and Monodromy Groups','["Nicholas M. Katz"]',NULL,'1988',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original monograph','https://web.math.princeton.edu/~nmk/Katz-GKM.pdf','8711424f8edb14f38c0e61606ef49d6efc67d5a93ac9f5bd9fa3e13b7c7d9ffe','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-KATZSARNAK1999','corpus/bibliography.jsonl',252,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-KATZSARNAK1999", "title": "Random matrices, Frobenius eigenvalues, and monodromy", "authors": ["Nicholas M. Katz", "Peter Sarnak"], "year": 1999, "venue": "AMS Colloquium Publications 45", "language": "English", "doi": "10.1090/coll/045", "arxiv_id": null, "canonical_url": "https://doi.org/10.1090/coll/045", "publication_status": "published", "version": "digitized original monograph", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §§9.2 and 9.6, especially Theorems 9.2.6 and 9.6.10.", "source_path": "sources/classical63_automorphic_geometry/katzsarnak1999.pdf", "source_url": "https://web.math.princeton.edu/~nmk/RMFEM.pdf", "source_sha256": "39beb011e5fab2737bb131611f054221108128fbebbb7f62ba2de9a56f755dd5", "pdf_pages": 436, "source_locator": "§§9.2 and 9.6, especially Theorems 9.2.6 and 9.6.10", "main_result": "Equidistribution theorems for unitarized Frobenius in pure lisse families, including uniform control in §9.6, support the separate normalized spacing limits of Chapter 1.", "classical_zeta_transfer_obstacle": "The proof needs purity and finite-field averaging plus explicit geometric monodromy. Even an agreement of spacing limits would not rule out exceptional zeros of a single classical function.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-KATZSARNAK1999"]}','Random matrices, Frobenius eigenvalues, and monodromy','["Nicholas M. Katz", "Peter Sarnak"]',NULL,'1999',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original monograph','https://web.math.princeton.edu/~nmk/RMFEM.pdf','39beb011e5fab2737bb131611f054221108128fbebbb7f62ba2de9a56f755dd5','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-KATZSARNAK1999B','corpus/bibliography.jsonl',253,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-KATZSARNAK1999B", "title": "Zeroes of zeta functions and symmetry", "authors": ["Nicholas M. Katz", "Peter Sarnak"], "year": 1999, "venue": "Bulletin of the AMS 36, 1–26", "language": "English", "doi": "10.1090/S0273-0979-99-00766-1", "arxiv_id": null, "canonical_url": "https://doi.org/10.1090/S0273-0979-99-00766-1", "publication_status": "published", "version": "original journal PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §3 and §4, equation (30) and the analogy table.", "source_path": "sources/classical63_automorphic_geometry/katzsarnak1999b.pdf", "source_url": "https://web.math.princeton.edu/~nmk/old/katzsarnakarticle.pdf", "source_sha256": "4f99e2242e7a63d65b81078bd7318be6ee57613f9b71e568532949a7e01b7a77", "pdf_pages": 26, "source_locator": "§3 and §4, equation (30) and the analogy table", "main_result": "Explains how Frobenius on curve cohomology gives a unitary conjugacy class and how symplectic monodromy for suitable curve families yields the corresponding family statistics.", "classical_zeta_transfer_obstacle": "The spectral interpretation in §3 depends on curve cohomology. Quantum-chaos or compact-group statistical similarity does not identify a classical ζ spectral operator.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-KATZSARNAK1999B"]}','Zeroes of zeta functions and symmetry','["Nicholas M. Katz", "Peter Sarnak"]',NULL,'1999',0,0,'selected_checkpoint_priority_work','full_text_accessed','original journal PDF','https://web.math.princeton.edu/~nmk/old/katzsarnakarticle.pdf','4f99e2242e7a63d65b81078bd7318be6ee57613f9b71e568532949a7e01b7a77','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-CKPSS2004','corpus/bibliography.jsonl',254,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-CKPSS2004", "title": "Functoriality for the classical groups", "authors": ["James W. Cogdell", "Henry H. Kim", "Ilya I. Piatetski-Shapiro", "Freydoun Shahidi"], "year": 2004, "venue": "Publications Mathématiques de l''IHÉS 99, 163–233", "language": "English", "doi": "10.1007/s10240-004-0020-z", "arxiv_id": null, "canonical_url": "https://doi.org/10.1007/s10240-004-0020-z", "publication_status": "published", "version": "original journal PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §1 Theorem 1.1.", "source_path": "sources/classical63_automorphic_geometry/ckpss2004.pdf", "source_url": "https://www.numdam.org/article/PMIHES_2004__99__163_0.pdf", "source_sha256": "ebc11f9b6ca0803ba296f9c1735df14064182a74a978ab258152ee3f882858a4", "pdf_pages": 71, "source_locator": "§1 Theorem 1.1", "main_result": "Irreducible globally generic cuspidal representations for the paper''s split classical groups over number fields admit the specified functorial lifts to GL(N).", "classical_zeta_transfer_obstacle": "Functoriality identifies local parameters and analytic L-functions. It imposes no all-zero constraint for ζ, whose GL(1) realization is already known.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-CKPSS2004"]}','Functoriality for the classical groups','["James W. Cogdell", "Henry H. Kim", "Ilya I. Piatetski-Shapiro", "Freydoun Shahidi"]',NULL,'2004',0,0,'selected_checkpoint_priority_work','full_text_accessed','original journal PDF','https://www.numdam.org/article/PMIHES_2004__99__163_0.pdf','ebc11f9b6ca0803ba296f9c1735df14064182a74a978ab258152ee3f882858a4','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-NGO2010','corpus/bibliography.jsonl',255,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-NGO2010", "title": "Le lemme fondamental pour les algèbres de Lie", "authors": ["Ngô Bảo Châu"], "year": 2010, "venue": "Publications Mathématiques de l''IHÉS 111, 1–169", "language": "French", "doi": "10.1007/s10240-010-0026-7", "arxiv_id": "0801.0446", "canonical_url": "https://doi.org/10.1007/s10240-010-0026-7", "publication_status": "published", "version": "arXiv:0801.0446v3, 2 May 2008", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1.11.1, support Theorem 7.6.6 and proof §8.6 in arXiv v3.", "source_path": "sources/classical63_automorphic_geometry/ngo2010.pdf", "source_url": "https://arxiv.org/pdf/0801.0446", "source_sha256": "4d48819f7ecf7e4e1d0fd036df2a62fa5b49f171f6fda56449b3dfbc0d43fb51", "pdf_pages": 197, "source_locator": "Theorem 1.11.1, support Theorem 7.6.6 and proof §8.6 in arXiv v3", "main_result": "The Lie-algebra fundamental lemma matches stable and weighted-by-character orbital integrals for corresponding endoscopic data, using geometric stabilization and the Hitchin fibration, under the stated local characteristic bounds.", "classical_zeta_transfer_obstacle": "The identities concern endoscopic orbital integrals. The Hitchin cohomology supplies Frobenius traces for that comparison, without realizing the completed classical ζ function.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "0801.0446", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-NGO2010"]}','Le lemme fondamental pour les algèbres de Lie','["Ngô Bảo Châu"]',NULL,'2010',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:0801.0446v3, 2 May 2008','https://arxiv.org/pdf/0801.0446','4d48819f7ecf7e4e1d0fd036df2a62fa5b49f171f6fda56449b3dfbc0d43fb51','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-MV2010','corpus/bibliography.jsonl',256,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-MV2010", "title": "The subconvexity problem for GL2", "authors": ["Philippe Michel", "Akshay Venkatesh"], "year": 2010, "venue": "Publications Mathématiques de l''IHÉS 112, 171–271", "language": "English", "doi": "10.1007/s10240-010-0025-8", "arxiv_id": "0903.3591", "canonical_url": "https://doi.org/10.1007/s10240-010-0025-8", "publication_status": "published", "version": "arXiv:0903.3591v2, 9 Mar 2010", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §1 Theorems 1.1 and 1.2.", "source_path": "sources/classical63_automorphic_geometry/mv2010.pdf", "source_url": "https://arxiv.org/pdf/0903.3591", "source_sha256": "f6e5ab7a892766ea5eb6ddab3feaadb64f8b9c1f770af0d4c6f29f14dd589dbf", "pdf_pages": 109, "source_locator": "§1 Theorems 1.1 and 1.2", "main_result": "An absolute δ>0 gives C^(1/4−δ) central-value bounds for GL(1), GL(2) with unitary central character and the stated GL(2)×GL(2) Rankin–Selberg family with one representation fixed; imaginary twists include t-aspect.", "classical_zeta_transfer_obstacle": "The method gives quantitative upper bounds for values. Such a bound lacks the zero exclusion needed in Re s>1/2 for ζ.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "0903.3591", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-MV2010"]}','The subconvexity problem for GL2','["Philippe Michel", "Akshay Venkatesh"]',NULL,'2010',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:0903.3591v2, 9 Mar 2010','https://arxiv.org/pdf/0903.3591','f6e5ab7a892766ea5eb6ddab3feaadb64f8b9c1f770af0d4c6f29f14dd589dbf','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-SHIN2011','corpus/bibliography.jsonl',257,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-SHIN2011", "title": "Galois representations arising from some compact Shimura varieties", "authors": ["Sug Woo Shin"], "year": 2011, "venue": "Annals of Mathematics 173, 1645–1741", "language": "English", "doi": "10.4007/annals.2011.173.3.9", "arxiv_id": null, "canonical_url": "https://doi.org/10.4007/annals.2011.173.3.9", "publication_status": "published", "version": "author-hosted manuscript with internal pagination", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1.2, assembled from Theorems 7.5, 7.11 and Corollary 7.13.", "source_path": "sources/classical63_automorphic_geometry/shin2011.pdf", "source_url": "https://math.berkeley.edu/~swshin/StableGal.pdf", "source_sha256": "93f4fe322200a646f337ae8d4aa9a036a866df1bb59ad5fe7bf09373324da75b", "pdf_pages": 62, "source_locator": "Theorem 1.2, assembled from Theorems 7.5, 7.11 and Corollary 7.13", "main_result": "For regular algebraic conjugate self-dual cuspidal GL(m) over CM fields with the stated slight regularity for even m, constructs semisimple ℓ-adic Galois representations realizing local parameters away from ℓ.", "classical_zeta_transfer_obstacle": "These Galois representations realize individual local parameters. Their existence gives no global Frobenius operator whose spectrum lists the classical ζ zeros.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-SHIN2011"]}','Galois representations arising from some compact Shimura varieties','["Sug Woo Shin"]',NULL,'2011',0,0,'selected_checkpoint_priority_work','full_text_accessed','author-hosted manuscript with internal pagination','https://math.berkeley.edu/~swshin/StableGal.pdf','93f4fe322200a646f337ae8d4aa9a036a866df1bb59ad5fe7bf09373324da75b','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-YUN2011','corpus/bibliography.jsonl',258,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-YUN2011", "title": "The fundamental lemma of Jacquet and Rallis", "authors": ["Zhiwei Yun", "Julia Gordon (appendix)"], "year": 2011, "venue": "Duke Mathematical Journal 156, 167–227", "language": "English", "doi": "10.1215/00127094-2010-210", "arxiv_id": "0901.0900", "canonical_url": "https://doi.org/10.1215/00127094-2010-210", "publication_status": "published", "version": "author-hosted final journal text", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Introduction, Main Theorem (Local part), Corollary, and Appendix Theorem A.1.", "source_path": "sources/classical63_automorphic_geometry/yun2011.pdf", "source_url": "https://math.mit.edu/~zyun/FLJR_published.pdf", "source_sha256": "0ac3554b8aec20b1509183722f2fb6b43e068e86d7daa954f90297f6c6d184ec", "pdf_pages": 62, "source_locator": "Introduction, Main Theorem (Local part), Corollary, and Appendix Theorem A.1", "main_result": "In equal characteristic >n, the local theorem identifies the specified graded Frobenius modules for matching invariants with trivial η on the discriminant. The corollary yields the Jacquet–Rallis orbital-integral identity, and Gordon''s transfer gives large-residue-characteristic cases.", "classical_zeta_transfer_obstacle": "The matched distributions are those of the relative trace formula over local fields. Transfer of local identities does not pass a finite-field Weil bound to classical ζ.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "0901.0900", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-YUN2011"]}','The fundamental lemma of Jacquet and Rallis','["Zhiwei Yun", "Julia Gordon (appendix)"]',NULL,'2011',0,0,'selected_checkpoint_priority_work','full_text_accessed','author-hosted final journal text','https://math.mit.edu/~zyun/FLJR_published.pdf','0ac3554b8aec20b1509183722f2fb6b43e068e86d7daa954f90297f6c6d184ec','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-AK2012','corpus/bibliography.jsonl',259,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-AK2012", "title": "The mean value of L(1/2, χ) in the hyperelliptic ensemble", "authors": ["Julio C. Andrade", "Jonathan P. Keating"], "year": 2012, "venue": "Journal of Number Theory 132, 2793–2816", "language": "English", "doi": "10.1016/j.jnt.2012.05.017", "arxiv_id": "1208.1131", "canonical_url": "https://doi.org/10.1016/j.jnt.2012.05.017", "publication_status": "published", "version": "arXiv:1208.1131v1, 6 Aug 2012", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §2, Theorem 1 and equation (2.5).", "source_path": "sources/classical63_automorphic_geometry/ak2012.pdf", "source_url": "https://arxiv.org/pdf/1208.1131", "source_sha256": "a5bae82be3b75e9a42f3b037a221ba556c702873550efc2ab7699d9f588c2fbe", "pdf_pages": 22, "source_locator": "§2, Theorem 1 and equation (2.5)", "main_result": "For fixed q≡1 mod 4, obtains the first moment of L(1/2,χ_D) over monic squarefree D of degree 2g+1, with Euler-product main and secondary terms and power-saving error.", "classical_zeta_transfer_obstacle": "The degree truncation from the curve L-polynomial, averaging over D and finite-field character cancellation are unavailable for a single classical ζ.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "1208.1131", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-AK2012"]}','The mean value of L(1/2, χ) in the hyperelliptic ensemble','["Julio C. Andrade", "Jonathan P. Keating"]',NULL,'2012',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1208.1131v1, 6 Aug 2012','https://arxiv.org/pdf/1208.1131','a5bae82be3b75e9a42f3b037a221ba556c702873550efc2ab7699d9f588c2fbe','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-KR2014','corpus/bibliography.jsonl',260,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-KR2014", "title": "The Variance of the Number of Prime Polynomials in Short Intervals and in Residue Classes", "authors": ["Jonathan P. Keating", "Zeév Rudnick"], "year": 2014, "venue": "International Mathematics Research Notices, 259–288", "language": "English", "doi": "10.1093/imrn/rns220", "arxiv_id": "1204.0708", "canonical_url": "https://doi.org/10.1093/imrn/rns220", "publication_status": "published", "version": "journal advance-access typeset PDF (2012)", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §2, Theorems 2.1 and 2.2.", "source_path": "sources/classical63_automorphic_geometry/kr2014.pdf", "source_url": "https://www.math.tau.ac.il/~rudnick/papers/KeatingRudnickIMRNfinal.pdf", "source_sha256": "5701fda6ed1487354f5e274b5f34933714216392e37cf99c9f7cb2287b614c7f", "pdf_pages": 30, "source_locator": "§2, Theorems 2.1 and 2.2", "main_result": "At fixed h<n−3, q^(−h−1) times the short interval variance tends to n−h−2 as q→∞. The progression theorem gives G(n;Q)∼q^n(deg Q−1) for fixed n≥2, Q squarefree and n≥deg Q−1.", "classical_zeta_transfer_obstacle": "The varying-field limit uses matrix trace averages from finite-field equidistribution. Its integer analogue involves a separate limit tied to ζ pair correlation.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "1204.0708", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-KR2014"]}','The Variance of the Number of Prime Polynomials in Short Intervals and in Residue Classes','["Jonathan P. Keating", "Zeév Rudnick"]',NULL,'2014',0,0,'selected_checkpoint_priority_work','full_text_accessed','journal advance-access typeset PDF (2012)','https://www.math.tau.ac.il/~rudnick/papers/KeatingRudnickIMRNfinal.pdf','5701fda6ed1487354f5e274b5f34933714216392e37cf99c9f7cb2287b614c7f','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-BARYSOROKER2014','corpus/bibliography.jsonl',261,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-BARYSOROKER2014", "title": "Hardy–Littlewood Tuple Conjecture over Large Finite Fields", "authors": ["Lior Bary-Soroker"], "year": 2014, "venue": "International Mathematics Research Notices, 568–575", "language": "English", "doi": "10.1093/imrn/rns249", "arxiv_id": "1206.3930", "canonical_url": "https://doi.org/10.1093/imrn/rns249", "publication_status": "published", "version": "arXiv:1206.3930v3, 4 Oct 2012", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1.1.", "source_path": "sources/classical63_automorphic_geometry/barysoroker2014.pdf", "source_url": "https://arxiv.org/pdf/1206.3930", "source_sha256": "aed115a867be797772c0131061d94ca54e3b61a2368ccc4834b5c2ae656bc1b0", "pdf_pages": 6, "source_locator": "Theorem 1.1", "main_result": "For fixed n,r and odd prime power q, the number of monic degree-n f with all f+a_i irreducible for distinct shifts of degree<n is q^n/n^r+O_(n,r)(q^(n−1/2)).", "classical_zeta_transfer_obstacle": "The bound uses geometric monodromy over coefficient space and finite-field Chebotarev with q→∞ at fixed degree. Integer primes do not vary over that coefficient space.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "1206.3930", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-BARYSOROKER2014"]}','Hardy–Littlewood Tuple Conjecture over Large Finite Fields','["Lior Bary-Soroker"]',NULL,'2014',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1206.3930v3, 4 Oct 2012','https://arxiv.org/pdf/1206.3930','aed115a867be797772c0131061d94ca54e3b61a2368ccc4834b5c2ae656bc1b0','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-AK2014','corpus/bibliography.jsonl',262,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-AK2014", "title": "Conjectures for the integral moments and ratios of L-functions over function fields", "authors": ["Julio C. Andrade", "Jonathan P. Keating"], "year": 2014, "venue": "Journal of Number Theory 142, 102–148", "language": "English", "doi": "10.1016/j.jnt.2014.02.019", "arxiv_id": "1407.3099", "canonical_url": "https://doi.org/10.1016/j.jnt.2014.02.019", "publication_status": "published", "version": "arXiv:1407.3099v1, 11 Jul 2014", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §5, Conjecture 5 and Theorem 1, equation (5.29).", "source_path": "sources/classical63_automorphic_geometry/ak2014.pdf", "source_url": "https://arxiv.org/pdf/1407.3099", "source_sha256": "a3f75ac6e34f1d732f411d1ddff1ff5623d9ad3cd18ddd55a19562d8bd1c3531", "pdf_pages": 40, "source_locator": "§5, Conjecture 5 and Theorem 1, equation (5.29)", "main_result": "Derives the predicted leading kth hyperelliptic moment conditional on Conjecture 5, with logarithmic exponent k(k+1)/2 and explicit arithmetic factor.", "classical_zeta_transfer_obstacle": "The moment formula is a conditional family prediction, so it provides neither an all-zero constraint nor a mechanism for changing the family or base field.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "1407.3099", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-AK2014"]}','Conjectures for the integral moments and ratios of L-functions over function fields','["Julio C. Andrade", "Jonathan P. Keating"]',NULL,'2014',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1407.3099v1, 11 Jul 2014','https://arxiv.org/pdf/1407.3099','a3f75ac6e34f1d732f411d1ddff1ff5623d9ad3cd18ddd55a19562d8bd1c3531','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-KATZWV2017','corpus/bibliography.jsonl',263,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-KATZWV2017", "title": "Witt Vectors and a Question of Rudnick and Waxman", "authors": ["Nicholas M. Katz"], "year": 2017, "venue": "International Mathematics Research Notices", "language": "English", "doi": "10.1093/imrn/rnw130", "arxiv_id": null, "canonical_url": "https://doi.org/10.1093/imrn/rnw130", "publication_status": "published", "version": "journal advance-access typeset PDF (2016)", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §5 Theorem 5.1.", "source_path": "sources/classical63_automorphic_geometry/katzwv2017.pdf", "source_url": "https://web.math.princeton.edu/~nmk/WVQRW.pdf", "source_sha256": "d49a1a1d4ee05e5f5ad21fa2007a7beaf71aa5f71115d6afaba87eb5a829e040", "pdf_pages": 36, "source_locator": "§5 Theorem 5.1", "main_result": "For odd n≥7 and field sizes tending to infinity, primitive super-even Witt-vector characters have normalized Frobenius classes equidistributed in USp(n−1), allowing varying characteristic. The n=3,5 clauses restrict characteristics.", "classical_zeta_transfer_obstacle": "The symmetry group arises from Witt-vector character sheaves and controls family sampling. The construction gives no classical ζ Frobenius class.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-KATZWV2017"]}','Witt Vectors and a Question of Rudnick and Waxman','["Nicholas M. Katz"]',NULL,'2017',0,0,'selected_checkpoint_priority_work','full_text_accessed','journal advance-access typeset PDF (2016)','https://web.math.princeton.edu/~nmk/WVQRW.pdf','d49a1a1d4ee05e5f5ad21fa2007a7beaf71aa5f71115d6afaba87eb5a829e040','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-FLOREA2017','corpus/bibliography.jsonl',264,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-FLOREA2017", "title": "The fourth moment of quadratic Dirichlet L-functions over function fields", "authors": ["Alexandra Florea"], "year": 2017, "venue": "Geometric and Functional Analysis 27, 541–595", "language": "English", "doi": "10.1007/s00039-017-0409-8", "arxiv_id": "1609.01262", "canonical_url": "https://doi.org/10.1007/s00039-017-0409-8", "publication_status": "published", "version": "arXiv:1609.01262v1, 5 Sep 2016", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1.1 and Appendix (9.19)–(9.21).", "source_path": "sources/classical63_automorphic_geometry/florea2017.pdf", "source_url": "https://arxiv.org/pdf/1609.01262", "source_sha256": "71032ed3c90867d4f3acd7fa1365424938fb86a8a0f8e8365c6d4acc0f01525a", "pdf_pages": 39, "source_locator": "Theorem 1.1 and Appendix (9.19)–(9.21)", "main_result": "For prime q≡1 mod 4, the fourth central moment over monic squarefree degree 2g+1 is q^(2g+1) times an explicit degree-10 polynomial truncated through g^8, with error O(q^(2g+1)g^(15/2+ε)).", "classical_zeta_transfer_obstacle": "Polynomial Poisson summation and exact finite degree cutoffs control this quadratic family. Its arithmetic and asymptotic scale differ from the t-aspect fourth moment of ζ.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "1609.01262", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-FLOREA2017"]}','The fourth moment of quadratic Dirichlet L-functions over function fields','["Alexandra Florea"]',NULL,'2017',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1609.01262v1, 5 Sep 2016','https://arxiv.org/pdf/1609.01262','71032ed3c90867d4f3acd7fa1365424938fb86a8a0f8e8365c6d4acc0f01525a','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-YUNZHANG2017','corpus/bibliography.jsonl',265,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-YUNZHANG2017", "title": "Shtukas and the Taylor expansion of L-functions", "authors": ["Zhiwei Yun", "Wei Zhang"], "year": 2017, "venue": "Annals of Mathematics 186, 767–911", "language": "English", "doi": "10.4007/annals.2017.186.3.2", "arxiv_id": "1512.02683", "canonical_url": "https://doi.org/10.4007/annals.2017.186.3.2", "publication_status": "published", "version": "arXiv:1512.02683v3, 11 Apr 2017", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorems 1.1 and 1.2, proof §9.3.2.", "source_path": "sources/classical63_automorphic_geometry/yunzhang2017.pdf", "source_url": "https://arxiv.org/pdf/1512.02683", "source_sha256": "76bb3576bc75dc1c5214597197e3d8ef62abc10784e2b2625657a0e7ea1821ff", "pdf_pages": 97, "source_locator": "Theorems 1.1 and 1.2, proof §9.3.2", "main_result": "For an everywhere unramified cuspidal representation of PGL(2) over the function field, the normalized even rth derivative at 1/2 of the quadratic base-change L-function equals the self-intersection of its projected Heegner–Drinfeld cycle.", "classical_zeta_transfer_obstacle": "This is a special-value identity for a base-change L-function on a moduli stack of shtukas. An identity at the center does not give the signs or spectral data for all classical ζ zeros.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "1512.02683", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-YUNZHANG2017"]}','Shtukas and the Taylor expansion of L-functions','["Zhiwei Yun", "Wei Zhang"]',NULL,'2017',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1512.02683v3, 11 Apr 2017','https://arxiv.org/pdf/1512.02683','76bb3576bc75dc1c5214597197e3d8ef62abc10784e2b2625657a0e7ea1821ff','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-SAWINWITT2018','corpus/bibliography.jsonl',266,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-SAWINWITT2018", "title": "The equidistribution of L-functions of twists by Witt vector Dirichlet characters over function fields", "authors": ["Will Sawin"], "year": 2018, "venue": "arXiv:1805.04330", "language": "English", "doi": null, "arxiv_id": "1805.04330", "canonical_url": "https://arxiv.org/abs/1805.04330", "publication_status": "preprint", "version": "arXiv:1805.04330v2, 12 Nov 2018", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1.1.", "source_path": "sources/classical63_automorphic_geometry/sawinwitt2018.pdf", "source_url": "https://arxiv.org/pdf/1805.04330", "source_sha256": "e41fdd4acde3bac91c6bc523cbd4c2f2df47395e67a29f82752666d47f66e5c8", "pdf_pages": 19, "source_locator": "Theorem 1.1", "main_result": "For pairwise twist-inequivalent cuspidal GL(m_i) representations with finite-order central characters and no nontrivial degree self-twist, most Witt twists admit normalized unitary conjugacy classes, which jointly equidistribute in the determinant-normalized sense of the theorem for d≥4.", "classical_zeta_transfer_obstacle": "The asymptotic is finite-field extension at fixed conductor exponent, via sheaf Fourier transforms and monodromy. It does not control zeros of classical ζ.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "1805.04330", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-SAWINWITT2018"]}','The equidistribution of L-functions of twists by Witt vector Dirichlet characters over function fields','["Will Sawin"]',NULL,'2018',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1805.04330v2, 12 Nov 2018','https://arxiv.org/pdf/1805.04330','e41fdd4acde3bac91c6bc523cbd4c2f2df47395e67a29f82752666d47f66e5c8','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-BLOMERKHAN2019','corpus/bibliography.jsonl',267,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-BLOMERKHAN2019", "title": "Twisted moments of L-functions and spectral reciprocity", "authors": ["Valentin Blomer", "Rizwanur Khan"], "year": 2019, "venue": "Duke Mathematical Journal 168, 1109–1177", "language": "English", "doi": "10.1215/00127094-2018-0060", "arxiv_id": "1706.01245", "canonical_url": "https://doi.org/10.1215/00127094-2018-0060", "publication_status": "published", "version": "arXiv:1706.01245v2, 1 Oct 2018", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1, equations (1.8)–(1.9).", "source_path": "sources/classical63_automorphic_geometry/blomerkhan2019.pdf", "source_url": "https://arxiv.org/pdf/1706.01245", "source_sha256": "2202809d37eaf451a0111f7ef8f655e594fbbc2b5411b8421254e8a90f09c139", "pdf_pages": 42, "source_locator": "Theorem 1, equations (1.8)–(1.9)", "main_result": "For admissible h, coprime q,ℓ, 1/2≤Re s≤Re w<3/4 and fixed GL(3) cusp form or minimal Eisenstein series, relates the twisted moment at level q to moments at level ℓ plus a main term.", "classical_zeta_transfer_obstacle": "Reciprocity exchanges level and twist in an averaged spectral moment. The identity imposes no spectral-location constraint on ζ.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "1706.01245", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-BLOMERKHAN2019"]}','Twisted moments of L-functions and spectral reciprocity','["Valentin Blomer", "Rizwanur Khan"]',NULL,'2019',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1706.01245v2, 1 Oct 2018','https://arxiv.org/pdf/1706.01245','2202809d37eaf451a0111f7ef8f655e594fbbc2b5411b8421254e8a90f09c139','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-BHKM2020','corpus/bibliography.jsonl',268,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-BHKM2020", "title": "Motohashi’s fourth moment identity for non-archimedean test functions and applications", "authors": ["Valentin Blomer", "Peter Humphries", "Rizwanur Khan", "Micah B. Milinovich"], "year": 2020, "venue": "Compositio Mathematica 156, 1004–1038", "language": "English", "doi": "10.1112/S0010437X20007101", "arxiv_id": "1902.07042", "canonical_url": "https://doi.org/10.1112/S0010437X20007101", "publication_status": "published", "version": "arXiv:1902.07042v1, 19 Feb 2019", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1, equations (1.14)–(1.15).", "source_path": "sources/classical63_automorphic_geometry/bhkm2020.pdf", "source_url": "https://arxiv.org/pdf/1902.07042", "source_sha256": "ee9b1279b4812dd03286b82a8252ee9072841685910b5d271c7bf4cee5566e20", "pdf_pages": 30, "source_locator": "Theorem 1, equations (1.14)–(1.15)", "main_result": "For prime q, coprime squarefree comparable twists a,b prime to q and the specified holomorphic Schwartz weight and shift strip, relates the twisted character moment and trivial term to a polar term and spectral moment.", "classical_zeta_transfer_obstacle": "The non-archimedean test function organizes a moment over Dirichlet characters and a Maaß spectral sum. Neither side expresses the full classical ζ zero set.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "1902.07042", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-BHKM2020"]}','Motohashi’s fourth moment identity for non-archimedean test functions and applications','["Valentin Blomer", "Peter Humphries", "Rizwanur Khan", "Micah B. Milinovich"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1902.07042v1, 19 Feb 2019','https://arxiv.org/pdf/1902.07042','ee9b1279b4812dd03286b82a8252ee9072841685910b5d271c7bf4cee5566e20','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-SAWINMOM2020','corpus/bibliography.jsonl',269,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-SAWINMOM2020", "title": "A representation theory approach to integral moments of L-functions over function fields", "authors": ["Will Sawin"], "year": 2020, "venue": "Algebra & Number Theory 14, 867–906", "language": "English", "doi": "10.2140/ant.2020.14.867", "arxiv_id": "1810.01303", "canonical_url": "https://doi.org/10.2140/ant.2020.14.867", "publication_status": "published", "version": "arXiv:1810.01303v2, 30 Oct 2019", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Hypothesis H and Theorem 1.4, equation (1.2).", "source_path": "sources/classical63_automorphic_geometry/sawinmom2020.pdf", "source_url": "https://arxiv.org/pdf/1810.01303", "source_sha256": "67ece39863633b0d962b96b02f75e1aeede8a73d452af2a9bcaf16fcbf82037e", "pdf_pages": 43, "source_locator": "Hypothesis H and Theorem 1.4, equation (1.2)", "main_result": "Under H(n,r,r̃,w), n>2max(r,r̃)+1, and characteristic different from 2 when n=4 or 5, evaluates the shifted twisted moment over primitive even characters up to the stated geometric error.", "classical_zeta_transfer_obstacle": "The key vanishing statement is a hypothesis on geometric cohomology of a conductor-controlled family, with no established classical ζ analogue.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "1810.01303", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-SAWINMOM2020"]}','A representation theory approach to integral moments of L-functions over function fields','["Will Sawin"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1810.01303v2, 30 Oct 2019','https://arxiv.org/pdf/1810.01303','67ece39863633b0d962b96b02f75e1aeede8a73d452af2a9bcaf16fcbf82037e','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-SAWINTEMPLIER2021','corpus/bibliography.jsonl',270,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-SAWINTEMPLIER2021", "title": "On the Ramanujan conjecture for automorphic forms over function fields I. Geometry", "authors": ["Will Sawin", "Nicolas Templier"], "year": 2021, "venue": "Journal of the AMS 34, 653–746", "language": "English", "doi": "10.1090/jams/968", "arxiv_id": "1805.12231", "canonical_url": "https://doi.org/10.1090/jams/968", "publication_status": "published", "version": "arXiv:1805.12231v4, 27 Sep 2020", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1.1 and Condition BC.", "source_path": "sources/classical63_automorphic_geometry/sawintemplier2021.pdf", "source_url": "https://arxiv.org/pdf/1805.12231", "source_sha256": "9dddd64e480b56f3987604a8daf096fa850b74fe998ab1963f55b17f373e3e3c", "pdf_pages": 88, "source_locator": "Theorem 1.1 and Condition BC", "main_result": "For a split semisimple group over a function field of characteristic >2, with a monomial geometric supercuspidal local component and base-changeability, proves temperedness at unramified places.", "classical_zeta_transfer_obstacle": "Temperedness controls local Satake parameters. For ζ these local parameters are elementary already, and a bound on their moduli does not locate global zeros.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "1805.12231", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-SAWINTEMPLIER2021"]}','On the Ramanujan conjecture for automorphic forms over function fields I. Geometry','["Will Sawin", "Nicolas Templier"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1805.12231v4, 27 Sep 2020','https://arxiv.org/pdf/1805.12231','9dddd64e480b56f3987604a8daf096fa850b74fe998ab1963f55b17f373e3e3c','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-NEWTONTHORNE2021','corpus/bibliography.jsonl',271,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-NEWTONTHORNE2021", "title": "Symmetric power functoriality for holomorphic modular forms, II", "authors": ["James Newton", "Jack A. Thorne"], "year": 2021, "venue": "Publications Mathématiques de l''IHÉS 134, 117–152", "language": "English", "doi": "10.1007/s10240-021-00126-4", "arxiv_id": "2009.07180", "canonical_url": "https://doi.org/10.1007/s10240-021-00126-4", "publication_status": "published", "version": "arXiv:2009.07180v2, 27 Sep 2021", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem A.", "source_path": "sources/classical63_automorphic_geometry/newtonthorne2021.pdf", "source_url": "https://arxiv.org/pdf/2009.07180", "source_sha256": "0f08214ebe03344c2e2851be76c49213dc4adf7928ff561610b674c423a2a6bf", "pdf_pages": 30, "source_locator": "Theorem A", "main_result": "All positive symmetric powers of a regular algebraic non-CM cuspidal GL(2) representation over Q exist as regular algebraic cuspidal GL(n+1) representations.", "classical_zeta_transfer_obstacle": "Symmetric power automorphy gives continuation and functional equations of different higher-rank L-functions. It adds no global zero exclusion for the trivial GL(1) L-function.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2009.07180", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-NEWTONTHORNE2021"]}','Symmetric power functoriality for holomorphic modular forms, II','["James Newton", "Jack A. Thorne"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2009.07180v2, 27 Sep 2021','https://arxiv.org/pdf/2009.07180','0f08214ebe03344c2e2851be76c49213dc4adf7928ff561610b674c423a2a6bf','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-SAWINSHUSTERMAN2022','corpus/bibliography.jsonl',272,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-SAWINSHUSTERMAN2022", "title": "On the Chowla and twin primes conjectures over F_q[T]", "authors": ["Will Sawin", "Mark Shusterman"], "year": 2022, "venue": "Annals of Mathematics 196, 457–506", "language": "English", "doi": "10.4007/annals.2022.196.2.1", "arxiv_id": "1808.04001", "canonical_url": "https://doi.org/10.4007/annals.2022.196.2.1", "publication_status": "published", "version": "arXiv:1808.04001v2, 7 Sep 2019", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorems 1.1 and 1.3.", "source_path": "sources/classical63_automorphic_geometry/sawinshusterman2022.pdf", "source_url": "https://arxiv.org/pdf/1808.04001", "source_sha256": "5b762a0888363d2d1140bb9831a6d940586208f690b4dda3fa6e712337e0a687", "pdf_pages": 41, "source_locator": "Theorems 1.1 and 1.3", "main_result": "At fixed q=p^a>685090p², p odd, and nonzero h, proves the monic twin prime asymptotic with a power saving as degree grows. The Chowla statement has its separately stated q and shift conditions.", "classical_zeta_transfer_obstacle": "The fixed-q limit uses geometric character sum estimates and polynomial factorization. It is a distinct prime-counting problem from integer prime correlations, let alone all zeros of ζ.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "1808.04001", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-SAWINSHUSTERMAN2022"]}','On the Chowla and twin primes conjectures over F_q[T]','["Will Sawin", "Mark Shusterman"]',NULL,'2022',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1808.04001v2, 7 Sep 2019','https://arxiv.org/pdf/1808.04001','5b762a0888363d2d1140bb9831a6d940586208f690b4dda3fa6e712337e0a687','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-FARGUESSCHOLZE','corpus/bibliography.jsonl',273,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-FARGUESSCHOLZE", "title": "Geometrization of the local Langlands correspondence", "authors": ["Laurent Fargues", "Peter Scholze"], "year": 2021, "venue": "arXiv:2102.13459", "language": "English", "doi": null, "arxiv_id": "2102.13459", "canonical_url": "https://arxiv.org/abs/2102.13459", "publication_status": "preprint", "version": "arXiv:2102.13459v4, 27 Nov 2024", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at § I.9 Theorem I.9.6 and § I.10 Theorem I.10.1.", "source_path": "sources/classical63_automorphic_geometry/farguesscholze.pdf", "source_url": "https://arxiv.org/pdf/2102.13459", "source_sha256": "1f8040751d3424f59ae56651d990d7b2d5030e6b7cae58bc2fc683358dfc2027", "pdf_pages": 356, "source_locator": "§ I.9 Theorem I.9.6 and § I.10 Theorem I.10.1", "main_result": "Constructs local L-parameters for irreducible smooth representations and proves compatibility properties including tori, parabolic induction and supercuspidal GL(n). Theorem I.10.1 treats a spectral action subject to the stated ℓ condition.", "classical_zeta_transfer_obstacle": "This is local geometry over a nonarchimedean field. The parameterization does not produce a global operator with the archimedean factor and zero spectrum of ζ.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2102.13459", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-FARGUESSCHOLZE"]}','Geometrization of the local Langlands correspondence','["Laurent Fargues", "Peter Scholze"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2102.13459v4, 27 Nov 2024','https://arxiv.org/pdf/2102.13459','1f8040751d3424f59ae56651d990d7b2d5030e6b7cae58bc2fc683358dfc2027','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-KEDLAYA2024','corpus/bibliography.jsonl',274,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-KEDLAYA2024", "title": "Étale and crystalline companions, II", "authors": ["Kiran S. Kedlaya"], "year": 2020, "venue": "arXiv:2008.13053", "language": "English", "doi": null, "arxiv_id": "2008.13053", "canonical_url": "https://arxiv.org/abs/2008.13053", "publication_status": "preprint", "version": "arXiv:2008.13053v8, 24 Mar 2026", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorems 0.1.1 and 0.1.2, Corollaries 8.1.5 and 8.1.7.", "source_path": "sources/classical63_automorphic_geometry/kedlaya2024.pdf", "source_url": "https://arxiv.org/pdf/2008.13053", "source_sha256": "870f23005b9ebdf0efdfa316ec12ab7e42db60a35b9c78b4464252991d2db8ff", "pdf_pages": 71, "source_locator": "Theorems 0.1.1 and 0.1.2, Corollaries 8.1.5 and 8.1.7", "main_result": "On a smooth scheme over a finite field, an irreducible coefficient with finite-order determinant is pure of weight 0 and admits companions including at p. Algebraic coefficients admit companions at the stated primes more generally.", "classical_zeta_transfer_obstacle": "Companion comparison preserves characteristic polynomials of closed-point Frobenius in existing finite-field cohomology. It has no input realizing classical ζ across all rational primes.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2008.13053", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-KEDLAYA2024"]}','Étale and crystalline companions, II','["Kiran S. Kedlaya"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2008.13053v8, 24 Mar 2026','https://arxiv.org/pdf/2008.13053','870f23005b9ebdf0efdfa316ec12ab7e42db60a35b9c78b4464252991d2db8ff','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-GAITSGORYRASKIN2024','corpus/bibliography.jsonl',275,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-GAITSGORYRASKIN2024", "title": "Proof of the geometric Langlands conjecture V: the multiplicity one theorem", "authors": ["Dennis Gaitsgory", "Sam Raskin"], "year": 2024, "venue": "arXiv:2409.09856", "language": "English", "doi": null, "arxiv_id": "2409.09856", "canonical_url": "https://arxiv.org/abs/2409.09856", "publication_status": "preprint", "version": "arXiv:2409.09856v3, 16 Jan 2026", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Introduction equation (0.1), Theorems 4.3.2 and 5.2.3.", "source_path": "sources/classical63_automorphic_geometry/gaitsgoryraskin2024.pdf", "source_url": "https://arxiv.org/pdf/2409.09856", "source_sha256": "d12cfa9b68ab1a29b302e6a439eaf03bc402339e9493e0734ed7020b93e2147e", "pdf_pages": 62, "source_locator": "Introduction equation (0.1), Theorems 4.3.2 and 5.2.3", "main_result": "Completes the geometric Langlands equivalence for the de Rham categories in the series. The argument uses scalar endomorphisms of the vacuum Poincaré sheaf and the indicated topology of irreducible local systems.", "classical_zeta_transfer_obstacle": "The geometric categorical equivalence for bundles and local systems on a curve does not identify the completed classical ζ function or certify real spectral parameters for its zeros.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2409.09856", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-GAITSGORYRASKIN2024"]}','Proof of the geometric Langlands conjecture V: the multiplicity one theorem','["Dennis Gaitsgory", "Sam Raskin"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2409.09856v3, 16 Jan 2026','https://arxiv.org/pdf/2409.09856','d12cfa9b68ab1a29b302e6a439eaf03bc402339e9493e0734ed7020b93e2147e','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-KWAN2024','corpus/bibliography.jsonl',276,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-KWAN2024", "title": "Spectral moment formulae for GL(3) × GL(2) L-functions I: The cuspidal case", "authors": ["Chung-Hang Kwan"], "year": 2024, "venue": "Algebra & Number Theory 18, 1817–1864", "language": "English", "doi": "10.2140/ant.2024.18.1817", "arxiv_id": "2112.08568", "canonical_url": "https://doi.org/10.2140/ant.2024.18.1817", "publication_status": "published", "version": "original journal PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §1B Theorems 1.1 and 1.2.", "source_path": "sources/classical63_automorphic_geometry/kwan2024.pdf", "source_url": "https://msp.org/ant/2024/18-10/ant-v18-n10-p02-p.pdf", "source_sha256": "a696f97832916848d825b5e3b9c4f4296e3fbc74eacb0a4dd26011c7f1c29a22", "pdf_pages": 50, "source_locator": "§1B Theorems 1.1 and 1.2", "main_result": "For a fixed Hecke-normalized spherical SL(3,Z) Maaß cusp form with imaginary Langlands parameters and H in Cη, for 1/4+1/200<Re s<3/4 gives a weighted GL(3)×GL(2) spectral first-moment identity with integral transforms; Theorem 1.2 gives an identity for the transform when 1/2+1/100<Re s<1.", "classical_zeta_transfer_obstacle": "The cusp form is fixed and the degree-six L-functions are averaged over SL(2,Z) spectrum. This is not an eigenvalue identity for ζ.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2112.08568", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-KWAN2024"]}','Spectral moment formulae for GL(3) × GL(2) L-functions I: The cuspidal case','["Chung-Hang Kwan"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','original journal PDF','https://msp.org/ant/2024/18-10/ant-v18-n10-p02-p.pdf','a696f97832916848d825b5e3b9c4f4296e3fbc74eacb0a4dd26011c7f1c29a22','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-KWAN2025','corpus/bibliography.jsonl',277,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-KWAN2025", "title": "Spectral moment formulae for GL(3) × GL(2) L-functions III: the twisted case", "authors": ["Chung-Hang Kwan"], "year": 2025, "venue": "Mathematische Annalen 391, 363–398", "language": "English", "doi": "10.1007/s00208-024-02914-9", "arxiv_id": "2311.15417", "canonical_url": "https://doi.org/10.1007/s00208-024-02914-9", "publication_status": "published", "version": "arXiv:2311.15417v2, 11 Jun 2024", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1.1, equation (1.4).", "source_path": "sources/classical63_automorphic_geometry/kwan2025.pdf", "source_url": "https://arxiv.org/pdf/2311.15417", "source_sha256": "cc3641418e51642042d719f6b21f1ca818f25551e8910b6079e484e054838b93", "pdf_pages": 27, "source_locator": "Theorem 1.1, equation (1.4)", "main_result": "An admissible weight H and 1/4+1/200<Re s<3/4 give a reciprocity formula for the Hecke-twisted GL(3)×GL(2) first moment, with continuous and explicit arithmetic terms.", "classical_zeta_transfer_obstacle": "The formula analyzes a Hecke-twisted average and its transforms. It carries no sign or vanishing implication for individual classical ζ zeros.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2311.15417", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-KWAN2025"]}','Spectral moment formulae for GL(3) × GL(2) L-functions III: the twisted case','["Chung-Hang Kwan"]',NULL,'2025',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2311.15417v2, 11 Jun 2024','https://arxiv.org/pdf/2311.15417','cc3641418e51642042d719f6b21f1ca818f25551e8910b6079e484e054838b93','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-KWAN2026','corpus/bibliography.jsonl',278,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-KWAN2026", "title": "Spectral moment formulae for GL(3) × GL(2) L-functions II: the Eisenstein case", "authors": ["Chung-Hang Kwan"], "year": 2026, "venue": "Journal of the Institute of Mathematics of Jussieu 25, 2265–2312", "language": "English", "doi": "10.1017/S1474748026101844", "arxiv_id": "2310.09419", "canonical_url": "https://doi.org/10.1017/S1474748026101844", "publication_status": "published", "version": "arXiv:2310.09419v3, 16 Mar 2026", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorems 1.3–1.5, especially (1.7).", "source_path": "sources/classical63_automorphic_geometry/kwan2026.pdf", "source_url": "https://arxiv.org/pdf/2310.09419", "source_sha256": "60788811b6948b325d3a6e0a623993ce0a77dfddd8533ced4730df813d7a0655", "pdf_pages": 37, "source_locator": "Theorems 1.3–1.5, especially (1.7)", "main_result": "For H in Cη and 1/4+ε₀<Re s<3/4 establishes the explicit Eisenstein spectral reciprocity identity with residue terms and zeta-product integral; the central specialization is in Theorem 1.5.", "classical_zeta_transfer_obstacle": "The identity does contain ζ-products, but as shifted moments integrated against a transform. It gives no positivity condition forcing each zero onto the line.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2310.09419", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-KWAN2026"]}','Spectral moment formulae for GL(3) × GL(2) L-functions II: the Eisenstein case','["Chung-Hang Kwan"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2310.09419v3, 16 Mar 2026','https://arxiv.org/pdf/2310.09419','60788811b6948b325d3a6e0a623993ce0a77dfddd8533ced4730df813d7a0655','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-DDFL2025','corpus/bibliography.jsonl',279,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-DDFL2025", "title": "Nonvanishing of L-functions associated to fixed order characters over function fields", "authors": ["Chantal David", "Alexandra Florea", "Matilde Lalín"], "year": 2025, "venue": "arXiv:2506.07815", "language": "English", "doi": null, "arxiv_id": "2506.07815", "canonical_url": "https://arxiv.org/abs/2506.07815", "publication_status": "preprint", "version": "arXiv:2506.07815v1, 9 Jun 2025", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1.1 and Corollary 1.2.", "source_path": "sources/classical63_automorphic_geometry/ddfl2025.pdf", "source_url": "https://arxiv.org/pdf/2506.07815", "source_sha256": "f7accd50e4afa22cdd239ab8651b38badf29ec6c01ce53a1937e138224db9054", "pdf_pages": 56, "source_locator": "Theorem 1.1 and Corollary 1.2", "main_result": "For ℓ≥3, q fixed with q≡1 mod 2ℓ, and d nonzero modulo ℓ, obtains one-level density for the specified thin family with Fourier support depending on ℓ (6/5 for ℓ=3 and 26/23 for ℓ=4) and proves positive-proportion central nonvanishing.", "classical_zeta_transfer_obstacle": "The argument starts from the function-field RH and bounds an average over residue-symbol characters. A central nonvanishing frequency does not constrain off-line zeros of ζ.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2506.07815", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-DDFL2025"]}','Nonvanishing of L-functions associated to fixed order characters over function fields','["Chantal David", "Alexandra Florea", "Matilde Lalín"]',NULL,'2025',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2506.07815v1, 9 Jun 2025','https://arxiv.org/pdf/2506.07815','f7accd50e4afa22cdd239ab8651b38badf29ec6c01ce53a1937e138224db9054','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-SAWINSHUSTERMAN2025','corpus/bibliography.jsonl',280,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-SAWINSHUSTERMAN2025", "title": "Short sums of trace functions over function fields and their applications", "authors": ["Will Sawin", "Mark Shusterman"], "year": 2025, "venue": "arXiv:2512.24080", "language": "English", "doi": null, "arxiv_id": "2512.24080", "canonical_url": "https://arxiv.org/abs/2512.24080", "publication_status": "preprint", "version": "arXiv:2512.24080v1, 30 Dec 2025", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1.3 and four preceding sheaf assumptions.", "source_path": "sources/classical63_automorphic_geometry/sawinshusterman2025.pdf", "source_url": "https://arxiv.org/pdf/2512.24080", "source_sha256": "ddc369f2b535bc51616acfa491a070e49024575d08b79c1f31c5b63f85fe13c1", "pdf_pages": 37, "source_locator": "Theorem 1.3 and four preceding sheaf assumptions", "main_result": "For the stated sheaves over squarefree moduli, bounds the sum over polynomials of norm <X by √q X^(1/2)Norm(g)^(log_q(2r(t)+c(t))). Each sheaf is mixed of nonpositive weights, has no finitely supported sections, has no geometric Artin–Schreier factor of the specified linear form (including the trivial factor), and has slopes at infinity at most 1.", "classical_zeta_transfer_obstacle": "The square-root mechanism uses geometric trace functions over the polynomial interval and conductor-dependent rank bounds. There is no supplied integer or classical ζ replacement for that geometry.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2512.24080", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-SAWINSHUSTERMAN2025"]}','Short sums of trace functions over function fields and their applications','["Will Sawin", "Mark Shusterman"]',NULL,'2025',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2512.24080v1, 30 Dec 2025','https://arxiv.org/pdf/2512.24080','ddc369f2b535bc51616acfa491a070e49024575d08b79c1f31c5b63f85fe13c1','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-NEWTONTHORNE2026','corpus/bibliography.jsonl',281,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-NEWTONTHORNE2026", "title": "Symmetric power functoriality for Hilbert modular forms", "authors": ["James Newton", "Jack A. Thorne"], "year": 2026, "venue": "Annals of Mathematics 203, 283–347", "language": "English", "doi": "10.4007/annals.2026.203.1.4", "arxiv_id": "2212.03595", "canonical_url": "https://doi.org/10.4007/annals.2026.203.1.4", "publication_status": "published", "version": "Cambridge repository manuscript with internal pagination", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem A.", "source_path": "sources/classical63_automorphic_geometry/newtonthorne2026.pdf", "source_url": "https://api.repository.cam.ac.uk/server/api/core/bitstreams/6bd9d94f-51d3-42e2-9cb1-ffc812189ac5/content", "source_sha256": "635cb99e56a6987814066d78bd9d27a18ebe7dbd4765f32073c7990d8e00d0c5", "pdf_pages": 52, "source_locator": "Theorem A", "main_result": "For totally real F and non-CM cuspidal GL(2) representations essentially square-integrable at infinity, each Sym^(n−1), n≥2, is cuspidal automorphic and realizes the symmetric power of the local Weil–Deligne representation at every place.", "classical_zeta_transfer_obstacle": "Matching local symmetric powers for holomorphic Hilbert forms cannot give a zero-exclusion result for degree-one ζ.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2212.03595", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-NEWTONTHORNE2026"]}','Symmetric power functoriality for Hilbert modular forms','["James Newton", "Jack A. Thorne"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','Cambridge repository manuscript with internal pagination','https://api.repository.cam.ac.uk/server/api/core/bitstreams/6bd9d94f-51d3-42e2-9cb1-ffc812189ac5/content','635cb99e56a6987814066d78bd9d27a18ebe7dbd4765f32073c7990d8e00d0c5','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-SAWIN2026','corpus/bibliography.jsonl',282,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-SAWIN2026", "title": "A refined random matrix model for function field L-functions", "authors": ["Will Sawin"], "year": 2026, "venue": "Duke Mathematical Journal 175, 1163–1263", "language": "English", "doi": "10.1215/00127094-2025-0049", "arxiv_id": "2409.02876", "canonical_url": "https://doi.org/10.1215/00127094-2025-0049", "publication_status": "published", "version": "arXiv:2409.02876v1, 4 Sep 2024", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorems 1.2, 1.3 and 1.5.", "source_path": "sources/classical63_automorphic_geometry/sawin2026.pdf", "source_url": "https://arxiv.org/pdf/2409.02876", "source_sha256": "e85fd4887b48d9234b7e46be8d43da296f0953c7ec97af853f99ad87636302ab", "pdf_pages": 69, "source_locator": "Theorems 1.2, 1.3 and 1.5", "main_result": "For q>11, Theorem 1.5 compares shifted critical-line mixed moments of fixed-conductor characters over F_q[T] to the refined model moments with an explicit power error. Theorems 1.2–1.3 control complementary test components.", "classical_zeta_transfer_obstacle": "The comparison fixes q and increases conductor degree, preserving arithmetic corrections of a finite-field family. It does not yield an identity for the zero set of a single classical function.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2409.02876", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-SAWIN2026"]}','A refined random matrix model for function field L-functions','["Will Sawin"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2409.02876v1, 4 Sep 2024','https://arxiv.org/pdf/2409.02876','e85fd4887b48d9234b7e46be8d43da296f0953c7ec97af853f99ad87636302ab','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-HONG2026','corpus/bibliography.jsonl',283,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-HONG2026", "title": "Non-vanishing of primitive cubic, quartic and sextic L-functions", "authors": ["Ziwei Hong"], "year": 2026, "venue": "arXiv:2610.15316", "language": "English", "doi": null, "arxiv_id": "2610.15316", "canonical_url": "https://arxiv.org/abs/2610.15316", "publication_status": "preprint", "version": "arXiv:2610.15316v2, 24 Oct 2026", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorems 1.1 and 1.2, family (1.2).", "source_path": "sources/classical63_automorphic_geometry/gaozhao2026.pdf", "source_url": "https://arxiv.org/pdf/2610.15316", "source_sha256": "de5714451e4bae80991097483e5ef9fe904afc134ad0493598b08433f1aa0a32", "pdf_pages": 31, "source_locator": "Theorems 1.1 and 1.2, family (1.2)", "main_result": "For ℓ=3,4,6 and fixed odd q≡−1 mod ℓ, gives a positive liminf for central nonvanishing within the specified primitive non-Kummer families along ℓ−1 dividing g; Theorem 1.2 gives twisted first moments for ℓ=4,6.", "classical_zeta_transfer_obstacle": "The proof uses special finite-field families and studies values at 1/2. No passage to an all-zero assertion for classical ζ follows.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2610.15316", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-HONG2026"]}','Non-vanishing of primitive cubic, quartic and sextic L-functions','["Ziwei Hong"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2610.15316v2, 24 Oct 2026','https://arxiv.org/pdf/2610.15316','de5714451e4bae80991097483e5ef9fe904afc134ad0493598b08433f1aa0a32','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AG63-NELSON','corpus/bibliography.jsonl',284,'full_text_accessed','papers/classical63_automorphic_geometry_notes.md','{"id": "PAPER-AG63-NELSON", "title": "Bounds for standard L-functions", "authors": ["Paul D. Nelson"], "year": 2021, "venue": "arXiv:2109.15230", "language": "English", "doi": null, "arxiv_id": "2109.15230", "canonical_url": "https://arxiv.org/abs/2109.15230", "publication_status": "preprint", "version": "arXiv:2109.15230v3, 10 Jun 2026", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1.1, equation (1.2).", "source_path": "sources/classical63_automorphic_geometry/nelson.pdf", "source_url": "https://arxiv.org/pdf/2109.15230", "source_sha256": "d50f4230d04db3992aeb512073024bb0cbc725b924eb5d5767ebca5dc3cde8d4", "pdf_pages": 256, "source_locator": "Theorem 1.1, equation (1.2)", "main_result": "For every n there is positive t-aspect subconvex saving for unitary cuspidal GL(n) over Q, and for n≥2 the explicit lower bound for δ_n is 2/(3n^5−2n^4−n²).", "classical_zeta_transfer_obstacle": "A saving in the growth exponent of central-line values cannot by itself exclude a zero with real part >1/2, including for degree one.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_automorphic_geometry_notes.md", "track_file": "papers/classical63_automorphic_geometry_records.jsonl", "arxiv": "2109.15230", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AG63-NELSON"]}','Bounds for standard L-functions','["Paul D. Nelson"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2109.15230v3, 10 Jun 2026','https://arxiv.org/pdf/2109.15230','d50f4230d04db3992aeb512073024bb0cbc725b924eb5d5767ebca5dc3cde8d4','papers/classical63_automorphic_geometry_notes.md','papers/classical63_automorphic_geometry_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-DM63-GARUNKSTIS2003','corpus/bibliography.jsonl',285,'full_text_accessed','papers/classical63_derivative_moments_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "arxiv_id": null, "audit_level": 0, "authors": ["Ramūnas Garunkštis"], "bibliographic_verified": true, "canonical_url": "https://empslocal.ex.ac.uk/people/staff/mrwatkin/zeta/garunkstis2.pdf", "conditions": "Unconditional, with the target normalization and quantitative size restrictions of Theorem 1.", "doi": null, "full_text_accessed": true, "id": "PAPER-DM63-GARUNKSTIS2003", "language": "English", "main_result": "An explicit finite shift bound and a uniform positive-measure lower bound for approximation on restricted discs.", "pdf_pages": 21, "publication_status": "published", "read_scope": "Read the target normalization, disc restriction, effective shift theorem and subsequent comparison to Voronin.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Author PDF pp.2–3, Theorem 1 and subsequent remarks", "source_path": "sources/classical63_derivative_moments/garunkstis2003.pdf", "source_sha256": "e034c059ec8000cfdaa72c870894cfbe310ed1e711db19d9e483d3ca2a548d52", "source_url": "https://empslocal.ex.ac.uk/people/staff/mrwatkin/zeta/garunkstis2.pdf", "substantive_reading": true, "title": "The effective universality theorem for the Riemann zeta function", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "Proceedings of the Session in Analytic Number Theory and Diophantine Equations, eds. D. R. Heath-Brown and B. Z. Moroz, Bonner Mathematische Schriften 360, article 16, 21 pp.", "version": "author proceedings manuscript dated February 2003", "whole_work_read": false, "year": 2003, "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DM63-GARUNKSTIS2003"]}','The effective universality theorem for the Riemann zeta function','["Ramūnas Garunkštis"]',NULL,'2003',0,0,'selected_checkpoint_priority_work','full_text_accessed','author proceedings manuscript dated February 2003','https://empslocal.ex.ac.uk/people/staff/mrwatkin/zeta/garunkstis2.pdf','e034c059ec8000cfdaa72c870894cfbe310ed1e711db19d9e483d3ca2a548d52','papers/classical63_derivative_moments_notes.md','papers/classical63_derivative_moments_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-DM63-NG2004','corpus/bibliography.jsonl',286,'full_text_accessed','papers/classical63_derivative_moments_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "arxiv_id": "math/0310382", "audit_level": 0, "authors": ["Nathan Ng"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1215/S0012-7094-04-12522-9", "conditions": "Theorem 1 assumes RH. The twisted formulas in Theorems 2–3 are stated unconditionally.", "doi": "10.1215/S0012-7094-04-12522-9", "full_text_accessed": true, "id": "PAPER-DM63-NG2004", "language": "English", "main_result": "The fourth discrete derivative moment is bounded above and below by positive constants times T(log(T/(2π)))⁹.", "pdf_pages": 25, "publication_status": "published", "read_scope": "Read the two-sided theorem and its relation to the two auxiliary twisted sums.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Author PDF pp.2–3, Theorems 1–3", "source_path": "sources/classical63_derivative_moments/ngfourth.pdf", "source_sha256": "5c4a21a411292ae5a24fdbd94c19e7ce4962f064092e286616f6cf68d9d69168", "source_url": "https://arxiv.org/pdf/math/0310382v1", "substantive_reading": true, "title": "The fourth moment of ζ′(ρ)", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "Duke Mathematical Journal 125(2), 243–266", "version": "author arXiv math/0310382v1", "whole_work_read": false, "year": 2004, "arxiv": "math/0310382", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DM63-NG2004"]}','The fourth moment of ζ′(ρ)','["Nathan Ng"]',NULL,'2004',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv math/0310382v1','https://arxiv.org/pdf/math/0310382v1','5c4a21a411292ae5a24fdbd94c19e7ce4962f064092e286616f6cf68d9d69168','papers/classical63_derivative_moments_notes.md'