INSERT INTO "papers" VALUES('PAPER-DM63-NG2007','corpus/bibliography.jsonl',287,'full_text_accessed','papers/classical63_derivative_moments_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "arxiv_id": "0706.1763", "audit_level": 0, "authors": ["Nathan Ng"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1112/S0025579300000255", "conditions": "Theorem 1.2 assumes RH and the large zero-free region conjecture for Dirichlet L-functions. Theorem 1.3 separates divisor and resonator coefficient cases.", "correction_history": "Benli–Elma–Ng 2024, paragraph following (11), identifies an inherited large-sieve error and minor errors in the Theorem 1.3 main term and gives the corrected one-shift approach.", "doi": "10.1112/S0025579300000255", "full_text_accessed": true, "id": "PAPER-DM63-NG2007", "language": "English", "main_result": "Theorem 1.3 gives an arithmetic expression for the linear twist Σζ′(ρ)X(ρ)Y(1−ρ). Theorem 1.1 on RH supplies infinitely many simple zeros with |ζ′(ρ)| larger than every prescribed fixed log power.", "pdf_pages": 41, "publication_status": "published", "read_scope": "Read the linear twist, coefficient and support assumptions, and the conditional large-derivative consequences.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Author PDF §§1–2, Theorems 1.1–1.3", "source_path": "sources/classical63_derivative_moments/ng2007.pdf", "source_sha256": "d5a43de8284d9693de6ac62433d7f7f432f650cb274b24529ee92137fa711cdd", "source_url": "https://arxiv.org/pdf/0706.1763v1", "substantive_reading": true, "title": "A discrete mean value of the derivative of the Riemann zeta function", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "Mathematika 54(1–2), 113–155", "version": "author arXiv 0706.1763v1", "whole_work_read": false, "year": 2007, "arxiv": "0706.1763", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DM63-NG2007"]}','A discrete mean value of the derivative of the Riemann zeta function','["Nathan Ng"]',NULL,'2007',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv 0706.1763v1','https://arxiv.org/pdf/0706.1763v1','d5a43de8284d9693de6ac62433d7f7f432f650cb274b24529ee92137fa711cdd','papers/classical63_derivative_moments_notes.md','papers/classical63_derivative_moments_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-DM63-SOUND2008','corpus/bibliography.jsonl',288,'full_text_accessed','papers/classical63_derivative_moments_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "arxiv_id": "0708.3990", "audit_level": 0, "authors": ["K. Soundararajan"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1007/s00208-008-0243-2", "conditions": "Unconditional. The theorem also gives a large-value measure lower bound in a specified V range.", "doi": "10.1007/s00208-008-0243-2", "full_text_accessed": true, "id": "PAPER-DM63-SOUND2008", "language": "English", "main_result": "The dyadic maximum of |ζ(1/2+it)| for T≤t≤2T is at least exp((1+o(1))√(log T/log log T)).", "pdf_pages": 16, "publication_status": "published", "read_scope": "Read the dyadic maximum lower bound and the comparison of two resonator quadratic forms.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Author PDF §1 Theorem 1 and §2 equations (3)–(5)", "source_path": "sources/classical63_derivative_moments/sound2008.pdf", "source_sha256": "016ef7f4681dfcdb50e194bcf105250e2a66d0d79821c2daf3d98bcfb094a21d", "source_url": "https://arxiv.org/pdf/0708.3990v2", "substantive_reading": true, "title": "Extreme values of zeta and L-functions", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "Mathematische Annalen 342(2), 467–486", "version": "author arXiv 0708.3990v2", "whole_work_read": false, "year": 2008, "arxiv": "0708.3990", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DM63-SOUND2008"]}','Extreme values of zeta and L-functions','["K. Soundararajan"]',NULL,'2008',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv 0708.3990v2','https://arxiv.org/pdf/0708.3990v2','016ef7f4681dfcdb50e194bcf105250e2a66d0d79821c2daf3d98bcfb094a21d','papers/classical63_derivative_moments_notes.md','papers/classical63_derivative_moments_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-DM63-NG2008','corpus/bibliography.jsonl',289,'full_text_accessed','papers/classical63_derivative_moments_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "arxiv_id": "0706.1765", "audit_level": 0, "authors": ["Nathan Ng"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1112/jlms/jdn022", "conditions": "Theorems 1 and 3 assume RH. The stronger large-value Theorem 2 also assumes the large zero-free region conjecture. The small-value conclusion allows multiple zeros.", "doi": "10.1112/jlms/jdn022", "full_text_accessed": true, "id": "PAPER-DM63-NG2008", "language": "English", "main_result": "In addition to large-derivative results, Theorem 3 gives |ζ′(ρ)|≪exp(−(√(2/3)−ε)√(log|γ|/log log|γ|)) infinitely often.", "pdf_pages": 16, "publication_status": "published", "read_scope": "Read the three hypotheses and §6 split into infinitely many multiple zeros and eventual simplicity.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Author PDF Theorems 1–3 and §6, Proposition 8", "source_path": "sources/classical63_derivative_moments/ng2008.pdf", "source_sha256": "210a03b498f3e6a7d23ee4461ba43ef2f304e59d859c0d81c7fc15e3b8b823cb", "source_url": "https://arxiv.org/pdf/0706.1765v1", "substantive_reading": true, "title": "Extreme values of ζ′(ρ)", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "Journal of the London Mathematical Society s2-78(2), 273–289", "version": "author arXiv 0706.1765v1", "whole_work_read": false, "year": 2008, "arxiv": "0706.1765", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DM63-NG2008"]}','Extreme values of ζ′(ρ)','["Nathan Ng"]',NULL,'2008',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv 0706.1765v1','https://arxiv.org/pdf/0706.1765v1','210a03b498f3e6a7d23ee4461ba43ef2f304e59d859c0d81c7fc15e3b8b823cb','papers/classical63_derivative_moments_notes.md','papers/classical63_derivative_moments_records.jsonl');
