INSERT INTO "papers" VALUES('PAPER-DM63-KIRILA2020','corpus/bibliography.jsonl',297,'full_text_accessed','papers/classical63_derivative_moments_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "arxiv_id": "1804.08826", "audit_level": 0, "authors": ["Scott Kirila"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1112/mtk.12008", "conditions": "RH. The proof uses shifted moments and Cauchy in a radius ≍1/log T.", "doi": "10.1112/mtk.12008", "full_text_accessed": true, "id": "PAPER-DM63-KIRILA2020", "language": "English", "main_result": "For fixed real k>0 the normalized 2k-th discrete derivative moment is ≪_k(log T)^{k(k+2)}.", "pdf_pages": 21, "publication_status": "published", "read_scope": "Read the sharp-exponent statements, complex shift range and relation between shift and derivative moments.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Author PDF Theorems 1.1–1.2, Corollary 1.3, proof outline", "source_path": "sources/classical63_derivative_moments/kirila2020.pdf", "source_sha256": "531ef3fae7e7d6ec1f421c4b9018474d24dcf2fb9a4ad7738886cf594c0a7e18", "source_url": "https://arxiv.org/pdf/1804.08826v2", "substantive_reading": true, "title": "An upper bound for discrete moments of the derivative of the Riemann zeta-function", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "Mathematika 66(2), 475–497", "version": "author arXiv 1804.08826v2", "whole_work_read": false, "year": 2020, "arxiv": "1804.08826", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DM63-KIRILA2020"]}','An upper bound for discrete moments of the derivative of the Riemann zeta-function','["Scott Kirila"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv 1804.08826v2','https://arxiv.org/pdf/1804.08826v2','531ef3fae7e7d6ec1