INSERT INTO "papers" VALUES('PAPER-DM63-GAO2021','corpus/bibliography.jsonl',298,'full_text_accessed','papers/classical63_derivative_moments_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "arxiv_id": "2106.03057", "audit_level": 0, "authors": ["Peng Gao"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2106.03057", "conditions": "RH.", "doi": null, "full_text_accessed": true, "id": "PAPER-DM63-GAO2021", "language": "English", "main_result": "The normalized 2k-th discrete derivative moment is ≫_k(log T)^{k(k+2)} for fixed real k≥0.", "pdf_pages": 15, "publication_status": "preprint", "read_scope": "Read the real moment range and the polynomial lower-bound principle.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Author PDF Theorem 1.1 and §§2–3", "source_path": "sources/classical63_derivative_moments/gao2021.pdf", "source_sha256": "daaeb413ab49a6b74efae66431fe7672d7a033b970301bec756dd551ef5ce610", "source_url": "https://arxiv.org/pdf/2106.03057v1", "substantive_reading": true, "title": "Sharp lower bounds for moments of ζ′(ρ)", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "arXiv:2106.03057", "version": "author arXiv 2106.03057v1", "whole_work_read": false, "year": 2021, "arxiv": "2106.03057", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DM63-GAO2021"]}','Sharp lower bounds for moments of ζ′(ρ)','["Peng Gao"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv 2106.03057v1','https://arxiv.org/pdf/2106.03057v1','daaeb413ab49a6b74efae66431fe7672d7a033b970301bec756dd551ef5ce610','papers/classical63_derivative_moments_notes.md','papers/classical63_derivative_moments_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-DM63-HLZ2022','corpus/bibliography.jsonl',299,'full_text_accessed','audits/adversarial_reviews/release75_hlz_whole_skeptic.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "additional_manifestations": [{"pdf_pages": 42, "source_path": "sources/classical63_derivative_moments/hlz2022.pdf", "source_sha256": "73c78d922741658678023e73bd0684c1003261906ccc97b48f2e727f5874f6f6", "source_url": "https://arxiv.org/pdf/2003.09368v1", "version": "author arXiv v1"}], "arxiv_id": "2003.09368", "audit_level": 1, "authors": ["Winston Heap", "Junxian Li", "Jing Zhao"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.2140/ant.2022.16.1589", "conditions": "Theorem 5 has small complex shifts ≪1/log T, length T^θ with θ<1/2, submultiplicativity and divisor/log coefficient bounds. Theorem 1 assumes RH and simplicity of all zeta zeros.", "doi": "10.2140/ant.2022.16.1589", "full_text_accessed": true, "id": "PAPER-DM63-HLZ2022", "language": "English", "main_result": "The unconditional two-shift theorem yields Σ|ζ′(ρ)|²|2^{1−ρ}−1|² after double differentiation and restriction to RH. The original negative-moment theorem is distinct.", "pdf_pages": 37, "publication_status": "published", "read_scope": "Two independent agents read all 37 journal pages, sections 1–6, acknowledgments and references, with arXiv v1 comparison. Complete reading is Level 1; the director has adjudicated the scoped Theorem 5 and sharp continuous interface and polynomial-band consequences. Whole-paper Level 3 adjudication, including source smoothing corrections and the complete negative-moment reconstruction, remains pending.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Printed Theorem 1 and §4 Theorem 5 (p.1605), equations (5), (6) and (24), complex shifts explicit at p.1607. Author version Theorem 2.", "source_path": "sources/classical63_derivative_moments/hlz2022print.pdf", "source_sha256": "6162632530cbeee8c1664d7ea53e844cffa9dbc53fe00a8cd8270e2d713b6a82", "source_url": "https://pure.mpg.de/rest/items/item_3368312_4/component/file_3451014/content", "substantive_reading": true, "title": "Lower bounds for discrete negative moments of the Riemann zeta function", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "Algebra & Number Theory 16(7), 1589–1625", "version": "journal version hosted by Max Planck, with repository cover", "whole_work_read": true, "year": 2022, "arxiv": "2003.09368", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DM63-HLZ2022"], "scope_update_history": [{"fields": {"claim_verification_status": "Scoped journal Theorem5 fixed-polynomial double differentiation and divisor-closed-padding transfer independently checked; negative-moment theorem not technically audited.", "read_scope": "Targeted full-text reading of §4 Theorem5 and complex-shift proof plus fixed coefficient specialization; two independent derivative-tail derivations. Whole-paper reading not claimed."}, "evidence": "audits/adversarial_reviews/director_hlz_prime_torus_round9.md", "track_file": "quality/zzzz_director_round9_source_scope_updates.jsonl"}, {"fields": {"audit_level": 1, "whole_work_read": true, "substantive_reading": true, "read_scope": "Two independent agents read all 37 journal pages, sections 1–6, acknowledgments and references, with arXiv v1 comparison. Complete reading is Level 1; the director has adjudicated the scoped Theorem 5 and sharp continuous interface and polynomial-band consequences. Whole-paper Level 3 adjudication, including source smoothing corrections and the complete negative-moment reconstruction, remains pending.", "claim_verification_status": "Complete reading at Level 1. Published Theorem 5 with explicit primary formula and independently repaired sharp interface is separately adjudicated. Literal arbitrary-smoothing-kernel claims are not endorsed by that scoped decision.", "independent_whole_reading_reviews": ["audits/adversarial_reviews/geometry75_hlz_whole_advocate.md", "audits/adversarial_reviews/release75_hlz_whole_skeptic.md"]}, "evidence": "audits/adversarial_reviews/release75_hlz_whole_skeptic.md", "track_file": "quality/zzzzzzz_round12_source_scope_updates.jsonl"}], "claim_verification_status": "Complete reading at Level 1. Published Theorem 5 with explicit primary formula and independently repaired sharp interface is separately adjudicated. Literal arbitrary-smoothing-kernel claims are not endorsed by that scoped decision.", "scope_update_evidence": "audits/adversarial_reviews/release75_hlz_whole_skeptic.md", "additional_scope_update_files": ["quality/zzzz_director_round9_source_scope_updates.jsonl", "quality/zzzzzzz_round12_source_scope_updates.jsonl"], "independent_whole_reading_reviews": ["audits/adversarial_reviews/geometry75_hlz_whole_advocate.md", "audits/adversarial_reviews/release75_hlz_whole_skeptic.md"]}','Lower bounds for discrete negative moments of the Riemann zeta function','["Winston Heap", "Junxian Li", "Jing Zhao"]',NULL,'2022',1,1,'selected_checkpoint_priority_work','full_text_accessed','journal version hosted by Max Planck, with repository cover','https://pure.mpg.de/rest/items/item_3368312_4/component/file_3451014/content','6162632530cbeee8c1664d7ea53e844cffa9dbc53fe00a8cd8270e2d713b6a82','papers/classical63_derivative_moments_notes.md','papers/classical63_derivative_moments_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-DM63-YANG2022','corpus/bibliography.jsonl',300,'full_text_accessed','papers/classical63_derivative_moments_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "arxiv_id": "2108.02301", "audit_level": 0, "authors": ["Daodao Yang"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1112/mtk.12130", "conditions": "Unconditional. The heights in these maxima have no zero constraint.", "doi": "10.1112/mtk.12130", "full_text_accessed": true, "id": "PAPER-DM63-YANG2022", "language": "English", "main_result": "For fixed l≥1 and 0≤β<1 the maximum of |ζ⁽ˡ⁾(1/2+it)| on [T^β,T] is ≥exp(c√(log T log₃T/log₂T)) for 0<c<√(2(1−β)). Theorem 1 treats the 1-line with l allowed to grow.", "pdf_pages": 25, "publication_status": "published", "read_scope": "Read the derivative-order ranges, vertical lines and height intervals of the unconditional lower bounds.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Printed pp.486–487, Theorems 1–2", "source_path": "sources/classical63_derivative_moments/yang2022.pdf", "source_sha256": "03696717c3fa332c51f541d37aaf75e660b80f061bd7ed623e2e6240ddbc0b5b", "source_url": "https://tugraz.elsevierpure.com/ws/portalfiles/portal/49282848/mathematika_yang_22_12130.pdf", "substantive_reading": true, "title": "Extreme values of derivatives of the Riemann zeta function", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "Mathematika 68(2), 486–510", "version": "author arXiv 2108.02301", "whole_work_read": false, "year": 2022, "arxiv": "2108.02301", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DM63-YANG2022"]}','Extreme values of derivatives of the Riemann zeta function','["Daodao Yang"]',NULL,'2022',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv 2108.02301','https://tugraz.elsevierpure.com/ws/portalfiles/portal/49282848/mathematika_yang_22_12130.pdf','03696717c3fa332c51f541d37aaf75e660b80f061bd7ed623e2e6240ddbc0b5b','papers/classical63_derivative_moments_notes.md','papers/classical63_derivative_moments_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-DM63-BEN2024','corpus/bibliography.jsonl',301,'full_text_accessed','papers/classical63_derivative_moments_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "arxiv_id": "2311.13554", "audit_level": 0, "authors": ["Kübra Benli", "Ertan Elma", "Nathan Ng"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1112/mtk.12281", "conditions": "Separate unconditional divisor/log-bounded and GRH(Θ) variants. Shift |α|≤1/(15 log T) and hypotheses (6)–(8) in the author version.", "correction_history": "Following (11), the authors identify the inherited improper large-sieve application in Conrey–Ghosh–Gonek and Ng, use Bui–Heath-Brown techniques, and correct the Ng 2007 main term.", "doi": "10.1112/mtk.12281", "full_text_accessed": true, "id": "PAPER-DM63-BEN2024", "language": "English", "main_result": "Evaluates a small one-shift mean of ζ(ρ+α) with two Dirichlet polynomials. A derivative in α gives a linear derivative twist.", "pdf_pages": 42, "publication_status": "published", "read_scope": "Read the single-shift theorem, support and coefficient conditions, and the correction and comparison paragraphs.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Author PDF §1, Theorem 1.1 and discussion after (11), comparison (12)", "source_path": "sources/classical63_derivative_moments/ben2024.pdf", "source_sha256": "e131c521aa4cb31e02acdba725fa5d2228fc30aa1903f243a9a699edf05ce2b0", "source_url": "https://arxiv.org/pdf/2311.13554v1", "substantive_reading": true, "title": "A discrete mean value of the Riemann zeta function", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "Mathematika 70(4), e12281", "version": "author arXiv 2311.13554v1", "whole_work_read": false, "year": 2024, "arxiv": "2311.13554", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "