INSERT INTO "papers" VALUES('PAPER-DM63-LEEPANKOWSKI2025','corpus/bibliography.jsonl',302,'full_text_accessed','audits/adversarial_reviews/director_lee_pankowski_scope_round9.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "additional_manifestations": [{"pdf_pages": 11, "source_path": "sources/classical63_derivative_moments/lp2025print.pdf", "source_sha256": "0d7ce7a15c27b69aaab0c8a9d750d115db1d90a0258f477acd1a453d73848470", "source_url": "https://link.springer.com/content/pdf/10.1007/s11139-025-01144-0.pdf", "version": "original journal PDF"}], "arxiv_id": "2502.15364", "audit_level": 1, "authors": ["Yoonbok Lee", "Łukasz Pańkowski"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1007/s11139-025-01144-0", "conditions": "Target continuous and nonvanishing on the closed disc and holomorphic in its interior. The disc lies strictly in 1/2<Re s<1.", "correction_history": "Nonvanishing omitted in both inspected restated statements; logarithmic proofs need it. Exact Rouche witness excludes literal RH-conditional target; global density alone does not refute exceptional-window limsup. Bounded correction search found none.", "doi": "10.1007/s11139-025-01144-0", "full_text_accessed": true, "id": "PAPER-DM63-LEEPANKOWSKI2025", "language": "English", "main_result": "For a nonvanishing target on a closed disc with left edge a>1/2, the logarithmic proof gives positive lower shift density for H=(log T)^B, B>2/(2a−1) on RH, and a positive upper density along selected blocks for B>4/(2a−1) unconditionally.", "pdf_pages": 7, "publication_status": "published", "read_scope": "Read all seven pages of arXiv v1 and compared the two theorem statements and relevant proof passages with the publisher PDF.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Author PDF §§1–4, Theorems 1.1–1.2, equation (3), §§2.4 and 3", "source_path": "sources/classical63_derivative_moments/lee_pankowski2025.pdf", "source_sha256": "aee29a78a4f1cac586eda71b02c0d99e6f2d050fc45677293677abf795a3be73", "source_url": "https://arxiv.org/pdf/2502.15364v1", "substantive_reading": true, "title": "Universality of the zeta function in short intervals", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "The Ramanujan Journal 68, article 5", "version": "author arXiv 2502.15364v1", "whole_work_read": true, "year": 2025, "arxiv": "2502.15364", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DM63-LEEPANKOWSKI2025"], "scope_update_history": [{"fields": {"correction_history": "Nonvanishing omitted in both inspected restated statements; logarithmic proofs need it. Exact Rouche witness excludes literal RH-conditional target; global density alone does not refute exceptional-window limsup. Bounded correction search found none.", "claim_verification_status": "Missing-target-hypothesis scope independently adjudicated; intended nonvanishing-target theorem not refuted, no verified-error flag."}, "evidence": "audits/adversarial_reviews/director_lee_pankowski_scope_round9.md", "track_file": "quality/zzzz_director_round9_source_scope_updates.jsonl"}], "claim_verification_status": "Missing-target-hypothesis scope independently adjudicated; intended nonvanishing-target theorem not refuted, no verified-error flag.", "scope_update_evidence": "audits/adversarial_reviews/director_lee_pankowski_scope_round9.md", "additional_scope_update_files": ["quality/zzzz_director_round9_source_scope_updates.jsonl"]}','Universality of the zeta function in short intervals','["Yoonbok Lee", "Łukasz Pańkowski"]',NULL,'2025',1,1,'selected_checkpoint_priority_work','full_text_accessed','author arXiv 2502.15364v1','https://arxiv.org/pdf/2502.15364v1','aee29a78a4f1cac586eda71b02c0d99e6f2d050fc45677293677abf795a3be73','papers/classical63_derivative_moments_notes.md','papers/classical63_derivative_mom