INSERT INTO "papers" VALUES('PAPER-DM63-HUGHESPEARCECRUMP2025','corpus/bibliography.jsonl',303,'full_text_accessed','papers/classical63_derivative_moments_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "arxiv_id": "2509.07792", "audit_level": 0, "authors": ["Christopher Hughes", "Andrew Pearce-Crump"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2509.07792", "conditions": "Theorem 1 as formulated uses RH, with an earlier unconditional proof and weaker error cited. The general recipe and Conjecture 5 are conjectural.", "doi": null, "full_text_accessed": true, "id": "PAPER-DM63-HUGHESPEARCECRUMP2025", "language": "English", "main_result": "Gives a conjectural general recipe for integer mixed derivative moments. Conjecture 5 concerns Σζ′(ρ)². Theorem 1 reformulates a known arithmetic asymptotic for the linear derivative sum.", "pdf_pages": 29, "publication_status": "preprint", "read_scope": "Read the general conjecture and the two examples, including the distinction between a complex square and an absolute square.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Author PDF §1, Conjectures 1 and 5, Theorem 1, and the remark following it", "source_path": "sources/classical63_derivative_moments/int2025.pdf", "source_sha256": "bc5fd175f02557dfbdba53343afca95ba22e5b48cb1514e2eaf863c9e756ba1a", "source_url": "https://arxiv.org/pdf/2509.07792v1", "substantive_reading": true, "title": "Integer moments of the derivatives of the Riemann zeta function", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "arXiv:2509.07792", "version": "author arXiv 2509.07792v1", "whole_work_read": false, "year": 2025, "arxiv": "2509.07792", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DM63-HUGHESPEARCECRUMP2025"]}','Integer moments of the derivatives o