INSERT INTO "papers" VALUES('PAPER-DM63-SIMMWEI2026','corpus/bibliography.jsonl',304,'full_text_accessed','papers/classical63_derivative_moments_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "arxiv_id": "2409.03687", "audit_level": 0, "authors": ["Nick Simm", "Fei Wei"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1112/jlms.70487", "conditions": "The zeta height-average limit comes first for fixed σ>1/2. CUE theorems have their own geometric and moment ranges.", "doi": "10.1112/jlms.70487", "full_text_accessed": true, "id": "PAPER-DM63-SIMMWEI2026", "language": "English", "main_result": "Theorem 1.8 gives the unconditional fourth moment limit 204/[π²(2σ−1)^8] as σ↓1/2. Theorem 1.9 supplies the analogous higher integer moments under Lindelöf.", "pdf_pages": 50, "publication_status": "published", "read_scope": "Read the fixed-disc CUE result, the zeta-moment conjecture and the proved off-line moment orders and hypotheses.", "record_path": "papers/classical63_derivative_moments_notes.md", "source_locator": "Author PDF §§1.2–1.3, Theorems 1.1, 1.8–1.9 and Conjecture 1", "source_path": "sources/classical63_derivative_moments/cue2026.pdf", "source_sha256": "42f92124548e1c0aa9199f2d638436fe04aa133a52469286c980ab138246cf69", "source_url": "https://arxiv.org/pdf/2409.03687v2", "substantive_reading": true, "title": "On moments of the derivative of CUE characteristic polynomials and the Riemann zeta function", "track_file": "papers/classical63_derivative_moments_records.jsonl", "venue": "Journal of the London Mathematical Society 113(3), e70487", "version": "author arXiv 2409.03687v2", "whole_work_read": false, "year": 2026, "arxiv": "2409.03687", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DM63-SIMMWEI2026"]}','On moments of the derivative of CUE characteristic polynomials and the Riemann zeta function','["Nick Simm", "Fei Wei"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv 2409.03687v2','https://arxiv.org/pdf/2409.03687v2','42f92124548e1c0aa9199f2d638436fe04aa133a52469286c980ab138246cf69','papers/classical63_derivative_moments_notes.md','papers/classical63_derivative_moments_records.jsonl');
