INSERT INTO "papers" VALUES('PAPER-LF63-CGG1984GAPS','corpus/bibliography.jsonl',306,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-CGG1984GAPS", "title": "A Note on Gaps between Zeros of the Zeta Function", "authors": ["J. B. Conrey", "A. Ghosh", "S. M. Gonek"], "year": 1984, "venue": "Bulletin of the London Mathematical Society 16(4), 421–424", "language": "English", "doi": "10.1112/blms/16.4.421", "arxiv_id": null, "canonical_url": "https://doi.org/10.1112/blms/16.4.421", "publication_status": "published", "version": "original journal PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "read_scope": "Read all four pages in print, including the main theorem, two weight choices, coefficient-independent bounds, contour sketch, and November 1983 addition. Recomputed both integral tests numerically.", "source_path": "sources/classical63_lfunctions/gonek1984gaps.pdf", "source_url": "https://www.sas.rochester.edu/mth/people/faculty/gonek-steve/assets/pdf/6-note-on-gaps.pdf", "source_sha256": "27ff111e932ae9ba41d6204f844157dfaa556c51254999568101a936541dfbd4", "pdf_pages": 4, "source_locator": "Printed pp.421–424, main theorem pp.421–422 and addition in proof p.424", "historical_role": "Conditional small and large normalized zeta gaps", "main_result": "Assuming RH, the printed theorem gives limsup normalized gap >2.337 and liminf <0.5172; the addition in proof announces limsup >2.68 and improves the method-specific 6.2 cutoff to 3.74.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "correction_history": "Received 5 March 1983, revised 14 June 1983. Explicit November 1983 addition in proof on p.424.", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status":