INSERT INTO "papers" VALUES('PAPER-LF63-CGG1998SIMPLE','corpus/bibliography.jsonl',309,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-CGG1998SIMPLE", "title": "Simple Zeros of the Riemann Zeta-Function", "authors": ["J. B. Conrey", "A. Ghosh", "S. M. Gonek"], "year": 1998, "venue": "Proceedings of the London Mathematical Society s3-76(3), 497–522", "language": "English", "doi": "10.1112/S0024611598000306", "arxiv_id": null, "canonical_url": "https://doi.org/10.1112/S0024611598000306", "publication_status": "published", "version": "original journal PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read the introduction, definitions of simple and distinct proportions, Theorem 1, and its correction remark.", "source_path": "sources/classical63_lfunctions/cgg1998.pdf", "source_url": "https://www.sas.rochester.edu/mth/people/faculty/gonek-steve/assets/pdf/simplezeros.pdf", "source_sha256": "c85505f4bc8937b0a830a74d45736fc7418e35b6b05ec849dd770ae0bb1f039c", "pdf_pages": 26, "source_locator": "Printed pp.497–499, especially p.498 Theorem 1 and Remark", "historical_role": "Mollified moments of the zeta derivative at zeros", "main_result": "Assuming RH and GLH, the limits inferior of the proportions of simple and distinct zeros satisfy Cs ≥19/27 and Cd ≥5/6+1/81.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "correction_history": "The journal Remark explicitly restores GLH omitted in an earlier version and applies the correction to the cited companion [5]. Bui–Heath-Brown later proved the same simple-zero bound under RH by a new argument.", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-CGG1998SIMPLE"]}','Simple Zeros of the Riemann Zeta-Function','["J. B. Conrey", "A. Ghosh", "S. M. Gonek"]',NULL,'1998',0,0,'selected_checkpoint_priority_work','full_text_accessed','original journal PDF','https://www.sas.rochester.edu/mth/people/faculty/gonek-steve/assets/pdf/simplezeros.pdf','c85505f4bc8937b0a830a74d45736fc7418e35b6b05ec849dd770ae0bb1f039c','papers/classical63_lfunctions_notes.md','papers/classical63_lfunctions_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-LF63-CG1998SIXTH','corpus/bibliography.jsonl',310,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-CG1998SIXTH", "title": "A conjecture for the sixth power moment of the Riemann zeta-function", "authors": ["J. B. Conrey", "A. Ghosh"], "year": 1998, "venue": "International Mathematics Research Notices 1998(15), 775–780", "language": "English", "doi": "10.1155/S1073792898000476", "arxiv_id": "math/9807187", "canonical_url": "https://doi.org/10.1155/S1073792898000476", "publication_status": "published", "version": "author arXiv v1 (2 July 1998), with independent journal metadata", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "read_scope": "Read all five author-version pages, both heuristic derivations, the two cited short-polynomial theorems, and final remarks. Checked how the factor 42 arises.", "source_path": "sources/classical63_lfunctions/cg1998.pdf", "source_url": "https://arxiv.org/pdf/math/9807187v1", "source_sha256": "0f8a0952fd561bc5172ea466114bbd34bbb200bf9a08d5a31d8f12f1b0c546dc", "pdf_pages": 5, "source_locator": "arXiv pp.1–5; short-polynomial theorems pp.3–4", "historical_role": "Sixth zeta moment and long-polynomial extrapolation", "main_result": "The actual short-polynomial results hold with fixed 0<θ<1/2. Extrapolation to θ=1 and additional moment-error assumptions lead to the conjectural leading factor 42a₃/9! multiplying T(log T)⁹.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "correction_history": "The arXiv history lists only v1. Scope of the journal version was verified bibliographically.", "arxiv": "math/9807187", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-CG1998SIXTH"]}','A conjecture for the sixth power moment of the Riemann zeta-function','["J. B. Conrey", "A. Ghosh"]',NULL,'1998',1,1,'selected_checkpoint_priority_work','full_text_accessed','author arXiv v1 (2 July 1998), with independent journal metadata','https://arxiv.org/pdf/math/9807187v1','0f8a0952fd561bc5172ea466114bbd34bbb200bf9a08d5a31d8f12f1b0c546dc','papers/classical63_lfunctions_notes.md','papers/classical63_lfunctions_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-LF63-SOUND2000','corpus/bibliography.jsonl',311,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-SOUND2000", "title": "Nonvanishing of quadratic Dirichlet L-functions at s = 1/2", "authors": ["K. Soundararajan"], "year": 2000, "venue": "Annals of Mathematics 152(2), 447–488", "language": "English", "doi": "10.2307/2261390", "arxiv_id": "math/9902163", "canonical_url": "https://doi.org/10.2307/2261390", "publication_status": "published", "version": "author arXiv v2 (1 September 2000), paginated Annals text", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read the family definition and precise nonvanishing count on pp.447–449.", "source_path": "sources/classical63_lfunctions/sound2000.pdf", "source_url": "https://arxiv.org/pdf/math/9902163v2", "source_sha256": "58e9ce5a2f5f15b683dc16a2769cc53e69adb51d0e95b2756bf75149e024dfa7", "pdf_pages": 42, "source_locator": "Printed p.448, Theorem 1", "historical_role": "Quadratic family central nonvanishing", "main_result": "Unconditionally at least 7/8 of the positive odd square-free d give L(1/2,χ₈d)≠0, in the asymptotic proportion meaning of Theorem 1.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "arxiv": "math/9902163", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-SOUND2000"]}','Nonvanishing of quadratic Dirichlet L-functions at s = 1/2','["K. Soundararajan"]',NULL,'2000',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv v2 (1 September 2000), paginated Annals text','https://arxiv.org/pdf/math/9902163v2','58e9ce5a2f5f15b683dc16a2769cc53e69adb51d0e95b2756bf75149e024dfa7','papers/classical63_lfunctions_notes.md','papers/classical63_lfunctions_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-LF63-HKO2000','corpus/bibliography.jsonl',312,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-HKO2000", "title": "Random matrix theory and the derivative of the Riemann zeta function", "authors": ["C. P. Hughes", "J. P. Keating", "N. O’Connell"], "year": 2000, "venue": "Proceedings of the Royal Society of London A 456, 2611–2627", "language": "English", "doi": "10.1098/rspa.2000.0628", "arxiv_id": null, "canonical_url": "https://doi.org/10.1098/rspa.2000.0628", "publication_status": "published", "version": "original journal PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read the introduction and separate CUE theorem and zeta conjecture on pp.2611–2613.", "source_path": "sources/classical63_lfunctions/hko2000.pdf", "source_url": "https://maths.ucd.ie/~noconnell/pubs/hko00.pdf", "source_sha256": "d73c088120f1b12c78ae21f403ff30d47e2a09f9e5df6184584edf35ec83b086", "pdf_pages": 17, "source_locator": "Printed p.2613, Theorem 1.2 and Conjecture 1.3", "historical_role": "Random-matrix model for discrete derivative moments", "main_result": "The CUE derivative moment averaged over eigenangles has asymptotic factor G(k+2)^2/G(2k+3) times N^{k(k+2)} for bounded k with Re k>−3/2. The zeta counterpart is conjectural and includes the arithmetic factor.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-HKO2000"]}','Random matrix theory and the derivative of the Riemann zeta function','["C. P. Hughes", "J. P. Keating", "N. O’Connell"]',NULL,'2000',0,0,'selected_checkpoint_priority_work','full_text_accessed','original journal PDF','https://maths.ucd.ie/~noconnell/pubs/hko00.pdf','d73c088120f1b12c78ae21f403ff30d47e2a09f9e5df6184584edf35ec83b086','papers/classical63_lfunctions_notes.md','papers/classical63_lfunctions_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-LF63-ILS2000','corpus/bibliography.jsonl',313,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-ILS2000", "title": "Low lying zeros of families of L-functions", "authors": ["Henryk Iwaniec", "Wenzhi Luo", "Peter Sarnak"], "year": 2000, "venue": "Publications Mathématiques de l’IHÉS 91, 55–131", "language": "English", "doi": "10.1007/BF02698741", "arxiv_id": "math/9901141", "canonical_url": "https://www.numdam.org/item/PMIHES_2000__91__55_0/", "publication_status": "published", "version": "Numdam original journal digitization hosted by Williams College", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read the introductory conditions and statements of the low-lying-density theorems. Checked the global GRH convention alongside the support restrictions.", "source_path": "sources/classical63_lfunctions/ils2000w.pdf", "source_url": "https://web.williams.edu/Mathematics/sjmiller/public_html/ntandrmt/handouts/Lfns/IwaniecLuoSarnak_LowLyiingZerosOfFamiliesOfLFns.pdf", "source_sha256": "0194cd0ee4658449a41eeaf7303333169b7d5f049f9ea651d661cb3e71bac308", "pdf_pages": 78, "source_locator": "Printed pp.55–62, especially GRH convention on p.56 and Theorems 1.1–1.5", "historical_role": "One-level densities of automorphic L-function families", "main_result": "Under the §1 GRH convention, Theorem 1.1 gives level-aspect one-level density with Fourier support inside (−2,2) for sign-split holomorphic newform families at fixed even weight and square-free levels.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "arxiv": "math/9901141", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-ILS2000"]}','Low lying zeros of families of L-functions','["Henryk Iwaniec", "Wenzhi Luo", "Peter Sarnak"]',NULL,'2000',0,0,'selected_checkpoint_priority_work','full_text_accessed','Numdam original journal digitization hosted by Williams College','https://web.williams.edu/Mathematics/sjmiller/public_html/ntandrmt/handouts/Lfns/IwaniecLuoSarnak_LowLyiingZerosOfFamiliesOfLFns.pdf','0194cd0ee4658449a41eeaf7303333169b7d5f049f9ea651d661cb3e71bac308','papers/classical63_lfunctions_notes.md','papers/classical63_lfunctions_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-LF63-CI2000CUBIC','corpus/bibliography.jsonl',314,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-CI2000CUBIC", "title": "The cubic moment of central values of automorphic L-functions", "authors": ["J. B. Conrey", "H. Iwaniec"], "year": 2000, "venue": "Annals of Mathematics 151(3), 1175–1216", "language": "English", "doi": "10.2307/121132", "arxiv_id": "math/9810182", "canonical_url": "https://doi.org/10.2307/121132", "publication_status": "published", "version": "author arXiv v2 (1 May 2000), published Annals pagination", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read exact cubic family, character parity, positivity input and individual subconvex consequence.", "source_path": "sources/classical63_lfunctions/ci2000.pdf", "source_url": "https://arxiv.org/pdf/math/9810182v2", "source_sha256": "f307b36f600b786b926020931f9c84aa8e31a216e80d84c7345eb92c385d0771", "pdf_pages": 42, "source_locator": "Printed pp.1175–1178, Theorem 1.1 and Corollary 1.2", "historical_role": "Automorphic cubic moments and central-value positivity", "main_result": "For real primitive χ of odd square-free conductor q and even weight k≥12 with matching parity, cubic averaging over primitive forms of levels dividing q is ≪q^{1+ε}; positivity gives q^{1/3+ε} for an individual central value.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "arxiv": "math/9810182", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-CI2000CUBIC"]}','The cubic moment of central values of automorphic L-functions','["J. B. Conrey", "H. Iwaniec"]',NULL,'2000',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv v2 (1 May 2000), published Annals pagination','https://arxiv.org/pdf/math/9810182v2','f307b36f600b786b926020931f9c84aa8e31a216e80d84c7345eb92c385d0771','papers/classical63_lfunctions_notes.md','papers/classical63_lfunctions_records.jsonl');
