INSERT INTO "papers" VALUES('PAPER-LF63-CG2001HIGH','corpus/bibliography.jsonl',316,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-CG2001HIGH", "title": "High moments of the Riemann zeta-function", "authors": ["J. B. Conrey", "S. M. Gonek"], "year": 2001, "venue": "Duke Mathematical Journal 107(3), 577–604", "language": "English", "doi": "10.1215/S0012-7094-01-10737-0", "arxiv_id": "math/9902162", "canonical_url": "https://doi.org/10.1215/S0012-7094-01-10737-0", "publication_status": "published", "version": "author arXiv v1 (1 February 1999)", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read the introduction, long-polynomial motivation, and sixth- and eighth-moment conjectural constants.", "source_path": "sources/classical63_lfunctions/cg2001.pdf", "source_url": "https://arxiv.org/pdf/math/9902162v1", "source_sha256": "181ac17b1c8efc84ef9597328f2fd06a1e46545e2f4564e6475de691eb901880", "pdf_pages": 27, "source_locator": "arXiv introduction and Conjecture 1", "historical_role": "Additive divisor conjectures and moments", "main_result": "Long-polynomial heuristic recovers the sixth-moment constant and proposes the eighth-moment constant, with combinatorial numerator 24024.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "arxiv": "math/9902162", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-CG2001HIGH"]}','High moments of the Riemann zeta-function','["J. B. Conrey", "S. M. Gonek"]',NULL,'2001',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv v1 (1 February 1999)','https://arxiv.org/pdf/math/9902162v1','181ac17b1c8efc84ef9597328f2fd06a1e46545e2f4