INSERT INTO "papers" VALUES('PAPER-LF63-CI2002SPACING','corpus/bibliography.jsonl',317,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-CI2002SPACING", "title": "Spacing of zeros of Hecke L-functions and the class number problem", "authors": ["J. B. Conrey", "H. Iwaniec"], "year": 2002, "venue": "Acta Arithmetica 103(3), 259–312", "language": "English", "doi": "10.4064/aa103-3-5", "arxiv_id": "math/0111012", "canonical_url": "https://doi.org/10.4064/aa103-3-5", "publication_status": "published", "version": "author arXiv v1 (1 November 2001)", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read the on-line zero-count convention including repeated nearest ordinates at multiple zeros, and the two gap hypotheses.", "source_path": "sources/classical63_lfunctions/ci2002.pdf", "source_url": "https://arxiv.org/pdf/math/0111012v1", "source_sha256": "779286b3fcffdec64b8b401c09a20a5a5240356100d84c7ff575f0f24f88aea5", "pdf_pages": 61, "source_locator": "arXiv pp.5–7, Theorems 1.1–1.2", "historical_role": "Small gaps and effective class-number bounds", "main_result": "An explicitly frequent small-spacing condition on critical-line zeros gives an effective lower bound on L(1,χ). Theorems 1.1–1.2 make distinct Hecke- and zeta-gap hypotheses.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "arxiv": "math/0111012", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-CI2002SPACING"]}','Spacing of zeros of Hecke L-functions and the class number problem','["J. B. Conrey", "H. Iwaniec"]',NULL,'2002',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv v1 (1 November 2001)','ht