INSERT INTO "papers" VALUES('PAPER-LF63-KMV2002','corpus/bibliography.jsonl',318,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-KMV2002", "title": "Rankin-Selberg L-functions in the level aspect", "authors": ["Emmanuel Kowalski", "Philippe Michel", "Jeffrey VanderKam"], "year": 2002, "venue": "Duke Mathematical Journal 114(1), 123–191", "language": "English", "doi": "10.1215/S0012-7094-02-11416-1", "arxiv_id": null, "canonical_url": "https://doi.org/10.1215/S0012-7094-02-11416-1", "publication_status": "published", "version": "author-hosted article manuscript", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read the family setup, fixed form conditions and level-aspect subconvex bound.", "source_path": "sources/classical63_lfunctions/kmv2002.pdf", "source_url": "https://people.math.ethz.ch/~kowalski/rankin-selberg.pdf", "source_sha256": "a210eaeb0bff7f40981518b0671cb38dd3d58e10e1e4b361a0d15d774bfa83ea", "pdf_pages": 50, "source_locator": "Manuscript pp.1–2, Theorem 1.1", "historical_role": "Rankin–Selberg family moments and level-aspect subconvexity", "main_result": "Theorem 1.1 breaks the q^{1/2} convexity level exponent by 1/80 for L(f⊗g,1/2+it) and derivatives, with specified good-prime and fixed-g conditions.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-KMV2002"]}','Rankin-Selberg L-functions in the level aspect','["Emmanuel Kowalski", "Philippe Michel", "Jeffrey VanderKam"]',NULL,'2002',0,0,'selected_checkpoint_priority_work','full_text_accessed','author-hosted article manuscript','https://people.math.e