INSERT INTO "papers" VALUES('PAPER-LF63-WATSON2002','corpus/bibliography.jsonl',319,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-WATSON2002", "title": "Rankin Triple Products and Quantum Chaos", "authors": ["Thomas C. Watson"], "year": 2002, "venue": "Princeton University PhD dissertation, June 2002; author revision 22 October 2008", "language": "English", "doi": null, "arxiv_id": "0810.0425", "canonical_url": "https://arxiv.org/abs/0810.0425", "publication_status": "dissertation", "version": "author dissertation revision arXiv v3 (22 October 2008)", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read the title and abstract, then the explicit triple-product identity and proof opening in §4.1.", "source_path": "sources/classical63_lfunctions/watson2008.pdf", "source_url": "https://arxiv.org/pdf/0810.0425v3", "source_sha256": "3e6e9e2046b56f563c36d3f1a5a1a3d02ba70346229c20f56c5e1231441de1e9", "pdf_pages": 66, "source_locator": "Abstract and §4.1, Theorem 3, printed p.51", "historical_role": "Automorphic triple periods and central Rankin values", "main_result": "For matched newforms of common square-free level, relates the squared normalized triple period to a completed central triple-product L-value, adjoint L-values, and local factors; the thesis describes the resulting route from subconvexity to arithmetic QUE.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "version_date": "2008-10-22", "arxiv": "0810.0425", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-WATSON2002"]}','Rankin Triple Products and Quantum Chaos','["Thomas C. Watson"]',NULL,'2002',0,0,'selected_checkpoi