INSERT INTO "papers" VALUES('PAPER-LF63-CRS2006','corpus/bibliography.jsonl',322,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-CRS2006", "title": "Moments of the Derivative of Characteristic Polynomials with an Application to the Riemann Zeta Function", "authors": ["J. B. Conrey", "M. O. Rubinstein", "N. C. Snaith"], "year": 2006, "venue": "Communications in Mathematical Physics 267(3), 611–629", "language": "English", "doi": "10.1007/s00220-006-0090-5", "arxiv_id": "math/0508378", "canonical_url": "https://doi.org/10.1007/s00220-006-0090-5", "publication_status": "published", "version": "author arXiv v2 (17 March 2006), PDF title matches journal", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read the setup distinguishing the characteristic polynomial and its real normalization, and statements of Theorems 1–3 and Conjecture 1.", "source_path": "sources/classical63_lfunctions/crs2006.pdf", "source_url": "https://arxiv.org/pdf/math/0508378v2", "source_sha256": "f5cb98905c1f38de0d1640cf7ddf17b51b4e73ef9c70396e4913929f4e2a137d", "pdf_pages": 19, "source_locator": "Author manuscript Theorems 1–3 and Conjecture 1", "historical_role": "Continuous derivative moment model at fixed angles", "main_result": "Haar unitary derivative moment asymptotics are theorems; the zeta derivative moment analogue on the critical line is conjectural.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "edition_note": "The arXiv landing page displays a different title. The v2 PDF title and journal title agree.", "arxiv": "math/0508378", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-CRS2006"]}','Moments of the Derivative of Characteristic Polynomials with an Application to the Riemann Zeta Function','["J. B. Conrey", "M. O. Rubinstein", "N. C. Snaith"]',NULL,'2006',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv v2 (17 March 2006), PDF title matches journal','https://arxiv.org/pdf/math/0508378v2','f5cb98905c1f38de0d1640cf7ddf17b51b4e73ef9c70396e4913929f4e2a137d','papers/classical63_lfunctions_notes.md','papers/classical63_lfunctions_records.jsonl');
