INSERT INTO "papers" VALUES('PAPER-LF63-BCY2011','corpus/bibliography.jsonl',325,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-BCY2011", "title": "More than 41% of the zeros of the zeta function are on the critical line", "authors": ["H. M. Bui", "Brian Conrey", "Matthew P. Young"], "year": 2011, "venue": "Acta Arithmetica 150(1), 35–64", "language": "English", "doi": "10.4064/aa150-1-3", "arxiv_id": "1002.4127", "canonical_url": "https://doi.org/10.4064/aa150-1-3", "publication_status": "published", "version": "original journal PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read the published introductory statement, setup and parameter choices. Compared the corresponding earlier and revised arXiv passages.", "source_path": "sources/classical63_lfunctions/bcy2011print.pdf", "source_url": "https://www.impan.pl/shop/en/publication/transaction/download/product/83077?download.pdf", "source_sha256": "dfd0c31ed900bf0cabf1aa2988747f2a05b1afed8a7ab28a0cbb35ff9d754cc3", "pdf_pages": 30, "source_locator": "Published Theorem 1.1 and §§2.1–2.2; preprints v1 and v2 §2.1", "historical_role": "Unconditional critical and simple-critical zeta proportions", "main_result": "The printed theorem gives κ≥0.4105 and κ*≥0.4058 with two-piece mollification.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "additional_manifestations": [{"source_path": "sources/classical63_lfunctions/bcy2011v1.pdf", "source_url": "https://arxiv.org/pdf/1002.4127v1", "source_sha256": "9c2d37ca72d0588bdec8962254d3d0a72f457d625deeb3e5fcfa2ce26e7f7b85", "pdf_pages": 23, "version": "arXiv v1 (22 February 2010)"}, {"source_path": "sources/classical63_lfunctions/bcy2011.pdf", "source_url": "https://arxiv.org/pdf/1002.4127v2", "source_sha25