INSERT INTO "papers" VALUES('PAPER-LF63-CIS2013CRIT','corpus/bibliography.jsonl',327,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-CIS2013CRIT", "title": "Critical zeros of Dirichlet L-functions", "authors": ["J. B. Conrey", "H. Iwaniec", "K. Soundararajan"], "year": 2013, "venue": "Journal für die reine und angewandte Mathematik 681, 175–198", "language": "English", "doi": "10.1515/crelle-2012-0032", "arxiv_id": "1105.1177", "canonical_url": "https://doi.org/10.1515/crelle-2012-0032", "publication_status": "published", "version": "author arXiv v1 (5 May 2011); journal issue dated 2013", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read the family smoothing weights, height range and exact definition of simple critical zeros.", "source_path": "sources/classical63_lfunctions/cis2012.pdf", "source_url": "https://arxiv.org/pdf/1105.1177v1", "source_sha256": "6366374afd7fd16e12cfac0deec25b6d4faa253d49febff30b7e0763d6d7360b", "pdf_pages": 23, "source_locator": "arXiv pp.1–3, definitions (1.4) and Theorem 1", "historical_role": "Simple critical zeros of Dirichlet L-functions on average", "main_result": "Theorem 1 gives at least 14/25 simple critical zeros in the weighted primitive-character family for (log Q)^6≤T≤(log Q)^A, with fixed A≥6 and Q sufficiently large.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "arxiv": "1105.1177", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-CIS2013CRIT"]}','Critical zeros of Dirichlet L-functions','["J. B. Conrey", "H. Iwaniec", "K. Soundararajan"]',NULL,'2013',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv v