INSERT INTO "papers" VALUES('PAPER-LF63-BUIHB2013','corpus/bibliography.jsonl',328,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-BUIHB2013", "title": "On simple zeros of the Riemann zeta-function", "authors": ["H. M. Bui", "D. R. Heath-Brown"], "year": 2013, "venue": "Bulletin of the London Mathematical Society 45(5), 953–961", "language": "English", "doi": "10.1112/blms/bdt026", "arxiv_id": "1302.5018", "canonical_url": "https://doi.org/10.1112/blms/bdt026", "publication_status": "published", "version": "author arXiv v1 (20 February 2013)", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Read the statement, relation to CGG, and the setup and identification of the replacement arithmetic tool.", "source_path": "sources/classical63_lfunctions/buihb2013.pdf", "source_url": "https://arxiv.org/pdf/1302.5018v1", "source_sha256": "b1c5a4d6cdba59d0fc552a18cb2465c442a8534be0c4e51a23db126316f83077", "pdf_pages": 10, "source_locator": "arXiv pp.1–2, theorem and corollary; §3 Lemma 3", "historical_role": "RH-conditional simple zeros without the CGG moment assumption", "main_result": "Under RH, at least 19/27 of zeta zeros are simple, and at least 0.84665 are distinct. Heath-Brown’s generalized Vaughan identity replaces the step that required GLH in CGG 1998.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "arxiv": "1302.5018", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LF63-BUIHB2013"]}','On simple zeros of the Riemann zeta-function','["H. M. Bui", "D. R. Heath-Brown"]',NULL,'2013',0,0,'selected_checkpoint_priority_work','full_text_accessed','author arXiv v1 (20 February 2013)','http