INSERT INTO "papers" VALUES('PAPER-LF63-MN2014','corpus/bibliography.jsonl',329,'full_text_accessed','papers/classical63_lfunctions_notes.md','{"id": "PAPER-LF63-MN2014", "title": "Lower Bounds for Moments of ζ′(ρ)", "authors": ["Micah B. Milinovich", "Nathan Ng"], "year": 2014, "venue": "International Mathematics Research Notices 2014(12), 3190–3216", "language": "English", "doi": "10.1093/imrn/rnt028", "arxiv_id": "0706.2321", "canonical_url": "https://doi.org/10.1093/imrn/rnt028", "publication_status": "published", "version": "revised author-hosted manuscript, journal date verified separately", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Compared the statement in the June 2007 draft, revised author manuscript and 2014 journal metadata.", "source_path": "sources/classical63_lfunctions/mn2014final.pdf", "source_url": "https://home.olemiss.edu/~mbmilino/Lower_Bounds.pdf", "source_sha256": "58f385d3fcb50c725bc0541e1e0d41e00e9f5f61cd869e314eb6ce08b7884e09", "pdf_pages": 19, "source_locator": "Revised manuscript pp.1–2, Theorem 1.1", "historical_role": "Lower bounds for positive integer derivative moments at zeros", "main_result": "On GRH for Dirichlet L-functions, J_k(T)≫_k(log T)^{k(k+2)} for positive integers k.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_lfunctions_notes.md", "track_file": "papers/classical63_lfunctions_records.jsonl", "additional_manifestations": [{"source_path": "sources/classical63_lfunctions/mn2014.pdf", "source_url": "https://www.cs.uleth.ca/~nathanng/RESEARCH/lwrboundspre.pdf", "source_sha256": "0993ad47a839375aeecfad2d61a39dff69a5ba68553085168931bb8f74baff06", "pdf_pages": 7, "version": "earlier June 2007 author manuscript"}], "correction_history": "Earlier author and arXiv draft used an RH formulation. Revised manuscript and publisher abstract explicitly assume GRH for Dirichlet