INSERT INTO "papers" VALUES('PAPER-CLASS63-HUXLEY1975','corpus/bibliography.jsonl',350,'full_text_accessed','papers/classical63_notes.md','{"id": "PAPER-CLASS63-HUXLEY1975", "title": "Large values of Dirichlet polynomials, III", "authors": ["M. N. Huxley"], "year": 1975, "venue": "Acta Arithmetica 26(4), 435–444", "language": "English", "doi": "10.4064/aa-26-4-435-444", "canonical_url": "https://doi.org/10.4064/aa-26-4-435-444", "source_url": "https://matwbn.icm.edu.pl/ksiazki/aa/aa26/aa2648.pdf", "publication_status": "published", "version": "original publication, digitized scan", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "full_text_access": "complete original issue or article PDF checked", "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "read_scope": "Read all ten printed pages, §§1–5 and errata, in the original journal scan. Checked the theorem statement and followed the product and subdivision argument; Part I external detector estimates were not re-derived.", "source_path": "sources/prefix_formula62_classical2/hux1975.pdf", "source_sha256": "cc8b7282c1963687d357829416d5e471e130810e5324709a96319bb7a2a3428f", "pdf_pages": 6, "source_locator": "Printed pp.435–444, especially pp.436–439, equations (2.1)–(2.35); errata on p.444", "historical_role": "Large values and hybrid density", "main_result": "For primitive characters with q≤Q divisible by q₀, gives a density exponent 12(1−σ)/5+ε on Q²T/q₀. The zeta-only statement gives the density-hypothesis exponent at σ>4/5.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_notes.md", "track_file": "papers/classical63_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-CLASS63-HUXLEY1975"]}','Large values of Dirichlet polynomials, III','["M. N. Huxley"]',NULL,'1975',1,1,'selected_chec