INSERT INTO "papers" VALUES('PAPER-CLASS63-JUTILA1977','corpus/bibliography.jsonl',352,'full_text_accessed','papers/classical63_notes.md','{"id": "PAPER-CLASS63-JUTILA1977", "title": "Zero-density estimates for L-functions", "authors": ["Matti Jutila"], "year": 1977, "venue": "Acta Arithmetica 32(1), 55–62", "language": "English", "doi": "10.4064/aa-32-1-55-62", "canonical_url": "https://doi.org/10.4064/aa-32-1-55-62", "source_url": "https://matwbn.icm.edu.pl/ksiazki/aa/aa32/aa3216.pdf", "publication_status": "published", "version": "original publication, digitized scan", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "full_text_access": "complete original issue or article PDF checked", "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "read_scope": "Read all eight printed pages, §§1–5 and the appendix. Checked ranges, bases and the algebra for the zeta threshold. The printed proof itself sketches the detector reduction and invokes external fourth-moment estimates.", "source_path": "sources/prefix_formula62_classical2/jut1977.pdf", "source_sha256": "cbe2d1e7115717cf28f9ffaffdc1fe232958595b17c5c2ee59fc968e8ff0d5a1", "pdf_pages": 5, "source_locator": "Printed pp.55–62, especially equations (1.1)–(1.8) and pp.57–61 for lemmas and proof", "historical_role": "Fourth moments, large values, and zero density", "main_result": "For all characters of one modulus and the primitive family on the qT and Q²T scales respectively, obtains the density-hypothesis exponent at α≥21/26. The alternate Q²T² primitive-family scale has threshold 7/9, and the zeta-only result has threshold 11/14.", "accessed_at": "2026-11-17", "record_path": "papers/classical63_notes.md", "track_file": "papers/classical63_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-CLASS63-JUTILA1977"]}','Zero-density estimates for L-functions','["Matti Jutila"]',NULL,'1977',1,1,'selected_checkpoint_priority_work','full_text_accessed','original publication, digitized scan','https://matwbn.icm.edu.pl/ksiazki/aa/aa32/aa3216.pdf','cbe2d1e7115717cf28f9ffaffdc1fe232958595b17c5c2ee59fc968e8ff0d5a1','papers/classical63_notes.md','papers/classical63_records.jsonl');
