INSERT INTO "papers" VALUES('PAPER-DAN63-ANDERS-NOTES','corpus/bibliography.jsonl',393,'full_text_accessed','papers/density63_analytic_dependencies_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-17", "area": "universality", "arxiv_id": "2312.04255", "audit_level": 0, "authors": ["Johan Andersson", "Ramūnas Garunkštis", "Roma Kačinskaitė", "Keita Nakai", "Łukasz Pańkowski", "Athanasios Sourmelidis", "Rasa Steuding", "Jörn Steuding", "Saeree Wananiyakul"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2312.04255", "dependency_note": "Andersson (3) cites the published Bourgain–Watt perturbed-cones paper (reference [4], DOI 10.1093/imrn/rnx009). Its arXiv counterpart 1505.04161v1, §13 Theorem 3, states the exact 1273/4053+ε input for all ε>0. A separately titled, withdrawn sequel (1709.04340) attempts an improvement and is a distinct work.", "dependency_receipt": "sources/analytic64_statistics/bw_perturbed.pdf", "dependency_status": "Cited mean-square statement verified in pinned primary source", "doi": "10.1007/s10986-024-09631-5", "full_text_accessed": true, "journal_counterpart": {"doi": "10.1007/s10986-024-09631-5", "venue": "Lithuanian Mathematical Journal", "year": 2024}, "language": "English", "main_result": "Theorem 1 states short-interval universality on [T,T+H] for T^(1273/4053)≤H≤T using the Bourgain–Watt mean-square estimate (3). It also considers exponentially growing shifts.", "novelty_claim": false, "paper_id": "PAPER-DAN63-ANDERS-NOTES", "pdf_pages": 14, "publication_receipt": "sources/density63_analytic_dependencies/crossref_receipts.json", "publication_status": "Journal counterpart verified through Crossref. Mathematical reading used pinned arXiv PDF.", "read_scope": "Targeted passage only. Abstract and §1 Theorem 1", "record_path": "papers/density63_analytic_dependencies_notes.md", "selection_reason": "Records the admissible sets, approximation targets or shift regimes in a universality argument.", "source_locator": "Abstract and §1 Theorem 1", "source_path": "sources/density63_analytic_dependencies/anders_notes.pdf", "source_sha256": "7853c3c4ed2865470e2d3485c4263d1edb455d411a54f9ac175859c865e42a12", "source_url": "https://arxiv.org/pdf/2312.04255v2", "substantive_reading": false, "title": "Notes on Universality in Short Intervals and Exponential Shifts", "track_file": "papers/density63_analytic_dependencies_records.jsonl", "venue": "arXiv", "version": "arXiv:2312.04255v2", "version_date": "2023-12-08", "version_receipt": "sources/density63_analytic_dependencies/anders_notes.html", "whole_work_read": false, "year": 2023, "id": "PAPER-DAN63-ANDERS-NOTES", "arxiv": "2312.04255", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-DAN63-ANDERS-NOTES"]}','Notes on Universality in Short Intervals and Exponential Shifts','["Johan Andersson", "Ramūnas Garunkštis", "Roma Kačinskaitė", "Keita Nakai", "Łukasz Pańkowski", "Athanasios Sourmelidis", "Rasa Steuding", "Jörn Steuding", "Saeree Wananiyakul"]',NULL,'2023',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2312.04255v2','https://arxiv.org/pdf/2312.04255v2','7853c3c4ed2865470e2d3485c4263d1edb455d411a54f9ac175859c865e42a12','papers/density63_analytic_dependencies_notes.md','papers/density63_analytic_dependencies_records.jsonl');
