INSERT INTO "papers" VALUES('PAPER-GEN63-BALAZARD','corpus/bibliography.jsonl',399,'full_text_accessed','papers/density63_generator_antecedents.md','{"paper_id": "PAPER-GEN63-BALAZARD", "title": "An Arithmetical Function Related to Báez-Duarte’s Criterion for the Riemann Hypothesis", "authors": ["Michel Balazard"], "year": 2021, "venue": "Harmonic Analysis and Applications, Springer Optimization and Its Applications 168, 43–58", "doi": "10.1007/978-3-030-61887-2_3", "arxiv_id": "1812.04309", "arxiv_doi": "10.48550/arXiv.1812.04309", "publication_status": "Published book chapter counterpart verified. Mathematical reading used the preprint.", "online_publication_date": "2020-10-13", "canonical_url": "https://doi.org/10.1007/978-3-030-61887-2_3", "version": "arXiv:1812.04309v1", "version_date": "2018-12-11", "source_edition": "Pinned arXiv v1 PDF", "version_receipt": "sources/jump_generator63_antecedents/balazard_1812.04309.arxiv.html", "publication_receipt": "sources/jump_generator63_antecedents/balazard_1812.04309.doi.json", "version_note": "The source hash and proposition locators refer to arXiv v1, not the Springer chapter. The DOI and chapter metadata were checked, while a full text comparison was outside scope.", "source_url": "https://arxiv.org/pdf/1812.04309v1", "source_path": "sources/jump_generator63_antecedents/balazard_1812.04309.pdf", "source_sha256": "c1fd5a199948318c4d24d06f1c2d74dad76acb394c368713484ed2c2a90ab466", "pages": 13, "audit_scope": "Targeted §1 definitions, §§2–3 coefficient and Mellin passages, §4 Propositions 10–11 and proof of (11), §5 Propositions 12–13, and §6 Question 2. No full read or chapter-version comparison.", "statement_locator": "§1; Propositions 4, 7–8, 10–13; §4 (11); §6 Question 2", "scoped_statement": "D₀ is the integer-cell step space and the closed natural Beurling span is all of D₀ under RH. For an element of that span the successive-jump Dirichlet series divided by ζ is holomorphic on Re s>1/2, by passage of every vanishing zero jet below its multiplicity to the norm limit. Möbius inversion gives continuous fixed coefficient functionals.", "selection_reason": "Exact primary antecedent to the discrete all-multiplicity obstruction and projection-coordinate method. Substituting the logarithmic jump target and obtaining the η′ quotient is the separate archive deduction.", "bibliographic_verified": true, "access_date": "2026-11-17", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "access_status": "full_text_accessed", "record_path": "papers/density63_generator_antecedents.md", "audit_path": "audits/adversarial_reviews/jump_generator63_antecedents.md", "source_hash_manifest": "sources/jump_generator63_antecedents/SHA256SUMS", "novelty_claim": false, "id": "PAPER-GEN63-BALAZARD", "arxiv": "1812.04309", "read_scope": "Targeted §1 definitions, §§2–3 coefficient and Mellin passages, §4 Propositions 10–11 and proof of (11), §5 Propositions 12–13, and §6 Question 2. No full read or chapter-version comparison.", "original_access_status": "full_primary_text_accessed_targeted_portions_read", "track_file": "papers/density63_generator_antecedents_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEN63-BALAZARD"]}','An Arithmetical Function Related to Báez-Duarte’s Criterion for the Riemann Hypothesis','["Michel Balazard"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1812.04309v1','https://arxiv.org/pdf/1812.04309v1','c1fd5a199948318c4d24d06f1c2d74dad76acb394c368713484ed2c2a90ab466','papers/density63_generator_antecedents.md','papers/density63_generator_antecedents_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEN63-BOBER','corpus/bibliography.jsonl',400,'full_text_accessed','papers/density63_generator_antecedents.md','{"paper_id": "PAPER-GEN63-BOBER", "title": "Factorial ratios, hypergeometric series, and a family of step functions", "authors": ["Jonathan W. Bober"], "year": 2009, "venue": "Journal of the London Mathematical Society 79(2), 422–444", "doi": "10.1112/jlms/jdn078", "arxiv_id": "0709.1977", "arxiv_doi": "10.48550/arXiv.0709.1977", "publication_status": "Published journal counterpart verified. Mathematical reading used the preprint.", "online_publication_date": "2009-02-13", "canonical_url": "https://doi.org/10.1112/jlms/jdn078", "version": "arXiv:0709.1977v1", "version_date": "2007-09-13", "source_edition": "Pinned arXiv v1 PDF", "version_receipt": "sources/jump_generator63_antecedents/bober_0709.1977.arxiv.html", "publication_receipt": "sources/jump_generator63_antecedents/bober_0709.1977.doi.json", "version_note": "The DOI is the Journal of the London Mathematical Society publication. The source hash and formula numbers refer to v1; later manuscript and journal changes were not compared.", "source_url": "https://arxiv.org/pdf/0709.1977v1", "source_path": "sources/jump_generator63_antecedents/bober_0709.1977.pdf", "source_sha256": "5f3cb3b1e7f74b791608669ce22a6d07ab51faac68436d806c9b329c9abf3201", "pages": 23, "audit_scope": "Targeted Theorem 1.1 (2), Theorem 1.2 (7), §1.1 balanced floor formulation, and the §3 Landau link around Theorem 3.1. The classification proof and hypergeometric analysis were outside scope.", "statement_locator": "Theorems 1.1–1.2, equations (2) and (7), §§1.1 and 3", "scoped_statement": "At a=b=1, (2) is the parity seed floor(x)−2 floor(x/2) and (7) is the central binomial coefficient. §1.1 identifies the balanced floor class used in the integer Nyman–Beurling problem.", "selection_reason": "Exact parity seed and central factorial family occurring in the explicit k=2 target. The source statements concern the seed and integer factorial ratios.", "bibliographic_verified": true, "access_date": "2026-11-17", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "access_status": "full_text_accessed", "record_path": "papers/density63_generator_antecedents.md", "audit_path": "audits/adversarial_reviews/jump_generator63_antecedents.md", "source_hash_manifest": "sources/jump_generator63_antecedents/SHA256SUMS", "novelty_claim": false, "id": "PAPER-GEN63-BOBER", "arxiv": "0709.1977", "read_scope": "Targeted Theorem 1.1 (2), Theorem 1.2 (7), §1.1 balanced floor formulation, and the §3 Landau link around Theorem 3.1. The classification proof and hypergeometric analysis were outside scope.", "original_access_status": "full_primary_text_accessed_targeted_portions_read", "track_file": "papers/density63_generator_antecedents_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEN63-BOBER"]}','Factorial ratios, hypergeometric series, and a family of step functions','["Jonathan W. Bober"]',NULL,'2009',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:0709.1977v1','https://arxiv.org/pdf/0709.1977v1','5f3cb3b1e7f74b791608669ce22a6d07ab51faac68436d806c9b329c9abf3201','papers/density63_generator_antecedents.md','papers/density63_generator_antecedents_records.jsonl');
