INSERT INTO "papers" VALUES('PAPER-C106','corpus/bibliography.jsonl',451,'full_text_accessed','papers/PAPER-C106.md','{"id": "PAPER-C106", "title": "A closure problem related to the Riemann zeta-function", "authors": ["Arne Beurling"], "date": "1955-05-15", "year": 1955, "venue": "Proceedings of the National Academy of Sciences of the United States of America41(5),312–314", "publication_status": "published_original_facsimile_read", "doi": "10.1073/pnas.41.5.312", "arxiv": null, "source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC528084/", "version": "original published pages312–314; communicated byHermanWeyl14March1955", "family": ["C", "D", "F"], "audit_level": 1, "whole_work_read": true, "inspected_portions_level": 2, "read_scope": "Complete article text on official scanned pages312–314 read visually. Dilation, Mellin, Hölder, support-propagation and duality steps reconstructed. Cited1953character theorem read separately. Canonical-factorization dependency not reproved from1922 source.", "access_status": "full_text_accessed", "available_formats": ["official_PNG_page_facsimiles", "local_OCR_for_search_only"], "source_files": ["sources/foundations_round2/beurling-p312.png", "sources/foundations_round2/beurling-p313.png", "sources/foundations_round2/beurling-p314.png"], "source_sha256": "b0f7f09d1f217d05c02ec91671921a99f6a623f1f370abbe5ff15b610d8e5813", "source_hash_method": "SHA256 of ordered concatenation of officialPNG pages312,313,314; individualhashes in retrieval manifest", "accessed_at": "2026-11-17", "main_result": "For each1<p<infinity, letC consist of finiteΣcν{θν/x},0<θν≤1,Σcνθν=0. ThenC is denseL^p(0,1) iffζ has nozero inRe(s)>1/p. The p=2case isRH; continuous dilations are essential to the stated theorem.", "proof_architecture": ["Compressed dilation invariance reducesdensity to approximating1", "Constrained Mellin identity cancels the pole term", "Hölder proves approximation⇒zero-freehalfplane", "Non-density givesdualannihilator", "Dyadic fractional-part tests excludeinitialsupportgap", "1953 weaker-topologycharacter theorem providesx^λ in allL^rclosuresr<p′", "Bounded Ctests preserveannihilation inweakerclosure", "Mellin identity forceszeroRe(s)>1/p"], "limitations": ["Endpointsp=1,infinity excluded.", "No reciprocal-integer restriction or prescribedcoefficients inoriginaltheorem.", "Character theorem does notpromise membership intheoriginaldualnormclosure.", "Detailed canonicalfactorization dependency remains external; no exhaustivecorrectionsearch."], "research_questions": ["Reconstruct the semigroup character step inmodernbounded-typefactorization language.", "Which unbounded testclasses retain annihilation under weaker L^r convergence?"], "correction_search_status": "primary identity checked; exhaustive latercorrectionsearch incomplete", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-C106.md", "track_file": "papers/foundations_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-C106"]}','A closure problem related to the Riemann zeta-function','["Arne Beurling"]','["C", "D", "F"]','1955',1,1,'selected_checkpoint_priority_work','full_text_accessed','original published pages312–314; communicated byHermanWeyl14March1955','https://pmc.ncbi.nlm.nih.gov/articles/PMC528084/','b0f7f09d1f217d05c02ec91671921a99f6a623f1f370abbe5ff15b610d8e5813','papers/PAPER-C106.md','papers/foundations_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-C107','corpus/bibliography.jsonl',452,'full_text_accessed','papers/PAPER-C107.md','{"id": "PAPER-C107", "title": "A theorem on functions defined on a semi-group", "authors": ["Arne Beurling"], "date": "1953-12-01", "year": 1953, "venue": "Mathematica Scandinavica1,127–130", "publication_status": "published_original_facsimile_read", "doi": "10.7146/math.scand.a-10372", "arxiv": null, "source_url": "https://journals.msp.org/mscand/article/download/2951/2950", "version": "original published four-page scan; received16March1953", "family": ["D", "F", "H"], "audit_level": 1, "whole_work_read": true, "inspected_portions_level": 2, "read_scope": "All four pages127–130 read as renderedimages. MainTheoremI proofarchitecture and Mellin/Fubini/pole and entire-function cases reconstructed; Nevanlinna canonicaldecomposition checked as identifiedexternalstandard input, not independentlyprovedfrom1922source. Finaladditive-semigroupremarks read but not independentlyreconstructed.", "access_status": "full_text_accessed", "available_formats": ["PDF_scanned", "local_OCR_for_search_only"], "source_file": "sources/foundations_round2/beurling1953.pdf", "source_sha256": "bc34c9ed892049d0190ca3cab53600a6b003164485d9aaea28f681e640af53f8", "accessed_at": "2026-11-17", "main_result": "TheoremI p128: for f∈L^P(0,1),1<P<infinity, with noinitialsupportgap, theintersection of allL^rclosuresr<P of its dilationorbit, intersectedwithL^P, contains x^(−λ) for someReλ<1/P. It neednotcontain suchacharacter intheoriginalL^Pclosure.", "proof_architecture": ["Annihilatorduality for weakerL^rclosures", "Mellin factorizationG=KF inoverlapstrip1/P<Re(s)<1/r byFubini", "Meromorphic continuation ofF=G/K", "Subunitboundary-growthexponent excludespoles onRe(s)=1/P", "Any leftpole supplies commoncharacterannihilatorzeros", "IfFentire,Nevanlinnadecomposition boundsgrowth by anexponentialat infinity", "Liouville,orrescalingafterexponentialfactor,forcesinitialsupportgapcontradiction"], "limitations": ["Strictweakeningr<P is partofthetheorem; anoriginalnormclosureversionis explicitlyreportedfalse.", "Canonicaldecomposition uses F.andR.Nevanlinna1922; thatsourcewasnotread.", "Reportedcounterexamples intheoriginaltopologywere not independentlyreconstructedfrom1949orNyman1950.", "MetadataaggregatorsmaymisassignHelson ascoauthor; actualarticlehasBeurlingalone."], "research_questions": ["Make thesingularfactoratinfinity explicit in modernMellin–Hardy language.", "Determineuniformcontrols neededtopassfromallweakerLp norms toanendpointnorm."], "correction_search_status": "publisheridentity and actualsole-authorarticleverified; exhaustivecorrectionsearch incomplete", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-C107.md", "track_file": "papers/foundations_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-C107"]}','A theorem on functions defined on a semi-group','["Arne Beurling"]','["D", "F", "H"]','1953',1,1,'selected_checkpoint_priority_work','full_text_accessed','original published four-page scan; received16March1953','https://journals.msp.org/mscand/article/download/2951/2950','bc34c9ed892049d0190ca3cab53600a6b003164485d9aaea28f681e640af53f8','papers/PAPER-C107.md','papers/foundations_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-EULER1744','corpus/bibliography.jsonl',453,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-EULER1744", "title": "Variae observationes circa series infinitas", "authors": ["Leonhard Euler"], "year": 1744, "venue": "Commentarii academiae scientiarum Petropolitanae 9, 160–188", "language": "Latin", "doi": null, "arxiv_id": null, "canonical_url": "https://scholarlycommons.pacific.edu/cgi/viewcontent.cgi?article=1071&context=euler-works", "publication_status": "published", "version": "original 1744 Latin publication scan with Euler Archive cover sheet", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorems 7–8, printed pp. 172–176.", "source_path": "sources/geometry64_historical_sources/euler1744.pdf", "source_url": "https://scholarlycommons.pacific.edu/cgi/viewcontent.cgi?article=1071&context=euler-works", "effective_source_url": "https://scholarlycommons.pacific.edu/cgi/viewcontent.cgi?article=1071&context=euler-works", "source_sha256": "3dd438f988674616afd0a75387805245ecaa51770396f250e0f372dc969abf38", "pdf_pages": 30, "accessed_at": "2026-11-18", "source_locator": "Theorems 7–8, printed pp. 172–176", "main_result": "Derives the multiplicative prime-product identity for reciprocal power sums and the divergence of the sum of reciprocals of primes.", "classical_zeta_transfer_obstacle": "The product is obtained in the region of convergence or via positive partial products. Its existence gives no zero exclusion inside the critical strip.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_prio