INSERT INTO "papers" VALUES('PAPER-HIST64-DIRICHLET1837','corpus/bibliography.jsonl',454,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-DIRICHLET1837", "title": "Beweis des Satzes, daß jede unbegrenzte arithmetische Progression, deren erstes Glied und Differenz ganze Zahlen ohne gemeinschaftlichen Factor sind, unendlich viele Primzahlen enthält", "authors": ["Peter Gustav Lejeune Dirichlet"], "year": 1837, "venue": "Abhandlungen der Königlich Preussischen Akademie der Wissenschaften, 45–71", "language": "German", "doi": null, "arxiv_id": null, "canonical_url": "https://sites.math.rutgers.edu/~alexk/2022S572/Dirichlet1837.pdf", "publication_status": "published", "version": "original journal reproduction hosted by Rutgers, with library cover", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at pp. 45–46, and the conclusion on pp. 69–71.", "source_path": "sources/geometry64_historical_sources/dirichlet1837.pdf", "source_url": "https://sites.math.rutgers.edu/~alexk/2022S572/Dirichlet1837.pdf", "effective_source_url": "https://sites.math.rutgers.edu/~alexk/2022S572/Dirichlet1837.pdf", "source_sha256": "28e84740e81f6beeed5bad5553571dba9eeb86f95c82005a192b68278326f60f", "pdf_pages": 28, "accessed_at": "2026-11-18", "source_locator": "pp. 45–46, and the conclusion on pp. 69–71", "main_result": "Proves infinitude of primes in every reduced arithmetic progression by decomposing a progression into characters and establishing the required nonvanishing at the real point 1.", "classical_zeta_transfer_obstacle": "The nonvanishing argument is at a boundary point for Dirichlet series. It does not control nontrivial zeros of the ordinary zeta function.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-DIRICHLET1837"]}','Beweis des Satzes, daß jede unbegrenzte arithmetische Progression, deren erstes Glied und Differenz ganze Zahlen ohne gemeinschaftlichen Factor sind, unendlich viele Primzahlen enthält','["Peter Gustav Lejeune Dirichlet"]',NULL,'1837',0,0,'selected_checkpoint_priority_work','full_text_accessed','original journal reproduction hosted by Rutgers, with library cover','https://sites.math.rutgers.edu/~alexk/2022S572/Dirichlet1837.pdf','28e84740e81f6beeed5bad5553571dba9eeb86f95c82005a192b68278326f60f','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-CHEB1852A','corpus/bibliography.jsonl',455,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-CHEB1852A", "title": "Sur la totalité des nombres premiers inférieurs à une limite donnée", "authors": ["Pafnuty Chebyshev"], "year": 1852, "venue": "Journal de Mathématiques Pures et Appliquées 17, 341–365", "language": "French", "doi": null, "arxiv_id": null, "canonical_url": "https://www.numdam.org/item/JMPA_1852_1_17__341_0.pdf", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at opening statement and closing estimates.", "source_path": "sources/geometry64_historical_sources/cheb1852a.pdf", "source_url": "https://www.numdam.org/item/JMPA_1852_1_17__341_0.pdf", "effective_source_url": "https://www.numdam.org/item/JMPA_1852_1_17__341_0.pdf", "source_sha256": "fb8cf2a1642e3c741fba3b6668f2f4b815a0f86ae4c4e743a1aa39d212923653", "pdf_pages": 26, "accessed_at": "2026-11-18", "source_locator": "opening statement and closing estimates", "main_result": "Studies the prime counting function via factorials and the summatory logarithms of primes, and constrains possible asymptotics, including the constant of any existing prime-number-theorem ratio.", "classical_zeta_transfer_obstacle": "The arguments give constraints on prime counts and possible asymptotic expansions. They do not supply bounds on zeta zeros in the critical strip.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-CHEB1852A"]}','Sur la totalité des nombres premiers inférieurs à une limite donnée','["Pafnuty Chebyshev"]',NULL,'1852',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/item/JMPA_1852_1_17__341_0.pdf','fb8cf2a1642e3c741fba3b6668f2f4b815a0f86ae4c4e743a1aa39d212923653','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-CHEB1852B','corpus/bibliography.jsonl',456,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-CHEB1852B", "title": "Mémoire sur les nombres premiers", "authors": ["Pafnuty Chebyshev"], "year": 1852, "venue": "Journal de Mathématiques Pures et Appliquées 17, 366–390", "language": "French", "doi": null, "arxiv_id": null, "canonical_url": "https://archive.numdam.org/item/JMPA_1852_1_17__366_0.pdf", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at pp. 382–390, prime-count bounds and proof of Bertrand''s postulate.", "source_path": "sources/geometry64_historical_sources/cheb1852b.pdf", "source_url": "https://archive.numdam.org/item/JMPA_1852_1_17__366_0.pdf", "effective_source_url": "https://archive.numdam.org/item/JMPA_1852_1_17__366_0.pdf", "source_sha256": "cb1534bcfbf7a2356af67532592ffa917ac8b5db7bf5c59b64a14af3476db796", "pdf_pages": 26, "accessed_at": "2026-11-18", "source_locator": "pp. 382–390, prime-count bounds and proof of Bertrand''s postulate", "main_result": "Gives explicit upper and lower comparisons for prime counts and proves the stated prime-existence interval of Bertrand.", "classical_zeta_transfer_obstacle": "Finite intervals and constant-factor bounds are compatible with error terms far larger than the square-root scale in RH.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-CHEB1852B"]}','Mémoire sur les nombres premiers','["Pafnuty Chebyshev"]',NULL,'1852',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://archive.numdam.org/item/JMPA_1852_1_17__366_0.pdf','cb1534bcfbf7a2356af67532592ffa917ac8b5db7bf5c59b64a14af3476db796','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-LANDAU1900','corpus/bibliography.jsonl',457,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-LANDAU1900", "title": "Sur quelques problèmes relatifs à la distribution des nombres premiers", "authors": ["Edmund Landau"], "year": 1900, "venue": "Bulletin de la Société Mathématique de France 28, 25–38", "language": "French", "doi": "10.24033/bsmf.619", "arxiv_id": null, "canonical_url": "https://doi.org/10.24033/bsmf.619", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §1 and closing equations (13)–(14).", "source_path": "sources/geometry64_historical_sources/landau1900.pdf", "source_url": "https://www.numdam.org/article/BSMF_1900__28__25_1.pdf", "effective_source_url": "https://www.numdam.org/article/BSMF_1900__28__25_1.pdf", "source_sha256": "91838df91181c5fef3ed9d82032dd21fda85f84cfa158932d61493e043469f3b", "pdf_pages": 15, "accessed_at": "2026-11-18", "source_locator": "§1 and closing equations (13)–(14)", "main_result": "Uses partial summation to move between weighted prime-counting statements. In particular the theorem for the sum of log p directly yields the corresponding logarithmic integral estimate without a second contour argument.", "classical_zeta_transfer_obstacle": "Partial summation preserves the scale of an available PNT remainder. It does not create the square-root scale necessary to constrain critical-strip zeros.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-LANDAU1900"]}','Sur quelques problèmes relatifs à la distribution des nombres premiers','["Edmund Landau"]',NULL,'1900',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/article/BSMF_1900__28__25_1.pdf','91838df91181c5fef3ed9d82032dd21fda85f84cfa158932d61493e043469f3b','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-LANDAU1905','corpus/bibliography.jsonl',458,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-LANDAU1905", "title": "Sur quelques inégalités dans la théorie de la fonction ζ(s) de Riemann", "authors": ["Edmund Landau"], "year": 1905, "venue": "Bulletin de la Société Mathématique de France 33, 229–241", "language": "French", "doi": "10.24033/bsmf.758", "arxiv_id": null, "canonical_url": "https://doi.org/10.24033/bsmf.758", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §§I and III, including (23)–(27).", "source_path": "sources/geometry64_historical_sources/landau1905.pdf", "source_url": "https://www.numdam.org/item/10.24033/bsmf.758.pdf", "effective_source_url": "https://www.numdam.org/item/10.24033/bsmf.758.pdf", "source_sha256": "89521efdaa6459be83b4d9c7ecd1217a3ae523451f1972e63ca9796477ec2fd3", "pdf_pages": 14, "accessed_at": "2026-11-18", "source_locator": "§§I and III, including (23)–(27)", "main_result": "Investigates inequalities for ζ near the edge of the critical strip and applies reciprocal-zeta estimates to sharpen the error for the squarefree counting function.", "classical_zeta_transfer_obstacle": "The reciprocal-zeta estimate applies on its specified boundary and contours. The resulting squarefree asymptotic does not establish a zero-free critical half-strip.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "correction_history": "Numdam metadata says intégrales, while the printed heading at p. 229 says inégalités. The title follows the printed article.", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-LANDAU1905"]}','Sur quelques inégalités dans la théorie de la fonction ζ(s) de Riemann','["Edmund Landau"]',NULL,'1905',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/item/10.24033/bsmf.758.pdf','89521efdaa6459be83b4d9c7ecd1217a3ae523451f1972e63ca9796477ec2fd3','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-HADAMARD1909','corpus/bibliography.jsonl',459,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-HADAMARD1909", "title": "Sur une propriété fonctionnelle de la fonction ζ(s) de Riemann", "authors": ["Jacques Hadamard"], "year": 1909, "venue": "Bulletin de la Société Mathématique de France 37, 59–60", "language": "French", "doi": "10.24033/bsmf.836", "arxiv_id": null, "canonical_url": "https://doi.org/10.24033/bsmf.836", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "read_scope": "Read both printed pages, including the Jensen antecedent, the two characterizing identities, their asymptotic normalization and the majorant argument.", "source_path": "sources/geometry64_historical_sources/hadamard1909.pdf", "source_url": "https://www.numdam.org/item/10.24033/bsmf.836.pdf", "effective_source_url": "https://www.numdam.org/item/10.24033/bsmf.836.pdf", "source_sha256": "0a050ffc324d3297ecba39320ca0c082b899a24b8ef6f69b7b8a11116f21873f", "pdf_pages": 3, "accessed_at": "2026-11-18", "source_locator": "formulas (3)–(5), pp. 59–60", "main_result": "Each of two shifted-argument identities, together with ζ(s+n) tending to 1, separately characterizes the zeta function. The iteration for (4) uses positive coefficients and majorizes the one for (3).", "classical_zeta_transfer_obstacle": "Positivity controls the recursion and its convergence. It is not the positivity of a spectral form over all zeros.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-HADAMARD1909"]}','Sur une propriété fonctionnelle de la fonction ζ(s) de Riemann','["Jacques Hadamard"]',NULL,'1909',1,1,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/item/10.24033/bsmf.836.pdf','0a050ffc324d3297ecba39320ca0c082b899a24b8ef6f69b7b8a11116f21873f','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-FANTAPPIE1925','corpus/bibliography.jsonl',460,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-FANTAPPIE1925", "title": "Le énième nombre premier comme valeur asymptotique d’une fonction déduite de la fonction ζ(s) de Riemann", "authors": ["Luigi Fantappiè"], "year": 1925, "venue": "Bulletin de la Société Mathématique de France 53, 226–234", "language": "French", "doi": "10.24033/bsmf.1091", "arxiv_id": null, "canonical_url": "https://doi.org/10.24033/bsmf.1091", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §§1–2 and applications to p_n in the later sections.", "source_path": "sources/geometry64_historical_sources/fantappie1925.pdf", "source_url": "https://www.numdam.org/item/10.24033/bsmf.1091.pdf", "effective_source_url": "https://www.numdam.org/item/10.24033/bsmf.1091.pdf", "source_sha256": "da229407092ad0f75887f647c5e4b9ba91d028f7e64a0c11e4335063b9699708", "pdf_pages": 10, "accessed_at": "2026-11-18", "source_locator": "§§1–2 and applications to p_n in the later sections", "main_result": "Recovers successive exponents and coefficients of a Dirichlet series from its real-axis asymptotics, and applies the extraction to functions of ζ to recover a fixed nth prime.", "classical_zeta_transfer_obstacle": "The limit sends real s to infinity for a fixed prime index. It gives no uniform inversion near the critical strip and no bound on off-line zeros.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-FANTAPPIE1925"]}','Le énième nombre premier comme valeur asymptotique d’une fonction déduite de la fonction ζ(s) de Riemann','["Luigi Fantappiè"]',NULL,'1925',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/item/10.24033/bsmf.1091.pdf','da229407092ad0f75887f647c5e4b9ba91d028f7e64a0c11e4335063b9699708','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-VANDERCORPUTKOKSMA1930','corpus/bibliography.jsonl',461,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-VANDERCORPUTKOKSMA1930", "title": "Sur l’ordre de grandeur de la fonction ζ(s) de Riemann dans la bande critique", "authors": ["Johannes G. van der Corput", "Jurjen F. Koksma"], "year": 1930, "venue": "Annales de la Faculté des Sciences de Toulouse 22, 1–39", "language": "French", "doi": null, "arxiv_id": null, "canonical_url": "https://www.numdam.org/item/AFST_1930_3_22__1_0.pdf", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Introduction and exponential-sum estimate applied to ζ in the last sections.", "source_path": "sources/geometry64_historical_sources/vandercorputkoksma1930.pdf", "source_url": "https://www.numdam.org/item/AFST_1930_3_22__1_0.pdf", "effective_source_url": "https://www.numdam.org/item/AFST_1930_3_22__1_0.pdf", "source_sha256": "0ac5e61b2b281c2281c2b2b28d83967d27d5ad44f86af87b3b39dde0d9b90f70", "pdf_pages": 40, "accessed_at": "2026-11-18", "source_locator": "Introduction and exponential-sum estimate applied to ζ in the last sections", "main_result": "Derives improvements for bounds on the size of ζ in the critical strip by estimating oscillatory sums arising from its analytic representation.", "classical_zeta_transfer_obstacle": "An upper bound on the modulus of ζ in a strip leaves open the location of its zeros there.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-VANDERCORPUTKOKSMA1930"]}','Sur l’ordre de grandeur de la fonction ζ(s) de Riemann dans la bande critique','["Johannes G. van der Corput", "Jurjen F. Koksma"]',NULL,'1930',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/item/AFST_1930_3_22__1_0.pdf','0ac5e61b2b281c2281c2b2b28d83967d27d5ad44f86af87b3b39dde0d9b90f70','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-SPEISER1935','corpus/bibliography.jsonl',462,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-SPEISER1935", "title": "Geometrisches zur Riemannschen Zetafunktion", "authors": ["Andreas Speiser"], "year": 1935, "venue": "Mathematische Annalen 110, 514–521", "language": "German", "doi": "10.1007/BF01448042", "arxiv_id": null, "canonical_url": "https://doi.org/10.1007/BF01448042", "publication_status": "published", "version": "original Mathematische Annalen volume 110 scan with GDZ coversheet dated 1935", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at pp. 517–519, discussion of level curves and branch points.", "source_path": "sources/geometry64_historical_sources/speiser1935.pdf", "source_url": "https://raw.githubusercontent.com/Kuberwastaken/riemann/94fa51e8f26794ef2d206c6c12e7adb4d85cbeaf/papers/analytic-progress/Speiser-1935-geometrisches.pdf", "effective_source_url": "https://raw.githubusercontent.com/Kuberwastaken/riemann/94fa51e8f26794ef2d206c6c12e7adb4d85cbeaf/papers/analytic-progress/Speiser-1935-geometrisches.pdf", "source_sha256": "52ebdf54f1ee8eed485ef6d6e7952ff2aa787646b1a2748d0b524136df994b29", "pdf_pages": 9, "accessed_at": "2026-11-18", "source_locator": "pp. 517–519, discussion of level curves and branch points", "main_result": "Relates the Riemann hypothesis to the absence of nontrivial ζ′ zeros to the left of the critical line by studying the level curves of ζ.", "classical_zeta_transfer_obstacle": "This transfers the needed global zero exclusion to a derivative and supplies a geometric way to phrase it. The exclusion itself is still required.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "correction_history": "1934 appears in some indexes and is the receipt year. This entry follows the 1935 volume year recorded on the GDZ wrapper.", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-SPEISER1935"]}','Geometrisches zur Riemannschen Zetafunktion','["Andreas Speiser"]',NULL,'1935',0,0,'selected_checkpoint_priority_work','full_text_accessed','original Mathematische Annalen volume 110 scan with GDZ coversheet dated 1935','https://raw.githubusercontent.com/Kuberwastaken/riemann/94fa51e8f26794ef2d206c6c12e7adb4d85cbeaf/papers/analytic-progress/Speiser-1935-geometrisches.pdf','52ebdf54f1ee8eed485ef6d6e7952ff2aa787646b1a2748d0b524136df994b29','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-LEVINSONMONTGOMERY1974','corpus/bibliography.jsonl',463,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-LEVINSONMONTGOMERY1974", "title": "Zeros of the derivatives of the Riemann zeta-function", "authors": ["Norman Levinson", "Hugh L. Montgomery"], "year": 1974, "venue": "Acta Mathematica 133, 49–65", "language": "English", "doi": "10.1007/BF02392141", "arxiv_id": null, "canonical_url": "https://doi.org/10.1007/BF02392141", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem 1, equations (1.1)–(1.2), and its corollary.", "source_path": "sources/geometry64_historical_sources/levinsonmontgomery1974.pdf", "source_url": "https://archive.ymsc.tsinghua.edu.cn/pacm_download/117/6174-11511_2006_Article_BF02392141.pdf", "effective_source_url": "https://archive.ymsc.tsinghua.edu.cn/pacm_download/117/6174-11511_2006_Article_BF02392141.pdf", "source_sha256": "fb3c5f7f7f7d0dd3a25559d712a4f7730509ea478cc578156904b98dd46ed0d3", "pdf_pages": 17, "accessed_at": "2026-11-18", "source_locator": "Theorem 1, equations (1.1)–(1.2), and its corollary", "main_result": "The counts of ζ and ζ′ zeros in the left half of the critical strip up to height T differ by O(log T). The ensuing corollary gives an explicit derivative nonvanishing equivalent to RH.", "classical_zeta_transfer_obstacle": "The comparison relates two potentially nonempty collections of zeros, so a separate argument is needed to exclude every ζ′ zero in that region.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-LEVINSONMONTGOMERY1974"]}','Zeros of the derivatives of the Riemann zeta-function','["Norman Levinson", "Hugh L. Montgomery"]',NULL,'1974',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://archive.ymsc.tsinghua.edu.cn/pacm_download/117/6174-11511_2006_Article_BF02392141.pdf','fb3c5f7f7f7d0dd3a25559d712a4f7730509ea478cc578156904b98dd46ed0d3','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-LEVINSON1973','corpus/bibliography.jsonl',464,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-LEVINSON1973", "title": "Asymptotic Formula for the Coordinates of the Zeros of Sections of the Zeta Function, ζ_N(s), Near s = 1", "authors": ["Norman Levinson"], "year": 1973, "venue": "PNAS 70, 985–987", "language": "English", "doi": "10.1073/pnas.70.4.985", "arxiv_id": null, "canonical_url": "https://doi.org/10.1073/pnas.70.4.985", "publication_status": "published", "version": "original PNAS printed page images assembled from PMC CDN into a PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Abstract and §1, and the concluding location argument.", "source_path": "sources/geometry64_historical_sources/levinson1973.pdf", "source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC433407/", "effective_source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC433407/", "source_sha256": "c512acfc8a528e89ea9b7e96cc56340e58145efd927e2d3702fc52b7e4b8f49c", "pdf_pages": 3, "accessed_at": "2026-11-18", "source_locator": "Abstract and §1, and the concluding location argument", "main_result": "For finite Dirichlet sections ζ_N, estimates the zeros near 1 at large N and establishes the stated left-of-1 position in that range.", "classical_zeta_transfer_obstacle": "The zeros of truncations and those of meromorphic ζ are distinct. Uniform convergence of the finite Dirichlet sums is available strictly to the right of 1, outside the intended critical region.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-LEVINSON1973"]}','Asymptotic Formula for the Coordinates of the Zeros of Sections of the Zeta Function, ζ_N(s), Near s = 1','["Norman Levinson"]',NULL,'1973',0,0,'selected_checkpoint_priority_work','full_text_accessed','original PNAS printed page images assembled from PMC CDN into a PDF','https://pmc.ncbi.nlm.nih.gov/articles/PMC433407/','c512acfc8a528e89ea9b7e96cc56340e58145efd927e2d3702fc52b7e4b8f49c','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-LEVINSON1974B','corpus/bibliography.jsonl',465,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-LEVINSON1974B", "title": "Generalization of Recent Method Giving Lower Bound for N₀(T) of Riemann’s Zeta-Function", "authors": ["Norman Levinson"], "year": 1974, "venue": "PNAS 71, 3984–3987", "language": "English", "doi": "10.1073/pnas.71.10.3984", "arxiv_id": null, "canonical_url": "https://doi.org/10.1073/pnas.71.10.3984", "publication_status": "published", "version": "original PNAS printed page images assembled from PMC CDN into a PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at p. 3984, the polynomial condition and equation (1).", "source_path": "sources/geometry64_historical_sources/levinson1974b.pdf", "source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC434311/", "effective_source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC434311/", "source_sha256": "8f0db26ca8b09d6be167aa28cd067efe2daf40cf5f2e67f3cea888403fecf3bc", "pdf_pages": 4, "accessed_at": "2026-11-18", "source_locator": "p. 3984, the polynomial condition and equation (1)", "main_result": "Generalizes a lower-bound argument for critical-line zeros by replacing the linear polynomial in the approximate Dirichlet expression with P satisfying P(0)=0 and P(x)+P(1−x)=1.", "classical_zeta_transfer_obstacle": "The polynomial freedom affects bounds for the proportion of zeros on the line. It does not rule out individual exceptions.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-LEVINSON1974B"]}','Generalization of Recent Method Giving Lower Bound for N₀(T) of Riemann’s Zeta-Function','["Norman Levinson"]',NULL,'1974',0,0,'selected_checkpoint_priority_work','full_text_accessed','original PNAS printed page images assembled from PMC CDN into a PDF','https://pmc.ncbi.nlm.nih.gov/articles/PMC434311/','8f0db26ca8b09d6be167aa28cd067efe2daf40cf5f2e67f3cea888403fecf3bc','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-LEVINSON1975A','corpus/bibliography.jsonl',466,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-LEVINSON1975A", "title": "Almost All Roots of ζ(s) = a Are Arbitrarily Close to σ = 1/2", "authors": ["Norman Levinson"], "year": 1975, "venue": "PNAS 72, 1322–1324", "language": "English", "doi": "10.1073/pnas.72.4.1322", "arxiv_id": null, "canonical_url": "https://doi.org/10.1073/pnas.72.4.1322", "publication_status": "published", "version": "original PNAS printed page images assembled from PMC CDN into a PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "read_scope": "Read all three printed pages, including the mean-square lemma, weighted root sums, the separate left and right tails, the a=1 modification and the closing note about Selberg''s refinement.", "source_path": "sources/geometry64_historical_sources/levinson1975a.pdf", "source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC432525/", "effective_source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC432525/", "source_sha256": "2f091b68fa53127b63e3e132b3c3686c3dc3a256d4859317ca554efd85c5d6d1", "pdf_pages": 3, "accessed_at": "2026-11-18", "source_locator": "main Theorem, p. 1322, with Lemmas 1–6 and proof on pp. 1322–1323", "main_result": "For fixed complex a and T^(1/2)≤U≤T, all but O(U log T/log log T) roots of ζ(s)=a with T<t<T+U lie within (log log T)^2/log T of the critical line. The inner count has main term U log T/(2π).", "classical_zeta_transfer_obstacle": "The same clustering holds even for nonzero target values. A density-one asymptotic for a shrinking strip does not prove exact location of every zero.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-LEVINSON1975A"]}','Almost All Roots of ζ(s) = a Are Arbitrarily Close to σ = 1/2','["Norman Levinson"]',NULL,'1975',1,1,'selected_checkpoint_priority_work','full_text_accessed','original PNAS printed page images assembled from PMC CDN into a PDF','https://pmc.ncbi.nlm.nih.gov/articles/PMC432525/','2f091b68fa53127b63e3e132b3c3686c3dc3a256d4859317ca554efd85c5d6d1','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-LEVINSON1975B','corpus/bibliography.jsonl',467,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-LEVINSON1975B", "title": "Deduction of Semi-Optimal Mollifier for Obtaining Lower Bound for N₀(T) for Riemann’s Zeta-Function", "authors": ["Norman Levinson"], "year": 1975, "venue": "PNAS 72, 294–297", "language": "English", "doi": "10.1073/pnas.72.1.294", "arxiv_id": null, "canonical_url": "https://doi.org/10.1073/pnas.72.1.294", "publication_status": "published", "version": "original PNAS printed page images assembled from PMC CDN into a PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "read_scope": "Read all four printed pages, following the choice of dominant term, the boundary constraints H(0)=0 and H(log y)=1, the optimized profile, and the final comparison in (33).", "source_path": "sources/geometry64_historical_sources/levinson1975b.pdf", "source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC432290/", "effective_source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC432290/", "source_sha256": "07096fdd2cd78fbf622c534245294b86026233d98e894c89823f1f95b51c520a", "pdf_pages": 4, "accessed_at": "2026-11-18", "source_locator": "equations (17)–(23) and (33), pp. 295–297", "main_result": "Derives an Euler–Lagrange equation after smoothing an optimization of the dominant contribution in Levinson''s mollified mean square. The paper reports a small improvement in the resulting lower bound.", "classical_zeta_transfer_obstacle": "The optimization treats only the dominant term and counts zeros on the line in bulk. It cannot exclude occasional off-line zeros.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-LEVINSON1975B"]}','Deduction of Semi-Optimal Mollifier for Obtaining Lower Bound for N₀(T) for Riemann’s Zeta-Function','["Norman Levinson"]',NULL,'1975',1,1,'selected_checkpoint_priority_work','full_text_accessed','original PNAS printed page images assembled from PMC CDN into a PDF','https://pmc.ncbi.nlm.nih.gov/articles/PMC432290/','07096fdd2cd78fbf622c534245294b86026233d98e894c89823f1f95b51c520a','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-DELANGE1954','corpus/bibliography.jsonl',468,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-DELANGE1954", "title": "Généralisation du théorème de Ikehara", "authors": ["Hubert Delange"], "year": 1954, "venue": "Annales Scientifiques de l’École Normale Supérieure 71, 213–242", "language": "French", "doi": "10.24033/asens.1023", "arxiv_id": null, "canonical_url": "https://doi.org/10.24033/asens.1023", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorems I–II, pp. 213–216.", "source_path": "sources/geometry64_historical_sources/delange1954.pdf", "source_url": "https://www.numdam.org/article/ASENS_1954_3_71_3_213_0.pdf", "effective_source_url": "https://www.numdam.org/article/ASENS_1954_3_71_3_213_0.pdf", "source_sha256": "4934b4bfba12d405fc267fa0c0318c3034ab29c9e8223388019377bb45ca0998", "pdf_pages": 31, "accessed_at": "2026-11-18", "source_locator": "Theorems I–II, pp. 213–216", "main_result": "For a nondecreasing summatory function with Laplace–Stieltjes transform having the specified one-sided boundary behavior and a controlled singular term, derives an asymptotic A exp(at)P(t). Theorem II relaxes the permitted boundary behavior.", "classical_zeta_transfer_obstacle": "A Tauberian result derives asymptotics from boundary data. It neither supplies boundary data on the critical line nor excludes internal zeros.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-DELANGE1954"]}','Généralisation du théorème de Ikehara','["Hubert Delange"]',NULL,'1954',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/article/ASENS_1954_3_71_3_213_0.pdf','4934b4bfba12d405fc267fa0c0318c3034ab29c9e8223388019377bb45ca0998','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-DELANGE1960','corpus/bibliography.jsonl',469,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-DELANGE1960", "title": "Distribution des nombres premiers et fonction ζ(s)", "authors": ["Hubert Delange"], "year": 1960, "venue": "Séminaire Delange–Pisot–Poitou 1, Exposé 1, 1–18", "language": "French", "doi": null, "arxiv_id": null, "canonical_url": "https://archive.numdam.org/item/SDPP_1959-1960__1__A1_0.pdf", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at items 12–14, including the Ikehara application.", "source_path": "sources/geometry64_historical_sources/delange1960.pdf", "source_url": "https://archive.numdam.org/item/SDPP_1959-1960__1__A1_0.pdf", "effective_source_url": "https://archive.numdam.org/item/SDPP_1959-1960__1__A1_0.pdf", "source_sha256": "723273d3b8236dd2f05a4e083c34ec890c10bebf70893f6db84950e5b89febc7", "pdf_pages": 19, "accessed_at": "2026-11-18", "source_locator": "items 12–14, including the Ikehara application", "main_result": "Explains how the nonvanishing of ζ at Re s=1 suffices for the PNT via Ikehara and how stronger zero information produces sharper prime-counting remainders.", "classical_zeta_transfer_obstacle": "The Tauberian theorem only uses the line Re s=1. It yields no zero exclusion in the open critical strip.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-DELANGE1960"]}','Distribution des nombres premiers et fonction ζ(s)','["Hubert Delange"]',NULL,'1960',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://archive.numdam.org/item/SDPP_1959-1960__1__A1_0.pdf','723273d3b8236dd2f05a4e083c34ec890c10bebf70893f6db84950e5b89febc7','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-DELANGE1961','corpus/bibliography.jsonl',470,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-DELANGE1961", "title": "Un théorème sur les fonctions arithmétiques multiplicatives et ses applications", "authors": ["Hubert Delange"], "year": 1961, "venue": "Annales Scientifiques de l’École Normale Supérieure 78, 1–29", "language": "French", "doi": null, "arxiv_id": null, "canonical_url": "https://www.numdam.org/item/ASENS_1961_3_78_1_1_0.pdf", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §1.1, equations (2)–(3).", "source_path": "sources/geometry64_historical_sources/delange1961.pdf", "source_url": "https://www.numdam.org/item/ASENS_1961_3_78_1_1_0.pdf", "effective_source_url": "https://www.numdam.org/item/ASENS_1961_3_78_1_1_0.pdf", "source_sha256": "fdd699c6c4b0608c6ebd10af5a4ff8e86f6f04b88440fc9981a12cd7ed33e80e", "pdf_pages": 30, "accessed_at": "2026-11-18", "source_locator": "§1.1, equations (2)–(3)", "main_result": "Under its multiplicativity, boundedness and divergence conditions at primes, the paper proves cancellation of the mean over all integers and over squarefree integers, with applications to additive-function distributions.", "classical_zeta_transfer_obstacle": "Prime-weighted mean cancellation is much weaker than the quantitative cancellation in the Möbius summatory function required for RH.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-DELANGE1961"]}','Un théorème sur les fonctions arithmétiques multiplicatives et ses applications','["Hubert Delange"]',NULL,'1961',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/item/ASENS_1961_3_78_1_1_0.pdf','fdd699c6c4b0608c6ebd10af5a4ff8e86f6f04b88440fc9981a12cd7ed33e80e','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-DELANGE1965','corpus/bibliography.jsonl',471,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-DELANGE1965", "title": "Démonstration élémentaire du théorème des nombres premiers", "authors": ["Hubert Delange"], "year": 1965, "venue": "Séminaire Delange–Pisot–Poitou 6(1), Exposé 6, 1–13", "language": "French", "doi": null, "arxiv_id": null, "canonical_url": "https://www.numdam.org/item/SDPP_1964-1965__6_1_A5_0.pdf", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at statement at items 1–2 and the final elementary argument.", "source_path": "sources/geometry64_historical_sources/delange1965.pdf", "source_url": "https://www.numdam.org/item/SDPP_1964-1965__6_1_A5_0.pdf", "effective_source_url": "https://www.numdam.org/item/SDPP_1964-1965__6_1_A5_0.pdf", "source_sha256": "6510106d74fc18e45864cf3e0da9d492668cc223c59929be1f637621d53b68b3", "pdf_pages": 14, "accessed_at": "2026-11-18", "source_locator": "statement at items 1–2 and the final elementary argument", "main_result": "Gives an elementary proof of the prime number theorem, phrased in terms of the asymptotic weighted prime sums and using Selberg''s identity.", "classical_zeta_transfer_obstacle": "The elementary prime number theorem gives an asymptotic of order x without an RH-scale bound for its remainder.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-DELANGE1965"]}','Démonstration élémentaire du théorème des nombres premiers','["Hubert Delange"]',NULL,'1965',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/item/SDPP_1964-1965__6_1_A5_0.pdf','6510106d74fc18e45864cf3e0da9d492668cc223c59929be1f637621d53b68b3','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
