INSERT INTO "papers" VALUES('PAPER-HIST64-STECHKIN1970','corpus/bibliography.jsonl',473,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-STECHKIN1970", "title": "О нулях дзета-функции Римана", "authors": ["Sergei B. Stechkin"], "year": 1970, "venue": "Математические заметки 8(4), 419–429", "language": "Russian", "doi": null, "arxiv_id": null, "canonical_url": "https://m.mathnet.ru/php/getFT.phtml?jrnid=mzm&option_lang=eng&paperid=9606&what=fullt", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at abstract, introduction equation (1), and the concluding theorem.", "source_path": "sources/geometry64_historical_sources/stechkin1970.pdf", "source_url": "https://m.mathnet.ru/php/getFT.phtml?jrnid=mzm&option_lang=eng&paperid=9606&what=fullt", "effective_source_url": "https://m.mathnet.ru/links/3928bd51a6f841a18561f24d410f4e74/mzm9606.pdf", "source_sha256": "940ced3e044ca51f4adc4cc3241945486638a46261b7a3f8adde48125e9aef65", "pdf_pages": 11, "accessed_at": "2026-11-18", "source_locator": "abstract, introduction equation (1), and the concluding theorem", "main_result": "Proves ζ(σ+it)≠0 for σ≥1−1/(9.65 log t) with t≥12, using a trigonometric polynomial and a differenced logarithmic derivative.", "classical_zeta_transfer_obstacle": "An explicit region adjacent to 1 leaves the complementary part of the right half-strip uncontrolled.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-S