INSERT INTO "papers" VALUES('PAPER-HIST64-VINOGRADOV1958N','corpus/bibliography.jsonl',474,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-VINOGRADOV1958N", "title": "О функции ζ(s)", "authors": ["Ivan M. Vinogradov"], "year": 1958, "venue": "Доклады Академии наук СССР 118(4), 631", "language": "Russian", "doi": null, "arxiv_id": null, "canonical_url": "https://m.mathnet.ru/php/getFT.phtml?jrnid=dan&option_lang=eng&paperid=22700&what=fullt", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at p. 631, equations (1)–(2).", "source_path": "sources/geometry64_historical_sources/vinogradov1958n.pdf", "source_url": "https://m.mathnet.ru/php/getFT.phtml?jrnid=dan&option_lang=eng&paperid=22700&what=fullt", "effective_source_url": "https://m.mathnet.ru/links/609c3bdda6d07515c4009f3294c215cd/dan22700.pdf", "source_sha256": "f132d12ee1b660ffe82e64d0e8260c8e9fc01a751a8ab3ee9d580ea90c5413ad", "pdf_pages": 1, "accessed_at": "2026-11-18", "source_locator": "p. 631, equations (1)–(2)", "main_result": "Announces a bound for ζ(1+it) from a new exponential-sum estimate, with the summed phase given by a multiple of ln x in the stated parameter range.", "classical_zeta_transfer_obstacle": "The individual value bound is on the right boundary and does not exclude interior zeros.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-VINOGRADOV1958N"]}','О функции ζ(s)','["Ivan M. Vinogradov"]',NULL,'