INSERT INTO "papers" VALUES('PAPER-HIST64-KOCH1901','corpus/bibliography.jsonl',475,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-KOCH1901", "title": "Sur la distribution des nombres premiers", "authors": ["Helge von Koch"], "year": 1901, "venue": "Acta Mathematica 24, 159–182", "language": "French", "doi": "10.1007/BF02403071", "arxiv_id": null, "canonical_url": "https://doi.org/10.1007/BF02403071", "publication_status": "published", "version": "original journal PDF with the Note additionnelle on printed p. 182", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §7 and the Note additionnelle, pp. 181–182.", "source_path": "sources/geometry64_historical_sources/koch1901.pdf", "source_url": "https://archive.ymsc.tsinghua.edu.cn/pacm_download/117/5070-11511_2006_Article_BF02403071.pdf", "effective_source_url": "https://archive.ymsc.tsinghua.edu.cn/pacm_download/117/5070-11511_2006_Article_BF02403071.pdf", "source_sha256": "d51cba281afc3870d3d6a085471b0b1dc547b086236787995fca880c927b052f", "pdf_pages": 24, "accessed_at": "2026-11-18", "source_locator": "§7 and the Note additionnelle, pp. 181–182", "main_result": "Under RH, §7 proves π(x)−Li(x)=O_ε(x^(1/2+ε)). The added note sharpens it to O(x^(1/2) log x).", "classical_zeta_transfer_obstacle": "The estimate relies on the critical-line hypothesis. Using the remainder to deduce RH would require proving the bound independently.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-KOCH1901"]}','Sur la distribution des nombres premiers','["Helge von Koch"]',NULL,'1901',0,0,'selected_checkpoint_priority_work','full_text_accessed','original journal PDF with the Note additionnelle on printed p. 182','https://archive.ymsc.tsinghua.edu.cn/pacm_download/117/5070-11511_2006_Article_BF02403071.pdf','d51cba281afc3870d3d6a085471b0b1dc547b086236787995fca880c927b052f','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-GRISO1978','corpus/bibliography.jsonl',476,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-GRISO1978", "title": "Équirépartition et zéros de la fonction zêta", "authors": ["Georges Griso"], "year": 1978, "venue": "Séminaire Delange–Pisot–Poitou 19(2), Exposé 23, 1–7", "language": "French", "doi": null, "arxiv_id": null, "canonical_url": "https://www.numdam.org/item/SDPP_1977-1978__19_2_A1_0.pdf", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at pp. 1–3, Landau sums (1)–(2) and Weyl criterion.", "source_path": "sources/geometry64_historical_sources/griso1978.pdf", "source_url": "https://www.numdam.org/item/SDPP_1977-1978__19_2_A1_0.pdf", "effective_source_url": "https://www.numdam.org/item/SDPP_1977-1978__19_2_A1_0.pdf", "source_sha256": "92cfb2b49a234c8611aa5df5b990e131d4a20fb3982d24c1b2850512c57decb5", "pdf_pages": 8, "accessed_at": "2026-11-18", "source_locator": "pp. 1–3, Landau sums (1)–(2) and Weyl criterion", "main_result": "Removes RH from the equidistribution modulo 1 of logarithmic rescalings of the full ordinates, by combining Landau''s weighted zero sums with a bound controlling the real parts, and gives a multidimensional extension for multiplicatively independent scales.", "classical_zeta_transfer_obstacle": "Uniform distribution modulo 1 of imaginary parts does not distinguish critical-line zeros from off-line zeros.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-GRISO1978"]}','Équirépartition et zéros de la fonction zêta','["Georges Griso"]',NULL,'1978',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/item/SDPP_1977-1978__19_2_A1_0.pdf','92cfb2b49a234c8611aa5df5b990e131d4a20fb3982d24c1b2850512c57decb5','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-BOREL1978','corpus/bibliography.jsonl',477,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-BOREL1978", "title": "Nombres premiers généralisés et équirépartition modulo 1", "authors": ["Jean-Pierre Borel"], "year": 1978, "venue": "Séminaire Delange–Pisot–Poitou 19(1), Exposé 7, 1–7", "language": "French", "doi": null, "arxiv_id": null, "canonical_url": "https://archive.numdam.org/item/SDPP_1977-1978__19_1_A5_0.pdf", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §§1–3, Theorems 1–3.", "source_path": "sources/geometry64_historical_sources/borel1978.pdf", "source_url": "https://archive.numdam.org/item/SDPP_1977-1978__19_1_A5_0.pdf", "effective_source_url": "https://archive.numdam.org/item/SDPP_1977-1978__19_1_A5_0.pdf", "source_sha256": "366631f0c690e84ce7e66d5701c3bc946f13acaca22fb6da1d8d0db483506714", "pdf_pages": 8, "accessed_at": "2026-11-18", "source_locator": "§§1–3, Theorems 1–3", "main_result": "Uses a Weyl criterion on generalized integers and generalized primes, with character hypotheses and estimates derived from the generalized prime number theorem.", "classical_zeta_transfer_obstacle": "The conclusion concerns distribution modulo 1 under generalized prime hypotheses. It places no restriction on every classical zeta zero.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-BOREL1978"]}','Nombres premiers généralisés et 