INSERT INTO "papers" VALUES('PAPER-HIST64-RYAVEC1977','corpus/bibliography.jsonl',478,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-RYAVEC1977", "title": "Inequalities for zeros of ζ(s)", "authors": ["Charles Ryavec"], "year": 1977, "venue": "Acta Arithmetica 33, 255–260", "language": "English", "doi": "10.4064/aa-33-3-255-260", "arxiv_id": null, "canonical_url": "https://doi.org/10.4064/aa-33-3-255-260", "publication_status": "published", "version": "Acta Arithmetica original printed article on two-page archive spreads", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorems 2–3, building on Lemma 1, pp. 255–260.", "source_path": "sources/geometry64_historical_sources/ryavec1977.pdf", "source_url": "https://matwbn.icm.edu.pl/ksiazki/aa/aa33/aa3334.pdf", "effective_source_url": "https://matwbn.icm.edu.pl/ksiazki/aa/aa33/aa3334.pdf", "source_sha256": "3bf96f9739d145f47d9754c6be3a29c30425338b8121836295b5ef42cf3618c4", "pdf_pages": 4, "accessed_at": "2026-11-18", "source_locator": "Theorems 2–3, building on Lemma 1, pp. 255–260", "main_result": "Constructs orthonormal families from a decomposition of the Mellin representation and applies Bessel''s inequality to restrict possible zeros; Theorem 3 gives explicit zero-free regions.", "classical_zeta_transfer_obstacle": "The inequalities depend on the constructed family and give the stated restricted regions, without covering the full off-line strip.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-RYAVEC1977"]}','Inequalities for zeros of ζ(s)','["Charles Ryavec"]',NULL,'1977',0,0,'selected_checkpoint_priority_work','full_text_accessed','Acta Arithmetica original printed article on two-page archive spreads','https://matwbn.icm.edu.pl/ksiazki/aa/aa33/aa3334.pdf','3bf96f9739d145f47d9754c6be3a29c30425338b8121836295b5ef42cf3618c4','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-RAMACHANDRA1978','corpus/bibliography.jsonl',479,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-RAMACHANDRA1978", "title": "On the zeros of the Riemann zeta-function and L-series", "authors": ["Kanakanahalli Ramachandra"], "year": 1978, "venue": "Acta Arithmetica 34, 211–218", "language": "English", "doi": "10.4064/aa-34-3-211-218", "arxiv_id": null, "canonical_url": "https://doi.org/10.4064/aa-34-3-211-218", "publication_status": "published", "version": "Acta Arithmetica original printed article on two-page archive spreads including neighboring article matter", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §1, Theorems 1–2, pp. 211–212.", "source_path": "sources/geometry64_historical_sources/ramachandra1978.pdf", "source_url": "https://matwbn.icm.edu.pl/ksiazki/aa/aa34/aa3434.pdf", "effective_source_url": "https://matwbn.icm.edu.pl/ksiazki/aa/aa34/aa3434.pdf", "source_sha256": "d3db25d9d71c29bab8209e076319cd8856ddfd23c512925ba06d300fa5b5a534", "pdf_pages": 5, "accessed_at": "2026-11-18", "source_locator": "§1, Theorems 1–2, pp. 211–212", "main_result": "Starting from one or two zeros with real part greater than 1/2 and ordinate above 100, gives lower bounds for a weighted sum over zeros in specified discs near the 1-line, subject to the stated scale restrictions.", "classical_zeta_transfer_obstacle": "The conditional neighborhood constraints describe consequences of a hypothetical off-line zero. The bounds do not by themselves contradict its presence.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "sel