INSERT INTO "papers" VALUES('PAPER-HIST64-TITCHMARSH1935','corpus/bibliography.jsonl',480,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-TITCHMARSH1935", "title": "The Zeros of the Riemann Zeta-Function", "authors": ["Edward C. Titchmarsh"], "year": 1935, "venue": "Proceedings of the Royal Society A 151, 234–255", "language": "English", "doi": "10.1098/rspa.1935.0146", "arxiv_id": null, "canonical_url": "https://doi.org/10.1098/rspa.1935.0146", "publication_status": "published", "version": "original journal scans on two-page spreads, 22 printed pages in 11 PDF pages", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at §1, pp. 234–235, and closing tables.", "source_path": "sources/geometry64_historical_sources/titchmarsh1935.pdf", "source_url": "https://mwolf.pracownicy.uksw.edu.pl/Proc_Roy_Soc_Lond_151%281936%29.pdf", "effective_source_url": "https://mwolf.pracownicy.uksw.edu.pl/Proc_Roy_Soc_Lond_151%281936%29.pdf", "source_sha256": "dc20e7532c52079e917da84bdde5d4d762aede4dda756628a1071a5cfa060fce", "pdf_pages": 11, "accessed_at": "2026-11-18", "source_locator": "§1, pp. 234–235, and closing tables", "main_result": "Uses the Riemann–Siegel asymptotic formula with a controlled remainder to locate the first 195 zeros up to ordinate 390 on the critical line.", "classical_zeta_transfer_obstacle": "The computation has a finite ordinate cutoff. Higher zeros require separate control.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-TITCHMARSH1935"]}','The Zeros of the Riemann Zeta-Function','["Edward C. Titchmarsh"]',NULL,'1935',0,0,'selected_checkpoint_priority_work','full_text_accessed','original journal scans on two-page spreads, 22 printed pages in 11 PDF pages','https://mwolf.pracownicy.uksw.edu.pl/Proc_Roy_Soc_Lond_151%281936%29.pdf','dc20e7532c52079e917da84bdde5d4d762aede4dda756628a1071a5cfa060fce','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-HADAMARD1893','corpus/bibliography.jsonl',481,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-HADAMARD1893", "title": "Étude sur les propriétés des fonctions entières et en particulier d’une fonction considérée par Riemann", "authors": ["Jacques Hadamard"], "year": 1893, "venue": "Journal de Mathématiques Pures et Appliquées 9, 171–215", "language": "French", "doi": null, "arxiv_id": null, "canonical_url": "https://www.numdam.org/item/JMPA_1893_4_9__171_0.pdf", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Part III, §§34–38, pp. 210–215.", "source_path": "sources/geometry64_historical_sources/hadamard1893.pdf", "source_url": "https://www.numdam.org/item/JMPA_1893_4_9__171_0.pdf", "effective_source_url": "https://www.numdam.org/item/JMPA_1893_4_9__171_0.pdf", "source_sha256": "572bc10ad6861735733f3ab13c50e9321d584660088d49d0017b0a1d42c64312", "pdf_pages": 46, "accessed_at": "2026-11-18", "source_locator": "Part III, §§34–38, pp. 210–215", "main_result": "Analyzes the growth and genus of the completed Riemann function, viewed in the squared centered variable, to justify the product structure assumed in Riemann''s memoir.", "classical_zeta_transfer_obstacle": "Entire-function genus gives convergence and structure of a product over zeros. It supplies no theorem forcing the individual factors'' zeros to lie on a line.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-HADAMARD1893"]}','Étude sur les propriétés des fonctions entières et en particulier d’une fonction considérée par Riemann','["Jacques Hadamard"]',NULL,'1893',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/item/JMPA_1893_4_9__171_0.pdf','572bc10ad6861735733f3ab13c50e9321d584660088d49d0017b0a1d42c64312','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-LEVINSON1972H','corpus/bibliography.jsonl',482,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-LEVINSON1972H", "title": "Ω-Theorems for Riemann’s Zeta-Function at Harmonic Combinations of Points", "authors": ["Norman Levinson"], "year": 1972, "venue": "PNAS 69, 1657–1658", "language": "English", "doi": "10.1073/pnas.69.7.1657", "arxiv_id": null, "canonical_url": "https://doi.org/10.1073/pnas.69.7.1657", "publication_status": "published", "version": "original PNAS printed page images assembled from PMC CDN into a PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at main statement and coefficient argument, pp. 1657–1658.", "source_path": "sources/geometry64_historical_sources/levinson1972h.pdf", "source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC426771/", "effective_source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC426771/", "source_sha256": "f9cb7975e1391ce582b2511dc667e1c18d44dcd2c716272d205caa09dd543191", "pdf_pages": 2, "accessed_at": "2026-11-18", "source_locator": "main statement and coefficient argument, pp. 1657–1658", "main_result": "Shows simultaneous large-product lower bounds for zeta values at harmonic ordinates for each fixed integer r≥2. Discusses analogues for fixed real parts between 1/2 and 1 and for reciprocal zeta at 1.", "classical_zeta_transfer_obstacle": "Large values at selected ordinates are compatible with off-line zeros elsewhere and are logically distinct from zero-free bounds.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-LEVINSON1972H"]}','Ω-Theorems for Riemann’s Zeta-Function at Harmonic Combinations of Points','["Norman Levinson"]',NULL,'1972',0,0,'selected_checkpoint_priority_work','full_text_accessed','original PNAS printed page images assembled from PMC CDN into a PDF','https://pmc.ncbi.nlm.nih.gov/articles/PMC426771/','f9cb7975e1391ce582b2511dc667e1c18d44dcd2c716272d205caa09dd543191','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-LEVINSON1972Q','corpus/bibliography.jsonl',483,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-LEVINSON1972Q", "title": "Ω-Theorems for Quotients of Zeta-Functions at Combinations of Points", "authors": ["Norman Levinson"], "year": 1972, "venue": "PNAS 69, 2528–2529", "language": "English", "doi": "10.1073/pnas.69.9.2528", "arxiv_id": null, "canonical_url": "https://doi.org/10.1073/pnas.69.9.2528", "publication_status": "published", "version": "original PNAS printed page images assembled from PMC CDN into a PDF", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem A, p. 2528.", "source_path": "sources/geometry64_historical_sources/levinson1972q.pdf", "source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC426980/", "effective_source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC426980/", "source_sha256": "76c625293d503e3f9f53b48ce0021f9ee26a3c8d7f34a4afabba8bc91dc57037", "pdf_pages": 2, "accessed_at": "2026-11-18", "source_locator": "Theorem A, p. 2528", "main_result": "For integers q,r in the stated ranges, proves limsup lower bounds for the absolute value of a quotient of zeta products on the 1-line, with factors indexed by harmonic scales.", "classical_zeta_transfer_obstacle": "A lower bound along selected sequences on the 1-line cannot exclude zeros further left.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-LEVINSON1972Q"]}','Ω-Theorems for Quotients of Zeta-Functions at Combinations of Points','["Norman Levinson"]',NULL,'1972',0,0,'selected_checkpoint_priority_work','full_text_accessed','original PNAS printed page images assembled from PMC CDN into a PDF','https://pmc.ncbi.nlm.nih.gov/articles/PMC426980/','76c625293d503e3f9f53b48ce0021f9ee26a3c8d7f34a4afabba8bc91dc57037','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-LANDAU1908','corpus/bibliography.jsonl',484,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-LANDAU1908", "title": "Nouvelle démonstration pour la formule de Riemann sur le nombre des nombres premiers inférieurs à une limite donnée et démonstration d’une formule plus générale pour le cas des nombres premiers d’une progression arithmétique", "authors": ["Edmund Landau"], "year": 1908, "venue": "Annales Scientifiques de l’École Normale Supérieure 25, 399–442", "language": "French", "doi": "10.24033/asens.595", "arxiv_id": null, "canonical_url": "https://doi.org/10.24033/asens.595", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at introduction, definition of f(x), and the later progression formula.", "source_path": "sources/geometry64_historical_sources/landau1908.pdf", "source_url": "https://www.numdam.org/article/ASENS_1908_3_25__399_0.pdf", "effective_source_url": "https://www.numdam.org/article/ASENS_1908_3_25__399_0.pdf", "source_sha256": "1404ca0d5d2949e6985ddecbd1af4c79589ab645a463a7815f330ad6a7be234b", "pdf_pages": 45, "accessed_at": "2026-11-18", "source_locator": "introduction, definition of f(x), and the later progression formula", "main_result": "Gives a new derivation of Riemann''s prime-power counting formula and its extension to primes in a reduced progression, using the appropriate Dirichlet L-series.", "classical_zeta_transfer_obstacle": "The explicit formula relates primes to a sum over zeros. It continues to require separate estimates or geometric information to locate the zeros.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-LANDAU1908"]}','Nouvelle démonstration pour la formule de Riemann sur le nombre des nombres premiers inférieurs à une limite donnée et démonstration d’une formule plus générale pour le cas des nombres premiers d’une progression arithmétique','["Edmund Landau"]',NULL,'1908',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/article/ASENS_1908_3_25__399_0.pdf','1404ca0d5d2949e6985ddecbd1af4c79589ab645a463a7815f330ad6a7be234b','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-PERRON1908','corpus/bibliography.jsonl',485,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-PERRON1908", "title": "Zur Theorie der Dirichletschen Reihen", "authors": ["Oskar Perron"], "year": 1908, "venue": "Journal für die reine und angewandte Mathematik 134, 95–143", "language": "German", "doi": "10.1515/crll.1908.134.95", "arxiv_id": null, "canonical_url": "https://doi.org/10.1515/crll.1908.134.95", "publication_status": "published", "version": "GDZ original volume pages extracted without altering printed pp. 95–143 (PDF pages 102–150 of the volume)", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at opening and §§4–5, especially the coefficient-summation integral on pp. 103–104.", "source_path": "sources/geometry64_historical_sources/perron1908.pdf", "source_url": "https://gdz.sub.uni-goettingen.de/download/pdf/PPN243919689_0134/PPN243919689_0134.pdf", "effective_source_url": "https://gdz.sub.uni-goettingen.de/download/pdf/PPN243919689_0134/PPN243919689_0134.pdf", "source_sha256": "41c2928bf7979217468db42825c3b25c261a20ba13869a99f4f539bdba82487a", "pdf_pages": 49, "accessed_at": "2026-11-18", "source_locator": "opening and §§4–5, especially the coefficient-summation integral on pp. 103–104", "main_result": "Supplies rigorous uniqueness and inversion results for Dirichlet series with increasing real exponents. His integral recovers coefficient sums with a boundary convention for exponents at the cutoff.", "classical_zeta_transfer_obstacle": "The inversion recovers sums from analytic data in a convergence half-plane. Moving the contour toward the critical line requires additional singularity and error control.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-PERRON1908"]}','Zur Theorie der Dirichletschen Reihen','["Oskar Perron"]',NULL,'1908',0,0,'selected_checkpoint_priority_work','full_text_accessed','GDZ original volume pages extracted without altering printed pp. 95–143 (PDF pages 102–150 of the volume)','https://gdz.sub.uni-goettingen.de/download/pdf/PPN243919689_0134/PPN243919689_0134.pdf','41c2928bf7979217468db42825c3b25c261a20ba13869a99f4f539bdba82487a','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-MOSER1976','corpus/bibliography.jsonl',486,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-MOSER1976", "title": "Об одной теореме Харди–Литтлвуда в теории дзета-функции Римана", "authors": ["Jan Moser"], "year": 1976, "venue": "Acta Arithmetica 31, 45–51", "language": "Russian", "doi": "10.4064/aa-31-1-45-51", "arxiv_id": null, "canonical_url": "https://doi.org/10.4064/aa-31-1-45-51", "publication_status": "published", "version": "Acta Arithmetica original printed article on two-page archive spreads", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at main theorem and (2)–(5), pp. 45–46.", "source_path": "sources/geometry64_historical_sources/moser1976.pdf", "source_url": "https://matwbn.icm.edu.pl/ksiazki/aa/aa31/aa3114.pdf", "effective_source_url": "https://matwbn.icm.edu.pl/ksiazki/aa/aa31/aa3114.pdf", "source_sha256": "9263a083bffb0e9de06ae1475c1dc8e50c4ad4ffcf9eb655c639fda0f14973ba", "pdf_pages": 4, "accessed_at": "2026-11-18", "source_locator": "main theorem and (2)–(5), pp. 45–46", "main_result": "Under its trigonometric-sum bound with exponent Δ, gives an odd-order critical-line zero in each sufficiently high interval of length T^(1/8+Δ/2) times an arbitrarily slowly increasing factor.", "classical_zeta_transfer_obstacle": "The interval contains at least one critical-line zero. This is consistent with other zeros in that interval off the critical line.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "correction_history": "The author returned to this result in the separate 1979 addendum, pp. 403–404, with a Lindelöf specialization and revised remainder estimate.", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-MOSER1976"]}','Об одной теореме Харди–Литтлвуда в теории дзета-функции Римана','["Jan Moser"]',NULL,'1976',0,0,'selected_checkpoint_priority_work','full_text_accessed','Acta Arithmetica original printed article on two-page archive spreads','https://matwbn.icm.edu.pl/ksiazki/aa/aa31/aa3114.pdf','9263a083bffb0e9de06ae1475c1dc8e50c4ad4ffcf9eb655c639fda0f14973ba','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-MOSER1977','corpus/bibliography.jsonl',487,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-MOSER1977", "title": "О поведении функций Re{ζ(s)}, Im{ζ(s)} в критической полосе", "authors": ["Jan Moser"], "year": 1977, "venue": "Acta Arithmetica 34, 25–35", "language": "Russian", "doi": "10.4064/aa-34-1-25-35", "arxiv_id": null, "canonical_url": "https://doi.org/10.4064/aa-34-1-25-35", "publication_status": "published", "version": "Acta Arithmetica original printed article on two-page archive spreads including neighboring article matter", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorems 1–2 and (1)–(8), p. 25.", "source_path": "sources/geometry64_historical_sources/moser1977.pdf", "source_url": "https://matwbn.icm.edu.pl/ksiazki/aa/aa34/aa3413.pdf", "effective_source_url": "https://matwbn.icm.edu.pl/ksiazki/aa/aa34/aa3413.pdf", "source_sha256": "03258eec1b0e3b7badd09e6090b5ce0355a2439316e59b6c41e69e1a77da8f0d", "pdf_pages": 6, "accessed_at": "2026-11-18", "source_locator": "Theorems 1–2 and (1)–(8), p. 25", "main_result": "Assuming the stated trigonometric-sum bound, proves that sufficiently high intervals specified in (2) at fixed σ=1/2+δ in the admitted range contain an ordinate where Im ζ vanishes and an ordinate where Re ζ equals 1.", "classical_zeta_transfer_obstacle": "Zeros of the imaginary part and real-target crossings are different level-set conditions. These results do not distinguish the locations of complex zeros of ζ.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-MOSER1977"]}','О поведении функций Re{ζ(s)}, Im{ζ(s)} в критической полосе','["Jan Moser"]',NULL,'1977',0,0,'selected_checkpoint_priority_work','full_text_accessed','Acta Arithmetica original printed article on two-page archive spreads including neighboring article matter','https://matwbn.icm.edu.pl/ksiazki/aa/aa34/aa3413.pdf','03258eec1b0e3b7badd09e6090b5ce0355a2439316e59b6c41e69e1a77da8f0d','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-MOSER1979','corpus/bibliography.jsonl',488,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-MOSER1979", "title": "Добавление к работе «Об одной теореме Харди–Литтлвуда в теории дзета-функции Римана»", "authors": ["Jan Moser"], "year": 1979, "venue": "Acta Arithmetica 35, 403–404", "language": "Russian", "doi": "10.4064/aa-35-4-403-404", "arxiv_id": null, "canonical_url": "https://doi.org/10.4064/aa-35-4-403-404", "publication_status": "published", "version": "Acta Arithmetica original printed addendum on two-page archive spreads including neighboring article matter", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "read_scope": "Read both printed pages. The first applies the Lindelöf exponential-sum formulation to the 1976 theorem and the second changes the truncation in its remainder analysis.", "source_path": "sources/geometry64_historical_sources/moser1979.pdf", "source_url": "https://matwbn.icm.edu.pl/ksiazki/aa/aa35/aa35410.pdf", "effective_source_url": "https://matwbn.icm.edu.pl/ksiazki/aa/aa35/aa35410.pdf", "source_sha256": "1d1893bd77e46d012a805c77a7b30d7d2f27111977d38995bb7dee9f5bd51644", "pdf_pages": 2, "accessed_at": "2026-11-18", "source_locator": "Theorem and (1)–(5), p. 403 and §2 p. 404", "main_result": "Under Lindelöf, every sufficiently high critical-line interval of length T^(1/8+ε) contains an odd-order zero. The addendum also refines the earlier remainder estimate by changing the summation cutoff.", "classical_zeta_transfer_obstacle": "The result is conditional and guarantees a critical-line zero in each interval. It does not locate all zeros there.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-MOSER1979"]}','Добавление к работе «Об одной теореме Харди–Литтлвуда в теории дзета-функции Римана»','["Jan Moser"]',NULL,'1979',1,1,'selected_checkpoint_priority_work','full_text_accessed','Acta Arithmetica original printed addendum on two-page archive spreads including neighboring article matter','https://matwbn.icm.edu.pl/ksiazki/aa/aa35/aa35410.pdf','1d1893bd77e46d012a805c77a7b30d7d2f27111977d38995bb7dee9f5bd51644','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-CAHEN1894','corpus/bibliography.jsonl',489,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-CAHEN1894", "title": "Sur la fonction ζ(s) de Riemann et sur des fonctions analogues", "authors": ["Eugène Cahen"], "year": 1894, "venue": "Annales Scientifiques de l’École Normale Supérieure 11, 75–164", "language": "French", "doi": "10.24033/asens.401", "arxiv_id": null, "canonical_url": "https://doi.org/10.24033/asens.401", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Part I, §§5–8, and opening discussion of functional relations.", "source_path": "sources/geometry64_historical_sources/cahen1894.pdf", "source_url": "https://www.numdam.org/article/ASENS_1894_3_11__75_0.pdf", "effective_source_url": "https://www.numdam.org/article/ASENS_1894_3_11__75_0.pdf", "source_sha256": "da2d5263275a212a58ce6f90930e8a209240df06df27a68c9936bf734e7e8550", "pdf_pages": 91, "accessed_at": "2026-11-18", "source_locator": "Part I, §§5–8, and opening discussion of functional relations", "main_result": "Develops the half-plane and line of convergence for generalized Dirichlet series and treats formulas relating the abscissa to sums of coefficients. Perron''s 1908 paper subsequently corrects some assertions and proof gaps.", "classical_zeta_transfer_obstacle": "Convergence and analytic continuation concern the representation of a function. Further zero-location information is needed within the domain of continuation.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-CAHEN1894"]}','Sur la fonction ζ(s) de Riemann et sur des fonctions analogues','["Eugène Cahen"]',NULL,'1894',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/article/ASENS_1894_3_11__75_0.pdf','da2d5263275a212a58ce6f90930e8a209240df06df27a68c9936bf734e7e8550','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HIST64-DELANGE1956D','corpus/bibliography.jsonl',490,'full_text_accessed','papers/geometry64_historical_sources_notes.md','{"id": "PAPER-HIST64-DELANGE1956D", "title": "Sur la distribution des entiers ayant certaines propriétés", "authors": ["Hubert Delange"], "year": 1956, "venue": "Annales Scientifiques de l’École Normale Supérieure 73, 15–74", "language": "French", "doi": "10.24033/asens.1041", "arxiv_id": null, "canonical_url": "https://doi.org/10.24033/asens.1041", "publication_status": "published", "version": "digitized original journal, proceedings or seminar publication", "bibliographic_verified": true, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "read_scope": "Targeted reading of the primary text at Theorem a, pp. 25–26, and applications beginning at Theorem 1.", "source_path": "sources/geometry64_historical_sources/delange1956d.pdf", "source_url": "https://www.numdam.org/item/10.24033/asens.1041.pdf", "effective_source_url": "https://www.numdam.org/item/10.24033/asens.1041.pdf", "source_sha256": "6a22756df097af375c36c6d439451a0ae43e3ec5d09213f3d28922993595b400", "pdf_pages": 61, "accessed_at": "2026-11-18", "source_locator": "Theorem a, pp. 25–26, and applications beginning at Theorem 1", "main_result": "Uses a generalization of Ikehara to pass from a controlled singular expansion at s=1 to asymptotics with logarithmic powers, then applies it to sets classified by prime divisors.", "classical_zeta_transfer_obstacle": "The analytic input is the local singularity at s=1 and control on its boundary line. It gives no general vanishing restriction in the critical strip.", "record_path": "papers/geometry64_historical_sources_notes.md", "track_file": "papers/geometry64_historical_sources_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HIST64-DELANGE1956D"]}','Sur la distribution des entiers ayant certaines propriétés','["Hubert Delange"]',NULL,'1956',0,0,'selected_checkpoint_priority_work','full_text_accessed','digitized original journal, proceedings or seminar publication','https://www.numdam.org/item/10.24033/asens.1041.pdf','6a22756df097af375c36c6d439451a0ae43e3ec5d09213f3d28922993595b400','papers/geometry64_historical_sources_notes.md','papers/geometry64_historical_sources_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-001','corpus/bibliography.jsonl',491,'full_text_accessed','audits/adversarial_reviews/director_deninger_whole_round11.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "number-field spectral transfer", "arxiv_id": "2204.02714", "audit_level": 3, "authors": ["Christopher Deninger"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2204.02714", "classical_zeta_transfer_obstacle": "This rules out one real descent requirement with the Artin compatibility (2.12). A complex or graded quaternionic theory, in particular the positive pairing (2.7) on every spectral component, remains conjectural. The obstruction applies to a theory covering the specified Galois fields, rather than to an isolated realization over Q.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-001", "language": "English", "main_result": "An Artin-compatible functorial real cohomology for all arithmetic curves is obstructed by a quaternionic irreducible representation with negative root number and odd central multiplicity; every complexification of a real representation has even multiplicity of that type.", "novelty_claim": false, "paper_id": "PAPER-GEO65-001", "pdf_pages": 8, "publication_status": "Verified arXiv manifestation", "read_scope": "The advocate, skeptic, and director independently read and reconstructed the complete eight-page arXiv v2. Includes two routes to the original root-number inputs, full journal comparison, and verification of the quantifiers in context.", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "This rules out one real descent requirement with the Artin compatibility (2.12). A complex or graded quaternionic theory, in particular the positive pairing (2.7) on every spectral component, remains conjectural. The obstruction applies to a theory covering the specified Galois fields, rather than to an isolated realization over Q.", "source_locator": "§1 and §2, properties (2.1)–(2.12), Theorem 2.13 and (2.14)–(2.15)", "source_path": "sources/geometry65/2204_02714.pdf", "source_sha256": "abef52f91f14b13f53602c5af2add8e657caffbcee984b288d3eaf8adca50e37", "source_url": "https://arxiv.org/pdf/2204.02714v2", "substantive_reading": true, "title": "There is no \"Weil-\"cohomology theory with real coefficients for arithmetic curves", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:2204.02714v2", "version": "arXiv:2204.02714v2, author manuscript", "whole_work_read": true, "year": 2022, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "2204.02714", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-001"], "scope_update_history": [{"fields": {"audit_level": 3, "whole_work_read": true, "version": "arXiv:2204.02714v2, author manuscript", "source_sha256": "abef52f91f14b13f53602c5af2add8e657caffbcee984b288d3eaf8adca50e37", "read_scope": "The advocate, skeptic, and director independently read and reconstructed the complete eight-page arXiv v2. Includes two routes to the original root-number inputs, full journal comparison, and verification of the quantifiers in context."}, "evidence": "audits/adversarial_reviews/director_deninger_whole_round11.md", "track_file": "quality/zz_round11_source_scope_updates.jsonl"}], "scope_update_evidence": "audits/adversarial_reviews/director_deninger_whole_round11.md", "additional_scope_update_files": ["quality/zz_round11_source_scope_updates.jsonl"]}','There is no "Weil-"cohomology theory with real coefficients for arithmetic curves','["Christopher Deninger"]',NULL,'2022',3,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2204.02714v2, author manuscript','https://arxiv.org/pdf/2204.02714v2','abef52f91f14b13f53602c5af2add8e657caffbcee984b288d3eaf8adca50e37','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-002','corpus/bibliography.jsonl',492,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "point counts and exponential sums", "arxiv_id": null, "audit_level": 1, "authors": ["Nicholas M. Katz"], "bibliographic_verified": true, "canonical_url": "https://web.math.princeton.edu/~nmk/old/estcharsums.pdf", "classical_zeta_transfer_obstacle": "Rank-one Lang sheaf has weight zero and H_c^1 already has weights at most one by finite-field Weil estimates. The contribution proved here is geometric vanishing and dimension; missing for ζ is a comparable cohomology and a global spectral correspondence.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-002", "language": "English", "main_result": "For an n-dimensional finite étale algebra over F_q, a regular element x and nontrivial multiplicative character of its units extended by zero, the sum of chi(t−x) over F_q has modulus at most (n−1)√q. The field case is Theorem 1.", "novelty_claim": false, "paper_id": "PAPER-GEO65-002", "pdf_pages": 5, "publication_status": "published", "read_scope": "Read the four printed pages, both theorems, proof, remarks and references. Followed Lang torsor and norm compatibility, the split inertia calculation, cohomological dimension and imported Weil weight bound. The last question is left open in the note.", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Rank-one Lang sheaf has weight zero and H_c^1 already has weights at most one by finite-field Weil estimates. The contribution proved here is geometric vanishing and dimension; missing for ζ is a comparable cohomology and a global spectral correspondence.", "source_locator": "pp. 197–200, Theorems 1–2 and Remarks and Questions (1)–(2)", "source_path": "sources/geometry65/katz_character.pdf", "source_sha256": "d88116f6bc2159ffe82467158fd8aa3b8fcd0b80be576cf1e9c6e9d94ef78adb", "source_url": "https://web.math.princeton.edu/~nmk/old/estcharsums.pdf", "substantive_reading": true, "title": "An Estimate for Character Sums", "track_file": "papers/geometry65_records.jsonl", "venue": "Journal of the American Mathematical Society 2(2), 197–200", "version": "Original printed journal/proceedings scan from author repository", "whole_work_read": true, "year": 1989, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-002"]}','An Estimate for Character Sums','["Nicholas M. Katz"]',NULL,'1989',1,1,'selected_checkpoint_priority_work','full_text_accessed','Original printed journal/proceedings scan from author repository','https://web.math.princeton.edu/~nmk/old/estcharsums.pdf','d88116f6bc2159ffe82467158fd8aa3b8fcd0b80be576cf1e9c6e9d94ef78adb','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-003','corpus/bibliography.jsonl',493,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "point counts and exponential sums", "arxiv_id": null, "audit_level": 1, "authors": ["Nicholas M. Katz"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1006/ffta.1995.1029", "classical_zeta_transfer_obstacle": "Grothendieck–Ogg–Shafarevich calculates the dimension, with an Artin–Schreier cancellation in characteristic two. Weight ≤1 is imported and gives the bound; this local trace has no operator realizing the completed classical zero divisor.", "doi": "10.1006/ffta.1995.1029", "full_text_accessed": true, "id": "PAPER-GEO65-003", "language": "English", "main_result": "For b different from 0 and 1 and nontrivial multiplicative character, the indicated mixed additive/multiplicative sum, on G_m or a quadratic norm-one torus with excluded poles, is bounded by 4√q in odd characteristic and 2√q in characteristic 2.", "novelty_claim": false, "paper_id": "PAPER-GEO65-003", "pdf_pages": 4, "publication_status": "published", "read_scope": "Read all four printed pages with page OCR, both estimates, conductor calculation in each characteristic, norm-one torus base change, purity remark and final question. Imported the finite-field weight and étale trace results as cited.", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Grothendieck–Ogg–Shafarevich calculates the dimension, with an Artin–Schreier cancellation in characteristic two. Weight ≤1 is imported and gives the bound; this local trace has no operator realizing the completed classical zero divisor.", "source_locator": "pp. 395–398, Theorems 1–2, proofs and final remark", "source_path": "sources/geometry65/katz_note.pdf", "source_sha256": "aaaddab3aa6d8c95ee9884766acad11264cd5bdea25617fa2d89c2b8da397e64", "source_url": "https://web.math.princeton.edu/~nmk/old/noteexpsums.pdf", "substantive_reading": true, "title": "A Note on Exponential Sums", "track_file": "papers/geometry65_records.jsonl", "venue": "Finite Fields and Their Applications 1, 395–398", "version": "Original printed journal/proceedings scan from author repository", "whole_work_read": true, "year": 1995, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-003"]}','A Note on Exponential Sums','["Nicholas M. Katz"]',NULL,'1995',1,1,'selected_checkpoint_priority_work','full_text_accessed','Original printed journal/proceedings scan from author repository','https://web.math.princeton.edu/~nmk/old/noteexpsums.pdf','aaaddab3aa6d8c95ee9884766acad11264cd5bdea25617fa2d89c2b8da397e64','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-004','corpus/bibliography.jsonl',494,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "weights, monodromy and companions", "arxiv_id": null, "audit_level": 1, "authors": ["Nicholas M. Katz"], "bibliographic_verified": true, "canonical_url": "https://web.math.princeton.edu/~nmk/old/katzWorkofPDicm1978.pdf", "classical_zeta_transfer_obstacle": "An analogue needs control of global poles for the even tensor powers and a bound uniform in the Cartesian-power exponent. An isolated trace identity supplies neither input.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-004", "language": "English", "main_result": "Katz explains Deligne’s two distinct amplifications. Even tensor powers of the variable sheaf enter the Euler-factor argument, with Grothendieck’s cohomological determinant and symplectic monodromy controlling poles. An intermediate q^((n+1)/2) bound for smooth projective even-dimensional Y is then sharpened through arbitrary even Cartesian powers of X.", "novelty_claim": false, "paper_id": "PAPER-GEO65-004", "pdf_pages": 6, "publication_status": "published", "read_scope": "Read all six printed pages and §§I–IV of this expository address. Traced the distinctions among rationality, algebraicity, tensor-power amplification, and geometric semisimplicity. Imported technical ingredient theorems at the level presented.", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "An analogue needs control of global poles for the even tensor powers and a bound uniform in the Cartesian-power exponent. An isolated trace identity supplies neither input.", "source_locator": "§I, pp. 49–50, and §III, pp. 51–52", "source_path": "sources/geometry65/katz_workdeligne.pdf", "source_sha256": "8c1ad2a8c6a1688f0f82e2a0de80f9c0e1b60b9eb44df454618a4fd290f704d6", "source_url": "https://web.math.princeton.edu/~nmk/old/katzWorkofPDicm1978.pdf", "substantive_reading": true, "title": "The Work of Pierre Deligne", "track_file": "papers/geometry65_records.jsonl", "venue": "Proceedings of the ICM, Helsinki 1978, 47–52", "version": "Original printed journal/proceedings scan from author repository", "whole_work_read": true, "year": 1978, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-004"]}','The Work of Pierre Deligne','["Nicholas M. Katz"]',NULL,'1978',1,1,'selected_checkpoint_priority_work','full_text_accessed','Original printed journal/proceedings scan from author repository','https://web.math.princeton.edu/~nmk/old/katzWorkofPDicm1978.pdf','8c1ad2a8c6a1688f0f82e2a0de80f9c0e1b60b9eb44df454618a4fd290f704d6','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-005','corpus/bibliography.jsonl',495,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Lefschetz trace and arithmetic geometry", "arxiv_id": "1405.6381", "audit_level": 0, "authors": ["Yakov Varshavsky"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1405.6381", "classical_zeta_transfer_obstacle": "Existence and density in the correspondence require the finite-field Frobenius and both dominance conditions. The statement concerns intersection points.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-005", "language": "English", "main_result": "If X and C are irreducible finite-type schemes over the algebraic closure of F_q, X is defined over F_q, and both projections of c:C→X×X are dominant, the preimage of the graph of the q^n-Frobenius is nonempty for every sufficiently large n. The union of these preimages is Zariski dense in C.", "novelty_claim": false, "paper_id": "PAPER-GEO65-005", "pdf_pages": 20, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 0.1 and Corollary 0.2", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Existence and density in the correspondence require the finite-field Frobenius and both dominance conditions. The statement concerns intersection points.", "source_locator": "Theorem 0.1 and Corollary 0.2", "source_path": "sources/geometry65/1405_6381.pdf", "source_sha256": "50b1128b102eac2e5b4f3fdeb737d64b2b6e0cdcae340c8cf359b0cb8bc57e3c", "source_url": "https://arxiv.org/pdf/1405.6381v3", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Intersection of a correspondence with a graph of Frobenius", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:1405.6381v3", "version": "arXiv:1405.6381v3, author manuscript", "whole_work_read": false, "year": 2014, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "1405.6381", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-005"]}','Intersection of a correspondence with a graph of Frobenius','["Yakov Varshavsky"]',NULL,'2014',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1405.6381v3, author manuscript','https://arxiv.org/pdf/1405.6381v3','50b1128b102eac2e5b4f3fdeb737d64b2b6e0cdcae340c8cf359b0cb8bc57e3c','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-006','corpus/bibliography.jsonl',496,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Lefschetz trace and arithmetic geometry", "arxiv_id": "2003.06815", "audit_level": 0, "authors": ["Yakov Varshavsky"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2003.06815", "classical_zeta_transfer_obstacle": "Use the appropriate fixed-point or almost-fixed-point hypothesis, and the proper component hypothesis for numeric local terms.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-006", "language": "English", "main_result": "For a c-invariant closed Z and no fixed points in its punctured tubular neighborhood, each connected component β of Fix(c|Z) proper over k is also a connected component of Fix(c), and the local term for every c-morphism agrees with its restriction there. Part (a) requires no almost-fixed points and gives equality of trace classes on Fix(c|Z).", "novelty_claim": false, "paper_id": "PAPER-GEO65-006", "pdf_pages": 18, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 4.10(a)–(b), Corollary 4.11 and Theorem 5.9", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Use the appropriate fixed-point or almost-fixed-point hypothesis, and the proper component hypothesis for numeric local terms.", "source_locator": "Theorem 4.10(a)–(b), Corollary 4.11 and Theorem 5.9", "source_path": "sources/geometry65/2003_06815.pdf", "source_sha256": "6a2c74173b5cbd164d28eb5a7669af5102d0ecb570d108eb71969e7c10e0ed8e", "source_url": "https://arxiv.org/pdf/2003.06815v3", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Local terms for transversal intersections", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:2003.06815v3", "version": "arXiv:2003.06815v3, author manuscript", "whole_work_read": false, "year": 2020, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "2003.06815", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-006"]}','Local terms for transversal intersections','["Yakov Varshavsky"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2003.06815v3, author manuscript','https://arxiv.org/pdf/2003.06815v3','6a2c74173b5cbd164d28eb5a7669af5102d0ecb570d108eb71969e7c10e0ed8e','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-007','corpus/bibliography.jsonl',497,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Lefschetz trace and arithmetic geometry", "arxiv_id": "2012.14257", "audit_level": 0, "authors": ["Dennis Gaitsgory", "Yakov Varshavsky"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2012.14257", "classical_zeta_transfer_obstacle": "A categorical trace object over a finite field identifies local terms. Classical ζ needs an arithmetic trace realization and a positive form on its zero-bearing sector.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-007", "language": "English", "main_result": "Categorical true local term maps for correspondences on Artin stacks are functorial under the specified proper-safe pushforward and smooth or contracting pullback conditions; true and naive maps agree for Frobenius.", "novelty_claim": false, "paper_id": "PAPER-GEO65-007", "pdf_pages": 54, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 0.4 and 0.8", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "A categorical trace object over a finite field identifies local terms. Classical ζ needs an arithmetic trace realization and a positive form on its zero-bearing sector.", "source_locator": "Theorems 0.4 and 0.8", "source_path": "sources/geometry65/2012_14257.pdf", "source_sha256": "6f45fba3b68770287ca5e7ea6b3c7f0c3e70e50f78721a014a3db220c6bd641c", "source_url": "https://arxiv.org/pdf/2012.14257v2", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Local terms for the categorical trace", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:2012.14257v2", "version": "arXiv:2012.14257v2, author manuscript", "whole_work_read": false, "year": 2020, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "2012.14257", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-007"]}','Local terms for the categorical trace','["Dennis Gaitsgory", "Yakov Varshavsky"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2012.14257v2, author manuscript','https://arxiv.org/pdf/2012.14257v2','6f45fba3b68770287ca5e7ea6b3c7f0c3e70e50f78721a014a3db220c6bd641c','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-008','corpus/bibliography.jsonl',498,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Lefschetz trace and arithmetic geometry", "arxiv_id": "2102.07906", "audit_level": 0, "authors": ["D. Arinkin", "D. Gaitsgory", "D. Kazhdan", "S. Raskin", "N. Rozenblyum", "Y. Varshavsky"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2102.07906", "classical_zeta_transfer_obstacle": "The trace identity uses the specified nilpotent singular-support category and geometric Frobenius. It is a categorical identification, without a standalone coefficient weight bound.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-008", "language": "English", "main_result": "In the stated curve/group setup, the categorical trace of geometric Frobenius pushforward on Shv_Nilp(Bun_G) identifies canonically with compactly supported functions on Bun_G(F_q). With Hecke insertions the theorem identifies the two shtuka functors Rep(G-dual)_Ran→Vect.", "novelty_claim": false, "paper_id": "PAPER-GEO65-008", "pdf_pages": 53, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. §0.2, Main Theorems 0.2.6 and 0.3.10; Theorem 4.1.2 and Corollary 4.1.4", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "The trace identity uses the specified nilpotent singular-support category and geometric Frobenius. It is a categorical identification, without a standalone coefficient weight bound.", "source_locator": "§0.2, Main Theorems 0.2.6 and 0.3.10; Theorem 4.1.2 and Corollary 4.1.4", "source_path": "sources/geometry65/2102_07906.pdf", "source_sha256": "7ddb4a08ce4cae463d9e68f982a1b07147208dabc9411a6bfd9c4da2056c9da5", "source_url": "https://arxiv.org/pdf/2102.07906v2", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Automorphic functions as the trace of Frobenius", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:2102.07906v2", "version": "arXiv:2102.07906v2, author manuscript", "whole_work_read": false, "year": 2021, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "2102.07906", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-008"]}','Automorphic functions as the trace of Frobenius','["D. Arinkin", "D. Gaitsgory", "D. Kazhdan", "S. Raskin", "N. Rozenblyum", "Y. Varshavsky"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2102.07906v2, author manuscript','https://arxiv.org/pdf/2102.07906v2','7ddb4a08ce4cae463d9e68f982a1b07147208dabc9411a6bfd9c4da2056c9da5','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-009','corpus/bibliography.jsonl',499,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Lefschetz trace and arithmetic geometry", "arxiv_id": "2106.10682", "audit_level": 0, "authors": ["K. V. Shuddhodan", "Yakov Varshavsky"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2106.10682", "classical_zeta_transfer_obstacle": "Retain the geometric-degree uniformity, quasi-finiteness, irreducibility and dominance conditions at their respective steps.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-009", "language": "English", "main_result": "For embedded reduced X and reduced closed C in X×X^(q) with geometric degrees ≤δ, c₂ quasi-finite and q≥M(n,δ), the k-point intersection is finite and at most M q^dim C. If C is irreducible and c₁ dominant, the main term is deg(c₁)q^dim C/deg(c₂)_insep and the error is ≤M q^(dim C−1/2).", "novelty_claim": false, "paper_id": "PAPER-GEO65-009", "pdf_pages": 36, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Setup 0.2, Theorem 0.3(a)–(b), Corollary 0.6", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Retain the geometric-degree uniformity, quasi-finiteness, irreducibility and dominance conditions at their respective steps.", "source_locator": "Setup 0.2, Theorem 0.3(a)–(b), Corollary 0.6", "source_path": "sources/geometry65/2106_10682.pdf", "source_sha256": "e5cf03848e30c96cbda5a0fc738928585159a5a8728bd439d45b1f64141b6354", "source_url": "https://arxiv.org/pdf/2106.10682v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "The Hrushovski-Lang-Weil estimates", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:2106.10682v1", "version": "arXiv:2106.10682v1, author manuscript", "whole_work_read": false, "year": 2021, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "2106.10682", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-009"]}','The Hrushovski-Lang-Weil estimates','["K. V. Shuddhodan", "Yakov Varshavsky"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2106.10682v1, author manuscript','https://arxiv.org/pdf/2106.10682v1','e5cf03848e30c96cbda5a0fc738928585159a5a8728bd439d45b1f64141b6354','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-010','corpus/bibliography.jsonl',500,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Lefschetz trace and arithmetic geometry", "arxiv_id": "1006.3810", "audit_level": 0, "authors": ["Weizhe Zheng"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1006.3810", "classical_zeta_transfer_obstacle": "Six operations and pairing supply a trace formalism. A global arithmetic zero-bearing realization, with positivity and the archimedean local term in the same realization, is still needed.", "doi": "10.1007/s11425-015-4970-z", "full_text_accessed": true, "id": "PAPER-GEO65-010", "language": "English", "main_result": "Constructs étale six operations for the specified Deligne–Mumford stacks and proves the Verdier pairing trace compatibility for correspondences under the properness conditions in §8.", "novelty_claim": false, "paper_id": "PAPER-GEO65-010", "pdf_pages": 62, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 5.28 and Theorem 8.8 with Corollary 8.9", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Six operations and pairing supply a trace formalism. A global arithmetic zero-bearing realization, with positivity and the archimedean local term in the same realization, is still needed.", "source_locator": "Theorem 5.28 and Theorem 8.8 with Corollary 8.9", "source_path": "sources/geometry65/1006_3810.pdf", "source_sha256": "6cfe7442559bb02ceb6879c3bb081acd5e4b67ceab0946cd46fa2ddd9c9500fd", "source_url": "https://arxiv.org/pdf/1006.3810v5", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Six operations and Lefschetz-Verdier formula for Deligne-Mumford stacks", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:1006.3810v5", "version": "arXiv:1006.3810v5, author manuscript", "whole_work_read": false, "year": 2010, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "1006.3810", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-010"]}','Six operations and Lefschetz-Verdier formula for Deligne-Mumford stacks','["Weizhe Zheng"]',NULL,'2010',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1006.3810v5, author manuscript','https://arxiv.org/pdf/1006.3810v5','6cfe7442559bb02ceb6879c3bb081acd5e4b67ceab0946cd46fa2ddd9c9500fd','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-011','corpus/bibliography.jsonl',501,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Lefschetz trace and arithmetic geometry", "arxiv_id": "1106.0076", "audit_level": 0, "authors": ["Yoichi Mieda"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1106.0076", "classical_zeta_transfer_obstacle": "A local Jacquet–Langlands character identity only sees the specified local representations, modulo continuous contributions in the virtual quotient. A global spectral determinant with the ζ zeros and all multiplicities is missing.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-011", "language": "English", "main_result": "For a non-archimedean local field of characteristic zero and a smooth irreducible representation rho of the central division algebra of invariant 1/d, the Lubin–Tate tower''s virtual cohomology rho-part equals (−1)^(d−1)d JL(rho) modulo parabolic inductions.", "novelty_claim": false, "paper_id": "PAPER-GEO65-011", "pdf_pages": 14, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 1.1, 3.7, 5.5 and Corollaries 1.2–1.3", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "A local Jacquet–Langlands character identity only sees the specified local representations, modulo continuous contributions in the virtual quotient. A global spectral determinant with the ζ zeros and all multiplicities is missing.", "source_locator": "Theorems 1.1, 3.7, 5.5 and Corollaries 1.2–1.3", "source_path": "sources/geometry65/1106_0076.pdf", "source_sha256": "e3e24c529255e569b41ae52c02ef4134bf7926ac91857f48e0bee8439e225bfc", "source_url": "https://arxiv.org/pdf/1106.0076v1", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Lefschetz trace formula and l-adic cohomology of Lubin-Tate tower", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:1106.0076v1", "version": "arXiv:1106.0076v1, author manuscript", "whole_work_read": false, "year": 2011, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "1106.0076", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-011"]}','Lefschetz trace formula and l-adic cohomology of Lubin-Tate tower','["Yoichi Mieda"]',NULL,'2011',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1106.0076v1, author manuscript','https://arxiv.org/pdf/1106.0076v1','e3e24c529255e569b41ae52c02ef4134bf7926ac91857f48e0bee8439e225bfc','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-012','corpus/bibliography.jsonl',502,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Lefschetz trace and arithmetic geometry", "arxiv_id": "1011.1720", "audit_level": 0, "authors": ["Yoichi Mieda"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1011.1720", "classical_zeta_transfer_obstacle": "An arithmetic transfer needs a justified compactification and a full boundary calculation. Even the simpler rigid geometric case admits an unmatched trace when boundary hypotheses are removed.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-012", "language": "English", "main_result": "For a smooth separated finite-type adic space with compactification and proper extension of the endomorphism having no boundary fixed point, the compact-support trace is the cohomological fixed-point number. Translation of a closed rigid disk with empty interior fixed locus shows why dropping boundary control fails.", "novelty_claim": false, "paper_id": "PAPER-GEO65-012", "pdf_pages": 44, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Introduction counterexample and Theorem 1.1, Definition 2.6", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "An arithmetic transfer needs a justified compactification and a full boundary calculation. Even the simpler rigid geometric case admits an unmatched trace when boundary hypotheses are removed.", "source_locator": "Introduction counterexample and Theorem 1.1, Definition 2.6", "source_path": "sources/geometry65/1011_1720.pdf", "source_sha256": "959ad529b4c5ea014f740e11dabfbf9f0f4c8dec56ec01740bded7b7d9497752", "source_url": "https://arxiv.org/pdf/1011.1720v2", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Lefschetz trace formula for open adic spaces", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:1011.1720v2", "version": "arXiv:1011.1720v2, author manuscript", "whole_work_read": false, "year": 2010, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "1011.1720", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-012"]}','Lefschetz trace formula for open adic spaces','["Yoichi Mieda"]',NULL,'2010',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1011.1720v2, author manuscript','https://arxiv.org/pdf/1011.1720v2','959ad529b4c5ea014f740e11dabfbf9f0f4c8dec56ec01740bded7b7d9497752','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-013','corpus/bibliography.jsonl',503,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "weights, monodromy and companions", "arxiv_id": "1312.5884", "audit_level": 0, "authors": ["Daniel Caro"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1312.5884", "classical_zeta_transfer_obstacle": "Purity of E enters Theorem 2.7 as a hypothesis. The conclusion is a cohomology isomorphism, and any separate vanishing claim requires separate support.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-013", "language": "English", "main_result": "For projective f:X→Y of realizable varieties, iota-pure E in F-Hol(X/K), and η the Chern class of a relative hyperplane, H_t^(−r)f_+(E)→H_t^r f_+(E)(r) induced by η^r is an isomorphism for every positive integer r. Theorem 1.15 is the projective-space pushforward formula.", "novelty_claim": false, "paper_id": "PAPER-GEO65-013", "pdf_pages": 13, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 1.15 and 2.7; display (2.7.1)", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Purity of E enters Theorem 2.7 as a hypothesis. The conclusion is a cohomology isomorphism, and any separate vanishing claim requires separate support.", "source_locator": "Theorems 1.15 and 2.7; display (2.7.1)", "source_path": "sources/geometry65/1312_5884.pdf", "source_sha256": "4d291ad9f00cf973b2913cc678b585eea7e8b82658e542f568cfc505887e0b0b", "source_url": "https://arxiv.org/pdf/1312.5884v2", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Hard Lefschetz Theorem in p-adic cohomology", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:1312.5884v2", "version": "arXiv:1312.5884v2, author manuscript", "whole_work_read": false, "year": 2013, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "1312.5884", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-013"]}','Hard Lefschetz Theorem in p-adic cohomology','["Daniel Caro"]',NULL,'2013',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1312.5884v2, author manuscript','https://arxiv.org/pdf/1312.5884v2','4d291ad9f00cf973b2913cc678b585eea7e8b82658e542f568cfc505887e0b0b','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-014','corpus/bibliography.jsonl',504,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "weights, monodromy and companions", "arxiv_id": "1303.0662", "audit_level": 0, "authors": ["Tomoyuki Abe", "Daniel Caro"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1303.0662", "classical_zeta_transfer_obstacle": "This is a weight stability result for the given coefficient category. The tensor inequality is a lower bound for mixed inputs in the displayed conventions; any better exponent requires additional input.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-014", "language": "English", "main_result": "The iota-mixed subcategory of Frobenius overholonomic complexes on realizable varieties is stable under the six operations. In the source conventions f_+ and f^! preserve ≥w, f_! and f^+ preserve ≤w, duality exchanges ≤w with ≥−w, and tensor product sends (≥w,≥w′) to ≥w+w′. Intermediate extension of an immersion preserves pure Frobenius complexes and their weights.", "novelty_claim": false, "paper_id": "PAPER-GEO65-014", "pdf_pages": 65, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Introduction Main Theorem (i)–(ii); Theorem 4.1.3 and Corollary 4.2.4", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "This is a weight stability result for the given coefficient category. The tensor inequality is a lower bound for mixed inputs in the displayed conventions; any better exponent requires additional input.", "source_locator": "Introduction Main Theorem (i)–(ii); Theorem 4.1.3 and Corollary 4.2.4", "source_path": "sources/geometry65/1303_0662.pdf", "source_sha256": "208d757863b33943e2ea98c0bee2bc0b847f5f6f4d14fd3b14f1df3355c87ecc", "source_url": "https://arxiv.org/pdf/1303.0662v4", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Theory of weights in p-adic cohomology", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:1303.0662v4", "version": "arXiv:1303.0662v4, author manuscript", "whole_work_read": false, "year": 2013, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "1303.0662", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-014"]}','Theory of weights in p-adic cohomology','["Tomoyuki Abe", "Daniel Caro"]',NULL,'2013',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1303.0662v4, author manuscript','https://arxiv.org/pdf/1303.0662v4','208d757863b33943e2ea98c0bee2bc0b847f5f6f4d14fd3b14f1df3355c87ecc','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-015','corpus/bibliography.jsonl',505,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "automorphic trace and analytic bounds", "arxiv_id": "2311.15300", "audit_level": 0, "authors": ["Dan Ciubotaru", "Michael Harris"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2311.15300", "classical_zeta_transfer_obstacle": "Geometricity (Weil q-number eigenvalues) is an input. Keep the split-place restriction and exceptional points, and invoke stronger hypotheses separately if excluding them.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-015", "language": "English", "main_result": "Theorem 1.11 assumes nonzero m_U(π) and Conjectures 9.1 and 9.3 or a Lafforgue parametrization, and uses a split place with π_v in the specified complementary series plus a place with geometric π_u. At the resulting split places, the Satake real part is central or one of the listed exceptional points.", "novelty_claim": false, "paper_id": "PAPER-GEO65-015", "pdf_pages": 39, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.11, Definition 2.5, Theorem 8.5 and §9", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Geometricity (Weil q-number eigenvalues) is an input. Keep the split-place restriction and exceptional points, and invoke stronger hypotheses separately if excluding them.", "source_locator": "Theorem 1.11, Definition 2.5, Theorem 8.5 and §9", "source_path": "sources/geometry65/2311_15300.pdf", "source_sha256": "7261083b46cc8ec3fad81215250ff6bef47da05ef6054813572de21db10dc103", "source_url": "https://arxiv.org/pdf/2311.15300v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "On the generalized Ramanujan and Arthur conjectures over function fields", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:2311.15300v1", "version": "arXiv:2311.15300v1, author manuscript", "whole_work_read": false, "year": 2023, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "2311.15300", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-015"]}','On the generalized Ramanujan and Arthur conjectures over function fields','["Dan Ciubotaru", "Michael Harris"]',NULL,'2023',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2311.15300v1, author manuscript','https://arxiv.org/pdf/2311.15300v1','7261083b46cc8ec3fad81215250ff6bef47da05ef6054813572de21db10dc103','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-016','corpus/bibliography.jsonl',506,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "automorphic trace and analytic bounds", "arxiv_id": "1505.06043", "audit_level": 0, "authors": ["Luis Lomelí"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1505.06043", "classical_zeta_transfer_obstacle": "A single q and polynomial Whittaker normalizations produce rationality. The step from rationality or a right-half-plane holomorphy result to zero-modulus purity needs independent input.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-016", "language": "English", "main_result": "For the specified Langlands–Shahidi generic function-field data, L-functions have meromorphic continuation rational in q^(−s), and Proposition 6.3 assumes Ramanujan and proves holomorphy for Re(s)>1, whereas Theorem 6.5 proves the same half-plane result for the specified classical-group Rankin–Selberg pair with at most a simple pole at 1.", "novelty_claim": false, "paper_id": "PAPER-GEO65-016", "pdf_pages": 27, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.2, Proposition 6.3 and Theorem 6.5", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "A single q and polynomial Whittaker normalizations produce rationality. The step from rationality or a right-half-plane holomorphy result to zero-modulus purity needs independent input.", "source_locator": "Theorem 1.2, Proposition 6.3 and Theorem 6.5", "source_path": "sources/geometry65/1505_06043.pdf", "source_sha256": "a499783e811fbf4d57c431475d8fe76ccb408d43c1a4f96b75e8d80f055d64f5", "source_url": "https://arxiv.org/pdf/1505.06043v3", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "On the rationality and holomorphy of Langlands-Shahidi L-functions over function fields", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:1505.06043v3", "version": "arXiv:1505.06043v3, author manuscript", "whole_work_read": false, "year": 2015, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "1505.06043", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-016"]}','On the rationality and holomorphy of Langlands-Shahidi L-functions over function fields','["Luis Lomelí"]',NULL,'2015',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1505.06043v3, author manuscript','https://arxiv.org/pdf/1505.06043v3','a499783e811fbf4d57c431475d8fe76ccb408d43c1a4f96b75e8d80f055d64f5','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-017','corpus/bibliography.jsonl',507,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "weights, monodromy and companions", "arxiv_id": "1310.0528", "audit_level": 0, "authors": ["Tomoyuki Abe"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1310.0528", "classical_zeta_transfer_obstacle": "Distinguish the unconditional curve correspondence from the higher-dimensional companion statement conditional in this edition.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-017", "language": "English", "main_result": "For the function field of a geometrically connected proper smooth curve, Theorem 4.2.2 matches irreducible rank-r isocrystals of finite-order determinant on opens with cuspidal GL_r representations of finite-order central character. The unramified loci and Frobenius/Hecke eigenvalues agree. In the pinned edition, Theorem 4.4.5 gives a number field and ℓ≠p companions on smooth finite-type X assuming Conjecture 4.4.2.", "novelty_claim": false, "paper_id": "PAPER-GEO65-017", "pdf_pages": 134, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 4.2.2; Theorem 4.4.5 and Conjecture 4.4.2", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Distinguish the unconditional curve correspondence from the higher-dimensional companion statement conditional in this edition.", "source_locator": "Theorem 4.2.2; Theorem 4.4.5 and Conjecture 4.4.2", "source_path": "sources/geometry65/1310_0528.pdf", "source_sha256": "b890ef139fd51ce395bf1e373cdeaa1312dbcb95f76d56eff495f96df8c8dd29", "source_url": "https://arxiv.org/pdf/1310.0528v3", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Langlands correspondence for isocrystals and the existence of crystalline companions for curves", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:1310.0528v3", "version": "arXiv:1310.0528v3, author manuscript", "whole_work_read": false, "year": 2013, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "1310.0528", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-017"]}','Langlands correspondence for isocrystals and the existence of crystalline companions for curves','["Tomoyuki Abe"]',NULL,'2013',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1310.0528v3, author manuscript','https://arxiv.org/pdf/1310.0528v3','b890ef139fd51ce395bf1e373cdeaa1312dbcb95f76d56eff495f96df8c8dd29','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-018','corpus/bibliography.jsonl',508,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "weights, monodromy and companions", "arxiv_id": "1811.00204", "audit_level": 0, "authors": ["Kiran S. Kedlaya"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1811.00204", "classical_zeta_transfer_obstacle": "The modified conjecture does not assume X connected. Preserve the distinction between input ℓ and companion ℓ′, and between the curve case and higher dimension.", "doi": "10.46298/epiga.2022.6820", "full_text_accessed": true, "id": "PAPER-GEO65-018", "language": "English", "main_result": "For irreducible ℓ-adic coefficient objects of finite-order determinant on smooth finite-type X, Theorem 1.3 establishes parts (i)–(v) as written, allowing ℓ=p for the input. Part (i) is weight-zero purity and part (v) gives ℓ′≠p companions. Theorem 1.2 includes part (vi), crystalline companions, in dimension one.", "novelty_claim": false, "paper_id": "PAPER-GEO65-018", "pdf_pages": 30, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Conjecture 1.1, Theorems 1.2–1.3 and §3.3", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "The modified conjecture does not assume X connected. Preserve the distinction between input ℓ and companion ℓ′, and between the curve case and higher dimension.", "source_locator": "Conjecture 1.1, Theorems 1.2–1.3 and §3.3", "source_path": "sources/geometry65/1811_00204.pdf", "source_sha256": "2fdc1d48d9ddab8f12041b111611f4524d2f05fb842959c42d9ebf7cf8c181d7", "source_url": "https://arxiv.org/pdf/1811.00204v6", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Etale and crystalline companions, I", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:1811.00204v6", "version": "arXiv:1811.00204v6, author manuscript", "whole_work_read": false, "year": 2018, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "1811.00204", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-018"]}','Etale and crystalline companions, I','["Kiran S. Kedlaya"]',NULL,'2018',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1811.00204v6, author manuscript','https://arxiv.org/pdf/1811.00204v6','2fdc1d48d9ddab8f12041b111611f4524d2f05fb842959c42d9ebf7cf8c181d7','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-019','corpus/bibliography.jsonl',509,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "weights, monodromy and companions", "arxiv_id": "1607.07112", "audit_level": 0, "authors": ["Tomoyuki Abe", "Hélène Esnault"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1607.07112", "classical_zeta_transfer_obstacle": "The curve depends on the selected point; preserve the dense-open and finite-determinant conditions.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-019", "language": "English", "main_result": "An irreducible overconvergent F-isocrystal of finite determinant on a smooth geometrically connected scheme over k pulls back irreducibly along a suitable map from a smooth irreducible curve through each closed point of a dense open. This underlies the ℓ-adic companion theorem and preservation of irreducibility.", "novelty_claim": false, "paper_id": "PAPER-GEO65-019", "pdf_pages": 18, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Introduction Theorem 0.3; Theorems 3.10 and 4.2", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "The curve depends on the selected point; preserve the dense-open and finite-determinant conditions.", "source_locator": "Introduction Theorem 0.3; Theorems 3.10 and 4.2", "source_path": "sources/geometry65/1607_07112.pdf", "source_sha256": "bef937fee08f997e2d3154fe2e5351a45f1505c822441a5f1db5dc332db666c9", "source_url": "https://arxiv.org/pdf/1607.07112v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "A Lefschetz theorem for overconvergent isocrystals with Frobenius structure", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:1607.07112v1", "version": "arXiv:1607.07112v1, author manuscript", "whole_work_read": false, "year": 2016, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "1607.07112", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-019"]}','A Lefschetz theorem for overconvergent isocrystals with Frobenius structure','["Tomoyuki Abe", "Hélène Esnault"]',NULL,'2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1607.07112v1, author manuscript','https://arxiv.org/pdf/1607.07112v1','bef937fee08f997e2d3154fe2e5351a45f1505c822441a5f1db5dc332db666c9','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-020','corpus/bibliography.jsonl',510,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "weights, monodromy and companions", "arxiv_id": "1604.00660", "audit_level": 0, "authors": ["Vladimir Drinfeld", "Kiran Kedlaya"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1604.00660", "classical_zeta_transfer_obstacle": "These are p-adic generic slopes and adjacent-slope gaps. A complex absolute-value weight bound is a separate statement.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-020", "language": "English", "main_result": "For an indecomposable rank-n F-isocrystal on the stated smooth irreducible quasi-compact scheme over a perfect field of characteristic p>0, adjacent generic slopes differ by at most one. Full faithfulness of restriction to a dense open is used to rule out a decomposition coming from a larger gap.", "novelty_claim": false, "paper_id": "PAPER-GEO65-020", "pdf_pages": 36, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. §1.1.1, Theorem 1.1.5 and Corollary 1.1.7", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "These are p-adic generic slopes and adjacent-slope gaps. A complex absolute-value weight bound is a separate statement.", "source_locator": "§1.1.1, Theorem 1.1.5 and Corollary 1.1.7", "source_path": "sources/geometry65/1604_00660.pdf", "source_sha256": "d4e6c409f78e2ae25e3cadd932999807b3481af1aad5b4b52d273f0accd1c37a", "source_url": "https://arxiv.org/pdf/1604.00660v11", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Slopes of indecomposable F-isocrystals", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:1604.00660v11", "version": "arXiv:1604.00660v11, author manuscript", "whole_work_read": false, "year": 2016, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "1604.00660", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-020"]}','Slopes of indecomposable F-isocrystals','["Vladimir Drinfeld", "Kiran Kedlaya"]',NULL,'2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1604.00660v11, author manuscript','https://arxiv.org/pdf/1604.00660v11','d4e6c409f78e2ae25e3cadd932999807b3481af1aad5b4b52d273f0accd1c37a','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-021','corpus/bibliography.jsonl',511,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "weights, monodromy and companions", "arxiv_id": "math/0210149", "audit_level": 0, "authors": ["Kiran S. Kedlaya"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0210149", "classical_zeta_transfer_obstacle": "The two weight inequalities have different input directions and cohomology functors. The slope interval is independent of the statement of the complex weight bounds.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-021", "language": "English", "main_result": "For a separated finite-type F_q-scheme and iota-realizable overconvergent F-isocrystal E, mixedness ≤w gives compact-support rigid cohomology weight ≤w+i. When X is smooth, mixedness ≥w gives ordinary rigid cohomology weight ≥w+i. Theorem 6.7.1 separately bounds p-adic slopes.", "novelty_claim": false, "paper_id": "PAPER-GEO65-021", "pdf_pages": 58, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 6.6.2(a)–(b), Theorem 6.7.1 and background Theorem 6.5.3", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "The two weight inequalities have different input directions and cohomology functors. The slope interval is independent of the statement of the complex weight bounds.", "source_locator": "Theorem 6.6.2(a)–(b), Theorem 6.7.1 and background Theorem 6.5.3", "source_path": "sources/geometry65/math_0210149.pdf", "source_sha256": "b678f13ceb5b0d0b528e927a20187e344f2fd40552819a5d528f7d52ab3f1599", "source_url": "https://arxiv.org/pdf/math/0210149v3", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Fourier transforms and p-adic \"Weil II\"", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:math/0210149v3", "version": "arXiv:math/0210149v3, author manuscript", "whole_work_read": false, "year": 2002, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "math/0210149", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-021"]}','Fourier transforms and p-adic "Weil II"','["Kiran S. Kedlaya"]',NULL,'2002',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0210149v3, author manuscript','https://arxiv.org/pdf/math/0210149v3','b678f13ceb5b0d0b528e927a20187e344f2fd40552819a5d528f7d52ab3f1599','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-022','corpus/bibliography.jsonl',512,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "standard conjectures and intersection positivity", "arxiv_id": "2011.06563", "audit_level": 0, "authors": ["James S. Milne"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2011.06563", "classical_zeta_transfer_obstacle": "The statements mainly trace conditional algebraicity and positivity implications for projective smooth varieties over finite fields. A classical ζ correspondence on which the induced positive involution is an adjoint remains missing.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-022", "language": "English", "main_result": "The strong Lefschetz standard conjecture over finite fields implies the almost-Hodge assertion for abelian varieties, and over the algebraic closure of F_p implies full Tate and Hodge standard conjectures for abelian varieties; full Tate over that field implies the standard conjectures there.", "novelty_claim": false, "paper_id": "PAPER-GEO65-022", "pdf_pages": 13, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 1–3, §§1–4", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "The statements mainly trace conditional algebraicity and positivity implications for projective smooth varieties over finite fields. A classical ζ correspondence on which the induced positive involution is an adjoint remains missing.", "source_locator": "Theorems 1–3, §§1–4", "source_path": "sources/geometry65/2011_06563.pdf", "source_sha256": "4cc91cbd749dae168601997d85d57cba869a89168d93bab9c97e653c557046cb", "source_url": "https://arxiv.org/pdf/2011.06563v1", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Grothendieck''s standard conjecture of Lefschetz type over finite fields", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:2011.06563v1", "version": "arXiv:2011.06563v1, author manuscript", "whole_work_read": false, "year": 2020, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "2011.06563", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-022"]}','Grothendieck''s standard conjecture of Lefschetz type over finite fields','["James S. Milne"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2011.06563v1, author manuscript','https://arxiv.org/pdf/2011.06563v1','4cc91cbd749dae168601997d85d57cba869a89168d93bab9c97e653c557046cb','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-023','corpus/bibliography.jsonl',513,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "standard conjectures and intersection positivity", "arxiv_id": "2112.12815", "audit_level": 0, "authors": ["James S. Milne"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2112.12815", "classical_zeta_transfer_obstacle": "It extends verified positivity for particular algebraic cycles. Such cycles act on actual reductions of varieties; no ζ cohomological object or trace conjugation is provided.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-023", "language": "English", "main_result": "For the specified neat A and A_0 and CM elliptic B with products losing neatness, algebraicity of the indicated Weil classes yields Hodge, Tate and standard conjectures for powers of the mixed products as stated; Markman''s algebraicity result supplies low-dimensional cases.", "novelty_claim": false, "paper_id": "PAPER-GEO65-023", "pdf_pages": 26, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 0.1 and 3.1", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "It extends verified positivity for particular algebraic cycles. Such cycles act on actual reductions of varieties; no ζ cohomological object or trace conjugation is provided.", "source_locator": "Theorems 0.1 and 3.1", "source_path": "sources/geometry65/2112_12815.pdf", "source_sha256": "2a2c2787168aac00c24cb970bb7966c212b4d0a48f999123dcf94b5f3962c739", "source_url": "https://arxiv.org/pdf/2112.12815v2", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "The Tate and Standard Conjectures for Certain Abelian Varieties", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:2112.12815v2", "version": "arXiv:2112.12815v2, author manuscript", "whole_work_read": false, "year": 2021, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "2112.12815", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-023"]}','The Tate and Standard Conjectures for Certain Abelian Varieties','["James S. Milne"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2112.12815v2, author manuscript','https://arxiv.org/pdf/2112.12815v2','2a2c2787168aac00c24cb970bb7966c212b4d0a48f999123dcf94b5f3962c739','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-024','corpus/bibliography.jsonl',514,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "standard conjectures and intersection positivity", "arxiv_id": "2210.14001", "audit_level": 0, "authors": ["Giuseppe Ancona", "Adriano Marmora"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2210.14001", "classical_zeta_transfer_obstacle": "A negative index divisible by four still permits a positive negative index. Positivity needs an additional argument ruling it out.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-024", "language": "English", "main_result": "For the indicated CM-lifted hyperplane classes on abelian varieties and products of K3 surfaces, the negative index of the primitive numerical intersection form is divisible by four. The motivic version assumes supersingular special fiber and a CM form polarizing its Betti realization.", "novelty_claim": false, "paper_id": "PAPER-GEO65-024", "pdf_pages": 31, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 1.4(1)–(2), 1.5 and 3.2", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "A negative index divisible by four still permits a positive negative index. Positivity needs an additional argument ruling it out.", "source_locator": "Theorems 1.4(1)–(2), 1.5 and 3.2", "source_path": "sources/geometry65/2210_14001.pdf", "source_sha256": "e079b2fa12a91ab8116afa935a75ae6965cdfd47cfa6ec56a138ae4a21dce361", "source_url": "https://arxiv.org/pdf/2210.14001v3", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "The Hilbert symbol in the Hodge standard conjecture", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:2210.14001v3", "version": "arXiv:2210.14001v3, author manuscript", "whole_work_read": false, "year": 2022, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "2210.14001", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-024"]}','The Hilbert symbol in the Hodge standard conjecture','["Giuseppe Ancona", "Adriano Marmora"]',NULL,'2022',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2210.14001v3, author manuscript','https://arxiv.org/pdf/2210.14001v3','e079b2fa12a91ab8116afa935a75ae6965cdfd47cfa6ec56a138ae4a21dce361','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-025','corpus/bibliography.jsonl',515,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "standard conjectures and intersection positivity", "arxiv_id": "2510.21562", "audit_level": 0, "authors": ["Thomas Agugliaro"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2510.21562", "classical_zeta_transfer_obstacle": "Use the appropriate geometric simplicity, rank and CM assumptions for general powers.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-025", "language": "English", "main_result": "The Hodge standard conjecture holds for powers of simple prime-dimensional abelian varieties over the algebraic closure of F_p. In Theorem 1.4, geometrically simple A/F_q of dimension g, rank r and multiplicity m must have m odd, r≥mg−1, and CM by DF with D totally real and disjoint from the endomorphism center F. Corollary 1.3 treats abelian threefold powers over any field.", "novelty_claim": false, "paper_id": "PAPER-GEO65-025", "pdf_pages": 29, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 1.2 and 1.4, Corollary 1.3", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Use the appropriate geometric simplicity, rank and CM assumptions for general powers.", "source_locator": "Theorems 1.2 and 1.4, Corollary 1.3", "source_path": "sources/geometry65/2510_21562.pdf", "source_sha256": "c28ff66383992c91e94fa7f02c31d847fee0b0bd73acc1685ccb7795abb0bcc5", "source_url": "https://arxiv.org/pdf/2510.21562v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Standard conjecture of Hodge type for powers of abelian varieties", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:2510.21562v1", "version": "arXiv:2510.21562v1, author manuscript", "whole_work_read": false, "year": 2025, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "2510.21562", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-025"]}','Standard conjecture of Hodge type for powers of abelian varieties','["Thomas Agugliaro"]',NULL,'2025',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2510.21562v1, author manuscript','https://arxiv.org/pdf/2510.21562v1','c28ff66383992c91e94fa7f02c31d847fee0b0bd73acc1685ccb7795abb0bcc5','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-026','corpus/bibliography.jsonl',516,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "weights, monodromy and companions", "arxiv_id": "2303.05610", "audit_level": 0, "authors": ["Peter Wear"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2303.05610", "classical_zeta_transfer_obstacle": "This proves weight–monodromy in the stated geometric case, using equal-characteristic input. Transfer needs a realization and an appropriate specialization comparison.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-026", "language": "English", "main_result": "Weight–monodromy holds for geometrically connected proper smooth Y which is a set-theoretic complete intersection in an abelian variety A over a local field of residue characteristic p. The argument follows the perfectoid reduction to equal characteristic.", "novelty_claim": false, "paper_id": "PAPER-GEO65-026", "pdf_pages": 54, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1.2 and §6", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "This proves weight–monodromy in the stated geometric case, using equal-characteristic input. Transfer needs a realization and an appropriate specialization comparison.", "source_locator": "Theorem 1.1.2 and §6", "source_path": "sources/geometry65/2303_05610.pdf", "source_sha256": "dd6a59291a03e40272ef998de0c3b07d4beb3105bd665dd7756474822e0f6a99", "source_url": "https://arxiv.org/pdf/2303.05610v1", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Perfectoid covers of abelian varieties and the weight-monodromy conjecture", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:2303.05610v1", "version": "arXiv:2303.05610v1, author manuscript", "whole_work_read": false, "year": 2023, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "2303.05610", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-026"]}','Perfectoid covers of abelian varieties and the weight-monodromy conjecture','["Peter Wear"]',NULL,'2023',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2303.05610v1, author manuscript','https://arxiv.org/pdf/2303.05610v1','dd6a59291a03e40272ef998de0c3b07d4beb3105bd665dd7756474822e0f6a99','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-027','corpus/bibliography.jsonl',517,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "automorphic trace and analytic bounds", "arxiv_id": "2405.02998", "audit_level": 0, "authors": ["Tian An Wong"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2405.02998", "classical_zeta_transfer_obstacle": "Convolution-square positivity bounds the zero distribution with correction terms. An unconditional sign of the uncorrected Weil form on a core exhaustive for classical ζ is absent.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-027", "language": "English", "main_result": "For the specified maximal Levi of GL_n and unramified cuspidal data, a spectral term is written in terms of nontrivial Rankin–Selberg zeros plus logarithmic-derivative and local intertwiner contributions; an extra term is included in the ramified case.", "novelty_claim": false, "paper_id": "PAPER-GEO65-027", "pdf_pages": 13, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorem 1.1, Corollaries 1.2–1.3 and (1.2)", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Convolution-square positivity bounds the zero distribution with correction terms. An unconditional sign of the uncorrected Weil form on a core exhaustive for classical ζ is absent.", "source_locator": "Theorem 1.1, Corollaries 1.2–1.3 and (1.2)", "source_path": "sources/geometry65/2405_02998.pdf", "source_sha256": "c4706a1c6a4fc4154dacb14811d92c2246357ccfc05bb79d0aebea3f2818ced1", "source_url": "https://arxiv.org/pdf/2405.02998v1", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Zeroes of Rankin-Selberg L-functions and the trace formula", "track_file": "papers/geometry65_records.jsonl",