INSERT INTO "papers" VALUES('PAPER-GEO65-028','corpus/bibliography.jsonl',518,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "automorphic trace and analytic bounds", "arxiv_id": "1608.02296", "audit_level": 0, "authors": ["Tian An Wong"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1608.02296", "classical_zeta_transfer_obstacle": "The lower bound contains the normalized intertwining and other explicit terms. No dominance argument yields a nonnegative ζ form on all necessary test functions.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-028", "language": "English", "main_result": "Relates the SL_2 continuous spectral term to a sum over Artin–Hecke zeros and Weil-type distributions, and obtains an explicit lower bound for the ζ zero sum on the specified convolution tests.", "novelty_claim": false, "paper_id": "PAPER-GEO65-028", "pdf_pages": 22, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 1.1–1.2 and Corollary 1.3, equations (1.3)–(1.4)", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "The lower bound contains the normalized intertwining and other explicit terms. No dominance argument yields a nonnegative ζ form on all necessary test functions.", "source_locator": "Theorems 1.1–1.2 and Corollary 1.3, equations (1.3)–(1.4)", "source_path": "sources/geometry65/1608_02296.pdf", "source_sha256": "bc4c09e40a2e1d9d01797274bba875357f9d689688e288c1ba61ffd5aa01a7ae", "source_url": "https://arxiv.org/pdf/1608.02296v2", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Explicit formulas for the spectral side of the trace formula of SL(2)", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:1608.02296v2", "version": "arXiv:1608.02296v2, author manuscript", "whole_work_read": false, "year": 2016, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "1608.02296", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-028"]}','Explicit formulas for the spectral side of the trace formula of SL(2)','["Tian An Wong"]',NULL,'2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1608.02296v2, author manuscript','https://arxiv.org/pdf/1608.02296v2','bc4c09e40a2e1d9d01797274bba875357f9d689688e288c1ba61ffd5aa01a7ae','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
