INSERT INTO "papers" VALUES('PAPER-GEO65-034','corpus/bibliography.jsonl',524,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "number-field spectral transfer", "arxiv_id": "math/0703392", "audit_level": 0, "authors": ["Alain Connes", "Caterina Consani", "Matilde Marcolli"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0703392", "classical_zeta_transfer_obstacle": "The number-field trace realization does not supply positivity. A correspondence analogue of finite-field Riemann–Roch/intersection positivity for the trace pairing is a missing step.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-034", "language": "English", "main_result": "Constructs an adèle-class cohomological trace with local distribution terms; Proposition 6.2 makes its twisted trace-pairing positivity equivalent to RH for the Grössencharakter L-functions.", "novelty_claim": false, "paper_id": "PAPER-GEO65-034", "pdf_pages": 61, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 4.16 and 6.1, Proposition 6.2 and §7", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "The number-field trace realization does not supply positivity. A correspondence analogue of finite-field Riemann–Roch/intersection positivity for the trace pairing is a missing step.", "source_locator": "Theorems 4.16 and 6.1, Proposition 6.2 and §7", "source_path": "sources/geometry65/math_0703392.pdf", "source_sha256": "88c4e34577e5107f8be2dc8488a71976b94a4efb5ea03f93e9f7d60681c41dee", "source_url": "https://arxiv.org/pdf/math/0703392v1", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "The Weil proof and the geometry of the adeles class space", "track_file": "papers/geometry65_records.jsonl", "venue": "a