INSERT INTO "papers" VALUES('PAPER-GEO65-035','corpus/bibliography.jsonl',525,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "number-field spectral transfer", "arxiv_id": "math/0204194", "audit_level": 0, "authors": ["Christopher Deninger"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0204194", "classical_zeta_transfer_obstacle": "The model encodes a single-finite-field arithmetic dynamical suspension. Closed orbit lengths and archimedean contributions for all rational places would have to be realized in a common arithmetic flow.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-035", "language": "English", "main_result": "Proves trace and index identities for a described foliated flow model; a specialization recovers the explicit formula for the function field of an elliptic curve.", "novelty_claim": false, "paper_id": "PAPER-GEO65-035", "pdf_pages": 25, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 2.1–2.3 and 3.1, Corollary 3.2", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "The model encodes a single-finite-field arithmetic dynamical suspension. Closed orbit lengths and archimedean contributions for all rational places would have to be realized in a common arithmetic flow.", "source_locator": "Theorems 2.1–2.3 and 3.1, Corollary 3.2", "source_path": "sources/geometry65/math_0204194.pdf", "source_sha256": "a59eafedf367b975168961f228f033c657a840da9e859968024a94913859bac1", "source_url": "https://arxiv.org/pdf/math/0204194v1", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "On the nature of the \"explicit formulas\" in analytic number theory - a simple example", "track_file": "papers/geometry65_records.jsonl", "venue": "arX