INSERT INTO "papers" VALUES('PAPER-GEO65-036','corpus/bibliography.jsonl',526,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "number-field spectral transfer", "arxiv_id": "math/0204192", "audit_level": 0, "authors": ["Anton Deitmar", "Christopher Deninger"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0204192", "classical_zeta_transfer_obstacle": "This is an actual dynamical trace, whose periodic-orbit data come from an existing geometric map. One needs a directly constructed arithmetic flow with matched orbit data and spectral traces.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-036", "language": "English", "main_result": "Derives a dynamical Lefschetz trace formula on the specified generalized algebraic Anosov setting, using representation-theoretic and foliation cohomological traces.", "novelty_claim": false, "paper_id": "PAPER-GEO65-036", "pdf_pages": 25, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Theorems 4.1 and 5.3", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "This is an actual dynamical trace, whose periodic-orbit data come from an existing geometric map. One needs a directly constructed arithmetic flow with matched orbit data and spectral traces.", "source_locator": "Theorems 4.1 and 5.3", "source_path": "sources/geometry65/math_0204192.pdf", "source_sha256": "a5fb93dcedf63dced1515d290beaded80852e6fd9f28bee4b9c57d7709cae5a0", "source_url": "https://arxiv.org/pdf/math/0204192v2", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "A dynamical Lefschetz trace formula for algebraic Anosov diffeomorphisms", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:math/0204192v2", "version": "arXiv:math/0204192v2, a