INSERT INTO "papers" VALUES('PAPER-GEO65-043','corpus/bibliography.jsonl',533,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "point counts and exponential sums", "arxiv_id": "math/0305127", "audit_level": 0, "authors": ["Hélène Esnault", "Nicholas M. Katz"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0305127", "classical_zeta_transfer_obstacle": "Frobenius divisibility is an algebraic-integer statement. Cohomology vanishing or a complex square-root estimate requires additional input.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-043", "language": "English", "main_result": "If nonconstant factors f_i have degrees d_i and X⊂A^n is cut out by products of the f_i with nonnegative exponents, each compact-support Frobenius eigenvalue on X and on its complement is divisible as an algebraic integer by q^μ, where μ=max(0,ceil((n−Σd_i)/max d_i)). On complement H_c^(n+j), j≥1, Theorem 2.3 strengthens this to q^(j+μ(n−j;d_i)).", "novelty_claim": false, "paper_id": "PAPER-GEO65-043", "pdf_pages": 10, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Definition (1.3), Theorems 2.1–2.3 and 4.1", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Frobenius divisibility is an algebraic-integer statement. Cohomology vanishing or a complex square-root estimate requires additional input.", "source_locator": "Definition (1.3), Theorems 2.1–2.3 and 4.1", "source_path": "sources/geometry65/math_0305127.pdf", "source_sha256": "15257645927bbd774c5d4b9b96fa471749c3d8eaf796ee9f88671e940b09be1e", "source_url": "https://arxiv.org/pdf/math/0305127v2", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Cohomological divisibility and point count divisibility", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:math/0305127v2", "version": "arXiv:math/0305127v2, author manuscript", "whole_work_read": false, "year": 2003, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "math/0305127", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-043"]}','Cohomological divisibility and point count divisibility','["Hélène Esnault", "Nicholas M. Katz"]',NULL,'2003',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0305127v2, author manuscript','https://arxiv.org/pdf/math/0305127v2','15257645927bbd774c5d4b9b96fa471749c3d8eaf796ee9f88671e940b09be1e','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-044','corpus/bibliography.jsonl',534,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "number-field spectral transfer", "arxiv_id": "2504.15767", "audit_level": 0, "authors": ["Christopher Deninger"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2504.15767", "classical_zeta_transfer_obstacle": "An abstract realization of central multiplicities can be built from the prescribed root-number sectors. Number-theoretic realization and positive control of the entire nontrivial zero spectrum remain separate.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO65-044", "language": "English", "main_result": "Distinguishes an abstract existence and uniqueness up to isomorphism of functors modeling the predicted central Artin multiplicities using negative-root-number symplectic irreducibles from the requested natural arithmetic construction and predicted central-value formula.", "novelty_claim": false, "paper_id": "PAPER-GEO65-044", "pdf_pages": 18, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passage only. Prediction 2.13, Theorems 2.15–2.16 and §4", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "An abstract realization of central multiplicities can be built from the prescribed root-number sectors. Number-theoretic realization and positive control of the entire nontrivial zero spectrum remain separate.", "source_locator": "Prediction 2.13, Theorems 2.15–2.16 and §4", "source_path": "sources/geometry65/2504_15767.pdf", "source_sha256": "e1386f2b6ee6b35a5d0b8bcffb58a83ccfa1d1d25115b54249a282fdd43bd853", "source_url": "https://arxiv.org/pdf/2504.15767v3", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Is there a Birch and Swinnerton-Dyer conjecture for Dedekind zeta functions?", "track_file": "papers/geometry65_records.jsonl", "venue": "arXiv:2504.15767v3", "version": "arXiv:2504.15767v3, author manuscript", "whole_work_read": false, "year": 2025, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": "2504.15767", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-044"]}','Is there a Birch and Swinnerton-Dyer conjecture for Dedekind zeta functions?','["Christopher Deninger"]',NULL,'2025',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2504.15767v3, author manuscript','https://arxiv.org/pdf/2504.15767v3','e1386f2b6ee6b35a5d0b8bcffb58a83ccfa1d1d25115b54249a282fdd43bd853','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-045','corpus/bibliography.jsonl',535,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "weights, monodromy and companions", "arxiv_id": null, "audit_level": 0, "authors": ["Nicholas M. Katz"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.2307/2374386", "classical_zeta_transfer_obstacle": "The all-fiber claim concerns independence of Frobenius polynomials in the specified sense, and the proof uses wild twists and Deligne’s techniques.", "doi": "10.2307/2374386", "full_text_accessed": true, "id": "PAPER-GEO65-045", "language": "English", "main_result": "For a smooth geometrically connected curve Y over F_q, a smooth F_q-scheme X and a proper F_q-morphism f:X→Y, Katz proves ℓ-independence for the total space X and all fibers of f. Smoothness is a condition on X over F_q; f can have singular fibers.", "novelty_claim": false, "paper_id": "PAPER-GEO65-045", "pdf_pages": 28, "publication_status": "published", "read_scope": "Targeted passage only. Introductory theorem, pp. 201–202 and its definition of independence of ℓ", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "The all-fiber claim concerns independence of Frobenius polynomials in the specified sense, and the proof uses wild twists and Deligne’s techniques.", "source_locator": "Introductory theorem, pp. 201–202 and its definition of independence of ℓ", "source_path": "sources/geometry65/katz_wild.pdf", "source_sha256": "1c03b8d0df92205cc1d79be5f4cb08957061188fae5e8deeba49d39c578b35fb", "source_url": "https://web.math.princeton.edu/~nmk/old/wildramif.pdf", "substantive_reading": false, "theorem_statement_status": "targeted statement with selected hypotheses", "title": "Wild Ramification and Some Problems of “Independence of ℓ”", "track_file": "papers/geometry65_records.jsonl", "venue": "American Journal of Mathematics 105(1), 201–227", "version": "Original printed journal/proceedings scan from author repository", "whole_work_read": false, "year": 1983, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-045"]}','Wild Ramification and Some Problems of “Independence of ℓ”','["Nicholas M. Katz"]',NULL,'1983',0,0,'selected_checkpoint_priority_work','full_text_accessed','Original printed journal/proceedings scan from author repository','https://web.math.princeton.edu/~nmk/old/wildramif.pdf','1c03b8d0df92205cc1d79be5f4cb08957061188fae5e8deeba49d39c578b35fb','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-046','corpus/bibliography.jsonl',536,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "point counts and exponential sums", "arxiv_id": null, "audit_level": 0, "authors": ["Nicholas M. Katz"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.2307/2373389", "classical_zeta_transfer_obstacle": "Point-count divisibility and p-adic slope effects do not imply complex absolute values of a number-field global spectral generator.", "doi": "10.2307/2373389", "full_text_accessed": true, "id": "PAPER-GEO65-046", "language": "English", "main_result": "Gives an Ax–Katz divisibility bound q^mu for simultaneous zeros of prescribed nonconstant polynomials over a finite field, using the degree-dependent exponent defined in §0.", "novelty_claim": false, "paper_id": "PAPER-GEO65-046", "pdf_pages": 16, "publication_status": "published", "read_scope": "Targeted passage only. Theorem 1.0 and Theorem 2.1, pp. 485–487", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "Point-count divisibility and p-adic slope effects do not imply complex absolute values of a number-field global spectral generator.", "source_locator": "Theorem 1.0 and Theorem 2.1, pp. 485–487", "source_path": "sources/geometry65/katz_ax.pdf", "source_sha256": "79f414e2df6f2083cc08051296d38737ea8d8ab6866451277194681c44185e71", "source_url": "https://web.math.princeton.edu/~nmk/old/ax.pdf", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "On a Theorem of Ax", "track_file": "papers/geometry65_records.jsonl", "venue": "American Journal of Mathematics 93(2), 485–499", "version": "Original printed journal/proceedings scan from author repository", "whole_work_read": false, "year": 1971, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-046"]}','On a Theorem of Ax','["Nicholas M. Katz"]',NULL,'1971',0,0,'selected_checkpoint_priority_work','full_text_accessed','Original printed journal/proceedings scan from author repository','https://web.math.princeton.edu/~nmk/old/ax.pdf','79f414e2df6f2083cc08051296d38737ea8d8ab6866451277194681c44185e71','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO65-047','corpus/bibliography.jsonl',537,'full_text_accessed','papers/geometry65_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "point counts and exponential sums", "arxiv_id": null, "audit_level": 1, "authors": ["André Weil"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1073/pnas.34.5.204", "classical_zeta_transfer_obstacle": "The absolute values of reciprocal roots are imported from the function-field RH via the abelian extension''s curve zeta and a finite conductor degree. There is no arithmetic-cover factorization that gives the corresponding modulus control on the entire classical zero divisor.", "doi": "10.1073/pnas.34.5.204", "full_text_accessed": true, "id": "PAPER-GEO65-047", "language": "English", "main_result": "For the indicated mixed ray-class character on the rational function field, the linear coefficient of its polynomial L-series is the exponential sum up to sign, yielding (N+d−2)√q under the stated conductor and nontriviality setup. The odd-characteristic Kloosterman specialization gives 2√q.", "novelty_claim": false, "paper_id": "PAPER-GEO65-047", "pdf_pages": 4, "publication_status": "published", "read_scope": "Read the complete contribution across pp. 204–207 using OCR and scan, including the conductor construction, coefficient comparison and both specializations. The cited class field, degree and curve RH results are external inputs.", "record_path": "papers/geometry65_notes.md", "result_status": "Source-stated result scoped to its hypotheses. No proof of classical RH.", "selection_reason": "The absolute values of reciprocal roots are imported from the function-field RH via the abelian extension''s curve zeta and a finite conductor degree. There is no arithmetic-cover factorization that gives the corresponding modulus control on the entire classical zero divisor.", "source_locator": "pp. 204–207, equations (1)–(5) and last estimates", "source_path": "sources/geometry65/weil_exponential.pdf", "source_sha256": "166cf7a04237ad116c72cad84bbccbb27443db03d4a493896a3bf08fdffc83f3", "source_url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC1079093/", "substantive_reading": true, "title": "On Some Exponential Sums", "track_file": "papers/geometry65_records.jsonl", "venue": "PNAS 34(5), 204–207", "version": "Original PNAS pages 204–207, assembled from the four PMC journal page images", "whole_work_read": true, "year": 1948, "admission_evidence": "quality/round11_source_admission_receipt.json", "original_pending_file": "quality/pending_round11/geometry65_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO65-047"]}','On Some Exponential Sums','["André Weil"]',NULL,'1948',1,1,'selected_checkpoint_priority_work','full_text_accessed','Original PNAS pages 204–207, assembled from the four PMC journal page images','https://pmc.ncbi.nlm.nih.gov/articles/PMC1079093/','166cf7a04237ad116c72cad84bbccbb27443db03d4a493896a3bf08fdffc83f3','papers/geometry65_notes.md','papers/geometry65_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-001','corpus/bibliography.jsonl',538,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "motivic positivity", "arxiv_id": null, "audit_level": 1, "authors": ["Jean-Pierre Serre"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.2307/1970088", "classical_zeta_transfer_obstacle": "The argument constructs actual Hermitian positivity by Hodge theory on a geometric cohomology. The arithmetic proposal lacks a counterpart for the complete zeta zero-bearing domain.", "doi": "10.2307/1970088", "full_text_accessed": true, "id": "PAPER-GEO70-001", "language": "French", "main_result": "Serre’s Theorem 1 assumes a smooth irreducible complex projective V and a morphism f:V→V with f*E algebraically equivalent to qE for a hyperplane section E and a positive integer q. The eigenvalues on H^r(V,C) have modulus q^(r/2). In Theorem 2 a complex-linear bidegree-preserving correspondence commuting with conjugation between compact connected Kähler manifolds of the same dimension must preserve the Lefschetz filtrations L^a ker L^b in condition (c). The degree-r trace of the map composed with its indicated adjoint is its squared Hilbert–Schmidt norm.", "novelty_claim": false, "paper_id": "PAPER-GEO70-001", "pdf_pages": 4, "publication_status": "published", "read_scope": "Read all three article pages including both theorems, normalization, duality, and primitive compatibility. Reconstructed the unitary rescaling and Hilbert–Schmidt argument from the cited Kähler identities.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The argument constructs actual Hermitian positivity by Hodge theory on a geometric cohomology. The arithmetic proposal lacks a counterpart for the complete zeta zero-bearing domain.", "source_locator": "Annals pp. 392–394, Theorems 1–2 and condition (c)", "source_path": "sources/geometry68/serre-annals.pdf", "source_sha256": "1aa00f7f9ce3763cc06ce414bddc38ee499da2b9fc7880841f4305d5a7137232", "source_url": "https://www.math.purdue.edu/~tongliu/seminar/Weil/Serre-1960.pdf", "substantive_reading": true, "title": "Analogues kählériens de certaines conjectures de Weil", "track_file": "papers/geometry70_records.jsonl", "venue": "Annals of Mathematics 71(2), 392–394", "version": "Original journal scan", "whole_work_read": true, "year": 1960, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-001"]}','Analogues kählériens de certaines conjectures de Weil','["Jean-Pierre Serre"]',NULL,'1960',1,1,'selected_checkpoint_priority_work','full_text_accessed','Original journal scan','https://www.math.purdue.edu/~tongliu/seminar/Weil/Serre-1960.pdf','1aa00f7f9ce3763cc06ce414bddc38ee499da2b9fc7880841f4305d5a7137232','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-002','corpus/bibliography.jsonl',539,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Artin and Galois realization", "arxiv_id": null, "audit_level": 1, "authors": ["Jacques Queyrut"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.24033/msmf.140", "classical_zeta_transfer_obstacle": "A quaternionic Artin constituent with odd central order obstructs ordinary real G-equivariant complexification when its central spectral multiplicity is prescribed. This leaves the isolated rational zeta problem open.", "doi": "10.24033/msmf.140", "full_text_accessed": true, "id": "PAPER-GEO70-002", "language": "French", "main_result": "For a finite Galois extension of number fields with group G, every virtual character of G realizable over R has Artin root number +1. The proof reduces by induction to real-realizable terms of degrees one and two, with the faithful dihedral case handled via a quadratic extension and a character trivial on the base idèles. The paper credits independent proofs by Fröhlich and Queyrut.", "novelty_claim": false, "paper_id": "PAPER-GEO70-002", "pdf_pages": 4, "publication_status": "published", "read_scope": "Read pp. 133–135 in full, including distinction between real-valued and real-realizable, degree-two induction reduction, the local-to-global idèle calculation, and references. Brauer–Witt and the local constant formula are imported.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "A quaternionic Artin constituent with odd central order obstructs ordinary real G-equivariant complexification when its central spectral multiplicity is prescribed. This leaves the isolated rational zeta problem open.", "source_locator": "Mémoires pp. 133–135, main theorem and quadratic idèle-class theorem", "source_path": "sources/geometry68/queyrut.pdf", "source_sha256": "99eeef3ede61f91ad6c7074d5f0defae1cf1eb85b53c3ddb2b75c7db34f2790f", "source_url": "https://www.numdam.org/item/MSMF_1974__37__133_0.pdf", "substantive_reading": true, "title": "Sur l’équation fonctionnelle des séries L d’Artin pour des caractères réels", "track_file": "papers/geometry70_records.jsonl", "venue": "Mémoires de la S.M.F. 37, 133–135", "version": "Original journal scan Numdam", "whole_work_read": true, "year": 1974, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-002"]}','Sur l’équation fonctionnelle des séries L d’Artin pour des caractères réels','["Jacques Queyrut"]',NULL,'1974',1,1,'selected_checkpoint_priority_work','full_text_accessed','Original journal scan Numdam','https://www.numdam.org/item/MSMF_1974__37__133_0.pdf','99eeef3ede61f91ad6c7074d5f0defae1cf1eb85b53c3ddb2b75c7db34f2790f','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-003','corpus/bibliography.jsonl',540,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "motivic positivity", "arxiv_id": "2202.03804", "audit_level": 1, "authors": ["Teruhisa Koshikawa"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2202.03804", "classical_zeta_transfer_obstacle": "This proves actual intersection positivity on particular numerical classes, with existing Frobenius data used to isolate the exotic part. None creates an all-place trace or positive pairing for ζ.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-003", "language": "English", "main_result": "For a simple abelian variety A with prime dimension or an absolutely simple almost ordinary finite-field specialization, numerical Hodge positivity holds for A×A and A×E for E elliptic. The odd-dimensional angle-rank g−1 or g finite-field theorem isolates exceptional middle-degree motives and uses Ancona’s rank-two lifting positivity theorem.", "novelty_claim": false, "paper_id": "PAPER-GEO70-003", "pdf_pages": 6, "publication_status": "Verified arXiv manifestation", "read_scope": "Read all six v1 pages and bibliography. Followed the angle-rank relation, localization to exotic middle-degree pieces, rank-two splitting, CM lifting and the imported Ancona result. Preserved its numerical-equivalence conclusion.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "This proves actual intersection positivity on particular numerical classes, with existing Frobenius data used to isolate the exotic part. None creates an all-place trace or positive pairing for ζ.", "source_locator": "Theorems 1.1 and 1.4, Lemma 2.2, Proposition 3.5 and Theorem 4.1", "source_path": "quality/pending_round12/geometry70_sources/2202_03804.pdf", "source_sha256": "337d588209f235cc1b06bd023647422c1d56f32bf36c81a6a6359f9febae049b", "source_url": "https://arxiv.org/pdf/2202.03804v1", "substantive_reading": true, "title": "The numerical Hodge standard conjecture for the square of a simple abelian variety of prime dimension", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:2202.03804v1", "version": "arXiv:2202.03804v1 author manuscript", "whole_work_read": true, "year": 2022, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "arxiv": "2202.03804", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-003"]}','The numerical Hodge standard conjecture for the square of a simple abelian variety of prime dimension','["Teruhisa Koshikawa"]',NULL,'2022',1,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2202.03804v1 author manuscript','https://arxiv.org/pdf/2202.03804v1','337d588209f235cc1b06bd023647422c1d56f32bf36c81a6a6359f9febae049b','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-004','corpus/bibliography.jsonl',541,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Artin and Galois realization", "arxiv_id": null, "audit_level": 0, "authors": ["Sami Omar"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1080/10586458.2001.10504445", "classical_zeta_transfer_obstacle": "The exact sign gives an odd-order witness for the real-descent obstruction when the spectral model imposes the corresponding Artin multiplicity in a number-field sector.", "doi": "10.1080/10586458.2001.10504445", "full_text_accessed": true, "id": "PAPER-GEO70-004", "language": "English", "main_result": "For an octic quaternion extension of Q the unique degree-two irreducible Artin factor is entire by Proposition 3.5. Table 1 row 3 reports a totally real example with exact root number −1, giving odd central order by Theorem 3.8. The tame normal-integral-basis criterion is credited to Fröhlich and Martinet. Exact odd order and the separate numerical evidence for order one have different status.", "novelty_claim": false, "paper_id": "PAPER-GEO70-004", "pdf_pages": 9, "publication_status": "published", "read_scope": "Targeted passages only (Proposition 3.5 and Theorems 3.6–3.8, printed p. 239; Table 1 p. 243). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The exact sign gives an odd-order witness for the real-descent obstruction when the spectral model imposes the corresponding Artin multiplicity in a number-field sector.", "source_locator": "Proposition 3.5 and Theorems 3.6–3.8, printed p. 239; Table 1 p. 243", "source_path": "sources/geometry68/omar-emis.pdf", "source_sha256": "41a2518dd9d9c82a9d0dae1b2c42f6ae2a9f06f0c1b1ba81e41a1f9faf0bb7f8", "source_url": "https://www.maths.tcd.ie/EMIS/journals/EM/restricted/10/10.2/omar.ps", "substantive_reading": false, "title": "On Artin L-Functions for Octic Quaternion Fields", "track_file": "papers/geometry70_records.jsonl", "venue": "Experimental Mathematics 10(2), 237–245", "version": "Original journal PostScript converted locally to PDF; original-byte receipt geometry68", "whole_work_read": false, "year": 2001, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-004"]}','On Artin L-Functions for Octic Quaternion Fields','["Sami Omar"]',NULL,'2001',0,0,'selected_checkpoint_priority_work','full_text_accessed','Original journal PostScript converted locally to PDF; original-byte receipt geometry68','https://www.maths.tcd.ie/EMIS/journals/EM/restricted/10/10.2/omar.ps','41a2518dd9d9c82a9d0dae1b2c42f6ae2a9f06f0c1b1ba81e41a1f9faf0bb7f8','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-005','corpus/bibliography.jsonl',542,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "motivic positivity", "arxiv_id": null, "audit_level": 0, "authors": ["James S. Milne"], "bibliographic_verified": true, "canonical_url": "https://www.jmilne.org/math/articles/1994aP.pdf", "classical_zeta_transfer_obstacle": "A coefficient category admitting quaternionic odd sectors avoids impossible ordinary real descent. It does not produce a number-field cohomology with the requisite zero multiplicities.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-005", "language": "English", "main_result": "Example 1.7 describes integer-graded complex vector spaces with a graded antilinear map whose square on degree m is (−1)^m, with its canonical homogeneous polarization. Theorem 1.18 concerns numerical motives over F = algebraic closure of F_p. The category is semisimple Tannakian over Q, and under Tate hypothesis (1.14) the indicated étale and crystalline realizations are fully faithful tensor functors after scalar extension.", "novelty_claim": false, "paper_id": "PAPER-GEO70-005", "pdf_pages": 58, "publication_status": "published", "read_scope": "Targeted passages only (Example 1.7, Theorem 1.18 and §1 construction). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "A coefficient category admitting quaternionic odd sectors avoids impossible ordinary real descent. It does not produce a number-field cohomology with the requisite zero multiplicities.", "source_locator": "Example 1.7, Theorem 1.18 and §1 construction", "source_path": "sources/geometry68/milne-motives.pdf", "source_sha256": "29d03e8ceeaaa2696d529d167722ce03ea3199eac752e3fe32df534d2362feb9", "source_url": "https://www.jmilne.org/math/articles/1994aP.pdf", "substantive_reading": false, "title": "Motives over Finite Fields", "track_file": "papers/geometry70_records.jsonl", "venue": "Motives, Proc. Symp. Pure Math. 55(1), 401–459", "version": "Author-hosted copy of chapter", "whole_work_read": false, "year": 1994, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-005"]}','Motives over Finite Fields','["James S. Milne"]',NULL,'1994',0,0,'selected_checkpoint_priority_work','full_text_accessed','Author-hosted copy of chapter','https://www.jmilne.org/math/articles/1994aP.pdf','29d03e8ceeaaa2696d529d167722ce03ea3199eac752e3fe32df534d2362feb9','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-006','corpus/bibliography.jsonl',543,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "motivic positivity", "arxiv_id": null, "audit_level": 0, "authors": ["Pierre Deligne", "James S. Milne"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1007/978-3-540-38955-2_4", "classical_zeta_transfer_obstacle": "The input includes an already constructed polarized category. Applying the theorem to proposed arithmetic cohomology would require precisely that input and a trace identity with ζ.", "doi": "10.1007/978-3-540-38955-2_4", "full_text_accessed": true, "id": "PAPER-GEO70-006", "language": "English", "main_result": "For a real algebraic Tannakian category endowed with a polarization whose parity element has order two, gives the exact faithful functor to a graded real/quaternionic category respecting parity and polarizations, unique up to isomorphism.", "novelty_claim": false, "paper_id": "PAPER-GEO70-006", "pdf_pages": 72, "publication_status": "published", "read_scope": "Targeted passages only (Theorem 4.29 and immediately preceding construction of V0). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The input includes an already constructed polarized category. Applying the theorem to proposed arithmetic cohomology would require precisely that input and a trace identity with ζ.", "source_locator": "Theorem 4.29 and immediately preceding construction of V0", "source_path": "sources/geometry68/deligne-milne.pdf", "source_sha256": "48f8af5249081217fc4a806414a764d9d69d66eff9092ddd8e2cf0ea078579e8", "source_url": "https://www.math.columbia.edu/~dejong/tannakian/Deligne-Milne-Tannakian-Categories.pdf", "substantive_reading": false, "title": "Tannakian Categories", "track_file": "papers/geometry70_records.jsonl", "venue": "Hodge Cycles, Motives, and Shimura Varieties, LNM 900, 101–228", "version": "Corrected 2012 TeX edition with original theorem numbers", "whole_work_read": false, "year": 1982, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-006"]}','Tannakian Categories','["Pierre Deligne", "James S. Milne"]',NULL,'1982',0,0,'selected_checkpoint_priority_work','full_text_accessed','Corrected 2012 TeX edition with original theorem numbers','https://www.math.columbia.edu/~dejong/tannakian/Deligne-Milne-Tannakian-Categories.pdf','48f8af5249081217fc4a806414a764d9d69d66eff9092ddd8e2cf0ea078579e8','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-007','corpus/bibliography.jsonl',544,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "dg-ga/9512002", "audit_level": 0, "authors": ["Anton Deitmar"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/dg-ga/9512002", "classical_zeta_transfer_obstacle": "The regularized determinant uses cohomology of an actual flow on the specified space. Identifying prime orbits and archimedean contributions with a classical-ζ model would require a new arithmetic construction.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-007", "language": "English", "main_result": "For the geodesic flow on the unit sphere bundle of a compact odd-dimensional hyperbolic manifold of curvature −1 and a finite-dimensional unitary representation φ of Γ, Cφ has closed differentials. If the corresponding flat bundle is acyclic, Theorem 1.1 identifies the alternating log determinant of the generator with minus the regularized weighted orbit-index sum modulo 2πiZ. Theorem 2.1 gives meromorphic continuation of the Ruelle product and, in the acyclic case, the determinant identity with an exponential of an odd polynomial.", "novelty_claim": false, "paper_id": "PAPER-GEO70-007", "pdf_pages": 9, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (§1, Theorem 1.1; §2 Theorem 2.1). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The regularized determinant uses cohomology of an actual flow on the specified space. Identifying prime orbits and archimedean contributions with a classical-ζ model would require a new arithmetic construction.", "source_locator": "§1, Theorem 1.1; §2 Theorem 2.1", "source_path": "quality/pending_round12/geometry70_sources/dg-ga_9512002.pdf", "source_sha256": "001ee9969b5401b527542a320e6588f875cb79b1d9da1bbce76b11680215adbf", "source_url": "https://arxiv.org/pdf/dg-ga/9512002v1", "substantive_reading": false, "title": "A Lefschetz formula for flows", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:dg-ga/9512002v1", "version": "arXiv:dg-ga/9512002v1 author manuscript", "whole_work_read": false, "year": 1995, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "dg-ga/9512002", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-007"]}','A Lefschetz formula for flows','["Anton Deitmar"]',NULL,'1995',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:dg-ga/9512002v1 author manuscript','https://arxiv.org/pdf/dg-ga/9512002v1','001ee9969b5401b527542a320e6588f875cb79b1d9da1bbce76b11680215adbf','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-008','corpus/bibliography.jsonl',545,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "math/0204110", "audit_level": 0, "authors": ["Christopher Deninger"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0204110", "classical_zeta_transfer_obstacle": "The theorem concerns a compact manifold and an everywhere-transverse flow without fixed points. A prime-orbit model would also need a justified archimedean contribution and a spectral space identifying classical ζ zeros.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-008", "language": "English", "main_result": "In §3.2 X is compact and oriented, the foliation has codimension one and the flow is everywhere transverse, hence has no fixed points. With nondegenerate periodic orbits, Theorem 3.3 (Álvarez López–Kordyukov) gives the alternating trace on all real times, with Connes’ Euler-characteristic term at zero and signed orbit terms at both positive and negative iterates. Theorem 3.4 gives a strongly continuous group for compatible flows and self-adjointness of −iΘ when the flow operators are orthogonal. Corollary 3.5 uses an everywhere-transverse nondegenerate compatible flow, a dense leaf on a compact three-manifold and leafwise conformality to express the distribution using eigenvalues. The paper remarks that the corollary’s hypotheses force the conformal exponent to vanish.", "novelty_claim": false, "paper_id": "PAPER-GEO70-008", "pdf_pages": 32, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 3.3–3.4 and Corollary 3.5). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The theorem concerns a compact manifold and an everywhere-transverse flow without fixed points. A prime-orbit model would also need a justified archimedean contribution and a spectral space identifying classical ζ zeros.", "source_locator": "Theorems 3.3–3.4 and Corollary 3.5", "source_path": "quality/pending_round12/geometry70_sources/math_0204110.pdf", "source_sha256": "eda801980bce22252521afceeaaf8e57391b56288c93ba8a2abb48ee3dc0e0b6", "source_url": "https://arxiv.org/pdf/math/0204110v1", "substantive_reading": false, "title": "Number theory and dynamical systems on foliated spaces", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0204110v1", "version": "arXiv:math/0204110v1 author manuscript", "whole_work_read": false, "year": 2002, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0204110", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-008"]}','Number theory and dynamical systems on foliated spaces','["Christopher Deninger"]',NULL,'2002',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0204110v1 author manuscript','https://arxiv.org/pdf/math/0204110v1','eda801980bce22252521afceeaaf8e57391b56288c93ba8a2abb48ee3dc0e0b6','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-009','corpus/bibliography.jsonl',546,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "math/0505354", "audit_level": 0, "authors": ["C. Deninger"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0505354", "classical_zeta_transfer_obstacle": "Local determinant realizations are compatible with Euler factors but do not construct a global cohomology whose generator has the completed zeta zeros.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-009", "language": "English", "main_result": "Proposition 3.1 gives an inverse regularized determinant for each local ζ-factor of Q, including infinity. Theorem 3.3 gives a separate complex-vector-space construction from ℓ-adic cohomology for algebraic F_p-schemes realizing (7), with Poincaré duality for regular connected projective equidimensional X. The proposed comparison (9) reduces there to the Tate conjecture. The mixed-characteristic dynamical cohomology discussed next is hypothetical.", "novelty_claim": false, "paper_id": "PAPER-GEO70-009", "pdf_pages": 48, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Proposition 3.1 and Theorem 3.3). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "Local determinant realizations are compatible with Euler factors but do not construct a global cohomology whose generator has the completed zeta zeros.", "source_locator": "Proposition 3.1 and Theorem 3.3", "source_path": "quality/pending_round12/geometry70_sources/math_0505354.pdf", "source_sha256": "2099b4d47919d0bed0d13e0ab14be4a8a1b692ba84bc4c09552500185470c877", "source_url": "https://arxiv.org/pdf/math/0505354v1", "substantive_reading": false, "title": "Arithmetic Geometry and Analysis on Foliated Spaces", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0505354v1", "version": "arXiv:math/0505354v1 author manuscript", "whole_work_read": false, "year": 2005, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0505354", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-009"]}','Arithmetic Geometry and Analysis on Foliated Spaces','["C. Deninger"]',NULL,'2005',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0505354v1 author manuscript','https://arxiv.org/pdf/math/0505354v1','2099b4d47919d0bed0d13e0ab14be4a8a1b692ba84bc4c09552500185470c877','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-010','corpus/bibliography.jsonl',547,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "0709.2801", "audit_level": 0, "authors": ["C. Deninger"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/0709.2801", "classical_zeta_transfer_obstacle": "The positive-time index excludes zero/negative-time terms and uses a conformal hypothesis. The special-value theorem does not attach an operator to classical ζ.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-010", "language": "English", "main_result": "Theorem 5 assumes the preceding everywhere-transverse codimension-one manifold setup, dimension three, a dense leaf and a leafwise conformal metric. It gives a degree-one eigenvalue expression on Re ρ=α/2 and, with nondegenerate periodic orbits, a trace identity on positive times. The text notes that its hypotheses force α=0. Theorem 8 gives acyclicity for the cup-product complex on the real cohomology of the oriented odd-dimensional manifold with a leafwise isometric flow. Its order and leading coefficient formulas for ζ_R additionally assume existence of the regularized determinants.", "novelty_claim": false, "paper_id": "PAPER-GEO70-010", "pdf_pages": 13, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 5 and 8). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The positive-time index excludes zero/negative-time terms and uses a conformal hypothesis. The special-value theorem does not attach an operator to classical ζ.", "source_locator": "Theorems 5 and 8", "source_path": "quality/pending_round12/geometry70_sources/0709_2801.pdf", "source_sha256": "877f6e69f908e014264fc550978b57a92443ec0f0ae7f8e8a7dd4d425ca1a1c4", "source_url": "https://arxiv.org/pdf/0709.2801v1", "substantive_reading": false, "title": "Analogies between analysis on foliated spaces and arithmetic geometry", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:0709.2801v1", "version": "arXiv:0709.2801v1 author manuscript", "whole_work_read": false, "year": 2007, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "0709.2801", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-010"]}','Analogies between analysis on foliated spaces and arithmetic geometry','["C. Deninger"]',NULL,'2007',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:0709.2801v1 author manuscript','https://arxiv.org/pdf/0709.2801v1','877f6e69f908e014264fc550978b57a92443ec0f0ae7f8e8a7dd4d425ca1a1c4','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-011','corpus/bibliography.jsonl',548,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "1807.06400", "audit_level": 0, "authors": ["Christopher Deninger"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1807.06400", "classical_zeta_transfer_obstacle": "Orbit packets do not provide the leafwise cohomology and archimedean trace required by the spectral proposal. With prescribed Artin central multiplicities in the quaternionic sectors, ordinary real G-equivariant complexification may face a separate parity obstruction.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-011", "language": "English", "main_result": "In the paper’s integral normal finite-type flat arithmetic-scheme construction, the dynamical systems have no fixed points. Closed points x index packets of periodic orbits of length log N(x); one packet can contain multiple orbits. Theorem 7.10 supplies continuous, R_{>0}-equivariant bijections from disjoint unions of the specified generic and Frobenius-suspended injective-character pieces to the full systems. The theorem does not assert a homeomorphism for these disjoint unions. Full admissibility and topological hypotheses are incompletely extracted.", "novelty_claim": false, "paper_id": "PAPER-GEO70-011", "pdf_pages": 119, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Introduction, Theorems 6.1 and 7.10, packet description). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "Orbit packets do not provide the leafwise cohomology and archimedean trace required by the spectral proposal. With prescribed Artin central multiplicities in the quaternionic sectors, ordinary real G-equivariant complexification may face a separate parity obstruction.", "source_locator": "Introduction, Theorems 6.1 and 7.10, packet description", "source_path": "quality/pending_round12/geometry70_sources/1807_06400.pdf", "source_sha256": "edd0bc8c2efb601ed7574e8eceae40e8cde21d0e4b2bc8c4ce7e60d8e1f82a09", "source_url": "https://arxiv.org/pdf/1807.06400v4", "substantive_reading": false, "title": "Dynamical systems for arithmetic schemes", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1807.06400v4", "version": "arXiv:1807.06400v4 author manuscript", "whole_work_read": false, "year": 2018, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1807.06400", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-011"]}','Dynamical systems for arithmetic schemes','["Christopher Deninger"]',NULL,'2018',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1807.06400v4 author manuscript','https://arxiv.org/pdf/1807.06400v4','edd0bc8c2efb601ed7574e8eceae40e8cde21d0e4b2bc8c4ce7e60d8e1f82a09','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-012','corpus/bibliography.jsonl',549,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "math/0204274", "audit_level": 0, "authors": ["Christopher Deninger"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0204274", "classical_zeta_transfer_obstacle": "An exact identity for the given arithmetic étale endomorphism is a real-place comparison. It does not calculate the prime and archimedean terms of the completed ζ explicit formula from one generator.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-012", "language": "English", "main_result": "With ℓ≠2 and the arithmetic étale setup preceding Theorem 2.1, the alternating compact-support trace is zero. If U=X is proper over Spec Z, ordinary compactified cohomology with j_*F is compared to the real analytic locus, with a local trace formula for generically smooth X and nondegenerate fixed points on X∞. Theorem 2.5 instead concerns a manifold carrying a flow, with a commuting finite-order automorphism and the prescribed sheaf data. Full standing hypotheses for that separate formula are incompletely extracted.", "novelty_claim": false, "paper_id": "PAPER-GEO70-012", "pdf_pages": 23, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 2.1, equations (5)–(7); Theorem 2.5 comparison). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "An exact identity for the given arithmetic étale endomorphism is a real-place comparison. It does not calculate the prime and archimedean terms of the completed ζ explicit formula from one generator.", "source_locator": "Theorem 2.1, equations (5)–(7); Theorem 2.5 comparison", "source_path": "quality/pending_round12/geometry70_sources/math_0204274.pdf", "source_sha256": "2aca40bbfaf26ef4dcd08e3e50e590f0c347fca13cac40023b1f800bfb4d1179", "source_url": "https://arxiv.org/pdf/math/0204274v1", "substantive_reading": false, "title": "A note on arithmetic topology and dynamical systems", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0204274v1", "version": "arXiv:math/0204274v1 author manuscript", "whole_work_read": false, "year": 2002, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0204274", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-012"]}','A note on arithmetic topology and dynamical systems','["Christopher Deninger"]',NULL,'2002',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0204274v1 author manuscript','https://arxiv.org/pdf/math/0204274v1','2aca40bbfaf26ef4dcd08e3e50e590f0c347fca13cac40023b1f800bfb4d1179','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-013','corpus/bibliography.jsonl',550,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zeta special values", "arxiv_id": "math/0302121", "audit_level": 0, "authors": ["F. Baldassarri", "C. Deninger", "N. Naumann"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0302121", "classical_zeta_transfer_obstacle": "Finite algebraic geometric symmetry gives a functional equation. It does not yield RH for an arithmetic two-variable analogue or any full global ζ spectral identity.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-013", "language": "English", "main_result": "Theorem 2 treats a smooth projective geometrically irreducible genus-g curve over K admitting a line bundle of degree one. For the paper’s motivic measure the denominator is (1−T)(1−uT) and the numerator satisfies P_{2g−i}(u)=u^{g−i}P_i(u), P_0=1, P_{2g}=u^g, and P(1,u)=μ(Pic^0). Theorem 3 states the absolute irreducibility criterion μ(Pic^0)≠0 in its field-valued, genus-at-least-one setup. Its proof invokes Theorem 2(d).", "novelty_claim": false, "paper_id": "PAPER-GEO70-013", "pdf_pages": 11, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 2(a)–(d), Theorem 3). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "Finite algebraic geometric symmetry gives a functional equation. It does not yield RH for an arithmetic two-variable analogue or any full global ζ spectral identity.", "source_locator": "Theorem 2(a)–(d), Theorem 3", "source_path": "quality/pending_round12/geometry70_sources/math_0302121.pdf", "source_sha256": "f6af4784750842d9950009cd9aec34be930314481ee1de61fb97ff1fdbdbe8e5", "source_url": "https://arxiv.org/pdf/math/0302121v1", "substantive_reading": false, "title": "A motivic version of Pellikaan''s two variable zeta function", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0302121v1", "version": "arXiv:math/0302121v1 author manuscript", "whole_work_read": false, "year": 2003, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0302121", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-013"]}','A motivic version of Pellikaan''s two variable zeta function','["F. Baldassarri", "C. Deninger", "N. Naumann"]',NULL,'2003',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0302121v1 author manuscript','https://arxiv.org/pdf/math/0302121v1','f6af4784750842d9950009cd9aec34be930314481ee1de61fb97ff1fdbdbe8e5','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-014','corpus/bibliography.jsonl',551,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "motivic positivity", "arxiv_id": "1001.1621", "audit_level": 0, "authors": ["C. Deninger"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1001.1621", "classical_zeta_transfer_obstacle": "Known positivity of the height pairing on rational points controls only that identified sector conditionally. It does not establish positivity on a zero-bearing global cohomology.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-014", "language": "English", "main_result": "Example 5 concerns an elliptic curve E/Q. In the proposed arithmetic cohomology the commutation of Hodge star and evolution in middle degree would give θ=1+S with S skew-symmetric. On the 1-eigenspace the Hodge pairing would identify, via the conjectural Abel–Jacobi isomorphism, with the negative of the negative-definite Néron–Tate pairing in the source’s normalization.", "novelty_claim": false, "paper_id": "PAPER-GEO70-014", "pdf_pages": 11, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (§§2–3 and Example 5, pp. 9–10). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "Known positivity of the height pairing on rational points controls only that identified sector conditionally. It does not establish positivity on a zero-bearing global cohomology.", "source_locator": "§§2–3 and Example 5, pp. 9–10", "source_path": "quality/pending_round12/geometry70_sources/1001_1621.pdf", "source_sha256": "f3b0fde0fa557ee5c522193236c3e21cc101e2f570c055ca79c5e0ce95d4c6e3", "source_url": "https://arxiv.org/pdf/1001.1621v1", "substantive_reading": false, "title": "The Hilbert-Polya strategy and height pairings", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1001.1621v1", "version": "arXiv:1001.1621v1 author manuscript", "whole_work_read": false, "year": 2010, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1001.1621", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-014"]}','The Hilbert-Polya strategy and height pairings','["C. Deninger"]',NULL,'2010',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1001.1621v1 author manuscript','https://arxiv.org/pdf/1001.1621v1','f3b0fde0fa557ee5c522193236c3e21cc101e2f570c055ca79c5e0ce95d4c6e3','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-015','corpus/bibliography.jsonl',552,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zeta special values", "arxiv_id": "math/0210269", "audit_level": 0, "authors": ["Christopher Deninger"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0210269", "classical_zeta_transfer_obstacle": "Regularized products in terms of zeros can be formed from the analytic function itself. An independently constructed generator with the required adjoint relation and all-zero identification is missing.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-015", "language": "English", "main_result": "For fixed complex w over the stated number-field setup, the two-variable zeta and H1 factor are 1/(2π)-zeta regularized, in the paper’s precise product sense.", "novelty_claim": false, "paper_id": "PAPER-GEO70-015", "pdf_pages": 39, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Proposition 3.2 and Theorem 5.2). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "Regularized products in terms of zeros can be formed from the analytic function itself. An independently constructed generator with the required adjoint relation and all-zero identification is missing.", "source_locator": "Proposition 3.2 and Theorem 5.2", "source_path": "quality/pending_round12/geometry70_sources/math_0210269.pdf", "source_sha256": "92016937fa58b47a44359396516c2b3ee6170f7ac8730ff0182f0825bdda6a7e", "source_url": "https://arxiv.org/pdf/math/0210269v1", "substantive_reading": false, "title": "Two-variable zeta functions and regularized products", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0210269v1", "version": "arXiv:math/0210269v1 author manuscript", "whole_work_read": false, "year": 2002, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0210269", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-015"]}','Two-variable zeta functions and regularized products','["Christopher Deninger"]',NULL,'2002',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0210269v1 author manuscript','https://arxiv.org/pdf/math/0210269v1','92016937fa58b47a44359396516c2b3ee6170f7ac8730ff0182f0825bdda6a7e','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-016','corpus/bibliography.jsonl',553,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zeta special values", "arxiv_id": "math/0407480", "audit_level": 0, "authors": ["Caterina Consani", "Matilde Marcolli"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0407480", "classical_zeta_transfer_obstacle": "The determinant is a local gamma-factor identity. It gives no prime orbit trace or global RH spectral operator.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-016", "language": "English", "main_result": "Proposition 3.2 concerns the cone of the archimedean monodromy operator on the paper’s complexes. In §3.2, the known identification of archimedean cohomology with inertia invariants and the Ray–Singer inverse determinant formula express local Γ-factors. Proposition 3.3 identifies the inverse determinant with the (−1)^{m+n}-weighted product of complex local factors in (3.19), using Φ restricted to inertia invariants and the insertion σ^L(w)^2 in the spectral trace. Precise complex hypotheses are incompletely extracted.", "novelty_claim": false, "paper_id": "PAPER-GEO70-016", "pdf_pages": 28, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Propositions 3.2–3.3, equation (3.19)). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "The determinant is a local gamma-factor identity. It gives no prime orbit trace or global RH spectral operator.", "source_locator": "Propositions 3.2–3.3, equation (3.19)", "source_path": "quality/pending_round12/geometry70_sources/math_0407480.pdf", "source_sha256": "17835e99e942f727a23a3fa318377c81f72b14052424565b9ec49806cb51d1af", "source_url": "https://arxiv.org/pdf/math/0407480v1", "substantive_reading": false, "title": "Archimedean cohomology revisited", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0407480v1", "version": "arXiv:math/0407480v1 author manuscript", "whole_work_read": false, "year": 2004, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0407480", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-016"]}','Archimedean cohomology revisited','["Caterina Consani", "Matilde Marcolli"]',NULL,'2004',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0407480v1 author manuscript','https://arxiv.org/pdf/math/0407480v1','17835e99e942f727a23a3fa318377c81f72b14052424565b9ec49806cb51d1af','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-017','corpus/bibliography.jsonl',554,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "math/0508642", "audit_level": 0, "authors": ["Anton Deitmar"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0508642", "classical_zeta_transfer_obstacle": "Finite-dimensional fixed-point cohomology and dynamical zeta determinants concern given maps or flows, with checkable orbit data. They supply no construction with all classical ζ zeros.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-017", "language": "English", "main_result": "Presents the Lefschetz determinant for strongly regular self-maps of a compact manifold with fixed-point indices all one and treats the stated suspension and geodesic-flow analogues. Only a synopsis of the cited result is extracted here; full auxiliary hypotheses and secondary statements are incomplete.", "novelty_claim": false, "paper_id": "PAPER-GEO70-017", "pdf_pages": 19, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 1.1–1.2, 2.1 and 5.2). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "Finite-dimensional fixed-point cohomology and dynamical zeta determinants concern given maps or flows, with checkable orbit data. They supply no construction with all classical ζ zeros.", "source_locator": "Theorems 1.1–1.2, 2.1 and 5.2", "source_path": "quality/pending_round12/geometry70_sources/math_0508642.pdf", "source_sha256": "03a3cc506ba7aedf72ce16e566ee072a7301f2f0ded9bb306056a2f645f387f0", "source_url": "https://arxiv.org/pdf/math/0508642v9", "substantive_reading": false, "title": "Lefschetz formulae and zeta functions", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0508642v9", "version": "arXiv:math/0508642v9 author manuscript", "whole_work_read": false, "year": 2005, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0508642", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-017"]}','Lefschetz formulae and zeta functions','["Anton Deitmar"]',NULL,'2005',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0508642v9 author manuscript','https://arxiv.org/pdf/math/0508642v9','03a3cc506ba7aedf72ce16e566ee072a7301f2f0ded9bb306056a2f645f387f0','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-018','corpus/bibliography.jsonl',555,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "math/0505405", "audit_level": 0, "authors": ["Anton Deitmar"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0505405", "classical_zeta_transfer_obstacle": "An exact local representation-theoretic identity on a p-adic quotient does not identify any classical ζ zero-bearing trace.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-018", "language": "English", "main_result": "For a neat discrete cocompact subgroup of the specified p-adic group, the Lefschetz formula compares the cohomological spectral term and centralizer Euler characteristics on the geometric side for uniformly smooth test functions supported in the negative chamber with the given integrability. Only a synopsis of the cited result is extracted here; full auxiliary hypotheses and secondary statements are incomplete.", "novelty_claim": false, "paper_id": "PAPER-GEO70-018", "pdf_pages": 18, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 3.1 and Corollary 3.2). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "An exact local representation-theoretic identity on a p-adic quotient does not identify any classical ζ zero-bearing trace.", "source_locator": "Theorem 3.1 and Corollary 3.2", "source_path": "quality/pending_round12/geometry70_sources/math_0505405.pdf", "source_sha256": "b010dbe4a05b55f615ce968901a02de5ea03ecd5cbc0c93f2acdc239ff50d516", "source_url": "https://arxiv.org/pdf/math/0505405v1", "substantive_reading": false, "title": "Lefschetz formulae for p-adic groups", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0505405v1", "version": "arXiv:math/0505405v1 author manuscript", "whole_work_read": false, "year": 2005, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0505405", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-018"]}','Lefschetz formulae for p-adic groups','["Anton Deitmar"]',NULL,'2005',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0505405v1 author manuscript','https://arxiv.org/pdf/math/0505405v1','b010dbe4a05b55f615ce968901a02de5ea03ecd5cbc0c93f2acdc239ff50d516','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-019','corpus/bibliography.jsonl',556,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "2003.00758", "audit_level": 0, "authors": ["Anton Deitmar"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2003.00758", "classical_zeta_transfer_obstacle": "The proved convergence is on the convergence side of the zeta problem. An analogous limit there would not ensure zero recovery in the critical strip.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-019", "language": "English", "main_result": "For a sequence of torsion-free cocompact lattices Γ_n in PSL₂(R), uniform discreteness and Plancherel convergence imply that (Z''_n/Z_n)(s)/vol(Γ_n\\G) tends to zero on Re s>1. This vanishing conversely implies Plancherel convergence without assuming uniform discreteness. In either case the convergence is uniform on Re s≥α for every α>1.", "novelty_claim": false, "paper_id": "PAPER-GEO70-019", "pdf_pages": 13, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 2.2, pp. 5–6). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The proved convergence is on the convergence side of the zeta problem. An analogous limit there would not ensure zero recovery in the critical strip.", "source_locator": "Theorem 2.2, pp. 5–6", "source_path": "quality/pending_round12/geometry70_sources/2003_00758.pdf", "source_sha256": "be745b72d00bcd9c7a3d96f4d4427d04f794bb70a4a7ca406d96bc26a4a20e1b", "source_url": "https://arxiv.org/pdf/2003.00758v1", "substantive_reading": false, "title": "Benjamini-Schramm convergence and zeta functions", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:2003.00758v1", "version": "arXiv:2003.00758v1 author manuscript", "whole_work_read": false, "year": 2020, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "2003.00758", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-019"]}','Benjamini-Schramm convergence and zeta functions','["Anton Deitmar"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2003.00758v1 author manuscript','https://arxiv.org/pdf/2003.00758v1','be745b72d00bcd9c7a3d96f4d4427d04f794bb70a4a7ca406d96bc26a4a20e1b','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-020','corpus/bibliography.jsonl',557,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "2112.13566", "audit_level": 0, "authors": ["Anton Deitmar"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2112.13566", "classical_zeta_transfer_obstacle": "Twisted spectral expansions may include signed multiplicities and depend on an existing locally symmetric system. Their determinant relation is not a positive realization of classical ζ.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-020", "language": "English", "main_result": "For the cocompact locally symmetric setup with finite-dimensional non-unitary twist, gives a Lefschetz trace formula and meromorphic continuation of the geometric Selberg product, with orders given by spectral multiplicities in the stated alternating formula. Only a synopsis of the cited result is extracted here; full auxiliary hypotheses and secondary statements are incomplete.", "novelty_claim": false, "paper_id": "PAPER-GEO70-020", "pdf_pages": 24, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Proposition 1.9, Theorem 3.14 and Theorem 4.5). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "Twisted spectral expansions may include signed multiplicities and depend on an existing locally symmetric system. Their determinant relation is not a positive realization of classical ζ.", "source_locator": "Proposition 1.9, Theorem 3.14 and Theorem 4.5", "source_path": "quality/pending_round12/geometry70_sources/2112_13566.pdf", "source_sha256": "402758aa7df6042791e207ab504fad752149c55c29d61eee67935a67e7993c4a", "source_url": "https://arxiv.org/pdf/2112.13566v2", "substantive_reading": false, "title": "Geometric zeta functions with non-unitary twists", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:2112.13566v2", "version": "arXiv:2112.13566v2 author manuscript", "whole_work_read": false, "year": 2021, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "2112.13566", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-020"]}','Geometric zeta functions with non-unitary twists','["Anton Deitmar"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2112.13566v2 author manuscript','https://arxiv.org/pdf/2112.13566v2','402758aa7df6042791e207ab504fad752149c55c29d61eee67935a67e7993c4a','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-021','corpus/bibliography.jsonl',558,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "math/0407509", "audit_level": 0, "authors": ["Anton Deitmar"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0407509", "classical_zeta_transfer_obstacle": "Actual finite Hecke adjacency provides the determinant. There is no analogous finite or convergent infinite complex with determinant equal to the completed classical zeta function.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-021", "language": "English", "main_result": "For the specified cocompact regular quotient of the PGL(3) building, the zeta reduces to a quotient with a power of a determinant in the two Hecke operators in the numerator, built using orientation and cycle data. Only a synopsis of the cited result is extracted here; full auxiliary hypotheses and secondary statements are incomplete.", "novelty_claim": false, "paper_id": "PAPER-GEO70-021", "pdf_pages": 16, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 0.1 and Theorems 3.1, 3.6). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "Actual finite Hecke adjacency provides the determinant. There is no analogous finite or convergent infinite complex with determinant equal to the completed classical zeta function.", "source_locator": "Theorem 0.1 and Theorems 3.1, 3.6", "source_path": "quality/pending_round12/geometry70_sources/math_0407509.pdf", "source_sha256": "92ad7f6e3aa5bdd07f5f5fa885fef45ee1f0b1498628219e4ae1fd755610809c", "source_url": "https://arxiv.org/pdf/math/0407509v2", "substantive_reading": false, "title": "The Ihara-Selberg zeta function for PGL(3) and Hecke operators", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0407509v2", "version": "arXiv:math/0407509v2 author manuscript", "whole_work_read": false, "year": 2004, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0407509", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-021"]}','The Ihara-Selberg zeta function for PGL(3) and Hecke operators','["Anton Deitmar"]',NULL,'2004',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0407509v2 author manuscript','https://arxiv.org/pdf/math/0407509v2','92ad7f6e3aa5bdd07f5f5fa885fef45ee1f0b1498628219e4ae1fd755610809c','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-022','corpus/bibliography.jsonl',559,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "1402.4759", "audit_level": 0, "authors": ["Antonius Deitmar", "Ming-Hsuan Kang"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1402.4759", "classical_zeta_transfer_obstacle": "Explicit cusp operator estimates justify this particular infinite determinant. The same estimates have not been obtained for a prime arithmetic flow realizing ζ, and rationality alone gives no purity.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-022", "language": "English", "main_result": "For cuspidal non-uniform tree lattices, the Ihara product converges near u=0 to a rational function through determinant-class operators and the stated trace/determinant identities. Only a synopsis of the cited result is extracted here; full auxiliary hypotheses and secondary statements are incomplete.", "novelty_claim": false, "paper_id": "PAPER-GEO70-022", "pdf_pages": 35, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 2.2, 4.3, 5.1 and 6.1). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "Explicit cusp operator estimates justify this particular infinite determinant. The same estimates have not been obtained for a prime arithmetic flow realizing ζ, and rationality alone gives no purity.", "source_locator": "Theorems 2.2, 4.3, 5.1 and 6.1", "source_path": "quality/pending_round12/geometry70_sources/1402_4759.pdf", "source_sha256": "b31464b17a23ea693b5feeb577f583dad335e6d9b061551a7340e76e95b6c182", "source_url": "https://arxiv.org/pdf/1402.4759v4", "substantive_reading": false, "title": "Tree-lattice zeta functions and class numbers", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1402.4759v4", "version": "arXiv:1402.4759v4 author manuscript", "whole_work_read": false, "year": 2014, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1402.4759", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-022"]}','Tree-lattice zeta functions and class numbers','["Antonius Deitmar", "Ming-Hsuan Kang"]',NULL,'2014',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1402.4759v4 author manuscript','https://arxiv.org/pdf/1402.4759v4','b31464b17a23ea693b5feeb577f583dad335e6d9b061551a7340e76e95b6c182','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-023','corpus/bibliography.jsonl',560,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": "1303.6848", "audit_level": 0, "authors": ["Anton Deitmar", "Ming-Hsuan Kang"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1303.6848", "classical_zeta_transfer_obstacle": "Ramanujan temperedness is a hypothesis for the indicated clean formula, not a positivity consequence of the zeta identity. The quotient geometry does not realize classical zeros.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-023", "language": "English", "main_result": "Theorem 5.1 gives a quotient of oriented geometric zetas for the specified PGL₃ building quotient, with factors P₁ and P₂ whose reciprocal roots have modulus √q and prescribed exceptional factors. Corollary 5.2 assumes the complex is Ramanujan and gives the simplified form (1−u³)^χ P₁(u)/[(1−u³)(1−q³u³)]. Theorem 1.2 supplies a separate higher-rank Lefschetz formula whose full hypotheses are incompletely extracted.", "novelty_claim": false, "paper_id": "PAPER-GEO70-023", "pdf_pages": 24, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 1.2, §5 Theorem 5.1 and Corollary 5.2). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "Ramanujan temperedness is a hypothesis for the indicated clean formula, not a positivity consequence of the zeta identity. The quotient geometry does not realize classical zeros.", "source_locator": "Theorem 1.2, §5 Theorem 5.1 and Corollary 5.2", "source_path": "quality/pending_round12/geometry70_sources/1303_6848.pdf", "source_sha256": "9c61bbba87929ed02c0c838cb09d071669d65ef2e5f395db2504dc94f288bfac", "source_url": "https://arxiv.org/pdf/1303.6848v3", "substantive_reading": false, "title": "Geometric zeta functions for higher rank p-adic groups", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1303.6848v3", "version": "arXiv:1303.6848v3 author manuscript", "whole_work_read": false, "year": 2013, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1303.6848", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-023"]}','Geometric zeta functions for higher rank p-adic groups','["Anton Deitmar", "Ming-Hsuan Kang"]',NULL,'2013',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1303.6848v3 author manuscript','https://arxiv.org/pdf/1303.6848v3','9c61bbba87929ed02c0c838cb09d071669d65ef2e5f395db2504dc94f288bfac','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-024','corpus/bibliography.jsonl',561,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zeta special values", "arxiv_id": "1605.01277", "audit_level": 0, "authors": ["Matthias Flach", "Baptiste Morin"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1605.01277", "classical_zeta_transfer_obstacle": "This is a special-value determinant-line theory: finite generation and duality assumptions must be retained. Such a line at an integer does not identify a full spectral zero divisor.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-024", "language": "English", "main_result": "Constructs the canonical derived morphism from dual rational motivic cohomology to the étale motivic complex under the standing duality and finite-generation assumptions, including L(X_et,n), L(X_et,d−n) and AV in the introduction, then uses such constructions for a Weil–étale formulation of special zeta values. Only a synopsis of the cited result is extracted here; full auxiliary hypotheses and secondary statements are incomplete.", "novelty_claim": false, "paper_id": "PAPER-GEO70-024", "pdf_pages": 108, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Introduction Conjectures L, B and special value formulation; Theorem 3.5). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "This is a special-value determinant-line theory: finite generation and duality assumptions must be retained. Such a line at an integer does not identify a full spectral zero divisor.", "source_locator": "Introduction Conjectures L, B and special value formulation; Theorem 3.5", "source_path": "quality/pending_round12/geometry70_sources/1605_01277.pdf", "source_sha256": "5389568efda4bbdfdee95359e03c28e7ff78ab3b2c7f530acf72dacfef79b04b", "source_url": "https://arxiv.org/pdf/1605.01277v2", "substantive_reading": false, "title": "Weil-étale cohomology and Zeta-values of proper regular arithmetic schemes", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1605.01277v2", "version": "arXiv:1605.01277v2 author manuscript", "whole_work_read": false, "year": 2016, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1605.01277", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-024"]}','Weil-étale cohomology and Zeta-values of proper regular arithmetic schemes','["Matthias Flach", "Baptiste Morin"]',NULL,'2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1605.01277v2 author manuscript','https://arxiv.org/pdf/1605.01277v2','5389568efda4bbdfdee95359e03c28e7ff78ab3b2c7f530acf72dacfef79b04b','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-025','corpus/bibliography.jsonl',562,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zeta special values", "arxiv_id": "2005.04829", "audit_level": 0, "authors": ["Matthias Flach", "Baptiste Morin"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2005.04829", "classical_zeta_transfer_obstacle": "A verification of correction terms and conditional compatibility is not a proof of the global functional equation in general and does not give critical-strip purity.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-025", "language": "English", "main_result": "For regular X of dimension d, proper and flat over Spec Z, Theorem 1.2 proves an unconditional comparison between the archimedean correction and Bloch-conductor factor. Theorem 1.4 assumes L(X_et,n), L(X_et,d−n), AV(X_et,n), B(X,n), B(X,d−n), and the completed meromorphic continuation and functional equation in Conjecture 1.3. It proves equivalence of the two special-value conjectures at n and d−n.", "novelty_claim": false, "paper_id": "PAPER-GEO70-025", "pdf_pages": 35, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 1.2 and 1.4, Conjecture 1.3). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "A verification of correction terms and conditional compatibility is not a proof of the global functional equation in general and does not give critical-strip purity.", "source_locator": "Theorems 1.2 and 1.4, Conjecture 1.3", "source_path": "quality/pending_round12/geometry70_sources/2005_04829.pdf", "source_sha256": "46cf08ed0b374ebe64c2fb0688e110b6a64c15ac48280b0485b3d09c1f9c32c9", "source_url": "https://arxiv.org/pdf/2005.04829v1", "substantive_reading": false, "title": "Compatibility of Special value conjectures with the functional equation of Zeta functions", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:2005.04829v1", "version": "arXiv:2005.04829v1 author manuscript", "whole_work_read": false, "year": 2020, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "2005.04829", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-025"]}','Compatibility of Special value conjectures with the functional equation of Zeta functions','["Matthias Flach", "Baptiste Morin"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2005.04829v1 author manuscript','https://arxiv.org/pdf/2005.04829v1','46cf08ed0b374ebe64c2fb0688e110b6a64c15ac48280b0485b3d09c1f9c32c9','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-026','corpus/bibliography.jsonl',563,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zeta special values", "arxiv_id": "1010.3833", "audit_level": 0, "authors": ["Matthias Flach", "Baptiste Morin"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1010.3833", "classical_zeta_transfer_obstacle": "This supplies an explicit failure of an integral mixed-characteristic construction, rather than an obstruction to all spectral constructions or a proof of RH.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-026", "language": "English", "main_result": "The fiber-product Weil–étale topos agrees with Lichtenbaum’s number-ring construction and the established finite-characteristic setup in the specified cases. Over a flat regular proper mixed-characteristic scheme some real-coefficient properties follow from analytic assumptions on the generic-fiber L-functions, but the integral properties (d),(e) fail for this definition.", "novelty_claim": false, "paper_id": "PAPER-GEO70-026", "pdf_pages": 84, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 1.1(i)–(iii) and §9.3 limitations). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "This supplies an explicit failure of an integral mixed-characteristic construction, rather than an obstruction to all spectral constructions or a proof of RH.", "source_locator": "Theorem 1.1(i)–(iii) and §9.3 limitations", "source_path": "quality/pending_round12/geometry70_sources/1010_3833.pdf", "source_sha256": "0f76aedbf1c2e8f6d729c5855aed1f98af92eeb10c8541996f1a6110f4efc2ae", "source_url": "https://arxiv.org/pdf/1010.3833v1", "substantive_reading": false, "title": "On the Weil-étale topos of regular arithmetic schemes", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1010.3833v1", "version": "arXiv:1010.3833v1 author manuscript", "whole_work_read": false, "year": 2010, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1010.3833", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-026"]}','On the Weil-étale topos of regular arithmetic schemes','["Matthias Flach", "Baptiste Morin"]',NULL,'2010',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1010.3833v1 author manuscript','https://arxiv.org/pdf/1010.3833v1','0f76aedbf1c2e8f6d729c5855aed1f98af92eeb10c8541996f1a6110f4efc2ae','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-027','corpus/bibliography.jsonl',564,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zeta special values", "arxiv_id": "math/0405164", "audit_level": 0, "authors": ["Thomas H. Geisser"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0405164", "classical_zeta_transfer_obstacle": "The comparison justifies a topology change with explicit hypotheses. Its generalized Tate comparison and semisimplicity statement are conjectural, not evidence for number-field spectral positivity.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-027", "language": "English", "main_result": "For a separated finite-type scheme over a field, étale and eh cohomology agree for the displayed root-of-unity torsion sheaves of invertible order. Under resolution in dimensions ≤d they agree for motivic complexes on smooth schemes of dimension ≤d.", "novelty_claim": false, "paper_id": "PAPER-GEO70-027", "pdf_pages": 27, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 1.1 and Conjecture 1.2). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The comparison justifies a topology change with explicit hypotheses. Its generalized Tate comparison and semisimplicity statement are conjectural, not evidence for number-field spectral positivity.", "source_locator": "Theorem 1.1 and Conjecture 1.2", "source_path": "quality/pending_round12/geometry70_sources/math_0405164.pdf", "source_sha256": "9f30765db4d3c68f1dff8003fd5e2cc19a1bcb3265486e6f30d2e658a471e8d9", "source_url": "https://arxiv.org/pdf/math/0405164v2", "substantive_reading": false, "title": "Arithmetic cohomology over finite fields and special values of zeta-functions", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0405164v2", "version": "arXiv:math/0405164v2 author manuscript", "whole_work_read": false, "year": 2004, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0405164", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-027"]}','Arithmetic cohomology over finite fields and special values of zeta-functions','["Thomas H. Geisser"]',NULL,'2004',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0405164v2 author manuscript','https://arxiv.org/pdf/math/0405164v2','9f30765db4d3c68f1dff8003fd5e2cc19a1bcb3265486e6f30d2e658a471e8d9','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-028','corpus/bibliography.jsonl',565,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zeta special values", "arxiv_id": "math/0404425", "audit_level": 0, "authors": ["Thomas H. Geisser"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0404425", "classical_zeta_transfer_obstacle": "This formula localizes to integer arguments and uses finite-field arithmetic. A special-value Euler characteristic is not a generator with all ζ zeros.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-028", "language": "English", "main_result": "For smooth projective X/F_q and integer n, Theorem 1.2 gives K(X,n)+K(X,d−n)⇒L(X,n)⇒K(X,n)⇒T(X,n), and the converse from T for all smooth projective X and n. Under K(X,n) Theorem 1.3 gives pole order rank H_W^{2n}(X,Z(n)) and leading term ±(1−q^{n−s})^(−ρ_n)χ(H_W^*(X,Z(n)),e)q^χ(X,O_X,n). The torsion-and-pairing expression for χ additionally assumes K(X,d−n).", "novelty_claim": false, "paper_id": "PAPER-GEO70-028", "pdf_pages": 23, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 1.2–1.3 and §8). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "This formula localizes to integer arguments and uses finite-field arithmetic. A special-value Euler characteristic is not a generator with all ζ zeros.", "source_locator": "Theorems 1.2–1.3 and §8", "source_path": "quality/pending_round12/geometry70_sources/math_0404425.pdf", "source_sha256": "1e740fd58ea2220c10ab63f45d4a52c208bebdc5e7b86d8d54f1d5ea79aa0276", "source_url": "https://arxiv.org/pdf/math/0404425v1", "substantive_reading": false, "title": "Weil-etale cohomology over finite fields", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0404425v1", "version": "arXiv:math/0404425v1 author manuscript", "whole_work_read": false, "year": 2004, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0404425", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-028"]}','Weil-etale cohomology over finite fields','["Thomas H. Geisser"]',NULL,'2004',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0404425v1 author manuscript','https://arxiv.org/pdf/math/0404425v1','1e740fd58ea2220c10ab63f45d4a52c208bebdc5e7b86d8d54f1d5ea79aa0276','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-029','corpus/bibliography.jsonl',566,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zeta special values", "arxiv_id": "1103.6061", "audit_level": 0, "authors": ["Baptiste Morin"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1103.6061", "classical_zeta_transfer_obstacle": "An integer special value of a number-field zeta is recovered without an operator computing the nontrivial zeros in the critical strip.", "doi": "10.1215/00127094-2681387", "full_text_accessed": true, "id": "PAPER-GEO70-029", "language": "English", "main_result": "Constructs the stated Weil–étale compact-support complex for regular proper X over Spec Z when X is in L(Z) or its connected components satisfy the stated finite generation conjecture, gives the conditional determinant-line formulation, and verifies its special-value conjecture for spectra of number rings. Only a synopsis of the cited result is extracted here; full auxiliary hypotheses and secondary statements are incomplete.", "novelty_claim": false, "paper_id": "PAPER-GEO70-029", "pdf_pages": 53, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 1.3, 1.5 and 1.6). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "An integer special value of a number-field zeta is recovered without an operator computing the nontrivial zeros in the critical strip.", "source_locator": "Theorems 1.3, 1.5 and 1.6", "source_path": "quality/pending_round12/geometry70_sources/1103_6061.pdf", "source_sha256": "7fd930461ebd23fe2851e8e95bb98a6e11878eb170fb2a17bdf96ea1562d6830", "source_url": "https://arxiv.org/pdf/1103.6061v2", "substantive_reading": false, "title": "Zeta functions of regular arithmetic schemes at s=0", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1103.6061v2", "version": "arXiv:1103.6061v2 author manuscript", "whole_work_read": false, "year": 2011, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1103.6061", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-029"]}','Zeta functions of regular arithmetic schemes at s=0','["Baptiste Morin"]',NULL,'2011',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1103.6061v2 author manuscript','https://arxiv.org/pdf/1103.6061v2','7fd930461ebd23fe2851e8e95bb98a6e11878eb170fb2a17bdf96ea1562d6830','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-030','corpus/bibliography.jsonl',567,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zeta special values", "arxiv_id": "1812.03619", "audit_level": 0, "authors": ["Thomas H. Geisser", "Takashi Suzuki"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1812.03619", "classical_zeta_transfer_obstacle": "Even the powerful special-value formula controls one central point under its finiteness hypothesis. It does not yield an all-zero number-field trace.", "doi": "10.1016/j.jnt.2019.08.013", "full_text_accessed": true, "id": "PAPER-GEO70-030", "language": "English", "main_result": "For an abelian variety over a global field of characteristic p with finite Tate–Shafarevich group, gives the order and leading coefficient at s=1 in terms of Weil–étale groups of the Néron model, coherent Lie term and log q; Kato–Trihan and the cited duality results are inputs. Only a synopsis of the cited result is extracted here; full auxiliary hypotheses and secondary statements are incomplete.", "novelty_claim": false, "paper_id": "PAPER-GEO70-030", "pdf_pages": 23, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 1.1–1.2, Introduction). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "Even the powerful special-value formula controls one central point under its finiteness hypothesis. It does not yield an all-zero number-field trace.", "source_locator": "Theorems 1.1–1.2, Introduction", "source_path": "quality/pending_round12/geometry70_sources/1812_03619.pdf", "source_sha256": "ac928298103c44f321d345d2c3c23e8a8f7c7d9fbd20611034a769dfd708ff95", "source_url": "https://arxiv.org/pdf/1812.03619v2", "substantive_reading": false, "title": "A Weil-etale version of the Birch and Swinnerton-Dyer formula over function fields", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1812.03619v2", "version": "arXiv:1812.03619v2 author manuscript", "whole_work_read": false, "year": 2018, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1812.03619", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-030"]}','A Weil-etale version of the Birch and Swinnerton-Dyer formula over function fields','["Thomas H. Geisser", "Takashi Suzuki"]',NULL,'2018',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1812.03619v2 author manuscript','https://arxiv.org/pdf/1812.03619v2','ac928298103c44f321d345d2c3c23e8a8f7c7d9fbd20611034a769dfd708ff95','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-031','corpus/bibliography.jsonl',568,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zeta special values", "arxiv_id": "2101.06530", "audit_level": 0, "authors": ["S. Lichtenbaum", "N. Ramachandran"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2101.06530", "classical_zeta_transfer_obstacle": "Equivalence of two special-value statements does not construct a positive operator for the entire zero divisor.", "doi": "10.1017/S1474748022000093", "full_text_accessed": true, "id": "PAPER-GEO70-031", "language": "English", "main_result": "For a regular projective flat surface over a ring of integers whose generic fiber is a geometrically connected smooth projective curve, Theorem 2 identifies the surface special-value conjecture at 1 with BSD for its generic Jacobian. The conjectural surface formula is stated up to powers of two. Corollary 4 transfers the validity of the conjecture between models whose generic Jacobians are isogenous.", "novelty_claim": false, "paper_id": "PAPER-GEO70-031", "pdf_pages": 29, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 2 and Corollary 4). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "Equivalence of two special-value statements does not construct a positive operator for the entire zero divisor.", "source_locator": "Theorem 2 and Corollary 4", "source_path": "quality/pending_round12/geometry70_sources/2101_06530.pdf", "source_sha256": "f1c85b943d93efd93ed831b31a128082295d864411549415e043da1521516f8f", "source_url": "https://arxiv.org/pdf/2101.06530v2", "substantive_reading": false, "title": "Values of zeta functions of arithmetic surfaces at s=1", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:2101.06530v2", "version": "arXiv:2101.06530v2 author manuscript", "whole_work_read": false, "year": 2021, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "2101.06530", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-031"]}','Values of zeta functions of arithmetic surfaces at s=1','["S. Lichtenbaum", "N. Ramachandran"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2101.06530v2 author manuscript','https://arxiv.org/pdf/2101.06530v2','f1c85b943d93efd93ed831b31a128082295d864411549415e043da1521516f8f','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-032','corpus/bibliography.jsonl',569,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zeta special values", "arxiv_id": "2108.00811", "audit_level": 0, "authors": ["Adrien Morin"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2108.00811", "classical_zeta_transfer_obstacle": "The special-value statement can be applied to twisted Artin factors via the given hypotheses but does not determine central-zero multiplicities or an all-zero cohomology.", "doi": "10.1016/j.jnt.2022.07.002", "full_text_accessed": true, "id": "PAPER-GEO70-032", "language": "English", "main_result": "For regular irreducible one-dimensional U of finite type over Z, Theorem A constructs the perfect compact-support complex for big or tiny Z-constructible sheaves, with the stated big-to-tiny functoriality. Theorem B gives the real-perfect regulator pairing. For any Z-constructible F, Theorem C gives ord_{s=0} L_U(F,s)=E_U(F) and L_U^*(F,0)=(−1)^{rank_Z F(K)}χ_U(F). This extension uses the Euler characteristic for general sheaves, without asserting that Theorem A constructs their complex.", "novelty_claim": false, "paper_id": "PAPER-GEO70-032", "pdf_pages": 49, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems A–C, Corollary D). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The special-value statement can be applied to twisted Artin factors via the given hypotheses but does not determine central-zero multiplicities or an all-zero cohomology.", "source_locator": "Theorems A–C, Corollary D", "source_path": "quality/pending_round12/geometry70_sources/2108_00811.pdf", "source_sha256": "839c62e8c815e82f0b70b65e8f84e12cf2bcffc4b736b25d5ffe8f47e63c3427", "source_url": "https://arxiv.org/pdf/2108.00811v1", "substantive_reading": false, "title": "Special values of L-functions on regular arithmetic schemes of dimension 1", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:2108.00811v1", "version": "arXiv:2108.00811v1 author manuscript", "whole_work_read": false, "year": 2021, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "2108.00811", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-032"]}','Special values of L-functions on regular arithmetic schemes of dimension 1','["Adrien Morin"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2108.00811v1 author manuscript','https://arxiv.org/pdf/2108.00811v1','839c62e8c815e82f0b70b65e8f84e12cf2bcffc4b736b25d5ffe8f47e63c3427','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-033','corpus/bibliography.jsonl',570,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "motivic positivity", "arxiv_id": "2206.10086", "audit_level": 0, "authors": ["Kazuhiro Ito", "Tetsushi Ito", "Teruhisa Koshikawa"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2206.10086", "classical_zeta_transfer_obstacle": "The proof explicitly does not avoid the existing Weil conjecture for finite-field K3 surfaces. It supplies genuine positivity but not a new independent route to purity of ζ.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-033", "language": "English", "main_result": "For any K3 surface X over a field and any ample line bundle on X×X, Theorem 1.2 proves the Hodge standard conjecture for the square. Corollary 1.4 combines this with the known Lefschetz standard conjecture to deduce the standard conjectures for that square, in particular equality of numerical and ℓ-adic homological equivalence. Remark 1.3 explicitly says the proof did not attempt to avoid the Weil conjecture.", "novelty_claim": false, "paper_id": "PAPER-GEO70-033", "pdf_pages": 24, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 1.2, Remark 1.3 and Corollary 1.4). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The proof explicitly does not avoid the existing Weil conjecture for finite-field K3 surfaces. It supplies genuine positivity but not a new independent route to purity of ζ.", "source_locator": "Theorem 1.2, Remark 1.3 and Corollary 1.4", "source_path": "quality/pending_round12/geometry70_sources/2206_10086.pdf", "source_sha256": "1da25fcf1bdbb11bfe63be0d931f2f974cd30bf12460cdd5e06175fb93355d85", "source_url": "https://arxiv.org/pdf/2206.10086v1", "substantive_reading": false, "title": "The Hodge standard conjecture for self-products of K3 surfaces", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:2206.10086v1", "version": "arXiv:2206.10086v1 author manuscript", "whole_work_read": false, "year": 2022, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "2206.10086", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-033"]}','The Hodge standard conjecture for self-products of K3 surfaces','["Kazuhiro Ito", "Tetsushi Ito", "Teruhisa Koshikawa"]',NULL,'2022',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2206.10086v1 author manuscript','https://arxiv.org/pdf/2206.10086v1','1da25fcf1bdbb11bfe63be0d931f2f974cd30bf12460cdd5e06175fb93355d85','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-034','corpus/bibliography.jsonl',571,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "motivic positivity", "arxiv_id": "math/0103175", "audit_level": 0, "authors": ["J. S. Milne"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0103175", "classical_zeta_transfer_obstacle": "The construction assumes motivic cycles and compatible specializations. The corresponding category and adjoint for arithmetic zero-bearing cohomology are missing.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-034", "language": "English", "main_result": "Assuming the Hodge conjecture for complex abelian varieties of CM type, Milne proves a conditional transfer of polarizations and deduces Theorem 3.3: over algebraically closed k, for every ℓ≠char k, numerical and ℓ-adic étale homological equivalence agree on abelian varieties, and the Hodge standard conjecture holds for this cohomology theory.", "novelty_claim": false, "paper_id": "PAPER-GEO70-034", "pdf_pages": 12, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 2.1 and 3.3 and Proposition 3.2). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The construction assumes motivic cycles and compatible specializations. The corresponding category and adjoint for arithmetic zero-bearing cohomology are missing.", "source_locator": "Theorems 2.1 and 3.3 and Proposition 3.2", "source_path": "quality/pending_round12/geometry70_sources/math_0103175.pdf", "source_sha256": "91e2770ef187f49fc1f22cf7131c943e7bcc2c1490830a502137c13036962df7", "source_url": "https://arxiv.org/pdf/math/0103175v3", "substantive_reading": false, "title": "Polarizations and Grothendieck''s Standard Conjectures", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0103175v3", "version": "arXiv:math/0103175v3 author manuscript", "whole_work_read": false, "year": 2001, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0103175", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-034"]}','Polarizations and Grothendieck''s Standard Conjectures','["J. S. Milne"]',NULL,'2001',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0103175v3 author manuscript','https://arxiv.org/pdf/math/0103175v3','91e2770ef187f49fc1f22cf7131c943e7bcc2c1490830a502137c13036962df7','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-035','corpus/bibliography.jsonl',572,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "motivic positivity", "arxiv_id": "1702.04248", "audit_level": 0, "authors": ["Giuseppe Ancona"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1702.04248", "classical_zeta_transfer_obstacle": "Conservativity identifies isomorphisms of existing motives, without supplying a motivic object whose Frobenius controls number-field zeros.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-035", "language": "English", "main_result": "Over a finite field, a morphism of abelian-type triangulated motives is an isomorphism if its ℓ-adic realizations are isomorphisms for almost all ℓ. For abelian-type Chow motives, a single prime ℓ invertible in the base suffices. Theorem 0.5, which is separate and conditional, concerns comparison of homological and numerical equivalence from a stronger conservativity hypothesis; its precise coefficient-family hypotheses are incompletely extracted.", "novelty_claim": false, "paper_id": "PAPER-GEO70-035", "pdf_pages": 12, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 0.3–0.5). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "Conservativity identifies isomorphisms of existing motives, without supplying a motivic object whose Frobenius controls number-field zeros.", "source_locator": "Theorems 0.3–0.5", "source_path": "quality/pending_round12/geometry70_sources/1702_04248.pdf", "source_sha256": "13b72bceb1c10d2990184f2e4af8c92d97314a8ef426cae70dc67ee1f1ef528e", "source_url": "https://arxiv.org/pdf/1702.04248v1", "substantive_reading": false, "title": "Conservativity of realizations on motives of abelian type over finite fields", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1702.04248v1", "version": "arXiv:1702.04248v1 author manuscript", "whole_work_read": false, "year": 2017, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1702.04248", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-035"]}','Conservativity of realizations on motives of abelian type over finite fields','["Giuseppe Ancona"]',NULL,'2017',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1702.04248v1 author manuscript','https://arxiv.org/pdf/1702.04248v1','13b72bceb1c10d2990184f2e4af8c92d97314a8ef426cae70dc67ee1f1ef528e','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-036','corpus/bibliography.jsonl',573,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "motivic positivity", "arxiv_id": "1806.03216", "audit_level": 0, "authors": ["Giuseppe Ancona"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1806.03216", "classical_zeta_transfer_obstacle": "This is actual cycle positivity on a specified geometric domain. It does not yield an arithmetic global trace space admitting a compatible positive pairing.", "doi": "10.1007/s00222-020-00990-7", "full_text_accessed": true, "id": "PAPER-GEO70-036", "language": "English", "main_result": "Theorem 1.3 proves numerical Hodge positivity for abelian fourfolds in positive characteristic. The middle intersection signature is (ρ₂−ρ₁+1,ρ₁−1). Theorem 1.6, combining this with Clozel’s theorem, gives equality of numerical and ℓ-adic homological equivalence for infinitely many primes ℓ. The mixed-characteristic rank-two theorem has separate realization and lifting hypotheses that are incompletely extracted.", "novelty_claim": false, "paper_id": "PAPER-GEO70-036", "pdf_pages": 57, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 1.3–1.4 and 1.6, Theorem 8.1). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "This is actual cycle positivity on a specified geometric domain. It does not yield an arithmetic global trace space admitting a compatible positive pairing.", "source_locator": "Theorems 1.3–1.4 and 1.6, Theorem 8.1", "source_path": "quality/pending_round12/geometry70_sources/1806_03216.pdf", "source_sha256": "8833cda419be3a7377c95b77bfbc41262104f39eb37f4c50fac6a1b9dce6479f", "source_url": "https://arxiv.org/pdf/1806.03216v3", "substantive_reading": false, "title": "Standard conjectures for abelian fourfolds", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1806.03216v3", "version": "arXiv:1806.03216v3 author manuscript", "whole_work_read": false, "year": 2018, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1806.03216", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-036"]}','Standard conjectures for abelian fourfolds','["Giuseppe Ancona"]',NULL,'2018',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1806.03216v3 author manuscript','https://arxiv.org/pdf/1806.03216v3','8833cda419be3a7377c95b77bfbc41262104f39eb37f4c50fac6a1b9dce6479f','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-037','corpus/bibliography.jsonl',574,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "motivic positivity", "arxiv_id": "1907.04143", "audit_level": 0, "authors": ["James S Milne"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1907.04143", "classical_zeta_transfer_obstacle": "Comparing coefficient realizations of one motive is distinct from comparing distinct local Frobenius operators across all rational places in a global determinant for classical ζ.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-037", "language": "English", "main_result": "For a weight-m motive X over F_q, Theorem 0.1 assumes semisimple Frobenius on the specified realization and gives the stated invariant-algebra generation and a Tate transfer under the indicated tensor-square and torus hypothesis. Theorem 0.2 assumes the full Tate conjecture for X^⊗2(m) and gives full faithfulness of ⟨X_ℓ⟩^⊗→⟨X_num⟩^⊗ for an infinite set of primes depending only on the center of End(X_num). The strengthened 3.7 and 4.3 statements are incompletely extracted.", "novelty_claim": false, "paper_id": "PAPER-GEO70-037", "pdf_pages": 16, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 0.1–0.2 and strengthened Theorems 3.7, 4.3). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "Comparing coefficient realizations of one motive is distinct from comparing distinct local Frobenius operators across all rational places in a global determinant for classical ζ.", "source_locator": "Theorems 0.1–0.2 and strengthened Theorems 3.7, 4.3", "source_path": "quality/pending_round12/geometry70_sources/1907_04143.pdf", "source_sha256": "6efdeee711f68874e44ff72c6f080e1b0036add25f43e209ae8c7806e96c1c91", "source_url": "https://arxiv.org/pdf/1907.04143v1", "substantive_reading": false, "title": "On the Tate and Standard Conjectures over Finite Fields", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1907.04143v1", "version": "arXiv:1907.04143v1 author manuscript", "whole_work_read": false, "year": 2019, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1907.04143", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-037"]}','On the Tate and Standard Conjectures over Finite Fields','["James S Milne"]',NULL,'2019',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1907.04143v1 author manuscript','https://arxiv.org/pdf/1907.04143v1','6efdeee711f68874e44ff72c6f080e1b0036add25f43e209ae8c7806e96c1c91','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-038','corpus/bibliography.jsonl',575,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "finite-field trace families", "arxiv_id": "1211.6043", "audit_level": 0, "authors": ["Étienne Fouvry", "Emmanuel Kowalski", "Philippe Michel"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1211.6043", "classical_zeta_transfer_obstacle": "Deligne and monodromy estimates control the finite-field trace values entering a prime sum. This is not a positivity identity for the classical ζ trace.", "doi": "10.1215/00127094-2690587", "full_text_accessed": true, "id": "PAPER-GEO70-038", "language": "English", "main_result": "For isotypic trace weight K on F_p from a nonexceptional, geometrically isotypic, pointwise weight-zero ℓ-adic Fourier sheaf F (ℓ≠p), X≥2 and smooth V supported on [1/2,2] with x^j V^(j)(x)≪_j Q^j, Q≥1, Theorem 1.5 gives a smoothed prime sum ≪ QX(1+p/X)^(1/6)p^(−η) and an unsmoothed sum ≪ X(1+p/X)^(1/12)p^(−η/2), for η<1/24. Constants depend at most polynomially on cond(F), and also depend on η and the smoothness constants. The statement uses finite-field sheaf and trace-weight hypotheses.", "novelty_claim": false, "paper_id": "PAPER-GEO70-038", "pdf_pages": 36, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 1.5 and §1 definitions). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "Deligne and monodromy estimates control the finite-field trace values entering a prime sum. This is not a positivity identity for the classical ζ trace.", "source_locator": "Theorem 1.5 and §1 definitions", "source_path": "quality/pending_round12/geometry70_sources/1211_6043.pdf", "source_sha256": "dab887e22fb0dc6ef1df2ffa10dca3cd68907f94435381d82aee32c1a5d1bbc5", "source_url": "https://arxiv.org/pdf/1211.6043v3", "substantive_reading": false, "title": "Algebraic trace functions over the primes", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1211.6043v3", "version": "arXiv:1211.6043v3 author manuscript", "whole_work_read": false, "year": 2012, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1211.6043", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-038"]}','Algebraic trace functions over the primes','["Étienne Fouvry", "Emmanuel Kowalski", "Philippe Michel"]',NULL,'2012',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1211.6043v3 author manuscript','https://arxiv.org/pdf/1211.6043v3','dab887e22fb0dc6ef1df2ffa10dca3cd68907f94435381d82aee32c1a5d1bbc5','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-039','corpus/bibliography.jsonl',576,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "finite-field trace families", "arxiv_id": "1410.7892", "audit_level": 0, "authors": ["Emmanuel Kowalski", "William F. Sawin"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1410.7892", "classical_zeta_transfer_obstacle": "The limit is for finite-field trace paths, with dependence controlled by monodromy; it does not identify a sequence of zeros of classical ζ.", "doi": "10.1112/S0010437X16007351", "full_text_accessed": true, "id": "PAPER-GEO70-039", "language": "English", "main_result": "Theorem 1.1 uses the normalized Kloosterman partial-sum path K_p(t,a), linearly interpolated with a uniform in F_p^×. For p→∞ it proves convergence of finite-dimensional distributions to the Fourier series with independent real Sato–Tate coefficients. The limiting series with symmetric partial sums is almost surely continuous and nowhere differentiable. Convergence in the uniform topology for this family is outside the statement cited here.", "novelty_claim": false, "paper_id": "PAPER-GEO70-039", "pdf_pages": 27, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 1.1(1)–(2), Introduction). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The limit is for finite-field trace paths, with dependence controlled by monodromy; it does not identify a sequence of zeros of classical ζ.", "source_locator": "Theorem 1.1(1)–(2), Introduction", "source_path": "quality/pending_round12/geometry70_sources/1410_7892.pdf", "source_sha256": "ff931cd090bba0cb841a8c66d0244b054cd5af5d03f3d3b8631e9cd5cea6194e", "source_url": "https://arxiv.org/pdf/1410.7892v1", "substantive_reading": false, "title": "Kloosterman paths and the shape of exponential sums", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1410.7892v1", "version": "arXiv:1410.7892v1 author manuscript", "whole_work_read": false, "year": 2014, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1410.7892", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-039"]}','Kloosterman paths and the shape of exponential sums','["Emmanuel Kowalski", "William F. Sawin"]',NULL,'2014',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1410.7892v1 author manuscript','https://arxiv.org/pdf/1410.7892v1','ff931cd090bba0cb841a8c66d0244b054cd5af5d03f3d3b8631e9cd5cea6194e','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-040','corpus/bibliography.jsonl',577,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "finite-field trace families", "arxiv_id": "1211.3282", "audit_level": 0, "authors": ["Étienne Fouvry", "Emmanuel Kowalski", "Philippe Michel"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1211.3282", "classical_zeta_transfer_obstacle": "Weight-zero purity is a premise. The decomposition identifies local exceptional structures but supplies no archimedean zeta spectral positivity.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-040", "language": "English", "main_result": "For a pointwise pure weight-zero, arithmetically semisimple middle-extension ℓ-adic sheaf F on A¹/F_p, with ℓ≠p and p>d≥1, Theorem 1.3 splits the trace into two trace functions. One satisfies U^d≤(5c(F))^((d+1)^2)/p in the paper’s Gowers convention. The second is a linear combination of at most rank(F) additive phases of degree ≤d−1, with coefficients bounded by rank(F). Corollary 1.4 assumes geometric irreducibility for its dichotomy.", "novelty_claim": false, "paper_id": "PAPER-GEO70-040", "pdf_pages": 19, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 1.3 and Corollary 1.4). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "Weight-zero purity is a premise. The decomposition identifies local exceptional structures but supplies no archimedean zeta spectral positivity.", "source_locator": "Theorem 1.3 and Corollary 1.4", "source_path": "quality/pending_round12/geometry70_sources/1211_3282.pdf", "source_sha256": "070bae302a85413ac08ef1cf3b558c41156f0ce913fecc8d99aef77ed80179a5", "source_url": "https://arxiv.org/pdf/1211.3282v3", "substantive_reading": false, "title": "An inverse theorem for Gowers norms of trace functions over prime fields", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1211.3282v3", "version": "arXiv:1211.3282v3 author manuscript", "whole_work_read": false, "year": 2012, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1211.3282", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-040"]}','An inverse theorem for Gowers norms of trace functions over prime fields','["Étienne Fouvry", "Emmanuel Kowalski", "Philippe Michel"]',NULL,'2012',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1211.3282v3 author manuscript','https://arxiv.org/pdf/1211.3282v3','070bae302a85413ac08ef1cf3b558c41156f0ce913fecc8d99aef77ed80179a5','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-041','corpus/bibliography.jsonl',578,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "finite-field trace families", "arxiv_id": "0807.2118", "audit_level": 0, "authors": ["Emmanuel Kowalski"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/0807.2118", "classical_zeta_transfer_obstacle": "It studies dependence within finite-field families of already pure zeros. The theorem is not uniform for arbitrarily many spectra and does not transfer to the zeros of one number-field function.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-041", "language": "English", "main_result": "Theorem 1.3 fixes a squarefree monic f∈Z[X] of degree 2g, g≥1, and an odd p not dividing its discriminant. For the stated hyperelliptic family on U={f≠0} over F_q of characteristic p, the two exceptional k-tuple counts (additive relations of inverse roots and nontrivial multiplicative relations of normalized roots) are each ≪_g c(g)^k q^{k−1/(29kg²)}log q. Remark 1.4 records the deterioration with k.", "novelty_claim": false, "paper_id": "PAPER-GEO70-041", "pdf_pages": 39, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 1.3 and Remark 1.4). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "It studies dependence within finite-field families of already pure zeros. The theorem is not uniform for arbitrarily many spectra and does not transfer to the zeros of one number-field function.", "source_locator": "Theorem 1.3 and Remark 1.4", "source_path": "quality/pending_round12/geometry70_sources/0807_2118.pdf", "source_sha256": "2f12c458b013e98acc682c153ba2cba01a400d36517766ef37bb4345dbb3450d", "source_url": "https://arxiv.org/pdf/0807.2118v1", "substantive_reading": false, "title": "The large sieve, monodromy and zeta functions of algebraic curves, II: independence of the zeros", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:0807.2118v1", "version": "arXiv:0807.2118v1 author manuscript", "whole_work_read": false, "year": 2008, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "0807.2118", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-041"]}','The large sieve, monodromy and zeta functions of algebraic curves, II: independence of the zeros','["Emmanuel Kowalski"]',NULL,'2008',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:0807.2118v1 author manuscript','https://arxiv.org/pdf/0807.2118v1','2f12c458b013e98acc682c153ba2cba01a400d36517766ef37bb4345dbb3450d','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-042','corpus/bibliography.jsonl',579,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "finite-field trace families", "arxiv_id": "math/0006236", "audit_level": 0, "authors": ["Daqing Wan"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0006236", "classical_zeta_transfer_obstacle": "This is an actual generalization of finite-field counting with Frobenius, not purity of a number-field zeta. Even within finite fields the divisibility condition matters for rationality.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-042", "language": "English", "main_result": "For coordinate-restricted counts on an affine finite-field scheme and subfield degrees forming a divisibility chain, Theorem 1.2 gives rationality and a signed power sum of algebraic integers of absolute values integral powers of √q. For arbitrary positive subfield degrees, Theorem 1.3 (Faltings) gives a normalized product with root-of-unity exponents, with algebraic-integer coefficients and analogous weight control for the rational factors. Such a product need not furnish rationality for arbitrary degrees.", "novelty_claim": false, "paper_id": "PAPER-GEO70-042", "pdf_pages": 10, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 1.2–1.3, §§2–3). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "This is an actual generalization of finite-field counting with Frobenius, not purity of a number-field zeta. Even within finite fields the divisibility condition matters for rationality.", "source_locator": "Theorems 1.2–1.3, §§2–3", "source_path": "quality/pending_round12/geometry70_sources/math_0006236.pdf", "source_sha256": "ea91f842f122873cdc63a50fec120133fb0f780fb7d4c606c16914ea4afae460", "source_url": "https://arxiv.org/pdf/math/0006236v1", "substantive_reading": false, "title": "Partial zeta functions of algebraic varieties over finite fields", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0006236v1", "version": "arXiv:math/0006236v1 author manuscript", "whole_work_read": false, "year": 2000, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0006236", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-042"]}','Partial zeta functions of algebraic varieties over finite fields','["Daqing Wan"]',NULL,'2000',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0006236v1 author manuscript','https://arxiv.org/pdf/math/0006236v1','ea91f842f122873cdc63a50fec120133fb0f780fb7d4c606c16914ea4afae460','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-043','corpus/bibliography.jsonl',580,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "finite-field trace families", "arxiv_id": "math/0409286", "audit_level": 0, "authors": ["Pierre Deligne", "Hélène Esnault"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0409286", "classical_zeta_transfer_obstacle": "Algebraic integrality of a lift of local Frobenius is distinct from archimedean absolute value purity and does not produce a global spectral measure.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-043", "language": "English", "main_result": "For a T-integral ℓ-adic sheaf C on V of finite type over the local field K and f:V→W with W also of finite type over K, Theorem 0.2 makes R^i f_!C T-integral. At closed w, both the eigenvalues of the geometric-Frobenius lift on the stalk and their products with |κ(w)|^{dim f^{-1}(w)−i} are integral over Z[1/t:t∈T]. For smooth V, Corollary 0.3 gives integrality on ordinary ℓ-adic cohomology and Corollary 0.4 gives |k|^κ divisibility for cohomology supported on a codimension-κ subscheme, with k the residue field of K.", "novelty_claim": false, "paper_id": "PAPER-GEO70-043", "pdf_pages": 5, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 0.2 and Corollaries 0.3–0.4). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "Algebraic integrality of a lift of local Frobenius is distinct from archimedean absolute value purity and does not produce a global spectral measure.", "source_locator": "Theorem 0.2 and Corollaries 0.3–0.4", "source_path": "quality/pending_round12/geometry70_sources/math_0409286.pdf", "source_sha256": "5ca6d61b3bd0848548f29b5b68229c8c0e6deb11cadbc650bac55a48591b04f9", "source_url": "https://arxiv.org/pdf/math/0409286v1", "substantive_reading": false, "title": "Appendix to ``Deligne''s integrality theorem in unequal characteristic and rational points over finite fields'''' by Hélène Esnault", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:math/0409286v1", "version": "arXiv:math/0409286v1 author manuscript", "whole_work_read": false, "year": 2004, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "math/0409286", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-043"]}','Appendix to ``Deligne''s integrality theorem in unequal characteristic and rational points over finite fields'''' by Hélène Esnault','["Pierre Deligne", "Hélène Esnault"]',NULL,'2004',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0409286v1 author manuscript','https://arxiv.org/pdf/math/0409286v1','5ca6d61b3bd0848548f29b5b68229c8c0e6deb11cadbc650bac55a48591b04f9','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-044','corpus/bibliography.jsonl',581,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Artin and Galois realization", "arxiv_id": "1609.04717", "audit_level": 0, "authors": ["Robert A. Kucharczyk", "Peter Scholze"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1609.04717", "classical_zeta_transfer_obstacle": "The identification is of étale fundamental groups and finite covers, not an explicit formula for classical ζ or a degree-one positive trace.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-044", "language": "English", "main_result": "For a characteristic-zero field F containing all roots of unity with a chosen embedding Q/Z→F^×, Theorems 1.5 and 5.2 identify finite extensions with connected finite covering spaces of X_F and identify the étale fundamental group with Gal(F̄/F). Definition 1.4 gives a rational Witt-vector character space. The compact Hausdorff model used in the paper is a deformation retract of that introductory space.", "novelty_claim": false, "paper_id": "PAPER-GEO70-044", "pdf_pages": 77, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorems 1.5 and 5.2, Definition 1.4). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The identification is of étale fundamental groups and finite covers, not an explicit formula for classical ζ or a degree-one positive trace.", "source_locator": "Theorems 1.5 and 5.2, Definition 1.4", "source_path": "quality/pending_round12/geometry70_sources/1609_04717.pdf", "source_sha256": "ab89e11d055ce4586dc7a1653c71a03ff180125e40f6ff3155153f80f3938fc9", "source_url": "https://arxiv.org/pdf/1609.04717v2", "substantive_reading": false, "title": "Topological realisations of absolute Galois groups", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1609.04717v2", "version": "arXiv:1609.04717v2 author manuscript", "whole_work_read": false, "year": 2016, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1609.04717", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-044"]}','Topological realisations of absolute Galois groups','["Robert A. Kucharczyk", "Peter Scholze"]',NULL,'2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1609.04717v2 author manuscript','https://arxiv.org/pdf/1609.04717v2','ab89e11d055ce4586dc7a1653c71a03ff180125e40f6ff3155153f80f3938fc9','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-045','corpus/bibliography.jsonl',582,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "finite-field trace families", "arxiv_id": "1901.08202", "audit_level": 0, "authors": ["Jordan S. Ellenberg", "Wanlin Li", "Mark Shusterman"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1901.08202", "classical_zeta_transfer_obstacle": "Fixed-point nonvanishing in a family of already pure function-field spectra gives no off-line exclusion for classical ζ.", "doi": "10.2140/ant.2020.14.1895", "full_text_accessed": true, "id": "PAPER-GEO70-045", "language": "English", "main_result": "At a fixed point 1/2+it and fixed odd characteristic, gives an O(p^(−k/276)) upper bound for the supremum over genera of the vanishing proportion over F_(p^k) as k increases; uses multiplicative restrictions on Frobenius to avoid a specified zero.", "novelty_claim": false, "paper_id": "PAPER-GEO70-045", "pdf_pages": 15, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 1.2 (=3.2) and Corollary 1.4). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "Fixed-point nonvanishing in a family of already pure function-field spectra gives no off-line exclusion for classical ζ.", "source_locator": "Theorem 1.2 (=3.2) and Corollary 1.4", "source_path": "quality/pending_round12/geometry70_sources/1901_08202.pdf", "source_sha256": "671d7df57785cf02e12e6faf7361bcb11e20d1ffb6724e43000e5894306816d3", "source_url": "https://arxiv.org/pdf/1901.08202v3", "substantive_reading": false, "title": "Nonvanishing of hyperelliptic zeta functions over finite fields", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1901.08202v3", "version": "arXiv:1901.08202v3 author manuscript", "whole_work_read": false, "year": 2019, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1901.08202", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-045"]}','Nonvanishing of hyperelliptic zeta functions over finite fields','["Jordan S. Ellenberg", "Wanlin Li", "Mark Shusterman"]',NULL,'2019',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1901.08202v3 author manuscript','https://arxiv.org/pdf/1901.08202v3','671d7df57785cf02e12e6faf7361bcb11e20d1ffb6724e43000e5894306816d3','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-046','corpus/bibliography.jsonl',583,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "finite-field trace families", "arxiv_id": "1111.4701", "audit_level": 0, "authors": ["Alina Bucur", "Chantal David", "Brooke Feigon", "Matilde Lalin", "Kaneenika Sinha"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1111.4701", "classical_zeta_transfer_obstacle": "The angles are already defined using finite-field RH, and the family limit does not locate classical ζ zeros.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-046", "language": "English", "main_result": "Fix F_q of characteristic p and the polynomial family F''_d of (5), with p∤d and coefficients of positive powers divisible by p set to zero. Theorem 1.1 proves a Gaussian limit for the zero count in the paper’s interval I after centering by (d−1)(p−1)|I| and scaling by sqrt(2(p−1)log(d|I|)/π²). The interval has fixed length in (0,1) or shrinks with d|I|→∞. Corollary 1.2 gives the corresponding genus-g, p-rank-zero family formulation. Finite-field RH supplies the zero angles used as input.", "novelty_claim": false, "paper_id": "PAPER-GEO70-046", "pdf_pages": 22, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (Theorem 1.1, Corollary 1.2 and family (5)). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The angles are already defined using finite-field RH, and the family limit does not locate classical ζ zeros.", "source_locator": "Theorem 1.1, Corollary 1.2 and family (5)", "source_path": "quality/pending_round12/geometry70_sources/1111_4701.pdf", "source_sha256": "886ee86014da739120a5f0695397e2c68ff478e685a9b0bab8f9233a1d86b57b", "source_url": "https://arxiv.org/pdf/1111.4701v2", "substantive_reading": false, "title": "Distribution of zeta zeroes of Artin--Schreier curves", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1111.4701v2", "version": "arXiv:1111.4701v2 author manuscript", "whole_work_read": false, "year": 2011, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1111.4701", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-046"]}','Distribution of zeta zeroes of Artin--Schreier curves','["Alina Bucur", "Chantal David", "Brooke Feigon", "Matilde Lalin", "Kaneenika Sinha"]',NULL,'2011',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1111.4701v2 author manuscript','https://arxiv.org/pdf/1111.4701v2','886ee86014da739120a5f0695397e2c68ff478e685a9b0bab8f9233a1d86b57b','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-047','corpus/bibliography.jsonl',584,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "motivic positivity", "arxiv_id": "1712.03708", "audit_level": 0, "authors": ["Peter Scholze"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1712.03708", "classical_zeta_transfer_obstacle": "The finite-field coefficient-category proposal accommodates a quaternionic odd-weight object. A global arithmetic trace and its spectral multiplicities remain separate requirements.", "doi": null, "full_text_accessed": true, "id": "PAPER-GEO70-047", "language": "English", "main_result": "Conjecture 9.5 proposes a Kt_Q-valued Weil cohomology for varieties over the algebraic closure of F_p, with crystalline realization at p, ℓ-adic realizations at ℓ≠p and a Kt_R-valued realization at infinity. The text derives it conditionally from the standard, Tate and CM Hodge conjectures via Langlands–Rapoport. In the supersingular test the predicted antilinear endomorphism on degree one squares to −1. The Kt_R target is a coefficient category, with quaternionic odd weights.", "novelty_claim": false, "paper_id": "PAPER-GEO70-047", "pdf_pages": 29, "publication_status": "Verified arXiv manifestation", "read_scope": "Targeted passages only (§9 Conjecture 9.5 and its following conditional argument). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The finite-field coefficient-category proposal accommodates a quaternionic odd-weight object. A global arithmetic trace and its spectral multiplicities remain separate requirements.", "source_locator": "§9 Conjecture 9.5 and its following conditional argument", "source_path": "quality/pending_round12/geometry70_sources/1712_03708.pdf", "source_sha256": "78d3e22049dd5d9957f4ef0513705563209e77b22f8148104ffb5625bcd9e40e", "source_url": "https://arxiv.org/pdf/1712.03708v1", "substantive_reading": false, "title": "p-adic geometry", "track_file": "papers/geometry70_records.jsonl", "venue": "arXiv:1712.03708v1", "version": "arXiv:1712.03708v1 author manuscript", "whole_work_read": false, "year": 2017, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": "1712.03708", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-047"]}','p-adic geometry','["Peter Scholze"]',NULL,'2017',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1712.03708v1 author manuscript','https://arxiv.org/pdf/1712.03708v1','78d3e22049dd5d9957f4ef0513705563209e77b22f8148104ffb5625bcd9e40e','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-048','corpus/bibliography.jsonl',585,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": null, "audit_level": 0, "authors": ["Christopher Deninger"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.4171/dms/1-1/2", "classical_zeta_transfer_obstacle": "The number-field global fixed-point theory, Hodge star and Poincaré duality are hypotheses or proposals. Local regularized determinants do not construct a global positive generator.", "doi": "10.4171/dms/1-1/2", "full_text_accessed": true, "id": "PAPER-GEO70-048", "language": "English", "main_result": "Theorem 3.3 constructs a complex flow cohomology from ℓ-adic data for algebraic F_p-schemes and gives Poincaré duality for regular connected projective equidimensional X. Theorem 3.4 gives local inverse regularized determinants from left exact additive functors on motives over Q, exact on motives integral at p, with tensor isomorphisms and dual compatibility on motives of good reduction at p. The real structure at infinity is local, with the displayed pairing in that theorem.", "novelty_claim": false, "paper_id": "PAPER-GEO70-048", "pdf_pages": 24, "publication_status": "published", "read_scope": "Targeted passages only (Printed pp. 169–175, Theorems 3.3–3.4 and formula (16)). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated result or proposal within the scope of the cited passages.", "selection_reason": "The number-field global fixed-point theory, Hodge star and Poincaré duality are hypotheses or proposals. Local regularized determinants do not construct a global positive generator.", "source_locator": "Printed pp. 169–175, Theorems 3.3–3.4 and formula (16)", "source_path": "quality/pending_round12/geometry70_sources/deninger_icm.pdf", "source_sha256": "0e99b0df27251838b64be07618cf3e0e600a13a79257bd831a3c3f05fc1ba050", "source_url": "https://content.ems.press/assets/public/full-texts/books/246/chapters/online-pdf/978-3-98547-544-5-volume-1-chapter-4682.pdf", "substantive_reading": false, "title": "Some Analogies Between Number Theory and Dynamical Systems on Foliated Spaces", "track_file": "papers/geometry70_records.jsonl", "venue": "Documenta Mathematica, Extra Volume ICM 1998 I, 163–186", "version": "Original proceedings pages from publisher", "whole_work_read": false, "year": 1998, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-048"]}','Some Analogies Between Number Theory and Dynamical Systems on Foliated Spaces','["Christopher Deninger"]',NULL,'1998',0,0,'selected_checkpoint_priority_work','full_text_accessed','Original proceedings pages from publisher','https://content.ems.press/assets/public/full-texts/books/246/chapters/online-pdf/978-3-98547-544-5-volume-1-chapter-4682.pdf','0e99b0df27251838b64be07618cf3e0e600a13a79257bd831a3c3f05fc1ba050','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO70-049','corpus/bibliography.jsonl',586,'full_text_accessed','quality/pending_round12/geometry70_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "spectral flow", "arxiv_id": null, "audit_level": 0, "authors": ["Christopher Deninger"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1090/pspum/055.1/1265547", "classical_zeta_transfer_obstacle": "The introduction explicitly labels the global arithmetic cohomology speculative. A formal spectral product over a prescribed zero divisor does not construct a positive spectral realization. The targeted extraction here is limited to the front matter and determinant definition.", "doi": "10.1090/pspum/055.1/1265547", "full_text_accessed": true, "id": "PAPER-GEO70-049", "language": "English", "main_result": "The introduction states that §§1–6 extend local determinant formulas to mixed motives in terms of realizations, with a finite-prime Riemann–Hilbert construction removing the earlier semisimplicity assumption. Section 1 states discrete finite-algebraic-multiplicity and zeta-series continuation requirements for the regularized determinant. The global arithmetic cohomology discussion in §7 is expressly speculative. Precise local theorem statements and proof hypotheses are incompletely extracted.", "novelty_claim": false, "paper_id": "PAPER-GEO70-049", "pdf_pages": 46, "publication_status": "published", "read_scope": "Targeted passages only (Author manuscript PDF pp. 1–3, Introduction and §1 regularized determinant definition). Proof, supplementary hypotheses elsewhere in the text, and citation dependencies outside these passages were not independently audited.", "record_path": "quality/pending_round12/geometry70_notes.md", "result_status": "Source-stated scoped result. Precise statement or hypotheses incompletely extracted as indicated.", "selection_reason": "The introduction explicitly labels the global arithmetic cohomology speculative. A formal spectral product over a prescribed zero divisor does not construct a positive spectral realization. The targeted extraction here is limited to the front matter and determinant definition.", "source_locator": "Author manuscript PDF pp. 1–3, Introduction and §1 regularized determinant definition", "source_path": "quality/pending_round12/geometry70_sources/deninger_motivic.pdf", "source_sha256": "efab72eac5f79e97781fbd8ea6deaecfc1d0c1e132c827b70381479fae1eaa7b", "source_url": "https://empslocal.ex.ac.uk/people/staff/mrwatkin/zeta/deninger3.pdf", "substantive_reading": false, "title": "Motivic L-functions and regularized determinants", "track_file": "papers/geometry70_records.jsonl", "venue": "Motives, Proc. Symp. Pure Math. 55(1), 707–743", "version": "46-page author/typeset manuscript manifestation; not the journal pagination", "whole_work_read": false, "year": 1994, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/geometry70_records.jsonl", "theorem_statement_status": "incomplete targeted extraction", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO70-049"]}','Motivic L-functions and regularized determinants','["Christopher Deninger"]',NULL,'1994',0,0,'selected_checkpoint_priority_work','full_text_accessed','46-page author/typeset manuscript manifestation; not the journal pagination','https://empslocal.ex.ac.uk/people/staff/mrwatkin/zeta/deninger3.pdf','efab72eac5f79e97781fbd8ea6deaecfc1d0c1e132c827b70381479fae1eaa7b','quality/pending_round12/geometry70_notes.md','papers/geometry70_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-G001','corpus/bibliography.jsonl',587,'full_text_accessed','papers/PAPER-G001.md','{"publication_status": "journal", "full_text_access": "Original journal PDF downloaded and text extracted; private copy excluded from distribution.", "bibliographic_verified": true, "full_text_accessed": true, "access_date": "2026-11-17", "correction_search": "Not systematically searched; no assertion that all corrections or later versions were located.", "arxiv_id": null, "date_semantics": "Publication year only, not an inferred exact day; access_date is this campaign’s retrieval/inspection date.", "selected": true, "paper_id": "PAPER-G001", "title": "Numbers of solutions of equations in finite fields", "authors": ["André Weil"], "year": 1949, "date": "1949", "publication_date": "1949", "venue": "Bulletin of the American Mathematical Society 55 (5), 497–508", "doi": "10.1090/S0002-9904-1949-09219-4", "canonical_url": "https://doi.org/10.1090/S0002-9904-1949-09219-4", "source_url": "https://math.ucr.edu/~res/math205B-2021/app2number-theory/weil-conjectures1949.pdf", "source_sha256": "55cb48abcb191cb344c01587afed7c9fea809b31826c5803c5dbd3092d1dd468", "version": "Original 1949 journal paper, university-hosted scan", "substantive_reading": true, "audit_level": 1, "audit_scope": "All twelve printed pages 497–508 read. Independently reconstructed the finite Gauss-sum norm argument in equation (4); character/Jacobi/Davenport–Hasse architecture traced. Not a full L2 audit of every lifting argument or antecedent.", "family": ["E", "A", "H"], "main_results": [{"locator": "Equation (4), pp. 500–501", "statement": "For a nontrivial multiplicative character χ and nontrivial additive character ψ of Fq, the Gauss sum has squared absolute value q."}, {"locator": "Formula (3), p. 500; estimate p. 502", "statement": "For ai∈Fq* and positive ni, the number N of affine solutions of Σ(i=0..r) ai xi^ni=0 satisfies |N−q^r|≤M(q−1)q^((r−1)/2), with M the number of rational tuples 0<αi<1, ni αi∈Z, Σαi∈Z. The actual character sum is restricted by di=gcd(ni,q−1); the stated M is a q-independent upper bound."}, {"locator": "Equation (5), pp. 503–505", "statement": "For degree-v finite-field extension, lifted characters χ′=χ∘Norm and ψ′=ψ∘Trace satisfy −G(χ′,ψ′)=(−G(χ,ψ))^v."}, {"locator": "pp. 505–507, equation (8)", "statement": "Diagonal projective examples yield rational generating functions with eigenvalue magnitudes matching their expected weights. The general higher-dimensional statements on p. 507 are explicitly conjectural in this paper."}], "definitions": ["Multiplicative and additive characters; gcd di=gcd(ni,q−1).", "Source Jacobi sum j(α), defined for nonzero character exponents summing to zero modulo 1.", "Extension-field norm/trace; generating series of point counts; conjectural Betti factors."], "proof_architecture": ["Express power-preimage counts by multiplicative character orthogonality.", "Reduce nonzero character contributions to Jacobi sums.", "Evaluate Gauss-sum norms and express Jacobi sums as products divided by q.", "Use norm/trace lift and a formal Euler product of monic polynomials to compare extensions.", "Pass from homogeneous affine counts to projective counts; infer diagonal zeta weights; formulate general conjectures."], "limitations": ["The general Weil-conjecture package is conjectural here, not proved.", "Smooth proper/projective hypotheses must be explicit in modern restatement; open A1/Gm refute unrestricted proper-curve factorization.", "Square-root Gauss cancellation does not constitute a general cohomological purity proof.", "No implication to classical RH is established."], "research_questions": ["Formalize the small Gauss-norm proof with both nontriviality hypotheses.", "Track exactly which diagonal equations give pure cohomological factors versus degenerations when characteristic divides the exponent.", "Compare formal Euler-product positivity with the genuinely geometric pole-control hypotheses."], "id": "PAPER-G001", "arxiv": null, "read_scope": "All twelve printed pages 497–508 read. Independently reconstructed the finite Gauss-sum norm argument in equation (4); character/Jacobi/Davenport–Hasse architecture traced. Not a full L2 audit of every lifting argument or antecedent.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "whole_work_read": true, "record_path": "papers/PAPER-G001.md", "track_file": "papers/geometry_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-G001"]}','Numbers of solutions of equations in finite fields','["André Weil"]','["E", "A", "H"]','1949',1,1,'selected_checkpoint_priority_work','full_text_accessed','Original 1949 journal paper, university-hosted scan','https://math.ucr.edu/~res/math205B-2021/app2number-theory/weil-conjectures1949.pdf','55cb48abcb191cb344c01587afed7c9fea809b31826c5803c5dbd3092d1dd468','papers/PAPER-G001.md','papers/geometry_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-G002','corpus/bibliography.jsonl',588,'full_text_accessed','papers/PAPER-G002.md','{"publication_status": "journal", "full_text_access": "Original journal PDF downloaded and text extracted; private copy excluded from distribution.", "bibliographic_verified": true, "full_text_accessed": true, "access_date": "2026-11-17", "correction_search": "Not systematically searched; no assertion that all corrections or later versions were located.", "arxiv_id": null, "date_semantics": "Publication year only, not an inferred exact day; access_date is this campaign’s retrieval/inspection date.", "selected": true, "paper_id": "PAPER-G002", "title": "La conjecture de Weil : I", "authors": ["Pierre Deligne"], "year": 1974, "date": "1974", "publication_date": "1974", "venue": "Publications Mathématiques de l’IHÉS 43, 273–307", "doi": "10.1007/BF02684373", "canonical_url": "https://www.numdam.org/item/PMIHES_1974__43__273_0/", "source_url": "https://www.numdam.org/item/PMIHES_1974__43__273_0.pdf", "source_sha256": "8392b345d4854e6dc55fb42cfc0b616d941935983723627237239a87348f42e5", "version": "Original French journal paper, Numdam scan", "substantive_reading": false, "audit_level": 0, "audit_scope": "Targeted primary-text reading of §§1–3 (pp.273–287), statements/context (5.10), (6.1)–(6.3), and §7 (pp.298–301). Independently checked coefficient positivity in (3.3)–(3.6) and the elementary power amplification in (7.3). SGA, Lefschetz and rationality dependencies not fully audited; whole paper does not qualify for completed L1.", "family": ["E", "C", "H"], "main_results": [{"locator": "Theorem (1.6), p. 276", "statement": "For X0 smooth projective over Fq and ℓ≠char Fq, det(tI−F | H^i_et(X0×Fq Fqbar,Qℓ)) has integer coefficients independent of ℓ, and all complex conjugates of its roots have magnitude q^(i/2). F is geometric Frobenius, identified with pullback of the geometric Frobenius morphism by (1.15)."}, {"locator": "Theorem (3.2), pp. 283–285", "statement": "For a lisse Qℓ-sheaf F0 on U0=P1/Fq minus finitely many points: a perfect alternating pairing F0⊗F0→Qℓ(−β), β∈Z; open geometric monodromy image in the corresponding Sp; and rational local characteristic polynomials at every closed point imply pointwise purity of weight β."}, {"locator": "Lemma (7.1), pp. 298–300; (7.3), p. 301", "statement": "A middle-degree bound q^(d/2−1/2)≤|α|≤q^(d/2+1/2) for smooth projective absolutely irreducible even-dimensional varieties is amplified on even cartesian powers, using Künneth, to exact magnitude q^(d/2)."}], "definitions": ["Geometric Frobenius versus inverse arithmetic Frobenius, (1.15).", "Z(X0,t), Pi(t)=det(1−tF | Hc^i), trace formula, (1.5).", "Weight β at closed x means all conjugates have magnitude |k(x)|^(β/2).", "Vanishing-cycle quotient E/(E∩Eperp), not an assumed nondegenerate E."], "proof_architecture": ["Grothendieck compact-support trace/determinant formula and Poincaré duality.", "Even tensor powers have positive rational local Euler coefficients; monodromy invariant theory restricts global poles.", "Lefschetz pencils supply vanishing cycles and open symplectic monodromy, (5.10).", "Rationality (6.2) on the nondegenerate quotient verifies the third hypothesis of (3.2).", "Leray filtration yields the weak middle-degree bound (7.1).", "Künneth and powers (7.3) remove a uniform ±1/2 exponent loss.", "Weak Lefschetz and duality reduce arbitrary degrees to the middle degree; weight separation yields integrality and ℓ-independence."], "limitations": ["No proof for Spec Z/classical ζ is given.", "The main theorem here is projective smooth; proper smooth is the later WeilII(3.3.9).", "Bilinear self-duality and positive Euler coefficients alone do not imply purity.", "The entire main proof and all external SGA dependencies were not audited here."], "research_questions": ["Replace open-Sp by a precisely sufficient even-tensor coinvariant pole bound and independently verify the derivation.", "Compute tensor invariants in one actual rank-two family and test local/global pole compatibility.", "Specify what sublinear tensor-degree localization error could mean in an actual number-field spectral model."], "id": "PAPER-G002", "arxiv": null, "read_scope": "Targeted primary-text reading of §§1–3 (pp.273–287), statements/context (5.10), (6.1)–(6.3), and §7 (pp.298–301). Independently checked coefficient positivity in (3.3)–(3.6) and the elementary power amplification in (7.3). SGA, Lefschetz and rationality dependencies not fully audited; whole paper does not qualify for completed L1.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-G002.md", "track_file": "papers/geometry_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-G002"]}','La conjecture de Weil : I','["Pierre Deligne"]','["E", "C", "H"]','1974',0,0,'selected_checkpoint_priority_work','full_text_accessed','Original French journal paper, Numdam scan','https://www.numdam.org/item/PMIHES_1974__43__273_0.pdf','8392b345d4854e6dc55fb42cfc0b616d941935983723627237239a87348f42e5','papers/PAPER-G002.md','papers/geometry_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-G003','corpus/bibliography.jsonl',589,'full_text_accessed','papers/PAPER-G003.md','{"publication_status": "journal", "full_text_access": "Original journal PDF downloaded and text extracted; private copy excluded from distribution.", "bibliographic_verified": true, "full_text_accessed": true, "access_date": "2026-11-17", "correction_search": "Not systematically searched; no assertion that all corrections or later versions were located.", "arxiv_id": null, "date_semantics": "Publication year only, not an inferred exact day; access_date is this campaign’s retrieval/inspection date.", "selected": true, "paper_id": "PAPER-G003", "title": "La conjecture de Weil : II", "authors": ["Pierre Deligne"], "year": 1980, "date": "1980", "publication_date": "1980", "venue": "Publications Mathématiques de l’IHÉS 52, 137–252", "doi": "10.1007/BF02684780", "canonical_url": "https://www.numdam.org/item/PMIHES_1980__52__137_0/", "source_url": "https://www.numdam.org/item/PMIHES_1980__52__137_0.pdf", "source_sha256": "b06eea61bf9cb2b596c162f5befcf85d1be69828910a6107c8aa3a99c4afcc71", "version": "Original French journal paper, Numdam scan", "substantive_reading": false, "audit_level": 0, "audit_scope": "Targeted reading: introduction pp.138–143; conventions(0.1)–(0.7); weight definitions(1.2.1)–(1.2.6), pp.153–154; §2 selected argument/Cor(2.2.10), pp.191,195–196; (3.2.3)–(3.2.5) and (3.2.15); (3.3.1)–(3.3.11), pp.204–207; (4.1.1)–(4.1.4), pp.217–218. The 116-page paper was not read in full; no completed L1 or full L2 audit.", "family": ["E", "A", "H"], "main_results": [{"locator": "Theorem (3.3.1), p. 204; conventions (0.1), p.144", "statement": "For f:X→Y between separated noetherian algebraic spaces of finite type over Z on which fixed ℓ is invertible, and a constructible Qℓbar-sheaf F mixed of weights ≤n, R^i f! F is mixed of weights ≤n+i. The paper calls these algebraic spaces schemes by convention."}, {"locator": "Corollaries (3.3.4)–(3.3.6), p. 206", "statement": "For finite-type X0/Fq and mixed F0 of weights ≤n, Hc^i(X,F) has weights ≤n+i. For X0 smooth and F0 lisse of weights ≥n, H^i has weights ≥n+i. If F0 is pure weight n and lisse, im(Hc^i→H^i) is pure weight n+i."}, {"locator": "Corollary (3.3.9), p. 207", "statement": "For X0 smooth proper over Fq and ℓ≠char Fq, det(tI−F | H^i_et(X,Qℓ)) is integral and ℓ-independent, with all eigenvalue conjugates of magnitude q^(i/2). This extends I(1.6) from projective to proper."}, {"locator": "Corollary (2.2.10), p. 196", "statement": "For X0/Fq a smooth curve and F0 lisse and iota-pure of weight β, each α on Hc^1(X,F) has wq(α)<β+2, where wq(α)=2log_q|iota(α)|."}, {"locator": "Theorem (4.1.1), p. 217", "statement": "For X smooth projective pure dimension n over an algebraically closed field of characteristic ≠ℓ, and ample invertible sheaf L with η=c1(L), η^i:H^(n−i)(X,Qℓ)→H^(n+i)(X,Qℓ)(i) is an isomorphism for i≥0. The source chooses a Tate-twist trivialization in this section and suppresses twists."}], "definitions": ["Pure number of weight n relative q: algebraic and every complex conjugate has magnitude q^(n/2).", "Mixed sheaf: finite filtration with pointwise pure quotients; weights are those nonzero quotient weights.", "iota-purity for a chosen field isomorphism Qℓbar→C; real weights allowed.", "Compact versus ordinary cohomology; image of the natural map; weight shift and Tate twist."], "proof_architecture": ["Local-monodromy weights and general purity criteria.", "Hadamard–de la Vallée-Poussin/Mertens method yields strict initial curve bound (2.2.10).", "Product-surface and vanishing-cycle iteration improves the bound by δ→δ/2, (3.2.4).", "Duality gives curve purity (3.2.3); dévissage and base change give (3.3.1).", "Opposite ordinary/compact weight inequalities give pure image and proper smooth purity.", "Geometric semisimplicity and nondegenerate invariants yield hard Lefschetz."], "limitations": ["General weights theorem concerns finite-field Frobenius at closed points; it does not establish classical RH.", "Purity of im(Hc→H) must not be inflated to purity of all ordinary or compact cohomology on open varieties.", "Theorem statement conventions include separatedness, noetherian hypotheses and invertible ℓ.", "Most local-monodromy and vanishing-cycle calculations remain unaudited in this campaign."], "research_questions": ["Fully reconstruct the strict-bound-to-contraction step for one concrete lisse sheaf family.", "Test whether proposed analytic transfers possess a real contraction mechanism, rather than merely coefficient positivity.", "Preserve properness and boundary-weight distinctions in future theorem chaining."], "id": "PAPER-G003", "arxiv": null, "read_scope": "Targeted reading: introduction pp.138–143; conventions(0.1)–(0.7); weight definitions(1.2.1)–(1.2.6), pp.153–154; §2 selected argument/Cor(2.2.10), pp.191,195–196; (3.2.3)–(3.2.5) and (3.2.15); (3.3.1)–(3.3.11), pp.204–207; (4.1.1)–(4.1.4), pp.217–218. The 116-page paper was not read in full; no completed L1 or full L2 audit.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-G003.md", "track_file": "papers/geometry_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-G003"]}','La conjecture de Weil : II','["Pierre Deligne"]','["E", "A", "H"]','1980',0,0,'selected_checkpoint_priority_work','full_text_accessed','Original French journal paper, Numdam scan','https://www.numdam.org/item/PMIHES_1980__52__137_0.pdf','b06eea61bf9cb2b596c162f5befcf85d1be69828910a6107c8aa3a99c4afcc71','papers/PAPER-G003.md','papers/geometry_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HC001','corpus/bibliography.jsonl',590,'full_text_accessed','papers/PAPER-HC001.md','{"id": "PAPER-HC001", "title": "Über die Riemannsche Funktionalgleichung der ζ-Funktion (Erste Mitteilung)", "authors": ["Hans Hamburger"], "year": 1921, "venue": "Mathematische Zeitschrift 10(3–4), 240–254", "doi": "10.1007/BF01211612", "arxiv": null, "version": "Original1921 journal scan; fifteen-page paper extracted from GDZ volume10.", "source_url": "https://gdz.sub.uni-goettingen.de/download/pdf/PPN266833020_0010/PPN266833020_0010.pdf", "source_file": "sources/hamburger_round3/hamburger1921.pdf", "audit_level": 0, "substantive_whole_work_read": false, "read_scope": "Original scanned pp240–242 only, including Satz1 and the two-series extension. Full paper accessed but not read.", "technical_review": "Exact hypotheses visually checked against the original German scan. Later Burnol theorem supplies the weaker-growth converse used in the model bridge.", "main_result_inspected": "Finite poles, global finite growth, an ordinary DS absolutely convergent for Re(s)>1, and exact conductor-one zeta FE imply cζ.", "publication_status": "published", "family": ["A", "D", "F", "G", "H"], "bibliographic_verified": true, "access_status": "full_text_accessed", "accessed_at": "2026-11-17", "correction_search_status": "incomplete; journal/preprint comparison not performed", "source_sha256": "3ed40c927e99ff66eef7bcdc7c04802a7a87453da5a581e037e6fe2cc47fe819", "audit_file": "audits/hamburger_converse_round3.md", "novelty_claim": false, "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-HC001.md", "track_file": "papers/hamburger_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HC001"]}','Über die Riemannsche Funktionalgleichung der ζ-Funktion (Erste Mitteilung)','["Hans Hamburger"]','["A", "D", "F", "G", "H"]','1921',0,0,'selected_checkpoint_priority_work','full_text_accessed','Original1921 journal scan; fifteen-page paper extracted from GDZ volume10.','https://gdz.sub.uni-goettingen.de/download/pdf/PPN266833020_0010/PPN266833020_0010.pdf','3ed40c927e99ff66eef7bcdc7c04802a7a87453da5a581e037e6fe2cc47fe819','papers/PAPER-HC001.md','papers/hamburger_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HC002','corpus/bibliography.jsonl',591,'full_text_accessed','papers/PAPER-HC002.md','{"id": "PAPER-HC002", "title": "Deux extensions de Théorèmes de Hamburger (portant sur l’équation fonctionnelle de la fonction zêta)", "authors": ["Jean-François Burnol"], "year": 2012, "date": "2012-01-07", "venue": "Expositiones Mathematicae 30(3), 295–308", "doi": "10.1016/j.exmath.2012.03.003", "arxiv": "1106.4749v2", "version": "arXiv v2, 7 January2012, fourteen-page preprint; published identity Crossref-verified; journal text not compared.", "source_url": "https://arxiv.org/pdf/1106.4749v2", "source_file": "sources/hamburger_round3/burnol2011.pdf", "audit_level": 1, "substantive_whole_work_read": true, "read_scope": "Complete fourteen-page primary preprint read. Theorem1 and Corollaries1–2 proof pp7–10 reconstructed with an explicit external Mellin/distribution dictionary dependency; not a fully independent audit of that dictionary or Theorems2–3.", "technical_review": "Scoped technical reconstruction: Phragmén–Lindelöf step, integer-support/Fourier periodicity, Bernoulli removals, and shift asymptotics. Burnol2007 Theorem4.54/Remark4.29 not audited here.", "main_result_inspected": "Ordinary DS convergence somewhere, finite poles, weak strip growth and dual right-half-plane control force a finite sum of even zeta shifts. Corollary2 forces cζ under a superpolynomially fast real dual limit.", "publication_status": "published", "family": ["A", "D", "F", "G", "H"], "bibliographic_verified": true, "access_status": "full_text_accessed", "accessed_at": "2026-11-17", "correction_search_status": "incomplete; journal/preprint comparison not performed", "source_sha256": "6a5a9f53d9c67ae5092bc7f08ffd7516fe6ee5bfff725f17fd4fc1d3484d0aff", "audit_file": "audits/hamburger_converse_round3.md", "novelty_claim": false, "original_access_status": "full_text_accessed", "whole_work_read": true, "record_path": "papers/PAPER-HC002.md", "track_file": "papers/hamburger_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HC002"]}','Deux extensions de Théorèmes de Hamburger (portant sur l’équation fonctionnelle de la fonction zêta)','["Jean-François Burnol"]','["A", "D", "F", "G", "H"]','2012',1,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv v2, 7 January2012, fourteen-page preprint; published identity Crossref-verified; journal text not compared.','https://arxiv.org/pdf/1106.4749v2','6a5a9f53d9c67ae5092bc7f08ffd7516fe6ee5bfff725f17fd4fc1d3484d0aff','papers/PAPER-HC002.md','papers/hamburger_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HC003','corpus/bibliography.jsonl',592,'full_text_accessed','papers/PAPER-HC003.md','{"id": "PAPER-HC003", "title": "Hamburger’s Theorem on ζ(s) and the Abundance Principle for Dirichlet Series with Functional Equations", "authors": ["Marvin I. Knopp"], "year": 2000, "venue": "Number Theory, 201–216", "doi": "10.1007/978-3-0348-7023-8_12", "alternate_doi": "10.1007/978-93-86279-02-6_12", "arxiv": null, "version": "Original2000 chapter identity; accessible scanned reprint bears2020 distribution watermark. Exact edition comparison not performed.", "source_url": "https://womengovtcollegevisakha.ac.in/departments/Number%20theory%20%5Bp211-226%5D.pdf", "source_file": "sources/hamburger_round3/knopp2000.pdf", "audit_level": 0, "substantive_whole_work_read": false, "read_scope": "Selected pp201–205 and211–216 read; pp201,211–212 key formulas visually checked. Modular-integral construction pp206–210 not fully read. Author restates Knopp1994 Theorem1 on p212;1994 publisher text inaccessible.", "technical_review": "Independent normalization check: R(z)=π^(−z)Γ(z)φ(z), symmetry z→1/2−z, ordinary φ(z) DS becomes sqrt(integer) frequencies in conventional zeta variable s=2z.", "main_result_inspected": "Abundance for a larger Dirichlet-frequency class, with arbitrary rational polar data subject to finite-codimension conditions; not an exception to the ordinary integer-frequency zeta converse.", "publication_status": "published", "family": ["A", "D", "F", "G", "H"], "bibliographic_verified": true, "access_status": "full_text_accessed", "accessed_at": "2026-11-17", "correction_search_status": "incomplete; journal/preprint comparison not performed", "source_sha256": "3b886687b301fcb363f490da24092bcee6b2996250a907fd41c8858b78545d80", "audit_file": "audits/hamburger_converse_round3.md", "novelty_claim": false, "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-HC003.md", "track_file": "papers/hamburger_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HC003"]}','Hamburger’s Theorem on ζ(s) and the Abundance Principle for Dirichlet Series with Functional Equations','["Marvin I. Knopp"]','["A", "D", "F", "G", "H"]','2000',0,0,'selected_checkpoint_priority_work','full_text_accessed','Original2000 chapter identity; accessible scanned reprint bears2020 distribution watermark. Exact edition comparison not performed.','https://womengovtcollegevisakha.ac.in/departments/Number%20theory%20%5Bp211-226%5D.pdf','3b886687b301fcb363f490da24092bcee6b2996250a907fd41c8858b78545d80','papers/PAPER-HC003.md','papers/hamburger_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HC004','corpus/bibliography.jsonl',593,'full_text_accessed','papers/PAPER-HC004.md','{"id": "PAPER-HC004", "title": "Dirichlet Series with Periodic Coefficients, Riemann’s Functional Equation, and Real Zeros of Dirichlet L-Functions", "authors": ["Takashi Nakamura"], "year": 2023, "date": "2021-09-10", "venue": "Mathematica Slovaca 73(5), 1145–1152", "doi": "10.1515/ms-2023-0084", "arxiv": "2008.02570v4", "version": "arXiv v4,10 September2021 inspected; published2023 identity Crossref-verified; journal text not accessed/compared.", "source_url": "https://arxiv.org/pdf/2008.02570v4", "source_file": "sources/hamburger_round3/nakamura2020.pdf", "audit_level": 1, "substantive_whole_work_read": true, "read_scope": "Complete seven-page preprint read, with p4 visually checked. Direct FE proof Theorem2.1(i) and ordinary-series Corollary2.2 checked. Cited zero-distribution results not independently audited.", "technical_review": "Main examples avoid the exact Hamburger hypotheses via generalized frequencies or Dirichlet-polynomial pole clearing. Background p4 Knopp(H2,H3,K) attribution has unresolved variable-normalization concern; no main theorem failure established and no journal comparison claimed.", "main_result_inspected": "Explicit q^sL(s,χ)+G(χ)L(s,barχ) has the exact even zeta FE; multiplying by symmetric inverse q^s+q^(1−s) yields an ordinary-series example with a different pole-clearing hypothesis.", "publication_status": "published", "family": ["A", "D", "F", "G", "H"], "bibliographic_verified": true, "access_status": "full_text_accessed", "accessed_at": "2026-11-17", "correction_search_status": "incomplete; journal/preprint comparison not performed", "source_sha256": "b2f5410d4e219b51101d1ab09799ea83237f0e7b8048882aa43064a583a4f032", "audit_file": "audits/hamburger_converse_round3.md", "novelty_claim": false, "original_access_status": "full_text_accessed", "whole_work_read": true, "record_path": "papers/PAPER-HC004.md", "track_file": "papers/hamburger_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HC004"]}','Dirichlet Series with Periodic Coefficients, Riemann’s Functional Equation, and Real Zeros of Dirichlet L-Functions','["Takashi Nakamura"]','["A", "D", "F", "G", "H"]','2023',1,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv v4,10 September2021 inspected; published2023 identity Crossref-verified; journal text not accessed/compared.','https://arxiv.org/pdf/2008.02570v4','b2f5410d4e219b51101d1ab09799ea83237f0e7b8048882aa43064a583a4f032','papers/PAPER-HC004.md','papers/hamburger_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HC005','corpus/bibliography.jsonl',594,'full_text_accessed','papers/PAPER-HC005.md','{"id": "PAPER-HC005", "title": "Entrelacement de co-Poisson", "authors": ["Jean-François Burnol"], "year": 2007, "venue": "Annales de l’Institut Fourier 57(2), 525–602", "doi": "10.5802/aif.2268", "arxiv": null, "version": "Publisher2007 PDF from Numdam; source-version history not audited.", "source_url": "https://www.numdam.org/item/10.5802/aif.2268.pdf", "source_file": "sources/hamburger_round3/burnol2007.pdf", "source_sha256": "f831b04340e862901a370ee26c57addac71fb0b52e66a30af410e301c12fa556", "audit_level": 0, "bibliographic_verified": true, "access_status": "full_text_accessed", "substantive_whole_work_read": false, "read_scope": "Selected p577,pp580–585,590–593: Definitions4.11,4.27,4.45,4.53; Remark4.29; Theorems4.26,4.31,4.54; Lemma4.50 and Proposition4.51. Whole78-page paper not read.", "technical_review": "Scoped reconstruction of moderate Mellin/Fourier dictionary, especially Theorem4.31 converse and4.54 meromorphic reduction. Standard Hardy Paley–Wiener/Nevanlinna/Fourier–Mellin results accepted; earlier distribution-smoothing lemmas not fully audited.", "main_result_inspected": "Even extended-S tempered distributions correspond to moderate meromorphic F with moderate χ(s)F(1−s); uniqueness modulo quasi-homogeneous distributions, or exact uniqueness when normalized to vanish near0.", "family": ["D", "F", "H"], "accessed_at": "2026-11-17", "publication_status": "published", "correction_search_status": "not_completed", "audit_file": "audits/hamburger_dictionary_round3.md", "novelty_claim": false, "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-HC005.md", "track_file": "papers/hamburger_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HC005"]}','Entrelacement de co-Poisson','["Jean-François Burnol"]','["D", "F", "H"]','2007',0,0,'selected_checkpoint_priority_work','full_text_accessed','Publisher2007 PDF from Numdam; source-version history not audited.','https://www.numdam.org/item/10.5802/aif.2268.pdf','f831b04340e862901a370ee26c57addac71fb0b52e66a30af410e301c12fa556','papers/PAPER-HC005.md','papers/hamburger_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-HC006','corpus/bibliography.jsonl',595,'primary_source_excerpt_accessed','papers/PAPER-HC006.md','{"id": "PAPER-HC006", "title": "On Dirichlet series satisfying Riemann’s functional equation", "authors": ["Marvin I. Knopp"], "year": 1994, "venue": "Inventiones Mathematicae117,361–372", "doi": "10.1007/BF01232248", "arxiv": null, "version": "Original1994 journal scan, printedpp361–363 accessed via GDZ IIIF; only three-page excerpt downloaded.", "source_url": "https://gdz.sub.uni-goettingen.de/id/PPN356556735_0117?tify=%7B%22pages%22:%5B367%5D%7D", "source_file": "sources/hamburger_round3/knopp1994_excerpt.pdf", "source_sha256": "22b3a9cf75df9e29f928eb21adbbe222167f2fd118032e8c32447224bf594010", "audit_level": 0, "bibliographic_verified": true, "access_status": "primary_source_excerpt_accessed", "substantive_whole_work_read": false, "read_scope": "Original printedpp361–363 visually read, including exact R normalization, conditions1–3, Theorem1, and beginning of Riemann–Hecke–Bochner correspondence. Full twelve-page work not accessed/read.", "technical_review": "Original p361 has R(s)=π^(−s)Γ(s)φ(s), reflection1/2−s. Original p362 abundance Theorem1 retains this normalization and ordinary φ(s); restrictive3(a) additionally requires ordinary φ(s/2). This confirms the normalization in the2000 author restatement. Construction/proof not audited.", "main_result_inspected": "Abundance under ordinary φ(s), finite genus after polynomial pole clearing, gamma Γ(s), reflection1/2−s, with finite-codimension rational polar-data statement.", "family": ["D", "F", "G", "H"], "accessed_at": "2026-11-17", "publication_status": "published", "correction_search_status": "incomplete", "audit_file": "audits/hamburger_converse_round3.md", "novelty_claim": false, "whole_work_read": false, "record_path": "papers/PAPER-HC006.md", "track_file": "papers/hamburger_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_