INSERT INTO "papers" VALUES('PAPER-D303','corpus/bibliography.jsonl',596,'full_text_accessed','papers/PAPER-D303.md','{"paper_id": "PAPER-D303", "title": "The roots of trigonometric integrals", "authors": ["N. G. de Bruijn"], "year": 1950, "date": "1950-09-01", "publication_date": "1950-09-01", "venue": "Duke Mathematical Journal17(3),197–226", "doi": "10.1215/S0012-7094-50-01720-0", "arxiv_id": null, "version": "Original1950 journal scan", "canonical_url": "https://doi.org/10.1215/S0012-7094-50-01720-0", "source_url": "https://repository.tudelft.nl/file/File_524a4d3c-0858-4c55-b425-8c8ce1fb89da", "publication_status": "journal", "full_text_access": "30-page original PDF obtained from TU Delft repository; private copy.", "bibliographic_verified": true, "full_text_accessed": true, "substantive_reading": false, "audit_level": 0, "audit_scope": "Targeted actual-source reading: introduction/Theorem1 and proof architecture,pp197–200; §3 Theorem10–14 and heat-contraction limit proof,pp204–205; selected §7 historical limitations and product-closure theorem. Whole30-page paper/saddle-point estimates not read or audited completely.", "correction_search": "No exhaustive correction search. Repository1948 field corresponds to received-era metadata; original journal and Crossref identify1950. Pages197–226 verified against original and Newmanreference;297–314 is not this paper.", "date_semantics": "Journal publication date from primary/Crossref metadata; printed received16July1948 is kept distinct.", "selected": true, "family": ["B", "F", "H"], "main_results": [{"locator": "Theorem10,p204; Theorem13,p205", "statement": "If f is integrable onR, f(u)=conjugate(f(−u)), f(u)=O(exp(−|u|^β)),β>2, and all Fourier zeros lie in|Imz|≤Δ, then multiplying f byexp(λ²u²/2),λ>0, moves all zeros into|Imz|≤sqrt(max(Δ²−λ²,0)). No positivity orC∞ hypothesis is present."}, {"locator": "Theorem1,p198", "statement": "For nonconstant even nonnegative real-axis entire potentialf whose derivative is a locally uniform limit of polynomials with only imaginary-axis roots, the Fourier integral ofexp(−f(u)) has only real zeros. In particular this applies to the quartic mollifierexp(−(u/ε)^4)."}], "limitations": ["Theorem13 requires all zeros in the initial strip, not merely all but finitely many.", "Atoms are not integrable functions and cannot silently be used as inputs to Theorem13.", "Gaussian heat factors were not shown in this source to have every asymptotic strong-universal-factor property.", "No direct classicalRH theorem is proved."], "research_questions": ["Independently audit the positive smooth sharpness construction and its exact source-class membership.", "Preserve heat normalizationλ²/2 versusdirectτ in computational transfers."], "source_sha256": "793a96ad64681bfc43740602cea0980ca5f86528ef2e96a4e14ed01ece83b8f5", "access_date": "2026-11-17", "id": "PAPER-D303", "arxiv": null, "read_scope": "Targeted actual-source reading: introduction/Theorem1 and proof architecture,pp197–200; §3 Theorem10–14 and heat-contraction limit proof,pp204–205; selected §7 historical limitations and product-closure theorem. Whole30-page paper/saddle-point estimates not read or audited completely.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-D303.md", "track_file": "papers/heatflow_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-D303"]}','The roots of trigonometric integrals','["N. G. de Bruijn"]','["B", "F", "H"]','1950',0,0,'selected_checkpoint_priority_work','full_text_accessed','Original1950 journal scan','https://repository.tudelft.nl/file/File_524a4d3c-0858-4c55-b425-8c8ce1fb89da','793a96ad64681bfc43740602cea0980ca5f86528ef2e96a4e14ed01ece83b8f5','papers/PAPER-D303.md','papers/heatflow_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-D304','corpus/bibliography.jsonl',597,'full_text_accessed','papers/PAPER-D304.md','{"paper_id": "PAPER-D304", "title": "Fourier transforms with only real zeros", "authors": ["Charles M. Newman"], "year": 1976, "date": "1976-12", "publication_date": "1976-12", "venue": "Proceedings of the American Mathematical Society61(2),245–251", "doi": "10.1090/S0002-9939-1976-0434982-5", "alternate_doi": "10.2307/2041319", "arxiv_id": null, "version": "Original journal article; received1976-01-05,revised1976-05-03", "canonical_url": "https://doi.org/10.1090/S0002-9939-1976-0434982-5", "source_url": "https://sites.math.northwestern.edu/~auffing/papers/Newman.pdf", "publication_status": "journal", "full_text_access": "University-hosted original journal scan,7printed pages plusJSTORcover, downloaded/text extracted; private copy.", "bibliographic_verified": true, "full_text_accessed": true, "substantive_reading": true, "audit_level": 1, "audit_scope": "All printed pages245–251 read; main theorem statements/classification product and cutoff endpoint checked against page images. Gaussian-convolution/weak-limit proof architecture and four lemmas reconstructed. Independently checked quartic lower bound and cutoff closure; external polynomial real-zero-preservation/entire-function antecedents and every estimate not independently audited.", "correction_search": "No exhaustive correction search. Issue dateDecember1976 and copyright1977 kept separate; source identity confirmed with Crossref.", "date_semantics": "Publication month from issue/Crossref; received/revision dates and latercopyright are distinct.", "selected": true, "family": ["B", "C", "F", "H"], "main_results": [{"locator": "Theorem1,p246", "statement": "Real even integrable f with super-Gaussian decayexp(−|u|^γ),γ>2,and initial Fourier zero stripΔ has strip sqrt(max(Δ²−2δ,0)) after multipliere^{δu²},δ>0."}, {"locator": "Theorem2,pp246–247", "statement": "Even nonnegative finite measures whose Gaussian-damped Laplace transforms have only imaginary zeros for everyb>0 are exactly a symmetric pair of atoms includinga0 case, or the canonical quartic/second-power densities with factors(1+u²/aj²)exp(−u²/aj²),Σaj^-4<∞,and stated integrability conditions. Exact formula in audit/theorem record."}, {"locator": "Theorem3 andRemark2,p247", "statement": "For originalΞ_b(x)=∫exp(ixu−bu²)F(u)du,withΞ_0(x)=ξ(1/2+ix), there is−1/8≤b0<∞ with real zeros iff b≤b0. RH meansb0≥0, and Newmanconjecturesb0≤0. Under inspected Rodgers–Tao scalingΛ_standard=−4b0."}], "proof_architecture": ["Gaussian convolution approximates the input measure by densities with canonical products inherited from the damped transforms.", "Bounded shape parameters yield normal-family density limits; divergent parameters force symmetric pair support.", "Polynomial/canonical-product approximations prove sufficiency.", "The classified densities have quartic-type lower tails, incompatible with the super-exponential Riemann kernel.", "Strip contraction gives a nonempty real-rooted half-line; exclusion from the classified class makes its threshold finite; Hurwitz gives endpoint inclusion."], "limitations": ["Finite Riemann cutoff does not imply finite cutoff for every positive rapid kernel;quarticexamples havethreshold−∞.", "A finite positive measure need not admit all positive heat tilts.", "Newmanb runs opposite to modernheat and has an additional scale4 relative to Rodgers–Tao.", "The classification is an all-b result, not a finite coefficient criterion."], "research_questions": ["Formalize the elementary logarithmic inequality and the exact atomic cutoff.", "Review the smooth positive-kernel/Li-prefix construction and sharpness proof.", "Do not infer global cutoff convergence from locally uniform transform convergence."], "source_sha256": "f154969b9a39b0e64075570eb9f4c920affbea85bbcee0367eb66302e7a1be28", "access_date": "2026-11-17", "id": "PAPER-D304", "arxiv": null, "read_scope": "All printed pages245–251 read; main theorem statements/classification product and cutoff endpoint checked against page images. Gaussian-convolution/weak-limit proof architecture and four lemmas reconstructed. Independently checked quartic lower bound and cutoff closure; external polynomial real-zero-preservation/entire-function antecedents and every estimate not independently audited.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "whole_work_read": true, "record_path": "papers/PAPER-D304.md", "track_file": "papers/heatflow_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-D304"]}','Fourier transforms with only real zeros','["Charles M. Newman"]','["B", "C", "F", "H"]','1976',1,1,'selected_checkpoint_priority_work','full_text_accessed','Original journal article; received1976-01-05,revised1976-05-03','https://sites.math.northwestern.edu/~auffing/papers/Newman.pdf','f154969b9a39b0e64075570eb9f4c920affbea85bbcee0367eb66302e7a1be28','papers/PAPER-D304.md','papers/heatflow_round2_records.jsonl');
