INSERT INTO "papers" VALUES('PAPER-D301','corpus/bibliography.jsonl',604,'full_text_accessed','papers/PAPER-D301.md','{"paper_id": "PAPER-D301", "title": "Characterizations of rectangular (para)-unitary rational functions", "authors": ["Daniel Alpay", "Palle Jorgensen", "Izchak Lewkowicz"], "year": 2016, "date": "2015-01-04", "publication_date": "2016", "venue": "Opuscula Mathematica 36 (6), 695–716", "doi": "10.7494/OpMath.2016.36.6.695", "arxiv_id": "1410.0283", "version": "v2", "version_date": "2015-01-04", "first_submission_date": "2014-10-01", "preprint_year": 2014, "publication_year": 2016, "canonical_url": "https://arxiv.org/abs/1410.0283v2", "source_url": "https://arxiv.org/pdf/1410.0283v2", "publication_status": "journal", "full_text_access": "19-page arXivv2 PDF downloaded; private research copy. Journal identity checked via Crossref/publisher-indexed metadata; typeset version not compared.", "bibliographic_verified": true, "full_text_accessed": true, "substantive_reading": false, "audit_level": 0, "audit_scope": "Targeted primary reading: introduction/conventions; Theorem2.1 and proof,pp5–6; §3 Theorem3.1/proof and cancellation remarks,pp10–11. Full19-page text, all cited Potapov theory and matrix-fraction results not audited.", "correction_search": "Primary arXiv history v1 2014-10-01 andv2 2015-01-04 inspected; no exhaustive correction certification.", "selected": true, "main_results": [{"locator": "Theorem3.1,pp10–11", "statement": "A rational p×m para-unitary function of McMillan degree d has a representation by rank-one Blaschke–Potapov factors and a constant (co)isometry, in the appropriate left/right orientation. The source allows arbitrary poles off the unit circle and hence factors from both sides; it is not solely an inner function theorem."}, {"locator": "Remarks after Theorem3.1,p11", "statement": "An arbitrary displayed product of d factors can have degree smaller than d through cancellation; reciprocal scalar factors on the same projection can cancel to identity."}, {"locator": "Theorem2.1,pp5–6", "statement": "In its Schur-stable/exterior-disc convention, lossless rational functions admit a minimal state realization with an isometric/coisometric colligation, unitary in the square case."}], "limitations": ["Unit-circle para-unitarity alone does not imply the all-upper-half-plane positive-phase hypothesis used in the new campaign.", "Mixed-pole factors can cancel and need not have nonnegative phase derivative.", "Only selected primary theorem/proof passages were read; no full-paper audit."], "research_questions": ["Map source disc conventions explicitly before reusing a factor in the upper-half-plane model.", "Use determinant degree and positive pole-side hypotheses, rather than raw arbitrary-factor count, to audit claimed state budgets."], "source_sha256": "51922b92442477f5720faf352b8e71c7fced8246c0e5d685a5711aaf9779f294", "access_date": "2026-11-17", "date_semantics": "date is inspected preprint revision; publication_date is independently retrieved journal date at its stated precision; access_date is retrieval.", "family": ["D", "F", "H"], "id": "PAPER-D301", "arxiv": "1410.0283", "read_scope": "Targeted primary reading: introduction/conventions; Theorem2.1 and proof,pp5–6; §3 Theorem3.1/proof and cancellation remarks,pp10–11. Full19-page text, all cited Potapov theory and matrix-fraction results not audited.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-D301.md", "track_file": "papers/inner_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-D301"]}','Characterizations of rectangular (para)-unitary rational functions','["Daniel Alpay", "Palle Jorgensen", "Izchak Lewkowicz"]','["D", "F", "H"]','2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/1410.0283v2','51922b92442477f5720faf352b8e71c7fced8246c0e5d685a5711aaf9779f294','papers/PAPER-D301.md','papers/inner_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-D302','corpus/bibliography.jsonl',605,'full_text_accessed','papers/PAPER-D302.md','{"paper_id": "PAPER-D302", "title": "Trapped modes in linear quantum stochastic networks with delays", "authors": ["Gil Tabak", "Hideo Mabuchi"], "year": 2016, "date": "2016-03-02", "publication_date": "2016-03-03", "venue": "EPJ Quantum Technology 3, article3", "doi": "10.1140/epjqt/s40507-016-0041-9", "arxiv_id": "1510.08942", "version": "v2", "version_date": "2016-03-02", "first_submission_date": "2015-10-29", "preprint_year": 2015, "publication_year": 2016, "canonical_url": "https://arxiv.org/abs/1510.08942v2", "source_url": "https://arxiv.org/pdf/1510.08942v2", "publication_status": "journal", "full_text_access": "26-page arXivv2 PDF downloaded and text extracted; private research copy.", "bibliographic_verified": true, "full_text_accessed": true, "substantive_reading": false, "audit_level": 0, "audit_scope": "Targeted primary reading of preliminaries/passivity context, §5 equations15–20 and half-plane factorization discussion,pp6–7; §9 equations39–43,p18, passive single-factor realization and cascade interpretation. Numerical simulations, infinite factor convergence and all appendices not audited; not a completed whole-paperL1.", "correction_search": "Primary arXiv history v1 2015-10-29,v2 2016-03-02 inspected; no exhaustive later correction search. PDF internal compilation date2022 is not treated as a new arXiv revision.", "selected": true, "main_results": [{"locator": "§5,equations15–20,pp6–7", "statement": "Half-plane passive inner transfer functions are discussed via Blaschke–Potapov factors and a separate singular/delay factor; finite factor phase constants can be absorbed in a unitary prefactor."}, {"locator": "§9,equations39–43,p18", "statement": "A rank-one factor is realized in passive state-space form with A=−C_out* C_out/2−iΩ, B=−C_out*D, and unitary D; successive factors are interpreted as a cascade."}], "limitations": ["Passive open-system input/output realization is not itself the closed compact-resolvent Hilbert-space proof; that proof is supplied separately in the campaign.", "Delay/singular inner factors and infinite products are outside a finite rational-degree budget unless explicitly accounted for.", "Full26-page mathematical/numerical audit was not completed."], "research_questions": ["Verify closed feedback boundary domains and dark-state accounting before importing open-system transfer identities into spectral counting.", "Preserve the Laplace-to-wave-number change s=−ik and the lower-half-plane pole convention."], "source_sha256": "f41a089bae35601b5be4e295a2b4dcd740d27ee470dd10ca68d811aa83dbb646", "access_date": "2026-11-17", "date_semantics": "date is inspected preprint revision; publication_date is independently retrieved journal date at its stated precision; access_date is retrieval.", "family": ["D", "F", "H"], "id": "PAPER-D302", "arxiv": "1510.08942", "read_scope": "Targeted primary reading of preliminaries/passivity context, §5 equations15–20 and half-plane factorization discussion,pp6–7; §9 equations39–43,p18, passive single-factor realization and cascade interpretation. Numerical simulations, infinite factor convergence and all appendices not audited; not a completed whole-paperL1.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-D302.md", "track_file": "papers/inner_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-D302"]}','Trapped modes in linear quantum stochastic networks with delays','["Gil Tabak", "Hideo Mabuchi"]','["D", "F", "H"]','2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/1510.08942v2','f41a089bae35601b5be4e295a2b4dcd740d27ee470dd10ca68d811aa83dbb646','papers/PAPER-D302.md','papers/inner_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-C110','corpus/bibliography.jsonl',606,'full_text_accessed','papers/PAPER-C110.md','{"id": "PAPER-C110", "title": "On Robin’s inequality and the Kaneko-Lagarias inequality", "authors": ["Idris Assani", "Aiden Chester", "Alex Paschal"], "date": "2025-08-16", "year": 2025, "venue": "arXiv preprint", "publication_status": "preprint_version_inspected", "doi": null, "arxiv": "2503.03159", "source_url": "https://arxiv.org/abs/2503.03159v2", "version": "v2,16August2025", "family": ["C", "A", "F"], "audit_level": 0, "whole_work_read": false, "inspected_portions_level": 2, "read_scope": "10-pagePDFaccessed. Read introductionpp1–2, complete§3pp7–9 and referencesp10. Robin-familyargumentsin§2notfullyread. MonotonicityandSA-implicationin§3 inspected; actualreal-limitidentitydistinguishedfromintegerformula andalternatecontinuousproofsupplied.", "access_status": "full_text_accessed", "source_file": "sources/lagarias_compact/2503.03159.pdf", "source_sha256": "e2668e7143e7c0aeeccb35f1dc87d0d20f5833d44312db42e550977a4f5976b7", "accessed_at": "2026-11-17", "main_result": "Proposition3.6 pp8–9 states K(x)=exp(H(x))logH(x)/x increasesforrealx≥4; Corollary3.7 givesmonotonicityatallintegers; Theorem3.9 p9 reducesleastKaneko–LagariascounterexamplestoSA. The sourceexplicitlyleavesanalogousoriginalLagariasextensionforfuturework(p2).", "limitations": ["DifferentprofilefromoriginalLagariasB(x)/x: no additiveH term.", "No logarithmicconcavitytheorem identified in§3.", "Itsreal-variableg_k-limitassertionusesanidentityoriginallystatedatintegers; a directalternateproofrepairscontinuousmonotonicity.", "Whole§2 andauthorsfinitechecksnotfullyaudited."], "research_questions": ["RecordshortdirectmonotonicityproofusingHlogH<x andxH′≥x/(x+1).", "Checkpriorityforglobal logconcavityoforiginalLagariasprofileacrossfurthercitedsources."], "correction_search_status": "actualv2 inspected; exhaustivecorrectionandforwardcitationsearchincomplete", "original_access_status": "full_