INSERT INTO "papers" VALUES('PAPER-C108','corpus/bibliography.jsonl',607,'full_text_accessed','papers/PAPER-C108.md','{"id": "PAPER-C108", "title": "On the Lagarias Inequality and Superabundant Numbers", "authors": ["Andrew MacArevey"], "date": "2026-02-19", "first_submission_date": "2026-02-16", "year": 2026, "venue": "arXiv preprint", "publication_status": "preprint_version_inspected", "doi": null, "arxiv": "2602.15905", "source_url": "https://arxiv.org/abs/2602.15905v2", "version": "v2,19February2026", "family": ["C", "A", "F"], "audit_level": 1, "whole_work_read": true, "read_scope": "Complete seven-page preprint read, including all proof text and references. Elementary monotonicity inequalities reconstructed; the reported finite direct checks1≤n≤54 were not replayed from author code.", "access_status": "full_text_accessed", "source_file": "sources/lagarias_compact/2602.15905.pdf", "source_sha256": "664da0ae3ace7e0bc1d13dfc7b4e5cc8d791904563f2047cb23dedec85a39e4e", "accessed_at": "2026-11-17", "main_result": "Proposition2.1 pp5–6 proves L′(x)>0 forx≥e^4, whereL(x)=[H(x)+exp(H(x))logH(x)]/x andH=digamma(x+1)+gamma. Corollary2.1 p6 states integer sequenceL(n) strictlyincreases foralln≥1, using finitechecksbelow55. Theorem3.1 p6 proves anyleast Lagarias counterexample must be superabundant.", "proof_architecture": ["DifferentiateL tofirst-derivativenumeratorN(x)", "BoundH′≥1/(x+1), log(x+1)≤H≤1+logx", "Obtain elementary lowerboundG(x) forN(x)", "Forlogx≥4, e^t≥2t²+3t+1makesGpositive", "Supplementwithfiniteintegerchecksbelow55", "Earlierrecordabundancy andmonotonicL forceleastcounterexampleSA"], "limitations": ["No log-concavity claim appears in the actual source.", "Continuous monotonicity is provedonly forx≥e^4; fullinteger monotonicity uses reportedfinitechecks.", "The source first-derivativeN(x) is different from the compactcampaignsecond-derivative numeratorN(h).", "NoRH proof or prescribedinfiniteendpointverification."], "research_questions": ["Can strongerglobal logarithmicconcavity yield common-parameter support-line interval certificates?"], "correction_search_status": "arXivv1/v2historychecked; exhaustiveforwardcitationprioritysearchincomplete", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-C108.md", "track_file": "papers/lagarias_sources_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-C108"]}','On the Lagarias Inequality and Superabundant Numbers','["Andrew MacArevey"]','["C", "A", "F"]','2026',1,1,'selected_checkpoint_priority_work','full_text_accessed','v2,19February2026','https://arxiv.org/abs/2602.15905v2','664da0ae3ace7e0bc1d13dfc7b4e5cc8d791904563f2047cb23dedec85a39e4e','papers/PAPER-C108.md','papers/lagarias_sources_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-C109','corpus/bibliography.jsonl',608,'full_text_accessed','papers/PAPER-C109.md','{"id": "PAPER-C109", "title": "VGPT-RSI for RH-Adjacent Formal Progress: Boundary Certificates, Verified Finite Lagarias Inequalities, and Explicit Failure Localization", "authors": ["Zhixin Hu", "Tao Xu", "Xiaodian Sun", "Li Jin", "Momiao Xiong"], "date": "2026-06-13", "year": 2026, "venue": "arXiv preprint,cs.AI", "publication_status": "preprint_version_inspected", "doi": null, "arxiv": "2606.15096", "source_url": "https://arxiv.org/abs/2606.15096v1", "version": "v1,13June2026", "family": ["C", "F", "H"], "audit_level": 0, "whole_work_read": false, "inspected_portions_level": 1, "read_scope": "31-pagePDF accessed. Read title/abstractpp1–3, Lagariasmethodspp12–18, finite-certificate/results/discussionpp20–26 and referencespp27–28. Relevantstatements compared; boundary-curve derivation not fully read; figuresnotindependentlyaudited; formal code/artifactsnotobtainedorreplayed.", "access_status": "full_text_accessed", "source_file": "sources/lagarias_compact/2606.15096.pdf", "source_sha256": "64a27d598053422cd918bb682c9008d49bc0503e41913636f507d2e841b2237a", "accessed_at": "2026-11-17", "main_result": "Source reports a Coq/CoqInterval finitecertificate forσ(n)≤H_n+exp(H_n)logH_n for1≤n≤10000, assembledfromtenchunks (pp21–23), and a separate finite boundary-curve certificate. It explicitly leavesglobaltail andextremal-integerreductionunresolved (pp17–18,24).", "proof_architecture": ["EncodefiniteLagariasobjects", "Grouptranscendental inequalitiesoverharmoniclowerbounds", "Useprime-power/multiplicativefactorizationsforfiniteσ upperbounds", "Compileten1000-integerchunks anddispatchwrapper", "Reportnonrecursivechecker/assumptionaudit; fullrecursivecheckertimeout", "Preserveglobaltailstatementasoutstanding"], "limitations": ["Formal-check claims are source-reported andnotindependentlyreplayed inthistrack.", "Codefilenamesaregiven but no machine-checkableartifactbundle wasobtained.", "No smoothharmonicprofileconcavity or common-εsupportendpoint theorem identifiedininspectedsections.", "Finiteverificationdoesnotproveglobaltail orRH.", "BoundaryB(x,T) isnotourLagariasenvelopeB(x)."], "research_questions": ["Obtain exactformalartifactversionsanddependenciesforindependentreplay.", "Separatefinitearithmeticcertificates froma calculuslemma enablingconditionalendpointinterpolation."], "correction_search_status": "arXivv1historychecked; formalartifact/versionandforwardcitationsearchincomplete", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-C109.md", "track_file": "papers/lagarias_sources_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-C109"]}','VGPT-RSI for RH-Adjacent Formal Progress: Boundary Certificates, Verified Finite Lagarias Inequalities, and Explicit Failure Localization','["Zhixin Hu", "Tao Xu", "Xiaodian Sun", "Li Jin", "Momiao Xiong"]','["C", "F", "H"]','2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1,13June2026','https://arxiv.org/abs/2606.15096v1','64a27d598053422cd918bb682c9008d49bc0503e41913636f507d2e841b2237a','papers/PAPER-C109.md','papers/lagarias_sources_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-001','corpus/bibliography.jsonl',609,'full_text_accessed','papers/PAPER-ANALYTIC62-001.md','{"paper_id": "PAPER-ANALYTIC62-001", "title": "Explicit results on the distribution of zeros of Hecke $L$-functions", "authors": ["Jesse Thorner", "Asif Zaman"], "year": 2016, "venue": "Journal of Number Theory", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2016-05", "online_publication_date": null, "doi": "10.1016/j.jnt.2015.10.003", "arxiv_id": "1510.08086", "version": "v1", "version_date": "2015-10-27", "first_submission_date": "2015-10-27", "canonical_url": "https://arxiv.org/abs/1510.08086v1", "source_url": "https://arxiv.org/pdf/1510.08086v1", "source_path": "sources/latest62_analytic2/1510.08086.pdf", "source_sha256": "94ddf7864fe74d266cef42816c9621516079321c48069d848527e7d0067b866d", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 32, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Theorem 1.1 and definitions checked in v1. Journal identity has a different title.", "statement": "Theorem 1.1 gives the effective log-free bound \\(\\sum_{\\chi(H)=1}N(\\sigma,T,\\chi)\\ll\\{e^{O(n_K)}D_K^2QT^{n_K}\\}^{81(1-\\sigma)}\\) for \\(1/2\\le\\sigma<1\\) and \\(T\\ge\\max\\{n_K D_K^{-2/n_K}Q^{-3/(5n_K)},1\\}\\). Here \\(H\\bmod\\mathfrak q\\) is a congruence class group in a number field \\(K\\) and \\(Q\\) is the largest primitive conductor norm for characters trivial on \\(H\\). The exponent constant 74 applies for \\(1-10^{-3}\\le\\sigma<1\\).", "statement_locator": "Theorem 1.1 and (1.10)–(1.12)", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-001.md", "version_receipt": "sources/latest62_analytic2/1510.08086.html", "publication_receipt": "sources/latest62_analytic2/1510.08086.doi.json", "id": "PAPER-ANALYTIC62-001", "arxiv": "1510.08086", "read_scope": "Theorem 1.1 and definitions checked in v1. Journal identity has a different title.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-001"]}','Explicit results on the distribution of zeros of Hecke $L$-functions','["Jesse Thorner", "Asif Zaman"]',NULL,'2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/1510.08086v1','94ddf7864fe74d266cef42816c9621516079321c48069d848527e7d0067b866d','papers/PAPER-ANALYTIC62-001.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-002','corpus/bibliography.jsonl',610,'full_text_accessed','papers/PAPER-ANALYTIC62-002.md','{"paper_id": "PAPER-ANALYTIC62-002", "title": "An explicit bound for the least prime ideal in the Chebotarev density theorem", "authors": ["Jesse Thorner", "Asif Zaman"], "year": 2017, "venue": "Algebra &amp; Number Theory", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2017-07-12", "online_publication_date": "2017-07-12", "doi": "10.2140/ant.2017.11.1135", "arxiv_id": "1604.01750", "version": "v2", "version_date": "2016-08-17", "first_submission_date": "2016-04-06", "canonical_url": "https://arxiv.org/abs/1604.01750v2", "source_url": "https://arxiv.org/pdf/1604.01750v2", "source_path": "sources/latest62_analytic2/1604.01750.pdf", "source_sha256": "5c4877ac9c0f0e5dc0c377ca966fb97f4aae6912c669b2f1334591aec0f36ee4", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 45, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Density theorem and main Chebotarev setup inspected, proofs outside scope.", "statement": "Theorem 3.2 gives \\(\\sum_{\\chi\\bmod H}N(\\sigma,T,\\chi)\\ll\\{e^{O(n_K)}D_K^2QT^{n_K+2}\\}^{81(1-\\sigma)}\\) for \\(1/2\\le\\sigma<1\\), \\(T\\ge\\max\\{n_K^{5/6}D_K^{-4/(3n_K)}Q^{-4/(9n_K)},1\\}\\), with 73.5 replacing 81 for \\(1-10^{-3}\\le\\sigma<1\\). The Chebotarev application uses this family density theorem with the separate repulsion estimate and an abelian subgroup meeting the target conjugacy class.", "statement_locator": "Theorems 1.1, 3.2–3.3", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-002.md", "version_receipt": "sources/latest62_analytic2/1604.01750.html", "publication_receipt": "sources/latest62_analytic2/1604.01750.doi.json", "id": "PAPER-ANALYTIC62-002", "arxiv": "1604.01750", "read_scope": "Density theorem and main Chebotarev setup inspected, proofs outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-002"]}','An explicit bound for the least prime ideal in the Chebotarev density theorem','["Jesse Thorner", "Asif Zaman"]',NULL,'2017',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/1604.01750v2','5c4877ac9c0f0e5dc0c377ca966fb97f4aae6912c669b2f1334591aec0f36ee4','papers/PAPER-ANALYTIC62-002.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-003','corpus/bibliography.jsonl',611,'full_text_accessed','papers/PAPER-ANALYTIC62-003.md','{"paper_id": "PAPER-ANALYTIC62-003", "title": "More than five-twelfths of the zeros of $\\zeta$ are on the critical line", "authors": ["Kyle Pratt", "Nicolas Robles", "Alexandru Zaharescu", "Dirk Zeindler"], "year": 2020, "venue": "Research in the Mathematical Sciences", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2020-03", "online_publication_date": "2019-12-06", "doi": "10.1007/s40687-019-0199-8", "arxiv_id": "1802.10521", "version": "v3", "version_date": "2019-09-15", "first_submission_date": "2018-02-28", "canonical_url": "https://arxiv.org/abs/1802.10521v3", "source_url": "https://arxiv.org/pdf/1802.10521v3", "source_path": "sources/latest62_analytic2/1802.10521.pdf", "source_sha256": "147187ac00831b06e674a99705b0798181eb03024b1b09fc2b740610c80b90aa", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 60, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Theorem 1.2, surrounding optimization and statement of the mollified main moment checked. Long proofs outside scope.", "statement": "Theorem 1.2 proves more than \\(5/12\\) of zeta zeros are on the critical line. The numerical optimization in the introduction gives \\(\\kappa>0.417293\\) and \\(\\kappa^*\\ge0.407511\\) for the simple critical proportion. These are different counts, both based on mollified twisted second moments.", "statement_locator": "Theorem 1.2 and preceding paragraph", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-003.md", "version_receipt": "sources/latest62_analytic2/1802.10521.html", "publication_receipt": "sources/latest62_analytic2/1802.10521.doi.json", "id": "PAPER-ANALYTIC62-003", "arxiv": "1802.10521", "read_scope": "Theorem 1.2, surrounding optimization and statement of the mollified main moment checked. Long proofs outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-003"]}','More than five-twelfths of the zeros of $\zeta$ are on the critical line','["Kyle Pratt", "Nicolas Robles", "Alexandru Zaharescu", "Dirk Zeindler"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','v3','https://arxiv.org/pdf/1802.10521v3','147187ac00831b06e674a99705b0798181eb03024b1b09fc2b740610c80b90aa','papers/PAPER-ANALYTIC62-003.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-004','corpus/bibliography.jsonl',612,'full_text_accessed','papers/PAPER-ANALYTIC62-004.md','{"paper_id": "PAPER-ANALYTIC62-004", "title": "An unconditional $\\mathrm{GL}(n)$ large sieve", "authors": ["Jesse Thorner", "Asif Zaman"], "year": 2021, "venue": "Advances in Mathematics", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2021-02", "online_publication_date": null, "doi": "10.1016/j.aim.2020.107529", "arxiv_id": "1906.07717", "version": "v6", "version_date": "2021-03-10", "first_submission_date": "2019-06-18", "canonical_url": "https://arxiv.org/abs/1906.07717v6", "source_url": "https://arxiv.org/pdf/1906.07717v6", "source_path": "sources/latest62_analytic2/1906.07717.pdf", "source_sha256": "525a52db9d70ac93dcb1b1015769a8e61f9bac07b6b657c51f7b7bade78ce5b5", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 17, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Theorems 1.1–1.2 and family definition checked in v6.", "statement": "Theorem 1.2 bounds the sum of \\(N_\\pi(\\sigma,T)=\\#\\{\\rho:\\beta>\\sigma,\\,|\\gamma|\\le T\\}\\) over cuspidal \\(\\pi\\) on \\(\\mathrm{GL}_n\\) over \\(F\\) of analytic conductor at most \\(Q\\) by \\(O_{n,[F:\\mathbb Q]}((QT^{[F:\\mathbb Q]})^{(7/10)n^4(1-\\sigma)})\\), for \\(Q,T\\ge1\\), \\(0\\le\\sigma\\le1\\). The log-free estimate is unconditional in this family and does not assume Ramanujan.", "statement_locator": "Theorem 1.2 and (1.4)", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-004.md", "version_receipt": "sources/latest62_analytic2/1906.07717.html", "publication_receipt": "sources/latest62_analytic2/1906.07717.doi.json", "id": "PAPER-ANALYTIC62-004", "arxiv": "1906.07717", "read_scope": "Theorems 1.1–1.2 and family definition checked in v6.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-004"]}','An unconditional $\mathrm{GL}(n)$ large sieve','["Jesse Thorner", "Asif Zaman"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','v6','https://arxiv.org/pdf/1906.07717v6','525a52db9d70ac93dcb1b1015769a8e61f9bac07b6b657c51f7b7bade78ce5b5','papers/PAPER-ANALYTIC62-004.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-005','corpus/bibliography.jsonl',613,'full_text_accessed','papers/PAPER-ANALYTIC62-005.md','{"paper_id": "PAPER-ANALYTIC62-005", "title": "A zero density estimate for Dedekind zeta functions", "authors": ["Jesse Thorner", "Asif Zaman"], "year": 2023, "venue": "International Mathematics Research Notices", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2023-04-12", "online_publication_date": "2022-03-21", "doi": "10.1093/imrn/rnac015", "arxiv_id": "1909.01338", "version": "v2", "version_date": "2022-01-06", "first_submission_date": "2019-09-03", "canonical_url": "https://arxiv.org/abs/1909.01338v2", "source_url": "https://arxiv.org/pdf/1909.01338v2", "source_path": "sources/latest62_analytic2/1909.01338.pdf", "source_sha256": "49b1d56c46f54b73b69dc7d0f7082b6ec7174a5da16bd5fedded90563c032c2e", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 14, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Theorems 1.1 and 2.1 and quotient count checked. Journal issue date differs from online first.", "statement": "For a finite nontrivial group \\(G\\) and a family \\(\\mathcal F_G(Q)\\) of Galois \\(K/\\mathbb Q\\) with group \\(G\\) and discriminant at most \\(Q\\), Theorem 1.1 sums the zero counts for \\(\\zeta_K/\\zeta\\). For \\(\\sigma\\ge0,\\ Q,T\\ge2\\), the result is \\(O_{|G|}(m_{\\mathcal F_G}(Q)(QT)^{(7/10)|G|^3(1-\\sigma)}(\\log QT)^{|G|^2})\\), with \\(m\\) the maximal number of family fields intersecting one chosen member nontrivially.", "statement_locator": "Theorem 1.1, equations (1.1)–(1.2)", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-005.md", "version_receipt": "sources/latest62_analytic2/1909.01338.html", "publication_receipt": "sources/latest62_analytic2/1909.01338.doi.json", "id": "PAPER-ANALYTIC62-005", "arxiv": "1909.01338", "read_scope": "Theorems 1.1 and 2.1 and quotient count checked. Journal issue date differs from online first.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-005"]}','A zero density estimate for Dedekind zeta functions','["Jesse Thorner", "Asif Zaman"]',NULL,'2023',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/1909.01338v2','49b1d56c46f54b73b69dc7d0f7082b6ec7174a5da16bd5fedded90563c032c2e','papers/PAPER-ANALYTIC62-005.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-006','corpus/bibliography.jsonl',614,'full_text_accessed','papers/PAPER-ANALYTIC62-006.md','{"paper_id": "PAPER-ANALYTIC62-006", "title": "Explicit zero density estimate for the Riemann zeta-function near the critical line", "authors": ["Aleksander Simonič"], "year": 2020, "venue": "Journal of Mathematical Analysis and Applications", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2020-11", "online_publication_date": null, "doi": "10.1016/j.jmaa.2020.124303", "arxiv_id": "1910.08274", "version": "v2", "version_date": "2019-11-29", "first_submission_date": "2019-10-18", "canonical_url": "https://arxiv.org/abs/1910.08274v2", "source_url": "https://arxiv.org/pdf/1910.08274v2", "source_path": "sources/latest62_analytic2/1910.08274.pdf", "source_sha256": "f2063ae6d962283eb59d0ba0b8ce12073de002abc6e3c853b7127fd4e91e334c", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 35, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Theorem 1 and definition of H0 checked in v2. Numerical estimates and journal proof comparison outside read scope.", "statement": "For the verification height \\(H_0=3.0610046\\times10^{10}\\) used by the paper, Theorem 1 proves \\(N(\\sigma,2T)-N(\\sigma,T)\\le10395.2\\,T^{1-(\\sigma-1/2)/4}\\log T+1.104\\log^2T+0.173\\log T\\log\\log T+0.51\\log T\\) for \\(T\\ge H_0,\\ 1/2\\le\\sigma\\le0.831\\). The interval is dyadic rather than of sublinear length.", "statement_locator": "Theorem 1", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-006.md", "version_receipt": "sources/latest62_analytic2/1910.08274.html", "publication_receipt": "sources/latest62_analytic2/1910.08274.doi.json", "id": "PAPER-ANALYTIC62-006", "arxiv": "1910.08274", "read_scope": "Theorem 1 and definition of H0 checked in v2. Numerical estimates and journal proof comparison outside read scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-006"]}','Explicit zero density estimate for the Riemann zeta-function near the critical line','["Aleksander Simonič"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/1910.08274v2','f2063ae6d962283eb59d0ba0b8ce12073de002abc6e3c853b7127fd4e91e334c','papers/PAPER-ANALYTIC62-006.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-007','corpus/bibliography.jsonl',615,'full_text_accessed','papers/PAPER-ANALYTIC62-007.md','{"paper_id": "PAPER-ANALYTIC62-007", "title": "Explicit zero density for the Riemann zeta function", "authors": ["Habiba Kadiri", "Allysa Lumley", "Nathan Ng"], "year": 2018, "venue": "Journal of Mathematical Analysis and Applications", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2018-09", "online_publication_date": null, "doi": "10.1016/j.jmaa.2018.04.071", "arxiv_id": "2101.12263", "version": "v1", "version_date": "2021-01-28", "first_submission_date": "2021-01-28", "canonical_url": "https://arxiv.org/abs/2101.12263v1", "source_url": "https://arxiv.org/pdf/2101.12263v1", "source_path": "sources/latest62_analytic2/2101.12263.pdf", "source_sha256": "fb11226af17a06d9246120d827abe98bec817ecec23554573d6b84110b4c3303", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 24, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Theorem and explicit constant locators checked in arXiv copy.", "statement": "Theorem 1.1, (1.7), gives \\(N(\\sigma,T)\\le(C_1/(2\\pi d))T^{8(1-\\sigma)/3}(\\log(kT))^{2\\sigma}(\\log T)^{5-4\\sigma}+(C_2/(2\\pi d))(\\log T)^2\\) for \\(T\\ge H_0,\\ \\sigma>1/2+d/\\log H_0\\), with \\(10^9/H_0\\le k\\le1,\\ H\\in[1002,H_0),\\ \\alpha>0,\\delta\\ge1,\\ 1+\\eta_0\\le\\mu\\le1+\\eta,\\ \\eta\\in(\\eta_0,1/2)\\), \\(d>0\\), and \\(\\eta_0=0.23622\\ldots\\). The preceding displayed (1.6) retains the logarithm with smaller numerical value. Constants \\(C_1,C_2\\) are explicit in (4.72)–(4.73).", "statement_locator": "Theorem 1.1, (1.6)–(1.7)", "version_note": "The 2018 journal article predates the 2021 arXiv deposit.", "record_path": "papers/PAPER-ANALYTIC62-007.md", "version_receipt": "sources/latest62_analytic2/2101.12263.html", "publication_receipt": "sources/latest62_analytic2/2101.12263.doi.json", "id": "PAPER-ANALYTIC62-007", "arxiv": "2101.12263", "read_scope": "Theorem and explicit constant locators checked in arXiv copy.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-007"]}','Explicit zero density for the Riemann zeta function','["Habiba Kadiri", "Allysa Lumley", "Nathan Ng"]',NULL,'2018',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2101.12263v1','fb11226af17a06d9246120d827abe98bec817ecec23554573d6b84110b4c3303','papers/PAPER-ANALYTIC62-007.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-008','corpus/bibliography.jsonl',616,'full_text_accessed','papers/PAPER-ANALYTIC62-008.md','{"paper_id": "PAPER-ANALYTIC62-008", "title": "Half-isolated zeros and zero-density estimates", "authors": ["James Maynard", "Kyle Pratt"], "year": 2024, "venue": "International Mathematics Research Notices", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2024-10-07", "online_publication_date": "2024-09-06", "doi": "10.1093/imrn/rnae191", "arxiv_id": "2206.11729", "version": "v2", "version_date": "2023-05-29", "first_submission_date": "2022-06-23", "canonical_url": "https://arxiv.org/abs/2206.11729v2", "source_url": "https://arxiv.org/pdf/2206.11729v2", "source_path": "sources/latest62_analytic2/2206.11729.pdf", "source_sha256": "e6407c953c4ddcbf9daa2fa941d1a84bf9db90f19a96e50ee8796bf9aea5947a", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 39, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Hypothesis F, Theorem 1 and the beginning of the detector statements checked in v2. Full proof outside scope.", "statement": "Under Hypothesis F that all nontrivial zeta zeros lie on finitely many fixed vertical lines, Theorem 1 gives \\(N(\\sigma,T)\\ll T^{2(1-\\sigma)}\\exp((\\log\\log T)^{O(1)})\\). Half-isolated zeros admit short detecting polynomials, and the argument separates horizontal and vertical clustering. The hypothesis is weaker than RH but remains an extra restriction on zeta zeros.", "statement_locator": "Theorem 1 and §1 Hypothesis F", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-008.md", "version_receipt": "sources/latest62_analytic2/2206.11729.html", "publication_receipt": "sources/latest62_analytic2/2206.11729.doi.json", "id": "PAPER-ANALYTIC62-008", "arxiv": "2206.11729", "read_scope": "Hypothesis F, Theorem 1 and the beginning of the detector statements checked in v2. Full proof outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-008"]}','Half-isolated zeros and zero-density estimates','["James Maynard", "Kyle Pratt"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/2206.11729v2','e6407c953c4ddcbf9daa2fa941d1a84bf9db90f19a96e50ee8796bf9aea5947a','papers/PAPER-ANALYTIC62-008.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-009','corpus/bibliography.jsonl',617,'full_text_accessed','papers/PAPER-ANALYTIC62-009.md','{"paper_id": "PAPER-ANALYTIC62-009", "title": "An explicit Vinogradov-Korobov zero-free region for Dirichlet L-functions", "authors": ["Tanmay Khale"], "year": 2024, "venue": "The Quarterly Journal of Mathematics", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2024-04-15", "online_publication_date": "2024-03-18", "doi": "10.1093/qmath/haae010", "arxiv_id": "2210.06457", "version": "v1", "version_date": "2022-10-12", "first_submission_date": "2022-10-12", "canonical_url": "https://arxiv.org/abs/2210.06457v1", "source_url": "https://arxiv.org/pdf/2210.06457v1", "source_path": "sources/latest62_analytic2/2210.06457.pdf", "source_sha256": "e232e295f93e4b3be4e33d4a0043145645832316fd765fde89eadfc7b735c136", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 29, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Theorem 1.1 and the height/conductor parameter definitions checked in v1.", "statement": "For every character modulo \\(q\\ge3\\), Theorem 1.1 excludes zeros for \\(|t|\\ge10\\) and \\(\\sigma\\ge1-[10.5\\log q+61.5(\\log|t|)^{2/3}(\\log\\log|t|)^{1/3}]^{-1}\\). Beyond an absolute effectively computable threshold it replaces \\(10.5,61.5\\) by \\(10.1,49.13\\). This high-height result does not rule out a possible low real exceptional zero.", "statement_locator": "Equations (1.2)–(1.3)", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-009.md", "version_receipt": "sources/latest62_analytic2/2210.06457.html", "publication_receipt": "sources/latest62_analytic2/2210.06457.doi.json", "id": "PAPER-ANALYTIC62-009", "arxiv": "2210.06457", "read_scope": "Theorem 1.1 and the height/conductor parameter definitions checked in v1.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-009"]}','An explicit Vinogradov-Korobov zero-free region for Dirichlet L-functions','["Tanmay Khale"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2210.06457v1','e232e295f93e4b3be4e33d4a0043145645832316fd765fde89eadfc7b735c136','papers/PAPER-ANALYTIC62-009.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-010','corpus/bibliography.jsonl',618,'full_text_accessed','papers/PAPER-ANALYTIC62-010.md','{"paper_id": "PAPER-ANALYTIC62-010", "title": "Explicit zero-free regions for the Riemann zeta-function", "authors": ["Michael J. Mossinghoff", "Timothy S. Trudgian", "Andrew Yang"], "year": 2024, "venue": "Research in Number Theory", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2024-03", "online_publication_date": "2024-01-12", "doi": "10.1007/s40993-023-00498-y", "arxiv_id": "2212.06867", "version": "v1", "version_date": "2022-12-13", "first_submission_date": "2022-12-13", "canonical_url": "https://arxiv.org/abs/2212.06867v1", "source_url": "https://arxiv.org/pdf/2212.06867v1", "source_path": "sources/latest62_analytic2/2212.06867.pdf", "source_sha256": "127c32eb86d0aea264cc5b1ba96cc83243ef6b763451591e1560edaca1767300", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 27, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Theorems 1.1–1.3 checked in v1. Polynomial numerical verification outside scope.", "statement": "Theorems 1.1–1.2 exclude zeros for \\(\\sigma\\ge1-[C(\\log|t|)^{2/3}(\\log\\log|t|)^{1/3}]^{-1}\\) with \\(C=55.241\\) for \\(|t|\\ge3\\), and \\(C=48.1588\\) for sufficiently large \\(|t|\\). Theorem 1.3 excludes zeros for \\(\\sigma\\ge1-(5.558691\\log|t|)^{-1}\\) and \\(|t|\\ge2\\). These are distinct height-dependent regions.", "statement_locator": "Equations (1.5)–(1.7)", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-010.md", "version_receipt": "sources/latest62_analytic2/2212.06867.html", "publication_receipt": "sources/latest62_analytic2/2212.06867.doi.json", "id": "PAPER-ANALYTIC62-010", "arxiv": "2212.06867", "read_scope": "Theorems 1.1–1.3 checked in v1. Polynomial numerical verification outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-010"]}','Explicit zero-free regions for the Riemann zeta-function','["Michael J. Mossinghoff", "Timothy S. Trudgian", "Andrew Yang"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2212.06867v1','127c32eb86d0aea264cc5b1ba96cc83243ef6b763451591e1560edaca1767300','papers/PAPER-ANALYTIC62-010.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-011','corpus/bibliography.jsonl',619,'full_text_accessed','papers/PAPER-ANALYTIC62-011.md','{"paper_id": "PAPER-ANALYTIC62-011", "title": "Explicit bounds on $\\zeta(s)$ in the critical strip and a zero-free region", "authors": ["Andrew Yang"], "year": 2024, "venue": "Journal of Mathematical Analysis and Applications", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2024-06", "online_publication_date": null, "doi": "10.1016/j.jmaa.2024.128124", "arxiv_id": "2301.03165", "version": "v2", "version_date": "2024-01-16", "first_submission_date": "2023-01-09", "canonical_url": "https://arxiv.org/abs/2301.03165v2", "source_url": "https://arxiv.org/pdf/2301.03165v2", "source_path": "sources/latest62_analytic2/2301.03165.pdf", "source_sha256": "ca09f14b33a2cda33502d17742c81b4cfe746f6addfd4bd1edd31eb710bddffc", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 51, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Theorem 1.1 and Corollary 1.2 checked in v2. No independent verification of the numerical optimization or comparison to subsequent bounds.", "statement": "Theorem 1.1 gives \\(|\\zeta(\\sigma_k+it)|\\le1.546\\,t^{1/(2^k-2)}\\log t\\) for \\(k\\ge4,\\ \\sigma_k=1-k/(2^k-2),\\ t\\ge3\\). Corollary 1.2 excludes zeros for \\(|t|\\ge3,\\ \\sigma>1-\\log\\log|t|/(21.233\\log|t|)\\), an explicit Littlewood-type region used in later finite-height patching.", "statement_locator": "Equations (1.2), (1.6)", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-011.md", "version_receipt": "sources/latest62_analytic2/2301.03165.html", "publication_receipt": "sources/latest62_analytic2/2301.03165.doi.json", "id": "PAPER-ANALYTIC62-011", "arxiv": "2301.03165", "read_scope": "Theorem 1.1 and Corollary 1.2 checked in v2. No independent verification of the numerical optimization or comparison to subsequent bounds.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-011"]}','Explicit bounds on $\zeta(s)$ in the critical strip and a zero-free region','["Andrew Yang"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/2301.03165v2','ca09f14b33a2cda33502d17742c81b4cfe746f6addfd4bd1edd31eb710bddffc','papers/PAPER-ANALYTIC62-011.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-012','corpus/bibliography.jsonl',620,'full_text_accessed','papers/PAPER-ANALYTIC62-012.md','{"paper_id": "PAPER-ANALYTIC62-012", "title": "Explicit bounds for the Riemann zeta function and a new zero-free region", "authors": ["Chiara Bellotti"], "year": 2024, "venue": "Journal of Mathematical Analysis and Applications", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2024-08", "online_publication_date": null, "doi": "10.1016/j.jmaa.2024.128249", "arxiv_id": "2306.10680", "version": "v1", "version_date": "2023-06-19", "first_submission_date": "2023-06-19", "canonical_url": "https://arxiv.org/abs/2306.10680v1", "source_url": "https://arxiv.org/pdf/2306.10680v1", "source_path": "sources/latest62_analytic2/2306.10680.pdf", "source_sha256": "e0703be3cb5e05577102e8db48d552346447ae749251992cfd371038cb352b4c", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 37, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Theorem 1.1, v1 numbers in Theorem 1.2, and asymptotic distinction checked.", "statement": "Theorem 1.1 bounds \\(|\\zeta(\\sigma+it)|\\) and \\(|\\zeta(\\sigma+it,u)-u^{-(\\sigma+it)}|\\) by \\(70.6995\\,|t|^{4.43795(1-\\sigma)^{3/2}}(\\log|t|)^{2/3}\\), for \\(|t|\\ge3,\\ 1/2\\le\\sigma\\le1,\\ 0<u\\le1\\) in the Hurwitz case. Theorem 1.2 gives a Vinogradov–Korobov denominator 54.004 for \\(|t|\\ge3\\) in this v1, and the subsequent sufficiently-large-height constant is 48.0718.", "statement_locator": "Theorems 1.1–1.2 and accompanying formula (1.4)", "version_note": "The March 2026 Bellotti–Trudgian–Yang preprint cites the journal work with 53.989 instead of v1’s 54.004. That is evidence of a version difference, not a comparison of the journal proof itself.", "record_path": "papers/PAPER-ANALYTIC62-012.md", "version_receipt": "sources/latest62_analytic2/2306.10680.html", "publication_receipt": "sources/latest62_analytic2/2306.10680.doi.json", "id": "PAPER-ANALYTIC62-012", "arxiv": "2306.10680", "read_scope": "Theorem 1.1, v1 numbers in Theorem 1.2, and asymptotic distinction checked.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-012"]}','Explicit bounds for the Riemann zeta function and a new zero-free region','["Chiara Bellotti"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2306.10680v1','e0703be3cb5e05577102e8db48d552346447ae749251992cfd371038cb352b4c','papers/PAPER-ANALYTIC62-012.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-013','corpus/bibliography.jsonl',621,'full_text_accessed','papers/PAPER-ANALYTIC62-013.md','{"paper_id": "PAPER-ANALYTIC62-013", "title": "A remark on density theorems for Riemann''s zeta-function", "authors": ["János Pintz"], "year": 2023, "venue": "Science China Mathematics", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2023-12", "online_publication_date": "2023-10-16", "doi": "10.1007/s11425-023-2215-7", "arxiv_id": "2310.04544", "version": "v1", "version_date": "2023-09-30", "first_submission_date": "2023-09-30", "canonical_url": "https://arxiv.org/abs/2310.04544v1", "source_url": "https://arxiv.org/pdf/2310.04544v1", "source_path": "sources/latest62_analytic2/2310.04544.pdf", "source_sha256": "0e9b49c131fb5f21dd06545037cf97d4efab364bc8893d93b5745b8a45e2b41d", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 14, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "selected": true, "audit_scope": "Full read pp. 1–14, including detector, Halász estimate, Theorem 2 and references. Theorem 1 range visually checked against (3.1).", "statement": "Writing \\(N(1-\\eta,T)\\ll_\\epsilon T^{\\eta B(\\eta)+\\epsilon}\\), the detector proof gives \\(B(\\eta)\\le\\max(4u_\\ell,3v_\\ell)\\) on \\(0<\\eta<\\min(1/3,2^{-\\ell})\\), with \\(u_\\ell=\\mu(1-2^{-\\ell})/(2^{-\\ell}-\\eta)\\), \\(v_\\ell=\\mu(1-2^{-(\\ell-1)})/[2(2^{-\\ell}-\\eta)]\\). Corollary 4 gives \\(B(\\eta)\\le1/(1-4\\eta)\\) for \\(0<\\eta<1/4\\); Corollary 1 conditionally gives \\(N(\\sigma,T)\\ll_{\\sigma,\\epsilon}T^\\epsilon\\) for fixed \\(\\sigma>3/4\\) under Lindelöf.", "statement_locator": "Theorem 1; (2.4)–(2.7), (3.1); Corollaries 1 and 4", "version_note": "Theorem 1 on v1 p. 5 prints max rather than min in its range, inconsistent with the proof and with denominators that vanish in the extra interval. The journal text was not independently compared.", "record_path": "papers/PAPER-ANALYTIC62-013.md", "version_receipt": "sources/latest62_analytic2/2310.04544.html", "publication_receipt": "sources/latest62_analytic2/2310.04544.doi.json", "id": "PAPER-ANALYTIC62-013", "arxiv": "2310.04544", "read_scope": "Full read pp. 1–14, including detector, Halász estimate, Theorem 2 and references. Theorem 1 range visually checked against (3.1).", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-013"]}','A remark on density theorems for Riemann''s zeta-function','["János Pintz"]',NULL,'2023',1,1,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2310.04544v1','0e9b49c131fb5f21dd06545037cf97d4efab364bc8893d93b5745b8a45e2b41d','papers/PAPER-ANALYTIC62-013.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-014','corpus/bibliography.jsonl',622,'full_text_accessed','papers/PAPER-ANALYTIC62-014.md','{"paper_id": "PAPER-ANALYTIC62-014", "title": "A note on the zeros of $L$-functions associated to fixed-order Dirichlet characters", "authors": ["C. C. Corrigan"], "year": 2024, "venue": "Bulletin of the Australian Mathematical Society", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2024-10", "online_publication_date": "2023-12-18", "doi": "10.1017/s0004972723001156", "arxiv_id": "2310.16518", "version": "v2", "version_date": "2023-10-31", "first_submission_date": "2023-10-25", "canonical_url": "https://arxiv.org/abs/2310.16518v2", "source_url": "https://arxiv.org/pdf/2310.16518v2", "source_path": "sources/latest62_analytic2/2310.16518.pdf", "source_sha256": "a935b3829f588650c217f6b01258a756be77e537debdaae72384c7609996d1b6", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 6, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Main table of Theorems 2.1–2.3 and family definition checked in v2.", "statement": "For \\(Q,T\\ge2,\\ 1/2<\\sigma<1\\), Theorem 2.1 sums zero counts over primitive quadratic characters of conductor at most \\(Q\\), giving \\(O_\\epsilon((QT)^\\epsilon\\min\\{(QT)^{8(1-\\sigma)/3},(Q^8T^5)^{(1-\\sigma)/(6\\sigma-3)}\\})\\). Theorems 2.2–2.3 handle orders 3, 6 and 4 with their own conductor exponents.", "statement_locator": "Theorems 2.1–2.3", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-014.md", "version_receipt": "sources/latest62_analytic2/2310.16518.html", "publication_receipt": "sources/latest62_analytic2/2310.16518.doi.json", "id": "PAPER-ANALYTIC62-014", "arxiv": "2310.16518", "read_scope": "Main table of Theorems 2.1–2.3 and family definition checked in v2.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-014"]}','A note on the zeros of $L$-functions associated to fixed-order Dirichlet characters','["C. C. Corrigan"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/2310.16518v2','a935b3829f588650c217f6b01258a756be77e537debdaae72384c7609996d1b6','papers/PAPER-ANALYTIC62-014.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-015','corpus/bibliography.jsonl',623,'full_text_accessed','papers/PAPER-ANALYTIC62-015.md','{"paper_id": "PAPER-ANALYTIC62-015", "title": "Explicit zero density estimate near unity", "authors": ["Chiara Bellotti"], "year": 2023, "venue": null, "publication_status": "arXiv preprint; journal status unverified", "publication_date": null, "online_publication_date": null, "doi": null, "arxiv_id": "2311.05136", "version": "v1", "version_date": "2023-11-09", "first_submission_date": "2023-11-09", "canonical_url": "https://arxiv.org/abs/2311.05136v1", "source_url": "https://arxiv.org/pdf/2311.05136v1", "source_path": "sources/latest62_analytic2/2311.05136.pdf", "source_sha256": "53b7f4f218e369e222548e7ce4e0f7f0bcf49e0e3ed3f9bb08b10be24fb8377d", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 24, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Theorems 1.1–1.3 checked. Author publications page states results are incorporated into the PhD thesis; no separate journal DOI verified.", "statement": "Theorem 1.2 gives \\(N(\\sigma,T)\\le C_1^\\prime T^{57.8875(1-\\sigma)^{3/2}}(\\log T)^{10393/900}\\) uniformly for \\(\\sigma\\in[0.98,1]\\), \\(T\\ge3\\), with \\(C_1^\\prime\\) tabulated by height. Theorem 1.3 gives \\(C_1^\\prime=4.45\\times10^{12}\\) for \\(T\\ge\\exp(6.7\\times10^{12})\\) in the same real-part range. The power of \\(\\log T\\) is part of the bound.", "statement_locator": "Theorems 1.1–1.3", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-015.md", "version_receipt": "sources/latest62_analytic2/2311.05136.html", "publication_receipt": null, "id": "PAPER-ANALYTIC62-015", "arxiv": "2311.05136", "read_scope": "Theorems 1.1–1.3 checked. Author publications page states results are incorporated into the PhD thesis; no separate journal DOI verified.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-015"]}','Explicit zero density estimate near unity','["Chiara Bellotti"]',NULL,'2023',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2311.05136v1','53b7f4f218e369e222548e7ce4e0f7f0bcf49e0e3ed3f9bb08b10be24fb8377d','papers/PAPER-ANALYTIC62-015.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-016','corpus/bibliography.jsonl',624,'full_text_accessed','papers/PAPER-ANALYTIC62-016.md','{"paper_id": "PAPER-ANALYTIC62-016", "title": "An explicit log-free zero density estimate for the Riemann zeta-function", "authors": ["Chiara Bellotti"], "year": 2025, "venue": "Journal of Number Theory", "publication_status": "published journal article; pinned arXiv PDF is the proof source", "publication_date": "2025-04", "online_publication_date": null, "doi": "10.1016/j.jnt.2024.10.001", "arxiv_id": "2405.12545", "version": "v2", "version_date": "2024-05-25", "first_submission_date": "2024-05-21", "canonical_url": "https://arxiv.org/abs/2405.12545v2", "source_url": "https://arxiv.org/pdf/2405.12545v2", "source_path": "sources/latest62_analytic2/2405.12545.pdf", "source_sha256": "8dd8bb96236397f236132e9f5548355443843576ef235d9d2472cfaaaea3d082", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 35, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Theorem 1.1, its one-constant specialization and Table 2 provenance checked in v2.", "statement": "Theorem 1.1 gives \\(N(\\sigma,T)\\le C T^{B(1-\\sigma)}\\) with height and real-part parameters specified in Table 2. A single explicit instance has \\(B=1.448,\\ C=1.62\\times10^{11}\\), \\(3\\times10^{12}<T\\le\\exp(6.7\\times10^{12})\\) and \\(0.9927\\le\\sigma\\le1\\). The finite upper height is essential for interpreting this log-free estimate.", "statement_locator": "Theorem 1.1 and Appendix A Table 2", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-016.md", "version_receipt": "sources/latest62_analytic2/2405.12545.html", "publication_receipt": "sources/latest62_analytic2/2405.12545.doi.json", "id": "PAPER-ANALYTIC62-016", "arxiv": "2405.12545", "read_scope": "Theorem 1.1, its one-constant specialization and Table 2 provenance checked in v2.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-016"]}','An explicit log-free zero density estimate for the Riemann zeta-function','["Chiara Bellotti"]',NULL,'2025',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/2405.12545v2','8dd8bb96236397f236132e9f5548355443843576ef235d9d2472cfaaaea3d082','papers/PAPER-ANALYTIC62-016.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-017','corpus/bibliography.jsonl',625,'full_text_accessed','papers/PAPER-ANALYTIC62-017.md','{"paper_id": "PAPER-ANALYTIC62-017", "title": "An explicit form of Ingham''s zero density estimate", "authors": ["Shashi Chourasiya", "Aleksander Simonič"], "year": 2025, "venue": null, "publication_status": "arXiv preprint; journal status unverified", "publication_date": null, "online_publication_date": null, "doi": null, "arxiv_id": "2507.15184", "version": "v2", "version_date": "2025-09-30", "first_submission_date": "2025-07-21", "canonical_url": "https://arxiv.org/abs/2507.15184v2", "source_url": "https://arxiv.org/pdf/2507.15184v2", "source_path": "sources/latest62_analytic2/2507.15184.pdf", "source_sha256": "11ebae58b467d14a20835eb732130c2c084f9440ef5e2fdbe38d697ba1e0d261", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 33, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Corollary 1 and the uniformity/uses of the intervals checked in v2. See the October Ouimet dependency audit for a specific use of the resulting uniform Ingham exponent. Contents of v1 not treated as interchangeable.", "statement": "For \\(T\\ge H_{\\rm RH}\\), Corollary 1 gives \\(N(\\sigma,T)\\le B_1T^{3(1-\\sigma)/(2-\\sigma)}(\\log T)^{(7-5\\sigma)/(2-\\sigma)}+B_2\\log^2T+B_3\\log T\\). The constants apply on the 16 subintervals \\([n/32,(n+1)/32]\\), \\(16\\le n\\le31\\), of Table 1. The strength for moving near-line \\(\\sigma\\) is uniform in each fixed table interval, with explicit logs and the Ingham power intact.", "statement_locator": "Corollary 1, (3), Table 1", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-017.md", "version_receipt": "sources/latest62_analytic2/2507.15184.html", "publication_receipt": null, "id": "PAPER-ANALYTIC62-017", "arxiv": "2507.15184", "read_scope": "Corollary 1 and the uniformity/uses of the intervals checked in v2. See the October Ouimet dependency audit for a specific use of the resulting uniform Ingham exponent. Contents of v1 not treated as interchangeable.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-017"]}','An explicit form of Ingham''s zero density estimate','["Shashi Chourasiya", "Aleksander Simonič"]',NULL,'2025',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/2507.15184v2','11ebae58b467d14a20835eb732130c2c084f9440ef5e2fdbe38d697ba1e0d261','papers/PAPER-ANALYTIC62-017.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-018','corpus/bibliography.jsonl',626,'full_text_accessed','papers/PAPER-ANALYTIC62-018.md','{"paper_id": "PAPER-ANALYTIC62-018", "title": "Zero-free regions inspired by work of Heath-Brown", "authors": ["Chiara Bellotti", "Tim Trudgian", "Andrew Yang"], "year": 2026, "venue": null, "publication_status": "arXiv preprint; journal status unverified", "publication_date": null, "online_publication_date": null, "doi": null, "arxiv_id": "2603.21490", "version": "v1", "version_date": "2026-03-23", "first_submission_date": "2026-03-23", "canonical_url": "https://arxiv.org/abs/2603.21490v1", "source_url": "https://arxiv.org/pdf/2603.21490v1", "source_path": "sources/latest62_analytic2/2603.21490.pdf", "source_sha256": "4337b896e2b46fbc3a27496e573ac46633dfd72769c980c0e0e80efd3c2e04f0", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 26, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "Read opening theorem statements, patch ranges and ending of the proof of Lemma 1. Numerical optimization and positivity proof not fully audited.", "statement": "Theorem 1 excludes zeta zeros for \\(t\\ge3,\\ \\sigma>1-(4.896\\log t)^{-1}\\), followed by conjugation for negative heights. Its finite argument through \\(\\exp(76.47)\\) and the explicit Littlewood region beyond \\(\\exp(76.463)\\) overlap. The preprint also displays a 4.8594 variant whose text makes the conclusion depend on the thesis bound and on a stronger finite Lemma 2 through \\(\\exp(56.693)\\).", "statement_locator": "Theorem 1, Lemma 1 and pp. 24–25", "version_note": "In v1 p. 3 the stronger variant is phrased as following once Lemma 2 is established. The proof ending explicitly concludes Lemma 1 only. Kept the 4.8594 entry as a displayed but unclosed variant in this source scope.", "record_path": "papers/PAPER-ANALYTIC62-018.md", "version_receipt": "sources/latest62_analytic2/2603.21490.html", "publication_receipt": null, "id": "PAPER-ANALYTIC62-018", "arxiv": "2603.21490", "read_scope": "Read opening theorem statements, patch ranges and ending of the proof of Lemma 1. Numerical optimization and positivity proof not fully audited.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-018"]}','Zero-free regions inspired by work of Heath-Brown','["Chiara Bellotti", "Tim Trudgian", "Andrew Yang"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2603.21490v1','4337b896e2b46fbc3a27496e573ac46633dfd72769c980c0e0e80efd3c2e04f0','papers/PAPER-ANALYTIC62-018.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-019','corpus/bibliography.jsonl',627,'full_text_accessed','papers/PAPER-ANALYTIC62-019.md','{"paper_id": "PAPER-ANALYTIC62-019", "title": "Large zeta sums and zeros of the Riemann zeta function", "authors": ["Zikang Dong", "Ruihua Wang", "Weijia Wang", "Hao Zhang"], "year": 2026, "venue": null, "publication_status": "arXiv preprint; journal status unverified", "publication_date": null, "online_publication_date": null, "doi": null, "arxiv_id": "2608.31060", "version": "v1", "version_date": "2026-08-31", "first_submission_date": "2026-08-31", "canonical_url": "https://arxiv.org/abs/2608.31060v1", "source_url": "https://arxiv.org/pdf/2608.31060v1", "source_path": "sources/latest62_analytic2/2608.31060.pdf", "source_sha256": "3c9ec2c584be3b00b751a96b47df0de2d96eb2657b1afbaa5cbf95b58fcc1972", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 19, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "selected": true, "audit_scope": "Full 19-page reading, including pretentious twist, Hadamard comparison, Gaussian pole, detection, exponent-pair range and references.", "statement": "For \\(T\\le|t|\\le2T,\\ \\exp(\\sqrt{\\log T})\\le x\\le\\sqrt T\\), a value \\(|\\sum_{n\\le x}n^{it}|=x/N\\) with \\(1\\le N\\le(\\log x)^{1/100}\\) forces a common \\(\\phi\\) with \\(|\\phi-t|\\le cN\\). For every \\(cN^6\\le L\\le(\\log x)/2\\), its open disk about \\(1+i\\phi\\) of radius \\(L\\log T/(\\log x)^2\\) has at least \\(L/360\\) zero copies. Theorem 1.2 runs in the reverse direction as a sufficient local zero count condition for a logarithmic saving in the arithmetic sum.", "statement_locator": "Theorems 1.1–1.2, Proposition 4.1 and Lemmas 3.3, 5.1", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-019.md", "version_receipt": "sources/latest62_analytic2/2608.31060.html", "publication_receipt": null, "id": "PAPER-ANALYTIC62-019", "arxiv": "2608.31060", "read_scope": "Full 19-page reading, including pretentious twist, Hadamard comparison, Gaussian pole, detection, exponent-pair range and references.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-019"]}','Large zeta sums and zeros of the Riemann zeta function','["Zikang Dong", "Ruihua Wang", "Weijia Wang", "Hao Zhang"]',NULL,'2026',1,1,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2608.31060v1','3c9ec2c584be3b00b751a96b47df0de2d96eb2657b1afbaa5cbf95b58fcc1972','papers/PAPER-ANALYTIC62-019.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-020','corpus/bibliography.jsonl',628,'full_text_accessed','papers/PAPER-ANALYTIC62-020.md','{"paper_id": "PAPER-ANALYTIC62-020", "title": "More than 83.69% of the zeros of the Riemann zeta function are distinct", "authors": ["Kristian Muri Knausgård"], "year": 2026, "venue": null, "publication_status": "arXiv preprint; journal status unverified", "publication_date": null, "online_publication_date": null, "doi": null, "arxiv_id": "2609.33043", "version": "v2", "version_date": "2026-10-07", "first_submission_date": "2026-09-27", "canonical_url": "https://arxiv.org/abs/2609.33043v2", "source_url": "https://arxiv.org/pdf/2609.33043v2", "source_path": "sources/latest62_analytic2/2609.33043.pdf", "source_sha256": "28e67cde6f11ecc20b250203644436c32233a9181663ed5d038fa9a8ab58f8f1", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 6, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "v2 Theorem 1 and scope of formal portions read. Primary source claim only for the new numerical bound and its numerical dependency.", "statement": "Theorem 1 of v2 claims \\(\\liminf N_d(T)/N(T)\\ge 16260119298029/19426831050000=0.83699288145242\\ldots\\), for distinct nontrivial zeros versus total multiplicity. The clipping argument is stated to be partly Lean-checked and the constant imports a computer-assisted local inequality from a non-refereed work. Neither external inequality nor a whole-theorem kernel replay is established by this record.", "statement_locator": "Theorem 1 and §4", "version_note": "The unchanged title rounds the result more conservatively than the v2 theorem. The v2 abstract explicitly identifies the external numerical dependency.", "record_path": "papers/PAPER-ANALYTIC62-020.md", "version_receipt": "sources/latest62_analytic2/2609.33043.html", "publication_receipt": null, "id": "PAPER-ANALYTIC62-020", "arxiv": "2609.33043", "read_scope": "v2 Theorem 1 and scope of formal portions read. Primary source claim only for the new numerical bound and its numerical dependency.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-020"]}','More than 83.69% of the zeros of the Riemann zeta function are distinct','["Kristian Muri Knausgård"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/2609.33043v2','28e67cde6f11ecc20b250203644436c32233a9181663ed5d038fa9a8ab58f8f1','papers/PAPER-ANALYTIC62-020.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-021','corpus/bibliography.jsonl',629,'full_text_accessed','papers/PAPER-ANALYTIC62-021.md','{"paper_id": "PAPER-ANALYTIC62-021", "title": "More than 8/9 zeros of the Riemann zeta function are simple or on the critical line", "authors": ["Cristian Cobeli", "Alexandru Zaharescu"], "year": 2026, "venue": null, "publication_status": "arXiv preprint; journal status unverified", "publication_date": null, "online_publication_date": null, "doi": null, "arxiv_id": "2610.23467", "version": "v1", "version_date": "2026-10-16", "first_submission_date": "2026-10-16", "canonical_url": "https://arxiv.org/abs/2610.23467v1", "source_url": "https://arxiv.org/pdf/2610.23467v1", "source_path": "sources/latest62_analytic2/2610.23467.pdf", "source_sha256": "1b7c7a5563ca6d7d31bd254103ac790eda0d23c41740d89bf9c8d265dd280dc3", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 15, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "v1 definitions, Theorem 1 and numerical constant locator checked. The long analytic/numerical chain was not independently validated.", "statement": "Theorem 1 claims \\(\\liminf N_{s\\cup0}(T)/N(T)>8/9\\), with \\(N_{s\\cup0}=N_s+N_0-N_{0s}\\). This is a union, so a multiple critical zero contributes its multiplicity; the excluded copies are exactly the multiple off-axis zeros. It is distinct from a lower bound on the intersection of simple and critical zeros. The paper reports approximately \\(0.88893\\) for its optimized constant.", "statement_locator": "Equation (1.1), Theorem 1, and (6.2)", "version_note": null, "record_path": "papers/PAPER-ANALYTIC62-021.md", "version_receipt": "sources/latest62_analytic2/2610.23467.html", "publication_receipt": null, "id": "PAPER-ANALYTIC62-021", "arxiv": "2610.23467", "read_scope": "v1 definitions, Theorem 1 and numerical constant locator checked. The long analytic/numerical chain was not independently validated.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-021"]}','More than 8/9 zeros of the Riemann zeta function are simple or on the critical line','["Cristian Cobeli", "Alexandru Zaharescu"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2610.23467v1','1b7c7a5563ca6d7d31bd254103ac790eda0d23c41740d89bf9c8d265dd280dc3','papers/PAPER-ANALYTIC62-021.md','papers/latest62_analytic2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-ANALYTIC62-022','corpus/bibliography.jsonl',630,'full_text_accessed','papers/PAPER-ANALYTIC62-022.md','{"paper_id": "PAPER-ANALYTIC62-022", "title": "Isolated zeros of the Riemann zeta function and zeros of linear combinations of Dirichlet $L$-functions", "authors": ["Youness Lamzouri"], "year": 2026, "venue": null, "publication_status": "arXiv preprint; journal status unverified", "publication_date": null, "online_publication_date": null, "doi": null, "arxiv_id": "2610.26841", "version": "v2", "version_date": "2026-10-26", "first_submission_date": "2026-10-19", "canonical_url": "https://arxiv.org/abs/2610.26841v2", "source_url": "https://arxiv.org/pdf/2610.26841v2", "source_path": "sources/latest62_analytic2/2610.26841.pdf", "source_sha256": "4684e9f03747b63c3dfe5c72fba926ddd2693ea3663384381a8eb4f34f6c9e1f", "source_date_status": "arXiv revision", "access_date": "2026-11-17", "pages": 26, "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "selected": true, "audit_scope": "v2 Theorems 1.1, 1.3 and 1.5 and the ordered multiplicity convention checked. Formula uses log T precisely as displayed; the introductory local-spacing convention uses log ordinate.", "statement": "Theorem 1.1 claims \\(\\liminf B_0(T,c)/N(T)\\ge0.6552\\ldots\\) for some fixed \\(c>0\\) and \\(\\ge0.50875\\) for \\(c=1/6\\), where \\(B_0\\) requires each adjacent ordered-ordinate gap to exceed \\(2\\pi c/\\log T\\) at a zero with \\(0<\\gamma\\le T\\). For a distinct pair of primitive characters of the same conductor and parity, Theorem 1.5 claims at least 31% odd-multiplicity critical zeros for linear combinations with nonzero real coefficients and the source’s respective root-number phase factors.", "statement_locator": "Equations (1.4)–(1.5), Theorems 1.3 and 1.5", "version_note": "v2 arXiv history records corrected typos and expanded introduction/exposition.", "record_path": "papers/PAPER-ANALYTIC62-022.md", "version_receipt": "sources/latest62_analytic2/2610.26841.html", "publication_receipt": null, "id": "PAPER-ANALYTIC62-022", "arxiv": "2610.26841", "read_scope": "v2 Theorems 1.1, 1.3 and 1.5 and the ordered multiplicity convention checked. Formula uses log T precisely as displayed; the introductory local-spacing convention uses log ordinate.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_analytic2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-ANALYTIC62-022"]}','Isolated zeros of the Riemann zeta function and zeros of linear combinations of Dirichlet $L$-functions','["Youness Lamzouri"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/2610.26841v2','4684e9f03747b63c3dfe5c72fba926ddd2693ea3663384381a8eb4f34f6c9e1f','papers/PAPER-ANALYTIC62-022.md','papers/latest62_analytic2_records.jsonl');
