INSERT INTO "papers" VALUES('PAPER-INV62-HARDY','corpus/bibliography.jsonl',635,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-HARDY", "title": "Hardy’s condition in the moment problem for probability distributions", "authors": ["Jordan Stoyanov", "Gwo Dong Lin"], "year": 2012, "venue": "Teoriya Veroyatnostei i ee Primeneniya 57(4), 811–820", "doi": "10.4213/tvp4485", "arxiv_id": null, "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.4213/tvp4485", "source_url": "https://www.mathnet.ru/php/getFT.phtml?jrnid=tvp&paperid=4485&what=fullt&option_lang=eng", "version": "Math-Net original journal PDF, English main text and Russian abstract", "version_date": null, "source_edition": "Math-Net original journal PDF, English main text and Russian abstract", "source_path": "sources/latest62_inverse_adjacent/hardy_stoyanov.pdf", "source_sha256": "eb130b3d70859ee435543bd95d0d342ef5ad252163d0e8155e37fe75c20fc0af", "pages": 10, "version_receipt": "sources/latest62_inverse_adjacent/hardy_stoyanov.html", "publication_receipt": "sources/latest62_inverse_adjacent/hardy_stoyanov.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read the square-root criterion and discussion of the cosine-transform proof, sharpness statement, factorial-moment condition, and the two Hardy references. Later multivariate claims are outside this scope.", "statement_locator": "Theorems 1–3 and §3, pp. 812–817", "scoped_statement": "For nonnegative X, E exp(c√X)<∞ for some c>0 implies Stieltjes determinacy. The condition is equivalent to a (2j)! moment envelope, and the exponent 1/2 is sharp for general nonnegative measures.", "prefix_inverse_transfer": "Apply after normalizing ν by M₀>0. The director proof implements the same square-root symmetrization with cosh transferring a finite exponential moment to every positive competitor. Sharpness over arbitrary half-line laws does not establish sharpness over the triangular lattice.", "topic": "Full moments and determinacy", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "translation_doi": "10.1137/S0040585X9798631X", "version_note": "English SIAM edition, Theory of Probability and Its Applications 57(4), 699–708 (2013), is a parallel citation. The hashed PDF is the 2012 original, not the SIAM translation.", "id": "PAPER-INV62-HARDY", "arxiv": null, "read_scope": "Read the square-root criterion and discussion of the cosine-transform proof, sharpness statement, factorial-moment condition, and the two Hardy references. Later multivariate claims are outside this scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-HARDY"]}','Hardy’s condition in the moment problem for probability distributions','["Jordan Stoyanov", "Gwo Dong Lin"]',NULL,'2012',0,0,'selected_checkpoint_priority_work','full_text_accessed','Math-Net original journal PDF, English main text and Russian abstract','https://www.mathnet.ru/php/getFT.phtml?jrnid=tvp&paperid=4485&what=fullt&option_lang=eng','eb130b3d70859ee435543bd95d0d342ef5ad252163d0e8155e37fe75c20fc0af','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-RATIO','corpus/bibliography.jsonl',636,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-RATIO", "title": "Moment Determinacy of Powers and Products of Nonnegative Random Variables", "authors": ["Gwo Dong Lin", "Jordan Stoyanov"], "year": 2015, "venue": "Journal of Theoretical Probability 28(4), 1337–1353", "doi": "10.1007/s10959-014-0546-z", "arxiv_id": "1403.0301", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1007/s10959-014-0546-z", "source_url": "https://arxiv.org/pdf/1403.0301v2", "version": "v2", "version_date": "2016-01-14", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/1403.0301.pdf", "source_sha256": "79b135bb6f3155b9a5f42b05e6f203d1cada7be0a73ea4972009bf8c12ee0608", "pages": 17, "version_receipt": "sources/latest62_inverse_adjacent/1403.0301.html", "publication_receipt": "sources/latest62_inverse_adjacent/1403.0301.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read selected statement and proof passages for the ratio-to-Carleman and ratio-to-Hardy implications. Product-specific sections outside scope.", "statement_locator": "Theorems 1 and 3, §6 Lemma 3", "scoped_statement": "The bound m_{j+1}/m_j=O((j+1)^2) implies both the Stieltjes Carleman condition and a square-root exponential moment.", "prefix_inverse_transfer": "After extracting the true moments from the prefix germ, this offers a separate sufficient certificate via the ratios M_{j+1}/M_j for M₀>0. The actual proof instead directly bounds the square-root exponential moment. No asymptotic ratio bound follows just from the stated moment envelope.", "topic": "Full moments and determinacy", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "online_publication_date": "2014-03-25", "version_note": "The arXiv v2 date is later than the journal issue.", "id": "PAPER-INV62-RATIO", "arxiv": "1403.0301", "read_scope": "Read selected statement and proof passages for the ratio-to-Carleman and ratio-to-Hardy implications. Product-specific sections outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-RATIO"]}','Moment Determinacy of Powers and Products of Nonnegative Random Variables','["Gwo Dong Lin", "Jordan Stoyanov"]',NULL,'2015',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/1403.0301v2','79b135bb6f3155b9a5f42b05e6f203d1cada7be0a73ea4972009bf8c12ee0608','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-GROWTH','corpus/bibliography.jsonl',637,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-GROWTH", "title": "On the Moment Determinacy of Products of Non-identically Distributed Random Variables", "authors": ["Gwo Dong Lin", "Jordan Stoyanov"], "year": 2014, "venue": null, "doi": null, "arxiv_id": "1406.1654", "publication_status": "arXiv preprint inspected; journal identity unverified", "canonical_url": "https://arxiv.org/abs/1406.1654v2", "source_url": "https://arxiv.org/pdf/1406.1654v2", "version": "v2", "version_date": "2014-11-12", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/1406.1654.pdf", "source_sha256": "001e5a9c10cbc0aac75c55501065e14e504cfba5e5845ec34a903ef32e78b372", "pages": 17, "version_receipt": "sources/latest62_inverse_adjacent/1406.1654.html", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read Lemma 1, Theorem 1 and the start of its sharpness construction. Applications to products are outside scope.", "statement_locator": "§2.1 Lemma 1 and Theorem 1", "scoped_statement": "Square-root exponential integrability is equivalent to a bounded limsup of m_j^{1/(2j)}/j and equivalent to m_j≤c₀^j(2j)!. Theorem 1 gives a nonnegative indeterminate law with m_j=O(j^{aj}) for every a>2.", "prefix_inverse_transfer": "The bounds on the director’s Taylor-to-moment outputs can be compared directly with this factorial envelope. The arbitrary half-line example sets a limit on moment growth criteria, and the director supplies the separate same-lattice counterexample.", "topic": "Full moments and determinacy", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "id": "PAPER-INV62-GROWTH", "arxiv": "1406.1654", "read_scope": "Read Lemma 1, Theorem 1 and the start of its sharpness construction. Applications to products are outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-GROWTH"]}','On the Moment Determinacy of Products of Non-identically Distributed Random Variables','["Gwo Dong Lin", "Jordan Stoyanov"]',NULL,'2014',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/1406.1654v2','001e5a9c10cbc0aac75c55501065e14e504cfba5e5845ec34a903ef32e78b372','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-INFUSINO','corpus/bibliography.jsonl',638,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-INFUSINO", "title": "The truncated moment problem on ℕ₀", "authors": ["Maria Infusino", "Tobias Kuna", "Joel L. Lebowitz", "Eugene R. Speer"], "year": 2017, "venue": "Journal of Mathematical Analysis and Applications 452(1), 443–468", "doi": "10.1016/j.jmaa.2017.02.060", "arxiv_id": "1504.02989", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1016/j.jmaa.2017.02.060", "source_url": "https://arxiv.org/pdf/1504.02989v2", "version": "v2", "version_date": "2015-09-15", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/1504.02989.pdf", "source_sha256": "94d4dd99122baef202096f392227479c46c44a478bda457fe3fd4fda8c70a23d", "pages": 36, "version_receipt": "sources/latest62_inverse_adjacent/1504.02989.html", "publication_receipt": "sources/latest62_inverse_adjacent/1504.02989.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read constructions in §2, the interior/boundary argument and the extension in §8. The degree 4–5 algorithms and remaining proofs are outside this reading.", "statement_locator": "§2 adjacent-node products, Lemma 4.2, Theorem 4.4, Remark 4.5 and §8, pp. 29–30", "scoped_statement": "Realizable boundary vectors have an annihilating nonnegative polynomial and a unique measure on its lattice zeros. Interior realization is governed by strict polynomial inequalities; §8 extends the criteria to lower-bounded infinite discrete supports.", "prefix_inverse_transfer": "Normalize and translate the triangular lattice to {0,4,10,…}. The polynomial P_M is in the adjacent-pair family, with a minimum-node factor for odd degree. Its saturation is a direct special case. Interior jets permit planting mass at any lattice node, with C(0) preserved when there is simple-mass slack.", "topic": "Lattice feasibility and bounds", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "version_note": "The pinned arXiv watermark lists 15 September 2015; the interior title page displays 31 May 2021. These dates describe separate source fields. The arXiv Eq. (8.7) repeats l(t₁), in conflict with the preceding root set; that line is not used.", "related_audit": "audits/latest62_inverse_adjacent_lattice.md", "id": "PAPER-INV62-INFUSINO", "arxiv": "1504.02989", "read_scope": "Read constructions in §2, the interior/boundary argument and the extension in §8. The degree 4–5 algorithms and remaining proofs are outside this reading.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-INFUSINO"]}','The truncated moment problem on ℕ₀','["Maria Infusino", "Tobias Kuna", "Joel L. Lebowitz", "Eugene R. Speer"]',NULL,'2017',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/1504.02989v2','94d4dd99122baef202096f392227479c46c44a478bda457fe3fd4fda8c70a23d','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-CUBATURE','corpus/bibliography.jsonl',639,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-CUBATURE", "title": "The proof of Tchakaloff’s Theorem", "authors": ["Christian Bayer", "Josef Teichmann"], "year": 2006, "venue": "Proceedings of the American Mathematical Society 134(10), 3035–3040", "doi": "10.1090/S0002-9939-06-08249-9", "arxiv_id": "math/0502473", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1090/S0002-9939-06-08249-9", "source_url": "https://arxiv.org/pdf/math/0502473v2", "version": "v2", "version_date": "2005-05-04", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/tchakaloff.pdf", "source_sha256": "58b258713c29a68c09f93d1d5f0bdff409f2804435ca1861133b9ded2c1ccb47", "pages": 6, "version_receipt": "sources/latest62_inverse_adjacent/tchakaloff.html", "publication_receipt": "sources/latest62_inverse_adjacent/tchakaloff.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "audit_scope": "Read all six pages of v2, including the closed-cone supporting-hyperplane argument, the pushforward in Corollary 2, the admissible polynomial space and references.", "statement_locator": "Theorem 1, Corollary 2, Theorem 2 and Remark 4", "scoped_statement": "Finite moments through degree n on a possibly unbounded support have positive cubature on that same support with at most n+1 points in one dimension. Corollary 2 permits any finite list of integrable test functions.", "prefix_inverse_transfer": "Finite lattice jets belong to the actual convex hull of lattice moment vectors. Applying Corollary 2 with the extra function 1/(m−1)^2 also preserves the multiple contribution to C(0), using at most n+2 nodes. Exact finite jet agreement can therefore coexist with radically different support beyond the sampled moments.", "topic": "Lattice feasibility and bounds", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "related_audit": "audits/latest62_inverse_adjacent_lattice.md", "id": "PAPER-INV62-CUBATURE", "arxiv": "math/0502473", "read_scope": "Read all six pages of v2, including the closed-cone supporting-hyperplane argument, the pushforward in Corollary 2, the admissible polynomial space and references.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-CUBATURE"]}','The proof of Tchakaloff’s Theorem','["Christian Bayer", "Josef Teichmann"]',NULL,'2006',1,1,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/math/0502473v2','58b258713c29a68c09f93d1d5f0bdff409f2804435ca1861133b9ded2c1ccb47','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-DUAL','corpus/bibliography.jsonl',640,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-DUAL", "title": "Optimal Inequalities in Probability Theory: A Convex Optimization Approach", "authors": ["Dimitris Bertsimas", "Ioana Popescu"], "year": 2005, "venue": "SIAM Journal on Optimization 15(3), 780–804", "doi": "10.1137/S1052623401399903", "arxiv_id": null, "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1137/S1052623401399903", "source_url": "https://doi.org/10.1137/S1052623401399903", "version": "Published SIAM typeset PDF; original mirror URL not preserved", "version_date": null, "source_edition": "Published SIAM typeset PDF; original mirror URL not preserved", "source_path": "sources/latest62_inverse_adjacent/bertsimas.pdf", "source_sha256": "1eceb8733ef9d56e45cda38b55afcb0d624a6eff9d1949e6801d402065d3063a", "pages": 25, "version_receipt": null, "publication_receipt": "sources/latest62_inverse_adjacent/bertsimas.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read the generalized moment primal and dual, weak-duality proof, interior hypothesis for strong duality and boundary discussion. Later optimizers and bounds are outside scope.", "statement_locator": "§2, (2.1)–(2.2), Theorems 2.1–2.2", "scoped_statement": "A polynomial majorizing an event indicator on the allowed domain gives a moment upper bound. Strong duality is stated for interior realizable moment vectors, with a separate boundary discussion.", "prefix_inverse_transfer": "On the triangular lattice P_M/P_M(μ_{M+1}) majorizes the tail indicator. Its integral gives a certified tail bound from the finite prefix jet. The result is sharp over profiles concentrated through μ_{M+1}; this does not assert pointwise optimality for all moment vectors.", "topic": "Lattice feasibility and bounds", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "related_audit": "audits/latest62_inverse_adjacent_lattice.md", "id": "PAPER-INV62-DUAL", "arxiv": null, "read_scope": "Read the generalized moment primal and dual, weak-duality proof, interior hypothesis for strong duality and boundary discussion. Later optimizers and bounds are outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-DUAL"]}','Optimal Inequalities in Probability Theory: A Convex Optimization Approach','["Dimitris Bertsimas", "Ioana Popescu"]',NULL,'2005',0,0,'selected_checkpoint_priority_work','full_text_accessed','Published SIAM typeset PDF; original mirror URL not preserved','https://doi.org/10.1137/S1052623401399903','1eceb8733ef9d56e45cda38b55afcb0d624a6eff9d1949e6801d402065d3063a','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-FLAT','corpus/bibliography.jsonl',641,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-FLAT", "title": "A generalized flat extension theorem for moment matrices", "authors": ["Monique Laurent", "Bernard Mourrain"], "year": 2009, "venue": "Archiv der Mathematik 93(1), 87–98", "doi": "10.1007/s00013-009-0007-6", "arxiv_id": null, "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1007/s00013-009-0007-6", "source_url": "https://homepages.cwi.nl/~monique/files/archivlm.pdf", "version": "Published version", "version_date": null, "source_edition": "Published PDF", "source_path": "sources/latest62_inverse_adjacent/laurent.pdf", "source_sha256": "a5236354b2054ce6278f59718844f3028f1dc0f0156edf7d663f99ee0fc651c5", "pages": 12, "version_receipt": null, "publication_receipt": "sources/latest62_inverse_adjacent/laurent.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "audit_scope": "Prior audit read all 12 published pages and reconstructed the truncated multiplication and unique extension mechanism. Inherited reading scope, with the title page and audit checked here.", "statement_locator": "Theorems 1.1, 1.4, 1.5, 3.2 and Lemmas 2.1–2.3", "scoped_statement": "A flat Hankel matrix on a monomial set connected to 1 and its border extends uniquely at the same rank. A real positive semidefinite extension gives a finite atomic measure.", "prefix_inverse_transfer": "Rank equality of H_r and H_{r−1} with exact positive moments through degree 2r certifies r-node recovery after 2r+1 nonconstant Taylor coefficients. The kernel gives support and the Vandermonde system gives weights.", "topic": "Flat extension and finite reconstruction", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "related_preprint": "0812.2563v1", "related_audit": "audits/latest62_inverse_adjacent_fullreads.md", "id": "PAPER-INV62-FLAT", "arxiv": null, "read_scope": "Prior audit read all 12 published pages and reconstructed the truncated multiplication and unique extension mechanism. Inherited reading scope, with the title page and audit checked here.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-FLAT"]}','A generalized flat extension theorem for moment matrices','["Monique Laurent", "Bernard Mourrain"]',NULL,'2009',1,1,'selected_checkpoint_priority_work','full_text_accessed','Published version','https://homepages.cwi.nl/~monique/files/archivlm.pdf','a5236354b2054ce6278f59718844f3028f1dc0f0156edf7d663f99ee0fc651c5','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-LOCALIZE','corpus/bibliography.jsonl',642,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-LOCALIZE", "title": "Truncated K-moment problems in several variables", "authors": ["Raúl E. Curto", "Lawrence A. Fialkow"], "year": 2005, "venue": "Journal of Operator Theory 54(1), 189–226", "doi": null, "arxiv_id": "math/0507067", "publication_status": "Published journal article", "canonical_url": "https://arxiv.org/abs/math/0507067v1", "source_url": "https://arxiv.org/pdf/math/0507067v1", "version": "v1", "version_date": "2005-07-04", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/curto.pdf", "source_sha256": "86745a435f01b7f2d25bb2a8c73d5e594abcc9d168ef86dc9053f725556a1c42", "pages": 30, "version_receipt": "sources/latest62_inverse_adjacent/curto.html", "publication_receipt": "sources/latest62_inverse_adjacent/curto_publication.html", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read main theorems and set-up for flat extension with localizing matrices. Remaining proofs outside scope.", "statement_locator": "Theorems 1.1–1.2, pp. 1–3", "scoped_statement": "A flat extension with positive localizing matrices gives a minimal-rank atomic measure on the associated semialgebraic set. The flat extension’s unique positive representing measure lies on the associated moment variety.", "prefix_inverse_transfer": "For prefix moments with a separately certified cutoff M, the support K={μ₂,…,μ_M} has the polynomial description −P_M²≥0. This permits finite-support localization, whereas the unbounded triangular lattice requires discrete moment machinery. Given true prefix moments and a matching flat Hankel block, the recovered variety can instead be checked node by node.", "topic": "Flat extension and finite reconstruction", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "journal_url": "https://mathjournals.org/jot/2005-054-001/2005-054-001-012.html", "id": "PAPER-INV62-LOCALIZE", "arxiv": "math/0507067", "read_scope": "Read main theorems and set-up for flat extension with localizing matrices. Remaining proofs outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-LOCALIZE"]}','Truncated K-moment problems in several variables','["Raúl E. Curto", "Lawrence A. Fialkow"]',NULL,'2005',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/math/0507067v1','86745a435f01b7f2d25bb2a8c73d5e594abcc9d168ef86dc9053f725556a1c42','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-PRONY','corpus/bibliography.jsonl',643,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-PRONY", "title": "On the Accuracy of Solving Confluent Prony Systems", "authors": ["Dmitry Batenkov", "Yosef Yomdin"], "year": 2013, "venue": "SIAM Journal on Applied Mathematics 73(1), 134–154", "doi": "10.1137/110836584", "arxiv_id": "1106.1137", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1137/110836584", "source_url": "https://arxiv.org/pdf/1106.1137v3", "version": "v3", "version_date": "2012-06-26", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/1106.1137.pdf", "source_sha256": "3b447256daad76552e75c76251f6583f2170215139678776549b97e2594db3dd", "pages": 21, "version_receipt": "sources/latest62_inverse_adjacent/1106.1137.html", "publication_receipt": "sources/latest62_inverse_adjacent/1106.1137.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read the recurrence and reconstruction setup and the local inverse error statement and its Jacobian factorization. Numerical sections and other proofs are outside scope.", "statement_locator": "Proposition 2.1, Hankel recovery in §2, and Theorem 4.5", "scoped_statement": "A finite confluent moment system satisfies an annihilating recurrence. At a regular point of the moment map, the local bound for a node error scales with noise divided by its highest-order amplitude.", "prefix_inverse_transfer": "For the prefix ν an occupied multiplicity class is an ordinary Prony atom, with coefficient a_m and no derivative terms even for a repeated zeta zero. Small positive a_m precludes a uniform unknown-support guarantee in this model. With lattice support known, recovering only the weights avoids the node-inverse Jacobian.", "topic": "Flat extension and finite reconstruction", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "id": "PAPER-INV62-PRONY", "arxiv": "1106.1137", "read_scope": "Read the recurrence and reconstruction setup and the local inverse error statement and its Jacobian factorization. Numerical sections and other proofs are outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-PRONY"]}','On the Accuracy of Solving Confluent Prony Systems','["Dmitry Batenkov", "Yosef Yomdin"]',NULL,'2013',0,0,'selected_checkpoint_priority_work','full_text_accessed','v3','https://arxiv.org/pdf/1106.1137v3','3b447256daad76552e75c76251f6583f2170215139678776549b97e2594db3dd','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-MINEXTRAP','corpus/bibliography.jsonl',644,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-MINEXTRAP", "title": "Exact Reconstruction using Beurling Minimal Extrapolation", "authors": ["Yohann de Castro", "Fabrice Gamboa"], "year": 2012, "venue": "Journal of Mathematical Analysis and Applications 395(1), 336–354", "doi": "10.1016/j.jmaa.2012.05.011", "arxiv_id": "1103.4951", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1016/j.jmaa.2012.05.011", "source_url": "https://arxiv.org/pdf/1103.4951v2", "version": "v2", "version_date": "2012-04-05", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/1103.4951.pdf", "source_sha256": "b8a4e2e020a90bed3f57beefeef2d2450ce803804861ca90da592f494c5b3612", "pages": 27, "version_receipt": "sources/latest62_inverse_adjacent/1103.4951.html", "publication_receipt": "sources/latest62_inverse_adjacent/1103.4951.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read the exact positive-measure theorem and nonnegative interpolation framework. Remaining algorithmic examples and Appendix proof outside scope.", "statement_locator": "Theorem 2.1 and Lemma 2.2", "scoped_statement": "An s-node nonnegative measure on an interval is recovered by generalized minimal extrapolation using 2s+1 observations from a homogeneous Markov system.", "prefix_inverse_transfer": "For finitely supported prefix ν in a bounded interval, use monomials 1,x,…,x^{2s} and moments from the jet through b^{2s+1}; the underlying polynomial ∏(x−x_i)^2 enforces the same finite-support conclusion. Known lattice geometry supplies certificates of lower degree for adjacent nodes.", "topic": "Positive superresolution", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "id": "PAPER-INV62-MINEXTRAP", "arxiv": "1103.4951", "read_scope": "Read the exact positive-measure theorem and nonnegative interpolation framework. Remaining algorithmic examples and Appendix proof outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-MINEXTRAP"]}','Exact Reconstruction using Beurling Minimal Extrapolation','["Yohann de Castro", "Fabrice Gamboa"]',NULL,'2012',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/1103.4951v2','b8a4e2e020a90bed3f57beefeef2d2450ce803804861ca90da592f494c5b3612','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-GAUSSIAN','corpus/bibliography.jsonl',645,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-GAUSSIAN", "title": "Superresolution without Separation", "authors": ["Geoffrey Schiebinger", "Elina Robeva", "Benjamin Recht"], "year": 2018, "venue": "Information and Inference: A Journal of the IMA 7(1), 1–30", "doi": "10.1093/imaiai/iax006", "arxiv_id": "1506.03144", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1093/imaiai/iax006", "source_url": "https://arxiv.org/pdf/1506.03144v2", "version": "v2", "version_date": "2015-08-13", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/1506.03144.pdf", "source_sha256": "20e6da7a83049afc0db068f3d956bcdd36ddae7a8e2c76b62f6643a6fe75f3f0", "pages": 23, "version_receipt": "sources/latest62_inverse_adjacent/1506.03144.html", "publication_receipt": "sources/latest62_inverse_adjacent/1506.03144.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read exact recovery hypotheses and the certificate reduction, with Gaussian specialization statement. Full determinant construction outside scope.", "statement_locator": "Conditions 1.1, Theorems 1.2–1.3 and Proposition 2.1", "scoped_statement": "The true M-node positive measure uniquely minimizes the stated objective under point-spread assumptions and more than 2M samples. The certificate interpolates a positive weight at occupied nodes and dominates it elsewhere.", "prefix_inverse_transfer": "In the exact prefix moment model, choose the constant weight 1, measured by M₀, and certificate 1+∏(x−x_i)^2 in the span of measured moments through degree 2M. Equality forces lattice support on the roots and the lower moments give the weights. This applies the certificate mechanism with monomials, independently of the Gaussian determinant theorem.", "topic": "Positive superresolution", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "online_publication_date": "2017-05-29", "id": "PAPER-INV62-GAUSSIAN", "arxiv": "1506.03144", "read_scope": "Read exact recovery hypotheses and the certificate reduction, with Gaussian specialization statement. Full determinant construction outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-GAUSSIAN"]}','Superresolution without Separation','["Geoffrey Schiebinger", "Elina Robeva", "Benjamin Recht"]',NULL,'2018',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/1506.03144v2','20e6da7a83049afc0db068f3d956bcdd36ddae7a8e2c76b62f6643a6fe75f3f0','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-POSSTABLE','corpus/bibliography.jsonl',646,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-POSSTABLE", "title": "Sparse non-negative super-resolution — simplified and stabilised", "authors": ["Armin Eftekhari", "Jared Tanner", "Andrew Thompson", "Bogdan Toader", "Hemant Tyagi"], "year": 2021, "venue": "Applied and Computational Harmonic Analysis 50, 216–280", "doi": "10.1016/j.acha.2019.08.004", "arxiv_id": "1804.01490", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1016/j.acha.2019.08.004", "source_url": "https://arxiv.org/pdf/1804.01490v2", "version": "v2", "version_date": "2019-11-26", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/1804.01490.pdf", "source_sha256": "09a17c72e67edcadec749769dd385f2bbd250dfe2f1e79b1dacaf8e84732717d", "pages": 59, "version_receipt": "sources/latest62_inverse_adjacent/1804.01490.html", "publication_receipt": "sources/latest62_inverse_adjacent/eftekhari_publication.html", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read exact uniqueness via a T-system and the statement of the dual-margin/Wasserstein estimates. Long determinant and Gaussian constant proofs are outside scope.", "statement_locator": "Proposition 8, Definition 10 and Theorems 4–5, 11", "scoped_statement": "A k-node positive measure on an interval is uniquely feasible from at least 2k+1 T-system samples. Quantitative versions require separate margin and approximation hypotheses.", "prefix_inverse_transfer": "For bounded-support prefix competitors, an affine rescaling of the monomials gives a T-system. On the full known lattice, the square-support polynomial itself has a positive minimum off the finite support, so its measured moment integral divided by that minimum gives a certified off-support mass bound. The Gaussian numerical constants do not follow for a finite-N staircase.", "topic": "Positive superresolution", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "online_publication_date": "2019-08-13", "id": "PAPER-INV62-POSSTABLE", "arxiv": "1804.01490", "read_scope": "Read exact uniqueness via a T-system and the statement of the dual-margin/Wasserstein estimates. Long determinant and Gaussian constant proofs are outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-POSSTABLE"]}','Sparse non-negative super-resolution — simplified and stabilised','["Armin Eftekhari", "Jared Tanner", "Andrew Thompson", "Bogdan Toader", "Hemant Tyagi"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/1804.01490v2','09a17c72e67edcadec749769dd385f2bbd250dfe2f1e79b1dacaf8e84732717d','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-FOURIER','corpus/bibliography.jsonl',647,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-FOURIER", "title": "Super-resolution of positive near-colliding point sources", "authors": ["Ping Liu", "Habib Ammari"], "year": 2023, "venue": "Information and Inference: A Journal of the IMA 12(4), 3087–3111", "doi": "10.1093/imaiai/iaad048", "arxiv_id": "2212.00536", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1093/imaiai/iaad048", "source_url": "https://arxiv.org/pdf/2212.00536v1", "version": "v1", "version_date": "2022-12-01", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/2212.00536.pdf", "source_sha256": "7b84ac269fb7019865a89f17e6ac979e2c396af4ed9699337041a00045a307a1", "pages": 20, "version_receipt": "sources/latest62_inverse_adjacent/2212.00536.html", "publication_receipt": "sources/latest62_inverse_adjacent/2212.00536.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read observation model, statements of upper/lower bounds and conditions in Theorem 2.3. Minimax proofs and numerical section outside scope.", "statement_locator": "§2, Theorems 2.1–2.3", "scoped_statement": "With a fixed positive sparse clustered class and bounded-band Fourier observations, Theorem 2.3 quantifies the superresolution factor in the worst-case location and amplitude errors.", "prefix_inverse_transfer": "Prefix moments determine derivatives at zero of the Fourier transform when they exist. With a separately certified common cutoff x≤X, the order-n Taylor remainder on |ω|≤Ω is at most M₀(2πΩX)^{n+1}/(n+1)! for the transform with e^{2πiωx}. Fourier recovery guarantees still require the stipulated sparsity, amplitude and geometry assumptions; the ambient continuous-cluster lower bound is not a lower bound on the restricted triangular lattice.", "topic": "Positive superresolution", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "id": "PAPER-INV62-FOURIER", "arxiv": "2212.00536", "read_scope": "Read observation model, statements of upper/lower bounds and conditions in Theorem 2.3. Minimax proofs and numerical section outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-FOURIER"]}','Super-resolution of positive near-colliding point sources','["Ping Liu", "Habib Ammari"]',NULL,'2023',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2212.00536v1','7b84ac269fb7019865a89f17e6ac979e2c396af4ed9699337041a00045a307a1','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-BERG','corpus/bibliography.jsonl',648,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-BERG", "title": "Indeterminate Stieltjes moment problems revisited", "authors": ["Christian Berg"], "year": 2026, "venue": "Arabian Journal of Mathematics 15(2), 561–571", "doi": "10.1007/s40065-025-00554-8", "arxiv_id": "2407.08511", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1007/s40065-025-00554-8", "source_url": "https://arxiv.org/pdf/2407.08511v1", "version": "v1", "version_date": "2024-07-11", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/2407.08511.pdf", "source_sha256": "0793ef3df0f7491bfa4c0ca10b000d7c48f7b01638ac2cef0e52c287bbdeb8ad", "pages": 15, "version_receipt": "sources/latest62_inverse_adjacent/2407.08511.html", "publication_receipt": "sources/latest62_inverse_adjacent/2407.08511.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "audit_scope": "Prior audit read all 15 pages in v1, §§1–4 and references, and reconstructed selected proofs. Inherited reading scope; title page and reading notes checked here.", "statement_locator": "Propositions 3.1–3.2 and Theorems 3.4, 3.5, 4.1", "scoped_statement": "Different self-adjoint extensions of an indeterminate minimal Jacobi operator have different cyclic measures. For Stieltjes indeterminacy the Friedrichs solution uniquely maximizes the bottom of the support among Hamburger solutions.", "prefix_inverse_transfer": "The moments of a hypothetical indeterminate prefix profile would fix the common Jacobi coefficients and might leave the operator realization undetermined. Lattice-preserving ambiguity needs its own construction. The actual Stieltjes tail criterion selects a unique half-line measure.", "topic": "Inverse spectral ambiguity", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "online_publication_date": "2025-08-14", "related_audit": "audits/latest62_inverse_adjacent_fullreads.md", "id": "PAPER-INV62-BERG", "arxiv": "2407.08511", "read_scope": "Prior audit read all 15 pages in v1, §§1–4 and references, and reconstructed selected proofs. Inherited reading scope; title page and reading notes checked here.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-BERG"]}','Indeterminate Stieltjes moment problems revisited','["Christian Berg"]',NULL,'2026',1,1,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2407.08511v1','0793ef3df0f7491bfa4c0ca10b000d7c48f7b01638ac2cef0e52c287bbdeb8ad','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-JACOBI','corpus/bibliography.jsonl',649,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-JACOBI", "title": "Indeterminate Jacobi operators", "authors": ["Christian Berg", "Ryszard Szwarc"], "year": 2025, "venue": "Journal of Operator Theory 93(1), 123–145", "doi": "10.7900/jot.2023ian02.2404", "arxiv_id": "2301.00586", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.7900/jot.2023ian02.2404", "source_url": "https://arxiv.org/pdf/2301.00586v1", "version": "v1", "version_date": "2023-01-02", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/2301.00586.pdf", "source_sha256": "50a4237cd52699070809e1261aeafb7c62b3fffaef2756f6508bbe7449c1ecdd", "pages": 29, "version_receipt": "sources/latest62_inverse_adjacent/2301.00586.html", "publication_receipt": "sources/latest62_inverse_adjacent/berg_jot.html", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read the minimal operator setup and selected statements about domains of the extensions and their supporting zero sets. Remainder of the 29-page preprint outside scope.", "statement_locator": "§1, Proposition 3.1 and Theorems 3.2, 3.4", "scoped_statement": "The closed minimal Jacobi operator of an indeterminate sequence has deficiency indices (1,1). The Nevanlinna parameters give distinct extremal supports and different domains, whose distinction is visible in the explicit sequences in §3.", "prefix_inverse_transfer": "Gram–Schmidt on the entire recovered M_j fixes the minimal Jacobi coefficients when all Hankel matrices are positive definite. For an indeterminate synthetic sequence this need not fix a self-adjoint boundary condition. No operator or support involving individual zeta ordinates is constructed.", "topic": "Inverse spectral ambiguity", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "id": "PAPER-INV62-JACOBI", "arxiv": "2301.00586", "read_scope": "Read the minimal operator setup and selected statements about domains of the extensions and their supporting zero sets. Remainder of the 29-page preprint outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-JACOBI"]}','Indeterminate Jacobi operators','["Christian Berg", "Ryszard Szwarc"]',NULL,'2025',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2301.00586v1','50a4237cd52699070809e1261aeafb7c62b3fffaef2756f6508bbe7449c1ecdd','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-EXTREMAL','corpus/bibliography.jsonl',650,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-EXTREMAL", "title": "Special N-extremal solutions to indeterminate moment problems", "authors": ["Christian Berg", "Ryszard Szwarc"], "year": 2026, "venue": "Complex Analysis and Operator Theory 20(6), article 138", "doi": "10.1007/s11785-026-02000-9", "arxiv_id": "2603.26302", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1007/s11785-026-02000-9", "source_url": "https://arxiv.org/pdf/2603.26302v1", "version": "v1", "version_date": "2026-03-27", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/2603.26302.pdf", "source_sha256": "b07a6c6f2c4efb406eb06ec6aba26563f0b81e876141ab6f30edcfcd4d87d5c3", "pages": 20, "version_receipt": "sources/latest62_inverse_adjacent/2603.26302.html", "publication_receipt": "sources/latest62_inverse_adjacent/2603.26302.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read the Friedrichs/Krein setup, the negative-first-moment constraints and selected proof of Theorem 3.3. Other weighting regimes outside scope.", "statement_locator": "Proposition 3.1 and Theorem 3.3", "scoped_statement": "For a normalized Stieltjes-indeterminate sequence, dividing the Friedrichs measure by x gives a determinate measure; dividing other specified N-extremal measures by x gives indeterminate sequences with new total mass t.", "prefix_inverse_transfer": "For any lattice-supported prefix profile, σ=dν/x has moments of degree j≥1 equal to M_{j−1}, and degree zero equal to ∫x⁻¹dν. The example explains how this last scalar can select among negative moment data in indeterminate half-line problems. C(0) weighs a_m by 1/(m−1)^2 and includes W₁, so it does not supply that inverse moment directly.", "topic": "Inverse spectral ambiguity", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "online_publication_date": "2026-07-08", "id": "PAPER-INV62-EXTREMAL", "arxiv": "2603.26302", "read_scope": "Read the Friedrichs/Krein setup, the negative-first-moment constraints and selected proof of Theorem 3.3. Other weighting regimes outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-EXTREMAL"]}','Special N-extremal solutions to indeterminate moment problems','["Christian Berg", "Ryszard Szwarc"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2603.26302v1','b07a6c6f2c4efb406eb06ec6aba26563f0b81e876141ab6f30edcfcd4d87d5c3','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-FRACTION','corpus/bibliography.jsonl',651,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-FRACTION", "title": "Continued-fraction characterization of Stieltjes moment sequences with support in [ξ, ∞)", "authors": ["Alan D. Sokal", "James Walrad"], "year": 2026, "venue": "Proceedings of the American Mathematical Society", "doi": "10.1090/proc/17639", "arxiv_id": "2404.12131", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1090/proc/17639", "source_url": "https://arxiv.org/pdf/2404.12131v1", "version": "v1", "version_date": "2024-04-18", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/2404.12131.pdf", "source_sha256": "488602b28ab60f1fc56736204fc9de5036c023e992f39bc9742949b978716698", "pages": 10, "version_receipt": "sources/latest62_inverse_adjacent/2404.12131.html", "publication_receipt": "sources/latest62_inverse_adjacent/2404.12131.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read the exact continued-fraction condition, including the insufficiency of the odd-coefficient lower bound. Proof and remaining examples outside scope.", "statement_locator": "Theorem 2, equations (3a)–(3b) and Remark 1", "scoped_statement": "The parameterization of the S-fraction by nonnegative g_i is equivalent to the existence of a representing measure supported on [ξ,∞).", "prefix_inverse_transfer": "At ξ=2, apply to the full moment sequence M_j after triangular extraction to test the left-edge half-line support condition. This criterion cannot enforce discrete gaps or constrain the largest occupied multiplicity.", "topic": "Inverse spectral ambiguity", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "publication_date": "2026-01-17", "id": "PAPER-INV62-FRACTION", "arxiv": "2404.12131", "read_scope": "Read the exact continued-fraction condition, including the insufficiency of the odd-coefficient lower bound. Proof and remaining examples outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-FRACTION"]}','Continued-fraction characterization of Stieltjes moment sequences with support in [ξ, ∞)','["Alan D. Sokal", "James Walrad"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2404.12131v1','488602b28ab60f1fc56736204fc9de5036c023e992f39bc9742949b978716698','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-INV62-SIMON','corpus/bibliography.jsonl',652,'full_text_accessed','papers/latest62_inverse_adjacent.md','{"paper_id": "PAPER-INV62-SIMON", "title": "The Classical Moment Problem as a Self-Adjoint Finite Difference Operator", "authors": ["Barry Simon"], "year": 1998, "venue": "Advances in Mathematics 137(1), 82–203", "doi": "10.1006/aima.1998.1728", "arxiv_id": "math-ph/9906008", "publication_status": "Published journal article", "canonical_url": "https://doi.org/10.1006/aima.1998.1728", "source_url": "https://arxiv.org/pdf/math-ph/9906008v1", "version": "v1", "version_date": "1999-06-08", "source_edition": "Pinned arXiv PDF", "source_path": "sources/latest62_inverse_adjacent/simon.pdf", "source_sha256": "a8099f113ccb4d76bc9206afb7f5500730d07163d556411b0901e3a9331149ee", "pages": 107, "version_receipt": "sources/latest62_inverse_adjacent/simon.html", "publication_receipt": "sources/latest62_inverse_adjacent/simon.doi.json", "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Read the operator correspondence and criteria statements, with selected proof passages. The long Padé and entire-function analyses are outside scope.", "statement_locator": "Theorems 2.10–2.14 and 5.21–5.22, introduction", "scoped_statement": "The Hamburger operator correspondence distinguishes essential self-adjointness from multiple self-adjoint extensions. The Stieltjes criteria distinguish half-line determinacy from Hamburger determinacy, and the paper develops the Jacobi strong-resolvent approach to Padé convergence.", "prefix_inverse_transfer": "The lifted signed-square-root distribution in the prefix proof is a different moment sequence and a different Jacobi operator from the original ν. Stieltjes determinacy of ν alone does not imply that its minimal Jacobi operator is essentially self-adjoint.", "topic": "Inverse spectral ambiguity", "prefix_theorem": "audits/adversarial_reviews/director_prefix_inverse_round8.md", "record_path": "papers/latest62_inverse_adjacent.md", "novelty_claim": false, "id": "PAPER-INV62-SIMON", "arxiv": "math-ph/9906008", "read_scope": "Read the operator correspondence and criteria statements, with selected proof passages. The long Padé and entire-function analyses are outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_inverse_adjacent_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-INV62-SIMON"]}','The Classical Moment Problem as a Self-Adjoint Finite Difference Operator','["Barry Simon"]',NULL,'1998',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/math-ph/9906008v1','a8099f113ccb4d76bc9206afb7f5500730d07163d556411b0901e3a9331149ee','papers/latest62_inverse_adjacent.md','papers/latest62_inverse_adjacent_records.jsonl');
