INSERT INTO "papers" VALUES('PAPER-STAT62-001','corpus/bibliography.jsonl',656,'unknown','papers/PAPER-STAT62-001.md','{"paper_id": "PAPER-STAT62-001", "title": "Theorem on the “universality” of the Riemann zeta-function", "authors": ["S. M. Voronin"], "year": 1975, "venue": "Math. USSR-Izv. 9(3), 443–453; Russian original Izv. Akad. Nauk SSSR Ser. Mat. 39(3), 475–486", "doi": "10.1070/IM1975v009n03ABEH001485", "arxiv_id": null, "version": null, "version_date": null, "first_submission_date": null, "publication_status": "journal work", "canonical_url": "https://doi.org/10.1070/IM1975v009n03ABEH001485", "source_url": "https://www.mathnet.ru/php/archive.phtml?jrnid=im&option_lang=eng&paperid=2037&wshow=paper", "source_path": null, "source_sha256": null, "pages": null, "local_version_receipt": null, "source_edition": "publisher or journal record", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": false, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Checked Math-Net’s original and translation bibliographic entries and the common DOI. The English PDF retrieval was blocked, so this record does not attribute the later general compact-set formulation to the original paper.", "selection_reason": "The original universality work concerns uniform approximation by vertical zeta translates of a nonvanishing holomorphic target on an interior disc in the critical strip. Its role is the starting point for Bagchi’s distribution and recurrence line.", "record_path": "papers/PAPER-STAT62-001.md", "id": "PAPER-STAT62-001", "arxiv": null, "read_scope": "Checked Math-Net’s original and translation bibliographic entries and the common DOI. The English PDF retrieval was blocked, so this record does not attribute the later general compact-set formulation to the original paper.", "access_status": "unknown", "track_file": "papers/latest62_statistics_records.jsonl", "origin