INSERT INTO "papers" VALUES('PAPER-STAT62-002','corpus/bibliography.jsonl',657,'unknown','papers/PAPER-STAT62-002.md','{"paper_id": "PAPER-STAT62-002", "title": "Recurrence in topological dynamics and the Riemann hypothesis", "authors": ["Bhaskar Bagchi"], "year": 1987, "venue": "Acta Mathematica Hungarica 50, 227–240", "doi": "10.1007/BF01903937", "arxiv_id": null, "version": null, "version_date": null, "first_submission_date": null, "publication_status": "journal work", "canonical_url": "https://doi.org/10.1007/BF01903937", "source_url": "https://link.springer.com/article/10.1007/BF01903937", "source_path": "sources/latest62_statistics/bagchi_recurrence.html", "source_sha256": "8bf536ad894b007b9957b0a32363651f41270ed03afb3de730bc5d0c825d092f", "pages": null, "local_version_receipt": null, "source_edition": "publisher or journal record", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": false, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Publisher metadata, date, pages and backward references inspected. The publisher full article is subscriber-restricted in the checked route. The ISI item was inspected only as a separate archival identity and is not the source of this record.", "selection_reason": "The dynamical recurrence formulation links self-approximation of zeta to RH and follows Bagchi’s 1982 joint universality work. This entry identifies the recurrence journal article rather than the archival thesis.", "record_path": "papers/PAPER-STAT62-002.md", "id": "PAPER-STAT62-002", "arxiv": null, "read_scope": "Publisher metadata, date, pages and backward references inspected. The publisher full article is subscriber-restricted in the checked route. The ISI item was inspected only as a separate archival identity and is not the source of this record.", "access_status": "unknown", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-002"]}','Recurrence in topological dynamics and the Riemann hypothesis','["Bhaskar Bagchi"]',NULL,'1987',0,0,'selected_checkpoint_priority_work','unknown','publisher or journal record','https://link.springer.com/article/10.1007/BF01903937','8bf536ad894b007b9957b0a32363651f41270ed03afb3de730bc5d0c825d092f','papers/PAPER-STAT62-002.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-003','corpus/bibliography.jsonl',658,'full_text_accessed','papers/PAPER-STAT62-003.md','{"paper_id": "PAPER-STAT62-003", "title": "On the Distribution of Spacings Between Zeros of the Zeta Function", "authors": ["A. M. Odlyzko"], "year": 1987, "venue": "Mathematics of Computation 48(177), 273–308", "doi": "10.2307/2007890", "arxiv_id": null, "version": null, "version_date": null, "first_submission_date": null, "publication_status": "journal work", "canonical_url": "https://doi.org/10.2307/2007890", "source_url": "https://web.williams.edu/Mathematics/sjmiller/public_html/ntprob19/handouts/computational/Odlyzko_DistrSpacingsZerosZeta.pdf", "source_path": "sources/latest62_statistics/odlyzko.pdf", "source_sha256": "efe68f0f0888c269acaa3bd59d8eda0e52640696566fa3061af3cd50779e6afb", "pages": 37, "local_version_receipt": null, "source_edition": "JSTOR scan of published article in university-hosted copy", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "JSTOR journal scan title and opening checked using page-image OCR. Numerical implementation, error certification and full figures were outside read scope.", "selection_reason": "Early large-scale numerical tests of Montgomery’s conjecture and GUE spacing predictions compare zeros around the origin and a much higher block. The article also identifies deviations related to primes. It is computational evidence about sampled blocks.", "record_path": "papers/PAPER-STAT62-003.md", "id": "PAPER-STAT62-003", "arxiv": null, "read_scope": "JSTOR journal scan title and opening checked using page-image OCR. Numerical implementation, error certification and full figures were outside read scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-003"]}','On the Distribution of Spacings Between Zeros of the Zeta Function','["A. M. Odlyzko"]',NULL,'1987',0,0,'selected_checkpoint_priority_work','full_text_accessed','JSTOR scan of published article in university-hosted copy','https://web.williams.edu/Mathematics/sjmiller/public_html/ntprob19/handouts/computational/Odlyzko_DistrSpacingsZerosZeta.pdf','efe68f0f0888c269acaa3bd59d8eda0e52640696566fa3061af3cd50779e6afb','papers/PAPER-STAT62-003.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-004','corpus/bibliography.jsonl',659,'full_text_accessed','papers/PAPER-STAT62-004.md','{"paper_id": "PAPER-STAT62-004", "title": "Zeros of principal L-functions and random matrix theory", "authors": ["Zeév Rudnick", "Peter Sarnak"], "year": 1996, "venue": "Duke Mathematical Journal 81(2), 269–322", "doi": "10.1215/S0012-7094-96-08115-6", "arxiv_id": null, "version": null, "version_date": null, "first_submission_date": null, "publication_status": "journal work", "canonical_url": "https://doi.org/10.1215/S0012-7094-96-08115-6", "source_url": "https://empslocal.ex.ac.uk/people/staff/mrwatkin/zeta/rudnick-sarnak.pdf", "source_path": "sources/latest62_statistics/rs.pdf", "source_sha256": "393cd6ad3a61036070ed7b86113de5dd1bb033b47eec8998fb9597bb091c13c7", "pages": 60, "local_version_receipt": null, "source_edition": "university-hosted author manuscript", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Introduction, hypotheses and Theorems 1.1–1.2 checked in hosted manuscript; proofs and published text comparison outside scope.", "selection_reason": "Theorem 1.1 proves a smoothed n-level correlation asymptotic with Fourier support sum |ξ_j|<2/m for cuspidal GL(m) over Q, subject to its condition (1.7) for m>3. Theorem 1.2 adds RH for the transition to ordered normalized zeros. The support restriction is central to the GUE comparison.", "record_path": "papers/PAPER-STAT62-004.md", "id": "PAPER-STAT62-004", "arxiv": null, "read_scope": "Introduction, hypotheses and Theorems 1.1–1.2 checked in hosted manuscript; proofs and published text comparison outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-004"]}','Zeros of principal L-functions and random matrix theory','["Zeév Rudnick", "Peter Sarnak"]',NULL,'1996',0,0,'selected_checkpoint_priority_work','full_text_accessed','university-hosted author manuscript','https://empslocal.ex.ac.uk/people/staff/mrwatkin/zeta/rudnick-sarnak.pdf','393cd6ad3a61036070ed7b86113de5dd1bb033b47eec8998fb9597bb091c13c7','papers/PAPER-STAT62-004.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-005','corpus/bibliography.jsonl',660,'full_text_accessed','papers/PAPER-STAT62-005.md','{"paper_id": "PAPER-STAT62-005", "title": "Random Matrix Theory and ζ(1/2 + it)", "authors": ["J. P. Keating", "N. C. Snaith"], "year": 2000, "venue": "Communications in Mathematical Physics 214(1), 57–89", "doi": "10.1007/s002200000261", "arxiv_id": null, "version": null, "version_date": null, "first_submission_date": null, "publication_status": "journal work", "canonical_url": "https://doi.org/10.1007/s002200000261", "source_url": "https://web.williams.edu/Mathematics/sjmiller/public_html/RH/KeatingSnaith_RandomMatrixThAndZeta%28s%2Bit%29.pdf", "source_path": "sources/latest62_statistics/ks.pdf", "source_sha256": "097f78ed43e8427864a4566b5448a92eecca901b73a64c0d970c296aa90a42c8", "pages": 33, "local_version_receipt": null, "source_edition": "university-hosted publisher PDF", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Publisher first page, characteristic polynomial setup, and lead discussion checked. CUE derivations and the full moment conjecture proof context were outside read scope.", "selection_reason": "Exact finite-size Haar-unitary characteristic-polynomial moments and a Gaussian limit provide the matrix side of the moment analogy. The proposed zeta moment leading term includes an Euler product and a Barnes G-factor; the latter comes from the CUE calculation.", "record_path": "papers/PAPER-STAT62-005.md", "id": "PAPER-STAT62-005", "arxiv": null, "read_scope": "Publisher first page, characteristic polynomial setup, and lead discussion checked. CUE derivations and the full moment conjecture proof context were outside read scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-005"]}','Random Matrix Theory and ζ(1/2 + it)','["J. P. Keating", "N. C. Snaith"]',NULL,'2000',0,0,'selected_checkpoint_priority_work','full_text_accessed','university-hosted publisher PDF','https://web.williams.edu/Mathematics/sjmiller/public_html/RH/KeatingSnaith_RandomMatrixThAndZeta%28s%2Bit%29.pdf','097f78ed43e8427864a4566b5448a92eecca901b73a64c0d970c296aa90a42c8','papers/PAPER-STAT62-005.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-006','corpus/bibliography.jsonl',661,'full_text_accessed','papers/PAPER-STAT62-006.md','{"paper_id": "PAPER-STAT62-006", "title": "Mesoscopic fluctuations of the zeta zeros", "authors": ["Paul Bourgade"], "year": 2010, "venue": "Probability Theory and Related Fields 148, 479–500", "doi": "10.1007/s00440-009-0237-3", "arxiv_id": "0902.1757", "version": "v1", "version_date": "2009-02-10", "first_submission_date": "2009-02-10", "publication_status": "journal work", "canonical_url": "https://arxiv.org/abs/0902.1757v1", "source_url": "https://arxiv.org/pdf/0902.1757v1", "source_path": "sources/latest62_statistics/bourgade.pdf", "source_sha256": "1e2ed2fc0419c23a0aa084c2e9ba86125266d6c7ca39942b1f29eee5f50c8ada", "pages": 20, "local_version_receipt": "sources/latest62_statistics/bourgade.abs.html", "source_edition": "pinned arXiv version", "publication_receipt": "sources/latest62_statistics/bourgade.crossref.json", "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": true, "substantive_reading": true, "audit_level": 1, "audit_scope": "All 20 pages of v1, including §§2–4 proofs, examples, diagram and references. Author-hosted version spot-checked for Corollary 1.3.", "selection_reason": "A joint Gaussian limit for log zeta at bounded moving shifts identifies the covariance from the logarithmic separation of the shifts. Its zero-count corollary is mesoscopic and shares the endpoint covariance structure of a Haar-unitary analogue.", "record_path": "papers/PAPER-STAT62-006.md", "id": "PAPER-STAT62-006", "arxiv": "0902.1757", "read_scope": "All 20 pages of v1, including §§2–4 proofs, examples, diagram and references. Author-hosted version spot-checked for Corollary 1.3.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-006"]}','Mesoscopic fluctuations of the zeta zeros','["Paul Bourgade"]',NULL,'2010',1,1,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/0902.1757v1','1e2ed2fc0419c23a0aa084c2e9ba86125266d6c7ca39942b1f29eee5f50c8ada','papers/PAPER-STAT62-006.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-007','corpus/bibliography.jsonl',662,'full_text_accessed','papers/PAPER-STAT62-007.md','{"paper_id": "PAPER-STAT62-007", "title": "Freezing Transition, Characteristic Polynomials of Random Matrices, and the Riemann Zeta Function", "authors": ["Yan V. Fyodorov", "Ghaith A. Hiary", "Jonathan P. Keating"], "year": 2012, "venue": "Physical Review Letters 108, 170601", "doi": "10.1103/PhysRevLett.108.170601", "arxiv_id": "1202.4713", "version": "v2", "version_date": "2012-04-27", "first_submission_date": "2012-02-21", "publication_status": "journal work", "canonical_url": "https://arxiv.org/abs/1202.4713v2", "source_url": "https://arxiv.org/pdf/1202.4713v2", "source_path": "sources/latest62_statistics/fhk.pdf", "source_sha256": "fde1660b3d0318fba6daf0aecdcecbb4d14edfd23553fb1683dac1471ec66d94", "pages": 4, "local_version_receipt": "sources/latest62_statistics/fhk.abs.html", "source_edition": "pinned arXiv version", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "The four-page letter’s setup, formulas (6)–(14), proposed law and simulation summaries inspected. No independent validation of the freezing argument.", "selection_reason": "The short-interval maximum conjecture uses a logarithmically correlated field and predicts a −(3/4) log log log T correction to log log T on the zeta side. The freezing heuristic, Toeplitz-moment comparison and finite-height experiments are distinguished from a theorem about zeta maxima.", "record_path": "papers/PAPER-STAT62-007.md", "id": "PAPER-STAT62-007", "arxiv": "1202.4713", "read_scope": "The four-page letter’s setup, formulas (6)–(14), proposed law and simulation summaries inspected. No independent validation of the freezing argument.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-007"]}','Freezing Transition, Characteristic Polynomials of Random Matrices, and the Riemann Zeta Function','["Yan V. Fyodorov", "Ghaith A. Hiary", "Jonathan P. Keating"]',NULL,'2012',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/1202.4713v2','fde1660b3d0318fba6daf0aecdcecbb4d14edfd23553fb1683dac1471ec66d94','papers/PAPER-STAT62-007.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-008','corpus/bibliography.jsonl',663,'full_text_accessed','papers/PAPER-STAT62-008.md','{"paper_id": "PAPER-STAT62-008", "title": "A central limit theorem for the zeroes of the zeta function", "authors": ["Brad Rodgers"], "year": 2014, "venue": "International Journal of Number Theory, 483–511", "doi": "10.1142/S1793042113501054", "arxiv_id": "1205.0303", "version": "v5", "version_date": "2014-05-10", "first_submission_date": "2012-05-02", "publication_status": "journal work", "canonical_url": "https://arxiv.org/abs/1205.0303v5", "source_url": "https://arxiv.org/pdf/1205.0303v5", "source_path": "sources/latest62_statistics/rodgers.pdf", "source_sha256": "3ec72fda8c30a6a56fbf87f21ab4f2fa1d7fd81ebd39a9612ff9f89844eefe2f", "pages": 22, "local_version_receipt": "sources/latest62_statistics/rodgers.abs.html", "source_edition": "pinned arXiv version", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Theorems 1.1–1.3 and introduction checked in arXiv v5. The related DOI is reported by arXiv; proofs outside scope.", "selection_reason": "Theorem 1.2 extends Fujii’s mesoscopic CLT to compactly supported real bounded-variation test functions with divergent integral of |x||η̂(x)|². The random height is uniform on [T,2T], and the scale n(T) tends to infinity with n(T)=o(log T). Variance is asymptotic to that integral truncated at ±n(T).", "record_path": "papers/PAPER-STAT62-008.md", "id": "PAPER-STAT62-008", "arxiv": "1205.0303", "read_scope": "Theorems 1.1–1.3 and introduction checked in arXiv v5. The related DOI is reported by arXiv; proofs outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-008"]}','A central limit theorem for the zeroes of the zeta function','["Brad Rodgers"]',NULL,'2014',0,0,'selected_checkpoint_priority_work','full_text_accessed','v5','https://arxiv.org/pdf/1205.0303v5','3ec72fda8c30a6a56fbf87f21ab4f2fa1d7fd81ebd39a9612ff9f89844eefe2f','papers/PAPER-STAT62-008.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-009','corpus/bibliography.jsonl',664,'full_text_accessed','papers/PAPER-STAT62-009.md','{"paper_id": "PAPER-STAT62-009", "title": "Sharp conditional bounds for moments of the Riemann zeta function", "authors": ["Adam J. Harper"], "year": 2013, "venue": null, "doi": null, "arxiv_id": "1305.4618", "version": "v1", "version_date": "2013-05-20", "first_submission_date": "2013-05-20", "publication_status": "arXiv preprint, journal publication unverified", "canonical_url": "https://arxiv.org/abs/1305.4618v1", "source_url": "https://arxiv.org/pdf/1305.4618v1", "source_path": "sources/latest62_statistics/harper.pdf", "source_sha256": "8ec5bdb754d04c020d38e5aa3debd65949d933427a3907ec1008e9aef394c77c", "pages": 20, "local_version_receipt": "sources/latest62_statistics/harper.abs.html", "source_edition": "pinned arXiv version", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Theorem 1 and the initial upper polynomial proposition checked. Proof of this sharp fixed-k result outside scope.", "selection_reason": "Assuming RH, the upper bound for the 2kth critical-line moment has the sharp order \\(T(\\log T)^{k^2}\\) for every fixed real \\(k\\ge0\\). Adaptive prime-block lengths remove the extra logarithmic loss from the earlier Soundararajan approach.", "record_path": "papers/PAPER-STAT62-009.md", "id": "PAPER-STAT62-009", "arxiv": "1305.4618", "read_scope": "Theorem 1 and the initial upper polynomial proposition checked. Proof of this sharp fixed-k result outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-009"]}','Sharp conditional bounds for moments of the Riemann zeta function','["Adam J. Harper"]',NULL,'2013',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/1305.4618v1','8ec5bdb754d04c020d38e5aa3debd65949d933427a3907ec1008e9aef394c77c','papers/PAPER-STAT62-009.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-010','corpus/bibliography.jsonl',665,'full_text_accessed','papers/PAPER-STAT62-010.md','{"paper_id": "PAPER-STAT62-010", "title": "Maximum of the characteristic polynomial of random unitary matrices", "authors": ["Louis-Pierre Arguin", "David Belius", "Paul Bourgade"], "year": 2017, "venue": "Communications in Mathematical Physics", "doi": "10.1007/s00220-016-2740-6", "arxiv_id": "1511.07399", "version": "v3", "version_date": "2016-06-03", "first_submission_date": "2015-11-23", "publication_status": "journal work", "canonical_url": "https://arxiv.org/abs/1511.07399v3", "source_url": "https://arxiv.org/pdf/1511.07399v3", "source_path": "sources/latest62_statistics/abb.pdf", "source_sha256": "4eea123f526a1116049725d2889edca6eb76351ca94653df8de4445e4637bb87", "pages": 39, "local_version_receipt": "sources/latest62_statistics/abb.abs.html", "source_edition": "pinned arXiv version", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Opening setup and Theorems 1.2–1.3 checked in primary paper; proofs and publisher-vs-arXiv comparison outside scope.", "selection_reason": "For Haar U(N), the full-circle maximum of the log modulus divided by log N tends to 1 in probability. The high-point set at level γ log N has logarithmic measure exponent −γ² for fixed 0<γ<1. These are matrix-ensemble results.", "record_path": "papers/PAPER-STAT62-010.md", "id": "PAPER-STAT62-010", "arxiv": "1511.07399", "read_scope": "Opening setup and Theorems 1.2–1.3 checked in primary paper; proofs and publisher-vs-arXiv comparison outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-010"]}','Maximum of the characteristic polynomial of random unitary matrices','["Louis-Pierre Arguin", "David Belius", "Paul Bourgade"]',NULL,'2017',0,0,'selected_checkpoint_priority_work','full_text_accessed','v3','https://arxiv.org/pdf/1511.07399v3','4eea123f526a1116049725d2889edca6eb76351ca94653df8de4445e4637bb87','papers/PAPER-STAT62-010.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-011','corpus/bibliography.jsonl',666,'full_text_accessed','papers/PAPER-STAT62-011.md','{"paper_id": "PAPER-STAT62-011", "title": "Maximum of the Riemann zeta function on a short interval of the critical line", "authors": ["Louis-Pierre Arguin", "David Belius", "Paul Bourgade", "Maksym Radziwiłł", "Kannan Soundararajan"], "year": 2019, "venue": "Communications on Pure and Applied Mathematics 72, 500–535", "doi": "10.1002/cpa.21791", "arxiv_id": "1612.08575", "version": "v3", "version_date": "2018-01-14", "first_submission_date": "2016-12-27", "publication_status": "journal work", "canonical_url": "https://arxiv.org/abs/1612.08575v3", "source_url": "https://arxiv.org/pdf/1612.08575v3", "source_path": "sources/latest62_statistics/abbrs.pdf", "source_sha256": "9b320442938ced37b941dc4a92c600e5987d4c7ef6a70717640498345f669943", "pages": 28, "local_version_receipt": "sources/latest62_statistics/abbrs.abs.html", "source_edition": "pinned arXiv version", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Theorem 1.1, leading order, window and probability normalization checked in v3. Proof details outside scope.", "selection_reason": "Theorem 1.1 gives an unconditional leading scale log log T for the maximum of log |ζ| over |t−u|≤1 for a proportion tending to one of t in [T,2T]. It records independent conditional work by Najnudel and does not establish the FHK second-order law.", "record_path": "papers/PAPER-STAT62-011.md", "id": "PAPER-STAT62-011", "arxiv": "1612.08575", "read_scope": "Theorem 1.1, leading order, window and probability normalization checked in v3. Proof details outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_stat