INSERT INTO "papers" VALUES('PAPER-STAT62-012','corpus/bibliography.jsonl',667,'full_text_accessed','papers/PAPER-STAT62-012.md','{"paper_id": "PAPER-STAT62-012", "title": "The Fyodorov-Hiary-Keating Conjecture. I", "authors": ["Louis-Pierre Arguin", "Paul Bourgade", "Maksym Radziwiłł"], "year": 2020, "venue": null, "doi": null, "arxiv_id": "2007.00988", "version": "v2", "version_date": "2020-10-09", "first_submission_date": "2020-07-02", "publication_status": "arXiv preprint, journal publication unverified", "canonical_url": "https://arxiv.org/abs/2007.00988v2", "source_url": "https://arxiv.org/pdf/2007.00988v2", "source_path": "sources/latest62_statistics/fhk1.pdf", "source_sha256": "6ae3190d09290d0afec47c5d61c177d712d25381e1271b9b07eb1506c9cdc71e", "pages": 49, "local_version_receipt": "sources/latest62_statistics/fhk1.abs.html", "source_edition": "pinned arXiv version", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Theorem 1 and submission history checked. The [Caltech author deposit](https://authors.library.caltech.edu/records/9wk6x-70098) supplies the acknowledgment. No line-by-line reconstruction of the initial Lemma 23 or of its repair.", "selection_reason": "Theorem 1 supplies the upper tail C y exp(−2y) at level eʸ log T/(log log T)^{3/4}, uniformly for T≥3 and y≥1, for the maximum over |h|≤1 about a uniformly random t in [T,2T]. The author deposit acknowledges an error pointed out in the initial proof of Lemma 23. The pinned v2 receipt notes a simplified Appendix B.", "record_path": "papers/PAPER-STAT62-012.md", "id": "PAPER-STAT62-012", "arxiv": "2007.00988", "read_scope": "Theorem 1 and submission history checked. The [Caltech author deposit](https://authors.library.caltech.edu/records/9wk6x-70098) supplies the acknowledgment. No line-by-line reconstruction of the initial Lemma 23 or of its repair.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-012"]}','The Fyodorov-Hiary-Keating Conjecture. I','["Louis-Pierre Arguin", "Paul Bourgade", "Maksym Radziwiłł"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/2007.00988v2','6ae3190d09290d0afec47c5d61c177d712d25381e1271b9b07eb1506c9cdc71e','papers/PAPER-STAT62-012.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-013','corpus/bibliography.jsonl',668,'full_text_accessed','papers/PAPER-STAT62-013.md','{"paper_id": "PAPER-STAT62-013", "title": "The Fyodorov-Hiary-Keating Conjecture. II", "authors": ["Louis-Pierre Arguin", "Paul Bourgade", "Maksym Radziwiłł"], "year": 2023, "venue": null, "doi": null, "arxiv_id": "2307.00982", "version": "v1", "version_date": "2023-07-03", "first_submission_date": "2023-07-03", "publication_status": "arXiv preprint, journal publication unverified", "canonical_url": "https://arxiv.org/abs/2307.00982v1", "source_url": "https://arxiv.org/pdf/2307.00982v1", "source_path": "sources/latest62_statistics/fhk2.pdf", "source_sha256": "08be620b1eec3fd9fdbd35720f8580f640e03f97a2af3d9e8613f113d1ab4db6", "pages": 41, "local_version_receipt": "sources/latest62_statistics/fhk2.abs.html", "source_edition": "pinned arXiv version", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Theorem 1 and Corollary 1 checked in arXiv v1. Ballot and multiscale proofs were outside scope.", "selection_reason": "Theorem 1 bounds the probability of the maximum falling below e⁻ʸ log T/(log log T)^{3/4} by c⁻¹y⁻ᶜ for 0<y≤(log log T)^{1/10}, T≥100. Paired with Part I this gives tightness of the recentered maximum, which is weaker than identifying its limiting law.", "record_path": "papers/PAPER-STAT62-013.md", "id": "PAPER-STAT62-013", "arxiv": "2307.00982", "read_scope": "Theorem 1 and Corollary 1 checked in arXiv v1. Ballot and multiscale proofs were outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-013"]}','The Fyodorov-Hiary-Keating Conjecture. II','["Louis-Pierre Arguin", "Paul Bourgade", "Maksym Radziwiłł"]',NULL,'2023',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2307.00982v1','08be620b1eec3fd9fdbd35720f8580f640e03f97a2af3d9e8613f113d1ab4db6','papers/PAPER-STAT62-013.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-014','corpus/bibliography.jsonl',669,'full_text_accessed','papers/PAPER-STAT62-014.md','{"paper_id": "PAPER-STAT62-014", "title": "The Fyodorov-Hiary-Keating Conjecture on Mesoscopic Intervals", "authors": ["Louis-Pierre Arguin", "Jad Hamdan"], "year": 2026, "venue": "The Annals of Probability", "doi": "10.1214/25-AOP1783", "arxiv_id": "2405.06474", "version": "v2", "version_date": "2026-05-25", "first_submission_date": "2024-05-10", "publication_status": "journal work", "canonical_url": "https://arxiv.org/abs/2405.06474v2", "source_url": "https://arxiv.org/pdf/2405.06474v2", "source_path": "sources/latest62_statistics/mesofhk.pdf", "source_sha256": "ba6dbdf851642d9d31fd1d16d4de72bd776ac099b80b1b4ab60d2f44cefda5f6", "pages": 44, "local_version_receipt": "sources/latest62_statistics/mesofhk.abs.html", "source_edition": "pinned arXiv version", "publication_receipt": "sources/latest62_statistics/fhk1.crossref.json", "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "v2 Theorems 1.2–1.3 and formulas (2)–(4) checked. Publisher DOI and issue year located independently; journal proof/correction comparison and v1/v2 mathematical diff outside scope.", "selection_reason": "Theorem 1.2 gives an upper tail refined by the Gaussian factor exp(−y²/((1+θ)log log T)) for fixed −1<θ≤0 and y between 2 and C log log T/log log log T. The critical-line radius is (log T)^θ, with the low-prime factor Pτ(θ) multiplying the maximum. Theorem 1.3 concerns the normalized second-moment partition function.", "record_path": "papers/PAPER-STAT62-014.md", "id": "PAPER-STAT62-014", "arxiv": "2405.06474", "read_scope": "v2 Theorems 1.2–1.3 and formulas (2)–(4) checked. Publisher DOI and issue year located independently; journal proof/correction comparison and v1/v2 mathematical diff outside scope.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-014"]}','The Fyodorov-Hiary-Keating Conjecture on Mesoscopic Intervals','["Louis-Pierre Arguin", "Jad Hamdan"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','v2','https://arxiv.org/pdf/2405.06474v2','ba6dbdf851642d9d31fd1d16d4de72bd776ac099b80b1b4ab60d2f44cefda5f6','papers/PAPER-STAT62-014.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-015','corpus/bibliography.jsonl',670,'full_text_accessed','papers/PAPER-STAT62-015.md','{"paper_id": "PAPER-STAT62-015", "title": "Lower bounds for the large deviations and moments of the Riemann zeta function on the critical line", "authors": ["Louis-Pierre Arguin", "Nathan Creighton"], "year": 2026, "venue": null, "doi": null, "arxiv_id": "2603.01711", "version": "v1", "version_date": "2026-03-02", "first_submission_date": "2026-03-02", "publication_status": "arXiv preprint, journal publication unverified", "canonical_url": "https://arxiv.org/abs/2603.01711v1", "source_url": "https://arxiv.org/pdf/2603.01711v1", "source_path": "sources/latest62_statistics/large2026.pdf", "source_sha256": "00df3499ba965af52f3e5729c62a0dfc563911946fbd31c364a83e08466b15c6", "pages": 26, "local_version_receipt": "sources/latest62_statistics/large2026.abs.html", "source_edition": "pinned arXiv version", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "v1 Theorems 1.1 and 1.3 and comparisons to earlier bounds checked. Multiscale lower-bound proof and constants not rederived.", "selection_reason": "Theorem 1.1 gives an unconditional lower bound by a positive α-dependent multiple of the Gaussian tail for V∼α log log T, every fixed α>0. It complements the existing separate upper bounds and also treats primitive even characters of prime conductor at central points in Theorem 1.3.", "record_path": "papers/PAPER-STAT62-015.md", "id": "PAPER-STAT62-015", "arxiv": "2603.01711", "read_scope": "v1 Theorems 1.1 and 1.3 and comparisons to earlier bounds checked. Multiscale lower-bound proof and constants not rederived.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-015"]}','Lower bounds for the large deviations and moments of the Riemann zeta function on the critical line','["Louis-Pierre Arguin", "Nathan Creighton"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2603.01711v1','00df3499ba965af52f3e5729c62a0dfc563911946fbd31c364a83e08466b15c6','papers/PAPER-STAT62-015.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-STAT62-016','corpus/bibliography.jsonl',671,'full_text_accessed','papers/PAPER-STAT62-016.md','{"paper_id": "PAPER-STAT62-016", "title": "Convergence in law of the maximum of the Riemann zeta function on expanding intervals near the critical line", "authors": ["Frédéric Ouimet"], "year": 2026, "venue": null, "doi": null, "arxiv_id": "2611.01905", "version": "v1", "version_date": "2026-11-01", "first_submission_date": "2026-11-01", "publication_status": "arXiv preprint, journal publication unverified", "canonical_url": "https://arxiv.org/abs/2611.01905v1", "source_url": "https://arxiv.org/pdf/2611.01905v1", "source_path": "sources/latest62_statistics/law2026.pdf", "source_sha256": "9429bc025f32ea954a9f2de78c7ee4097ded8dfea45ec07d9577bc9866d6d861", "pages": 60, "local_version_receipt": "sources/latest62_statistics/law2026.abs.html", "source_edition": "pinned arXiv version", "publication_receipt": null, "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": false, "audit_level": 0, "audit_scope": "Targeted dependency audit of v1 §§2–6, including assumptions, conditional local laws, annulus estimates, grid and continuum arguments, exact recentering, and final zeta transfer. Reconstructed the cited October predecessor’s unconditional approximation bridge. Selected rare-tail and fractional-moment proofs remain unverified in full. See audits/latest62_ouimet_gumbel_dependency.md.", "selection_reason": "Theorem 2.1 states an unconditional Gumbel limit with scale 1/(2√(1+θ)), fixed θ>0, about a uniform random height in [T,2T]. Its interval radius is (log T)^θ and its real part moves to 1/2 from the right under the prime-power cutoff and displacement hypotheses in (2.1). Centering uses an exact upper quantile in the auxiliary Haar model. This is a distinct regime from the critical-line maximum.", "record_path": "papers/PAPER-STAT62-016.md", "id": "PAPER-STAT62-016", "arxiv": "2611.01905", "read_scope": "Targeted dependency audit of v1 §§2–6, including assumptions, conditional local laws, annulus estimates, grid and continuum arguments, exact recentering, and final zeta transfer. Reconstructed the cited October predecessor’s unconditional approximation bridge. Selected rare-tail and fractional-moment proofs remain unverified in full. See audits/latest62_ouimet_gumbel_dependency.md.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/latest62_statistics_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-STAT62-016"]}','Convergence in law of the maximum of the Riemann zeta function on expanding intervals near the critical line','["Frédéric Ouimet"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2611.01905v1','9429bc025f32ea954a9f2de78c7ee4097ded8dfea45ec07d9577bc9866d6d861','papers/PAPER-STAT62-016.md','papers/latest62_statistics_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-E008','corpus/bibliography.jsonl',672,'full_text_accessed','audits/adversarial_reviews/director_li_whole_round12.md','{"id": "PAPER-E008", "title": "The Positivity of a Sequence of Numbers and the Riemann Hypothesis", "authors": ["Xian-Jin Li"], "date": "1997-08", "year": 1997, "venue": "Journal of Number Theory65(2)(1997),325–333", "publication_status": "published; journal-typeset manifestation accessed through a public mirror", "doi": "10.1006/jnth.1997.2137", "arxiv": null, "source_url": "https://doi.org/10.1006/jnth.1997.2137", "publisher_pii": "S0022314X97921375", "article_number": "NT972137", "mirror_url": "https://paperzz.com/doc/7086946/--science-direct", "version": "1997 journal-typeset manifestation, pp. 325–333, recovered from Paperzz mirror", "family": ["C", "E"], "audit_level": 3, "whole_work_read": true, "inspected_portions_level": 2, "read_scope": "Complete nine-page journal-typeset manifestation read by advocate, skeptic and director. Both main criteria reconstructed; exact Dedekind normalization and nonvanishing-symbol repairs preserve them. All equations, coefficient centers, branches, convergence, endpoint constants and reference roles inspected. Publisher-byte identity and complete upstream ancestry remain unverified.", "access_status": "full_text_accessed", "available_formats": ["journal-typeset PDF from mirror", "older degraded primary-text reproduction"], "source_file": "sources/li_original_round2/li1997_journal_typeset_mirror.pdf", "source_sha256": "8f5719751f869d71907c9da75270cb8c012b54f1453f54179461dbc331d255a1", "accessed_at": "2026-11-18", "metadata_provenance": "sources/li_original_round2/crossref.json", "main_result": "ForXi(s)=s(s−1)π^(−s/2)Γ(s/2)ζ(s),λ_n=D^n[s^(n−1)logXi(s)]_(s1)/(n−1)!, RH iffλ_n>=0forallpositiveintegersn(Theorem1,p325). Theorem2,p329 givesanalogouscritical-linecriterionforDedekindzetaofanynumberfieldwithnormalizedentirecompletion.", "definitions": "phi(z)=Xi(1/(1−z))=1+Σa_j z^j. Pairzerosrho,1−rho inproductsandsums; derivativeat1 firstgivesinversepowers, pairreflectionconvertspositivepowers.", "proof_architecture": ["Positive theta integralgivesa_j>0", "Localphi′=phiΣλ_n z^(n−1)", "Recurrenceandallλ_n>=0 imply0<=λ_n<=n a_n", "Coefficientdominationextendsλseriesanalyticallytofulldisk", "AnalyticODEexcludesphizeros; MöbiusmapandfunctionalreflectiongiveRH", "Converselycriticalzerosgivepairednonnegative2−2cos(nθ)contributions"], "limitations": ["Every positive integer coefficient is required; a finite prefix does not imply RH.", "Zero sums use reflected pairing rather than arbitrary absolute reordering.", "Current publisher PDF bytes and all original cited book editions were not obtained; matched inputs and independent replacements are documented."], "audit_file": "audits/li1997_round2.md", "correction_search_status": "Crossrefandtargetedsourcequerieschecked; noverifiedcorrigendumlocated; exhaustivehistoryincomplete", "research_questions": ["What arithmetic information can control the unseen Li-coefficient tail?", "Can stable finite coefficient information be coupled to an independently proved global growth or positivity constraint?"], "original_access_status": "full_primary_text_accessed_via_degraded_mirror; publisheranddownloadPDF403", "record_path": "papers/PAPER-E008.md", "track_file": "papers/li_original_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-E008"], "scope_update_history": [{"fields": {"audit_level": 3, "whole_work_read": true, "substantive_reading": true, "version": "1997 journal-typeset manifestation, pp. 325–333, recovered from Paperzz mirror", "source_path": "sources/li_original_round2/li1997_journal_typeset_mirror.pdf", "source_file": "sources/li_original_round2/li1997_journal_typeset_mirror.pdf", "source_sha256": "8f5719751f869d71907c9da75270cb8c012b54f1453f54179461dbc331d255a1", "publication_status": "published; journal-typeset manifestation accessed through a public mirror", "available_formats": ["journal-typeset PDF from mirror", "older degraded primary-text reproduction"], "additional_manifestations": [{"version": "Previously inspected degraded primary-text reproduction", "source_file": "sources/li_original_round2/li1997_paperzz_tool_response.json", "source_sha256": "845a2d9b2c86da1acf3502f9ed2f7f17ae5e922f87761d42c34f321708ba6f2c"}], "accessed_at": "2026-11-18", "read_scope": "Complete nine-page journal-typeset manifestation read by advocate, skeptic and director. Both main criteria reconstructed; exact Dedekind normalization and nonvanishing-symbol repairs preserve them. All equations, coefficient centers, branches, convergence, endpoint constants and reference roles inspected. Publisher-byte identity and complete upstream ancestry remain unverified.", "claim_verification_status": "Whole-work Level 3 for the registered mirror manifestation, with explicit local corrections; neither main criterion is refuted.", "limitations": ["Every positive integer coefficient is required; a finite prefix does not imply RH.", "Zero sums use reflected pairing rather than arbitrary absolute reordering.", "Current publisher PDF bytes and all original cited book editions were not obtained; matched inputs and independent replacements are documented."], "research_questions": ["What arithmetic information can control the unseen Li-coefficient tail?", "Can stable finite coefficient information be coupled to an independently proved global growth or positivity constraint?"], "correction_history": "Bounded correction search found no verified separate corrigendum. The pinned typeset text has a local zeta/Xi nonvanishing-symbol slip and a missing positive complex-place factor in equations (3.4), (3.7); exact repairs and witnesses are director adjudicated."}, "evidence": "audits/adversarial_reviews/director_li_whole_round12.md", "track_file": "quality/zzzzzzz_round12_source_scope_updates.jsonl"}], "substantive_reading": true, "source_path": "sources/li_original_round2/li1997_journal_typeset_mirror.pdf", "additional_manifestations": [{"version": "Previously inspected degraded primary-text reproduction", "source_file": "sources/li_original_round2/li1997_paperzz_tool_response.json", "source_sha256": "845a2d9b2c86da1acf3502f9ed2f7f17ae5e922f87761d42c34f321708ba6f2c"}], "claim_verification_status": "Whole-work Level 3 for the registered mirror manifestation, with explicit local corrections; neither main criterion is refuted.", "correction_history": "Bounded correction search found no verified separate corrigendum. The pinned typeset text has a local zeta/Xi nonvanishing-symbol slip and a missing positive complex-place factor in equations (3.4), (3.7); exact repairs and witnesses are director adjudicated.", "scope_update_evidence": "audits/adversarial_reviews/director_li_whole_round12.md", "additional_scope_update_files": ["quality/zzzzzzz_round12_source_scope_updates.jsonl"]}','The Positivity of a Sequence of Numbers and the Riemann Hypothesis','["Xian-Jin Li"]','["C", "E"]','1997',3,1,'selected_checkpoint_priority_work','full_text_accessed','1997 journal-typeset manifestation, pp. 325–333, recovered from Paperzz mirror','https://doi.org/10.1006/jnth.1997.2137','8f5719751f869d71907c9da75270cb8c012b54f1453f54179461dbc331d255a1','papers/PAPER-E008.md','papers/li_original_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-L001','corpus/bibliography.jsonl',673,'full_text_accessed','papers/PAPER-L001.md','{"id": "PAPER-L001", "title": "Li coefficients for automorphic L-functions", "authors": ["Jeffrey C. Lagarias"], "year": 2007, "date": null, "venue": "Annales de l’Institut Fourier 57(5), 1689–1740", "publication_status": "published", "doi": "10.5802/aif.2311", "arxiv": "math/0404394", "source_url": "https://aif.centre-mersenne.org/item/10.5802/aif.2311.pdf", "version": "published 2007 version; associated arXiv history not audited", "family": ["C", "E"], "audit_level": 0, "bibliographic_verified": true, "access_status": "full_text_accessed", "substantive_whole_work_read": false, "read_scope": "Initial inspection pp.1690–1692; independent supplementary reading now includes introductionpp.1689–1695, definitions/Theorem2.1pp.1696–1699, and fullSection6pp.1721–1726. Page1694 visually checked. Remaining article not read; overallLevel0/partial.", "source_sha256": "844a21e7e397d90ce8a12b31768ac088c1187e3a1a12efe54114fb6e008f19df", "source_file": "sources/li_campaign/lagarias-automorphic.pdf", "accessed_at": "2026-11-17", "mathematical_content_inspected": [{"claim": "For the reflected zeta zero set, derivative Li coefficients equal zero-sum Li coefficients after λ_n=λ_(-n); the derivative at s=1 functorially corresponds first to λ_(-n).", "evidence": "p.1690, equations (1.1)–(1.5)"}, {"claim": "The introduction attributes a general multiset Li criterion to Bombieri–Lagarias and states summability/omitted-point requirements.", "evidence": "p.1691, equations (1.6)–(1.8); original BL proof not audited here"}, {"claim": "Theorem1.1 under automorphicRH gives N nlogn/2+C1n+O(sqrt nlogn), and the introduction credits off-line exponential domination to BL1999Theorem1(c).", "evidence": "pp.1693–1694,equations(1.13),(1.18),andfollowingparagraph", "status": "Original stated theorem and context read; whole theorem proof not audited."}, {"claim": "The finalTheorem6.1 remainder can be obtained with horizontal height2sqrt n ratherthan sqrt n; this makes the product majorant geometric while moving the cutoff costsO(sqrt nlogn).", "evidence": "Source§6pp.1721–1726; independent reconstruction in audits/lagarias2007_contour_scope_round3.md", "status": "Supplied alternate proof, pending independent review."}], "limitations": ["No full technical audit of this paper.", "No correction-history search completed.", "No arithmetic automorphic theorem is inferred from the generic campaign construction."], "research_connection": "Generic finite positivity obstruction in proposals/independent_campaigns/li_advocate.md; a single zero contribution is sensitive to convention before reflection symmetry.", "correction_search_status": "not_completed", "additional_inspections": [{"reviewer": "li_skeptic", "date": "2026-11-17", "scope": "Introduction1689–1695; definitions/Theorem2.1 and some surrounding discussion1696–1699; complete§6,1721–1726. No whole-work reading.", "audit": "audits/lagarias2007_contour_scope_round3.md", "source_file": "sources/li_detection_priority_round3/lagarias2007.pdf", "source_sha256": "844a21e7e397d90ce8a12b31768ac088c1187e3a1a12efe54114fb6e008f19df", "classification": "Source priority/context and scoped alternate-contour reconstruction; independent review pending; no false-main-theorem or novelty claim."}], "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-L001.md", "track_file": "papers/li_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-L001"]}','Li coefficients for automorphic L-functions','["Jeffrey C. Lagarias"]','["C", "E"]','2007',0,0,'selected_checkpoint_priority_work','full_text_accessed','published 2007 version; associated arXiv history not audited','https://aif.centre-mersenne.org/item/10.5802/aif.2311.pdf','844a21e7e397d90ce8a12b31768ac088c1187e3a1a12efe54114fb6e008f19df','papers/PAPER-L001.md','papers/li_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-L002','corpus/bibliography.jsonl',674,'full_text_accessed','audits/adversarial_reviews/director_mellin_explicit_formula_round15.md','{"id": "PAPER-L002", "title": "Complements to Li’s Criterion for the Riemann Hypothesis", "authors": ["Enrico Bombieri", "Jeffrey C. Lagarias"], "date": "1999-08", "year": 1999, "venue": "Journal of Number Theory 77(2), 274–287", "publication_status": "published_work_author_manuscript_inspected", "doi": "10.1006/jnth.1999.2392", "arxiv": null, "source_url": "https://websites.umich.edu/~lagarias/doc/bombieri.pdf", "canonical_urls": ["https://doi.org/10.1006/jnth.1999.2392", "https://websites.umich.edu/~lagarias/doc/bombieri.pdf"], "version": "Michigan author-hosted 12-page manuscript, version date unverified", "family": ["C", "F"], "audit_level": 1, "read_scope": "Two independent readings of all 12 rendered author-manuscript pages, sections, footnotes and references. The separately paginated 14-page publisher version was bibliographically matched; its PDF bytes were unavailable.", "access_status": "full_text_accessed", "available_formats": ["PDF"], "whole_work_read": true, "inspected_portions_level": 2, "source_sha256": "cd13c8560f961c68e21256e5ba107bdd08fa7f34ce1e2cffbd4b63a16e8d48e0", "accessed_at": "2026-11-17", "main_result": "Theorem 1 (manuscript p.3) for a multiset R with 1 not in R and sum_rho (1+|Re rho|)/(1+|rho|)^2 finite: Re rho<=1/2 for every rho iff sum_rho Re[1-(1-1/rho)^(-n)]>=0 for every positive integer n; equivalently these real sums have subexponential lower bounds for every epsilon>0. Corollary 1 (pp.4–5), adding reflection and conjugation symmetry and excluding0,1, gives the familiar positive-power Li criterion for the critical line.", "proof_architecture": ["Half-plane implication from |1-1/rho|^(-1)<=1", "Off-half-plane extremal moduli attained finitely under summability", "Separate maximal-modulus roots from strictly smaller remainder", "Simultaneous Diophantine approximation makes extremal phase cosines approach their common maximum", "Reflection and conjugation convert half-plane to critical-line criterion and inverse powers to positive powers"], "limitations": ["Every-n quantifier essential; no finite-prefix implication is stated.", "Not a source-specific arithmetic theorem alone: the main criterion applies to general multisets.", "Arithmetic explicit-formula sections were not read in this independent track.", "No exhaustive subsequent-corrections search performed."], "research_questions": ["Which additional arithmetic structure could supply uniform tail control for finite Li-positivity certificates?", "Can finite-data robustness bounds be quantified in classes satisfying stronger growth and explicit-formula constraints?"], "reusable_lemma": "The inverse-power root formula is natural for derivatives at s=1; reflection symmetry is required before using the standard positive-power zero sum.", "correction_search_status": "publisher identity and author source verified; exhaustive correction search incomplete", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-L002.md", "track_file": "papers/li_skeptic_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-L002"], "scope_update_history": [{"fields": {"version": "Michigan author-hosted 12-page manuscript, version date unverified", "source_url": "https://websites.umich.edu/~lagarias/doc/bombieri.pdf", "source_path": "sources/uniform121_bombieri_lagarias/bombieri_lagarias_author.pdf", "source_sha256": "cd13c8560f961c68e21256e5ba107bdd08fa7f34ce1e2cffbd4b63a16e8d48e0", "pdf_pages": 12, "audit_level": 1, "whole_work_read": true, "substantive_reading": true, "independent_whole_reading_reviews": ["audits/adversarial_reviews/uniform121_bombieri_lagarias_whole_advocate.md", "audits/adversarial_reviews/weighted121_bombieri_lagarias_whole_skeptic.md"], "read_scope": "Two independent readings of all 12 rendered author-manuscript pages, sections, footnotes and references. The separately paginated 14-page publisher version was bibliographically matched; its PDF bytes were unavailable.", "audit_scope": "Scoped director adjudication of the author-manuscript pp. 5–6 explicit-formula test class and p. 8 finite equation (3.5). The smooth countermodel defeats the asserted raw height limit on the broad printed class. A positive finite correction restores (3.5); it vanishes in the main theorem''s limit.", "claim_verification_status": "Complete author-manuscript reading at Level 1. Scoped countermodel and finite-cutoff repair adjudicated; compact tests and the multiset criterion survive. The source assessment is pinned to this manuscript."}, "evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md", "track_file": "quality/zzzzzzzzzzz_round15_source_scope_updates.jsonl"}], "source_path": "sources/uniform121_bombieri_lagarias/bombieri_lagarias_author.pdf", "pdf_pages": 12, "substantive_reading": true, "independent_whole_reading_reviews": ["audits/adversarial_reviews/uniform121_bombieri_lagarias_whole_advocate.md", "audits/adversarial_reviews/weighted121_bombieri_lagarias_whole_skeptic.md"], "audit_scope": "Scoped director adjudication of the author-manuscript pp. 5–6 explicit-formula test class and p. 8 finite equation (3.5). The smooth countermodel defeats the asserted raw height limit on the broad printed class. A positive finite correction restores (3.5); it vanishes in the main theorem''s limit.", "claim_verification_status": "Complete author-manuscript reading at Level 1. Scoped countermodel and finite-cutoff repair adjudicated; compact tests and the multiset criterion survive. The source assessment is pinned to this manuscript.", "scope_update_evidence": "audits/adversarial_reviews/director_mellin_explicit_formula_round15.md", "additional_scope_update_files": ["quality/zzzzzzzzzzz_round15_source_scope_updates.jsonl"]}','Complements to Li’s Criterion for the Riemann Hypothesis','["Enrico Bombieri", "Jeffrey C. Lagarias"]','["C", "F"]','1999',1,1,'selected_checkpoint_priority_work','full_text_accessed','Michigan author-hosted 12-page manuscript, version date unverified','https://websites.umich.edu/~lagarias/doc/bombieri.pdf','cd13c8560f961c68e21256e5ba107bdd08fa7f34ce1e2cffbd4b63a16e8d48e0','papers/PAPER-L002.md','papers/li_skeptic_records.jsonl');
