INSERT INTO "papers" VALUES('PAPER-LRP001','corpus/bibliography.jsonl',677,'full_text_accessed','papers/PAPER-LRP001.md','{"id": "PAPER-LRP001", "title": "Convergence and the Riemann hypothesis", "authors": ["Jungseob Lee"], "date": "1996-03-01", "year": 1996, "venue": "Communications of the Korean Mathematical Society11(1)(1996),57–62", "publication_status": "published_journal_article", "doi": null, "arxiv": null, "canonical_url": "https://ckms.kms.or.kr/journal/view.html?uid=1217", "source_url": "https://ckms.kms.or.kr/journal/download_pdf.php?spage=57&volume=11&number=1", "other_identifiers": {"candidate": "CAND-41E4476772DA", "openalex": "W813808457", "koreascience_old": "DBSHCJ_1996_v11n1_57", "koreascience_current": "JAKO199611919487598"}, "version": "Official publisher scan, six printed pages57–62; received1995-09-13, revised1995-09-26; publisher printing date1996-03-01", "source_file": "sources/logarithmic_riesz_priority_skeptic_round4/lee1996.pdf", "source_sha256": "debbc5132b4338e06b8f2d81cb20ab8c47051e1d4e0cda15af713077c9ef4099", "metadata_provenance": ["sources/logarithmic_riesz_priority_skeptic_round4/lee1996_publisher.html", "sources/logarithmic_riesz_priority_skeptic_round4/lee1996_retrieval.json"], "family": ["A", "C"], "audit_level": 1, "whole_work_read": true, "inspected_portions_level": 1, "read_scope": "Complete six-page primary text read; main theoremp59 and central proofpp60–61 visually checked. No full technical verification; p61 scan partly streaked but displayed mathematical passages readable.", "access_status": "full_text_accessed", "main_result": "For fixed1<p<=2, zero-free Re(s)>1/p iff the prescribed unsmoothed fractional-part sums sum_(n<=N)mu(n){1/(nx)} converge to−1 in every fixedL^r(0,1),1<r<p; equivalent density statements for constrained real/rational Beurling generators. Main unnumbered theoremp59; constrained correction Eq2p60.", "limitations": ["Endpoint r=p is excluded; no L²-boundary convergence is claimed at p2.", "No moving logarithmic Riesz weights or shifted n^−epsilon array appears.", "Printed infinite Perron absolute-majorant integralp59 diverges as written; no L2 audit or false-main-theorem claim is made.", "No DOI supplied in inspected publisher metadata; absence is not a proof no DOI exists.", "Priority of the archive moving-array construction remains unassessed."], "record_file": "papers/PAPER-LRP001.md", "accessed_at": "2026-11-17", "original_access_status": "full_primary_publisher_pdf_accessed_and_substantively_read", "record_path": "papers/PAPER-LRP001.md", "track_file": "papers/logarithmic_riesz_priority_skeptic_round4_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LRP001"]}','Convergence and the Riemann hypothesis','["Jungseob Lee"]','["A", "C"]','1996',1,1,'selected_checkpoint_priority_work','full_text_accessed','Official publisher scan, six printed pages57–62; received1995-09-13, revised1995-09-26; publisher printing date1996-03-01','https://ckms.kms.or.kr/journal/download_pdf.php?spage=57&volume=11&number=1','debbc5132b4338e06b8f2d81cb20ab8c47051e1d4e0cda15af713077c9ef4099','papers/PAPER-LRP001.md','papers/logarithmic_riesz_priority_skeptic_round4_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-LRP002','corpus/bibliography.jsonl',678,'full_text_accessed','papers/PAPER-LRP002.md','{"id": "PAPER-LRP002", "title": "Riesz summability on boundary lines of holomorphic functions of finite order generated by Dirichlet series", "authors": ["Andreas Defant", "Ingo Schoolmann"], "date": "2023-03-22", "year": 2023, "venue": "Mathematische Zeitschrift303(4)(2023),article102", "doi": "10.1007/s00209-023-03235-4", "arxiv": "2107.10145", "canonical_url": "https://doi.org/10.1007/s00209-023-03235-4", "source_url": "https://arxiv.org/pdf/2107.10145v3", "version": "Actual text read arXivv3,2022-03-22; journal metadata verified but mathematical journal version not compared", "audit_level": 0, "whole_work_read": false, "inspected_portions_level": 1, "read_scope": "Definitions pp2–3; selected introduction/classical comparisons pp6–10; exact Perron formula/kernel and boundary theorem pp15–18, including Theorems1.2,4.1,5.1. Not whole38-page manuscript or complete proof audit.", "source_file": "sources/logarithmic_riesz_priority_skeptic_round4/defant_schoolmann2107.pdf", "source_sha256": "28a42a54c4697a9655347a3717d21d8bfeb2b48e35abf644ea93d486c08e38c1", "main_result_in_inspected_scope": "Fixed k>ell boundary Riesz convergence for general-frequency germs with uniform sup_(Re>0)|f/(1+s)^ell| finite; exact gamma/Perron kernel. Classical finite-boundary-pole theorem recalled separately.", "limitations": ["Reciprocal zeta shifted to the critical boundary fails the uniform growth hypothesis near every boundary zero.", "The fixed-order theorem and recalled finitely-many-pole theorem are not claimed to imply the moving-array weighted product norm.", "No publication novelty conclusion; original Riesz1909 not read."], "family": ["A", "C", "H"], "access_status": "full_text_accessed", "accessed_at": "2026-11-17", "audit_file": "audits/growing_logarithmic_riesz_priority_skeptic_round4.md", "selection_scope": "supporting_priority_comparison_source", "record_f