INSERT INTO "papers" VALUES('PAPER-LRP003','corpus/bibliography.jsonl',679,'full_text_accessed','papers/PAPER-LRP003.md','{"id": "PAPER-LRP003", "title": "On Divergence of Fourier Series by Some Methods of Summability", "authors": ["Shakro Tetunashvili"], "date": "2012", "year": 2012, "venue": "Journal of Function Spaces and Applications2012,article542607,9pages", "doi": "10.1155/2012/542607", "arxiv": null, "canonical_url": "https://doi.org/10.1155/2012/542607", "source_url": "https://ftp.rmi.ge/geo/open_science/annex4_docs_geo/Tetunashvili-422.pdf", "version": "Actual primary typeset article; downloaded file has nine article pages and one unrelated advertisement page", "audit_level": 0, "whole_work_read": false, "inspected_portions_level": 1, "read_scope": "Introduction/triangular-matrix definitions; Theorems1.3–1.4 and proof excerpts pp5–7; Remark2.4 pp8–9. Not full proof audit.", "source_file": "sources/logarithmic_riesz_priority_skeptic_round4/tetunashvili2012.pdf", "source_sha256": "d8667386b0e4f97272acbde490ba12f839732d5e00c994b9aea0c43968c1e033", "main_result_in_inspected_scope": "Variable arithmetic Riesz orders are explicitly defined in Remark2.4. The compared divergence statements have alpha_n<=C/log n with C<log2, hence vanishing order.", "limitations": ["Arithmetic frequency and vanishing order differ from the growing logarithmic order of the investigated array.", "Fourier divergence examples do not provide a Mobius weighted boundary-norm criterion."], "family": ["A", "C", "H"], "access_status": "full_text_accessed", "accessed_at": "2026-11-17", "audit_file": "audits/growing_logarithmic_riesz_priority_skeptic_round4.md", "selection_scope": "supporting_priority_comparison_source", "record_file": "papers/PAPER-LRP003.md", "original_access_status": "full_primary_text_accessed_targeted_portions_read", "record_path": "papers/PAPER-LRP003.md", "track_file": "papers/logarithmic_riesz_priority_skeptic_round4_records.jsonl", "original_selection_status": null, "s