INSERT INTO "papers" VALUES('PAPER-LRP004','corpus/bibliography.jsonl',680,'full_text_accessed','papers/PAPER-LRP004.md','{"id": "PAPER-LRP004", "title": "On the Wintner-Ingham-Segal summability method", "authors": ["Shigeru Kanemitsu", "Takako Kuzumaki", "Yoshio Tanigawa"], "date": "2019-01-23", "year": 2019, "volume_year": 2018, "venue": "Hardy–Ramanujan Journal41(2018),40–47", "doi": "10.46298/hrj.2019.5104", "arxiv": null, "canonical_url": "https://doi.org/10.46298/hrj.2019.5104", "source_url": "https://hrj.episciences.org/5104/pdf", "version": "Actual eight-page journal text; printed volume year2018, Crossref online date2019-01-23", "audit_level": 0, "whole_work_read": false, "inspected_portions_level": 1, "read_scope": "Initial definitions and assumptions pp40–41; Proposition3.2, smoothing identities3.18–3.19, Theorem3.4 and references pp43–47. Intermediate proof estimates not fully audited.", "source_file": "sources/logarithmic_riesz_priority_skeptic_round4/wintner_ingham_segal2018.pdf", "source_sha256": "9afa53802cc1a37af54a8e7eada857cf01a47b22b8ac824ddd298f0004469444", "main_result_in_inspected_scope": "Ingham arithmetic convolution summability implies fixed F(k/r)-smoothing under the stated shape and PNT-decay assumptions; supplies references to Wintner and Segal originals.", "limitations": ["Fixed arithmetic smoothing does not directly cover an N-dependent logarithmic Riesz order and weighted critical product norm.", "Wintner1957 and Segal1975/1977 originals were not read in this investigation.", "Volume year and online metadata date distinguished."], "family": ["A", "C", "H"], "access_status": "full_text_accessed", "accessed_at": "2026-11-17", "audit_file": "audits/growing_logarithmic_riesz_priority_skeptic_round4.md", "selection_scope": "supporting_priority_comparison_source", "record_file": "papers/PAPER-LRP004.md", "original_access_status": "full_primary_text_accessed_targeted_portions_read", "record_path": "papers/PAPER-LRP004.md", "track_file": "papers/logarithmic_riesz_priority_skeptic_round4_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LRP004"]}','On the Wintner-Ingham-Segal summability method','["Shigeru Kanemitsu", "Takako Kuzumaki", "Yoshio Tanigawa"]','["A", "C", "H"]','2019',0,0,'selected_checkpoint_priority_work','full_text_accessed','Actual eight-page journal text; printed volume year2018, Crossref online date2019-01-23','https://hrj.episciences.org/5104/pdf','9afa53802cc1a37af54a8e7eada857cf01a47b22b8ac824ddd298f0004469444','papers/PAPER-LRP004.md','papers/logarithmic_riesz_priority_skeptic_round4_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-LRP005','corpus/bibliography.jsonl',681,'full_text_accessed','papers/PAPER-LRP005.md','{"id": "PAPER-LRP005", "title": "Arithmetical Aspects of Beurling’s Real Variable Reformulation of the Riemann Hypothesis", "authors": ["Luis Báez-Duarte"], "date": "2000-11-29", "year": 2000, "venue": "arXiv:math/0011254v1", "doi": null, "arxiv": "math/0011254", "canonical_url": "https://arxiv.org/abs/math/0011254", "source_url": "https://arxiv.org/pdf/math/0011254v1", "version": "Actual v1 posted2000-11-29; internal manuscript date2000-10-20. Related published text New versions of the Nyman-Beurling criterion,IJMMS31(7)(2002),387–406,DOI10.1155/S0161171202013248 has matching inspected introductory objects/results; full journal revision not compared. Do not count that related title as an independently read second work.", "related_publication": {"title": "New versions of the Nyman-Beurling criterion for the Riemann hypothesis", "doi": "10.1155/S0161171202013248", "comparison_status": "matching primary-text preview introduction and main-result descriptions; publisher PDF not recovered and full version comparison not done"}, "audit_level": 0, "whole_work_read": false, "inspected_portions_level": 1, "read_scope": "Preprint introduction/definitions pp1–5, relevant divergence statements and proofs pp17–20, references. Not full21-page paper. Published-text preview pp387–390 inspected only.", "source_file": "sources/logarithmic_riesz_priority_skeptic_round4/baez_arithmetical2000.pdf", "source_sha256": "951ecc56eaae5b80eb8128ab4f98b5184d06ed97da608a130d65940daea8e94c", "main_result_in_inspected_scope": "Propositions4.4 and4.7: natural unsmoothed approximants and fixed-coefficient series in the constrained natural generators cannot converge in the endpoint norm when a zero lies on Re(s)=1/p; the critical L2 case occurs. Precise several approximation sequences defined in Eqs1.14–1.19.", "limitations": ["The archive moving taper has N-dependent coefficients and is not a frozen-coefficient series; no contradiction with the cited barrier.", "No exact moving order was found in inspected passages, which is not a whole-literature absence claim.", "Journal mathematical version only partially compared through degraded text preview."], "family": ["A", "C", "H"], "access_status": "full_text_accessed", "accessed_at": "2026-11-17", "audit_file": "audits/growing_logarithmic_riesz_priority_skeptic_round4.md", "selection_scope": "supporting_priority_comparison_source", "record_file": "papers/PAPER-LRP005.md", "original_access_status": "full_primary_text_accessed_targeted_portions_read", "record_path": "papers/PAPER-LRP005.md", "track_file": "papers/logarithmic_riesz_priority_skeptic_round4_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LRP005"]}','Arithmetical Aspects of Beurling’s Real Variable Reformulation of the Riemann Hypothesis','["Luis Báez-Duarte"]','["A", "C", "H"]','2000',0,0,'selected_checkpoint_priority_work','full_text_accessed','Actual v1 posted2000-11-29; internal manuscript date2000-10-20. Related published text New versions of the Nyman-Beurling criterion,IJMMS31(7)(2002),387–406,DOI10.1155/S0161171202013248 has matching inspected introductory objects/results; full journal revision not compared. Do not count that related title as an independently read second work.','https://arxiv.org/pdf/math/0011254v1','951ecc56eaae5b80eb8128ab4f98b5184d06ed97da608a130d65940daea8e94c','papers/PAPER-LRP005.md','papers/logarithmic_riesz_priority_skeptic_round4_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-M002','corpus/bibliography.jsonl',682,'full_text_accessed','papers/PAPER-M002.md','{"id": "PAPER-M002", "title": "The General Theory of Dirichlet’s Series", "authors": ["G. H. Hardy", "Marcel Riesz"], "year": 1915, "date": "1915", "venue": "Cambridge University Press; Cambridge Tracts in Mathematics and Mathematical Physics18, viii+78pp", "publication_status": "published_monograph", "doi": null, "arxiv": null, "source_url": "https://archive.org/details/cu31924060184441", "canonical_url": "https://archive.org/details/cu31924060184441", "version": "1915 text in Cornell1991 preservation facsimile; title and series pages visually verified; not the2015 reissue", "family": ["A", "C", "H"], "audit_level": 0, "whole_work_read": false, "inspected_portions_level": 1, "read_scope": "Title/series pages; printedpp21–23 definitions/naming of typical means; pp49–51 Theorem38 proof,Theorem39/Lemma10 and shifted formula,Theorem40 statement. Not whole book or full dependency audit.", "access_status": "full_text_accessed", "available_formats": ["scanned_pdf", "ocr_text"], "source_file": "sources/logarithmic_riesz_round3/cu31924060184441.pdf", "source_sha256": "506e09782db969bbe3e2724f3a528df9b59a8bec9437141761ec9612e177cfad", "main_result": "For positive real orderκ, first-kind means at frequenciesλ_n=logn are logarithmic; Theorem39 pp50–51 gives their inverse-Laplace/Perron kernel s^(-κ-1)/Γ(κ+1) normalization. Second-kind means use Gamma quotients,Theorem40p51.", "limitations": ["Targeted passages only; earlier summability dependencies not fully audited.", "Used only in absolutely convergent initial-line specialization.", "Private facsimile not bundled as third-party source."], "audit_file": "papers/PAPER-M002.md", "accessed_at": "2026-11-17", "original_access_status": "full_scanned_primary_text_accessed_targeted_passages_read", "record_path": "papers/PAPER-M002.md", "track_file": "papers/logarithmic_riesz_round3_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-M002"]}','The General Theory of Dirichlet’s Series','["G. H. Hardy", "Marcel Riesz"]','["A", "C", "H"]','1915',0,0,'selected_checkpoint_priority_work','full_text_accessed','1915 text in Cornell1991 preservation facsimile; title and series pages visually verified; not the2015 reissue','https://archive.org/details/cu31924060184441','506e09782db969bbe3e2724f3a528df9b59a8bec9437141761ec9612e177cfad','papers/PAPER-M002.md','papers/logarithmic_riesz_round3_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-E011','corpus/bibliography.jsonl',683,'full_text_accessed','papers/PAPER-E011.md','{"id": "PAPER-E011", "title": "Relations among some conjectures on the Möbius function and the Riemann zeta-function", "authors": ["Shōta Inoue"], "year": 2019, "date": "2019-08-12", "venue": "Acta Arithmetica191(1)(2019),1–32", "publication_status": "published_journal_article_with_accessed_preprint", "doi": "10.4064/aa170622-16-10", "arxiv": "1705.00853", "source_url": "https://arxiv.org/pdf/1705.00853v2", "canonical_url": "https://doi.org/10.4064/aa170622-16-10", "version": "Actual mathematical text read arXiv1705.00853v2,2017-06-22; journal metadata verified, journal mathematical version not compared", "family": ["A", "B", "C"], "audit_level": 0, "whole_work_read": false, "inspected_portions_level": 1, "read_scope": "Preprint introductionpp1–3,Theorem1p3,Lemma6 and proofpp13–14; selected Mellin formulas. Not full explicit-formula or variable-order audit.", "access_status": "full_text_accessed", "available_formats": ["pdf", "extracted_text"], "source_file": "sources/logarithmic_riesz_round3/inoue1705.pdf", "source_sha256": "0cdbc0b10e26922337c892a46a2f096df52b9d179dfecb8b9356d47c0ab11a98", "metadata_provenance": ["sources/logarithmic_riesz_round3/inoue_crossref.json", "sources/logarithmic_riesz_round3/inoue_publisher.html"], "main_result": "Thm1p3: underRH, if a fixedτ>0 arithmetic Riesz mean Mτ=Γ(τ+1)^(-1)Σμ(n)(1−n/x)^τ is o(√x(logx)^β), then every nontrivial zero multiplicitym<β+1. Lemma6pp13–14 gives Ω±(√x(logx)^(m−1)) underRH.", "limitations": ["Only preprint passages read; published text/version changes not checked.", "Arithmetic and logarithmic Riesz orders differ; kernels may not be identified.", "External RH-growth and Montgomery–Vaughan argument ancestry not fully audited."], "audit_file": "papers/PAPER-E011.md", "accessed_at": "2026-11-17", "original_access_status": "full_primary_preprint_accessed_targeted_passages_read", "record_path": "papers/PAPER-E011.md", "track_file": "papers/logarithmic_riesz_round3_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-E011"]}','Relations among some conjectures on the Möbius function and the Riemann zeta-function','["Shōta Inoue"]','["A", "B", "C"]','2019',0,0,'selected_checkpoint_priority_work','full_text_accessed','Actual mathematical text read arXiv1705.00853v2,2017-06-22; journal metadata verified, journal mathematical version not compared','https://arxiv.org/pdf/1705.00853v2','0cdbc0b10e26922337c892a46a2f096df52b9d179dfecb8b9356d47c0ab11a98','papers/PAPER-E011.md','papers/logarithmic_riesz_round3_records.jsonl');
