INSERT INTO "papers" VALUES('PAPER-NOOR-A001','corpus/bibliography.jsonl',686,'full_text_accessed','papers/PAPER-NOOR-A001.md','{"id": "PAPER-NOOR-A001", "candidate_id": "CAND-C088E85F2FA8", "title": "A Hardy space analysis of the Báez-Duarte criterion for the RH", "authors": ["S. Waleed Noor"], "year": 2019, "date": "2019-07", "venue": "Advances in Mathematics 350 (2019), 242–255", "publication_status": "published_journal_article", "doi": "10.1016/j.aim.2019.04.064", "arxiv": "1809.09577v4", "canonical_url": "https://doi.org/10.1016/j.aim.2019.04.064", "source_url": "https://arxiv.org/pdf/1809.09577v4", "version": "arXiv v4, 9 May 2019, 11 pages; journal identity verified via Crossref, journal text inaccessible", "version_history": "Inspected v4 only; complete version/correction search not performed", "family": ["C", "D", "F"], "selected": true, "audit_level": 1, "whole_work_read": true, "read_scope": "Complete 11-page primary preprint including all sections, proofs, and references substantively read. Targeted independent reconstruction of unitary T, preimages, coefficient identity, semigroup invariance, and Lemma11 elementary convergence; external local-Dirichlet and sequence-criterion ancestry not fully audited.", "inspected_portions_level": 2, "access_status": "full_text_accessed", "available_formats": ["pdf", "extracted_text"], "source_file": "sources/noor_advocate_round4/noor2019_advocate.pdf", "source_sha256": "ce82e3353c0dcd5e43a935b1ac34b87a9f9057c3646b2538fb1f747f526b6c99", "metadata_evidence": "sources/noor_advocate_round4/noor_advocate_crossref_round4.json", "main_result": "Theorem6 RH iff 1 lies in H²-closure of span h_k=(1-z)^(-1)log[(1+...+z^(k-1))/k]; Theorem8 equivalent full H² density/cyclicity. Theorem9 unconditional density of (1-z)span h_k in H²; Theorem10 compact-open density only; Theorem12 restricted orthogonality Nperp intersection localDirichlet_at1={0}.", "dependency_objective": "Exact original source for the Hardy-space map T:H²→A≈D−2 and its closure/domain distinctions; assess critical weighted-Dirichlet repair separately.", "limitations": ["Not a whole-paper Level2 audit.", "Publisher version not read or compared.", "No graph-core or bounded inverse for T1:D−1→D−3 follows from this source.", "New Bergman density reconstruction is separate, not attributed to Noor and no novelty claim."], "audit_file": "audits/adversarial_reviews/noor_source_and_unitary_advocate_round4.md", "research_followup": "proposals/independent_campaigns/noor_critical_bergman_advocate_round4.md", "accessed_at": "2026-11-17", "research_followup_reviews": ["audits/adversarial_reviews/noor_critical_bergman_skeptic_round4.md"], "original_access_status": "full_primary_preprint_accessed_journal_pdf_blocked", "record_path": "papers/PAPER-NOOR-A001.md", "track_file": "papers/noor_advocate_round4_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-NOOR-A001"]}','A Hardy space analysis of the Báez-Duarte criterion for the RH','["S. Waleed Noor"]','["C", "D", "F"]','2019',1,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv v4, 9 May 2019, 11 pages; journal identity verified via Crossref, journal text inaccessible','https://arxiv.org/pdf/1809.09577v4','ce82e3353c0dcd5e43a935b1ac34b87a9f9057c3646b2538fb1f747f526b6c99','papers/PAPER-NOOR-A001.md','papers/noor_advocate_round4_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEOMETRY102-PETROV2026','corpus/bibliography.jsonl',687,'full_text_accessed','papers/PAPER-GEOMETRY102-PETROV2026.md','{"paper_id": "PAPER-GEOMETRY102-PETROV2026", "title": "A Borodin-Okounkov-Geronimo-Case identity for tilted Toeplitz minors", "authors": ["Petrov, Leonid"], "year": 2026, "venue": "arXiv (math.FA)", "publication_status": "Verified preprint manifestation; no journal manifestation established in this check", "doi": "10.48550/arXiv.2605.24976", "arxiv_id": "2605.24976", "version": "arXiv:2605.24976v1, 24 May 2026", "canonical_url": "https://arxiv.org/abs/2605.24976", "source_url": "https://arxiv.org/pdf/2605.24976v1", "source_path": "sources/round13_petrov/2605.24976v1.pdf", "source_sha256": "f8b1c3386d49e61e767ae969a02131b509a42af276151ff04492b8be75a79214", "pdf_pages": 34, "access_status": "full_text_accessed", "full_text_accessed": true, "accessed_at": "2026-11-18", "bibliographic_verified": true, "audit_level": 0, "whole_work_read": false, "substantive_reading": false, "selection_status": "selected_checkpoint_priority_work", "area": "Random matrices and Toeplitz determinants", "source_locator": "PDF pp. 1–3 (§§1.1–1.3); p. 8 (2.6); pp. 9–11 (3.3)–(3.8), Theorem 3.1; pp. 13–16 (4.2)–(4.11), Theorem 4.4, Propositions 4.6–4.7; supplementary spot checks of §5 and Appendix A", "read_scope": "Scoped comparison of the Hardy-space splitting, Gram-invertibility and graph-chart hypotheses, their determinant identities, and applicability of the analytic polynomial row and column tilts. Not a complete reading.", "main_result": "A tilted Toeplitz minor factors into a Szegő factor, a finite Gram determinant, and a Fredholm determinant on an oblique complementary space. Under additional graph-chart invertibility a canonical-tail form is available, with a bounded-rank kernel correction for bounded-degree polynomial tilts.", "result_status": "Source statements and role in proposed proof dependency checked in cited passages. No whole-work audit, novelty conclusion, or arithmetic transfer.", "selection_reason": "The exact general tilted identity applies to the finite circular Jacobi numerator for the derivative-rooted CUE statistic. This is a direct alternate proof interface and supports the exact Gram versus complementary-series comparison.", "transfer_hypothesis": "At fixed N the symbol is the nonvanishing exponential of a finite Laurent polynomial, and the row and column polynomial tilts have degree J. The Gram is invertible near zero and on the real Laplace axis by the matched adjoint structure. The optional fixed-tail graph chart has a separate invertibility condition.", "record_path": "papers/PAPER-GEOMETRY102-PETROV2026.md", "scope_note": "audits/adversarial_reviews/geometry102_petrov_source_decision.md", "novelty_claim": false, "id": "PAPER-GEOMETRY102-PETROV2026", "selected": true, "selection_review": "audits/adversarial_reviews/analytic104_petrov_release_qa.md", "admission_receipt": "quality/round13_petrov_admission_receipt.json", "arxiv": "2605.24976", "original_access_status": "full_text_accessed", "track_file": "papers/petrov_round13_records.jsonl", "original_selection_status": "selected_proof_dependency", "source_record_ids": ["PAPER-GEOMETRY102-PETROV2026"]}','A Borodin-Okounkov-Geronimo-Case identity for tilted Toeplitz minors','["Petrov, Leonid"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2605.24976v1, 24 May 2026','https://arxiv.org/pdf/2605.24976v1','f8b1c3386d49e61e767ae969a02131b509a42af276151ff04492b8be75a79214','papers/PAPER-GEOMETRY102-PETROV2026.md','papers/petrov_round13_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-BESSEL-S01','corpus/bibliography.jsonl',688,'full_text_accessed','papers/PAPER-BESSEL-S01.md','{"id": "PAPER-BESSEL-S01", "title": "On the ν-zeros of the modified Bessel function K_{iν}(x) of positive argument", "authors": ["R. B. Paris"], "date": "2022-04-07", "year": 2022, "venue": "arXiv preprint", "publication_status": "preprint_version_inspected; later publication not verified", "doi": null, "arxiv": "2108.01447", "source_url": "https://arxiv.org/abs/2108.01447v2", "version": "v2, 7 April 2022", "family": ["B", "D", "F", "H"], "audit_level": 1, "whole_work_read": true, "inspected_portions_level": 2, "read_scope": "Complete 6-page PDF, including appendix and references. Independently reconstructed fixed-argument zero counting through the linear term using I-series and gamma phase; higher expansion coefficients and numerical table not independently recomputed.", "access_status": "full_text_accessed", "source_file": "sources/positive_kernel_bessel_skeptic_round3/paris2021.pdf", "main_result": "Theorem 1, page 4, equation (3.5): for fixed x>0, ν_n has an asymptotic expansion beginning m/W(2m/(e x)), m=(n+3/4)π, followed by explicit inverse-m corrections. Equation (1.1) supplies the even Fourier integral; equations (2.1)–(2.4) reconstruct the large-order phase.", "limitations": ["Fixed positive argument x; no uniformity in growing x independently established.", "Countably many real order zeros cited from earlier source; all-complex-zero exclusion independently reconstructed in audit.", "Higher saddle coefficients, subdominant saddles and numerical table read but not deeply audited."], "research_questions": ["Use this classical kernel as a rigorous negative control for Li-prefix and smooth-kernel sufficient conditions.", "Track the arithmetic conditions absent from an otherwise RVM-compatible zero count."], "correction_search_status": "v2 actual source inspected; exhaustive forward-citation/correction search incomplete", "accessed_at": "2026-11-17", "source_sha256": "90aaa5403af1ea6f55759062e161556135658e35c88c58212b4308d2bf952fba", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-BESSEL-S01.md", "track_file": "papers/positive_kernel_bessel_skeptic_round3_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-BESSEL-S01"]}','On the ν-zeros of the modified Bessel function K_{iν}(x) of positive argument','["R. B. Paris"]','["B", "D", "F", "H"]','2022',1,1,'selected_checkpoint_priority_work','full_text_accessed','v2, 7 April 2022','https://arxiv.org/abs/2108.01447v2','90aaa5403af1ea6f55759062e161556135658e35c88c58212b4308d2bf952fba','papers/PAPER-BESSEL-S01.md','papers/positive_kernel_bessel_skeptic_round3_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-BESSEL-S03','corpus/bibliography.jsonl',689,'full_text_accessed','papers/PAPER-BESSEL-S03.md','{"id": "PAPER-BESSEL-S03", "title": "Bemerkung über die Integraldarstellung der Riemannschen ξ-Funktion", "authors": ["G. Pólya"], "date": "1926", "year": 1926, "venue": "Acta Mathematica 48(3–4) (1926), 305–317", "publication_status": "published original article scan", "doi": "10.1007/BF02565336", "arxiv": null, "source_url": "https://doi.org/10.1007/BF02565336", "fulltext_url": "https://archive.ymsc.tsinghua.edu.cn/pacm_download/117/5376-11511_2007_Article_BF02565336.pdf", "version": "Original 1926 article; first and last signatures printed March1926; no exact issue date inferred", "family": ["B", "D", "F", "G", "H"], "audit_level": 1, "whole_work_read": true, "inspected_portions_level": 2, "read_scope": "Complete 13-page primary PDF text read; pages306 and315 visually rendered to verify exact integral definition, all-simple-imaginary conclusion and O(1) counting formula. Independent spectral/phase reconstruction of central Bessel result; not every constant in original gamma-series and rectangle argument independently recomputed.", "access_status": "full_text_accessed", "source_file": "sources/positive_kernel_bessel_skeptic_round3/polya1926_acta.pdf", "source_sha256": "a338ba3c2d585dd6896784c85076fceb6d5710cac50642e661618fc11e651f24", "accessed_at": "2026-11-17", "main_result": "Equation(7), p306: G(z;a)=∫R exp[−a(e^u+e^(−u))+zu]du, a>0, i.e. 2K_z(2a). Sections1–3 prove every zero simple and purely imaginary. Page315 gives positive-ordinate count y/pi log(y/a)−y/pi+O(1). Therefore K_{w/2}(2π) already has the RVM smooth main through its linear term with O(1) error by the exact substitution z=w/2,a=π. Equation(6), p306 defines the classical symmetrized fake xi function, and pp316–317 prove its real-zero property using HilfssatzII.", "proof_architecture": ["Integration by parts gives difference equation(9), p307.", "Gamma expansion(11), pp307–308 yields asymptotic control and initial small-a zero confinement in Section2.", "Zero exclusion on Re(z)=±1 follows from the recurrence, conjugation and impossible indefinitely shifted zeros, Section3 IV.", "Parameter continuation in a excludes outside-strip zeros, Section3 V.", "Argument-principle rectangles and phase control force no nonimaginary zeros and no excess multiplicity, Section3 VI, pp313–315.", "HilfssatzI, pp315–316: a first nonzero odd derivative at zero produces an eventual fixed-sign algebraic cosine-transform tail; naive nonsymmetric finite xi-kernel truncations consequently have only finitely many real zeros.", "HilfssatzII, pp316–317: symmetric imaginary shifts preserve real zeros for real entire genus0/1 functions with all zeros real and at least one zero; this gives real zeros for the symmetrized fake xi."], "limitations": ["The source does not prove RH or identify individual zeta zeros.", "Our quartet perturbation/strict-log-concavity/Li-prefix assembly is not identified in this source; its priority remains unassessed.", "The odd-derivative obstruction needs real analyticity at the origin and appropriate derivative decay; do not generalize to arbitrary smooth kernels.", "Original formulas were read but the entire original 1926 technical proof is not claimed independently verified."], "research_questions": ["Which arithmetic constraints distinguish the true xi kernel from classical RVM-compatible fake xi kernels?", "Use exact symmetric countermodels to test finite certificates while retaining all needed normalization factors.", "Trace prior polynomial perturbations and shape constraints before making novelty claims."], "correction_search_status": "Original source and Crossref identity inspected; exhaustive correction/forward-citation search incomplete", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-BESSEL-S03.md", "track_file": "papers/positive_kernel_bessel_skeptic_round3_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-BESSEL-S03"]}','Bemerkung über die Integraldarstellung der Riemannschen ξ-Funktion','["G. Pólya"]','["B", "D", "F", "G", "H"]','1926',1,1,'selected_checkpoint_priority_work','full_text_accessed','Original 1926 article; first and last signatures printed March1926; no exact issue date inferred','https://doi.org/10.1007/BF02565336','a338ba3c2d585dd6896784c85076fceb6d5710cac50642e661618fc11e651f24','papers/PAPER-BESSEL-S03.md','papers/positive_kernel_bessel_skeptic_round3_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-POS64-OPPROB-001','corpus/bibliography.jsonl',690,'full_text_accessed','papers/positivity64_operator_probability_notes.md','{"id": "PAPER-POS64-OPPROB-001", "title": "A complete Riemann zeta distribution and the Riemann hypothesis", "authors": ["Takashi Nakamura"], "year": 2015, "venue": "Bernoulli 21(1), 604–617", "doi": "10.3150/13-BEJ581", "arxiv": "1504.03438", "version": "v1", "publication_status": "journal work", "canonical_url": "https://doi.org/10.3150/13-BEJ581", "source_url": "https://arxiv.org/pdf/1504.03438v1", "source_sha256": "f9a2e290751b83286e325f7c3e319b2553f74afc1c39dec9c5076e270c6b68bc", "pages": 15, "access_date": "2026-11-18", "bibliographic_verified": true, "full_text_accessed": true, "access_status": "full_text_accessed", "selected": true, "selection_status": "selected_checkpoint_priority_work", "audit_level": 0, "whole_work_read": false, "substantive_reading": false, "read_scope": "Verified primary PDF title, version, and abstract or opening statement for targeted relevance.", "topic": "probability", "source_summary": "The completed ξ ratio is an ordinary characteristic function on a broad range. A more restrictive signed-measure representation for every σ in (1/2,1) yields a distinct RH criterion.", "main_results": [], "record_path": "papers/positivity64_operator_probability_notes.md", "original_access_status": "full_text_accessed", "track_file": "papers/positivity64_operator_probability_records.jsonl", "original_selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-POS64-OPPROB-001"]}','A complete Riemann zeta distribution and the Riemann hypothesis','["Takashi Nakamura"]',NULL,'2015',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/1504.03438v1','f9a2e290751b83286e325f7c3e319b2553f74afc1c39dec9c5076e270c6b68bc','papers/positivity64_operator_probability_notes.md','papers/positivity64_operator_probability_records.jsonl');
