INSERT INTO "papers" VALUES('PAPER-POS64-OPPROB-016','corpus/bibliography.jsonl',705,'full_text_accessed','audits/adversarial_reviews/director_central_drift_round10.md','{"id": "PAPER-POS64-OPPROB-016", "title": "A probabilistic interpretation for central zeros of L-functions in the Selberg class", "authors": ["Takashi Nakamura", "Masatoshi Suzuki"], "year": 2023, "venue": null, "doi": null, "arxiv": "2307.02027", "version": "v1", "publication_status": "arXiv preprint accessed; journal status unverified", "canonical_url": "https://arxiv.org/abs/2307.02027", "source_url": "https://arxiv.org/pdf/2307.02027v1", "source_sha256": "d833f2af1f426c36f72cfb43df6b67bb3b3bf50ac9324c5069bc7442768a72d9", "pages": 6, "access_date": "2026-11-18", "bibliographic_verified": true, "full_text_accessed": true, "access_status": "full_text_accessed", "selected": true, "selection_status": "selected_checkpoint_priority_work", "audit_level": 1, "whole_work_read": true, "substantive_reading": true, "read_scope": "Allsixv1pages read; sourcePDF/TeX, centralfactor/drift, fulltransform, actualSelbergexamples and primary degree1classification compared. Scoped regular-part and vertical-family results adjudicated.", "topic": "probability", "source_summary": "Proposes a Selberg-class infinite-divisibility criterion with central-zero multiplicity represented by Gaussian variance. The printed drift requires regularization at a central zero.", "main_results": [{"locator": "Entire arXiv v1, pp. 1–6, §§1–3, Theorems 2.1–2.2 and eqs. (2.7)–(2.13)", "statement": "The authors state a Selberg-class GRH equivalence with real-line infinite divisibility. Central multiplicity m0 contributes Gaussian variance and noncentral real ordinates contribute mγ/γ² atomic jumps. As printed, the drift definition is undefined for a central zero. See notes for the regular part indicated by the displayed Hadamard form.", "status": "source statement"}], "record_path": "papers/positivity64_operator_probability_notes.md", "original_access_status": "full_text_accessed", "track_file": "papers/positivity64_operator_probability_records.jsonl", "original_selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-POS64-OPPROB-016"], "scope_update_history": [{"fields": {"claim_verification_status": "Scoped source drift repair and corrected GRH criterion, unconditional degree-one vertical-shift counterexample to unnormalized degree discussion. Whole-work readingLevel1 only; journal status unverified.", "read_scope": "Allsixv1pages read; sourcePDF/TeX, centralfactor/drift, fulltransform, actualSelbergexamples and primary degree1classification compared. Scoped regular-part and vertical-family results adjudicated."}, "evidence": "audits/adversarial_reviews/director_central_drift_round10.md", "track_file": "quality/zzzzz_director_round10_source_scope_updates.jsonl"}], "claim_verification_status": "Scoped source drift repair and corrected GRH criterion, unconditional degree-one vertical-shift counterexample to unnormalized degree discussion. Whole-work readingLevel1 only; journal status unverified.", "scope_update_evidence": "audits/adversarial_reviews/director_central_drift_round10.md", "additional_scope_update_files": ["quality/zzzzz_director_round10_source_scope_updates.jsonl"]}','A probabilistic interpretation for central zeros of L-functions in the Selberg class','["Takashi Nakamura", "Masatoshi Suzuki"]',NULL,'2023',1,1,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2307.02027v1','d833f2af1f426c36f72cfb43df6b67bb3b3bf50ac9324c5069bc7442768a72d9','papers/positivity64_operator_probability_notes.md','papers/positivity64_operator_probability_records.jsonl');
