INSERT INTO "papers" VALUES('PAPER-POS64-OPPROB-028','corpus/bibliography.jsonl',717,'full_text_accessed','papers/positivity64_operator_probability_notes.md','{"id": "PAPER-POS64-OPPROB-028", "title": "A Riemann zeta stochastic process", "authors": ["Werner Ehm"], "year": 2007, "venue": "Comptes Rendus Mathématique 345, 279–282", "doi": "10.1016/j.crma.2007.07.023", "arxiv": null, "version": "Publisher version of record", "publication_status": "journal work", "canonical_url": "https://doi.org/10.1016/j.crma.2007.07.023", "source_url": "https://comptes-rendus.academie-sciences.fr/mathematique/item/10.1016/j.crma.2007.07.023.pdf", "source_sha256": "d8b37494c3d7fad01311a7108411966b137fd3a1d3cc653b0be62c959f01f28b", "pages": 4, "access_date": "2026-11-18", "bibliographic_verified": true, "full_text_accessed": true, "access_status": "full_text_accessed", "selected": true, "selection_status": "selected_checkpoint_priority_work", "audit_level": 1, "whole_work_read": true, "substantive_reading": true, "read_scope": "Entire journal note, pp. 279–282, §§1–3, eqs. (1)–(9), Theorems 3.1–3.2", "topic": "probability", "source_summary": "Constructs a continuous-parameter zeta process from independent geometric prime processes. Gives exponential-marginal and Brownian functional limits under distinct variance scalings.", "main_results": [{"locator": "Entire journal note, pp. 279–282, §§1–3, eqs. (1)–(9), Theorems 3.1–3.2", "statement": "For σ>1 the coupled logarithmic zeta process has independent decrements from independent geometric prime processes. Theorem 3.1 gives a variance-time Skorokhod limit with exponential marginals of mean √u and independent increments. Theorem 3.2 gives a Brownian limit for the variance-time centered prime-factor count. The source outlines parts of the limit proofs.", "status": "source statement"}], "record_path": "papers/positivity64_operator_probability_notes.md", "original_access_status": "full_text_accessed", "track_file": "papers/positivity64_operator_probability_records.jsonl", "original_selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-POS64-OPPROB-028"]}','A Riemann zeta stochastic process','["Werner Ehm"]',NULL,'2007',1,1,'selected_checkpoint_priority_work','full_text_accessed','Publisher version of record','https://comptes-rendus.academie-sciences.fr/mathematique/item/10.1016/j.crma.2007.07.023.pdf','d8b37494c3d7fad01311a7108411966b137fd3a1d3cc653b0be62c959f01f28b','papers/positivity64_operator_probability_notes.md','papers/positivity64_operator_probability_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-POS64-OPPROB-029','corpus/bibliography.jsonl',718,'full_text_accessed','papers/positivity64_operator_probability_notes.md','{"id": "PAPER-POS64-OPPROB-029", "title": "A stochastic interpretation of the Riemann zeta function", "authors": ["Kenneth S. Alexander", "Kenneth Baclawski", "Gian-Carlo Rota"], "year": 1993, "venue": "Proceedings of the National Academy of Sciences 90(2), 697–699", "doi": "10.1073/pnas.90.2.697", "arxiv": null, "version": "Author-hosted copy of version of record", "publication_status": "journal work", "canonical_url": "https://doi.org/10.1073/pnas.90.2.697", "source_url": "https://ken.baclawski.org/pub/1993/01/public.pdf", "source_sha256": "b9119bd4c979ec799e1297d5167252c5dd1c23ee886d5baf121db2aa91f5b118", "pages": 3, "access_date": "2026-11-18", "bibliographic_verified": true, "full_text_accessed": true, "access_status": "full_text_accessed", "selected": true, "selection_status": "selected_checkpoint_priority_work", "audit_level": 1, "whole_work_read": true, "substantive_reading": true, "read_scope": "Entire journal note, pp. 697–699, §§1–5, Theorems 1–4 and Corollaries 1–2", "topic": "probability", "source_summary": "Constructs the discrete-time zeta law from profinite Haar measure and a greatest-divisor random variable, via a general Rédei-zeta framework.", "main_results": [{"locator": "Entire journal note, pp. 697–699, §§1–5, Theorems 1–4 and Corollaries 1–2", "statement": "For each integer s>1, the largest common divisor of the first s Haar coordinates in the profinite completion of the integers is finite almost surely with law n^(−s)/ζ(s). Theorem 4 uses the homogeneous inverse-system formulation, infinite-poset Möbius inversion, and independence across primes.", "status": "source statement"}], "record_path": "papers/positivity64_operator_probability_notes.md", "original_access_status": "full_text_accessed", "track_file": "papers/positivity64_operator_probability_records.jsonl", "original_selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-POS64-OPPROB-029"]}','A stochastic interpretation of the Riemann zeta function','["Kenneth S. Alexander", "Kenneth Baclawski", "Gian-Carlo Rota"]',NULL,'1993',1,1,'selected_checkpoint_priority_work','full_text_accessed','Author-hosted copy of version of record','https://ken.baclawski.org/pub/1993/01/public.pdf','b9119bd4c979ec799e1297d5167252c5dd1c23ee886d5baf121db2aa91f5b118','papers/positivity64_operator_probability_notes.md','papers/positivity64_operator_probability_records.jsonl');
