INSERT INTO "papers" VALUES('PAPER-NIK1995-NB','corpus/bibliography.jsonl',746,'full_text_accessed','papers/prefix_formula62_generalL.md','{"id": "PAPER-NIK1995-NB", "title": "Distance formulae and invariant subspaces, with an application to localization of zeros of the Riemann ζ-function", "authors": ["Nikolai Nikolski"], "year": 1995, "venue": "Annales de l’Institut Fourier 45(1), 143–159", "version": "Published version", "canonical_url": "https://doi.org/10.5802/aif.1451", "doi": "10.5802/aif.1451", "arxiv": null, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "read_scope": "§4 Corollaries 4.1–4.2 and their references to the invariant-subspace theorem.", "audit_level": 0, "main_result": "Continuous Hardy-kernel distance gives a half-plane zero-free criterion and finite-subspace distances give explicit zero-free discs.", "selection_reason": "Underlying Hardy distance formula used in the general criteria for Dirichlet series.", "accessed_at": "2026-11-17", "record_path": "papers/prefix_formula62_generalL.md", "theorem_statements": "theorems/prefix_formula62_generalL_statements.md", "source_path": "sources/prefix_formula62_generalL/nikolski.pdf", "source_file": "sources/prefix_formula62_generalL/nikolski.pdf", "source_sha256": "0b40aed3e88b06491c824fc149d0e8207060a73966e729751b35afd86525544a", "pdf_pages": 18, "bibliographic_verified": true, "source_url": "https://doi.org/10.5802/aif.1451", "original_access_status": "full_text_accessed", "track_file": "papers/prefix_formula62_generalL_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-NIK1995-NB"]}','Distance formulae and invariant subspaces, with an application to localization of zeros of the Riemann ζ-function','["Nikolai Nikolski"]',NULL,'1995',0,0,'selected_checkpoint_priority_work','full_text_accessed','Published version','https://doi.org/10.5802/aif.1451','0b40aed3e88b06491c824fc1