INSERT INTO "papers" VALUES('PAPER-BD2005-KERNEL','corpus/bibliography.jsonl',747,'full_text_accessed','papers/prefix_formula62_generalL.md','{"id": "PAPER-BD2005-KERNEL", "title": "A general strong Nyman-Beurling Criterion for the Riemann Hypothesis", "authors": ["Luis Báez-Duarte"], "year": 2005, "venue": "arXiv preprint", "version": "arXiv v1, 2005-05-22", "canonical_url": "https://arxiv.org/abs/math/0505453", "doi": null, "arxiv": "math/0505453", "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": true, "read_scope": "Complete 10-page arXiv v1, §§1–3 and references. Reconstructed the good-kernel hypotheses, dilation-commuting convolution, Müntz identity, and both directions of Theorem 1.2. Intermediate sign placement in §2.3 is under independent review.", "audit_level": 1, "main_result": "For eligible smooth kernels f, RH implies approximation of f by integer dilates of its Müntz transform. For compactly supported f the reverse implication forces inclusion of right-half critical-strip zeta zeros in the zero set of the Mellin transform of f.", "selection_reason": "Separates a generalized target in the zeta problem from generalizing the L-function itself.", "accessed_at": "2026-11-17", "record_path": "papers/prefix_formula62_generalL.md", "theorem_statements": "theorems/prefix_formula62_generalL_statements.md", "source_path": "sources/prefix_formula62_generalL/baez_general.pdf", "source_file": "sources/prefix_formula62_generalL/baez_general.pdf", "source_sha256": "ae798c555cdb8a503ed09ffb396b954a1da1786cd9d662ddf03f7d37b4118d70", "pdf_pages": 10, "bibliographic_verified": true, "audit_evidence": "audits/general_l_priority_and_transfer_skeptic62.md", "source_url": "https://arxiv.org/abs/math/0505453", "original_access_status": "full_text_accessed", "track_file": "papers/prefix_formula62_generalL_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-BD2005-KERNEL"]}','A general strong Nyman-Beurling Criterion for the Riemann Hypothesis','["Luis Báez-Duarte"]',NULL,'2005',1,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv v1, 2005-05-22','https://arxiv.org/abs/math/0505453','ae798c555cdb8a503ed09ffb396b954a1da1786cd9d662ddf03f7d37b4118d70','papers/prefix_formula62_generalL.md','papers/prefix_formula62_generalL_records.jsonl');
