INSERT INTO "papers" VALUES('PAPER-LIU2026-BBM-METRIC','corpus/bibliography.jsonl',774,'full_text_accessed','papers/prefix_skeptic62_spectral.md','{"id": "PAPER-LIU2026-BBM-METRIC", "title": "Metric completion of the Bender–Brody–Müller Hamiltonian: dilation spectrum and missing eigenstates", "authors": ["Kejun Liu"], "year": 2026, "venue": "arXiv preprint", "version": "arXiv v1, 2026-07-21", "canonical_url": "https://arxiv.org/abs/2607.19067", "doi": null, "arxiv": "2607.19067", "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "read_scope": "Metric definition, completion theorem and missing-state argument independently checked. Transported-core deficiency classification not audited.", "audit_level": 0, "main_result": "In one specified half-line shift-metric completion, the critical-line Hurwitz candidates fail the state-space norm.", "selection_reason": "Pins the obstruction to a concrete completion while retaining its scope.", "claim_scope": "scoped_metric_obstruction", "accessed_at": "2026-11-17", "record_path": "papers/prefix_skeptic62_spectral.md", "source_url": "https://arxiv.org/pdf/2607.19067v1", "source_path": "sources/prefix_skeptic62_spectral/bbm_metric.pdf", "source_file": "sources/prefix_skeptic62_spectral/bbm_metric.pdf", "source_sha256": "8269515b0f88dd4fcc07a9697564cd7069bc7b2649951bfa0aa6f04e8e2ba1ba", "pdf_pages": 11, "bibliographic_verified": true, "original_access_status": "full_text_accessed", "track_file": "papers/prefix_skeptic62_spectral_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LIU2026-BBM-METRIC"]}','Metric completion of the Bender–Brody–Müller Hamiltonian: dilation spectrum and missing eigenstates','["Kejun Liu"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv v1, 2026-07-21','https://arxiv.org/pdf/2607.19067v1','8269515b0f88dd4fcc07a9697564cd7069bc7b2649951bfa0aa6f04e8e