INSERT INTO "papers" VALUES('PAPER-LP1974-SCATTER','corpus/bibliography.jsonl',776,'full_text_accessed','papers/prefix_skeptic62_spectral.md','{"id": "PAPER-LP1974-SCATTER", "title": "A scattering theory for automorphic functions", "authors": ["Peter D. Lax", "Ralph S. Phillips"], "year": 1974, "venue": "Séminaire Équations aux dérivées partielles, École Polytechnique 1973–1974, exposé 23, pp. 1–7", "version": "Published seminar facsimile", "canonical_url": "https://www.numdam.org/item/SEDP_1973-1974____A21_0/", "doi": null, "arxiv": null, "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "read_scope": "Printed pp. XXIII.4–6, energy-space and causal factorization, Eqs. (20)–(24) visually checked.", "audit_level": 0, "main_result": "Identifies a modular scattering coefficient whose meromorphic poles are related to the zeta zeros.", "selection_reason": "Contrasts true resonance locations with ordinary point-spectrum spectral measures.", "claim_scope": "rigorous_scattering_framework", "accessed_at": "2026-11-17", "record_path": "papers/prefix_skeptic62_spectral.md", "source_url": "https://www.numdam.org/article/SEDP_1973-1974____A21_0.pdf", "source_path": "sources/prefix_skeptic62_spectral/lax_phillips.pdf", "source_file": "sources/prefix_skeptic62_spectral/lax_phillips.pdf", "source_sha256": "3bd28ded0ccadc55b4b01c323d5d76be7bf6aea65960e9f40b1b6c0af0c18f46", "pdf_pages": 10, "bibliographic_verified": true, "original_access_status": "full_text_accessed", "track_file": "papers/prefix_skeptic62_spectral_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-LP1974-SCATTER"]}','A scattering theory for automorphic functions','["Peter D. Lax", "Ralph S. Phillips"]',NULL,'1974',0,0,'selected_checkpoint_priority_work','full_text_accessed','Published seminar facsimile','https://www.numdam.org/article/SEDP_1973-1974____A21_0.pdf','3bd28ded0ccadc55b4b01c32