INSERT INTO "papers" VALUES('PAPER-HJKP2026-SR-COMPARISON','corpus/bibliography.jsonl',777,'full_text_accessed','papers/prefix_skeptic62_spectral.md','{"id": "PAPER-HJKP2026-SR-COMPARISON", "title": "Eigenvalue-by-Eigenvalue Comparison of a Sierra–Rodríguez-Laguna-Type Spectrum with the Riemann Zeros", "authors": ["Mi-Ra Hwang", "Eylee Jung", "MuSeong Kim", "DaeKil Park"], "year": 2026, "venue": "arXiv preprint", "version": "arXiv v2, 2026-10-25", "canonical_url": "https://arxiv.org/abs/2609.23353", "doi": null, "arxiv": "2609.23353", "access_status": "full_text_accessed", "full_text_accessed": true, "whole_work_read": false, "read_scope": "Abstract, fixed-phase Bessel equation and numerical/smooth offset comparison.", "audit_level": 0, "main_result": "Compares 606 SR-type numerical model levels with zeta-zero ordinates and analyzes a smooth offset.", "selection_reason": "Tests the difference between a smooth spectral staircase and the fluctuations of individual zero ordinates.", "claim_scope": "numerical_and_asymptotic_comparison", "accessed_at": "2026-11-17", "record_path": "papers/prefix_skeptic62_spectral.md", "source_url": "https://arxiv.org/pdf/2609.23353v2", "source_path": "sources/prefix_skeptic62_spectral/sierra_comparison.pdf", "source_file": "sources/prefix_skeptic62_spectral/sierra_comparison.pdf", "source_sha256": "4dd170f2cb118070b68220f9c072c76cc1e79fd472d537fde81f9407465fdcda", "pdf_pages": 11, "bibliographic_verified": true, "original_access_status": "full_text_accessed", "track_file": "papers/prefix_skeptic62_spectral_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-HJKP2026-SR-COMPARISON"]}','Eigenvalue-by-Eigenvalue Comparison of a Sierra–Rodríguez-Laguna-Type Spectrum with the Riemann Zeros','["Mi-Ra Hwang", "Eylee Jung", "MuSeong Kim", "DaeKil Park"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv v2, 2026-10-25','https://arx