INSERT INTO "papers" VALUES('PAPER-PM64-B-DENSITY','corpus/bibliography.jsonl',778,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2012.09045", "audit_level": 0, "authors": ["Szilárd Gy. Révész"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2012.09045v3", "doi": "10.1112/mtk.12156", "full_text_accessed": true, "language": "English", "main_result": "For an Axiom A system with integer-valued norms (B) and G: X^−1Σ_{ν≤X}G(ν)^(1+p)≪ε X^ε for some p>1 and every ε>0, with G(ν) the norm multiplicity, the count in β≥α, |γ|≤T is at most Cε T^(((6−2θ)/(1−θ))(1−α)+ε) for α>(1+θ)/2 and sufficiently large T. The local theorem uses Axiom A alone but assumes an adjacent zero-free rectangle.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-DENSITY", "pdf_pages": 33, "provider_identity_only_ids": ["CAND-3C06A884957D"], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §§2–4, Definitions 2–3 and Theorems 1–2", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Test whether a local cluster estimate can replace the taper''s crude unit-window multiplicity count. The global theorem adds arithmetic hypotheses and the local gain requires the zero-free rectangle, so neither supplies unconstrained critical-line spacing.", "source_locator": "§§2–4, Definitions 2–3 and Theorems 1–2", "source_path": "sources/prime64_beurling_adjacent/2012.09045.pdf", "source_sha256": "f39cade2cbc3301f2a279bc66d5e35b6954d879762aa732b55686a7c9a55e47b", "source_url": "https://arxiv.org/pdf/2012.09045v3", "substantive_reading": false, "title": "Density estimates for the zeros of the Beurling ζ function in the critical strip", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2012.09045v3", "version_date": "2022-06-25", "version_receipt": "sources/prime64_beurling_adjacent/2012.09045.html", "whole_work_read": false, "year": 2022, "id": "PAPER-PM64-B-DENSITY", "arxiv": "2012.09045", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-DENSITY"]}','Density estimates for the zeros of the Beurling ζ function in the critical strip','["Szilárd Gy. Révész"]',NULL,'2022',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2012.09045v3','https://arxiv.org/pdf/2012.09045v3','f39cade2cbc3301f2a279bc66d5e35b6954d879762aa732b55686a7c9a55e47b','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-DENSITY-KERNEL','corpus/bibliography.jsonl',779,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2407.12746", "audit_level": 1, "authors": ["János Pintz", "Szilárd Gy. Révész"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2407.12746v1", "comparison_manifestation": {"read_scope": "Theorem 1 and §5.4 equation (45), first-branch range preserved and last-branch threshold ambiguity retained.", "sha256": "1b05f3bdef41e60029cf076fe014a61ef8f37d8622460b8d8e6f6fb934a72878", "source_path": "sources/prime64_beurling_adjacent/2407.12746_journal_comparison.pdf", "source_url": "https://www.impan.pl/shop/en/publication/transaction/download/product/116232", "whole_work_read": false}, "doi": "10.4064/aa240719-3-6", "full_text_accessed": true, "language": "English", "main_result": "Under Axiom A, integrality and pointwise Ramanujan G(n)≪ε n^ε, the first regime 0<η<min(1−θ,4/29,(8+13θ)/71) gives a two-sign zero count ≪η,ε T^(2η/(1−θ−η)+ε). The detector works on ordinary reciprocal Dirichlet series with bounds on both coefficient arrays.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-DENSITY-KERNEL", "pdf_pages": 8, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Complete pinned edition. Whole PDF pp. 1–8, especially §3 Theorem 1, §4 Lemma 1 and §5.4", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "A kernel route to a right-slab density estimate independent of generalized mean-value bounds. Integrality is decisive in the reciprocal-series detector and the result concerns a fixed right slab, with no derivative weights or phase recovery.", "source_locator": "Whole PDF pp. 1–8, especially §3 Theorem 1, §4 Lemma 1 and §5.4", "source_path": "sources/prime64_beurling_adjacent/2407.12746.pdf", "source_sha256": "6e0b16c71381e22c7da7957d9fdc8c1d1c1858c05f89b847bf2a6f98cb9c0d74", "source_url": "https://arxiv.org/pdf/2407.12746v1", "substantive_reading": true, "title": "New zero-density estimates for the Beurling ζ function", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2407.12746v1", "version_date": "2024-07-17", "version_receipt": "sources/prime64_beurling_adjacent/2407.12746.html", "whole_work_read": true, "year": 2024, "id": "PAPER-PM64-B-DENSITY-KERNEL", "arxiv": "2407.12746", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-DENSITY-KERNEL"]}','New zero-density estimates for the Beurling ζ function','["János Pintz", "Szilárd Gy. Révész"]',NULL,'2024',1,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2407.12746v1','https://arxiv.org/pdf/2407.12746v1','6e0b16c71381e22c7da7957d9fdc8c1d1c1858c05f89b847bf2a6f98cb9c0d74','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-RANDOM-DISCRETE','corpus/bibliography.jsonl',780,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2102.08478", "audit_level": 0, "authors": ["Frederik Broucke", "Jasson Vindas"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2102.08478v2", "doi": "10.1007/s00209-024-03526-4", "full_text_accessed": true, "language": "English", "main_result": "For unbounded nondecreasing right-continuous F with F(1)=0 and F(x)≪x/log x, constructs discrete generalized primes whose counting discrepancy is bounded and whose Mellin twist discrepancy is ≪√x+√(x log(1+|t|)/log(1+x)), uniformly in x≥1 and real t. Continuity permits strictly increasing primes.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-RANDOM-DISCRETE", "pdf_pages": 15, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Theorem 1.2 and §2 construction", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Provides a transfer condition from continuous synthetic prime measures to genuine Beurling systems while tracking vertical oscillations. It preserves estimates only at the stated discrepancy scale; deductions involving the inverse zeta and RH-line geometry need separate control.", "source_locator": "§1 Theorem 1.2 and §2 construction", "source_path": "sources/prime64_beurling_adjacent/2102.08478.pdf", "source_sha256": "66b727b7b5b151844558b88c1495e1eca902b1c0ea01840b5e783f4b2ff0c9c8", "source_url": "https://arxiv.org/pdf/2102.08478v2", "substantive_reading": false, "title": "A new generalized prime random approximation procedure and some of its applications", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2102.08478v2", "version_date": "2024-06-17", "version_receipt": "sources/prime64_beurling_adjacent/2102.08478.html", "whole_work_read": false, "year": 2024, "id": "PAPER-PM64-B-RANDOM-DISCRETE", "arxiv": "2102.08478", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-RANDOM-DISCRETE"]}','A new generalized prime random approximation procedure and some of its applications','["Frederik Broucke", "Jasson Vindas"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2102.08478v2','https://arxiv.org/pdf/2102.08478v2','66b727b7b5b151844558b88c1495e1eca902b1c0ea01840b5e783f4b2ff0c9c8','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-PERRON','corpus/bibliography.jsonl',781,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2110.11463", "audit_level": 0, "authors": ["Szilárd Gy. Révész"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2110.11463v1", "doi": "10.1556/314.2021.00019", "full_text_accessed": true, "language": "English", "main_result": "Under Axiom A, a constructed contour Γ_b with θ<b<1 and admissible truncation heights t_k supports a Riemann–von Mangoldt-type explicit formula for ψ(x), with x−Σρ x^ρ/ρ and an explicit contour-dependent remainder.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-PERRON", "pdf_pages": 29, "provider_identity_only_ids": ["CAND-8DCC4BC99BDF"], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §4 Lemma 4.2 and §5 Theorem 5.1", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "A candidate replacement for the ordinary integer proof''s good horizontal heights when zeta continuation stops at θ. It controls a prime summatory function, so the tapered array still needs its squared Mellin norm and an anchor at the pole.", "source_locator": "§4 Lemma 4.2 and §5 Theorem 5.1", "source_path": "sources/prime64_beurling_adjacent/2110.11463.pdf", "source_sha256": "716eac89fe76858bc0d492015de2a6088b60d62bd95904670ff6275c2103117c", "source_url": "https://arxiv.org/pdf/2110.11463v1", "substantive_reading": false, "title": "A Riemann-von Mangoldt-type formula for the distribution of Beurling primes", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2110.11463v1", "version_date": "2021-10-21", "version_receipt": "sources/prime64_beurling_adjacent/2110.11463.html", "whole_work_read": false, "year": 2021, "id": "PAPER-PM64-B-PERRON", "arxiv": "2110.11463", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-PERRON"]}','A Riemann-von Mangoldt-type formula for the distribution of Beurling primes','["Szilárd Gy. Révész"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2110.11463v1','https://arxiv.org/pdf/2110.11463v1','716eac89fe76858bc0d492015de2a6088b60d62bd95904670ff6275c2103117c','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-DENSITY-MOMENT','corpus/bibliography.jsonl',782,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2409.10051", "audit_level": 0, "authors": ["Frederik Broucke"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2409.10051v1", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "For N(x)=Ax+O(x^θ), obtains N(ζ_P;α,T)≪T^(4(1−α)/(3−2α−θ))(log T)^9 uniformly at α≥(1+θ)/2 within the critical strip and T≥2. The proof uses a new second moment with local clusters of generalized frequencies.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-DENSITY-MOMENT", "pdf_pages": 24, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Theorems 1.2–1.3 and §2 Theorem 2.1", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "This is a direct analytic route around lack of an approximate functional equation. Apply the cluster moment only after verifying the integer-count axiom and local frequency counts; this is an unweighted zero count, so it cannot by itself replace the sampled ζ′ moments.", "source_locator": "§1 Theorems 1.2–1.3 and §2 Theorem 2.1", "source_path": "sources/prime64_beurling_adjacent/2409.10051.pdf", "source_sha256": "a0c87f3b29324d1a6994be6bd7c6ee4f20f0afc1af003bad37b7c78e3f788b79", "source_url": "https://arxiv.org/pdf/2409.10051v1", "substantive_reading": false, "title": "On zero-density estimates for Beurling zeta functions", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2409.10051v1", "version_date": "2024-09-16", "version_receipt": "sources/prime64_beurling_adjacent/2409.10051.html", "whole_work_read": false, "year": 2024, "id": "PAPER-PM64-B-DENSITY-MOMENT", "arxiv": "2409.10051", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-DENSITY-MOMENT"]}','On zero-density estimates for Beurling zeta functions','["Frederik Broucke"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2409.10051v1','https://arxiv.org/pdf/2409.10051v1','a0c87f3b29324d1a6994be6bd7c6ee4f20f0afc1af003bad37b7c78e3f788b79','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-CLUSTER-MEAN','corpus/bibliography.jsonl',783,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2211.08716", "audit_level": 0, "authors": ["Frederik Broucke", "Gregory Debruyne"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2211.08716v2", "doi": "10.4064/aa221223-15-2", "full_text_accessed": true, "language": "English", "main_result": "For θ-well-behaved integers (N(x)=Ax+O(x^θ)), obtains N(α,T)=o(T) for α>(θ+2)/3. The generalized mean-value estimate in Theorem 2.1 keeps track of real frequencies grouped in short clusters.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-CLUSTER-MEAN", "pdf_pages": 22, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §§1–2, Theorems 1.2 and 2.1, Corollaries 1.3 and 2.3", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Exposes the replacement for ordinary logarithmic frequency spacing in dyadic Hardy/Mellin calculations. Its finite coefficient norm must charge a cluster with its multiplicities; a direct diagonal-only replacement would fail when generalized integers share a norm.", "source_locator": "§§1–2, Theorems 1.2 and 2.1, Corollaries 1.3 and 2.3", "source_path": "sources/prime64_beurling_adjacent/2211.08716.pdf", "source_sha256": "1b9413c599a123f69df38ebecb780d37b6123bf2d1a25cc960ec99e488bfa7c8", "source_url": "https://arxiv.org/pdf/2211.08716v2", "substantive_reading": false, "title": "On zero-density estimates and the PNT in short intervals for Beurling generalized numbers", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2211.08716v2", "version_date": "2022-12-21", "version_receipt": "sources/prime64_beurling_adjacent/2211.08716.html", "whole_work_read": false, "year": 2022, "id": "PAPER-PM64-B-CLUSTER-MEAN", "arxiv": "2211.08716", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-CLUSTER-MEAN"]}','On zero-density estimates and the PNT in short intervals for Beurling generalized numbers','["Frederik Broucke", "Gregory Debruyne"]',NULL,'2022',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2211.08716v2','https://arxiv.org/pdf/2211.08716v2','1b9413c599a123f69df38ebecb780d37b6123bf2d1a25cc960ec99e488bfa7c8','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-CESARO-SEPARATION','corpus/bibliography.jsonl',784,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "1505.04174", "audit_level": 0, "authors": ["Gregory Debruyne", "Jan-Christoph Schlage-Puchta", "Jasson Vindas"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1505.04174v2", "doi": "10.4064/aa8168-7-2016", "full_text_accessed": true, "language": "English", "main_result": "For 1<α<3/2 constructs discrete systems whose integer remainder is O_n(x/log^n x) in the paper''s Cesàro sense for every n, while the indicated logarithmically weighted squared error diverges and π_P(x)=x/log x+O(x/log^α x). At the endpoint model the PNT fails.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-CESARO-SEPARATION", "pdf_pages": 26, "provider_identity_only_ids": ["CAND-11247867E6B1"], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Theorems 1.1–1.2, equations (1.4), (1.7)–(1.9)", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "An exact counterexample to transferring strong smoothed integer estimates to a global L² statement. A weighted-square upgrade for the tapered construction must control far tails separately.", "source_locator": "§1 Theorems 1.1–1.2, equations (1.4), (1.7)–(1.9)", "source_path": "sources/prime64_beurling_adjacent/1505.04174.pdf", "source_sha256": "257c64c83aff1d4c4fa7afa6462c80ed46e8cd7f1fda562159702e79b6437184", "source_url": "https://arxiv.org/pdf/1505.04174v2", "substantive_reading": false, "title": "Some examples in the theory of Beurling''s generalized prime numbers", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1505.04174v2", "version_date": "2016-10-01", "version_receipt": "sources/prime64_beurling_adjacent/1505.04174.html", "whole_work_read": false, "year": 2016, "id": "PAPER-PM64-B-CESARO-SEPARATION", "arxiv": "1505.04174", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-CESARO-SEPARATION"]}','Some examples in the theory of Beurling''s generalized prime numbers','["Gregory Debruyne", "Jan-Christoph Schlage-Puchta", "Jasson Vindas"]',NULL,'2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1505.04174v2','https://arxiv.org/pdf/1505.04174v2','257c64c83aff1d4c4fa7afa6462c80ed46e8cd7f1fda562159702e79b6437184','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-ASYMMETRIC-OSC','corpus/bibliography.jsonl',785,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2004.11501", "audit_level": 0, "authors": ["Frederik Broucke", "Gregory Debruyne", "Jasson Vindas"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2004.11501v2", "doi": "10.1016/j.aim.2020.107240", "full_text_accessed": true, "language": "English", "main_result": "There exists a discrete system with π(x)=Li(x)+O(√x), but N(x)−ρx is Ω±(x exp(−c√(log x log log x))) for every c>2√2. A continuous model precedes discretization.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-ASYMMETRIC-OSC", "pdf_pages": 31, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Theorems 1.1 and 1.3", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Separates a square-root-scale prime error from power-saving generalized integer counts. Thus a good prime-side log derivative estimate is insufficient for the vertical moment hypotheses used by the Beurling taper analogue.", "source_locator": "§1 Theorems 1.1 and 1.3", "source_path": "sources/prime64_beurling_adjacent/2004.11501.pdf", "source_sha256": "375da1cc390d96ebd7ee8c9b177c23fcfc874c439c98051f9b3de3bfb0f814b6", "source_url": "https://arxiv.org/pdf/2004.11501v2", "substantive_reading": false, "title": "Beurling integers with RH and large oscillation", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2004.11501v2", "version_date": "2020-05-26", "version_receipt": "sources/prime64_beurling_adjacent/2004.11501.html", "whole_work_read": false, "year": 2020, "id": "PAPER-PM64-B-ASYMMETRIC-OSC", "arxiv": "2004.11501", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-ASYMMETRIC-OSC"]}','Beurling integers with RH and large oscillation','["Frederik Broucke", "Gregory Debruyne", "Jasson Vindas"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2004.11501v2','https://arxiv.org/pdf/2004.11501v2','375da1cc390d96ebd7ee8c9b177c23fcfc874c439c98051f9b3de3bfb0f814b6','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-MALLIAVIN-BOUND','corpus/bibliography.jsonl',786,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2012.06220", "audit_level": 0, "authors": ["Frederik Broucke"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2012.06220v1", "doi": "10.1007/s00605-021-01593-x", "full_text_accessed": true, "language": "English", "main_result": "For 0<β<1 the constructed system has N(x)=Ax+O(x exp(−c′(log x)^β)) while the generalized π(x) remainder has an Ω result with exponent β/(β+1) in the stretched exponential.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-MALLIAVIN-BOUND", "pdf_pages": 11, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 definitions and endpoint sharpness result, §§2–3", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "The integer-to-prime exponent in this class cannot be upgraded by formal Mellin inversion. This constrains which zero-free/prime-tail rate one can hope to recover from N-error input alone.", "source_locator": "§1 definitions and endpoint sharpness result, §§2–3", "source_path": "sources/prime64_beurling_adjacent/2012.06220.pdf", "source_sha256": "c36535c1f87278253dd2762391ddd954b2405c8235036af6aedf1007b030aa59", "source_url": "https://arxiv.org/pdf/2012.06220v1", "substantive_reading": false, "title": "Note on a conjecture of Bateman and Diamond concerning the abstract PNT with Malliavin-type remainder", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2012.06220v1", "version_date": "2020-12-11", "version_receipt": "sources/prime64_beurling_adjacent/2012.06220.html", "whole_work_read": false, "year": 2020, "id": "PAPER-PM64-B-MALLIAVIN-BOUND", "arxiv": "2012.06220", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-MALLIAVIN-BOUND"]}','Note on a conjecture of Bateman and Diamond concerning the abstract PNT with Malliavin-type remainder','["Frederik Broucke"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2012.06220v1','https://arxiv.org/pdf/2012.06220v1','c36535c1f87278253dd2762391ddd954b2405c8235036af6aedf1007b030aa59','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-PRESCRIBED-ZEROS','corpus/bibliography.jsonl',787,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2309.01567", "audit_level": 0, "authors": ["Frederik Broucke", "Gregory Debruyne", "Szilárd Révész"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2309.01567v2", "doi": "10.1090/tran/9274", "full_text_accessed": true, "language": "English", "main_result": "For every α∈[0,1), β∈[1/2,1) constructs an [α,β]-system in the paper''s exact limsup-error sense. Theorem 3.2 allows two finite disjoint conjugation-symmetric multisets in 0<Re s<1 and gives a ψ-expansion displaying prescribed signed pole/zero contributions.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-PRESCRIBED-ZEROS", "pdf_pages": 24, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Theorems 1.1 and 1.3, §3 Theorem 3.2", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "A concrete way to test what generalized Euler-product structure can force about off-line quartets and inverse recovery. Passing a synthetic counterexample to the ordinary primes would require a separate arithmetic obstruction; the theorem provides flexible Beurling parameters only.", "source_locator": "§1 Theorems 1.1 and 1.3, §3 Theorem 3.2", "source_path": "sources/prime64_beurling_adjacent/2309.01567.pdf", "source_sha256": "eb6863d69a936594e9df03485688ec8115b3ac0ade7de4e3dd99efa4fe14d899", "source_url": "https://arxiv.org/pdf/2309.01567v2", "substantive_reading": false, "title": "Some examples of well-behaved Beurling number systems", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2309.01567v2", "version_date": "2024-06-26", "version_receipt": "sources/prime64_beurling_adjacent/2309.01567.html", "whole_work_read": false, "year": 2024, "id": "PAPER-PM64-B-PRESCRIBED-ZEROS", "arxiv": "2309.01567", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-PRESCRIBED-ZEROS"]}','Some examples of well-behaved Beurling number systems','["Frederik Broucke", "Gregory Debruyne", "Szilárd Révész"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2309.01567v2','https://arxiv.org/pdf/2309.01567v2','eb6863d69a936594e9df03485688ec8115b3ac0ade7de4e3dd99efa4fe14d899','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-M-PNT','corpus/bibliography.jsonl',788,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "1609.03504", "audit_level": 0, "authors": ["Gregory Debruyne", "Harold G. Diamond", "Jasson Vindas"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1609.03504v1", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "PNT and the O-density condition N(x)≪x imply M(x)=o(x) for a generalized number system, via a log-convolution identity. Other sufficient integer density conditions and examples are treated separately.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-M-PNT", "pdf_pages": 14, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §§2–4, especially §2 Theorem 2.1 and Lemma 2.2", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Identifies a missing integer majorant when using prime-side asymptotics to conclude cancellation of inverse coefficients. The conclusion is an unsigned-scale o(x), so a critical-line reciprocal-moment estimate requires stronger input.", "source_locator": "§§2–4, especially §2 Theorem 2.1 and Lemma 2.2", "source_path": "sources/prime64_beurling_adjacent/1609.03504.pdf", "source_sha256": "3f87d03d65adcb13508e41c1651706eedf36a4a7d892d60c5a599aa382eac2f8", "source_url": "https://arxiv.org/pdf/1609.03504v1", "substantive_reading": false, "title": "M(x)=o(x) Estimates for Beurling numbers", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1609.03504v1", "version_date": "2016-09-12", "version_receipt": "sources/prime64_beurling_adjacent/1609.03504.html", "whole_work_read": false, "year": 2016, "id": "PAPER-PM64-B-M-PNT", "arxiv": "1609.03504", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-M-PNT"]}','M(x)=o(x) Estimates for Beurling numbers','["Gregory Debruyne", "Harold G. Diamond", "Jasson Vindas"]',NULL,'2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1609.03504v1','https://arxiv.org/pdf/1609.03504v1','3f87d03d65adcb13508e41c1651706eedf36a4a7d892d60c5a599aa382eac2f8','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-MERTENS-CONSTANT','corpus/bibliography.jsonl',789,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "1606.03579", "audit_level": 0, "authors": ["Gregory Debruyne", "Jasson Vindas"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1606.03579v3", "doi": "10.1007/s00605-016-0979-9", "full_text_accessed": true, "language": "English", "main_result": "PNT, N(x)=ax+o(x/log x), and convergence of ∫₁∞(N(x)−ax)x^−2 dx imply the sharp generalized Mertens relation ψ₁(x)=log x+c+o(1), with c determined by the residual integral.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-MERTENS-CONSTANT", "pdf_pages": 21, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Theorem 1 and equation (1.5)", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "The constant is a generalized Laurent-anchor analogue for a Mellin taper. Its existence depends on a convergence hypothesis, and convergence of that residual integral alone gives no finite-N derivative or second-moment estimate.", "source_locator": "§1 Theorem 1 and equation (1.5)", "source_path": "sources/prime64_beurling_adjacent/1606.03579.pdf", "source_sha256": "6e594a5f1834de7087698e3498f7d0d3a5afb7f538be165e86a48b5401a20c07", "source_url": "https://arxiv.org/pdf/1606.03579v3", "substantive_reading": false, "title": "On PNT equivalences for Beurling numbers", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1606.03579v3", "version_date": "2016-10-09", "version_receipt": "sources/prime64_beurling_adjacent/1606.03579.html", "whole_work_read": false, "year": 2016, "id": "PAPER-PM64-B-MERTENS-CONSTANT", "arxiv": "1606.03579", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-MERTENS-CONSTANT"]}','On PNT equivalences for Beurling numbers','["Gregory Debruyne", "Jasson Vindas"]',NULL,'2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1606.03579v3','https://arxiv.org/pdf/1606.03579v3','6e594a5f1834de7087698e3498f7d0d3a5afb7f538be165e86a48b5401a20c07','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-M-PERTURB','corpus/bibliography.jsonl',790,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2406.00736", "audit_level": 1, "authors": ["Jasson Vindas"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2406.00736v2", "doi": "10.1007/s10476-024-00061-6", "full_text_accessed": true, "language": "English", "main_result": "The convolution inverse of a prime measure Π₀+E+R has M(x)=o(x) if M₀(x)=O(x/log^a x), a>0, |dE|([1,x])=o(x/log x), and ∫u^−1|dR|<∞. Kahane''s monotone perturbation even has M_K=o(x/log x).", "novelty_claim": false, "paper_id": "PAPER-PM64-B-M-PERTURB", "pdf_pages": 9, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Complete pinned edition. Whole PDF pp. 1–9, Theorem 1.1, Proposition 1.2 and §§2–4", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Specifies allowable perturbations of the inverse coefficient sequence. Norm control on the perturbation is in weighted variation, so simple matching of counts or a pointwise Mellin limit cannot invoke the theorem.", "source_locator": "Whole PDF pp. 1–9, Theorem 1.1, Proposition 1.2 and §§2–4", "source_path": "sources/prime64_beurling_adjacent/2406.00736.pdf", "source_sha256": "490ca2711f14947b6637b44c9efd39735f49709fb82f99faa50afabed98c4de8", "source_url": "https://arxiv.org/pdf/2406.00736v2", "substantive_reading": true, "title": "On the estimate M(x)=o(x) for Beurling generalized numbers", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2406.00736v2", "version_date": "2024-09-22", "version_receipt": "sources/prime64_beurling_adjacent/2406.00736.html", "whole_work_read": true, "year": 2024, "id": "PAPER-PM64-B-M-PERTURB", "arxiv": "2406.00736", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-M-PERTURB"]}','On the estimate M(x)=o(x) for Beurling generalized numbers','["Jasson Vindas"]',NULL,'2024',1,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2406.00736v2','https://arxiv.org/pdf/2406.00736v2','490ca2711f14947b6637b44c9efd39735f49709fb82f99faa50afabed98c4de8','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-HALASZ','corpus/bibliography.jsonl',791,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "1902.03870", "audit_level": 0, "authors": ["Gregory Debruyne", "Frederick Maes", "Jasson Vindas"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1902.03870v3", "doi": "10.4064/aa190210-22-5", "full_text_accessed": true, "language": "English", "main_result": "A positive generalized integer density and a Chebyshev upper bound for the generalized primes suffice for M(x)=o(x). Theorems 2.1 and 2.3 treat multiplicative measures through a compact-uniform boundary asymptotic plus stated convolution hypotheses.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-HALASZ", "pdf_pages": 12, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §§1–2, Corollaries 1.2 and 2.2, Theorem 2.3", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Shows what would be needed to transport pretentious mean-value control off N. Positivity/density and compact-uniform transform information are additional to the Euler-product identity, and the boundary is Re s=1, not the critical-line energy norm.", "source_locator": "§§1–2, Corollaries 1.2 and 2.2, Theorem 2.3", "source_path": "sources/prime64_beurling_adjacent/1902.03870.pdf", "source_sha256": "030201a60958a854ac8ba9c52c00df5bb892a3ee1bbfb5b9a9dc2d89453e1d3b", "source_url": "https://arxiv.org/pdf/1902.03870v3", "substantive_reading": false, "title": "Halász''s theorem for Beurling generalized numbers", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1902.03870v3", "version_date": "2020-02-25", "version_receipt": "sources/prime64_beurling_adjacent/1902.03870.html", "whole_work_read": false, "year": 2020, "id": "PAPER-PM64-B-HALASZ", "arxiv": "1902.03870", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-HALASZ"]}','Halász''s theorem for Beurling generalized numbers','["Gregory Debruyne", "Frederick Maes", "Jasson Vindas"]',NULL,'2020',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1902.03870v3','https://arxiv.org/pdf/1902.03870v3','030201a60958a854ac8ba9c52c00df5bb892a3ee1bbfb5b9a9dc2d89453e1d3b','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-OMEGA-RESIDUES','corpus/bibliography.jsonl',792,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2002.00927", "audit_level": 1, "authors": ["Gregory Debruyne"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2002.00927v1", "comparison_manifestation": {"read_scope": "Remark 2.3, equation (2.15), corrected logarithmic density normalization.", "sha256": "91e2204ce3b98aac7b007701ad19fc1ca37397ba025e841a849171fbcf6d4175", "source_path": "sources/prime64_beurling_adjacent/2002.00927_repository_comparison.pdf", "source_url": "https://backoffice.biblio.ugent.be/download/8687953/8711793", "whole_work_read": false}, "doi": "10.4064/aa200130-15-6", "full_text_accessed": true, "language": "English", "main_result": "For discrete Beurling systems with π(x)≪x/log x and N(x)∼ax, counts of integers with Ω(n)≡c mod K are asymptotic to ax/K for fixed K≥2 and c. Remark 2.2 supplies the distinct-prime variant.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-OMEGA-RESIDUES", "pdf_pages": 5, "provider_identity_only_ids": ["CAND-EDFFBE2FA7F8"], "publication_status": "verified arXiv manifestation", "read_scope": "Complete pinned edition. Whole PDF pp. 1–5, Theorem 1.1, Lemma 2.1 and Remark 2.2", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Finite root-of-unity filters distinguish a genuine fixed-character arithmetic averaging theorem from the prime-torus limit of derivative-weighted zero samples. Neither a growing K nor a statement about zero phases follows from this fixed K theorem.", "source_locator": "Whole PDF pp. 1–5, Theorem 1.1, Lemma 2.1 and Remark 2.2", "source_path": "sources/prime64_beurling_adjacent/2002.00927.pdf", "source_sha256": "b5d45a6cee8440ee4fbddddfd918e576d14c9bbadd4a61f6f3653fd161ec566e", "source_url": "https://arxiv.org/pdf/2002.00927v1", "substantive_reading": true, "title": "Beurling numbers whose number of prime factors lies in a specified residue class", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2002.00927v1", "version_date": "2020-02-03", "version_receipt": "sources/prime64_beurling_adjacent/2002.00927.html", "whole_work_read": true, "year": 2020, "id": "PAPER-PM64-B-OMEGA-RESIDUES", "arxiv": "2002.00927", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-OMEGA-RESIDUES"]}','Beurling numbers whose number of prime factors lies in a specified residue class','["Gregory Debruyne"]',NULL,'2020',1,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2002.00927v1','https://arxiv.org/pdf/2002.00927v1','b5d45a6cee8440ee4fbddddfd918e576d14c9bbadd4a61f6f3653fd161ec566e','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-BOUNDARY-REMAINDERS','corpus/bibliography.jsonl',793,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "1601.05324", "audit_level": 0, "authors": ["Gregory Debruyne", "Jasson Vindas"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1601.05324v2", "doi": "10.1007/978-3-319-51911-1_6", "full_text_accessed": true, "language": "English", "main_result": "Super-logarithmic PNT remainders π(x)=Li(x)+O_n(x/log^n x) for every n are equivalent to N(x)=ax+O_n(x/log^n x) for every n. Theorem 3 pins the required C∞ and vertical derivative conditions for the pole-subtracted zeta.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-BOUNDARY-REMAINDERS", "pdf_pages": 15, "provider_identity_only_ids": ["CAND-B2E810579D8D"], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §§1 and 4, Theorems 1 and 3", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "A model for checking exact Hardy/Mellin boundary hypotheses. Sectorial smoothness without the specified vertical control is not a substitute for a boundary derivative estimate; these remain Re s≥1 statements.", "source_locator": "§§1 and 4, Theorems 1 and 3", "source_path": "sources/prime64_beurling_adjacent/1601.05324.pdf", "source_sha256": "5100c8395e6eb149e76fd3d62cf5146d38faac1804afa6c7d9f0dd7e9f30464c", "source_url": "https://arxiv.org/pdf/1601.05324v2", "substantive_reading": false, "title": "On General Prime Number Theorems with Remainder", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1601.05324v2", "version_date": "2017-02-17", "version_receipt": "sources/prime64_beurling_adjacent/1601.05324.html", "whole_work_read": false, "year": 2017, "id": "PAPER-PM64-B-BOUNDARY-REMAINDERS", "arxiv": "1601.05324", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-BOUNDARY-REMAINDERS"]}','On General Prime Number Theorems with Remainder','["Gregory Debruyne", "Jasson Vindas"]',NULL,'2017',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1601.05324v2','https://arxiv.org/pdf/1601.05324v2','5100c8395e6eb149e76fd3d62cf5146d38faac1804afa6c7d9f0dd7e9f30464c','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-GIVEN-ZERO','corpus/bibliography.jsonl',794,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2202.01837", "audit_level": 0, "authors": ["Szilárd Gy. Révész"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2202.01837v3", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "Under Axiom A, one specified zero β₀>θ forces |ψ(x)−x|≥(1−ε)x^β₀/|ρ₀| arbitrarily far out, with factor π/2−ε if γ₀≠0. A constructed model gives near-sharpness in the indicated β₀,r regime.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-GIVEN-ZERO", "pdf_pages": 28, "provider_identity_only_ids": ["CAND-A71C9009EDBA"], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Theorems 2–3", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Tests the distinction between detecting an off-line zero through a signed arithmetic witness and obtaining a global norm lower bound. The existence of large subsequence values is not uniform phase recovery or a finite-range estimate.", "source_locator": "§1 Theorems 2–3", "source_path": "sources/prime64_beurling_adjacent/2202.01837.pdf", "source_sha256": "513da18b5e8c9054f5cce499ae5c32340aff60640b759b1ddd3a66eaee772f89", "source_url": "https://arxiv.org/pdf/2202.01837v3", "substantive_reading": false, "title": "Oscillation of the remainder term in the prime number theorem of Beurling, \"caused by a given zeta-zero\"", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2202.01837v3", "version_date": "2022-09-15", "version_receipt": "sources/prime64_beurling_adjacent/2202.01837.html", "whole_work_read": false, "year": 2022, "id": "PAPER-PM64-B-GIVEN-ZERO", "arxiv": "2202.01837", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-GIVEN-ZERO"]}','Oscillation of the remainder term in the prime number theorem of Beurling, "caused by a given zeta-zero"','["Szilárd Gy. Révész"]',NULL,'2022',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2202.01837v3','https://arxiv.org/pdf/2202.01837v3','513da18b5e8c9054f5cce499ae5c32340aff60640b759b1ddd3a66eaee772f89','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-ZETA-FREQUENCIES','corpus/bibliography.jsonl',795,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "math/0410270", "audit_level": 0, "authors": ["Titus W. Hilberdink", "Michel L. Lapidus"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0410270v1", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "A power-saving ψ(x)=x+Oε(x^(α+ε)) implies continuation with a simple pole at 1 and zero-freeness on Re s>α. Conversely continuation and zero-freeness yield the same error given uniform subpower growth of the logarithmic derivative in smaller half-planes.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-ZETA-FREQUENCIES", "pdf_pages": 31, "provider_identity_only_ids": ["CAND-16318A72701E"], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §2.1 Theorem 2.1 and §2.2 Theorem 2.2", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Precisely locates a missing control in transferring zero-free contours to Beurling prime sums. Close real norms are possible, and omitting the log-derivative growth hypothesis would overstate the converse.", "source_locator": "§2.1 Theorem 2.1 and §2.2 Theorem 2.2", "source_path": "sources/prime64_beurling_adjacent/math_0410270.pdf", "source_sha256": "34fe75bc30bbcc68f8d94ddc9d9e7ab84d62a41e50924475ccc5d7aaaad22f08", "source_url": "https://arxiv.org/pdf/math/0410270v1", "substantive_reading": false, "title": "Beurling Zeta Functions, Generalised Primes, and Fractal Membranes", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:math/0410270v1", "version_date": "2004-10-11", "version_receipt": "sources/prime64_beurling_adjacent/math_0410270.html", "whole_work_read": false, "year": 2004, "id": "PAPER-PM64-B-ZETA-FREQUENCIES", "arxiv": "math/0410270", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-ZETA-FREQUENCIES"]}','Beurling Zeta Functions, Generalised Primes, and Fractal Membranes','["Titus W. Hilberdink", "Michel L. Lapidus"]',NULL,'2004',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0410270v1','https://arxiv.org/pdf/math/0410270v1','34fe75bc30bbcc68f8d94ddc9d9e7ab84d62a41e50924475ccc5d7aaaad22f08','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-INGHAM-MAP','corpus/bibliography.jsonl',796,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2207.00665", "audit_level": 0, "authors": ["Szilárd Gy. Révész"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2207.00665v2", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "Axiom A and a zero-free region Re s>1−η(|t|) yield Δ_P(x)=O(x exp(−(1−ε)ωη(x))), where ωη(x)=inf_{t≥1}(η(t)log x+log t). Infinitely many zeros in that region with η(e^v) convex give the stated Ω counterpart with 1+ε.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-INGHAM-MAP", "pdf_pages": 29, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 equations (11)–(12) and Theorems 5–6", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "A forward/inverse transfer that preserves rather than hides the regularity hypothesis on the boundary. It bounds the order of prime error, without identifying a particular line zero or uniform zero-phase coefficients.", "source_locator": "§1 equations (11)–(12) and Theorems 5–6", "source_path": "sources/prime64_beurling_adjacent/2207.00665.pdf", "source_sha256": "9c00d0f7d91e003845a3215a033bce95b2636c8aa812d176d34eac9ab85b08f0", "source_url": "https://arxiv.org/pdf/2207.00665v2", "substantive_reading": false, "title": "The method of Pintz for the Ingham question about the connection of distribution of ζ-zeros and order of the error in the PNT in the Beurling context", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2207.00665v2", "version_date": "2023-02-21", "version_receipt": "sources/prime64_beurling_adjacent/2207.00665.html", "whole_work_read": false, "year": 2023, "id": "PAPER-PM64-B-INGHAM-MAP", "arxiv": "2207.00665", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-INGHAM-MAP"]}','The method of Pintz for the Ingham question about the connection of distribution of ζ-zeros and order of the error in the PNT in the Beurling context','["Szilárd Gy. Révész"]',NULL,'2023',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2207.00665v2','https://arxiv.org/pdf/2207.00665v2','9c00d0f7d91e003845a3215a033bce95b2636c8aa812d176d34eac9ab85b08f0','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-EXPLICIT-DENSITY','corpus/bibliography.jsonl',797,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "2209.01689", "audit_level": 0, "authors": ["Szilárd Gy. Révész"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2209.01689v3", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "Under Axiom A alone the count at σ>(1+θ)/2 satisfies N(σ,T)≤1000(A+κ)^4 T^(12(1−σ)/(1−θ))(log T)^5/[(1−θ)^3(1−σ)^4] beyond an explicitly parameter-dependent threshold.", "novelty_claim": false, "paper_id": "PAPER-PM64-B-EXPLICIT-DENSITY", "pdf_pages": 21, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §2 Theorem 1, equation (12)", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Supplies a checkable right-slab tail count without an approximate functional equation. It is numerically weaker than later exponents and is not a local derivative sum or a zero-free conclusion.", "source_locator": "§2 Theorem 1, equation (12)", "source_path": "sources/prime64_beurling_adjacent/2209.01689.pdf", "source_sha256": "41376e59e7d86407849059acf5c123ea196600bb9b40f0f773a1f3e1490d4ac6", "source_url": "https://arxiv.org/pdf/2209.01689v3", "substantive_reading": false, "title": "The Carlson-type zero-density theorem for the Beurling zeta function", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2209.01689v3", "version_date": "2024-11-12", "version_receipt": "sources/prime64_beurling_adjacent/2209.01689.html", "whole_work_read": false, "year": 2024, "id": "PAPER-PM64-B-EXPLICIT-DENSITY", "arxiv": "2209.01689", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-EXPLICIT-DENSITY"]}','The Carlson-type zero-density theorem for the Beurling zeta function','["Szilárd Gy. Révész"]',NULL,'2024',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2209.01689v3','https://arxiv.org/pdf/2209.01689v3','41376e59e7d86407849059acf5c123ea196600bb9b40f0f773a1f3e1490d4ac6','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-B-PSEUDOFUNCTION','corpus/bibliography.jsonl',798,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Beurling systems and Mellin tools", "arxiv_id": "1604.05069", "audit_level": 0, "authors": ["Gregory Debruyne", "Jasson Vindas"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1604.05069v2", "doi": "10.1007/s11854-019-0045-3", "full_text_accessed": true, "language": "English", "main_result": "For a slowly decreasing function supported on the positive half-line with convergent Laplace transform, local pseudofunction boundary behavior of the remainder after specified poles and log powers yields explicit linear, oscillatory and power-log asymptotic terms plus o(1).", "novelty_claim": false, "paper_id": "PAPER-PM64-B-PSEUDOFUNCTION", "pdf_pages": 30, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Theorem 1.3(i) and §2 definitions", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "A candidate transfer from Mellin singularities to real arithmetic asymptotics. Requires the one-sided slowly-decreasing premise and the distributional boundary remainder; sharp pole models or analytic continuation alone do not check either.", "source_locator": "§1 Theorem 1.3(i) and §2 definitions", "source_path": "sources/prime64_beurling_adjacent/1604.05069.pdf", "source_sha256": "12d464b46a730ab8b5c5763ced370eefb4d90906be7c136a5ddfcbedd7a9d978", "source_url": "https://arxiv.org/pdf/1604.05069v2", "substantive_reading": false, "title": "Complex Tauberian theorems for Laplace transforms with local pseudofunction boundary behavior", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1604.05069v2", "version_date": "2016-11-11", "version_receipt": "sources/prime64_beurling_adjacent/1604.05069.html", "whole_work_read": false, "year": 2016, "id": "PAPER-PM64-B-PSEUDOFUNCTION", "arxiv": "1604.05069", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-B-PSEUDOFUNCTION"]}','Complex Tauberian theorems for Laplace transforms with local pseudofunction boundary behavior','["Gregory Debruyne", "Jasson Vindas"]',NULL,'2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1604.05069v2','https://arxiv.org/pdf/1604.05069v2','12d464b46a730ab8b5c5763ced370eefb4d90906be7c136a5ddfcbedd7a9d978','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-M-ALMOST-SCALES','corpus/bibliography.jsonl',799,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "multiplicative orthogonality", "arxiv_id": "1809.02518", "audit_level": 0, "authors": ["Terence Tao", "Joni Teräväinen"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1809.02518v2", "doi": "10.2140/ant.2019.13.2103", "full_text_accessed": true, "language": "English", "main_result": "Unweighted fixed-shift correlations are structured in logarithmic scale mean, allowing a twisted character n^{it} in the obstruction. Odd-order and binary Chowla for distinct fixed shifts hold outside a set of logarithmic density zero.", "novelty_claim": false, "paper_id": "PAPER-PM64-M-ALMOST-SCALES", "pdf_pages": 48, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Theorem 1.7 and Corollaries 1.13–1.14", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Tracks the precise loss in switching from weighted correlations to ordinary averages. A logarithmically negligible scale set can still contain every chosen approximation scale, so deterministic finite-N array control requires a different argument.", "source_locator": "§1 Theorem 1.7 and Corollaries 1.13–1.14", "source_path": "sources/prime64_beurling_adjacent/1809.02518.pdf", "source_sha256": "488b266bdf62adf9da8759717646b534339a5ac86b519072a3e370735fb01608", "source_url": "https://arxiv.org/pdf/1809.02518v2", "substantive_reading": false, "title": "The structure of correlations of multiplicative functions at almost all scales, with applications to the Chowla and Elliott conjectures", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1809.02518v2", "version_date": "2019-06-26", "version_receipt": "sources/prime64_beurling_adjacent/1809.02518.html", "whole_work_read": false, "year": 2019, "id": "PAPER-PM64-M-ALMOST-SCALES", "arxiv": "1809.02518", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-M-ALMOST-SCALES"]}','The structure of correlations of multiplicative functions at almost all scales, with applications to the Chowla and Elliott conjectures','["Terence Tao", "Joni Teräväinen"]',NULL,'2019',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1809.02518v2','https://arxiv.org/pdf/1809.02518v2','488b266bdf62adf9da8759717646b534339a5ac86b519072a3e370735fb01608','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-M-HALASZ-TRANSFER','corpus/bibliography.jsonl',800,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "multiplicative orthogonality", "arxiv_id": "1706.03749", "audit_level": 0, "authors": ["Andrew Granville", "Adam J Harper", "K. Soundararajan"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1706.03749v1", "doi": "10.1112/S0010437X18007522", "full_text_accessed": true, "language": "English", "main_result": "For fixed κ and multiplicative f in C(κ), whose logarithmic-derivative coefficients are bounded by κΛ, a weighted integral of the maximum of F(1+σ+it)/(1+σ+it) controls Σf(n). Corollary 1.2 gives the (1+M)e^−M suppression from the single-line maximum.", "novelty_claim": false, "paper_id": "PAPER-PM64-M-HALASZ-TRANSFER", "pdf_pages": 36, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Theorem 1.1, Corollary 1.2, and Theorem 1.3", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "An exact near-one-line bridge between phase selection and arithmetic sums akin to the Dong localization. Verifying the C(κ) bound and near-one-line maximum is essential, and neither yields critical-line derivative norm control automatically.", "source_locator": "§1 Theorem 1.1, Corollary 1.2, and Theorem 1.3", "source_path": "sources/prime64_beurling_adjacent/1706.03749.pdf", "source_sha256": "f0e172b6d6a89bfda96c5b4f264641509742030a7567cc9f0ae9815dccde7d06", "source_url": "https://arxiv.org/pdf/1706.03749v1", "substantive_reading": false, "title": "A new proof of Halász''s Theorem, and its consequences", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1706.03749v1", "version_date": "2017-06-12", "version_receipt": "sources/prime64_beurling_adjacent/1706.03749.html", "whole_work_read": false, "year": 2017, "id": "PAPER-PM64-M-HALASZ-TRANSFER", "arxiv": "1706.03749", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-M-HALASZ-TRANSFER"]}','A new proof of Halász''s Theorem, and its consequences','["Andrew Granville", "Adam J Harper", "K. Soundararajan"]',NULL,'2017',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1706.03749v1','https://arxiv.org/pdf/1706.03749v1','f0e172b6d6a89bfda96c5b4f264641509742030a7567cc9f0ae9815dccde7d06','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-M-EFFECTIVE-TWO','corpus/bibliography.jsonl',801,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "multiplicative orthogonality", "arxiv_id": "2609.28526", "audit_level": 0, "authors": ["Scott D. Hughes"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2609.28526v1", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "For admissible independent affine forms and g₁,g₂∈{μ,λ}, claims an effective logarithmic two-point bound ε log ω for x≥ω≥exp₄(CBε^−2), with B from the coefficients. This is a source-stated arXiv theorem.", "novelty_claim": false, "paper_id": "PAPER-PM64-M-EFFECTIVE-TWO", "pdf_pages": 29, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Definition 1.1 and Theorems 1.2–1.3", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Useful benchmark for the cost of a genuinely uniform window estimate. Even on its source-stated hypotheses the tower threshold is not a practical finite-N certificate and controls a scalar two-point correlation, not adaptive weighted Gram errors.", "source_locator": "§1 Definition 1.1 and Theorems 1.2–1.3", "source_path": "sources/prime64_beurling_adjacent/2609.28526.pdf", "source_sha256": "a54f900da7c070d37ac67cae962b8f67c22ea993e2f8d0cfaf48b98011051467", "source_url": "https://arxiv.org/pdf/2609.28526v1", "substantive_reading": false, "title": "Effective logarithmic two-point Chowla bounds in every window", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:2609.28526v1", "version_date": "2026-09-22", "version_receipt": "sources/prime64_beurling_adjacent/2609.28526.html", "whole_work_read": false, "year": 2026, "id": "PAPER-PM64-M-EFFECTIVE-TWO", "arxiv": "2609.28526", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-M-EFFECTIVE-TWO"]}','Effective logarithmic two-point Chowla bounds in every window','["Scott D. Hughes"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2609.28526v1','https://arxiv.org/pdf/2609.28526v1','a54f900da7c070d37ac67cae962b8f67c22ea993e2f8d0cfaf48b98011051467','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-M-SARNAK-ERGODIC','corpus/bibliography.jsonl',802,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "multiplicative orthogonality", "arxiv_id": "1708.00677", "audit_level": 0, "authors": ["Nikos Frantzikinakis", "Bernard Host"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1708.00677v4", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "For a zero-topological-entropy system with at most countably many ergodic invariant measures, every orbit''s continuous observable has zero logarithmically averaged Möbius and Liouville correlation.", "novelty_claim": false, "paper_id": "PAPER-PM64-M-SARNAK-ERGODIC", "pdf_pages": 46, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §§1–2, Theorems 1.1, 1.3 and 1.6", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "The framework could handle a fixed deterministic test sequence only after constructing its dynamical model and checking the entropy and ergodic-measure hypotheses. It has no bound on growing families of truncation test vectors.", "source_locator": "§§1–2, Theorems 1.1, 1.3 and 1.6", "source_path": "sources/prime64_beurling_adjacent/1708.00677.pdf", "source_sha256": "68a33b6885e55277f8966957495257103fc3352c7592de61ed17654bc6e1ee2f", "source_url": "https://arxiv.org/pdf/1708.00677v4", "substantive_reading": false, "title": "The logarithmic Sarnak conjecture for ergodic weights", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1708.00677v4", "version_date": "2019-02-02", "version_receipt": "sources/prime64_beurling_adjacent/1708.00677.html", "whole_work_read": false, "year": 2019, "id": "PAPER-PM64-M-SARNAK-ERGODIC", "arxiv": "1708.00677", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-M-SARNAK-ERGODIC"]}','The logarithmic Sarnak conjecture for ergodic weights','["Nikos Frantzikinakis", "Bernard Host"]',NULL,'2019',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1708.00677v4','https://arxiv.org/pdf/1708.00677v4','68a33b6885e55277f8966957495257103fc3352c7592de61ed17654bc6e1ee2f','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-M-FURSTENBERG','corpus/bibliography.jsonl',803,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "multiplicative orthogonality", "arxiv_id": "1804.08556", "audit_level": 0, "authors": ["Nikos Frantzikinakis", "Bernard Host"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1804.08556v3", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "For bounded multiplicative functions a joint logarithmic Furstenberg system is a factor of a system with no irrational spectrum and nilsystem–Bernoulli ergodic components. Theorem 1.3 gives orthogonality to suitable zero-entropy, totally ergodic logarithmic test systems.", "novelty_claim": false, "paper_id": "PAPER-PM64-M-FURSTENBERG", "pdf_pages": 20, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Theorems 1.3 and 1.5", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "A test for when a deterministic sequence has the kind of irrational phase or ergodicity needed for correlation arguments. These sequence-shift factors are distinct from the compact group indexed by rational logarithms in the zero-tail result.", "source_locator": "§1 Theorems 1.3 and 1.5", "source_path": "sources/prime64_beurling_adjacent/1804.08556.pdf", "source_sha256": "9c7bb508fce143bc18f181f041e385d359f1be71d0e0b058d28f883b8bc612e5", "source_url": "https://arxiv.org/pdf/1804.08556v3", "substantive_reading": false, "title": "Furstenberg systems of bounded multiplicative functions and applications", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1804.08556v3", "version_date": "2019-03-04", "version_receipt": "sources/prime64_beurling_adjacent/1804.08556.html", "whole_work_read": false, "year": 2019, "id": "PAPER-PM64-M-FURSTENBERG", "arxiv": "1804.08556", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-M-FURSTENBERG"]}','Furstenberg systems of bounded multiplicative functions and applications','["Nikos Frantzikinakis", "Bernard Host"]',NULL,'2019',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1804.08556v3','https://arxiv.org/pdf/1804.08556v3','9c7bb508fce143bc18f181f041e385d359f1be71d0e0b058d28f883b8bc612e5','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-M-GOWERS','corpus/bibliography.jsonl',804,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "multiplicative orthogonality", "arxiv_id": "1403.0945", "audit_level": 0, "authors": ["Nikos Frantzikinakis", "Bernard Host"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1403.0945v2", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "Bounded aperiodic multiplicative functions, meaning zero mean on each infinite arithmetic progression, have vanishing U^s[N] for every fixed s≥2, by a decomposition into a structured component and a uniform component.", "novelty_claim": false, "paper_id": "PAPER-PM64-M-GOWERS", "pdf_pages": 80, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §§1–2, Theorems 1.1 and 2.5", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Explains how to handle a fixed-complexity nilsequence test on integer inputs. The existing rational-log Fourier inverse problem does not provide a nilsequence realization or complexity uniformity, so this is not an automatic coefficient bound.", "source_locator": "§§1–2, Theorems 1.1 and 2.5", "source_path": "sources/prime64_beurling_adjacent/1403.0945.pdf", "source_sha256": "5d4f38a1c4fdd46d1593160bb841e27677d01e3c0328d9938db4882b227f93ee", "source_url": "https://arxiv.org/pdf/1403.0945v2", "substantive_reading": false, "title": "Higher order Fourier analysis of multiplicative functions and applications", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1403.0945v2", "version_date": "2016-01-26", "version_receipt": "sources/prime64_beurling_adjacent/1403.0945.html", "whole_work_read": false, "year": 2016, "id": "PAPER-PM64-M-GOWERS", "arxiv": "1403.0945", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-M-GOWERS"]}','Higher order Fourier analysis of multiplicative functions and applications','["Nikos Frantzikinakis", "Bernard Host"]',NULL,'2016',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1403.0945v2','https://arxiv.org/pdf/1403.0945v2','5d4f38a1c4fdd46d1593160bb841e27677d01e3c0328d9938db4882b227f93ee','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-M-KATAI-SET','corpus/bibliography.jsonl',805,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "multiplicative orthogonality", "arxiv_id": "1705.07322", "audit_level": 0, "authors": ["V. Bergelson", "J. Kułaga-Przymus", "M. Lemańczyk", "F. K. Richter"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1705.07322v2", "doi": "10.3934/dcds.2019108", "full_text_accessed": true, "language": "English", "main_result": "When a bounded sequence''s distinct-prime dilation correlations sum to o(x) for every fixed pair, it is asymptotically orthogonal to indicators of sets in the three specified multiplicative level-set classes. Counterexample limits arbitrary level sets.", "novelty_claim": false, "paper_id": "PAPER-PM64-M-KATAI-SET", "pdf_pages": 32, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 Theorem A, Definitions 1.3 and Corollary B", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "The dossier''s dilations make this an exact possible bridge if the p,q tests can be proved for the concrete sequence. A bound on original inner products without the dilated pair correlations does not verify the criterion.", "source_locator": "§1 Theorem A, Definitions 1.3 and Corollary B", "source_path": "sources/prime64_beurling_adjacent/1705.07322.pdf", "source_sha256": "d8b1735b847ef66cf432967bf59f30fcc4c316b05f0523a5d83f24a5608dd948", "source_url": "https://arxiv.org/pdf/1705.07322v2", "substantive_reading": false, "title": "A generalization of Kátai''s orthogonality criterion with applications", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1705.07322v2", "version_date": "2017-08-08", "version_receipt": "sources/prime64_beurling_adjacent/1705.07322.html", "whole_work_read": false, "year": 2017, "id": "PAPER-PM64-M-KATAI-SET", "arxiv": "1705.07322", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-M-KATAI-SET"]}','A generalization of Kátai''s orthogonality criterion with applications','["V. Bergelson", "J. Kułaga-Przymus", "M. Lemańczyk", "F. K. Richter"]',NULL,'2017',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1705.07322v2','https://arxiv.org/pdf/1705.07322v2','d8b1735b847ef66cf432967bf59f30fcc4c316b05f0523a5d83f24a5608dd948','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-R-SIEVE-RESTRICTION','corpus/bibliography.jsonl',806,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "restriction and mean values", "arxiv_id": "math/0405581", "audit_level": 0, "authors": ["Ben Green", "Terence Tao"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/math/0405581v2", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "For the enveloping-sieve weight β_R of a product of admissible integer linear forms, 1≪R≪N^(1/10) and 1<q<2, a finite cyclic Fourier transform satisfies a weighted L² bound from ℓ^q with constants in q and form count.", "novelty_claim": false, "paper_id": "PAPER-PM64-R-SIEVE-RESTRICTION", "pdf_pages": 36, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §§3–4, Propositions 3.1, 4.1 and 4.2", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Controls additive frequencies for a prime-support majorant. Transferring to t log n requires an explicit finite-frequency embedding and multiplicative collision bound; an additive majorant cannot be silently used in the tapered Mellin Gram matrix.", "source_locator": "§§3–4, Propositions 3.1, 4.1 and 4.2", "source_path": "sources/prime64_beurling_adjacent/math_0405581.pdf", "source_sha256": "4f8c5a757831ae583e0fbc0f205be9b07ae304d138e60fe131697ca7a9a1ced1", "source_url": "https://arxiv.org/pdf/math/0405581v2", "substantive_reading": false, "title": "Restriction theory of the Selberg sieve, with applications", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:math/0405581v2", "version_date": "2005-05-10", "version_receipt": "sources/prime64_beurling_adjacent/math_0405581.html", "whole_work_read": false, "year": 2005, "id": "PAPER-PM64-R-SIEVE-RESTRICTION", "arxiv": "math/0405581", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-R-SIEVE-RESTRICTION"]}','Restriction theory of the Selberg sieve, with applications','["Ben Green", "Terence Tao"]',NULL,'2005',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:math/0405581v2','https://arxiv.org/pdf/math/0405581v2','4f8c5a757831ae583e0fbc0f205be9b07ae304d138e60fe131697ca7a9a1ced1','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-R-MEAN-FLUCT','corpus/bibliography.jsonl',807,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "restriction and mean values", "arxiv_id": "1212.0660", "audit_level": 0, "authors": ["Aleksandar Ivić"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1212.0660v2", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "For T^(2/3+ε)≤H≤T the integral of E*(t)^2, the squared difference between the zeta second-moment error and a modified divisor error, is ≫H T^(1/3)log³T. Theorem 2 bounds the integrated residual R in specified ranges.", "novelty_claim": false, "paper_id": "PAPER-PM64-R-MEAN-FLUCT", "pdf_pages": 14, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §1 equations (1.2), (1.3), and Theorems 1–2", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "A sharp warning about treating local continuous ζ mean-square errors as flat in dyadic Hardy bounds. E* is an error observable, not the derivative zero measure, and the lower bound excludes rough extrapolation of the smooth main term.", "source_locator": "§1 equations (1.2), (1.3), and Theorems 1–2", "source_path": "sources/prime64_beurling_adjacent/1212.0660.pdf", "source_sha256": "93533dfdc3366750fa9419fb902dd2986f1652c769979c8b9c95a7e668bcaea3", "source_url": "https://arxiv.org/pdf/1212.0660v2", "substantive_reading": false, "title": "On some mean square estimates for the zeta-function in short intervals", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1212.0660v2", "version_date": "2012-12-12", "version_receipt": "sources/prime64_beurling_adjacent/1212.0660.html", "whole_work_read": false, "year": 2012, "id": "PAPER-PM64-R-MEAN-FLUCT", "arxiv": "1212.0660", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-R-MEAN-FLUCT"]}','On some mean square estimates for the zeta-function in short intervals','["Aleksandar Ivić"]',NULL,'2012',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1212.0660v2','https://arxiv.org/pdf/1212.0660v2','93533dfdc3366750fa9419fb902dd2986f1652c769979c8b9c95a7e668bcaea3','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-R-WRONSKIAN','corpus/bibliography.jsonl',808,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "restriction and mean values", "arxiv_id": "1406.7862", "audit_level": 0, "authors": ["Jean Bourgain"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1406.7862v1", "doi": null, "full_text_accessed": true, "language": "English", "main_result": "For n≥3, nonvanishing Wronskian of the listed third derivatives and macroscopically separated index intervals yield a multilinear moment bound at p=2(n+1)/(n−1), with a coefficient form. Spacing-count estimates are proved only in stated δ-ranges.", "novelty_claim": false, "paper_id": "PAPER-PM64-R-WRONSKIAN", "pdf_pages": 23, "provider_identity_only_ids": [], "publication_status": "verified arXiv manifestation", "read_scope": "Targeted reading. §3 Theorem 1 and Remark (i), §4 Theorem 9", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "Suggests a way to bound off-diagonal frequency collisions after validating a precise phase-curve lift. The multilinear separation and δ regimes are substantive and cannot be read as a generic cluster bound near coincident zero ordinates.", "source_locator": "§3 Theorem 1 and Remark (i), §4 Theorem 9", "source_path": "sources/prime64_beurling_adjacent/1406.7862.pdf", "source_sha256": "71eee84dc535ffc97d789e764bf222e1ed470ff6b35c40799093ba6f602f0b48", "source_url": "https://arxiv.org/pdf/1406.7862v1", "substantive_reading": false, "title": "Decoupling inequalities and some mean-value theorems", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "arXiv", "version": "arXiv:1406.7862v1", "version_date": "2014-06-30", "version_receipt": "sources/prime64_beurling_adjacent/1406.7862.html", "whole_work_read": false, "year": 2014, "id": "PAPER-PM64-R-WRONSKIAN", "arxiv": "1406.7862", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-R-WRONSKIAN"]}','Decoupling inequalities and some mean-value theorems','["Jean Bourgain"]',NULL,'2014',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1406.7862v1','https://arxiv.org/pdf/1406.7862v1','71eee84dc535ffc97d789e764bf222e1ed470ff6b35c40799093ba6f602f0b48','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-PM64-R-MONOMIAL-SPACING','corpus/bibliography.jsonl',809,'full_text_accessed','papers/prime64_beurling_adjacent_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "restriction and mean values", "arxiv_id": null, "audit_level": 0, "authors": ["Olivier Robert", "Patrick Sargos"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1515/crelle.2006.012", "doi": "10.1515/crelle.2006.012", "full_text_accessed": true, "language": "English", "main_result": "For fixed real α≠0,1 and M≥2, the number of quadruples of integers in (M,2M] with |m₁^α+m₂^α−m₃^α−m₄^α|≤δM^α is ≪α,ε M^(2+ε)+δM^(4+ε) for δ>0.", "novelty_claim": false, "paper_id": "PAPER-PM64-R-MONOMIAL-SPACING", "pdf_pages": 20, "provider_identity_only_ids": ["CAND-0ED9B8F84203"], "publication_status": "journal version of record", "read_scope": "Targeted reading. §5 Theorem 2 and equations (5.1)–(5.2)", "record_path": "papers/prime64_beurling_adjacent_notes.md", "result_status": "Source-stated; no transfer to the ordinary critical-line problem is claimed.", "selection_reason": "A precise input to moment calculations with a curved monomial frequency. It does not automatically bound log-product collisions by α→0, because the exponent is fixed and the constants and normalization would need uniform control as curvature degenerates.", "source_locator": "§5 Theorem 2 and equations (5.1)–(5.2)", "source_path": "sources/prime64_beurling_adjacent/robert_sargos.pdf", "source_sha256": "9d4e54047488ed6b842e91302584b1c8bd07b7f8dd533493f2910652a7238373", "source_url": "https://perso.univ-st-etienne.fr/rool6510/robert-2006-crelle.pdf", "substantive_reading": false, "title": "Three-dimensional exponential sums with monomials", "track_file": "papers/prime64_beurling_adjacent_records.jsonl", "venue": "Journal für die reine und angewandte Mathematik", "version": "journal 591 (2006), 1–20", "version_date": null, "version_receipt": "sources/prime64_beurling_adjacent/robert_sargos_crossref.json", "whole_work_read": false, "year": 2006, "id": "PAPER-PM64-R-MONOMIAL-SPACING", "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-PM64-R-MONOMIAL-SPACING"]}','Three-dimensional exponential sums with monomials','["Olivier Robert", "Patrick Sargos"]',NULL,'2006',0,0,'selected_checkpoint_priority_work','full_text_accessed','journal 591 (2006), 1–20','https://perso.univ-st-etienne.fr/rool6510/robert-2006-crelle.pdf','9d4e54047488ed6b842e91302584b1c8bd07b7f8dd533493f2910652a7238373','papers/prime64_beurling_adjacent_notes.md','papers/prime64_beurling_adjacent_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AN79-HR-MOCK','corpus/bibliography.jsonl',810,'full_text_accessed','papers/PAPER-AN79-HR-MOCK.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "random matrices", "arxiv_id": "math/0206289", "audit_level": 0, "authors": ["C. P. Hughes", "Z. Rudnick"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1088/0305-4470/36/12/304", "doi": "10.1088/0305-4470/36/12/304", "full_text_accessed": true, "id": "PAPER-AN79-HR-MOCK", "language": "English", "main_result": "For the microscopic periodization of a Schwartz test f, Theorem 1 gives convergence of the first m ordinary Haar U(N) moments to Gaussian moments when supp(f̂) ⊆ [−2/m,2/m], with mean ∫f and variance ∫min(|u|,1)|f̂(u)|²du for real f. Theorem 2 takes even real f and gives the corresponding support windows [−1/m,1/m] for Sp(N), with N even, and (−1/m,1/m) for SO(N). Theorem 3 gives exact mixed trace moments under the separate total index bounds N+1 and N−1. Theorem 7 attributes the balanced Fourier cumulant estimate to Soshnikov.", "novelty_claim": false, "paper_id": "PAPER-AN79-HR-MOCK", "pdf_pages": 15, "publication_status": "published", "read_scope": "Targeted theorem and cumulant passages of the journal, compared to arXiv v1. Whole proofs unextracted.", "record_path": "papers/PAPER-AN79-HR-MOCK.md", "result_status": "Recorded primary theorem statements and their Fourier-window scope; no full proof or derivative-rooted transfer claimed.", "selected": true, "selection_reason": "Classical ordinary-Haar antecedent for finite Fourier-support moment windows. The derivative-rooted rank-two correction requires a separate argument.", "selection_status": "selected_checkpoint_priority_work", "source_locator": "Printed pp. 2919–2922, introduction and Theorems 1–3; p. 2926, Theorem 7", "source_path": "sources/prior_art82/hughes_rudnick_mock_journal.pdf", "source_sha256": "344e849fb291029f57057c9dc91b48fd677f6b1dc829404d98de474823ea5e1f", "source_url": "https://www.math.tau.ac.il/~rudnick/papers/a31204.pdf", "substantive_reading": false, "title": "Mock-Gaussian behaviour for linear statistics of classical compact groups", "track_file": "papers/prior_art82_records.jsonl", "transfer_hypothesis": "Classical ordinary-Haar antecedent for finite Fourier-support moment windows. The derivative-rooted rank-two correction requires a separate argument.", "venue": "Journal of Physics A: Mathematical and General 36(12), 2919–2932", "version": "2003 journal typeset article in author-hosted PDF with one unnumbered provider cover, 15 PDF pages", "whole_work_read": false, "year": 2003, "arxiv": "math/0206289", "original_access_status": "full_text_accessed", "original_selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AN79-HR-MOCK"]}','Mock-Gaussian behaviour for linear statistics of classical compact groups','["C. P. Hughes", "Z. Rudnick"]',NULL,'2003',0,0,'selected_checkpoint_priority_work','full_text_accessed','2003 journal typeset article in author-hosted PDF with one unnumbered provider cover, 15 PDF pages','https://www.math.tau.ac.il/~rudnick/papers/a31204.pdf','344e849fb291029f57057c9dc91b48fd677f6b1dc829404d98de474823ea5e1f','papers/PAPER-AN79-HR-MOCK.md','papers/prior_art82_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AN79-HR-ZETA','corpus/bibliography.jsonl',811,'full_text_accessed','audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zero statistics", "arxiv_id": "math/0208220", "audit_level": 3, "authors": ["Chris Hughes", "Zeév Rudnick"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1016/S1631-073X%2802%2902541-4", "doi": "10.1016/S1631-073X(02)02541-4", "full_text_accessed": true, "id": "PAPER-AN79-HR-ZETA", "language": "English", "main_result": "With real even f, smooth compact Fourier transform of strict radius sigma, m sigma/2<a and H=T^a, 0<a≤1, the oscillatory prime part has its finite Gaussian window for nonnegative unit-mass bandlimited w. The full statistic has the stated finite Gaussian moments if ∫f=0 or ∫w log^m(2+|u|)<infinity. The literal printed weight class alone is too broad.", "novelty_claim": false, "paper_id": "PAPER-AN79-HR-ZETA", "pdf_pages": 4, "publication_status": "published", "read_scope": "Complete four-page journal pinned and independently reconstructed; the separate nine-page arXiv v1 was also checked. The original oscillatory moment theorem survives the printed class. The full statistic needs the documented logarithmic-moment alternative and additive comparison.", "record_path": "papers/PAPER-AN79-HR-ZETA.md", "result_status": "Source-stated theorem. The literal weight-tail question and a Schwartz-weight qualification are pending independent director adjudication, not a verified source error.", "scope_qualification": "The cited note gives a translated band-limited density mixture with divergent log moment under the literally listed weight conditions and presents a sufficient Schwartz setting. Preserve this as an audit candidate separate from the source rendering.", "scope_qualification_status": "pending_review", "selected": true, "selection_reason": "The explicit formula contains the same prime logarithmic frequency but the theorem uses a different sampling law and smooth cutoff.", "selection_status": "selected_checkpoint_priority_work", "source_locator": "Printed pp. 668–670, Theorem 1.1, Lemmas 2.1–2.2, Proposition 2.3 and (2)–(6); title p. 667", "source_path": "sources/prior_art82/hughes_rudnick_zeta_journal.pdf", "source_sha256": "b4572e5bdbf3cf7e891a4128aeb3bb56d151f2b16d23f9e63a94b1a2d2c09139", "source_url": "https://archive.numdam.org/item/CRMATH_2002__335_8_667_0.pdf", "substantive_reading": true, "title": "Linear statistics for zeros of Riemann’s zeta function", "track_file": "papers/prior_art82_records.jsonl", "transfer_hypothesis": "The explicit formula contains the same prime logarithmic frequency but the theorem uses a different sampling law and smooth cutoff.", "venue": "Comptes Rendus Mathématique 335(8), 667–670", "version": "2002 journal typeset version, C. R. Math. 335(8), 667–670", "whole_work_read": true, "year": 2002, "arxiv": "math/0208220", "original_access_status": "full_text_accessed", "original_selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AN79-HR-ZETA"], "scope_update_history": [{"fields": {"version": "2002 journal typeset version, C. R. Math. 335(8), 667–670", "source_sha256": "b4572e5bdbf3cf7e891a4128aeb3bb56d151f2b16d23f9e63a94b1a2d2c09139", "audit_level": 3, "whole_work_read": true, "substantive_reading": true, "read_scope": "Complete four-page journal pinned and independently reconstructed; the separate nine-page arXiv v1 was also checked. The original oscillatory moment theorem survives the printed class. The full statistic needs the documented logarithmic-moment alternative and additive comparison.", "claim_verification_status": "Whole-work Level 3 for the exact journal version. One version-scoped missing-hypothesis finding and a valid repair. Finite moments without RH.", "main_result": "With real even f, smooth compact Fourier transform of strict radius sigma, m sigma/2<a and H=T^a, 0<a≤1, the oscillatory prime part has its finite Gaussian window for nonnegative unit-mass bandlimited w. The full statistic has the stated finite Gaussian moments if ∫f=0 or ∫w log^m(2+|u|)<infinity. The literal printed weight class alone is too broad.", "independent_whole_reading_reviews": ["audits/adversarial_reviews/analytic89_hr_whole_advocate.md", "audits/adversarial_reviews/weighted88_hr_whole_skeptic.md"], "additional_source_manifestation": {"version": "arXiv:math/0208220v1, nine pages", "source_sha256": "2225d590d97abd13a4b973bd3d936a7b07fb45a3296739438f8ce57f657cdebd", "scope": "Complete comparison by both independent reviewers; promotion pinned to journal."}}, "evidence": "audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md", "track_file": "quality/zzzzzzzz_round13_research_source_scope_updates.jsonl"}], "claim_verification_status": "Whole-work Level 3 for the exact journal version. One version-scoped missing-hypothesis finding and a valid repair. Finite moments without RH.", "independent_whole_reading_reviews": ["audits/adversarial_reviews/analytic89_hr_whole_advocate.md", "audits/adversarial_reviews/weighted88_hr_whole_skeptic.md"], "additional_source_manifestation": {"version": "arXiv:math/0208220v1, nine pages", "source_sha256": "2225d590d97abd13a4b973bd3d936a7b07fb45a3296739438f8ce57f657cdebd", "scope": "Complete comparison by both independent reviewers; promotion pinned to journal."}, "scope_update_evidence": "audits/adversarial_reviews/director_hughes_rudnick_whole_round13.md", "additional_scope_update_files": ["quality/zzzzzzzz_round13_research_source_scope_updates.jsonl"]}','Linear statistics for zeros of Riemann’s zeta function','["Chris Hughes", "Zeév Rudnick"]',NULL,'2002',3,1,'selected_checkpoint_priority_work','full_text_accessed','2002 journal typeset version, C. R. Math. 335(8), 667–670','https://archive.numdam.org/item/CRMATH_2002__335_8_667_0.pdf','b4572e5bdbf3cf7e891a4128aeb3bb56d151f2b16d23f9e63a94b1a2d2c09139','papers/PAPER-AN79-HR-ZETA.md','papers/prior_art82_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-AN79-MAJ-PW-PND','corpus/bibliography.jsonl',812,'full_text_accessed','papers/PAPER-AN79-MAJ-PW-PND.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "polynomial-normal transforms", "arxiv_id": null, "audit_level": 0, "authors": ["Monika Maj", "Zbigniew Pasternak-Winiarski"], "bibliographic_verified": true, "canonical_url": "https://www.ms.u-tokyo.ac.jp/journal/abstract_e/jms140402_e.html", "doi": null, "full_text_accessed": true, "id": "PAPER-AN79-MAJ-PW-PND", "language": "English", "main_result": "Propositions 8–9 give the polynomial-normal density/characteristic function equivalence under the normalized-density or actual-characteristic-function premise, with real location b and symmetric positive-definite precision A. The forward direction transforms a degree-2l polynomial times the nonsingular Gaussian density to a degree-2l polynomial times exp(ibtᵀ−tA⁻¹tᵀ/2). The converse assumes this product is a characteristic function and identifies its polynomial-normal density by Fourier uniqueness. Arbitrary polynomial factors need not give positive-definite transforms.", "novelty_claim": false, "paper_id": "PAPER-AN79-MAJ-PW-PND", "pdf_pages": 20, "publication_status": "published", "read_scope": "Targeted source reading of the definition and transform equivalence. Main decomposition proof unextracted.", "record_path": "papers/PAPER-AN79-MAJ-PW-PND.md", "result_status": "Targeted primary-source confirmation of the transform equivalence. Main decomposition theorem not audited.", "selected": true, "selection_reason": "Standard transform antecedent for testing a formal arithmetic Gaussian-polynomial continuation for positivity. Positive definiteness is a hypothesis of the converse.", "selection_status": "selected_checkpoint_priority_work", "source_locator": "Printed pp. 511–512 and 520–522, definition and Propositions 8–9", "source_path": "sources/prior_art82/polynomial_normal_tokyo_2007.pdf", "source_sha256": "d771e1ae496c50fa00cbf77b33210ca3c5c4c172ff052747a901f969fb8ce05e", "source_url": "https://www.ms.u-tokyo.ac.jp/journal/pdf/jms140402.pdf", "substantive_reading": false, "title": "Composition and Decomposition of Multidimensional Polynomial-Normal Distribution", "track_file": "papers/prior_art82_records.jsonl", "transfer_hypothesis": "Standard transform antecedent for testing a formal arithmetic Gaussian-polynomial continuation for positivity. Positive definiteness is a hypothesis of the converse.", "venue": "Journal of Mathematical Sciences, The University of Tokyo 14(4), 511–530", "version": "Journal typeset version", "whole_work_read": false, "year": 2007, "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-AN79-MAJ-PW-PND"]}','Composition and Decomposition of Multidimensional Polynomial-Normal Distribution','["Monika Maj", "Zbigniew Pasternak-Winiarski"]',NULL,'2007',0,0,'selected_checkpoint_priority_work','full_text_accessed','Journal typeset version','https://www.ms.u-tokyo.ac.jp/journal/pdf/jms140402.pdf','d771e1ae496c50fa00cbf77b33210ca3c5c4c172ff052747a901f969fb8ce05e','papers/PAPER-AN79-MAJ-PW-PND.md','papers/prior_art82_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-GEO82-MANGOLDT1905','corpus/bibliography.jsonl',813,'full_text_accessed','audits/adversarial_reviews/geometry85_mangoldt1905_whole.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "zero-counting", "arxiv_id": null, "audit_level": 1, "authors": ["Hans von Mangoldt"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1007/BF01447494", "doi": "10.1007/BF01447494", "full_text_accessed": true, "id": "PAPER-GEO82-MANGOLDT1905", "language": "German", "main_result": "For the total zero count of Riemann’s completed xi as a function of t, the opening states an additive O(log T) bound about (T/(2π))log(T/(2π))−T/(2π) for T>28.558, sharpening the additive O(log² T) bound recalled from the same author’s 1895 p. 266. The count is not a count of critical-line zeros alone.", "novelty_claim": false, "paper_id": "PAPER-GEO82-MANGOLDT1905", "pdf_pages": 20, "publication_status": "published", "read_scope": "Complete original German article, nineteen printed pages plus archive cover, read and reconstructed by the historical agent. Adjacent-argument kernel, one-sided maximum, multiplicities and endpoints independently checked at their source passages. Original decimal bound retained as published rather than fully recertified; no whole-work Level 2/3 promotion.", "record_path": "papers/PAPER-GEO82-MANGOLDT1905.md", "result_status": "Primary theorem statement only; no whole-proof or exact boundary convention claim.", "selected": true, "selection_reason": "Primary source of the sharper logarithmic error scale for the classical total zero count, separating the 1859 sketch, 1895 count and 1905 improvement.", "selection_status": "selected_checkpoint_priority_work", "source_locator": "Printed p. 1 (PDF p. 2), opening theorem and footnote citing the 1895 count on p. 266", "source_path": "sources/prior_art82/mangoldt1905_gdz.pdf", "source_sha256": "7dd69d353ee6a173cc856131fc1bb07e222e1e2f99b138b4b251d0998d11a5ec", "source_url": "https://gdz.sub.uni-goettingen.de/download/pdf/PPN235181684_0060/LOG_0007.pdf", "substantive_reading": true, "title": "Zur Verteilung der Nullstellen der Riemannschen Funktion ξ(t)", "track_file": "papers/prior_art82_records.jsonl", "transfer_hypothesis": "Classical total zero count supplies an analytic input for local height-ordered estimates. It does not establish the number of critical-line zeros or RH.", "venue": "Mathematische Annalen 60, 1–19", "version": "1905 original German journal scan, GDZ PPN235181684_0060, LOG_0007; one provider cover followed by printed pp. 1–19", "whole_work_read": true, "year": 1905, "arxiv": null, "original_access_status": "full_text_accessed", "original_selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-GEO82-MANGOLDT1905"], "scope_update_history": [{"fields": {"audit_level": 1, "whole_work_read": true, "substantive_reading": true, "read_scope": "Complete original German article, nineteen printed pages plus archive cover, read and reconstructed by the historical agent. Adjacent-argument kernel, one-sided maximum, multiplicities and endpoints independently checked at their source passages. Original decimal bound retained as published rather than fully recertified; no whole-work Level 2/3 promotion.", "claim_verification_status": "Complete Level 1 reading. The published O(log T) count and the scoped kernel comparisons retain separate evidence. The improved historical coefficient is not a modern best bound or weighted-tail advance."}, "evidence": "audits/adversarial_reviews/geometry85_mangoldt1905_whole.md", "track_file": "quality/zzzzzzzz_round13_source_scope_updates.jsonl"}], "claim_verification_status": "Complete Level 1 reading. The published O(log T) count and the scoped kernel comparisons retain separate evidence. The improved historical coefficient is not a modern best bound or weighted-tail advance.", "scope_update_evidence": "audits/adversarial_reviews/geometry85_mangoldt1905_whole.md", "additional_scope_update_files": ["quality/zzzzzzzz_round13_source_scope_updates.jsonl"]}','Zur Verteilung der Nullstellen der Riemannschen Funktion ξ(t)','["Hans von Mangoldt"]',NULL,'1905',1,1,'selected_checkpoint_priority_work','full_text_accessed','1905 original German journal scan, GDZ PPN235181684_0060, LOG_0007; one provider cover followed by printed pp. 1–19','https://gdz.sub.uni-goettingen.de/download/pdf/PPN235181684_0060/LOG_0007.pdf','7dd69d353ee6a173cc856131fc1bb07e222e1e2f99b138b4b251d0998d11a5ec','papers/PAPER-GEO82-MANGOLDT1905.md','papers/prior_art82_records.jsonl');
