INSERT INTO "papers" VALUES('PAPER-REL70-1504-01524','corpus/bibliography.jsonl',850,'full_text_accessed','quality/pending_round12/release70_positivity_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Entire functions and real-rooted approximation", "arxiv_id": "1504.01524", "audit_level": 1, "authors": ["Kostov, Vladimir Petrov"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/1504.01524", "doi": null, "full_text_accessed": true, "main_result": "For fixed 0<|q|<1 the distant zeros approach −q^(−k), the normalized canonical product has genus zero, and only finitely many zeros can be multiple. For positive q from the j-th spectral transition excluded to the (j+1)-st included, exactly j nonreal conjugate pairs are factored away to leave an LP-I factor.", "novelty_claim": false, "paper_id": "PAPER-REL70-1504-01524", "pdf_pages": 6, "publication_status": "Verified accessed manifestation", "read_scope": "All six PDF pages, §§1–2, Theorem 1(1)–(5), remarks and references", "record_path": "quality/pending_round12/release70_positivity_notes.md", "result_status": "Source-stated scope. No independent theorem certification or RH transfer.", "selection_reason": "Compare growth, coefficient, root-location and approximation assumptions with the hypotheses required for ζ or ξ.", "source_locator": "All six PDF pages, §§1–2, Theorem 1(1)–(5), remarks and references", "source_path": "sources/release70_positivity/1504.01524.pdf", "source_sha256": "1015ad5b953cc3569b1c586c1dd9d299b5f5a56c616ef4c6e291dc89df8a3eaf", "source_url": "https://arxiv.org/pdf/1504.01524v1", "substantive_reading": true, "title": "A property of a partial theta function", "topic": "Entire functions and real-rooted approximation", "track_file": "papers/release70_positivity_records.jsonl", "transfer_hypothesis": "Compare growth, coefficient, root-location and approximation assumptions with the hypotheses required for ζ or ξ.", "venue": "arXiv", "versio