INSERT INTO "papers" VALUES('PAPER-REL70-1106-6262','corpus/bibliography.jsonl',851,'full_text_accessed','quality/pending_round12/release70_positivity_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Entire functions and real-rooted approximation", "arxiv_id": "1106.6262", "audit_level": 0, "authors": ["Kostov, Vladimir Petrov", "Shapiro, Boris"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1215/00127094-2087264", "doi": "10.1215/00127094-2087264", "full_text_accessed": true, "main_result": "For positive-coefficient polynomials normalized by constant term 1 whose every initial section is real-rooted, the coefficient-quotient infimum m_i is at least 3. It is attained in degree i+1 by p_(i+1), unique within that normalized class up to scaling x. The equivalent monic statement uses reversal and leading sections.", "novelty_claim": false, "paper_id": "PAPER-REL70-1106-6262", "pdf_pages": 24, "publication_status": "Verified accessed manifestation", "read_scope": "Theorems 1–2; section-hyperbolic definition and monic reversal, pp. 1–3", "record_path": "quality/pending_round12/release70_positivity_notes.md", "result_status": "Cited statement checked at selection scope. Full theorem proof and any hypotheses beyond the cited passage remain unextracted.", "selection_reason": "Compare growth, coefficient, root-location and approximation assumptions with the hypotheses required for ζ or ξ.", "source_locator": "Theorems 1–2; section-hyperbolic definition and monic reversal, pp. 1–3", "source_path": "sources/release70_positivity/1106.6262.pdf", "source_sha256": "2feae2b4e23a848da8b7b9d618b7296af4321407b22557e6c32603cbe09ec005", "source_url": "https://arxiv.org/pdf/1106.6262v1", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "Hardy-Petrovitch-Hutchinson''s problem and partial theta function", "topic": "Entire functions and real-rooted approximation", "track_file": "papers/release70_positivity_records.jsonl", "transfer_hypothesis": "Compare growth, coefficient, root-location and approximation assumptions with the hypotheses required for ζ or ξ.", "venue": "arXiv", "version": "arXiv:1106.6262v1", "whole_work_read": false, "year": 2011, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/release70_positivity_records.jsonl", "id": "PAPER-REL70-1106-6262", "arxiv": "1106.6262", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-REL70-1106-6262"]}','Hardy-Petrovitch-Hutchinson''s problem and partial theta function','["Kostov, Vladimir Petrov", "Shapiro, Boris"]',NULL,'2011',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:1106.6262v1','https://arxiv.org/pdf/1106.6262v1','2feae2b4e23a848da8b7b9d618b7296af4321407b22557e6c32603cbe09ec005','quality/pending_round12/release70_positivity_notes.md','papers/release70_positivity_records.jsonl');
