INSERT INTO "papers" VALUES('PAPER-REL70-HASELGROVE','corpus/bibliography.jsonl',864,'primary_source_excerpt_accessed','quality/pending_round12/release70_positivity_notes.md','{"access_status": "primary_source_excerpt_accessed", "accessed_at": "2026-11-18", "area": "Sign conjectures, oscillation and spectral limits", "arxiv_id": null, "audit_level": 0, "authors": ["C. B. Haselgrove"], "bibliographic_dependence": "PAPER-REL70-BORWEIN §1, equations (3)–(7)", "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1112/S0025579300001480", "doi": "10.1112/S0025579300001480", "full_text_accessed": false, "main_result": "The preserved publisher extract defines λ by prime-factor parity and gives its zeta Dirichlet-series description. The original proof and numerical details are unextracted. Borwein–Ferguson–Mossinghoff §1, eqs. (3)–(7), separately documents the 1958 positive smoothed unweighted sum using 649 zeros and the negative smoothed Turán sum.", "novelty_claim": false, "paper_id": "PAPER-REL70-HASELGROVE", "pdf_pages": null, "publication_status": "Verified accessed manifestation", "read_scope": "Cambridge Core publisher extract and bibliographic metadata only", "record_path": "quality/pending_round12/release70_positivity_notes.md", "result_status": "Publisher extract only. Original theorem and proof pages remain unextracted; later attribution separately identified.", "selection_reason": "Distinguish the original counterexample or obstruction, the conditions of the transfer, and the weaker assertions still compatible with RH.", "source_locator": "Cambridge Core publisher extract and bibliographic metadata only", "source_path": "sources/release70_positivity/haselgrove_publisher.html", "source_sha256": "6d6463ffb09533e7f5872e9cdd1f9a26dfd63b3f864eeccaad7da748029a10fb", "source_url": "https://www.cambridge.org/core/journals/mathematika/article/abs/disproof-of-a-conjecture-of-polya/F44F62DF2736A41AD4EEAA858DC952F5", "substantive_reading": false, "theorem_sta