INSERT INTO "papers" VALUES('PAPER-REL70-POLYA-TURAN','corpus/bibliography.jsonl',866,'full_text_accessed','quality/pending_round12/release70_positivity_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Sign conjectures, oscillation and spectral limits", "arxiv_id": null, "audit_level": 0, "authors": ["Michael J. Mossinghoff", "Timothy S. Trudgian"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1017/S1446788712000201", "doi": "10.1017/S1446788712000201", "full_text_accessed": true, "main_result": "The source distinguishes L(x)=Σ_(n≤x)λ(n) and T(x)=Σ_(n≤x)λ(n)/n. Turán’s sufficient condition for RH is T(n)>−c/√n eventually for some c>0. It credits Haselgrove with infinite sign changes and distinguishes these from Lehman’s explicit L(906180359)=1, Tanaka’s least positive L crossing after 1 at 906105257, and the later least negative T crossing at 72185376951205. The historical attribution of the conjecture labels is qualified.", "novelty_claim": false, "paper_id": "PAPER-REL70-POLYA-TURAN", "pdf_pages": 15, "publication_status": "Verified accessed manifestation", "read_scope": "§1, printed pp. 157–159, Pólya’s and Turán’s problems", "record_path": "quality/pending_round12/release70_positivity_notes.md", "result_status": "Cited statement checked at selection scope. Full theorem proof and any hypotheses beyond the cited passage remain unextracted.", "selection_reason": "Distinguish the original counterexample or obstruction, the conditions of the transfer, and the weaker assertions still compatible with RH.", "source_locator": "§1, printed pp. 157–159, Pólya’s and Turán’s problems", "source_path": "sources/release70_positivity/polya-turan.pdf", "source_sha256": "fce06d7a1e4aa45541d772cf70323cb5bf7a818a7fe718ee1d235e3ae451cf0a", "source_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/47909344EF97983FE77337CC0B0E1D5C/S1446788712000201a.pdf/div-class-title-between-the-problems-of-p