INSERT INTO "papers" VALUES('PAPER-REL70-2108-01827','corpus/bibliography.jsonl',872,'full_text_accessed','quality/pending_round12/release70_positivity_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Entire functions and real-rooted approximation", "arxiv_id": "2108.01827", "audit_level": 0, "authors": ["Wagner, Ian"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.2140/pjm.2022.320.177", "doi": "10.2140/pjm.2022.320.177", "full_text_accessed": true, "main_result": "For eventually nonnegative coefficients, shifted type-I multiplier status, real nonpositive Jensen zeros at sufficiently large shift for each fixed degree, and shifted type-I Laguerre–Pólya membership are equivalent. Theorem 1.2 gives eventual generalized Laguerre inequalities at each fixed order for the shifted class SL-P; the converse is Conjecture 1.3.", "novelty_claim": false, "paper_id": "PAPER-REL70-2108-01827", "pdf_pages": 13, "publication_status": "Verified accessed manifestation", "read_scope": "Theorem 1.1 and Theorem 1.2 with Conjecture 1.3", "record_path": "quality/pending_round12/release70_positivity_notes.md", "result_status": "Cited statement checked at selection scope. Full theorem proof and any hypotheses beyond the cited passage remain unextracted.", "selection_reason": "Compare growth, coefficient, root-location and approximation assumptions with the hypotheses required for ζ or ξ.", "source_locator": "Theorem 1.1 and Theorem 1.2 with Conjecture 1.3", "source_path": "sources/release70_positivity/2108.01827.pdf", "source_sha256": "dc8b44a06faba50008a9bae4848cc135b0fcd454e88ad8e2b1efe73d7dfba821", "source_url": "https://arxiv.org/pdf/2108.01827v2", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "On a new class of Laguerre-Pólya type functions with applications in number theory", "topic": "Entire functions and real-rooted approximation", "track_file": "papers/release70_positivity_records.jsonl", "transfer_hypothesis": "Compare growth, coefficient, root-location and approximation assumptions with the hypotheses required for ζ or ξ.", "venue": "arXiv", "version": "arXiv:2108.01827v2", "whole_work_read": false, "year": 2021, "admission_evidence": "quality/round12_source_admission_receipt.json", "original_pending_file": "quality/pending_round12/release70_positivity_records.jsonl", "id": "PAPER-REL70-2108-01827", "arxiv": "2108.01827", "original_access_status": "full_text_accessed", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-REL70-2108-01827"]}','On a new class of Laguerre-Pólya type functions with applications in number theory','["Wagner, Ian"]',NULL,'2021',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2108.01827v2','https://arxiv.org/pdf/2108.01827v2','dc8b44a06faba50008a9bae4848cc135b0fcd454e88ad8e2b1efe73d7dfba821','quality/pending_round12/release70_positivity_notes.md','papers/release70_positivity_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-REL70-2611-02944','corpus/bibliography.jsonl',873,'full_text_accessed','quality/pending_round12/release70_positivity_notes.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Entire functions and real-rooted approximation", "arxiv_id": "2611.02944", "audit_level": 0, "authors": ["Sra, Suvrit"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2611.02944", "doi": null, "full_text_accessed": true, "main_result": "The preprint claims both reciprocal-transform densities are PF_k at k=1810540931075 from verification through height 3000175332800. It also states that RH up to T>1/2 implies all generalized Laguerre inequalities for Ξ on |x|≤T−1/2. The finite-order argument and numerical certificate remain unextracted. PF∞ for either whole density is the separate RH equivalence in Proposition A.1, attributed to the Schoenberg transform theory and later Xi specializations.", "novelty_claim": false, "paper_id": "PAPER-REL70-2611-02944", "pdf_pages": 53, "publication_status": "Verified accessed manifestation", "read_scope": "Abstract, §§1.1–1.3, Proposition A.1 statement and §5.2 attribution", "record_path": "quality/pending_round12/release70_positivity_notes.md", "result_status": "Cited statement checked at selection scope. Full theorem proof and any hypotheses beyond the cited passage remain unextracted.", "selection_reason": "Compare growth, coefficient, root-location and approximation assumptions with the hypotheses required for ζ or ξ.", "source_locator": "Abstract, §§1.1–1.3, Proposition A.1 statement and §5.2 attribution", "source_path": "sources/release70_positivity/2611.02944.pdf", "source_sha256": "c8a659bb1c42bf53243a45241ce27e685b94ea7f10c0b59a615f360b34925cb3", "source_url": "https://arxiv.org/pdf/2611.02944v1", "substantive_reading": false, "theorem_statement_status": "incomplete targeted extraction", "title": "On some positivity properties of the Riemann Ξ function", "topic":