INSERT INTO "papers" VALUES('PAPER-U78-RMT-BNR-EWENS','corpus/bibliography.jsonl',896,'full_text_accessed','papers/PAPER-U78-RMT-BNR-EWENS.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Random matrix theory", "arxiv_id": "0712.0848", "audit_level": 0, "authors": ["Paul Bourgade", "Ashkan Nikeghbali", "Alain Rouault"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.1007/978-3-642-15217-7_15", "doi": "10.1007/978-3-642-15217-7_15", "full_text_accessed": true, "language": "English", "main_result": "For Re δ>−1/2 the source gives the rescaled determinantal correlation kernel at the circular Jacobi singularity z=1, in confluent hypergeometric form. δ=2 is the |1−z|^4 case of the rooted model.", "novelty_claim": false, "paper_id": "PAPER-U78-RMT-BNR-EWENS", "pdf_pages": 26, "publication_status": "Bibliographic journal or chapter identity verified; archived bytes are the stated preprint manifestation.", "read_scope": "Targeted primary theorem passages only. §5, circular model weight w_1, Theorem 5, (33)–(36)", "record_path": "papers/PAPER-U78-RMT-BNR-EWENS.md", "result_status": "Source-stated dependency only; full theorem proof and remaining sections unextracted. No arithmetic full-law transfer.", "selected": true, "selection_reason": "Primary antecedent for the local circular Jacobi kernel; the paper does not supply the noncompact band linear-statistic limit extracted in the archive.", "source_locator": "§5, circular model weight w_1, Theorem 5, (33)–(36)", "source_path": "sources/rmt80/bnr_0712.0848v2_author.pdf", "source_sha256": "7f3c9609109d7609017334a434304e5e74a6989bd0461744e0a9e0540b263b93", "source_url": "https://cims.nyu.edu/~bourgade/papers/SemProb.pdf", "substantive_reading": false, "title": "Ewens Measures on Compact Groups and Hypergeometric Kernels", "topic": "Rooted CUE and Palm projection dependencies", "track_file": "papers/rmt80_records.jsonl", "transfer_hypothesis": "Primary antecedent for the lo