INSERT INTO "papers" VALUES('PAPER-R112-BAKER2012','corpus/bibliography.jsonl',901,'full_text_accessed','papers/PAPER-R112-BAKER2012.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Analytic number theory", "audit_level": 0, "authors": ["Roger C. Baker"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.4064/aa156-4-4", "doi": "10.4064/aa156-4-4", "full_text_accessed": true, "id": "PAPER-R112-BAKER2012", "issue": 4, "language": "English", "main_result": "Theorem 2 gives the average over all integer moduli Q<q≤2Q of the maximum over unit numerators of the dyadic inverse-prime sum, at most (Q^(11/10)x^(4/5)+Qx^(11/12))Q^epsilon for Q^(1/2)≤x≤2Q.", "novelty_claim": false, "pages": "351–372", "paper_id": "PAPER-R112-BAKER2012", "pdf_pages": 22, "publication_status": "Published journal article", "read_scope": "Targeted reading of definition, all-integer dyadic modulus convention, and averaged inverse-prime bound. Full PDF retained privately.", "record_path": "papers/PAPER-R112-BAKER2012.md", "result_status": "Exact source statement checked at targeted passages. The local transition-band transfer is a separately reviewed argument.", "scope_note": "audits/adversarial_reviews/release112_baker_bhm_source_selection.md", "selection_reason": "Direct primary estimate for the two inverse-prime phases in the smooth C-star transition band.", "selection_status": "selected_checkpoint_priority_work", "source_locator": "§1, p. 351, definition of S_q(a;x); p. 352, q∼Q notation and Theorem 2", "source_path": "sources/prime107_references/baker2012_acta.pdf", "source_sha256": "2b1b0690e08489b077bb632fef2d6ea777ebe6684dc02efe5d6af9e67127cbda", "source_url": "https://www.impan.pl/shop/en/publication/transaction/download/product/82065", "substantive_reading": false, "title": "Kloosterman sums with prime variable", "transfer_hypothesis": "The dual numerator must be a unit, the dyadic prime range lies within the source scale window, and partial summation uses a common prime endpoint across moduli. The paper does not supply inverse-square or long-range cancellation.", "venue": "Acta Arithmetica 156(4), 351–372", "version": "2012 Acta Arithmetica publisher PDF, vol. 156 no. 4, pp. 351–372", "volume": 156, "whole_work_read": false, "year": 2012, "selected": true, "admission_receipt": "quality/round14_dependency_admission_receipt.json", "arxiv": null, "original_access_status": "full_text_accessed", "track_file": "papers/round14_dependency_records.jsonl", "original_selection_status": "selected_scoped_proof_dependency", "source_record_ids": ["PAPER-R112-BAKER2012"]}','Kloosterman sums with prime variable','["Roger C. Baker"]',NULL,'2012',0,0,'selected_checkpoint_priority_work','full_text_accessed','2012 Acta Arithmetica publisher PDF, vol. 156 no. 4, pp. 351–372','https://www.impan.pl/shop/en/publication/transaction/download/product/82065','2b1b0690e08489b077bb632fef2d6ea777ebe6684dc02efe5d6af9e67127cbda','papers/PAPER-R112-BAKER2012.md','papers/round14_dependency_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-R112-BHM2007','corpus/bibliography.jsonl',902,'full_text_accessed','papers/PAPER-R112-BHM2007.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Analytic number theory", "audit_level": 0, "authors": ["Valentin Blomer", "Gergely Harcos", "Philippe Michel"], "bibliographic_verified": true, "canonical_url": "https://www.numdam.org/item/ASENS_2007_4_40_5_697_0/", "doi": "10.1016/j.ansens.2007.05.003", "full_text_accessed": true, "id": "PAPER-R112-BHM2007", "issue": 5, "language": "English", "main_result": "Equation (2.27) gives a logarithmic main integral independent of unit numerator d and two Bessel dual sums with phases e(±inverse(d)m/c). The level-aspect subconvexity theorem is outside this passage review.", "novelty_claim": false, "pages": "697–740", "paper_id": "PAPER-R112-BHM2007", "pdf_pages": 44, "publication_status": "Published journal article", "read_scope": "Targeted source passage on smooth divisor Voronoi, kernels, and numerator-independent diagonal. Full PDF retained privately.", "record_path": "papers/PAPER-R112-BHM2007.md", "result_status": "Exact source formula and phase conventions checked at targeted passages. No whole-work audit.", "scope_note": "audits/adversarial_reviews/release112_baker_bhm_source_selection.md", "selection_reason": "Exact primary formula supplying the inverse-phase transform in the smooth C-star transition band.", "selection_status": "selected_checkpoint_priority_work", "series": 4, "source_locator": "§2.3, pp. 708–709, equations (2.25)–(2.27)", "source_path": "sources/prime107_references/blomer_harcos_michel2007_annales.pdf", "source_sha256": "7a07387f1f9da1dcd20d9dda329d0ee02d6d8df5aa3af885227545cbc4149fb5", "source_url": "https://www.numdam.org/item/10.1016/j.ansens.2007.05.003.pdf", "substantive_reading": false, "title": "Bounds for modular L-functions in the level aspect", "transfer_hypothesis": "Positive integer modulus c, unit d, and compactly supported smooth test on (0,∞). Freeze a coprime prime factor before applying the formula and perform principal subtraction on the same original modulus.", "venue": "Annales scientifiques de l’École Normale Supérieure, Série 4, 40(5), 697–740", "version": "2007 journal typeset PDF, Numdam ASENS_2007_4_40_5_697_0", "volume": 40, "whole_work_read": false, "year": 2007, "selected": true, "admission_receipt": "quality/round14_dependency_admission_receipt.json", "arxiv": null, "original_access_status": "full_text_accessed", "track_file": "papers/round14_dependency_records.jsonl", "original_selection_status": "selected_scoped_proof_dependency", "source_record_ids": ["PAPER-R112-BHM2007"]}','Bounds for modular L-functions in the level aspect','["Valentin Blomer", "Gergely Harcos", "Philippe Michel"]',NULL,'2007',0,0,'selected_checkpoint_priority_work','full_text_accessed','2007 journal typeset PDF, Numdam ASENS_2007_4_40_5_697_0','https://www.numdam.org/item/10.1016/j.ansens.2007.05.003.pdf','7a07387f1f9da1dcd20d9dda329d0ee02d6d8df5aa3af885227545cbc4149fb5','papers/PAPER-R112-BHM2007.md','papers/round14_dependency_records.jsonl');
