INSERT INTO "papers" VALUES('PAPER-R114-FOUVRY-SHPARLINSKI2011','corpus/bibliography.jsonl',906,'full_text_accessed','papers/PAPER-R114-FOUVRY-SHPARLINSKI2011.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Analytic number theory", "audit_level": 0, "authors": ["Étienne Fouvry", "Igor E. Shparlinski"], "bibliographic_verified": true, "canonical_url": "https://doi.org/10.4064/aa150-3-5", "doi": "10.4064/aa150-3-5", "full_text_accessed": true, "id": "PAPER-R114-FOUVRY-SHPARLINSKI2011", "issue": 3, "language": "English", "main_result": "Theorem 3.3 bounds the dyadic integer-modulus average of the maximum over unit numerators of the inverse-prime sum by a constant times (Q^(13/10)x^(3/5)+Q^(13/12)x^(5/6))Q^epsilon uniformly for 1≤x≤Q^(3/2).", "novelty_claim": false, "pages": "285–314", "paper_id": "PAPER-R114-FOUVRY-SHPARLINSKI2011", "pdf_pages": 30, "publication_status": "Published journal article", "read_scope": "Targeted check of the dyadic inverse-prime phase, integer modulus, unit numerator, and the averaged upper bound and length range. Full PDF retained privately.", "record_path": "papers/PAPER-R114-FOUVRY-SHPARLINSKI2011.md", "result_status": "Exact source statement checked at targeted passages. The local power-saving region depends on the independently reviewed weight and modulus accounting.", "scope_note": "audits/adversarial_reviews/prime113_uniform_voronoi_envelope.md", "selection_reason": "Direct source bound for the longer prime window, including some P>K, and reduced-modulus blocks in the general smooth C-star prime-stratum estimate.", "selection_status": "selected_checkpoint_priority_work", "source_locator": "§3.1, printed p. 296/PDF p. 12, inverse-prime sum definition; §3.5, printed p. 301/PDF p. 17, Theorem 3.3", "source_path": "sources/prime113_references/fouvry_shparlinski2011.pdf", "source_sha256": "dff49b00d5e506a73ecfeab2fd4ab3ccfdc8ed6f5774c939538ebfedae707cff", "source_url": "https://www.impan.pl/shop/publication/transaction/download/product/82801", "substantive_reading": false, "title": "On a ternary quadratic form over primes", "transfer_hypothesis": "Use reduced unit numerators on each reduced modulus block and common prime endpoints in Abel summation. Check 1≤x≤Q^(3/2) for the applicable blocks, using a separate bound for smaller moduli.", "venue": "Acta Arithmetica 150(3), 285–314", "version": "2011 Acta Arithmetica publisher PDF, vol. 150 no. 3, pp. 285–314", "volume": 150, "whole_work_read": false, "year": 2011, "selected": true, "admission_receipt": "quality/round14_dependency_admission_receipt.json", "arxiv": null, "original_access_status": "full_text_accessed", "track_file": "papers/round14_dependency_records.jsonl", "original_selection_status": "selected_scoped_proof_dependency", "source_record_ids": ["PAPER-R114-FOUVRY-SHPARLINSKI2011"]}','On a ternary quadratic form over primes','["Étienne Fouvry", "Igor E. Shparlinski"]',NULL,'2011',0,0,'selected_checkpoint_priority_work','full_text_accessed','2011 Acta Arithmetica publisher PDF, vol. 150 no. 3, pp. 285–314','https://www.impan.pl/shop/publication/transaction/download/product/82801','dff49b00d5e506a73ecfeab2fd4ab3ccfdc8ed6f5774c939538ebfedae707cff','papers/PAPER-R114-FOUVRY-SHPARLINSKI2011.md','papers/round14_dependency_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-P122-FIORI-JASKARI-PNT','corpus/bibliography.jsonl',907,'full_text_accessed','papers/PAPER-P122-FIORI-JASKARI-PNT.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Analytic number theory", "arxiv_id": "2609.23222", "audit_level": 0, "authors": ["Andrew Fiori", "Mikko Jaskari"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2609.23222v2", "doi": "10.48550/arXiv.2609.23222", "doi_kind": "arXiv/DataCite preprint DOI", "full_text_accessed": true, "id": "PAPER-P122-FIORI-JASKARI-PNT", "main_result": "Theorem 1.1 bounds |ψ(x)−x|/x for x≥x0≥e³ using D≈0.1982767 and the tabulated factor L(x0), with L(e³)=0.2390. Theorem 1.4 separately transfers a stipulated half-plane to a PNT bound.", "novelty_claim": false, "openalex_id": "https://openalex.org/W7214051944", "paper_id": "PAPER-P122-FIORI-JASKARI-PNT", "pdf_pages": 50, "provider_candidate_id": "CAND-C214EEA5C23D", "publication_status": "Preprint", "read_scope": "Targeted theorem and proof-interface check. Numerical interval estimates and Sage code not independently audited.", "record_path": "papers/PAPER-P122-FIORI-JASKARI-PNT.md", "selection_reason": "Unconditional explicit PNT input gives an effective constant for the prime-to-integral substitution in Gonek Lemma 8.", "selection_status": "selected_checkpoint_priority_work", "source_bytes": 571536, "source_locator": "PDF pp. 4–5 Theorems 1.1 and 1.4; pp. 44–45 Theorems 5.2–5.3 and §§5.1–5.2", "source_metadata_path": "sources/prime122_frontier_pending/2609.23222.html", "source_metadata_sha256": "cbcbed704f5c326be048099a70249b1579c4f6496c0d070899381ba242a3c671", "source_path": "sources/prime122_frontier_pending/2609.23222.pdf", "source_sha256": "77d12f382218e5d63e1c3b6de0f96a7bb9dfe23538f1ecf0221d28d1f840c8db", "source_url": "https://arxiv.org/pdf/2609.23222v2", "submission_date": "2026-09-19", "substantive_reading": false, "title": "Explicit bounds for the prime number theorem", "transfer_hypothesis": "Only Theorem 1.1 is used for the unconditional Abel substitution constant. Theorem 1.4 and its σ=7/8 example inherit their half-plane assumption. No improvement for the other Gonek constants or C₂ follows.", "venue": "arXiv (math.NT)", "version": "arXiv:2609.23222v2", "version_date": "2026-10-08", "whole_work_read": false, "year": 2026, "selected": true, "candidate_id": "CAND-C214EEA5C23D", "selection_review": "audits/adversarial_reviews/geometry132_latest_sources_selection_review.md", "admission_receipt": "quality/round15_dependency_admission_receipt.json", "arxiv": "2609.23222", "original_access_status": "full_text_accessed", "track_file": "papers/round15_dependency_records.jsonl", "original_selection_status": "selected_scoped_dependency_or_frontier_comparator", "source_record_ids": ["PAPER-P122-FIORI-JASKARI-PNT"]}','Explicit bounds for the prime number theorem','["Andrew Fiori", "Mikko Jaskari"]',NULL,'2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','arXiv:2609.23222v2','https://arxiv.org/pdf/2609.23222v2','77d12f382218e5d63e1c3b6de0f96a7bb9dfe23538f1ecf0221d28d1f840c8db','papers/PAPER-P122-FIORI-JASKARI-PNT.md','papers/round15_dependency_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-P122-INUMARU-SUGIYAMA-TWISTED-DENSITY','corpus/bibliography.jsonl',908,'full_text_accessed','audits/adversarial_reviews/geometry132_latest_sources_selection_review.md','{"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "area": "Analytic number theory", "arxiv_id": "2610.41394", "audit_level": 1, "authors": ["Naoto Inumaru", "Shingo Sugiyama"], "bibliographic_verified": true, "canonical_url": "https://arxiv.org/abs/2610.41394v1", "doi": "10.48550/arXiv.2610.41394", "doi_kind": "arXiv/DataCite preprint DOI", "full_text_accessed": true, "id": "PAPER-P122-INUMARU-SUGIYAMA-TWISTED-DENSITY", "main_result": "Theorem 1.3 evaluates the fixed-character continuously weighted one-level density for real 1/2≤σ≤1 and Schwartz tests with Fourier support in (−σ/(σ+1),σ/(σ+1)), without GRH in this support range. Theorem 1.4 treats distinct characters.", "novelty_claim": false, "openalex_id": "https://openalex.org/W7225102923", "paper_id": "PAPER-P122-INUMARU-SUGIYAMA-TWISTED-DENSITY", "pdf_pages": 30, "provider_candidate_id": "CAND-AC026DA96A1D", "publication_status": "Preprint", "read_scope": "Two independent substantive readings of all 30 pinned v1 pages, §§1–4, Appendix A, acknowledgments, references [1]–[38], and author affiliations. Named upstream proof dependencies remain external.", "record_path": "papers/PAPER-P122-INUMARU-SUGIYAMA-TWISTED-DENSITY.md", "selection_reason": "New Fourier support for a fixed-character continuous weighted one-level statistic, including q=1; a precise scope comparator for the Observatory derivative-root law.", "selection_status": "selected_checkpoint_priority_work", "source_bytes": 422470, "source_locator": "PDF §§1.1–1.4, §2 AFE setup, §§3–4 normalized twists and Theorems 4.1 and 4.3, Appendix A", "source_metadata_path": "sources/prime122_frontier_pending/2610.41394.html", "source_metadata_sha256": "0084b958ebc0c460cc8caf697f7265c61971a9c671a2b3e64ffbe643f460fc2c", "source_path": "sources/prime122_frontier_pending/2610.41394.pdf", "source_sha256": "70d2a3caf711fab1a5d7926ed099e098ab8e41c99bd3075dddf0a218b7d7e290", "source_url": "https://arxiv.org/pdf/2610.41394v1", "submission_date": "2026-10-30", "substantive_reading": true, "title": "Twisted second moments of Dirichlet L-functions with applications to weighted one-level density", "transfer_hypothesis": "Tempered Schwartz tests with compact Fourier support admit an entire extension to complex zero coordinates. At q=1 the fixed-twist estimate is weaker than the existing shifted aggregate J bound; the continuous height law does not estimate the long discrete additive prime twist.", "venue": "arXiv (math.NT)", "version": "arXiv:2610.41394v1", "version_date": "2026-10-30", "whole_work_read": true, "year": 2026, "selected": true, "candidate_id": "CAND-AC026DA96A1D", "selection_review": "audits/adversarial_reviews/geometry132_latest_sources_selection_review.md", "admission_receipt": "quality/round15_dependency_admission_receipt.json", "arxiv": "2610.41394", "original_access_status": "full_text_accessed", "track_file": "papers/round15_dependency_records.jsonl", "original_selection_status": "selected_scoped_dependency_or_frontier_comparator", "source_record_ids": ["PAPER-P122-INUMARU-SUGIYAMA-TWISTED-DENSITY"], "scope_update_history": [{"fields": {"access_status": "full_text_accessed", "accessed_at": "2026-11-18", "arxiv_id": "2610.41394", "audit_level": 1, "authors": ["Naoto Inumaru", "Shingo Sugiyama"], "pdf_pages": 30, "read_scope": "Two independent substantive readings of all 30 pinned v1 pages, §§1–4, Appendix A, acknowledgments, references [1]–[38], and author affiliations. Named upstream proof dependencies remain external.", "source_bytes": 422470, "source_path": "sources/prime122_frontier_pending/2610.41394.pdf", "source_sha256": "70d2a3caf711fab1a5d7926ed099e098ab8e41c99bd3075dddf0a218b7d7e290", "source_url": "https://arxiv.org/pdf/2610.41394v1", "substantive_reading": true, "version": "arXiv:2610.41394