INSERT INTO "papers" VALUES('PAPER-LUECKING1986-BERGMAN-MULTIPLIERS','corpus/bibliography.jsonl',909,'full_text_accessed','audits/adversarial_reviews/prime150_luecking_whole_advocate.md','{"access_status": "full_text_accessed", "admission_receipt": "quality/round16_dependency_admission_receipt.json", "area": "Bergman spaces", "audit_level": 1, "authors": ["Daniel H. Luecking"], "bibliography_verified": true, "canonical_url": "https://doi.org/10.1017/S001309150001748X", "doi": "10.1017/S001309150001748X", "family": ["H"], "full_text_accessed": true, "id": "PAPER-LUECKING1986-BERGMAN-MULTIPLIERS", "issue": "1", "main_result": "For 0<q<p<∞ and a positive finite Borel measure on the unit disk, the embedding A^p→L^q(μ) is bounded exactly when the fixed-radius pseudohyperbolic disk mass divided by its normalized area lies in L^{p/(p−q)}.", "novelty_claim": false, "pages": "125–131", "paper_id": "PAPER-LUECKING1986-BERGMAN-MULTIPLIERS", "pdf_pages": 7, "publication_status": "Published journal article", "read_scope": "Two independent complete readings of the pinned seven-page journal article, pp. 125–131. Coverage includes the main criterion, radius independence, necessity via uniform interpolation, and the multiplier consequence.", "record_path": "papers/PAPER-LUECKING1986-BERGMAN-MULTIPLIERS.md", "selected": true, "selection_reason": "Adjacent Bergman-space antecedent for the ambient weighted Mellin trace criterion. The strip transfer uses further inputs. The article supplies neither a physically constrained counterexample nor a signed endpoint result.", "selection_review": "audits/adversarial_reviews/prime150_luecking_whole_advocate.md", "selection_status": "selected_checkpoint_priority_work", "source_bytes": 298914, "source_locator": "p. 126 main criterion, p. 127 radius lemma, pp. 127–130 necessity, and pp. 130–131 multipliers", "source_path": "sources/prime146_mellin_provenance/luecking1986.pdf", "source_sha256": "e5d194ad05a844e376a65b18bc7082864baa38b01ddb1d4f217f67c28cb0d301", "source_url": "https://doi.org/10.1017/S001309150001748X", "substantive_reading": true, "title": "Multipliers of Bergman spaces into Lebesgue spaces", "venue": "Proceedings of the Edinburgh Mathematical Society", "version": "1986 Cambridge journal version, Proceedings of the Edinburgh Mathematical Society 29(1), 125–131", "volume": "29", "whole_work_read": true, "year": 1986, "arxiv": null, "original_access_status": "full_text_accessed", "track_file": "papers/round16_dependency_records.jsonl", "original_selection_status": "selected_scoped_dependency", "source_record_ids": ["PAPER-LUECKING1986-BERGMAN-MULTIPLIERS"], "scope_update_history": [{"fields": {"audit_level": 1, "claim_verification_status": "Complete reading at Level 1.", "independent_whole_reading_reviews": ["audits/adversarial_reviews/prime150_luecking_whole_advocate.md", "audits/adversarial_reviews/analytic150_luecking_whole_skeptic.md"], "read_scope": "Two independent complete readings of the pinned seven-page journal article, pp. 125–131. Coverage includes the main criterion, radius independence, necessity via uniform interpolation, and the multiplier consequence.", "substantive_reading": true, "whole_work_read": true}, "evidence": "audits/adversarial_reviews/prime150_luecking_whole_advocate.md", "track_file": "quality/zzzzzzzzzzzz_round16_source_scope_updates.jsonl"}], "claim_verification_status": "Complete reading at Level 1.", "independent_whole_reading_reviews": ["audits/adversarial_reviews/prime150_luecking_whole_advocate.md", "audits/adversarial_reviews/analytic150_luecking_whole_skeptic.md"], "scope_update_evidence": "audits/adversarial_reviews/prime150_luecking_whole_advocate.md", "additional_scope_update_files": ["quality/zzzzzzzzzzzz_round16_source_scope_updates.jsonl"]}','Multipliers of Bergman spaces into Lebesgue spaces','["Daniel H. Luecking"]','["H"]','1986',1,1,'selected_checkpoint_priority_work','full_text_accessed','1986 Cambridge journal version, Proceedings of the Edinburgh Mathematical Society 29(1), 125–131','https://doi.org/10.1017/S001309150001748X','e5d194ad05a844e376a65b18bc7082864baa38b01ddb1d4f217f67c28cb0d301','papers/PAPER-LUECKING1986-BERGMAN-MULTIPLIERS.md','papers/round16_dependency_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-E010','corpus/bibliography.jsonl',910,'full_text_accessed','papers/PAPER-E010.md','{"id": "PAPER-E010", "title": "Cyclicity in Dirichlet-type spaces and extremal polynomials", "authors": ["Catherine Bénéteau", "Alberto A. Condori", "Constanze Liaw", "Daniel Seco", "Alan A. Sola"], "year": 2015, "date": "2015-04", "venue": "Journal d’Analyse Mathématique126(2015),259–286", "doi": "10.1007/s11854-015-0017-1", "arxiv": null, "source_url": "https://e-archivo.uc3m.es/rest/api/core/bitstreams/08715cb4-fb9a-4356-82a7-5ff0cf4bcb1c/content", "canonical_url": "https://doi.org/10.1007/s11854-015-0017-1", "candidate_id": "CAND-969060871C4E", "version": "Institutionalpostprintwith2015publishedcitationcover; mathematicalmanuscriptdate2013-01-17; typesetjournalidentitynotcompared", "family": ["C", "H"], "access_status": "full_text_accessed", "audit_level": 0, "whole_work_read": false, "inspected_portions_level": 1, "read_scope": "Targeteddefinitions/selected§2,§3Prop3.2,ControlLemma3.3,Thm3.4andproofs(internalpp12–17),Rieszdiscussionpp10,20. Otherwholepaperpartsnotread; no wholeworkL1.", "source_file": "sources/scalar_window_round3/beneteau_jam.pdf", "source_sha256": "cb6c356d1a2c3a7282a9f66996e3764942e04991713bb3796168e8cc5b23a3ad", "metadata_provenance": "sources/scalar_window_round3/beneteau_jam_crossref.json; postprintcover", "main_result": "Thm3.4:fixedα≤1,polynomialfzerosoutsideopendisk, optimaldistance² O_(α,f)(1/φ_α(N+1)); matchingpositive lowerconstantifatleastoneboundaryzero. φ_α(x)=x^(1−α)forα<1,log⁺xforα1. Locatorsareinternalpostprintpp16–17.", "limitations": ["Partialreadonly.", "Constantsdependfandα,notasserteduniformthroughrootcollisions.", "Equivalentintegralnormsareusedin§2; donotimportexactoptimalcoefficientsintostandardH²withoutnormalizationcheck."], "audit_file": "proposals/independent_campaigns/unit_circle_scalar_window_round3.md", "accessed_at": "2026-11-17", "original_access_status": "full_primary_postprint_pdf_accessed", "