INSERT INTO "papers" VALUES('PAPER-C101','corpus/bibliography.jsonl',911,'full_text_accessed','papers/PAPER-C101.md','{"id": "PAPER-C101", "title": "The Nyman–Beurling equivalent form for the Riemann hypothesis", "authors": ["Michel Balazard", "Éric Saias"], "date": "1998-11-12", "year": 1998, "venue": "Expositiones Mathematicae 18(2) (2000), 131–138; ESI 623 manuscript inspected", "publication_status": "published_work_preprint_inspected", "doi": null, "arxiv": null, "source_url": "https://www.esi.ac.at/preprints/esi623.pdf", "version": "ESI Preprint623; body dated12November1998, cover27October1998", "family": ["C", "F"], "audit_level": 0, "whole_work_read": false, "inspected_portions_level": 1, "read_scope": "Introduction and §5 pp6–7, especially Question4; middle Hardy-space proof not audited.", "access_status": "full_text_accessed", "available_formats": ["PDF"], "source_file": "sources/selberg_round2/balazard_saias.pdf", "source_sha256": "5cc11918451f92cf9cbc06941271adc41d3f550ade2ec2dae97b0d754b51c815", "accessed_at": "2026-11-17", "main_result": "Question4 p7 explicitly asks whether RH implies convergence for the fixed logarithmic Selberg coefficient array in the full critical-line norm. Question2 concerns arbitrary discrete arrays and Question3 unsmoothed Möbius sums.", "limitations": ["The fixed-array question is not the discrete closure theorem. The paper predates Báez-Duarte’s solution of the arbitrary-array closure question.", "Only the stated scope was inspected; no whole-paper reading is claimed."], "research_questions": ["Which endpoint uniformity or arithmetic tail estimate would prove convergence for the exact prescribed Selberg family?"], "correction_search_status": "Focused later-source search performed; exhaustive forward-citation and correction history incomplete", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-C101.md", "track_file": "papers/selberg_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-C101"]}','The Nyman–Beurling equivalent form for the Riemann hypothesis','["Michel Balazard", "Éric Saias"]','["C", "F"]','1998',0,0,'selected_checkpoint_priority_work','full_text_accessed','ESI Preprint623; body dated12November1998, cover27October1998','https://www.esi.ac.at/preprints/esi623.pdf','5cc11918451f92cf9cbc06941271adc41d3f550ade2ec2dae97b0d754b51c815','papers/PAPER-C101.md','papers/selberg_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-C102','corpus/bibliography.jsonl',912,'full_text_accessed','papers/PAPER-C102.md','{"id": "PAPER-C102", "title": "On the Balazard-Saias criterion for the Riemann Hypothesis", "authors": ["J. Brian Conrey", "Gerald Myerson"], "date": "2000-02-09", "year": 2000, "venue": "arXiv preprint", "publication_status": "preprint", "doi": null, "arxiv": "math/0002254", "source_url": "https://arxiv.org/abs/math/0002254v1", "version": "v1", "family": ["C", "F"], "audit_level": 0, "whole_work_read": false, "inspected_portions_level": 1, "read_scope": "Printed pp1–6: definitions, Proposition1, Theorem1 statement and Remarks1–2; proof of uniform convergence in remaining pages not read.", "access_status": "full_text_accessed", "available_formats": ["PDF"], "source_file": "sources/selberg_round2/conrey_myerson.pdf", "source_sha256": "9832f2e62f4e4eef5e79dac297887eb5e9a4c38bacd77f0929b4212d4f3fa9c1", "accessed_at": "2026-11-17", "main_result": "Prop1 p2 identifies the critical-line norm of ζV_N/s with the reciprocal-fractional-part norm of W_N(u)=Σ b_n{nu}/n. Theorem1 p5 states unconditional uniform convergence to −sin(2πu)/π. Remark1 pp5–6 gives the small-u contribution (Σ b_n)²/N.", "limitations": ["Uniform convergence does not imply the weighted norm convergence at u=0. A reported Conrey–Farmer separation-conditional result is cited as in preparation rather than proved in this source.", "Only the stated scope was inspected; no whole-paper reading is claimed."], "research_questions": ["Which endpoint uniformity or arithmetic tail estimate would prove convergence for the exact prescribed Selberg family?"], "correction_search_status": "Focused later-source search performed; exhaustive forward-citation and correction history incomplete", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-C102.md", "track_file": "papers/selberg_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-C102"]}','On the Balazard-Saias criterion for the Riemann Hypothesis','["J. Brian Conrey", "Gerald Myerson"]','["C", "F"]','2000',0,0,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/abs/math/0002254v1','9832f2e62f4e4eef5e79dac297887eb5e9a4c38bacd77f0929b4212d4f3fa9c1','papers/PAPER-C102.md','papers/selberg_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-C103','corpus/bibliography.jsonl',913,'full_text_accessed','audits/balazard_roton_ratio_round3.md; actualsources/selberg_round2/balazard_roton.pdf','{"id": "PAPER-C103", "title": "Sur un critère de Báez-Duarte pour l’hypothèse de Riemann", "authors": ["Michel Balazard", "Anne de Roton"], "date": "2008-12-09", "year": 2008, "venue": "International Journal of Number Theory6(4) (2010),883–903; arXiv manuscript inspected", "publication_status": "published_work_preprint_inspected", "doi": "10.1142/S1793042110003307", "arxiv": "0812.1689", "source_url": "https://arxiv.org/abs/0812.1689v1", "version": "arXiv header v1 9December2008; body prints8November2018, discrepancy recorded", "family": ["C", "F"], "audit_level": 1, "whole_work_read": true, "inspected_portions_level": 1, "read_scope": "Previousreaderpp1–5; equivalencessubsequentlyreadall20primarymanuscriptpagesincluding§§3–7andreferences. TargetedtechnicalreconstructionofProps2,4,5pp5–8; externalSoundararajan/zero-majorantdependenciesnotfullyaudited. Published2010versionnotcompared; header2008/body2018discrepancyretained.", "access_status": "full_text_accessed", "available_formats": ["PDF"], "source_file": "sources/selberg_round2/balazard_roton.pdf", "source_sha256": "d22890fc5903bce4c8be302a35ff5b4d84f33c63a84e9799c04136e5fdf76311", "accessed_at": "2026-11-17", "main_result": "Under RH, optimized d_N²≪δ(loglogN)^(5/2+δ)(logN)^(-1/2). Propositions 1–3 prove this through coefficients μ(n)n^(-ε), with ε=25(loglogN)^(5/2+δ)/sqrt(logN).", "limitations": ["The source supplies an admissible shifted-array upper bound and hence bounds the infimum. It does not give the same bound for the fixed logarithmic Selberg family.", "Only the stated scope was inspected; no whole-paper reading is claimed."], "research_questions": ["Which endpoint uniformity or arithmetic tail estimate would prove convergence for the exact prescribed Selberg family?"], "correction_search_status": "Focused later-source search performed; exhaustive forward-citation and correction history incomplete", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-C103.md", "track_file": "papers/selberg_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-C103"], "scope_update_history": [{"fields": {"whole_work_read": true, "audit_level": 1, "read_scope": "Previousreaderpp1–5; equivalencessubsequentlyreadall20primarymanuscriptpagesincluding§§3–7andreferences. TargetedtechnicalreconstructionofProps2,4,5pp5–8; externalSoundararajan/zero-majorantdependenciesnotfullyaudited. Published2010versionnotcompared; header2008/body2018discrepancyretained."}, "evidence": "audits/balazard_roton_ratio_round3.md; actualsources/selberg_round2/balazard_roton.pdf", "track_file": "quality/equivalence_source_scope_updates_round3.jsonl"}], "scope_update_evidence": "audits/balazard_roton_ratio_round3.md; actualsources/selberg_round2/balazard_roton.pdf", "additional_scope_update_files": ["quality/equivalence_source_scope_updates_round3.jsonl"]}','Sur un critère de Báez-Duarte pour l’hypothèse de Riemann','["Michel Balazard", "Anne de Roton"]','["C", "F"]','2008',1,1,'selected_checkpoint_priority_work','full_text_accessed','arXiv header v1 9December2008; body prints8November2018, discrepancy recorded','https://arxiv.org/abs/0812.1689v1','d22890fc5903bce4c8be302a35ff5b4d84f33c63a84e9799c04136e5fdf76311','papers/PAPER-C103.md','papers/selberg_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-C104','corpus/bibliography.jsonl',914,'full_text_accessed','audits/baez_duarte_deep_round2.md; logs/equivalence_round2.md; source math/0202166v1','{"id": "PAPER-C104", "title": "On an analytic estimate in the theory of the Riemann zeta function and a theorem of Báez-Duarte", "authors": ["Jean-François Burnol"], "date": "2002-02-18", "year": 2002, "venue": "Acta Cientifica Venezolana54(3) (2003),210–215; arXiv preprint inspected", "publication_status": "published_work_preprint_inspected", "doi": null, "arxiv": "math/0202166", "source_url": "https://arxiv.org/abs/math/0202166v1", "version": "v1", "family": ["C", "F"], "audit_level": 1, "whole_work_read": true, "inspected_portions_level": 1, "read_scope": "Round2 first reader inspected pp1–5. Independent equivalence agent subsequently read all nine pages including section4/references; full substantive reading now complete, no complete technical audit.", "access_status": "full_text_accessed", "available_formats": ["PDF"], "source_file": "sources/selberg_round2/burnol_analytic.pdf", "source_sha256": "797d9b4be56e75b1540b63053a2bec9cd7f7ee7d58f6023a142967026ff2c342", "accessed_at": "2026-11-17", "main_result": "Theorem1.3 underRH bounds ζ(s)/ζ(s+A) on Re(s)=1/2 uniformly forA≥0. Section2 uses fixedε>0 and N→∞ thenε↓0 to reconstruct discrete closure.", "limitations": ["Two-parameter convergence does not authorize settingε=0 at finiteN or replacing shifted coefficients by a prescribed logarithmic array.", "Only the stated scope was inspected; no whole-paper reading is claimed."], "research_questions": ["Which endpoint uniformity or arithmetic tail estimate would prove convergence for the exact prescribed Selberg family?"], "correction_search_status": "Focused later-source search performed; exhaustive forward-citation and correction history incomplete", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-C104.md", "track_file": "papers/selberg_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-C104"], "scope_update_history": [{"fields": {"whole_work_read": true, "audit_level": 1, "read_scope": "Round2 first reader inspected pp1–5. Independent equivalence agent subsequently read all nine pages including section4/references; full substantive reading now complete, no complete technical audit."}, "evidence": "audits/baez_duarte_deep_round2.md; logs/equivalence_round2.md; source math/0202166v1", "track_file": "quality/source_scope_updates.jsonl"}], "scope_update_evidence": "audits/baez_duarte_deep_round2.md; logs/equivalence_round2.md; source math/0202166v1", "additional_scope_update_files": ["quality/source_scope_updates.jsonl"]}','On an analytic estimate in the theory of the Riemann zeta function and a theorem of Báez-Duarte','["Jean-François Burnol"]','["C", "F"]','2002',1,1,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/abs/math/0202166v1','797d9b4be56e75b1540b63053a2bec9cd7f7ee7d58f6023a142967026ff2c342','papers/PAPER-C104.md','papers/selberg_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-C105','corpus/bibliography.jsonl',915,'full_text_accessed','papers/PAPER-C105.md','{"id": "PAPER-C105", "title": "A characterization of the zero-free region of the Riemann zeta function and its applications", "authors": ["Fei Wei", "Dongsheng Wu"], "date": "2022-12", "year": 2022, "venue": "Expositiones Mathematicae 40(4) (2022),961–993", "publication_status": "published_work_preprint_inspected", "doi": "10.1016/j.exmath.2022.07.004", "arxiv": null, "source_url": "https://bimsa.net/doc/publication/1424.pdf", "version": "32-page institutional manuscript createdJune2022; published preview independently checked", "family": ["C", "F"], "audit_level": 0, "whole_work_read": false, "inspected_portions_level": 2, "read_scope": "Institutional manuscript pp1–7 and pp27–29: Problem1, Proposition 1.9 and proof, Remark5.8, Theorem 1.10 statement. General Hardy-space characterization and all of Theorem 1.10 proof not fully audited.", "access_status": "full_text_accessed", "available_formats": ["PDF"], "source_file": "sources/selberg_round2/zero_free_2022.pdf", "source_sha256": "6edf13136d488d35415aff9dfa7f68ae38a13061c78138874ec36e201210fabe", "accessed_at": "2026-11-17", "main_result": "Proposition 1.9 p7: fixed Selberg full-critical-line error tending to0 impliesRH and all nontrivial zeros simple. Proofpp27–28 reconstructed independently. Problem1 pp6–7 leaves RH-alone reverse open. Theorem 1.10 establishes convergence on every fixed shifted lineRe(s)>1/2 iffRH, and boundary boundedness impliesRH.", "limitations": ["No fixed-boundary convergence underRHalone is established; a proof would also proveRH implies simplicity. Institutional and published versions differ in pagination/references, so manuscript page citations are explicit.", "Only the stated scope was inspected; no whole-paper reading is claimed."], "research_questions": ["Which endpoint uniformity or arithmetic tail estimate would prove convergence for the exact prescribed Selberg family?"], "correction_search_status": "Focused later-source search performed; exhaustive forward-citation and correction history incomplete", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-C105.md", "track_file": "papers/selberg_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-C105"]}','A characterization of the zero-free region of the Riemann zeta function and its applications','["Fei Wei", "Dongsheng Wu"]','["C", "F"]','2022',0,0,'selected_checkpoint_priority_work','full_text_accessed','32-page institutional manuscript createdJune2022; published preview independently checked','https://bimsa.net/doc/publication/1424.pdf','6edf13136d488d35415aff9dfa7f68ae38a13061c78138874ec36e201210fabe','papers/PAPER-C105.md','papers/selberg_round2_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-SG001','corpus/bibliography.jsonl',916,'full_text_accessed','papers/PAPER-SG001.md','{"id": "PAPER-SG001", "title": "Determinantal Random Point Fields", "authors": ["Alexander Soshnikov"], "year": 2000, "date": "2000-11-28", "venue": "Russian Mathematical Surveys55(5),923–975", "doi": "10.1070/RM2000v055n05ABEH000321", "arxiv": "math/0002099v4", "version": "arXivv4,28Nov2000,66-page preprint; journal identity verified separately, text not compared.", "source_url": "https://arxiv.org/pdf/math/0002099v4", "source_file": "sources/sine_gram_round3/soshnikov2000.pdf", "read_scope": "Selected actual primary p3 Definition2/Eq1.5; p8 Definition3/Eq1.20; p13 Theorem3; p28 Eq2.35 unit-density sine kernel. Entire66-page work not read.", "main_result_inspected": "Factorial correlation convention, determinantal correlation definition, existence for locally trace-class0<=K<=I, and exact sine-kernel normalization.", "technical_review": "Sine-process rho_l<=1, pair function, mean/variance, and factorial-expansion inputs independently reconstructed. Soshnikov mixing theorem is not needed by the expected-law quantile proof.", "publication_status": "published_work_preprint_inspected", "family": ["B", "D", "F", "H"], "audit_level": 0, "bibliographic_verified": true, "access_status": "full_text_accessed", "substantive_whole_work_read": false, "accessed_at": "2026-11-17", "source_sha256": "73fea6b802f7ec00dcb281438904ae89108412ce469be7e5ca651903b4806d0b", "correction_search_status": "incomplete", "audit_file": "proposals/independent_campaigns/sine_gram_all_moments_round3.md", "novelty_claim": false, "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-SG001.md", "track_file": "papers/sine_gram_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-SG001"]}','Determinantal Random Point Fields','["Alexander Soshnikov"]','["B"