INSERT INTO "papers" VALUES('PAPER-SG002','corpus/bibliography.jsonl',917,'full_text_accessed','papers/PAPER-SG002.md','{"id": "PAPER-SG002", "title": "Minimality, (Weighted) Interpolation in Paley-Wiener Spaces & Control Theory", "authors": ["Frédéric Gaunard"], "year": 2011, "date": "2011-10-08", "venue": "arXiv1110.1714v1 preprint", "doi": null, "arxiv": "1110.1714v1", "version": "SidebararXivv1,8Oct2011; downloaded PDF bodydate27Nov2024. Revision/recompilation history not audited; these dates are preserved separately.", "source_url": "https://arxiv.org/pdf/1110.1714v1", "source_file": "sources/sine_gram_round3/gaunard2011.pdf", "read_scope": "Printedpp2,5–7 and bibliography. PW^p definition, interpolation definition, and Theorem3 density statement visually inspected; rest of18-page preprint not read.", "main_result_inspected": "Theorem3,p7: uniformly separated sequence in a finite horizontal strip and D+<tau/pi is interpolating for PW_tau^p; real p2,tau=pi case supplies sinc-Gram Riesz lower bound via Hilbert open-mapping.", "technical_review": "Actual theorem is Paley–Wiener L^p includingp2, not Bernstein supremum-only. It cites Seip1995Theorem2.2/Beurling1989; those original proofs not accessed. Evaluation-to-Riesz implication independently reconstructed.", "publication_status": "preprint_version_inspected; correspondence_to_later_revised_journal_articles_not_audited", "family": ["B", "D", "F", "H"], "audit_level": 0, "bibliographic_verified": true, "access_status": "full_text_accessed", "substantive_whole_work_read": false, "accessed_at": "2026-11-17", "source_sha256": "584e4e5840f34df6b777b5ed290e764cf6641f255cc6c7e1c70464c4f94203f1", "correction_search_status": "incomplete", "audit_file": "proposals/independent_campaigns/sine_gram_all_moments_round3.md", "novelty_claim": false, "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-SG002.md", "track_file": "papers/sine_gram_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-SG002"]}','Minimality, (Weighted) Interpolation in Paley-Wiener Spaces & Control Theory','["Frédéric Gaunard"]','["B", "D", "F", "H"]','2011',0,0,'selected_checkpoint_priority_work','full_text_accessed','SidebararXivv1,8Oct2011; downloaded PDF bodydate27Nov2024. Revision/recompilation history not audited; these dates are preserved separately.','https://arxiv.org/pdf/1110.1714v1','584e4e5840f34df6b777b5ed290e764cf6641f255cc6c7e1c70464c4f94203f1','papers/PAPER-SG002.md','papers/sine_gram_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-SG003','corpus/bibliography.jsonl',918,'full_text_accessed','papers/PAPER-SG003.md','{"id": "PAPER-SG003", "title": "Multipliers for Entire Functions and an Interpolation Problem of Beurling", "authors": ["Joaquim Ortega-Cerdà", "Kristian Seip"], "date": "1999-03-10", "year": 1999, "venue": "Journal of Functional Analysis162(2)(1999),400–415", "doi": "10.1006/jfan.1998.3357", "arxiv": null, "publication_status": "Published; repository author manuscript inspected", "source_url": "https://hdl.handle.net/2445/164425", "fulltext_url": "https://diposit.ub.edu/server/api/core/bitstreams/bbe5243b-6094-4096-b939-b6692a19f366/content", "version": "Repository author manuscript dated15August1998; published1999 identity verified against repository and publisher metadata", "family": ["C", "D", "F", "H"], "audit_level": 0, "whole_work_read": false, "read_scope": "Manuscript introduction and exact definitions/Theorem1,pp1–3. Bernstein interpolation and density/separation/Carleson hypotheses read directly. Main multiplier and interpolation proof sections not read. Independent real-line Bernstein-to-PW² upgrade reconstructed in the audit; no whole-workLevel1 claim.", "access_status": "full_text_accessed", "source_file": "sources/sine_gram_skeptic_round4/ortega_cerda_seip.pdf", "source_sha256": "ea6d4e6651e82a548ab64e70539e9df773ce1c38a9e5d6b011388c421d2505cd", "accessed_at": "2026-11-17", "main_result_inspected": "Theorem1,p2 characterizes interpolation in BernsteinB_tau by separation for sigma(z,w)=|z-w|/[1+|z-conjw|], a two-sided Carleson condition, and upper uniform densityD+<tau/pi. For real sets the Carleson sum vanishes and this separation is equivalent to positive Euclidean separation. The source explicitly distinguishes Bernstein from Paley-WienerLp atcriticaldensity.", "research_connection": "With strict density margin choose tau0<pi; bounded Bernstein Lagrange functions multiplied by a squared-sinc envelope give bounded ell² interpolation inPW_pi². This supplies the exact external Riesz input in the sine-Gram no-zero-atom proof.", "limitations": ["Partial source reading only; original Beurling1989 and Seip1995 proofs not accessed.", "No assertion at critical densityD+=1.", "No uniform Riesz constant over all capped configurations is inferred."], "independent_reconstruction": "audits/adversarial_reviews/sine_gram_skeptic_round4.md", "correction_search_status": "Version identity checked; exhaustive correction and forward-citation search incomplete", "original_access_status": "full_text_accessed", "record_path": "papers/PAPER-SG003.md", "track_file": "papers/sine_gram_skeptic_round4_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-SG003"]}','Multipliers for Entire Functions and an Interpolation Problem of Beurling','["Joaquim Ortega-Cerdà", "Kristian Seip"]','["C", "D", "F", "H"]','1999',0,0,'selected_checkpoint_priority_work','full_text_accessed','Repository author manuscript dated15August1998; published1999 identity verified against repository and publisher metadata','https://hdl.handle.net/2445/164425','ea6d4e6651e82a548ab64e70539e9df773ce1c38a9e5d6b011388c421d2505cd','papers/PAPER-SG003.md','papers/sine_gram_skeptic_round4_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-E013','corpus/bibliography.jsonl',919,'full_text_accessed','papers/PAPER-E013.md','{"id": "PAPER-E013", "title": "Partial sums of the Möbius function", "authors": ["Kannan Soundararajan"], "year": 2009, "date": "2009-01", "venue": "Journal für die reine und angewandte Mathematik631(2009),141–152", "doi": "10.1515/CRELLE.2009.044", "arxiv": "0705.0723", "source_url": "https://arxiv.org/pdf/0705.0723v2", "canonical_url": "https://doi.org/10.1515/CRELLE.2009.044", "version": "Actual mathematical source arXiv0705.0723v2,13February2008; v1 listed5May2007. Published2009 text not compared.", "family": ["A", "B", "C"], "audit_level": 1, "whole_work_read": true, "inspected_portions_level": 2, "read_scope": "All11preprint pages including proofs and references read substantively. Typical-height lower-bound mechanism and main dependency architecture reconstructed; full original Selberg/Vaaler/large-sieve ancestry not audited. No whole-paper Level2.", "access_status": "full_text_accessed", "source_file": "sources/soundararajan_round4/sound0705v2.pdf", "source_sha256": "9bacaa0c6bbaf687091d8be7b9f0df3e58727339002c9cabcb4de90e33f41fa7", "metadata_provenance": ["sources/soundararajan_round4/sound_crossref.json", "sources/soundararajan_round4/sound_arxiv_abs.html", "https://profiles.stanford.edu/kannan-soundararajan"], "main_result": "Theorem1 underRH: M(x)≪sqrt(x)exp(sqrt(logx)(loglogx)^14). Theorem2 andProp4 bound rare zero-cluster/atypical heights; Prop5 bounds inversezeta at typical heights. Later exponent5/2+delta is a refinement, not the original stated theorem.", "limitations": ["Published journal mathematical text not compared.", "External primary proofs of interval majorants, explicit formula and Maier–Montgomery large sieve not all audited.", "Original and later delta-dependent typicality definitions differ.", "No claimed new source error or historical priority."], "audit_file": "audits/soundararajan_mobius_round4.md", "accessed_at": "2026-11-17", "original_access_status": "full_primary_preprint_accessed_and_read", "record_path": "papers/PAPER-E013.md", "track_file": "papers/soundararajan_round4_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-E013"]}','Partial sums of the Möbius function','["Kannan Soundararajan"]','["A", "B", "C"]','2009',1,1,'selected_checkpoint_priority_work','full_text_accessed','Actual mathematical source arXiv0705.0723v2,13February2008; v1 listed5May2007. Published2009 text not compared.','https://arxiv.org/pdf/0705.0723v2','9bacaa0c6bbaf687091d8be7b9f0df3e58727339002c9cabcb4de90e33f41fa7','papers/PAPER-E013.md','papers/soundararajan_round4_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-D201','corpus/bibliography.jsonl',920,'full_text_accessed','papers/PAPER-D201.md','{"paper_id": "PAPER-D201", "title": "The Duistermaat index and eigenvalue interlacing for self-adjoint extensions of a symmetric operator", "authors": ["Gregory Berkolaiko", "Graham Cox", "Yuri Latushkin", "Selim Sukhtaiev"], "year": 2026, "date": "2025-09-11", "version_date": "2025-09-11", "publication_date": "2026", "first_submission_date": "2023-11-12", "preprint_year": 2023, "publication_year": 2026, "venue": "Journal of Spectral Theory 16 (2026), 1–49; inspected arXiv preprint v4", "doi": "10.4171/jst/590", "arxiv_id": "2311.06701", "version": "v4", "canonical_url": "https://arxiv.org/abs/2311.06701v4", "source_url": "https://arxiv.org/pdf/2311.06701v4", "publication_status": "journal", "publication_metadata_scope": "Journal reference and DOI observed on primary arXiv landing page; journal typeset text not compared.", "full_text_access": "35-page v4 PDF downloaded and text extracted; private research copy.", "bibliographic_verified": true, "full_text_accessed": true, "substantive_reading": false, "audit_level": 0, "audit_scope": "Targeted primary-text reading: §1 main hypotheses/Theorems1.1–1.3 and discussion; §5 Proposition5.3 and proofs of1.1–1.2; §6 Theorem6.2, Lemma6.3 and resolvent proof; selected §7 examples. Whole35-page paper and every Duistermaat-index argument were not read/audited completely. The unbounded-both-directions auxiliary theorem is independently reconstructed separately, not attributed to sourceTheorem1.1.", "source_sha256": "52ef994bb33f9cf7fb22fd1581563d59b059065d515ecb6f9df0b55c6500eca5", "access_date": "2026-11-17", "correction_search": "Primary arXiv version history inspected: v1 2023-11-12, v2 2024-01-09, v3 2025-08-25, v4 2025-09-11; abstract comments report fixes/streamlining. No exhaustive later correction search.", "date_semantics": "date/version_date is inspected arXiv version date; publication_date is journal year only. Internal PDF date says15Sep2025; archive header/history identify v4 revision11Sep2025.", "selected": true, "family": ["D", "F", "H"], "main_results": [{"locator": "Theorem1.1,pp2–3; equations1.11–1.14", "statement": "S closed densely defined bounded below symmetric, finite equal deficiency(n,n), boundary triplet. For two selfadjoint extensions H1,H2, the global spectral shift below essential spectrum lies in a fixed interval[−σ−,σ+], with σ−+σ+=n−dim(L1∩L2)≤n; endpoints are Duistermaat indices relative to the Friedrichs extension."}, {"locator": "Theorem1.2,p4; proof§5,p19", "statement": "Under the same hypotheses, for[a,b] disjoint from essential spectrum, N_H1((a,b])−N_H2((a,b]) equals the difference of endpoint Duistermaat indices. Unique continuation is not required for this relative count."}, {"locator": "Theorem6.2,pp22–24; equations6.21–6.31", "statement": "At common real resolvent λ, the resolvent difference reduces to ker(S*−λ), has constant rank n−dim(L1∩L2), and its positive/negative inertia is expressed by Duistermaat indices. The source retains the setting of Theorem1.1."}], "proof_architecture": ["Boundary triplets identify selfadjoint domains with Lagrangian planes.", "Cauchy data spaces, Maslov-index monotonicity and the triple-index identity give relative interval counts.", "Common real eigenvalues missed without UCP cancel between the two extensions.", "An alternative proof places resolvent differences in finite-dimensional defect spaces, computes inertia, then anchors below both spectra and applies finite-rank Weyl interlacing."], "limitations": ["Semiboundedness is an explicit hypothesis; the main theorem cannot be directly cited for arbitrary two-sided spectra.", "Friedrichs anchoring and counts from−∞ are unavailable for an arbitrary unbounded-both-directions operator.", "No full-paper L1 audit; published typeset version not compared.", "No result about Riemann zeros or arbitrary energy-dependent unitary scattering matrices."], "research_questions": ["Independently review the two-sided compact-resolvent relative-count proof in audits/extension_interlacing_round2.md.", "For an actual unbounded boundary coupling identify the common closed symmetric restriction, finite defect, fixed domains and compactness.", "Determine the effective resolvent rank r rather than overcounting all boundary coordinates."], "id": "PAPER-D201", "arxiv": "2311.06701", "read_scope": "Targeted primary-text reading: §1 main hypotheses/Theorems1.1–1.3 and discussion; §5 Proposition5.3 and proofs of1.1–1.2; §6 Theorem6.2, Lemma6.3 and resolvent proof; selected §7 examples. Whole35-page paper and every Duistermaat-index argument were not read/audited completely. The unbounded-both-directions auxiliary theorem is independently reconstructed separately, not attributed to sourceTheorem1.1.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "whole_work_read": false, "record_path": "papers/PAPER-D201.md", "track_file": "papers/spectral_extension_round2_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-D201"]}','The Duistermaat index and eigenvalue interlacing for self-adjoint extensions of a symmetric operator','["Gregory Berkolaiko", "Graham Cox", "Yuri Latushkin", "Selim Sukhtaiev"]','["D", "F", "H"]','2026',0,0,'selected_checkpoint_priority_work','full_text_accessed','v4','https://arxiv.org/pdf/2311.06701v4','52ef994bb33f9cf7fb22fd1581563d59b059065d515ecb6f9df0b55c6500eca5','papers/PAPER-D201.md','papers/spectral_extension_round2_records.jsonl');
