INSERT INTO "papers" VALUES('PAPER-SM63-COMP-001','corpus/bibliography.jsonl',929,'full_text_accessed','papers/suzuki_model63_computational_notes.md','{"paper_id": "PAPER-SM63-COMP-001", "title": "A Method for the Calculation of the Zeta-Function", "authors": ["Alan M. Turing"], "year": 1943, "venue": "Proceedings of the London Mathematical Society (2) 48, 180–197", "doi": "10.1112/plms/s2-48.1.180", "arxiv_id": null, "version": null, "publication_status": "journal work", "canonical_url": "https://doi.org/10.1112/plms/s2-48.1.180", "source_url": "https://mediadepot.kings.cam.ac.uk/getmedia/79/be4a3d910d5d58e3911315113c60a09f6293fa896a5e3795998fa6b4fb72b71446336e3c7c92d5e08fd0fb2762b6f663279ba799d7fd562480b4bf63c63e02b9", "source_path": null, "source_sha256": "7464f8ff372dce48e1651917a4d7533571dfd06c9264d8a9e61e7645d46e5b15", "pages": 20, "source_edition": "King’s College Turing Digital Archive original offprint", "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "topic": "quadrature", "audit_scope": "The archive offprint prints 1943 on p. 180 and received/read dates in March 1939. The publisher DOI landing page uses 1945. Method and error estimates were sampled. No finite zero census is claimed from this item.", "main_results": [{"locator": "pp. 180–182, 195–197", "statement": "Article derives a zeta evaluation method from an approximate functional equation with an integral remainder. The proposed approximation replaces the remainder integral by a finite sum and adjusts the main sums. The author identifies the intermediate range between small-height Euler–Maclaurin evaluation and the large-height Riemann–Siegel regime as the primary use case."}], "record_path": "papers/suzuki_model63_computational_notes.md", "archive_catalogue": "https://turingarchive.kings.cam.ac.uk/publications-lectures-and-talks-amtb/amt-b-17", "local_version_receipt": "Original viewed and checksummed. Archive scan excluded from the retained source folder.", "id": "PAPER-SM63-COMP-001", "arxiv": null, "read_scope": "The archive offprint prints 1943 on p. 180 and received/read dates in March 1939. The publisher DOI landing page uses 1945. Method and error estimates were sampled. No finite zero census is claimed from this item.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/suzuki_model63_computational_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-SM63-COMP-001"]}','A Method for the Calculation of the Zeta-Function','["Alan M. Turing"]',NULL,'1943',0,0,'selected_checkpoint_priority_work','full_text_accessed','King’s College Turing Digital Archive original offprint','https://mediadepot.kings.cam.ac.uk/getmedia/79/be4a3d910d5d58e3911315113c60a09f6293fa896a5e3795998fa6b4fb72b71446336e3c7c92d5e08fd0fb2762b6f663279ba799d7fd562480b4bf63c63e02b9','7464f8ff372dce48e1651917a4d7533571dfd06c9264d8a9e61e7645d46e5b15','papers/suzuki_model63_computational_notes.md','papers/suzuki_model63_computational_records.jsonl');
INSERT INTO "papers" VALUES('PAPER-SM63-COMP-002','corpus/bibliography.jsonl',930,'full_text_accessed','papers/suzuki_model63_computational_notes.md','{"paper_id": "PAPER-SM63-COMP-002", "title": "Some Calculations of the Riemann Zeta-Function", "authors": ["Alan M. Turing"], "year": 1953, "venue": "Proceedings of the London Mathematical Society (3) 3(1), 99–117", "doi": "10.1112/plms/s3-3.1.99", "arxiv_id": null, "version": null, "publication_status": "journal work", "canonical_url": "https://doi.org/10.1112/plms/s3-3.1.99", "source_url": "https://mediadepot.kings.cam.ac.uk/getmedia/83/be4a3d910d5d58e3911315113c60a09f6293fa896a5e3795998fa6b4fb72b71446336e3c7c92d5e08fd0fb2762b6f663279ba799d7fd562480b4bf63c63e02b9", "source_path": null, "source_sha256": "7fe475d2c67cd754fd51a72bf7c23db192278b34bf91eae83889e0b8ef25c0a5", "pages": 19, "source_edition": "King’s College Turing Digital Archive original offprint", "access_date": "2026-11-17", "bibliographic_verified": true, "selected": true, "full_text_accessed": true, "whole_work_read": false, "substantive_reading": true, "audit_level": 0, "topic": "finite verification", "audit_scope": "Historical claim read with its own caveat. Lehman''s later correction to details is cited by Trudgian and Saouter–Gourdon–Demichel. This is neither a modern interval-arithmetic replay nor a verified initial segment extending to the high band.", "main_results": [{"locator": "Introduction, Theorems 4–5, pp. 115–117", "statement": "The paper uses an explicit integrated argument estimate and a zero-counting criterion for the Manchester Mark 1 computation. The primary run reports simple critical-line zeros in the band 2π·63² < Im(s) < 2π·64², with the author''s qualification on reliability. The smaller-height run was curtailed by breakdown."}], "record_path": "papers/suzuki_model63_computational_notes.md", "archive_catalogue": "https://turingarchive.kings.cam.ac.uk/publications-lectures-and-talks-amtb/amt-b-21", "local_version_receipt": "Original viewed and checksummed. Archive scan excluded from the retained source folder.", "id": "PAPER-SM63-COMP-002", "arxiv": null, "read_scope": "Historical claim read with its own caveat. Lehman''s later correction to details is cited by Trudgian and Saouter–Gourdon–Demichel. This is neither a modern interval-arithmetic replay nor a verified initial segment extending to the high band.", "access_status": "full_text_accessed", "original_access_status": "full_text_accessed", "track_file": "papers/suzuki_model63_computational_records.jsonl", "original_selection_status": null, "selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-SM63-COMP-002"]}','Some Calculations of the Riemann Zeta-Function','["Alan M. Turing"]',NULL,'1953',0,0,'selected_checkpoint_priority_work','full_text_accessed','King’s College Turing Digital Archive original offprint','https://mediadepot.kings.cam.ac.uk/getmedia/83/be4a3d910d5d58e3911315113c60a09f6293fa896a5e3795998fa6b4fb72b71446336e3c7c92d5e08fd0fb2762b6f663279ba799d7fd562480b4bf63c63e02b9','7fe475d2c67cd754fd51a72bf7c23db192278b34bf91eae83889e0b8ef25c0a5','papers/suzuki_model63_computational_notes.md','papers/suzuki_model63_computational_records.jsonl');
