INSERT INTO "papers" VALUES('PAPER-SM63-POS-040','corpus/bibliography.jsonl',993,'full_text_accessed','audits/adversarial_reviews/director_nakamura_whole_round10.md','{"id": "PAPER-SM63-POS-040", "title": "On infinitely divisible distributions related to the Riemann hypothesis", "authors": ["Takashi Nakamura", "Masatoshi Suzuki"], "year": 2023, "preprint_date": "2023-06-14", "venue": "Statistics & Probability Letters 201, 109889", "doi": "10.1016/j.spl.2023.109889", "arxiv": "2306.08317", "version": "v1", "publication_status": "journal work", "canonical_url": "https://doi.org/10.1016/j.spl.2023.109889", "source_url": "https://arxiv.org/pdf/2306.08317", "source_sha256": "756288c39bfd743f08f24b1e5074bb8a4adbe8a959d42edd763af07678801830", "pages": 5, "access_date": "2026-11-17", "bibliographic_verified": true, "full_text_accessed": true, "access_status": "full_text_accessed", "selected": true, "selection_status": "selected_checkpoint_priority_work", "audit_level": 3, "whole_work_read": true, "substantive_reading": true, "read_scope": "All five pages of pinned v1, every mathematical display, two theorems, two lemmas, appendix and references; two complete independent reconstructions and director. Individual-term damping qualification does not affect working domain.", "topic": "probabilistic positivity", "source_summary": "Equates RH with infinite divisibility of exp(gζ), whose Lévy measure on RH is a summable atomic measure over signed zero ordinates.", "main_results": [{"locator": "pp. 1–5, §§1–3, Theorems 1.1–1.2, Lemmas 2.1–2.2 and appendix", "statement": "For the explicitly defined even gζ, RH is equivalent to exp(gζ) being the characteristic function of an infinitely divisible distribution. Under RH the law is compound Poisson and its finite Lévy measure has atoms at −γ of mass mγ/γ².", "status": "source statement"}], "record_path": "papers/suzuki_model63_positivity_notes.md", "version_url": "https://arxiv.org/abs/2306.08317v1", "original_access_status": "full_text_accessed", "track_file": "papers/suzuki_model63_positivity_records.jsonl", "original_selection_status": "selected_checkpoint_priority_work", "source_record_ids": ["PAPER-SM63-POS-040"], "scope_update_history": [{"fields": {"audit_level": 3, "whole_work_read": true, "substantive_reading": true, "read_scope": "All five pages of pinned v1, every mathematical display, two theorems, two lemmas, appendix and references; two complete independent reconstructions and director. Individual-term damping qualification does not affect working domain.", "claim_verification_status": "Whole-work Level3 for exact arxivv1; journal proof text inaccessible. Classical inputs and independent finite-Levy/abscissa reconstructions documented."}, "evidence": "audits/adversarial_reviews/director_nakamura_whole_round10.md", "track_file": "quality/zzzzz_director_round10_source_scope_updates.jsonl"}], "claim_verification_status": "Whole-work Level3 for exact arxivv1; journal proof text inaccessible. Classical inputs and independent finite-Levy/abscissa reconstructions documented.", "scope_update_evidence": "audits/adversarial_reviews/director_nakamura_whole_round10.md", "additional_scope_update_files": ["quality/zzzzz_director_round10_source_scope_updates.jsonl"]}','On infinitely divisible distributions related to the Riemann hypothesis','["Takashi Nakamura", "Masatoshi Suzuki"]',NULL,'2023',3,1,'selected_checkpoint_priority_work','full_text_accessed','v1','https://arxiv.org/pdf/2306.08317','756288c39bfd743f08f24b1e5074bb8a4adbe8a959d42edd763af07678801830','papers/suzuki_model63_positivity_notes.md','papers/suzuki_model63_positivity_records.jsonl');
